INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('tangshi300-001','行宫','元稹','tangshi300','','五言绝句','寥落古行宫，宫花寂寞红。
白头宫女在，闲坐说玄宗。','',''),('tangshi300-002','登鹳雀楼','王之涣','tangshi300','','五言绝句','白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。','',''),('tangshi300-003','新嫁娘词','王建','tangshi300','','五言绝句','三日入厨下，洗手作羹汤。
未谙姑食性，先遣小姑尝。','',''),('tangshi300-004','相思','王维','tangshi300','','五言绝句','红豆生南国，春来发几枝。
愿君多采撷，此物最相思。','',''),('tangshi300-005','杂诗','王维','tangshi300','','五言绝句','君自故乡来，应知故乡事。
来日绮窗前，寒梅着花未？','',''),('tangshi300-006','鹿柴','王维','tangshi300','','五言绝句','空山不见人，但闻人语响。
返景入深林，复照青苔上。','',''),('tangshi300-007','竹里馆','王维','tangshi300','','五言绝句','独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。','',''),('tangshi300-008','山中送别','王维','tangshi300','','五言绝句','山中相送罢，日暮掩柴扉。
春草明年绿，王孙归不归？(明年 一作：年年)','',''),('tangshi300-009','问刘十九','白居易','tangshi300','','五言绝句','绿蚁新醅酒，红泥小火炉。
晚来天欲雪，能饮一杯无？','',''),('tangshi300-010','哥舒歌','西鄙人','tangshi300','','五言绝句','北斗七星高，哥舒夜带刀。
至今窥牧马，不敢过临洮。','',''),('tangshi300-011','静夜思','李白','tangshi300','','五言绝句','床前明月光，疑是地上霜，
举头望明月，低头思故乡。','',''),('tangshi300-012','怨情','李白','tangshi300','','五言绝句','美人卷珠帘，深坐颦蛾眉。(颦 一作：蹙)
但见泪痕湿，不知心恨谁。','',''),('tangshi300-013','登乐游原','李商隐','tangshi300','','五言绝句','向晚意不适，驱车登古原。
夕阳无限好，只是近黄昏。','',''),('tangshi300-014','听筝','李端','tangshi300','','五言绝句','鸣筝金粟柱，素手玉房前。
欲得周郎顾，时时误拂弦。','',''),('tangshi300-015','渡汉江','宋之问','tangshi300','','五言绝句','岭外音书断，经冬复历春。
近乡情更怯，不敢问来人。','',''),('tangshi300-016','八阵图','杜甫','tangshi300','','五言绝句','功盖三分国，名成八阵图。（名成 一作：名高）
江流石不转，遗恨失吞吴。','',''),('tangshi300-017','宿建德江','孟浩然','tangshi300','','五言绝句','移舟泊烟渚，日暮客愁新。
野旷天低树，江清月近人。','',''),('tangshi300-018','春晓','孟浩然','tangshi300','','五言绝句','春眠不觉晓，处处闻啼鸟。
夜来风雨声，花落知多少。','',''),('tangshi300-019','春怨','金昌绪','tangshi300','','五言绝句','打起黄莺儿，莫教枝上啼。
啼时惊妾梦，不得到辽西。','',''),('tangshi300-020','江雪','柳宗元','tangshi300','','五言绝句','千山鸟飞绝，万径人踪灭。
孤舟蓑笠翁，独钓寒江雪。','',''),('tangshi300-021','秋夜寄邱员外','韦应物','tangshi300','','五言绝句','怀君属秋夜，散步咏凉天。
空山松子落，幽人应未眠。','',''),('tangshi300-022','终南望余雪','祖咏','tangshi300','','五言绝句','终南阴岭秀，积雪浮云端。
林表明霁色，城中增暮寒。','',''),('tangshi300-023','宫词','张祜','tangshi300','','五言绝句','故国三千里，深宫二十年。
一声何满子，双泪落君前。','',''),('tangshi300-024','寻隐者不遇','贾岛','tangshi300','','五言绝句','松下问童子，言师采药去。
只在此山中，云深不知处。','',''),('tangshi300-025','送崔九','裴迪','tangshi300','','五言绝句','归山深浅去，须尽丘壑美。
莫学武陵人，暂游桃源里。','',''),('tangshi300-026','送灵澈上人','刘长卿','tangshi300','','五言绝句','苍苍竹林寺，杳杳钟声晚。
荷笠带斜阳，青山独归远。(斜阳 一作：夕阳)','',''),('tangshi300-027','听弹琴','刘长卿','tangshi300','','五言绝句','泠泠七弦上，静听松风寒。(七弦 一作：七丝)
古调虽自爱，今人多不弹。','',''),('tangshi300-028','送上人','刘长卿','tangshi300','','五言绝句','孤云将野鹤，岂向人间住。
莫买沃洲山，时人已知处。','',''),('tangshi300-029','玉台体','权德舆','tangshi300','','五言绝句','昨夜裙带解，今朝蟢子飞。
铅华不可弃，莫是藁砧归。','',''),('tangshi300-030','芙蓉楼送辛渐','王昌龄','tangshi300','','七言绝句','寒雨连江夜入吴，平明送客楚山孤。
洛阳亲友如相问，一片冰心在玉壶。','',''),('tangshi300-031','闺怨','王昌龄','tangshi300','','七言绝句','闺中少妇不知愁，春日凝妆上翠楼。
忽见陌头杨柳色，悔教夫婿觅封侯。','',''),('tangshi300-032','春宫曲','王昌龄','tangshi300','','七言绝句','昨夜风开露井桃，未央前殿月轮高。
平阳歌舞新承宠，帘外春寒赐锦袍。','',''),('tangshi300-033','九月九日忆山东兄弟','王维','tangshi300','','七言绝句','独在异乡为异客，每逢佳节倍思亲。
遥知兄弟登高处，遍插茱萸少一人。','',''),('tangshi300-034','凉州词','王翰','tangshi300','','七言绝句','葡萄美酒夜光杯，欲饮琵琶马上催。
醉卧沙场君莫笑，古来征战几人回？','',''),('tangshi300-035','后宫词','白居易','tangshi300','','七言绝句','泪湿罗巾梦不成，夜深前殿按歌声。
红颜未老恩先断，斜倚薰笼坐到明。','',''),('tangshi300-036','宫中词','朱庆余','tangshi300','','七言绝句','寂寂花时闭院门，美人相并立琼轩。
含情欲说宫中事，鹦鹉前头不敢言。','',''),('tangshi300-037','近试上张水部','朱庆余','tangshi300','','七言绝句','洞房昨夜停红烛，待晓堂前拜舅姑。
妆罢低声问夫婿，画眉深浅入时无。','',''),('tangshi300-038','逢入京使','岑参','tangshi300','','七言绝句','故园东望路漫漫，双袖龙钟泪不干。
马上相逢无纸笔，凭君传语报平安。','',''),('tangshi300-039','黄鹤楼送孟浩然之广陵','李白','tangshi300','','七言绝句','故人西辞黄鹤楼，烟花三月下扬州。
孤帆远影碧空尽，唯见长江天际流。 (唯 通：惟)','',''),('tangshi300-040','早发白帝城','李白','tangshi300','','七言绝句','朝辞白帝彩云间，千里江陵一日还。
两岸猿声啼不住，轻舟已过万重山。','',''),('tangshi300-041','夜上受降城闻笛','李益','tangshi300','','七言绝句','回乐烽前沙似雪，受降城外月如霜。(回乐
一作：回乐
）
不知何处吹芦管，一夜征人尽望乡。','',''),('tangshi300-042','贾生','李商隐','tangshi300','','七言绝句','宣室求贤访逐臣，贾生才调更无伦。
可怜夜半虚前席，不问苍生问鬼神。','',''),('tangshi300-043','隋宫','李商隐','tangshi300','','七言绝句','乘兴南游不戒严，九重谁省谏书函。
春风举国裁宫锦，半作障泥半作帆。','',''),('tangshi300-044','瑶池','李商隐','tangshi300','','七言绝句','瑶池阿母绮窗开，黄竹歌声动地哀。
八骏日行三万里，穆王何事不重来。','',''),('tangshi300-045','嫦娥','李商隐','tangshi300','','七言绝句','云母屏风烛影深，长河渐落晓星沉。
嫦娥应悔偷灵药，碧海青天夜夜心。','',''),('tangshi300-046','夜雨寄北','李商隐','tangshi300','','七言绝句','君问归期未有期，巴山夜雨涨秋池。
何当共剪西窗烛，却话巴山夜雨时。','',''),('tangshi300-047','寄令狐郎中','李商隐','tangshi300','','七言绝句','嵩云秦树久离居，双鲤迢迢一纸书。
休问梁园旧宾客，茂陵秋雨病相如。','',''),('tangshi300-048','为有','李商隐','tangshi300','','七言绝句','为有云屏无限娇，凤城寒尽怕春宵。
无端嫁得金龟婿，辜负香衾事早朝。','',''),('tangshi300-049','江南逢李龟年','杜甫','tangshi300','','七言绝句','岐王宅里寻常见，崔九堂前几度闻。
正是江南好风景，落花时节又逢君。','',''),('tangshi300-050','赠别·其一','杜牧','tangshi300','','七言绝句','娉娉袅袅十三余，豆蔻梢头二月初。
春风十里扬州路，卷上珠帘总不如。','',''),('tangshi300-051','赠别·其二','杜牧','tangshi300','','七言绝句','多情却似总无情，唯觉樽前笑不成。
蜡烛有心还惜别，替人垂泪到天明。','',''),('tangshi300-052','金谷园','杜牧','tangshi300','','七言绝句','繁华事散逐香尘，流水无情草自春。
日暮东风怨啼鸟，落花犹似坠楼人。','',''),('tangshi300-053','寄扬州韩绰判官','杜牧','tangshi300','','七言绝句','青山隐隐水迢迢，秋尽江南草未凋。
二十四桥明月夜，玉人何处教吹箫？','',''),('tangshi300-054','遣怀','杜牧','tangshi300','','七言绝句','落魄江南载酒行，楚腰纤细掌中轻。(江南 一作：江湖；纤细 一作：肠断)
十年一觉扬州梦，赢得青楼薄幸名。','',''),('tangshi300-055','秋夕','杜牧','tangshi300','','七言绝句','银烛秋光冷画屏，轻罗小扇扑流萤。
天阶夜色凉如水，卧看牵牛织女星。','',''),('tangshi300-056','将赴吴兴登乐游原一绝','杜牧','tangshi300','','七言绝句','清时有味是无能，闲爱孤云静爱僧。
欲把一麾江海去，乐游原上望昭陵。','',''),('tangshi300-057','赤壁','杜牧','tangshi300','','七言绝句','折戟沉沙铁未销，自将磨洗认前朝。
东风不与周郎便，铜雀春深锁二乔。','',''),('tangshi300-058','泊秦淮','杜牧','tangshi300','','七言绝句','烟笼寒水月笼沙，夜泊秦淮近酒家。
商女不知亡国恨，隔江犹唱后庭花。','',''),('tangshi300-059','征人怨','柳中庸','tangshi300','','七言绝句','岁岁金河复玉关，朝朝马策与刀环。
三春白雪归青冢，万里黄河绕黑山。','',''),('tangshi300-060','金陵图','韦庄','tangshi300','','七言绝句','谁谓伤心画不成，画人心逐世人情。
君看六幅南朝事，老木寒云满故城。','',''),('tangshi300-061','滁州西涧','韦应物','tangshi300','','七言绝句','独怜幽草涧边生，上有黄鹂深树鸣。
春潮带雨晚来急，野渡无人舟自横。','',''),('tangshi300-062','桃花溪','张旭','tangshi300','','七言绝句','隐隐飞桥隔野烟，石矶西畔问渔船。
桃花尽日随流水，洞在清溪何处边。','',''),('tangshi300-063','寄人','张泌','tangshi300','','七言绝句','别梦依依到谢家，小廊回合曲阑斜。
多情只有春庭月，犹为离人照落花。','',''),('tangshi300-064','题金陵渡','张祜','tangshi300','','七言绝句','金陵津渡小山楼，一宿行人自可愁。
潮落夜江斜月里，两三星火是瓜州。','',''),('tangshi300-065','赠内人','张祜','tangshi300','','七言绝句','禁门宫树月痕过，媚眼惟看宿鹭窠。
斜拔玉钗灯影畔，剔开红焰救飞蛾。','',''),('tangshi300-066','集灵台·其一','张祜','tangshi300','','七言绝句','日光斜照集灵台，红树花迎晓露开。
昨夜上皇新授箓，太真含笑入帘来。','',''),('tangshi300-067','集灵台·其二','张祜','tangshi300','','七言绝句','虢国夫人承主恩，平明骑马入宫门。
却嫌脂粉污颜色，淡扫蛾眉朝至尊。','',''),('tangshi300-068','枫桥夜泊','张继','tangshi300','','七言绝句','月落乌啼霜满天，江枫渔火对愁眠。
姑苏城外寒山寺，夜半钟声到客船。','',''),('tangshi300-069','陇西行','陈陶','tangshi300','','七言绝句','誓扫匈奴不顾身，五千貂锦丧胡尘。
可怜无定河边骨，犹是春闺梦里人！(春闺 一作：深闺)','',''),('tangshi300-070','杂诗','佚名','tangshi300','','七言绝句','近寒食雨草萋萋，着麦苗风柳映堤。
等是有家归未得，杜鹃休向耳边啼。','',''),('tangshi300-071','回乡偶书·其一','贺知章','tangshi300','','七言绝句','少小离家老大回，乡音无改鬓毛衰。
儿童相见不相识，笑问客从何处来。','',''),('tangshi300-072','瑶瑟怨','温庭筠','tangshi300','','七言绝句','冰簟银牀梦不成，碧天如水夜云轻。
雁声远过潇湘去，十二楼中月自明。','',''),('tangshi300-073','月夜','刘方平','tangshi300','','七言绝句','更深月色半人家，北斗阑干南斗斜。
今夜偏知春气暖，虫声新透绿窗纱。','',''),('tangshi300-074','春怨','刘方平','tangshi300','','七言绝句','纱窗日落渐黄昏，金屋无人见泪痕。
寂寞空庭春欲晚，梨花满地不开门。','',''),('tangshi300-075','乌衣巷','刘禹锡','tangshi300','','七言绝句','朱雀桥边野草花，乌衣巷口夕阳斜。
旧时王谢堂前燕，飞入寻常百姓家。','',''),('tangshi300-076','春词','刘禹锡','tangshi300','','七言绝句','新妆宜面下朱楼，深锁春光一院愁。
行到中庭数花朵，蜻蜓飞上玉搔头。','',''),('tangshi300-077','马嵬坡','郑畋','tangshi300','','七言绝句','玄宗回马杨妃死，云雨虽亡日月新。
终是圣明天子事，景阳宫井又何人。','',''),('tangshi300-078','寒食','韩翃','tangshi300','','七言绝句','春城无处不飞花，寒食东风御柳斜。
日暮汉宫传蜡烛，轻烟散入五侯家。','',''),('tangshi300-079','已凉','韩偓','tangshi300','','七言绝句','碧阑干外绣帘垂，猩血屏风画折枝。
八尺龙须方锦褥，已凉天气未寒时。','',''),('tangshi300-080','宫词','顾况','tangshi300','','七言绝句','长乐宫连上苑春，玉楼金殿艳歌新。
君门一入无由出，唯有宫莺得见人。','',''),('tangshi300-081','送杜少府之任蜀州','王勃','tangshi300','','五言律诗','城阙辅三秦，风烟望五津。
与君离别意，同是宦游人。
海内存知己，天涯若比邻。
无为在歧路，儿女共沾巾。','',''),('tangshi300-082','送梓州李使君','王维','tangshi300','','五言律诗','万壑树参天，千山响杜鹃。
山中一夜雨，树杪百重泉。
汉女输幢布，巴人讼芋田。
文翁翻教授，不敢倚先贤。','',''),('tangshi300-083','汉江临眺','王维','tangshi300','','五言律诗','楚塞三湘接，荆门九派通。
江流天地外，山色有无中。
郡邑浮前浦，波澜动远空。
襄阳好风日，留醉与山翁。','',''),('tangshi300-084','终南别业','王维','tangshi300','','五言律诗','中岁颇好道，晚家南山陲。
兴来每独往，胜事空自知。
行到水穷处，坐看云起时。
偶然值林叟，谈笑无还期。','',''),('tangshi300-085','终南山','王维','tangshi300','','五言律诗','太乙近天都，连山接海隅。
白云回望合，青霭入看无。
分野中峯变，阴晴众壑殊。
欲投人处宿，隔水问樵夫。','',''),('tangshi300-086','酬张少府','王维','tangshi300','','五言律诗','晚年唯好静，万事不关心。自顾无长策，空知返旧林。
松风吹解带，山月照弹琴。君问穷通理，渔歌入浦深。','',''),('tangshi300-087','过香积寺','王维','tangshi300','','五言律诗','不知香积寺，数里入云峯。
古木无人径，深山何处钟。
泉声咽危石，日色冷青松。
薄暮空潭曲，安禅制毒龙。','',''),('tangshi300-088','辋川闲居赠裴秀才迪','王维','tangshi300','','五言律诗','寒山转苍翠，秋水日潺湲。
倚杖柴门外，临风听暮蝉。
渡头余落日，墟里上孤烟。
复值接舆醉，狂歌五柳前。','',''),('tangshi300-089','山居秋暝','王维','tangshi300','','五言律诗','空山新雨后，天气晚来秋。
明月松间照，清泉石上流。
竹喧归浣女，莲动下渔舟。
随意春芳歇，王孙自可留。','',''),('tangshi300-090','归嵩山作','王维','tangshi300','','五言律诗','清川带长薄，车马去闲闲。
流水如有意，暮禽相与还。
荒城临古渡，落日满秋山。
迢递嵩高下，归来且闭关。','',''),('tangshi300-091','次北固山下','王湾','tangshi300','','五言律诗','客路青山外，行舟绿水前。(青山外 一作：青山下)
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达？归雁洛阳边。','',''),('tangshi300-092','云阳馆与韩绅宿别','司空曙','tangshi300','','五言律诗','故人江海别，几度隔山川。
乍见翻疑梦，相悲各问年。
孤灯寒照雨，深竹暗浮烟。
更有明朝恨，离杯惜共传。','',''),('tangshi300-093','喜外弟卢纶见宿','司空曙','tangshi300','','五言律诗','静夜四无邻，荒居旧业贫。
雨中黄叶树，灯下白头人。
以我独沉久，愧君相见频。
平生自有分，况是蔡家亲。','',''),('tangshi300-094','贼平后送人北归','司空曙','tangshi300','','五言律诗','世乱同南去，时清独北还。
他乡生白发，旧国见青山。
晓月过残垒，繁星宿故关。
寒禽与衰草，处处伴愁颜。','',''),('tangshi300-095','赋得古原草送别','白居易','tangshi300','','五言律诗','离离原上草，一岁一枯荣。
野火烧不尽，春风吹又生。
远芳侵古道，晴翠接荒城。
又送王孙去，萋萋满别情。','',''),('tangshi300-096','题大庾岭北驿','宋之问','tangshi300','','五言律诗','阳月南飞雁，传闻至此回。
我行殊未已，何日复归来。
江静潮初落，林昏瘴不开。
明朝望乡处，应见陇头梅。','',''),('tangshi300-097','寄左省杜拾遗','岑参','tangshi300','','五言律诗','联步趋丹陛，分曹限紫微。
晓随天仗入，暮惹御香归。
白发悲花落，青云羡鸟飞。
圣朝无阙事，自觉谏书稀。','',''),('tangshi300-098','听蜀僧浚弹琴','李白','tangshi300','','五言律诗','蜀僧抱绿绮，西下峨眉峯。
为我一挥手，如听万壑松。
客心洗流水，余响入霜钟。
不觉碧山暮，秋云暗几重。','',''),('tangshi300-099','夜泊牛渚怀古','李白','tangshi300','','五言律诗','牛渚西江夜，青天无片云。
登舟望秋月，空忆谢将军。
余亦能高咏，斯人不可闻。
明朝挂帆席，枫叶落纷纷。(挂帆
一作：去)','',''),('tangshi300-100','赠孟浩然','李白','tangshi300','','五言律诗','吾爱孟夫子，风流天下闻。
红颜弃轩冕，白首卧松云。
醉月频中圣，迷花不事君。
高山安可仰，徒此揖清芬。','',''),('tangshi300-101','渡荆门送别','李白','tangshi300','','五言律诗','渡远荆门外，来从楚国游。
山随平野尽，江入大荒流。
月下飞天镜，云生结海楼。
仍怜故乡水，万里送行舟。','',''),('tangshi300-102','送友人','李白','tangshi300','','五言律诗','青山横北郭，白水绕东城。
此地一为别，孤蓬万里征。
浮云游子意，落日故人情。
挥手自兹去，萧萧班马鸣。','',''),('tangshi300-103','喜见外弟又言别','李益','tangshi300','','五言律诗','十年离乱后，长大一相逢。
问姓惊初见，称名忆旧容。
别来沧海事，语罢暮天钟。
明日巴陵道，秋山又几重。','',''),('tangshi300-104','凉思','李商隐','tangshi300','','五言律诗','客去波平槛，蝉休露满枝。永怀当此节，倚立自移时。
北斗兼春远，南陵寓使迟。天涯占梦数，疑误有新知。','',''),('tangshi300-105','北青萝','李商隐','tangshi300','','五言律诗','残阳西入崦，茅屋访孤僧。落叶人何在，寒云路几层。
独敲初夜磬，闲倚一枝藤。世界微尘里，吾宁爱与憎。','',''),('tangshi300-106','蝉','李商隐','tangshi300','','五言律诗','本以高难饱，徒劳恨费声。
五更疏欲断，一树碧无情。
薄宦梗犹泛，故园芜已平。
烦君最相警，我亦举家清。','',''),('tangshi300-107','风雨','李商隐','tangshi300','','五言律诗','凄凉宝剑篇，羁泊欲穷年。
黄叶仍风雨，青楼自管弦。
新知遭薄俗，旧好隔良缘。
心断新丰酒，销愁斗几千。','',''),('tangshi300-108','落花','李商隐','tangshi300','','五言律诗','高阁客竟去，小园花乱飞。参差连曲陌，迢递送斜晖。
肠断未忍扫，眼穿仍欲归。芳心向春尽，所得是沾衣。','',''),('tangshi300-109','登岳阳楼','杜甫','tangshi300','','五言律诗','昔闻洞庭水，今上岳阳楼。
吴楚东南坼，干坤日夜浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。','',''),('tangshi300-110','奉济驿重送严公四韵','杜甫','tangshi300','','五言律诗','远送从此别，青山空复情。几时杯重把，昨夜月同行。
列郡讴歌惜，三朝出入荣。江村独归处，寂寞养残生。','',''),('tangshi300-111','别房太尉墓','杜甫','tangshi300','','五言律诗','他乡复行役，驻马别孤坟。
近泪无干土，低空有断云。
对棋陪谢傅，把剑觅徐君。
唯见林花落，莺啼送客闻。','',''),('tangshi300-112','旅夜书怀','杜甫','tangshi300','','五言律诗','细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章着，官应老病休。
飘飘何所似，天地一沙鸥。','',''),('tangshi300-113','至德二载甫自京金光门','杜甫','tangshi300','','五言律诗','此道昔归顺，西郊胡正繁。
至今残破胆，应有未招魂。
近得归京邑，移官岂至尊。
无才日衰老，驻马望千门。','',''),('tangshi300-114','月夜忆舍弟','杜甫','tangshi300','','五言律诗','戍鼓断人行，边秋一雁声。(边秋 一作:秋边)
露从今夜白，月是故乡明。
有弟皆分散，无家问死生。
寄书长不达，况乃未休兵。','',''),('tangshi300-115','天末怀李白','杜甫','tangshi300','','五言律诗','凉风起天末，君子意如何。
鸿雁几时到，江湖秋水多。
文章憎命达，魑魅喜人过。
应共冤魂语，投诗赠汨罗。','',''),('tangshi300-116','月夜','杜甫','tangshi300','','五言律诗','今夜鄜州月，闺中只独看。遥怜小儿女，未解忆长安。
香雾云鬟湿，清辉玉臂寒。何时倚虚幌，双照泪痕干。','',''),('tangshi300-117','春望','杜甫','tangshi300','','五言律诗','国破山河在，城春草木深。
感时花溅泪，恨别鸟惊心。
烽火连三月，家书抵万金。
白头搔更短，浑欲不胜簪。','',''),('tangshi300-118','春宿左省','杜甫','tangshi300','','五言律诗','花隐掖垣暮，啾啾栖鸟过。
星临万户动，月傍九霄多。
不寝听金钥，因风想玉珂。
明朝有封事，数问夜如何。','',''),('tangshi300-119','旅宿','杜牧','tangshi300','','五言律诗','旅馆无良伴，凝情自悄然。
寒灯思旧事，断雁警愁眠。
远梦归侵晓，家书到隔年。
沧江好烟月，门系钓鱼船。','',''),('tangshi300-120','春宫怨','杜荀鹤','tangshi300','','五言律诗','早被婵娟误，欲妆临镜慵。承恩不在貌，教妾若为容。
风暖鸟声碎，日高花影重。年年越溪女，相忆采芙蓉。','',''),('tangshi300-121','和晋陵陆丞早春游望','杜审言','tangshi300','','五言律诗','独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光转绿苹。
忽闻歌古调，归思欲沾巾。','',''),('tangshi300-122','杂诗三首·其三','沈佺期','tangshi300','','五言律诗','闻道黄龙戍，频年不解兵。
可怜闺里月，长在汉家营。
少妇今春意，良人昨夜情。
谁能将旗鼓，一为取龙城。','',''),('tangshi300-123','宿桐庐江寄广陵旧游','孟浩然','tangshi300','','五言律诗','山暝闻猿愁，沧江急夜流。(闻 一作：听)
风鸣两岸叶，月照一孤舟。
建德非吾土，维扬忆旧游。
还将两行泪，遥寄海西头。','',''),('tangshi300-124','留别王维','孟浩然','tangshi300','','五言律诗','寂寂竟何待，朝朝空自归。欲寻芳草去，惜与故人违。
当路谁相假，知音世所稀。只应守寂寞，还掩故园扉。','',''),('tangshi300-125','早寒有怀','孟浩然','tangshi300','','五言律诗','木落雁南度，北风江上寒。
我家襄水曲，遥隔楚云端。
乡泪客中尽，孤帆天际看。(孤帆 一作：归帆)
迷津欲有问，平海夕漫漫。','',''),('tangshi300-126','岁暮归南山','孟浩然','tangshi300','','五言律诗','北阙休上书，南山归敝庐。不才明主弃，多病故人疏。
白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。','',''),('tangshi300-127','过故人庄','孟浩然','tangshi300','','五言律诗','故人具鸡黍，邀我至田家。
绿树村边合，青山郭外斜。
开轩面场圃，把酒话桑麻。
待到重阳日，还来就菊花。','',''),('tangshi300-128','秦中寄远上人','孟浩然','tangshi300','','五言律诗','一丘常欲卧，三径苦无资。
北土非吾愿，东林怀我师。
黄金燃桂尽，壮志逐年衰。
日夕凉风至，闻蝉但益悲。','',''),('tangshi300-129','望洞庭湖赠张丞相','孟浩然','tangshi300','','五言律诗','八月湖水平，涵虚混太清。
气蒸云梦泽，波撼岳阳城。
欲济无舟楫，端居耻圣明。
坐观垂钓者，徒有羡鱼情。','',''),('tangshi300-130','与诸子登岘山','孟浩然','tangshi300','','五言律诗','人事有代谢，往来成古今。
江山留胜迹，我辈复登临。
水落鱼梁浅，天寒梦泽深。
羊公碑尚在，读罢泪沾襟。(尚在 一作：字在)','',''),('tangshi300-131','宴梅道士山房','孟浩然','tangshi300','','五言律诗','林卧愁春尽，开轩览物华。
忽逢青鸟使，邀入赤松家。
金竈初开火，仙桃正发花。
童颜若可驻，何惜醉流霞。','',''),('tangshi300-132','章台夜思','韦庄','tangshi300','','五言律诗','清瑟怨遥夜，绕弦风雨哀。孤灯闻楚角，残月下章台。
芳草已云暮，故人殊未来。乡书不可寄，秋雁又南回。','',''),('tangshi300-133','淮上喜会梁州故人','韦应物','tangshi300','','五言律诗','江汉曾为客，相逢每醉还。
浮云一别后，流水十年间。
欢笑情如旧，萧疏鬓已斑。
何因不归去？淮上有秋山。','',''),('tangshi300-134','赋得暮雨送李曹','韦应物','tangshi300','','五言律诗','楚江微雨里，建业暮钟时。
漠漠帆来重，冥冥鸟去迟。
海门深不见，浦树远含滋。
相送情无限，沾襟比散丝。','',''),('tangshi300-135','经邹鲁祭孔子而叹之','李隆基','tangshi300','','五言律诗','夫子何为者，栖栖一代中。
地犹鄹氏邑，宅即鲁王宫。
叹凤嗟身否，伤麟怨道穷。
今看两楹奠，当与梦时同。','',''),('tangshi300-136','灞上秋居','马戴','tangshi300','','五言律诗','灞原风雨定，晚见雁行频。
落叶他乡树，寒灯独夜人。
空园白露滴，孤壁野僧邻。
寄卧郊扉久，何年致此身。','',''),('tangshi300-137','楚江怀古三首·其一','马戴','tangshi300','','五言律诗','露气寒光集，微阳下楚丘。猿啼洞庭树，人在木兰舟。
广泽生明月，苍山夹乱流。云中君不见，竟夕自悲秋。','',''),('tangshi300-138','除夜有怀','崔涂','tangshi300','','五言律诗','迢递三巴路，羁危万里身。
乱山残雪夜，孤烛异乡人。
渐与骨肉远，转于僮仆亲。
那堪正飘泊，明日岁华新。','',''),('tangshi300-139','孤雁','崔涂','tangshi300','','五言律诗','几行归塞尽，念尔独何之。
暮雨相呼失，寒塘欲下迟。
渚云低暗度，关月冷相随。
未必逢矰缴，孤飞自可疑。','',''),('tangshi300-140','题破山寺后禅院','常建','tangshi300','','五言律诗','清晨入古寺，初日照高林。
曲径通幽处，禅房花木深。
山光悦鸟性，潭影空人心。
万籁此俱寂，唯闻钟磬音。','',''),('tangshi300-141','望月怀远','张九龄','tangshi300','','五言律诗','海上生明月，天涯共此时。
情人怨遥夜，竟夕起相思。
灭烛怜光满，披衣觉露滋。
不堪盈手赠，还寝梦佳期。','',''),('tangshi300-142','书边事','张乔','tangshi300','','五言律诗','调角断清秋，征人倚戍楼。春风对青冢，白日落梁州。
大汉无兵阻，穷边有客游。蕃情似此水，长愿向南流。','',''),('tangshi300-143','没蕃故人','张籍','tangshi300','','五言律诗','前年伐月支，城下没全师。
蕃汉断消息，死生长别离。
无人收废帐，归马识残旗。
欲祭疑君在，天涯哭此时。','',''),('tangshi300-144','秋日赴阙题潼关驿楼','许浑','tangshi300','','五言律诗','红叶晚萧萧，长亭酒一瓢。
残云归太华，疏雨过中条。
树色随山迥，河声入海遥。
帝乡明日到，犹自梦渔樵。','',''),('tangshi300-145','早秋','许浑','tangshi300','','五言律诗','遥夜泛清瑟，西风生翠萝。
残萤委玉露，早雁拂金河。
高树晓还密，远山晴更多。
淮南一叶下，自觉洞庭波。','',''),('tangshi300-146','送人东游','温庭筠','tangshi300','','五言律诗','荒戍落黄叶，浩然离故关。
高风汉阳渡，初日郢门山。
江上几人在，天涯孤棹还。
何当重相见，樽酒慰离颜。','',''),('tangshi300-147','寻陆鸿渐不遇','皎然','tangshi300','','五言律诗','移家虽带郭，野径入桑麻。近种篱边菊，秋来未着花。
扣门无犬吠，欲去问西家。报道山中去，归时每日斜。','',''),('tangshi300-148','寻南溪常道士','刘长卿','tangshi300','','五言律诗','一路经行处，莓苔见履痕。
白云依静渚，春草闭闲门。
过雨看松色，随山到水源。
溪花与禅意，相对亦忘言。','',''),('tangshi300-149','新年作','刘长卿','tangshi300','','五言律诗','乡心新岁切，天畔独潸然。
老至居人下，春归在客先。
岭猿同旦暮，江柳共风烟。
已似长沙傅，从今又几年。','',''),('tangshi300-150','秋日登吴公台上寺远眺','刘长卿','tangshi300','','五言律诗','古台摇落后，秋日望乡心。
野寺来人少，云峯隔水深。
夕阳依旧垒，寒磬满空林。
惆怅南朝事，长江独至今。','',''),('tangshi300-151','送李中丞归汉阳别业','刘长卿','tangshi300','','五言律诗','流落征南将，曾驱十万师。
罢归无旧业，老去恋明时。
独立三边静，轻生一剑知。
茫茫江汉上，日暮欲何之。','',''),('tangshi300-152','饯别王十一南游','刘长卿','tangshi300','','五言律诗','望君烟水阔，挥手泪沾巾。
飞鸟没何处，青山空向人。
长江一帆远，落日五湖春。
谁见汀洲上，相思愁白苹。','',''),('tangshi300-153','蜀先主庙','刘禹锡','tangshi300','','五言律诗','天地英雄气，千秋尚凛然。势分三足鼎，业复五铢钱。
得相能开国，生儿不象贤。凄凉蜀故妓，来舞魏宫前。','',''),('tangshi300-154','阙题','刘昚虚','tangshi300','','五言律诗','道由白云尽，春与青溪长。
时有落花至，远随流水香。
闲门向山路，深柳读书堂。
幽映每白日，清辉照衣裳。','',''),('tangshi300-155','送李端','卢纶','tangshi300','','五言律诗','故关衰草遍，离别自堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
掩泪空相向，风尘何处期。','',''),('tangshi300-156','送僧归日本','钱起','tangshi300','','五言律诗','上国随缘住，来途若梦行。
浮天沧海远，去世法舟轻。
水月通禅寂，鱼龙听梵声。
惟怜一灯影，万里眼中明。','',''),('tangshi300-157','谷口书斋寄杨补阙','钱起','tangshi300','','五言律诗','泉壑带茅茨，云霞生薜帷。
竹怜新雨后，山爱夕阳时。
闲鹭栖常早，秋花落更迟。
家僮扫萝径，昨与故人期。','',''),('tangshi300-158','在狱咏蝉','骆宾王','tangshi300','','五言律诗','西陆蝉声唱，南冠客思深。(客思深 一作：客思侵)
不堪玄鬓影，来对白头吟。(不堪 一作：那堪)
露重飞难进，风多响易沉。
无人信高洁，谁为表予心？','',''),('tangshi300-159','江乡故人偶集客舍','戴叔伦','tangshi300','','五言律诗','天秋月又满，城阙夜千重。
还作江南会，翻疑梦里逢。
风枝惊暗鹊，露草覆寒蛩。
羁旅长堪醉，相留畏晓钟。','',''),('tangshi300-160','酬程延秋夜即事见赠','韩翃','tangshi300','','五言律诗','长簟迎风早，空城澹月华。
星河秋一雁，砧杵夜千家。
节候看应晚，心期卧亦赊。
向来吟秀句，不觉已鸣鸦。','',''),('tangshi300-161','遣悲怀三首·其一','元稹','tangshi300','','七言律诗','谢公最小偏怜女，自嫁黔娄百事乖。
顾我无衣搜荩箧，泥他沽酒拔金钗。(荩箧 一作：画箧)
野蔬充膳甘长藿，落叶添薪仰古槐。
今日俸钱过十万，与君营奠复营斋。','',''),('tangshi300-162','遣悲怀三首·其二','元稹','tangshi300','','七言律诗','昔日戏言身后事，今朝都到眼前来。
衣裳已施行看尽，针线犹存未忍开。
尚想旧情怜婢仆，也曾因梦送钱财。
诚知此恨人人有，贫贱夫妻百事哀。','',''),('tangshi300-163','遣悲怀三首·其三','元稹','tangshi300','','七言律诗','闲坐悲君亦自悲，百年都是几多时。
邓攸无子寻知命，潘岳悼亡犹费词。
同穴窅冥何所望，他生缘会更难期。
惟将终夜常开眼，报答平生未展眉。','',''),('tangshi300-164','赠郭给事','王维','tangshi300','','七言律诗','洞门高阁霭余辉，桃李阴阴柳絮飞。
禁里疏钟官舍晚，省中啼鸟吏人稀。
晨摇玉佩趋金殿，夕奉天书拜琐闱。
强欲从君无那老，将因卧病解朝衣。','',''),('tangshi300-165','和贾至舍人早朝大明宫','王维','tangshi300','','七言律诗','绛帻鸡人送晓筹，尚衣方进翠云裘。
九天阊阖开宫殿，万国衣冠拜冕旒。
日色才临仙掌动，香菸欲傍衮龙浮。
朝罢须裁五色诏，佩声归向凤池头。','',''),('tangshi300-166','奉和圣制从蓬莱向兴庆阁道','王维','tangshi300','','七言律诗','渭水自萦秦塞曲，黄山旧绕汉宫斜。
銮舆迥出千门柳，阁道回看上苑花。
云里帝城双凤阙，雨中春树万人家。
为乘阳气行时令，不是宸游玩物华。(玩 一作：重)','',''),('tangshi300-167','积雨辋川庄作','王维','tangshi300','','七言律诗','积雨空林烟火迟，蒸藜炊黍饷东菑。
漠漠水田飞白鹭，阴阴夏木啭黄鹂。
山中习静观朝槿，松下清斋折露葵。
野老与人争席罢，海鸥何事更相疑。','',''),('tangshi300-168','望月有感','白居易','tangshi300','','七言律诗','时难年荒世业空，弟兄羁旅各西东。
田园寥落干戈后，骨肉流离道路中。
吊影分为千里雁，辞根散作九秋蓬。
共看明月应垂泪，一夜乡心五处同。','',''),('tangshi300-169','奉和中书舍人贾至早朝','岑参','tangshi300','','七言律诗','鸡鸣紫陌曙光寒，莺啭皇州春色阑。
金阙晓钟开万户，玉阶仙仗拥千官。
花迎剑佩星初落，柳拂旌旗露未干。
独有凤凰池上客，阳春一曲和皆难。','',''),('tangshi300-170','登金陵凤凰台','李白','tangshi300','','七言律诗','凤凰台上凤凰游，凤去台空江自流。
吴宫花草埋幽径，晋代衣冠成古丘。
三山半落青天外，二水中分白鹭洲。(二水 一作：一水)
总为浮云能蔽日，长安不见使人愁。','',''),('tangshi300-171','无题·重帏深下莫愁堂','李商隐','tangshi300','','七言律诗','重帏深下莫愁堂，卧后清宵细细长。
神女生涯原是梦，小姑居处本无郎。
风波不信菱枝弱，月露谁教桂叶香。
直道相思了无益，未妨惆怅是清狂。','',''),('tangshi300-172','无题·凤尾香罗薄几重','李商隐','tangshi300','','七言律诗','凤尾香罗薄几重，碧文圆顶夜深缝。
扇裁月魄羞难掩，车走雷声语未通。
曾是寂寥金烬暗，断无消息石榴红。
斑骓只系垂杨岸，何处西南任好风。(任 一作：待)','',''),('tangshi300-173','无题·相见时难别亦难','李商隐','tangshi300','','七言律诗','相见时难别亦难，东风无力百花残。
春蚕到死丝方尽，蜡炬成灰泪始干。
晓镜但愁云鬓改，夜吟应觉月光寒。
蓬山此去无多路，青鸟殷勤为探看。(蓬山 一作：蓬莱)','',''),('tangshi300-174','无题·来是空言去绝踪','李商隐','tangshi300','','七言律诗','来是空言去绝踪，月斜楼上五更钟。
梦为远别啼难唤，书被催成墨未浓。
蜡照半笼金翡翠，麝薰微度绣芙蓉。
刘郎已恨蓬山远，更隔蓬山一万重！','',''),('tangshi300-175','无题·飒飒东风细雨来','李商隐','tangshi300','','七言律诗','飒飒东风细雨来，芙蓉塘外有轻雷。
金蟾啮锁烧香入，玉虎牵丝汲井回。
贾氏窥帘韩掾少，宓妃留枕魏王才。
春心莫共花争发，一寸相思一寸灰！','',''),('tangshi300-176','无题·昨夜星辰昨夜风','李商隐','tangshi300','','七言律诗','昨夜星辰昨夜风，画楼西畔桂堂东。
身无彩凤双飞翼，心有灵犀一点通。
隔座送钩春酒暖，分曹射覆蜡灯红。
嗟余听鼓应官去，走马兰台类转蓬。','',''),('tangshi300-177','春雨','李商隐','tangshi300','','七言律诗','怅卧新春白袷衣，白门寥落意多违。
红楼隔雨相望冷，珠箔飘灯独自归。
远路应悲春晼晚，残霄犹得梦依稀。
玉璫缄札何由达，万里云罗一雁飞。','',''),('tangshi300-178','筹笔驿','李商隐','tangshi300','','七言律诗','猿鸟犹疑畏简书，风云常为护储胥。
徒令上将挥神笔，终见降王走传车。
管乐有才原不忝，关张无命欲何如？
他年锦里经祠庙，梁父吟成恨有余。','',''),('tangshi300-179','锦瑟','李商隐','tangshi300','','七言律诗','锦瑟无端五十弦，一弦一柱思华年。
庄生晓梦迷蝴蝶，望帝春心托杜鹃。
沧海月明珠有泪，蓝田日暖玉生烟。
此情可待成追忆，只是当时已惘然。','',''),('tangshi300-180','隋宫','李商隐','tangshi300','','七言律诗','紫泉宫殿锁烟霞，欲取芜城作帝家。
玉玺不缘归日角，锦帆应是到天涯。
于今腐草无萤火，终古垂杨有暮鸦。
地下若逢陈后主，岂宜重问后庭花。','',''),('tangshi300-181','送魏万之京','李颀','tangshi300','','七言律诗','朝闻游子唱离歌，昨夜微霜初渡河。
鸿雁不堪愁里听，云山况是客中过。
关城树色催寒近，御苑砧声向晚多。(
色 一作：曙)
莫见长安行乐处，空令岁月易蹉跎。','',''),('tangshi300-182','咏怀古迹·其一','杜甫','tangshi300','','七言律诗','支离东北风尘际，漂泊西南天地间。
三峡楼台淹日月，五溪衣服共云山。
羯胡事主终无赖，词客哀时且未还。
庾信平生最萧瑟，暮年诗赋动江关。','',''),('tangshi300-183','咏怀古迹·其二','杜甫','tangshi300','','七言律诗','摇落深知宋玉悲，风流儒雅亦吾师。
怅望千秋一洒泪，萧条异代不同时。
江山故宅空文藻，云雨荒台岂梦思。
最是楚宫俱泯灭，舟人指点到今疑。','',''),('tangshi300-184','咏怀古迹·其三','杜甫','tangshi300','','七言律诗','羣山万壑赴荆门，生长明妃尚有村。
一去紫台连朔漠，独留青冢向黄昏。
画图省识春风面，环佩空归夜月魂。(夜月 一作：月夜 环
一作：环
)
千载琵琶作胡语，分明怨恨曲中论。','',''),('tangshi300-185','咏怀古迹·其四','杜甫','tangshi300','','七言律诗','蜀主窥吴幸三峡，崩年亦在永安宫。
翠华想像空山里，玉殿虚无野寺中。
古庙杉松巢水鹤，岁时伏腊走村翁。
武侯祠堂常邻近，一体君臣祭祀同。','',''),('tangshi300-186','咏怀古迹·其五','杜甫','tangshi300','','七言律诗','诸葛大名垂宇宙，宗臣遗像肃清高。
三分割据纡筹策，万古云霄一羽毛。
伯仲之间见伊吕，指挥若定失萧曹。
运移汉祚终难复，志决身歼军务劳。','',''),('tangshi300-187','宿府','杜甫','tangshi300','','七言律诗','清秋幕府井梧寒，独宿江城蜡炬残。
永夜角声悲自语，中天月色好谁看。
风尘荏苒音书绝，关塞萧条行路难。
已忍伶俜十年事，强移栖息一枝安。','',''),('tangshi300-188','阁夜','杜甫','tangshi300','','七言律诗','岁暮阴阳催短景，天涯霜雪霁寒宵。
五更鼓角声悲壮，三峡星河影动摇。
野哭几家闻战伐，夷歌数处起渔樵。
卧龙跃马终黄土，人事依依漫寂寥。','',''),('tangshi300-189','闻官军收河南河北','杜甫','tangshi300','','七言律诗','剑外忽传收蓟北，初闻涕泪满衣裳。
却看妻子愁何在，漫卷诗书喜欲狂。
白日放歌须纵酒，青春作伴好还乡。
即从巴峡穿巫峡，便下襄阳向洛阳。','',''),('tangshi300-190','登高','杜甫','tangshi300','','七言律诗','风急天高猿啸哀，渚清沙白鸟飞回。
无边落木萧萧下，不尽长江滚滚来。
万里悲秋常作客，百年多病独登台。
艰难苦恨繁霜鬓，潦倒新停浊酒杯。','',''),('tangshi300-191','登楼','杜甫','tangshi300','','七言律诗','花近高楼伤客心，万方多难此登临。
锦江春色来天地，玉垒浮云变古今。
北极朝廷终不改，西山寇盗莫相侵。
可怜后主还祠庙，日暮聊为梁甫吟。(梁甫 一作：梁父)','',''),('tangshi300-192','蜀相','杜甫','tangshi300','','七言律诗','丞相祠堂何处寻，锦官城外柏森森。
映阶碧草自春色，隔叶黄鹂空好音。
三顾频烦天下计，两朝开济老臣心。(频烦 一作：频繁)
出师未捷身先死，长使英雄泪满襟。','',''),('tangshi300-193','客至','杜甫','tangshi300','','七言律诗','舍南舍北皆春水，但见羣鸥日日来。
花径不曾缘客扫，蓬门今始为君开。
盘飧市远无兼味，樽酒家贫只旧醅。
肯与邻翁相对饮，隔篱呼取尽余杯。(余 通：余)','',''),('tangshi300-194','野望','杜甫','tangshi300','','七言律诗','西山白雪三城戍，南浦清江万里桥。
海内风尘诸弟隔，天涯涕泪一身遥。
惟将迟暮供多病，未有涓埃答圣朝。(惟 通：唯)
跨马出郊时极目，不堪人事日萧条。','',''),('tangshi300-195','登柳州城楼寄漳汀封连四州','柳宗元','tangshi300','','七言律诗','城上高楼接大荒，海天愁思正茫茫。
惊风乱颭芙蓉水，密雨斜侵薜荔墙。
岭树重遮千里目，江流曲似九回肠。
共来百越文身地，犹自音书滞一乡。','',''),('tangshi300-196','春思','皇甫冉','tangshi300','','七言律诗','莺啼燕语报新年，马邑龙堆路几千。
家住层城临汉苑，心随明月到胡天。(层城 一作：秦城)
机中锦字论长恨，楼上花枝笑独眠。
为问元戎窦车骑，何时返旆勒燕然。','',''),('tangshi300-197','寄李儋元锡','韦应物','tangshi300','','七言律诗','去年花里逢君别，今日花开又一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几回圆。','',''),('tangshi300-198','望蓟门','祖咏','tangshi300','','七言律诗','燕台一望客心惊，笳鼓喧喧汉将营。(笳鼓 一作：箫鼓)
万里寒光生积雪，三边曙色动危旌。
沙场烽火侵胡月，海畔云山拥蓟城。
少小虽非投笔吏，论功还欲请长缨。','',''),('tangshi300-199','贫女','秦韬玉','tangshi300','','七言律诗','蓬门未识绮罗香，拟托良媒益自伤。
谁爱风流高格调，共怜时世俭梳妆。
敢将十指夸针巧，不把双眉斗画长。
苦恨年年压金线，为他人作嫁衣裳。','',''),('tangshi300-200','送李少府贬峡中王少府贬','高适','tangshi300','','七言律诗','嗟君此别意何如，驻马衔杯问谪居。
巫峡啼猿数行泪，衡阳归雁几封书。
青枫江上秋帆远，白帝城边古木疏。
圣代即今多雨露，暂时分手莫踌躇。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('tangshi300-201','九日登望仙台呈刘明府','崔曙','tangshi300','','七言律诗','汉文皇帝有高台，此日登临曙色开。
三晋云山皆北向，二陵风雨自东来。
关门令尹谁能识，河上仙翁去不回。
且欲近寻彭泽宰，陶然共醉菊花杯。','',''),('tangshi300-202','登黄鹤楼','崔颢','tangshi300','','七言律诗','昔人已乘黄鹤去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，芳草萋萋鹦鹉洲。
日暮乡关何处是？烟波江上使人愁。','',''),('tangshi300-203','行经华阴','崔颢','tangshi300','','七言律诗','岧峣太华俯咸京，天外三峯削不成。
武帝祠前云欲散，仙人掌上雨初晴。
河山北枕秦关险，驿树西连汉畤平。
借问路傍名利客，无如此处学长生。','',''),('tangshi300-204','利州南渡','温庭筠','tangshi300','','七言律诗','澹然空水对斜晖，曲岛苍茫接翠微。
波上马嘶看棹去，柳边人歇待船归。
数丛沙草羣鸥散，万顷江田一鹭飞。
谁解乘舟寻范蠡，五湖烟水独忘机。','',''),('tangshi300-205','苏武庙','温庭筠','tangshi300','','七言律诗','苏武魂销汉使前，古祠高树两茫然。
云边雁断胡天月，陇上羊归塞草烟。
回日楼台非甲帐，去时冠剑是丁年。
茂陵不见封侯印，空向秋波哭逝川。','',''),('tangshi300-206','江州重别薛六柳','刘长卿','tangshi300','','七言律诗','生涯岂料承优诏，世事空知学醉歌。
江上月明胡雁过，淮南木落楚山多。
寄身且喜沧洲近，顾影无如白发何。
今日龙钟人共弃，愧君犹遣慎风波。','',''),('tangshi300-207','长沙过贾谊宅','刘长卿','tangshi300','','七言律诗','三年谪宦此栖迟，万古惟留楚客悲。
秋草独寻人去后，寒林空见日斜时。
汉文有道恩犹薄，湘水无情吊岂知。
寂寂江山摇落处，怜君何事到天涯。','',''),('tangshi300-208','自夏口至鹦鹉洲夕望岳阳','刘长卿','tangshi300','','七言律诗','汀洲无浪复无烟，楚客相思益渺然。
汉口夕阳斜渡鸟，洞庭秋水远连天。
孤城背岭寒吹角，独树临江夜泊船。(独树 一作：独戍)
贾谊上书忧汉室，长沙谪去古今怜。','',''),('tangshi300-209','西塞山怀古','刘禹锡','tangshi300','','七言律诗','王浚楼船下益州，金陵王气黯然收。
千寻铁锁沉江底，一片降幡出石头。
人世几回伤往事，山形依旧枕寒流。
今逢四海为家日，故垒萧萧芦荻秋。','',''),('tangshi300-210','晚次鄂州','卢纶','tangshi300','','七言律诗','云开远见汉阳城，犹是孤帆一日程。
估客昼眠知浪静，舟人夜语觉潮生。
三湘愁鬓逢秋色，万里归心对月明。
旧业已随征战尽，更堪江上鼓鼙声。','',''),('tangshi300-211','赠阙下裴舍人','钱起','tangshi300','','七言律诗','二月黄莺飞上林，春城紫禁晓阴阴。
长乐钟声花外尽，龙池柳色雨中深。
阳和不散穷途恨，霄汉长怀捧日心。
献赋十年犹未遇，羞将白发对华簪。','',''),('tangshi300-212','宫词','薛逢','tangshi300','','七言律诗','十二楼中尽晓妆，望仙楼上望君王。
锁衔金兽连环冷，水滴铜龙昼漏长。
云髻罢梳还对镜，罗衣欲换更添香。
遥窥正殿帘开处，袍袴宫人扫御牀。','',''),('tangshi300-213','同题仙游观','韩翃','tangshi300','','七言律诗','仙台初见五城楼，风物凄凄宿雨收。
山色遥连秦树晚，砧声近报汉宫秋。
疏松影落空坛静，细草香闲小洞幽。
何用别寻方外去，人间亦自有丹丘。','',''),('tangshi300-214','贼退示官吏','元结','tangshi300','','五言古诗','昔岁逢太平，山林二十年。
泉源在庭户，洞壑当门前。
井税有常期，日晏犹得眠。
忽然遭世变，数岁亲戎旃。
今来典斯郡，山夷又纷然。
城小贼不屠，人贫伤可怜。
是以陷邻境，此州独见全。
使臣将王命，岂不如贼焉？
今彼征敛者，迫之如火煎。
谁能绝人命，以作时世贤！
思欲委符节，引竿自刺船。
将家就鱼麦，归老江湖边。','',''),('tangshi300-215','同从弟销南斋玩月忆山阴','王昌龄','tangshi300','','五言古诗','高卧南斋时，开帷月初吐。
清辉澹水木，演漾在窗户。
冉冉几盈虚，澄澄变今古。
美人清江畔，是夜越吟苦。
千里共如何，微风吹兰杜。','',''),('tangshi300-216','渭川田家','王维','tangshi300','','五言古诗','斜阳照墟落，穷巷牛羊归。(斜阳 一作：斜光)
野老念牧童，倚杖候荆扉。
雉雊麦苗秀，蚕眠桑叶稀。
田夫荷锄至，相见语依依。
即此羡闲逸，怅然吟式微。','',''),('tangshi300-217','西施咏','王维','tangshi300','','五言古诗','艳色天下重，西施宁久微。
朝为越溪女，暮作吴宫妃。
贱日岂殊众，贵来方悟稀。
邀人傅香粉，不自着罗衣。
君宠益娇态，君怜无是非。
当时浣纱伴，莫得同车归。
持谢邻家子，效颦安可希。','',''),('tangshi300-218','送别','王维','tangshi300','','五言古诗','下马饮君酒，问君何所之？
君言不得意，归卧南山陲。
但去莫复问，白云无尽时。','',''),('tangshi300-219','送綦毋潜落第还乡','王维','tangshi300','','五言古诗','圣代无隐者，英灵尽来归。
遂令东山客，不得顾采薇。
既至金门远，孰云吾道非。
江淮度寒食，京洛缝春衣。
置酒长安道，同心与我违。
行当浮桂棹，未几拂荆扉。
远树带行客，孤城当落晖。
吾谋适不用，勿谓知音稀。','',''),('tangshi300-220','青溪','王维','tangshi300','','五言古诗','言入黄花川，每逐清溪水。
随山将万转，趣途无百里。
声喧乱石中，色静深松里。
漾漾泛菱荇，澄澄映葭苇。
我心素已闲，清川澹如此。
请留磐石上，垂钓将已矣。(磐石 一作：盘石)','',''),('tangshi300-221','与高适薛据同登慈恩寺','岑参','tangshi300','','五言古诗','塔势如涌出，孤高耸天宫。
登临出世界，磴道盘虚空。
突兀压神州，峥嵘如鬼工。
四角碍白日，七层摩苍穹。
下窥指高鸟，俯听闻惊风。
连山若波涛，奔凑似朝东。(凑 一作：走；似 一作：如)
青槐夹驰道，宫馆何玲珑。(馆 一作：观)
秋色从西来，苍然满关中。
五陵北原上，万古青蒙蒙。
净理了可悟，胜因夙所宗。
誓将挂冠去，觉道资无穷。','',''),('tangshi300-222','下终南山过斛斯山人宿置酒','李白','tangshi300','','五言古诗','暮从碧山下，山月随人归。
却顾所来径，苍苍横翠微。
相携及田家，童稚开荆扉。
绿竹入幽径，青萝拂行衣。
欢言得所憩，美酒聊共挥。
长歌吟松风，曲尽河星稀。
我醉君复乐，陶然共忘机。','',''),('tangshi300-223','月下独酌四首·其一','李白','tangshi300','','五言古诗','花间一壶酒，独酌无相亲。
举杯邀明月，对影成三人。
月既不解饮，影徒随我身。
暂伴月将影，行乐须及春。
我歌月徘徊，我舞影零乱。
醒时同交欢，醉后各分散。(同交欢 一作：相交欢)
永结无情游，相期邈云汉。','',''),('tangshi300-224','春思','李白','tangshi300','','五言古诗','燕草如碧丝，秦桑低绿枝。
当君怀归日，是妾断肠时。
春风不相识，何事入罗帏。','',''),('tangshi300-225','梦李白·其一','杜甫','tangshi300','','五言古诗','死别已吞声，生别常恻恻。江南瘴疠地，逐客无消息。
故人入我梦，明我长相忆。恐非平生魂，路远不可测。
魂来枫叶青，魂返关塞黑。君今在罗网，何以有羽翼。
落月满屋梁，犹疑照颜色。水深波浪阔，无使蛟龙得。','',''),('tangshi300-226','梦李白·其二','杜甫','tangshi300','','五言古诗','浮云终日行，游子久不至。
三夜频梦君，情亲见君意。
告归常局促，苦道来不易。
江湖多风波，舟楫恐失坠。
出门搔白首，若负平生志。
冠盖满京华，斯人独憔悴。
孰云网恢恢，将老身反累。
千秋万岁名，寂寞身后事。','',''),('tangshi300-227','望岳','杜甫','tangshi300','','五言古诗','岱宗夫如何？齐鲁青未了。
造化钟神秀，阴阳割昏晓。
荡胸生曾云，决眦入归鸟。( 曾 通：层)
会当凌绝顶，一览众山小。','',''),('tangshi300-228','赠卫八处士','杜甫','tangshi300','','五言古诗','人生不相见，动如参与商。
今夕复何夕，共此灯烛光！
少壮能几时？鬓发各已苍！
访旧半为鬼，惊呼热中肠。','',''),('tangshi300-229','佳人','杜甫','tangshi300','','五言古诗','绝代有佳人，幽居在空谷。
自云良家女，零落依草木。
关中昔丧乱，兄弟遭杀戮。
官高何足论，不得收骨肉。
世情恶衰歇，万事随转烛。
夫婿轻薄儿，新人美如玉。
合昏尚知时，鸳鸯不独宿。
但见新人笑，那闻旧人哭。
在山泉水清，出山泉水浊。
侍婢卖珠回，牵萝补茅屋。
摘花不插发，采柏动盈掬。
天寒翠袖薄，日暮倚修竹。','',''),('tangshi300-230','秋登兰山寄张五','孟浩然','tangshi300','','五言古诗','北山白云里，隐者自怡悦。
相望试登高，心随雁飞灭。(试 一作 始)
愁因薄暮起，兴是清秋发。
时见归村人，沙行渡头歇。
天边树若荠，江畔洲如月。
何当载酒来，共醉重阳节。','',''),('tangshi300-231','夏日南亭怀辛大','孟浩然','tangshi300','','五言古诗','山光忽西落，池月渐东上。
散发乘夕凉，开轩卧闲敞。
荷风送香气，竹露滴清响。
欲取鸣琴弹，恨无知音赏。
感此怀故人，中宵劳梦想。(
宵 一作：终)','',''),('tangshi300-232','宿业师山房待丁大不至','孟浩然','tangshi300','','五言古诗','夕阳度西岭，羣壑倏已暝。
松月生夜凉，风泉满清听。
樵人归欲尽，烟鸟栖初定。
之子期宿来，孤琴候萝径。','',''),('tangshi300-233','寻西山隐者不遇','丘为','tangshi300','','五言古诗','绝顶一茅茨，直上三十里。
扣关无僮仆，窥室唯案几。
若非巾柴车，应是钓秋水。
差池不相见，黾勉空仰止。
草色新雨中，松声晚窗里。
及兹契幽绝，自足荡心耳。
虽无宾主意，颇得清净理。
兴尽方下山，何必待之子。','',''),('tangshi300-234','晨诣超师院读禅经','柳宗元','tangshi300','','五言古诗','汲井漱寒齿，清心拂尘服。
闲持贝叶书，步出东斋读。
真源了无取，妄迹世所逐。
遗言冀可冥，缮性何由熟。
道人庭宇静，苔色连深竹。
日出雾露余，青松如膏沐。
澹然离言说，悟悦心自足。','',''),('tangshi300-235','溪居','柳宗元','tangshi300','','五言古诗','久为簪组累，幸此南夷谪。
闲依农圃邻，偶似山林客。
晓耕翻露草，夜榜响溪石。
来往不逢人，长歌楚天碧。','',''),('tangshi300-236','送杨氏女','韦应物','tangshi300','','五言古诗','永日方戚戚，出行复悠悠。
女子今有行，大江溯轻舟。
尔辈苦无恃，抚念益慈柔。
幼为长所育，两别泣不休。
对此结中肠，义往难复留。
自小阙内训，事姑贻我忧。
赖兹托令门，任恤庶无尤。
贫俭诚所尚，资从岂待周。
孝恭遵妇道，容止顺其猷。
别离在今晨，见尔当何秋。
居闲始自遣，临感忽难收。
归来视幼女，零泪缘缨流。','',''),('tangshi300-237','长安遇冯着','韦应物','tangshi300','','五言古诗','客从东方来，衣上灞陵雨。
问客何为来，采山因买斧。
冥冥花正开，扬扬燕新乳。
昨别今已春，鬓丝生几缕。','',''),('tangshi300-238','夕次盱眙县','韦应物','tangshi300','','五言古诗','落帆逗淮镇，停舫临孤驿。浩浩风起波，冥冥日沉夕。
人归山郭暗，雁下芦洲白。独夜忆秦关，听钟未眠客。','',''),('tangshi300-239','东郊','韦应物','tangshi300','','五言古诗','吏舍局终年，出郊旷清曙。
杨柳散和风，青山澹吾虑。
依丛适自憩，缘涧还复去。
微雨霭芳原，春鸠鸣何处。
乐幽心屡止，遵事迹犹遽。
终罢斯结庐，慕陶直可庶。','',''),('tangshi300-240','郡斋雨中与诸文士燕集','韦应物','tangshi300','','五言古诗','兵卫森画戟，宴寝凝清香。
海上风雨至，逍遥池阁凉。
烦疴近消散，嘉宾复满堂。
自惭居处崇，未睹斯民康。
理会是非遣，性达形迹忘。
鲜肥属时禁，蔬果幸见尝。
俯饮一杯酒，仰聆金玉章。
神欢体自轻，意欲凌风翔。
吴中盛文史，羣彦今汪洋。
方知大藩地，岂曰财赋强。','',''),('tangshi300-241','初发扬子寄元大校书','韦应物','tangshi300','','五言古诗','凄凄去亲爱，泛泛入烟雾。
归棹洛阳人，残钟广陵树。
今朝此为别，何处还相遇。
世事波上舟，沿洄安得住。','',''),('tangshi300-242','寄全椒山中道士','韦应物','tangshi300','','五言古诗','今朝郡斋冷，忽念山中客。
涧底束荆薪，归来煮白石。
欲持一瓢酒，远慰风雨夕。
落叶满空山，何处寻行迹。','',''),('tangshi300-243','宿王昌龄隐居','常建','tangshi300','','五言古诗','清溪深不测，隐处唯孤云。
松际露微月，清光犹为君。
茅亭宿花影，药院滋苔纹。
余亦谢时去，西山鸾鹤羣。','',''),('tangshi300-244','感遇·孤鸿海上来','张九龄','tangshi300','','五言古诗','孤鸿海上来，池潢不敢顾。
侧见双翠鸟，巢在三珠树。
矫矫珍木巅，得无金丸惧？
美服患人指，高明逼神恶。
今我游冥冥，弋者何所慕！','',''),('tangshi300-245','感遇·兰叶春葳蕤','张九龄','tangshi300','','五言古诗','兰叶春葳蕤，桂华秋皎洁。
欣欣此生意，自尔为佳节。
谁知林栖者，闻风坐相悦。
草木有本心，何求美人折！','',''),('tangshi300-246','感遇·幽人归独卧','张九龄','tangshi300','','五言古诗','幽人归独卧，滞虑洗孤清。
持此谢高鸟，因之传远情。
日夕怀空意，人谁感至精？
飞沈理自隔，何所慰吾诚?','',''),('tangshi300-247','感遇·江南有丹橘','张九龄','tangshi300','','五言古诗','江南有丹橘，经冬犹绿林。
岂伊地气暖？自有岁寒心。
可以荐嘉客，奈何阻重深。
运命惟所遇，循环不可寻。
徒言树桃李，此木岂无阴？','',''),('tangshi300-248','春泛若耶溪','綦毋潜','tangshi300','','五言古诗','幽意无断绝，此去随所偶。
晚风吹行舟，花路入溪口。
际夜转西壑，隔山望南斗。
潭烟飞溶溶，林月低向后。
生事且弥漫，愿为持竿叟。','',''),('tangshi300-249','石鱼湖上醉歌','元结','tangshi300','','七言古诗','石鱼湖，似洞庭，夏水欲满君山青。
山为樽，水为沼，酒徒历历坐洲岛。
长风连日作大浪，不能废人运酒舫。
我持长瓢坐巴丘，酌饮四坐以散愁。','',''),('tangshi300-250','长恨歌','白居易','tangshi300','','七言古诗','汉皇重色思倾国，御宇多年求不得。杨家有女初长成，养在深闺人未识。
天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。
春寒赐浴华清池，温泉水滑洗凝脂。侍儿扶起娇无力，始是新承恩泽时。
云鬓花颜金步摇，芙蓉帐暖度春宵。春宵苦短日高起，从此君王不早朝。
承欢侍宴无闲暇，春从春游夜专夜。后宫佳丽三千人，三千宠爱在一身。
金屋妆成娇侍夜，玉楼宴罢醉和春。姊妹弟兄皆列土，可怜光彩生门户。
遂令天下父母心，不重生男重生女。骊宫高处入青云，仙乐风飘处处闻。
缓歌慢舞凝丝竹，尽日君王看不足。渔阳鼙鼓动地来，惊破霓裳羽衣曲。
九重城阙烟尘生，千乘万骑西南行。翠华摇摇行复止，西出都门百余里。
六军不发无奈何，宛转蛾眉马前死。花钿委地无人收，翠翘金雀玉搔头。
君王掩面救不得，回看血泪相和流。黄埃散漫风萧索，云栈萦纡登剑阁。
峨嵋山下少人行，旌旗无光日色薄。蜀江水碧蜀山青，圣主朝朝暮暮情。
行宫见月伤心色，夜雨闻铃肠断声。天旋地转回龙驭，到此踌躇不能去。
马嵬坡下泥土中，不见玉颜空死处。君臣相顾尽沾衣，东望都门信马归。
归来池苑皆依旧，太液芙蓉未央柳。芙蓉如面柳如眉，对此如何不泪垂。
春风桃李花开日，秋雨梧桐叶落时。西宫南内多秋草，落叶满阶红不扫。(花开日 一作：花开夜；南内 一作：南苑)
梨园弟子白发新，椒房阿监青娥老。夕殿萤飞思悄然，孤灯挑尽未成眠。
迟迟钟鼓初长夜，耿耿星河欲曙天。鸳鸯瓦冷霜华重，翡翠衾寒谁与共。
悠悠生死别经年，魂魄不曾来入梦。临邛道士鸿都客，能以精诚致魂魄。
为感君王辗转思，遂教方士殷勤觅。排空驭气奔如电，升天入地求之遍。
上穷碧落下黄泉，两处茫茫皆不见。忽闻海上有仙山，山在虚无缥渺间。
楼阁玲珑五云起，其中绰约多仙子。中有一人字太真，雪肤花貌参差是。
金阙西厢叩玉扃，转教小玉报双成。闻道汉家天子使，九华帐里梦魂惊。
揽衣推枕起徘徊，珠箔银屏迤逦开。云鬓半偏新睡觉，花冠不整下堂来。
风吹仙袂飘飘举，犹似霓裳羽衣舞。玉容寂寞泪阑干，梨花一枝春带雨。(阑 通：栏；飘飘 一作：飘颻)
含情凝睇谢君王，一别音容两渺茫。昭阳殿里恩爱绝，蓬莱宫中日月长。
回头下望人寰处，不见长安见尘雾。惟将旧物表深情，钿合金钗寄将去。
钗留一股合一扇，钗擘黄金合分钿。但教心似金钿坚，天上人间会相见。
临别殷勤重寄词，词中有誓两心知。七月七日长生殿，夜半无人私语时。
在天愿作比翼鸟，在地愿为连理枝。天长地久有时尽，此恨绵绵无绝期。','',''),('tangshi300-251','琵琶行','白居易','tangshi300','','七言古诗','浔阳江头夜送客，枫叶荻花秋瑟瑟。
主人下马客在船，举酒欲饮无管弦。
醉不成欢惨将别，别时茫茫江浸月。
忽闻水上琵琶声，主人忘归客不发。
寻声暗问弹者谁？琵琶声停欲语迟。
移船相近邀相见，添酒回灯重开宴。
千呼万唤始出来，犹抱琵琶半遮面。
转轴拨弦三两声，未成曲调先有情。
弦弦掩抑声声思，似诉平生不得志。（不得志 一作：意）
低眉信手续续弹，说尽心中无限事。
轻拢慢捻抹复挑，初为《霓裳》后《六幺》（六幺 一作：绿腰）。
大弦嘈嘈如急雨，小弦切切如私语。
嘈嘈切切错杂弹，大珠小珠落玉盘。
间关莺语花底滑，幽咽泉流冰下难。
冰泉冷涩弦凝绝，凝绝不通声暂歇。(暂歇 一作：渐歇)
别有幽愁暗恨生，此时无声胜有声。
银瓶乍破水浆迸，铁骑突出刀枪鸣。
曲终收拨当心画，四弦一声如裂帛。
东船西舫悄无言，唯见江心秋月白。
沉吟放拨插弦中，整顿衣裳起敛容。
自言本是京城女，家在虾蟆陵下住。
十三学得琵琶成，名属教坊第一部。
曲罢曾教善才服，妆成每被秋娘妒。
五陵年少争缠头，一曲红绡不知数。
钿头银篦击节碎，血色罗裙翻酒污。(银篦 一作：云)
今年欢笑复明年，秋月春风等闲度。
弟走从军阿姨死，暮去朝来颜色故。
门前冷落鞍马稀，老大嫁作商人妇。
商人重利轻别离，前月浮梁买茶去。
去来江口守空船，绕船月明江水寒。
夜深忽梦少年事，梦啼妆泪红阑干。
我闻琵琶已叹息，又闻此语重唧唧。
同是天涯沦落人，相逢何必曾相识！
我从去年辞帝京，谪居卧病浔阳城。
浔阳地僻无音乐，终岁不闻丝竹声。
住近湓江地低湿，黄芦苦竹绕宅生。
其间旦暮闻何物？杜鹃啼血猿哀鸣。
春江花朝秋月夜，往往取酒还独倾。
岂无山歌与村笛？呕哑嘲哳难为听。
今夜闻君琵琶语，如听仙乐耳暂明。
莫辞更坐弹一曲，为君翻作《琵琶行》。
感我此言良久立，却坐促弦弦转急。
凄凄不似向前声，满座重闻皆掩泣。
座中泣下谁最多？江州司马青衫湿。','',''),('tangshi300-252','走马川行奉送封大夫出师','岑参','tangshi300','','七言古诗','君不见走马川行雪海边，平沙莽莽黄入天。
轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。
匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。
将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。
马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。
虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。','',''),('tangshi300-253','轮台歌奉送封大夫出师','岑参','tangshi300','','七言古诗','轮台城头夜吹角，轮台城北旄头落。
羽书昨夜过渠黎，单于已在金山西。
戍楼西望烟尘黑，汉军屯在轮台北。
上将拥旄西出征，平明吹笛大军行。
四边伐鼓雪海涌，三军大呼阴山动。
虏塞兵气连云屯，战场白骨缠草根。
剑河风急雪片阔，沙口石冻马蹄脱。(雪片阔 一作：云片阔)
亚相勤王甘苦辛，誓将报主静边尘。
古来青史谁不见，今见功名胜古人。','',''),('tangshi300-254','白雪歌送武判官归京','岑参','tangshi300','','七言古诗','北风卷地白草折，胡天八月即飞雪。
忽如一夜春风来，千树万树梨花开。
散入珠帘湿罗幕，狐裘不暖锦衾薄。
将军角弓不得控，都护铁衣冷难着。(难着 一作：犹着)
瀚海阑干百丈冰，愁云惨淡万里凝。
中军置酒饮归客，胡琴琵琶与羌笛。
纷纷暮雪下辕门，风掣红旗冻不翻。
轮台东门送君去，去时雪满天山路。
山回路转不见君，雪上空留马行处。','',''),('tangshi300-255','宣州谢脁楼饯别校书叔云','李白','tangshi300','','七言古诗','弃我去者，昨日之日不可留；
乱我心者，今日之日多烦忧。
长风万里送秋雁，对此可以酣高楼。
蓬莱文章建安骨，中间小谢又清发。
俱怀逸兴壮思飞，欲上青天揽明月。(览 通：揽；明月 一作：日月)
抽刀断水水更流，举杯消愁愁更愁。
人生在世不称意，明朝散发弄扁舟。','',''),('tangshi300-256','庐山谣寄卢侍御虚舟','李白','tangshi300','','七言古诗','我本楚狂人，凤歌笑孔丘。
手持绿玉杖，朝别黄鹤楼。
五岳寻仙不辞远，一生好入名山游。
庐山秀出南斗傍，屏风九叠云锦张。
影落明湖青黛光，金阙前开二峯长，银河倒挂三石梁。
香炉瀑布遥相望，回崖沓嶂凌苍苍。
翠影红霞映朝日，鸟飞不到吴天长。
登高壮观天地间，大江茫茫去不还。
黄云万里动风色，白波九道流雪山。
好为庐山谣，兴因庐山发。
闲窥石镜清我心，谢公行处苍苔没。
早服还丹无世情，琴心三叠道初成。
遥见仙人彩云里，手把芙蓉朝玉京。
先期汗漫九垓上，愿接卢敖游太清。','',''),('tangshi300-257','梦游天姥吟留别','李白','tangshi300','','七言古诗','海客谈瀛洲，烟涛微茫信难求；
越人语天姥，云霞明灭或可睹。
天姥连天向天横，势拔五岳掩赤城。
天台四万八千丈，对此欲倒东南倾。(四万 一作：一万)
我欲因之梦吴越，一夜飞度镜湖月。(度 通：渡)
湖月照我影，送我至剡溪。
谢公宿处今尚在，渌水荡漾清猿啼。
脚着谢公屐，身登青云梯。
半壁见海日，空中闻天鸡。
千岩万转路不定，迷花倚石忽已暝。
熊咆龙吟殷岩泉，栗深林兮惊层巅。
云青青兮欲雨，水澹澹兮生烟。
列缺霹雳，丘峦崩摧。
洞天石扉，訇然中开。
青冥浩荡不见底，日月照耀金银台。
霓为衣兮风为马，云之君兮纷纷而来下。
虎鼓瑟兮鸾回车，仙之人兮列如麻。
忽魂悸以魄动，恍惊起而长嗟。
惟觉时之枕席，失向来之烟霞。
世间行乐亦如此，古来万事东流水。
别君去兮何时还？且放白鹿青崖间，须行即骑访名山。
安能摧眉折腰事权贵，使我不得开心颜!','',''),('tangshi300-258','金陵酒肆留别','李白','tangshi300','','七言古诗','风吹柳花满店香，吴姬压酒唤客尝。(劝客 一作：唤客)
金陵子弟来相送，欲行不行各尽觞。
请君试问东流水，别意与之谁短长。','',''),('tangshi300-259','韩碑','李商隐','tangshi300','','七言古诗','元和天子神武姿，彼何人哉轩与羲。
誓将上雪列圣耻，坐法宫中朝四夷。
淮西有贼五十载，封狼生貙貙生罴。
不据山河据平地，长戈利矛日可麾。
帝得圣相相曰度，贼斫不死神扶持。
腰悬相印作都统，阴风惨澹天王旗。
愬武古通作牙爪，仪曹外郎载笔随。
行军司马智且勇，十四万众犹虎貔。
入蔡缚贼献太庙，功无与让恩不訾。
帝曰汝度功第一，汝从事愈宜为辞。
愈拜稽首蹈且舞，金石刻画臣能为。
古者世称大手笔，此事不系于职司。
当仁自古有不让，言讫屡颔天子颐。
公退斋戒坐小阁，濡染大笔何淋漓。
点窜尧典舜典字，涂改清庙生民诗。
文成破体书在纸，清晨再拜铺丹墀。
表曰臣愈昧死上，咏神圣功书之碑。
碑高三丈字如斗，负以灵鳌蟠以螭。
句奇语重喻者少，谗之天子言其私。
长绳百尺拽碑倒，粗砂大石相磨治。
公之斯文若元气，先时已入人肝脾。
汤盘孔鼎有述作，今无其器存其辞。
呜呼圣王及圣相，相与烜赫流淳熙。
公之斯文不示后，曷与三五相攀追。
愿书万本诵万遍，口角流沫右手胝。
传之七十有二代，以为封禅玉检明堂基。','',''),('tangshi300-260','听董大弹胡笳声兼寄语','李颀','tangshi300','','七言古诗','蔡女昔造胡笳声，一弹一十有八拍。
胡人落泪沾边草，汉使断肠对归客。
古戍苍苍烽火寒，大荒沉沉飞雪白。
先拂商弦后角羽，四郊秋叶惊摵摵。
董夫子，通神明，深山窃听来妖精。
言迟更速皆应手，将往复旋如有情。
空山百鸟散还合，万里浮云阴且晴。
嘶酸雏雁失羣夜，断绝胡儿恋母声。
川为静其波，鸟亦罢其鸣。
乌孙部落家乡远，逻娑沙尘哀怨生。
幽音变调忽飘洒，长风吹林雨堕瓦。
迸泉飒飒飞木末，野鹿呦呦走堂下。
长安城连东掖垣，凤凰池对青琐门。
高才脱略名与利，日夕望君抱琴至。','',''),('tangshi300-261','听安万善吹觱篥歌','李颀','tangshi300','','七言古诗','南山截竹为觱篥，此乐本自龟兹出。
流传汉地曲转奇，凉州胡人为我吹。
傍邻闻者多叹息，远客思乡皆泪垂。
世人解听不解赏，长飙风中自来往。
枯桑老柏寒飕飗，九雏鸣凤乱啾啾。
龙吟虎啸一时发，万籁百泉相与秋。
忽然更作渔阳掺，黄云萧条白日暗。
变调如闻杨柳春，上林繁花照眼新。
岁夜高堂列明烛，美酒一杯声一曲。','',''),('tangshi300-262','古意','李颀','tangshi300','','七言古诗','男儿事长征，少小幽燕客。
赌胜马蹄下，由来轻七尺。
杀人莫敢前，须如猬毛磔。
黄云陇底白云飞，未得报恩不能归。
辽东小妇年十五，惯弹琵琶解歌舞。
今为羌笛出塞声，使我三军泪如雨。','',''),('tangshi300-263','送陈章甫','李颀','tangshi300','','七言古诗','四月南风大麦黄，枣花未落桐阴长。
青山朝别暮还见，嘶马出门思旧乡。
陈侯立身何坦荡，虬须虎眉仍大颡。
腹中贮书一万卷，不肯低头在草莽。
东门酤酒饮我曹，心轻万事如鸿毛。
醉卧不知白日暮，有时空望孤云高。
长河浪头连天黑，津口停舟渡不得。
郑国游人未及家，洛阳行子空叹息。
闻道故林相识多，罢官昨日今如何。','',''),('tangshi300-264','琴歌','李颀','tangshi300','','七言古诗','主人有酒欢今夕，请奏鸣琴广陵客。
月照城头乌半飞，霜凄万树风入衣。(万树 一作：万木)
铜炉华烛烛增辉，初弹渌水后楚妃。
一声已动物皆静，四座无言星欲稀。
清淮奉使千余里，敢告云山从此始。','',''),('tangshi300-265','古柏行','杜甫','tangshi300','','七言古诗','孔明庙前有老柏，柯如青铜根如石。
霜皮溜雨四十围，黛色参天二千尺。
君臣已与时际会，树木犹为人爱惜。
云来气接巫峡长，月出寒通雪山白。
忆昨路绕锦亭东，先主武侯同閟宫。
崔嵬枝干郊原古，窈窕丹青户牖空。
落落盘踞虽得地，冥冥孤高多烈风。
扶持自是神明力，正直原因造化工。
大厦如倾要梁栋，万牛回首丘山重。
不露文章世已惊，未辞翦伐谁能送？
苦心岂免容蝼蚁，香叶终经宿鸾凤。
志士幽人莫怨嗟：古来材大难为用。','',''),('tangshi300-266','观公孙大娘弟子舞剑器行','杜甫','tangshi300','','七言古诗','昔有佳人公孙氏，一舞剑器动四方。
观者如山色沮丧，天地为之久低昂。
霍如羿射九日落，矫如羣帝骖龙翔。
来如雷霆收震怒，罢如江海凝清光。
绛唇珠袖两寂寞，晚有弟子传芬芳。
临颍美人在白帝，妙舞此曲神扬扬。
与余问答既有以，感时抚事增惋伤。
先帝侍女八千人，公孙剑器初第一。
五十年间似反掌，风尘澒洞昏王室。
梨园弟子散如烟，女乐余姿映寒日。
金粟堆南木已拱，瞿唐石城草萧瑟。
玳筵急管曲复终，乐极哀来月东出。
老夫不知其所往，足茧荒山转愁疾。','',''),('tangshi300-267','韦讽录事宅观曹将军画马','杜甫','tangshi300','','七言古诗','国初已来画鞍马，神妙独数江都王。
将军得名三十载，人间又见真乘黄。
曾貌先帝照夜白，龙池十日飞霹雳。
内府殷红玛瑙盘，婕妤传诏才人索。
盘赐将军拜舞归，轻纨细绮相追飞。
贵戚权门得笔迹，始觉屏障生光辉。
昔日太宗拳毛騧，近时郭家狮子花。
今之新图有二马，复令识者久叹嗟。
此皆骑战一敌万，缟素漠漠开风沙。
其余七匹亦殊绝，迥若寒空动烟雪。
霜蹄蹴踏长楸间，马官厮养森成列。
可怜九马争神骏，顾视清高气深稳。
借问苦心爱者谁，后有韦讽前支遁。
忆昔巡幸新丰宫，翠华拂天来向东。
腾骧磊落三万匹，皆与此图筋骨同。
自从献宝朝河宗，无复射蛟江水中。
君不见金粟堆前松柏里，龙媒去尽鸟呼风。','',''),('tangshi300-268','丹青引赠曹霸将军','杜甫','tangshi300','','七言古诗','将军魏武之子孙，于今为庶为清门。
英雄割据虽已矣，文采风流今尚存。
学书初学卫夫人，但恨无过王右军。
丹青不知老将至，富贵于我如浮云。
开元之中常引见，承恩数上南薰殿。
凌烟功臣少颜色，将军下笔开生面。
良相头上进贤冠，猛将腰间大羽箭。
褒公鄂公毛发动，英姿飒爽来酣战。
先帝御马五花骢，画工如山貌不同。
是日牵来赤墀下，迥立阊阖生长风。
诏谓将军拂绢素，意匠惨澹经营中。
斯须九重真龙出，一洗万古凡马空。
玉花却在御榻上，榻上庭前屹相向。
至尊含笑催赐金，圉人太仆皆惆怅。
弟子韩干早入室，亦能画马穷殊相。
干惟画肉不画骨，忍使骅骝气凋丧。
将军画善盖有神，必逢佳士亦写真。
即今漂泊干戈际，屡貌寻常行路人。
途穷反遭俗眼白，世上未有如公贫。
但看古来盛名下，终日坎壈缠其身。','',''),('tangshi300-269','寄韩谏议','杜甫','tangshi300','','七言古诗','今我不乐思岳阳，身欲奋飞病在牀。
美人娟娟隔秋水，濯足洞庭望八荒。
鸿飞冥冥日月白，青枫叶赤天雨霜。
玉京羣帝集北斗，或骑麒麟翳凤凰。
芙蓉旌旗烟雾落，影动倒景摇潇湘。
星宫之君醉琼浆，羽人稀少不在旁。
似闻昨者赤松子，恐是汉代韩张良。
昔随刘氏定长安，帷幄未改神惨伤。
国家成败吾岂敢，色难腥腐餐枫香。
周南留滞古所惜，南极老人应寿昌。
美人胡为隔秋水，焉得置之贡玉堂。','',''),('tangshi300-270','夜归鹿门山歌','孟浩然','tangshi300','','七言古诗','山寺钟鸣昼已昏，渔梁渡头争渡喧。
人随沙岸向江村，余亦乘舟归鹿门。
鹿门月照开烟树，忽到庞公栖隐处。
岩扉松径长寂寥，惟有幽人自来去。','',''),('tangshi300-271','渔翁','柳宗元','tangshi300','','七言古诗','渔翁夜傍西岩宿，晓汲清湘燃楚竹。
烟销日出不见人，唉乃一声山水绿。
回看天际下中流，岩上无心云相逐。','',''),('tangshi300-272','登幽州台歌','陈子昂','tangshi300','','七言古诗','前不见古人，后不见来者。
念天地之悠悠，独怆然而涕下。','',''),('tangshi300-273','石鼓歌','韩愈','tangshi300','','七言古诗','张生手持石鼓文，劝我试作石鼓歌。
少陵无人谪仙死，才薄将奈石鼓何。
周纲凌迟四海沸，宣王愤起挥天戈。
大开明堂受朝贺，诸侯剑佩鸣相磨。
搜于岐阳骋雄俊，万里禽兽皆遮罗。
镌功勒成告万世，凿石作鼓隳嵯峨。
从臣才艺咸第一，拣选撰刻留山阿。
雨淋日灸野火燎，鬼物守护烦撝呵。
公从何处得纸本，毫发尽备无差讹。
辞严义密读难晓，字体不类隶与蝌。
年深岂免有缺画，快剑斫断生蛟鼍。
鸾翔凤翥众仙下，珊瑚碧树交枝柯。
金绳铁索锁钮壮，古鼎跃水龙腾梭。
陋儒编诗不收入，二雅褊迫无委蛇。
孔子西行不到秦，掎摭星宿遗羲娥。
嗟余好古生苦晚，对此涕泪双滂沱。
忆昔初蒙博士征，其年始改称元和。
故人从军在右辅，为我度量掘臼科。
濯冠沐浴告祭酒，如此至宝存岂多。
毡包席裹可立致，十鼓只载数骆驼。
荐诸太庙比郜鼎，光价岂止百倍过。
圣恩若许留太学，诸生讲解得切磋。
观经鸿都尚填咽，坐见举国来奔波。
剜苔剔藓露节角，安置妥帖平不颇。
大厦深檐与盖覆，经历久远期无佗。
中朝大官老于事，讵肯感激徒媕婀。
牧童敲火牛砺角，谁复着手为摩挲。
日销月铄就埋没，六年西顾空吟哦。
羲之俗书趁姿媚，数纸尚可博白鹅。
继周八代争战罢，无人收拾理则那。
方今太平日无事，柄任儒术崇丘轲。
安能以此尚论列，愿借辩口如悬河。
石鼓之歌止于此，呜呼吾意其蹉跎。','',''),('tangshi300-274','山石','韩愈','tangshi300','','七言古诗','山石荦确行径微，黄昏到寺蝙蝠飞。
升堂坐阶新雨足，芭蕉叶大栀子肥。
僧言古壁佛画好，以火来照所见稀。
铺牀拂席置羹饭，疏粝亦足饱我饥。
夜深静卧百虫绝，清月出岭光入扉。
天明独去无道路，出入高下穷烟霏。
山红涧碧纷烂漫，时见松枥皆十围。
当流赤足踏涧石，水声激激风吹衣。
人生如此自可乐，岂必局束为人鞿？(鞿 一作：靰)
嗟哉吾党二三子，安得至老不更归。','',''),('tangshi300-275','八月十五夜赠张功曹','韩愈','tangshi300','','七言古诗','纤云四卷天无河，清风吹空月舒波。
沙平水息声影绝，一杯相属君当歌。
君歌声酸辞且苦，不能听终泪如雨。
洞庭连天九疑高，蛟龙出没猩鼯号。
十生九死到官所，幽居默默如藏逃。
下牀畏蛇食畏药，海气湿蛰薰腥臊。
昨者州前捶大鼓，嗣皇继圣登夔皋。
赦书一日行万里，罪从大辟皆除死。
迁者追回流者还，涤瑕荡垢清朝班。
州家申名使家抑，坎轲只得移荆蛮。
判司卑官不堪说，未免捶楚尘埃间。
同时辈流多上道，天路幽险难追攀。
君歌且休听我歌，我歌今与君殊科。
一年明月今宵多，人生由命非由他。
有酒不饮奈明何。','',''),('tangshi300-276','谒衡岳庙遂宿岳寺题门楼','韩愈','tangshi300','','七言古诗','五岳祭秩皆三公，四方环镇嵩当中。
火维地荒足妖怪，天假神柄专其雄。
喷云泄雾藏半腹，虽有绝顶谁能穷？
我来正逢秋雨节，阴气晦昧无清风。
潜心默祷若有应，岂非正直能感通！
须臾静扫众峯出，仰见突兀撑青空。
紫盖连延接天柱，石廪腾掷堆祝融。
森然魄动下马拜，松柏一径趋灵宫。
粉墙丹柱动光彩，鬼物图画填青红。
升阶伛偻荐脯酒，欲以菲薄明其衷。
庙令老人识神意，睢盱侦伺能鞠躬。
手持杯珓导我掷，云此最吉余难同。
窜逐蛮荒幸不死，衣食才足甘长终。
侯王将相望久绝，神纵欲福难为功。
夜投佛寺上高阁，星月掩映云曈昽。
猿鸣钟动不知曙，杲杲寒日生于东。','',''),('tangshi300-277','凉州词','王之涣','tangshi300','','乐府','黄河远上白云间，一片孤城万仞山。
羌笛何须怨杨柳，春风不度玉门关。','',''),('tangshi300-278','出塞·秦时明月汉时关','王昌龄','tangshi300','','乐府','秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。','',''),('tangshi300-279','塞上曲·蝉鸣空桑林','王昌龄','tangshi300','','乐府','蝉鸣空桑林，八月萧关道。
出塞入塞寒，处处黄芦草。
从来幽并客，皆共尘沙老。
莫学游侠儿，矜夸紫骝好。','',''),('tangshi300-280','塞下曲·饮马渡秋水','王昌龄','tangshi300','','乐府','饮马渡秋水，水寒风似刀。
平沙日未没，黯黯见临洮。
昔日长城战，咸言意气高。
黄尘足今古，白骨乱蓬蒿。','',''),('tangshi300-281','长信怨','王昌龄','tangshi300','','乐府','金井梧桐秋叶黄，珠帘不卷夜来霜。
熏笼玉枕无颜色，卧听南宫清漏长。
高殿秋砧响夜阑，霜深犹忆御衣寒。
银灯青琐裁缝歇，还向金城明主看。
奉帚平明金殿开，暂将团扇共徘徊。
玉颜不及寒鸦色，犹带昭阳日影来。
真成薄命久寻思，梦见君王觉后疑。
火照西宫知夜饮，分明覆道奉恩时。
长信宫中秋月明，昭阳殿下捣衣声。
白露堂中细草迹，红罗帐里不胜情。','',''),('tangshi300-282','渭城曲','王维','tangshi300','','乐府','渭城朝雨浥轻尘，客舍青青柳色新。(一作：客舍依依杨柳春)
劝君更尽一杯酒，西出阳关无故人。','',''),('tangshi300-283','秋夜曲','王维','tangshi300','','乐府','桂魄初生秋露微，轻罗已薄未更衣。
银筝夜久殷勤弄，心怯空房不忍归。','',''),('tangshi300-284','洛阳女儿行','王维','tangshi300','','乐府','洛阳女儿对门居，才可颜容十五余。
良人玉勒乘骢马，侍女金盘脍鲤鱼。
画阁朱楼尽相望，红桃绿柳垂檐向。
罗帷送上七香车，宝扇迎归九华帐。
狂夫富贵在青春，意气骄奢剧季伦。
自怜碧玉亲教舞，不惜珊瑚持与人。
春窗曙灭九微火，九微片片飞花琐。
戏罢曾无理曲时，妆成祗是薰香坐。
城中相识尽繁华，日夜经过赵李家。
谁怜越女颜如玉，贫贱江头自浣纱。','',''),('tangshi300-285','老将行','王维','tangshi300','','乐府','少年十五二十时，步行夺得胡马骑。
射杀山中白额虎，肯数邺下黄须儿！
一身转战三千里，一剑曾当百万师。
汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。
卫青不败由天幸，李广无功缘数奇。
自从弃置便衰朽，世事蹉跎成白首。
昔时飞箭无全目，今日垂杨生左肘。
路旁时卖故侯瓜，门前学种先生柳。
苍茫古木连穷巷，寥落寒山对虚牖。
誓令疏勒出飞泉，不似颍川空使酒。
贺兰山下阵如云，羽檄交驰日夕闻。
节使三河募年少，诏书五道出将军。
试拂铁衣如雪色，聊持宝剑动星文。
愿得燕弓射大将，耻令越甲鸣吾君。
莫嫌旧日云中守，犹堪一战取功勋。','',''),('tangshi300-286','桃源行','王维','tangshi300','','乐府','渔舟逐水爱山春，两岸桃花夹古津。
坐看红树不知远，行尽青溪不见人。
山口潜行始隈隩，山开旷望旋平陆。
遥看一处攒云树，近入千家散花竹。
樵客初传汉姓名，居人未改秦衣服。
居人共住武陵源，还从物外起田园。
月明松下房栊静，日出云中鸡犬喧。
惊闻俗客争来集，竞引还家问都邑。
平明闾巷扫花开，薄暮渔樵乘水入。
初因避地去人间，及至成仙遂不还。
峡里谁知有人事，世中遥望空云山。
不疑灵境难闻见，尘心未尽思乡县。
出洞无论隔山水，辞家终拟长游衍。
自谓经过旧不迷，安知峯壑今来变。
当时只记入山深，青溪几度到云林。
春来遍是桃花水，不辨仙源何处寻。','',''),('tangshi300-287','清平调·云想衣裳花想容','李白','tangshi300','','乐府','云想衣裳花想容，春风拂槛露华浓。
若非羣玉山头见，会向瑶台月下逢。','',''),('tangshi300-288','清平调·一枝红艳露凝香','李白','tangshi300','','乐府','一枝红艳露凝香，云雨巫山枉断肠。
借问汉宫谁得似，可怜飞燕倚新妆。','',''),('tangshi300-289','清平调·名花倾国两相欢','李白','tangshi300','','乐府','名花倾国两相欢，常得君王带笑看。
解释春风无限恨，沉香亭北倚栏杆。','',''),('tangshi300-290','行路难·金樽清酒斗十千','李白','tangshi300','','乐府','金樽清酒斗十千，玉盘珍羞直万钱。(羞 通：馐；直 通 值)
停杯投箸不能食，拔剑四顾心茫然。
欲渡黄河冰塞川，将登太行雪满山。(雪满山 一作：雪暗天)
闲来垂钓碧溪上，忽复乘舟梦日边。
行路难！行路难！多歧路，今安在？
长风破浪会有时，直挂云帆济沧海。','',''),('tangshi300-291','行路难·大道如青天','李白','tangshi300','','乐府','大道如青天，我独不得出。
羞逐长安社中儿，赤鸡白雉赌梨栗。
弹剑作歌奏苦声，曳裾王门不称情。
淮阴市井笑韩信，汉朝公卿忌贾生。
君不见昔时燕家重郭隗，拥彗折节无嫌猜。
剧辛乐毅感恩分，输肝剖胆效英才。
昭王白骨萦蔓草，谁人更扫黄金台？
行路难，归去来！','',''),('tangshi300-292','行路难·有耳莫洗颍川水','李白','tangshi300','','乐府','有耳莫洗颍川水，有口莫食首阳蕨。
含光混世贵无名，何用孤高比云月？
吾观自古贤达人，功成不退皆殒身。
子胥既弃吴江上，屈原终投湘水滨。
陆机雄才岂自保？李斯税驾苦不早。
华亭鹤唳讵可闻？上蔡苍鹰何足道？
君不见吴中张翰称达生，秋风忽忆江东行。
且乐生前一杯酒，何须身后千载名？','',''),('tangshi300-293','将进酒','李白','tangshi300','','乐府','君不见，黄河之水天上来，奔流到海不复回。
君不见，高堂明镜悲白发，朝如青丝暮成雪。
人生得意须尽欢，莫使金樽空对月。
天生我材必有用，千金散尽还复来。
烹羊宰牛且为乐，会须一饮三百杯。
岑夫子，丹丘生，将进酒，杯莫停。
与君歌一曲，请君为我倾耳听。(倾耳听 一作：侧耳听)
钟鼓馔玉不足贵，但愿长醉不复醒。(不足贵 一作：何足贵；不复醒 一作：不愿醒/不用醒)
古来圣贤皆寂寞，惟有饮者留其名。(古来 一作：自古；惟 通：唯)
陈王昔时宴平乐，斗酒十千恣欢谑。
主人何为言少钱，径须沽取对君酌。
五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。','',''),('tangshi300-294','玉阶怨','李白','tangshi300','','乐府','玉阶生白露，夜久侵罗袜。
却下水晶帘，玲珑望秋月。(水晶 一作 水精)','',''),('tangshi300-295','长相思·其一','李白','tangshi300','','乐府','长相思，在长安。
络纬秋啼金井阑，微霜凄凄簟色寒。
孤灯不明思欲绝，卷帷望月空长叹。
美人如花隔云端！
上有青冥之长天，下有渌水之波澜。
天长路远魂飞苦，梦魂不到关山难。
长相思，摧心肝！','',''),('tangshi300-296','长相思·其二','李白','tangshi300','','乐府','日色欲尽花含烟，月明欲素愁不眠。(欲素 一作：如素)
赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。
此曲有意无人传，愿随春风寄燕然。
忆君迢迢隔青天，昔日横波目，今作流泪泉。
不信妾断肠，归来看取明镜前。(断肠 一作：肠断)','',''),('tangshi300-297','长干行·其一','李白','tangshi300','','乐府','妾发初覆额，折花门前剧。
郎骑竹马来，绕牀弄青梅。
同居长干里，两小无嫌猜，
十四为君妇，羞颜未尝开。
低头向暗壁，千唤不一回。
十五始展眉，愿同尘与灰。
常存抱柱信，岂上望夫台。
十六君远行，瞿塘滟滪堆。
五月不可触，猿声天上哀。(猿
一作：鸣)
门前迟行迹，一一生绿苔。
苔深不能扫，落叶秋风早。
八月蝴蝶来，双飞西园草。
感此伤妾心，坐愁红颜老。
早晚下三巴，预将书报家。
相迎不道远，直至长风沙。','',''),('tangshi300-298','蜀道难','李白','tangshi300','','乐府','噫吁嚱，危乎高哉！
蜀道之难，难于上青天！
蚕丛及鱼凫，开国何茫然！
尔来四万八千岁，不与秦塞通人烟。
西当太白有鸟道，可以横绝峨眉巅。
地崩山摧壮士死，然后天梯石栈相钩连。
上有六龙回日之高标，下有冲波逆折之回川。
黄鹤之飞尚不得过，猿猱欲度愁攀援。(攀援 一作：攀缘)
青泥何盘盘，百步九折萦岩峦。
扪参历井仰胁息，以手抚膺坐长叹。
问君西游何时还？畏途巉岩不可攀。
但见悲鸟号古木，雄飞雌从绕林间。
又闻子规啼夜月，愁空山。
蜀道之难,难于上青天，使人听此凋朱颜！
连峯去天不盈尺，枯松倒挂倚绝壁。
飞湍瀑流争喧豗，砯崖转石万壑雷。
其险也如此，嗟尔远道之人胡为乎来哉！(也如此 一作：也若此)
剑阁峥嵘而崔嵬，一夫当关，万夫莫开。
所守或匪亲，化为狼与豺。
朝避猛虎，夕避长蛇；磨牙吮血，杀人如麻。
锦城虽云乐，不如早还家。
蜀道之难,难于上青天，侧身西望长谘嗟！','',''),('tangshi300-299','子夜吴歌·春歌','李白','tangshi300','','乐府','秦地罗敷女，采桑绿水边。
素手青条上，红妆白日鲜。
蚕饥妾欲去，五马莫留连。','',''),('tangshi300-300','子夜吴歌·夏歌','李白','tangshi300','','乐府','镜湖三百里，菡萏发荷花。
五月西施采，人看隘若耶。
回舟不待月，归去越王家。','',''),('tangshi300-301','子夜吴歌·秋歌','李白','tangshi300','','乐府','长安一片月，万户捣衣声。
秋风吹不尽，总是玉关情。
何日平胡虏，良人罢远征。','',''),('tangshi300-302','子夜吴歌·冬歌','李白','tangshi300','','乐府','明朝驿使发，一夜絮征袍。
素手抽针冷，那堪把剪刀。
裁缝寄远道，几日到临洮。','',''),('tangshi300-303','关山月','李白','tangshi300','','乐府','明月出天山，苍茫云海间。
长风几万里，吹度玉门关。
汉下白登道，胡窥青海湾。
由来征战地，不见有人还。
戍客望边邑，思归多苦颜。(望边邑 一作：望边色)
高楼当此夜，叹息未应闲。','',''),('tangshi300-304','江南曲','李益','tangshi300','','乐府','嫁得瞿塘贾，朝朝误妾期。
早知潮有信，嫁与弄潮儿。','',''),('tangshi300-305','古从军行','李颀','tangshi300','','乐府','白日登山望烽火，黄昏饮马傍交河。
行人刁斗风沙暗，公主琵琶幽怨多。
野云万里无城郭，雨雪纷纷连大漠。
胡雁哀鸣夜夜飞，胡儿眼泪双双落。
闻道玉门犹被遮，应将性命逐轻车。
年年战骨埋荒外，空见蒲桃入汉家。','',''),('tangshi300-306','哀王孙','杜甫','tangshi300','','乐府','长安城头头白乌，夜飞延秋门上呼。
又向人家啄大屋，屋底达官走避胡。
金鞭断折九马死，骨肉不得同驰驱。
腰下宝玦青珊瑚，可怜王孙泣路隅。
问之不肯道姓名，但道困苦乞为奴。
已经百日窜荆棘，身上无有完肌肤。
高帝子孙尽隆准，龙种自与常人殊。
豺狼在邑龙在野，王孙善保千金躯。
不敢长语临交衢，且为王孙立斯须。
昨夜东风吹血腥，东来橐驼满旧都。
朔方健儿好身手，昔何勇锐今何愚。
窃闻天子已传位，圣德北服南单于。
花门剺面请雪耻，慎勿出口他人狙。
哀哉王孙慎勿疏，五陵佳气无时无。','',''),('tangshi300-307','兵车行','杜甫','tangshi300','','乐府','车辚辚，马萧萧，行人弓箭各在腰。
耶娘妻子走相送，尘埃不见咸阳桥。(
娘 一作：“爷”)
牵衣顿足拦道哭，哭声直上干云霄。
道旁过者问行人，行人但云点行频。
或从十五北防河，便至四十西营田。
去时里正与裹头，归来头白还戍边。
边庭流血成海水，武皇开边意未已。
君不闻，汉家山东二百州，千村万落生荆杞。
纵有健妇把锄犁，禾生陇亩无东西。
况复秦兵耐苦战，被驱不异犬与鸡。
长者虽有问，役夫敢申恨？
且如今年冬，未休关西卒。
县官急索租，租税从何出？
信知生男恶，反是生女好。
生女犹得嫁比邻，生男埋没随百草。
君不见，青海头，古来白骨无人收。
新鬼烦冤旧鬼哭，天阴雨湿声啾啾！','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('tangshi300-308','丽人行','杜甫','tangshi300','','乐府','三月三日天气新，长安水边多丽人。
态浓意远淑且真，肌理细腻骨肉匀。
绣罗衣裳照暮春，蹙金孔雀银麒麟。
头上何所有？翠微盍叶垂鬓唇。
背后何所见？珠压腰衱稳称身。
就中云幕椒房亲，赐名大国虢与秦。
紫驼之峯出翠釜，水精之盘行素鳞。
犀箸厌饫久未下，鸾刀缕切空纷纶。
黄门飞鞚不动尘，御厨络绎送八珍。
箫鼓哀吟感鬼神，宾从杂遝实要津。
后来鞍马何逡巡，当轩下马入锦茵。
杨花雪落覆白苹，青鸟飞去衔红巾。
炙手可热势绝伦，慎莫近前丞相嗔！','',''),('tangshi300-309','哀江头','杜甫','tangshi300','','乐府','少陵野老吞声哭，春日潜行曲江曲。
江头宫殿锁千门，细柳新蒲为谁绿？
忆昔霓旌下南苑，苑中万物生颜色。
昭阳殿里第一人，同辇随君侍君侧。
辇前才人带弓箭，白马嚼啮黄金勒。
翻身向天仰射云，一笑正坠双飞翼。
明眸皓齿今何在？血污游魂归不得。
清渭东流剑阁深，去住彼此无消息。
人生有情泪沾臆，江水江花岂终极！
黄昏胡骑尘满城，欲往城南望城北。','',''),('tangshi300-310','金缕衣','佚名','tangshi300','','乐府','劝君莫惜金缕衣，劝君惜取少年时。(惜取 一作：须取)
花开堪折直须折，莫待无花空折枝。(花开 一作：有花)','',''),('tangshi300-311','独不见','沈佺期','tangshi300','','乐府','卢家少妇郁金堂，海燕双栖玳瑁梁。
九月寒砧催木叶，十年征戍忆辽阳。
白狼河北音书断，丹凤城南秋夜长。
谁谓含愁独不见，更教明月照流黄。','',''),('tangshi300-312','烈女操','孟郊','tangshi300','','乐府','梧桐相待老，鸳鸯会双死。
贞女贵殉夫，舍生亦如此。
波澜誓不起，妾心古井水。(古井水 一作：井中水)','',''),('tangshi300-313','游子吟','孟郊','tangshi300','','乐府','慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。','',''),('tangshi300-314','燕歌行','高适','tangshi300','','乐府','汉家烟尘在东北，汉将辞家破残贼。
男儿本自重横行，天子非常赐颜色。
摐金伐鼓下榆关，旌旆逶迤碣石间。
校尉羽书飞瀚海，单于猎火照狼山。
山川萧条极边土，胡骑凭陵杂风雨。
战士军前半死生，美人帐下犹歌舞。
大漠穷秋塞草腓，孤城落日斗兵稀。
身当恩遇恒轻敌，力尽关山未解围。
铁衣远戍辛勤久，玉箸应啼别离后。
少妇城南欲断肠，征人蓟北空回首。
边庭飘颻那可度，绝域苍茫更何有。
杀气三时作阵云，寒声一夜传刁斗。
相看白刃血纷纷，死节从来岂顾勋。
君不见沙场征战苦，至今犹忆李将军。','',''),('tangshi300-315','长干行·君家何处住','崔颢','tangshi300','','乐府','君家何处住，妾住在横塘。
停船暂借问，或恐是同乡。','',''),('tangshi300-316','长干行·家临九江水','崔颢','tangshi300','','乐府','家临九江水，来去九江侧。
同是长干人，生小不相识。','',''),('tangshi300-317','塞下曲·鹫翎金仆姑','卢纶','tangshi300','','乐府','鹫翎金仆姑，燕尾绣蝥弧。
独立扬新令，千营共一呼。','',''),('tangshi300-318','塞下曲·林暗草惊风','卢纶','tangshi300','','乐府','林暗草惊风，将军夜引弓。
平明寻白羽，没在石棱中。','',''),('tangshi300-319','塞下曲·月黑雁飞高','卢纶','tangshi300','','乐府','月黑雁飞高，单于夜遁逃。
欲将轻骑逐，大雪满弓刀。','',''),('tangshi300-320','塞下曲·野幕敞琼筵','卢纶','tangshi300','','乐府','野幕敞琼筵，羌戎贺劳旋。
醉和金甲舞，雷鼓动山川。','',''),('qianjiashi-001','春眠','孟浩然','qianjiashi','','五言绝句','春眠不觉晓，处处闻啼鸟。
夜来风雨声，花落知多少。','',''),('qianjiashi-002','访袁拾遗不遇','孟浩然','qianjiashi','','五言绝句','洛阳访才子，江岭作流人。
闻说梅花早，何如此地春。','',''),('qianjiashi-003','送郭司仓','王昌齡','qianjiashi','','五言绝句','映门淮水绿，留骑主人心。
明月随良掾，春潮夜夜深。','',''),('qianjiashi-004','洛阳道','儲光羲','qianjiashi','','五言绝句','大道直如发，春来佳气多。
五陵贵公子，双双呜玉珂。','',''),('qianjiashi-005','独坐敬亭山','李白','qianjiashi','','五言绝句','众鸟高飞尽，孤云独去闲。
相看两不厌，只有敬亭山。','',''),('qianjiashi-006','登鹳雀楼','王之渙','qianjiashi','','五言绝句','白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。','',''),('qianjiashi-007','观永乐公主入番','孫逖','qianjiashi','','五言绝句','边地莺花少，年来未觉新。
美人天上落，龙塞始应春。','',''),('qianjiashi-008','伊州歌','金昌緒','qianjiashi','','五言绝句','打起黄莺儿，莫教枝上啼。
啼时惊妾梦，不得到辽西。','',''),('qianjiashi-009','左掖梨花','丘爲','qianjiashi','','五言绝句','冷艳全欺雪，余香乍入衣。
春风且莫定，吹向玉阶飞。','',''),('qianjiashi-010','思君恩','令狐楚','qianjiashi','','五言绝句','小苑莺歌歇，长门蝶舞多。
眼看春又去，翠辇不曾过。','',''),('qianjiashi-011','题袁氏别业','賀知章','qianjiashi','','五言绝句','主人不相识，偶坐为林泉。
莫谩愁沽酒，囊中自有钱。','',''),('qianjiashi-012','夜送赵纵','楊炯','qianjiashi','','五言绝句','赵氏连城璧，由来天下传。
送君还旧府，明月满前川。','',''),('qianjiashi-013','竹里馆','王維','qianjiashi','','五言绝句','独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。','',''),('qianjiashi-014','送朱大入秦','王維','qianjiashi','','五言绝句','避人五陵去，宝剑值千金。
分手脱相赠，平生一片心。','',''),('qianjiashi-015','长干行','崔顥','qianjiashi','','五言绝句','君家在何处？妾住在横塘。
停船暂借问，或恐是同乡。','',''),('qianjiashi-016','咏史','高適','qianjiashi','','五言绝句','尚有绨袍赠，应怜范叔寒。
不知天下士，犹作布衣看。','',''),('qianjiashi-017','罢相作','李適之','qianjiashi','','五言绝句','避贤初罢相，乐圣且衔杯。
为问门前客，今朝几个来。','',''),('qianjiashi-018','逢侠者','錢起','qianjiashi','','五言绝句','燕赵悲歌士，相逢剧孟家。
寸心言不尽，前路日将斜。','',''),('qianjiashi-019','江行望匡庐','錢起','qianjiashi','','五言绝句','咫尺愁风雨，匡庐不可登。
只疑云雾窟，犹有六朝僧。','',''),('qianjiashi-020','答李浣','韋應物','qianjiashi','','五言绝句','林中观易罢，溪上对鸥闲。
楚俗饶词客，何人最往还。','',''),('qianjiashi-021','秋风引','劉禹錫','qianjiashi','','五言绝句','何处秋风至，萧萧送雁羣。
朝来入庭树，孤客最先闻。','',''),('qianjiashi-022','秋夜寄丘员外','韋應物','qianjiashi','','五言绝句','怀君属秋夜，散步咏凉天。
山空松子落，幽人应未眠。','',''),('qianjiashi-023','秋日','耿湋','qianjiashi','','五言绝句','返照入闾巷，忧来谁共语。
古道少人行，秋风动禾黍。','',''),('qianjiashi-024','秋日湖上','薛瑩','qianjiashi','','五言绝句','落日五湖游，烟波处处愁。
浮沉千古事，谁与问东流。','',''),('qianjiashi-025','宫中题','李昂','qianjiashi','','五言绝句','辇路生秋草，上林花满枝。
凭高何限意，无复侍臣知。','',''),('qianjiashi-026','汾上惊秋','蘇頲','qianjiashi','','五言绝句','北风吹白云，万里渡河汾。
心绪逢摇落，秋声不可闻。','',''),('qianjiashi-027','寻隐者不遇','賈島','qianjiashi','','五言绝句','松下问童子，言师采药去。
只在此山中，云深不知处。','',''),('qianjiashi-028','蜀道后期','張說','qianjiashi','','五言绝句','客心争日月，来往预期程。
秋风不相待，先至洛阳城。','',''),('qianjiashi-029','静夜思','李白','qianjiashi','','五言绝句','牀前明月光，疑是地上霜。
举头望明月，低头思故乡。','',''),('qianjiashi-030','秋浦歌','李白','qianjiashi','','五言绝句','白发三千丈，离愁似个长。
不知明镜里，何处得秋霜。','',''),('qianjiashi-031','赠乔侍郎','陳子昂','qianjiashi','','五言绝句','汉廷荣巧宦，云阁薄边功。
可怜骢马使，白首为谁雄。','',''),('qianjiashi-032','答五陵太守','王昌齡','qianjiashi','','五言绝句','仗剑行千里，微躯敢一言。
曾为大梁客，不负信陵恩。','',''),('qianjiashi-033','行军九日思长安故园','岑參','qianjiashi','','五言绝句','强欲登高去，无人送酒来。
遥怜故园菊，应傍战场开。','',''),('qianjiashi-034','婕妤怨','皇甫冉','qianjiashi','','五言绝句','花枝出建章，凤管发昭阳。
借问承恩者，双蛾几许长？','',''),('qianjiashi-035','题竹林寺','朱放','qianjiashi','','五言绝句','岁月人间促，烟霞此地多。
殷勤竹林寺，更得几回过？','',''),('qianjiashi-036','过三闾庙','戴叔倫','qianjiashi','','五言绝句','沅湘流不尽，屈子怨何深！
日暮秋风起，萧萧枫树林。','',''),('qianjiashi-037','易水送别','駱賓王','qianjiashi','','五言绝句','此地别燕丹，壮士发冲冠。
昔时人已没，今日水犹寒。','',''),('qianjiashi-038','别卢秦卿','司空曙','qianjiashi','','五言绝句','知有前期在，难分此夜中。
无将故人酒，不及石尤风。','',''),('qianjiashi-039','答人','太上隱者','qianjiashi','','五言绝句','偶来松树下，高枕石头眠。
山中无历日，寒尽不知年。','',''),('qianjiashi-040','幸蜀回至剑门','李隆基','qianjiashi','','五言律诗','剑阁横云峻，銮舆出狩回。
翠屏千仞合，丹嶂五丁开。
灌木萦旗转，仙云拂马来。
乘时方在德，嗟尔勒铭才。','',''),('qianjiashi-041','和晋陵陆承相','杜審言','qianjiashi','','五言律诗','独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光转绿苹。
忽闻歌古调，归思欲沾巾。','',''),('qianjiashi-042','蓬莱三殿侍宴奉敕咏终南山','杜審言','qianjiashi','','五言律诗','北斗挂城边，南山倚殿前。
云标金阙回，树杪玉堂悬。
半岭通佳气，中峯绕瑞烟。
小臣持献寿，长此戴尧天。','',''),('qianjiashi-043','春夜别友人','陳子昂','qianjiashi','','五言律诗','银烛吐青烟，金尊对绮筵。
离堂思琴瑟，别路绕山川。
明月悬高树，长河没晓天。
悠悠洛阳道，此会在何年。','',''),('qianjiashi-044','长宁公主东庄侍宴','李嶠','qianjiashi','','五言律诗','别业临青甸，鸣銮降紫霄。
长筵鵷鹭集，仙管凤凰调。
树接南山近，烟含北渚遥。
承恩咸已醉，恋赏未还镳。','',''),('qianjiashi-045','恩赐丽正殿书院赐宴应制得林字','張說','qianjiashi','','五言律诗','东壁图书府，西园翰墨林。
诵诗闻国政，讲易见天心。
位窃和羹重，恩叨醉酒深。
载歌春兴曲，情竭为知音。','',''),('qianjiashi-046','送友人','李白','qianjiashi','','五言律诗','青山横北郭，白水绕东城。
此地一为别，孤篷万里征。
浮云游子意，落日故人情。
挥手自兹去，萧萧斑马鸣。','',''),('qianjiashi-047','送友人入蜀','李白','qianjiashi','','五言律诗','见说蚕丛路，崎岖不易行。
山从人面起，云傍马头生。
芳树笼秦栈，春流绕蜀城。
升沈应已定，不必问君平。','',''),('qianjiashi-048','次北固山下','王灣','qianjiashi','','五言律诗','客路青山外，行舟绿水前。
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达，归雁洛阳边。','',''),('qianjiashi-049','苏氏别业','祖詠','qianjiashi','','五言律诗','别业居幽处，到来生隐心。
南山当户牖，澧水映园林。
竹覆经冬雪，庭昏未夕阴。
寥寥人境外，闲坐听春禽。','',''),('qianjiashi-050','春宿左省','杜甫','qianjiashi','','五言律诗','花隐掖垣暮，啾啾栖鸟过。
星临万户动，月傍九霄多。
不寝听金钥，因风想玉坷。
明朝有封事，数问夜如何？','',''),('qianjiashi-051','题玄武禅师屋壁','杜甫','qianjiashi','','五言律诗','何年顾虎头，满壁画沧州。
赤日石林气，青天江海流。
锡飞常近鹤，杯渡不惊鸥。
似得庐山路，真随惠远游。','',''),('qianjiashi-052','终南山','王維','qianjiashi','','五言律诗','太乙近天都，连山到海隅。
白云回望合，青霭入看无。
分野中峯变，阴晴众壑殊。
欲投何处宿，隔水问樵夫。','',''),('qianjiashi-053','登总持阁','岑參','qianjiashi','','五言律诗','高阁逼诸天，登临近日边。
晴开万井树，愁看五陵烟。
槛外低秦岭，窗中小渭川。
早知清净理，常愿奉金仙。','',''),('qianjiashi-054','寄左省杜拾遗','岑參','qianjiashi','','五言律诗','联步趋丹陛，分曹限紫薇。
晓随天仗入，暮惹御香归。
白发悲花落，青云羡鸟飞。
圣朝无阙事，自觉谏书稀。','',''),('qianjiashi-055','登兖州城楼','杜甫','qianjiashi','','五言律诗','东郡趋庭日，南楼纵目初。
浮云连海岱，平野入青徐。
孤嶂秦碑在，荒城鲁殿余。
从来多古意，临眺独踌躇。','',''),('qianjiashi-056','杜少府之任蜀州','王勃','qianjiashi','','五言律诗','城阙辅三秦，风烟望五津。
与君离别意，同是宦游人。
海内存知己，天涯若比邻。
无为在歧路，儿女共沾巾。','',''),('qianjiashi-057','送崔融','杜審言','qianjiashi','','五言律诗','君王行出将，书记远从征。
祖帐连河阙，军麾动洛城。
旌旗朝朔气，笳吹夜边声。
坐觉烟尘少，秋风古北平。','',''),('qianjiashi-058','扈从登封途中作','宋之問','qianjiashi','','五言律诗','帐殿郁崔嵬，仙游实壮哉！
晓云连幕卷，夜火杂星回。
谷暗千旗出，山鸣万乘来。
扈从良可赋，终乏掞天才。','',''),('qianjiashi-059','题义公禅房','孟浩然','qianjiashi','','五言律诗','义公习禅寂，结宇依空林。
户外一峯秀，阶前众壑深。
夕阳连雨足，空翠落庭阴。
看取莲花净，方知不染心。','',''),('qianjiashi-060','醉后赠张九旭','高適','qianjiashi','','五言律诗','世上漫相识，此翁殊不然。
兴来书自圣，醉后语尤颠。
白发老闲事，青云在目前。
牀头一壶酒，能更几回眠。','',''),('qianjiashi-061','玉台观','高適','qianjiashi','','五言律诗','浩劫因王造，平台访古游。
彩云萧史驻，文字鲁恭留。
宫阙通羣帝，干坤到十洲。
人传有笙鹤，时过北山头。','',''),('qianjiashi-062','观李固请司马弟山水图','杜甫','qianjiashi','','五言律诗','方丈浑连水，天台总映云。
人间长见画，老去限空闻。
范蠡舟偏小，王乔鹤不羣。
此生随万物，何处出尘氛。','',''),('qianjiashi-063','旅夜书怀','杜甫','qianjiashi','','五言律诗','细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章着，官因老病休。
飘飘何所似，天地一沙鸥。','',''),('qianjiashi-064','登岳阳楼','杜甫','qianjiashi','','五言律诗','昔闻洞庭水，今上岳阳楼。
吴楚东南坼，干坤日月浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。','',''),('qianjiashi-065','江南旅情','祖詠','qianjiashi','','五言律诗','楚山不可极，归路但萧条。
海色晴看雨，江声夜听潮。
剑留南斗近，书寄北风遥。
为报空潭橘，无媒寄洛桥。','',''),('qianjiashi-066','宿龙兴寺','綦毋潛','qianjiashi','','五言律诗','香刹夜忘归，松清古殿扉。
灯明方丈室，珠系比丘衣。
白日传心净，青莲喻法微。
天花落不尽，处处鸟衔飞。','',''),('qianjiashi-067','破山寺后禅院','常建','qianjiashi','','五言律诗','清晨入古寺，初日照高林。
曲径通幽处，禅房花木深。
山光悦鸟性，潭影空人心。
万籁此俱寂，惟闻钟磬音。','',''),('qianjiashi-068','题松汀驿','張佑','qianjiashi','','五言律诗','山色远含空，苍茫泽国东。
海明先见日，江白迥闻风。
鸟道高原去，人烟小径通。
那知旧遗逸，不在五湖中。','',''),('qianjiashi-069','圣果寺','釋處默','qianjiashi','','五言律诗','路自中峯上，盘回出薜萝。
到江吴地尽，隔岸越山多。
古木丛青蔼，遥天浸白波。
下方城郭近，钟磬杂笙歌。','',''),('qianjiashi-070','野望','王績','qianjiashi','','五言律诗','东皋薄暮望，徙倚欲何依。
树树皆秋色，山山惟落晖。
牧人驱犊返，猎马带禽归。
相顾无相识，长歌怀采薇。','',''),('qianjiashi-071','送着作佐郎崔融等从梁王东征','陳子昂','qianjiashi','','五言律诗','金天方肃杀，白露始专征。
王师非乐战，之子慎佳兵。
海气侵南部，边风扫北平。
莫卖卢龙塞，归邀麟阁名。','',''),('qianjiashi-072','携妓纳凉晚际遇雨','杜甫','qianjiashi','','五言律诗','[object Object]
[object Object]','',''),('qianjiashi-073','宿云门寺阁','孫逖','qianjiashi','','五言律诗','香阁东山下，烟花象外幽。
悬灯千嶂夕，卷幔五湖秋。
画壁余鸿雁，纱窗宿斗牛。
更疑天路近，梦与白云游。','',''),('qianjiashi-074','秋登宣城谢眺北楼','李白','qianjiashi','','五言律诗','江城如画里，山晚望晴空。
两水夹明镜，双桥落彩虹。
人烟寒橘柚，秋色老梧桐。
谁念北楼上，临风怀谢公。','',''),('qianjiashi-075','临洞庭','孟浩然','qianjiashi','','五言律诗','八月湖水平，涵虚混太清。
气蒸云梦泽，波撼岳阳城。
欲济无舟楫，端居耻圣明。
坐观垂钓者，徒有羡鱼情。','',''),('qianjiashi-076','过香积寺','王維','qianjiashi','','五言律诗','不知香积寺，数里入云峯。
古木无人径，深山何处钟。
泉声咽危石，日色冷青松。
薄暮空潭曲，安禅制毒龙。','',''),('qianjiashi-077','送郑侍御谪闽中','高適','qianjiashi','','五言律诗','谪去君无恨，闽中我旧过。
大都秋雁少，只是夜猿多。
东路云山合，南天瘴疠和。
自当逢雨露，行矣顺风波。','',''),('qianjiashi-078','秦州杂诗','杜甫','qianjiashi','','五言律诗','凤林戈未息，鱼海路常难。
候火云峯峻，悬军幕井干。
风连西极动，月过北庭寒。
故老思飞将，何时议筑坛。','',''),('qianjiashi-079','禹庙','杜甫','qianjiashi','','五言律诗','禹庙空山里，秋风落日斜。
荒庭垂橘柚，古屋画龙蛇。
云气生虚壁，江深走白沙。
早知乘四载，疏凿控三巴。','',''),('qianjiashi-080','望秦川','李頎','qianjiashi','','五言律诗','秦川朝望迥，日出正东峯。
远近山河净，逶迤城阙重。
秋声万户竹，寒色五陵松。
有客归欤叹，凄其霜露浓。','',''),('qianjiashi-081','同王征君洞庭有怀','張謂','qianjiashi','','五言律诗','八月洞庭秋，潇湘水北流。
还家万里梦，为客五更愁。
不用开书帙，偏宜上酒楼。
故人京洛满，何日复同游。','',''),('qianjiashi-082','渡扬子江','丁仙芝','qianjiashi','','五言律诗','桂楫中流望，空波两岸明。
林开扬子驿，山出润州城。
海尽边阴静，江寒朔吹生。
更闻枫叶下，淅沥度秋声。','',''),('qianjiashi-083','幽州夜歌','張說','qianjiashi','','五言律诗','凉风吹夜雨，萧瑟动寒林。
正有高堂宴，能忘迟暮心。
军中宜剑舞，塞上重笳音。
不作边城将，谁知恩遇深。','',''),('qianjiashi-084','春日偶成','程顥','qianjiashi','','七言绝句','云淡风轻近午天，傍花随柳过前川。
时人不识余心乐，将谓偷闲学少年。','',''),('qianjiashi-085','春日','朱熹','qianjiashi','','七言绝句','胜日寻芳泗水滨，无边光景一时新。
等闲识得东风面，万紫千红总是春。','',''),('qianjiashi-086','春宵','蘇軾','qianjiashi','','七言绝句','春宵一刻值千金，花有清香月有阴。
歌管楼台声细细，秋千院落夜沈沈。','',''),('qianjiashi-087','城东早春','楊巨源','qianjiashi','','七言绝句','诗家清景在新春，绿柳才黄半未匀。
若待上林花似锦，出门俱是看花人。','',''),('qianjiashi-088','春夜','王安石','qianjiashi','','七言绝句','金炉香烬漏声残，剪剪轻风阵阵寒。
春色恼人眠不得，月移花影上栏杆。','',''),('qianjiashi-089','初春小雨','韓愈','qianjiashi','','七言绝句','天街小雨润如酥，草色遥看近却无。
最是一年春好处，绝胜烟柳满皇都。','',''),('qianjiashi-090','元日','王安石','qianjiashi','','七言绝句','爆竹声中一岁除，春风送暖入屠苏。
千门万户曈曈日，总把新桃换旧符。','',''),('qianjiashi-091','上元侍宴','蘇軾','qianjiashi','','七言绝句','淡月疏星绕建章，仙风吹下御炉香。
侍臣鹄立通明殿，一朵红云捧玉皇。','',''),('qianjiashi-092','立春偶成','張栻','qianjiashi','','七言绝句','律回岁晚冰霜少，春到人间草木知。
便觉眼前生意满，东风吹水绿参差。','',''),('qianjiashi-093','打球图','晁無咎','qianjiashi','','七言绝句','阊阖千门万户开，三郎沈醉打球回。
