九天阊阖开宫殿，万国衣冠拜冕旒。
日色才临仙掌动，香菸欲傍衮龙浮。
朝罢须裁五色诏，佩声归到凤池头。','',''),('qianjiashi-179','和贾舍人早朝','岑參','qianjiashi','','七言律诗','鸡鸣紫陌曙光寒，莺啭皇州春色阑。
金阙晓钟开万户，玉阶仙仗拥千官。
花迎剑佩星初落，柳拂旌旗露未干。
独有凤凰池上客，阳春一曲和皆难。','',''),('qianjiashi-180','上元应制','蔡襄','qianjiashi','','七言律诗','高列千峯宝炬森，端门方喜翠华临。
宸游不为三元夜，乐事还同万众心。
天上清光留此夕，人间和气阁春阴。
要知尽庆华封祝，四十余年惠爱深。','',''),('qianjiashi-181','上元应制','王淇','qianjiashi','','七言律诗','雪消华月满仙台，万烛当楼宝扇开。
双凤云中扶辇下，六鳌海上驾山来。
镐京春酒沾周宴，汾水秋风陋汉才。
一曲升平人尽乐，君王又进紫霞杯。','',''),('qianjiashi-182','侍宴','沈佺期','qianjiashi','','七言律诗','皇家贵主好神仙，别业初开云汉边。
山出尽如鸣凤岭，池成不让饮龙川。
妆楼翠幌教春住，舞阁金铺借日悬。
敬从乘舆来此地，称觞献寿乐钧天。','',''),('qianjiashi-183','答丁元珍','歐陽修','qianjiashi','','七言律诗','春风疑不到天涯，二月山城未见花。
残雪压枝犹有橘，冻雷惊笋欲抽芽。
夜闻啼雁生乡思，病入新年感物华。
曾是洛阳花下客，野芳虽晚不须嗟。','',''),('qianjiashi-184','插花吟','邵雍','qianjiashi','','七言律诗','头上花枝照酒卮，酒卮中有好花枝。
身经两世太平日，眼见四朝全盛时。
况复筋骸粗康健，那堪时节正芳菲。
酒涵花影红光溜，争忍花前不醉归。','',''),('qianjiashi-185','寓意','晏殊','qianjiashi','','七言律诗','油壁香车不再逢，峡云无迹任西东。
梨花院落溶溶月，柳絮池塘淡淡风。
几日寂寥伤酒后，一番萧瑟禁菸中。
鱼书欲寄何由达，水远山长处处同。','',''),('qianjiashi-186','寒食书事','趙鼎','qianjiashi','','七言律诗','寂寂柴门村落里，也教插柳纪年华。
禁菸不到粤人国，上冢亦携庞老家。
汉寝唐陵无麦饭，山溪野径有梨花。
一樽竟藉青苔卧，莫管城头奏暮笳。','',''),('qianjiashi-187','清明','黃庭堅','qianjiashi','','七言律诗','佳节清明桃李笑，野田荒冢只生愁。
雷惊天地龙蛇蛰，雨足郊原草木柔。
人乞祭余骄妾妇，士甘焚死不公侯。
贤愚千载知谁是，满眼蓬蒿共一丘。','',''),('qianjiashi-188','清明','高菊卿','qianjiashi','','七言律诗','南北山头多墓田，清明祭扫各纷然。
纸灰飞作白蝴蝶，泪血染成红杜鹃。
日落狐狸眠冢上，夜归儿女笑灯前。
人生有酒须当醉，一滴何曾到九泉。','',''),('qianjiashi-189','郊行即事','程顥','qianjiashi','','七言律诗','芳原绿野恣行时，春入遥山碧四围。
兴逐乱红穿柳巷，困临流水坐苔矶。
莫辞盏酒十分劝，只恐风花一片飞。
况是清明好天气，不妨游衍莫忘归。','',''),('qianjiashi-190','秋千','僧惠洪','qianjiashi','','七言律诗','画架双裁翠络偏，佳人春戏小楼前。
飘扬血色裙拖地，断送玉容人上天。
花皮润沾红杏雨，彩绳斜挂绿杨烟。
下来闲处从容立，疑是蟾宫谪神仙。','',''),('qianjiashi-191','曲江对酒','杜甫','qianjiashi','','七言律诗','[object Object]
[object Object]','',''),('qianjiashi-192','黄鹤楼','崔顥','qianjiashi','','七言律诗','昔人已乘黄鹤去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，芳草萋萋鹦鹉州。
日暮乡关何处是，烟波江上使人愁。','',''),('qianjiashi-193','旅怀','崔塗','qianjiashi','','七言律诗','水流花谢两无情，送尽东风过楚城。
蝴蝶梦中家万里，杜鹃枝上月三更。
故园书动经年绝，华发春催两鬓生。
自是不归归便得，五湖烟景有谁争。','',''),('qianjiashi-194','答李儋','韋應物','qianjiashi','','七言律诗','去年花里逢君别，今日花开又一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几回圆。','',''),('qianjiashi-195','江村','杜甫','qianjiashi','','七言律诗','清江一曲抱村流，长夏江村事事幽。
自去自来梁上燕，相亲相近水中鸥。
老妻画纸为棋局，稚子敲针作钓钩。
多病所须惟药物，微躯此外更何求。','',''),('qianjiashi-196','夏日','張文潛','qianjiashi','','七言律诗','长夏江村风日清，檐牙燕雀已生成。
蝶衣晒粉花枝午，蛛网添丝屋角晴。
落落疏廉邀月影，嘈嘈虚枕纳溪声。
久斑两鬓如霜雪，直欲樵渔过此生。','',''),('qianjiashi-197','积雨辋川庄作','王維','qianjiashi','','七言律诗','积雨空林烟火迟，蒸藜炊黍饷东菑。
漠漠水田飞白鹭，阴阴夏木啭黄鹂。
山中习静合朝槿，松下清斋折露葵。
野老与人争席罢，海鸥何事更相疑。','',''),('qianjiashi-198','新竹','陸游','qianjiashi','','七言律诗','插棘编篱谨护持，养成寒碧映涟漪。
清风掠地秋先到，赤日行天午不知。
解箨时闻声簌簌，放梢初见影离离。
归闲我欲频来此，枕簟仍教到处随。','',''),('qianjiashi-199','偶成','程顥','qianjiashi','','七言律诗','闲来无事不从容，睡觉东窗日已红。
万物静观皆自得，四时佳兴与人同。
道通天地有形外，思入风云变态中。
富贵不淫贫贱乐，男儿到此是豪雄。','',''),('qianjiashi-200','表兄话旧','竇叔向','qianjiashi','','七言律诗','夜合花开香满庭，夜深微雨醉初醒。
远书珍重何由达，旧事凄凉不可听。
去日儿童皆长大，昔年亲友半凋零。
明朝又是孤舟别，愁见河桥酒幔青。','',''),('qianjiashi-201','游月陂','程顥','qianjiashi','','七言律诗','月坡堤上四徘徊，北有中天百尺台。
万物已随秋气改，一樽聊为晚凉开。
水心云影闲相照，林下泉声静自来。
世事无端何足计，但逢佳节约重陪。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('qianjiashi-202','秋兴八首','杜甫','qianjiashi','','七言律诗','[object Object]
[object Object]
[object Object]
[object Object]','',''),('qianjiashi-203','月夜舟中','戴復古','qianjiashi','','七言律诗','满船明月浸虚空，绿水无痕夜气冲。
诗思浮沈樯影里，梦魂摇拽橹声中。
星辰冷落碧潭水，鸿雁悲鸣红蓼风。
数点渔灯依古岸，断桥垂露滴梧桐。','',''),('qianjiashi-204','长安秋望','趙嘏','qianjiashi','','七言律诗','云物凄凉拂署流，汉家宫阙动高秋。
残星几点雁横塞，长笛一声人倚楼。
紫艳半开篱菊静，红衣落尽渚莲愁。
鲈鱼正美不归去，空戴南冠学楚囚。','',''),('qianjiashi-205','新秋','杜甫','qianjiashi','','七言律诗','火云犹未敛奇峯，欹枕初惊一叶风。
几处园林萧瑟里，谁家砧杵寂寥中。
蝉声断续悲残月，萤焰高低照暮空。
赋就金门期再献，夜深搔首叹飞蓬。','',''),('qianjiashi-206','中秋','李樸','qianjiashi','','七言律诗','皓魄当空宝镜升，云间仙籁寂无声。
平分秋色一轮满，长伴云衢千里明。
狡兔空从弦外落，妖蟆休向眼前生。
灵槎拟约同携手，更待银河澈底清。','',''),('qianjiashi-207','九日蓝耕会饮','杜甫','qianjiashi','','七言律诗','老去悲秋强自宽，兴来今日尽君欢。
羞将短发还吹帽，笑倩旁人为正冠。
蓝水远从千涧落，玉山高并两峯寒。
明年此会知谁健，醉把茱萸仔细看。','',''),('qianjiashi-208','秋思','陸游','qianjiashi','','七言律诗','利欲驱人万火牛，江湖浪迹一沙鸥。
日长似岁闲方觉，事大如天醉亦休。
砧杵敲残深巷月，梧桐摇落故园秋。
欲舒老眼无高处，安得元龙百尺楼。','',''),('qianjiashi-209','与朱山人','杜甫','qianjiashi','','七言律诗','锦里先生乌角巾，园收芋栗未全贫。
惯看宾客儿童喜，得食阶除鸟雀驯。
秋水才深四五尺，野航恰受两三人。
白沙翠竹江村暮，相送柴门月色新。','',''),('qianjiashi-210','闻笛','趙嘏','qianjiashi','','七言律诗','谁家吹笛画楼中，断续声随断续风。
响遏行云横碧落，清和冷月到帘栊。
兴来三弄有桓子，赋就一篇怀马融。
曲罢不知人在否，余音嘹亮尚飘空。','',''),('qianjiashi-211','冬景','劉克莊','qianjiashi','','七言律诗','晴窗早觉爱朝曦，竹外秋声渐作威。
命仆安排新暖阁，呼童熨贴旧寒衣。
叶浮嫩绿酒初熟，橙切香黄蟹正肥。
蓉菊满园皆可羡，赏心从此莫相违。','',''),('qianjiashi-212','冬至','杜甫','qianjiashi','','七言律诗','天时人事日相催，冬至阳生春又来。
刺绣五纹添弱线，吹葭六管动飞灰。
岸容待腊将舒柳，山意冲寒欲放梅。
云物不殊乡国异，教儿且覆掌中杯。','',''),('qianjiashi-213','梅花','林逋','qianjiashi','','七言律诗','众芳摇落独鲜妍，占断风情向小园。
疏影横斜水清浅，暗香浮动月黄昏。
霜禽欲下先偷眼，粉蝶如知合断魂。
幸有微吟可相狎，不须檀板共金樽。','',''),('qianjiashi-214','左迁至蓝关示侄孙湘','韓愈','qianjiashi','','七言律诗','一封朝奏九重天，夕贬潮阳路八千。
本为圣朝除弊政，敢将衰朽惜残年。
云横秦岭家何在，雪拥蓝关马不前。
知汝远来应有意，好收吾骨瘴江边。','',''),('qianjiashi-215','干戈','王中','qianjiashi','','七言律诗','干戈未定欲何之，一事无成两鬓丝。
踪迹大纲王粲传，情怀小样杜陵诗。
鹡鸰音断人千里，乌鹊巢寒月一枝。
安得中山千日酒，酩然直到太平时。','',''),('qianjiashi-216','归隐','陳摶','qianjiashi','','七言律诗','十年踪迹走红尘，回首青山入梦频。
紫绶纵荣争及睡，朱门虽富不如贫。
愁闻剑戟扶危主，闷听笙歌聒醉人。
携取旧书归旧隐，野花啼鸟一般春。','',''),('qianjiashi-217','山中寡妇','杜荀鶴','qianjiashi','','七言律诗','夫因兵乱守蓬茅，麻苎裙衫鬓发焦。
桑柘废来犹纳税，田园荒尽尚征苗。
时挑野菜和根煮，旋砍生柴带叶烧。
任是深山最深处，也应无计避征徭。','',''),('qianjiashi-218','送天师','朱權','qianjiashi','','七言律诗','霜落芝城柳影疏，殷勤送客出鄱湖。
黄金甲锁雷霆印，红锦韬缠日月符。
天上晓行骑只鹤，人间夜宿解双凫。
匆匆归到神仙府，为问蟠桃熟也无。','',''),('qianjiashi-219','送毛伯温','明世宗','qianjiashi','','七言律诗','大将南征胆气豪，腰横秋水雁翎刀。
风吹鼍鼓山河动，电闪旌旗日月高。
天上麒麟原有种，穴中蝼蚁岂能逃。
太平待诏归来日，朕与先生解战袍。','',''),('songci300-001','湘春夜月','黄孝迈','songci300','湘春夜月','','近清明。
翠禽枝上消魂。
可惜一片清歌，都付与黄昏。
欲共柳花低诉，怕柳花轻薄，不解伤春。
念楚乡旅宿，柔情别绪，谁与温存。
空樽夜泣，青山不语，残月当门。
翠玉楼前，惟是有、一波湘水，摇荡湘云。
天长梦短，问甚时、重见桃根。
这次第，算人间没个并刀，翦断心上愁痕。','',''),('songci300-002','瑞鹤仙','陆睿','songci300','瑞鹤仙','','湿云黏雁影。
望征路愁迷，离绪难整。
千金买光景。
但疏钟催晓，乱鸦啼暝。
花暗省。
许多情、相逢梦境。
便行云、都不归来，也合寄将音信。
孤迥。
盟鸾心在，跨鹤程高，后期无准。
情丝待翦。
翻惹得，旧时恨。
怕天教何处，参差双燕，还染残朱剩粉。
对菱花、与说相思，看谁瘦损。','',''),('songci300-003','渡江云三犯・渡江云','吴文英','songci300','渡江云三犯・渡江云','','羞红颦浅恨，晚风为落，片绣点重茵。
旧堤分燕尾，桂棹轻鸥，宝勒倚残云。
千丝怨碧，渐路入、仙坞迷津。
肠漫回，隔花时见，背面楚腰身。
逡巡。
题门惆怅，堕履牵萦，数幽期难准。
还始觉、留情缘眼，宽带因春。
明朝事与孤烟冷，做满湖、风雨愁人。
山黛暝，尘波澹绿无痕。','',''),('songci300-004','霜叶飞','吴文英','songci300','霜叶飞','','断烟离绪。
关心事，斜阳红隐霜树。
半壶秋水荐黄花，香西风雨。
纵玉勒、轻飞迅羽。
凄凉谁吊荒台古。
记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。
聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。
小蟾斜影转东篱，夜冷残蛩语。
早白发、缘愁万缕。
惊飙从卷乌纱去。
漫细将、茱萸看，但约明年，翠微高处。','',''),('songci300-005','瑞鹤仙','吴文英','songci300','瑞鹤仙','','晴丝牵绪乱。
对沧江斜日，花飞人远。
垂杨暗吴苑。
正旗亭烟冷，河桥风暖。
兰情蕙盼。
惹相思、春根酒畔。
又争知、吟骨萦销，渐把旧衫重翦。
凄断。
流红千浪，缺月孤楼，总难留燕。
歌尘凝扇。
待凭信，拌分钿。
试挑灯欲写，还依不忍，笺幅偷和泪卷。
寄残云、剩雨蓬莱，也应梦见。','',''),('songci300-006','宴清都','吴文英','songci300','宴清都','','绣幄鸳鸯柱。
红情密，腻云低护秦树。
芳根兼倚，花梢钿合，锦屏人妒。
东风睡足交枝，正梦花、瑶钗燕股。
障滟蜡、满照欢丛，嫠蟾冷落羞度。
人间万感幽单，华清惯浴，春盎风露。
连鬟并暖，同心共结，向承恩处。
凭谁为歌长恨，暗殿锁、秋灯夜语。
叙旧期、不负春盟，红朝翠暮。','',''),('songci300-007','齐天乐','吴文英','songci300','齐天乐','','烟波桃叶西陵路，十年断魂潮尾。
古柳重攀，轻鸥聚别，陈迹危亭独倚。
凉飔乍起。
渺烟碛飞帆，暮山横翠。
但有江花，共临秋镜照憔悴。
华堂烛暗送客，眼波回盼处，芳艳流水。
素骨凝冰，柔葱蘸雪，犹忆分瓜深意。
清尊未洗。
梦不湿行云，漫沾残泪。
可惜秋宵，乱蛩疏雨里。','',''),('songci300-008','风入松','吴文英','songci300','风入松','','听风听雨过清明。
愁草瘗花铭。
楼前绿暗分携路，一丝柳、一寸柔情。
料峭春寒中酒，交加晓梦啼莺。
西园日日扫林亭。
依旧赏新晴。
黄蜂频扑秋千索，有当时、纤手香凝。
惆怅双鸳不到，幽阶一夜苔生。','',''),('songci300-009','莺啼序','吴文英','songci300','莺啼序','','残寒正欺病酒，掩沈香绣户。
燕来晚、飞入西城，似说春事迟暮。
画船载、清明过却，晴烟冉冉吴宫树。
念羁情游荡，随风化为轻絮。
十载西湖，傍柳系马，趁娇尘软雾。
溯红渐、招入仙溪，锦儿偷寄幽素。
倚银屏、春宽梦窄，断红湿、歌纨金缕。
暝堤空，轻把斜阳，总还鸥鹭。
幽兰旋老，杜若还生，水乡尚寄旅。
别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。
长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。
青楼彷佛，临分败壁题诗，泪墨惨澹尘土。
危亭望极，草色天涯，吹鬓侵半苎。
暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。
殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。
伤心千里江南，怨曲重招，断魂在否。','',''),('songci300-010','惜黄花慢','吴文英','songci300','惜黄花慢','','送客吴皋。
正试霜夜冷，枫落长桥。
望天不尽，背城渐杳，离亭黯黯，恨水迢迢。
翠香零落红衣老，暮愁锁、残柳眉梢。
念瘦腰。
沈郎旧日，曾系兰桡。
仙人凤咽琼箫。
怅断魂送远，九辨难招。
醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。
素秋不解随船去，败红趁、一叶寒涛。
梦翠翘。
怨鸿料过南谯。','',''),('songci300-011','瑞鹤仙','袁去华','songci300','瑞鹤仙','','郊原初过雨。
见败叶零乱，风定犹舞。
斜阳挂深树。
映浓愁浅黛，遥山眉妩。
来时旧路。
尚岩花、娇黄半吐。
到而今，唯有溪边流水，见人如故。
无语。
邮亭深静，下马还寻，旧曾题处。
无聊倦旅。
伤离恨，最愁苦。
纵收香藏镜，他年重到，人面桃花在否。
念沈沈、小阁幽窗，有时梦去。','',''),('songci300-012','剑器近','袁去华','songci300','剑器近','','夜来雨。
赖倩得、东风吹住。
海棠正妖饶处。
且留取。
悄庭户。
试细听、莺啼燕语。
分明共人愁绪。
怕春去。
佳树。
翠阴初转午。
重帘未卷，乍睡起、寂寞看风絮。
偷弹清泪寄烟波，见江头故人，为言憔悴如许。
彩笺无数。
去却寒暄，到了浑无定据。
断肠落日千山暮。','',''),('songci300-013','安公子','袁去华','songci300','安公子','','弱柳丝千缕。
嫩黄匀遍鸦啼处。
寒入罗衣春尚浅，过一番风雨。
问燕子来时，绿水桥边路。
曾画楼、见个人人否。
料静掩云窗，尘满哀弦危柱。
庾信愁如许。
为谁都着眉端聚。
独立东风弹泪眼，寄烟波东去。
念永昼春闲，人倦如何度。
闲傍枕、百啭黄鹂语。
唤觉来厌厌，残照依然花坞。','',''),('songci300-014','卜算子','陆游','songci300','卜算子','','驿外断桥边，寂寞开无主。
已是黄昏独自愁，更着风和雨。
无意苦争春，一任群芳妒。
零落成泥碾作尘，只有香如故。','',''),('songci300-015','凤箫吟・芳草','韩缜','songci300','凤箫吟・芳草','','锁离愁，连绵无际，来时陌上初熏。
绣帏人念远，暗垂珠泪，泣送征轮。
长亭长在眼，更重重、远水孤云。
但望极楼高，尽日目断王孙。
消魂。
池塘别后，曾行处、绿妒轻裙。
恁时携素手，乱花飞絮里，缓步香。
朱颜空自改，向年年、芳意长新。
遍绿野，嬉游醉眠，莫负青春。','',''),('songci300-016','桂枝香','王安石','songci300','桂枝香','','登临送目。
正故国晚秋，天气初肃。
千里澄江似练，翠峰如簇。
归帆去棹残阳里，背西风、酒旗斜矗。
彩舟云淡，星河鹭起，画图难足。
念往昔、繁华竞逐。
叹门外楼头，悲恨相续。
千古凭高，对此漫嗟荣辱。
六朝旧事随流水，但寒烟、芳草凝绿。
至今商女，时时犹唱，后庭遗曲。','',''),('songci300-017','清平乐','王安石','songci300','清平乐','','留春不住。
费尽莺儿语。
满地残红宫锦污。
昨夜南园风雨。
小怜初上琵琶。
晓来思绕天涯。
不肯画堂朱户，春风自在杨花。','',''),('songci300-018','千秋岁引','王安石','songci300','千秋岁引','','别馆寒砧，孤城画角。
一派秋声入寥廓。
东归燕从海上去，南来雁向沙头落。
楚台风，庾楼月，宛如昨。
无奈被些名利缚。
无奈被他情担阁。
可惜风流总闲却。
当初漫留华表语，而今误我秦楼约。
梦阑时，酒醒后，思量着。','',''),('songci300-019','清平乐','王安国','songci300','清平乐','','留春不住。
费尽莺儿语。
满地残红宫锦污。
昨夜南园风雨。
小怜初上琵琶。
晓来思绕天涯。
不肯画堂朱户，春风自在梨花。','',''),('songci300-020','临江仙','晏几道','songci300','临江仙','','梦后楼台高锁，酒醒帘幕低垂。
去年春恨却来时。
落花人独立，微雨燕双飞。
记得小苹初见，两重心字罗衣。
琵琶弦上说相思。
当时明月在，曾照彩云归。','',''),('songci300-021','蝶恋花','晏几道','songci300','蝶恋花','','卷絮风头寒欲尽。
坠粉飘红，日日香成阵。
新酒又添残酒困。
今春不减前春恨。
蝶去莺飞无处问。
隔水高楼，望断双鱼信。
恼乱层波横一寸。
斜阳只与黄昏近。','',''),('songci300-022','蝶恋花','晏几道','songci300','蝶恋花','','醉别西楼醒不记。
春梦秋云，聚散真容易。
斜月半窗还少睡。
画屏闲展吴山翠。
衣上酒痕诗里字。
点点行行，总是凄凉意。
红烛自怜无好计。
夜寒空替人垂泪。','',''),('songci300-023','蝶恋花','晏几道','songci300','蝶恋花','','梦入江南烟水路。
行尽江南，不与离人遇。
睡里消魂无说处。
觉来惆怅消魂误。
欲尽此情书尺素。
浮雁沈鱼，终了无凭据。
却倚缓弦歌别绪。
断肠移破秦筝柱。','',''),('songci300-024','鹧鸪天','晏几道','songci300','鹧鸪天','','彩袖殷勤捧玉锺。
当年拼却醉颜红。
舞低杨柳楼心月，歌尽桃花扇影风。
从别后，忆相逢。
几回魂梦与君同。
今宵剩把银釭照，犹恐相逢是梦中。','',''),('songci300-025','生查子','晏几道','songci300','生查子','','关山魂梦长，鱼雁音尘少。
两鬓可怜青，只为相思老。
归梦碧纱窗，说与人人道。
真个别离难，不似相逢好。','',''),('songci300-026','清平乐','晏几道','songci300','清平乐','','留人不住。
醉解兰舟去。
一棹碧涛春水路。
过尽晓莺啼处。
渡头杨柳青青。
枝枝叶叶离情。
此后锦书休寄，画楼云雨无凭。','',''),('songci300-027','木兰花・玉楼春','晏几道','songci300','木兰花・玉楼春','','秋千院落重帘暮。
彩笔闲来题绣户。
墙头丹杏雨馀花，门外绿杨风后絮。
朝云信断知何处。
应作襄王春梦去。
紫骝认得旧游踪，嘶过画桥东畔路。','',''),('songci300-028','菩萨蛮','晏几道','songci300','菩萨蛮','','哀筝一弄湘江曲。
声声写尽湘波绿。
纤指十三弦。
细将幽恨传。
当筵秋水慢。
玉柱斜飞雁。
弹到断肠时。
春山眉黛低。','',''),('songci300-029','玉楼春','晏几道','songci300','玉楼春','','东风又作无情计。
艳粉娇红吹满地。
碧楼帘影不遮愁，还似去年今日意。
谁知错管春残事。
到处登临曾费泪。
此时金盏直须深，看尽落花能几醉。','',''),('songci300-030','阮郎归','晏几道','songci300','阮郎归','','旧香残粉似当初。
人情恨不如。
一春犹有数行书。
秋来书更疏。
衾凤冷，枕鸳孤。
愁肠待酒舒。
梦魂纵有也成虚。
那堪和梦无。','',''),('songci300-031','阮郎归','晏几道','songci300','阮郎归','','天边金掌露成霜。
云随雁字长。
绿杯红袖称重阳。
人情似故乡。
兰佩紫，菊簪黄。
殷勤理旧狂。
欲将沈醉换悲凉。
清歌莫断肠。','',''),('songci300-032','六么令','晏几道','songci300','六么令','','绿阴春尽，飞絮绕香阁。
晚来翠眉宫样，巧把远山学。
一寸狂心未说，已向横波觉。
画帘遮币。
新翻曲妙，暗许闲人带偷掏。
前度书多隐语，意浅愁难答。
昨夜诗有回纹，韵险还慵押。
都待笙歌散了，记取留时霎。
不消红蜡。
闲云归后，月在庭花旧阑角。','',''),('songci300-033','御街行','晏几道','songci300','御街行','','街南绿树春饶絮。
雪满游春路。
树头花艳杂娇云，树底人家朱户。
北楼闲上，疏帘高卷，直见街南树。
阑干倚尽犹慵去。
几度黄昏雨。
晚春盘马踏青苔，曾傍绿阴深驻。
落花犹在，香屏空掩，人面知何处。','',''),('songci300-034','虞美人','晏几道','songci300','虞美人','','曲阑干外天如水。
昨夜还曾倚。
初将明月比佳期。
长向月圆时候、望人归。
罗衣着破前香在。
旧意谁教改。
一春离恨懒调弦。
犹有两行闲泪、宝筝前。','',''),('songci300-035','留春令','晏几道','songci300','留春令','','画屏天畔，梦回依约，十洲云水。
手拈红笺寄人书，写无限、伤春事。
别浦高楼曾漫倚。
对江南千里。
楼下分流水声中，有当日、凭高泪。','',''),('songci300-036','思远人','晏几道','songci300','思远人','','红叶黄花秋意晚，千里念行客。
飞云过尽，归鸿无信，何处寄书得。
泪弹不尽临窗滴。
就砚旋研墨。
渐写到别来，此情深处，红笺为无色。','',''),('songci300-037','生查子','王观','songci300','生查子','','关山魂梦长，塞雁音书少。
两鬓可怜青，一夜相思老。
归傍碧纱窗，说与人人道。
真个别离难，不似相逢好。','',''),('songci300-038','水龙吟','苏轼','songci300','水龙吟','','似花还似非花，也无人惜从教坠。
抛家傍路，思量却是，无情有思。
萦损柔肠，困酣娇眼，欲开还闭。
梦随风万里，寻郎去处，又还被、莺呼起。
不恨此花飞尽，恨西园、落红难缀。
晓来雨过，遗踪何在，一池萍碎。
春色三分，二分尘土，一分流水。
细看来，不是杨花点点，是离人泪。','',''),('songci300-039','水调歌头','苏轼','songci300','水调歌头','','明月几时有，把酒问青天。
不知天上宫阙，今夕是何年。
我欲乘风归去，又恐琼楼玉宇，高处不胜寒。
起舞弄清影，何似在人间。
转朱阁，低绮户，照无眠。
不应有恨，何事长向别时圆。
人有悲欢离合，月有阴晴圆缺，此事古难全。
但愿人长久，千里共婵娟。','',''),('songci300-040','临江仙','苏轼','songci300','临江仙','','夜饮东坡醒复醉，归来仿佛三更。
家童鼻息已雷鸣。
敲门都不应，倚杖听江声。
长恨此身非我有，何时忘却营营。
夜阑风静縠纹平。
小舟从此逝，江海寄馀生。','',''),('songci300-041','定风波','苏轼','songci300','定风波','','莫听穿林打叶声。
何妨吟啸且徐行。
竹杖芒鞋轻胜马。
谁怕。
一蓑烟雨任平生。
料峭春风吹酒醒。
微冷。
山头斜照却相迎。
回首向来萧瑟处。
归去。
也无风雨也无晴。','',''),('songci300-042','卜算子','苏轼','songci300','卜算子','','缺月挂疏桐，漏断人初静。
时见幽人独往来，缥缈孤鸿影。
惊起却回头，有恨无人省。
拣尽寒枝不肯栖，枫落吴江冷。','',''),('songci300-043','贺新郎','苏轼','songci300','贺新郎','','乳燕飞华屋。
悄无人、桐阴转午，晚凉新浴。
手弄生绡白团扇，扇手一时似玉。
渐困倚、孤眠清熟。
帘外谁来推绣户，枉教人、梦断瑶台曲。
又却是，风敲竹。
石榴半吐红巾蹙。
待浮花、浪蕊都尽，伴君幽独。
艳一枝细看取，芳心千重似束。
又恐被、秋风惊绿。
若待得君来向此，花前对酒不忍触。
共粉泪，两蔌蔌。','',''),('songci300-044','洞仙歌','苏轼','songci300','洞仙歌','','冰肌玉骨，自清凉无汗。
水殿风来暗香满。
绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。
起来携素手，庭户无声，时见疏星渡河汉。
试问夜如何，夜已三更，金波淡、玉绳低转。
但屈指、西风几时来，又不道、流年暗中偷换。','',''),('songci300-045','江神子・江城子','苏轼','songci300','江神子・江城子','','十年生死两茫茫。
不思量。
自难忘。
千里孤坟，无处话凄凉。
纵使相逢应不识，尘满面，鬓如霜。
夜来幽梦忽还乡。
小轩窗。
正梳妆。
相顾无言，惟有泪千行。
料得年年断肠处，明月夜，短松冈。','',''),('songci300-046','永遇乐','苏轼','songci300','永遇乐','','明月如霜，好风如水，清景无限。
曲港跳鱼，圆荷泻露，寂寞无人见。
如三鼓，铿然一叶，黯黯梦云惊断。
夜茫茫，重寻无处，觉来小园行遍。
天涯倦客，山中归路，望断故园心眼。
燕子楼空，佳人何在，空锁楼中燕。
古今如梦，何曾梦觉，但有旧欢新怨。
异时对，黄楼夜景，为余浩叹。','',''),('songci300-047','青玉案','苏轼','songci300','青玉案','','三年枕上吴中路。
遣黄耳、随君去。
若到松江呼小渡。
莫惊鸥鹭，四桥尽是，老子经行处。
辋川图上看春暮。
常记高人右丞句。
作个归期天已许。
春衫犹是，小蛮针线，曾湿西湖雨。','',''),('songci300-048','谢池春','李之仪','songci300','谢池春','','残寒销尽，疏雨过、清明后。
花径敛馀红，风沼萦新皱。
乳燕穿庭户，飞絮沾襟袖。
正佳时，仍晚昼。
着人滋味，真个浓如酒。
频移带眼，空只恁、厌厌瘦。
不见又思量，见了还依旧。
为问频相见，何似长相守。
天不老，人未偶。
且将此恨，分付庭前柳。','',''),('songci300-049','卜算子','李之仪','songci300','卜算子','','我住长江头，君住长江尾。
日日思君不见君，共饮长江水。
此水几时休，此恨何时已。
只愿君心似我心，定不负相思意。','',''),('songci300-050','虞美人','舒亶','songci300','虞美人','','芙蓉落尽天涵水。
日暮沧波起。
背飞双燕帖云寒。
独向小楼东畔、倚阑看。
浮生只合尊前老。
雪满长安道。
故人早晚上高台。
赠我江南春色、一枝梅。','',''),('songci300-051','高阳台','韩','songci300','高阳台','','频听银签，重燃绛蜡，年华衮衮惊心。
饯旧迎新，能消几刻光阴。
老来可惯通宵饮，待不眠、还怕寒侵。
掩清尊。
多谢梅花，伴我微吟。
邻娃已试春妆了，更蜂腰簇翠，燕股横金。
勾引东风，也知芳思难禁。
朱颜那有年年好，逞艳游、赢取如今。
恣登临。
残雪楼台，迟日园林。','',''),('songci300-052','玉楼春','严仁','songci300','玉楼春','','春风只在园西畔。
荠菜花繁胡蝶乱。
冰池晴绿照还空，香径落红吹已断。
意长翻恨游丝短。
尽日相思罗带缓。
宝奁明月不欺人，明日归来君试看。','',''),('songci300-053','生查子','刘克庄','songci300','生查子','','繁灯夺霁华。
戏鼓侵明发。
物色旧时同，情味中年别。
浅画镜中眉，深拜楼西月。
人散市声收，渐入愁时节。','',''),('songci300-054','高阳台','张炎','songci300','高阳台','','接叶巢莺，平波卷絮，断桥斜日归船。
能几番游，看花又是明年。
东风且伴蔷薇住，到蔷薇、春已堪怜。
更凄然。
万绿西泠，一抹荒烟。
当年燕子知何处，但苔深韦曲，草暗斜川。
见说新愁，如今也到鸥边。
无心再续笙歌梦，掩重门、浅醉闲眠。
莫开帘。
怕见飞花，怕听啼鹃。','',''),('songci300-055','贺新郎','刘克庄','songci300','贺新郎','','深院榴花吐。
画帘开、衣纨扇，午风清暑。
儿女纷纷夸结束，新样钗符艾虎。
早已有、游人观渡。
老大逢场慵作戏，任陌头、年少争旗鼓。
溪雨急，浪花舞。
灵均标致高如许。
忆生平、既纫兰佩，更怀椒糈。
谁信骚魂千载后，波底垂涎角黍。
又说是、蛟馋龙怒。
把似而今醒到了，料当年、醉死差无苦。
聊一笑，吊千古。','',''),('songci300-056','贺新郎','刘克庄','songci300','贺新郎','','湛湛长空黑。
更那堪、斜风细雨，乱愁如织。
老眼平生空四海，赖有高楼百尺。
看浩荡、千崖秋色。
白发书生神州泪，尽凄凉、不向牛山滴。
追往事，去无迹。
少年自负凌云笔。
到而今、春华落尽，满怀萧瑟。
常恨世人新意少，爱说南朝狂客。
把破帽、年年拈出。
若对黄花孤负酒，怕黄花、也笑人岑寂。
鸿北去，日西匿。','',''),('songci300-057','玉楼春','刘克庄','songci300','玉楼春','','年年跃马长安市。
客舍似家家似寄。
青钱换酒日无何，红烛呼庐宵不寐。
易挑锦妇机中字。
难得玉人心下事。
男儿西北有神州，莫滴水西桥畔泪。','',''),('songci300-058','好事近','韩元吉','songci300','好事近','','凝碧旧池头，一听管弦凄切。
多少梨园声在，总不堪华发。
杏花无处避春愁，也傍野烟发。
惟有御沟声断，似知人呜咽。','',''),('songci300-059','六州歌头','韩元吉','songci300','六州歌头','','东风着意。
先上小桃枝。
红粉腻。
娇如醉。
倚朱扉。
记年时。
隐映新妆，面临水岸。
春将半。
云日暖。
斜桥转。
夹城西。
草软莎平跋马，垂杨渡、玉勒争嘶。
认蛾眉凝笑，脸薄拂燕支。
绣户曾窥。
恨依依。
共携手处。
香如雾。
红随步。
怨春迟。
消瘦损。
凭谁问。
只花知。
泪空垂。
旧日堂前燕，和烟雨，又双飞。
人自老。
春长好。
梦佳期。
前度刘郎，几许风流地，花也应悲。
但茫茫暮霭，目断武陵溪。
往事难追。','',''),('songci300-060','烛影摇红','张抡','songci300','烛影摇红','','双阙中天，凤楼十二春寒浅。
去年元夜奉宸游，曾侍瑶池宴。
玉殿珠帘尽卷。
拥群仙、蓬壶阆苑。
五云深处，万烛光中，揭天丝管。
驰隙流年，恍如一瞬星霜换。
今宵谁念泣孤臣，回首长安远。
可是尘缘未断。
谩惆怅、华胥梦短。
满怀幽恨，数点寒灯，几声归雁。','',''),('songci300-061','永遇乐','辛弃疾','songci300','永遇乐','','千古江山，英雄无觅，孙仲谋处。
舞榭歌台，风流总被，雨打风吹去。
斜阳草树，寻常巷陌，人道寄奴曾住。
想当年，金戈铁马，气吞万里如虎。
元嘉草草，封狼居胥，赢得仓皇北顾。
四十三年，望中犹记，烽火扬州路。
可堪回首，佛狸祠下，一片神鸦社鼓。
凭谁问，廉颇老矣，尚能饭否。','',''),('songci300-062','绿意・疏影','张炎','songci300','绿意・疏影','','碧圆自洁。
向浅洲远渚，亭亭清绝。
犹有遗簪，不展秋心，能卷几多炎热。
鸳鸯密语同倾盖，且莫与、浣纱人说。
恐怨歌、忽断花风，碎却翠云千叠。
回首当年汉舞，怕飞去、谩皱留仙裙摺。
恋恋青衫，犹染枯香，还叹鬓丝飘雪。
盘心清露如铅水，又一夜、西风吹折。
喜静看、匹练秋光，倒泻半湖明月。','',''),('songci300-063','绿头鸭・多丽','晁端礼','songci300','绿头鸭・多丽','','晚云收，淡天一片琉璃。
烂银盘、来从海底，皓色千里澄辉。
莹无尘、素娥淡伫，静可数、丹桂参差。
玉露初零，金风未凛，一年无似此佳时。
露坐久，疏莹时度，乌鹊正南飞。
瑶台冷，栏干凭暖，玉下迟迟。
念佳人，音尘别后，对此应解相思。
最关情、漏声正永，暗断肠、花影偷移。
料得来宵，清光未减，阴晴天气又争知。
共凝恋、如今别后，还是隔年期。
人强健，清尊素影，长愿相随。','',''),('songci300-064','洞仙歌','李元膺','songci300','洞仙歌','','雪云散尽，放晓晴池院。
杨柳于人便青眼。
更风流多处，一点梅心、相映远。
约略轻笑浅。
一年春好处，不在浓芳，小艳疏香最娇软。
到清明时候，百紫千红花正乱。
已失春风一半。
蚤占取韶光，共追游，但莫管春寒，醉红自暖。','',''),('songci300-065','渔家傲','朱服','songci300','渔家傲','','小雨廉纤风细细。
万家杨柳轻烟里。
恋树湿花飞不起。
愁无比。
和春付与西流水。
九十光阴能有几。
金龟解尽留无计。
寄语东城沽酒市。
拼一醉。
而今乐事他年泪。','',''),('songci300-066','青门饮','时彦','songci300','青门饮','','胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。
古木连空，乱山无数，行尽暮沙衰草。
星斗横幽馆，夜无眠、灯花空老。
雾浓香鸭，冰凝泪烛，霜天难晓。
长记晓妆才了，一杯未尽，离怀多少。
醉里秋波，梦中朝雨，都是醒时烦恼。
料有牵情处，忍思量、耳边曾道。
甚时跃马归来，认得迎门轻笑。','',''),('songci300-067','望海潮','秦观','songci300','望海潮','','梅英疏淡，冰澌溶泄，东风暗换年华。
金谷俊游，铜驼巷陌，新晴细履平沙。
长记误随车。
正絮翻蝶舞，芳思交加。
柳下桃蹊，乱分春色到人家。
西园夜饮鸣笳。
有华灯碍月，飞盖妨花。
兰苑未空，行人渐老，重来是事堪嗟。
烟暝酒旗斜。
但倚楼极目，时见栖鸦。
无奈归心。
暗随流水到天涯。','',''),('songci300-068','满庭芳','秦观','songci300','满庭芳','','山抹微云，天连衰草，画角声断谯门。
暂停征棹，聊共引离尊。
多少蓬莱旧事，空回首、烟霭纷纷。
斜阳外，寒鸦万点，流水绕孤村。
销魂。
当此际，香囊暗解，罗带轻分。
谩赢得、青楼薄名存。
此去何时见也，襟袖上、空惹啼痕。
伤情处，高城望断，灯火已黄昏。','',''),('songci300-069','浣溪沙','秦观','songci300','浣溪沙','','漠漠轻寒上小楼。
晓阴无赖似穷秋。
淡烟流水画屏幽。
自在飞花轻似梦，无边丝雨细如愁。
宝帘闲挂小银钩。','',''),('songci300-070','阮郎归','秦观','songci300','阮郎归','','湘天风雨破寒初。
深沈庭院虚。
丽谯吹罢《小单于》。
迢迢清夜徂。
乡梦断，旅魂孤。
峥嵘岁又除。
衡阳犹有雁传书。
郴阳和雁无。','',''),('songci300-071','满庭芳','秦观','songci300','满庭芳','','晓色云开，春随人意，骤雨才过还晴。
古台芳榭，飞燕蹴红英。
舞困榆钱自落，秋千外、绿水桥平。
东风里，朱门映柳，低底按小秦筝。
多情。
行乐处，珠钿翠盖，玉辔红缨。
渐酒空金，花困蓬瀛。
豆蔻梢头旧恨，十年梦，屈指堪惊。
凭阑久，疏烟淡日，寂寞下芜城。','',''),('songci300-072','帝台春','李甲','songci300','帝台春','','芳草碧色，萋萋遍南陌。
暖絮乱红，也知人、春愁无力。
忆得盈盈拾翠侣，共携赏、凤城寒食。
到今来，海角逢春，天涯为客。
愁旋释。
还似织。
泪暗拭。
又偷滴。
谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。
拼则而已今拼了，忘则怎生便忘得。
又还问鳞鸿，试重寻消息。','',''),('songci300-073','蝶恋花','赵令','songci300','蝶恋花','','欲减罗衣寒未去。
不卷珠帘，人在深深处。
红杏枝头花几许。
啼痕止恨清明雨。
尽日沈烟香一缕。
宿酒醒迟，恼破春情绪。
飞燕又将归信误。
小屏风上西江路。','',''),('songci300-074','醉中真・浣溪沙','贺铸','songci300','醉中真・浣溪沙','','不信芳春厌老人。
老人几度送春归。
惜春行乐莫辞频。
巧笑艳歌皆我意，恼花颠酒拼君嗔。
物情惟有醉中真。','',''),('songci300-075','人南渡・感皇恩','贺铸','songci300','人南渡・感皇恩','','兰芷满芳洲，游思横路。
罗袜尘生步。
迎顾。
整鬟颦黛，脉脉两情难语。
细风吹柳絮。
人南渡。
回首旧游，山无重数。
花底深朱户。
何处。
半黄梅子，向晚一帘疏雨。
断魂分付与。
春将去。','',''),('songci300-076','薄幸','贺铸','songci300','薄幸','','艳真多态。
更的的，频回眄睐。
便认得、琴心相许，与写宜男双带。
记画堂、斜月朦胧，轻颦微笑娇无奈。
便翡翠屏开，芙蓉帐掩，与把香罗偷解。
自过了收灯后，都不见、踏青挑菜。
几回凭双燕，丁宁深意，往来翻恨重帘碍。
约何时再。
正春浓酒暖，人闲昼永无聊赖。
厌厌睡起，犹有花梢日在。','',''),('songci300-077','伴云来・天香','贺铸','songci300','伴云来・天香','','烟络横林，山沈远照，逦迤黄昏钟鼓。
烛映帘栊，蛩催机杼，共苦清秋风露。
不眠思妇，齐应和、几声砧杵。
惊动天涯倦宦，岁华行暮。
当年酒狂自负。
谓东君、已春相付。
流浪征骖北道，客墙南浦。
幽恨无人晤语。
赖明月曾知旧游处。
好伴云来，还将梦去。','',''),('songci300-078','青玉案','无名氏','songci300','青玉案','','一年春事都来几。
早过了、三之二。
绿暗红嫣浑可事。
绿杨庭院，暖风帘幕，有个人憔悴。
买花载酒长安市。
又争似家山见桃李。
不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。','',''),('songci300-079','高阳台','吴文英','songci300','高阳台','','修竹凝妆，垂杨驻马，凭阑浅画成图。
山色谁题，楼前有雁斜书。
东风紧送斜阳下，弄旧寒、晚酒醒馀。
自销凝，能几花前，顿老相如。
伤春不在高楼上，在灯前攲枕，雨外熏炉。
怕舣游船，临流可奈清臞。
飞红若到西湖底，搅翠澜、总是愁鱼。
莫重来，吹尽香绵，泪满平芜。','',''),('songci300-080','高阳台','吴文英','songci300','高阳台','','宫粉雕痕，仙云堕影，无人野水荒湾。
古石埋香，金沙锁骨连环。
南楼不恨吹横笛，恨晓风、千里关山。
半飘零，庭上黄昏，月冷阑干。
寿阳空理愁鸾。
问谁调玉髓，暗补香瘢。
细雨归鸿，孤山无限春寒。
离魂难倩招清些，梦缟衣、解佩溪边。
最愁人，啼鸟晴明，叶底青圆。','',''),('songci300-081','三姝媚','吴文英','songci300','三姝媚','','湖山经醉惯。
溃春衫、啼痕酒痕无限。
又客长安，叹断襟零袂，尘谁浣。
紫曲门荒，沿败井、风摇青蔓。
对语东邻，犹是曾巢，谢堂双燕。
春梦人间须断。
但怪得、当年梦缘能短。
绣屋秦筝，傍海棠偏爱，夜深开宴。
舞歇歌沈，花未减、红颜先变。
伫久河桥欲去，斜阳泪满。','',''),('songci300-082','八声甘州','吴文英','songci300','八声甘州','','渺空烟四远，是何年、青天坠长星。
幻苍崖云树，名娃金屋，残霸宫城。
箭径酸风射眼，腻水染花腥。
时靸双鸳响，廊叶秋声。
宫里吴王沈醉，倩五湖倦客，独钓醒醒。
问苍波无语，华发奈山青。
水涵空、阑干高处，送乱鸦、斜日落渔汀。
连呼酒，上琴台去，秋与云平。','',''),('songci300-083','夜合花','吴文英','songci300','夜合花','','柳暝河桥，莺晴台苑，短策频惹春香。
当时夜泊，温柔便入深乡。
词韵窄，酒杯长。
翦蜡花、壶箭催忙。
共追游处，凌波翠陌，连棹横塘。
十年一梦凄凉。
似西湖燕去，吴馆巢荒。
重来万感，依前唤酒银罂。
溪雨急，岸花狂。
趁残鸦、飞过苍茫。
故人楼上，凭谁指与，芳草斜阳。','',''),('songci300-084','蹋莎行・踏莎行','吴文英','songci300','蹋莎行・踏莎行','','润玉笼绡，檀樱倚扇。
绣圈犹带脂香浅。
榴心空叠舞裙红，艾枝应压愁鬟乱。
午梦千山，窗阴一箭。
香瘢新褪红丝腕。
隔江人在雨声中，晚风菰叶生秋怨。','',''),('songci300-085','夜游宫','吴文英','songci300','夜游宫','','人去西楼雁杳。
叙别梦、扬州一觉。
云澹星疏楚山晓。
听啼乌，立河桥，话未了。
雨外蛩声早。
细织就、霜丝多少。
说与萧娘未知道。
向长安，对秋灯，几人老。','',''),('songci300-086','鹧鸪天','吴文英','songci300','鹧鸪天','','池上红衣伴倚阑。
栖鸦常带夕阳还。
殷云度雨疏桐落，明月生凉宝扇闲。
乡梦窄，水天宽。
小窗愁黛澹秋山。
吴鸿好为传归信，杨柳阊门屋数间。','',''),('songci300-087','唐多令','吴文英','songci300','唐多令','','何处合成愁。
离人心上秋。
纵芭蕉、不雨也飕飕。
都道晚凉天气好，有明月、怕登楼。
年事梦中休。
花空烟水流。
燕辞归、客尚淹留。
垂柳不萦裙带住，漫长是、系行舟。','',''),('songci300-088','金缕歌・贺新郎','吴文英','songci300','金缕歌・贺新郎','','乔木生云气。
访中兴、英雄陈迹，暗追前事。
战舰东风悭借便，梦断神州故里。
旋小筑、吴宫闲地。
华表月明归夜鹤，叹当时、花竹今如此。
枝上露，溅清泪。
遨头小簇行春队。
步苍苔、寻幽别坞，问梅开未。
重唱梅边吸度曲，催发寒梢冻蕊。
此心与、东君同意。
后不如今非昔，两无言、相对沧浪水。
怀此恨，寄残醉。','',''),('songci300-089','大有','潘希白','songci300','大有','','戏马台前，采花篱下，问岁华、还是重九。
恰归来、南山翠色依旧。
帘栊昨夜听风雨，都不似、登归时候。
一片宋玉情怀，十分卫郎清瘦。
红萸佩、空对酒。
砧杆动微寒，暗欺罗袖。
秋已无多，早是败荷衰柳。
强整帽檐侧，曾经向、天涯搔首。
几回忆、故国莼鲈，霜前雁后。','',''),('songci300-090','兰陵王','刘辰翁','songci300','兰陵王','','送春去。
春去人间无路。
秋千外、芳草连天，谁遣风沙暗南浦。
依依甚意绪。
漫忆海门飞絮。
乱鸦过，斗转城荒，不见来时试灯处。
春去。
最谁苦。
但箭雁沉边，梁燕无主。
杜鹃声里长门暮。
想玉树凋土，泪盘如露。
咸阳送客屡回顾。
斜日未能度。
春去。
尚来否。
正江令恨别，庾信愁赋。
苏堤尽日风和雨。
叹神游故国，花记前度。
人生流落，顾孺子，共夜雨。','',''),('songci300-091','宝鼎现','刘辰翁','songci300','宝鼎现','','红妆春骑。
踏月影、竿旗穿市。
望不尽、楼台歌舞，习习香尘莲步底。
箫声断、约彩鸾归去，未怕金吾呵醉。
甚辇路、喧阗且止。
听得念奴歌起。
父老犹记宣和事。
抱铜仙、清泪如水。
还转盼、沙河多丽。
漾明光连邸第。
帘影冻、散红光成绮。
月浸葡萄十里。
看往来、神仙才子。
肯把菱花扑碎。
肠断竹马儿童，空见说、三千乐指。
等多时春不归来，到春时欲睡。
又说向、灯前拥髻。
暗滴鲛珠坠。
便当日、亲见霓裳，天上人间梦里。','',''),('songci300-092','永遇乐','刘辰翁','songci300','永遇乐','','璧月初晴，黛云远澹，春事谁主。
禁苑娇寒，湖堤倦暖，前度遽如许。
香尘暗陌，华灯明昼，长是懒携手去。
谁知道，断烟禁夜，满城似愁风雨。
宣和旧日，临安南渡，芳景犹自如故。
缃帙流离，风鬟三五，能赋词最苦。
江南无路，州今夜，此苦又谁知否。
空相对，残无寐，满村社鼓。','',''),('songci300-093','摸鱼儿','刘辰翁','songci300','摸鱼儿','','怎知他、春归何处，相逢且尽尊酒。
少年袅袅天涯恨，长结西湖烟柳。
休回首。
但细雨断桥，憔悴人归后。
东风似旧。
问前度桃花，刘郎能记，花复认郎否。
君且住，草草留君翦韭。
前宵更恁时候。
深杯欲共歌声滑，翻湿春衫半袖。
空眉皱。
看白发尊前，已似人人有。
临分把手。
叹一笑论文，清狂顾曲，此会几时又。','',''),('songci300-094','绣鸾凤花犯・花犯','周密','songci300','绣鸾凤花犯・花犯','','楚江湄，湘娥乍见，无言洒清泪。
淡然春意。
空独倚东风，芳思谁寄。
凌波路冷秋无际。
香云随步起。
谩记得，汉宫仙掌，亭亭明月底。
冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。
春思远，谁叹赏、国香风味。
相将共、岁寒伴侣。
小窗净、沈烟熏翠袂。
幽梦觉，涓涓清露，一枝灯影里。','',''),('songci300-095','瑶花慢','周密','songci300','瑶花慢','','朱钿宝。
天上飞琼，比人间春别。
江南江北，曾未见，谩拟梨云梅雪。
淮山春晚，问谁识、芳心高洁。
消几番、花落花开，老了玉关豪杰。
金壶翦送琼枝，看一骑红尘，香度瑶阙。
韶华正好，应自喜、初识长安蜂蝶。
杜郎老矣，想旧事、花须能说。
记少年，一梦扬州，二十四桥明月。','',''),('songci300-096','玉京秋','周密','songci300','玉京秋','','烟水阔。
高林弄残照，晚蜩凄切。
碧砧度韵，银床飘叶。
衣湿桐阴露冷，采凉花、时赋秋雪。
叹轻别。
一襟幽事，砌蛩能说。
客思吟商还怯。
怨歌长、琼壶暗缺。
翠扇恩疏，红衣香褪，翻成消歇。
玉骨西风，恨最恨、闲却新凉时节。
楚箫咽。
谁倚西楼淡月。','',''),('songci300-097','曲游春','周密','songci300','曲游春','','楚苑东风外，暖丝情絮，春思如织。
燕约莺期，恼芳情偏在，翠深红隙。
漠漠香尘隔。
沸十里、乱弦丛笛。
看画船，尽入西泠，闲却半湖春色。
柳陌。
新烟凝碧。
映帘底宫眉，堤上游勒。
轻暝笼寒，怕梨云梦冷，杏香愁幂。
歌管酬寒食。
奈蝶怨、良宵岑寂。
正满湖、碎月摇花，怎生去得。','',''),('songci300-098','高阳台','周密','songci300','高阳台','','照野旌旗，朝天车马，平沙万里天低。
宝带金章，尊前茸帽风。
秦关汴水经行地，想登临、都付新诗。
纵英游，叠鼓清笳，骏马名姬。
酒酣应对燕山雪，正冰河月冻，晓陇云飞。
投老残年，江南谁念方回。
东风渐绿西湖柳，雁已还、人未南归。
最关情，折尽梅花，难寄相思。','',''),('songci300-099','摸鱼儿','朱嗣发','songci300','摸鱼儿','','对西风、鬓摇烟碧，参差前事流水。
紫丝罗带鸳鸯结，的的镜盟钗誓。
浑不记、漫手织回文，几度欲心碎。
安花着蒂。
奈雨覆云翻，情宽分窄，石上玉簪脆。
朱楼外。
愁压空云欲坠。
月痕犹照无寐。
阴晴也只随天意。
枉了玉消香碎。
君且醉。
君不见、长门青草春风泪。
一时左计。
悔不早荆钗，暮天修竹，头白倚寒翠。','',''),('songci300-100','解佩环・疏影','彭元逊','songci300','解佩环・疏影','','江空不渡，恨蘼芜杜若，零落无数。
远道荒寒，婉娩流年，望望美人迟暮。
风烟雨雪阴晴晚，更何须，春风千树。
尽孤城、落木萧萧，日夜江声流去。
日晏山深闻笛，恐他年流落，与子同赋。
事阔心违，交淡媒劳，蔓草沾衣多露。
汀洲窈窕馀醒寐，遗浮沈沣浦。
有白鸥淡月，微波寄语，逍遥容与。','',''),('songci300-101','六丑','彭元逊','songci300','六丑','','似东风老大，那复有、当时风气。
有情不收，江山身是寄。
浩荡何世。
但忆临官道，暂来不住，便出门千里。
痴心指望回风坠。
扇底相逢，钗头微缀。
他家万条千缕，解遮亭障驿，不隔江水。
瓜洲曾舣，等行人岁岁。
日下长秋，城乌夜起。
帐庐好在春睡。
共飞归湖上，草青无地。
雨、春心如腻。
欲待化、丰乐楼前，青门都废。
何人念、流落无几。
点点抟作，雪绵松润，为君泪。','',''),('songci300-102','瑞鹤仙','陆淞','songci300','瑞鹤仙','','脸霞红印枕。
睡觉来、冠儿还是不整。
屏间麝煤冷。
但眉峰压翠，泪珠弹粉。
堂深昼永。
燕交飞、风帘露井。
恨无人，与说相思，近日带围宽尽。
重省。
残灯朱幌，淡月纱窗，那时风景。
阳台路迥。
云雨梦，便无准。
待归来，先指花梢教看，却把心期细问。
问因循、过了青春，怎生意稳。','',''),('songci300-103','减字浣溪沙・浣溪沙','贺铸','songci300','减字浣溪沙・浣溪沙','','楼角初销一缕霞。
淡黄杨柳暗栖鸦。
玉人和月摘梅花。
笑拈粉香归洞户，更垂帘幕护窗纱。
东风寒似夜来些。','',''),('songci300-104','天门谣','贺铸','songci300','天门谣','','牛渚天门险。
限南北、七雄豪占。
清雾敛。
与闲人登览。
待月上潮平波滟滟。
塞管轻吹新《阿滥》。
风满槛。
历历数、西州更点。','',''),('songci300-105','石州引・石州慢','贺铸','songci300','石州引・石州慢','','薄雨初寒，斜照弄晴，春意空阔。
长亭柳色缠黄，远客一枝先折。
烟横水际，映带几点归鸦，东风销尽龙沙雪。
还记初关来，恰而今时节。
将发。
画楼芳酒，红泪清歌，顿成清别。
已是经年，杳杳音尘多绝。
欲知方寸，共有几许清愁，芭蕉不展丁香结。
枉望断天涯，两厌厌风月。','',''),('songci300-106','望湘人','贺铸','songci300','望湘人','','厌莺声到枕，花气动帘，醉魂愁梦相半。
被惜馀薰，带惊剩眼。
几许伤春春晚。
泪竹痕鲜，佩兰香老，湘天浓暖。
记小江、风月佳时，屡约非烟游伴。
须信鸾弦易断。
奈云和再鼓，曲终人远。
认罗袜无踪，旧处弄波清浅。
青翰棹舣，白苹洲畔。
尽木临皋飞观。
不解寄、一字相思，幸有归来双燕。','',''),('songci300-107','蝶恋花','贺铸','songci300','蝶恋花','','几许伤春春复暮。
杨柳清阴，偏碍游丝度。
天际小山桃叶步。
白苹花满湔裙处。
竟日微吟长短句。
帘影灯昏，心寄胡琴语。
数点雨声风约住。
朦胧淡月云来去。','',''),('songci300-108','夏云峰','仲殊','songci300','夏云峰','','天阔云高，溪横水远。
晚日寒生轻晕。
闲阶静、杨花渐少，朱门掩、莺声犹嫩。
悔匆匆、过却清明，旋占得馀芳，已成幽恨。
都几日阴沈，连宵慵困。
起来韶华都尽。
怨入双眉闲斗损。
乍品得情怀，看承全近。
深深态、无非自许。
厌厌意、终羞人间。
争知道、梦里蓬莱，待忘了馀香，时传音信。
纵留得莺花，东风不住，也则眼前愁闷。','',''),('songci300-109','汉宫春','李邴','songci300','汉宫春','','潇洒江梅，向竹梢疏处，横两三枝。
东君也不爱惜，雪压霜欺。
无情燕子，怕春寒、轻失花期。
却是有，年年塞雁，归来曾见开时。
清浅小溪如练，问玉堂何似，茅舍疏篱。
伤心故人去后，冷落新诗。
微云淡月，对江天、分付他谁。
空自忆，清香未减，风流不在人知。','',''),('songci300-110','贺新郎','潘汾','songci300','贺新郎','','篆缕销香鼎。
翠沈沈、庭阴转午，画堂人静。
芳草王孙知何处，惟有杨花糁径。
正玉枕、瞢腾初醒。
门外残红春已去，镇无聊、酒厌厌病。
云髻，未整。
江南旧事休重省。
但天涯、寻消问息，断鸿难倩。
月满西楼凭阑久，依旧归期未定。
便只恐、瓶沈金井。
嘶骑不来银烛暗，枉教人、立尽梧桐影。
谁伴我，对鸾镜。','',''),('songci300-111','忆王孙','李重元','songci300','忆王孙','','萋萋芳草忆王孙。
柳外楼高空断魂。
杜宇声声不忍闻。
欲黄昏。
雨打梨花深闭门。','',''),('songci300-112','贺新郎','李玉','songci300','贺新郎','','篆缕销金鼎。
醉沈沈、庭阴转午，画堂人静。
芳草王孙知何处，惟有杨花糁径。
渐玉枕、腾腾春醒。
帘外残红春已透，镇无聊、酒厌厌病。
云鬓乱，未整。
江南旧事休重省。
遍天涯、寻消问息，断鸿难倩。
月满西楼凭栏久，依旧归期未定。
又只恐、瓶沈金井。
嘶骑不来银烛暗，枉教人、立尽梧桐影。
谁伴我，对鸾镜。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('songci300-113','临江仙','陈与义','songci300','临江仙','','高咏楚词酬午日，天涯节序匆匆。
榴花不似舞裙红。
无人知此意，歌罢满帘风。
万事一身伤老矣，戌葵凝笑墙东。
酒杯深浅去年同。
试浇桥下水，今夕到湘中。','',''),('songci300-114','临江仙','陈与义','songci300','临江仙','','忆昔午桥桥上饮，坐中多是豪英。
长沟流月去无声。
杏花疏影里，吹笛到天明。
二十馀年如一梦，此身虽在堪惊。
闲登小阁看新晴。
古今多少事，渔唱起三更。','',''),('songci300-115','兰陵王','张元干','songci300','兰陵王','','卷朱箔。
朝雨轻阴乍阁。
阑干外，烟柳弄晴，芳草侵阶映红药。
东风妒花恶。
吹落。
梢头嫩萼。
屏山掩，沈水倦熏，中酒心情怕杯勺。
寻思旧京洛。
正年少疏狂，歌笑迷着。
障泥油壁催梳掠。
曾驰道同载，上林携手，灯夜初过早共约。
又争信漂泊。
寂寞。
念行乐。
甚粉淡衣襟，音断弦索。
琼枝璧月春如昨。
怅别后华表，那回双鹤。
相思除是，向醉里、暂忘却。','',''),('songci300-116','石州慢','张元干','songci300','石州慢','','寒水依痕，春意渐回，沙际烟阔。
溪梅晴照生香，冷芯数枝争发。
天涯旧恨，试看几许消魂，长亭门外山重叠。
不尽眼中青，是愁来时节。
情切。
画楼深闭，想见东风，暗销肌雪。
辜负枕前云雨，尊前花月。
心期切处，更有多少凄凉，殷勤留与归时说。
到得却相逢，恰经年离别。','',''),('songci300-117','薄幸','吕渭老','songci300','薄幸','','青楼春晚。
昼寂寂、梳匀又懒。
乍听得、鸦啼莺弄，惹起新愁无限。
记年时、偷掷春心，花间隔雾遥相见。
便角枕题诗，宝钗贳酒，共醉青苔深院。
怎忘得、回廊下，携手处、花明月满。
如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。
却谁拘管。
尽无言、闲品秦筝，泪满参差雁。
腰支渐小，心与杨花共远。','',''),('songci300-118','满江红','岳飞','songci300','满江红','','怒发冲冠，凭阑处、潇潇雨歇。
抬望眼、仰天长啸，壮怀激烈。
三十功名尘与土，八千里路云和月。
莫等闲、白了少年头，空悲切。
靖康耻，犹未雪。
臣子恨，何时灭。
驾长车踏破，贺兰山缺。
壮志饥餐胡虏肉，笑谈渴饮匈奴血。
待从头、收拾旧山河，朝天阙。','',''),('songci300-119','水龙吟','陈亮','songci300','水龙吟','','闹花深处层楼，画帘半卷东风软。
春归翠陌，平莎茸嫩，垂杨金浅。
迟日催花，淡云阁雨，轻寒轻暖。
恨芳菲世界，游人未赏，都付与、莺和燕。
寂寞凭高念远。
向南楼、一声归雁。
金钗斗草，青丝勒马，风流云散。
罗绶分香，翠绡封泪，几多幽怨。
正销魂，又是疏烟淡月，子规声断。','',''),('songci300-120','宴山亭・燕山亭','张','songci300','宴山亭・燕山亭','','幽梦初回，重阴未开，晓色吹成疏雨。
竹槛气寒，蕙畹声摇，新绿暗通南浦。
未有人行，才半启、回廊朱户。
无绪。
空望极霓旌，锦书难据。
苔径追忆曾游，念谁伴、秋千采绳芳柱。
犀奁黛卷，凤枕云孤，应也几番凝伫。
怎得伊来，花雾绕、小堂深处。
留住。
直到老、不教归去。','',''),('songci300-121','唐多令','刘过','songci300','唐多令','','芦叶满汀洲。
塞沙带浅流。
二十年、重过南楼。
柳下系舟犹未稳，能几日、又中秋。
黄鹤断矶头。
故人今不在。
旧江山，浑是新愁。
欲买桂花同载酒，终不似、少年游。','',''),('songci300-122','点绛唇','姜夔','songci300','点绛唇','','燕雁无心，太湖西畔随云去。
数峰清苦。
商略黄昏雨。
第四桥边，拟共天随住。
今何许。
凭栏怀古。
残柳参差舞。','',''),('songci300-123','鹧鸪天','姜夔','songci300','鹧鸪天','','肥水东流无尽期。
当初不合种相思。
梦中未比丹青见，暗里忽惊山鸟啼。
春未绿，鬓先丝。
人间别久不成悲。
谁教岁岁红莲夜，两处沈吟各自知。','',''),('songci300-124','杏花天','姜夔','songci300','杏花天','','绿丝低拂鸳鸯浦。
想桃叶、当时唤渡。
又将愁眼与春风，待去。
倚兰桡、更少驻。
金陵路。
莺吟燕舞。
算潮水、知人最苦。
满汀芳草不成归，日暮。
更移舟、向甚处。','',''),('songci300-125','踏莎行','姜夔','songci300','踏莎行','','燕燕轻盈，莺莺娇软。
分明又向华胥见。
夜长争得薄情知，春初早被相思染。
别后书辞，别时针线。
离魂暗逐郎行远。
淮南皓月冷千山，冥冥归去无人管。','',''),('songci300-126','霓裳中序第一','姜夔','songci300','霓裳中序第一','','亭皋正望极。
乱落江莲归未得。
多病却无气力。
况纨扇渐疏，罗衣初萦。
流光过隙。
叹杏梁、双燕如客。
人何在，一帘淡月，仿佛照颜色。
幽寂。
乱蛩吟壁。
动庾信、清愁似织。
沈思年少浪迹。
笛里关山，柳下坊陌。
坠红无信息。
漫暗水，涓涓溜碧。
漂零久，而今何意，醉卧酒垆侧。','',''),('songci300-127','庆宫春・高阳台','姜夔','songci300','庆宫春・高阳台','','双桨莼波，一蓑松雨，暮愁渐满空阔。
呼我盟鸥，翩翩欲下，背人还过木末。
那回归去，荡云雪、孤舟夜发。
伤心重见，依约眉山，黛痕低压。
采香径里春寒，老子婆娑，自歌谁答。
垂虹西望，飘然引去，此兴平生难遏。
酒醒波远，政凝想、明素袜。
如今安在，唯有阑干，伴人一霎。','',''),('songci300-128','齐天乐','姜夔','songci300','齐天乐','','庾郎先自吟愁赋。
凄凄更闻私语。
露湿铜铺，苔侵石井，都是曾听伊处。
哀音似诉。
正思妇无眠，起寻机杼。
曲曲屏山，夜凉独自甚情绪。
西窗又吹暗雨。
为谁频断续，相和砧杵。
候馆迎秋，离宫吊月，别有伤心无数。
豳诗漫与。
笑篱落呼灯，世间儿女。
写入琴丝，一声声更苦。','',''),('songci300-129','一萼红','姜夔','songci300','一萼红','','古城阴。
有官梅几许，红萼未宜簪。
池面冰胶，墙腰雪老，云意还又沈沈。
翠藤共、闲穿径竹，渐笑语、惊起卧沙禽。
野老林泉，故王台榭，呼唤登临。
南去北来何事，荡湘云楚水，目极伤心。
朱户黏鸡，金盘簇燕，空叹时序侵寻。
记曾共，西楼雅集，想垂杨、还袅万丝金。
待得归鞍到时，只怕春深。','',''),('songci300-130','念奴娇','姜夔','songci300','念奴娇','','闹红一舸，记来时、尝与鸳鸯为侣。
三十六陂人未到，水佩风裳无数。
翠叶吹凉，玉容销酒，更洒菰蒲雨。
嫣然摇动，冷香飞上诗句。
日暮。
青盖亭亭，情人不见，争忍凌波去。
只恐舞衣寒易落，愁入西风南浦。
高柳垂阴，老鱼吹浪，留我花间住。
田田多少，几回沙际归路。','',''),('songci300-131','琵琶仙・自度曲','姜夔','songci300','琵琶仙・自度曲','','双桨来时，有人似、旧曲桃根桃叶。
歌扇轻约飞花，蛾眉正奇绝。
春渐远、汀洲自绿，更添了、几声啼。
十里扬州，三生杜牧，前事休说。
又还是、宫烛分烟，奈愁里、匆匆换时节。
都把一襟芳思，与空阶榆荚。
千万缕、藏鸦细柳，为玉尊、起舞回雪。
想见西出阳关，故人初别。','',''),('songci300-132','八归','姜夔','songci300','八归','','芳莲坠粉，蔬桐吹绿，庭院暗雨乍歇。
无端抱影销魂处，还见筱墙萤暗，藓阶蛩切。
送客重寻西去路，问水面、琵琶谁拨。
最可惜、一片江山，总付与啼。
长恨相从未款，而今何事，又对西风离别。
渚寒烟淡，棹移人远，缥缈行舟如叶。
想文君望久，倚竹愁生步罗袜。
归来后、翠尊双饮，下了珠帘，玲珑闲看月。','',''),('songci300-133','扬州慢','姜夔','songci300','扬州慢','','淮左名都，竹西佳处，解鞍少驻初程。
过春风十里，尽荠麦青青。
自胡马窥江去后，废池乔木，犹厌言兵。
渐黄昏，清角吹寒，都在空城。
杜郎俊赏，算而今，重到须惊。
纵豆蔻词工，青楼梦好，难赋深情。
二十四桥仍在，波心荡、冷月无声。
念桥边红药，年年知为谁生。','',''),('songci300-134','长亭怨慢','姜夔','songci300','长亭怨慢','','渐吹尽、枝头香絮。
是处人家，绿深门户。
远浦萦回，暮帆零乱向何许。
阅人多矣，谁得似、长亭树。
树若有情时，不会得、青青如此。
日暮。
望高城不见，只见乱山无数。
韦郎去也，怎忘得、玉环分付。
第一是、早早归来，怕红萼、无人为主。
算空有并刀，难翦离愁千缕。','',''),('songci300-135','淡黄柳','姜夔','songci300','淡黄柳','','空城晓月。
吹入垂杨陌。
马上单衣寒恻恻。
看尽鹅黄嫩绿，都是江南旧相识。
正岑寂。
明朝又寒食。
强携酒、小桥宅，怕梨花落尽成秋色。
燕燕飞来，问春何在，唯有池塘自碧。','',''),('songci300-136','暗香','姜夔','songci300','暗香','','旧时月色。
算几番照我，梅边吹笛。
唤起玉人，不管清寒与攀摘。
何逊而今渐老，都忘却、春风词笔。
但怪得、竹外疏花，香冷入瑶席。
江国。
正寂寂。
叹寄与路遥，夜雪初积。
翠尊易泣。
红萼无言耿相忆。
长记曾携手处，千树压、西湖寒碧。
又片片、吹尽也，几时见得。','',''),('songci300-137','疏影','姜夔','songci300','疏影','','苔枝缀玉。
有翠禽小小，枝上同宿。
客里相逢，篱角黄昏，无言自倚修竹。
昭君不惯胡沙远，但暗忆、江南江北。
想佩环、月夜归来，化作此花幽独。
犹记深宫旧事，那人正睡里，飞近蛾绿。
莫似春风，不管盈盈，早与安排金屋。
还教一片随波去，又却怨、玉龙哀曲。
等恁时、重觅幽香，已入小窗横幅。','',''),('songci300-138','翠楼吟','姜夔','songci300','翠楼吟','','月冷龙沙，尘轻虎落，今年汉初赐。
新翻胡部曲，听毡幕、元戎歌吹。
层楼高峙。
看栏曲萦红，檐牙飞翠。
人姝丽。
粉香吹下，夜寒风细。
此地。
宜有词仙，拥素云黄鹤，与君游戏。
玉梯凝望久，叹芳草、萋萋千里。
天涯情味。
仗酒清愁，花销英气。
西山外。
晚来还卷，一帘秋霁。','',''),('songci300-139','木兰花・玉楼春','钱惟演','songci300','木兰花・玉楼春','','城上风光莺语乱。
城下烟波春拍岸。
绿杨芳草几时休，泪眼愁肠先已断。
情怀渐变成衰晚。
鸾鉴朱颜惊暗换。
昔年多病厌芳尊，今日芳尊惟恐浅。','',''),('songci300-140','苏幕遮','范仲淹','songci300','苏幕遮','','碧云天，黄叶地。
秋色连波，波上寒烟翠。
山映斜阳天接水。
芳草无情，更在斜阳外。
黯乡魂，追旅思。
夜夜除非，好梦留人睡。
明月楼高休独倚。
酒入愁肠，化作相思泪。','',''),('songci300-141','御街行','范仲淹','songci300','御街行','','纷纷堕叶飘香砌。
夜寂静、寒声碎。
真珠帘卷玉楼空，天淡银河垂地。
年年今夜，月华如练，长是人千里。
愁肠已断无由醉。
酒未到、先成泪。
残灯明灭枕头欹。
谙尽孤眠滋味。
都来此事，眉间心上，无计相回避。','',''),('songci300-142','曲玉管','柳永','songci300','曲玉管','','陇首云飞，江边日晚，烟波满目凭阑久。
立望关河萧索，千里清秋。
忍凝眸。
杳杳神京，盈盈仙子，别来锦字终难偶。
断雁无凭，冉冉飞下汀洲。
思悠悠。
暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁。
阻追游。
每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。','',''),('songci300-143','雨霖铃','柳永','songci300','雨霖铃','','寒蝉凄切。
对长亭晚，骤雨初歇。
都门帐饮无绪，留恋处、兰舟催发。
执手相看泪眼，竟无语凝噎。
念去去、千里烟波，暮霭沈沈楚天阔。
多情自古伤离别。
更那堪、冷落清秋节。
今宵酒醒何处，杨柳岸、晓风残月。
此去经年，应是良辰、好景虚设。
便纵有、千种风情，更与何人说。','',''),('songci300-144','采莲令','柳永','songci300','采莲令','','月华收，云淡霜天曙。
西征客、此时情苦。
翠娥执手送临歧，轧轧开朱户。
千娇面、盈盈伫立，无言有泪，断肠争忍回顾。
一叶兰舟，便恁急桨凌波去。
贪行色、岂知离绪。
万般方寸，但饮恨，脉脉同谁语。
更回首、重城不见，寒江天外，隐隐两三烟树。','',''),('songci300-145','凤栖梧・蝶恋花','柳永','songci300','凤栖梧・蝶恋花','','伫倚危楼风细细。
望极春愁，黯黯生天际。
草色烟光残照里。
无言谁会凭阑意。
拟把疏狂图一醉。
对酒当歌，强乐还无味。
衣带渐宽终不悔。
为伊消得人憔悴。','',''),('songci300-146','浪淘沙','柳永','songci300','浪淘沙','','梦觉、透窗风一线，寒灯吹息。
那堪酒醒，又闻空阶，夜雨频滴。
嗟因循、久作天涯客。
负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。
愁极。
再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。
云尤雨，有万般千种，相怜相惜。
恰到如今，天长漏永，无端自家疏隔。
知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。','',''),('songci300-147','定风波','柳永','songci300','定风波','','自春来、惨绿愁红，芳心是事可可。
日上花梢，莺穿柳带，犹压香衾卧。
暖酥消，腻云。
终日厌厌倦梳裹。
无那。
恨薄情一去，音书无个。
早知恁麽。
悔当初、不把雕鞍锁。
向鸡窗、只与蛮笺象管，拘束教吟课。
镇相随，莫抛躲。
针线闲拈伴伊坐。
和我。
免使年少，光阴虚过。','',''),('songci300-148','少年游','柳永','songci300','少年游','','长安古道马迟迟。
高柳乱蝉栖。
夕阳岛外，秋风原上，目断四天垂。
归云一去无踪迹，何处是前期。
狎兴生疏，酒徒萧索，不似去年时。','',''),('songci300-149','戚氏','柳永','songci300','戚氏','','晚秋天。
一霎微雨洒庭轩。
槛菊萧疏，井梧零乱惹残烟。
凄然。
望江关。
飞云黯淡夕阳间。
当时宋玉悲感，向此临水与登山。
远道迢递，行人凄楚，倦听陇水潺。
正蝉吟败叶，蛩响衰草，相应喧喧。
孤馆度日如年。
风露渐变，悄悄至更阑。
长天净，绛河清浅，皓月婵娟。
思绵绵。
夜永对景，那堪屈指，暗想从前。
未名未禄，绮陌红楼，往往经岁迁延。
帝里风光好，当年少日，暮宴朝欢。
况有狂朋怪侣，遇当歌、对酒竞留连。
别来迅景如梭，旧游似梦，烟水程何限。
念利名、憔悴长萦绊。
追往事、空惨愁颜。
漏箭移、稍觉轻寒。
渐呜咽、画角数声残。
对闲窗畔，停灯向晓，抱影无眠。','',''),('songci300-150','夜半乐','柳永','songci300','夜半乐','','冻云黯淡天气，扁舟一叶，乘兴离江渚。
渡万壑千岩，越溪深处。
怒涛渐息，樵风乍起，更闻商旅相呼。
片帆高举。
泛画鹢、翩翩过南浦。
望中酒旆闪闪，一簇烟村，数行霜树。
残日下，渔人鸣榔归去。
败荷零落，衰杨掩映，岸边两两三三，浣沙游女。
避行客、含羞笑相语。
到此因念，绣阁轻抛，浪萍难驻。
叹后约丁宁竟何据。
惨离怀，空恨岁晚归期阻。
凝泪眼、杳杳神京路。
断鸿声远长天暮。','',''),('songci300-151','玉蝴蝶','柳永','songci300','玉蝴蝶','','望处雨收云断，凭阑悄悄，目送秋光。
晚景萧疏，堪动宋玉悲凉。
水风轻、苹花渐老，月露冷、梧叶飘黄。
遣情伤。
故人何在，烟水茫茫。
难忘。
文期酒会，几孤风月，屡变星霜。
海阔山遥，未知何处是潇湘。
念双燕、难凭远信，指暮天、空识归航。
黯相望。
断鸿声里，立尽斜阳。','',''),('songci300-152','八声甘州','柳永','songci300','八声甘州','','对潇潇、暮雨洒江天，一番洗清秋。
渐霜风凄惨，关河冷落，残照当楼。
是处红衰翠减，苒苒物华休。
惟有长江水，无语东流。
不忍登高临远，望故乡渺邈，归思难收。
叹年来踪迹，何事苦淹留。
想佳人、妆楼望，误几回、天际识归舟。
争知我、倚阑干处，正恁凝愁。','',''),('songci300-153','竹马子・竹马儿','柳永','songci300','竹马子・竹马儿','','登孤垒荒凉，危亭旷望，静临烟渚。
对雌霓挂雨，雄风拂槛，微收烦暑。
渐觉一叶惊秋，残蝉噪晚，素商时序。
览景想前欢，指神京，非雾非烟深处。
向此成追感，新愁易积，故人难聚。
凭高尽日凝伫。
赢得消魂无语。
极目霁霭霏微，暝鸦零乱，萧索江城暮。
南楼画角，又送残阳去。','',''),('songci300-154','迷神引','柳永','songci300','迷神引','','一叶扁舟轻帆卷。
暂泊楚江南岸。
孤城暮角，引胡茄怨。
水茫茫，平沙雁、旋惊散。
烟敛寒林簇，画屏展。
天际遥山小，黛眉浅。
旧赏轻抛，到此成游宦。
觉客程劳，年光晚。
异乡风物，忍萧索、当愁眼。
帝城赊，秦楼阻，旅魂乱。
芳草连空阔，残照满。
佳人无消息，断云远。','',''),('songci300-155','醉垂鞭','张先','songci300','醉垂鞭','','双蝶绣罗裙。
东池宴。
初相见。
朱粉不深匀。
闲花淡淡春。
细看诸处好。
人人道。
柳腰身。
昨日乱山昏。
来时衣上云。','',''),('songci300-156','一丛花令・一丛花','张先','songci300','一丛花令・一丛花','','伤高怀远几时穷。
无物似情浓。
离愁正引千丝乱，更东陌、飞絮。
嘶骑渐遥，征尘不断，何处认郎踪。
双鸳池沼水溶溶。
南北小桡通。
梯横画阁黄昏后，又还是、斜月帘栊。
沈恨细思，不如桃杏，犹解嫁东风。','',''),('songci300-157','天仙子','张先','songci300','天仙子','','水调数声持酒听。
午醉醒来愁未醒。
送春春去几时回，临晚镜。
伤流景。
往事后期空记省。
沙上并禽池上暝。
云破月来花弄影。
重重帘幕密遮灯，风不定。
人初静。
明日落红应满径。','',''),('songci300-158','千秋岁','张先','songci300','千秋岁','','数声鶗鴂。
又报芳菲歇。
惜春更把残红折。
雨轻风色暴，梅子青时节。
永丰柳，无人尽日飞花雪。
莫把幺弦拨。
怨极弦能说。
天不老，情难绝。
心似双丝网，中有千千结。
夜过也，东窗未白凝残月。','',''),('songci300-159','青门引・青门饮','张先','songci300','青门引・青门饮','','乍暖还轻冷。
风雨晚来方定。
庭轩寂寞近清明，残花中酒，又是去年病。
楼头画角风吹醒。
入夜重门静。
那堪更被明月，隔墙送过秋千影。','',''),('songci300-160','浣溪沙','晏殊','songci300','浣溪沙','','一曲新词酒一杯。
去年天气旧亭台。
夕阳西下几时回。
无可奈何花落去，似曾相识燕归来。
小园香径独徘徊。','',''),('songci300-161','浣溪沙','晏殊','songci300','浣溪沙','','一向年光有限身。
等闲离别易消魂。
酒筵歌席莫辞频。
满目山河空念远，落花风雨更伤春。
不如怜取眼前人。','',''),('songci300-162','清平乐','晏殊','songci300','清平乐','','金风细细。
叶叶梧桐坠。
绿酒初尝人易醉。
一枕小窗浓睡。
紫微朱槿花残。
斜阳却照阑干。
双燕欲归时节，银屏昨夜微寒。','',''),('songci300-163','清平乐','晏殊','songci300','清平乐','','红笺小字。
说尽平生意。
鸿雁在云鱼在水。
惆怅此情难寄。
斜阳独倚西楼。
遥山恰对帘钩。
人面不知何处，绿波依旧东流。','',''),('songci300-164','木兰花・玉楼春','晏殊','songci300','木兰花・玉楼春','','燕鸿过后莺归去。
细算浮生千万绪。
长于春梦几多时，散似秋云无觅处。
闻琴解佩神仙侣。
挽断罗衣留不住。
劝君莫作独醒人，烂醉花间应有数。','',''),('songci300-165','木兰花・玉楼春','晏殊','songci300','木兰花・玉楼春','','池塘水绿风微暖。
记得玉真初见面。
重头歌韵响铮琮，入破舞腰红乱旋。
玉钩阑下香阶畔。
醉后不知斜日晚。
当时共我赏花人，点检如今无一半。','',''),('songci300-166','踏莎行','晏殊','songci300','踏莎行','','祖席离歌，长亭别宴。
香尘已隔犹回面。
居人匹马映林嘶，行人去棹依波转。
画阁魂消，高楼目断。
斜阳只送平波远。
无穷无尽是离愁，天涯地角寻思遍。','',''),('songci300-167','踏莎行','晏殊','songci300','踏莎行','','小径红稀，芳郊绿遍。
高台树色阴阴见。
春风不解禁杨花，乱扑行人面。
翠叶藏莺，朱帘隔燕。
炉香静逐游丝转。
一场愁梦酒醒时，斜阳却照深深院。','',''),('songci300-168','玉楼春','晏殊','songci300','玉楼春','','绿杨芳草长亭路。
年少抛人容易去。
楼头残梦五更钟，花底离情三月雨。
无情不似多情苦。
一寸还成千万缕。
天涯地角有穷时，只有相思无尽处。','',''),('songci300-169','玉楼春','宋祁','songci300','玉楼春','','东城渐觉风光好。
皱波纹迎客棹。
绿杨烟外晓寒轻，红杏枝头春意闹。
浮生长恨欢娱少。
肯爱千金轻一笑。
为君持酒劝斜阳，且向花间留晚照。','',''),('songci300-170','采桑子','欧阳修','songci300','采桑子','','群芳过后西湖好，狼籍残红。
飞絮蒙蒙。
垂柳阑干尽日风。
笙歌散尽游人去，始觉春空。
垂下帘栊。
双燕归来细雨中。','',''),('songci300-171','诉衷情','欧阳修','songci300','诉衷情','','清晨帘幕卷轻霜。
呵手试梅妆。
都缘自有离恨，故画作远山长。
思往事，惜流芳。
易成伤。
拟歌先敛，欲笑还颦，最断人肠。','',''),('songci300-172','踏莎行','欧阳修','songci300','踏莎行','','候馆梅残，溪桥柳细。
草熏风暖摇征辔。
离愁渐远渐无穷，迢迢不断如春水。
寸寸柔肠，盈盈粉泪。
楼高莫近危阑倚。
平芜尽处是春山，行人更在春山外。','',''),('songci300-173','蝶恋花','欧阳修','songci300','蝶恋花','','独倚危楼风细细。
望极离愁，黯黯生天际。
草色山光残照里。
无人会得凭阑意。
也拟疏狂图一醉。
对酒当歌，强饮还无味。
衣带渐宽都不悔。
况伊销得人憔悴。','',''),('songci300-174','玉楼春','欧阳修','songci300','玉楼春','','池塘水绿春微暖。
记得玉真初见面。
从头歌韵响铮鏦，入破舞腰红乱旋。
玉钩帘下香阶畔。
醉后不知红日晚。
当时共我赏花人，点检如今无一半。','',''),('songci300-175','玉楼春','欧阳修','songci300','玉楼春','','燕鸿过后春归去。
细算浮生千万绪。
来如春梦几多时，去似朝云无觅处。
闻琴解神仙侣。
挽断罗衣留不住。
劝君莫作独醒人，烂醉花间应有数。','',''),('songci300-176','玉楼春','欧阳修','songci300','玉楼春','','别后不知君远近。
触目凄凉多少闷。
渐行渐远渐无书，水阔鱼沈何处问。
夜深风竹敲秋韵。
万叶千声皆是恨。
故欹单枕梦中寻，梦又不成灯又尽。','',''),('songci300-177','浪淘沙','欧阳修','songci300','浪淘沙','','把酒祝东风。
且共从容。
垂杨紫陌洛城东。
总是当时携手处，游遍芳丛。
聚散苦匆匆。
此恨无穷。
今年花胜去年红。
可惜明年花更好，知与谁同。','',''),('songci300-178','风入松','俞国宝','songci300','风入松','','一春长费买花钱。
日日醉花边。
玉骢惯识西湖路，骄嘶过、沽酒垆前。
红杏香中箫鼓，绿杨影里秋千。
暖风十里丽人天。
花压髻云偏。
画船载取春归去，馀情寄、湖水湖烟。
明日重扶残醉，来寻陌上花钿。','',''),('songci300-179','绮罗香','史达祖','songci300','绮罗香','','做冷欺花，将烟困柳，千里偷催春暮。
尽日冥迷，愁里欲飞还住。
惊粉重、蝶宿西园，喜泥润、燕归南浦。
最妨它、佳约风流，钿车不到杜陵路。
沈沈江上望极，还被春潮晚急，难寻官渡。
隐约遥峰，和泪谢娘眉妩。
临断岸、新绿生时，是落红、带愁流处。
记当日、门掩梨花，翦灯深夜语。','',''),('songci300-180','双双燕','史达祖','songci300','双双燕','','过春社了，度帘幕中间，去年尘冷。
差池欲住，试入旧巢相并。
还相雕梁藻井。
又软语、商量不定。
飘然快拂花梢，翠尾分开红影。
芳径。
芹泥雨润。
爱贴地争飞，竞夸轻俊。
红楼归晚，看足柳昏花暝。
应自栖香正稳。
便忘了、天涯芳信。
愁损翠黛双蛾，日日画阑独凭。','',''),('songci300-181','东风第一枝','史达祖','songci300','东风第一枝','','巧沁兰心，偷黏草甲，东风欲障新暖。
谩凝碧瓦难留，信知暮寒轻浅。
行天入镜，做弄出、轻松纤软。
料故园、不卷重帘，误了乍来双燕。
青未了、柳回白眼。
红欲断、杏开素面。
旧游忆着山阴，厚盟遂妨上苑。
寒炉重暖，便放慢春衫针线。
恐凤靴、挑菜归来，万一灞桥相见。','',''),('songci300-182','喜迁莺','史达祖','songci300','喜迁莺','','月波疑滴。
望玉壶天近，了无尘隔。
翠眼圈花，冰丝织练，黄道宝光相直。
自怜诗酒瘦，难应接、许多春色。
最无赖，是随香趁烛，曾伴狂客。
踪迹。
谩记忆。
老了杜郎，忍听东风笛。
柳院灯疏，梅厅雪在，谁与细倾春碧。
旧情拘未定，犹自学、当年游历。
怕万一，误玉人、夜寒帘隙。','',''),('songci300-183','三姝媚','史达祖','songci300','三姝媚','','烟光摇缥瓦。
望晴檐多风，柳花如洒。
锦瑟横床，想泪痕尘影，凤弦常下。
倦出犀帷，频梦见、王孙骄马。
讳道相思，偷理绡裙，自惊腰衩。
惆怅南楼遥夜。
记翠箔张灯，枕肩歌罢。
又入铜驼，遍旧家门巷，首询声价。
可惜东风，将恨与、闲花俱谢。
记取崔徽模样，归来暗写。','',''),('songci300-184','夜合花','史达祖','songci300','夜合花','','柳锁莺魂，花翻蝶梦，自知愁染潘郎。
轻衫未揽，犹将泪点偷藏。
念前事，怯流光。
早春窥、酥雨池塘。
向销凝里，梅开半面，情满徐妆。
风丝一寸柔肠。
曾在歌边惹恨，烛底萦香。
芳机瑞锦，如何未织鸳鸯。
人扶醉，月依墙。
是当初、谁敢疏狂。
把闲言语，花房夜久，各自思量。','',''),('songci300-185','八归','史达祖','songci300','八归','','秋江带雨，寒沙萦水，人瞰画阁愁独。
烟蓑散响惊诗思，还被乱鸥飞去，秀句难续。
冷眼尽归图画上，认隔岸、微茫云屋。
想半属、渔市樵村，欲暮竞然竹。
须信风流未老，凭持酒、慰此凄凉心目。
一鞭南陌，几篙官渡，赖有歌眉舒绿。
只匆匆眺远，早觉闲愁挂乔木。
应难奈，故人天际，望彻淮山，相思无雁足。','',''),('songci300-186','玉胡蝶・玉蝴蝶','史达祖','songci300','玉胡蝶・玉蝴蝶','','晚雨未摧宫树，可怜闲叶，犹抱凉蝉。
短景归秋，吟思又接愁边。
漏初长、梦魂难禁，人渐老、风月俱寒。
想幽欢。
土花庭，虫网阑干。
无端。
啼蛄搅夜，恨随团扇，苦近秋莲。
一笛当楼，谢娘悬泪立风前。
故园晚、强留诗酒，新雁远、不致寒暄。
隔苍烟。
楚香罗袖，谁伴婵娟。','',''),('songci300-187','秋霁','史达祖','songci300','秋霁','','江水苍苍，望倦柳愁荷，共感秋色。
废阁先凉，古帘空暮，雁程最嫌风力。
故园信息。
爱渠入眼南山碧。
念上国。
谁是、脍鲈江汉未归客。
还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。
露蛩悲、清灯冷屋，翻书愁上鬓毛白。
年少俊游浑断得。
但可怜处，无奈苒苒魂惊，采香南浦，翦梅烟驿。','',''),('songci300-188','宴清都','卢祖皋','songci300','宴清都','','春讯飞琼管。
风日薄、度墙啼鸟声乱。
江城次第，笙歌翠合，绮罗香暖。
溶溶涧渌冰泮。
醉梦里、年华暗换。
料黛眉重锁隋堤，芳心还动梁苑。
新来雁阔云音，鸾分槛影，无计重见。
啼春细雨，笼愁澹月，恁时庭院。
离肠未语先断。
算犹有、凭高望眼。
更那堪、芳草连天，飞梅弄晚。','',''),('songci300-189','江城子','卢祖皋','songci300','江城子','','画楼帘幕卷新晴。
掩银屏。
晓寒轻。
坠粉飘香，日日唤愁生。
暗数十年湖上路，能几度，着娉婷。
年华空自感飘零。
拥春酲。
对谁醒。
天阔云闲，无处觅箫声。
载酒买花年少事，浑不似，旧心情。','',''),('songci300-190','小重山','章良能','songci300','小重山','','柳暗花明春事深。
小阑红芍药，已抽簪。
雨馀风软碎鸣禽。
迟迟日，犹带一分阴。
往事莫沈吟。
身闲时序好，且登临。
旧游无处不堪寻。
无寻处，惟有少年心。','',''),('songci300-191','满庭芳','张','songci300','满庭芳','','月洗高梧，露幽草，宝钗楼外秋深。
土花沿翠，萤火坠墙阴。
静听寒声断续，微韵转、凄咽悲沈。
争求侣，殷勤劝织，促破晓机心。
儿时，曾记得，呼灯灌穴，敛步随音。
任满身花影，犹自追寻。
携向花堂戏斗，亭台小、笼巧妆金。
今休说，从渠床下，凉夜伴孤吟。','',''),('songci300-192','花犯','吴文英','songci300','花犯','','小娉婷，清铅素靥，蜂黄暗偷晕。
翠翘敧鬓。
昨夜冷中庭，月下相认。
睡浓更苦凄风紧。
惊回心未稳。
送晓色、一壶葱茜，才知花梦准。
湘娥化作此幽芳，凌波路，古岸云沙遗恨。
临砌影，寒香乱、冻梅藏韵。
熏炉畔、旋移傍枕，还又见、玉人垂绀鬒。
料唤赏、清华池馆，台杯须满引。','',''),('songci300-193','浣溪沙','吴文英','songci300','浣溪沙','','门隔花深梦旧游。
夕阳无语燕归愁。
玉纤香动小帘钩。
落絮无声春堕泪，行云有影月含羞。
东风临夜冷于秋。','',''),('songci300-194','浣溪沙','吴文英','songci300','浣溪沙','','波面铜花冷不收。
玉人垂钓理纤钩。
月明池阁夜来秋。
江燕话归成晓别，水花红减似春休。
西风梧井叶先愁。','',''),('songci300-195','点绛唇','吴文英','songci300','点绛唇','','卷尽愁云，素娥临夜新梳洗。
暗尘不起。
酥润凌波地。
辇路重来，仿佛灯前事。
情如水。
小楼熏被。
春梦笙歌里。','',''),('songci300-196','祝英台近','吴文英','songci300','祝英台近','','采幽香，巡古苑，竹冷翠微路。
斗草溪根，沙印小莲步。
自怜两鬓清霜，一年寒食，又身在、云山深处。
昼闲度。
因甚天也悭春，轻阴便成雨。
绿暗长亭，归梦趁风絮。
有情花影阑干，莺声门径，解留我、霎时凝伫。','',''),('songci300-197','祝英台近','吴文英','songci300','祝英台近','','翦红情，裁绿意，花信上钗股。
残日东风，不放岁华去。
有人添烛西窗，不眠侵晓，笑声转、新年莺语。
旧尊俎。
玉纤曾擘黄柑，柔香系幽素。
归梦湖边，还迷镜中路。
可怜千点吴霜，寒销不尽，又相对、落梅如雨。','',''),('songci300-198','澡兰香','吴文英','songci300','澡兰香','','盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。
银瓶露井，彩云窗，往事少年依约。
为当时、曾写榴裙，伤心红绡褪萼。
黍梦光阴渐老，汀洲烟箬。
莫唱江南古调，怨抑难招，楚江沈魄。
薰风燕乳，暗雨梅黄，午镜澡兰帘幕。
念秦楼、也拟人归，应翦菖浦自酌。
但怅望、一屡新蟾，随人天角。','',''),('songci300-199','燕山亭','赵佶','songci300','燕山亭','','裁翦冰绡，打叠数重，冷淡燕脂匀注。
新样靓妆，艳溢香融，羞杀蕊珠宫女。
易得凋零，更多少、无情风雨。
愁苦。
闲院落凄凉，几番春暮。
凭寄离恨重重，这双燕，何曾会人言语。
天遥地远，万水千山，知他故宫何处。
怎不思量，除梦里、有时会去。
无据。
和梦也、有时不做。','',''),('songci300-200','烛影摇红','廖世美','songci300','烛影摇红','','霭霭春空，画楼森耸凌云渚。
紫薇登览最关情，绝妙夸能赋。
惆怅相思迟暮。
记当日、朱阑共语。
塞鸿难问，岸柳何穷，别愁纷絮。
催促年光，旧来流水知何处。
断肠何必更残阳，极目伤平楚。
晚霁波声带雨。
悄无人、舟横野渡。
数峰江上，芳草天涯，参差烟树。','',''),('songci300-201','凤凰台上忆吹箫','李清照','songci300','凤凰台上忆吹箫','','香冷金猊，被翻红浪，起来人未梳头。
任宝奁闲掩，日上帘钩。
生怕闲愁暗恨，多少事、欲说还休。
今年瘦，非干病酒，不是悲秋。
明朝，这回去也，千万遍阳关，也即难留。
念武陵春晚，云锁重楼。
记取楼前绿水，应念我、终日凝眸。
凝眸处，从今更数，几段新愁。','',''),('songci300-202','醉花阴','李清照','songci300','醉花阴','','薄雾浓云愁永昼。
瑞脑消金兽。
佳节又重阳，玉枕纱厨，半夜凉初透。
东篱把洒黄昏后，有暗香盈袖。
莫道不消魂，帘卷西风，人似黄花瘦。','',''),('songci300-203','念奴娇','李清照','songci300','念奴娇','','萧条庭院，有斜风细雨，重门须闭。
宠柳娇花寒食近，种种恼人天气。
险韵诗成，扶头酒醒，别是闲滋味。
征鸿过尽，万千心事难寄。
楼上几日春寒，帘垂四面，玉阑干慵倚。
被冷香消新梦觉，不许愁人不起。
清露晨流，新桐初引，多少游春意。
日高烟敛，更看今日晴未。','',''),('songci300-204','永遇乐','李清照','songci300','永遇乐','','落日熔金，暮云合璧，人在何处。
染柳烟浓，吹梅笛怨，春意知几许。
元宵佳节，融和天气，次第岂无风雨。
来相召、香车宝马，谢他酒朋诗侣。
中州盛日，闺门多暇，记得偏重三五。
铺翠冠儿，拈金雪柳，簇带争济楚。
如今憔悴，风鬟霜鬓，怕见夜间出去。
不如向、帘儿底下，听人笑语。','',''),('songci300-205','声声慢','李清照','songci300','声声慢','','寻寻觅觅，冷冷清清，凄凄惨惨戚戚。
乍暖还寒时候，最难将息。
三杯两盏淡酒，怎敌他、晚来风急。
雁过也，正伤心，却是旧时相识。
满地黄花堆积。
憔悴损，如今有谁摘。
守着窗儿，独自怎生得黑。
梧桐更兼细雨，到黄昏、点点滴滴。
这次第，怎一个、愁字了得。','',''),('songci300-206','苏武慢','蔡伸','songci300','苏武慢','','雁落平沙，烟笼寒水，古垒鸣笳声断。
青山隐隐，败叶萧萧，天际暝鸦零乱。
楼上黄昏，片帆千里归程，年华将晚。
望碧云空暮，佳人何处，梦魂俱远。
忆旧游、邃馆朱扉，小园香径，尚想桃花人面。
书盈锦轴，恨满金徽，难写寸心幽怨。
两地离愁，一尊芳酒，凄凉危阑倚遍。
尽迟留、凭仗西风，吹干泪眼。','',''),('songci300-207','柳梢青','蔡伸','songci300','柳梢青','','数声鶗鴂。
可怜又是，春归时节。
满院东风，海棠铺绣，梨花飘雪。
丁香露泣残枝，算未比、愁肠寸结。
自是休文，多情多感，不干风月。','',''),('songci300-208','摸鱼儿','辛弃疾','songci300','摸鱼儿','','更能消、几番风雨。
匆匆春又归去。
惜春长恨花开早，何况落红无数。
春且住。
见说道、天涯芳草迷归路。
怨春不语。
算只有殷勤，画檐珠网，尽日惹飞絮。
长门事，准拟佳期又误。
蛾眉曾有人妒。
千金纵买相如赋，脉脉此情谁诉。
君莫舞。
君不见、玉环飞燕皆尘土。
闲愁最苦。
休去倚危楼，斜阳正在，烟柳断肠处。','',''),('songci300-209','水龙吟','辛弃疾','songci300','水龙吟','','楚天千里清秋，水随天去秋无际。
遥岑远目，献愁供恨，玉簪螺髻。
落日楼头，断鸿声里，江南游子。
把吴钩看了，栏干拍遍，无人会、登临意。
休说鲈鱼堪。
尽西风、季鹰归未。
求田问舍，怕应羞见，刘郎才气。
可惜流年，忧愁风雨，树犹如此。
倩何人，唤取盈盈翠袖，英雄泪。','',''),('songci300-210','念奴娇','辛弃疾','songci300','念奴娇','','野棠花落，又匆匆、过了青明时节。
地东风欺客梦，一夜云屏寒怯。
曲岸持觞，垂杨系马，此地曾轻别。
楼空人去，旧游飞燕能说。
闻道绮陌东头，行人长见，帘底纤纤月。
旧恨春江流未断，新恨云山千叠。
料得明朝，尊前重见，镜里花难折。
也应惊问，近来多少华发。','',''),('songci300-211','鹧鸪天','辛弃疾','songci300','鹧鸪天','','枕簟溪堂冷欲秋。
断云依水晚来收。
红莲相倚浑如醉，白鸟无言定自愁。
书咄咄，且休休。
一丘一壑也风流。
不知筋力衰多少，但觉新来懒上楼。','',''),('songci300-212','菩萨蛮','辛弃疾','songci300','菩萨蛮','','郁孤台下清江水。
中间多少行人泪。
西北是长安。
可怜无数山。
青山遮不住。
毕竟江流去。
江晚正愁予。
山深闻鹧鸪。','',''),('songci300-213','木兰花慢','辛弃疾','songci300','木兰花慢','','老来情味减，对别酒、怯流年。
况屈指中秋，十分好月，不照人圆。
无情水、都不管，共西风、只等送归船。
秋晚莼鲈江上，夜深儿女灯前。
征衫。
便好去朝天。
玉殿正思贤。
想夜半承明，留教视草，却遣筹边。
长安故人问我，道寻常、泥酒只依然。
目断秋霄落雁，醉来时响空弦。','',''),('songci300-214','祝英台令','辛弃疾','songci300','祝英台令','','宝钗分，桃叶渡。
烟柳暗南浦。
怕上层楼，十日九风雨。
断肠片片飞红，都无人管，倩谁唤、流莺声住。
鬓边觑。
试把花卜心期，才簪又重数。
罗帐灯昏，呜咽梦中语。
是他春带愁来，春归何处。
却不解、将愁归去。','',''),('songci300-215','青玉案','辛弃疾','songci300','青玉案','','东风夜放花千树。
更吹落、星如雨。
宝马雕车香满路。
凤箫声动，玉壶光转，一夜鱼龙舞。
蛾儿雪柳黄金缕。
笑语盈盈暗香去。
众里寻他千百度。
蓦然回首，那人却在，灯火阑珊处。','',''),('songci300-216','贺新郎','辛弃疾','songci300','贺新郎','','凤尾龙香拨。
自开元、霓裳曲罢，几番风月。
最苦浔阳江头客，画舸亭亭待发。
记出塞、黄云堆雪。
马上离愁三万里，望昭阳、宫殿孤鸿没。
弦解语，恨难说。
辽阳驿使音尘绝。
琐窗寒、轻拢慢拈，泪珠盈睫。
推手含情还却手，一抹梁州哀彻。
千古事、云飞烟灭。
贺老定场无消息，想沈香亭北繁华歇。
弹到此，为呜咽。','',''),('songci300-217','贺新郎','辛弃疾','songci300','贺新郎','','绿树听鹈。
更那堪、鹧鸪声住，杜鹃声切。
啼到春归无寻处，苦恨芳菲都歇。
算未抵、人间离别。
马上琵琶关塞黑，更长门、翠辇辞金阙。
看燕燕，送归妾。
将军百战身名裂。
向河梁、回头万里，故人长绝。
易水萧萧西风冷，满座衣冠似雪。
正壮士、悲歌未彻。
啼鸟还知如许恨，料不啼清泪长啼血。
谁共我，醉明月。','',''),('songci300-218','汉宫春','辛弃疾','songci300','汉宫春','','春已归来，看美人头上，袅袅春幡。
无端风雨，未肯收尽馀寒。
年时燕子，料今宵、梦到西园。
浑未办、黄柑荐酒，更传青韭堆盘。
却笑东风从此，便薰梅染柳，更没些闲。
闲时又来镜里，转变朱颜。
清愁不断，问何人、会解连环。
生怕见、花开花落，朝来塞雁先还。','',''),('songci300-219','水龙吟','程垓','songci300','水龙吟','','夜来风雨匆匆，故园定是花无几。
愁多愁极，等闲孤负，一年芳意。
柳困花慵，杏青梅小，对人容易。
算好春长在，好花长见，元只是、人憔悴。
回首池南旧事。
恨星星、不堪重记。
如今但有，看花老眼，伤时清泪。
不怕逢花瘦，只愁怕、老来风味。
待繁红乱处，留云借月，也须拼醉。','',''),('songci300-220','绿头鸭・多丽','贺铸','songci300','绿头鸭・多丽','','玉人家，画楼珠箔临津。
托微风、彩箫流怨，断肠马上曾闻。
燕堂开、艳妆丛里，调琴思、认歌颦。
麝蜡烟浓，玉莲漏短，更衣不待酒初醺。
绣屏掩、枕鸳相就，香气渐暾暾。
回廊影，疏钟淡月，几许销魂。
翠钗分、银笺封泪，舞鞋从此生尘。
住兰舟、载将离恨，转南浦、背西曛。
记取明年，蔷薇谢后，佳期应未误行云。
凤城远，楚梅香嫩，先寄一枝春。
青门外，祗凭芳草，寻访郎君。','',''),('songci300-221','水龙吟','晁补之','songci300','水龙吟','','问春何苦匆匆，带风伴雨如驰骤。
幽葩细萼，小园低槛，壅培未就。
吹尽繁红，占春长久，不如垂柳。
算春常不老，人愁春老，愁只是、人间有。
春恨十常八九。
忍轻辜、芳醪经口。
那知自是，桃花结子，不因春瘦。
世上功名，老来风味，春归时候。
纵樽前痛饮，狂歌似旧，情难依旧。','',''),('songci300-222','忆少年','晁补之','songci300','忆少年','','无穷官柳，无情画舸，无根行客。
南山尚相送，只高城人隔。
罨画园林溪绀碧。
算重来、尽成陈迹。
刘郎鬓如此，况桃花颜色。','',''),('songci300-223','洞仙歌','晁补之','songci300','洞仙歌','','青烟幂处，碧海飞金镜。
永夜闲阶卧桂影。
露凉时、零乱多少寒，神京远，惟有蓝桥路近。
水晶帘不下，云母屏开，冷浸佳人淡脂粉。
待都将许多明，付与金尊，投晓共、流霞倾尽。
更携取、胡床上南楼，看玉做人间，素秋千倾。','',''),('songci300-224','瑞龙吟','周邦彦','songci300','瑞龙吟','','章台路。
还见褪粉梅梢，试花桃树。
坊陌人家，定巢燕子，归来旧处。
暗凝伫。
因念个人痴小，乍窥门户。
侵晨浅约宫黄，障风映袖，盈盈笑语。
前度刘郎重到，访邻寻里，同时歌舞。
唯有旧家秋娘，声价如故。
吟笺赋笔，犹记燕台句。
知谁伴，名园露饮，东城闲步。
事与孤鸿去。
探春尽是，伤离意绪。
官柳低金缕。
归骑晚，纤纤池塘飞雨。
断肠院落，一帘风絮。','',''),('songci300-225','锁窗寒・琐寒窗','周邦彦','songci300','锁窗寒・琐寒窗','','暗柳啼鸦，单衣伫立，小帘朱户。
桐花半亩，静锁一庭愁雨。
洒空阶，夜阑未休，故人剪烛西窗语。
似楚江暝宿，风灯零乱，少年羁旅。
迟暮。
嬉游处。
正店舍无烟，禁城百五。
旗亭唤酒，付与高阳俦侣。
想东园，桃李自春，小唇秀靥今在否。
到归时，定有残英，待客携尊俎。','',''),('songci300-226','风流子','周邦彦','songci300','风流子','','新绿小池塘。
风帘动，碎影舞斜阳。
羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。
绣阁凤帏深几许，曾听得理丝簧。
欲说又休，虑乖芳信，未歌先咽，愁近清觞。
遥知新妆了，开朱户，应自待月西厢。
最苦梦魂，今宵不到伊行。
问甚时说与，佳音密耗，寄将秦镜，偷换韩香。
天便教人，霎时厮见何妨。','',''),('songci300-227','应天长','周邦彦','songci300','应天长','','条风布暖，霏雾弄晴，池塘遍满春色。
正是夜堂无月，沈沈暗寒食。
梁间燕，前社客。
似笑我、闭门愁寂。
乱花过，隔院芸香，满地狼藉。
长记那回时，邂逅相逢，郊外驻油壁。
又见汉宫传烛，飞烟五候宅。
青青草，迷路陌。
强带酒，细寻前迹。
市桥远，柳下人家，犹自相识。','',''),('songci300-228','解连环','周邦彦','songci300','解连环','','怨怀无托。
嗟情人断绝，信音辽邈。
信妙手、能解连环，似风散雨收，雾轻云薄。
燕子楼空，暗尘锁、一床弦索。
想移根换叶。
尽是旧时，手种红药。
汀洲渐生杜若。
料舟依岸曲，人在天角。
谩记得、当日音书，把闲语闲言，待总烧却。
水驿春回，望寄我、江南梅萼。
拚今生，对花对酒，为伊落泪。','',''),('songci300-229','瑞鹤仙','周邦彦','songci300','瑞鹤仙','','悄郊原带郭。
行路永，客去车尘漠漠。
斜阳映山落。
敛馀红、犹恋孤城栏角。
凌波步弱。
过短亭、何用素约。
有流莺劝我，重解绣鞍，缓引春酌。
不记归时早暮，上马谁扶，醒眠朱阁。
惊飙动幕。
扶残醉，绕红药。
叹西园、已是花深无地，东风何事又恶。
任流光过却。
犹喜洞天自乐。','',''),('songci300-230','浪涛沙・浪淘沙','周邦彦','songci300','浪涛沙・浪淘沙','','昼阴重，霜凋岸草，雾隐城堞。
南陌脂车待发。
东门帐饮乍阕。
正拂面垂杨堪缆结。
掩红泪、玉手亲折。
念汉浦离鸿去何许，经时信音绝。
情切。
望中地远天阔。
向露冷风清，无人处、耿耿寒漏咽。
嗟万事难忘，唯是轻别。
翠尊未竭。
凭断云留取，西楼残月。
罗带光销纹衾叠。
连环解、旧香顿歇。
怨歌永、琼壶敲尽缺。
恨春去、不与人期，弄夜色，空馀满地梨花雪。','',''),('songci300-231','满庭芳','周邦彦','songci300','满庭芳','','风老莺雏，雨肥梅子，午阴嘉树清圆。
地卑山近，衣润费垆烟。
人静乌鸢自乐，小桥外、新绿溅溅。
凭栏久，黄芦苦竹，拟泛九江船。
年年。
如社燕，飘流瀚海，来寄修椽。
且莫思身外，长近尊前。
憔悴江南倦客，不堪听、急管繁弦。
歌筵畔，先安簟枕，容我醉时眠。','',''),('songci300-232','过秦楼','周邦彦','songci300','过秦楼','','水浴清蟾，叶喧凉吹，巷陌马声初断。
闲依露井，笑扑流萤，惹破画罗轻扇。
人静夜久凭阑，愁不归眠，立残更箭。
叹年华一瞬，人今千里，梦沈书远。
空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。
梅风地溽，虹雨苔滋，一架舞红都变。
谁信无，为伊才减江淹，情伤荀倩。
但明河影下，还看稀星数点。','',''),('songci300-233','夜游宫','周邦彦','songci300','夜游宫','','叶下斜阳照水。
卷轻浪、沈沈千里。
桥上酸风射眸子。
立多时，看黄昏，灯火市。
古屋寒窗底。
听几片、井桐飞坠。
不恋单衾再三起。
有谁知，为萧娘，书一纸。','',''),('songci300-234','解语花','周邦彦','songci300','解语花','','风销焰蜡，露烘炉。
花市光相射。
桂华流瓦。
纤云散，耿耿素娥欲下。
衣裳淡雅。
看楚女、纤腰一把。
箫鼓喧，人影参差，满路飘香麝。
因念都城放夜。
望千门如昼，嬉笑游冶。
钿车罗帕。
相逢处，自有暗尘随马。
年光是也。
唯只见、旧情衰谢。
清漏移，飞盖归来，从舞休歌罢。','',''),('songci300-235','大','周邦彦','songci300','大','','对宿烟收，春禽静，飞雨时鸣高屋。
墙头青玉旆，洗铅霜都尽，嫩梢相触。
润逼琴丝，寒侵枕障，虫网吹沾帘竹。
邮亭无人处，听檐声不断，困眠初熟。
奈愁极顿惊，梦轻难记，自怜幽独。
行人归意速。
最先念、流潦妨车毂。
怎奈向、兰成憔悴，卫清羸，等闲时、易伤心目。
未怪平阳客，双泪落、笛中哀曲。
况萧索、青芜国。
红糁铺地，门外荆桃如菽。
夜游共谁秉烛。','',''),('songci300-236','花犯','周邦彦','songci300','花犯','','粉墙低，梅花照眼，依然旧风味。
露痕轻缀。
疑净洗铅华，无限佳丽。
去年胜赏曾孤倚。
冰盘同宴喜。
更可惜，雪中高树，香篝熏素被。
今年对花最匆匆，相逢似有恨，依依愁悴。
吟望久，青苔上、旋看飞坠。
相将见、脆丸荐酒，人正在、空江烟浪里。
但梦想、一枝潇洒，黄昏斜照水。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('songci300-237','六丑','周邦彦','songci300','六丑','','正单衣试酒，恨客里、光阴虚掷。
愿春暂留，春归如过翼。
一去无迹。
为问花何在，夜来风雨，葬楚宫倾国。
钗钿堕处遗香泽。
乱点桃蹊，轻翻柳陌。
多情为谁追惜。
但蜂媒蝶使，时叩窗隔。
东园岑寂。
渐蒙笼暗碧。
静绕珍丛底，成叹息。
长条故惹行客。
似牵衣待话，别情无极。
残英小、强簪巾帻。
终不似一朵，钗头颤袅，向人侧。
漂流处、莫趁潮汐。
恐断红、尚有相思字，何由见得。','',''),('songci300-238','兰陵王','周邦彦','songci300','兰陵王','','柳阴直。
烟里丝丝弄碧。
隋堤上、曾见几番，拂水飘绵送行色。
登临望故国。
谁识。
京华倦客。
长亭路，年去岁来，应折柔条过千尺。
闲寻旧踪迹。
又酒趁哀弦，灯照离席。
梨花榆火催寒食。
愁一箭风快，半篙波暖，回头迢递便数驿。
望人在天北。
凄恻。
恨堆积。
渐别浦萦回，津堠岑寂。
斜阳冉冉春无极。
念月榭携手，露桥闻笛。
沈思前事，似梦里，泪暗滴。','',''),('songci300-239','西河','周邦彦','songci300','西河','','佳丽地。
南朝盛事谁记。
山围故国绕清江，髻鬟对起。
怒涛寂寞打孤城，风樯遥度天际。
断崖树，犹倒倚。
莫愁艇子曾系。
空馀旧迹郁苍苍，雾沈半垒。
夜深月过女墙来，赏心东望淮水。
酒旗戏鼓甚处市。
想依稀、王谢邻里。
燕子不知何世。
入寻常、巷陌人家，相对如说兴亡，斜阳里。','',''),('songci300-240','绮寮怨','周邦彦','songci300','绮寮怨','','上马人扶残醉，晓风吹未醒。
映水曲、翠瓦朱檐，垂杨里、乍见津亭。
当时曾题败壁，蛛丝罩、淡墨苔晕青。
念去来、岁月如流，徘徊久、叹息愁思盈。
去去倦寻路程。
江陵旧事，何曾再问杨琼。
旧曲凄清。
敛愁黛、与谁听。
尊前故人如在，想念我、最关情。
何须渭城。
歌声未尽处，先泪零。','',''),('songci300-241','拜星月・拜星月慢','周邦彦','songci300','拜星月・拜星月慢','','夜色催更，清尘收露，小曲幽坊月暗。
竹槛灯窗，识秋娘庭院。
笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。
水眄兰情，总平生稀见。
画图中、旧识春风面。
谁知道、自到瑶台畔。
眷恋雨润云温，苦惊风吹散。
念荒寒、寄宿无人馆。
重门闭、败壁秋虫叹。
怎奈向、一缕相思，隔溪山不断。','',''),('songci300-242','尉迟杯','周邦彦','songci300','尉迟杯','','隋堤路。
渐日晚、密霭生深树。
阴阴淡月笼沙，还宿河桥深处。
无情画舸，都不管、烟波隔南浦。
等行人、醉拥重衾，载将离恨归去。
因念旧客京华，长偎傍、疏林小槛欢聚。
冶叶倡条俱相识，仍惯见、珠歌翠舞。
如今向、渔村水驿，夜如岁、焚香独自语。
有何人、念我无，梦魂凝想鸳侣。','',''),('songci300-243','蝶恋花','周邦彦','songci300','蝶恋花','','月皎惊乌栖不定。
更漏将残，辘，牵金井。
唤起两眸清炯炯。
泪花落枕红棉泠。
执手霜风吹鬓影。
去意徊徨，别语愁难听。
楼上阑干横斗柄。
露寒人远鸡相应。','',''),('songci300-244','夜飞鹊・夜飞鹊慢','周邦彦','songci300','夜飞鹊・夜飞鹊慢','','河桥送人处，凉夜何其。
斜月远堕馀辉。
铜盘烛泪已流尽，霏霏凉露沾衣。
相将散离会，探风前津鼓，树杪参旗。
华骢会意，纵扬鞭、亦自行迟。
迢递路回清野，人语渐无闻，空带愁归。
何意重红满地，遗钿不见，斜径都迷。
兔葵燕麦，向残阳、欲与人齐。
但徘徊班草，欷酹酒，极望天西。','',''),('songci300-245','关河令・清商怨','周邦彦','songci300','关河令・清商怨','','秋阴时晴渐向暝，变一庭凄冷。
伫听寒声，云深无雁影。
更深人去寂静。
但照壁、孤灯相映。
酒已都醒，如何消夜永。','',''),('songci300-246','南浦','孔夷','songci300','南浦','','风悲画角，听单于、三弄落谯门。
投宿征骑，飞雪满孤村。
酒市渐闲灯火，正敲窗、乱叶舞纷纷。
送数声惊雁，下离烟水，嘹唳度寒云。
好在半胧溪月，到如今、无处不销魂。
故国梅花归梦，愁损绿罗裙。
为问暗香闲艳，也相思、万点付啼痕。
算翠屏应是，两眉馀恨倚黄昏。','',''),('songci300-247','临江仙','晁冲之','songci300','临江仙','','忆昔西池池上饮，年年多少欢娱。
别来不寄一行书。
寻常相见了，犹道不如初。
安稳锦屏今夜梦，月明好度江湖。
相思休问定何如。
情知春去后，管得落花无。','',''),('songci300-248','惜分飞','毛滂','songci300','惜分飞','','泪湿阑干花着露。
愁到眉峰碧聚。
此恨平分取。
更无言语。
空相觑。
短雨残云无意绪。
寂寞朝朝暮暮。
今夜山深处。
断魂分付。
潮回去。','',''),('songci300-249','天香','王沂孙','songci300','天香','','孤峤蟠烟，层涛蜕月，骊宫夜采铅水。
讯远槎风，梦深薇露，化作断魂心字。
红瓷候火，还乍识、冰环玉指。
一缕萦帘翠影，依稀海天云气。
几回娇半醉。
翦春灯、夜寒花碎。
更好故溪飞雪，小窗深闭。
荀令如今顿老，总忘却、樽前旧风味。
谩惜馀熏，空篝素被。','',''),('songci300-250','眉妩','王沂孙','songci300','眉妩','','渐新痕悬柳，澹彩穿花，依约破初暝。
便有团圆意，深深拜，相逢谁在香径。
画眉未稳，料素娥、犹带离恨。
最堪爱、一曲银钩小，宝帘挂秋冷。
千古盈亏休问。
叹慢磨玉斧，难补金镜。
太液池犹在，凄凉处、何人重赋清景。
故山夜永。
试待他、窥户端正。
看云外山河，还老尽、桂花影。','',''),('songci300-251','齐天乐','王沂孙','songci300','齐天乐','','一襟馀恨宫魂断，年年翠阴庭树。
乍咽凉柯，还移暗叶，重把离愁深诉。
西窗过雨。
怪瑶佩流空，玉筝调柱。
镜暗妆残，为谁娇鬓尚如许。
铜仙铅泪似洗，叹携盘去远，难贮零露。
病翼惊秋，枯形阅世，消得斜阳几度。
馀音更苦。
甚独抱清高，顿成凄楚。
谩想薰风，柳丝千万缕。','',''),('songci300-252','高阳台','王沂孙','songci300','高阳台','','残雪庭阴，轻寒帘影，霏霏玉管春葭。
小帖金泥，不知春在谁家。
相思一夜窗前梦，奈个人、水隔天遮。
但凄然，满树幽香，满地横斜。
江南自是离愁苦，况游骢古道，归雁平沙。
怎得银笺，殷勤与说年华。
如今处处生芳草，纵凭高、不见天涯。
更消他，几度东风，几度飞花。','',''),('songci300-253','法曲献仙音','王沂孙','songci300','法曲献仙音','','层绿峨峨，纤琼皎皎，倒压波痕清浅。
过眼年华，动人幽意，相逢几番春换。
记唤酒寻芳处，盈盈褪妆晚。
已销黯。
况凄凉、近来离思，应忘却、明月夜深归辇。
荏苒一枝春，恨东风、人似天远。
纵有残花，洒征衣、铅泪都满。
但殷勤折取，自遣一襟幽怨。','',''),('songci300-254','长亭怨・长亭怨慢','王沂孙','songci300','长亭怨・长亭怨慢','','泛孤艇、东皋过遍。
尚记当日，绿阴门掩。
屐齿莓阶，酒痕罗袖事何限。
欲寻前迹，空惆怅、成秋苑。
自约赏花人，别后总、风流云散。
水远。
怎知流水外，却是乱山尤远。
天涯梦短。
想忘了、绮疏雕槛。
望不尽、苒苒斜阳，抚乔木、年华将晚。
但数点红英，犹识西园凄婉。','',''),('songci300-255','紫萸香慢','姚云文','songci300','紫萸香慢','','近重阳、偏多风雨，绝怜此日暄明。
问秋香浓未，待携客、出西城。
正自羁怀多感，怕荒台高处，更不胜情。
向尊前、又忆洒酒插花人。
只座上、已无老兵。
凄情。
浅醉还醒。
愁不肯、与诗平。
记长楸走马，雕弓笮柳，前事休评。
紫萸一枝传赐，梦谁到、汉家陵。
尽乌纱、便随风去，要天知道，华发如此星星。
歌罢涕零。','',''),('songci300-256','贺新郎','蒋捷','songci300','贺新郎','','梦冷黄金屋。
叹秦筝、斜鸿阵里，素弦尘扑。
化作娇莺飞归去，犹认纱窗旧绿。
正过雨、荆桃如菽。
此恨难平君知否，似琼台、涌起弹棋局。
消瘦影，嫌明烛。
鸳楼碎泻东西玉。
问芳、何时再展，翠钗难卜。
待把宫眉横云样，描上生绡画幅。
怕不是、新来妆束。
彩扇红牙今都在，恨无人、解听开元曲。
空掩袖，倚寒竹。','',''),('songci300-257','女冠子','蒋捷','songci300','女冠子','','蕙花香也。
雪晴池馆如画。
春风飞到，宝钗楼上，一片笙箫，琉璃光射。
而今灯漫挂。
不是暗尘明月，那时元夜。
况年来、心懒意怯，羞与蛾儿争要。
江城人悄初更打。
问繁华谁解，再向天公借。
剔残红灺。
但梦里隐隐，钿车罗帕。
吴笺银粉砑。
待把旧家风景，写成闲话。
笑绿鬟邻女，倚窗犹唱，夕阳西下。','',''),('songci300-258','瑞鹤仙','蒋捷','songci300','瑞鹤仙','','绀烟迷雁迹。
渐断鼓零钟，街喧初息。
风檠背寒壁。
放冰蜍飞到，丝丝窗隙。
琼瑰暗泣。
念乡关、霜芜似织。
漫将身、化鹤归来，忘却旧游端的。
欢极。
蓬壶蕖浸，花院梨溶，醉连春夕。
柯云罢弈。
樱桃在，梦难觅。
劝清光，乍可幽窗相伴，休照红楼夜笛。
怕人间、换谱伊凉，素娥未识。','',''),('songci300-259','甘州・八声甘州','张炎','songci300','甘州・八声甘州','','记玉关、踏雪事清游。
寒气脆貂裘。
傍枯林古道，长河饮马，此意悠悠。
短梦依然江表，老泪洒西州。
一字无题处，落叶都愁。
载取白云归去，问谁留楚佩，弄影中洲。
折芦花赠远，零落一身秋。
向寻常野桥流水，待招来、不是旧沙鸥。
空怀感，有斜阳处，却怕登楼。','',''),('songci300-260','渡江云','张炎','songci300','渡江云','','山空天入海，倚楼望极，风急暮潮初。
一帘鸠外雨，几处闲田，隔水动春锄。
新烟禁柳，想如今、绿到西湖。
犹记得、当年深隐，门掩两三株。
愁余。
荒洲古溆，断梗疏萍，更漂流何处。
空自觉、围羞带减，影怯灯孤。
常疑即见桃花面，甚近来、翻笑无书。
书纵远，如何也都无。','',''),('songci300-261','解连环','张炎','songci300','解连环','','楚江空晚。
怅离群万里，恍然惊散。
自顾影、欲下寒塘，正沙净草枯，水平天远。
写不成书，只寄得、相思一点。
料因循误了，残毡拥雪，故人心眼。
谁怜旅愁荏苒。
谩长门夜悄，锦筝弹怨。
想伴侣、犹宿芦花，也曾念春前，去程应转。
暮雨相呼，怕蓦地、玉关重见。
未羞他、双燕归来，画帘半卷。','',''),('songci300-262','月下笛','张炎','songci300','月下笛','','万里孤云，清游渐远，故人何处。
寒窗梦里，犹记经行旧时路。
连昌约略无多柳，第一是、难听夜雨。
谩惊回凄悄，相看烛影，拥衾谁语。
张绪。
归何暮。
半零落，依依断桥鸥鹭。
天涯倦旅。
此时心事良苦。
只愁重洒西州泪，问杜曲、人家在否。
恐翠袖、正天寒，犹倚梅花那树。','',''),('songci300-263','点绛唇','苏过','songci300','点绛唇','','新月娟娟，夜寒江静山衔斗。
起来搔首。
梅影横窗瘦。
好个霜天，闲却传杯手。
君知否。
乱鸦啼后。
归兴浓如酒。','',''),('songci300-264','贺新郎','叶梦得','songci300','贺新郎','','睡起啼莺语。
掩青苔、房栊向晚，乱红无数。
吹尽残花无人见，惟有垂杨自舞。
渐暖霭、初回轻暑。
宝扇重寻明月影，暗尘侵、尚有乘鸾女。
惊旧恨，遽如许。
江南梦断横江渚。
浪黏天、葡萄涨绿，半空烟雨。
无限楼前沧波意，谁采苹花寄取。
但怅望、兰舟容与。
万里云帆何时到，送孤鸿、目断千山阻。
谁为我，唱金缕。','',''),('songci300-265','虞美人','叶梦得','songci300','虞美人','','落花已作风前舞。
又送黄昏雨。
晓来庭院半残红。
惟有游丝千丈、晴空。
殷勤花下同携手。
更尽杯中酒。
美人不用敛蛾眉。
我亦多情、无奈酒阑时。','',''),('songci300-266','喜迁莺','刘一止','songci300','喜迁莺','','晓光催角。
听宿鸟未惊，邻鸡先觉。
迤逦烟村，马嘶人起，残月尚穿林薄。
泪痕带霜微凝，酒力冲寒犹弱。
叹倦客、悄不禁，重染风尘京洛。
追念，人别后，心事万重，难觅孤鸿托。
翠幌娇深，曲屏香暖，争念岁寒飘泊。
怨月恨花烦恼，不是不曾经着。
这情味，望一成消减，新来还恶。','',''),('songci300-267','点绛唇','汪藻','songci300','点绛唇','','新月娟娟，夜寒江静山衔斗。
起来搔首。
梅影横窗瘦。
好个霜天，闲却传杯手。
君知否。
乱鸦啼后。
归兴浓于酒。','',''),('songci300-268','蓦山溪','曹组','songci300','蓦山溪','','洗妆真态，不作铅华御。
竹外一枝斜，想佳人、天寒日暮。
黄昏小院，无处着清香，风细细，雪垂垂，何况江头路。
月边疏影，梦到消魂处。
结子欲黄时，又须着、廉纤细雨。
孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。','',''),('songci300-269','三台','万俟咏','songci300','三台','','见梨花初带夜月，海棠半含朝雨。
内苑春、不禁过青门，御沟涨、潜通南浦。
东风静、细柳垂金缕。
望凤阙、非烟非雾。
好时代、朝野多欢，遍九陌、太平箫鼓。
乍莺儿百啭断续，燕子飞来飞去。
近绿水、台榭映秋千，斗草聚、双双游女。
饧香更、酒冷踏青路。
会暗识、夭桃朱户。
向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。
正轻寒轻暖漏永，半阴半晴云暮。
禁火天、已是试新妆，岁华到、三分佳处。
清明看、汉宫传蜡炬。
散翠烟、飞入槐府。
敛兵卫、阊阖门开，住传宣、又还休务。','',''),('songci300-270','江神子慢・江城子慢','田为','songci300','江神子慢・江城子慢','','玉台挂秋月。
铅素浅，梅花傅香雪。
冰姿洁。
金莲衬、小小凌波罗袜。
雨初歇。
楼外孤鸿声渐远，远山外、行人音信绝。
此恨对语犹难，那堪更寄书说。
教人红销翠减，觉衣宽金缕，都为轻别。
太情切。
消魂处、画角黄昏时节。
声呜咽。
落尽庭花春去也，银蟾迥、无情圆又缺。
恨伊不似馀香，惹鸳鸯结。','',''),('songci300-271','菩萨蛮','陈克','songci300','菩萨蛮','','赤阑桥尽香街直。
笼街细柳娇无力。
金碧上青空。
花晴帘影红。
黄衫飞白马。
日日青楼下。
醉眼不逢人。
午香吹暗尘。','',''),('songci300-272','菩萨蛮','陈克','songci300','菩萨蛮','','绿芜墙绕青苔院。
中庭日淡芭蕉卷。
蝴蝶上阶飞。
烘帘自在垂。
玉钩双语燕。
宝甃杨花转。
几处簸钱声。
绿窗春睡轻。','',''),('songci300-273','鹧鸪天','周紫芝','songci300','鹧鸪天','','一点残红欲尽时。
乍凉秋气满屏帏。
梧桐叶上三更雨，叶叶声声是别离。
调宝瑟，拨金猊。
那时同唱鹧鸪词。
如今风雨西楼夜，不听清歌也泪垂。','',''),('songci300-274','踏莎行','周紫芝','songci300','踏莎行','','情似游丝，人如飞絮。
泪珠阁定空相觑。
一溪烟柳万丝垂，无因系得兰舟住。
雁过斜阳，草迷烟渚。
如今已是愁无数。
明朝且做莫思量，如何过得今宵去。','',''),('songci300-275','青玉案','无名氏','songci300','青玉案','','年年社日停针线。
怎忍见、双飞燕。
今日江城春已半。
一身犹在，乱山深处，寂寞溪桥畔。
春衫着破谁针线。
点点行行泪痕满。
落日解鞍芳草岸。
花无人戴，酒无人劝，醉也无人管。','',''),('songci300-276','秦楼月・忆秦娥','范成大','songci300','秦楼月・忆秦娥','','楼阴缺。
阑干影卧东厢月。
东厢月。
一天风露，杏花如雪。
隔烟催漏金虬咽。
罗帏暗淡灯花结。
灯花结。
片时春梦，江南天阔。','',''),('songci300-277','霜天晓角','范成大','songci300','霜天晓角','','晚晴风歇。
一夜春折威。
脉脉花疏天淡，云来去、数枝雪。
胜绝。
愁亦绝。
此情谁共说。
惟有两行低雁，知人倚、画楼月。','',''),('songci300-278','眼儿媚','范成大','songci300','眼儿媚','','酣酣日脚紫烟浮。
妍暖破轻裘。
困人天色，醉人花气，午梦扶头。
春慵恰似春塘水，一片縠纹愁。
溶溶泄泄，东风无力，欲皱还休。','',''),('songci300-279','六州歌头','张孝祥','songci300','六州歌头','','长怀望断，关塞莽然平。
征尘暗，霜风劲，悄边声。
黯销凝。
追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。
隔水毡乡，落日牛羊下，区脱纵横。
看名王宵猎，骑火一川明。
笳鼓悲鸣。
遣人惊。
念腰间箭，匣中剑，空埃蠹，竟何成。
时易失，心徒壮，岁将零。
渺神京。
干羽方怀远，静烽燧，且休兵。
冠盖使，纷驰骛，若为情。
闻道中原遗老，常南望，羽葆霓旌。
使行人到此，忠愤气填膺。
有泪如倾。','',''),('songci300-280','念奴娇','张孝祥','songci300','念奴娇','','洞庭青草，近中秋、更无一点风色。
玉鉴琼田三万顷，着我扁舟一叶。
素月分辉，明河共影，表里俱澄澈。
悠然心会，妙处难与君说。
应念岭海经年，孤光自照，肝肺皆冰雪。
短发萧骚襟袖冷，稳泛沧浪空阔。
尽吸西江，细斟北斗，万象为宾客。
扣舷独笑，不知今夕何夕。','',''),('shijing-001','关雎','','shijing','','国风 · 周南','关关雎鸠，在河之洲。窈窕淑女，君子好逑。
参差荇菜，左右流之。窈窕淑女，寤寐求之。
求之不得，寤寐思服。悠哉悠哉，辗转反侧。
参差荇菜，左右采之。窈窕淑女，琴瑟友之。
参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。','',''),('shijing-002','葛覃','','shijing','','国风 · 周南','葛之覃兮，施于中谷，维叶萋萋。黄鸟于飞，集于灌木，其鸣喈喈。
葛之覃兮，施于中谷，维叶莫莫。是刈是濩，为絺为绤，服之无斁。
言告师氏，言告言归。薄污我私，薄浣我衣。害浣害否，归宁父母。','',''),('shijing-003','卷耳','','shijing','','国风 · 周南','采采卷耳，不盈顷筐。嗟我怀人，置彼周行。
陟彼崔嵬，我马虺颓。我姑酌彼金罍，维以不永怀。
陟彼高冈，我马玄黄。我姑酌彼兕觥，维以不永伤。
陟彼砠矣，我马瘏矣，我仆痡矣，云何吁矣。','',''),('shijing-004','樛木','','shijing','','国风 · 周南','南有樛木，葛藟累之。乐只君子，福履绥之。
南有樛木，葛藟荒之。乐只君子，福履将之。
南有樛木，葛藟萦之。乐只君子，福履成之。','',''),('shijing-005','螽斯','','shijing','','国风 · 周南','螽斯羽，诜诜兮。宜尔子孙，振振兮。
螽斯羽，薨薨兮。宜尔子孙。绳绳兮。
螽斯羽，揖揖兮。宜尔子孙，蛰蛰兮。','',''),('shijing-006','桃夭','','shijing','','国风 · 周南','桃之夭夭，灼灼其华。之子于归，宜其室家。
桃之夭夭，有蕡其实。之子于归，宜其家室。
桃之夭夭，其叶蓁蓁。之子于归，宜其家人。','',''),('shijing-007','兔罝','','shijing','','国风 · 周南','肃肃兔罝，椓之丁丁。赳赳武夫，公侯干城。
肃肃兔罝，施于中逵。赳赳武夫，公侯好仇。
肃肃免罝，施于中林。赳赳武夫，公侯腹心。','',''),('shijing-008','芣苡','','shijing','','国风 · 周南','采采芣苡，薄言采之。采采芣苡，薄言有之。
采采芣苡，薄言掇之。采采芣苡，薄言捋之。
采采芣苡，薄言袺之。采采芣苡，薄言襭之。','',''),('shijing-009','汉广','','shijing','','国风 · 周南','南有乔木，不可休息。汉有游女，不可求思。汉之广矣，不可泳思。江之永矣，不可方思。
翘翘错薪，言刈其楚。之子于归，言秣其马。汉之广矣，不可泳思。江之永矣，不可方思。
翘翘错薪，言刈其蒌。之子于归。言秣其驹。汉之广矣，不可泳思。江之永矣，不可方思。','',''),('shijing-010','汝坟','','shijing','','国风 · 周南','遵彼汝坟，伐其条枚。未见君子，惄如调饥。
遵彼汝坟，伐其条肄。既见君子，不我遐弃。
鲂鱼赪尾，王室如毁。虽则如毁，父母孔迩。','',''),('shijing-011','麟之趾','','shijing','','国风 · 周南','麟之趾，振振公子，于嗟麟兮。
麟之定，振振公姓，于嗟麟兮。
麟之角，振振公族，于嗟麟兮。','',''),('shijing-012','鹊巢','','shijing','','国风 · 召南','维鹊有巢，维鸠居之。之子于归，百两御之。
维鹊有巢，维鸠方之。之子于归，百两将之。
维鹊有巢，维鸠盈之。之子于归，百两成之。','',''),('shijing-013','采蘩','','shijing','','国风 · 召南','于以采蘩？于沼于沚。于以用之？公侯之事。
于以采蘩？于涧之中。于以用之？公侯之宫。
被之僮僮，夙夜在公。被之祁祁，薄言还归。','',''),('shijing-014','草虫','','shijing','','国风 · 召南','喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。亦既见止，亦既觏止，我心则降。
陟彼南山，言采其蕨。未见君子，忧心惙惙。亦既见止，亦既觏止，我心则说。
陟彼南山，言采其薇。未见君子，我心伤悲。亦既见止，亦既觏止，我心则夷。','',''),('shijing-015','采苹','','shijing','','国风 · 召南','于以采苹？南涧之滨。于以采藻？于彼行潦。
于以盛之？维筐及筥。于以湘之？维锜及釜。
于以奠之？宗室牖下。谁其尸之？有齐季女。','',''),('shijing-016','甘棠','','shijing','','国风 · 召南','蔽芾甘棠，勿翦勿伐，召伯所茇。
蔽芾甘棠，勿翦勿败，召伯所憩。
蔽芾甘棠，勿翦勿拜，召伯所说。','',''),('shijing-017','行露','','shijing','','国风 · 召南','厌浥行露，岂不夙夜，谓行多露。
谁谓雀无角？何以穿我屋？谁谓女无家？何以速我狱？虽速我狱，室家不足！
谁谓鼠无牙？何以穿我墉？谁谓女无家？何以速我讼？虽速我讼，亦不女从！','',''),('shijing-018','羔羊','','shijing','','国风 · 召南','羔羊之皮，素丝五紽。退食自公，委蛇委蛇。
羔羊之革，素丝五緎。委蛇委蛇，自公退食。
羔羊之缝，素丝五总。委蛇委蛇，退食自公。','',''),('shijing-019','殷其雷','','shijing','','国风 · 召南','殷其雷，在南山之阳。何斯违斯，莫敢或遑？振振君子，归哉归哉！
殷其雷，在南山之侧。何斯违斯，莫敢遑息？振振君子，归哉归哉！
殷其雷，在南山之下。何斯违斯，莫或遑处？振振君子，归哉归哉！','',''),('shijing-020','摽有梅','','shijing','','国风 · 召南','摽有梅，其实七兮。求我庶士，迨其吉兮。
摽有梅，其实三兮。求我庶士，迨其今兮。
摽有梅，顷筐塈之。求我庶士，迨其谓之。','',''),('shijing-021','小星','','shijing','','国风 · 召南','嘒彼小星，三五在东。肃肃宵征，夙夜在公。寔命不同！
嘒彼小星，维参与昴。肃肃宵征，抱衾与裯。寔命不犹！','',''),('shijing-022','江有汜','','shijing','','国风 · 召南','江有汜，之子归，不我以。不我以，其后也悔。
江有渚，之子归，不我与。不我与，其后也处。
江有沱，之子归，不我过。不我过，其啸也歌。','',''),('shijing-023','野有死麕','','shijing','','国风 · 召南','野有死麕，白茅包之。有女怀春，吉士诱之。
林有朴樕，野有死鹿。白茅纯束，有女如玉。
舒而脱脱兮，无感我帨兮，无使尨也吠。','',''),('shijing-024','何彼襛矣','','shijing','','国风 · 召南','何彼襛矣，唐棣之华？曷不肃雍？王姬之车。
何彼襛矣，华如桃李？平王之孙，齐侯之子。
其钓维何？维丝伊缗。齐侯之子，平王之孙。','',''),('shijing-025','驺虞','','shijing','','国风 · 召南','彼茁者葭，壹发五豝，于嗟乎驺虞！
彼茁者蓬，壹发五豵，于嗟乎驺虞！','',''),('shijing-026','柏舟','','shijing','','国风 · 邶风','泛彼柏舟，亦泛其流。耿耿不寐，如有隐忧。微我无酒，以敖以游。
我心匪鉴，不可以茹。亦有兄弟，不可以据。薄言往诉，逢彼之怒。
我心匪石，不可转也。我心匪席，不可卷也。威仪棣棣，不可选也。
忧心悄悄，愠于群小。觏闵既多，受侮不少。静言思之，寤辟有摽。
日居月诸，胡迭而微？心之忧矣，如匪浣衣。静言思之，不能奋飞。','',''),('shijing-027','绿衣','','shijing','','国风 · 邶风','绿兮衣兮，绿衣黄裹。心之忧矣，曷维其已！
绿兮衣兮，绿衣黄裳。心之忧矣，曷维其亡！
绿兮丝兮，女所治兮。我思古人，俾无訧兮！
絺兮绤兮，凄其以风。我思古人，实获我心！','',''),('shijing-028','燕燕','','shijing','','国风 · 邶风','燕燕于飞，差池其羽。之子于归，远送于野。瞻望弗及，泣涕如雨。
燕燕于飞，颉之颃之。之子于归，远于将之。瞻望弗及，伫立以泣。
燕燕于飞，下上其音。之子于归，远送于南。瞻望弗及，实劳我心。
仲氏任只，其心塞渊。终温且惠，淑慎其身。先君之思，以勖寡人。','',''),('shijing-029','日月','','shijing','','国风 · 邶风','日居月诸，照临下土。乃如之人兮，逝不古处？胡能有定？宁不我顾。
日居月诸，下土是冒。乃如之人兮，逝不相好。胡能有定？宁不我报。
日居月诸，出自东方。乃如之人兮，德音无良。胡能有定？俾也可忘。
日居月诸，东方自出。父兮母兮，畜我不卒。胡能有定？报我不述。','',''),('shijing-030','终风','','shijing','','国风 · 邶风','终风且暴，顾我则笑，谑浪笑敖，中心是悼。
终风且霾，惠然肯来，莫往莫来，悠悠我思。
终风且曀，不日有曀，寤言不寐，愿言则嚏。
曀曀其阴，虺虺其雷，寤言不寐，愿言则怀。','',''),('shijing-031','击鼓','','shijing','','国风 · 邶风','击鼓其镗，踊跃用兵。土国城漕，我独南行。
从孙子仲，平陈与宋。不我以归，忧心有忡。
爰居爰处？爰丧其马？于以求之？于林之下。
死生契阔，与子成说。执子之手，与子偕老。
于嗟阔兮，不我活兮。于嗟洵兮，不我信兮。','',''),('shijing-032','凯风','','shijing','','国风 · 邶风','凯风自南，吹彼棘心。棘心夭夭，母氏劬劳。
凯风自南，吹彼棘薪。母氏圣善，我无令人。
爰有寒痊？在浚之下。有子七人，母氏劳苦。
睍睆黄鸟，载好其音。有子七人，莫慰母心。','',''),('shijing-033','雄雉','','shijing','','国风 · 邶风','雄雉于飞，泄泄其羽。我之怀矣，自诒伊阻。
雄雉于飞，下上其音。展矣君子，实劳我心。
瞻彼日月，悠悠我思。道之云远，曷云能来？
百尔君子，不知德行。不忮不求，何用不臧。','',''),('shijing-034','匏有苦叶','','shijing','','国风 · 邶风','匏有苦叶，济有深涉。深则厉，浅则揭。
有弥济盈，有鷕雉鸣。济盈不濡轨，雉鸣求其牡。
雍雍鸣雁，旭日始旦。士如归妻，迨冰未泮。
招招舟子，人涉昂否。不涉昂否，昂须我友。','',''),('shijing-035','谷风','','shijing','','国风 · 邶风','习习谷风，以阴以雨。黾勉同心，不宜有怒。采葑采菲，无以下体？德音莫违，及尔同死。
行道迟迟，中心有违。不远伊迩，薄送我畿。谁谓荼苦，其甘如荠。宴尔新婚，如兄如弟。
泾以渭浊，湜湜其沚。宴尔新婚，不我屑以。毋逝我梁，毋发我笱。我躬不阅，遑恤我后。
就其深矣，方之舟之。就其浅矣，泳之游之。何有何亡，黾勉求之。凡民有丧，匍匐救之。
不我能畜，反以我为仇。既阻我德，贾用不售。昔育恐育鞫，及尔颠覆。既生既育，比予于毒。
我有旨蓄，亦以御冬。宴尔新婚，以我御穷。有洸有溃，既诒我肄。不念昔者，伊余来塈。','',''),('shijing-036','式微','','shijing','','国风 · 邶风','式微，式微，胡不归？微君之故，胡为乎中露！
式微，式微，胡不归？微君之躬，胡为乎泥中！','',''),('shijing-037','旄丘','','shijing','','国风 · 邶风','旄丘之葛兮，何诞之节兮。叔兮伯兮，何多日也？
何其处也？必有与也！何其久也？必有以也！
狐裘蒙戎，匪车不东。叔兮伯兮，靡所与同。
琐兮尾兮，流离之子。叔兮伯兮，袖如充耳。','',''),('shijing-038','简兮','','shijing','','国风 · 邶风','简兮简兮，方将万舞。日之方中，在前上处。
硕人俣俣，公庭万舞。有力如虎，执辔如组。
左手执龠，右手秉翟。赫如渥赭，公言锡爵。
山有榛，隰有苓。云谁之思？西方美人。彼美人兮，西方之人兮。','',''),('shijing-039','泉水','','shijing','','国风 · 邶风','毖彼泉水，亦流于淇。有怀于卫，靡日不思。娈彼诸姬，聊与之谋。
出宿于泲，饮饯于祢。女子有行，远父母兄弟，问我诸姑，遂及伯姊。
出宿于干，饮饯于言。载脂载辖，还车言迈。遄臻于卫，不瑕有害？
我思肥泉，兹之永叹。思须与漕，我心悠悠。驾言出游，以写我忧。','',''),('shijing-040','北门','','shijing','','国风 · 邶风','出自北门，忧心殷殷。终窭且贫，莫知我艰。已焉哉！天实为之，谓之何哉！
王事适我，政事一埤益我。我入自外，室人交遍谪我。已焉哉！天实为之，谓之何哉！
王事敦我，政事一埤遗我。我入自外，室人交遍摧我。已焉哉！天实为之，谓之何哉！','',''),('shijing-041','北风','','shijing','','国风 · 邶风','北风其凉，雨雪其雱。惠而好我，携手同行。其虚其邪？既亟只且！
北风其喈，雨雪其霏。惠而好我，携手同归。其虚其邪？既亟只且！
莫赤匪狐，莫黑匪乌。惠而好我，携手同车。其虚其邪？既亟只且！','',''),('shijing-042','静女','','shijing','','国风 · 邶风','静女其姝，俟我于城隅。爱而不见，搔首踟蹰。
静女其娈，贻我彤管。彤管有炜，说怿女美。
自牧归荑，洵美且异。匪女之为美，美人之贻。','',''),('shijing-043','新台','','shijing','','国风 · 邶风','新台有泚，河水弥弥。燕婉之求，蘧篨不鲜。
新台有洒，河水浼浼。燕婉之求，蘧篨不殄。
鱼网之设，鸿则离之。燕婉之求，得此戚施。','',''),('shijing-044','二子乘舟','','shijing','','国风 · 邶风','二子乘舟，泛泛其景。愿言思子，中心养养！
二子乘舟，泛泛其逝。愿言思子，不瑕有害？','',''),('shijing-045','柏舟','','shijing','','国风 · 鄘风','泛彼柏舟，在彼中河。髧彼两髦，实维我仪。之死矢靡它。母也天只，不谅人只！
泛彼柏舟，在彼河侧。髧彼两髦，实维我特。之死矢靡慝。母也天只，不谅人只！','',''),('shijing-046','墙有茨','','shijing','','国风 · 鄘风','墙有茨，不可扫也。中冓之言，不可道也。所可道也，言之丑也。
墙有茨，不可襄也。中冓之言，不可详也。所可详也，言之长也。
墙有茨，不可束也。中冓之言，不可读也。所可读也，言之辱也。','',''),('shijing-047','君子偕老','','shijing','','国风 · 鄘风','君子偕老，副笄六珈。委委佗佗，如山如河，象服是宜。子之不淑，云如之何？
玼兮玼兮，其之翟也。鬒发如云，不屑髢也。玉之瑱也，象之揥也，扬且之晰也。胡然而天也！胡然而帝也。
瑳兮瑳兮，其之展也。蒙彼绉絺，是绁袢也。子之清扬，扬且之颜也。展如之人兮，邦之媛也！','',''),('shijing-048','桑中','','shijing','','国风 · 鄘风','爰采唐矣？沬之乡矣。云谁之思？美孟姜矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。
爰采麦矣？沬之北矣。云谁之思？美孟弋矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。
爰采葑矣？沬之东矣。云谁之思？美孟庸矣。期我乎桑中，要我乎上宫，送我乎淇之上矣。','',''),('shijing-049','鹑之奔奔','','shijing','','国风 · 鄘风','鹑之奔奔，鹊之彊彊。人之无良，我以为兄！
鹊之彊彊，鹑之奔奔。人之无良，我以为君！','',''),('shijing-050','定之方中','','shijing','','国风 · 鄘风','定之方中，作于楚宫。揆之以日，作于楚室。树之榛栗，椅桐梓漆，爰伐琴桑。
升彼虚矣，以望楚矣。望楚与堂，景山与京。降观于桑，卜云其吉，终然允臧。
灵雨既零，命彼倌人，星言夙驾，说于桑田。匪直也人，秉心塞渊，騋牝三千。','',''),('shijing-051','蝃蝀','','shijing','','国风 · 鄘风','蝃蝀在东，莫之敢指。女子有行，远父母兄弟。
朝隮于西，崇朝其雨。女子有行，远兄弟父母。
乃如之人也，怀婚姻也。大无信也，不知命也！','',''),('shijing-052','相鼠','','shijing','','国风 · 鄘风','相鼠有皮，人而无仪！人而无仪，不死何为？
相鼠有齿，人而无止！人而无止，不死何俟？
相鼠有体，人而无礼，人而无礼！胡不遄死？','',''),('shijing-053','干旄','','shijing','','国风 · 鄘风','孑孑干旄，在浚之郊。素丝纰之，良马四之。彼姝者子，何以畀之？
孑孑干旟，在浚之都。素丝组之，良马五之。彼姝者子，何以予之？
孑孑干旌，在浚之城。素丝祝之，良马六之。彼姝者子，何以告之？','',''),('shijing-054','载驰','','shijing','','国风 · 鄘风','载驰载驱，归唁卫侯。驱马悠悠，言至于漕。大夫跋涉，我心则忧。
既不我嘉，不能旋反。视尔不臧，我思不远。
既不我嘉，不能旋济？视尔不臧，我思不閟。
陟彼阿丘，言采其蝱。女子善怀，亦各有行。许人尤之，众稚且狂。
我行其野，芃芃其麦。控于大邦，谁因谁极？大夫君子，无我有尤。百尔所思，不如我所之。','',''),('shijing-055','淇奥','','shijing','','国风 · 卫风','瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨，瑟兮僴兮，赫兮咺兮。有匪君子，终不可谖兮。
瞻彼淇奥，绿竹青青。有匪君子，充耳秀莹，会弁如星。瑟兮僴兮。赫兮咺兮，有匪君子，终不可谖兮。
瞻彼淇奥，绿竹如箦。有匪君子，如金如锡，如圭如璧。宽兮绰兮，猗重较兮。善戏谑兮，不为虐兮。','',''),('shijing-056','考盘','','shijing','','国风 · 卫风','考盘在涧，硕人之宽。独寐寤言，永矢弗谖。
考盘在阿，硕人之薖。独寐寤歌，永矢弗过。
考盘在六，硕人之轴。独寐寤宿，永矢弗告。','',''),('shijing-057','硕人','','shijing','','国风 · 卫风','硕人其颀，衣锦褧衣。齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私。
手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。
硕人敖敖，说于农郊。四牡有骄，朱幩镳镳。翟茀以朝。大夫夙退，无使君劳。
河水洋洋，北流活活。施罛濊濊，鳣鲔发发。葭菼揭揭，庶姜孽孽，庶士有朅。','',''),('shijing-058','氓','','shijing','','国风 · 卫风','氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。
乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。
桑之未落，其叶沃若。于嗟鸠兮！无食桑葚。于嗟女兮！无与士耽。士之耽兮，犹可说也。女之耽兮，不可说也。
桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士二其行。士也罔极，二三其德。
三岁为妇，靡室劳矣。夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。
及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏，信誓旦旦，不思其反。反是不思，亦已焉哉！','',''),('shijing-059','竹竿','','shijing','','国风 · 卫风','籊籊竹竿，以钓于淇。岂不尔思？远莫致之。
泉源在左，淇水在右。女子有行，远兄弟父母。
淇水在右，泉源在左。巧笑之瑳，佩玉之傩。
淇水滺滺，桧楫松舟。驾言出游，以写我忧。','',''),('shijing-060','芄兰','','shijing','','国风 · 卫风','芄兰之支，童子佩觿。虽则佩觿，能不我知。容兮遂兮，垂带悸兮。
芄兰之叶，童子佩韘。虽则佩韘，能不我甲。容兮遂兮，垂带悸兮。','',''),('shijing-061','河广','','shijing','','国风 · 卫风','谁谓河广？一苇杭之。谁谓宋远？跂予望之。
谁谓河广？曾不容刀。谁谓宋远？曾不崇朝。','',''),('shijing-062','伯兮','','shijing','','国风 · 卫风','伯兮朅兮，邦之桀兮。伯也执殳，为王前驱。
自伯之东，首如飞蓬。岂无膏沐？谁适为容！
其雨其雨，杲杲出日。愿言思伯，甘心首疾。
焉得谖草？言树之背。愿言思伯。使我心痗。','',''),('shijing-063','有狐','','shijing','','国风 · 卫风','有狐绥绥，在彼淇梁。心之忧矣，之子无裳。
有狐绥绥，在彼淇厉。心之忧矣，之子无带。
有狐绥绥，在彼淇侧。心之忧矣，之子无服。','',''),('shijing-064','木瓜','','shijing','','国风 · 卫风','投我以木瓜，报之以琼琚。匪报也，永以为好也！
投我以木桃，报之以琼瑶。匪报也，永以为好也！
投我以木李，报之以琼九。匪报也，永以为好也！','',''),('shijing-065','黍离','','shijing','','国风 · 王风','彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？
彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？
彼黍离离，彼稷之实。行迈靡靡，中心如噎。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？','',''),('shijing-066','君子于役','','shijing','','国风 · 王风','君子于役，不知其期。曷至哉？鸡栖于埘。日之夕矣，羊牛下来。君子于役，如之何勿思！
君子于役，不日不月。曷其有佸？鸡栖于桀。日之夕矣，羊牛下括。君子于役，苟无饥渴？','',''),('shijing-067','君子阳阳','','shijing','','国风 · 王风','君子阳阳，左执簧，右招我由房，其乐只且！
君子陶陶，左执翿，右招我由敖，其乐只且！','',''),('shijing-068','扬之水','','shijing','','国风 · 王风','扬之水，不流束薪。彼其之子，不与我戍申。怀哉怀哉，曷月予还归哉？
扬之水，不流束楚。彼其之子，不与我戍甫。怀哉怀哉，曷月予还归哉？
扬之水，不流束蒲。彼其之子，不与我戍许。怀哉怀哉，曷月予还归哉？','',''),('shijing-069','中谷有蓷','','shijing','','国风 · 王风','中谷有蓷，暵其干矣。有女仳离，慨其叹矣。慨其叹矣，遇人之艰难矣。
中谷有蓷，暵其修矣。有女仳离，条其歗矣。条其歗矣，遇人之不淑矣。
中谷有蓷，暵其湿矣。有女仳离，啜其泣矣。啜其泣矣，何嗟及矣。','',''),('shijing-070','兔爰','','shijing','','国风 · 王风','有兔爰爰，雉离于罗。我生之初，尚无为；我生之后，逢此百罹。尚寐无吪。
有兔爰爰，雉离于罘。我生之初，尚无造；我生之后，逢此百忧。尚寐无觉。
有兔爰爰，雉离于罿。我生之初，尚无庸；我生之后，逢此百凶。尚寐无聪。','',''),('shijing-071','葛藟','','shijing','','国风 · 王风','绵绵葛藟，在河之浒。终远兄弟，谓他人父。谓他人父，亦莫我顾！
绵绵葛爰，在河之藟。终远兄弟，谓他人母。谓他人母，亦莫我有！
绵绵葛藟，在河之漘。终远兄弟，谓他人昆。谓他人昆，亦莫我闻！','',''),('shijing-072','采葛','','shijing','','国风 · 王风','彼采葛兮，一日不见，如三月兮！
彼采萧兮，一日不见，如三秋兮！
彼采艾兮！一日不见，如三岁兮！','',''),('shijing-073','大车','','shijing','','国风 · 王风','大车槛槛，毳衣如菼。岂不尔思？畏子不敢。
大车啍啍，毳衣如璊，岂不尔思？畏子不奔。
谷则异室，死则同穴。谓予不信，有如皎日。','',''),('shijing-074','丘中有麻','','shijing','','国风 · 王风','丘中有麻，彼留子嗟。彼留子嗟，将其来施施。
丘中有麦，彼留子国。彼留子国，将其来食。
丘中有李，彼留之子。彼留之子，贻我佩九。','',''),('shijing-075','缁衣','','shijing','','国风 · 郑风','缁衣之宜兮，敝予又改为兮。适子之馆兮。还予授子之粲兮。
缁衣之好兮，敝予又改造兮。适子之馆兮，还予授子之粲兮。
缁衣之席兮，敝予又改作兮。适子之馆兮，还予授子之粲兮。','',''),('shijing-076','将仲子','','shijing','','国风 · 郑风','将仲子兮，无逾我里，无折我树杞。岂敢爱之？畏我父母。仲可怀也，父母之言亦可畏也。
将仲子兮，无逾我墙，无折我树桑。岂敢爱之？畏我诸兄。仲可怀也，诸兄之言亦可畏也。
将仲子兮，无逾我园，无折我树檀。岂敢爱之？畏人之多言。仲可怀也，人之多言亦可畏也。','',''),('shijing-077','叔于田','','shijing','','国风 · 郑风','叔于田，巷无居人。岂无居人？不如叔也。洵美且仁。
叔于狩，巷无饮酒。岂无饮酒？不如叔也。洵美且好。
叔适野，巷无服马。岂无服马？不如叔也。洵美且武。','',''),('shijing-078','大叔于田','','shijing','','国风 · 郑风','叔于田，乘乘马。执辔如组，两骖如舞。叔在薮，火烈具举。襢裼暴虎，献于公所。将叔勿狃，戒其伤女。
叔于田，乘乘黄。两服上襄，两骖雁行。叔在薮，火烈具扬。叔善射忌，又良御忌。抑罄控忌，抑纵送忌。
叔于田，乘乘鸨。两服齐首，两骖如手。叔在薮，火烈具阜。叔马慢忌，叔发罕忌，抑释掤忌，抑鬯弓忌。','',''),('shijing-079','清人','','shijing','','国风 · 郑风','清人在彭，驷介旁旁。二矛重英，河上乎翱翔。
清人在消，驷介麃麃。二矛重乔，河上乎逍遥。
清人在轴，驷介陶陶。左旋右抽，中军作好。','',''),('shijing-080','羔裘','','shijing','','国风 · 郑风','羔裘如濡，洵直且侯。彼其之子，舍命不渝。
羔裘豹饰，孔武有力。彼其之子，邦之司直。
羔裘晏兮，三英粲兮。彼其之子，邦之彦兮。','',''),('shijing-081','遵大路','','shijing','','国风 · 郑风','遵大路兮，掺执子之祛兮。无我恶兮，不蓵故也！
遵大路兮，掺执子之手兮。无我魗兮，不蓵好也！','',''),('shijing-082','女曰鸡鸣','','shijing','','国风 · 郑风','女曰鸡鸣，士曰昧旦。子兴视夜，明星有烂。将翱将翔，弋凫与雁。
弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好。
知子之来之，杂佩以赠之。知子之顺之，杂佩以问之。知子之好之，杂佩以报之。','',''),('shijing-083','有女同车','','shijing','','国风 · 郑风','有女同车，颜如舜华。将翱将翔，佩玉琼琚。彼美孟姜，洵美且都。
有女同行，颜如舜英。将翱将翔，佩玉将将。彼美孟姜，德音不忘。','',''),('shijing-084','山有扶苏','','shijing','','国风 · 郑风','山有扶苏，隰有荷华。不见子都，乃见狂且。
山有乔松，隰有游龙，不见子充，乃见狡童。','',''),('shijing-085','萚兮','','shijing','','国风 · 郑风','萚兮萚兮，风其吹女。叔兮伯兮，倡予和女。
萚兮萚兮，风其漂女。叔兮伯兮，倡予要女。','',''),('shijing-086','狡童','','shijing','','国风 · 郑风','彼狡童兮，不与我言兮。维子之故，使我不能餐兮。
彼狡童兮，不与我食兮。维子之故，使我不能息兮。','',''),('shijing-087','褰裳','','shijing','','国风 · 郑风','子惠思我，褰裳涉溱。子不我思，岂无他人？狂童之狂也且！
子惠思我，褰裳涉洧。子不我思，岂无他士？狂童之狂也且！','',''),('shijing-088','丰','','shijing','','国风 · 郑风','子之丰兮，俟我乎巷兮，悔予不送兮。
子之昌兮，俟我乎堂兮，悔予不将兮。
衣锦褧衣，裳锦褧裳。叔兮伯兮，驾予与行。
裳锦褧裳，衣锦褧衣。叔兮伯兮，驾予与归。','',''),('shijing-089','东门之墠','','shijing','','国风 · 郑风','东门之墠，茹藘在阪。其室则迩，其人甚远。
东门之栗，有践家室。岂不尔思？子不我即！','',''),('shijing-090','风雨','','shijing','','国风 · 郑风','风雨凄凄，鸡鸣喈喈，既见君子。云胡不夷？
风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳？
风雨如晦，鸡鸣不已。既见君子，云胡不喜？','',''),('shijing-091','子衿','','shijing','','国风 · 郑风','青青子衿，悠悠我心。纵我不往，子宁不嗣音？
青青子佩，悠悠我思。纵我不往，子宁不来？
挑兮达兮，在城阙兮。一日不见，如三月兮。','',''),('shijing-092','扬之水','','shijing','','国风 · 郑风','扬之水，不流束楚。终鲜兄弟，维予与女。无信人之言，人实诳女。
扬之水，不流束薪。终鲜兄弟，维予二人。无信人之言，人实不信。','',''),('shijing-093','出其东门','','shijing','','国风 · 郑风','出其东门，有女如云。虽则如云。匪我思存。缟衣綦巾，聊乐我员。
出其闉阇，有女如荼。虽则如荼，匪我思且。缟衣茹藘，聊可与娱。','',''),('shijing-094','野有蔓草','','shijing','','国风 · 郑风','野有蔓草，零露漙兮。有美一人，清扬婉兮。邂逅相遇，适我愿兮。
野有蔓草，零露瀼瀼。有美一人，婉如清扬。邂逅相遇，与子偕臧。','',''),('shijing-095','溱洧','','shijing','','国风 · 郑风','溱与洧，方涣涣兮。士与女，方秉蕳兮。女曰观乎？士曰既且。且往观乎？
洧之外，洵訏且乐。维士与女，伊其相谑，赠之以勺药。
溱与洧，浏其清矣。士与女，殷其盈矣。女曰观乎？士曰既且。且往观乎？
洧之外，洵訏且乐。维士与女，伊其将谑，赠之以勺药。','',''),('shijing-096','鸡鸣','','shijing','','国风 · 齐风','鸡既鸣矣，朝既盈矣。匪鸡则鸣，苍蝇之声。
东方明矣，朝既昌矣。匪东方则明，月出之光。
虫飞薨薨，甘与子同梦。会且归矣，无庶予子憎。','',''),('shijing-097','还','','shijing','','国风 · 齐风','子之还兮，遭我乎狃之间兮。并驱从两肩兮，揖我谓我儇兮。
子之茂兮，遭我乎狃之道兮。并驱从两牡兮，揖我谓我好兮。
子之昌兮，遭我乎狃之阳兮。并驱从两狼兮，揖我谓我臧兮。','',''),('shijing-098','着','','shijing','','国风 · 齐风','俟我于着乎而，充耳以素乎而，尚之以琼华乎而。
俟我于庭乎而，充耳以青乎而，尚之以琼莹乎而。
俟我于堂乎而，充耳以黄乎而，尚之以琼英乎而。','',''),('shijing-099','东方之日','','shijing','','国风 · 齐风','东方之日兮，彼姝者子，在我室兮。在我室兮，履我即兮。
东方之月兮，彼姝者子，在我闼兮。在我闼兮，履我发兮。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('shijing-100','东方未明','','shijing','','国风 · 齐风','东方未明，颠倒衣裳。颠之倒之，自公召之。
东方未曦，颠倒裳衣。倒之颠之，自公令之。
折柳樊圃，狂夫瞿瞿。不能辰夜，不夙则莫。','',''),('shijing-101','南山','','shijing','','国风 · 齐风','南山崔崔，雄狐绥绥。鲁道有荡，齐子由归。既曰归止，曷又怀止？
葛屦五两，冠緌双止。鲁道有荡，齐子庸止。既曰庸止，曷又从止？
蓺麻如之何？衡从其亩。取妻如之何？必告父母。既曰告止，曷又鞠止？
析薪如之何？匪斧不克。取妻如之何？匪媒不得。既曰得止，曷又极止？','',''),('shijing-102','甫田','','shijing','','国风 · 齐风','无田甫田，维莠骄骄。无思远人，劳心忉忉。
无田甫田，维莠桀桀。无思远人，劳心怛怛。
婉兮娈兮。总角丱兮。未几见兮，突而弁兮！','',''),('shijing-103','卢令','','shijing','','国风 · 齐风','卢令令，其人美且仁。
卢重环，其人美且鬈。
卢重鋂，其人美且偲。','',''),('shijing-104','敝笱','','shijing','','国风 · 齐风','敝笱在梁，其鱼鲂鳏。齐子归止，其从如云。
敝笱在梁，其鱼鲂鱮。齐子归止，其从如雨。
敝笱在梁，其鱼唯唯。齐子归止，其从如水。','',''),('shijing-105','载驱','','shijing','','国风 · 齐风','载驱薄薄，簟茀朱鞹。鲁道有荡，齐子发夕。
四骊济济，垂辔沵沵。鲁道有荡，齐子岂弟。
汶水汤汤，行人彭彭。鲁道有荡，齐子翱翔。
汶水滔滔，行人儦儦。鲁道有荡，齐了游敖。','',''),('shijing-106','猗嗟','','shijing','','国风 · 齐风','猗嗟昌兮，颀而长兮。抑若扬兮，美目扬兮。巧趋跄兮，射则臧兮。
猗嗟名兮，美目清兮。仪既成兮，终日射侯，不出正兮，展我甥兮。
猗嗟娈兮，清扬婉兮。舞则选兮，射则贯兮，四矢反兮，以御乱兮。','',''),('shijing-107','葛屦','','shijing','','国风 · 魏风','纠纠葛屦，可以履霜？掺掺女手，可以缝裳？要之襋之，好人服之。
好人提提，宛然左辟，佩其象揥。维是褊心，是以为刺。','',''),('shijing-108','汾沮洳','','shijing','','国风 · 魏风','彼汾沮洳，言采其莫。彼其之子，美无度。美无度，殊异乎公路。
彼汾一方，言采其桑。彼其之子，美如英。美如英，殊异乎公行。
彼汾一曲，言采其藚。彼其之子，美如玉。美如玉，殊异乎公族。','',''),('shijing-109','园有桃','','shijing','','国风 · 魏风','园有桃，其实之肴。心之忧矣，我歌且谣。不知我者，谓我士也骄。
彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！
园有棘，其实之食。心之忧矣，聊以行国。不知我者，谓我士也罔极。
彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！','',''),('shijing-110','陟岵','','shijing','','国风 · 魏风','陟彼岵兮，瞻望父兮。父曰：嗟！予子行役，夙夜无已。上慎旃哉，犹来！无止！
陟彼屺兮，瞻望母兮。母曰：嗟！予季行役，夙夜无寐。上慎旃哉，犹来！无弃！
陟彼冈兮，瞻望兄兮。兄曰：嗟！予弟行役，夙夜必偕。上慎旃哉，犹来！无死！','',''),('shijing-111','十亩之间','','shijing','','国风 · 魏风','十亩之间兮，桑者闲闲兮，行与子还兮。
十亩之外兮，桑者泄泄兮，行与子逝兮。','',''),('shijing-112','伐檀','','shijing','','国风 · 魏风','坎坎伐檀兮，置之河之干兮。河水清且涟猗。不稼不穑，胡取禾三百廛兮？
不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！
坎坎伐辐兮，置之河之侧兮。河水清且直猗。不稼不穑，胡取禾三百亿兮？
不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！
坎坎伐轮兮，置之河之漘兮。河水清且沦猗。不稼不穑，胡取禾三百囷兮？
不狩不猎，胡瞻尔庭有县鹑兮？彼君子兮，不素飧兮！','',''),('shijing-113','硕鼠','','shijing','','国风 · 魏风','硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。
硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。
硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？','',''),('shijing-114','蟋蟀','','shijing','','国风 · 唐风','蟋蟀在堂，岁聿其莫。今我不乐，日月其除。无已大康，职思其居。好乐无荒，良士瞿瞿。
蟋蟀在堂，岁聿其逝。今我不乐，日月其迈。无已大康，职思其外。好乐无荒，良士蹶蹶。
蟋蟀在堂，役车其休。今我不乐，日月其慆。无以大康。职思其忧。好乐无荒，良士休休。','',''),('shijing-115','山有枢','','shijing','','国风 · 唐风','山有枢，隰有榆。子有衣裳，弗曳弗娄。子有车马，弗驰弗驱。宛其死矣，他人是愉。
山有栲，隰有杻。子有廷内，弗洒弗扫。子有钟鼓，弗鼓弗考。宛其死矣，他人是保。
山有漆，隰有栗。子有酒食，何不日鼓瑟？且以喜乐，且以永日。宛其死矣，他人入室。','',''),('shijing-116','扬之水','','shijing','','国风 · 唐风','扬之水，白石凿凿。素衣朱襮，从子于沃。既见君子，云何不乐？
扬之水，白石皓皓。素衣朱绣，从子于鹄。既见君子，云何其忧？
扬之水，白石粼粼。我闻有命，不敢以告人。','',''),('shijing-117','椒聊','','shijing','','国风 · 唐风','椒聊之实，蕃衍盈升。彼其之子，硕大无朋。椒聊且，远条且。
椒聊之实，蕃衍盈匊。彼其之子，硕大且笃。椒聊且，远条且。','',''),('shijing-118','绸缪','','shijing','','国风 · 唐风','绸缪束薪，三星在天。今夕何夕，见此良人？子兮子兮，如此良人何？
绸缪束刍，三星在隅。今夕何夕，见此邂逅？子兮子兮，如此邂逅何？
绸缪束楚，三星在户。今夕何夕，见此粲者？子兮子兮，如此粲者何？','',''),('shijing-119','杕杜','','shijing','','国风 · 唐风','有杕之杜，其叶湑湑。独行踽踽。岂无他人？不如我同父。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？
有杕之杜，其叶箐箐。独行睘睘。岂无他人？不如我同姓。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？','',''),('shijing-120','羔裘','','shijing','','国风 · 唐风','羔裘豹祛，自我人居居。岂无他人？维子之故。
羔裘豹袖，自我人究究。岂无他人？维子之好。','',''),('shijing-121','鸨羽','','shijing','','国风 · 唐风','肃肃鸨羽，集于苞栩。王事靡盬，不能蓺稷黍。父母何怙？悠悠苍天，曷其有所？
肃肃鸨翼，集于苞棘。王事靡盬，不能蓺黍稷。父母何食？悠悠苍天，曷其有极？
肃肃鸨行，集于苞桑，王事靡盬，不能蓺稻梁。父母何尝？悠悠苍天，曷其有常？','',''),('shijing-122','无衣','','shijing','','国风 · 唐风','岂曰无衣七兮？不如子之衣，安且吉兮！
岂曰无衣六兮？不如子之衣，安且燠兮！','',''),('shijing-123','有杕之杜','','shijing','','国风 · 唐风','有杕之杜，生于道左。彼君子兮，噬肯适我？中心好之，曷饮食之？
有杕之杜，生于道周。彼君子兮，噬肯来游？中心好之，曷饮食之？','',''),('shijing-124','葛生','','shijing','','国风 · 唐风','葛生蒙楚，蔹蔓于野。予美亡此，谁与？独处？
葛生蒙棘，蔹蔓于域。予美亡此，谁与？独息？
角枕粲兮，锦衾烂兮。予美亡此，谁与？独旦？
夏之日，冬之夜。百岁之后，归于其居。
冬之夜，夏之日。百岁之后，归于其室。','',''),('shijing-125','采苓','','shijing','','国风 · 唐风','采苓采苓，首阳之巅。人之为言，苟亦无信。舍旃舍旃，苟亦无然。人之为言，胡得焉？
采苦采苦，首阳之下。人之为言，苟亦无与。舍旃舍旃，苟亦无然。人之为言，胡得焉？
采葑采葑，首阳之东。人之为言，苟亦无从。舍旃舍旃，苟亦无然。人之为言，胡得焉？','',''),('shijing-126','车邻','','shijing','','国风 · 秦风','有车邻邻，有马白颠。未见君子，寺人之令。
阪有漆，隰有栗。既见君子，并坐鼓瑟。今者不乐，逝者其耋。
阪有桑，隰有杨。既见君子，并坐鼓簧。今者不乐，逝者其亡。','',''),('shijing-127','驷驖','','shijing','','国风 · 秦风','驷驖孔阜，六辔在手。公之媚子，从公于狩。
奉时辰牡，辰牡孔硕。公曰左之，舍拔则获。
游于北园，四马既闲。輶车鸾镳，载猃歇骄。','',''),('shijing-128','小戎','','shijing','','国风 · 秦风','小戎俴收，五楘梁辀。游环胁驱，阴靷鋈续。文茵畅毂，驾我骐馵。
言念君子，温其如玉。在其板屋，乱我心曲。
四牡孔阜，六辔在手。骐骝是中，騧骊是骖。龙盾之合，鋈以觼軜。
言念君子，温其在邑。方何为期？胡然我念之！
俴驷孔群，厹矛鋈錞。蒙伐有苑，虎韔镂膺。交韔二弓，竹闭绲縢。
言念君子，载寝载兴。厌厌良人，秩秩德音。','',''),('shijing-129','蒹葭','','shijing','','国风 · 秦风','蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。
蒹葭萋萋，白露未曦。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。
蒹葭采采，白露未已。所谓伊人，在水之涘。溯洄从之，道阻且右。溯游从之，宛在水中沚。','',''),('shijing-130','终南','','shijing','','国风 · 秦风','终南何有？有条有梅。君子至止，锦衣狐裘。颜如渥丹，其君也哉！
终南何有？有纪有堂。君子至止，黻衣绣裳。佩玉将将，寿考不忘！','',''),('shijing-131','黄鸟','','shijing','','国风 · 秦风','交交黄鸟，止于棘。谁从穆公？子车奄息。维此奄息，百夫之特。
临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！
交交黄鸟，止于桑。谁从穆公？子车仲行。维此仲行，百夫之防。
临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！
交交黄鸟，止于楚。谁从穆公？子车针虎。维此针虎，百夫之御。
临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！','',''),('shijing-132','晨风','','shijing','','国风 · 秦风','鴥彼晨风，郁彼北林。未见君子，忧心钦钦。如何如何，忘我实多！
山有苞栎，隰有六驳。未见君子，忧心靡乐。如何如何，忘我实多！
山有苞棣，隰有树檖。未见君子，忧心如醉。如何如何，忘我实多！','',''),('shijing-133','无衣','','shijing','','国风 · 秦风','岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！
岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！
岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！','',''),('shijing-134','渭阳','','shijing','','国风 · 秦风','我送舅氏，曰至渭阳。何以赠之？路车乘黄。
我送舅氏，悠悠我思。何以赠之？琼瑰玉佩。','',''),('shijing-135','权舆','','shijing','','国风 · 秦风','于我乎，夏屋渠渠，今也每食无余。于嗟乎，不承权舆！
于我乎，每食四簋，今也每食不饱。于嗟乎，不承权舆！','',''),('shijing-136','宛丘','','shijing','','国风 · 陈风','子之汤兮，宛丘之上兮。洵有情兮，而无望兮。
坎其击鼓，宛丘之下。无冬无夏，值其鹭羽。
坎其击缶，宛丘之道。无冬无夏，值其鹭翿。','',''),('shijing-137','东门之枌','','shijing','','国风 · 陈风','东门之枌，宛丘之栩。子仲之子，婆娑其下。
谷旦于差，南方之原。不绩其麻，市也婆娑。
谷旦于逝，越以鬷迈。视尔如荍，贻我握椒。','',''),('shijing-138','衡门','','shijing','','国风 · 陈风','衡门之下，可以栖迟。泌之洋洋，可以乐饥。
岂其食鱼，必河之鲂？岂其取妻，必齐之姜？
岂其食鱼，必河之鲤？岂其取妻，必宋之子？','',''),('shijing-139','东门之池','','shijing','','国风 · 陈风','东门之池，可以沤麻。彼美淑姬，可与晤歌。
东门之池，可以沤纻。彼美淑姬，可与晤语。
东门之池，可以沤菅。彼美淑姬，可与晤言。','',''),('shijing-140','东门之杨','','shijing','','国风 · 陈风','东门之杨，其叶牂牂。昏以为期，明星煌煌。
东门之杨，其叶肺肺。昏以为期，明星晰晰。','',''),('shijing-141','墓门','','shijing','','国风 · 陈风','墓门有棘，斧以斯之。夫也不良，国人知之。知而不已，谁昔然矣。
墓门有梅，有鸮萃止。夫也不良，歌以讯之。讯予不顾，颠倒思予。','',''),('shijing-142','防有鹊巢','','shijing','','国风 · 陈风','防有鹊巢，邛有旨苕。谁侜予美？心焉忉忉。
中唐有甓，邛有旨鷊。谁侜予美？心焉惕惕。','',''),('shijing-143','月出','','shijing','','国风 · 陈风','月出皎兮。佼人僚兮。舒窈纠兮。劳心悄兮。
月出皓兮。佼人懰兮。舒忧受兮。劳心慅兮。
月出照兮。佼人燎兮。舒夭绍兮。劳心惨兮。','',''),('shijing-144','株林','','shijing','','国风 · 陈风','胡为乎株林？从夏南！匪适株林，从夏南！
驾我乘马，说于株野。乘我乘驹，朝食于株！','',''),('shijing-145','泽陂','','shijing','','国风 · 陈风','彼泽之陂，有蒲与荷。有美一人，伤如之何？寤寐无为，涕泗滂沱。
彼泽之陂，有蒲与蕳。有美一人，硕大且卷。寤寐无为，中心悁悁。
彼泽之陂，有蒲菡萏。有美一人，硕大且俨。寤寐无为，辗转伏枕。','',''),('shijing-146','羔裘','','shijing','','国风 · 桧风','羔裘逍遥，狐裘以朝。岂不尔思？劳心忉忉。
羔裘翱翔，狐裘在堂。岂不尔思？我心忧伤。
羔裘如膏，日出有曜。岂不尔思？中心是悼。','',''),('shijing-147','素冠','','shijing','','国风 · 桧风','庶见素冠兮，棘人栾栾兮。劳心慱慱兮。
庶见素衣兮，我心伤悲兮。聊与子同归兮。
庶见素韠兮，我心蕴结兮。聊与子如一兮。','',''),('shijing-148','隰有苌楚','','shijing','','国风 · 桧风','隰有苌楚，猗傩其枝，夭之沃沃，乐子之无知。
隰有苌楚，猗傩其华，夭之沃沃。乐子之无家。
隰有苌楚，猗傩其实，夭之沃沃。乐子之无室。','',''),('shijing-149','匪风','','shijing','','国风 · 桧风','匪风发兮，匪车偈兮。顾瞻周道，中心怛兮。
匪风飘兮，匪车嘌兮。顾瞻周道，中心吊兮。
谁能亨鱼？溉之釜鬵。谁将西归？怀之好音。','',''),('shijing-150','蜉蝣','','shijing','','国风 · 曹风','蜉蝣之羽，衣裳楚楚。心之忧矣，于我归处。
蜉蝣之翼，采采衣服。心之忧矣，于我归息。
蜉蝣掘阅，麻衣如雪。心之忧矣，于我归说。','',''),('shijing-151','候人','','shijing','','国风 · 曹风','彼候人兮，何戈与祋。彼其之子，三百赤芾。
维鹈在梁，不濡其翼。彼其之子，不称其服。
维鹈在梁，不濡其咮。彼其之子，不遂其媾。
荟兮蔚兮，南山朝隮。婉兮娈兮，季女斯饥。','',''),('shijing-152','鳲鸠','','shijing','','国风 · 曹风','鳲鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮。
鳲鸠在桑，其子在梅。淑人君子，其带伊丝。其带伊丝，其弁伊骐。
鳲鸠在桑，其子在棘。淑人君子，其仪不忒。其仪不忒，正是四国。
鳲鸠在桑，其子在榛。淑人君子，正是国人，正是国人。胡不万年？','',''),('shijing-153','下泉','','shijing','','国风 · 曹风','冽彼下泉，浸彼苞稂。忾我寤叹，念彼周京。
冽彼下泉，浸彼苞萧。忾我寤叹，念彼京周。
冽彼下泉，浸彼苞蓍。忾我寤叹，念彼京师。
芃芃黍苗，阴雨膏之。四国有王，郇伯劳之。','',''),('shijing-154','七月','','shijing','','国风 · 豳风','七月流火，九月授衣。一之日觱发，二之日栗烈。无衣无褐，何以卒岁？
三之日于耜，四之日举趾。同我妇子，馌彼南亩。田畯至喜。
七月流火，九月授衣。春日载阳，有鸣仓庚。女执懿筐，遵彼微行，爰求柔桑。
春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归。
七月流火，八月萑苇。蚕月条桑，取彼斧斨。以伐远扬，猗彼女桑。
七月鸣鵙，八月载绩。载玄载黄，我朱孔阳，为公子裳。
四月秀葽，五月鸣蜩。八月其获，十月陨萚。一之日于貉，取彼狐狸，为公子裘。
二之日其同，载缵武功。言私其豵，献豜于公。
五月斯螽动股，六月莎鸡振羽。七月在野，八月在宇，九月在户，十月蟋蟀，入我床下。
穹窒熏鼠，塞向墐户。嗟我妇子，曰为改岁，入此室处。
六月食郁及薁，七月亨葵及菽。八月剥枣，十月获稻。为此春酒，以介眉寿。
七月食瓜，八月断壶，九月叔苴，采荼薪樗。食我农夫。
九月筑场圃，十月纳禾稼。黍稷重穋，禾麻菽麦。嗟我农夫，我稼既同，上入执宫功。
昼尔于茅，宵尔索綯，亟其乘屋，其始播百谷。
二之日凿冰冲冲，三之日纳于凌阴。四之日其蚤，献羔祭韭。九月肃霜，十月涤场。
朋酒斯飨，曰杀羔羊，跻彼公堂。称彼兕觥：万寿无疆！','',''),('shijing-155','鸱鸮','','shijing','','国风 · 豳风','鸱鸮鸱鸮，既取我子，无毁我室。恩斯勤斯，鬻子之闵斯。
迨天之未阴雨，彻彼桑土，绸缪牖户。今女下民，或敢侮予？
予手拮据，予所捋荼。予所蓄租，予口卒瘏，曰予未有室家。
予羽谯谯，予尾翛翛，予室翘翘。风雨所漂摇，予维音哓哓！','',''),('shijing-156','东山','','shijing','','国风 · 豳风','我徂东山，慆慆不归。我来自东，零雨其蒙。我东曰归，我心西悲。
制彼裳衣，勿士行枚。蜎蜎者蠋，烝在桑野。敦彼独宿，亦在车下。
我徂东山，慆慆不归。我来自东，零雨其蒙。果臝之实，亦施于宇。
伊威在室，蟏蛸在户。町畽鹿场，熠耀宵行。不可畏也，伊可怀也。
我徂东山，慆慆不归。我来自东，零雨其蒙。鹳鸣于垤，妇叹于室。
洒扫穹窒，我征聿至。有敦瓜苦，烝在栗薪。自我不见，于今三年。
我徂东山，慆慆不归。我来自东，零雨其蒙。仓庚于飞，熠耀其羽。
之子于归，皇驳其马。亲结其缡，九十其仪。其新孔嘉，其旧如之何？','',''),('shijing-157','破斧','','shijing','','国风 · 豳风','既破我斧，又缺我斨。周公东征，四国是皇。哀我人斯，亦孔之将。
既破我斧，又缺我锜。周公东征，四国是遒。哀我人斯，亦孔之嘉。
既破我斧，又缺我銶。周公东征，四国是遒。哀我人斯，亦孔之休。','',''),('shijing-158','伐柯','','shijing','','国风 · 豳风','伐柯如何？匪斧不克。取妻如何？匪媒不得。
伐柯伐柯，其则不远。我觏之子，笾豆有践。','',''),('shijing-159','九罭','','shijing','','国风 · 豳风','九罭之鱼，鳟鲂。我觏之子，衮衣绣裳。
鸿飞遵渚，公归无所，于女信处。鸿飞遵六，公归不复，于女信宿。
是以有衮衣兮，无以我公归兮，无使我心悲兮。','',''),('shijing-160','狼跋','','shijing','','国风 · 豳风','狼跋其胡，载疐其尾。公孙硕肤，赤舄几几。
狼疐其尾，载跋其胡。公孙硕肤，德音不瑕？','',''),('shijing-161','鹿鸣','','shijing','','小雅 · 鹿鸣之什','呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。吹笙鼓簧，承筐是将。人之好我，示我周行。
呦呦鹿鸣，食野之蒿。我有嘉宾，德音孔昭。视民不恌，君子是则是效。我有旨酒，嘉宾式燕以敖。
呦呦鹿鸣，食野之芩。我有嘉宾，鼓瑟鼓琴。鼓瑟鼓琴，和乐且湛。我有旨酒，以燕乐嘉宾之心。','',''),('shijing-162','四牡','','shijing','','小雅 · 鹿鸣之什','四牡騑騑，周道倭迟。岂不怀归？王事靡盬，我心伤悲。
四牡騑騑，啴啴骆马。岂不怀归？王事靡盬，不遑启处。
翩翩者鵻，载飞载下，集于苞栩。王事靡盬，不遑将父。
翩翩者鵻，载飞载止，集于苞杞。王事靡盬，不遑将母。
驾彼四骆，载骤骎骎。岂不怀归？是用作歌，将母来谂。','',''),('shijing-163','皇皇者华','','shijing','','小雅 · 鹿鸣之什','皇皇者华，于彼原隰。駪駪征夫，每怀靡及。
我马维驹，六辔如濡。载驰载驱，周爰咨诹。
我马维骐，六辔如丝。载驰载驱，周爰咨谋。
我马维骆，六辔沃若。载驰载驱，周爰咨度。
我马维骃，六辔既均。载驰载驱，周爰咨询。','',''),('shijing-164','棠棣','','shijing','','小雅 · 鹿鸣之什','棠棣之华，鄂不韡韡。凡今之人，莫如兄弟。
死丧之威，兄弟孔怀。原隰裒矣，兄弟求矣。
脊令在原，兄弟急难。每有良朋，况也永叹。
兄弟阋于墙，外御其务。每有良朋，烝也无戎。
丧乱既平，既安且宁。虽有兄弟，不如友生？
傧尔笾豆，饮酒之饫。兄弟既具，和乐且孺。
妻子好合，如鼓瑟琴。兄弟既翕，和乐且湛。
宜尔室家，乐尔妻帑。是究是图，亶其然乎？','',''),('shijing-165','伐木','','shijing','','小雅 · 鹿鸣之什','伐木丁丁，鸟鸣嘤嘤。出自幽谷，迁于乔木。嘤其鸣矣，求其友声。
相彼鸟矣，犹求友声。矧伊人矣，不求友生？神之听之，终和且平。
伐木许许，酾酒有藇！既有肥羜，以速诸父。宁适不来，微我弗顾。
于粲洒扫，陈馈八簋。既有肥牡，以速诸舅。宁适不来，微我有咎。
伐木于阪，酾酒有衍。笾豆有践，兄弟无远。民之失德，干糇以愆。
有酒湑我，无酒酤我。坎坎鼓我，蹲蹲舞我。迨我暇矣，饮此湑矣。','',''),('shijing-166','天保','','shijing','','小雅 · 鹿鸣之什','天保定尔，亦孔之固。俾尔单厚，何福不除？俾尔多益，以莫不庶。
天保定尔，俾尔戬谷。罄无不宜，受天百禄。降尔遐福，维日不足。
天保定尔，以莫不兴。如山如阜，如冈如陵，如川之方至，以莫不增。
吉蠲为饎，是用孝享。禴祠烝尝，于公先王。君曰：卜尔，万寿无疆。
神之吊矣，诒尔多福。民之质矣，日用饮食。群黎百姓，遍为尔德。
如月之恒，如日之升。如南山之寿，不骞不崩。如松柏之茂，无不尔或承。','',''),('shijing-167','采薇','','shijing','','小雅 · 鹿鸣之什','采薇采薇，薇亦作止。曰归曰归，岁亦莫止。靡室靡家，玁狁之故。不遑启居，玁狁之故。
采薇采薇，薇亦柔止。曰归曰归，心亦忧止。忧心烈烈，载饥载渴。我戍未定，靡使归聘。
采薇采薇，薇亦刚止。曰归曰归，岁亦阳止。王事靡盬，不遑启处。忧心孔疚，我行不来！
彼尔维何？维常之华。彼路斯何？君子之车。戎车既驾，四牡业业。岂敢定居？一月三捷。
驾彼四牡，四牡骙骙。君子所依，小人所腓。四牡翼翼，象弭鱼服。岂不日戒？玁狁孔棘！
昔我往矣，杨柳依依。今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！','',''),('shijing-168','出车','','shijing','','小雅 · 鹿鸣之什','我出我车，于彼牧矣。自天子所，谓我来矣。召彼仆夫，谓之载矣。王事多难，维其棘矣。
我出我车，于彼郊矣。设此旐矣，建彼旄矣。彼旟旐斯，胡不旆旆？忧心悄悄，仆夫况瘁。
王命南仲，往城于方。出车彭彭，旗旐央央。天子命我，城彼朔方。赫赫南仲，玁狁于襄。
昔我往矣，黍稷方华。今我来思，雨雪载途。王事多难，不遑启居。岂不怀归？畏此简书。
喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。既见君子，我心则降。赫赫南仲，薄伐西戎。
春日迟迟，卉木萋萋。仓庚喈喈，采蘩祁祁。执讯获丑，薄言还归。赫赫南仲，玁狁于夷。','',''),('shijing-169','杕杜','','shijing','','小雅 · 鹿鸣之什','有杕之杜，有睆其实。王事靡盬，继嗣我日。日月阳止，女心伤止，征夫遑止。
有杕之杜，其叶萋萋。王事靡盬，我心伤悲。卉木萋止，女心悲止，征夫归止！
陟彼北山，言采其杞。王事靡盬，忧我父母。檀车幝幝，四牡痯痯，征夫不远！
匪载匪来，忧心孔疚。斯逝不至，而多为恤。卜筮偕止，会言近止，征夫迩止！','',''),('shijing-170','鱼丽','','shijing','','小雅 · 鹿鸣之什','鱼丽于罶，鲿鲨。君子有酒，旨且多。
鱼丽于罶，鲂鳢。君子有酒，多且旨。
鱼丽于罶，鰋鲤。君子有酒，旨且有。物其多矣，
维其嘉矣！物其旨矣，维其偕矣！物其有矣，维其时矣！','',''),('shijing-171','南有嘉鱼','','shijing','','小雅 · 南有嘉鱼之什','南有嘉鱼，烝然罩罩。君子有酒，嘉宾式燕以乐。
南有嘉鱼，烝然汕汕。君子有酒，嘉宾式燕以衎。
南有樛木，甘瓠累之。君子有酒，嘉宾式燕绥之。
翩翩者鵻，烝然来思。君子有酒，嘉宾式燕又思。','',''),('shijing-172','南山有台','','shijing','','小雅 · 南有嘉鱼之什','南山有台，北山有莱。乐只君子，邦家之基。乐只君子，万寿无期。
南山有桑，北山有杨。乐只君子，邦家之光。乐只君子，万寿无疆。
南山有杞，北山有李。乐只君子，民之父母。乐只君子，德音不已。
南山有栲，北山有杻。乐只君子，遐不眉寿。乐只君子，德音是茂。
南山有枸，北山有楰。乐只君子，遐不黄耇。乐只君子，保艾尔后。','',''),('shijing-173','蓼萧','','shijing','','小雅 · 南有嘉鱼之什','蓼彼萧斯，零露湑兮。既见君子，我心写兮。燕笑语兮，是以有誉处兮。
蓼彼萧斯，零露瀼瀼。既见君子，为龙为光。其德不爽，寿考不忘。
蓼彼萧斯，零露泥泥。既见君子，孔燕岂弟。宜兄宜弟，令德寿岂。
蓼彼萧斯，零露浓浓。既见君子，鞗革忡忡。和鸾雍雍，万福攸同。','',''),('shijing-174','湛露','','shijing','','小雅 · 南有嘉鱼之什','湛湛露斯，匪阳不曦。厌厌夜饮，不醉无归。
湛湛露斯，在彼丰草。厌厌夜饮，在宗载考。
湛湛露斯，在彼杞棘。显允君子，莫不令德。
其桐其椅，其实离离。岂弟君子，莫不令仪。','',''),('shijing-175','彤弓','','shijing','','小雅 · 南有嘉鱼之什','彤弓弨兮，受言藏之。我有嘉宾，中心贶之。钟鼓既设，一朝飨之。
彤弓弨兮，受言载之。我有嘉宾，中心喜之。钟鼓既设，一朝右之。
彤弓弨兮，受言櫜之。我有嘉宾，中心好之。钟鼓既设，一朝酬之。','',''),('shijing-176','菁菁者莪','','shijing','','小雅 · 南有嘉鱼之什','菁菁者莪，在彼中阿。既见君子，乐且有仪。
菁菁者莪，在彼中沚。既见君子，我心则喜。
菁菁者莪，在彼中陵。既见君子，锡我百朋。
泛泛杨舟，载沉载浮。既见君子，我心则休。','',''),('shijing-177','六月','','shijing','','小雅 · 南有嘉鱼之什','六月栖栖，戎车既饬。四牡骙骙，载是常服。玁狁孔炽，我是用急。王于出征，以匡王国。
比物四骊，闲之维则。维此六月，既成我服。我服既成，于三十里。王于出征，以佐天子。
四牡修广，其大有颙。薄伐玁狁，以奏肤公。有严有翼，共武之服。共武之服，以定王国。
玁狁匪茹，整居焦获。侵镐及方，至于泾阳。织文鸟章，白旆央央。元戎十乘，以先启行。
戎车既安，如轾如轩。四牡既佶，既佶且闲。薄伐玁狁，至于大原。文武吉甫，万邦为宪。
吉甫燕喜，既多受祉。来归自镐，我行永久。饮御诸友，炮鳖脍鲤。侯谁在矣？张仲孝友。','',''),('shijing-178','采芑','','shijing','','小雅 · 南有嘉鱼之什','薄言采芑，于彼新田，呈此菑亩。方叔涖止，其车三千。师干之试，方叔率止。
乘其四骐，四骐翼翼。路车有奭，簟茀鱼服，钩膺鞗革。
薄言采芑，于彼新田，于此中乡。方叔涖止，其车三千。旗旐央央，方叔率止。
约軧错衡，八鸾玱玱。服其命服，朱芾斯皇，有玱葱珩。
鴥彼飞隼，其飞戾天，亦集爰止。方叔涖止，其车三千。师干之试，方叔率止。
钲人伐鼓，陈师鞠旅。显允方叔，伐鼓渊渊，振旅阗阗。
蠢尔蛮荆，大邦为仇。方叔元老，克壮其犹。方叔率止，执讯获丑。戎车啴啴，
啴啴焞焞，如霆如雷。显允方叔，征伐玁狁，蛮荆来威。','',''),('shijing-179','车攻','','shijing','','小雅 · 南有嘉鱼之什','我车既攻，我马既同。四牡庞庞，驾言徂东。
田车既好，田牡孔阜。东有甫草，驾言行狩。
之子于苗，选徒嚣嚣。建旐设旄，搏兽于敖。
驾彼四牡，四牡奕奕。赤芾金舄，会同有绎。
决拾既佽，弓矢既调。射夫既同，助我举柴。
四黄既驾，两骖不猗。不失其驰，舍矢如破。
萧萧马鸣，悠悠旆旌。徒御不惊，大庖不盈。
之子于征，有闻无声。允矣君子，展也大成。','',''),('shijing-180','吉日','','shijing','','小雅 · 南有嘉鱼之什','吉日维戊，既伯既祷。田车既好，四牡孔阜。升彼大阜，从其群丑。
吉日庚午，既差我马。兽之所同，麀鹿麌麌。漆沮之从，天子之所。
瞻彼中原，其祁孔有。儦儦俟俟，或群或友。悉率左右，以燕天子。
既张我弓，既挟我矢。发彼小豝，殪此大兕。以御宾客，且以酌醴。','',''),('shijing-181','鸿雁','','shijing','','小雅 · 鸿雁之什','鸿雁于飞，肃肃其羽。之子于征，劬劳于野。爰及矜人，哀此鳏寡。
鸿雁于飞，集于中泽。之子于垣，百堵皆作。虽则劬劳，其究安宅？
鸿雁于飞，哀鸣嗷嗷。维此哲人，谓我劬劳。维彼愚人，谓我宣骄。','',''),('shijing-182','庭燎','','shijing','','小雅 · 鸿雁之什','夜如何其？夜未央，庭燎之光。君子至止，鸾声将将。
夜如何其？夜未艾，庭燎晣晣。君子至止，鸾声哕哕。
夜如何其？夜乡晨，庭燎有辉。君子至止，言观其旗。','',''),('shijing-183','沔水','','shijing','','小雅 · 鸿雁之什','沔彼流水，朝宗于海。鴥彼飞隼，载飞载止。嗟我兄弟，邦人诸友。莫肯念乱，谁无父母？
沔彼流水，其流汤汤。鴥彼飞隼，载飞载扬。念彼不迹，载起载行。心之忧矣，不可弭忘。
鴥彼飞隼，率彼中陵。民之讹言，宁莫之惩？我友敬矣，谗言其兴。','',''),('shijing-184','鹤鸣','','shijing','','小雅 · 鸿雁之什','鹤鸣于九皋，声闻于野。鱼潜在渊，或在于渚。乐彼之园，爰有树檀，其下维萚。他山之石，可以为错。
鹤鸣于九皋，声闻于天。鱼在于渚，或潜在渊。乐彼之园，爰有树檀，其下维谷。他山之石，可以攻玉。','',''),('shijing-185','祈父','','shijing','','小雅 · 鸿雁之什','祈父，予王之爪牙。胡转予于恤，靡所止居？
祈父，予王之爪士。胡转予于恤，靡所厎止？
祈父，亶不聪。胡转予于恤？有母之尸饔。','',''),('shijing-186','白驹','','shijing','','小雅 · 鸿雁之什','皎皎白驹，食我场苗。絷之维之，以永今朝。所谓伊人，于焉逍遥？
皎皎白驹，食我场藿。絷之维之，以永今夕。所谓伊人，于焉嘉客？
皎皎白驹，贲然来思。尔公尔侯，逸豫无期？慎尔优游，勉尔遁思。
皎皎白驹，在彼空谷。生刍一束，其人如玉。毋金玉尔音，而有遐心。','',''),('shijing-187','黄鸟','','shijing','','小雅 · 鸿雁之什','黄鸟黄鸟，无集于谷，无啄我粟。此邦之人，不我肯谷。言旋言归，复我邦族。
黄鸟黄鸟，无集于桑，无啄我粱。此邦之人，不可与明。言旋言归，复我诸兄。
黄鸟黄鸟，无集于栩，无啄我黍。此邦之人，不可与处。言旋言归，复我诸父。','',''),('shijing-188','我行其野','','shijing','','小雅 · 鸿雁之什','我行其野，蔽芾其樗。婚姻之故，言就尔居。尔不我畜，复我邦家。
我行其野，言采其蓫。婚姻之故，言就尔宿。尔不我畜，言归斯复。
我行其野，言采其葍。不思旧姻，求尔新特。成不以富，亦祗以异。','',''),('shijing-189','斯干','','shijing','','小雅 · 鸿雁之什','秩秩斯干，幽幽南山。如竹苞矣，如松茂矣。兄及弟矣，式相好矣，无相犹矣。
似续妣祖，筑室百堵，西南其户。爰居爰处，爰笑爰语。
约之阁阁，椓之橐橐。风雨攸除，鸟鼠攸去，君子攸芋。
如跂斯翼，如矢斯棘，如鸟斯革，如翚斯飞，君子攸跻。
殖殖其庭，有觉其楹。哙哙其正，哕哕其冥。君子攸宁。
下莞上簟，乃安斯寝。乃寝乃兴，乃占我梦。吉梦维何？维熊维罴，维虺维蛇。
大人占之：维熊维罴，男子之祥；维虺维蛇，女子之祥。
乃生男子，载寝之床。载衣之裳，载弄之璋。其泣喤喤，朱芾斯皇，室家君王。
乃生女子，载寝之地。载衣之裼，载弄之瓦。无非无仪，唯酒食是议，无父母诒罹。','',''),('shijing-190','无羊','','shijing','','小雅 · 鸿雁之什','谁谓尔无羊？三百维群。谁谓尔无牛？九十其犉。尔羊来思，其角濈濈。尔牛来思，其耳湿湿。
或降于阿，或饮于池，或寝或讹。尔牧来思，何蓑何笠，或负其糇。三十维物，尔牲则具。
尔牧来思，以薪以蒸，以雌以雄。尔羊来思，矜矜兢兢，不骞不崩。麾之以肱，毕来既升。
牧人乃梦，众维鱼矣，旐维旟矣，大人占之；众维鱼矣，实维丰年；旐维旟矣，室家溱溱。','',''),('shijing-191','节南山','','shijing','','小雅 · 节南山之什','节彼南山，维石岩岩。赫赫师尹，民具尔瞻。忧心如惔，不敢戏谈。国既卒斩，何用不监！
节彼南山，有实其猗。赫赫师尹，不平谓何。天方荐瘥，丧乱弘多。民言无嘉，惨莫惩嗟。
尹氏大师，维周之氐；秉国之钧，四方是维。天子是毗，俾民不迷。不吊昊天，不宜空我师。
弗躬弗亲，庶民弗信。弗问弗仕，勿罔君子。式夷式已，无小人殆。琐琐姻亚，则无膴仕。
昊天不佣，降此鞠讻。昊天不惠，降此大戾。君子如届，俾民心阕。君子如夷，恶怒是违。
不吊昊天，乱靡有定。式月斯生，俾民不宁。忧心如酲，谁秉国成？不自为政，卒劳百姓。
驾彼四牡，四牡项领。我瞻四方，蹙蹙靡所骋。
方茂尔恶，相尔矛矣。既夷既怿，如相酬矣。
昊天不平，我王不宁。不惩其心，覆怨其正。
家父作诵，以究王讻。式讹尔心，以畜万邦。','',''),('shijing-192','正月','','shijing','','小雅 · 节南山之什','正月繁霜，我心忧伤。民之讹言，亦孔之将。念我独兮，忧心京京。哀我小心，癙忧以痒。
父母生我，胡俾我愈？不自我先，不自我后。好言自口，莠言自口。忧心愈愈，是以有侮。
忧心惸惸，念我无禄。民之无辜，并其臣仆。哀我人斯，于何从禄？瞻乌爰止？于谁之屋？
瞻彼中林，侯薪侯蒸。民今方殆，视天梦梦。既克有定，靡人弗胜。有皇上帝，伊谁云憎？
谓山盖卑，为冈为陵。民之讹言，宁莫之惩。召彼故老，讯之占梦。具曰予圣，谁知乌之雌雄！
谓天盖高，不敢不局。谓地盖厚，不敢不蹐。维号斯言，有伦有脊。哀今之人，胡为虺蜴？
瞻彼阪田，有菀其特。天之杌我，如不我克。彼求我则，如不我得。执我仇仇，亦不我力。
心之忧矣，如或结之。今兹之正，胡然厉矣？燎之方扬，宁或灭之？赫赫宗周，褒姒灭之！
终其永怀，又窘阴雨。其车既载，乃弃尔辅。载输尔载，将伯助予！
无弃尔辅，员于尔辐。屡顾尔仆，不输尔载。终逾绝险，曾是不意。
鱼在于沼，亦匪克乐。潜虽伏矣，亦孔之照。忧心惨惨，念国之为虐！
彼有旨酒，又有嘉肴。洽比其邻，婚姻孔云。念我独兮，忧心殷殷。
佌佌彼有屋，蔌蔌方有谷。民今之无禄，天夭是椓。哿矣富人，哀此惸独。','',''),('shijing-193','十月之交','','shijing','','小雅 · 节南山之什','十月之交，朔月辛卯。日有食之，亦孔之丑。彼月而微，此日而微；今此下民，亦孔之哀。
日月告凶，不用其行。四国无政，不用其良。彼月而食，则维其常；此日而食，于何不臧。
烨烨震电，不宁不令。百川沸腾，山冢崒崩。高岸为谷，深谷为陵。哀今之人，胡惨莫惩？
皇父卿士，番维司徒，家伯维宰，仲允膳夫，棸子内史，蹶维趣马，楀维师氏。醘妻煽方处。
抑此皇父，岂曰不时？胡为我作，不即我谋？彻我墙屋，田卒污莱。曰予不戕，礼则然矣。
皇父孔圣，作都于向。择三有事，亶侯多藏。不慭遗一老，俾守我王。择有车马，以居徂向。
黾勉从事，不敢告劳。无罪无辜，谗口嚣嚣。下民之孽，匪降自天。噂沓背憎，职竞由人。
悠悠我里，亦孔之痗。四方有羡，我独居忧。民莫不逸，我独不敢休。天命不彻，我不敢效我友自逸。','',''),('shijing-194','雨无正','','shijing','','小雅 · 节南山之什','浩浩昊天，不骏其德。降丧饥馑，斩伐四国。旻天疾威，弗虑弗图。舍彼有罪，既伏其辜。若此无罪，沦胥以铺。
周宗既灭，靡所止戾。正大夫离居，莫知我勚。三事大夫，莫肯夙夜。邦君诸侯，莫肯朝夕。庶曰式臧，覆出为恶。
如何昊天，辟言不信。如彼行迈，则靡所臻。凡百君子，各敬尔身。胡不相畏，不畏于天？
戎成不退，饥成不遂。曾我暬御，惨惨日瘁。凡百君子，莫肯用讯。听言则答，谮言则退。
哀哉不能言，匪舌是出，维躬是瘁。哿矣能言，巧言如流，俾躬处休！
维曰予仕，孔棘且殆。云不何使，得罪于天子；亦云可使，怨及朋友。
谓尔迁于王都。曰予未有室家。鼠思泣血，无言不疾。昔尔出居，谁从作尔室？','',''),('shijing-195','小旻','','shijing','','小雅 · 节南山之什','旻天疾威，敷于下土。谋犹回遹，何日斯沮？谋臧不从，不臧覆用。我视谋犹，亦孔之邛。
潝潝訿訿，亦孔之哀。谋之其臧，则具是违。谋之不臧，则具是依。我视谋犹，伊于胡厎。
我龟既厌，不我告犹。谋夫孔多，是用不集。发言盈庭，谁敢执其咎？如匪行迈谋，是用不得于道。
哀哉为犹，匪先民是程，匪大犹是经。维迩言是听，维迩言是争。如彼筑室于道谋，是用不溃于成。
国虽靡止，或圣或否。民虽靡膴，或哲或谋，或肃或艾。如彼泉流，无沦胥以败。
不敢暴虎，不敢冯河。人知其一，莫知其他。战战兢兢，如临深渊，如履薄冰。','',''),('shijing-196','小宛','','shijing','','小雅 · 节南山之什','宛彼鸣鸠，翰飞戾天。我心忧伤，念昔先人。明发不寐，有怀二人。
人之齐圣，饮酒温克。彼昏不知，一醉日富。各敬尔仪，天命不又。
中原有菽，庶民采之。螟蛉有子，蜾蠃负之。教诲尔子，式谷似之。
题彼脊令，载飞载鸣。我日斯迈，而月斯征。夙兴夜寐，毋忝尔所生。
交交桑扈，率场啄粟。哀我填寡，宜岸宜狱。握粟出卜，自何能谷？
温温恭人，如集于木。惴惴小心，如临于谷。战战兢兢，如履薄冰。','',''),('shijing-197','小弁','','shijing','','小雅 · 节南山之什','弁彼鸴斯，归飞提提。民莫不谷，我独于罹。何辜于天？我罪伊何？心之忧矣，云如之何？
踧踧周道，鞫为茂草。我心忧伤，惄焉如捣。假寐永叹，维忧用老。心之忧矣，疢如疾首。
维桑与梓，必恭敬止。靡瞻匪父，靡依匪母。不属于毛？不罹于里？天之生我，我辰安在？
菀彼柳斯，鸣蜩嘒嘒，有漼者渊，萑苇淠淠。譬彼舟流，不知所届，心之忧矣，不遑假寐。
鹿斯之奔，维足伎伎。雉之朝雊，尚求其雌。譬彼坏木，疾用无枝。心之忧矣，宁莫之知？
相彼投兔，尚或先之。行有死人，尚或墐之。君子秉心，维其忍之。心之忧矣，涕既陨之。
君子信谗，如或酬之。君子不惠，不舒究之。伐木掎矣，析薪扡矣。舍彼有罪，予之佗矣。
莫高匪山，莫浚匪泉。君子无易由言，耳属于垣。无逝我梁，无发我笱。我躬不阅，遑恤我后。','',''),('shijing-198','巧言','','shijing','','小雅 · 节南山之什','悠悠昊天，曰父母且。无罪无辜，乱如此幠。昊天已威，予慎无罪。昊天大幠，予慎无辜。
乱之初生，僭始既涵。乱之又生，君子信谗。君子如怒，乱庶遄沮。君子如祉，乱庶遄已。
君子屡盟，乱是用长。君子信盗，乱是用暴。盗言孔甘，乱是用餤。匪其止共，维王之邛。
奕奕寝庙，君子作之。秩秩大猷，圣人莫之。他人有心，予忖度之。跃跃毚兔，遇犬获之。
荏染柔木，君子树之。往来行言，心焉数之。蛇蛇硕言，出自口矣。巧言如簧，颜之厚矣。
彼何人斯？居河之麋。无拳无勇，职为乱阶。既微且尰，尔勇伊何？为犹将多，尔居徒几何？','',''),('shijing-199','何人斯','','shijing','','小雅 · 节南山之什','彼何人斯？其心孔艰。胡逝我梁，不入我门？伊谁云从？维暴之云。
二人从行，谁为此祸？胡逝我梁，不入唁我？始者不如今，云不我可
彼何人斯？胡逝我陈？我闻其声，不见其身。不愧于人？不畏于天？
彼何人斯？其为飘风。胡不自北？胡不自南？胡逝我梁？絺搅我心。
尔之安行，亦不遑舍。尔之亟行，遑脂尔车。一者之来，云何其盱。
尔还而入，我心易也。还而不入，否难知也。一者之来，俾我絺也。
伯氏吹埙，仲氏吹篪。及尔如贯，谅不我郑出此三物，以诅尔斯。
为鬼为蜮，则不可得。有腼面目，视人罔极。作此好歌，以极反侧。','',''),('shijing-200','巷伯','','shijing','','小雅 · 节南山之什','萋兮斐兮，成是贝锦。彼谮人者，亦已大甚！
哆兮侈兮，成是南箕。彼谮人者，谁适与谋。
缉缉翩翩，谋欲谮人。慎尔言也，谓尔不信。
捷捷幡幡，谋欲谮言。岂不尔受？既其女迁。
骄人好好，劳人草草。苍天苍天，视彼骄人，矜此劳人。
彼谮人者，谁适与谋？取彼谮人，投畀豺虎。豺虎不食，投畀有北。有北不受，投畀有昊！
杨园之道，猗于亩丘。寺人孟子，作为此诗。凡百君子，敬而听之。','',''),('shijing-201','谷风','','shijing','','小雅 · 谷风之什','习习谷风，维风及雨。将恐将惧，维予与女。将安将乐，女转弃予。
习习谷风，维风及颓。将恐将惧，置予于怀。将安将乐，弃予如遗。
习习谷风，维山崔嵬。无草不死，无木不萎。忘我大德，思我小怨。','',''),('shijing-202','蓼莪','','shijing','','小雅 · 谷风之什','蓼蓼者莪，匪莪伊蒿。哀哀父母，生我劬劳。
蓼蓼者莪，匪莪伊蔚。哀哀父母，生我劳瘁。
瓶之罄矣，维罍之耻。鲜民之生，不如死之久矣。无父何怙？无母何恃？出则衔恤，入则靡至。
父兮生我，母兮鞠我。抚我畜我，长我育我，顾我复我，出入腹我。欲报之德。昊天罔极！
南山烈烈，飘风发发。民莫不谷，我独何害！南山律律，飘风弗弗。民莫不谷，我独不卒！','',''),('shijing-203','大东','','shijing','','小雅 · 谷风之什','有饛簋飧，有捄棘匕。周道如砥，其直如矢。君子所履，小人所视。眷言顾之，潸焉出涕。
小东大东，杼柚其空。纠纠葛屦，可以履霜。佻佻公子，行彼周行。既往既来，使我心疚。
有冽氿泉，无浸获薪。契契寤叹，哀我惮人。薪是获薪，尚可载也。哀我惮人，亦可息也。
东人之子，职劳不来。西人之子，粲粲衣服。舟人之子，熊罴是裘。私人之子，百僚是试。
或以其酒，不以其浆。鞙鞙佩璲，不以其长。维天有汉，监亦有光。跂彼织女，终日七襄。
虽则七襄，不成报章。睆彼牵牛，不以服箱。东有启明，西有长庚。有捄天毕，载施之行。
维南有箕，不可以簸扬。维北有斗，不可以挹酒浆。维南有箕，载翕其舌。维北有斗，西柄之揭。','',''),('shijing-204','四月','','shijing','','小雅 · 谷风之什','四月维夏，六月徂署。先祖匪人，胡宁忍予？
秋日凄凄，百卉具腓。乱离瘼矣，爰其适归？
冬日烈烈，飘风发发。民莫不谷，我独何害？
山有嘉卉，侯栗侯梅。废为残贼，莫知其尤！
相彼泉水，载清载浊。我日构祸，曷云能谷？
滔滔江汉，南国之纪。尽瘁以仕，宁莫我有？
匪鹑匪鸢，翰飞戾天。匪鳣匪鲔，潜逃于渊。
山有蕨薇，隰有杞桋。君子作歌，维以告哀。','',''),('shijing-205','北山','','shijing','','小雅 · 谷风之什','陟彼北山，言采其杞。偕偕士子，朝夕从事。王事靡盬，忧我父母。
溥天之下，莫非王土；率土之滨，莫非王臣。大夫不均，我从事独贤。
四牡彭彭，王事傍傍。嘉我未老，鲜我方将。旅力方刚，经营四方。
或燕燕居息，或尽瘁事国；或息偃在床，或不已于行。
或不知叫号，或惨惨劬劳；或栖迟偃仰，或王事鞅掌。
或湛乐饮酒，或惨惨畏咎；或出入风议，或靡事不为。','',''),('shijing-206','无将大车','','shijing','','小雅 · 谷风之什','无将大车，只自尘兮。无思百忧，只自疧兮。
无将大车，维尘冥冥。无思百忧，不出于颎。
无将大车，维尘雍兮。无思百忧，只自重兮。','',''),('shijing-207','小明','','shijing','','小雅 · 谷风之什','明明上天，照临下土。我征徂西，至于艽野。二月初吉，载离寒暑。
心之忧矣，其毒大苦。念彼共人，涕零如雨。岂不怀归？畏此罪罟！
昔我往矣，日月方除。曷云其还？岁聿云莫。念我独兮，我事孔庶。
心之忧矣，惮我不暇。念彼共人，眷眷怀顾！岂不怀归？畏此谴怒。
昔我往矣，日月方奥。曷云其还？政事愈蹙。岁聿云莫，采萧获菽。
心之忧矣，自诒伊戚。念彼共人，兴言出宿。岂不怀归？畏此反覆。
嗟尔君子，无恒安处。靖共尔位，正直是与。神之听之，式谷以女。
嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。','',''),('shijing-208','鼓钟','','shijing','','小雅 · 谷风之什','鼓钟将将，淮水汤汤，忧心且伤。淑人君子，怀允不忘。
鼓钟喈喈，淮水湝湝，忧心且悲。淑人君子，其德不回。
鼓钟伐鼛，淮有三洲，忧心且妯。淑人君子，其德不犹。
鼓钟钦钦，鼓瑟鼓琴，笙磬同音。以雅以南，以龠不僭。','',''),('shijing-209','楚茨','','shijing','','小雅 · 谷风之什','楚楚者茨，言抽其棘，自昔何为？我蓺黍稷。我黍与与，我稷翼翼。
我仓既盈，我庾维亿。以为酒食，以享以祀，以妥以侑，以介景福。
济济跄跄，絜尔牛羊，以往烝尝。或剥或亨，或四或将。祝祭于祊，
祀事孔明。先祖是皇，神保是飨。孝孙有庆，报以介福，万寿无疆！
执爨踖踖，为俎孔硕，或燔或炙。君妇莫莫，为豆孔庶。为宾为客，
献酬交错。礼仪卒度，笑语卒获。神保是格，报以介福，万寿攸酢！
我孔戁矣，式礼莫愆。工祝致告，徂赉孝孙。苾芬孝祀，神嗜饮食。
卜尔百福，如几如式。既齐既稷，既匡既敕。永锡尔极，时万时亿！
礼仪既备，钟鼓既戒，孝孙徂位，工祝致告，神具醉止，皇尸载起。
鼓钟送尸，神保聿归。诸宰君妇，废彻不迟。诸父兄弟，备言燕私。
乐具入奏，以绥后禄。尔肴既将，莫怨具庆。既醉既饱，小大稽首。
神嗜饮食，使君寿考。孔惠孔时，维其尽之。子子孙孙，勿替引之！','',''),('shijing-210','信南山','','shijing','','小雅 · 谷风之什','信彼南山，维禹甸之。畇畇原隰，曾孙田之。我疆我理，南东其亩。
上天同云。雨雪雰雰，益之以霡霂。既优既渥，既沾既足。生我百谷。
疆埸翼翼，黍稷彧彧。曾孙之穑，以为酒食。畀我尸宾，寿考万年。
中田有庐，疆埸有瓜。是剥是菹，献之皇祖。曾孙寿考，受天之祜。
祭以清酒，从以骍牡，享于祖考。执其鸾刀，以启其毛，取其血膋。
是烝是享，苾苾芬芬。祀事孔明，先祖是皇。报以介福。万寿无疆。','',''),('shijing-211','甫田','','shijing','','小雅 · 甫田之什','倬彼甫田，岁取十千。我取其陈，食我农人。自古有年。
今适南亩，或耘或耔。黍稷薿薿，攸介攸止，烝我髦士。
以我齐明，与我牺羊，以社以方。我田既臧，农夫之庆。
琴瑟击鼓，以御田祖。以祈甘雨，以介我稷黍，以谷我士女。
曾孙来止，以其妇子。馌彼南亩，田畯至喜。攘其左右，
尝其旨否。禾易长亩，终善且有。曾孙不怒，农夫克敏。
曾孙之稼，如茨如梁。曾孙之庾，如坻如京。乃求千斯仓，
乃求万斯箱。黍稷稻粱，农夫之庆。报以介福，万寿无疆。','',''),('shijing-212','大田','','shijing','','小雅 · 甫田之什','大田多稼，既种既戒，既备乃事。以我覃耜，俶载南亩。
播厥百谷，既庭且硕，曾孙是若。
既方既皂，既坚既好，不稂不莠。去其螟螣，及其蟊贼，
无害我田稚。田祖有神，秉畀炎火。
有渰萋萋，兴雨祈祈。雨我公田，遂及我私。彼有不获稚，
此有不敛穧，彼有遗秉，此有滞穗，伊寡妇之利。
曾孙来止，以其妇子。馌彼南亩，田畯至喜。来方禋祀，
以其骍黑，与其黍稷。以享以祀，以介景福。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('shijing-213','瞻彼洛矣','','shijing','','小雅 · 甫田之什','瞻彼洛矣，维水泱泱。君子至止，福禄如茨。韎韐有奭，以作六师。
瞻彼洛矣，维水泱泱。君子至止，鞸琫有珌。君子万年，保其家室。
瞻彼洛矣，维水泱泱。君子至止，福禄既同。君子万年，保其家邦。','',''),('shijing-214','裳裳者华','','shijing','','小雅 · 甫田之什','裳裳者华，其叶湑兮。我觏之子，我心写兮。我心写兮，是以有誉处兮。
裳裳者华，芸其黄矣。我觏之子，维其有章矣。维其有章矣，是以有庆矣。
裳裳者华，或黄或白。我觏之子，乘其四骆。乘其四骆，六辔沃若。
左之左之，君子宜之。右之右之，君子有之。维其有之，是以似之。','',''),('shijing-215','桑扈','','shijing','','小雅 · 甫田之什','交交桑扈，有莺其羽。君子乐胥，受天之祜。
交交桑扈，有莺其领。君子乐胥，万邦之屏。
之屏之翰，百辟为宪。不戢不难，受福不那。
兕觥其觩，旨酒思柔。彼交匪敖，万福来求。','',''),('shijing-216','鸳鸯','','shijing','','小雅 · 甫田之什','鸳鸯于飞，毕之罗之。君子万年，福禄宜之。
鸳鸯在梁，戢其左翼。君子万年，
宜其遐福。乘马在厩，摧之秣之。君子万年，福禄艾之。
乘马在厩，秣之摧之。君子万年，福禄绥之。','',''),('shijing-217','頍弁','','shijing','','小雅 · 甫田之什','有頍者弁，实维伊何？尔酒既旨，尔肴既嘉。岂伊异人？兄弟匪他。
茑与女萝，施于松柏。未见君子，忧心奕奕；既见君子，庶几说怿。
有頍者弁，实维何期？尔酒既旨，尔肴既时。岂伊异人？兄弟具来。
茑与女萝，施于松上。未见君子，忧心怲怲；既见君子，庶几有臧。
有頍者弁，实维在首。尔酒既旨，尔肴既阜。岂伊异人？兄弟甥舅。
如彼雨雪，先集维霰。死丧无日，无几相见。乐酒今夕，君子维宴。','',''),('shijing-218','车舝','','shijing','','小雅 · 甫田之什','间关车之舝兮，思娈季女逝兮。匪饥匪渴，德音来括。虽无好友？式燕且喜。
依彼平林，有集维鷮。辰彼硕女，令德来教。式燕且誉，好尔无射。
虽无旨酒？式饮庶几。虽无嘉肴？式食庶几。虽无德与女？式歌且舞？
陟彼高冈，析其柞薪。析其柞薪，其叶湑兮。鲜我觏尔，我心写兮。
高山仰止，景行行止。四牡騑騑，六辔如琴。觏尔新婚，以慰我心。','',''),('shijing-219','青蝇','','shijing','','小雅 · 甫田之什','营营青蝇，止于樊。岂弟君子，无信谗言。
营营青蝇，止于棘。谗人罔极，交乱四国。
营营青蝇，止于榛。谗人罔极，构我二人。','',''),('shijing-220','宾之初筵','','shijing','','小雅 · 甫田之什','宾之初筵，左右秩秩。笾豆有楚，肴核维旅。酒既和旨，饮酒孔偕。
钟鼓既设，举酬逸逸。大侯既抗，弓矢斯张。射夫既同，献尔发功。
发彼有的，以祈尔爵。
龠舞笙鼓，乐既和奏。烝衎烈祖，以洽百礼。百礼既至，有壬有林。
锡尔纯嘏，子孙其湛。其湛曰乐，各奏尔能。宾载手仇，室人入又。
酌彼康爵，以奏尔时。
宾之初筵，温温其恭。其未醉止，威仪反反。曰既醉止，威仪幡幡。
舍其坐迁，屡舞仙仙。其未醉止，威仪抑抑。曰既醉止，威仪抑抑。
是曰既醉，不知其秩。
宾既醉止，载号载呶。乱我笾豆，屡舞僛僛。是曰既醉，不知其邮。
侧弁之俄，屡舞傞傞。既醉而出，并受其福。醉而不出，是谓伐德。
饮酒孔嘉，维其令仪。
凡此饮酒，或醉或否。既立之监，或佐之史。彼醉不臧，不醉反耻。
式勿从谓，无俾大怠。匪言勿言，匪由勿语。由醉之言，俾出童羖。
三爵不识，矧敢多又。','',''),('shijing-221','鱼藻','','shijing','','小雅 · 鱼藻之什','鱼在在藻，有颁其首。王在在镐，岂乐饮酒。
鱼在在藻，有莘其尾。王在在镐，饮酒乐岂。
鱼在在藻，依于其蒲。王在在镐，有那其居。','',''),('shijing-222','采菽','','shijing','','小雅 · 鱼藻之什','采菽采菽，筐之莒之。君子来朝，何锡予之？虽无予之？路车乘马。又何予之？玄衮及黼。
觱沸槛泉，言采其芹。君子来朝，言观其旗。其旗淠淠，鸾声嘒嘒。载骖载驷，君子所届。
赤芾在股，邪幅在下。彼交匪纾，天子所予。乐只君子，天子命之。乐只君子，福禄申之。
维柞之枝，其叶蓬蓬。乐只君子，殿天子之邦。乐只君子，万福攸同。平平左右，亦是率从。
泛泛杨舟，绋纚维之。乐只君子，天子葵之。乐只君子，福禄膍之。优哉游哉，亦是戾矣。','',''),('shijing-223','角弓','','shijing','','小雅 · 鱼藻之什','骍骍角弓，翩其反矣。兄弟婚姻，无胥远矣。
尔之远矣，民胥然矣。尔之教矣，民胥效矣。
此令兄弟，绰绰有裕。不令兄弟，交相为愈。
民之无良，相怨一方。受爵不让，至于已斯亡。
老马反为驹，不顾其后。如食宜饇，如酌孔取。
毋教猱升木，如涂涂附。君子有徽猷，小人与属。
雨雪瀌瀌，见晛曰消。莫肯下遗，式居娄骄。
雨雪浮浮，见晛曰流。如蛮如髦，我是用忧。','',''),('shijing-224','菀柳','','shijing','','小雅 · 鱼藻之什','有菀者柳，不尚息焉。上帝甚蹈，无自昵焉。俾予靖之，后予极焉。
有菀者柳，不尚愒焉。上帝甚蹈，无自瘵焉。俾予靖之，后予迈焉。
有鸟高飞，亦傅于天。彼人之心，于何其臻。曷予靖之，居以凶矜。','',''),('shijing-225','都人士','','shijing','','小雅 · 鱼藻之什','彼都人士，狐裘黄黄。其容不改，出言有章。行归于周，万民所望。
彼都人士，台笠缁撮。彼君子女，绸直如发。我不见兮，我心不说。
彼都人士，充耳琇实。彼君子女，谓之尹吉。我不见兮，我心苑结。
彼都人士，垂带而厉。彼君子女，卷发如虿。我不见兮，言从之迈。
匪伊垂之，带则有余。匪伊卷之，发则有旟。我不见兮，云何盱矣。','',''),('shijing-226','采绿','','shijing','','小雅 · 鱼藻之什','终朝采绿，不盈一匊。予发曲局，薄言归沐。
终朝采蓝，不盈一襜。五日为期，六日不詹。
之子于狩，言韔其弓。之子于钓，言纶之绳。
其钓维何？维鲂及鱮。维鲂及鱮，薄言观者。','',''),('shijing-227','黍苗','','shijing','','小雅 · 鱼藻之什','芃芃黍苗，阴雨膏之。悠悠南行，召伯劳之。
我任我辇，我车我牛。我行既集，盖云归哉。
我徒我御，我师我旅。我行既集，盖云归处。
肃肃谢功，召伯营之。烈烈征师，召伯成之。
原隰既平，泉流既清。召伯有成，王心则宁。','',''),('shijing-228','隰桑','','shijing','','小雅 · 鱼藻之什','隰桑有阿，其叶有难。既见君子，其乐如何。
隰桑有阿，其叶有沃。既见君子，云何不乐。
隰桑有阿，其叶有幽。既见君子，德音孔胶。
心乎爱矣，遐不谓矣？中心藏之，何日忘之！','',''),('shijing-229','白华','','shijing','','小雅 · 鱼藻之什','白华菅兮，白茅束兮。之子之远，俾我独兮。
英英白云，露彼菅茅。天步艰难，之子不犹。
滮池北流，浸彼稻田。啸歌伤怀，念彼硕人。
樵彼桑薪，昂烘于煁。维彼硕人，实劳我心。
鼓钟于宫，声闻于外。念子懆懆，视我迈迈。
有鹙在梁，有鹤在林。维彼硕人，实劳我心。
鸳鸯在梁，戢其左翼。之子无良，二三其德。
有扁斯石，履之卑兮。之子之远，俾我疧兮。','',''),('shijing-230','绵蛮','','shijing','','小雅 · 鱼藻之什','绵蛮黄鸟，止于丘阿。道之云远，我劳如何。饮之食之，教之诲之。命彼后车，谓之载之。
绵蛮黄鸟，止于丘隅。岂敢惮行，畏不能趋。饮之食之。教之诲之。命彼后车，谓之载之。
绵蛮黄鸟，止于丘侧。岂敢惮行，畏不能极。饮之食之，教之诲之。命彼后车，谓之载之。','',''),('shijing-231','瓠叶','','shijing','','小雅 · 鱼藻之什','幡幡瓠叶，采之亨之。君子有酒，酌言尝之。
有兔斯首，炮之燔之。君子有酒，酌言献之。
有兔斯首，燔之炙之。君子有酒，酌言酢之。
有兔斯首，燔之炮之。君子有酒，酌言酬之。','',''),('shijing-232','渐渐之石','','shijing','','小雅 · 鱼藻之什','渐渐之石，维其高矣。山川悠远，维其劳矣。武人东征，不遑朝矣。
渐渐之石，维其卒矣。山川悠远，曷其没矣？武人东征，不遑出矣。
有豕白蹢，烝涉波矣。月离于毕，俾滂沱矣。武人东征，不皇他矣。','',''),('shijing-233','苕之华','','shijing','','小雅 · 鱼藻之什','苕之华，芸其黄矣。心之忧矣，维其伤矣！
苕之华，其叶青青。知我如此，不如无生！
牂羊坟首，三星在罶。人可以食，鲜可以饱！','',''),('shijing-234','何草不黄','','shijing','','小雅 · 鱼藻之什','何草不黄？何日不行？何人不将？经营四方。
何草不玄？何人不矜？哀我征夫，独为匪民。
匪兕匪虎，率彼旷野。哀我征夫，朝夕不暇。
有芃者狐，率彼幽草。有栈之车，行彼周道。','',''),('shijing-235','文王','','shijing','','大雅 · 文王之什','文王在上，于昭于天。周虽旧邦，其命维新。有周不显，帝命不时。文王陟降，在帝左右。
亹亹文王，令闻不已。陈锡哉周，侯文王孙子。文王孙子，本支百世，凡周之士，不显亦世。
世之不显，厥犹翼翼。思皇多士，生此王国。王国克生，维周之桢；济济多士，文王以宁。
穆穆文王，于缉熙敬止。假哉天命。有商孙子。商之孙子，其丽不亿。上帝既命，侯于周服。
侯服于周，天命靡常。殷士肤敏。裸将于京。厥作裸将，常服黼冔。王之荩臣。无念尔祖。
无念尔祖，聿修厥德。永言配命，自求多福。殷之未丧师，克配上帝。宜鉴于殷，骏命不易！
命之不易，无遏尔躬。宣昭义问，有虞殷自天。上天之载，无声无臭。仪刑文王，万邦作孚。','',''),('shijing-236','大明','','shijing','','大雅 · 文王之什','明明在下，赫赫在上。天难忱斯，不易维王。天位殷适，使不挟四方。
挚仲氏任，自彼殷商，来嫁于周，曰嫔于京。乃及王季，维德之行。
大任有身，生此文王。维此文王，小心翼翼。昭事上帝，聿怀多福。厥德不回，以受方国。
天监在下，有命既集。文王初载，天作之合。在洽之阳，在渭之涘。
文王嘉止，大邦有子。大邦有子，伣天之妹。文定厥祥，亲迎于渭。造舟为梁，不显其光。
有命自天，命此文王。于周于京，缵女维莘。长子维行，笃生武王。保右命尔，燮伐大商。
殷商之旅，其会如林。矢于牧野，维予侯兴。上帝临女，无二尔心。
牧野洋洋，檀车煌煌，驷騵彭彭。维师尚父，时维鹰扬。凉彼武王，四伐大商，会朝清明。','',''),('shijing-237','绵','','shijing','','大雅 · 文王之什','绵绵瓜瓞。民之初生，自土沮漆。古公亶父，陶复陶冗，未有家室。
古公亶父，来朝走马。率西水浒，至于岐下。爰及姜女，聿来胥宇。
周原膴膴，堇荼如饴。爰始爰谋，爰契我龟，曰止曰时，筑室于兹。
乃慰乃止，乃左乃右，乃疆乃理，乃宣乃亩。自西徂东，周爰执事。
乃召司空，乃召司徒，俾立室家。其绳则直，缩版以载，作庙翼翼。
捄之陾陾，度之薨薨，筑之登登，削屡冯冯。百堵皆兴，鼛鼓弗胜。
乃立皋门，皋门有伉。乃立应门，应门将将。乃立冢土，戎丑攸行。
四不殄厥愠，亦不陨厥问。柞棫拔矣，行道兑矣。混夷駾矣，维其喙矣！
虞芮质厥成，文王蹶厥生。予曰有疏附，予曰有先后。予曰有奔奏，予曰有御侮！','',''),('shijing-238','棫朴','','shijing','','大雅 · 文王之什','芃芃棫朴，薪之槱之。济济辟王，左右趣之。
济济辟王，左右奉璋。奉璋峨峨，髦士攸宜。
淠彼泾舟，烝徒楫之。周王于迈，六师及之。
倬彼云汉，为章于天。周王寿考，遐不作人？
追琢其章，金玉其相。勉勉我王，纲纪四方。','',''),('shijing-239','旱麓','','shijing','','大雅 · 文王之什','瞻彼旱麓，榛楛济济。岂弟君子，干禄岂弟。
瑟彼玉瓒，黄流在中。岂弟君子，福禄攸降。
鸢飞戾天，鱼跃于渊。岂弟君子，遐不作人？
清酒既载，骍牡既备。以享以祀，以介景福。
瑟彼柞棫，民所燎矣。岂弟君子，神所劳矣。
莫莫葛藟，施于条枚。岂弟君子，求福不回。','',''),('shijing-240','思齐','','shijing','','大雅 · 文王之什','思齐大任，文王之母，思媚周姜，京室之妇。大姒嗣徽音，则百斯男。
惠于宗公，神罔时怨，神罔时恫。刑于寡妻，至于兄弟，以御于家邦。
雍雍在宫，肃肃在庙。不显亦临，无射亦保。
四戎疾不殄，烈假不瑕。不闻亦式，不谏亦入。四成人有德，小子有造。古之人无斁，誉髦斯士。','',''),('shijing-241','皇矣','','shijing','','大雅 · 文王之什','皇矣上帝，临下有赫。监观四方，求民之莫。维此二国，其政不获。
维彼四国，爰究爰度。上帝耆之，憎其式廓。乃眷西顾，此维与宅。
作之屏之，其菑其翳。修之平之，其灌其栵。启之辟之，其柽其椐。
攘之剔之，其檿其柘。帝迁明德，串夷载路。天立厥配，受命既固。
帝省其山，柞棫斯拔，松柏斯兑。帝作邦作对，自大伯王季。维此王季，
因心则友。则友其兄，则笃其庆，载锡之光。受禄无丧，奄有四方。
维此王季，帝度其心。貊其德音，其德克明。克明克类，克长克君。
王此大邦，克顺克比。比于文王，其德靡悔。既受帝祉，施于孙子。
帝谓文王：无然畔援，无然歆羡，诞先登于岸。密人不恭，敢距大邦，
侵阮徂共。王赫斯怒，爰整其旅，以按徂旅。以笃于周祜，以对于天下。
依其在京，侵自阮疆。陟我高冈，无矢我陵。我陵我阿，无饮我泉，
我泉我池。度其鲜原，居岐之阳，在渭之将。万邦之方，下民之王。
帝谓文王：予怀明德，不大声以色，不长夏以革。不识不知，顺帝之则。
帝谓文王：訽尔仇方，同尔弟兄。以尔钩援，与尔临冲，以伐崇墉。
临冲闲闲，崇墉言言。执讯连连，攸馘安安。是类是禡，是致是附，
四方以无侮。临冲茀茀，崇墉仡仡。是伐是四，是绝是忽。四方以无拂。','',''),('shijing-242','灵台','','shijing','','大雅 · 文王之什','经始灵台，经之营之。庶民攻之，不日成之。经始勿亟，庶民子来。
王在灵囿，麀鹿攸伏。麀鹿濯濯，白鸟翯翯。王在灵沼，于牣鱼跃。
虡业维枞，贲鼓维镛。于论鼓钟，于乐辟雍。
于论鼓钟，于乐辟雍。鼍鼓逢逢。蒙瞍奏公。','',''),('shijing-243','下武','','shijing','','大雅 · 文王之什','下武维周，世有哲王。三后在天，王配于京。
王配于京，世德作求。永言配命，成王之孚。
成王之孚，下土之式。永言孝思，孝思维则。
媚兹一人，应侯顺德。永言孝思，昭哉嗣服。
昭兹来许，绳其祖武。于万斯年，受天之祜。
受天之祜，四方来贺。于万斯年，不遐有佐。','',''),('shijing-244','文王有声','','shijing','','大雅 · 文王之什','文王有声，遹骏有声。遹求厥宁，遹观厥成。文王烝哉！
文王受命，有此武功。既伐于崇，作邑于丰。文王烝哉！
筑城伊淢，作丰伊匹。匪棘其欲，遹追来孝。王后烝哉！
王公伊濯，维丰之垣。四方攸同，王后维翰。王后烝哉！
丰水东注，维禹之绩。四方攸同，皇王维辟。皇王烝哉！
镐京辟雍，自西自东，自南自北，无思不服。皇王烝哉！
考卜维王，宅是镐京。维龟正之，武王成之。武王烝哉！
丰水有芑，武王岂不仕？诒厥孙谋，以燕翼子。武王烝哉！','',''),('shijing-245','生民','','shijing','','大雅 · 生民之什','厥初生民，时维姜嫄。生民如何？克禋克祀，以弗无子。
履帝武敏歆，攸介攸止，载震载夙。载生载育，时维后稷。
诞弥厥月，先生如达。不拆不副，无菑无害。以赫厥灵。
上帝不宁，不康禋祀，居然生子。
诞置之隘巷，牛羊腓字之。诞置之平林，会伐平林。
诞置之寒冰，鸟覆翼之。鸟乃去矣，后稷呱矣。
实覃实訏，厥声载路。诞实匍匐，克岐克嶷。以就口食。
蓺之荏菽，荏菽旆旆。禾役穟穟，麻麦幪幪，瓜瓞唪唪。
诞后稷之穑，有相之道。茀厥丰草，种之黄茂。实方实苞，实种实袖。
实发实秀，实坚实好。实颖实栗，即有邰家室。
诞降嘉种，维秬维秠，维穈维芑。恒之秬秠，是获是亩。
恒之穈芑，是任是负。以归肇祀。
诞我祀如何？或舂或揄，或簸或蹂。释之叟叟，烝之浮浮。
载谋载惟。取萧祭脂，取羝以軷，载燔载烈，以兴嗣岁。
昂盛于豆，于豆于登。其香始升，上帝居歆。胡臭亶时。
后稷肇祀。庶无罪悔，以迄于今。','',''),('shijing-246','行苇','','shijing','','大雅 · 生民之什','敦彼行苇，牛羊勿践履。方苞方体，维叶泥泥。
戚戚兄弟，莫远具尔。或四之筵，或授之几。
四筵设席，授几有缉御。或献或酢，洗爵奠斝。
醓醢以荐，或燔或炙。嘉肴脾臄，或歌或咢。
敦弓既坚，四鍭既均，舍矢既均，序宾以贤。
敦弓既句，既挟四鍭。四鍭如树，序宾以不侮。
曾孙维主，酒醴维醽，酌以大斗，以祈黄耇。
黄耇台背，以引以翼。寿考维祺，以介景福。','',''),('shijing-247','既醉','','shijing','','大雅 · 生民之什','既醉以酒，既饱以德。君子万年，介尔景福。
既醉以酒，尔肴既将。君子万年，介尔昭明。
昭明有融，高朗令终，令终有俶。公尸嘉告。
其告维何？笾豆静嘉。朋友攸摄，摄以威仪。
威仪孔时，君子有孝子。孝子不匮，永锡尔类。
其类维何？室家之壶。君子万年，永锡祚胤。
其胤维何？天被尔禄。君子万年，景命有仆。
其仆维何？厘尔女士。厘尔女士，从以孙子。','',''),('shijing-248','凫鹥','','shijing','','大雅 · 生民之什','凫鹥在泾，公尸在燕来宁。尔酒既清，尔肴既馨。公尸燕饮，福禄来成。
凫鹥在沙，公尸来燕来宜。尔酒既多，尔肴既嘉。公尸燕饮，福禄来为。
凫鹥在渚，公尸来燕来处。尔酒既湑，尔肴伊脯。公尸燕饮，福禄来下。
凫鹥在潀，公尸来燕来宗，既燕于宗，福禄攸降。公尸燕饮，福禄来崇。
凫鹥在亹，公尸来止熏熏。旨酒欣欣，燔炙芬芬。公尸燕饮，无有后艰。','',''),('shijing-249','假乐','','shijing','','大雅 · 生民之什','假乐君子，显显令德，宜民宜人。受禄于天，保右命之，自天申之。
千禄百福，子孙千亿。穆穆皇皇，宜君宜王。不愆不忘，率由旧章。
威仪抑抑，德音秩秩。无怨无恶，率由群匹。受福无疆，四方之纲。
之纲之纪，燕及朋友。百辟卿士，媚于天子。不解于位，民之攸塈。','',''),('shijing-250','公刘','','shijing','','大雅 · 生民之什','笃公刘，匪居匪康。乃埸乃疆，乃积乃仓；乃裹糇粮，于橐于囊。
思辑用光，弓矢斯张；干戈戚扬，爰方启行。
笃公刘，于胥斯原。既庶既繁，既顺乃宣，而无永叹。陟则在巘，
复降在原。何以舟之？维玉及瑶，鞞琫容刀。
笃公刘，逝彼百泉。瞻彼溥原，乃陟南冈。乃觏于京，京师之野。
于时处处，于时庐旅，于时言言，于时语语。
笃公刘，于京斯依。跄跄济济，俾筵俾几。既登乃依，乃造其曹。
执豕于牢，酌之用匏。食之饮之，君之宗之。
笃公刘，既溥既长。既景乃冈，相其阴阳，观其流泉。其军三单，
度其隰原。彻田为粮，度其夕阳。豳居允荒。
笃公刘，于豳斯馆。涉渭为乱，取厉取锻，止基乃理。爰众爰有，
夹其皇涧。溯其过涧。止旅乃密，芮鞫之即。','',''),('shijing-251','泂酌','','shijing','','大雅 · 生民之什','泂酌彼行潦，挹彼注兹，可以餴饎。岂弟君子，民之父母。
泂酌彼行潦，挹彼注兹，可以濯罍。岂弟君子，民之攸归。
泂酌彼行潦，挹彼注兹，可以濯溉。岂弟君子，民之攸墍。','',''),('shijing-252','卷阿','','shijing','','大雅 · 生民之什','有卷者阿，飘风自南。岂弟君子，来游来歌，以矢其音。
伴奂尔游矣，优游尔休矣。岂弟君子，俾尔弥尔性，似先公酋矣。
尔土宇昄章，亦孔之厚矣。岂弟君子，俾尔弥尔性，百神尔主矣。
尔受命长矣，茀禄尔康矣。岂弟君子，俾尔弥尔性，纯嘏尔常矣。
有冯有翼，有孝有德，以引以翼。岂弟君子，四方为则。
颙颙昂昂，如圭如璋，令闻令望。岂弟君子，四方为纲。
凤凰于飞，翙翙其羽，亦集爰止。蔼蔼王多吉士，维君子使，媚于天子。
凤凰于飞，翙翙其羽，亦傅于天。蔼蔼王多吉人，维君子命，媚于庶人。
凤凰鸣矣，于彼高冈。梧桐生矣，于彼朝阳。菶菶萋萋，雍雍喈喈。
君子之车，既庶且多。君子之马，既闲且驰。矢诗不多，维以遂歌。','',''),('shijing-253','民劳','','shijing','','大雅 · 生民之什','民亦劳止，汔可小康。惠此中国，以绥四方。无纵诡随，以谨无良。
式遏寇虐，憯不畏明。柔远能迩，以定我王。
民亦劳止，汔可小休。惠此中国，以为民逑。无纵诡随，以谨惛怓。
式遏寇虐，无俾民忧。无弃尔劳，以为王休。
民亦劳止，汔可小息。惠此京师，以绥四国。无纵诡随，以谨罔极。
式遏寇虐，无俾作慝。敬慎威仪，以近有德。
民亦劳止，汔可小愒。惠此中国，俾民忧泄。无纵诡随，以谨丑厉。
式遏寇虐，无俾正败。戎虽小子，而式弘大。
民亦劳止，汔可小安。惠此中国，国无有残。无纵诡随，以谨缱绻。
式遏寇虐，无俾正反。王欲玉女，是用大谏。','',''),('shijing-254','板','','shijing','','大雅 · 生民之什','上帝板板，下民卒瘅。出话不然，为犹不远。
靡圣管管。不实于亶。犹之未远，是用大谏。
天之方难，无然宪宪。天之方蹶，无然泄泄。
辞之辑矣，民之洽矣。辞之怿矣，民之莫矣。
我虽异事，及尔同僚。我即尔谋，听我嚣嚣。
我言维服，勿以为笑。先民有言，询于刍荛。
天之方虐，无然谑谑。老夫灌灌，小子蹻蹻。
匪我言耄，尔用忧谑。多将熇熇，不可救药。
天之方懠。无为夸毗。威仪卒迷，善人载尸。
民之方殿屎，则莫我敢葵？丧乱蔑资，曾莫惠我师？
天之牖民，如埙如篪，如璋如圭，如取如携。
携无曰益，牖民孔易。民之多辟，无自立辟。
价人维藩，大师维垣，大邦维屏，大宗维翰，
怀德维宁，宗子维城。无俾城坏，无独斯畏。
敬天之怒，无敢戏豫。敬天之渝，无敢驰驱。
昊天曰明，及尔出王。昊天曰旦，及尔游衍。','',''),('shijing-255','荡','','shijing','','大雅 · 荡之什','荡荡上帝，下民之辟。疾威上帝，其命多辟。
天生烝民，其命匪谌。靡不有初，鲜克有终。
文王曰咨，咨汝殷商。曾是彊御？曾是掊克？
曾是在位？曾是在服？天降滔德，女兴是力。
文王曰咨，咨女殷商。而秉义类，彊御多怼。
流言以对。寇攘式内。侯作侯祝，靡届靡究。
文王曰咨，咨女殷商。女炮烋于中国。敛怨以为德。
不明尔德，时无背无侧。尔德不明，以无陪无卿。
文王曰咨，咨女殷商。天不湎尔以酒，不义从式。
既衍尔止。靡明靡晦。式号式呼。俾昼作夜。
文王曰咨，咨女殷商。如蜩如螗，如沸如羹。
小大近丧，人尚乎由行。内奰于中国，覃及鬼方。
文王曰咨，咨女殷商。匪上帝不时，殷不用旧。
虽无老成人，尚有典刑。曾是莫听，大命以倾。
文王曰咨，咨女殷商。人亦有言：颠沛之揭，
枝叶未有害，本实先拨。殷鉴不远，在夏后之世。','',''),('shijing-256','抑','','shijing','','大雅 · 荡之什','抑抑威仪，维德之隅。人亦有言：靡哲不愚，庶人之愚，亦职维疾。
哲人之愚，亦维斯戾。无竞维人，四方其训之。有觉德行，四国顺之。
訏谟定命，远犹辰告。敬慎威仪，维民之则。其在于今，兴迷乱于政。
颠覆厥德，荒湛于酒。女虽湛乐从，弗念厥绍。罔敷求先王，克共明刑。
四皇天弗尚，如彼泉流，无沦胥以亡。夙兴夜寐，洒扫庭内，维民之章。
修尔车马，弓矢戎兵，用戒戎作，用逷蛮方。质尔人民，谨尔侯度，用戒不虞。
慎尔出话，敬尔威仪，无不柔嘉。白圭之玷，尚可磨也；斯言之玷，不可为也！
无易由言，无曰苟矣，莫扪朕舌，言不可逝矣。无言不仇，无德不报。
惠于朋友，庶民小子。子孙绳绳，万民靡不承。视尔友君子，辑柔尔颜，不遐有愆。
相在尔室，尚不愧于屋漏。无曰不显，莫予云觏。神之格思，不可度思，矧可射思！
辟尔为德，俾臧俾嘉。淑慎尔止，不愆于仪。不僭不贼，鲜不为则。投我以桃，报之以李。
彼童而角，实虹小子。荏染柔木，言缗之丝。温温恭人，维德之基。
其维哲人，告之话言，顺德之行。其维愚人，覆谓我僭。民各有心。
于乎小子，未知臧否。匪手携之，言示之事。匪面命之，言提其耳。
借曰未知，亦既抱子。民之靡盈，谁夙知而莫成？昊天孔昭，我生靡乐。
视尔梦梦，我心惨惨。诲尔谆谆，听我藐藐。匪用为教，覆用为虐。
借曰未知，亦聿既耄。于乎，小子，告尔旧止。听用我谋，庶无大悔。
天方艰难，曰丧厥国。取譬不远，昊天不忒。回遹其德，俾民大棘。','',''),('shijing-257','桑柔','','shijing','','大雅 · 荡之什','菀彼桑柔，其下侯旬，捋采其刘，瘼此下民。不殄心忧，仓兄填兮。倬彼昊天，宁不我矜？
四牡骙骙，旟旐有翩。乱生不夷，靡国不泯。民靡有黎，具祸以烬。于乎有哀，国步斯频。
国步灭资，天不我将。靡所止疑，云徂何往？君子实维，秉心无竞。谁生厉阶，至今为梗？
忧心殷殷，念我土宇。我生不辰，逢天僤怒。自西徂东，靡所定处。多我觏痻，孔棘我圉。
为谋为毖，乱况斯削。告尔忧恤，诲尔序爵。谁能执热，逝不以濯？其何能淑，载胥及溺。
如彼溯风，亦孔之僾。民有肃心，荓云不逮。好是稼穑，力民代食。稼穑维宝，代食维好？
天降丧乱，灭我立王。降此蟊贼，稼穑卒痒。哀恫中国，具赘卒荒。靡有旅力，以念穹苍。
维此惠君，民人所瞻。秉心宣犹，考慎其相。维彼不顺，自独俾臧。自有肺肠，俾民卒狂。
瞻彼中林，甡甡其鹿。朋友已谮，不胥以谷。人亦有言：进退维谷。
维此圣人，瞻言百里。维彼愚人，覆狂以喜。匪言不能，胡斯畏忌？
维此良人，弗求弗迪。维彼忍心，是顾是复。民之贪乱，宁为荼毒。
大风有隧，有空大谷。维此良人，作为式谷。维彼不顺，征以中垢。
大风有隧，贪人败类。听言则对，诵言如醉。匪用其良，复俾我悖。
嗟尔朋友，予岂不知而作。如彼飞虫，时亦弋获。既之阴女，反予来赫。
民之罔极，职凉善背。为民不利，如云不克。民之回遹，职竞用力。
民之未戾，职盗为寇。凉曰不可，覆背善詈。虽曰匪予，既作尔歌！','',''),('shijing-258','云汉','','shijing','','大雅 · 荡之什','倬彼云汉，昭回于天。王曰：于乎！何辜今之人？天降丧乱，饥馑荐臻。
靡神不举，靡爱斯牲。圭壁既卒，宁莫我听？
旱既大甚，蕴隆虫虫。不殄禋祀，自郊徂宫。上下奠瘗，靡神不宗。
后稷不克，上帝不临。耗斁下土，宁丁我梗
旱既大甚，则不可推。兢兢业业，如霆如雷。周余黎民，靡有孑遗。
昊天上帝，则不我遗。胡不相畏？先祖于摧。
旱既大甚，则不可沮。赫赫炎炎，云我无所。大命近止，靡瞻靡顾。
群公先正，则不我助。父母先祖，胡宁忍予？
旱既大甚，涤涤山川。旱魃为虐，如惔如焚。我心惮暑，忧心如熏。
群公先正，则不我闻。昊天上帝，宁俾我遁？
旱既大甚，黾勉畏去。胡宁瘨我以旱？憯不知其故。祈年孔夙，方社不莫。
昊天上帝，则不我虞。
敬恭明神，宜无悔怒。旱既大甚，散无友纪。鞫哉庶正，疚哉冢宰。
趣马师氏，膳夫左右。靡人不周。无不能止，瞻昂昊天，云如何里！
瞻昂昊天，有嘒其星。大夫君子，昭假无赢。大命近止，无弃尔成。
何求为我。以戾庶正。瞻昂昊天，曷惠其宁？','',''),('shijing-259','崧高','','shijing','','大雅 · 荡之什','崧高维岳，骏极于天。维岳降神，生甫及申。维申及甫，维周之翰。四国于蕃。四方于宣。
亹亹申伯，王缵之事。于邑于谢，南国是式。王命召伯，定申伯之宅。登是南邦，世执其功。
王命申伯，式是南邦。因是谢人，以作尔庸。王命召伯，彻申伯土田。王命傅御，迁其私人。
申伯之功，召伯是营。有俶其城，寝庙既成。既成藐藐，王锡申伯。四牡蹻蹻，钩膺濯濯。
王遣申伯，路车乘马。我图尔居，莫如南土。锡尔介圭，以作尔宝。往近王舅，南土是保。
申伯信迈，王饯于郿。申伯还南，谢于诚归。王命召伯，彻申伯土疆。以峙其粻，式遄其行。
申伯番番，既入于谢。徒御啴啴。周邦咸喜，戎有良翰。不显申伯，王之元舅，文武是宪。
申伯之德，柔惠且直。揉此万邦，闻于四国。吉甫作诵，其诗孔硕。其风四好，以赠申伯。','',''),('shijing-260','烝民','','shijing','','大雅 · 荡之什','天生烝民，有物有则。民之秉彝，好是懿德。天监有周，昭假于下。保兹天子，生仲山甫。
仲山甫之德，柔嘉维则。令仪令色。小心翼翼。古训是式。威仪是力。天子是若，明命使赋。
王命仲山甫，式是百辟，缵戎祖考，王躬是保。出纳王命，王之喉舌。赋政于外，四方爰发。
肃肃王命，仲山甫将之。邦国若否，仲山甫明之。既明且哲，以保其身。夙夜匪解，以事一人。
人亦有言，柔则茹之，刚则吐之。维仲山甫，柔亦不茹，刚亦不吐。不侮矜寡，不畏强御。
人亦有言，德輶如毛，民鲜克举之。我仪图之，维仲山甫举之。爱莫助之。衮职有阙，维仲山甫补之。
仲山甫出祖。四牡业业。征夫捷捷，每怀靡及。四牡彭彭，八鸾锵锵。王命仲山甫，城彼东方。
四牡骙骙，八鸾喈喈。仲山甫徂齐，式遄其归。吉甫作诵，穆如清风。仲山甫永怀，以慰其心。','',''),('shijing-261','韩奕','','shijing','','大雅 · 荡之什','奕奕梁山，维禹甸之，有倬其道。
韩侯受命，王亲命之：缵戎祖考，无废朕命。
夙夜匪解，虔共尔位，朕命不易。
粲不庭方，以佐戎辟。四牡奕奕，孔修且张。
韩侯入觐，以其介圭，入觐于王。
王锡韩侯，淑旗绥章，簟茀错衡。
玄衮赤舄，钩膺镂锡，鞹鞃浅幭，鞗革金厄。
韩侯出祖，出宿于屠。显父饯之，清酒百壶。
其肴维何？炮鳖鲜鱼。其蔌维何？维笋及蒲。
其赠维何？乘马路车。笾豆有且。侯氏燕胥。
韩侯取妻，汾王之甥，蹶父之子。
韩侯迎止，于蹶之里。
百两彭彭，八鸾锵锵，不显其光。
诸娣从之，祁祁如云。韩侯顾之，烂其盈门。
蹶父孔武，靡国不到。为韩姞相攸，莫如韩乐。
孔乐韩土，川泽訏訏，鲂鱮甫甫，麀鹿噳噳。
有熊有罴，有猫有虎。庆既令居，韩姞燕誉。
溥彼韩城，燕师所完。以先祖受命，因时百蛮。
王锡韩侯，其追其貊。奄受北国，因以其伯。
实墉实壑，实亩实藉。献其貔皮，赤豹黄罴。','',''),('shijing-262','江汉','','shijing','','大雅 · 荡之什','江汉浮浮，武夫滔滔。匪安匪游，淮夷来求。既出我车，既设我旟。匪安匪舒，淮夷来铺。
江汉汤汤，武夫洸洸。经营四方，告成于王。四方既平，王国庶定。时靡有争，王心载宁。
江汉之浒，王命召虎：式辟四方，彻我疆土。匪疚匪棘，王国来极。于疆于理，至于南海。
王命召虎：来旬来宣。文武受命，召公维翰。无曰予小子，召公是似。肇敏戎公，用锡尔祉。
厘尔圭瓒，秬鬯一卣。告于文人，锡山土田。于周受命，自召祖命，虎拜稽首：天子万年！
虎拜稽首，对扬王休。作召公考：天子万寿！明明天子，令闻不已，矢其文德，洽此四国。','',''),('shijing-263','常武','','shijing','','大雅 · 荡之什','赫赫明明。王命卿士，南仲大祖，大师皇父。整我六师，以修我戎。既敬既戒，惠此南国。
王谓尹氏，命程伯休父，左右陈行。戒我师旅，率彼淮浦，省此徐土。不留不处，三事就绪。
赫赫业业，有严天子。王舒保作，匪绍匪游。徐方绎骚，震惊徐方。如雷如霆，徐方震惊。
王奋厥武，如震如怒。进厥虎臣，阚如虓虎。铺敦淮濆，仍执丑虏。截彼淮浦，王师之所。
王旅啴啴，如飞如翰。如江如汉，如山之苞。如川之流，绵绵翼翼。不测不克，濯征徐国。
王犹允塞，徐方既来。徐方既同，天子之功。四方既平，徐方来庭。徐方不回，王曰还归。','',''),('shijing-264','瞻昂','','shijing','','大雅 · 荡之什','瞻昂昊天，则不我惠。孔填不宁，降此大厉。邦靡有定，士民其瘵。
蟊贼蟊疾，靡有夷届。罪罟不收，靡有夷瘳。
人有土田，女反有之。人有民人，女覆夺之。此宜无罪，女反收之。
彼宜有罪，女覆说之。
哲夫成城，哲妇倾城。懿厥哲妇，为枭为鸱。妇有长舌，维厉之阶。
乱匪降自天，生自妇人。匪教匪诲，时维妇寺。
鞫人忮忒。谮始竞背。岂曰不极？伊胡为慝？如贾三倍，君子是识。
妇无公事，休其蚕织。
天何以剌？何神不富？舍尔介狄，维予胥忌。不吊不祥，威仪不类。
人之云亡，邦国殄瘁。
天之降罔，维其优矣。人之云亡，心之忧矣。天之降罔，维其几矣。
人之云亡，心之悲矣。
觱沸槛泉，维其深矣。心之忧矣，宁自今矣？不自我先，不自我后。
藐藐昊天，无不克巩。无忝皇祖，式救尔后。','',''),('shijing-265','召旻','','shijing','','大雅 · 荡之什','旻天疾威，天笃降丧。瘨我饥馑，民卒流亡。我居圉卒荒。
天降罪罟，蟊贼内讧。昏椓靡共，溃溃回遹，实靖夷我邦。
皋皋訿訿，曾不知其玷。兢兢业业，孔填不宁，我位孔贬。
如彼岁旱，草不溃茂，如彼栖苴。我相此邦，无不溃止。
维昔之富不如时，维今之疚不如兹。彼疏斯粺，胡不自替？职兄斯引。
池之竭矣，不云自频。泉之竭矣，不云自中。溥斯害矣，职兄斯弘，不灾我躬。
昔先王受命，有如召公，日辟国百里，今也日蹙国百里。于乎哀哉！维今之人，不尚有旧！','',''),('shijing-266','清庙','','shijing','','周颂 · 清庙之什','于穆清庙，肃雍显相。济济多士，秉文之德。对越在天，骏奔走在庙。不显不承，无射于人斯。','',''),('shijing-267','维天之命','','shijing','','周颂 · 清庙之什','维天之命，于穆不已。于乎不显，文王之德之纯。假以溢我，我其收之。骏惠我文王，曾孙笃之。','',''),('shijing-268','维清','','shijing','','周颂 · 清庙之什','维清缉熙，文王之典。肇禋，迄用有成，维周之祯。','',''),('shijing-269','烈文','','shijing','','周颂 · 清庙之什','烈文辟公，锡兹祉福。惠我无疆，子孙保之。无封靡于尔邦，维王其崇之。
念兹戎功，继序其皇之。无竞维人，四方其训之。不显维德，百辟其刑之。于乎，前王不忘！','',''),('shijing-270','天作','','shijing','','周颂 · 清庙之什','天作高山，大王荒之。彼作矣，文王康之。彼徂矣，岐有夷之行。子孙保之。','',''),('shijing-271','昊天有成命','','shijing','','周颂 · 清庙之什','昊天有成命，二后受之。成王不敢康，夙夜基命宥密。于缉熙！单厥心，四其靖之。','',''),('shijing-272','我将','','shijing','','周颂 · 清庙之什','我将我享，维羊维牛，维天其右之。仪式刑文王之典，日靖四方。
伊嘏文王，既右飨之。我其夙夜，畏天之威，于时保之。','',''),('shijing-273','时迈','','shijing','','周颂 · 清庙之什','时迈其邦，昊天其子之，实右序有周。薄言震之，莫不震叠。怀柔百神，及河乔岳，允王维后。
明昭有周，式序在位。载戢干戈，载橐弓矢。我求懿德，四于时夏，允王保之。','',''),('shijing-274','执竞','','shijing','','周颂 · 清庙之什','执竞武王，无竞维烈。不显成康，上帝是皇。自彼成康，奄有四方，斤斤其明。
钟鼓喤喤，磬莞将将，降福穰穰。降福简简，威仪反反。既醉既饱，福禄来反。','',''),('shijing-275','思文','','shijing','','周颂 · 清庙之什','思文后稷，克配彼天。立我烝民，莫菲尔极。贻我来牟，帝命率育，无此疆尔界。陈常于时夏。','',''),('shijing-276','臣工','','shijing','','周颂 · 臣工之什','嗟嗟臣工，敬尔在公。王厘尔成，来咨来茹。嗟嗟保介，维莫之春，亦又何求？如何新畲？
于皇来牟，将受厥明。明昭上帝，迄用康年。命我众人：庤乃钱镈，奄观铚艾。','',''),('shijing-277','噫嘻','','shijing','','周颂 · 臣工之什','噫嘻成王，既昭假尔。率时农夫，播厥百谷。骏发尔私，终三十里。亦服尔耕，十千维耦。','',''),('shijing-278','振鹭','','shijing','','周颂 · 臣工之什','振鹭于飞，于彼西雍。我客戾止，亦有斯容。在彼无恶，在此无斁。庶几夙夜，以永终誉。','',''),('shijing-279','丰年','','shijing','','周颂 · 臣工之什','丰年多黍多稌，亦有高廪，万亿及秭。为酒为醴，烝畀祖妣。以洽百礼，降福孔皆。','',''),('shijing-280','有瞽','','shijing','','周颂 · 臣工之什','有瞽有瞽，在周之庭。设业设虡，崇牙树羽。应田县鼓，鞉磬柷圉。既备
乃奏，箫管备举。喤喤厥声，肃雍和鸣，先祖是听。我客戾止，永观厥成。','',''),('shijing-281','潜','','shijing','','周颂 · 臣工之什','猗与漆沮，潜有多鱼。有鳣有鲔，鲦鲿鰋鲤。以享以祀，以介景福。','',''),('shijing-282','雝','','shijing','','周颂 · 臣工之什','有来雝雝，至止肃肃。相维辟公，天子穆穆。于荐广牡，相予四祀。假哉皇考！绥予孝子。
宣哲维人，文武维后。燕及皇天，克昌厥后。绥我眉寿，介以繁祉，既右烈考，亦右文母。','',''),('shijing-283','载见','','shijing','','周颂 · 臣工之什','载见辟王，曰求厥章。龙旗阳阳，和铃央央。鞗革有鸧，休有烈光。率见昭考，以孝以享。
以介眉寿，永言保之，思皇多祜。烈文辟公，绥以多福，俾缉熙于纯嘏。','',''),('shijing-284','有客','','shijing','','周颂 · 臣工之什','有客有客，亦白其马。有萋有且，敦琢其旅。有客宿宿，有客信信。
言授之絷，以絷其马。薄言追之，左右绥之。既有淫威，降福孔夷。','',''),('shijing-285','武','','shijing','','周颂 · 臣工之什','于皇武王！无竞维烈。允文文王，克开厥后。嗣武受之，胜殷遏刘，耆定尔功。','',''),('shijing-286','闵予小子','','shijing','','周颂 · 闵予小子之什','闵予小子，遭家不造，嬛嬛在疚。于乎皇考，永世克孝。
念兹皇祖，陟降庭止。维予小子，夙夜敬止。于乎皇王，继序思不忘。','',''),('shijing-287','访落','','shijing','','周颂 · 闵予小子之什','访予落止，率时昭考。于乎悠哉，朕未有艾。将予就之，继犹判涣。
维予小子，未堪家多难。绍庭上下，陟降厥家。休矣皇考，以保明其身。','',''),('shijing-288','敬之','','shijing','','周颂 · 闵予小子之什','敬之敬之，天维显思，命不易哉。无曰高高在上，陟降厥士，日监在兹。
维予小子，不聪敬止。日就月将，学有缉熙于光明。佛时仔肩，示我显德行。','',''),('shijing-289','小毖','','shijing','','周颂 · 闵予小子之什','予其惩，而毖后患。莫予荓蜂，自求辛螫。肇允彼桃虫，拚飞维鸟。未堪家多难，予又集于蓼。','',''),('shijing-290','载芟','','shijing','','周颂 · 闵予小子之什','载芟载柞，其耕泽泽。千耦其耘，徂隰徂畛。侯主侯伯，侯亚侯旅，侯彊侯以。
有嗿其馌，思媚其妇，有依其士。有略其耜，俶载南亩，播厥百谷。实函斯活，驿驿其达。
有厌其杰，厌厌其苗，绵绵其麃。载获济济，有实其积，万亿及秭。为酒为醴，烝畀祖妣，不洽百礼。
有飶其香。邦家之光。有椒其馨，胡考之宁。匪且有且，匪今斯今，振古如兹。','',''),('shijing-291','良耜','','shijing','','周颂 · 闵予小子之什','畟畟良耜，俶载南亩。播厥百谷，实函斯活。或来瞻女，载筐及莒，其馕伊黍。
其笠伊纠，其镈斯赵，以薅荼蓼。荼蓼朽止，黍稷茂止。获之挃挃，积之栗栗。
其崇如墉，其比如栉。以开百室，百室盈止，妇子宁止。杀时犉牡，有捄其角。以似以续，续古之人。','',''),('shijing-292','丝衣','','shijing','','周颂 · 闵予小子之什','丝衣其紑，载弁俅俅。自堂徂基，自羊徂牛，鼐鼎及鼒，兕觥其觩。旨酒思柔。不吴不敖，胡考之休。','',''),('shijing-293','酌','','shijing','','周颂 · 闵予小子之什','于铄王师，遵养时晦。时纯熙矣，是用大介。我龙受之，蹻蹻王之造。载用有嗣，实维尔公允师。','',''),('shijing-294','桓','','shijing','','周颂 · 闵予小子之什','绥万邦，屡丰年。天命匪解，桓桓武王。保有厥士，于以四方，克定厥家。于昭于天，皇以间之。','',''),('shijing-295','赉','','shijing','','周颂 · 闵予小子之什','文王既勤止，我应受之。敷时绎思，我徂维求定。时周之命，于绎思。','',''),('shijing-296','般','','shijing','','周颂 · 闵予小子之什','于皇时周！陟其高山，嶞山乔岳，允犹翕河。敷天之下，裒时之对。时周之命。','',''),('shijing-297','駉','','shijing','','鲁颂 · 駉之什','駉駉牡马，在坰之野。薄言駉者，有驈有皇，有骊有黄，以车彭彭。思无疆思，马斯臧。
駉駉牡马，在坰之野。薄言駉者，有骓有駓，有骍有骐，以车伾伾。思无期思，马斯才。
駉駉牡马，在坰之野。溥言駉者，有驒有骆，有骝有雒，以车绎绎。思无斁思，马斯作。
駉駉牡马，在坰之野。薄言駉者，有骃有騢，有驔有鱼，以车祛祛。思无邪思，马斯徂。','',''),('shijing-298','有駜','','shijing','','鲁颂 · 駉之什','有駜有駜，駜彼乘黄。夙夜在公，在公明明。振振鹭，鹭于下。鼓咽咽，醉言舞。于胥乐兮！
有駜有駜，駜彼乘牡。夙夜在公，在公饮酒。振振鹭，鹭于飞。鼓咽咽，醉言归。于胥乐兮！
有駜有駜，駜彼乘駽。夙夜在公，在公载燕。自今以始，岁其有。君子有谷，诒孙子。于胥乐兮！','',''),('shijing-299','泮水','','shijing','','鲁颂 · 駉之什','思乐泮水，薄采其芹。鲁侯戾止，言观其旗。其旗茷茷，鸾声哕哕。无小无大，从公于迈。
思乐泮水，薄采其藻。鲁侯戾止，其马蹻蹻。其马蹻蹻，其音昭昭。载色载笑，匪怒伊教。
思乐泮水，薄采其茆。鲁侯戾止，在泮饮酒。既饮旨酒，永锡难老。顺彼长道，屈此群丑。
穆穆鲁侯，敬明其德。敬慎威仪，维民之则。允文允武，昭假烈祖。靡有不孝，自求伊祜。
明明鲁侯，克明其德。既作泮宫，淮夷攸服。矫矫虎臣，在泮献馘。淑问如皋陶，在泮献囚。
济济多士，克广德心。桓桓于征，狄彼东南。烝烝皇皇，不吴不扬。不告于讻，在泮献功。
角弓其觩。束矢其搜。戎车孔博。徒御无斁。既克淮夷，孔淑不逆。式固尔犹，淮夷卒获。
翩彼飞鸮，集于泮林。食我桑黮，怀我好音。憬彼淮夷，来献其琛。元龟象齿，大赂南金。','',''),('shijing-300','閟宫','','shijing','','鲁颂 · 駉之什','閟宫有侐，实实枚枚。赫赫姜嫄，其德不回。上帝是依，无灾无害。
弥月不迟，是生后稷。降之百福。黍稷重穋，稙稚菽麦。奄有下国，俾民稼穑。
有稷有黍，有稻有秬。奄有下土，缵禹之绪。后稷之孙，实维大王。
居岐之阳，实始剪商。至于文武，缵大王之绪，致天之届，于牧之野。
无二无虞，上帝临女。敦商之旅，克咸厥功。王曰叔父，建尔元子，俾侯于鲁。
大启尔宇，为周室辅。乃命鲁公，俾侯于东。锡之山川，土田附庸。
周公之孙，庄公之子。龙旗承祀。六辔耳耳。春秋匪解，享祀不忒。
皇皇后帝！皇祖后稷！享以骍牺，是飨是宜。降福既多，周公皇祖，亦其福女。
秋而载尝，夏而楅衡，白牡骍刚。牺尊将将，毛炮胾羹。笾豆大房，万舞洋洋。
孝孙有庆。俾尔炽而昌，俾尔寿而臧。保彼东方，鲁邦是尝。不亏不崩，不震不腾。
三寿作朋，如冈如陵。公车千乘，朱英绿縢。二矛重弓。公徒三万，贝胄朱綅。
烝徒增增，戎狄是膺，荆舒是惩，则莫我敢承！俾尔昌而炽，俾尔寿而富。
黄发台背，寿胥与试。俾尔昌而大，俾尔耆而艾。万有千岁，眉寿无有害。
泰山岩岩，鲁邦所詹。奄有龟蒙，遂荒大东。至于海邦，淮夷来同。
莫不率从，鲁侯之功。保有凫绎，遂荒徐宅。至于海邦，淮夷蛮貊。
及彼南夷，莫不率从。莫敢不诺，鲁侯是若。天锡公纯嘏，眉寿保鲁。
居常与许，复周公之宇。鲁侯燕喜，令妻寿母。宜大夫庶士，邦国是有。
既多受祉，黄发儿齿。徂徕之松，新甫之柏。是断是度，是寻是尺。
松桷有舄，路寝孔硕，新庙奕奕。奚斯所作，孔曼且硕，万民是若。','',''),('shijing-301','那','','shijing','','商颂 · 那之什','猗与那与！置我鞉鼓。奏鼓简简，衎我烈祖。汤孙奏假，绥我思成。
鞉鼓渊渊，嘒嘒管声。既和且平，依我磬声。于赫汤孙！穆穆厥声。
庸鼓有斁，万舞有奕。我有嘉客，亦不夷怿。自古在昔，先民有作。
温恭朝夕，执事有恪，顾予烝尝，汤孙之将。','',''),('shijing-302','烈祖','','shijing','','商颂 · 那之什','嗟嗟烈祖！有秩斯祜。申锡无疆，及尔斯所。既载清酤，赉我思成。
亦有和羹，既戒既平。鬷假无言，时靡有争。绥我眉寿，黄耇无疆。
约軧错衡，八鸾鸧鸧。以假以享，我受命溥将。自天降康，丰年穰穰。
来假来飨，降福无疆。顾予烝尝，汤孙之将。','',''),('shijing-303','玄鸟','','shijing','','商颂 · 那之什','天命玄鸟，降而生商，宅殷土芒芒。古帝命武汤，正域彼四方。
方命厥后，奄有九有。商之先后，受命不殆，在武丁孙子。武丁孙子，武王靡不胜。
龙旗十乘，大糦是承。邦畿千里，维民所止，肇域彼四海。
四海来假，来假祁祁。景员维河。殷受命咸宜，百禄是何。','',''),('shijing-304','长发','','shijing','','商颂 · 那之什','浚哲维商，长发其祥。洪水芒芒，禹敷下土方。外大国是疆，幅陨既长。有娀方将，帝立子生商。
玄王桓拨，受小国是达，受大国是达。率履不越，遂视既发。相士烈烈。海外有截。
帝命不违，至于汤齐。汤降不迟，圣敬日跻。昭假迟迟，上帝是祗，帝命式于九围。
受小球大球，为下国缀旒，何天之休。不竞不絿，不刚不柔。敷政优优。百禄是遒。
受小共大共，为下国骏厖。何天之龙，敷奏其勇。不震不动，不戁不竦，百禄是总。
武王载旆，有虔秉钺。如火烈烈，则莫我敢曷。苞有三蘖，莫遂莫达。九有有截，韦顾既伐，昆吾夏桀。
昔在中叶，有震且业。允也天子，降予卿士。实维阿衡，实左右商王。','',''),('shijing-305','殷武','','shijing','','商颂 · 那之什','挞彼殷武，奋伐荆楚。深入其阻，裒荆之旅。有截其所，汤孙之绪。
维女荆楚，居国南乡。昔有成汤，自彼氐羌，莫敢不来享，莫敢不来王。曰商是常。
天命多辟，设都于禹之绩。岁事来辟，勿予祸适，稼穑匪解。
天命降监，下民有严。不僭不滥，不敢怠遑。命于下国，封建厥福。
商邑翼翼，四方之极。赫赫厥声，濯濯厥灵。寿考且宁，以保我后生。
陟彼景山，松伯丸丸。是断是迁，方斫是虔。松桷有梴，旅楹有闲，寝成孔安。','',''),('chuci-001','离骚','屈原','chuci','','离骚','帝高阳之苗裔兮，朕皇考曰伯庸。
