屯余车其千乘兮，齐玉轪而并驰。
驾八龙之婉婉兮，载云旗之委蛇。
抑志而弭节兮，神高驰之邈邈。
奏《九歌》而舞《韶》兮，聊假日以偷乐。
陟升皇之赫戏兮，忽临睨夫旧乡。
仆夫悲余马怀兮，蜷局顾而不行。
乱曰：已矣哉！国无人莫我知兮，又何怀乎故都！
既莫足与为美政兮，吾将从彭咸之所居！','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('chuci-002','东皇太一','屈原','chuci','','九歌','吉日兮辰良，穆将愉兮上皇
抚长剑兮玉珥，璆锵鸣兮琳琅
瑶席兮玉瑱，盍将把兮琼芳
蕙肴蒸兮兰藉，奠桂酒兮椒浆
扬枹兮拊鼓，疏缓节兮安歌
陈竽瑟兮浩倡
灵偃蹇兮姣服，芳菲菲兮满堂
五音纷兮繁会，君欣欣兮乐康。','',''),('chuci-003','云中君','屈原','chuci','','九歌','浴兰汤兮沐芳，华采衣兮若英
灵连蜷兮既留，烂昭昭兮未央
謇将憺兮寿宫，与日月兮齐光
龙驾兮帝服，聊翱游兮周章
灵皇皇兮既降，猋远举兮云中
览冀洲兮有余，横四海兮焉穷
思夫君兮太息，极劳心兮忡忡','',''),('chuci-004','湘君','屈原','chuci','','九歌','君不行兮夷犹，蹇谁留兮中洲
美要眇兮宜修，沛吾乘兮桂舟
令沅湘兮无波，使江水兮安流
望夫君兮未来，吹参差兮谁思
驾飞龙兮北征，邅吾道兮洞庭
薜荔柏兮蕙绸，荪桡兮兰旌
望涔阳兮极浦，横大江兮扬灵
扬灵兮未极，女婵媛兮为余太息
横流涕兮潺湲，隐思君兮陫侧
桂棹兮兰枻，斵冰兮积雪
采薜荔兮水中，搴芙蓉兮木末
心不同兮媒劳，恩不甚兮轻绝
石濑兮浅浅，飞龙兮翩翩
交不忠兮怨长，期不信兮告余以不闲
朝骋骛兮江皋，夕弭节兮北渚
鸟次兮屋上，水周兮堂下
捐余玦兮江中，遗余佩兮醴浦
采芳洲兮杜若，将以遗兮下女
时不可兮再得，聊逍遥兮容与。','',''),('chuci-005','湘夫人','屈原','chuci','','九歌','帝子降兮北渚，目眇眇兮愁予
袅袅兮秋风，洞庭波兮木叶下
登白薠兮骋望，与佳期兮夕张
鸟何萃兮苹中，罾何为兮木上？
沅有茝兮醴有兰，思公子兮未敢言
荒忽兮远望，观流水兮潺湲
麋何食兮庭中，蛟何为兮水裔
朝驰余马兮江皋，夕济兮西澨
闻佳人兮召余，将腾驾兮偕逝
筑室兮水中，葺之兮荷盖
荪壁兮紫坛，播芳椒兮成堂
桂栋兮兰橑，辛夷楣兮药房
罔薜荔兮为帷，擗蕙櫋兮既张
白玉兮为镇，疏石兰兮为芳
芷葺兮荷屋，缭之兮杜衡
合百草兮实庭，建芳馨兮庑门
九嶷缤兮并迎，灵之来兮如云
捐余袂兮江中，遗余褋兮醴浦
搴汀洲兮杜若，将以遗兮远者
时不可兮骤得，聊逍遥兮容与！','',''),('chuci-006','大司命','屈原','chuci','','九歌','广开兮天门，纷吾乘兮玄云
令飘风兮先驱，使涷雨兮洒尘
君回翔兮以下，逾空桑兮从女
纷总总兮九州，何寿夭兮在予
高飞兮安翔，乘清气兮御阴阳
吾与君兮齐速，导帝之兮九坑
灵衣兮被被，玉佩兮陆离
一阴兮一阳，众莫知兮余所为
折疏麻兮瑶华，将以遗兮离居
老冉冉兮既极，不寖近兮愈疏
乘龙兮辚辚，高驰兮冲天
结桂枝兮延伫，羌愈思兮愁人
愁人兮奈何，愿若今兮无亏
固人命兮有当，孰离合兮何为？','',''),('chuci-007','少司命','屈原','chuci','','九歌','秋兰兮麋芜，罗生兮堂下
绿叶兮素华，芳菲菲兮袭予
夫人兮自有美子，荪何以兮愁苦
秋兰兮青青，绿叶兮紫茎
满堂兮美人，忽独与余兮目成
入不言兮出不辞，乘回风兮载云旗
悲莫悲兮生别离，乐莫乐兮新相知
荷衣兮蕙带，儵而来兮忽而逝
夕宿兮帝郊，君谁须兮云之际
与女沐兮咸池，曦女发兮阳之阿
望美人兮未来，临风怳兮浩歌
孔盖兮翠旌，登九天兮抚彗星
竦长剑兮拥幼艾，荪独宜兮为民正。','',''),('chuci-008','东君','屈原','chuci','','九歌','暾将出兮东方，照吾槛兮扶桑
抚余马兮安驱，夜皎皎兮既明
驾龙輈兮乘雷，载云旗兮委蛇
长太息兮将上，心低徊兮顾怀
羌声色兮娱人，观者儋兮忘归
縆瑟兮交鼓，萧钟兮瑶簴
鸣篪兮吹竽，思灵保兮贤姱
翾飞兮翠曾，展诗兮会舞
应律兮合节，灵之来兮敝日
青云衣兮白霓裳，举长矢兮射天狼
操余弧兮反沦降，援北斗兮酌桂浆
撰余辔兮高驰翔，杳冥冥兮以东行。','',''),('chuci-009','河伯','屈原','chuci','','九歌','与女游兮九河，冲风起兮水扬波
乘水车兮荷盖，驾两龙兮骖螭
登昆仑兮四望，心飞扬兮浩荡
日将暮兮怅忘归，惟极浦兮寤怀
鱼鳞屋兮龙堂，紫贝阙兮珠宫
灵何惟兮水中
乘白鼋兮逐文鱼，与女游兮河之渚
流澌纷兮将来下
子交手兮东行，送美人兮南浦
波滔滔兮来迎，鱼鳞鳞兮媵予。','',''),('chuci-010','山鬼','屈原','chuci','','九歌','若有人兮山之阿，被薜荔兮带女萝
既含睇兮又宜笑，子慕予兮善窈窕
乘赤豹兮从文狸，辛夷车兮结桂旗
被石兰兮带杜衡，折芬馨兮遗所思
余处幽篁兮终不见天，路险难兮独后来
表独立兮山之上，云容容兮而在下
杳冥冥兮羌昼晦，东风飘兮神灵雨
留灵修兮憺忘归，岁既晏兮孰华予
采三秀兮于山间，石磊磊兮葛蔓蔓
怨公子兮怅忘归，君思我兮不得闲
山中人兮芳杜若，饮石泉兮荫松柏
君思我兮然疑作
雷填填兮雨冥冥，猿啾啾兮狖夜鸣
风飒飒兮木萧萧，思公子兮徒离忧。','',''),('chuci-011','国殇','屈原','chuci','','九歌','操吴戈兮被犀甲，车错毂兮短兵接
旌蔽日兮敌若云，矢交坠兮士争先
凌余阵兮躐余行，左骖殪兮右刃伤
霾两轮兮絷四马，援玉枹兮击鸣鼓
天时怼兮威灵怒，严杀尽兮弃原野
出不入兮往不反，平原忽兮路超远
带长剑兮挟秦弓，首身离兮心不惩
诚既勇兮又以武，终刚强兮不可凌
身既死兮神以灵，魂魄毅兮为鬼雄。','',''),('chuci-012','礼魂','屈原','chuci','','九歌','成礼兮会鼓，
传芭兮代舞
姱女倡兮容与
春兰兮秋菊，
长无绝兮终古。','',''),('chuci-013','天问','屈原','chuci','','天问','曰：
遂古之初，谁传道之？
上下未形，何由考之？
冥昭瞢暗，谁能极之？
冯翼惟象，何以识之？
明明暗暗，惟时何为？
阴阳三合，何本何化？
圜则九重，孰营度之？
惟兹何功，孰初作之？
斡维焉系，天极焉加？
八柱何当，东南何亏？
九天之际，安放安属？
隅隈多有，谁知其数？
天何所沓？
十二焉分？
日月安属？
列星安陈？
出自汤谷，次于蒙汜。
自明及晦，所行几里？
夜光何德，死则又育？
厥利维何，而顾菟在腹？
女岐无合，夫焉取九子？
伯强何处？
惠气安在？
何阖而晦？
何开而明？
角宿未旦，曜灵安藏？
不任汩鸿，师何以尚之？
佥曰
“何忧，何不课而行之？”
鸱龟曳衔，鲧何听焉？
顺欲成功，帝何刑焉？
永遏在羽山，夫何三年不施？
伯禹愎鲧，夫何以变化？
纂就前绪，遂成考功。
何续初继业，而厥谋不同？
洪泉极深，何以窴之？
地方九则，何以坟之？
河海应龙？
何尽何历？
鲧何所营？
禹何所成？
康回冯怒，墬何故以东南倾？
九州安错？
川谷何洿？
东流不溢，孰知其故？
东西南北，其修孰多？
南北顺椭，其衍几何？
昆仑悬圃，其尻安在？
增城九重，其高几里？
四方之门，其谁从焉？
西北辟启，何气通焉？
日安不到？
烛龙何照？
羲和之未扬，若华何光？
何所冬暖？
何所夏寒？
焉有石林？
何兽能言？
焉有虬龙，负熊以游？
雄虺九首，鯈忽焉在？
何所不死？
长人何守？
靡蓱九衢，枲华安居？
灵蛇吞象，厥大何如？
黑水玄趾，三危安在？
延年不死，寿何所止？
鲮鱼何所？
鬿堆焉处？
羿焉彃日？
乌焉解羽？
禹之力献功，降省下土四方。
焉得彼嵞山女，而通之于台桑？
闵妃匹合，厥身是继。
胡维嗜不同味，而快鼌饱？
启代益作后，卒然离蠥。
何启惟忧，而能拘是达？
皆归射鞫，而无害厥躬。
何后益作革，而禹播降？
启棘宾商，《九辨》《九歌》。
何勤子屠母，而死分竟地？
帝降夷羿，革孽夏民。
胡射夫河伯，而妻彼雒嫔？
冯珧利决，封豨是射。
何献蒸肉之膏，而后帝不若？
浞娶纯狐，眩妻爰谋。
何羿之射革，而交吞揆之？
阻穷西征，岩何越焉？
化而为黄熊，巫何活焉？
咸播秬黍，莆雚是营。
何由并投，而鲧疾修盈？
白霓婴茀，胡为此堂？
安得夫良药，不能固臧？
天式从横，阳离爰死。
大鸟何鸣，夫焉丧厥体？
蓱号起雨，何以兴之？
撰体协胁，鹿何膺之？
鳌戴山拚，何以安之？
释舟陵行，何之迁之？
惟浇在户，何求于嫂？
何少康逐犬，而颠陨厥首？
女歧缝裳，而馆同爰止。
何颠易厥首，而亲以逢殆？
汤谋易旅，何以厚之？
覆舟斟寻，何道取之？
桀伐蒙山，何所得焉？
妺嬉何肆，汤何殛焉？
舜闵在家，父何以鳏？
尧不姚告，二女何亲？
厥萌在初，何所亿焉？
璜台十成，谁所极焉？
登立为帝，孰道尚之？
女娲有体，孰制匠之？
舜服厥弟，终然为害。
何肆犬豕，而厥身不危败？
吴获迄古，南岳是止。
孰期去斯，得两男子？
缘鹄饰玉，后帝是飨。
何承谋夏桀，终以灭丧？
帝乃降观，下逢伊挚。
何条放致罚，而黎服大说？
简狄在台，喾何宜？
玄鸟致贻，女何喜？
该秉季德，厥父是臧。
胡终弊于有扈，牧夫牛羊？
干协时舞，何以怀之？
平胁曼肤，何以肥之？
有扈牧竖，云何而逢？
击床先出，其命何从？
恒秉季德，焉得夫朴牛？
何往营班禄，不但还来？
昏微循迹，有狄不宁。
何繁鸟萃棘，负子肆情？
眩弟并淫，危害厥兄。
何变化以作诈，而后嗣逢长？
成汤东巡，有莘爰极。
何乞彼小臣，而吉妃是得？
水滨之木，得彼小子。
夫何恶之，媵有莘之妇？
汤出重泉，夫何辠尤？
不胜心伐帝，夫谁使挑之？
会朝争盟，何践吾期？
苍鸟群飞，孰使萃之？
列击纣躬，叔旦不嘉。
何亲揆发足，周之命以咨嗟？
授殷天下，其位安施？
反成乃亡，其罪伊何？
争遣伐器，何以行之？
并驱击翼，何以将之？
昭后成游，南土爰底。
厥利惟何，逢彼白雉？
穆王巧梅，夫何为周流？
环理天下，夫何索求？
妖夫曳炫，何号于市？
周幽谁诛？
焉得夫褒姒？
天命反侧，何罚何佑？
齐桓九会，卒然身杀。
彼王纣之躬，孰使乱惑？
何恶辅弼，谗谄是服？
比干何逆，而抑沈之？
雷开阿顺，而赐封之？
何圣人之一德，卒其异方？
梅伯受醢，箕子详狂？
稷维元子，帝何竺之？
投之于冰上，鸟何燠之？
何冯弓挟矢，殊能将之？
既惊帝切激，何逢长之？
伯昌号衰，秉鞭作牧。
何令彻彼岐社，命有殷国？
迁藏就岐，何能依？
殷有惑妇，何所讥？
受赐兹醢，西伯上告。
何亲就上帝罚，殷之命以不救？
师望在肆，昌何识？
鼓刀扬声，后何喜？
武发杀殷，何所悒？
载尸集战，何所急？
伯林雉经，维其何故？
何感天抑墬，夫谁畏惧？
皇天集命，惟何戒之？
受礼天下，又使至代之？
初汤臣挚，后兹承辅。
何卒官汤，尊食宗绪？
勋阖梦生，少离散亡。
何壮武历，能流厥严？
彭铿斟雉，帝何飨？
受寿永多，夫何久长？
中央共牧，后何怒？
蜂蛾微命，力何固？
惊女采薇，鹿何佑？
北至回水，萃何喜？
兄有噬犬，弟何欲？
易之以百两，卒无禄？
薄暮雷电，归何忧？
厥严不奉，帝何求？
伏匿穴处，爰何云？
荆勋作师，夫何长？
悟过改更，我又何言？
吴光争国，久余是胜。
何环穿自闾社丘陵，爰出子文？
吾告堵敖以不长。
何试上自予，忠名弥彰？','',''),('chuci-014','惜诵','屈原','chuci','','九章','惜诵以致愍兮，发愤以抒情。
所作忠而言之兮，指苍天以为正。
令五帝使折中兮，戒六神与向服。
俾山川以备御兮，命咎繇使听直。
竭忠诚而事君兮，反离群而赘肬。
忘儇媚以背众兮，待明君其知之。
言与行其可迹兮，情与貌其不变。
故相臣莫若君兮，所以证之不远。
吾谊先君而后身兮，羌众人之所仇也。
专惟君而无他兮，又众兆之所雠也。
壹心而不豫兮，羌无可保也。
疾亲君而无他兮，有招祸之道也。
思君其莫我忠兮，忽忘身之贱贫。
事君而不贰兮，迷不知宠之门。
患何罪以遇罚兮，亦非余之所志也。
行不群以巅越兮，又众兆之所咍也。
纷逢尤以离谤兮，謇不可释也。
情沉抑而不达兮，又蔽而莫之白也。
心郁邑余侘傺兮，又莫察余之中情。
固烦言不可结而诒兮，愿陈志而无路。
退静默而莫余知兮，进号呼又莫吾闻。
申侘傺之烦惑兮，中闷瞀之忳忳。
昔余梦登天兮，魂中道而无杭。
吾使厉神占之兮，曰有志极而无旁。
终危独以离异兮，曰君可思而不可恃。
故众口其铄金兮，初若是而逢殆。
惩于羹者而吹齑兮，何不变此志也？
欲释阶而登天兮，犹有曩之态也。
众骇遽以离心兮，又何以为此伴也？
同极而异路兮，又何以为此援也？
晋申生之孝子兮，父信谗而不好。
