因气变而遂曾举兮，忽神奔而鬼怪。
时仿佛以遥见兮，精晈晈以往来。
超氛埃而淑邮兮，终不反其故都。
免众患而不惧兮，世莫知其所如。
恐天时之代序兮，耀灵晔而西征。
微霜降而下沦兮，悼芳草之先蘦。
聊仿佯而逍遥兮，永历年而无成。
谁可与玩斯遗芳兮？
长向风而舒情。
高阳邈以远兮，余将焉所程？
重曰：
春秋忽其不淹兮，奚久留此故居。
轩辕不可攀援兮，吾将从王乔而娱戏。
餐六气而饮沆瀣兮，漱正阳而含朝霞。
保神明之清澄兮，精气入而麤秽除。
顺凯风以从游兮，至南巢而壹息。
见王子而宿之兮，审壹气之和德。
曰“道可受兮，不可传
其小无内兮，其大无垠。
毋滑而魂兮，彼将自然
壹气孔神兮，于中夜存。
虚以待之存，无为之先
庶类以成兮，此德之门。”
闻至贵而遂徂兮，忽乎吾将行。
仍羽人于丹丘，留不死之旧乡。
朝濯发于汤谷兮，夕曦余身兮九阳。
吸飞泉之微液兮，怀琬琰之华英。
玉色頩以脕颜兮，精醇粹而始壮。
质销铄以汋约兮，神要眇以淫放。
嘉南州之炎德兮，丽桂树之冬荣
山萧条而无兽兮，野寂漠其无人。
载营魄而登霞兮，掩浮云而上征。
命天阍其开关兮，排阊阖而望予。
召丰隆使先导兮，问太微之所居。
集重阳入帝宫兮，造旬始而观清都。
朝发轫于太仪兮，夕始临乎于微闾。
屯余车之万乘兮，纷容与而并驰。
驾八龙之婉婉兮，载云旗之逶蛇。
建雄虹之采旄兮，五色杂而炫耀。
服偃蹇以低昂兮，骖连蜷以骄骜。
骑胶葛以杂乱兮，斑漫衍而方行。
撰余辔而正策兮，吾将过乎句芒。
历太皓以右转兮，前飞廉以启路。
阳杲杲其未光兮，凌天地以径度。
风伯为余先驱兮，氛埃辟而清凉。
凤凰翼其承旗兮，遇蓐收乎西皇。
揽慧星以为旍兮，举斗柄以为麾。
叛陆离其上下兮，游惊雾之流波。
时暧曃其曭莽兮，召玄武而奔属。
后文昌使掌行兮，选署众神以并毂。
路漫漫其修远兮，徐弭节而高厉。
