欲度世以忘归兮，意姿睢以抯挢。
内欣欣而自美兮，聊偷娱以淫乐。
涉青云以泛滥游兮，忽临睨夫旧乡。
仆夫怀余心悲兮，边马顾而不行。
思旧故以想象兮，长太息而掩涕。
汜容与而遐举兮，聊抑志而自弭。
