超无为以至清兮，与泰初而为邻。','',''),('chuci-024','卜居','屈原','chuci','','卜居','屈原既放，三年不得复见。竭知尽忠而蔽障于谗。心烦虑乱，不知所从。乃往见太卜郑詹尹曰：“余有所疑，愿因先生决之。”詹尹乃端策拂龟，曰：“君将何以教之？”
屈原曰：“吾宁悃悃款款，朴以忠乎，将送往劳来，斯无穷乎？宁诛锄草茅以力耕乎，将游大人以成名乎？宁正言不讳以危身乎，将从俗富贵以偷生乎？宁超然高举以保真乎，将哫訾栗斯，喔咿儒儿，以事妇人乎？宁廉洁正直以自清乎，将突梯滑稽，如脂如韦，以洁楹乎？宁昂昂若千里之驹乎，将泛泛若水中之凫，与波上下，偷以全吾躯乎？宁与骐骥亢轭乎，将随驽马之迹乎？宁与黄鹄比翼乎，将与鸡鹜争食乎？此孰吉孰凶？何去何从？世溷浊而不清：蝉翼为重，千钧为轻黄钟毁弃，瓦釜雷鸣谗人高张，贤士无名。吁嗟默默兮，谁知吾之廉贞！”
詹尹乃释策而谢曰：“夫尺有所短，寸有所长物有所不足，智有所不明数有所不逮，神有所不通。用君之心，行君之意。龟策诚不能知此事。”','',''),('chuci-025','渔父','屈原','chuci','','渔父','屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：“子非三闾大夫与？何故至于斯？”屈原曰：“举世皆浊我独清，众人皆醉我独醒，是以见放。”
渔父曰：“圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉，何不哺其糟而歠其醨？何故深思高举，自令放为？”
屈原曰：“吾闻之，新沐者必弹冠，新浴者必振衣安能以身之察察，受物之汶汶者乎？宁赴湘流，葬于江鱼之腹中。安能以皓皓之白，而蒙世俗之尘埃乎?”
渔父莞尔而笑，鼓枻而去。
乃歌曰：“沧浪之水清兮，可以濯吾缨。沧浪之水浊兮，可以濯吾足。”遂去，不复与言。','',''),('chuci-026','九辩','宋玉','chuci','','九辩','悲哉，秋之为气也！萧瑟兮草木摇落而变衰。
憭栗兮若在远行，登山临水兮送将归。
泬漻兮天高而气清，寂寥兮收潦而水清。
憯凄增欷兮，薄寒之中人，怆怳懭悢兮，去故而就新。
坎廪兮贫士失职而志不平，廓落兮羁旅而无友生，惆怅兮而私自怜！
燕翩翩其辞归兮，蝉寂漠而无声。
雁痈痈而南游兮，鹍鸡啁哳而悲鸣。
独申旦而不寐兮，哀蟋蟀之宵征。
时亹亹而过中兮，蹇淹留而无成。
悲忧穷戚兮独处廓，有美一人兮心不绎。
去乡离家兮来远客，超逍遥兮今焉薄！
专思君兮不可化，君不知兮可奈何！
蓄怨兮积思，心烦憺兮忘食事。
原一见兮道余意，君之心兮与余异。
车既驾兮朅而归，不得见兮心伤悲。
倚结軨兮长太息，涕潺湲兮下霑轼。
忼慨绝兮不得，中瞀乱兮迷惑。
