心怦怦兮谅直。
皇天平分四时兮，窃独悲此凛秋。
白露既下百草兮，奄离披此梧楸。
去白日之昭昭兮，袭长夜之悠悠。
离芳蔼之方壮兮，余萎约而悲愁。
秋既先戒以白露兮，冬又申之以严霜。
收恢台之孟夏兮，然欿傺而沉藏。
叶菸邑而无色兮，枝烦挐而交横。
