萷櫹椮之可哀兮，形销铄而瘀伤。
惟其纷糅而将落兮，恨其失时而无当。
揽騑辔而下节兮，聊逍遥以相佯。
岁忽忽而遒尽兮，恐余寿之弗将。
悼余生之不时兮，逢此世之俇攘。
澹容与而独倚兮，蟋蟀鸣此西堂。
