以为君独服此蕙兮，羌无以异于众芳。
闵奇思之不通兮，将去君而高翔。
心闵怜之惨凄兮，愿一见而有明。
重无怨而生离兮，中结轸而增伤。
岂不郁陶而思君兮？
君之门以九重！猛犬狺狺而迎吠兮，关梁闭而不通。
皇天淫溢而秋霖兮，后土何时而得漧？
块独守此无泽兮，仰浮云而永叹！何时俗之工巧兮？
