太公九十乃显荣兮，诚未遇其匹合。
谓骐骥兮安归？
谓凤皇兮安栖？
变古易俗兮世衰，今之相者兮举肥。
骐骥伏匿而不见兮，凤皇高飞而不下。
鸟兽犹知怀德兮，何云贤士之不处？
骥不骤进而求服兮，凤亦不贪餧而妄食。
