窃慕诗人之遗风兮，原讬志乎素餐。
蹇充倔而无端兮，泊莽莽而无垠。
无衣裘以御冬兮，恐溘死不得见乎阳春。
靓杪秋之遥夜兮，心缭悷而有哀。
春秋逴逴而日高兮，然惆怅而自悲。
