事亹亹而觊进兮，蹇淹留而踌躇。
何泛滥之浮云兮？
猋壅蔽此明月。
忠昭昭而原见兮，然霠曀而莫达。
原皓日之显行兮，云蒙蒙而蔽之。
窃不自聊而原忠兮，或黕点而污之。
尧舜之抗行兮，瞭冥冥而薄天。
何险巇之嫉妒兮？
被以不慈之伪名。
彼日月之照明兮，尚黯黮而有瑕。
何况一国之事兮，亦多端而胶加。
被荷裯之晏晏兮，然潢洋而不可带。
既骄美而伐武兮，负左右之耿介。
憎愠惀之修美兮，好夫人之慷慨。
众踥蹀而日进兮，美超远而逾迈。
农夫辍耕而容与兮，恐田野之芜秽。
事緜緜而多私兮，窃悼后之危败。
世雷同而炫曜兮，何毁誉之昧昧！
今修饰而窥镜兮，后尚可以窜藏。
愿寄言夫流星兮，羌倏忽而难当。
卒壅蔽此浮云，下暗漠而无光。
尧舜皆有所举任兮，故高枕而自适。
谅无怨于天下兮，心焉取此怵惕？
乘骐骥之浏浏兮，驭安用夫强策？
谅城郭之不足恃兮，虽重介之何益？
邅翼翼而无终兮，忳惛惛而愁约。
生天地之若过兮，功不成而无嶜。
原沉滞而不见兮，尚欲布名乎天下。
然潢洋而不遇兮，直怐愗而自苦。
莽洋洋而无极兮，忽翱翔之焉薄？
