罔流涕以聊虑兮，惟着意而得之。
纷纯纯之愿忠兮，妒被离而鄣之。
原赐不肖之躯而别离兮，放游志乎云中。
乘精气之抟抟兮，骛诸神之湛湛。
骖白霓之习习兮，历群灵之丰丰。
左朱雀之茇茇兮，右苍龙之躣躣。
