计专专之不可化兮，原遂推而为臧。
赖皇天之厚德兮，还及君之无恙！','',''),('chuci-027','招魂','宋玉','chuci','','招魂','朕幼清以廉洁兮，身服义而未沫。
主此盛德兮，牵于俗而芜秽。
上无所考此盛德兮，长离殃而愁苦。
帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”
巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”
巫阳焉乃下招曰：魂兮归来！去君之恒干，何为四方些？
舍君之乐处，而离彼不祥些！魂兮归来！东方不可以讬些。
长人千仞，惟魂是索些。
十日代出，流金铄石些。
彼皆习之，魂往必释些。
归来兮！不可以讬些。
