雕题黑齿，得人肉以祀，以其骨为醢些。
蝮蛇蓁蓁，封狐千里些。
雄虺九首，往来倏忽，吞人以益其心些。
归来兮！不可久淫些。
魂兮归来！西方之害，流沙千里些。
旋入雷渊，爢散而不可止些。
