赤蚁若象，玄蜂若壶些。
五谷不生，丛菅是食些。
其土烂人，求水无所得些。
彷徉无所倚，广大无所极些。
归来兮！恐自遗贼些。
魂兮归来！北方不可以止些。
增冰峨峨，飞雪千里些。
归来兮！不可以久些。
