魂兮归来！君无下此幽都些。
土伯九约，其角觺觺些。
敦脄血拇，逐人伂駓駓些。
参目虎首，其身若牛些。
此皆甘人，归来！恐自遗灾些。
魂兮归来！入修门些。
工祝招君，背行先些。
秦篝齐缕，郑绵络些。
招具该备，永啸呼些。
魂兮归来！反故居些。
天地四方，多贼奸些。
像设君室，静闲安些。
高堂邃宇，槛层轩些。
层台累榭，临高山些。
网户朱缀，刻方连些。
冬有穾厦，夏室寒些。
川谷径复，流潺湲些。
光风转蕙，泛崇兰些。
经堂入奥，朱尘筵些。
砥室翠翘，挂曲琼些。
翡翠珠被，烂齐光些。
蒻阿拂壁，罗帱张些。
纂组绮缟，结琦璜些。
室中之观，多珍怪些。
兰膏明烛，华容备些。
二八侍宿，射递代些。
九侯淑女，多迅众些。
盛鬋不同制，实满宫些。
容态好比，顺弥代些。
弱颜固植，謇其有意些。
姱容修态，絚洞房些。
蛾眉曼睩，目腾光些。
靡颜腻理，遗视矊些。
离榭修幕，侍君之闲些。
悲帷翠帐，饰高堂些。
红壁沙版，玄玉梁些。
仰观刻桷，画龙蛇些。
坐堂伏槛，临曲池些。
芙蓉始发，杂芰荷些。
紫茎屏风，文缘波些。
文异豹饰，侍陂陁些。
轩辌既低，步骑罗些。
兰薄户树，琼木篱些。
魂兮归来！何远为些？
室家遂宗，食多方些。
稻粢穱麦，挐黄梁些。
大苦醎酸，辛甘行些。
肥牛之腱，臑若芳些。
和酸若苦，陈吴羹些。
胹鳖炮羔，有柘浆些。
鹄酸臇凫，煎鸿鸧些。
露鸡臛蠵，厉而不爽些。
粔籹蜜饵，有餦餭些。
瑶浆蜜勺，实羽觞些。
挫糟冻饮，酎清凉些。
华酌既陈，有琼浆些。
归来反故室，敬而无妨些。
肴羞未通，女乐罗些。
敶钟按鼓，造新歌些。
《涉江》《采菱》，发《扬荷》些。
美人既醉，朱颜酡些。
嬉光眇视，目曾波些。
被文服纤，丽而不奇些。
长发曼鬋，艳陆离些。
二八齐容，起郑舞些。
衽若交竿，抚案下些。
竽瑟狂会，搷鸣鼓些。
宫庭震惊，发<激楚>些。
吴歈蔡讴，奏大吕些。
士女杂坐，乱而不分些。
放敶组缨，班其相纷些。
郑卫妖玩，来杂陈些。
《激楚》之结，独秀先些。
菎蔽象棋，有六簙些。
分曹并进，遒相迫些。
成枭而牟，呼五白些。
晋制犀比，费白日些。
铿钟摇簴，揳梓瑟些。
娱酒不废，沈日夜些。
兰膏明烛，华灯错些。
结撰至思，兰芳假些。
人有所极，同心赋些。
酎饮尽欢，乐先故些。
魂兮归来！反故居些。
乱曰：献岁发春兮，汨吾南征。
菉苹齐叶兮，白芷生。
路贯庐江兮，左长薄。
倚沼畦瀛兮，遥望博。
青骊结驷兮，齐千乘。
悬火延起兮，玄颜烝。
步及骤处兮，诱骋先。
抑骛若通兮，引车右还。
与王趋梦兮，课后先。
君王亲发兮，惮青兕。
朱明承夜兮，时不可以淹。
皋兰被径兮，斯路渐。
湛湛江水兮，上有枫。
目极千里兮，伤春心。
魂兮归来，哀江南！','',''),('chuci-028','大招','景差','chuci','','大招','青春受谢，白日昭只。
