东有大海，溺水浟浟只。
螭龙并流，上下悠悠只。
雾雨淫淫，白皓胶只。
魂乎无东！汤谷寂寥只。
魂乎无南！南有炎火千里，蝮蛇蜒只。
山林险隘，虎豹蜿只。
鰅鳙短狐，王虺骞只。
魂乎无南！蜮伤躬只
魂乎无西！西方流沙，漭洋洋只。
