炙鸹烝凫，煔鹑敶只。
煎鰿膗雀，遽爽存只。
魂乎归来！丽以先只。
四酎并孰，不涩嗌只。
清馨冻饮，不歠役只。
吴醴白蘖，和楚沥只。
魂乎归来！不遽惕只。
代秦郑卫，鸣竽张只。
伏戏《驾辩》，楚《劳商》只。
讴和《扬阿》，赵萧倡只。
魂乎归来！定空桑只。
二八接舞，投诗赋只。
叩钟调磬，娱人乱只。
四上竞气，极声变只。
魂乎归来！听歌撰只。
朱唇皓齿，嫭以姱只。
比德好闲，习以都只。
丰肉微骨，调以娱只。
魂乎归来！安以舒只。
嫮目宜笑，娥眉曼只。
容则秀雅，稚朱颜只。
魂乎归来！静以安只。
姱修滂浩，丽以佳只。
曾颊倚耳，曲眉规只。
滂心绰态，姣丽施只。
小腰秀颈，若鲜卑只。
魂乎归来！思怨移只。
易中利心，以动作只。
粉白黛黑，施芳泽只。
长袂拂面，善留客只。
魂乎归来！以娱昔只。
青色直眉，美目媔只。
靥辅奇牙，宜笑嘕只。
丰肉微骨，体便娟只。
魂乎归来！恣所便只。
夏屋广大，沙堂秀只。
