执弓挟矢，揖辞让只。
魂乎来归！尚三王只。','',''),('chuci-029','惜誓','贾谊','chuci','','惜誓','惜余年老而日衰兮，岁忽忽而不反。
登苍天而高举兮，历众山而日远。
观江河之纡曲兮，离四海之霑濡。
攀北极而一息兮，吸沆瀣以充虚。
飞朱鸟使先驱兮，驾太一之象舆。
苍龙蚴虬于左骖兮，白虎骋而为右騑。
建日月以为盖兮，载玉女于后车。
驰骛于杳冥之中兮，休息呼昆仑之墟。
乐穷极而不厌兮，愿从容呼神明。
涉丹水而驰骋兮，右大夏之遗风。
黄鹄之一举兮，知山川之纡曲。
再举兮，睹天地之圜方。
临中国之众人兮，讬回飙乎尚羊。
乃至少原之野兮，赤松、王乔皆在旁。
二子拥瑟而调均兮，余因称乎清商。
澹然而自乐兮，吸众气而翱翔。
念我长生而久仙兮，不如反余之故乡。
黄鹄后时而寄处兮，鸱枭群而制之。
神龙失水而陆居兮，为蝼蚁之所裁。
夫黄鹄神龙犹如此兮，况贤者之逢乱世哉。
寿冉冉而日衰兮，固儃回而不息。
俗流从而不止兮，众枉聚而矫直。
或偷合而苟进兮，或隐居而深藏。
苦称量之不审兮，同权概而就衡。
或推迻而苟容兮，或直言之谔謣。
伤诚是之不察兮，并纫茅丝以为索。
方世俗之幽昏兮，眩白黑之美恶。
放山渊之龟玉兮，相与贵夫砾石。
梅伯数谏而至醢兮，来革顺志而用国。
悲仁人之尽节兮，反为小人之所贼。
比干忠谏而剖心兮，箕子被发而佯狂。
水背流而源竭兮，木去根而不长。
非重躯以虑难兮，惜伤身之无功。
已矣哉！独不见夫鸾凤之高翔兮，乃集大皇之野。
循四极而回周兮，见盛德而后下。
彼圣人之神德兮，远浊世而自藏。
使麒麟可得羁而系兮，又何以异呼犬羊？','',''),('chuci-030','招隐士','淮南小山','chuci','','招隐士','桂树丛生兮山之幽，偃蹇连蜷兮枝相缭。
山气巄嵷兮石嵯峨，溪谷崭岩兮水曾波。
猿狖群啸兮虎豹嗥，攀援桂枝兮聊淹留。
王孙游兮不归，春草生兮萋萋。
岁暮兮不自聊，蟪蛄鸣兮啾啾。
坱兮轧，山曲岪，心淹留兮恫慌忽。
罔兮沕，憭兮栗，虎豹穴。
丛薄深林兮，人上栗。
嵚岑崎礒兮，碅磳磈硊
树轮相纠兮，林木茷骫。
青莎杂树兮，薠草靃靡
白鹿麏麚兮，或腾或倚。
状貌崟崟兮峨峨，凄凄兮漇漇。
猕猴兮熊罴，慕类兮以悲
攀援桂枝兮聊淹留。
虎豹斗兮熊罴咆，禽兽骇兮亡其曹。
王孙兮归来，山中兮不可以久留。','',''),('chuci-031','初放','东方朔','chuci','','七谏','平生于国兮，长于原野。
言语讷譅兮，又无彊辅。
浅智褊能兮，闻见又寡。
数言便事兮，见怨门下。
王不察其长利兮，卒见弃乎原野。
伏念思过兮，无可改者。
群众成朋兮，上浸以惑。
巧佞在前兮，贤者灭息。
尧、舜圣已没兮，孰为忠直？
高山崔巍兮，水流汤汤。
死日将至兮，与麋鹿同坑。
块兮鞠，当道宿，举世皆然兮，余将谁告？
斥逐鸿鹄兮，近习鸱枭，斩伐橘柚兮，列树苦桃。
便娟之修竹兮，寄生乎江潭。
上葳蕤而防露兮，下泠泠而来风。
孰知其不合兮，若竹柏之异心。
往者不可及兮，来者不可待。
悠悠苍天兮，莫我振理。
窃怨君之不寤兮，吾独死而后已。','',''),('chuci-032','沉江','东方朔','chuci','','七谏','惟往古之得失兮，览私微之所伤。
尧舜圣而慈仁兮，后世称而弗忘。
齐桓失于专任兮，夷吾忠而名彰。
晋献惑于孋姬兮，申生孝而被殃。
偃王行其仁义兮，荆文寤而徐亡。
纣暴虐以失位兮，周得佐乎吕望。
修往古以行恩兮，封比干之丘垄。
贤俊慕而自附兮，日浸淫而合同。
明法令而修理兮，兰芷幽而有芳。
苦众人之妒予兮，箕子寤而佯狂。
不顾地以贪名兮，心怫郁而内伤。
联蕙芷以为佩兮，过鲍肆而失香。
正臣端其操行兮，反离谤而见攘。
世俗更而变化兮，伯夷饿于首阳。
独廉洁而不容兮，叔齐久而逾明。
浮云陈而蔽晦兮，使日月乎无光。
忠臣贞而欲谏兮，谗谀毁而在旁。
秋草荣其将实兮，微霜下而夜降。
商风肃而害生兮，百草育而不长。
众并谐以妒贤兮，孤圣特而易伤。
怀计谋而不见用兮，岩穴处而隐藏。
成功隳而不卒兮，子胥死而不葬。
世从俗而变化兮，随风靡而成行。
信直退而毁败兮，虚伪进而得当。
追悔过之无及兮，岂尽忠而有功。
废制度而不用兮，务行私而去公。
终不变而死节兮，惜年齿之未央。
将方舟而下流兮，冀幸君之发蒙。
痛忠言之逆耳兮，恨申子之沉江。
愿悉心之所闻兮，遭值君之不聪。
不开寤而难道兮，不别横之与纵。
听奸臣之浮说兮，绝国家之久长。
灭规矩而不用兮，背绳墨之正方。
离忧患而乃寤兮，若纵火于秋蓬。
业失之而不救兮，尚何论乎祸凶。
彼离畔而朋党兮，独行之士其何望？
日渐染而不自知兮，秋毫微哉而变容。
众轻积而折轴兮，原咎杂而累重。
赴湘沅之流澌兮，恐逐波而复东。
怀沙砾而自沉兮，不忍见君之蔽壅。','',''),('chuci-033','怨世','东方朔','chuci','','七谏','世沉淖而难论兮，俗岒峨而嵾嵯。
清泠泠而歼灭兮，溷湛湛而日多。
枭鸮既以成群兮，玄鹤弭翼而屏移。
蓬艾亲入御于床笫兮，马兰踸踔而日加。
弃捐药芷与杜衡兮，余柰世之不知芳何？
何周道之平易兮，然芜秽而险戏。
高阳无故而委尘兮，唐虞点灼而毁议。
谁使正其真是兮，虽有八师而不可为。
皇天保其高兮，后土持其久。
服清白以逍遥兮，偏与乎玄英异色。
西施媞媞而不得见兮，嫫母勃屑而日侍。
桂蠹不知所淹留兮，蓼虫不知徙乎葵菜。
处闵闵之浊世兮，今安所达乎吾志。
意有所载而远逝兮，固非众人之所识。
骥踌躇于弊輂兮，遇孙阳而得代。
吕望穷困而不聊生兮，遭周文而舒志。
宁戚饭牛而商歌兮，桓公闻而弗置。
路室女之方桑兮，孔子过之以自侍。
吾独乖剌而无当兮，心悼怵而耄思。
思比干之恲恲兮，哀子胥之慎事。
悲楚人之和氏兮，献宝玉以为石。
遇厉武之不察兮，羌两足以毕斮。
小人之居势兮，视忠正之何若？
改前圣之法度兮，喜嗫嚅而妄作。
亲谗谀而疏贤圣兮，讼谓闾娵为丑恶。
愉近习而蔽远兮，孰知察其黑白？
卒不得效其心容兮，安眇眇而无所归薄。
专精爽以自明兮，晦冥冥而壅蔽。
年既已过太半兮，然埳轲而留滞。
欲高飞而远集兮，恐离罔而灭败。
独冤抑而无极兮，伤精神而寿夭。
皇天既不纯命兮，余生终无所依。
愿自沉于江流兮，绝横流而径逝。
宁为江海之泥涂兮，安能久见此浊世？','',''),('chuci-034','怨思','东方朔','chuci','','七谏','贤士穷而隐处兮，廉方正而不容。
子胥谏而靡躯兮，比干忠而剖心。
子推自割而飤君兮，德日忘而怨深。
行明白而曰黑兮，荆棘聚而成林。
江离弃于穷巷兮，蒺藜蔓乎东厢。
贤者蔽而不见兮，谗谀进而相朋。
枭鸮并进而俱鸣兮，凤皇飞而高翔。
原壹往而径逝兮，道壅绝而不通。','',''),('chuci-035','自悲','东方朔','chuci','','七谏','居愁勤其谁告兮，独永思而忧悲。
内自省而不惭兮，操愈坚而不衰。
隐三年而无决兮，岁忽忽其若颓。
怜余身不足以卒意兮，冀一见而复归。
哀人事之不幸兮，属天命而委之咸池。
身被疾而不闲兮，心沸热其若汤。
冰炭不可以相并兮，吾固知乎命之不长。
哀独苦死之无乐兮，惜予年之未央。
悲不反余之所居兮，恨离予之故乡。
鸟兽惊而失群兮，犹高飞而哀鸣。
狐死必首丘兮，夫人孰能不反其真情？
故人疏而日忘兮，新人近而俞好。
莫能行于杳冥兮，孰能施于无报？
苦众人之皆然兮，乘回风而远游。
凌恒山其若陋兮，聊愉娱以忘忧。
悲虚言之无实兮，苦众口之铄金。
过故乡而一顾兮，泣歔欷而霑衿。
厌白玉以为面兮，怀琬琰以为心。
邪气入而感内兮，施玉色而外淫。
何青云之流澜兮，微霜降之蒙蒙。
徐风至而徘徊兮，疾风过之汤汤。
闻南籓乐而欲往兮，至会稽而且止。
见韩众而宿之兮，问天道之所在？
借浮云以送予兮，载雌霓而为旌。
驾青龙以驰骛兮，班衍衍之冥冥。
忽容容其安之兮，超慌忽其焉如？
苦众人之难信兮，愿离群而远举。
登峦山而远望兮，好桂树之冬荣。
观天火之炎炀兮，听大壑之波声。
引八维以自道兮，含沆瀣以长生。
居不乐以时思兮，食草木之秋实。
饮菌若之朝露兮，构桂木而为室。
杂橘柚以为囿兮，列新夷与椒桢。
鹍鹤孤而夜号兮，哀居者之诚贞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('chuci-036','哀命','东方朔','chuci','','七谏','哀时命之不合兮，伤楚国之多忧。
内怀情之洁白兮，遭乱世而离尤。
恶耿介之直行兮，世溷浊而不知。
何君臣之相失兮，上沅湘而分离。
测汨罗之湘水兮，知时固而不反。
伤离散之交乱兮，遂侧身而既远。
处玄舍之幽门兮，穴岩石而窟伏。
从水蛟而为徙兮，与神龙乎休息。
何山石之崭岩兮，灵魂屈而偃蹇。
含素水而蒙深兮，日眇眇而既远。
哀形体之离解兮，神罔两而无舍。
惟椒兰之不反兮，魂迷惑而不知路。
愿无过之设行兮，虽灭没之自乐。
痛楚国之流亡兮，哀灵修之过到。
固时俗之溷浊兮，志瞀迷而不知路。
念私门之正匠兮，遥涉江而远去。
念女嬃之婵媛兮，涕泣流乎于悒。
我决死而不生兮，虽重追吾何及。
戏疾濑之素水兮，望高山之蹇产。
哀高丘之赤岸兮，遂没身而不反。','',''),('chuci-037','谬谏','东方朔','chuci','','七谏','怨灵修之浩荡兮，夫何执操之不固？
悲太山之为隍兮，孰江河之可涸？
愿承闲而效志兮，恐犯忌而干讳。
卒抚情以寂寞兮，然怊怅而自悲。
玉与石其同匮兮，贯鱼眼与珠玑。
驽骏杂而不分兮，服罢牛而骖骥。
年滔滔而自远兮，寿冉冉而愈衰。
心悇憛而烦冤兮，蹇超摇而无冀。
固时俗之工巧兮，灭规矩而改错。
郤骐骥而不乘兮，策驽骀而取路。
当世岂无骐骥兮，诚无王良之善驭。
见执辔者非其人兮，故驹跳而远去。
不量凿而正枘兮，恐矩矱之不同。
不论世而高举兮，恐操行之不调。
弧弓弛而不张兮，孰云知其所至？
无倾危之患难兮，焉知贤士之所死？
俗推佞而进富兮，节行张而不着。
贤良蔽而不群兮，朋曹比而党誉。
邪说饰而多曲兮，正法弧而不公。
直士隐而避匿兮，谗谀登乎明堂。
弃彭咸之娱乐兮，灭巧倕之绳墨。
菎蕗杂于黀蒸兮，机蓬矢以射革。
驾蹇驴而无策兮，又何路之能极？
以直针而为钓兮，又何鱼之能得？
伯牙之绝弦兮，无锺子期而听之。
和抱璞而泣血兮，安得良工而剖之？
同音者相和兮，同类者相似。
飞鸟号其群兮，鹿鸣求其友。
故叩宫而宫应兮，弹角而角动。
虎啸而谷风至兮，龙举而景云往。
音声之相和兮，言物类之相感也。
夫方圜之异形兮，势不可以相错。
列子隐身而穷处兮，世莫可以寄讬。
众鸟皆有行列兮，凤独翔翔而无所薄。
经浊世而不得志兮，愿侧身岩穴而自讬。
欲阖口而无言兮，尝被君之厚德。
独便悁而怀毒兮，愁郁郁之焉极？
念三年之积思兮，愿壹见而陈辞。
不及君而骋说兮，世孰可为明之？
身寝疾而日愁兮，情沉抑而不扬。
众人莫可与论道兮，悲精神之不通。
乱曰：鸾皇孔凤日以远兮，畜凫驾鹅。
鸡鹜满堂坛兮，鼍黾游乎华池。
要褭奔亡兮，腾驾橐驼。
铅刀进御兮，遥弃太阿。
拔搴玄芝兮，列树芋荷。
橘柚萎枯兮，苦李旖旎。
甂瓯登于明堂兮，周鼎潜潜乎深渊。
自古而固然兮，吾又何怨乎今之人。','',''),('chuci-038','哀时命','庄忌','chuci','','哀时命','哀时命之不及古人兮，夫何予生之不遘时！
往者不可扳援兮，徕者不可与期。
志憾恨而不逞兮，杼中情而属诗。
夜炯炯而不寐兮，怀隐忧而历兹。
心郁郁而无告兮，众孰可与深谋！
欿愁悴而委惰兮，老冉冉而逮之。
居处愁以隐约兮，志沉抑而不扬。
道壅塞而不通兮，江河广而无梁。
愿至昆仑之悬圃兮，采锺山之玉英。
揽瑶木之橝枝兮，望阆风之板桐。
弱水汩其为难兮，路中断而不通。
势不能凌波以径度兮，又无羽翼而高翔。
然隐悯而不达兮，独徙倚而彷徉。
怅惝罔以永思兮，心纡轸而增伤。
倚踌躇以淹留兮，日饥馑而绝粮。
廓抱景而独倚兮，超永思乎故乡。
廓落寂而无友兮，谁可与玩此遗芳？
白日晼晼其将入兮，哀余寿之弗将。
车既弊而马罢兮，蹇邅徊而不能行。
身既不容于浊世兮，不知进退之宜当。
冠崔嵬而切云兮，剑淋离而从横。
衣摄叶以储与兮，左祛挂于榑桑
右衽拂于不周兮，六合不足以肆行。
上同凿枘于伏戏兮，下合矩矱于虞唐。
原尊节而式高兮，志犹卑夫禹汤。
虽知困其不改操兮，终不以邪枉害方。
世并举而好朋兮，壹斗斛而相量。
众比周以肩迫兮，贤者远而隐藏。
为凤皇作鹑笼兮，虽翕翅其不容。
灵皇其不寤知兮，焉陈词而效忠。
俗嫉妒而蔽贤兮，孰知余之从容？
愿舒志而抽冯兮，庸讵知其吉凶？
璋圭杂于甑窐兮，陇廉与孟娵同宫。
举世以为恒俗兮，固将愁苦而终穷。
幽独转而不寐兮，惟烦懑而盈匈。
魂眇眇而驰骋兮，心烦冤之忡忡。
志欿憾而不憺兮，路幽昧而甚难。
块独守此曲隅兮，然欿切而永叹。
愁修夜而宛转兮，气涫沸其若波。
握剞劂而不用兮，操规矩而无所施。
骋骐骥于中庭兮，焉能极夫远道？
置援狖于棂槛兮，夫何以责其捷巧？
驷跛鳖而上山兮，吾固知其不能升。
释管晏而任臧获兮，何权衡之能称？
箟簬杂于黀蒸兮，机蓬矢以射革。
负檐荷以丈尺兮，欲伸要而不可得。
外迫胁于机臂兮，上牵联于矰隿。
肩倾侧而不容兮，固陿腹而不得息。
务光自投于深渊兮，不获世之尘垢。
孰魁摧之可久兮，愿退身而穷处。
凿山楹而为室兮，下被衣于水渚。
雾露蒙蒙其晨降兮，云依斐而承宇。
虹霓纷其朝霞兮，夕淫淫而淋雨。
怊茫茫而无归兮，怅远望此旷野。
下垂钓于溪谷兮，上要求于仙者。
与赤松而结友兮，比王侨而为耦。
使枭杨先导兮，白虎为之前后。
浮云雾而入冥兮，骑白鹿而容与。
魂眐眐以寄独兮，汨徂往而不归。
处卓卓而日远兮，志浩荡而伤怀。
鸾凤翔于苍云兮，故矰缴而不能加。
蛟龙潜于旋渊兮，身不挂于罔罗。
知贪饵而近死兮，不如下游乎清波。
宁幽隐以远祸兮，孰侵辱之可为。
子胥死而成义兮，屈原沉于汨罗。
虽体解其不变兮，岂忠信之可化。
志怦怦而内直兮，履绳墨而不颇。
执权衡而无私兮，称轻重而不差。
摡尘垢之枉攘兮，除秽累而反真。
形体白而质素兮，中皎洁而淑清。
时猒饫而不用兮，且隐伏而远身。
聊窜端而匿迹兮，嗼寂默而无声。
独便悁而烦毒兮，焉发愤而筊抒。
时暧暧其将罢兮，遂闷叹而无名。
伯夷死于首阳兮，卒夭隐而不荣。
太公不遇文王兮，身至死而不得逞。
怀瑶象而佩琼兮，愿陈列而无正。
生天坠之若过兮，忽烂漫而无成。
邪气袭余之形体兮，疾憯怛而萌生。
原壹见阳春之白日兮，恐不终乎永年。','',''),('chuci-039','匡机','王褒','chuci','','九怀','极运兮不中，来将屈兮困穷。
余深愍兮惨怛，愿一列兮无从。
乘日月兮上征，顾游心兮鄗酆。
弥览兮九隅，彷徨兮兰宫。
芷闾兮药房，奋摇兮众芳。
菌阁兮蕙楼，观道兮从横。
宝金兮委积，美玉兮盈堂。
桂水兮潺湲，扬流兮洋洋。
蓍蔡兮踊跃，孔鹤兮回翔。
抚槛兮远望，念君兮不忘。
怫郁兮莫陈，永怀兮内伤。','',''),('chuci-040','通路','王褒','chuci','','九怀','天门兮墬户，孰由兮贤者？
无正兮溷厕，怀德兮何睹？
假寐兮愍斯，谁可与兮寤语？
痛凤兮远逝，畜鴳兮近处。
鲸鱏兮幽潜，从虾兮游陼。
乘虬兮登阳，载象兮上行。
朝发兮葱岭，夕至兮明光。
北饮兮飞泉，南采兮芝英。
宣游兮列宿，顺极兮彷徉。
红采兮骍衣，翠缥兮为裳。
舒佩兮綝纚，竦余剑兮干将。
腾蛇兮后从，飞駏兮步旁。
微观兮玄圃，览察兮瑶光。
启匮兮探策，悲命兮相当。
纫蕙兮永辞，将离兮所思。
浮云兮容与，道余兮何之？
远望兮仟眠，闻雷兮阗阗。
阴忧兮感余，惆怅兮自怜。','',''),('chuci-041','危俊','王褒','chuci','','九怀','林不容兮鸣蜩，余何留兮中州？
陶嘉月兮总驾，搴玉英兮自修。
结荣茝兮逶逝，将去烝兮远游。
径岱土兮魏阙，历九曲兮牵牛。
聊假日兮相佯，遗光耀兮周流。
望太一兮淹息，纡余辔兮自休。
曦白日兮皎皎，弥远路兮悠悠。
顾列孛兮缥缥，观幽云兮陈浮。
钜宝迁兮砏磤，雉咸雊兮相求。
泱莽莽兮究志，惧吾心兮懤懤。
步余马兮飞柱，览可与兮匹俦。
卒莫有兮纤介，永余思兮怞怞。','',''),('chuci-042','昭世','王褒','chuci','','九怀','世溷兮冥昏，违君兮归真。
乘龙兮偃蹇，高回翔兮上臻。
袭英衣兮缇[糹习]，披华裳兮芳芬。
登羊角兮扶舆，浮云漠兮自娱。
握神精兮雍容，与神人兮相胥。
流星坠兮成雨，进瞵盼兮上丘墟。
览旧邦兮滃郁，余安能兮久居。
志怀逝兮心懰栗，纡余辔兮踌躇。
闻素女兮微歌，听王后兮吹竽。
魂凄怆兮感哀，肠回回兮盘纡。
抚余佩兮缤纷，高太息兮自怜。
使祝融兮先行，令昭明兮开门。
驰六蛟兮上征，竦余驾兮入冥。
历九州兮索合，谁可与兮终生。
忽反顾兮西囿，睹轸丘兮崎倾。
横垂涕兮泫流，悲余后兮失灵。','',''),('chuci-043','尊嘉','王褒','chuci','','九怀','季春兮阳阳，列草兮成行。
余悲兮兰生，委积兮从横。
江离兮遗捐，辛夷兮挤臧。
伊思兮往古，亦多兮遭殃。
伍胥兮浮江，屈子兮沉湘。
运余兮念兹，心内兮怀伤。
望淮兮沛沛，滨流兮则逝。
榜舫兮下流，东注兮磕磕。
蛟龙兮导引，文鱼兮上濑。
抽蒲兮陈坐，援芙蕖兮为盖。
水跃兮余旌，继以兮微蔡。
云旗兮电骛，倏忽兮容裔。
河伯兮开门，迎余兮欢欣。
顾念兮旧都，怀恨兮艰难。
窃哀兮浮萍，泛淫兮无根。','',''),('chuci-044','蓄英','王褒','chuci','','九怀','秋风兮萧萧，舒芳兮振条。
微霜兮眇眇，病夭兮鸣蜩。
玄鸟兮辞归，飞翔兮灵丘。
望溪谷兮滃郁，熊罴兮呴嗥。
唐虞兮不存，何故兮久留？
临渊兮汪洋，顾林兮忽荒。
修余兮袿衣，骑霓兮南上。
乘云兮回回，亹亹兮自强。
将息兮兰皋，失志兮悠悠。
蒶蕴兮霉黧，思君兮无聊。
身去兮意存，怆恨兮怀愁。','',''),('chuci-045','思忠','王褒','chuci','','九怀','登九灵兮游神，静女歌兮微晨。
悲皇丘兮积葛，众体错兮交纷。
贞枝抑兮枯槁，枉车登兮庆云。
感余志兮惨栗，心怆怆兮自怜。
驾玄螭兮北征，向吾路兮葱岭。
连五宿兮建旄，扬氛气兮为旌。
历广漠兮驰骛，览中国兮冥冥。
玄武步兮水母，与吾期兮南荣。
登华盖兮乘阳，聊逍遥兮播光。
抽库娄兮酌醴，援瓟瓜兮接粮。
毕休息兮远逝，发玉轫兮西行。
惟时俗兮疾正，弗可久兮此方。
寤辟摽兮永思，心怫郁兮内伤。','',''),('chuci-046','陶壅','王褒','chuci','','九怀','览杳杳兮世惟，余惆怅兮何归。
伤时俗兮溷乱，将奋翼兮高飞。
驾八龙兮连蜷，建虹旌兮威夷。
观中宇兮浩浩，纷翼翼兮上跻。
浮溺水兮舒光，淹低徊兮京沶。
屯余车兮索友，睹皇公兮问师。
道莫贵兮归真，羡余术兮可夷。
吾乃逝兮南娭，道幽路兮九疑。
越炎火兮万里，过万首兮嶷嶷。
济江海兮蝉蜕，绝北梁兮永辞。
浮云郁兮昼昏，霾土忽兮塺々。
息阳城兮广夏，衰色罔兮中怠。
意晓阳兮燎寤，乃自诊兮在兹。
思尧舜兮袭兴，幸咎繇兮获谋。
悲九州兮靡君，抚轼叹兮作诗。','',''),('chuci-047','株昭','王褒','chuci','','九怀','悲哉于嗟兮，心内切磋。
款冬而生兮，凋彼叶柯。
瓦砾进宝兮，捐弃随和。
铅刀厉御兮，顿弃太阿。
骥垂两耳兮，中坂蹉跎。
蹇驴服驾兮，无用日多。
修洁处幽兮，贵宠沙劘。
凤皇不翔兮，鹑鴳飞扬。
乘虹骖霓兮，载云变化。
焦明开路兮，后属青蛇。
步骤桂林兮，超骧卷阿。
丘陵翔儛兮，溪谷悲歌。
神章灵篇兮，赴曲相和。
余私娱兹兮，孰哉复加。
还顾世俗兮，坏败罔罗。
卷佩将逝兮，涕流滂沲。
乱曰：皇门开兮照下土，株秽除兮兰芷睹。
四佞放兮后得禹，圣舜摄兮昭尧绪，孰能若兮原为辅。','',''),('chuci-048','逢纷','刘向','chuci','','九叹','伊伯庸之末胄兮，谅皇直之屈原。
云余肇祖于高阳兮，惟楚怀之婵连。
原生受命于贞节兮，鸿永路有嘉名。
齐名字于天地兮，并光明于列星。
吸精粹而吐氛浊兮，横邪世而不取容。
行叩诚而不阿兮，遂见排而逢谗。
后听虚而黜实兮，不吾理而顺情。
肠愤悁而含怒兮，志迁蹇而左倾。
心戃慌其不我与兮，躬速速其不吾亲。
辞灵修而陨志兮，吟泽畔之江滨。
椒桂罗以颠覆兮，有竭信而归诚。
谗夫蔼蔼而漫着兮，曷其不舒予情？
始结言于庙堂兮，信中涂而叛之。
怀兰蕙与衡芷兮，行中野而散之。
声哀哀而怀高丘兮，心愁愁而思旧邦。
愿承闲而自恃兮，径淫曀而道壅。
颜霉黧以沮败兮，精越裂而衰耄。
裳襜襜而含风兮，衣纳纳而掩露。
赴江湘之湍流兮，顺波凑而下降。
徐徘徊于山阿兮，飘风来之汹汹。
驰余车兮玄石，步余马兮洞庭。
平明发兮苍梧，夕投宿兮石城。
芙蓉盖而菱华车兮，紫贝阙而玉堂。
薜荔饰而陆离荐兮，鱼鳞衣而白霓裳。
登逢龙而下陨兮，违故都之漫漫。
思南郢之旧俗兮，肠一夕而九运。
扬流波之潢潢兮，体溶溶而东回。
心怊怅以永思兮，意暗暗而日颓。
白露纷以涂涂兮，秋风浏以萧萧。
身永流而不还兮，魂长逝而常愁。
叹曰：
譬彼流水纷扬磕兮，波逢汹涌濆壅滂兮。
揄扬涤荡飘流陨往触崟石兮，龙昂脟圈缭戾宛转阻相薄兮，
遭纷逢凶蹇离尤兮，垂文扬采遗将来兮。','',''),('chuci-049','离世','刘向','chuci','','九叹','灵怀其不吾知兮，灵怀其不吾闻。
就灵怀之皇祖兮，愬灵怀之鬼神。
灵怀曾不吾与兮，即听夫人之谀辞。
余辞上参于天坠兮，旁引之于四时。
指日月使延照兮，抚招摇以质正。
立师旷俾端辞兮，命咎繇使并听。
兆出名曰正则兮，卦发字曰灵均。
余幼既有此鸿节兮，长愈固而弥纯。
不从俗而诐行兮，直躬指而信志。
不枉绳以追曲兮，屈情素以从事。
端余行其如玉兮，述皇舆之踵迹。
群阿容以晦光兮，皇舆覆以幽辟。
舆中涂以回畔兮，驷马惊而横奔。
执组者不能制兮，必折轭而摧辕。
断镳衔以驰骛兮，暮去次而敢止。
路荡荡其无人兮，遂不御乎千里。
身衡陷而下沉兮，不可获而复登。
不顾身之卑贱兮，惜皇舆之不兴。
出国门而端指兮，冀壹寤而锡还。
哀仆夫之坎毒兮，屡离忧而逢患。
九年之中不吾反兮，思彭咸之水游。
惜师延之浮渚兮，赴汨罗之长流。
遵江曲之逶移兮，触石崎而衡游。
波澧澧而扬浇兮，顺长濑之浊流。
凌黄沱而下低兮，思还流而复反。
玄舆驰而并集兮，身容与而日远。
棹舟杭以横濿兮，济湘流而南极。
立江界而长吟兮，愁哀哀而累息。
情慌忽以忘归兮，神浮游以高历。
心蛩蛩而怀顾兮，魂眷眷而独逝。
叹曰：
余思旧邦心依违兮，日暮黄昏羌幽悲兮，
去郢东迁余谁慕兮，谗夫党旅其以兹故兮，
河水淫淫情所愿兮，顾瞻郢路终不返兮。','',''),('chuci-050','怨思','刘向','chuci','','九叹','惟郁郁之忧毒兮，志坎壈而不违。
身憔悴而考旦兮，日黄昏而长悲。
闵空宇之孤子兮，哀枯杨之冤雏。
孤雌吟于高墉兮，鸣鸠栖于桑榆。
玄蝯失于潜林兮，独偏弃而远放。
征夫劳于周行兮，处妇愤而长望。
申诚信而罔违兮，情素洁于纽帛。
光明齐于日月兮，文采耀耀于玉石。
伤压次而不发兮，思沉抑而不扬。
芳懿懿而终败兮，名靡散而不彰。
背玉门以奔骛兮，蹇离尤而干诟。
若龙逢之沉首兮，王子比干之逢醢。
念社稷之几危兮，反为雠而见怨。
思国家之离沮兮，躬获愆而结难。
若青蝇之伪质兮，晋骊姬之反情。
恐登阶之逢殆兮，故退伏于末庭。
孽臣之号啕兮，本朝芜而不治。
犯颜色而触谏兮，反蒙辜而被疑。
菀蘼芜与菌若兮，渐藁本于洿渎。
淹芳芷于腐井兮，弃鸡骇于筐簏。
执棠溪以刜蓬兮，秉干将以割肉。
筐泽泻以豹鞟兮，破荆和以继筑。
时溷浊犹未清兮，世肴乱犹未察。
欲容与以俟时兮，惧年岁之既晏。
顾屈节以从流兮，心巩巩而不夷。
宁浮沅而驰骋兮，下江湘以邅回。
叹曰：
山中槛槛余伤怀兮，征夫皇皇其孰依兮，
经营原野杳冥冥兮，乘骐骋骥舒吾情兮，
归骸旧邦莫谁语兮，长辞远逝乘湘去兮。','',''),('chuci-051','远逝','刘向','chuci','','九叹','志隐隐而郁怫兮，愁独哀而冤结。
肠纷纭以缭转兮，涕渐渐其若屑。
情慨慨而长怀兮，信上皇而质正。
合五岳与八灵兮，讯九鬿与六神。
指列宿以白情兮，诉五帝以置辞。
北斗为我折中兮，太一为余听之。
云服阴阳之正道兮，御后土之中和。
佩苍龙之蚴虬兮，带隐虹之逶蛇。
曳彗星之皓旰兮，抚朱爵与鵔鸃。
游清灵之飒戾兮，服云衣之披披。
杖玉策与朱旗兮，垂明月之玄珠。
举霓旌之墆翳兮，建黄纁之总旄。
躬纯粹而罔愆兮，承皇考之妙仪。
惜往事之不合兮，横汨罗而下沥。
乘隆波而南渡兮，逐江湘之顺流。
赴阳侯之潢洋兮，下石濑而登洲。
陆魁堆以蔽视兮，云冥冥而暗前。
山峻高以无垠兮，遂曾闳而迫身。
雪雰雰而薄木兮，云霏霏而陨集。
阜隘狭而幽险兮，石嵾嵯以翳日。
悲故乡而发忿兮，去余邦之弥久。
背龙门而入河兮，登大坟而望夏首。
横舟航而济湘兮，耳聊啾而戃慌。
波淫淫而周流兮，鸿溶溢而滔荡。
路曼曼其无端兮，周容容而无识。
引日月以指极兮，少须臾而释思。
水波远以冥冥兮，眇不睹其东西。
顺风波以南北兮，雾宵晦以纷纷。
日杳杳以西颓兮，路长远而窘迫。
欲酌醴以娱忧兮，蹇骚骚而不释。
叹曰：
飘风蓬龙埃坲々兮，草木摇落时槁悴兮，
遭倾遇祸不可救兮，长吟永欷涕究究兮，
舒情陈诗冀以自免兮，颓流下陨身日远兮。','',''),('chuci-052','惜贤','刘向','chuci','','九叹','览屈氏之离骚兮，心哀哀而怫郁。
声嗷嗷以寂寥兮，顾仆夫之憔悴。
拨谄谀而匡邪兮，切淟涊之流俗。
荡渨涹之奸咎兮，夷蠢蠢之溷浊。
怀芬香而挟蕙兮，佩江蓠之婓婓。
握申椒与杜若兮，冠浮云之峨峨。
登长陵而四望兮，览芷圃之蠡蠡。
游兰皋与蕙林兮，睨玉石之嵾嵯。
扬精华以炫耀兮，芳郁渥而纯美。
结桂树之旖旎兮，纫荃蕙与辛夷。
芳若兹而不御兮，捐林薄而菀死。
驱子侨之奔走兮，申徒狄之赴渊。
若由夷之纯美兮，介子推之隐山。
晋申生之离殃兮，荆和氏之泣血。
吴申胥之抉眼兮，王子比干之横废。
欲卑身而下体兮，心隐恻而不置。
方圜殊而不合兮，钩绳用而异态。
欲俟时于须臾兮，日阴曀其将暮。
时迟迟其日进兮，年忽忽而日度。
妄周容而入世兮，内距闭而不开。
俟时风之清激兮，愈氛雾其如塺。
进雄鸠之耿耿兮，谗介介而蔽之。
默顺风以偃仰兮，尚由由而进之。
心懭悢以冤结兮，情舛错以曼忧。
搴薜荔于山野兮，采拈支于中洲。
望高丘而叹涕兮，悲吸吸而长怀。
孰契契而委栋兮，日暗暗而下颓。
叹曰：
江湘油油长流汩兮，挑揄扬汰荡迅疾兮。
忧心展转愁怫郁兮，冤结未舒长隐忿兮，
丁时逢殃可奈何兮，劳心悁悁涕滂沱兮。','',''),('chuci-053','忧苦','刘向','chuci','','九叹','悲余心之悁悁兮，哀故邦之逢殃。
辞九年而不复兮，独茕茕而南行。
思余俗之流风兮，心纷错而不受。
遵野莽以呼风兮，步从容于山廋。
巡陆夷之曲衍兮，幽空虚以寂寞。
倚石岩以流涕兮，忧憔悴而无乐。
登巑岏以长企兮，望南郢而闚之。
山修远其辽辽兮，涂漫漫其无时。
听玄鹤之晨鸣兮，于高冈之峨峨。
独愤积而哀娱兮，翔江洲而安歌。
三鸟飞以自南兮，览其志而欲北。
原寄言于三鸟兮，去飘疾而不可得。
欲迁志而改操兮，心纷结其未离。
外彷徨而游览兮，内恻隐而含哀。
聊须臾以时忘兮，心渐渐其烦错。
原假簧以舒忧兮，志纡郁其难释。
叹《离骚》以扬意兮，犹未殚于《九章》。
长嘘吸以于悒兮，涕横集而成行。
伤明珠之赴泥兮，鱼眼玑之坚藏。
同驽骡与乘驵兮，杂斑驳与阘茸。
葛藟虆于桂树兮，鸱鸮集于木兰。
偓促谈于廊庙兮，律魁放乎山间。
恶虞氏之箫《韶》兮，好遗风之《激楚》。
潜周鼎于江淮兮，爨土鬵于中宇。
且人心之持旧兮，而不可保长。
邅彼南道兮，征夫宵行。
思念郢路兮，还顾睠睠。
涕流交集兮，泣下涟涟。
叹曰：
登山长望中心悲兮，菀彼青青泣如颓兮，
留思北顾涕渐渐兮，折锐摧矜凝泛滥兮，
念我茕茕魂谁求兮，仆夫慌悴散若流兮。','',''),('chuci-054','愍命','刘向','chuci','','九叹','昔皇考之嘉志兮，喜登能而亮贤。
情纯洁而罔薉兮，姿盛质而无愆。
放佞人与谄谀兮，斥谗夫与便嬖。
亲忠正之悃诚兮，招贞良与明智。
心溶溶其不可量兮，情澹澹其若渊。
回邪辟而不能入兮，诚原藏而不可迁。
逐下袟于后堂兮，迎虙妃于伊雒。
刜谗贼于中廇兮，选吕管于榛薄。
丛林之下无怨士兮，江河之畔无隐夫。
三苗之徒以放逐兮，伊皋之伦以充庐。
今反表以为里兮，颠裳以为衣。
戚宋万于两楹兮，废周邵于遐夷。
却骐骥以转运兮，腾驴骡以驰逐。
蔡女黜而出帷兮，戎妇入而彩绣服。
庆忌囚于阱室兮，陈不占战而赴围。
破伯牙之号钟兮，挟人筝而弹纬。
藏瑉石于金匮兮，捐赤瑾于中庭。
韩信蒙于介胄兮，行夫将而攻城。
莞芎弃于泽洲兮，瓟瓥蠹于筐簏。
麒麟奔于九皋兮，熊罴群而逸囿。
折芳枝与琼华兮，树枳棘与薪柴。
掘荃蕙与射干兮，耘藜藿与蘘荷。
惜今世其何殊兮，远近思而不同。
或沉沦其无所达兮，或清激其无所通。
哀余生之不当兮，独蒙毒而逢尤。
虽謇謇以申志兮，君乖差而屏之。
诚惜芳之菲菲兮，反以兹为腐也。
怀椒聊之蔎蔎兮，乃逢纷以罹诟也。
叹曰：
嘉皇既殁终不返兮，山中幽险郢路远兮。
谗人諓諓孰可愬兮，征夫罔极谁可语兮。
行吟累欷声喟喟兮，怀忧含戚何侘傺兮。','',''),('chuci-055','思古','刘向','chuci','','九叹','冥冥深林兮，树木郁郁。
山参差以崭岩兮，阜杳杳以蔽日。
悲余心之悁悁兮，目眇眇而遗泣。
风骚屑以摇木兮，云吸吸以湫戾。
悲余生之无欢兮，愁倥偬于山陆。
旦徘徊于长阪兮，夕彷徨而独宿。
发披披以鬤鬤兮，躬劬劳而瘏悴。
魂俇俇而南行兮，泣霑襟而濡袂。
心婵媛而无告兮，口噤闭而不言。
违郢都之旧闾兮，回湘、沅而远迁。
念余邦之横陷兮，宗鬼神之无次。
闵先嗣之中绝兮，心惶惑而自悲。
聊浮游于山陿兮，步周流于江畔。
临深水而长啸兮，且倘佯而泛观。
兴离骚之微文兮，冀灵修之壹悟。
还余车于南郢兮，复往轨于初古。
道修远其难迁兮，伤余心之不能已。
背三五之典刑兮，绝洪范之辟纪。
播规矩以背度兮，错权衡而任意。
操绳墨而放弃兮，倾容幸而侍侧。
甘棠枯于丰草兮，藜棘树于中庭。
西施斥于北宫兮，仳倠倚于弥楹。
乌获戚而骖乘兮，燕公操于马圉。
蒯聩登于清府兮，咎繇弃而在野。
盖见兹以永叹兮，欲登阶而狐疑。
乘白水而高骛兮，因徙弛而长词。
叹曰：
倘佯垆阪沼水深兮，容与汉渚涕淫淫兮，锺牙已死谁为声兮？
纤阿不御焉舒情兮，曾哀凄欷心离离兮，还顾高丘泣如洒兮。','',''),('chuci-056','远游','刘向','chuci','','九叹','悲余性之不可改兮，屡惩艾而不迻。
服觉皓以殊俗兮，貌揭揭以巍巍。
譬若王侨之乘云兮，载赤霄而凌太清。
欲与天地参寿兮，与日月而比荣。
登昆仑而北首兮，悉灵圉而来谒。
选鬼神于太阴兮，登阊阖于玄阙。
回朕车俾西引兮，褰虹旗于玉门。
驰六龙于三危兮，朝西灵于九滨。
结余轸于西山兮，横飞谷以南征。
绝都广以直指兮，历祝融于朱冥。
枉玉衡于炎火兮，委两馆于咸唐。
贯澒蒙以东朅兮，维六龙于扶桑。
周流览于四海兮，志升降以高驰。
征九神于回极兮，建虹采以招指。
驾鸾凤以上游兮，从玄鹤与鹪明。
孔鸟飞而送迎兮，腾群鹤于瑶光。
排帝宫与罗囿兮，升县圃以眩灭。
结琼枝以杂佩兮，立长庚以继日。
凌惊雷以轶骇电兮，缀鬼谷于北辰。
鞭风伯使先驱兮，囚灵玄于虞渊。
遡高风以低徊兮，览周流于朔方。
就颛顼而敶辞兮，考玄冥于空桑。
旋车逝于崇山兮，奏虞舜于苍梧。
济杨舟于会稽兮，就申胥于五湖。
见南郢之流风兮，殒余躬于沅湘。
望旧邦之黯黮兮，时溷浊其犹未央。
怀兰茝之芬芳兮，妒被离而折之。
张绛帷以襜襜兮，风邑邑而蔽之。
日暾暾其西舍兮，阳焱焱而复顾。
聊假日以须臾兮，何骚骚而自故。
叹曰：
譬彼蛟龙乘云浮兮，泛淫澒溶纷若雾兮。
潺湲轇轕雷动电发馺高举兮。
升虚凌冥沛浊浮清入帝宫兮，摇翘奋羽驰风骋雨游无穷兮。','',''),('chuci-057','逢尤','王逸','chuci','','九思','悲兮愁，哀兮忧！
天生我兮当暗时，被诼谮兮虚获尤。
心烦愦兮意无聊，严载驾兮出戏游。
周八极兮历九州，求轩辕兮索重华。
世既卓兮远眇眇，握佩玖兮中路躇。
羡咎繇兮建典谟，懿风后兮受瑞图。
愍余命兮遭六极，委玉质兮于泥涂。
遽傽遑兮驱林泽，步屏营兮行丘阿。
车軏折兮马虺颓，蠢怅立兮涕滂沱。
思丁文兮圣明哲，哀平差兮迷谬愚。
吕傅举兮殷周兴，忌嚭专兮郢吴虚。
仰长叹兮气噎结，悒殟绝兮咶复苏。
虎兕争兮于廷中，豺狼斗兮我之隅。
云雾会兮日冥晦，飘风起兮扬尘埃。
走鬯罔兮乍东西，欲窜伏兮其焉如？
念灵闺兮隩重深，原竭节兮隔无由。
望旧邦兮路逶随，忧心悄兮志勤劬。
魂茕茕兮不遑寐，目眽眽兮寤终朝。','',''),('chuci-058','怨上','王逸','chuci','','九思','令尹兮謷謷，群司兮譨譨。
哀哉兮淈淈，上下兮同流。
菽藟兮蔓衍，芳虈兮挫枯。
朱紫兮杂乱，曾莫兮别诸。
倚此兮岩穴，永思兮窈悠。
嗟怀兮眩惑，用志兮不昭。
将丧兮玉斗，遗失兮钮枢。
我心兮煎熬，惟是兮用忧。
进恶兮九旬，复顾兮彭务。
拟斯兮二踪，未知兮所投。
谣吟兮中野，上察兮璇玑。
大火兮西睨，摄提兮运低。
雷霆兮硠磕，雹霰兮霏霏。
奔电兮光晃，凉风兮怆凄。
鸟兽兮惊骇，相从兮宿栖。
鸳鸯兮噰噰，狐狸兮徾徾。
哀吾兮介特，独处兮罔依。
蝼蛄兮鸣东，蟊蠽兮号西。
蛓缘兮我裳，蠋入兮我怀。
虫豸兮夹余，惆怅兮自悲。
伫立兮忉怛，心结縎兮折摧。','',''),('chuci-059','疾世','王逸','chuci','','九思','周徘徊兮汉渚，求水神兮灵女。
嗟此国兮无良，媒女诎兮謰謱。
鴳雀列兮哗讙，鸲鹆鸣兮聒余。
抱昭华兮宝璋，欲炫鬻兮莫取。
言旋迈兮北徂，叫我友兮配耦。
日阴曀兮未光，阒睄窕兮靡睹。
纷载驱兮高驰，将谘询兮皇羲。
遵河皋兮周流，路变易兮时乖。
濿沧海兮东游，沐盥浴兮天池。
访太昊兮道要，云靡贵兮仁义。
志欣乐兮反征，就周文兮邠歧。
秉玉英兮结誓，日欲暮兮心悲。
惟天禄兮不再，背我信兮自违。
逾陇堆兮渡漠，过桂车兮合黎。
赴昆山兮馽騄，从邛遨兮栖迟。
吮玉液兮止渴，啮芝华兮疗饥。
居嵺廓兮尠畴，远梁昌兮几迷。
望江汉兮濩渃，心紧絭兮伤怀。
时昢昢兮且旦，尘莫莫兮未曦。
忧不暇兮寝食，吒增叹兮如雷。','',''),('chuci-060','悯上','王逸','chuci','','九思','哀世兮睩睩，諓諓兮嗌喔。
众多兮阿媚，骪靡兮成俗。
贪枉兮党比，贞良兮茕独。
鹄窜兮枳棘，鹈集兮帷幄。
罽蕠兮青葱，槁本兮萎落。
睹斯兮伪惑，心为兮隔错。
逡巡兮圃薮，率彼兮畛陌。
川谷兮渊渊，山阜兮峉峉。
丛林兮崟崟，株榛兮岳岳。
霜雪兮漼溰，冰冻兮洛泽。
东西兮南北，罔所兮归薄。
庇廕兮枯树，匍匐兮岩石。
蜷局兮寒局数，独处兮志不申。
年齿尽兮命迫促，魁垒挤摧兮常困辱。
含忧强老兮愁无乐，须发苎悴兮顠鬓白。
思灵泽兮一膏沐，怀兰英兮把琼若，待天明兮立踯躅。
云蒙蒙兮电鯈烁，孤雌惊兮鸣呴呴。
思怫郁兮肝切剥，忿悁悒兮孰诉告。','',''),('chuci-061','遭厄','王逸','chuci','','九思','悼屈子兮遭厄，沉王躬兮湘汨。
何楚国兮难化，迄于今兮不易。
士莫志兮羔裘，竞佞谀兮谗阋。
指正义兮为曲，訿玉璧兮为石。
殦雕游兮华屋，鵔鸃栖兮柴蔟。
起奋迅兮奔走，违群小兮謑訽。
载青云兮上升，适昭明兮所处。
蹑天衢兮长驱，踵九阳兮戏荡。
越云汉兮南济，秣余马兮河鼓。
云霓纷兮暗翳，参辰回兮颠倒。
逢流星兮问路，顾我指兮从左。
俓娵觜兮直驰，御者迷兮失轨。
遂踢达兮邪造，与日月兮殊道。
志阏绝兮安如，哀所求兮不耦。
攀天阶兮下视，见鄢郢兮旧宇。
意逍遥兮欲归，众秽盛兮沓沓。
思哽饐兮诘诎，涕流澜兮如雨。','',''),('chuci-062','悼乱','王逸','chuci','','九思','嗟嗟兮悲夫，肴乱兮纷挐。
茅丝兮同综，冠屦兮共絇。
督万兮侍宴，周邵兮负刍。
白龙兮见射，灵龟兮执拘。
仲尼兮困厄，邹衍兮幽囚。
伊余兮念兹，奔遁兮隐居。
将升兮高山，上有兮猴猿。
欲入兮深谷，下有兮虺蛇。
左见兮鸣鵙，右睹兮呼枭。
惶悸兮失气，踊跃兮距跳。
便旋兮中原，仰天兮增叹。
菅蒯兮茂莽，雚苇兮仟眠。
鹿蹊兮躖躖，貒貉兮蟫蟫。
鹯鹞兮轩轩，鹑鹌兮甄甄。
哀我兮寡独，靡有兮齐伦。
意欲兮沉吟，迫日兮黄昏。
玄鹤兮高飞，曾逝兮青冥。
鸧鹒兮喈喈，山鹊兮嘤嘤。
鸿鸬兮振翅，归雁兮于征。
吾志兮觉悟，怀我兮圣京。
垂屣兮将起，跓俟兮硕明。','',''),('chuci-063','伤时','王逸','chuci','','九思','惟昊天兮昭灵，阳气发兮清明。
风习习兮和暖，百草萌兮华荣。
堇荼茂兮扶疏，蘅芷雕兮莹嫇。
愍贞良兮遇害，将夭折兮碎糜。
时混混兮浇饡，哀当世兮莫知。
览往昔兮俊彦，亦诎辱兮系累。
管束缚兮桎梏，百贸易兮传卖。
遭桓缪兮识举，才德用兮列施。
且从容兮自慰，玩琴书兮游戏。
迫中国兮迮陿，吾欲之兮九夷。
超五岭兮嵯峨，观浮石兮崔嵬。
陟丹山兮炎野，屯余车兮黄支。
就祝融兮稽疑，嘉己行兮无为。
乃回朅兮北逝，遇神孈兮宴娭。
欲静居兮自娱，心愁戚兮不能。
放余辔兮策驷，忽飙腾兮浮云。
跖飞杭兮越海，从安期兮蓬莱。
缘天梯兮北上，登太一兮玉台。
使素女兮鼓簧，乘戈和兮讴谣。
声噭誂兮清和，音晏衍兮要淫。
咸欣欣兮酣乐，余眷眷兮独悲。
顾章华兮太息，志恋恋兮依依。','',''),('chuci-064','哀岁','王逸','chuci','','九思','旻天兮清凉，玄气兮高朗。
北风兮潦洌，草木兮苍唐。
蛜蚗兮噍噍，蝍蛆兮穰穰。
岁忽忽兮惟暮，余感时兮凄怆。
伤俗兮泥浊，蒙蔽兮不章。
宝彼兮沙砾，捐此兮夜光。
椒瑛兮湟污，葈耳兮充房。
摄衣兮缓带，操我兮墨阳。
升车兮命仆，将驰兮四荒。
下堂兮见虿，出门兮触螽。
巷有兮蚰蜓，邑多兮螳螂。
睹斯兮嫉贼，心为兮切伤。
俛念兮子胥，仰怜兮比干。
投剑兮脱冕，龙屈兮蜿蟤。
潜藏兮山泽，匍匐兮丛攒。
窥见兮溪涧，流水兮沄沄。
鼋鼍兮欣欣，鳣鲇兮延延。
群行兮上下，骈罗兮列陈。
自恨兮无友，特处兮茕茕。
冬夜兮陶陶，雨雪兮冥冥。
神光兮颎颎，鬼火兮荧荧。
修德兮困控，愁不聊兮遑生。
忧纡兮郁郁，恶所兮写情。','',''),('chuci-065','守志','王逸','chuci','','九思','陟玉峦兮逍遥，览高冈兮峣峣。
桂树列兮纷敷，吐紫华兮布条。
实孔鸾兮所居，今其集兮惟鸮。
乌鹊惊兮哑哑，余顾盼兮怊怊。
彼日月兮暗昧，障覆天兮祲氛。
伊我后兮不聪，焉陈诚兮效忠。
摅羽翮兮超俗，游陶遨兮养神。
乘六蛟兮蜿蝉，遂驰骋兮升云。
扬彗光兮为旗，秉电策兮为鞭。
朝晨发兮鄢郢，食时至兮增泉。
绕曲阿兮北次，造我车兮南端。
谒玄黄兮纳贽，崇忠贞兮弥坚。
历九宫兮遍观，睹秘藏兮宝珍。
就传说兮骑龙，与织女兮合婚。
举天罼兮掩邪，彀天弧兮射奸。
随真人兮翱翔，食元气兮长存。
望太微兮穆穆，睨三阶兮炳分。
相辅政兮成化，建烈业兮垂勋。
目瞥瞥兮西没，道遐回兮阻叹。
志稸积兮未通，怅敞罔兮自怜。
乱曰：
天庭明兮云霓藏，三光朗兮镜万方。
斥蜥蜴兮进龟龙，策谋从兮翼机衡。
配稷契兮恢唐功，嗟英俊兮未为双。','',''),('yuanqu-001','诈妮子调风月・仙吕/点绛唇','关汉卿','yuanqu','','','半世为人，不曾教大人心困。
虽是搽胭粉，只争不裹头巾，将那等不做人的婆娘恨。','',''),('yuanqu-002','诈妮子调风月・混江龙','关汉卿','yuanqu','','','男儿人若不依本分，一个抢白是非两家分。
壮鼻凹硬如石铁，教满耳根都做了烧云。
普天下汉子尽教都先有意，牢把定自己休不成人。
虽然两家无意，便待一面成亲，不分晓便似包着一肚皮干牛粪。
知人无意，及早抽身。','',''),('yuanqu-003','诈妮子调风月・那吒令','关汉卿','yuanqu','','','等不得水温，一声要面盆；恰递与面盆，一声要手巾；却执与手巾，一声解纽门。
使的人无淹润、百般支分！。','',''),('yuanqu-004','诈妮子调风月・鹊踏枝','关汉卿','yuanqu','','','入得房门，怎回身？厅独卧房儿窄窄别别，有甚铺呈？燕燕己身有甚么孝顺？拗不过哥哥行在意殷勤。','',''),('yuanqu-005','诈妮子调风月・寄生草','关汉卿','yuanqu','','','卧地观经史，坐地对圣人。
你观的国风、雅、颂施诂训，诵的典谟训诰居尧舜，（末云了）（正旦唱）说的温良恭俭行忠信。
燕燕子理会得龙盘虎踞灭燕齐，谁会甚儿婚女聘成秦晋？（末云）这书院好。','',''),('yuanqu-006','诈妮子调风月・幺篇','关汉卿','yuanqu','','','这书房存得阿马，会得客宾。
翠筠月朗龙蛇印，碧轩夜冷灯香信，绿窗雨细琴书润。
每朝席上宴佳宾，抵多少"十年窗下无人问"！（末云住）（正旦唱）。','',''),('yuanqu-007','诈妮子调风月・村里迓鼓','关汉卿','yuanqu','','','更做道一家生女，百家求问。
才说贞烈，那里取一个时辰？见他语言儿栽排得淹润，怕不待言词硬，性格村、他怎比寻常世人？（末云了）（正旦唱）。','',''),('yuanqu-008','诈妮子调风月・元和令','关汉卿','yuanqu','','','无男儿只一身，担寂寞受孤闷；有男儿呓梦入劳魂，心肠百处分。
知得有情人不曾来问肯，便待要成眷姻。','',''),('yuanqu-009','诈妮子调风月・上马娇','关汉卿','yuanqu','','','自勘婚，自说亲，也是"贱媳妇责媒人"。
往常我冰清玉洁难亲近，是他亲，子管教话儿亲。
我煞待嗔，我便恶相闻。','',''),('yuanqu-010','诈妮子调风月・胜葫芦','关汉卿','yuanqu','','','怕不依随蒙君一夜恩，争奈忒达地、忒知根，兼上亲上成亲好对门。
觑了他兀的模样，这般身分。
若脱过这好郎君。','',''),('yuanqu-011','诈妮子调风月・幺篇','关汉卿','yuanqu','','','教人道"眼里无珍一世贫"；成就了又怕辜恩。
若往常烈焰飞腾情性紧，若一遭儿恩爱，再来不问，枉侵了这百年恩。','',''),('yuanqu-012','诈妮子调风月・柳叶儿','关汉卿','yuanqu','','','一个个背槽抛粪，一个个负义忘恩，自来鱼雁无音信。
自思忖，不审得话儿真，枉葫芦提了"燕尔新婚。','',''),('yuanqu-013','诈妮子调风月・尾','关汉卿','yuanqu','','','忽地却掀帘，兜地回头问，不由我心儿里便亲。
你把那并枕睡的日头儿再定轮，休教我逐宵价握雨携云。
过今春，先教我不系腰裙，便是半簸箕头钱扑个复纯。
教人道"眼里有珍"，你可休"言而无信"！（云）许下我包髻、团衫、绣手巾。
专等你世袭千户的小夫人。
（下）。','',''),('yuanqu-014','诈妮子调风月・中吕/粉蝶儿','关汉卿','yuanqu','','','年例寒食，邻姬每斗来邀会，去年时没人将我拘管收拾。
打秋千，闲斗草，直到个昏天黑地；今年个不敢来迟，有一个未拿着性儿女婿。','',''),('yuanqu-015','诈妮子调风月・醉春风','关汉卿','yuanqu','','','因甚把玉粳米牙儿抵，金莲花攒枕倚？或嗔或喜脸儿多？哎！你、你！教我没想没思，两心两意，早晨古自一家一计！。','',''),('yuanqu-016','诈妮子调风月・朱履曲','关汉卿','yuanqu','','','莫不是郊外去逢着甚邪祟？又不疯又不呆痴，面没罗、呆答孩、死堆灰。
这烦恼在谁身上？莫不在我根底，打听得些闲是非？。','',''),('yuanqu-017','诈妮子调风月・满庭芳','关汉卿','yuanqu','','','见我这般微微喘息，语言恍惚，脚步儿查梨。
慢松松胸带儿频那系，裙腰儿空闲里偷提。
见我这般气丝丝偏斜了髟。','',''),('yuanqu-018','诈妮子调风月・十二月','关汉卿','yuanqu','','','直到个天昏地黑，不肯更换衣袂；把兔鹘解开，纽扣相离，把袄子疏剌剌松开上拆，将手帕撇漾在田地。','',''),('yuanqu-019','诈妮子调风月・尧民歌','关汉卿','yuanqu','','','见那厮手慌脚乱紧收拾，被我先藏在香罗袖儿里。
是好哥哥和我做头敌，咱两个官司有商议。
休提！体提！哥哥撇下的手帕是阿谁的？（末云了）（正旦唱）。','',''),('yuanqu-020','诈妮子调风月・江儿水','关汉卿','yuanqu','','','老阿者使将来伏侍你，展污了咱身起。
你养着别个的，看我如奴婢，燕燕那些儿亏负你？（旦做住）（末告科）（正旦唱）。','',''),('yuanqu-021','草桥店梦莺莺(第四本)・仙吕/端正好','王实甫','yuanqu','','','因姐姐玉精神，花模样，无倒断晓夜思量。
着一片志诚心盖抹了漫天谎。
出画阁，向书房；离楚岫，赴高唐；学窃玉，试偷香；巫娥女，楚襄王；楚襄王敢先在阳台上。
(下)。','',''),('yuanqu-022','草桥店梦莺莺(第四本)・仙吕/点绛唇','王实甫','yuanqu','','','伫立闲阶。
夜深香霭、横金界。
萧洒书斋，闷杀读书客。','',''),('yuanqu-023','草桥店梦莺莺(第四本)・油葫芦','王实甫','yuanqu','','','情思昏昏眼倦开，单枕侧，梦魂飞入梦阳台。
早知道无明无夜因他害，想当初"不如不遇倾城色"。
人有过，必自责，勿惮改。
我却待"贤贤易色"将心戒，怎禁他兜的上心来。','',''),('yuanqu-024','草桥店梦莺莺(第四本)・天下乐','王实甫','yuanqu','','','我则索倚定门儿手托腮，好着我难猜：来也那不来？夫人行料应难离侧。
望得人眼欲穿，想得人心越窄，多管是冤家不自在。','',''),('yuanqu-025','草桥店梦莺莺(第四本)・那吒令','王实甫','yuanqu','','','他若是肯来，早身离贵宅；他若是到来，便春生敝斋；他若是不来，似石沉大海。
数着他脚步儿行，倚定窗棂儿待。
寄语多才：。','',''),('yuanqu-026','草桥店梦莺莺(第四本)・鹊踏枝','王实甫','yuanqu','','','恁的般恶抢白，并不曾记心怀；拔得个意转心回，夜去明来。
空调眼色经今半载，这其间委实难捱。','',''),('yuanqu-027','草桥店梦莺莺(第四本)・寄生草','王实甫','yuanqu','','','安排着害，准备着抬。
想着这异乡身强把茶汤捱，则为这可憎才熬得心肠耐，办一片志诚心留得形骸在。
试着那司天台打算半年愁，端的是太平车约有十余载。','',''),('yuanqu-028','草桥店梦莺莺(第四本)・村里迓鼓','王实甫','yuanqu','','','猛见他可憎模样，--小生那里得病来--早医可九分不快。
先前见责，谁承望今宵欢爱！着小姐这般用心，不才张珙，合当跪拜。
小生无宋玉般容，潘安般貌，子建般才；姐姐，你则是可怜见为人在客！。','',''),('yuanqu-029','草桥店梦莺莺(第四本)・元和令','王实甫','yuanqu','','','绣鞋儿刚半拆，柳腰儿勾一搦，羞答答不肯把头抬，只将鸳枕捱。
云鬟仿佛坠金钗，偏宜髟狄髻儿歪。','',''),('yuanqu-030','草桥店梦莺莺(第四本)・胜葫芦','王实甫','yuanqu','','','我这里软玉温香抱满怀。
呀，阮肇到天台，春至人间花弄色。
将柳腰款摆，花心轻拆，露滴牡丹开。','',''),('yuanqu-031','草桥店梦莺莺(第四本)・后庭花','王实甫','yuanqu','','','春罗原莹白，早见红香点嫩色。
(旦云)羞人答答的，看甚么？(末)灯下偷晴觑，胸前着肉揣。
畅奇战，浑身通泰，不知春从何处来？无能的张秀才，孤身西洛客，自从逢稔色，思量的不下怀；忧愁因间隔，相思无摆划，谢芳卿不见责。','',''),('yuanqu-032','草桥店梦莺莺(第四本)・柳叶儿','王实甫','yuanqu','','','我将你做心肝儿般看待，点污了小姐清白。
忘餐废寝舒心害，若不是真心耐，志诚捱，怎能够这相思苦尽甘来？。','',''),('yuanqu-033','草桥店梦莺莺(第四本)・青哥儿','王实甫','yuanqu','','','成就了今宵欢爱，魂正在九霄云外。
投至得见你多情小奶奶，憔悴形骸，瘦似麻秸。
今夜和谐，犹自疑猜。
露滴香埃，风静闲阶，月射书斋，云锁阳台；审问明白，只疑是昨夜梦中来，愁无奈。','',''),('yuanqu-034','草桥店梦莺莺(第四本)・寄生草','王实甫','yuanqu','','','多丰韵，忒稔色。
乍时相见教人害，霎时不见教人怪，些儿得见教人爱。
今宵同会碧纱厨，何时重解香罗带。','',''),('yuanqu-035','草桥店梦莺莺(第四本)・煞尾','王实甫','yuanqu','','','春意透酥胸，春色横眉黛，贱却人间玉帛。
杏脸桃腮，乘着月色，娇滴滴越显得红白。
下香阶，懒步苍苔，动人处弓鞋凤头窄。
叹鲰生不才，谢多娇错爱。
若小姐不弃小生，此情一心者，你是必破工夫明夜早些来。
(下)。','',''),('yuanqu-036','草桥店梦莺莺(第四本)・越调/斗鹌鹑','王实甫','yuanqu','','','则着你夜去明来，倒有个天长地久，不争你握雨携云，常使我提心在口。
你则合带月披星，谁着你停眠整宿？老夫人心数多，情性亻刍；使不着我巧语花言，将没做有。','',''),('yuanqu-037','草桥店梦莺莺(第四本)・紫花儿序','王实甫','yuanqu','','','老夫人猜那穷酸做了新婿，小姐做了娇妻，这小贱人做了牵头。
俺小姐这些时春山低翠，秋水凝眸。
别样的都休，试把你裙带儿拴，纽门儿扣，比着你旧时肥瘦，出落得精神，别样的风流。
(旦云)红娘，你到那里小心回话者！(红云)我到夫人处，必问："这小贱人，。','',''),('yuanqu-038','草桥店梦莺莺(第四本)・金蕉叶','王实甫','yuanqu','','','"我着你但去处行监坐守，谁着你拖逗的胡行乱走？"若问着此一节呵如何诉休？你便索与他个"知情"的犯由。','',''),('yuanqu-039','草桥店梦莺莺(第四本)・调笑令','王实甫','yuanqu','','','你绣帏里效绸缪，倒凤颠鸾百事有。
我在窗儿外几曾轻咳嗽，立苍苔将绣鞋儿冰透。
今日个嫩皮肤到将粗棍抽，姐姐呵，俺这通殷勤的着甚来由？。','',''),('yuanqu-040','草桥店梦莺莺(第四本)・鬼三台','王实甫','yuanqu','','','夜坐时停了针绣，共姐姐闲穷究，说张生哥哥病久。
咱两个背着夫人，向书房问候。
(夫人云)问候呵，他说甚么？(红云)他说来，道"老夫人事已休，将恩变为仇，着小生半途喜变做忧"。
他道："红娘你且先行，教小姐权时落后。','',''),('yuanqu-041','中吕・阳春曲别情','王伯成','yuanqu','','','多情去后香留枕，好梦回时冷透衾，闷愁山重海来深。
独自寝，夜雨百年心。','',''),('yuanqu-042','仙吕・春从天上来闺怨','王伯成','yuanqu','','','巡官算我，道我命运乖，教奴镇日无精彩。
为想佳期不敢傍妆台，又恐怕爹娘做猜，把容颜只恁改。
漏永更长，不由人泪满腮。
他情是歹，咱心且捱，终须也要还满了相思债。
套数。','',''),('yuanqu-043','般涉调・哨遍项羽自刎','王伯成','yuanqu','','','虎视鲸吞相并，灭强秦已换炎刘姓。
数年逐鹿走中原，创图基祚隆兴。
各驰骋，布衣学剑，陇亩兴师，霸业特昌盛。
今日悉皆扫荡，上合天统，下应民情。
睢河岸外勇难施，广武山前血犹腥。
恨错放高皇，懊失追韩信，悔不从范增。','',''),('yuanqu-044','幺・行走行迎，故然怒激刚强性。迤逗向垓心，预埋伏掩映山形，猛围定。','王伯成','yuanqu','','','涧溪沟壑，列介胄寒光莹，昼夜攻催劫掠，爪牙脱落，羽翼雕零。
一个向五云乡里贺升平，一个向八卦图中竞残生，更那堪时月严凝。','',''),('yuanqu-045','麻婆子・汉祖胜乘威势，上苍助显号令。四野布层阴重，六花飞万片轻。','王伯成','yuanqu','','','不添和气报丰年，特呈凶兆害生灵。
手拘束难施展，足滑擦岂暂停。','',''),('yuanqu-046','幺・自清晓彻终日，从黄昏睚五更。趁水泽身难到，夺樵路力不能。旋消','王伯成','yuanqu','','','冰雪润枯肠，冻烧器械焰荒荆。
马无草人无饭，立不安坐不宁。','',''),('yuanqu-047','墙头花・军收雪霁，起凛冽严风劲，汗湿征衣背似冰。战欣欣火灭烟消，','王伯成','yuanqu','','','干剥剥天寒地冷。','',''),('yuanqu-048','幺・征夫梦寐清，深夜疆场静，四面悲歌忍泪听。便不思败国亡家，皆子','王伯成','yuanqu','','','想离乡背井。','',''),('yuanqu-049','急曲子・帐周回立故壁，阵东南破去程。众儿郎已杳然，总安眠睡未惊。','王伯成','yuanqu','','','忽闻嘶困乏征碗，猛唤回凄凉梦境。','',''),('yuanqu-050','耍孩儿・唯除个植楚怀忠政，错认做奸人暗等。误截一臂不任疼，猛魂飘','王伯成','yuanqu','','','已赴幽冥。
碧澄澄万里天如水，明朗朗十分月满营。
马首立虞姬氏，翠蛾低敛，粉泪双擎。','',''),('yuanqu-051','幺・绝疑的宝剑挥圆颈，不二色的刚肠痛。怎教暴露在效墟，惜香肌难入','王伯成','yuanqu','','','山陵。
望碧云芳草封高冢，对黄土寒沙赴浅坑。
伤情兴，须臾天晓，仿佛平明。','',''),('yuanqu-052','三煞・衡路九条，山垓九层，区区纵堑奔荒径。开基创业时皆尽，争帝图','王伯成','yuanqu','','','王势已倾。
军逐，因寻江路，误入阴陵。','',''),('yuanqu-053','二・付能归船路开，却懒将踏板登，丧八千子弟无踪影。羞归西楚亲求救，','王伯成','yuanqu','','','耻向东吴再起兵。
辞了枪骑，伏霜锋闪烁，从二足奔腾。','',''),('yuanqu-054','一・杀五侯虽惧怯，奈只身枉战争，自知此地绝天命。壮怀已丧英雄气，','王伯成','yuanqu','','','巨口全无叱咤声。
寻思到一场长叹，百战衰形。','',''),('yuanqu-055','尾・解委颔把顿项推，举太阿将咽颈称。子见红飘飘光的的绛缨先偏侧了','王伯成','yuanqu','','','金盔顶，碜可可湿浸浸鲜血早淋漓了战袍领。
赠长春宫雪庵学士过隙驹难留时暂，百年几度聪明暗。
尘事饱经谙，叹狙公暮四朝三。
抵自惭，远投苍海，平步风波，空擘骊龙颔。
谩赢得此身良苦，家私分外，活计尴尬。
寝食玉锁紧牵连，行坐金枷自披担。
世累相萦，阴行难修，业缘未减。','',''),('yuanqu-056','幺・因见无常，谩劳供养看经忏。虽有六亲人，谁能替入棺函。劝省咱，','王伯成','yuanqu','','','从今白甚，则管教人，吃粉羹餐酸馅，皮骨这回绝却。
三年乳哺，十月怀耽，长春有景闷时游，大道无极静中参。
出凡笼再不争搀。','',''),('yuanqu-057','幺・浮云世态将人赚，识破也诚何以堪。布袍独驾九天风，玩无穷绿水青','王伯成','yuanqu','','','东游瀛海思徐福，西度流沙慕老聃。
抛持尽雀巢燕垒，虎窟龙潭。','',''),('yuanqu-058','一煞・从释缚，自脱监，纸鸢无线舟无缆。风寒暑湿非吾患，昧色声香莫','王伯成','yuanqu','','','我贪。
休只待，船中满载，水低俱淹。','',''),('yuanqu-059','三煞・衣锦裘，乘骏骖，与朋共敝虽无憾。箪瓢自乐颜回巷，版筑谁亲傅','王伯成','yuanqu','','','说岩。
君不见，花飞树底，日转天南。','',''),('yuanqu-060','五煞・饭已熟，睡正酣，尽他世味无如淡。诗囊经卷随藜杖，苍木黄菁满','王伯成','yuanqu','','','药篮。
回头笑，青钱拍板，乌帽蓝衫。','',''),('yuanqu-061','董秀英花月东墙记・仙吕/赏花时','白朴','yuanqu','','','文质彬彬一丈夫，千里寻师为学谋。
今日个践路途，单身独步，云外雁声孤。','',''),('yuanqu-062','董秀英花月东墙记・幺篇','白朴','yuanqu','','','我如今赤手空拳百事无，父丧家贫不似初，囊箧尽消疏。
鹏程有路，何日赴皇都？(云)行了个月期程，到得松江府。
家童，你寻个客店安下。
(童云)理会的。
兀那就是一所店房。
店主在家么？(净上，云)谁叫，谁叫？(童云)老者，俺家长来此投宿。
(做见科，云)小生动问老公公，此处董府尹在否？(净云)府尹下世去了。
(生云)他宅子在何处？(净云)隔壁就是。
足下与府尹甚亲？(生云)先父与府尹相交契厚。
自先父下世，一向间阔，不曾问候。
(净云)足下如今那里去？(生云)小生儒业进身，游学至此，将赴诏选。
敢问公公，有房舍借一间小生借居，待来春赴试。
(净云)足下既要安住，老夫有一小顽，名曰山寿，就托足下教训攻书。
老夫东墙下有一花木堂，先生就在其中设馆，如何？(生云)如此多谢！(净云)院公，疾忙收拾洁净者。
(院公云)已停当了。
(净云)先生，请往花木堂安歇。
(同下)。','',''),('yuanqu-063','董秀英花月东墙记・吕仙/点绛唇','白朴','yuanqu','','','万物乘春，落花成阵，莺声嫩。
垂柳黄匀，越引起心间闷。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-064','董秀英花月东墙记・混江龙','白朴','yuanqu','','','三春时分，南园草木一时新。
清和天气，淑景良辰。
紫陌游人嫌日短，青闺素女怕黄昏。
寻芳俊士，拾翠佳人。
千红万紫，花柳分春。
对韶光半晌不开言，一天愁都结做心间恨。
憔悴了玉肌金粉，瘦损了窈窕精神。','',''),('yuanqu-065','董秀英花月东墙记・油葫芦','白朴','yuanqu','','','杏朵桃枝似绛唇，柳絮纷，春光偏闪断肠人。
微风细雨催花信，闲愁万种心间印。
罗帏绣被，孤寒欲断魂。
掩重门尽日无人问，情不遂越伤神。','',''),('yuanqu-066','董秀英花月东墙记・天下乐','白朴','yuanqu','','','我只见杨柳横墙易得春，欢欣，可意人，一见了心下如何忍。
送秋波眼角情，近东墙住左邻，觑了可憎才有就因。','',''),('yuanqu-067','董秀英花月东墙记・那吒令','白朴','yuanqu','','','一见了那人，不由我断魂；思量起这人，有韩文柳文；他是个俏人，读齐论鲁论。
想的咱不下怀，几时得成秦晋，甚何年一处温存？。','',''),('yuanqu-068','董秀英花月东墙记・鹊踏枝','白朴','yuanqu','','','好教我闷昏昏，泪纷纷，都只为美貌潘安，仁者能仁。
一会家心中自忖，谁与俺通个殷勤。','',''),('yuanqu-069','董秀英花月东墙记・寄生草','白朴','yuanqu','','','怕的是黄昏后，入罗帏愁越狠。
孤眠独枕教人闷，愁潘病沈教人恨，行迟力顿教人困。
似这等含情掩卧象牙床，几时得阳台上遇着多才俊。
(梅云)姐姐，我猜着你，敢待和昨日那秀才说话。
他在那壁，你在这壁，如何得会？(旦云)想当初卓文君怎生私奔相如来？(梅云)他两个缘何便得成就来？(旦唱)。','',''),('yuanqu-070','董秀英花月东墙记・幺篇','白朴','yuanqu','','','汉相如在寒窗下，卓氏女配做婚。
都只为我情你意相投顺，姻缘自把佳期问，郎才女貌皆相趁。
你道是阻东墙难会碧纱厨，似俺这干荷叶那讨灵犀润。','',''),('yuanqu-071','董秀英花月东墙记・后庭花','白朴','yuanqu','','','似这等害相思怎地忍？不由人上心来雨泪频。
避不的老母将将怪，好教我留连心上人。
枉劳魂，不觉的罗衣宽褪。
被生寒怎地温？看看的憔悴了身，厌厌的害杀人。
唤梅香掩上门，把沉檀炉内焚，志诚心祷告神。','',''),('yuanqu-072','董秀英花月东墙记・柳叶儿','白朴','yuanqu','','','呀，愁锁定眉尖春恨，怎不教心怀忧闷？见如今人远天涯近，难勾引，怎相交？越加上鬼病三分。','',''),('yuanqu-073','董秀英花月东墙记・青哥儿','白朴','yuanqu','','','对人前一言难尽，老夫人治家严训，怨俺那火性如雷老母亲。
谨慎闺门，昼夜追巡，坐守行跟，恐失人伦。
但若离了半时辰，来相问。
(梅云)姐姐，似你今春多病，可以自己调理，莫费神思。
不争你这等念想，倘若其身有失，如何是了？休休，莫要护病成疾，自损其身。
姐姐自当思之。
(旦云)梅香，你可知我心间的事？(梅云)妾虽不知，见姐姐身体不快，以此谏劝，自可调理。
(旦云)似这等病，如何治度？我一会家不想起来便罢，一会家想将起，好是凄凉人也！(唱)。','',''),('yuanqu-074','董秀英花月东墙记・赚煞','白朴','yuanqu','','','合晚至黄昏，独宿心间闷。
苦厌厌忧愁自忖。
便有铁石心肠也断魂。
串香焚被冷谁温，引入多情梦里人。
窗儿外月华正新，玉人儿在方寸，我将这海棠花分付与东君。','',''),('yuanqu-075','董秀英花月东墙记・正宫/端正好','白朴','yuanqu','','','下香阶，踏芳径，步苍苔月影当庭。
过回廊一弄凄凉景，好教我添悲兴。','',''),('yuanqu-076','董秀英花月东墙记・滚绣球','白朴','yuanqu','','','垂杨宿鸟惊，绣鞋不待行。
降明香问天求聘，志诚心祷告神灵。
相思病渐成，看看瘦损形，受寂寞事关前定，盼佳期井底银瓶。
似这等栖迟误了奴家命，强打精神拜斗星，何日安宁？(梅云)姐姐，你听那里冰弦之声。
(旦唱)。','',''),('yuanqu-077','董秀英花月东墙记・倘秀才','白朴','yuanqu','','','则道是半空中神仙胜境，却元来东墙下把丝桐慢整，你听他款抚冰弦音韵清。
夜阑人静，情悲戚，话丁宁，怎不教人动情？。','',''),('yuanqu-078','董秀英花月东墙记・滚绣球','白朴','yuanqu','','','我向这东墙仔细听。
凤求鸾曲未成，怎不教想的人成病，今日个聪明的遇着聪明。
这琴陶潜膝上横，蔡邕爨下生。
断肠人这答儿孤另，一句句诉你飘零。
几时得同衾共枕销金帐，满斗焚香说誓盟，愿足平生。','',''),('yuanqu-079','董秀英花月东墙记・倘秀才','白朴','yuanqu','','','他在那东墙下诗和了一声，我这里近亭轩把绣鞋立定，好教我兜上心来意不宁。
愁攒眉角上，忽的动伤情，知他是怎生？。','',''),('yuanqu-080','董秀英花月东墙记・呆骨朵','白朴','yuanqu','','','我这里闷厌厌锁不住疏狂性，怎禁的独自伤情？孤帏里翠减香消，花稍上蜂喧蝶并。
少年人辜负了三春景，身体也无康盛。
自思量怎奈何，渐染出风流病。','',''),('yuanqu-081','江州司马青衫泪・仙吕/点绛唇','马致远','yuanqu','','','从天未拔白，酒旗挑在歌楼外。
呀地门开，早送旧客迎新客。','',''),('yuanqu-082','江州司马青衫泪・天下乐','马致远','yuanqu','','','则索倚定门儿手托腮，想别人家奴胎，也得个自在；轮到我根脚里，都世袭了烟月牌。
他管甚桃李开，风雨筛，更问甚青春不再来。
(白乐天同贾、孟上，云)走了这半日，人说道这是裴妈妈家。
不好进去，我咳嗽一声。
(卜儿云)是谁在外边？(出见科)原来是三位进士公，请里面坐。
(白乐天同贾、孟云)妈妈祗揖。
(卜儿云)兴奴孩儿，来陪三位进士公。
快抬桌儿，看酒来！(正旦觑科，云)好是奇怪，娘见了三个秀才踏门，怎生便教看酒？(唱)。','',''),('yuanqu-083','江州司马青衫泪・醉扶归','马致远','yuanqu','','','送了几辈儿茶员外，都是这一副儿酒船台。
俺娘吃不的荤腥教酒肉搋，待觅厌饫的新黄菜。
他手里怎容得这几个酸寒秀才？(带云)我知道了也。
(唱)俺娘八分里又看上他那条乌犀带。
(正旦出见科)三位万福。
(白乐天同贾、孟云)大姐祗揖了。
(正旦唱)。','',''),('yuanqu-084','江州司马青衫泪・后庭花','马致远','yuanqu','','','这里是风尘花柳街，又不是王侯宰相宅。
我忙着笑脸儿迎将去，学士是甚风儿吹到来？(白乐天云)我等久慕高名，特来一拜。
(正旦唱)是几个俊秀才，偏他还咱一拜，怎做的内心儿不敬色。
(云)敢问官人尊姓大名？(白乐天云)小生是侍郎白居易。
这二位是学士贾浪仙、孟浩然。
因此春日，公衙无事，换了衣服来街市闲行。
久慕大姐德容，一径的来拜望。
(正旦云)不敢不敢。
学士大人不弃下贱，小酌三杯如何？(白乐天云)好便好，只是不敢取扰。
(正旦把酒科)(贾浪仙云)今日幸遇大姐，咱多饮几杯。
(孟浩然云)我还有人求的几首诗未了，少吃醉些。
(正旦唱)。','',''),('yuanqu-085','江州司马青衫泪・后庭花','马致远','yuanqu','','','你待赚鳌鱼钓颊腮，怎想与刘伶装布袋？我这怪脸儿奸如鬼，你酒肠宽似海。
(贾、孟云)我们都已醉了，不要过了酒戒，不吃罢。
(正旦唱)畅开怀，都似你朦胧酒戒，那醉乡侯安在哉？(卜儿云)二位学士醉了，侍郎再坐一坐。
(贾、孟云)乐天侍郎，咱且回去，明日再来。
(白乐天云)平白里打扰了一日，怎生就空去了？(正旦唱)。','',''),('yuanqu-086','江州司马青衫泪・金盏儿','马致远','yuanqu','','','我不曾流水出天台，你怎么走马到章台。
(乐天云)定害了你这一日。
(正旦唱)更待要秦楼夜访金钗客，索甚么恶叉白赖闹了洛阳街。
兀那酒丧门临本命，饿太岁犯家宅。
虽是我管待这两个穷秀士，权当一百日血光灾！。','',''),('yuanqu-087','江州司马青衫泪・赚煞','马致远','yuanqu','','','稍似间有些钱，抵死里无多债，权做这场折本买卖。
若信着俺当家老奶奶，把惜花心七事儿分开。
哎，你个俏多才，不是我相择，你更怕辱没着俺门前下马台！俺娘山河易改，解元每少怪。
(带云)侍郎记者，(唱)怕你再行踏，休引外人来。
(同下)楔子。','',''),('yuanqu-088','江州司马青衫泪・正宫/端正好','马致远','yuanqu','','','命轻薄，身微贱，好人死万万千。
世间儿女别离遍，也敷不上俺那阳关怨！(带云)侍郎，不争你去了，教我倚靠何人？(唱)。','',''),('yuanqu-089','江州司马青衫泪・滚绣球','马致远','yuanqu','','','你好下得白解元，闪下我女少年。
道不得可怜而见，他又不曾故违着天子三宣。
(云)人说白侍郎吟诗吃酒误了政事，前人也有这等的。
(唱)只那长安市李谪仙，他向酒里卧酒里眠，尚古自得贵妃捧砚，常走马在五凤楼前。
偏教他江州迭配三千里，可不道吏部文章二百年，甚些的纳士招贤？(见卜科，云)母亲，叫你孩儿怎么？(卜儿云)白侍郎一去杳无音信，咱家柴没米没，怎生过活？如今浮梁刘官人有三千引茶，又标致又肯使钱。
你留下他，赚些钱养家。
(正旦云)母亲，我与白侍郎有约在前，我再不留人了。
(卜儿云)我说你也不信，请刘官人自家来和你说。
(净见旦科，云)大姐拜揖，小人久慕大名，拿着三千引茶来与大姐焐脚，先送白银五十两做见面钱。
(正旦云)过一边去！好不知高低。
我做了白侍郎之妻，休来缠我！(卜儿云)你不肯陪我刘员外，好个白侍郎夫人！如今白侍郎那里敢颓气了也。
(正旦唱)。','',''),('yuanqu-090','江州司马青衫泪・倘秀才','马致远','yuanqu','','','这姻缘成不成在天，你休见兔儿起呵漾砖。
情知普天下虔婆那一个不爱钱。
(带云)刘员外呵，(唱)他便是贵公子、赵平原，你也要过遣。
(净云)你家是卖俏门庭，我来做一程子弟，你不留我，如何倒拒绝我？(正旦唱)。','',''),('yuanqu-091','江州司马青衫泪・滚绣球','马致远','yuanqu','','','这的是我逆耳言，休厮缠、厮缠着舞裙歌扇，这两般儿曾风流断没了家缘。
刘员外你若识空便，早动转，倒落得满门良贱。
休觑着我这陷人坑，似误入桃源；我怕你两尖担脱了孤馆思乡客，三不归翻了风帆下水船，枉受熬煎。','',''),('yuanqu-092','江州司马青衫泪・倘秀才','马致远','yuanqu','','','这些时但合眼早怀儿里梦见，则是俺吃倒赚江州乐天。
(卜儿云)见钟不打，更去炼铜。
乐天乐天，在那里？(净云)小子也看的过，咱做一程夫妻，怕做甚么？(正旦唱)谁教你闷向秦楼列管弦？(带云)刘员外，(唱)休信我，醉中言，说则说在前。
(云)天那！怎生教我陪伴这样人也！(唱)。','',''),('yuanqu-093','江州司马青衫泪・叨叨令','马致远','yuanqu','','','我这两日上西楼，盼望三十遍；空存得故人书，不见离人面。
听的行雁来也，我立尽吹箫院；闻得声马嘶也，目断垂杨线。
相公呵，你原来死了也么哥？你原来死了也么哥？从今后越思量越想的冤魂儿现！。','',''),('yuanqu-094','江州司马青衫泪・倘秀才','马致远','yuanqu','','','侍郎呵，你往常出入在皇宫内院，只合生死在京师帝辇，也落得个金水河边好墓田。
(带云)刘员外，(唱)你且离了我跟前，他从来有些腼腆。','',''),('yuanqu-095','江州司马青衫泪・滚绣球','马致远','yuanqu','','','你文章胜贾浪仙，诗篇压孟浩然。
不能够侍君王在九间朝殿，怎想他短卒律命似颜渊。
今日扑通的瓶坠井，支楞的琴断弦，怎能够眼前面死魂活现？你若有灵圣，显形影向月下星前。
则这半提淡水招魂纸，侍郎也，当得你一盏阴司买酒钱。
止不住雨泪涟涟。','',''),('yuanqu-096','江州司马青衫泪・醉太平','马致远','yuanqu','','','烧一陌纸儿钱，叙几句儿衷言。
待不啼哭，夫乃妇之天，抛闪杀我也少年！只见一个来来往往旋风足律即留转，吓的我慌慌张张手脚滴羞笃速战。
一个俏魂灵不离了我打盘旋，我做人的解元。
(净云)大姐，纸也烧了，夫妇之情也尽了，请上船罢。
(正旦唱)。','',''),('yuanqu-097','江州司马青衫泪・一煞','马致远','yuanqu','','','兴奴也，你早则不满梳绀发挑灯剪，一炷心香对月燃。
我心下情绝，上船恩断；怎舍他临去时舌奸，至死也心坚。
到如今鹤归华表，人老长沙，海变桑田。
别无些挂恋，须索何红蓼岸绿杨川。
(净云)大姐去罢。
这等哭，哭到几时？(正旦唱)。','',''),('yuanqu-098','江州司马青衫泪・二煞','马致远','yuanqu','','','少不的听那惊回客梦黄昏犬，聒碎人心落日蝉。
止不过临万顷苍波，落几双白鹭；对千里青山，闻两岸啼猿。
愁的是三秋雁字，一夏蚊雷，二月芦烟。
不见他青灯黄卷，却索共渔火对愁眠。
(卜儿云)员外等久了，云罢。
(正旦唱)。','',''),('yuanqu-099','江州司马青衫泪・四煞','马致远','yuanqu','','','怎想他能捱磨扇似风车转，更合着梦见槐花要黄袄儿穿。
我虚度三旬，是这婆娘亲女；受用了十年，是这赵妈妈金莲。
我也曾有厅上待客，后阁内留宾，只不曾坐车上当辕。
偌来大穷坑火院，只央我一身填。','',''),('yuanqu-100','江州司马青衫泪・双调/新水令','马致远','yuanqu','','','正夕阳天阔暮江迷，倚晴空楚山叠翠。
冰壶天上下，云锦树高低。
谁倩王维，写愁入画图内？。','',''),('yuanqu-101','诸宫调风月紫云庭・幺','石君宝','yuanqu','','','西出阳关无故人，则见俺在这南国梁园依旧亲。
舍人呵，谁不知俺娘劣，恁爷狠？伯伯，两阵狂风是紧，也不到得教吹散楚城云。
(下)。','',''),('yuanqu-102','诸宫调风月紫云庭・仙吕/点绛唇','石君宝','yuanqu','','','怎想俺这月馆风亭，竹溪花径，变得这般嘿光景。
我每日撇嵌为生，俺娘向诸宫调里寻争竞。','',''),('yuanqu-103','诸宫调风月紫云庭・油葫芦','石君宝','yuanqu','','','我但有些卧枕着床脑袋疼，他委实却也心内惊，他急荒的清医人诊了脉却笑容生，他道是喜的女孩儿感得些风寒症，惭愧呵谢天地不是相思病。
(带云)你教俺尽世儿厮守着，娘呵，(唱)你这般毒害心，狠劣情。
但见对锦鸳鸯他水上才交颈，你早则着棒打过蓼花汀！。','',''),('yuanqu-104','诸宫调风月紫云庭・天下乐','石君宝','yuanqu','','','呵！你肯教双宿双飞过一生，便则我子弟每行依平。
休有情，教我打迭起那暖和出落着冷。
满脸儿半指霜，通身儿一块冰。
娘呵，我一处也画堂春自生。','',''),('yuanqu-105','诸宫调风月紫云庭・醉中天','石君宝','yuanqu','','','我唱道那双渐临川令，他便脑袋不嫌听，提起那冯员外，便望空里助采声。
把个苏妈妈便是上古贤人般敬。
我正唱到不肯上贩茶船的小卿，向那岸边厢刁蹬，(带云)俺这虔婆道，(唱)兀得不好拷末娘七代先灵！。','',''),('yuanqu-106','诸宫调风月紫云庭・醉扶归','石君宝','yuanqu','','','这逗镘的是咱些权柄，呵，色就事便是你得人情。
那厮每拿着二分钞便害疼。
(带云)害疼，咱每就呵便二十锭三十锭呵，(唱)更磕着如今等。
干咽唾相思的后生，那个不害这般干使钞干嘿病？(正末云住)(正旦唱)。','',''),('yuanqu-107','诸宫调风月紫云庭・金盏儿','石君宝','yuanqu','','','上俺门来的酒客每为我这妙唱若雏莺，引的他每豪饮似长鲸。
我委实为甚停杯听曲教快成病，我安排桃花扇影，他每便破香枨。
尚自着瓦磁为巨器，也则是陶泻庆新声。
嗷！若还更酒斟金潋滟。
大的好歌立玉娉婷！。','',''),('yuanqu-108','诸宫调风月紫云庭・后庭花','石君宝','yuanqu','','','俺这老婆，肚皮里将六韬三略盛，面皮上把四时八节擎。
未见钱罗，呀，冬雪严霜降；得了钞罗，春风和气生。
俺这个狠精灵，他那生时节决定，犯着甚爱钱巴镘的星。','',''),('yuanqu-109','诸宫调风月紫云庭・幺','石君宝','yuanqu','','','也难奈何俺那六臂那吒般狠柳青，我唱的那七国里庞涓也没这短命，则是个八怪洞里爱钱精。
我若还更九番家厮并，他比的十恶罪尚尤轻。','',''),('yuanqu-110','诸宫调风月紫云庭・赚尾','石君宝','yuanqu','','','郎君每我行有十遍雨云期，除是害九伯风魔病。
俺家里八下里窝弓陷坑，你便有七步才无钱也不许行，六艺全便休卖聪明。
哎！为甚恁这五陵人，把俺这等嘿交易难成？你便是四付马上驼来也索两平。
俺这里别是个三街市井，另置下二连等秤，恰好的教恁一分银买一分情！(下)。','',''),('yuanqu-111','诸宫调风月紫云庭・南吕/一枝花','石君宝','yuanqu','','','(残缺)。','',''),('yuanqu-112','诸宫调风月紫云庭・梁州第七','石君宝','yuanqu','','','(残缺)。','',''),('yuanqu-113','诸宫调风月紫云庭・感皇恩','石君宝','yuanqu','','','□□□□，□□□□。
□□□，□□□。
只教我立化做一块望夫石。
我便似病人冲太岁，他管也小鬼见钟馗腌材料，风短命，欠东西。','',''),('yuanqu-114','诸宫调风月紫云庭・隔尾','石君宝','yuanqu','','','嗨，比俺娘那熬煎增十倍，恰才这些崎险艰难好做一回。
哎，不做美的恩官干坏了他把戏。
哎，唱话的小一，则好打恁兀那把门的老嘿，切不可放过这没钱雁看的。','',''),('yuanqu-115','诸宫调风月紫云庭・红芍药','石君宝','yuanqu','','','兀的那般恶缘恶业镇相随，好教人难摘难离。
也是某年某月不曾离，无事无非。
奶奶，你是老人家，(唱)须知些道理，有的事便捱不到家里？(卜儿云，住)(正旦唱)越道着越查声破嗓越骂得精细，前面他老相公听的。','',''),('yuanqu-116','诸宫调风月紫云庭・二煞','石君宝','yuanqu','','','当日那梁公曾施行虎豹是真锋利，哎！包龙图呵，你这般拆散鸳鸯算甚正直？我也觑不得这光景掩不迭这泪。
我这壁道防送早催逼，他那壁带铁锁囚人监系，俺两处各心碎！是有遭间阻的也不似俺不吉利，兀的是甚末娘别离！。','',''),('yuanqu-117','诸宫调风月紫云庭・收尾','石君宝','yuanqu','','','几曾见递流南浦人千里，怎饮这，配役阳关酒一杯！到如今说甚的，比别的记相识，你情知我心意，你知咱我知你。
歹处无好处记，休想我再出入。
我寸肠中似刀刺，恁尊居。
忒情理，合舍了怕甚的！哎，莲子花官人愿的你一千岁。
嗨！怎直恁般下得？(卜儿云了)(正旦唱)咭！则是你了得，吡！都是你个吸人髓虔婆直攘到底！(下)。','',''),('yuanqu-118','诸宫调风月紫云庭・中吕/粉蝶儿','石君宝','yuanqu','','','我本是个邪祟妖魔，他那俏魂灵倒将咱着末。
呵，大冈来意气相合，今日把我情肠，他肺腑都混成一个。
虽隔着千里关河，不曾有半个时辰意中捱过。','',''),('yuanqu-119','诸宫调风月紫云庭・醉春风','石君宝','yuanqu','','','人害兀那魔病有时潜，则这相思无处躲。
直到再团圆被儿里得些温存，恁地后便可、可。
我想世上这一点情缘，百般缠缴，有几人识破？(卜儿云，外住)(正旦唱)。','',''),('yuanqu-120','诸宫调风月紫云庭・迎仙客','石君宝','yuanqu','','','姨姨，我为甚罢了雨云？却也是避些风波。
做这些淡生涯，且熬那穷过活。
这些时调不上勤儿，却则是忙着俺老婆。
都则为我不肯张罗，以此上闲放着盘千斤磨。','',''),('yuanqu-121','临江驿潇湘秋夜雨・仙吕/端正好','杨显之','yuanqu','','','我恰才沉没这急流中，挣的到河滩上。
只看我这湿渌渌上下衣裳。
若不是渔翁肯把咱恩养，(带云)天那！(唱)这泼性命休承望。
(同下)。','',''),('yuanqu-122','临江驿潇湘秋夜雨・仙吕/点绛唇','杨显之','yuanqu','','','举目生愁，父亲别后难根究。
这一片悠悠，可也还留得残生否？。','',''),('yuanqu-123','临江驿潇湘秋夜雨・昆江龙','杨显之','yuanqu','','','若不是渔翁搭救，险些儿趁一江春水向东流。
我如今偷挨岁月，爹爹呵，知他在何处沉浮？则我这一寸心怀千古恨，两条眉锁十分忧。
多谢的那老父恩临厚，不将我似世人看待，直做个亲女收留。','',''),('yuanqu-124','临江驿潇湘秋夜雨・油葫芦','杨显之','yuanqu','','','则见他抄定攀蟾折桂手。
(崔甸士云)妹子，恕生面少拜识。
(正旦唱)待趋前还褪后，我则索慌忙施礼半含羞。
(崔甸士云)妹子，小生有缘得此一见。
(正旦唱)则见他身儿俊俏庞儿秀。
(崔甸士云)妹子，小生此后又不知何时重会哩。
(正旦唱)则见他性儿温润情儿厚。
且休夸潘安貌欠十分，子建才非八斗。
单只是白凉衫稳缀着鸳鸯扣，上下无半点儿不风流。','',''),('yuanqu-125','临江驿潇湘秋夜雨・天下乐','杨显之','yuanqu','','','则愿的早夺词场第一筹，文优福亦优，宴琼林是你男儿得志秋。
标题的名姓又香，打扮的体态又作，准备着插宫花饮御酒。','',''),('yuanqu-126','临江驿潇湘秋夜雨・醉中天','杨显之','yuanqu','','','才救出淮河口，又送上楚峰头。
(做背哭科，云)俺那父亲呵，(唱)生死茫茫未可水，怎便待通媒媾……(孛老云)我儿，你怎么不答应我一句儿？姻缘姻缘，事非偶然。
我也须不误了你。
(正旦唱)虽然道姻缘不偶，我可一言难就，有多少雨泣云愁。
(孛老云)我儿，这个是喜事，怎么倒哭起来？快不要这等。
我看的那侄儿满腹文章，一定是做官的。
故此将你许配了他。
常言道：女大不中留。
你见那家女孩儿养老在家里的？你只依着我，就今日两边行一个礼，承认了罢。
(正旦唱)。','',''),('yuanqu-127','临江驿潇湘秋夜雨・金盏儿','杨显之','yuanqu','','','元来他敬儒流，意绸缪。
可甚么是非只为多开口，倒道我女大不中留。
他分明亲许出，着我怎抬头？虽然俺心下有，我须是脸儿羞。
(孛老扯旦、末行礼科，云)则今日好日辰，成合了这门亲事。
侄儿，你与我便上朝求官应举去，得一官半职，回来改换家门．则是休忘了我的思念。
(正旦云)多谢父亲。
则怕崔秀才此一去，久后负了人也。
(崔甸士云)小生若负了你呵，天不盖，地不载，日月不照临。
(正旦云)秀才也，你去则去，频频的稍个书信回来。
(崔甸士云)小生知道，你放心者。
(正旦唱)。','',''),('yuanqu-128','临江驿潇湘秋夜雨・赚煞','杨显之','yuanqu','','','则他这胸臆卷江淮，宝剑辉星斗。
是俺那父亲匹配下鸾交凤友。
想着你千里关山独自个走，则今宵有梦难投。
你若到至公楼，占了鳌头，则怕你金榜无名誓不休。
莫便要心不应口，早做了背亲忘旧。
(带云)崔秀才也，(唱)休着我倚柴门，凝望断不归舟。
(下)。','',''),('yuanqu-129','临江驿潇湘秋夜雨・梁州','杨显之','yuanqu','','','我则见舞旋旋飘空的这败叶，恰便似红溜溜血染胭脂。
冷飕飕西风了却黄花事。
看了些林梢掩映，山势参差。
走的我口干舌苦，眼晕头疵。
我可也把不住抹泪揉眵，行不上软弱腰肢。
我、我、我，款款的兜定这鞋儿，是、是、是，慢慢的按下这笠儿，呀、呀、呀，我可便轻轻的拽起这裙儿。
我想起亏心的那厮，你为官消不得人伏侍。
你忙杀呵，写不得那半张纸？我也须有个日头儿见你时，好着我仔细寻思。
(云)可早来到秦川县了也。
我问人咱。
(做向古门问科，云)敢问哥哥，那里是崔甸士的私宅？(内云)则前面那个八字墙门便是。
(正旦云)哥哥，我寄着这包袱儿在这里，我认了亲眷呵便采取也。
(内云)放在这里不妨事，你自去。
(正旦云)门上有人么？你报复去，道有夫人在于门首。
(祗从云)兀那娘子，你敢差走了。
俺相公自有夫人哩。
(正旦云)你道甚么？(祗从云)俺相公自有夫人哩。
(正旦唱)。','',''),('yuanqu-130','临江驿潇湘秋夜雨・牧羊关','杨显之','yuanqu','','','兀的是闲言浯，甚意思？他怎肯道节外生枝。
我和他离别了三年，我怎肯半星儿失志？我则道他不肯弃糟糠妇，他原来别寻了个女娇姿。
只待要打灭了这穷妻子，呀、呀、呀，你畅好是负心的崔甸土。','',''),('yuanqu-131','临江驿潇湘秋夜雨・隔尾','杨显之','yuanqu','','','我则待妇随夫唱和你调琴瑟。
谁知你再娶停婚先有个泼贱儿。
(搽旦怒云)你这天杀的，他倒骂我哩。
(崔甸士云)左右，还不扯下去打呀？(正旦唱)倒将我横拖竖拽离阶址。
(带云)崔甸士，(唱)你须记的，那时亲设下誓词。
(崔甸士云)胡说，我有甚么誓词。
(正旦唱)你说道：不亏心，不亏心，把天地来指。','',''),('yuanqu-132','临江驿潇湘秋夜雨・哭皇天','杨显之','yuanqu','','','则我这脊梁上如刀刺，打得来青间紫。
飕飕的雨点下，烘烘的疼半时。
怎当他无情无情的棍子，打得来连皮彻骨，夹脑通心，肉飞筋断，血溅魂消，直着我一疼来，一疼来一个死。
我只问你个亏心甸上，怎揣与我这无名的罪儿？。','',''),('yuanqu-133','临江驿潇湘秋夜雨・乌夜啼','杨显之','yuanqu','','','你这短命贼怎将我来胡雕刺？迭配去别处官司，世不曾见这等跷蹊事。
哭的我气噎声丝，诉不出一肚嗟咨。
想天公难道不悲慈？只愿得你嫡亲伯父登时至，两下里质对个如何是？看你那能牙利齿，说我甚过犯公私？。','',''),('yuanqu-134','临江驿潇湘秋夜雨・黄钟煞','杨显之','yuanqu','','','休、休、休，劝君莫把机谋使，现、现、现，东岳新添-个速报司。
你、你、你，负心人，信有之，咱、咱、咱，薄命妾，自不是。
快、快、快，就今日，逐离此。
行、行、行，可怜见，只独自。
细、细、细心儿里，暗忖思，苦、苦、苦业身躯怎动止？管、管、管少不的在路上停尸。
(做悲科唱)哎哟，天那？但不知那塌儿里把我来磨勒死？(同解子下)(搽旦云)相公，莫非是你的前妻，敢不中么？不如留他在家，做个使用丫头，也省的人谈论。
(崔甸士云)夫人不要多心。
我那里有前妻来？(搽旦云)他适才说，等你嫡亲伯父来，要和你面对。
这怎么说？(崔甸士云)是我有个亲伯父，叫做崔文远。
这原是我伯父家丫头，卖与我的。
你看他模样倒也看的过。
只是手脚不好要做贼。
我前日到处寻不着他，今日自来寻我，怎么饶的他过？如今这一去，遇秋天阴雨，棒疮发呵，他也无那活的人也。
咱和你后堂中饮酒去来。
(诗云)幸今朝捉住逃奴，迭配去必死中途。
(搽旦诗云)他若果然是前时妻小，倒不如你也去一搭里当夫。
(同下)。','',''),('yuanqu-135','临江驿潇湘秋夜雨・喜迁莺','杨显之','yuanqu','','','淋的我走投无路，知他这沙门岛是何处酆都？长吁气成云雾。
行行里着车辙把腿陷住，可又早闪了胯骨。
