我吃饭时晒干了旧衣服，上路时又淋湿我这布里肚，吃交时掉下了一个枣木梳。','',''),('yuanqu-137','临江驿潇湘秋夜雨・幺篇','杨显之','yuanqu','','','我心中忧虑，有三桩事我命卒。
