(正旦唱)这云呵，他可便遮天映日闭了郊墟，这风呵，恰便似走石吹沙拔了树木，这雨可，他似箭竿悬麻妆助我十分苦。
(解子云)你走便走，不走我打你也。
(正旦云)哥哥。
(唱)。','',''),('yuanqu-138','临江驿潇湘秋夜雨・山坡羊','杨显之','yuanqu','','','则愿你停嗔息怒，百凡照觑，怎便精唇泼口骂到有三十句。
这路崎岖，水萦纡，急的我战钦钦不敢望前去，况是棒疮发怎支吾？刚挪得半步。
(带云)哥哥，你便打杀我呵，(唱)你可也没甚福。
(解子云)你休要多嘴多舌。
如今秋雨淋漓，一日难走一日。
快与我行动些。
(正旦唱)。','',''),('yuanqu-139','临江驿潇湘秋夜雨・刮地风','杨显之','yuanqu','','','则见他努眼撑睛大叫呼，不邓邓气夯胸脯。
我湿淋淋只待要巴前路，哎，行不动我这打损的身躯。
