不辨四东，把凌波步轻那动。','',''),('yuanqu-142','沙门岛张生煮海・混江龙','李好古','yuanqu','','','清宵无梦，引着这小精灵，闲伴我游踪。
恰离了澄澄碧海，遥望那耿耿长空。
