(侍女云)海中景物，与人间敢不同么？(正旦唱)觑了那人间风阙，怎比我水国龙宫？清湛湛、洞天福地任逍遥，碧悠悠、那愁他浴凫飞雁争喧哄。
似俺这闺情深远，直恁般好信难通！。','',''),('yuanqu-143','沙门岛张生煮海・油葫芦','李好古','yuanqu','','','海上神仙年寿永，这蓬莱在眼界中。
风飘仙袂绛绡红，则我这云鬟高挽金钗重，蛾眉轻展花钿动。
袖儿笼，指十葱，裙儿簌，鞋半弓。
只待学吹箫同跨丹山凤，那其间，登碧落，趁天风。
(侍女云)想天上人间，自然难比。
(正旦唱)。','',''),('yuanqu-144','沙门岛张生煮海・天下乐','李好古','yuanqu','','','不比那人世繁华扫地空，尘中，似转蓬，则他这春过夏来秋又冬。
