又不是采莲女拨棹声，又不是捕鱼叟鸣榔动，惊的那夜眠人睡眼朦胧。','',''),('yuanqu-146','沙门岛张生煮海・寄生草','李好古','yuanqu','','','他一字字情无限，一声声曲未终。
恰便似颤巍巍金菊秋风动，香馥馥丹桂秋风送，响珊珊翠竹秋风弄。
咿呀呀，偏似那织金梭撺断锦机声；滴溜溜，舒春纤乱撒珍珠进。','',''),('yuanqu-147','沙门岛张生煮海・六幺序','李好古','yuanqu','','','表诉那弦中语，出落着指下功，胜檀槽慢掇轻拢。
则见他正色端容，道貌仙丰。
莫不是汉相如作客临邛，也待要动文君，曲奏求凰风；不由咱不引起情浓。
你听这清风明月琴三弄，端的个金徽汹涌，玉轸玲珑。','',''),('yuanqu-148','沙门岛张生煮海・幺篇','李好古','yuanqu','','','端的心聪，那更神工，悲若鸣鸿，切若寒蛩，娇比花容，雄似雷轰，真乃是消磨了闲愁万种。
这秀才一事精，百事通。
我蹑足潜踪，他换羽移宫。
抵多少盼盼女词媚涪翁。
似良宵一枕游仙梦。
因此上偷窥方丈，非是我不守房栊。','',''),('yuanqu-149','沙门岛张生煮海・金盏儿','李好古','yuanqu','','','家住在碧云空，绿波中，有披鳞带角相随从，深居富贵水晶宫。
我便是海中龙氏女，胜似那天上许飞琼。
岂不知众星皆拱北，无水不朝东？(张生云)小娘子姓龙氏，我记得何承天《姓苑》上有这个姓来。
难道小娘子既然有姓，岂可无名？因甚至此？(正旦云)妾身龙氏三娘，小字琼莲。
见秀才弹琴，因听琴至此。
(张生云)小娘子既为听琴而至，这等，是赏音的了。
何不到书房中坐下，待小生细弹一曲，何如？(正旦云)愿往。
(做到书房科，正旦云)敢问先生高姓？(张生云)小生姓张名羽，字伯腾，潮州人氏。
早年父母双亡，也曾饱学诗书，争奈功名未遂，游学至此，并无妻室。
(侍女云)这秀才好没来头，谁问你有妻无妻哩！(家童云)不则是相公，我也无妻。
(张生云)小娘子不弃小生贫寒，肯与小生为妻么？(正旦云)我见秀才聪明智慧，丰标俊雅，一心愿与你为妻。
则是有父母在堂，等我问了时，你到八月十五日中秋节届，前来我家，招你为婿。
(张生云)既蒙小娘子俯允，只不如今夜便成就了，何等有趣，着小生几时等到八月十五日也！(家童云)正是，我也等不得。
(侍女云)你等不得，且是容易哩。
(正旦云)常言道："有情何怕隔年期"，这有甚等不得那？(唱)。','',''),('yuanqu-150','沙门岛张生煮海・后庭花','李好古','yuanqu','','','那里也阳台云雨踪，不比那秦楼风月丛。
(张生云)敢问小娘子家在何处？(正旦唱)只在这沧海三千丈，险似那巫山十二峰。
(张生云)小生做贵宅女婿，就做了富贵之郎，不知可有人服侍么？(正旦唱)俺可更有门风：无非足蛟虬参从，还有那鼋将军、鳖相公、鱼大人、虾爱宠、鼍先锋、龟老翁。
能浮波，惯弄风；隔云山，千万重；要相逢，指顾中。
(张生云)只要小娘子言而有信，俺小生是一个志诚老实的。
(正旦唱)。','',''),('yuanqu-151','沙门岛张生煮海・梁州第七','李好古','yuanqu','','','你看那缥缈间十洲三岛，微茫处阆苑蓬莱，望黄河一股儿浑流派。
高冲九曜，远映三台，上连银汉，下接黄埃。
势汪洋无岸无涯，出许多异宝奇哉。
看、看、看，波涛涌，光隐隐无价珠玑；是、是、是，草木氏，香喷喷长生药材；有、有、有，蛟龙偃，郁沉沉精怪灵胎。
常则是云昏气霭，碧油油隔断红尘界，恍疑在九天外。
平吞了八九区云梦泽，问甚么翠岛苍崖。','',''),('yuanqu-152','沙门岛张生煮海・牧羊关','李好古','yuanqu','','','猛地里难回避，可教人怎离摘？则见他叉手前来，多管是迷了路的行人，多管是失了船的过客。
(张生云)道姑，敢问这搭儿是何处也？(仙姑唱)比及你来相问，先对俺说明白。
(张生云)我到此，只为那可意人儿，不知在那里？(仙姑唱)且将个采芝女，权休怪，只问那可意人，安在哉？。','',''),('yuanqu-153','沙门岛张生煮海・骂玉郎','李好古','yuanqu','','','可知道龙宫美女多娇态，想当时因有约，则今日独寻来，拚的个舍残生，做下风流债。
那龙也青脸儿长左猜，恶性儿无可解，狠势儿将人害。
(张生云)可怎生恁般利害？(仙姑唱)。','',''),('yuanqu-154','沙门岛张生煮海・感皇恩','李好古','yuanqu','','','呀！他把那牙爪张开，头角轻抬。
一会儿起波涛，一会儿摧山岳，一会儿卷江淮。
变大呵，干坤中较窄；变小呵，芥子里藏埋。
他可便能英勇，显神通，放狂乖。','',''),('yuanqu-155','沙门岛张生煮海・采茶歌','李好古','yuanqu','','','他兴云雾，片时来，动风雨，满尘埃，则怕惊急烈一命丧尸骸。
休为那约雨期云龙氏女，送了你个攀蟾折桂俊多才。','',''),('yuanqu-156','沙门岛张生煮海・黄钟煞尾','李好古','yuanqu','','','这宝呵。
出八那瑶台紫府清虚界，碧落苍空天上来。
任熬煎，任布划，可从心，可称怀，不求亲，不纳财，做行媒，做娇客，连理枝，并蒂开，凤鸾交，鱼水谐，休将他，觑小哉，信神仙，妙手策。
也是那前生福有安排，直着你沸汤般煎干了这大洋海。
(下)。','',''),('yuanqu-157','沙门岛张生煮海・正宫/端正好','李好古','yuanqu','','','一地里受煎熬，遍寰宇空劳攘，兀的不慌杀了海上龙王。
我则见水晶宫血气从空撞，闻不得鼻口内干烟炝。','',''),('yuanqu-158','沙门岛张生煮海・滚绣球','李好古','yuanqu','','','那秀才谁承望，急煎煎做这场，不知他挟着的甚般伎俩，只待要卖弄杀手段高强。
莫不是放火光，逼太阳，烧的来焰腾腾滚波翻浪。
纵有那雷和雨，也救不得惊惶。
则见锦鳞鱼活泼刺波心跳，银脚蟹乱扒沙在岸上藏，但着一点儿，就是一个燎浆。
(做到科，云)来到此间，正是沙门岛海岸了。
兀那秀才，你在此煮着些甚么哩？(张生云)我煮海也。
(正末云)你煮他那海做甚么？(张生云)老师父不知，小生前夜在于寺中操琴，有一女子前来窃听，他说是龙氏三娘，小字琼莲，亲许我中秋会约。
不见他来，因此在这里煮海，定要煎他出来。
(正末唱)。','',''),('yuanqu-159','沙门岛张生煮海・滚绣球','李好古','yuanqu','','','俺也不是化道粮，也不是要供养，我则是特来相访。
(张生云)我是个穷秀才，相访我有甚么化与你。
(正末唱)俺本是出家人，便乞化何妨。
(张生云)若得见那小娘子，肯招我做女婿，便有布施。
(正末唱)则为那窈窕娘，不招你个俊俏郎，弄出这一番祸从天降。
你穷则穷道与他门户辉光，你那里得熬煎铅汞山头火？你那里觅医治相思海上方？此物非常。
(张生云)老师父，我老实对你说，若那夜女子不出来呵，我则管煮哩。
(正末云)秀才，你听者：东海龙神着老僧来做媒，招你为东床娇客，你意下如何？(张生云)老师父你不要耍我，这海中一望是白茫茫的水，小生是个凡人，怎生去的？(家僮云)相公，这个不妨事，你只跟着长老去，若是他不淹死，难道独独淹死了你？(正末唱)。','',''),('yuanqu-160','沙门岛张生煮海・脱布衫','李好古','yuanqu','','','俺实丕丕要问行藏，你慢腾腾好去商量。
将这水指一指翻为土壤，分一分步行坦荡。','',''),('yuanqu-161','须贾大夫谇范叔・仙吕/端正好','高文秀','yuanqu','','','凭着俺仲尼书，苍颉字，周公礼，子产文辞。
奈家贫不遇人驱使，怎肯道是无用也于才思。','',''),('yuanqu-162','须贾大夫谇范叔・幺篇','高文秀','yuanqu','','','常则是半生忙，不遂我平生志，居陋巷甘分随时。
今日个和使臣冠盖相随次，离魏国，到临淄；凭喉舌，决雄雌；休战阵，免兴师，(带云)大人放心，凭范雎三寸之舌，包请俺公子归国便了。
(唱)管成就这公事。
(下)。','',''),('yuanqu-163','须贾大夫谇范叔・仙吕/点绛唇','高文秀','yuanqu','','','日月煎熬，利名牵扰，人空老。
今日明朝，则俺这愁思知多少。','',''),('yuanqu-164','须贾大夫谇范叔・混江龙','高文秀','yuanqu','','','若依着先王典教，贫而无谄富无骄，俺可甚一身流落，半世辛劳？常只是白首相知犹按剑，枉了也朱门先达有同袍。
猛回头则落的纥地微微笑，倒不如痴呆懵懂，甘守着陋巷的这箪瓢。','',''),('yuanqu-165','须贾大夫谇范叔・天下乐','高文秀','yuanqu','','','他每只是些躲避当差影身草，自古来文章，可便将人都误了。
(邹衍云)我想古人都是靠着文章出身的，怎见得就误了人来？(正末唱)劝今人休将前辈学。
(邹衍云)学便如何？(正末唱)学卞庄斩虎的入虎穴，学吕望钓鱼的近池沼，学太康放鹰鹘拿燕雀。','',''),('yuanqu-166','须贾大夫谇范叔・那吒令','高文秀','yuanqu','','','我论着那斩虎的，则不如去斩蛟；(邹衍云)这钓鱼的，可是如何？(正末唱)钓于的，则不如去钓鳌；(邹衍云)这放鹰的，可是如何？(正末唱)放鹰的，则不如去放雕。
调大谎往上趱，抱粗腿向前跳，倒能够禄重官高。','',''),('yuanqu-167','须贾大夫谇范叔・鹊踏枝','高文秀','yuanqu','','','但有些个好穿着，好靴脚，出来的苫眼铺眉，一个个纳胯挪腰。
说谎的今时可便使着，天那，则俺这诚实的管老死蓬蒿！。','',''),('yuanqu-168','须贾大夫谇范叔・寄生草','高文秀','yuanqu','','','本待要寻知契、谒故交，见十家九家门关了。
起三阵五阵檐风哨，有千片万片梨花落。
但得个一顷半顷洛阳田，谁待想七月八月长安道？(邹衍云)张千，将酒来。
(张千云)酒到。
(邹衍云)贤士，小官奉命将着那牛酒管待贤士，请满饮此杯者。
(做递酒科，正末云)大人请。
(邹衍云)贤士请。
(正末云)恭敬不如从命，小生饮这杯酒咱。
(做饮酒科)(邹衍云)小官奉主公的命，在此驿亭中管待贤士，须要尽醉方归。
张千，唤将那歌儿舞女来者，着他席间伏侍贤士。
(张千云)歌儿舞女走动。
(二旦上，动乐科)(邹衍云)贤士，如今暮冬天道，纷纷扬扬下的是国家祥瑞，更接着这歌儿舞女，娇喉细细，红袖翩翩。
贤士请放开怀抱，满饮一杯者。
(正末云)大人，委的是好受用也！(唱)。','',''),('yuanqu-169','须贾大夫谇范叔・醉扶归','高文秀','yuanqu','','','俺则待手把着严陵钓，耳洗着许由瓢。
不图他顶冠束带立于朝，但得个身安乐。
(邹衍云)贤士，你怎么说这等没志气的话？人生功名富贵，皆由自取，也不专是天数。
(正末唱)则这的便是俺一斟一酌，再休题富贵也有个轮来到。','',''),('yuanqu-170','须贾大夫谇范叔・梁州第七','高文秀','yuanqu','','','但只问魏公子因何释放，全仗着那一个游说齐邦？怎生这功劳不在咱头上？几曾沾一丝儿赏赐，壮半米儿行装？可着俺越多伎俩，越受凄凉。
枉误了十载文章，干捱了半世风霜。
他、他、他，谁肯念陋巷间一瓢的书生，是、是、是，我愿则愿那都堂中八府的宰相，来、来、来，他每都不着我见那深宫内万岁的君王。
这天气，怎当？白茫茫冰连江海三千丈。
徒步去，将何往？早则是冒雪冰寒冻欲僵，这便是咱衣锦还乡！。','',''),('yuanqu-171','须贾大夫谇范叔・隔尾','高文秀','yuanqu','','','你那里葡萄酒设销金帐，罗绮筵开白玉堂。
闻知道魏相国亲身到宅上。
(做徘徊科，云)既是请丞相赴宴，怎又请我？(唱)故意把寒儒厮奖，显的他宽洪海量。
(云)哦，我知道了也。
(唱)多应是须贾高情，将我这范雎来讲。','',''),('yuanqu-172','须贾大夫谇范叔・隔尾','高文秀','yuanqu','','','正是那耕牛为主遭鞭杖，哑妇倾杯反受殃，灾祸临身自天降。
我吃了这一场棍棒，天那！这的是为国于家落来的赏。','',''),('yuanqu-173','须贾大夫谇范叔・牧羊关','高文秀','yuanqu','','','泪雹子腮边落，血冬凌满脊梁，冻剥剥雪上加霜。
则被你饿掉了三魂，敲翻了五脏。
带肉连皮颤，彻髓透心凉。
似这等勘范叔森罗殿，抵多少冻苏秦冰雪堂。','',''),('yuanqu-174','须贾大夫谇范叔・菩萨梁州','高文秀','yuanqu','','','则我这绵囤也似衣裳，坐不的红炉也那土坑。
吃黄齑的肚肠，(带云)抬了者。
(唱)我吃不的这法酒肥羊。
则我这三般地狱怎生当？无情风雪无情棒。
似吃着无心草，死熬这掩情况。
打得我肉绽皮开内外伤，眼见的不久身亡。','',''),('yuanqu-175','须贾大夫谇范叔・隔尾','高文秀','yuanqu','','','哎呀，我几曾醉眠绣被流苏帐，莫不是梦断茅庐映雪窗？长叹罢刚将眼睁放，我看了这厢，我又觑了那厢。
天也，原来我这七尺身躯在那厕坑里躺。','',''),('yuanqu-176','须贾大夫谇范叔・牧羊关','高文秀','yuanqu','','','待走来如何走？待藏来怎地藏？没揣的偏和他打个头撞。
(院公云)我举起这灯来试看咱。
我道是谁，原来是范雎。
你看一身秽污，你也少吃一钟波。
(正末唱)我几曾吃美酒羊羔，刚刚是吃了会胡枷乱棒。
(院公云)你既不醉呵，怎生浑身都是秽污？(正末唱)则被这粪沾湿我两鬓角，尿浸透我一胸膛。
(院公云)你站开些，这臭气当不得。
(正末唱)你闻不的我这秽气浑身臭，院公也，我几吃那开埕十里香。
(院公云)你原来不曾吃酒，可怎生这个模样？(正末做跪科，云)院公可怜见，你救我咱。
我同大夫入齐为使，见了齐王，一席话间，齐王大喜，便将公子魏申释放还国。
齐王命中大夫邹衍在驿亭中赐牛酒管待小生，又赐黄金千两，我并不曾受，这是大夫亲见的。
今归本国，安排筵宴请魏齐丞相饮酒，说我以阴事告齐，将我三推六问，吊拷绷扒，打死了我，丢在这粪坑中，倒亏这秽气熏活了。
望院公怎生救我出去，此恩异日必当重报。
(院公云)嗨，好可怜人也。
这里也无人，你跟我将来，打些水淋的你身上干净，脱了你那秽污衣服。
这寒冷天道，不冻杀了你来。
我有穿的旧绵衣服，待我取来与你穿。
(做取砌末科上，云)你穿了这衣服，还有五两碎银子，与你将息去。
我如今开了后角门，放你出去。
你休在这里，不问他州外府，逃你的性命。
你久已后若得志呵，只休忘了我的恩念。
(正末做拜科，云)院公，你是我重生的父母，再养的爷娘。
小生也不往他处，唯有秦国最强，可以报仇，就此告辞去也。
(唱)。','',''),('yuanqu-177','须贾大夫谇范叔・黄钟尾','高文秀','yuanqu','','','我便似伍员去楚心犹壮，孙膑投齐气怎降？谢恩人肯主张，放咱去入咸阳。
仗英雄显志量，见秦君说勾当。
管穰侯立辞相，不荒唐有承望，(云)院公，不是我范雎说口，想报冤之期，可也不远。
(唱)你则待的到蛰龙一声雷震响。
(下)。','',''),('yuanqu-178','须贾大夫谇范叔・正宫/端正好','高文秀','yuanqu','','','未亨通，遭穷困，身居在白屋寒门。
两轮日月消磨尽，不觉的添霜鬓。','',''),('yuanqu-179','须贾大夫谇范叔・滚绣球','高文秀','yuanqu','','','人道是文章好济贫，偏我被儒冠误此身，到今日越无求进，我本待学儒人倒不如人。
昨日周，今日秦，(带云)似这般途路难逢呵，(唱)可着我有家难奔，恰便似断蓬般移转无根。
道不得个地无松柏非为贵，腹隐诗书未是贫，则着我何处飘沦？(正末做窥望)(须贾见科，云)奇怪，大雪中走将来这个人，好似范雎也。
待道是呵，我当初打杀他了，再怎生得个范雎来？待道不是呵，你看那身分儿好生相似。
且休问他是不是，待我唤一声：范雎，范雎，近前来，我和你说话咱。
(正末云)谁唤范雎哩？(唱)。','',''),('yuanqu-180','须贾大夫谇范叔・叨叨令','高文秀','yuanqu','','','我听的他两三番叫咱往前进，猛可便扭回身行至车儿近。
我这里忙掠开泪眼将他认，(须贾云)是我唤你哩。
(正末唱)我这里觑绝时倒把身躯褪。
(正末做怕科)(须贾云)范雎，你见了小官，这般慌做甚么那？(正末唱)大夫也，你莫不又待打我也波哥，你莫不又待打我也波哥，唬的我兢兢战战忙逃奔。
(须贾云)范雎少待，一别许久，正要和你讲话，何故如此惊恐？先生固无恙乎？(正末唱)。','',''),('yuanqu-181','梁山泊李逵负荆・仙吕/点绛唇','康进之','yuanqu','','','饮兴难酬，醉魂依旧。
寻村酒，恰问罢王留。
(云)俺问王留道，那里有酒？那厮不说便走。
俺喝道：走那里去？被俺赶上一把揪住张口毛，恰待要打。
那王留道：休打，休打，爹爹，有。
(唱)王留道兀那里人家有。','',''),('yuanqu-182','梁山泊李逵负荆・混江龙','康进之','yuanqu','','','可正是清明时候，却言风雨替花愁。
和风渐起，暮雨初收。
俺则见杨柳半藏沽酒市，桃花深映钓鱼舟。
更和这碧粼粼春水波纹绉，有往来社燕，远近沙鸥。','',''),('yuanqu-183','梁山泊李逵负荆・油葫芦','康进之','yuanqu','','','往常时酒债寻常行处有，十欠着九。
(带云)老王也，(唱)则你这杏花庄压尽他谢家楼。
你与我便熟油般造下春醅酒，你与我花羔般煮下肥羊肉。
一壁厢肉又熟，一壁厢酒正等。
抵多少锦封未拆香先透，我则待乘兴饮两三瓯。','',''),('yuanqu-184','梁山泊李逵负荆・天下乐','康进之','yuanqu','','','可正是一盏能消万种愁，(云)老王也，咱吃了这酒呵，(唱)把烦恼都也波丢，都丢在脑背后，这些时吃一个没了休。
(带云)我醉了呵。
(唱)遮莫我倒在路边，遮莫我卧在瓮头，(做吐科，云)老王僳，(唱)直醉的来在这搭里呕。','',''),('yuanqu-185','梁山泊李逵负荆・赏花时','康进之','yuanqu','','','咱两个每日尊前语话投，今日呵，为甚将咱佯不愀。
(王林云)你不知道，我自嫁我的女孩儿，为此着恼。
(正末唱)哎！你个呆老子畅好是忒掐搜，(云)比似你这般烦恼，休嫁他不的。
(王林哭科，云)哎哟！我那满堂娇儿也。
(正末唱)你何不养着他到苍颜皓首？(云)你晓的世上有三不留么？(王林云)哥，是那三不留？(王末云)蚕老不中留，人老不中留，(唱)呆老子，常言道：女大不中留。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-186','梁山泊李逵负荆・金盏儿','康进之','yuanqu','','','我这里猛睁眸，他那里巧舌头，是非只为多开口。
但半星儿虚谬，恼翻我怎干休！一把火将你那草团瓢烧成为腐炭，盛酒瓮摔成碎瓷瓯。
(带云)绰起俺两把板斧来，(唱)砍折你那蟠根桑枣树，活杀您那阔角水黄牛。','',''),('yuanqu-187','梁山泊李逵负荆・正宫/端正好','康进之','yuanqu','','','抖搜着黑精神，扎煞开黄髭髟。','',''),('yuanqu-188','梁山泊李逵负荆・滚绣球','康进之','yuanqu','','','宋江口来，这是甚所为？甚道理？不知他主着何意？激的我怒气如雷。
可不道他是谁，我是谁，俺两个半生来岂有些嫌隙？到今日，却做了日月交食。
不争几句闲言语，我则怕恶识多年旧面皮，展转猜疑。','',''),('yuanqu-189','梁山泊李逵负荆・倘秀才','康进之','yuanqu','','','哎！你个刎颈的知交庆喜，(宋江云)庆甚么喜？(正末唱)则你那压寨的夫人在那里？(指鲁智深科，云)秃驴，你做的好事来。
(唱)打干净球儿不道的走了你。
(宋江云)怎么？智深兄弟，也有你那？(正末唱)强赌当，硬支持，要见个到底。
(宋江云)山儿，你下山去，有甚么事，何不就明对我说？(正末做恼不言语科)(宋江云)山儿，既然不好和我说，你就对学究哥哥根前说波。
(正末唱)。','',''),('yuanqu-190','梁山泊李逵负荆・倘秀才','康进之','yuanqu','','','不争你抢了他花朵般青春艳质，这其间抛闪杀那草桥店白头老的。
(宋江云)这事其中必有暗昧。
(正末唱)这桩事分明甚暗昧，生割舍，痛悲凄，(带云)宋江口来，(唱)他其实怨你。','',''),('yuanqu-191','梁山泊李逵负荆・叨叨令','康进之','yuanqu','','','那老儿，一会家便哭啼啼在那茅店里，(带云)觑着山寨，宋江好恨也！(唱)他这般急张拘诸的立。
那老儿，一会家便怒畔畔在那柴门外，(带云)哭道：我那满堂娇儿也！(唱)他这般乞留曲律的气。
(宋江云)他怎生烦庙那？(正未唱)那老儿，一会家便闷沉沉在那酒瓮边，(带云)那老儿拿起瓢耙，揭开蒲墩，舀一瓢冷酒来，汨汨的咽了。
(唱)他这般迷留没乱的醉。
那若儿，托着-片席头便慢腾腾放在土坑上，(带云)他出的门来，看一看，又不见来，哭道：我那满堂娇儿！(唱)他这般壹留兀渌的睡。
似这般过不的也么哥，似这般过不的也么哥，(宋江云)这厮怎的？(正末唱)他道俺梁山泊不甜人不义。','',''),('yuanqu-192','梁山泊李逵负荆・一煞','康进之','yuanqu','','','则为尔两头白面搬兴废，转背言词说是非。
这厮敢狗行狼心，虎头蛇尾。
不是我节外生枝，囊里盛锥。
谁着你夺人爱女，逞己风流，被咱都知(宋江云)你看黑牛这村沙样势那。
(正末唱)休怪我村沙样势，平地上起孤堆。','',''),('yuanqu-193','梁山泊李逵负荆・商调/集贤宾','康进之','yuanqu','','','过的这翠巍巍-带山崖脚，遥望见滴溜溜的酒旗招。
想悲欢不同昨夜，论真假只在今朝。
(云)花和尚，你也小脚儿，这般走不动，多则是做媒的心虚，不敢走哩。
(鲁智深云)你看这厮！(正末唱)鲁智深似窟里拔蛇，(云)宋公明，你也行动些儿。
你只是拐了人家女孩儿，害羞也不敢走哩。
(宋江云)你看他波！(正末唱)宋公明似毡上拖毛。
则俺那周琼姬，你可甚么上子乔，玉人在何处吹箫？我不合蹬翻了莺燕友，拆散了这凤鸾交。','',''),('yuanqu-194','梁山泊李逵负荆・逍遥乐','康进之','yuanqu','','','倒做了逢山开道，(鲁智深云)山儿，我还要你遇水搭桥哩。
(正末唱)你休得顺水推船，偏不许我过河拆桥。
(宋江做前走科)(正末唱)当不的他纳胯扭腰。
(宋江云)山儿，你不记得上山时，认俺做哥哥，也曾八拜之交哩。
(正末唱)哥也，你只说在先时，有八拜之交。
元宋是花木瓜儿外看好，不由咱不回头儿暗笑。
待和你争甚么头角，辩甚的衷肠，惜甚的皮毛。','',''),('yuanqu-195','梁山泊李逵负荆・醋葫芦','康进之','yuanqu','','','这老儿外名唤做半槽，就里带着一杓。
是则是去了你那一十八岁这个满堂娇，更做你家年纪老。
(云)俺叫了两三声不开门，第三声道：送将你那满堂娇女孩儿来了。
他开开门，搂着俺那黑膊子，叫道：我那满堂娇儿也。
(唱)老儿也似这般烦恼的无颠无倒，越惹你揉眵抹泪哭嚎啕。','',''),('yuanqu-196','梁山泊李逵负荆・幺篇','康进之','yuanqu','','','你则合低头就坐来，谁着你睁睛先去瞧？则你个宋公明威势怎生豪，刚一瞅，早将他魂灵吓掉了。
这便是你替天行道，则俺那无情板斧肯担饶？(云)老王，你来，兀那秃厮，便是做媒的鲁智深，你再去认咱。
(鲁智深云)你快认来。
(王林做再认科，云)不是！不是！那两个一个是青眼儿长子，如今这个是黑矮的。
那一个是稀头发腊梨，如今这个是剃头发的和尚。
不是！不是！(鲁智深云)山儿，我可是哩。
(正末云)你这秃厮，由他自认，你先幺喝一声怎么？(唱)。','',''),('yuanqu-197','梁山泊李逵负荆・幺篇','康进之','yuanqu','','','谁不知你是镇关西鲁智深，离五台山才落草。
便在黑影中摸索也应着，只被你爆雷似一声先唬倒。
那呆老子怕不知名号，(带云)适才间他也待认来。
(唱)只见他摇头侧脑费量度。','',''),('yuanqu-198','梁山泊李逵负荆・双雁儿','康进之','yuanqu','','','就恨不一把火，刮刮拶拶烧了你这草团瓢。
将人来，险中倒，气得咱，一似那鲫鱼跳。
可不道家有老敬老，家有小敬小。','',''),('yuanqu-199','梁山泊李逵负荆・双调/新水令','康进之','yuanqu','','','这一场烦恼可也奔人来，没来由共哥哥赌赛。
袒下我这红内袄，跌绽我这旧皮鞋。
心下量猜，(带云)到山寨上，哥哥不打，则要头。
(唱)怎发付脖项上这一块？。','',''),('yuanqu-200','梁山泊李逵负荆・驻马听','康进之','yuanqu','','','有心待不顾形骸，(带云)这碧湛湛石崖不得底的深涧我待跳下去，休说一个，便是十个黑旋风也不见了。
(唱)两三番自投碧湛崖。
敬临山寨，行一步如上吓魂台。
我死后，墓顶上谁定远乡牌？灵位边谁咒生天界？怎擘划，但得个完全尸首，便是十分采。','',''),('yuanqu-201','南吕・一枝花禄山谋反','孔文卿','yuanqu','','','苍烟拥剑门，老树屯云栈。
西风吹渭水，落叶满长安。
近帝都景物凋残，伤感起人愁叹。
只合在边寒间，只见那白茫茫莎草连天，甚的是娇滴滴莺花过眼。','',''),('yuanqu-202','梁州・不幸遣东归蓟北，更胜如西出阳关，看几时捱彻相思限？怕的是孤','孔文卿','yuanqu','','','灯荧暗，残月弓弯，戍楼人静，梅帐更阑。
思量玉砌雕阑，消磨尽绿鬓朱颜。
再几时染浓香翡翠衾温，迷醉魂芙蓉帐暖，解余酲荔枝浆寒？这近间，敢病番，旧时的衣衤肯频频亻替。
瘦证候何经惯？那的是从来最稀罕，单出落着废寝忘餐。','',''),('yuanqu-203','三煞・动无喘息行无汗，坐也昏沉睡不安，两行泪道渍成斑。每日家做伴','孔文卿','yuanqu','','','的胡友胡儿，胡舞胡歌，胡吹胡弹，知他是甚风范？偏恁一曲霓裳宠玉环，羯鼓声干。','',''),('yuanqu-204','二煞・拚了教匆匆行色催征雁，止不过拍拍离愁满战鞍，驱兵早晚到骊山。','孔文卿','yuanqu','','','若夺了娘娘，教唐天子登时两分散，休想再能够看一看。
四件事分明紧调犯，势到也怎摭拦？。','',''),('yuanqu-205','尾声・把六宫心事分明的慢，将半纸音书党闭的悭，教千里途程阻隔的难。','孔文卿','yuanqu','','','我因此上一点春心酝酿的反。','',''),('yuanqu-206','双调・蟾宫曲','刘唐卿','yuanqu','','','博山铜细袅香风，两行纱笼，烛影摇红。
翠袖殷勤捧金钟，半露春葱。
畅好是会受用文章巨公，绮罗业醉眼朦胧。
夜宴将终，十二帘栊，月转梧桐。','',''),('yuanqu-207','正宫・甘草子','薛昂夫','yuanqu','','','金凤发，飒飒秋香，冷落在阑干下。
万柳稀，重阳暇，看红叶赏黄花。
促织儿啾啾添潇洒，陶渊明欢乐煞。
耐冷迎霜鼎内插，看雁落平沙。','',''),('yuanqu-208','中吕・朝天曲','薛昂夫','yuanqu','','','沛公，大风，也得文章用。
却教猛士叹良弓，多了游云梦。
驾驭英雄，能擒能纵，无人出彀中。
后宫，外宗，险把炎刘并。
子牙，鬓华，才上非熊卦。
争些老死向天涯，只恁垂钩罢。
满腹天机，天人齐发，武王任不差。
用他，讨罚，一怒安天下。
伍员，报亲，多了鞭君忿。
可怜悬首在东门，不见包胥恨。
半夜潮声，千年孤愤，钱塘万马奔。
骇人，怒魂，何似吹箫韵？卞和，抱璞，只合荆山坐。
三朝不遇待如何，两跣遭祸。
传国争符，伤身行货，谁教献与他？切磋，琢磨，何似偷敲破？邵平，不平，楚汉争秦鼎。
将军便去作园丁，软了英雄性。
瓜苦瓜甜，秦衰秦盛，青门浪得名。
此生，本轻，不是封侯命。
假王，气昂，跨下羞都忘。
提牌不过一中郎，漂母曾相饷。
蒯彻名言，将军将强。
良弓不早藏。
未央，法场，险似坛台上。
叔孙，讨论，早定君臣分。
礼成文武两班分，舞蹈扬尘顺。
拔剑争功，垂绅消忿，方知天子尊。
武臣，勇人，也被书生困。
丙吉，宰执，燮理阴阳气。
有司不问尔相推，人命关天地。
牛喘非时，何须留意？原来养得肥。
早知，好吃，杀了供堂食。
子陵，价轻，便入刘郎聘。
等闲赢得一虚名，卖了先生姓。
百尺丝纶，千年高兴，偶然一足横。
帝星，客星，不料天文应。
董永，卖身，孝感天心顺。
谁知织女是天孙，同受为奴困。
自有牛郎，佳期将近，书生休认真。
本因，孝亲，不是夫妻分。
老莱，戏采，七十年将迈。
堂前取水作婴孩，犹欲双亲爱。
东倒西歪，佯啼颠拜，虽然称孝哉。
上阶，下阶，跌杀休相赖。
董卓，巨饕，为恶天须报。
一脐然出万民膏，谁把逃亡照？谋位藏金，贪心无道，谁知没下梢！好教，火烧，难买棺材料。
杜甫，自苦，踏雪寻梅去。
吟肩高耸冻来驴，迷却前村路。
暖阁红炉，党家门户，玉纤捧绿醑。
假如，便俗，也胜穷酸处。
洞宾，道人，未到天仙分。
岳阳三醉洞庭春，卖墨无人问。
欲斩黄龙，青蛇犹钝，纯阳能几分。
养真，炼神，却被仙姑困。
伯牙，韵雅，自与松风话。
高山流水淡生涯，心与琴俱化。
欲铸钟期，黄金无价，知音人既寡。
尽他，爨下，煮了仙鹤罢。
则天，改元，雌鸟长朝殿。
昌宗出入二十年，怀义阴功健。
四海淫风，满朝窑变，《关睢》无此篇。
弄权，妒贤，却听梁公劝。
孟母，丧夫，教子迁离墓。
再迁市井厌屠沽，迁傍芹宫住。
如此三迁，房钱无数，方成一大儒。
问猪，引取，好辩长于喻。
弄玉，度曲，只道吹箫苦。
谁知凤只和鸾孤，吹到声圆处。
明月台空，萧郎同去，秦王一叹吁。
假如，嫁夫，明白人间住。
采鸾，怕寒，甲帐无人伴。
文箫连累堕人间，卖韵供烟爨。
谁使思凡，尘缘难断，羞还玉女班。
紫坛，犯奸，误了朝元限。
禄山，玉环，子母肠难断。
何须兵变陷长安，且向宫中乱。
赶得三郎，鸾舆逃窜，连云蜀道难。
内奸，外反，误却霓裳慢。
老矣，倦矣，消减尽风云气。
世情嚼蜡烂如呢，不见真滋味。
蜗角虚名，蝇头微利，便得来真做的。
布衣，袖里，试屈指英雄辈。
好官，也兴阑，早勇退身无患。
人生六十便宜闲，十载疏狂限。
买两个丫鬟，自拈牙板，一个歌一个弹。
醒时节过眼，醉时节破颜，能到此是英雄汉。','',''),('yuanqu-209','中吕・阳春曲','薛昂夫','yuanqu','','','坐听西掖钟声动，睡起东窗日影红，山林朝市两无穷。
一梦中，樽有酒且从容。
耐惊耐怕黄齑瓮，长满长干老酒盆，一贫尽可张吾军。
休忘本，樽有酒且论文。
胸中太华身难憾，舌底狂澜口且缄，看渠暮四与朝三。
呆大胆，樽有酒且醺酣。
周郎赤壁鏖兵后，苏子扁舟载月秋，千年慷慨一时酬。
今在否？樽有酒且绸缪。
芸窗月影吟情荡，纸帐梅花醉梦香，觉来身世两相忘。
休妄想，樽有酒且疏狂。
岁云暮矣虽无补，时复中之尽有余，老来吾亦爱吾庐。
清债苦，樽有酒且消除。','',''),('yuanqu-210','双调・蟾宫曲叹世','薛昂夫','yuanqu','','','鸡羊鹅鸭休争，偶尔相逢，堪炙堪烹。
天地中间，生老病死，物理常情。
有一日符到奉行，只图个月朗风清。
笑杀刘伶，荷插埋尸，犹未忘形。
人生尔尔堪怜，富贵何时，又待问舍求田？想昨日秦宫，今朝汉阙，呀，可早晋地唐天！能几许长安少年，急回头两鬓皤然。
谩说求仙，百计千方，都不似樽前。
雪天仙碧玉琼瑶，点点杨花，片片鹅毛。
访戴归来，寻梅懒去，独钓无聊。
一个饮羊羔红炉暖阁，一个冻骑驴野店溪桥。
你自评跋，那个清高，那个粗豪？题烂柯石桥甚神仙久占岩桥，一局楸枰，满耳松涛。
引得樵夫，旁观不觉，晋换了唐朝。
斧柄儿虽云料却，裤腰儿难保坚牢。
王母蟠桃，三千岁开化，总是虚谣。
懒朝元石上围棋，问仙子何争？樵叟忘归。
洞锁青霞，斧柯已烂，局势犹迷。
恰滚滚桑田浪起，又飘飘沧海尘飞。
恰待持杯，酒未沾唇，日又平西。
快阁怀古舣扁舟快阁盘桓，看一道澄江，落木千山。
自山谷留题，坡仙阁笔，我试凭阑。
问今古诗人往还，比盟鸥几个能闲？天地中间，物我无干，只除是美酒佳人，意颇相关。
知音问芳筵歌者何人？便折简相招，恣意开樽。
细切清风，薄批明月，何必云云。
是久厌黄齑菜根，要听他白雪阳春。
翠袖殷勤，雪霁梅开，正好论文。','',''),('yuanqu-211','双调・湘妃怨集句','薛昂夫','yuanqu','','','几年无事傍江湖，醉倒黄公旧酒垆。
人间纵有伤心处，也不到刘伶坟上土，醉乡中不辨贤愚。
对风流人物，看江山画图，便醉倒何如？。','',''),('yuanqu-212','双调・殿前欢春','薛昂夫','yuanqu','','','据危阑，看浮屠双耸倚高寒，鳞鳞万瓦连霄汉。
俯视尘寰，望飞来紫翠间。
云初散，放老眼情无限。
知他是西山傲我，我傲西山？夏柳扶疏，玻璃万项浸冰壶，流莺声里笙歌度。
士女相呼，有丹青画不如。
迷归路，又撑入荷深处。
知他是西湖恋我，我恋西湖？秋洞箫歌，问当年赤壁乐如何，比西湖画航争些个？一样烟波，有吟人景便多。
四海诗名播，千载谁酬和？知他是东坡让我，我让东坡？冬捻冰髭，绕孤山枉了费寻思，自逋仙去后无高士。
冷落幽姿，道梅花不要诗。
休说推敲字，效杀颦难似。
知他是西施笑我，我笑西施？浪淘淘，看渔翁举网趁春潮，林间又见樵夫闹。
伐木声高，比功名客更劳。
虽然道，他终是心中乐。
知他是渔樵笑我，我笑渔樵？醉归来，袖春风下马笑腮，笙歌接到朱帘外。
夜宴重开，十年前一秀才。
黄齑菜，打熬到文章伯。
施展出江湖气概，抖擞出风月情怀。','',''),('yuanqu-213','双调・楚天遥过清江引','薛昂夫','yuanqu','','','花开人正欢，花落春如醉。
春醉有时醒，人老欢难会，一江春水流，万点杨花坠。
谁道是杨花？点点离人泪！回首有情风万里，渺渺天无际。
愁共海潮来，潮去愁难退，更那堪晚来风又急！屈指数春来，弹指惊春去。
蛛丝网落花，也要留春住。
几日喜春睛，几夜愁春雨。
六曲小山屏，题满伤春句。
春若有情应解语，问着无凭据。
江东日暮云，渭北春天树，不知那答儿是春住处？有意送春归，无计留春住。
明年又着来，何似休归去？桃花也解愁，点点飘红玉。
目断楚天遥，不见春归路。
春若有情春更苦，暗里韶光度。
夕阳山外山，春水渡傍渡，不知那答儿是春住处？套数。','',''),('yuanqu-214','正宫・端正好高隐','薛昂夫','yuanqu','','','访知音习酬和，也不问名利如何。
不贪不爱随缘过，把世事都参破。','',''),('yuanqu-215','滚绣球・叹光阴疾似梭，想人生能几何，转回头百年已过，急回首两鬓斑','薛昂夫','yuanqu','','','花阴转眼那，日光弹指过，送了些干峥嵘且贪呆货，有两句古语您自评跋。
相随故友年年少，郊外新坟岁岁多，一枕南柯。','',''),('yuanqu-216','倘秀才・日落西山衔着烈火，月出东云托着玉钵，似这般东去西来怎奈何？','薛昂夫','yuanqu','','','金乌疾如箭，玉兔似撺梭，自心中定夺。','',''),('yuanqu-217','滚绣球・则不如山田一二亩，栽桑麻数百棵，驱家人使牛耕播，住几间无','薛昂夫','yuanqu','','','忧愁草苫庄坡。
一朝苗稼锄，趁时将黍豆割，养春蚕桑叶忙锉，着山妻上布织梭。
秃厮姑紧紧的将绵花纺，村伴姐慌将麻线搓，一弄儿农器家活。','',''),('yuanqu-218','倘秀才・闲时节疏林外磁瓯瓦钵，盛摘下些生桃硬果，晚趁斜阳景物多。','薛昂夫','yuanqu','','','听水声流浪远，观山色岭嵯峨，与俺那庄农每会合。','',''),('yuanqu-219','赛鸿秋・我若是醉时节笑引着儿孙和，醉时节麦场上闲独磨，醉时节六轴','薛昂夫','yuanqu','','','上乔衙坐，醉时节巴棚下和衣儿卧。
酒醒觉来时，直睡到参儿锉，不听的五更钟人马街前过。','',''),('yuanqu-220','耍孩儿・收成黍豆盈仓垛，经年不缺半合。收耕罢织足衣食，将柴门紧紧','薛昂夫','yuanqu','','','扃合。
早晨间豆粥吃三碗，收晚来齑汤做一锅，暖炕上和衣卧。
守着俺山妻稚子，喂养些牛畜驴骡。','',''),('yuanqu-221','四煞・到春来绿依依柳吐烟，红馥馥桃喷火，粉蝶儿来往穿花过。黄莺出','薛昂夫','yuanqu','','','谷寻新柳，紫燕归巢觅旧窝。
时雨降天公贺，庆新春齐敲社鼓，赛牛王共击铜锣。','',''),('yuanqu-222','三煞・到夏来玩池塘十里长，赏荷花百步阔，青铺翠盖穿红破。虽无那彩','薛昂夫','yuanqu','','','船画舫游池沼，也有那短棹渔舟泛浅波。
故友来相贺，绕溪边鲜鱼旋买，沿村务沽酒频酌。','',''),('yuanqu-223','二煞・来秋来碧天雁几行，黄花儿开数朵，满川红叶似胭脂抹。青山隐隐','薛昂夫','yuanqu','','','连巅岭，绿水潺潺泛浅波。
鲜藕莲根锉，团脐蟹味欺着锦鲤，嫩黄鸡胜似肥鹅。','',''),('yuanqu-224','一煞・到冬来朔风遍地刮，彤云密布合，纷纷雪片钱来大。须臾云汉飘白','薛昂夫','yuanqu','','','蕊，咫尺空中舞玉蛾。
冬景堪酬和，草庵前寒梅雪压，短窗边瘦影频磨。','',''),('yuanqu-225','尾声・四时景物佳，放形骸堪正可。我比你少忧愁省烦恼无灾祸，到大来','薛昂夫','yuanqu','','','无是无非快活煞我！闺怨小庭幽，重门静，东风软膏雨初晴。
猛听的卖花声过天街应，惊谢芙蓉兴。','',''),('yuanqu-226','刘晨阮肇误入桃源・仙吕/点绛唇','王子一','yuanqu','','','啸傲烟霞，寸心休把名牵挂。
暗里年华，青镜添白发。','',''),('yuanqu-227','刘晨阮肇误入桃源・油葫芦','王子一','yuanqu','','','一上天台石径滑，践翠霞则见这竹篱茅舍两三家，听得那夕阳杜宇啼声煞，这时节春风桃李花开罢。
我虽不伴长沮事耦耕，学严陵理钓槎。
常则是杖头三百青钱挂，抵多少坐三日县官衙！。','',''),('yuanqu-228','刘晨阮肇误入桃源・天下乐','王子一','yuanqu','','','也算个闲趁东风数落花，荣华，谁恋他？敢则是瓦盆边几场沉醉杀。
快清风，袍袖宽，倦红尘路径狭，便休题相逢不下马。','',''),('yuanqu-229','刘晨阮肇误入桃源・鹊踏枝','王子一','yuanqu','','','远奢华，近清佳，火炼丹砂，水煮黄芽。
牢拴住心猿意马，急疏开利锁名枷。
(阮肇云)这几年天下荒荒，干戈并起，不能勾风尘宁静。
若有英雄生于此时，觑事业如拾芥耳。
(正末云)贤者避世，其次避地，其次避色，其次避言。
兄弟，还只是我们的见识高得多哩。
(唱)。','',''),('yuanqu-230','刘晨阮肇误入桃源・寄生草','王子一','yuanqu','','','我情愿弃轩冕离人世，傍泉石度岁华。
一任他英雄并起图王霸，烟尘并起兴戈甲，异端并起伤风化。
我和你韬光晦迹老山中，煞强如齐家治国平天下。','',''),('yuanqu-231','刘晨阮肇误入桃源・幺篇','王子一','yuanqu','','','去去山无尽，行行路转差。
则为那白云渐渐迷高下，不由咱寸心悄悄耽惊怕，见-个村翁远远来迎迓。
我这里为迷山路问樵夫，抵多少因过竹院逢僧话。','',''),('yuanqu-232','刘晨阮肇误入桃源・醉中天','王子一','yuanqu','','','信脚山之下，洗耳水之涯。
正失路迷踪没乱煞，(带云)得遇老人呵，(唱)抵多少卖得龟儿卦。
(太白云)二位可通个姓名，现居何处？(正末唱)我两个本东庄措大。
(太白云)我看你二位生得齐整，像个出仕的人。
(正末唱)休认做名题科甲，(太白云)二位可还有甚陪伴的么？(正末云)若问我陪伴的呵，(唱)无非是糜鹿鱼虾。','',''),('yuanqu-233','刘晨阮肇误入桃源・后庭花','王子一','yuanqu','','','并不想有轩车有驷马，我则愿无根椽无片瓦。
出来的一品职千钟禄，那里有六韬书三略法，他都是井中蛙妄称尊大。
比周公不握发，比陈蕃不下榻。
空结实花木瓜，费琢磨水晶塔。
斗筲器不足夸，粪土墙容易塌，儿童见惊讶杀。','',''),('yuanqu-234','刘晨阮肇误入桃源・青歌儿','王子一','yuanqu','','','空一带江山、江山如画，止不过饭囊、饭囊衣架，塞满长安乱似麻。
每日价大纛高牙，冠盖头踏。
人物不撑达，服色尽奢华，心行更奸猾。
举止少谦洽。
纷纷扰扰由他，多多少少欺咱，言言语语参杂。
是是非非交加。
因此上不事王侯，不求闻达。
隐姓埋名做庄家，学耕稼。','',''),('yuanqu-235','刘晨阮肇误入桃源・赚煞','王子一','yuanqu','','','投至的山上采芝回，早难道江上踏青罢，眼见得路迢遥芒鞋邋遢。
抵多少古道西风鞭瘦马，叹明朝回首天涯。
谩嗟呀，那里也出入通达，不觉的枯木寒烟噪晚鸦。
望青山那搭，红轮直下，兀的是白云深处有人家。
(同阮下)。','',''),('yuanqu-236','刘晨阮肇误入桃源・正宫/端正好','王子一','yuanqu','','','风力紧羽衣轻，露华湿乌巾重。
我本为厌红尘跳出樊笼，只待要拨开云雾丘陇，身世外无擒纵。','',''),('yuanqu-237','刘晨阮肇误入桃源・倘秀才','王子一','yuanqu','','','我待学炼九转丹砂葛洪，上万丈昆仑赤松，因此上思入风云变态中。
(云)兄弟，你看一溪流水，几片落花，这山中必有人家也。
(唱)则见一溪流水绿，几片落花红，兀的把春光断送。
(云)兄弟，这般景物，畅是宜人，我且题咏几句咱。
(阮云)兄长正好题咏几句，小弟拱听。
(正末唱)。','',''),('yuanqu-238','刘晨阮肇误入桃源・滚绣球','王子一','yuanqu','','','水呵莫不黄河天上来？花呵莫不碧桃天上种？水呵索强如翠岩前三千丈玉泉飞进，花呵干闪下闹西园一队队课蜜游蜂。
水呵则是弥漫三月雨，花呵可惜狼藉一夜风。
水呵近沧波濯尘缨一溪光莹，花呵性轻薄乱飘零枉费春工。
水呵抵多少长江后浪催前浪，花呵早则一片西飞一片东，岁月匆匆。','',''),('yuanqu-239','刘晨阮肇误入桃源・倘秀才','王子一','yuanqu','','','我这里长啸时草木振动，怅望处风涛怒涌，不觉的悄然而悲悚然恐。
(阮肇云)咱两个则傍这一道流水寻去，料的前面必有个渔家可以投宿。
(正末唱)盼不的渔家春水渡，(阮肇云)这山中敢有个寺儿么？(正末唱)闻不见僧寺夕阳钟，(带去)兄弟呵，(唱)咱两个莫不被樵大调哄？。','',''),('yuanqu-240','刘晨阮肇误入桃源・呆骨朵','王子一','yuanqu','','','你便铁石人也惹起凡心动，莫不是驾青鸾天上飞琼？似这般花月神仙，晃动了文章巨公。
(做相见科，旦云)刘郎、阮郎，请同到舍下。
(正末云)他女娘家怎知我们的名姓，便以刘郎、阮郎呼之？兄弟，我和你莫非是梦中么？(唱)没揣的撞到风流阵，引入花胡同。
摆列着金钗十二行，敢则梦上他巫山十二峰。','',''),('yuanqu-241','刘晨阮肇误入桃源・脱布衫','王子一','yuanqu','','','光闪闪贝阙珠宫，齐臻臻碧瓦朱甍。
宽绰绰罗帏绣栊，郁巍巍画梁雕栋。','',''),('yuanqu-242','刘晨阮肇误入桃源・醉太平','王子一','yuanqu','','','注金波碧筒，烧银烛纱笼，笙歌引至画堂中，红遮翠拥。
人心此会应相重，人情今夜初相共，人生何处不相逢？早忘却更长漏水。
(二旦做意把盏科，云)草草杯盘，不足以待贤者，惶恐！惶恐！(正末谢云)生等不才，多承错爱，何以克当？(唱)。','',''),('yuanqu-243','刘晨阮肇误入桃源・倘秀才','王子一','yuanqu','','','则见他喜孜孜幽欢密宠，便一似悄促促私期暗通，怎消得翠袖殷勤捧玉钟？屏开金孔雀，褥隐绣芙蓉，兀的般受用。','',''),('yuanqu-244','刘晨阮肇误入桃源・叨叨令','王子一','yuanqu','','','记不的轩辕一枕华胥梦，学不的淳于一枕南柯梦，盼不的文王一枕非熊梦，成不的庄周一枕蝴蝶梦。
倒大来福分也么哥，倒大来福分也么哥，恰做了襄王一枕高唐梦。','',''),('yuanqu-245','刘晨阮肇误入桃源・二煞','王子一','yuanqu','','','一杯未尽笙歌送，两意初谐语话同。
效文君私奔相如，比巫娥愿从宋玉，似莺莺暗约张生，学孟光自许梁鸿。
他年不骑鹤，何日可登鳌？今夜恰乘龙。
说甚的只鸾单凤，天与配雌雄。','',''),('yuanqu-246','冤报冤赵氏孤儿・仙吕/赏花时','纪君祥','yuanqu','','','枉了我报主的忠良一旦休，只他那蠹国的奸臣权在手；他平白地使机谋，将俺云阳市斩首，兀的是出气力的下场头。','',''),('yuanqu-247','冤报冤赵氏孤儿・幺篇','纪君祥','yuanqu','','','落不的身埋在故丘。
(云)公主，我嘱咐你的说话，你牢记者！(旦儿云)妾身知道了也！(赵朔唱)分付了腮边雨泪流，俺一句一回愁；待孩儿他年长后，着与俺这三百口，可兀的报冤仇。
(死科，下)(旦儿云)驸马！则被你痛杀我也！(下)(使命云)赵朔用短刀身，亡了也。
公主已囚在府中，小官须回主公的话去来。
(诗云)西戎当日进神獒，赵家百口命难逃；可怜公主犹囚禁，赵朔能无决短刀！(下)。','',''),('yuanqu-248','冤报冤赵氏孤儿・仙吕/点绛唇','纪君祥','yuanqu','','','列国纷纷，莫强于晋。
才安稳，怎有这屠岸贾贼臣，他则把忠孝的公卿损。','',''),('yuanqu-249','冤报冤赵氏孤儿・昆江龙','纪君祥','yuanqu','','','不甫能风调雨顺，太平年宠用着这般人。
忠孝的在市曹中斩首，奸佞的在帅府内安身。
现如今全作威来全作福，还说甚半由君也半由臣。
他他他，把爪和牙布满在朝门，但违拗的早一个个诛夷尽。
多咱是人间恶煞，可甚么阃外将军！。','',''),('yuanqu-250','冤报冤赵氏孤儿・油葫芦','纪君祥','yuanqu','','','他待要剪草防芽绝祸根，使着俺把府门。
俺也是了家为国旧时臣。
那一个藏孤儿的便不合将他隐，这一个杀孤儿的你可也心何忍。
(带云)屠岸贾，你好狠也。
(唱)有一日怒了亡苍，恼了下民，怎不怕沸腾腾万口争谈沦，天也显着个青脸儿不饶人。','',''),('yuanqu-251','冤报冤赵氏孤儿・天下乐','纪君祥','yuanqu','','','却不道远在儿孙近在身，哎，你个贼也波臣，和赵盾，岂可二十载同僚没些儿义分。
便兴心使歹心，指贤人作歹人。
他两个细评论，还是那个狠。','',''),('yuanqu-252','冤报冤赵氏孤儿・河西后庭花','纪君祥','yuanqu','','','你本是赵盾家堂上宾，我须是屠岸贾门下人。
你便藏着那未满月麒麟种，(带云)程婴你见么？(唱)怎出的这不通风虎豹屯。
我不是下将军，也不将你来盘问。
(云)程婴，我想你多曾受赵家恩来！(程婴云)是。
知恩报恩，何必要说。
(正末唱)你道是既知恩合报恩，只怕你要脱身难脱身。
前和后把住门，地和天那处奔？若拿回审个真，将孤儿往报闻，生不能，死有准。','',''),('yuanqu-253','冤报冤赵氏孤儿・金盏儿','纪君祥','yuanqu','','','见孤儿额颅上汗律津，口角头乳食喷，骨碌碌睁一双小眼儿将咱认，悄促促箱儿里似把声吞，紧绑绑难展足，窄狭狭怎翻身。
他正是成人不自在，自在不成人。','',''),('yuanqu-254','冤报冤赵氏孤儿・醉中天','纪君祥','yuanqu','','','我若是献出去图荣进，却不道利自己损别人。
可怜他三百口亲丁尽不存，着谁来雪这终天恨？(带云)那屠岸贾若见这孤儿呵，(唱)怕不就连皮带筋，捻成齑粉。
我可也没来由立这样没眼的功勋。
(云)程婴，你抱的这孤儿出去。
若屠岸贾问呵，我自与你回话。
(程婴云)索谢了将军。
(做抱箱儿走出，又回，跪科)(正末云)程婴，我说放你去，难道耍你？可快出去！(程婴云)索谢了将军。
(做走，又回，跪科)(正末云)程婴，你怎生又回来？(唱)。','',''),('yuanqu-255','冤报冤赵氏孤儿・金盏儿','纪君祥','yuanqu','','','敢猜着我调假小为真，那知道蕙叹惜芝焚；去不去我几回家将伊尽，可怎生到门前兜的又回身？(带云)程婴，(唱)你既没包身胆，谁着你强做保孤人？可不道忠臣不怕死，怕死不忠臣。
(程婴云)将军，我若出的这府门去，你报与屠岸贾知道，别差将军赶来拿住我程婴，这个孤儿万无活理。
罢！罢！罢！将军，你拿将程婴去，请功受赏;我与赵氏孤儿，情愿一处身亡便了！(正末云)程婴，你好去的不放心也：(唱)。','',''),('yuanqu-256','冤报冤赵氏孤儿・醉扶归','纪君祥','yuanqu','','','你为赵氏存遗胤，我于屠贼有何亲？却待要乔做人情遣众军，打一个回风阵。
你义忠我可也又信，你若肯舍残生，我也愿把这头来刎。','',''),('yuanqu-257','冤报冤赵氏孤儿・青歌儿','纪君祥','yuanqu','','','端的是一言一言难尽。
(带云)程婴，(唱)你也忒眼内眼内无珍。
将孤儿好去深山深处隐，那其间教训成人，演武修文；重掌三军，拿住贼臣；碎首分身，报答亡魂，也不负了我和你硬踹着是非门，担危困。','',''),('yuanqu-258','冤报冤赵氏孤儿・隔尾','纪君祥','yuanqu','','','你道是古来多被奸臣弄，便是圣世何尝没四凶，谁似这万人恨千人赚一人重。
他不廉不公，不孝不忠，单只会把赵盾全家杀的个绝了种。
(程婴云)老宰辅，幸得皇天有眼，赵氏还未绝种哩！(正末云)他家满门良贱三百余口，诛尽杀绝，便是驸马也被三般朝典短刀自刎了，公主也将裙带缢死了，还有甚么种在那里？(程婴云)那前项的事，老宰辅都已知道，不必说了。
近日公主囚禁府中，生下一子，唤做孤儿。
这不是赵家是那家的种？但恐屠岸贾得知，又要杀坏，若杀了这一个小的，可不将赵家真绝了种也！(正末云)如今这孤儿却在那里？不知可有人救的出来么？(程婴云)老宰辅既有这点见怜之意，在下敢不实说。
公主临亡时，将这孤儿交付与了程婴，着好生照觑他，待到成人长大，与父母报仇雪恨。
我程婴抱的这孤儿出门，被韩厥将军要拿的去报与屠岸贾。
是程婴数说了一场，那韩厥将军放我出了府门，自刎而亡。
如今将的这孤儿无处掩藏，我特来投奔老宰辅。
我想宰辅与赵盾元是一殿之臣，必然交厚，怎生可怜见救这个孤儿咱！(正末云)那孤儿今在何处？(程婴云)现在芭棚下哩！(正末云)休惊吓着孤儿，你快抱的来。
(程婴做取箱开看科，云)谢天地，小舍人还睡着哩。
(正末接科)(唱)。','',''),('yuanqu-259','冤报冤赵氏孤儿・牧羊关','纪君祥','yuanqu','','','这孩儿未生时绝了亲戚，怀着时灭了祖宗，便长成人也则是少吉多凶。
他父亲斩首在云阳，他娘呵囚在禁中。
那里是血腥的白衣相，则是个无恩念的黑头虫。
(程婴云)赵氏一家，全靠着这小舍人，要他报仇哩。
(正末唱)你道他是个报父母的真男子；我道来，则是个妨爷娘的小业种。','',''),('yuanqu-260','冤报冤赵氏孤儿・红芍药','纪君祥','yuanqu','','','须二十年报仇的主人公，恁时节才称心胸。
只怕我迟疾死后一场空。
(程婴云)老宰辅，你精神还强健哩。
(正末唱)我精神比往日难同，闪下这小孩童怎见功？你急切里老不的形容，正好替赵家出力做先锋。
(带云)程婴，你只依着我便了。
(唱)我委实的捱不彻暮鼓晨钟。','',''),('yuanqu-261','冤报冤赵氏孤儿・三煞','纪君祥','yuanqu','','','这两家做下敌头重。
但要访的孤儿有影踪，必然把太严庄上兵围拥，铁桶般密不通风。
(云)那屠岸贾拿住了我，高声喝道：老匹夫岂不见三日前出下榜文，偏是你藏下赵氏孤儿。
与俺作对，请波请波！(唱)则说老匹大清先入瓮，也须知榜揭处天都动；偏你这罢职归田一老农，公然敢剔蝎撩蜂。','',''),('yuanqu-262','冤报冤赵氏孤儿・二煞','纪君祥','yuanqu','','','他把绷扒吊拷般般用，情节根由细细穷；那其间枯皮朽骨难禁痛，少不得从实攀供，可知道你个程婴怕恐。
(带云)程婴，你放心者。
(唱)我从来一诺似千金重，便将我送上刀山与剑峰，断不做有始无终。','',''),('yuanqu-263','冤报冤赵氏孤儿・煞尾','纪君祥','yuanqu','','','凭着赵家枝叶千年永，晋国山河百二雄。
显耀英材统军众，威压诸邦尽伏拱；遍拜公卿诉苦衷。
祸难当初起下宫，可怜三百口亲丁饮剑锋；刚留得孤苦伶仃一小童，巴到今朝袭父封。
提起冤仇泪如涌，要请甚旗牌下九重，早拿出奸臣帅府中，断首分骸祭祖宗，九族全诛不宽纵，恁时节才不负你冒死存孤报主公，便是我也甘心儿葬近要离路旁冢。
(下)(程婴云)事势急了，我依旧将这孤儿抱的我家去，将我的孩儿送到太平庄上来。
(诗云)甘将自己亲生子，偷换他家赵氏孤；这本程婴义分应该得，只可惜遗累公孙老大夫。
(下)。','',''),('yuanqu-264','冤报冤赵氏孤儿・双调/新水令','纪君祥','yuanqu','','','我则见荡征尘飞过小溪桥，多管是损忠良贼徒来到。
齐臻臻摆着士卒，明晃晃列着枪刀。
眼见的我死在今朝，更避甚痛笞掠。
(屠岸贾同程婴领卒子上，云)来到这吕吕太平庄上也。
令人，与我围了太平庄者。
程婴，那里是公孙杵臼宅院？(程婴云)则这个便是。
(屠岸贾云)拿过那老匹夫来。
公孙杵臼，你知罪么？(正末云)我不知罪。
(屠岸贾云)我知你个老匹夫和赵盾是一殿之臣。
你怎敢掩藏着赵氏孤儿！(正末云)老元帅，我有熊心豹胆？怎敢掩藏着赵氏孤儿！(屠岸贾云)不打不招。
令人，与我拣大棒子着实打者。
(卒子做打科)(正末唱)。','',''),('yuanqu-265','冤报冤赵氏孤儿・驻马听','纪君祥','yuanqu','','','想着我罢职辞朝，曾与赵盾名为刎颈交。
(云)这事是谁见来？(屠岸贾云)观有程婴首告着你哩。
(正末唱)是那个埋情出告，原来这程婴舌是斩身刀。
(云)你杀了赵家满门良贱三百余口，则剩下这孩儿，你又要伤他性命。
(唱)你正是狂风偏纵扑天雕，严霜故打枯根草。
不争把孤儿又杀坏了。
可着他三百口冤仇甚人来报。','',''),('yuanqu-266','河南府张鼎勘头巾・仙吕/点绛唇','孙仲章','yuanqu','','','杜宇伤春，锦莺啼恨。
东风顺，则听的叫唤声频，早将我酒力消磨尽。','',''),('yuanqu-267','河南府张鼎勘头巾・混江龙','孙仲章','yuanqu','','','我把这衣衫整顿，急煎煎行出卧房门。
悠悠的惊了七魂，忽忽的唬了三魂。
脚趔趄难支吾荒冗冗，眼朦胧犹兀自醉醺醺。
我这里下阶基转影壁亲身问，问一个事从来历，唱叫缘因。','',''),('yuanqu-268','河南府张鼎勘头巾・油葫芦','孙仲章','yuanqu','','','他是个腰系红裙一妇人，你试议论，有甚事便推天抢地手粘身。
(王小二云)你家狗咬了我。
(正末云)你打破我缸，倒说狗咬了你。
(唱)且休论这两家凭伤损，(带云)常言道：男不和女斗。
王小二，(唱)你先合该笞四十批头棍。
(带云)你骂了人，倒说你是。
(唱)你没事哏，没事村，则你那帮闲钻懒腌身分，到宫中也不索取词因。','',''),('yuanqu-269','河南府张鼎勘头巾・天下乐','孙仲章','yuanqu','','','敢拖到官中拷断你筋，哎！你个乔人，情性村，则你那泼言语赖人不本分。
着我待饶来怎地饶？待忍来怎地忍？恨不的莽拳头嘴缝墩。
(云)是谁家的狗咬着你来？(王小二云)你家的狗咬着我来。
(正末云)你道我家狗咬着你，众街坊试看咱：若是我家狗咬他，我便写与你保辜文书。
若不曾咬着，你便陪我缸来。
(街坊云)员外说的是。
俺看他这条腿不曾咬着。
(王小二云)不是这条腿，是那一条腿。
(街坊云)也不曾咬。
(正末唱)。','',''),('yuanqu-270','河南府张鼎勘头巾・醉中天','孙仲章','yuanqu','','','谁小二哥休心困，觑两条腿辨清浑。
羞的那厮一柄脸通红似绛云，他慌遮掩忙身褪。
瞒不过相识街坊众亲，定晴觑认，并无些咬破牙痕。
(云)原来不曾咬着，这弟子孩儿这等图赖人。
(王小二云)这等恶狗，你养他怎的？(正末唱)。','',''),('yuanqu-271','河南府张鼎勘头巾・金盏儿','孙仲章','yuanqu','','','俺这犬吠柴门，和月待黄昏。
只除是盗贼不敢来相近，(带云)若是闲人呵。
(唱)无过是摇头摆尾弄精神。
他可也能熬鞭杖打，不弃主人贫。
我则理会妻贤先嫁主，这的是恶犬护三村。
(王小二云)员外，你轻呵轻君子，重呵重小人，怎将狗比我？(正末云)我这富汉打死你这穷汉，则苦了几文钱。
(王小二云)你说这等大话。
我大街上撞见你，一无话说。
僻巷里撞见你，我杀了你。
(旦云)好也，这厮不只是说出来，一定做出来。
问他要一纸生死文书，一百日以里，但有头疼脑热，都是你，一百日以外并不干你事。
(正末云)做甚么哩？(旦云)王小二要杀了你，我问他要保辜文书。
(正末云)大嫂，他怎敢杀人？王小二你听者。
(唱)。','',''),('yuanqu-272','河南府张鼎勘头巾・赚煞','孙仲章','yuanqu','','','你伏低呵自商和，我寻罪责官司问。
若不看解劝街坊面分。
小后生从来火性紧，发狂言信口胡喷。
自评论，口是祸之门，我劝你言同休记恨。
减些性粗性蠢，则要你妆痴妆坌，(王小二云)员外，是我的不是了。
我与你陪礼，取一瓶儿酒，请员外饮一杯罢。
(正末唱)何须你倒擎着酒盏去求人？(同旦下)。','',''),('yuanqu-273','河南府张鼎勘头巾・仙吕/赏花时','孙仲章','yuanqu','','','落日西园花正浓，扑面东风酒力涌。
全不省上青骢，只记得金钟漫捧，直劝我吃的到喉咙。','',''),('yuanqu-274','河南府张鼎勘头巾・幺篇','孙仲章','yuanqu','','','你觑那片草浑如蜀锦蒙，残照堪为烛影红，垂柳作帘栊。
暂撇下心烦意冗，醉卧绿阴中。
(做睡科)(净上杀末科，云)我杀了刘员外也。
拿着这芝麻罗头巾，减银环子。
回大嫂话去来。
(下)(街坊上，云)刘员外娘子，不知是甚么人杀了员外也？(旦上。
云)众街坊，甚么人杀了俺员外？(街坊云)知道是甚么人？(旦云)别无仇人，则是王小二，到他家试问咱。
早到门首也。
(唤科)(王小二上，见科)(旦云)好也，你与了我保辜文书，不上十日，就把员外杀了。
明有王法，我和你见宫去来。
(王小二云)我门也不曾出，可怎么冤我杀了员外？谁人与我做主咱？(下)。','',''),('yuanqu-275','河南府张鼎勘头巾・南吕/一枝花','孙仲章','yuanqu','','','虽是个判行的旧状词，合干办新公事。
出司房忙进步，登涩道下阶址。
又无甚过犯公私；把文卷依节次，请新官题判时。
先呈与个押解牒文，后押上今拘头佥字。','',''),('yuanqu-276','河南府张鼎勘头巾・牧羊关','孙仲章','yuanqu','','','这的是行恶的供成招伏，(府尹云)这一宗呢？(正末唱)这是打家贼责下口词。
(府尹云)这是甚么文卷？(正末唱)这的是远仓粮犹未关支，(府尹云)这一纸呢？(正末唱)这的是再修理道路桥梁，(府尹云)桥梁道路库狱仓廒，都是合管的，便该修理去。
又这一宗文卷呢？(正末唱)这的是重盖下仓廒库司。
(府尹云)这一宗呢？(正末唱)这的是亲兄弟争田土，(府尹云)这个呢？(正末唱)这的是亲女婿赖了家私。
(府尹云)这一宗呢？(正末唱)这的是相斗争商和状，(府尹云)这宗可是甚么文书？(正末唱)大人，立的是打杀人也未检尸。','',''),('yuanqu-277','河南府张鼎勘头巾・贺新郎','孙仲章','yuanqu','','','这头巾在菜园坦埋伏许多时，可怎生无半点儿尘丝，一星儿土渍？(令史云)瘸刘家菜园里井口边大石板压着，怎么得泥来？(正末唱)那更这减银上因何不见生涩？则他这一春雨何曾道是住止？(带云)大人寻思波。
(唱)可怎生黑真真的不动个文字？请先生别勘问，告大人再寻思。
这厮每其中敢有暗昧跷蹊事。
(做问科，云)谁是原告？(白云)妾身是原告。
(正末云)兀那妇人，且一壁去。
这妇人不是个良人。
(府尹云)怎生见得他不是良人？(正末唱)这妇人晴天开水路，无事设曹司。','',''),('yuanqu-278','河南府张鼎勘头巾・牧羊关','孙仲章','yuanqu','','','我跟前休胡讳，那其间必受私，既不沙怎无个放舍悲慈。
常言道：饱食伤心，忠言逆耳。
且休说受苞苴是穷民血，便那请俸禄也是瘦民脂。
咱则合分解民冤枉，怎下的将平人去刀下死。
(云)赵令史，道不的人性命关天关地也。
(唱)。','',''),('yuanqu-279','河南府张鼎勘头巾・商调/集贤宾','孙仲章','yuanqu','','','没来山惹这场闲是非，亲自问杀人贼。
全不论清廉正直，倒不如懵懂愚痴。
为别人受怕耽惊，没来由废寝忘食。
则俺那不明白该死的在那里，好教我闷恹恹蹙损双眉。
则为我一言容易出，今日个驷马却难追。','',''),('yuanqu-280','河南府张鼎勘头巾・逍遥乐','孙仲章','yuanqu','','','我为你亲身临牢内，审问虚实，端详就里。
(云)可早来到这牢门首也。
我拽动这铃索波。
(张千云)这是孔目来了(做开门见科，云)我开开这门，哥哥请进来。
(正末入科，云)张千，拿过王小二来。
(做拿王跪料，末云)兀那厮，你从实说来。
(唱)若说的半句儿差池，稳情取六问三推。
休想我等闲间觑面皮，向我行如何支对。
也无那八棒十枷，万死千生，都不到一时半刻。','',''),('yuanqu-281','河南府张鼎勘头巾・醋葫芦','孙仲章','yuanqu','','','你道是打的慌胡乱指，不想这头巾在那里，则你那勘时节莫不有甚么外人知？(张千云)哥也，这是狱不通风，谁敢来，并无人知。
(正末唱)取来时不有甚么人见你？(张千云)是我张千取来的，并无人见。
(正末云)勘时节也无人知，取时节又无人见。
(唱)这公事深藏着暖昧，好教我左猜右忖没端倪。
(云)张千，这头巾当初是你去取来？(张千云)是我取来。
(正末云)你到瘸刘家菜园里，曾叫那地主和房邻眼同一齐取来么？(张千云)不曾叫那地主、房邻，我自家跳过墙去取来了。
(正末云)张千，你不曾叫那地主、房邻眼同去取，又是越墙而过。
张千，这头巾环子敢是你放在那里？刘员外敢是你杀了么？(张千云)哥哥，干我甚么事？(正末云)可知不干你事哩，你则与个不应的状子。
(张千云)怎么把我也问个不应？(正末云)你看这厮不中用。
休说别的，则说这个问事厅，你来我跟前支了多少钱钞？今日也修理，明日也修理，便无那瓦呵，你也买几个草来苫一苫可也好。
(张千笑料，云)哦，我想起来了也。
(正末云)张千，你想起甚么来？这等笑？(张干云)那一日问王小二头巾环子时，有一个卖草的在这里来。
(正末唱)。','',''),('yuanqu-282','河南府张鼎勘头巾・幺篇','孙仲章','yuanqu','','','听言绝则我沉默默腹内忧，都做了虚飘飘心上喜，则那的便是图财致命杀人贼。
(带云)张千(唱)你手里要昨日卖草索钱的，(云)快与我拿的那个人来。
(张千云)我拿去。
(正末云)回来。
(唱)你听言仔细，(带云)你若拿不来，(唱)不拿来你身上有灾危。','',''),('yuanqu-283','河南府张鼎勘头巾・幺篇','孙仲章','yuanqu','','','则他那身材儿长共短？(张千云)我试想着，我记的他是个矮的。
(正末唱)画皮儿瘦共肥？(张千云)是个黄甘甘瘦脸儿。
(正末唱)他住居村舍可也近城池？(张千云)他说住在望京店，我记的他有些苫唇髭髟。','',''),('yuanqu-284','河南府张鼎勘头巾・挂金索','孙仲章','yuanqu','','','省可里后拥前推，着他向书案傍边立。
祗候人悄语低声。
休监押休着他跪。
(带云)孩儿也，(唱)你若说实情呵，我可便买与你个合酪吃。
(丑云)你孩儿肚里正饥哩。
(正末唱)我则问你言词，你一句句明支对。','',''),('yuanqu-285','河南府张鼎勘头巾・醋葫芦','孙仲章','yuanqu','','','听言罢他口内词，不由我心内疑，况兼那婆娘颜色有谁及。
他莫不共先生平口有些不伶俐？只他两个同谋设计，我十猜八九是真实。
(云)张千，着他吃合酪去。
(丑下)(正末云)张千，你去拿刘平远浑家来。
(张千云)理会的。
(出门科，云)兀那刘员外浑家，衙门里唤你哩。
(旦做醉上，云)妾身刘员外的浑家。
俺男儿被王小二杀了，众街坊都来与我解闷，饮了几杯散闷酒。
有衙门里着人来唤我，不知说甚么？须索走一遭去。
(见末科)(正末云)这妇人不吃酒来？（旦云)是吃闷解酒来。
(正末云)敢是解闷酒？(旦云)是众街坊见死了员外，都替我解闷来。
(正末唱)。','',''),('yuanqu-286','立成汤伊尹耕莘・仙吕/赏花时','郑光祖','yuanqu','','','今日个奉敕亲蒙圣帝差，(东华仙云)降生人间，辅佐于清朝，尔为仕途良相也。
(正末唱)待教我谪降尘寰做将相才。
(东华仙云)则今日离了紫府仙班，便索长行也。
(正末唱)拜辞了玉阙共金阶，离了这仙坛世界。
(东华仙云)上帝着你出离仙骨，托化凡胎，为世间辅弼之臣也。
(正末唱)待教我出仙骨我今日去托凡胎。
(下)。','',''),('yuanqu-287','立成汤伊尹耕莘・仙吕/点绛唇','郑光祖','yuanqu','','','混元始宇宙洪荒，二仪四象。
天差降，五帝三皇，安排定百二山河壮。','',''),('yuanqu-288','立成汤伊尹耕莘・混江龙','郑光祖','yuanqu','','','把干坤开创，教民耕种定纲常。
疏河源功高大禹，行庠序重德尧王。
那其间尧用一夔兴礼乐，公孙甲子论阴阳。
端的便察地理占天象，留心于社稷，运用于穹苍。','',''),('yuanqu-289','立成汤伊尹耕莘・油葫芦','郑光祖','yuanqu','','','想当日至德仁明掌万邦，用贤良定四方。
用天之道理之常，弘敷五典无偏党。
劳心尽思行温让，致令的四时和雨露均，八方宁士庶康，人心悦天意同和畅，因此上万国尽来降。','',''),('yuanqu-290','立成汤伊尹耕莘・天下乐','郑光祖','yuanqu','','','那其间四野桑麻禾稼穰，百姓每讴歌将天祭享。
军无战争民户昌，顺民心减税科，应天心绝逸荒，端的是普天下尊圣皇。','',''),('yuanqu-291','立成汤伊尹耕莘・醉中天','郑光祖','yuanqu','','','他每都争急言情状，语句意慌张。
(伴哥云)老员外，一个小小婴孩，在多年的空桑树里头里。
(正末唱)他道是年小孩童在古树里藏。
(王留云)特来报与老员外知道，并不虚言。
(正末唱)更说道并不言虚诳。
我这里心中暗想，今日个事从天降。
(伴哥云)谁敢不报与老员外知道。
(正末唱)一一的诉真情细说行藏。','',''),('yuanqu-292','立成汤伊尹耕莘・金盏儿','郑光祖','yuanqu','','','你看他青渗渗秀眉长，高耸耸俊鼻梁。
拳挛着手脚精神爽，潜形古树在村庄。
生的来清奇面似雪，肤体白如霜。
却怎么不教存画阁，莫不他举意隐空桑。','',''),('yuanqu-293','立成汤伊尹耕莘・醉中天','郑光祖','yuanqu','','','他生的神彩非凡像，美貌更端详。
莫不是谪降天宫坠下方？不由我心欢畅。
(李老人云)此子生的眉清目朗也。
(正末唱)真乃是眉清目朗，可怎生流落在村庄深巷？他那里叫吖吖两泪成行。
(云)王留、伴哥，好好的抱到家中，便寻觅奶母，好生将养着，也是好的勾当。
(李老人云)此子若长成，必然贵重也。
(正末唱)。','',''),('yuanqu-294','立成汤伊尹耕莘・尾声','郑光祖','yuanqu','','','你与我诚心儿好温存，用意相将傍。
看寒暑温凉作养，乳哺依时要忖量，另立所避风寒大厦高堂。
莫张荒，等的他那气血方刚，那其间着志求贤将师道访，习练的才高智广，文强武壮，恁时节扶持王业尽忠良。
(同老人下)。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-295','立成汤伊尹耕莘・中吕/粉蝶儿','郑光祖','yuanqu','','','想当日挚逝封尧，善能行圣人之道，以全图禹任皋陶。
他每都应天心，行正法，将黎民抚教。
自履癸临朝，运糟粕信从贪暴。','',''),('yuanqu-296','立成汤伊尹耕莘・醉春风','郑光祖','yuanqu','','','可怜见致涂炭庶和民，适灾危禽共鸟。
见如今天乙修德有谁如，端实是少，少。
上应天心，外施仁义，内存纯孝。','',''),('yuanqu-297','立成汤伊尹耕莘・迎仙客','郑光祖','yuanqu','','','我则待习农务耕绿野，趁农时效锄刨。
(余章云)似这等不肯进身，哥哥高见为何？(正末唱)这的是老生涯养拙一世了。
(余章云)似此可是怎生也？(正末唱)一任待卧烟霞，眠绿草，醒来时浊酒相邀。
(余章云)哥哥差矣。
似此怎么了得身事也。
(正末唱)这的是伊尹穷安乐。','',''),('yuanqu-298','立成汤伊尹耕莘・斗鹌鹑','郑光祖','yuanqu','','','着我受束带朝章，怎发付这儒冠布袄？(汝方云)更有驷马高车，请升车到朝中，加升官职也。
(正末唱)摆列下驷马高车，奉天建爵。
又不曾燮理阴阳将鼎鼐调，退夷狄边塞遥。
拜辞了草舍茅庵，受用的兰堂画阁。','',''),('yuanqu-299','立成汤伊尹耕莘・上小楼','郑光祖','yuanqu','','','我无那擎天动作，又无那惊人才调。
(汝方云)据贤士经济之才，俊伟之器，堪为将相也。
(正末唱)我不会辨别星斗，嗅土闻风，云雾低高。
(汝方云)贤士疾忙而起，贤臣遇明主而出。
正谓此也。
(正末唱)止不过播种耕耘，力习农务，攻锄田稻。
(汝方云)见有丹诏敕文在此。
(正末唱)怎消的紫泥宣一封丹诏。','',''),('yuanqu-300','立成汤伊尹耕莘・幺篇','郑光祖','yuanqu','','','你着我忙除了儒士冠，疾脱了粗布袍。
(汝方云)左右伺候，头答摆的齐整者！贤士请登程途。
(正末唱)他将水罐银瓶，伞盖头答，摆列周遭。
(汝方云)贤士，你穿用紫袍金带，骑坐着那白马红缨，端的是显威严也。
(正末唱)你道是白马红缨，紫袍金带，施威显耀。
(汝方云)贤士为官，贤士的妻房情受五花官诰，为贤德夫人也。
(正末云)荆布之妇。
(唱)怎消受五花官诰。','',''),('yuanqu-301','立成汤伊尹耕莘・耍孩儿','郑光祖','yuanqu','','','看一番揩磨日月兴宗庙，拣士马驱兵战讨。
经纶天地定皇朝，保持的社稷坚牢。
凋和那盐梅燮理阴阳顺，致令的天地和同风雨调。
休想我污婪矫权狡，托赖着一人有庆，稳情取万姓歌谣。
(云)大人，俺去来。
(唱)。','',''),('yuanqu-302','立成汤伊尹耕莘・尾声','郑光祖','yuanqu','','','慑伏的四夷朝帝京，八蛮贺圣朝。
遍干坤丰稔黎民乐太平表。
(同下)。','',''),('yuanqu-303','立成汤伊尹耕莘・正宫/端正好','郑光祖','yuanqu','','','再不见青霭霭柳阴浓，高耸耸山叠翠。
乐耕锄拽耙扶犁，我如今受皇宣着我居官位，端的也衣紫身荣贵。','',''),('yuanqu-304','立成汤伊尹耕莘・滚绣球','郑光祖','yuanqu','','','我则见头答左右随，公人前后围。
慢腾腾缓行着骏骑，喜孜孜列鼎而食。
辅佐的中华社稷安，揩磨的干坤日月辉。
展经纶补完天地，尽忠减心若金石。
(汝方云)聘贤士入朝，可也不轻也。
(正末唱)凭着这两支手掌扶王业，稳情着百二山河壮帝基，四海传檄。','',''),('yuanqu-305','立成汤伊尹耕莘・倘秀才','郑光祖','yuanqu','','','我本是田野中愚浊村鄙。
(仲虺云)特请贤士辅于公子，着贤士权临八府，印掌三台，为柱石之臣也。
(正末唱)怎做的相府内贤良宰职。
(方伯云)据贤士之才德，堪可为国家柱石也。
(正末唱)道我是立地擎天大柱石。
(汝方云)因贤士超越今古，智识高明，特赐象简紫衣，则是着贤士尽忠诚辅弼也。
(正末唱)则这白象简，紫罗衣。
(方伯云)全凭你高才大手，安邦定国也。
(正末唱)待教我安邦定国。
(汝方云)贤士，今欲兴师，未彻兵家用事，贤士展神鬼不测之机，兴一旅之师，辅佐公子，以成大事。
(正末云)小生是一扶犁叟，岂知兵家之事也！(仲虺云)论贤士之智能，觑夏桀有何难哉！(正末唱)。','',''),('yuanqu-306','铁拐李度金童玉女・仙吕/八声甘州','贾仲明','yuanqu','','','花遮翠拥，香霭飘霞，烛影摇红。
月梁云栋，上金钩十二帘栊。
