爽气透襟怀，满面春风。
(铁拐上，云)贫道按落云头，来到女直地面。
这里就是金安寿家。
我去与他添寿化斋，看他说甚么。
(见科云)稽首。
贫道特来化斋添寿。
(正末云)一个先生来化斋求利市。
不知先生从那里来？(铁拐云)从三岛来。
(正末云)往那里去？(铁拐云)特来度你为神仙，往蓬莱去。
(正末云)休胡说那。
(唱)。','',''),('yuanqu-307','铁拐李度金童玉女・寄生草','贾仲明','yuanqu','','','俺围珠翠冰绡内，胜蓬莱阆苑中。
