(铁拐云)贫道昨日蕊珠宫醉倒，今日却在这里。
(正末笑科)(唱)你昨宵个夜沉沉醉卧蕊珠宫，今日暖融融误入桃源洞。','',''),('yuanqu-308','铁拐李度金童玉女・满堂红','贾仲明','yuanqu','','','凤凰台下风凰台也波台。
