弦管声中更漏永，千般婉转，万般调弄，不觉夜将终。','',''),('yuanqu-313','铁拐李度金童玉女・幺篇','贾仲明','yuanqu','','','可正是歌尽桃花扇底风，人面映和花红，两下春心应自懂。
怜香惜玉，颠鸾倒凤，人在锦胡同。','',''),('yuanqu-314','铁拐李度金童玉女・赚煞尾','贾仲明','yuanqu','','','枉了你费精神，休则管相拦纵，怎撇的玉天仙风流爱宠？(铁拐云)这尤物要他怎么？(正末唱)端的个鱼水夫妻两意同，少年人兴味偏浓。
