锦绣肠，江湖量，都分付水国江乡。','',''),('yuanqu-350','苏子瞻风雪贬黄州・鹊踏枝','费唐臣','yuanqu','','','万言策上君王，一骑马度衡阳。
索离了三岛蓬莱，直走遍九曲沧浪。
学不的李太白逍遥在醉乡，参破了韩昌黎夕贬潮阳。','',''),('yuanqu-351','苏子瞻风雪贬黄州・寄生草','费唐臣','yuanqu','','','臣则待居蛮貊，再谁想立庙堂。
今日有曾参难免投梭诳，今日有周公难免流言讲，有仲尼难免狐裘谤。
本是个长门献赋汉相如，怎做的东篱赏菊陶元亮。','',''),('yuanqu-352','苏子瞻风雪贬黄州・幺篇','费唐臣','yuanqu','','','臣折么流儋耳，臣折么贬夜郎。
一个因书贾谊长沙放，一个因诗杜甫江边葬，一个因文李白波心丧。
臣觑屈原千载汨罗江，便是禹门三月桃花浪。','',''),('yuanqu-353','苏子瞻风雪贬黄州・金盏儿','费唐臣','yuanqu','','','不荒唐，不颠狂，折末云阳枭首高竿上，也要将碧天风月两平章。
拚着梦魂游故国，想像赴高堂。
则今日伤心游海岛，携手上河梁。
(末云)罢、罢，则今日拜辞了圣驾，别了丞相，只索长行也。
(唱)。','',''),('yuanqu-354','苏子瞻风雪贬黄州・赚煞','费唐臣','yuanqu','','','则为不入虎狼群，躲离鲸鲵浪，直贬过淘淘大江，不信行人不断肠。
赤紧的接天隅烟水茫茫，助凄凉衰草斜阳，休想我筑起高台望故乡。
这里有当途虎狼，那里有拍天风浪。
我要过水云乡，则是跳出是非场。
(下)。','',''),('yuanqu-355','苏子瞻风雪贬黄州・正宫/端正好','费唐臣','yuanqu','','','道德五千言，礼乐三十卷。
本待经纶就舜日尧天，只因两角蜗蛮战，贬得我日近长安远。','',''),('yuanqu-356','苏子瞻风雪贬黄州・幺篇','费唐臣','yuanqu','','','瑶台昨夜蛟龙战，玉鳞甲飞满山川。
冯夷饮罢琼林宴，醉把鲛绡剪。
(云)好大雪也呵。
(唱)。','',''),('yuanqu-357','苏子瞻风雪贬黄州・滚绣球','费唐臣','yuanqu','','','泼墨云垂四野，铸银河插半天。
把人间番做了广寒宫殿，有一千顷玉界琼田。
这其间骚客迁，朝士贬。
五云乡杳然不见，止不过隔蓬莱弱水三千。
不能彀风吹章表随龙去，可做了雪拥蓝关马不前，哽咽无言。','',''),('yuanqu-358','苏子瞻风雪贬黄州・倘秀才','费唐臣','yuanqu','','','早是水杳山长路远，那更雪冻风寒云卷。
(云)你道我行的慢呵，可知可知(唱)我可甚为爱青山懒赠鞭！呵冻手，从双肩。
我只索向前。
(童云)老爹，人都说你好才学，却怎生遭贬，到不知老爹与上古贤人君子，那几个相似！(末云)这小的虽小倒也省事。
你既问我，你听我与你说。
(唱)。','',''),('yuanqu-359','苏子瞻风雪贬黄州・滚绣球','费唐臣','yuanqu','','','我怕不文章似韩退之史，笔如司马迁。
英俊如仲宣子建，豪迈如居易宗元。
风骚如杜少陵，疏狂如李谪仙。
高洁如谢安李愿。
德行如闵子颜渊。
为不学乘桴浮海鸱夷子，生扭做踏雪寻梅孟浩然。
困煞英贤。','',''),('yuanqu-360','苏子瞻风雪贬黄州・倘秀才','费唐臣','yuanqu','','','脱离了长安市廛，须捱到黄州地面，更狠似夕贬潮阳路八千。
往常师往圣，友前贤，到如今怎展！。','',''),('yuanqu-361','苏子瞻风雪贬黄州・滚绣球','费唐臣','yuanqu','','','我也曾写珠玑一万联，判莺花三百篇，扫千军笔端鏖战，但行处天子三宣。
结平生诗酒缘，掌中天风月权。
不是将帝王埋怨，为甚把苏轼似贾谊南迁。
如今一牧童子随驴后，可甚两行朱衣到马前。
四野萧然。','',''),('yuanqu-362','苏子瞻风雪贬黄州・呆骨朵','费唐臣','yuanqu','','','见黄童白叟把香醪劝，怕不透彻了酒兴诗颠。
(马云)老夫久闻大才，敢求佳作见教。
(末云)大人饮酒则饮酒。
再休言诗。
(马云)诗酒乃吾生分内事。
大人此行，与诗酒何干。
(末唱)我须不是为酒忘家，见如今因诗受贬。
酒债是寻常事，诗病是平生愿。
我为甚远流身万里，因此上怕吟诗百篇。
(马云)苏大人高才重望，正宜居朝佐主，以治太平。
岂宜放逐！(末唱)。','',''),('yuanqu-363','苏子瞻风雪贬黄州・五煞','费唐臣','yuanqu','','','我情愿闲居村落攻经典，谁想闷向秦楼列管弦。
枕碧水千寻，对青山一带，趁白云万顷，尽茅屋三间草舍蓬窗，苜蓿盘中，老瓦盆边，乐于贫贱，灯火对床眠。','',''),('yuanqu-364','苏子瞻风雪贬黄州・四煞','费唐臣','yuanqu','','','从教头上青天鉴，不愿腰间金印悬。
受他冷冷清清，多多少少，避是是非非，万万千千。
或向林皋声里，舴艋舟中，霍索溪边。
一壶村酒，白眼望青天。','',''),('yuanqu-365','苏子瞻风雪贬黄州・三煞','费唐臣','yuanqu','','','紫袍金带无心恋，两笠烟蓑有意穿。
或向新妇矶头，鸥鹭乡中，儿女浦口，鹦鹉洲边。
涨一竿春水，带一抹寒烟，掉一只渔舡。
黑甜一枕睡，灯火对愁眠。','',''),('yuanqu-366','仙吕/点绛唇','杨景贤','yuanqu','','','宝殿生香，美人扶向，瑶阶上。
列七宝旌幢，端坐泥金亢。','',''),('yuanqu-367','混江龙','杨景贤','yuanqu','','','我怕不似嫦娥模样，将一座广寒宫移下五云乡。
两般比谕，一样凄凉。
嫦娥夜夜孤眠居月窟，我朝朝独自守家邦。
虽无那强文壮武，宰相朝郎，列两行脂粉，无四野刀枪。
千年只照井泉生，平生不识男儿像。
见一幅画来的也情动，见一个泥塑的也心伤。','',''),('yuanqu-368','油葫芦','杨景贤','yuanqu','','','说他几载其间离了大唐，来到俺地方，安排香案快疾忙。
今日取经直过俺金阶上，抵多少醉鞭误入平康巷。
我是一个聪明女，他是一个少年郎。
谁着他不明白抢入我花罗网，准备着金殿锁鸳鸯。','',''),('yuanqu-369','天下乐','杨景贤','yuanqu','','','稳情取和气春风满画堂，宰下肥羊，安排的五味香，与俺那菜馒头的老兄腾了肚肠。
陪妆奁留他做丈夫，舍身躯与他做正房，可知道男儿当自强。','',''),('yuanqu-370','那叱令','杨景贤','yuanqu','','','身才儿俊长，加持得鬼王；容貌儿善良，修持得梵正；胸襟儿纪纲，扶持得帝王。
头如蓝靛青，语似春雷壮，这和尚端的非常。','',''),('yuanqu-371','鹊踏枝','杨景贤','yuanqu','','','执方尊泻琼浆，露春葱捧瑶觞。
(唐僧云)娘娘，及早修业，无常有限者。
(女王唱)但能勾两意多情，尽教他一日无常。
天魔女邪施伎俩，敢是你个释迦佛，也按不住心肠。','',''),('yuanqu-372','寄生草','杨景贤','yuanqu','','','直裰上胭脂污，袈裟上腻粉香。
似魔腾伽把阿难摄在淫山上，若鬼子母将如来围定在灵山上，巫枝祗把张僧拿住在龟山上。
不是我魔王苦苦害真僧，如今佳人个个要寻和尚。','',''),('yuanqu-373','幺','杨景贤','yuanqu','','','徒弟每诸般劝，师父独自慌。
俺女兵不用猴为将，女王岂用猪为相？如今女娘都爱唐三藏。
你休痴迷修行今世有来生，我则待长江后浪催前浪。
(女王做扯唐僧科)这正殿上不是说话的去处，俺两个后殿里去来。
(唐僧云)孙悟空救我。
(下)(行者云)我自也顾不得。
(诸女做捉番孙、猪、沙发科)(下)(女王扯唐僧上，云)唐僧，我和你成其夫妇，你则今日就做国王，如何？(唐僧云)善哉！我要取经哩。
(发科)(女王唱)。','',''),('yuanqu-374','六幺序','杨景贤','yuanqu','','','香馥郁销金帐，光灿烂白象床，俺两个破题儿待弄玉偷香。
听得说天地阴阳，自有纲常，人伦上下，不可孤孀。
俺这里天生阴地无阳长，你何辜不近好婆娘？浮屠尽把三纲丧。
(唐僧云)佛教自是一家。
(女王云)说你那佛怎么？孔夫子文章贯世，天下传扬。','',''),('yuanqu-375','幺','杨景贤','yuanqu','','','你虽奉唐王，不看文章。
舜娶娥皇，不告爷娘。
后代度量，孟子参详。
他父母非良，兄弟参商，告废了人伦大纲，因此上自上张。
你非比俗辈儿郎，没来由独锁空房。
不从咱除是飞在天上，箭射下来也待成双。
你若不肯呵，锁你在冷房子里，枉熬煎得你镜中白发三千丈。
成就了一宵恩爱，索强似百世流芳。','',''),('yuanqu-376','金盏儿','杨景贤','yuanqu','','','披金甲貌堂堂，持宝杵气昂昂。
莫不是淹蓝桥烧祆庙的腌神将？比唐僧模样更非常。
(韦云)吾神三十老，完为童子身。
特来护法来。
(女王云)又是个柳下惠、颜叔子。
焦则么那村柳舍？叫则么那口吞颜郎？你整村了三十载，他干过了二十霜。
(韦云)若不送师父出来，一杵打你做泥尘。
(女王做放手科)。','',''),('yuanqu-377','尾','杨景贤','yuanqu','','','我无缘保的他无恙，闹炒起花烛洞房。
怕甚么深院沉沉秋夜长，决撒了帽儿光光。
恨韦郎，不做周方，我不道的恼乱苏州刺史肠。
我如今去，我这里收拾下画堂，埋伏下兵将，等回来拿住再商量。
(下)。','',''),('yuanqu-378','南吕/玉交枝','杨景贤','yuanqu','','','贪杯无厌，每日价汛流霞潋滟。
子云嘲谑防微渐，托鸱夷彩笔拈。
季鹰好饮豪兴添，忆莼鲈只为葡萄酽。
倒玉山恁般瑕玷，又不是周晏相沾。
糟腌着葛仙翁，曲埋那张孝廉。
恣狂情，谁与砭？英雄尽你夸，富贵饶他占，则这黄垆畔有祸殃，玉缸边多危险，酒呵，播声名天下嫌。','',''),('yuanqu-379','幺','杨景贤','yuanqu','','','富豪的偏俭，奢华的无过是聚敛。
王戎、郭况心无厌，拥金穴握牙签。
可知道分金鲍叔廉，煞强如牢把铜山占。
晋和峤也多褒贬，恰便是朱方聚歼。
有齿的焚身，多财的要谦。
斗量珠，树系缣，刑伤为美姝，杀伐因求剑。
空有那万贯钱，到底来亡沟堑。
财呵，播声名天下嫌。','',''),('yuanqu-380','醉乡春','杨景贤','yuanqu','','','打渔鼓高歌兴添，采灵芝快乐无厌。
大叫高呼，前遮后掩。
远量度，近观瞻，谨廉礼谦，休猜我做避世陶潜。','',''),('yuanqu-381','碧玉霄','杨景贤','yuanqu','','','瀑布签寒，涧落水帘，木绕山尖，猿啸虎张髯。
仗法力则可行，无神通休强参。
将山色来瞻，似碧玉无瑕玷。
苦辛不厌，大发慈悲念。
师父趱行者。','',''),('yuanqu-382','随尾','杨景贤','yuanqu','','','玉鞭紧紧催金革占，火焰山千难万险。
早求法力到西天，莫把残躯葬山崦。
(下)。','',''),('yuanqu-383','正宫/端正好','杨景贤','yuanqu','','','我在巽宫里居，离宫里过，我直滚沙石撼动娑婆。
天长地久谁煞得我？把世界都参破。','',''),('yuanqu-384','滚绣球','杨景贤','yuanqu','','','孟婆是我教成，风神是我正果。
我和骊山老母是姊妹两个，我通风他通火。
角木蛟、井木犴是叔伯亲，斗木獬、奎木狼是舅姑哥。
当日宴蟠桃惹起这场灾祸，西王母道他金能欺风木催槎。
当日个酒逢知己千钟少，话不投机一句多，死也待如何？俺这里铁嵯峰，好景致也呵。','',''),('yuanqu-385','尉迟恭三夺槊・仙吕/点绛唇','尚仲贤','yuanqu','','','想当日霸业图王，岂知今亡，把江山掌。
虽不是外国他邦，今日做僚宰为卿相。','',''),('yuanqu-386','尉迟恭三夺槊・混江龙','尚仲贤','yuanqu','','','不着些宽洪海量，划地信谗言佞语损忠良。
谁不曾忘生舍死？谁不曾展土开疆？不枉了截发搓绳穿断甲，征旗作带勒金疮。
我与你不避金瓜下丧，直言在宝殿，苦谏在昭阳。','',''),('yuanqu-387','尉迟恭三夺槊・天下乐','尚仲贤','yuanqu','','','谁似俺出气力功臣不气长，想当时，反在晋阳。
若不是唐元帅少年有纪纲，义伏了徐茂公，礼慑了褚遂良，智降了苏定方。','',''),('yuanqu-388','尉迟恭三夺槊・醉扶归','尚仲贤','yuanqu','','','当日都是那不主事萧丞相，更合着那没政事汉高皇，把韩元帅葫芦提斩在未央。
今日个人都讲，若有举鼎拔山的霸王，哎．汉高呀你怎敢正眼儿把韩侯望。','',''),('yuanqu-389','尉迟恭三夺槊・后庭花','尚仲贤','yuanqu','','','陛下，则将这美良川水冤恨想，却把那榆窠园耻英雄忘。
更做道世事云千变，敬德呵则消得功名纸半张。
陛下试参详，更做道贵人多忘，咱数年问有倚仗。','',''),('yuanqu-390','尉迟恭三夺槊・金盏儿','尚仲贤','yuanqu','','','那敬德自归了唐，到咱行，把六十四处烟尘荡。
杀得敌军胆丧，马到处不能当，苦相持一万阵，恶战讨了九千场。
全凭着竹节鞭，生并了些草头王。','',''),('yuanqu-391','尉迟恭三夺槊・赏花时','尚仲贤','yuanqu','','','元帅不合短箭轻弓观他洛阳，怎想阔剑长枪埋在浅岗，映着秋草半苍黄。
初间那唐元帅怎想，脑背后不堤防。','',''),('yuanqu-392','尉迟恭三夺槊・幺篇','尚仲贤','yuanqu','','','呀，则见那骨刺剌征旗遮了太阳，赤力力征鼙振动上苍，那单雄信恁高强。
他猛观了敌军势况，忙拨转紫丝缰。','',''),('yuanqu-393','尉迟恭三夺槊・胜葫芦','尚仲贤','yuanqu','','','打得匹不剌刺征马宛走电光，藉不得众儿郎，过涧沿坡寻路忄葱。
过了些乱烘烘的荆棘，密稠稠榆柳，齐臻臻长成行。','',''),('yuanqu-394','尉迟恭三夺槊・金盏儿','尚仲贤','yuanqu','','','元帅却是那些儿慌，那些忙，(带云)忙不忙，元帅也记得。
把一领锦征袍扯裸得没头当。
单雄信先地赶上手拈着绿沉枪，枪尖儿看看地着脊背，着脊背透过胸堂。
那时若不是胡敬德。
(带云)陛下圣鉴谁搭救小秦王？。','',''),('yuanqu-395','尉迟恭三夺槊・醉扶归','尚仲贤','yuanqu','','','索甚把白己千般奖，齐王呵，不如教别人道一声强。
若共胡敬德草草的鞭斗枪，分明立了执结并文状，则他家自卖弄伶俐半晌，把一条虎眼鞭直揽头直上。','',''),('yuanqu-396','尉迟恭三夺槊・尾','尚仲贤','yuanqu','','','这厮则除了铁天灵，铜脖项，铜脑袋，石镌就的脊梁。
那鞭上常有半纸血糊涂的人脑浆，则那鞭则是铁头中取命的阎正。
若论高强，鞭着处便不死十分地也带重伤。
也是青天会对当，故教这尉迟恭磨障，磨障这杀君杀父的劣心肠。
(下)。','',''),('yuanqu-397','尉迟恭三夺槊・南吕/一枝花','尚仲贤','yuanqu','','','箭空攒白凤翎，弓闲挂乌龙角，土培损金锁甲，尘昧了锦征袍。
空喂得那匹战马咆哮，劈椤锏生疏却，那些儿俺心越焦。
我往常雄纠纠的阵面上相持，恶喑喑的沙场上战讨。','',''),('yuanqu-398','尉迟恭三夺槊・梁州','尚仲贤','yuanqu','','','这些时但做梦早和敌军对垒，才合眼早不刺剌地战马相交。
则听的韵悠悠的耳畔吹寒角，一回价不冬冬的催军鼓擂，响当当的助战锣敲。
稀撒撒地朱帘筛日，滴溜溜的绣幕翻风，只疑是古剌剌杂彩旗摇。
那的是急煎煎心痒难揉，往常则许咱遇水叠桥，除了咱逢山开道，嗨，如今央别人跨海征辽。
壮怀怎消，近新来病体儿直然较，我自喑约也枉了医疗，被这秋气重金疮越发作，好教我痛苦难消。','',''),('yuanqu-399','尉迟恭三夺槊・贺新郎','尚仲贤','yuanqu','','','我欠起这病身躯出产急相邀，你知我迭不的相迎，带云不沙，贼丑生唱你也合早些儿通报。
见齐王元吉都来到，半晌不迭手脚，我强强地曲脊低腰。
怪早来喜蛛儿的溜溜在檐外垂，灵鹊儿咋咋地头直上噪，昨夜个银台上剥地灯花爆。
他两个是九重天上皇太子，来探俺这半残不病旧臣僚。','',''),('yuanqu-400','尉迟恭三夺槊・隔尾','尚仲贤','yuanqu','','','我从二十三上早驱军校，经到四五千场恶战讨。
怎想头直上轮还老来到。
我暗约，慢慢的想度，嗨，刮马似三十年过去了。','',''),('yuanqu-401','尉迟恭三夺槊・隔尾','尚仲贤','yuanqu','','','那鞭却似一条玉蟒生鳞角？便是半截乌龙去了牙爪，那鞭着远望了吸吸地脑门上跳。
那鞭休道十分的正着，则若轻轻地抹着，敢教你睡梦里惊急列地怕到晓。','',''),('yuanqu-402','尉迟恭三夺槊・尾','尚仲贤','yuanqu','','','可知道金风未动蝉先觉，那宝剑得来你怎消，不出君王行。
厮般调，侵着眉楞，擦着眼角。
则若是轻轻的虎眼鞭抹着，稳情取你那天灵盖半截不见了。
(下)。','',''),('yuanqu-403','尉迟恭三夺槊・步步娇','尚仲贤','yuanqu','','','便折末烂锉得我尸骸为泥粪，折末金瓜打碎我天灵尽。
既然俺不怨恨，问那厮损坏忠臣佞词因。
咱那亢金椅上圣明君，则但般着半句儿十分地信。','',''),('yuanqu-404','尉迟恭三夺槊・川拨棹','尚仲贤','yuanqu','','','听元帅说原因，心头上一千团火块滚。
气的肚里生嗔，愁的似地惨天昏。
恰便似心内火块滚，好教人怎受忍。','',''),('yuanqu-405','萧何月夜追韩信・仙吕/点绛唇','金仁杰','yuanqu','','','想着我独步才超，性与天道，凌云浩。
世事皆浊，则我这美玉谁雕琢？。','',''),('yuanqu-406','萧何月夜追韩信・混江龙','金仁杰','yuanqu','','','消磨了圣人之教，儿时的经纶天地。
整皇朝。
时遇着梁雌雉，急切钓不的沧海鲸鳌。
泪洒就长江千尺浪，气冲开云汉几重霄。
啊次包罗大地，肺腑卷摄江河。
笔尖能摇山岳，剑锋可摘星辰。
叹英雄何日朝闻道，盼杀我也玉堂金马，困杀我也陋巷箪瓢。','',''),('yuanqu-407','萧何月夜追韩信・油葫芦','金仁杰','yuanqu','','','寻思我枉把孙吴韬略学，天交我不发迹直等到老，一回家怨天公自恁困英豪。
叹良金美玉何人晓，恨高山流水知音少。
礼不通忘了管辖，道不行无了木铎。
枉着那兵书战策习的玄妙，争奈俺命不济谩徒劳。','',''),('yuanqu-408','萧何月夜追韩信・天下乐','金仁杰','yuanqu','','','空教我日夜思量计万条，一回家心焦，何日了？越把我磨剑的志节懒堕却，窄将文业攻，武艺学，至如学将来有甚好。','',''),('yuanqu-409','萧何月夜追韩信・那吒令','金仁杰','yuanqu','','','似这般大雪呵，街上黎民也懊恼；似这般大雪呵，山上樵夫也怎熬；似这般大雪呵，江上渔翁也冻倒。
便有个姜子牙也难应非熊兆，子索把绿蓑衣披着。','',''),('yuanqu-410','萧何月夜追韩信・鹊踏枝','金仁杰','yuanqu','','','昔零零洒琼瑶，乱纷纷翦鹅毛。
越映的江阔天低，水远山遥。
冰雪堂苏秦冻倒，漏早堂颜子难熬。','',''),('yuanqu-411','萧何月夜追韩信・寄生草','金仁杰','yuanqu','','','凛凛寒风刮，扬扬大雪飘。
如银河滚下飞虹瀑，似玉龙喷出梨花落，比白云满地无入扫，我则见败残鳞甲满天飞，抵多少西风落叶长安道。
(做见旦外，并旦施礼科)(旦云了)。','',''),('yuanqu-412','萧何月夜追韩信・幺','金仁杰','yuanqu','','','你道我秋夏间犹难过，冬月天怎地熬，可不春来依旧生芳草。
你道我白身无靠何时了，可不说青霄有路终须到。
则我这男儿未济妇人嫌，真乃是龙归浅水蟆虫麻笑。','',''),('yuanqu-413','萧何月夜追韩信・村里迓鼓','金仁杰','yuanqu','','','凭着我五陵豪气，不信道一生穷暴。
(云)夫子抱麒麟而哭生不遇时。
我若生在春秋那时，英雄志登时宣召。
凭着满腹才调，非咱心傲。
论勇呵那里说卞庄强，论武呵也不数廉颇会，论文呵怎肯比子产高，沦智呵我敢和伍子胥临潼斗宝。
(等外并旦又住)。','',''),('yuanqu-414','萧何月夜追韩信・元和令','金仁杰','yuanqu','','','晋灵辙得饭了，请赵盾且休闹。
圣人言谋道不谋食，居无安食无饱。
觑了田文门下女妖娆，(做烦恼出门，唱)我宁可首阳山白饿倒。
(等净土，打撞怒云)。','',''),('yuanqu-415','萧何月夜追韩信・上马娇','金仁杰','yuanqu','','','口口庚运歹也逢太岁恶，但行处撞着儿曹。
(等净做住，行着唱)他把我丕丕的赶过长安道，恶难怎逃。
时下怎归着，忿气不消，赶到我二十遭。','',''),('yuanqu-416','萧何月夜追韩信・游四门','金仁杰','yuanqu','','','呀，早剑横秋水手中提，(等净云了)我可甚由自想来朝。
(等净云了)你道拜为兄长相结好，为朋友便耽饶。
呵，咱两个做知交。','',''),('yuanqu-417','萧何月夜追韩信・胜葫芦','金仁杰','yuanqu','','','可知大古是人伴贤良智转高，(净怒云了)呀，怎想舌是斩身刀。
则见他恶歆歆伏着龙泉寻左错，他把我踢收秃刷观觑，则觉我惊惊战战心怕，不由我的羞剔痒腿艇摇。','',''),('yuanqu-418','萧何月夜追韩信・后庭花','金仁杰','yuanqu','','','归冥鸿惜羽毛，休想先王懒折腰。
(做钻一遭)赤紧在他双股下，子索伏低且做小。
(做又钻一遭)向胯下扒步到两三遭，避个的乡人海耻笑恨难消。
伏软弱痛难熬，儿曹每行霸道。
(等外唱净下了)是准人把剑客赶去了？细身躯猛回头观觑着。','',''),('yuanqu-419','萧何月夜追韩信・柳叶儿','金仁杰','yuanqu','','','却元来是孟尝君来到。
(等旦云)见桑新妇乱下风雹，哥哥咱止是扬鞭举棹休相笑。
却才那齐管仲行无道，义见鲁义姑逞粗豪，咱呵可甚晏平仲善与人交。','',''),('yuanqu-420','萧何月夜追韩信・尾','金仁杰','yuanqu','','','(卜儿砌末)真乃是孟母断机心，(等外与砌末了)怎忘的鲍叔般相结好。
(旦云了)我早则离了你贤达嫂嫂，(等旦云了)人丈夫何愁刎颈交。
(旦云了)割鸡焉用牛刀，打听波女妖娆，有一日平步青霄，不信鸿鹄同燕雀。
(等旦云了)噤声！凭着我整干妇六韬，展江山三略，笑谈间束带立于朝。
(下)。','',''),('yuanqu-421','萧何月夜追韩信・双调/新水令','金仁杰','yuanqu','','','恨天涯流落客孤寒。
叹英雄半世虚幻。
坐下马空踏遍山水雄。
背上剑枉射得斗牛寒。
恨塞于天地之间，云遮断玉砌雕栏，按不住浩然气透霄汉。','',''),('yuanqu-422','萧何月夜追韩信・雁儿落','金仁杰','yuanqu','','','丞相道将咱来不住的赶，韩信则索把程途盼。
(萧何云了)为甚却相逢便噤声，非是我不言语相轻慢。','',''),('yuanqu-423','萧何月夜追韩信・得胜令','金仁杰','yuanqu','','','我又怕叉手告人难，闲此上懒下宝雕鞍。
(萧何云了)说着汉天子犹心困，量着楚重瞳怎挂眼。
(萧何云了)弃骏马雕鞍，向落日夕阳岸。
办蓑笠纶竿，钓西风渭水寒。','',''),('yuanqu-424','萧何月夜追韩信・挂玉钩','金仁杰','yuanqu','','','我怎肯一事无成两鬓斑，(萧何云了)既然你不用我这英雄汉，因此上铁甲将军夜度关。
你端的为马来将人盼，既不为马共人，却有甚别公干？我汉室江山，可知、可知保奏得我甚挂印登坛。
(萧何云了)(渔公上，云了)(萧何并末上船科)丞相道渔公说得是，官人每不在家里快活，也这般戴月披星生受了。
末将谓韩信功名如此艰辛，元末打鱼的觅衣饭吃，更是生受。','',''),('yuanqu-425','便宜行事虎头牌・仙吕/点绛唇','李直夫','yuanqu','','','一来是祖父的家门，二来是自家的福分，悬牌印。
扫荡征尘，将勇力拖逞尽。','',''),('yuanqu-426','便宜行事虎头牌・昆江龙','李直夫','yuanqu','','','几回家开旗临阵。
战番兵累次建功勋。
怕不的资财足备，孳畜成群。
长养着百槽冲锋的惯战马，掌管着一千户屯田的镇番军。
我如今欲待去清愁闷，则队得飞鹰走犬，逐逝追奔。','',''),('yuanqu-427','便宜行事虎头牌・天下乐','李直夫','yuanqu','','','只见他越寻思越着昏，敢三魂失了二魂。
(带云)我试猜波。
(唱)莫不是铁哥镇抚家远探亲？(六儿云)不是。
(正末唱)莫不是达鲁家老太君？(六儿云)也不是。
(正末唱)莫不足普察家小舍人？(六儿云)也不是。
(正末唱)莫不是叔叔婶子两口儿来访问？。','',''),('yuanqu-428','便宜行事虎头牌・醉中天','李直夫','yuanqu','','','叔叔你鞍马上多劳困，婶子你程途上受艰早，一自别来五六春，数载家无音信。
则这个山寿马别无甚痛亲，我一言难尽，来探你这歹孩儿索是远路风尘。','',''),('yuanqu-429','便宜行事虎头牌・金盏儿','李直夫','yuanqu','','','我自小里化了双亲，忒孤贫，谢叔叔婶子把我来似亲儿般训。
演习的武和文，我如今镇边关为元帅，把隘口统三军。
我当初成人不自在，我若是自在不成人。','',''),('yuanqu-430','便宜行事虎头牌・一半儿','李直夫','yuanqu','','','则俺那祖公是开国旧功臣，叔父你从小里一个敢战军，这金牌子与叔父带呵，也是本分。
见婶子那壁意欣欣，(云)叔父，你受了这牌子者！(老千户云)我可怎么做的？(正末唱)我见他一半儿推辞一半儿肯。','',''),('yuanqu-431','便宜行事虎头牌・金盏儿','李直夫','yuanqu','','','我为甚么语谆谆，单怕你醉醺醺，只看那斗来粗肘后黄金印，怎辜负的主人恩。
但愿你扶持今社稷，驱灭旧妖氛。
常言道"家贫显孝子，国难识忠臣"。','',''),('yuanqu-432','便宜行事虎头牌・赚煞','李直夫','yuanqu','','','则今日过关津，度州郡，没揣的逢他敌人，阵面上相持赌的是狠。
托赖着俺祖公是番宿家门，哎，你莫因循。
便只待人急偎亲，畅奸道厮杀无过是咱父子军，誓将那鲸鲵来尽吞。
只将这边关守紧，你可便舍一腔热血报明君。
(同旦儿、六儿下)(老千户云)俺侄儿去了也。
则今日往渤海寨搬取家小走一遭去。
(同老旦下)。','',''),('yuanqu-433','便宜行事虎头牌・双调/五供养','李直夫','yuanqu','','','愁冗冗，恨绵绵，争余我赤子空拳，只得问别人借了几文钱。
可买的这一瓶儿村酪洒，等与我那第二弟兄祖饯。
想着他期限迫难留恋，可若是今番云也，知他是甚日个团圆。
(云)兀的不是我兄弟？(老千户云)兀的不是我哥哥？(见科，云)哥哥，你兄弟做了金牌上千户，如今镇守夹山口去，一径的辞哥哥来。
(正末云)兄弟，我知道你做了金牌千户，镇守夹山口子去。
我无甚么，买这一瓶儿酒，与兄弟饯行。
(老千户云)看你这般艰难，你那里得这钱来买酒？教哥哥费心。
(正末做递酒科，唱)。','',''),('yuanqu-434','便宜行事虎头牌・落梅风','李直夫','yuanqu','','','我抹的这瓶口儿净，我斟的这盏面儿圆。
(老千户做接盏科)(正末云)兄弟，且休便吃。
(唱)待我望着那碧天边太阳浇奠。
则俺这穷人家又不会别咒愿，则愿的俺兄弟海每可便早能勾相见。
(做浇奠、再递酒科，云)兄弟满饮一杯。
(老千户云)哥哥先饮。
(正末云)好波，我先吃了。
兄弟饮。
(老千户云)待你兄弟吃。
(正末云)兄弟再饮一杯。
(老千户云)只我今日见了哥哥，吃几杯酒；到了夹山口子，我一点酒也不吃了。
(正末云)兄弟，你哥哥无甚么与你。
(老千户云)我今日辞哥哥去，敢问哥哥要甚么？(正末唱)。','',''),('yuanqu-435','便宜行事虎头牌・阿那忽','李直夫','yuanqu','','','再得我往日家缘，可敢赍发与你些个盘缠。
有他这鳔接来的两根儿家竹箭，(老千户云)你兄弟收了者。
(正末云)还有哩。
(唱)更有条蜡打来的这弓弦。','',''),('yuanqu-436','便宜行事虎头牌・慢金盏','李直夫','yuanqu','','','我着这苦口儿说些良言，劝你那酒莫贪，劝你那财休恋。
你可便久镇着南边夹山的那峪前，统领着军健，相持的那地面。
但要你用心儿把守得安然，你可便只愁升，不愁贬。','',''),('yuanqu-437','便宜行事虎头牌・石竹子','李直夫','yuanqu','','','则俺那山寿马侄儿是软善，犯着的休想他便厅见怜。
假若是非当刑死而怨，赤紧的元帅令更狠似帝王宣。','',''),('yuanqu-438','便宜行事虎头牌・大拜门','李直夫','yuanqu','','','我可也不想今朝，常记的往年，到处里追陪下些亲眷。
我也曾吹弹那管弦，快活了万千，可便是大拜门撒敦家的筵宴。','',''),('yuanqu-439','便宜行事虎头牌・山石榴','李直夫','yuanqu','','','往常我便打扮的别，流妆的善，干皂靴鹿皮绵团也似软，那一领家夹袄子是蓝腰线。','',''),('yuanqu-440','便宜行事虎头牌・醉娘子','李直夫','yuanqu','','','则我那珍珠豌豆也似圆，我尚兀自拣择穿。
头巾上砌的粉花儿现，我系的那一条玉兔鹘是余厢面。','',''),('yuanqu-441','便宜行事虎头牌・相公爱','李直夫','yuanqu','','','则我那银盆也似庞儿腻粉钿。
墨锭也似髭须着绒绳儿缠。
对着这官员，亲将那筹箸传，等的个安筵盏初巡遍。','',''),('yuanqu-442','便宜行事虎头牌・不拜门','李直夫','yuanqu','','','则听的这［者刺骨］笛儿悠悠聒耳喧，那驼皮鼓冬冬的似春雷健。
我向这筵前，筵前，我也曾舞蹁跹，舞罢呵谁不把咱来夸羡！。','',''),('yuanqu-443','便宜行事虎头牌・醉也摩娑','李直夫','yuanqu','','','则被你抛闪杀业人也波天，则被你抛闪杀业人也波天。
我无卖也那无典，无吃也那无穿，-年不如一年。','',''),('yuanqu-444','便宜行事虎头牌・月儿弯','李直夫','yuanqu','','','则俺那生忿忏逆的丑生，有人向中都曾见。
伴着火泼男也那泼女，茶房也那洒肆，在那瓦市里穿，几年间再没个信儿传。
有句话舌尖上挑着，我去那喉咙里咽。','',''),('yuanqu-445','救孝子贤母不认尸・仙吕/点绛唇','王仲文','yuanqu','','','家业消乏，拙夫亡化，抛撇下痴小冤家，整受了二十载穷孤寡。','',''),('yuanqu-446','救孝子贤母不认尸・混江龙','王仲文','yuanqu','','','今日个孩儿每成人长大。
我看的似掌中珠，怀内宝，怎做的眼前花？一个学吟诗写字，一个学武剑轮挝，乞求的两个孩儿学成文武艺，一心待货与帝王家。
时坎坷，受波查。
且浇菜，且看瓜，且种麦，且栽麻。
尽他人纷纭甲第厌膏粱，谁知俺贫居陋巷甘粗粝。
今日个茅檐草舍，久以后博的个大纛高牙。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-447','救孝子贤母不认尸・油葫芦','王仲文','yuanqu','','','俺孩儿耕种锄刨怕甚么，那里也有人笑话？想先贤古圣未通达。
(杨谢祖云)母亲，自古以来可是那几个？(正旦唱)有一个伊尹呵，他在莘野中扶犁耙。
有一个傅说呵，他在岩墙下拿锹锸。
(杨谢祖云)这两个都怎生来？(正旦唱)那一个佐中兴事武丁，那一个辅成汤放太甲。
(带云)休说这两个人。
(唱)则他那无名的草木年年发，到春来那一个树无花。','',''),('yuanqu-448','救孝子贤母不认尸・青哥儿','王仲文','yuanqu','','','儿呵，你不索问天、问天买卦，也只为人消、人消的这物化。
弄的我母子分离天一涯。
见孩儿攀鞍跨马，披袍贯甲，臂上刀扎，腰间箭插，就不由俺不扑簌簌泪如麻，情牵挂。','',''),('yuanqu-449','救孝子贤母不认尸・仙吕/赏花时','王仲文','yuanqu','','','可正是目下农忙难离摘，我也几度徘徊无百刂划。
(带云)待不教你去呵，(唱)争奈我许的他明白，等收了蚕麦，直送到庄宅。','',''),('yuanqu-450','救孝子贤母不认尸・幺篇','王仲文','yuanqu','','','依着我皓首苍颜老奶奶，使着你个黄卷青灯的小秀才。
日离了看书斋，小叔叔送嫂嫂也非为分外。
(带云)但送过山坡，望见庄宅，(唱)教他独自去，你便早回来。
(下)。','',''),('yuanqu-451','救孝子贤母不认尸・正宫/端正好','王仲文','yuanqu','','','只我那腹中愁，心头闷，也何如大限临身。
(带云)便好大限临身呵，(唱)合着双眼都不问，今日个这愁闷何时尽？。','',''),('yuanqu-452','救孝子贤母不认尸・滚绣球','王仲文','yuanqu','','','儿呵，咱子母们紧厮跟，索与他打簸箕的寻趁，恨不得播土扬尘。
又无个过往的人，左右的邻，你叫我向着那一搭儿盘问？越寂寂四野无闻。
谩踏践萋萋芳草迷荒径，凝望见，段段田苗接远村。
(带云)媳妇儿呵！(唱)知他那里也安身。','',''),('yuanqu-453','救孝子贤母不认尸・倘秀才','王仲文','yuanqu','','','我也避不得臭气怎闻，觑不的尸虫乱滚。
疑怪这鸦鹊成群，绕定着这座坟。
尸骸虽朽烂，衣袂尚完存，见带着些血痕。','',''),('yuanqu-454','救孝子贤母不认尸・滚绣球','王仲文','yuanqu','','','我这里孜孜的觑个真，悠悠的唬了魂。
(杨谢祖云)母亲，你怕怎么？(正旦唱)儿呵，怎不教你娘心困。
怎生来你这送女客了事的公人！(卜儿云)兀那死了的是我那女孩儿也！(正旦唱)媳妇儿也，你心性儿淳，气格儿温，比着那望夫子石不差分寸。
这的就是您筑坟台包土罗裙。
则这半丘黄土谁埋骨，抵多少一上青山便化身，也枉了你这芳春。
(卜儿云)还说个甚么？我女孩儿现今没了，明有清官。
我和你见官去来！(净扮孤同丑今史，张千、李万冲上)(孤诗云)小官姓巩，诸般不懂，虽然做官，吸利打哄。
小官乃本处推官巩得中是也，一来下乡劝农，二来不见了个梅香，我如令就去寻一寻。
摆开头踏，慢慢的行者。
(卜儿跪下告科，云)好冤屈也！(孤云)你告甚么？(卜儿云)告人命事。
(孤云)外郎，快家去来！他告人命事哩，休累我！(令史云)相公，不妨事，我自有主意。
(孤云)我则依着你。
张千，接了马者。
(令史云)相公下马来，整理这公事，张千，借个桌子来，等相公坐下。
张千，拿过那一起人来、(做拿众跪科)(孤云)外郎也，你不放了屁也？(令史云)不是我。
(孤云)我闻一闻，真个不是你。
哦，元来是那林浪里一个死尸臭。
外郎，你问他，我则不言语。
(令史云)相公且住一边，待我替你问。
兀那婆子，你敢为这尸首告状么？(卜儿云)正是为这个尸首，(令史云)谁是尸亲？(卜儿云)婆子是尸亲。
(令史云)兀那婆子，说你那词因来。
(卜儿云)大人可怜见。
老身乃东军庄人氏，姓王，有个女孩儿是春香。
(令史喝云)噤声！老弟子说词因，两片嘴必溜不刺泻马屁眼也似的，俺这令史有七脚八手？你慢慢的说！(卜儿云)大人可怜见。
老身是东军庄人氏，姓王。
我有个女孩儿，唤做春香，嫁与西军庄杨兴相为妻，就是这婆子的大孩儿。
杨兴祖当军去了，有小叔叔杨谢祖，数番家调戏我这女孩儿，见他不肯，将俺孩儿引到半路里杀坏了，望大人与我做主咱！(令史云)兀那婆子，这尸首是么？(正旦云)这衣服是，尸首不是俺媳妇儿的。
(令史云)怎么这衣服是，尸首不是？你说我是听咱。
(正旦唱)。','',''),('yuanqu-455','救孝子贤母不认尸・倘秀才','王仲文','yuanqu','','','被鸦鹊啄破面门，狼狗咬断脚跟，到底是自己孩儿看的亲。
(孤云)依着我则是打。
(正旦唱)官人休发怒，外郎你莫生嗔，且听咱从长议论。
(令史云)兀那婆子，人命的事，待议论甚么？(正旦唱)。','',''),('yuanqu-456','救孝子贤母不认尸・滚绣球','王仲文','yuanqu','','','人命事，多有假，未必真。
(令史云)我务要问成也。
(正旦唱)要问时，则宜慢，不可紧。
为甚的审缘因再三磨问，也则是恐其中暗昧难分。
(令史云)我是六案都孔目。
(正旦唱)休倚恃你这牙爪威，(令史云)我这管笔，着人死便死。
(正旦唱)休调弄你，这笔力狠。
(令史云)我这枝笔比刀子还快哩。
(正旦唱)你那笔尖儿快如刀刃，杀人呵须再不还魂。
可不道闻钟始觉山藏寺，到岸方知水隔村。
休屈勘平人！。','',''),('yuanqu-457','救孝子贤母不认尸・叨叨令','王仲文','yuanqu','','','这关天的人命事，要您个官司问。
又不曾检验，怎着我尸亲认。
现如今雨淋漓，正值着暑月分。
那尸骸全毁烂，都是些蛆螬粪。
我其实认不得也波哥，我其实认不得也波哥，怎与他那从前模样浑别尽。','',''),('yuanqu-458','救孝子贤母不认尸・三煞','王仲文','yuanqu','','','则合将艳醋儿泼得来匀匀的润，则合将粗纸儿搭得来款款的温。
为甚来行凶？为甚来起衅？是那个主谋？是那个见人？依文案本，遍体通身，洗垢寻痕。
若是初检时不曾审问，怕只怕那再检日怎支分？(令史云)噤声！这婆子好无理也。
我是把法的人，倒要你教我这等这等检尸。
你也晓的，春正夏四，秋九冬十，才是检尸的时分。
如今正是六月天道，雨水也下了几阵，暑气蒸，蛆虫钻，筋骨凋零，眉目难分，爪发解脱，难以检覆。
张千，你去城里唤一个巧笔丹青来，依着这尸首画一个图本，着这婆子画一个字，领将这尸首去烧毁了。
依着这尸伤图本打官司，便与我烧了这尸首者！(正旦云)烧不的！(令史云)怎么烧不的？(正旦唱)。','',''),('yuanqu-459','救孝子贤母不认尸・二煞','王仲文','yuanqu','','','不争将这尸伤彩画成图本，则合把尸状词因依例申。
便做道尸首伤残，爪发难脱，筋骨凋零，眉目难分。
(令史云)可知检不得了也。
我照觑你，只是领那尸首去烧了者。
(正旦云)烧不的，烧不的！(唱)你道是难以检覆，照觑尸亲，许令烧焚。
我只道不如生殡，且留着别冤屈辨清浑。','',''),('yuanqu-460','救孝子贤母不认尸・中吕/粉蝶儿','王仲文','yuanqu','','','不知那天道何如？怎生个善人家有这场点污！人命事不比其余，若是没清官，无良吏，教我对谁分诉？早是俺活计消疏，更打着这非钱儿不行的时务。','',''),('yuanqu-461','救孝子贤母不认尸・醉春风','王仲文','yuanqu','','','天那！这冤枉儿时伸，忧愁甚日楚？但留的俺这雪霜也似白头颅。
儿也，倒大来是福、福，只索打会官司，吃会痛苦，受会耻辱。','',''),('yuanqu-462','救孝子贤母不认尸・迎仙客','王仲文','yuanqu','','','怕不要倩外人，那里取工夫？正农忙百般无事处，因此上教小孩儿莫违阻，您娘亲面嘱付，送嫂嫂到一半路程，便回来，着他自家去。
(令史云)这小厮和那嫂嫂敢不和么？(正旦唱)。','',''),('yuanqu-463','救孝子贤母不认尸・红绣鞋','王仲文','yuanqu','','','他叔嫂从来和睦。
(令史云)你这婆子替儿嫌妇那？(正旦唱)俺姑媳又没甚伤触。
(令史云)一定是这小厮发意生情，杀了他嫂嫂也。
(正旦唱)若说他发意生情，半星也无。
(带云)大人啊，(唱)您揣明镜，悬秋月，照肝胆，察实虚，与俺那平人每好生做主。','',''),('yuanqu-464','救孝子贤母不认尸・普天乐','王仲文','yuanqu','','','受摧残，遭凌辱，这无情的棍棒，俺孩儿是有限的身躯。
(祗候做唤科，云)杨谢祖苏醒着！(正旦唱)你看么，揪头发将名姓呼，喷冷水将形容来污。
打的来应心疼痛处，怎不教我放声啼哭。
常言道做着不避，避着不做，(正旦做打闪过跪科，唱)我可便死待何如？。','',''),('yuanqu-465','包待制智赚生金阁・仙吕/赏花时','武汉臣','yuanqu','','','一来我应举京师赴选场，二来我为远去他乡躲祸殃，(卜儿云)孩儿也，俺子母每今日别去，不知何日相见？到得京师，你则着志者。
(正末唱)就拜辞了老爹娘。
非是您孩儿自夸得这自奖，我若是不富贵，可兀的不还乡。','',''),('yuanqu-466','包待制智赚生金阁・仙吕/点绛唇','武汉臣','yuanqu','','','则我这口内嗟吁，腹中忧虑。
离家去，可又早一月多余，则我这白发添无数。
(旦云儿)秀才，想古来也有未遇的人，这般受苦么？(正末唱)。','',''),('yuanqu-467','包待制智赚生金阁・混江龙','武汉臣','yuanqu','','','想前贤不遇，我便似阮嗣宗恸哭在穷途。
早知道这般的担惊受恐，我可也图甚么衣紫拖朱？每日慵将书去习，逐朝常把药的那来扶。
我这刚移足趾，强整身躯，滑七擦争些跌倒，战笃速恁艰虞。
天也，我如今整三十，可着我半路里学那步？(旦云儿)秀才，你挣坐些着。
(正末唱)但只见黑漫漫同云黯淡，白茫茫瑞雪模糊。','',''),('yuanqu-468','包待制智赚生金阁・天下乐','武汉臣','yuanqu','','','想刺股悬头去读书，则我这当也波初，自窨付，怕不的满胸中藏他万卷余。
又不曾上春官显姓名，又不曾向皇家请俸禄，哎，也干着了忍三冬受尽苦。','',''),('yuanqu-469','包待制智赚生金阁・金盏儿','武汉臣','yuanqu','','','我则见他人马闹喧呼，这人物不寻俗。
一群价飞鹰走犬相随逐，都是些貂裘暖帽锦衣服。
虽不见门排十二戟，户列入椒图，你觑那金牌上悬铜虎，玉带上挂银鱼。','',''),('yuanqu-470','包待制智赚生金阁・醉扶归','武汉臣','yuanqu','','','小生呵，家住在河中府。
(衙内云)曾学甚么武艺来？(正末唱)幼年间读几行圣贤书。
(衙内云)这等，你可怎么不做官？(正末唱)则为我运拙时乖天不与，(衙内云)可知则是一个穷秀才。
(正末唱)甘分守穷活路。
(衙内云)你家里有甚么人？(正末唱)拜辞了年高的父母，(衙内云)你如今往那里去？(正末云)我一径的取应往梁园去。','',''),('yuanqu-471','包待制智赚生金阁・金盏儿','武汉臣','yuanqu','','','听小生说从初，(衙内云)可也端的少有。
(正末唱)这宝贝世间无，(衙内云)你可那里得来？(正末唱)俺家里祖传三辈牢收取。
(衙内云)你可要多少钱钞？(正末唱)我也不求厚赂，但遂意，便沽诸。
(衙内云)我与你些绫罗段匹换的么？(正末唱)也不要绫罗段匹，(衙内云)与你些宝贝金珠可好？(正末唱)也不要宝贝共金珠。
(衙内云)你都不要，可要些甚么？(正末唱)小生只博个小前程来帝里，便也好将名分入乡闾。','',''),('yuanqu-472','包待制智赚生金阁・赚煞','武汉臣','yuanqu','','','罢、罢、罢，怎干休，难分诉，世做的冯河暴虎，赤紧的先要了我这希奇无价物，又生出百计亏图。
哎，你个泼无徒，胆大心粗。
俺夫妻每负屈衔冤谁做主？你强夺了花枝媳妇，又将咱性命屠毒，(带云)哎，早知今日，我不带的浑家出来也罢。
(唱)方知道"美女累其夫"。
(下)。','',''),('yuanqu-473','包待制智赚生金阁・紫花儿序','武汉臣','yuanqu','','','早辰间放开仓库，晌午里绰扫了花园，末傍晚我又索执料厨房。
小丫鬟忙来呼唤，道衙内共我商量。
岂敢行唐？大走向庭前去问当。
(正旦做见衙内科)(唱)哥哥，你有何明降？对老身至尾从头，说短论长。','',''),('yuanqu-474','包待制智赚生金阁・小桃红','武汉臣','yuanqu','','','老身非敢自夸强，我不比那蒯通无名望。
(衙内云)我礼拜磕头，央及你波。
(衙内做拜科)(正旦唱)呀、呀、呀，何须的礼拜磕头把咱央？(衙内云)好奶奶，没奈何，好生劝他一劝。
(正旦唱)直恁般痛着忙，就待要安排共宿芙容帐。
凭着我甜话儿厮搪，更将些美情儿相向。
哥哥也，你稳情取金殿锁鸳鸯。
(同下)。','',''),('yuanqu-475','包待制智赚生金阁・凭栏人','武汉臣','yuanqu','','','则这女聘男婚礼正当。
你两下和谐可着人赞扬，哎，你个女艳妆，你心中可怎不思想？(旦儿云)嬷嬷，你怎知道？我那里是大财大礼娶的？我本是郭成的浑家，有庞衙内强要了我生金阁儿，又逼我为妻，将俺丈夫锁在马房里。
嬷嬷？你可知道我这等冤枉也！(正旦云)你若不说，我怎生得知？难道有这等事？(唱)。','',''),('yuanqu-476','包待制智赚生金阁・鬼三台','武汉臣','yuanqu','','','听的他言分朗，唬的我魂飘荡。
姐姐也，你怎生则撞入天罗地网？俺那厮驴狗儿一片家狠心肠，有谁人好来阻当？(旦儿云)嬷嬷，我今日不曾看见丈夫，多敢杀坏了。
兀的不痛杀我也。
(正旦唱)你道他昨来个那埚儿里杀坏了范杞梁，今日个这埚儿里没乱杀你女孟姜。
(旦儿云)嬷嬷，我待要寻一个大大的衙门，告他去哩！(正旦唱)你侍要叫屈声冤，姐姐也，谁敢便收词接状？。','',''),('yuanqu-477','包待制智赚生金阁・寨儿令','武汉臣','yuanqu','','','我见他痛感伤，泪汪汪，(旦儿云)当初只为我生的风流，长的可喜，将我男儿陷害了性命，挝了我这面皮罢。
(正旦云)哎哟，可惜了也。
(唱)水晶般指甲儿挝破面上。
(衙内同随从做听科)(正旦唱)俺那厮少不的落马身足庄。
不久沦亡，他可便遭贼盗值重丧。','',''),('yuanqu-478','包待制智赚生金阁・幺篇','武汉臣','yuanqu','','','多不到半月时光。
餐刀刃亲赴云阳，高杆首吊脊梁，木驴上碎分张，浑身的害么娘碗大血疔疮。','',''),('yuanqu-479','包待制智赚生金阁・金蕉叶','武汉臣','yuanqu','','','是谁人村声泼嗓？他壁听在门儿外厢。
(旦儿做惊科，云)嬷嬷，窗儿外有人咳嗽。
(正旦唱)姐姐也，你且休慌心劳意攘，我可便自把那言词说上。','',''),('yuanqu-480','包待制智赚生金阁・调笑令','武汉臣','yuanqu','','','息怒波宰相，听老身说行藏。
(衙内云)你还说甚的？可敢再骂我么？(正旦云)哥哥，我不曾说甚来？(唱)我道是楚襄王寄语巫山窈窕娘，也不须遮遮掩掩妆模样，早共晚准备下雨席云床。
(衙内云)你道不骂我，恰才我都听的了也。
(正旦唱)我道您哥哥也，在城中第一家财帛广，还有那鸦飞不过的田地池塘。','',''),('yuanqu-481','包待制智赚生金阁・梁州第七','武汉臣','yuanqu','','','我也则为那万般愁常萦心上，两条恨不去眉梢，急回身又遇着新春到。
我只见寒梅晚谢，冻雪初消。
傍几家儿村鸡哑哑，隔半程儿野犬口牢口牢。
妆点来则恁的景物萧条，可不道有丹青也便巧笔难描。
我、我、我，看了些青渗渗峻岭层峦，是、是、是，行了些黄穰穰沙堤得这古道，呀、呀、呀，兀良，早过了些碧澄澄野水横桥。
归来路杳，袅丝鞭羡杀投林鸟。
薄暮也，在荒郊，怎当这疲马西风雪正飘，说不尽寂寥。','',''),('yuanqu-482','包待制智赚生金阁・贺新郎','武汉臣','yuanqu','','','他那里擎杯举酒对天浇，现如今五谷丰登，万民安乐，卖弄池田蚕十倍收成了。
说不尽庄家，庄家这好，还待要薄税轻徭。
他道官长每如卓鲁，令史每压萧曹，高眠莫被闲愁搅。
似这等人心无压足厌则怕天也填不的许多凹。','',''),('yuanqu-483','包待制智赚生金阁・牧羊关','武汉臣','yuanqu','','','他那里才言罢，唬的我魂暗消。
离城中则半载其高，可怎么白日神嚎，到黄昏鬼闹。
我半生多正直，怎见这蹊跷？只今的离村疃犹然早，(云)张千，将马来。
(张千云)理会的。
(正末唱)我和你到皇都赴晚朝。','',''),('yuanqu-484','包待制智赚生金阁・哭皇天','武汉臣','yuanqu','','','则你那"催动坑"刚才道，可怎生这公事便妆幺？则你那口是祸之苗，(娄青做打脸科，云)你怎么多嘴？(正末唱)舌是斩身刀。
(带云)娄青，(唱)你与我去城隍根前祝祷，(娄青云)爷着孩儿祝祷甚的？(正末唱)你说与那衔冤的业鬼，屈死的冤魂，你着他今宵插状，此夜呈词。
你道这包龙图专在南衙里，南衙里等待着，(娄青云)您孩儿知道了，便勾去。
(正末云)娄青你转来，天色还早哩。
(娄青云)这等多早晚去？(正末唱)直等的金乌向山坠，银蟾出海角。
(娄青云)您孩儿便依着爷的言语，对城隍神道祝祷了。
他两个耳朵是泥塑的，怕不听见？(正末云)娄青，我与你一道牒文去。
(唱)。','',''),('yuanqu-485','中吕・满庭芳','姚燧','yuanqu','','','天风海涛，昔人曾此，酒圣诗豪。
我到此闲登眺，日远天高。
山接水茫茫渺渺，水连天隐隐迢迢。
供吟笑，功名事了，不待老僧招。
帆收钓浦，烟笼浅沙，水满平湖。
晚来尽滩头聚，笑语相呼。
鱼有剩和烟旋煮，酒无多带月须沽。
盘中物，山肴野蔌，且尽葫芦。','',''),('yuanqu-486','中吕・普天乐','姚燧','yuanqu','','','浙江秋，吴山夜，愁随潮去，恨与山叠。
塞雁来，芙蓉谢，冷雨青灯读书舍，待离别怎忍离别？今宵醉也，明朝去也，宁奈些些！。','',''),('yuanqu-487','中吕・醉高歌感怀','姚燧','yuanqu','','','十年燕月歌声，几点吴霜鬓影。
西风吹起鲈鱼兴，已在桑榆暮景。
荣枯枕上三更，傀儡场头四并。
人生幻化如泡影，那个临危自省？岸边烟柳苍苍，江上寒波漾漾。
阳关旧曲低低唱，只恐行人断肠。
十年旧剑长吁，一曲琵琶暗许。
月明江上别湓浦，愁听兰舟夜雨。','',''),('yuanqu-488','中吕・阳春曲','姚燧','yuanqu','','','墨磨北海乌龙角，笔蘸南山紫兔毫。
花笺铺展砚台高，诗气豪，凭换紫罗袍！石榴子露颜回齿，菡萏花含月女姿。
不知张敞画眉时，甚意思，墨点了那些儿。
金鱼玉带罗袍就，皂盖朱幡赛五侯。
山河判断笔尖头，得志秋，分破帝王忧。
笔头风月时时过，眼底儿曹渐渐多。
有人问我事如何？人海阔，无日不风波。','',''),('yuanqu-489','越调・凭阑人','姚燧','yuanqu','','','博带峨冠年少郎，高髻云鬟窈窕娘。
我文章你艳妆，你一斤咱十六两。
马上墙头瞥见他，眼角眉尖拖逗咱。
论文章他爱咱，睹妖娆咱爱他。
织就回文停玉梭，独守银灯思念他。
梦儿里休呵，觉来时愁越多。
宫髻高盘铺绿云，仙袂轻飘兰麝薰。
粉香罗帕新，未曾淹泪痕。
羞对鸾台梳绿云，两叶春山眉黛颦。
强将脂粉匀，几回填泪痕。
寄与多情王子高，今夜佳期休误了。
等夫人熟睡着，悄声儿窗外敲。
两处相思无计留，君上孤舟妾倚楼。
这些兰叶舟，怎装如许愁。
寄征衣欲寄君衣君不还，不寄君衣君又寒。
寄与不寄间，妾身千万难！。','',''),('yuanqu-490','双调・蟾宫曲','姚燧','yuanqu','','','博山铜细袅香风，两行纱笼，烛影摇红。
翠袖殷勤捧金钟，半露春葱。
唱好是会受用文章巨公，绮罗丛醉眼朦胧。
夜宴将终，十二帘栊，月转梧桐。','',''),('yuanqu-491','双调・寿阳曲','姚燧','yuanqu','','','酒可红双颊，愁能白二毛，对樽前尽可开怀χ。
天若有情天亦老，且休教少年知道。
红颜褪，绿鬓凋，酒席上渐疏了欢笑。
风流近来都忘了，谁信道也曾年少？襄王梦，神女情，多般儿酿成愁病。
琵琶慢调弦上声，相思字越弹着不应。
咏李白贵妃亲擎砚，力士与脱靴，御调羹就飧不谢。
醉模糊将吓蛮书便写，写着甚杨柳岸晓风残月。','',''),('yuanqu-492','双调・拨不断四景','姚燧','yuanqu','','','草萋萋，日迟迟，王孙士女春游戏。
宫殿风微燕雀飞，池塘沙暖鸳鸯睡，正值着养花天气。
芰荷香，露华凉，若耶溪上莲舟放。
岸上谁家白面郎，舟中越女红裙唱，逞娇羞模样。
楚天秋，好追游，龙山风物全依旧。
破帽多情却恋头，白衣有意能携酒，好风流重九。
雪漫漫，拥蓝关，长安远客心偏惮。
瀹玉瓯中冰雪寒，销金帐里羊羔镟，这两般任拣。','',''),('yuanqu-493','幺・笑停云老子人豪，过信少陵诗语。更何消斫桂婆婆，早已有吴刚挥斧。','姚燧','yuanqu','','','套数。','',''),('yuanqu-494','双调・新水令冬怨','姚燧','yuanqu','','','梅花一夜漏春工，隔纱窗暗香时送。
篆消金睡鸭，帘卷绣蟠龙。
去凤声中，又题觉半衾梦。','',''),('yuanqu-495','驻马听・心事匆匆，斜倚云屏愁万钟。襟怀冗冗，半欹鸳枕恨千重。金钗','姚燧','yuanqu','','','剪烛晓犹红，胆瓶盛水寒偏冻。
冷清清，掩流苏帐暖和谁共？。','',''),('yuanqu-496','得胜令・书信寄封封，烟水隔重重。夜月巴陵下，秋风渭水东。相逢，枕','姚燧','yuanqu','','','上欢娱梦。
飘蓬，天涯怅望中。','',''),('yuanqu-497','沽美酒・龙涛倾白玉钟，羊羔泛紫金觥，兽炭添煤火正红。业身躯自拥，','姚燧','yuanqu','','','听门外雪花风。','',''),('yuanqu-498','太平令・悔当日东墙窥宋，有心教夫婿乘龙。见如今天寒地冻，知他共何','姚燧','yuanqu','','','人陪奉？想这厮指空、话空、脱空，巧舌头将人搬弄。','',''),('yuanqu-499','水仙子・朔风掀倒楚王宫，冻雨埋藏神女峰，雪雹打碎桃源洞。冷丁丁总','姚燧','yuanqu','','','是空，簌湘帘翠霭重重。
写幽恨题残春扇，敲郁闷听绝暮钟，数归期曲损春葱。','',''),('yuanqu-500','尾声・这冤仇怀恨千钧重，见时节心头气拥。想盼的我肠断眼睛儿穿，直','姚燧','yuanqu','','','掴的他腮颊脸儿肿！。','',''),('yuanqu-501','黄钟・节节高题洞庭鹿角庙壁','卢挚','yuanqu','','','雨晴云散，满江明月。
风微浪息，扁舟一叶。
半夜心，三生梦，万里别，闷倚篷窗睡些。','',''),('yuanqu-502','正宫・黑漆弩','卢挚','yuanqu','','','晚泊采石，醉歌田不伐。','',''),('yuanqu-503','黑漆弩・，因次其韵，寄蒋长卿佥司、刘芜湖巨川。','卢挚','yuanqu','','','湘南长忆嵩南住，只怕失约了巢父。
舣归舟唤醒湖光，听我篷窗春雨。
故人倾倒襟期，我亦载愁东去。
记朝来黯别江滨，又弭棹蛾眉晚处。','',''),('yuanqu-504','南吕・金字经嵩南秋晚','卢挚','yuanqu','','','谢公东山卧，有时携妓游，老我嵩南画满楼。
楼外头，乱峰云锦秋。
谁为寿，绿鬟双玉舟。
宿邯郸驿梦中邯郸道，又来走这遭，须不是山人索价高。
时自嘲，虚名无处逃。
谁惊觉，晓霜侵鬓毛。','',''),('yuanqu-505','中吕・普天乐湘阳道中','卢挚','yuanqu','','','岳阳来，湘阳路。
望炊烟田舍，掩映沟渠。
山远近，云来去。
溪上招提烟中树，看时见三两樵渔。
凭谁画出，行人得句，不用前驱。','',''),('yuanqu-506','商调・梧叶儿赠歌妓','卢挚','yuanqu','','','红绡皱，眉黛愁，明艳信清秋。
文章守，令素侯，最风流，送花与疏斋病叟。
席间戏作四章花间坐，竹外歌，颦翠黛转秋波。
你自在空踌躇，我如何肯恁么，却又可信着他，没倒断痴心儿为我。
低声语，娇唱歌，韵远更情多。
筵席上，疑怪他，怎生呵，眼挫里频频地觑我。
新来瘦，忒闷过，非酒病为诗魔。
纤腰舞，皓齿歌，便俏些个，待有甚风流罪过。
全不见白髭鬓，才四十整，有家珍无半点儿心肠硬。
醇一味，庞道儿，□锦片也似好前程，到健如青春后生。
邯郸道，不再游，豪气傲王侯。
琴三弄，酒数瓯，醉时休，缄口抽头袖手。
平安过，无事居，金紫待何如？低檐屋，粗布裾，黍禾熟，是我平生愿足。','',''),('yuanqu-507','越调・小桃红','卢挚','yuanqu','','','寿筵添上小桃红，妆点壶天供，茜蕊冰痕半浮动。
彩云中，生香唤醒罗浮梦。
银杯绿蚁，琼枝清唱，金胜醉鳌峰。','',''),('yuanqu-508','双调・寿阳曲','卢挚','yuanqu','','','银台烛，金兽烟，夜方阑画堂开宴。
管弦停玉杯斟较浅，听春风遏云歌遍。
金蕉叶，银萼花，卷长江酒杯低亚。
醉书生且休扶上马，听春风玉箫吹罢。
诗难咏，画怎描，欠渔翁玉蓑独钓。
低唱浅斟金帐晓，胜烹茶党家风调。
攒江酒，味转佳，刻春宵古今无价。
约寻盟绿杨中闲系马，醉春风碧纱窗下。
别珠帘秀才欢悦，早间别，痛煞煞好难割舍！画船儿载将春去也，空留下半江明月。
夜忆窗间月，檐外铁，这凄凉对谁分说？剔银灯欲将心事写，长吁气把灯吹灭！灯将残，人睡也，空留得半窗明月。
孤眠心硬熬浑似铁，这凄凉怎捱今夜？灯将灭，人睡些，照离愁半窗残月。
多情直恁的心似铁，辜负了好天良夜。
灯下词，寄与伊，都道是二人心事。
是必你来会一遭儿，抵多少梦中景致。','',''),('yuanqu-509','双调・湘妃怨西湖','卢挚','yuanqu','','','湖山佳处那些儿，恰到轻寒微雨时。
东风懒倦催春事，嗔垂杨袅绿丝，海棠花偷抹胭脂。
任吴岫眉尖恨，厌钱塘江上词，是个妒色的西施。
朱帘画舫那人儿，林影荷香雨霁时。
樽前歌舞多才思，紫云英琼树枝，对波光山色参差。
切香脆江瑶脍，擘轻红新荔枝，是个好客的西施。
苏堤鞭影半痕儿，常记吴山月上时。
闲寻灵鹫西岩寺，冷泉亭偏费诗，看烟鬟尘外丰姿。
染绛绡裁霜叶，酿清香飘桂子，是个百巧的西施。
梅梢雪霁月芽儿，点破湖烟雪落时。
朝来亭树琼瑶似，笑渔蓑学鹭鸶，照歌台玉镜冰姿。
谁亻孱亻愁鸱夷子，也新添两鬓丝，是个淡净的西施。','',''),('yuanqu-510','同乐院燕青博鱼・幺篇','李文蔚','yuanqu','','','罢波，我枉舍了火也似热热的一丹心，早没了我镜也似朗朗的双明目，可着谁养赡我这七尺之躯。
想弟兄每虎据了山东路，则捻了个不出力的燕青去。
(下)。','',''),('yuanqu-511','同乐院燕青博鱼・大石调/六国朝','李文蔚','yuanqu','','','我揣巴些残汤剩水，打叠起浪酒闲茶，我着些气呵暖我这冻拳头，再着些唾揩光我这冷鼻凹。
瘦的来我这身子儿没个麻秸大，兀的不消磨了我剌绣的青黛和这朱砂。
眼见的穷活路觅不出衣和饭，怕不道酷寒亭把我来冻饿杀。
全不见那昏惨惨云遮了银汉，则听的淅零零雪糁琼沙，我、我、我待踮着个鞋底儿去拣那浅中行，先绰的这棒头来向深处插。','',''),('yuanqu-512','同乐院燕青博鱼・喜秋风','李文蔚','yuanqu','','','我与你便吖吖叫，我与你便磨磨擦。
我为甚将这脚尖儿细细踏？我怕只怕这路儿有些步步滑。
(带云)似我这模样，像个甚的？(唱)将那前街后巷我便如盘卦，刚才个渐渐里呵的我这手温和，可又早切切里冻的我这脚麻辣。','',''),('yuanqu-513','同乐院燕青博鱼・归塞北','李文蔚','yuanqu','','','天那！您不肯道是相赍发，专与俺这穷汉做冤家。
这雪呵，他如柳絮不添我身上絮，似梨花却变做了眼前花，则我这拄杖冻难拿。
(带云)有那等人道："兀的君子，那东京城里有的是买卖营生，你寻些做可不好那？"我道哥也，你岂知我无眼那？他便道："寻你那无眼营生去做。
"哥也，您那里知道咱。
(唱)。','',''),('yuanqu-514','同乐院燕青博鱼・憨货郎','李文蔚','yuanqu','','','莫不是千化身观音菩萨，救了我这双无目沿街的叫化。
他道是妙手通灵，圣心无假。
哥也，多谢你个良医肯把金针下，我又没甚的米麦丝麻，哥也，你则可怜见我这穷汉瞎。','',''),('yuanqu-515','同乐院燕青博鱼・归塞北','李文蔚','yuanqu','','','他把我眼角儿才针罢，则我这疮口儿未结痂。
早将我两只手揉开了这一对眼，(带云)是好手段也！(唱)则当一枚外挑去了一重沙，恰便似日日退残霞。','',''),('yuanqu-516','同乐院燕青博鱼・初问口','李文蔚','yuanqu','','','俺也曾那草坡前把滥官拿，则俺那梁山泊上宋江，须不比那帮源洞里的方腊。
