从今日拜辞了主人家，绰着这过眼齐眉的枣子棍，依旧到杀人放火蓼儿洼，须认的俺狠那吒。','',''),('yuanqu-517','同乐院燕青博鱼・尾声','李文蔚','yuanqu','','','你道是他打了我呵似房檐上揭瓦，不信道我打了他呵就着我这脖项上披枷。
调动我这莽拳头，拓动我这长捎靶，我向那前街后巷便去爪寻他。
(带云)若见了他呵，(唱)我一只手揪住那厮黄头发，一只手把腰脚牢掐，我可敢滴溜扑活撺那厮在马直下。
(下)。','',''),('yuanqu-518','同乐院燕青博鱼・仙吕/点绛唇','李文蔚','yuanqu','','','刚留的我这没影孤身，借人资本，为营运。
避不得艰辛，则要这两家"衣食"准。','',''),('yuanqu-519','同乐院燕青博鱼・混江龙','李文蔚','yuanqu','','','可怜咱十分贫窘，恰才那打鱼人赊与俺这卖鱼人。
凭着我六文家铜馒，博的是这三尺金鳞。
鱼也你在荷叶盘中犹跌尾，怎不想桃花浪里一翻身。
我去那新红盒子内，拿着这常占胜，不占输，只愁富，不愁穷，明丢丢的几个头钱问。
钱那！若是告一场响豁，便是我半路里落的这殷勤。','',''),('yuanqu-520','同乐院燕青博鱼・那吒令','李文蔚','yuanqu','','','这鱼呵，重七斤八斤，你若是博呵，要五纯六纯，着小人呵，也觅一文半文。
(带云)主人家有么？(唱)快与我抹下浅盆，磨下刀刃你看我雪片也似批鳞。','',''),('yuanqu-521','同乐院燕青博鱼・金盏儿','李文蔚','yuanqu','','','比及问五陵人，先顶礼二郎神，哥也，你便博一千博，我这胳膊也无些儿困。
我将那竹根的绳拂子绰了这地皮尘，(云)哥也，老实的博。
(燕大云)我只是博耍子，有甚么老实不老实？(正末唱)不要你蹲着腰虚土里纵，叠着指漫砖上墩；则要你平着身往下撇，不要你探着手可便往前分。','',''),('yuanqu-522','同乐院燕青博鱼・油葫芦','李文蔚','yuanqu','','','则这新染来的头钱不甚昏，可不算选的准，手心里明明白白摆定一文文。
(燕大做博科，云)我博了六个镘儿，我赢了也。
(正末唱)呀呀呀，我则见五个镘儿乞丢磕塔稳，更和一个字儿急留骨碌滚。
唬的我咬定下唇，掐定指纹，又被这个不防头爱撇的砖儿稳，可是他便一博六浑纯。','',''),('yuanqu-523','同乐院燕青博鱼・金盏儿','李文蔚','yuanqu','','','我这里抢起折支巾，拽起夜叉裙，(杨衙内做见搽旦科，云)姐姐休怪，我来迟了也。
(正末做扳杨衙内科，云)哥也，唱着喏去！(做打杨衙内科)(杨衙内打筋斗科)(正末唱)拳着处早可扑的精砖上盹。
(燕大云)你打死他了也。
(正末云)哥，你休怕者。
(唱)看那厮眼朦胧正着昏，我将这大拇指去那厮人中里掐。
(带云)主人家有水将的些来。
(唱)新汲水那厮面皮上喷。
(杨衙内做叹气科)(正末云)哥也，他不死哩。
(唱)那厮热拖拖的才出气，(杨衙内舒身科)(燕大云)他早翻过身哩。
(正末云)他怎么肯死？(唱)那厮他跌躞躞的恰还魂。','',''),('yuanqu-524','同乐院燕青博鱼・赚煞尾','李文蔚','yuanqu','','','你看这鬏髻上扭的出那棘针油，面皮上刮的下那桃花粉，只这两棒儿管做了你个哥哥的祸根。
穿着些素淡衣服越风韵，兀的不是天生成玉软香温。
我见他扭回身，抖擞下精神，则被他那眼角眉尖断送了春。
(正末做打耳喑科，云)哥也，可是这般。
(燕大云)我知道了也。
(正末唱)我恰才舌贴着你那耳轮，敢可也一言难尽，哎，哥也你是个好男儿休戴着这一顶屎头巾。
(下)。','',''),('yuanqu-525','同乐院燕青博鱼・中吕/粉蝶儿','李文蔚','yuanqu','','','鼓打初更，是谁人推出这一轮明镜，原来是配金乌那兔魄东生。
这早晚玉绳高，银河浅，恰正是夜阑人静。
端的这月白风清。
我则见滴溜溜倒垂着斗柄。','',''),('yuanqu-526','同乐院燕青博鱼・叫声','李文蔚','yuanqu','','','我恰才便横饮到两三巡，灌得我来酩酊、酩酊，犹未醒，(带云)怪道我这脚趔趄站不定呵，(唱)原来那一盏盏都是瓮头甭。','',''),('yuanqu-527','同乐院燕青博鱼・醉春风','李文蔚','yuanqu','','','我铺的这艾呀纹藤席净。
