(带云)我是听这上衙更鼓咱。
(做打二鼓科)(唱)。','',''),('yuanqu-528','同乐院燕青博鱼・倘秀才','李文蔚','yuanqu','','','鼓打到一更也那二更，犬吠到三声也那四声。
