咱两个打着个暗号：赤、赤、赤！(杨衙内搽旦做跳过正末身科)(正末唱)我这里呵欠罢翻身打个呓挣，(搽旦云)赤、赤、赤！(杨衙内云)赤、赤、赤！(正末唱)蓦见那女娉婷引着个后生。','',''),('yuanqu-529','同乐院燕青博鱼・叫声','李文蔚','yuanqu','','','眼见的八九分是奸情，是谁家鬼精、鬼精，做出这乔行径？(搽旦云)穿的那衣服，拖天扫地的，一脚踹着，不险些儿绊倒了？捋起衣服来，走、走，赤、赤、赤！(杨衙内云)赤、赤、赤！(正末唱)怎知道黑影里偏撞着俺这泼燕青。','',''),('yuanqu-530','仙吕・一半儿题情','王和卿','yuanqu','','','鸦翎般水鬓似刀裁，小颗颗芙蓉花额儿窄，待不梳妆怕娘左猜。
