搽-个红颊腮似赤马猴，舒着双黑爪老似通臂猿，抱着面紫檀槽弹不的昭君怨，凤凰箫吹不出鹧鸪天。','',''),('yuanqu-546','玉箫女两世姻缘・天下乐','乔吉','yuanqu','','','哎，也算做闷向秦楼列管弦，(带云)到那三杯酒后呵，(唱)觑不的那抓掀。
鬏髻偏，便似那披荷叶搭刺着个褐袖肩。
