藕池中锯折并头莲，泥窝里掏杀双飞燕。','',''),('yuanqu-550','玉箫女两世姻缘・得胜乐','乔吉','yuanqu','','','将罗袖卷，香醪劝，请学士官人稳便，这的是酿清泉朝来新镟，直吃的金盏里倒垂莲。
(卜儿上，打咳嗽科)(正旦唱)。','',''),('yuanqu-551','玉箫女两世姻缘・后庭花','乔吉','yuanqu','','','今日在汴河边倚画船，明日在天津桥闻杜鹃。
最苦是相思病，极高的离恨天，空教我泪涟涟。
