苦恹恹恨怎言？急煎煎情惨然。','',''),('yuanqu-552','玉箫女两世姻缘・青歌儿','乔吉','yuanqu','','','天那！人在这离亭、离亭开宴，酒和愁怎生、怎生吞咽？狠毒娘下的也么天！情绪绵绵。
想柳畔花边，月下星前，共枕同眠，携手凭肩。
离暮雨亭轩，望落日山川，问雕鞍何日是归年？俺和你重相见。','',''),('yuanqu-553','玉箫女两世姻缘・赚煞','乔吉','yuanqu','','','眼见的天阔雁书迟，赤紧的日近长安远，则怕我受官诰的缘薄分浅，则愿的一举成名在日边。
(带云)你寄音书呵，(唱)休爱惜象管鸾笺。
(末云)大姐，屈着指头儿数，不出三年，我便来也。
(正旦唱)则愿的早三年，人月团圆，休教妾常倚东风泣断弦。
你休恋京师帝辇，别求夫人宅眷，把咱好姻缘翻做了恶姻缘。
(下)。','',''),('yuanqu-554','玉箫女两世姻缘・商调/集贤宾','乔吉','yuanqu','','','隔纱窗日高花弄影，听何处啭流莺。
虚飘飘半衾幽梦，困腾腾一枕春酲。
趁着那游丝儿恰飞过竹坞桃溪，随着这蝴蝶儿又来到月榭风亭。
觉来时倚着这翠云十二屏，恍惚似坠露飞萤。
多咱是寸肠千万结，只落的长叹两三声！。','',''),('yuanqu-555','玉箫女两世姻缘・逍遥乐','乔吉','yuanqu','','','犹古自身心不定，倚遍危楼，望不见长安帝京。
何处也，薄情，多应恋金屋银屏。
想则想于咱不志诚，空说于碜磕磕海誓山盟。
赤紧的关河又远，岁月如流，鱼雁无凭。','',''),('yuanqu-556','玉箫女两世姻缘・尚京马','乔吉','yuanqu','','','我觑不的雁行弦断卧瑶筝，风嘴声残冷玉笙，兽面香消闲翠鼎。
门半掩悄悄冥冥，断肠人和泪梦初醒。','',''),('yuanqu-557','玉箫女两世姻缘・梧叶儿','乔吉','yuanqu','','','火燎也似身躯热，锥剜也似额角疼，即渐里瘦子身形。
这几日茶饭上不待吃，睡卧又不甚宁。
(卜儿云)我请医者看看你这脉息，知他是甚么症候。
(正旦唱)若将这脉来凭，多管是废寝忘餐病症。
(卜儿云)梅香，好生伏事您姐姐，我下边看些汤药来。
(虚下)(梅香云)姐姐，你怎么这等想俺姐夫？(正旦云)我实瞒不的你，据着他那人物才学，如何教我不想也！(唱)。','',''),('yuanqu-558','玉箫女两世姻缘・醋葫芦','乔吉','yuanqu','','','看了他容貌儿实是撑，衣冠儿别样整，更风流、更洒落、更聪明。
唱一篇小曲儿宫调清，一团儿软款温柔情性，兀的不坑下人性命、引了人魂灵！。','',''),('yuanqu-559','玉箫女两世姻缘・金菊香','乔吉','yuanqu','','','想着他锦心绣腹那才能，怎教我月下花前不动情！信口里小曲儿编捏成，端的足剪雪裁冰，惺惺的自古惜惺惺。','',''),('yuanqu-560','玉箫女两世姻缘・浪里来','乔吉','yuanqu','','','假若我乍吹箫别院声，他便眼巴巴帘下等，自等到星移斗转二三更。
入门来画堂春自生，紧紧的将咱搂定，那温存、那将惜、那劳承！(带云)解元呵，想起你那般风韵，害杀我也！(唱)。','',''),('yuanqu-561','玉箫女两世姻缘・后庭花','乔吉','yuanqu','','','想着他和蔷薇花露清，点胭脂红蜡冷，整花朵心偏耐，画蛾眉手惯经，梳说罢将玉肩凭，恰似对鸳鸯交颈。
到如今玉叽骨减了九停，粉香消没了半星，空凝盼秋水横，甚情将云鬓整。
骨岩岩瘦不胜，闷恹恹扮不成。','',''),('yuanqu-562','玉箫女两世姻缘・金菊香','乔吉','yuanqu','','','怕不待儿番落笔强施呈，争奈一段伤心画不能。
腮斗上泪痕粉渍定，没颜色鬓乱钗横，和我这眼皮眉黛欠分明。','',''),('yuanqu-563','晋陶母剪发待宾・仙吕/点绛唇','秦简夫','yuanqu','','','夫主归天，老身发愿。
将豚犬，严教了十年，下苦志习经典。','',''),('yuanqu-564','晋陶母剪发待宾・混江龙','秦简夫','yuanqu','','','我将些衣服头面，都做了文房四宝束修钱。
他学的赋课成八韵，诗吟就全篇。
十载寒窗黄卷客，博一纸九重天上紫泥宣。
(云)念老身治家教子，我孩儿事奉萱亲。
着他受半生辛苦，指望待一举成名。
我与人缝联补绽，洗衣刮裳。
(唱)那个不说儿文章亏杀了娘针线，学成了诗云子曰，久以后忠孝双全。','',''),('yuanqu-565','晋陶母剪发待宾・油葫芦','秦简夫','yuanqu','','','你不肯刺骨悬头作状元，全榜上将名姓显，你则待长安市上酒家眠。
则他这匡衡墙紧靠着编修院，则他那杜康宅隔壁是悲田院。
你学仲宣空倚楼，似祖生憎着鞭。
你则待醉乡中早称了平生愿，常留着一体在头边。','',''),('yuanqu-566','晋陶母剪发待宾・天下乐','秦简夫','yuanqu','','','哎，儿也，你几时能勾两行朱衣列马前？(云)孩儿，你须知道的：(唱)则俺这家缘，可也无甚钱，则怕典不了卖不了咱金谷园。
你则待醉华筵学五侯，望竹林访七贤，几曾见凌烟阁上画醉仙？(云)孩儿，想你这般攻书呵，你娘那里得那钱物来？(陶云)孩儿知道，则是多亏了母亲！。','',''),('yuanqu-567','晋陶母剪发待宾・哪吒令','秦简夫','yuanqu','','','则他这今年，非同似往年。
恰还了纸钱，又少欠下笔钱。
常着我左肩，那在这右肩。
与人家做生活打些坌活，闲停止妆宅眷，端的使碎我这意马心猿。','',''),('yuanqu-568','晋陶母剪发待宾・鹊踏枝','秦简夫','yuanqu','','','你则待要赴佳筵，倒金船；咱如今少米无柴，赤手空拳。
你不学汉贾谊献长策万言，你则待学刘伶般烂醉十年。','',''),('yuanqu-569','晋陶母剪发待宾・寄生草','秦简夫','yuanqu','','','你则待扶头酒寻半碗，谒人诗赠几篇。
请着你不离随着他转，逢着你的唱偌迎着他善，后来便说着你的体面难消遣。
则你这拖狗皮缠定这谢家楼，几时得布衣人走上黄金殿！。','',''),('yuanqu-570','晋陶母剪发待宾・金盏儿','秦简夫','yuanqu','','','钱字是大金傍戋，信字是立人边言。
信近于义钱招怨，这一个有钱可更有信，两件事古来传。
这一个有钱的石崇般富。
这一个有信的范丹贤。
你常存着立身夫子信，(云)抬了者！(唱)休恋这转肚邓通钱！。','',''),('yuanqu-571','晋陶母剪发待宾・醉扶归','秦简夫','yuanqu','','','你可便休把他人怨，你可便不听你这母亲言？(陶云)母亲闪了手也！(旦唱)陶侃，你多大年纪也？(陶云)母亲，孩儿二十岁了。
(旦云)你如今二十岁也不索可便虚受了一岁者波，你可也央及了我十九年。
(云)不打这厮惯了他。
陶侃，你再敢吃酒么？(陶云)你孩儿再不敢了也！(旦唱)我这里自解叹无人将我来劝，我这里欲待要打也索好着我心儿里可怜。
(云)陶侃起来！我不打你，饶了你者。
(陶云)我谢了母亲，为甚么不打你孩儿？(旦云)你问我为甚么不打你，(唱)我看着未及第的书生面。','',''),('yuanqu-572','晋陶母剪发待宾・赚煞','秦简夫','yuanqu','','','不为一纸傲书迟，二怕你交朋怨，则我这老益壮贫而益坚。
我甘分饥寒守自然，(云)那冷时节熬的旧颜欹，(唱)这饥时节是我忍过的心闲。
哎，儿也，你曾看这《鲁论篇》？(陶云)孩儿也曾读来，不知是那一篇？(旦云)"齐景公有马千驷"。
(唱)"民无德而称焉"。
都是些有德行颜渊、闵子骞。
你与我书读那万卷，愁甚么户封八县！(云)咱要发迹呵，也至容易。
(唱)你再上那六经中苦志二三年。
(旦下)(陶云)母亲言语，不敢不依。
将着这五贯钱，去那韩夫人家，赎那信字，走一遭去。
(下)。','',''),('yuanqu-573','晋陶母剪发待宾・正宫/端正好','秦简夫','yuanqu','','','甘守分半生贫，则为我有孟母三迁志，我当了二十年无倚靠的家私。
我几曾买卖临街市？我如今顾不的人轻视。','',''),('yuanqu-574','晋陶母剪发待宾・倘秀才','秦简夫','yuanqu','','','我家里请下客非同造次，等着钱家小使，谁家自己发与人做头发儿？(韩夫人云)恁的呵，我不买。
(旦云)你不买罢。
(唱)常存的青丝在，须有变钱时，他比不的秋后的扇儿！。','',''),('yuanqu-575','晋陶母剪发待宾・滚绣球','秦简夫','yuanqu','','','你道是一点墨半张纸，不中吃不中使，(云)俺典了信字，管待秀才。
(唱)又则道俺咬文嚼字。
(韩夫人云)量这个信字，打甚么不紧？(旦唱)都是那十数画儿有这信字。
为臣的作个重臣，为子的作个诤子，为吏的情取个素身行止，借人钱财主每休想道推辞。
(云)姐姐，咱这妇道人家，有这个信字呵，(唱)则被这亲男儿敬重做贤达妇，(云)男子汉有这个信字呵，(唱)交朋友皆呼信有之，你可休看觑因而！(韩夫人云)婆婆，我有心看上你那秀才，肯与我做个女婿，我陪奁房断送，我女孩儿与他为妻。
你意下如何？(旦云)我这里卖头发来？说亲来？下次使不的个媒人说不的！(韩夫人云)我许这亲事早哩。
(旦唱)。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-576','晋陶母剪发待宾・倘秀才','秦简夫','yuanqu','','','俺孩儿"善与人交久而敬之"。
(云)姐姐，你待要题亲呵，(唱)你可便"见贤思齐""默而识之"。
你分明是般调人家小样儿。
俺孩儿常存着读书志，怎肯教不记下楼诗？见俺那读书的小厮。
(韩夫人云)你今日行许了这亲者！(旦云)夫人且等着。
(韩夫人云)等着甚么？(旦唱)。','',''),('yuanqu-577','晋陶母剪发待宾・呆骨朵','秦简夫','yuanqu','','','俺那孩儿遥受着玉堂金马三学士，你便斗的俺那栋梁材节外生枝。
(韩夫人云)小秀才只恁怕你。
(旦唱)你道是儿怕娘严，(云)着姐姐道也，(唱)大古里子孝父慈。
不争着秀才每无忠信，便使美玉生瑕疵。
你待要闺中养艳妹，姐姐也我则理会的棒头出孝子。','',''),('yuanqu-578','晋陶母剪发待宾・脱布衫','秦简夫','yuanqu','','','你可便休卖弄花朵儿般娇姿，休倚仗你铜斗儿家私。
好前程万中怎选？你待题亲事一家无二。','',''),('yuanqu-579','晋陶母剪发待宾・醉太平','秦简夫','yuanqu','','','你待实心儿外侍，也索转意儿寻思。
(云)要成亲早哩。
(唱)直等的俺孩儿金榜挂名时，那其间新婚燕尔。
俺孩儿守寒窗遂了十年志，战群儒一扫三千字，上天梯赋就五言诗，恁时封妻荫子。
(韩夫人云)你许了我这亲事者。
(旦云)你还我头发钱来。
(韩夫人云)谁偷了你的也？(旦云)圣人道先功名而后妻室。
等俺孩儿得了官呵，那其间成这亲事，未为迟哩！(唱)。','',''),('yuanqu-580','晋陶母剪发待宾・尾声','秦简夫','yuanqu','','','等俺孩儿若受了千钟禄三品职，成就了高堂大厦英杰子。
你儿那时节五花诰驷马车，做一个大院深宅媳妇儿。
更有乡邻不轻视，车马迎门不造次，百味珍羞拣口儿，喝婢呼奴换套儿，富贵荣华有人使，儿女团圆做了亲事。
恁时节永远姻亲，方显的我慎终始。
(下)。','',''),('yuanqu-581','晋陶母剪发待宾・中吕/粉蝶儿','秦简夫','yuanqu','','','则俺这茅舍疏篱，又无甚厅堂客位，则见些蓬窗上炕芦席。
虽然是饭蔬食，薄酒味，大刚来是俺主人家情意。
秀才每淡饭黄齑，与你个咽珍羞大人厌饫。','',''),('yuanqu-582','晋陶母剪发待宾・醉春风','秦简夫','yuanqu','','','俺家里甑有范丹尘，厨无原宪米，量这些藜羹黍饭不成席，则是个理、理。
都是些栋梁之材，风麟之瑞，庙堂之器。','',''),('yuanqu-583','正宫・塞鸿秋代人作','贯云石','yuanqu','','','战西风几点宾鸿至，感起我南朝千古伤心事。
展花笺欲写几句知心事，空教我停霜毫半晌无才思。
往常得兴时，一扫无瑕疵，今日个病厌厌刚写下两个相思字。
起初儿相见十分砒タ，心肝儿般敬重将他占。
数年间来往何曾厌？这些时陡恁的恩情俭。
推道是板障柳青严，统镘姨夫欠，只被俏苏卿抛闪煞穷双渐。','',''),('yuanqu-584','正宫・小梁州','贯云石','yuanqu','','','朱颜绿鬓少年郎，都变做白发苍苍。
尽教他花柳自芬芳，无心赏，不趁燕莺忙。','',''),('yuanqu-585','幺・东家醉了东家唱，西家再醉何妨？醉的强，醒的强，百年浑是醉，三','贯云石','yuanqu','','','万六千场。
桃花如面柳如腰，他生的且自妖娆。
醉阑乘兴会今宵，低低道，无语眼儿瞧。','',''),('yuanqu-586','幺・垂杨渡口人相送，拜深深暗祝东风：“他去的高挂起帆，则愿休吹动。”','贯云石','yuanqu','','','刚留一宿，天意肯相容？春春风花草满园香，马系在垂杨。
桃红柳绿映池塘，堪游赏，沙暖睡鸳鸯。','',''),('yuanqu-587','・佳人才子游船上，醉醺醺笑饮琼浆。归棹晚，湖光荡，一钩新月，十里芰荷香。秋','贯云石','yuanqu','','','幺芙蓉映水菊花黄，满目秋光。
枯荷叶底鹭鸶藏，金风荡，飘动桂枝香。','',''),('yuanqu-588','・雷峰塔畔登高望，见钱塘一派长江。湖水清，江潮漾，天边斜月，新雁两三行。冬','贯云石','yuanqu','','','幺彤去密布锁高峰，凛冽寒风。
银河片片洒长空，梅梢冻，雪压路难通。','',''),('yuanqu-589','・六桥顷刻如银洞，粉妆成九里寒松。酒满斟，笙歌送，玉船银棹，人在水晶宫。','贯云石','yuanqu','','','幺巴到黄昏祷告天，焚起香烟。
自从他去泪涟涟，关山还，抛闪的奴家孤枕独眠。','',''),('yuanqu-590','幺・盼才郎早早成姻眷，知他是甚日何年？何年见可怜？可怜见俺成姻眷，','贯云石','yuanqu','','','天地下团圆，带累的俺团圆。','',''),('yuanqu-591','正宫・醉太平失题','贯云石','yuanqu','','','长街上告人，破窑里安身，捱的是一年春尽一年春，谁承望眷姻？红鸾来照孤辰运，白身合有姻缘分，绣球落处便成亲，因此上忍着疼撞门。','',''),('yuanqu-592','南吕・金字经','贯云石','yuanqu','','','晓来春匀透，西园第一枝，香暖朱帘酒满卮。
思，休歌肠断词。
关心事，夜阑入静时。
金芽薰晓日，碧风度小溪，香暖金炉酒满杯。
奇，夜来香透帏。
人初睡，玉堂春梦回。
峨眉能自惜，别离泪似倾，休唱阳关第四声。
情，夜深愁寐醒。
人孤另，萧萧月二更。
泪溅描金袖，不知心为谁？芳草萋萋人未归。
期，一春鱼雁稀。
人憔悴，愁堆入字眉。
紫箫声初散，玉炉香正浓，凉月溶溶小院中。
从，别来衾枕空。
游仙梦，一帘梅雪风。
轻寒堆翠被，东风暖玉纤，香冷金猊月转帘。
添，蛾眉新淡尖。
香收焰，倚窗愁未タ。
楚台云归去，待都来三二朝，闲煞东风碧玉箫。
箫，宝钗金凤翘。
风流貌，把人来憔悴了。','',''),('yuanqu-593','中吕・小上楼赠伶妇','贯云石','yuanqu','','','觑着你十分艳姿，千成心事。
若不就着青春，择个良姻，更待何时？等个忄空伺，寻个挣四，成就了这翰林学士。','',''),('yuanqu-594','中吕・红绣鞋','贯云石','yuanqu','','','东村醉西村依旧，今日醒来日扶头，直吃得海枯石烂恁时休！将屠龙剑，钓鳌钩，遇知音都去做酒。
返旧约十年心事，动新愁半夜相思，常记得小窗人静夜深时。
正西风闲时水，秋兴浅不禁诗，凋零了红叶儿。
雪香兰高侵云鬓，玉灵芝斜捧乌云，轮靥里包藏着些粉霜痕。
耳垂儿冰雪捏，小孔儿里都是玉酥湮，只被这业环儿把他拖逗损。
挨着靠着云窗同坐，偎着抱着月枕双歌，听着数着愁着怕着早四更过。
四更过情未足，情未足夜如梭，天哪，更闰一更儿妨什么！。','',''),('yuanqu-595','中吕・阳春曲金莲','贯云石','yuanqu','','','金莲早自些娘大，着意收拾越逞过。
如今相识眼皮儿薄，休显豁，越遮护着越情多。','',''),('yuanqu-596','中吕・醉高歌过红绣鞋','贯云石','yuanqu','','','看别人鞍马上胡颜，叹自己如尘世污眼。
英雄谁识男儿汉，岂肯向人行诉难？阳气盛冰消北岸，暮云遮日落西山，四时天气尚轮还。
秦甘罗疾发禄，姜吕望晚登坛，迟和疾时运里趱。','',''),('yuanqu-597','中吕・醉高歌过喜春来题情','贯云石','yuanqu','','','自然体态温柔，可意庞儿奈羞。
看时节偷眼将人溜，送与人些风流证候。
蜂媒蝶使空迤逗，燕子莺儿不自由。
恰便似一枝红杏出墙头，不能够折入手，空教人风雨替花羞。','',''),('yuanqu-598','越调・凭阑人题情','贯云石','yuanqu','','','花债萦牵酒病魔，谁唱相思肠断歌？旧愁没奈何，更添新恨多。
昨日欢娱今日别，满腹离愁何处说？一声长叹嗟，凭阑人去也。
冷落桃花扇影歌，羞对青铜扫翠蛾。
风流情减多，未知是若何？情泪新痕压旧痕，心事相关谁共论？黄昏深闭门，被儿独自温。
懒对菱花不欲拈，愁理晨妆不甚タ。
玉纤春笋尖，倦将脂粉添。
红叶传情着意拈，书遍相思苦未タ。
诉愁斑管尖，旋将心事添。
梦里相逢情倍加，梦断香闺愁恨多。
梦他憔悴他，争如休梦他。','',''),('yuanqu-599','双调・蟾宫曲','贯云石','yuanqu','','','竹风过雨新香，锦瑟朱弦，乱错宫商。
樵管惊秋，渔歌唱晚，淡月疏篁。
准备了今宵乐章，怎行云不住高唐？目外秋江，意外风光，环佩空归，分付下凄凉。
相逢忘却余咱，梦隔行云，尽好诗夸。
江上人归，宫中粉淡，明月无涯。
从别却西湖酒家，遇逋翁便属仙葩。
袜重霜华，春色交加，夜半相思，香透窗纱。
问胸中谁有西湖？算诗酒东坡，清淡林逋。
月枕冰痕，露凝荷泪，梦断云裾。
桂子冷香仍月古，是嫦娥厌倦妆梳。
春景扶疏，秋色模糊，若比西施，西子何如？凌波晚步晴烟，太华云高，天外无天。
翠羽摇风，寒珠泣露，总解留连。
明月冷亭亭玉莲，荡轻香散满湖船。
人已如仙，花正堪怜，酒满金樽，诗满鸾笺。
送春问东君何处天涯？落日啼鹃，流水桃花。
淡淡遥山，萋萋芳草，隐隐残霞。
随柳絮吹归那答？趁游丝惹在谁家？倦理琵琶，人倚秋千，月照窗纱。
赠曹绣莲薰吹吹醒横塘，一派波光，掩映红妆。
娇态盈盈，香风冉冉，翠盖昂昂。
一任游人竞赏，尽教鸥鹭埋藏。
世态炎凉，只恐秋凉，冷落空房。','',''),('yuanqu-600','双调・寿阳曲','贯云石','yuanqu','','','担春盛，问酒家，绿杨阴似开图画。
下秋千玉容强似花，汗溶溶透入罗帕。
松杉翠，茉莉香，步回廊老仙策杖。
月明中晚风宝殿凉，玉池深藕花千丈。
鱼吹浪，雁落沙，倚吴山翠屏高挂。
看江潮鼓声千万家，卷朱帘玉人如画。
新诗句，浊酒壶，野人闲不知春去。
家童柳边闲钓鱼，趁残红满江鸥鹭。
新秋至，人乍别，顺长江水流残月。
悠悠画船东去也，这思量起头儿一夜。','',''),('yuanqu-601','双调・水仙子田家','贯云石','yuanqu','','','绿阴茅屋两三间，院后溪流门外山，山桃野杏开无限。
怕春光虚过眼，得浮生半日清闲。
邀邻翁为伴，使家僮过盏，直吃的老瓦盆干。
满林红叶乱翩翩，醉尽秋霜锦树残，苍苔静拂题诗看。
酒微温石鼎寒，瓦杯深洗尽愁烦。
衣宽解，事不关，直吃的老瓦盆干。
田翁无梦到长安，婢织奴耕尽我闲，蚕收稻熟今秋办。
可无饥不受寒，乐丰年畅饮开颜。
唤稚子ド新酿，靠篷窗对客弹，直吃的老瓦盆干。
布袍草履耐风寒，茅舍疏斋三两间，荣华富贵皆虚幻。
觑功名如等闲，任逍遥绿水青山。
寻几个知心伴，酿村醪饮数碗，直吃的老瓦盆干。','',''),('yuanqu-602','双调・殿前欢','贯云石','yuanqu','','','畅幽哉，春风无处不楼台。
一时怀抱俱无奈，总对天开。
就渊明归去来，怕鹤怨山禽怪，问甚功名在？酸斋是我，我是酸斋。
楚怀王，忠臣跳入汨罗江。
《离骚》读罢空惆怅，日月同光。
伤心来笑一场，笑你个三闾强，为甚不身心放？沧浪污你，你污沧浪。
觉来评，求名求利不多争。
西风吹起山林兴，便了余生。
白云边创草亭，便留下寻芳径，消日月存天性。
功名戏我，我戏功名。
怕西风，晚来吹上广寒宫。
玉台不放香奁梦，正要情浓。
此时心造物同，听甚《霓裳》弄，酒后黄鹤送。
山翁醉我，我醉山翁。
怕相逢，怕相逢歌罢酒樽空。
醉归来纵有阳台梦，云雨元踪。
楼心月扇底风，情缘重，恨不似钗头凤。
东阳瘦损，羞对青铜。
怕秋来，怕秋来秋绪感秋怀。
扫空阶落叶西风外，独立苍苔。
看黄花谩自开，人安在？还不彻相思债。
朝云暮雨，都变了梦里阳台。
隔帘听，几番风送卖花声。
夜来微雨天阶净，小院闲庭。
轻寒翠袖生，穿芳径，十二阑干凭。
杏花疏影，杨柳新晴。
数归期，绿苔墙划损短金篦。
裙刀儿刻得阑干碎，都为别离。
西楼上雁过稀，无消息，空滴尽相思泪。
山长水远，何日回归？夜啼乌，柳枝和月翠扶疏。
绣鞋香染莓苔路，搔首踟蹰。
灯残瘦影孤，花落流度度，春去佳期误。
离鸾有恨，过雁无书。
和阿里西瑛懒云窝懒云窝，阳台谁与送巫娥？蟾光一任来穿破，遁迹由他。
蔽一天星斗多，分半榻蒲团坐，尽万里鹏程挫。
向烟霞笑傲，任世事蹉跎。
套数。','',''),('yuanqu-603','薛仁贵荣归故里・仙吕/端正好','张国宾','yuanqu','','','你如今离了村庄，别了乡党，拜辞了年老爹娘。
(薛仁贵云)您孩儿此去，定要赤心报国，展土开疆，博个封侯拜将而回。
父亲放心者。
(正末唱)你待要，忘生舍死在这沙场上。
则你那雄赳赳气昂昂，身凛凛貌堂堂。
知甚日得还乡？哎！儿也，休教您这两口儿斜倚定门儿望。
(同卜儿下)(旦儿云)大哥，妾身在家，情愿替你侍养公婆，你放心的自去。
妾身送你出这柴门外也。
(薛仁贵云)大嫂，堂上无人，你自回去，侍奉公婆，不必送我。
(拜别科)(薛仁贵诗云)我今日远去投军，惟愿你孝顺双亲。
(先下)(旦做悲科，诗云)虽然是芳年连理，为功名只得离分。
(下)。','',''),('yuanqu-604','薛仁贵荣归故里・仙吕/点绛唇','张国宾','yuanqu','','','恰便似猛虎当途，甚人敢拒？有一个白袍卒，奋勇前驱，直杀的他无奔处。
(云)却被那总管张士贵要混赖薛仁贵的功劳。
这是老夫在阵面上亲目所睹，怎生好混赖也？(唱)。','',''),('yuanqu-605','薛仁贵荣归故里・混江龙','张国宾','yuanqu','','','那厮每杀人可恕，将别人功绩强糊突。
贪着个一时爵赏，使出这百计赃诬。
则问你九里山前都是谁的力？比及凌烟阁上倒把恁来图。
我待要叩金阶款款的明开去，着甚来论黄数黑，也则是恶紫夺朱。','',''),('yuanqu-606','薛仁贵荣归故里・油葫芦','张国宾','yuanqu','','','当日个鸭绿江边列阵图，(张士贵云)众位大人在上，你就说这一场三箭定了天山，不是张士贵的，却是谁的功劳来？(正末唱)现对着这文共武，(徐茂功云)三箭定了天山，此功最大。
您二将争竞，未知是谁的功劳也？(正末云)这是老夫亲目所见，委实是薛仁贵的。
(唱)则他这定大山三箭若连珠。
(张上贵云)我是个总管的官，堪上功劳簿。
那薛仁贵不过马前小卒，他怎么上的功劳簿？(正末唱)哎！不索你个将军争竞功劳簿，抵多少凤凰《在梧桐树(张士贵云)薛仁贵走到高丽地面，就生了一身疥疮，每日则是挠痒，几曾厮杀来。
只他寸箭皆无，他有甚么功劳？(正末唱)那薛仁贵有十大功，你可也寸箭无，你待做赵高妄指秦庭鹿，怎不去学龙伯钓鳌鱼？(张士贵云)不是我张士贵夸口，那个似我这等？骑的劣马，拽的硬弓；吃的冷饭，嚼的憨葱；若有好酒，打上三钟。
俺真个是铁挣挣的好汉子哩。
(正末唱)。','',''),('yuanqu-607','薛仁贵荣归故里・天下乐','张国宾','yuanqu','','','敢待卖弄你这英雄大丈夫，准也波如。
自窨付，可甚的养由基善穿杨百步馀？(张士贵云)那薛仁贵到的高丽地面，则去扑蚂蚱，摸螃蟹，掏促蜘，几曾会甚么厮杀来？(正末唱)是谁人领着大军？是谁人统着帅府？(张士贵云)你不要说嘴，您都有甚么功劳在那里？(正末云)则你道波。
(唱)那一个无功劳的请俸禄？。','',''),('yuanqu-608','薛仁贵荣归故里・那吒令','张国宾','yuanqu','','','论着你这文呵，怎的如管仲和鲍叔？(张士贵云)论我的武呢？(正末唱)论着你那武呵，怎如的周瑜鲁肃？(张士贵云)论我的智量呢？(正末唱)论着你智量呵，怎如的卧龙也那凤雏？(张士贵云)论着我兵书战策，揣着一肚子。
我久后还要拜相封侯做大大的官哩。
(正末唱)遮莫似张子房，辞朝待要归山去，再习些战策兵马。','',''),('yuanqu-609','薛仁贵荣归故里・鹊踏枝','张国宾','yuanqu','','','你道他是农夫，做军卒，(带云)想那诸葛亮呵，(唱)偏不曾隐迹南阳，乐意耕锄。
(张士贵云)他后来却怎的？(正末唱)命通也逢着帝王，一年间三谒茅庐。','',''),('yuanqu-610','薛仁贵荣归故里・寄生草','张国宾','yuanqu','','','想当日韩元帅，乞食那漂母。
若不是萧何举荐元戎做，则那汉王怎把重瞳蹙？显见的忠良多在寒门出。
(张士贵云)监军大人，依着我只将薛仁贵革了他军，赶回家去，仍旧种田，才称了我心也。
(正末唱)则你这筑沙堤推倒了紫金梁，怎如他沤麻坑扶立的擎天柱？。','',''),('yuanqu-611','薛仁贵荣归故里・金盏儿','张国宾','yuanqu','','','你两个较赢输，辨实虚，(徐茂功云)只今日要见个明白，方好论功行赏也。
(正末唱)这的是功劳簿上无差误。
(徐茂功云)射不着金钱的，罢官卸职；射着金钱的，着他衣紫腰金哩。
(正末唱)射不着罢官也那卸职，射着的玉匠带上挂金鱼。
(徐茂功云)射不着的打为庶民，射着的着他位列三公之上。
(正末唱)射不着的苫庄三顷地，扶手一张锄。
射着的稳情取门排十二戟，户列八椒图。','',''),('yuanqu-612','薛仁贵荣归故里・赚煞尾','张国宾','yuanqu','','','也不负了你血染战袍红，镫藏着征靴绿，那一枝方天戟超今越古。
看这赖功贼容颜如粪土，出辕门豕窜狼逋。
怎知你喜都都，后拥前呼，那里也一将功成万骨枯。
(薛仁贵云)量小将有甚功劳，感蒙监军大人这般抬举。
(正末唱)则为你外疆展土，拿云握雾，托赖着圣明天子百灵扶。
(下)。','',''),('yuanqu-613','薛仁贵荣归故里・逍遥乐','张国宾','yuanqu','','','哎哟！儿也，自从您投军出外。
我每日家少精也那无神，失魂丧魄。
哎哟！儿也，知他那里日炙风节，博功名苦尽甘来。
我也只指望你一箭成功把门户改，光显随祖宗先代。
我如今无亲无眷，无靠无捱，(哭科)(唱)哎哟！儿也，每日家无米无柴。
(正末做见卜儿科，云)婆婆，你唤我做甚么？(卜儿云)老的也，你动不动烦天恼地。
这般啼哭做甚么？我恰才唤你，你可在那里来？(正末云)我在庄东里吃做亲的喜酒去来。
(卜儿云)老的也。
我往庄东里吃喜酒去，可是谁家的女儿招了谁家的小厮？你说一遍咱。
(正末云)婆婆听我说者。
(唱)。','',''),('yuanqu-614','薛仁贵荣归故里・后庭花','张国宾','yuanqu','','','割舍了一不做二不该，(做举拄杖，卜儿夺科)(正末云)婆婆放手。
(卜儿云)老的也息怒。
(三科)(正末唱)我打这厮千自由百自在。
(云)驴哥，你去了几时也？(薛仁贵云)您孩儿去了十年光景也。
(正末唱)你从那二十二上投军去，你怎生三十三岁上恰到来？(薛仁贵云)父亲，您孩儿尽忠，便不能尽孝也。
(正末唱)你那一日离庄宅，登紫陌，绛州城气概，龙门镇施手策。
你道把家门即便改，谁承望又过了十数载。','',''),('yuanqu-615','薛仁贵荣归故里・双雁儿','张国宾','yuanqu','','','恰便似送曾哀赵藁不回来。
哎哟！儿也，我则道父子每，相间隔，不想想孩儿也，俨然在。
做娘的筋力衰，做爹的发鬓白。','',''),('yuanqu-616','薛仁贵荣归故里・醋葫芦','张国宾','yuanqu','','','你将那酒去买，鸡快宰。
(卜儿云)老的也，着些甚么买那酒和鸡来？(正末唱)你与我店东头折当了那一对旧麻鞋。
(卜儿云)便买些小酒食也醉不的他，驴哥儿酒量大哩。
(正末唱)你道是薛驴哥酒量儿宽似海，(带云)婆婆，有！有！(唱)床底下还有那二升家的乔麦。
哎！儿也，知他是甚风儿足律律，吹你可兀的到家来。','',''),('yuanqu-617','薛仁贵荣归故里・幺篇','张国宾','yuanqu','','','则见他怕撇撇开圣旨，早唬的来黄甘甘改了面色。
(张士贵云)令人两边摆着，休着那老的上前来。
(卜儿哭科)(正末云)儿也。
(唱)则见他恶哏哏的公吏两边排，则除是南海救苦难观自在。
(张士贵云)打开那老的，休着他劫夺了。
(正末唱)唬的我磕头也那礼拜。
(带云)大人。
(唱)你饶过俺孩儿一命不强似把万僧斋？。','',''),('yuanqu-618','薛仁贵荣归故里・浪里来煞','张国宾','yuanqu','','','把孩儿扑碌碌推出门，(张士贵云)抢出去杀坏了罢。
(正末唱)眼睁睁的要杀坏，空教我心劳意攘怎支划？(张士贵云)执缚定着，休走这厮也。
(正末唱)我只见麻绳背绑教他难挣坐，养谁来把孩儿耽待？哎哟！儿也，咱要相逢，则除是九重天将这一纸赦书来。
(正末同卜儿下)。','',''),('yuanqu-619','薛仁贵荣归故里・中吕/粉蝶儿','张国宾','yuanqu','','','正值着日暖风微，一家家上坟准备。
准备些节下茶食，菜馒头，瓢漏粉，鸡豚狗彘。
这的是甚所乔为，直吃的恁般沙势。','',''),('yuanqu-620','薛仁贵荣归故里・尧民歌','张国宾','yuanqu','','','呀！莫不是空中降下雪神祗？(薛仁贵云)兀那庄家，你住者。
(正末唱)他叫一声雄吼若春雷。
(薛仁贵云)你休慌，我要问你句话哩。
(正末唱)唬的我心儿胆儿急獐拘猪的自昏迷，手儿脚儿滴羞笃速的似呆痴。
禁也波持，身躯怎动移，我可便不待酒佯妆醉。','',''),('yuanqu-621','薛仁贵荣归故里・上小楼','张国宾','yuanqu','','','蓦听的人言马嘶。
威风也那猛势。
唬的我战战兢兢，慌慌张张。
只待要哭哭啼啼。
这一壁那一壁，怎生逃避？好着我磕扑的在马前跑膝。
(薛仁贵云)兀那厮，我问着你，您休推东主西的。
(正末云)小人怎敢？(唱)。','',''),('yuanqu-622','薛仁贵荣归故里・满庭芳','张国宾','yuanqu','','','怎敢道是推东主西？我则怕言无关典，话不投机。
(薛仁贵云)你可是土居也？可是寄居？当着甚么差徭？(正末唱)孩儿每在龙门镇民户当夫役。
(薛仁贵云)您成群打伙，在这里做甚么哩？(正末唱)今日正百五寒食，上坟的都是同乡共里，吃酒用瓦钵和这磁杯。
怕官人待要来敛科税，我去村头行报知。
官人也你但道的我便依随。','',''),('yuanqu-623','双调・殿前欢秋日湖上','张可久','yuanqu','','','倚吟篷，障西风十里锦芙蓉。
照沧浪似入桃源桐，欠个渔翁。
冰泉泻翠筒，玉液浮银瓮，罗袖擎金凤。
团香弄粉，泛绿依红。
次酸斋韵二首钓鱼台，十年不上野鸥猜。
白云来往青山在，对酒开怀。
欠伊周济世才，犯刘阮贪杯戒，还李杜吟诗债。
酸斋笑我，我笑酸斋。
唤归来，西湖山上野猿哀。
二十年多少风流怪，花落花开。
望云霄拜将台，袖星斗安邦策，破烟月迷魂寨。
酸斋笑我，我笑酸斋。
离思二首夜啼乌，柳枝和月翠扶疏。
绣鞋香染莓苔露，搔首踟蹰。
灯残瘦影孤，花落流年度，春去佳期误。
离鸾有恨，过雁无书。
月笼沙，十年心事付琵琶。
相思懒看帏屏画，人在天涯。
春残豆蔻花，情寄鸳鸯帕，香冷荼コ架。
旧游台榭，晓梦窗纱。
西湖晚晴总宜船，绿情红意雨余天。
盈盈皓月明如练，棹举冰田。
神仙太乙莲，图画崔徽面，才思班姬扇。
新诗象管，古调冰弦。
客中二首望长安，前程渺渺鬓斑斑。
南来北往随征雁，行路艰难。
青泥小剑关，红叶湓江岸，白草连云栈。
功名半纸，风雪千山。
锦缠头，粉筝低按舞《凉州》。
佳人一去春残后，香冷云兜。
晴山翠黛愁，绿水罗裙皱，细柳宫腰瘦。
梨花暮雨，燕子空楼。','',''),('yuanqu-624','双调・清江引秋思','张可久','yuanqu','','','自从玉关人去也，寂寞银屏夜。
风寒白藕花，露冷青桐叶，雁儿未来书再写。
幽居红尘是非不到我，茅屋秋风破。
山村小过活，老砚闲工课，疏篱外玉梅三四朵。
桐柏山中松风小楼香缥缈，一曲寻仙操。
秋风玉兔寒，野树金猿啸，白云半天山月小。
湖山避暑好山尽将图画写，诗会白云社。
桃笙卷浪花，茶乳翻冰叶，荷香月明人散也。
春思二首杜鹃几声烟树暖，风雨相撺断。
梨花月未圆，柳絮春将半，夜长可怜归梦短。
绣针懒拈闲素手，倦枕金钗溜。
莺啼绿柳春，燕舞红帘昼，东风院落人病酒。
九日湖上西风又吹湖上柳，画舫携红袖。
鸥眠野水闲，蝶舞秋花瘦，风流醉翁不在酒。
山居春枕门前好山云占了，尽日无人到。
松风响翠涛，槲叶烧丹灶，先生醉眠春自老。
春晚二首黄昏闭门谁笑语，燕子飞不去。
珠帘溅雨花，翠坞埋烟树，酒醒五更闻杜宇。
离愁困人帘未卷，上下飞双燕。
孤云带雨痕，暗水流花片，湖边日长春去远。
湖上晚望东西往来船斗蚁，拍手胡姬醉。
歌声落照边，塔影孤云际，荷风夜凉天似水。
秋怀西风信来家万里，问我归期未？雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里。','',''),('yuanqu-625','中吕・朝天子山中杂书三首','张可久','yuanqu','','','罢手，去休，已落在渊明后。
百年心事付沙鸥，更谁是忘机友。
洞口渔舟，桥边村酒，这清闲何处有？树头，锦鸠，花外啼春昼。
夜长，未央，盼杀鸡三唱。
东华听漏满靴霜，却笑渊明强。
月朗禅床，风清鹤帐，梦不到名利场。
草堂，暗香，春已到梅梢上。
醉馀，草书，李愿盘谷序。
青山一片范宽图，怪我来何暮？鹤骨清癯，蜗壳蘧庐，得安闲心自足。
蹇驴，和酒壶，风雪梅花路。
野景亭瓜田邵平，草堂杜陵，五柳庄彭泽令。
牵牛篱落掩柴荆，犬吠林塘静。
树顶蟾明，水面风生，听渔歌三四声。
小亭，野景，动着我莼鲈兴。
酸斋席上听胡琴玉鞭，翠钿，记马上昭君面。
一梭银线解冰泉，碎拆骊珠串。
雁舞秋烟，莺啼春院，伤心塞草边。
醉仙，彩笺，写万里关山怨。
春思见他，问咱，怎忘了当初话？东风残梦小窗纱，月冷秋千架。
自把琵琶，灯前弹罢，春深不到家。
五花，骏马，何处垂杨下。
梅友元帅席上老夫，病余，尚草《长门赋》。
阿莲娇吻贯骊珠，试听《莺啼序》。
玉露冰壶，香风琼树，醉归来不用扶。
小奴，按舞，看了梅花去。','',''),('yuanqu-626','中吕・红绣鞋次韵','张可久','yuanqu','','','剑击西风鬼啸，琴弹夜月猿号，半醉渊明可人招。
南来山隐隐，东去浪淘淘，浙江归路杳。
春日湖上二首百五日清明节假，两三攒绿暗人家，客子飘零尚天涯。
春风轻柳絮，夜雨瘦梨花，绿杨阴谁系马？绿树当门酒肆，红妆映水鬟儿，眼底殷勤座间诗。
尘埃三五字，杨柳万千丝，记年时曾到此。
春夜燕子来时酒病，牡丹开处诗情，庭院黄昏雨初晴。
镜心闲挂月，筝手碎弹冰，樽前春夜永。
湖上无是无非心事，不寒不暖花时，妆点西湖似西施。
控青丝玉面马，歌《金缕》粉团儿，信人生行乐耳。
圣水寺山亭佛国清凉境界，壶天金碧楼台，照眼西山画屏开。
海云推月上，江水带潮来，醉嫌天地窄。
越山即事山拥玉皇香案，烟笼翠羽仙鬟，两袖天风倚高寒。
鹤归苍树杪，犬吠白云间，蓬莱迷望眼。
天台瀑布寺绝顶峰攒雪剑，悬崖水挂冰帘，倚树哀猿弄云尖。
血华啼杜字，阴洞吼飞廉，比人心山未险。
次归去来韵东舍西邻酒债，春花秋月诗才，两字功名困尘埃。
青山依旧好，黄菊近新栽，没商量归去来。
洞庭道中二首白鹭荒堤老葑，黄云远水长空，百尺蒲帆饱西风。
酒旗花影里，钓艇树阴中，好山千万重。
逐名利长安日下，望乡关倦客天涯，孤雁南来倍思家。
乱山云掩翠，老树雪生花，冻吟诗骑瘦马。
天台桐柏山中谈世事渔樵闲问，洗征尘麋鹿相亲，步入蓬莱误寻真。
竹声摇翠雨，山影护苍云，神仙深处隐。
雪芳亭金错落樽前酒令，玉娉婷乐府新声，夜深花睡嫩寒生。
一围云锦树，四面雪芳亭，月斜时人未醒。
春晚圆旧梦衾闲锦绣，按新声弦断箜篌，满襟离思倦登楼。
花寒鹦鹉病，春去杜鹃愁，倚栏人困酒。
岁暮二首金莲步苍苔小径，玉钩垂翠竹闲亭，物换星移暗伤情。
游鱼翻冻影，啼鸟泛春声，落梅香暮景。
竞酒争花公事，吟风弄月神思，好春能有几何时？玲珑心似锦，积渐鬓成丝，落一张闲故纸。
山中黄叶青烟丹灶，曲阑明月诗巢，绿波亭下小红桥。
老梅盘鹤膝，新柳舞蛮腰，嫩茶舒凤爪。
鉴湖落叶山容消瘦，题诗人物风流，一片闲云驻行舟。
月寒清镜晓，花淡碧壶秋，谪仙同载酒。
三衢山中白酒黄柑山郡，短衣瘦马诗人，袖手观棋度青春。
仙桥藏老树，石笋瘗苍云，松花飘瑞粉。','',''),('yuanqu-627','双调・沉醉东风钓台','张可久','yuanqu','','','貂裘敝谁怜倦客，锦笺寒难写秋怀。
野水边，闲云外，尽教他鸥鹭惊猜。
溪上良田得数顷来，也敢上严陵钓台。
湖上垂杨柳无人自舞，提葫芦有意相呼。
酒醒时，花深处，插花枝满头归去。
莫惜千金倒玉壶，春已近梨花暮雨。
元夜明月无心紫箫，夕阳何处蓝桥？蕙帐寒，梅花落，故人稀渐疏谈笑。
看见鹅黄上柳条，等闲放元宵过了。
幽居二首脚到处青山绿水，兴来时白酒黄鸡。
远是非，绝名利，腹便便午窗酣睡。
鹦鹉杯中昼日迟，到强似麒麟画里。
笑白发犹缠利锁，喜红尘不到渔蓑。
八咏诗，三闾些，收拾下晚春工课。
茅舍疏篱小过活，有情分沙鸥伴我。','',''),('yuanqu-628','双调・庆东原次马致远先辈韵九篇九首','张可久','yuanqu','','','烧丹灶，洗药瓢，乐清闲几个人知道。
闲吹凤箫，闷拈兔毫，焉用牛刀。
他得志笑闲人，他失脚闲人笑。
门长闭，客任敲，山童不唤陈抟觉。
袖中《六韬》，鬓边二毛，家里箪瓢。
他得志笑闲人，他失脚闲人笑。
杀三士，因二桃，不如五柳庄前傲。
文魔贾岛，诗穷孟郊，酒困山涛。
他得志笑闲人，他失脚闲人笑。
繁华梦，贫贱交，唐尧不改巢由调。
纷纷紫袍，区区绿袍，恋恋绨袍。
他得志笑闲人，他失脚闲人笑。
诗情放，剑气豪，英雄不把穷通较。
江中斩蛟，云间射雕，席上挥毫。
他得志笑闲人，他失脚闲人笑。
难开眼，懒折腰，白云不应蒲轮召。
解组汉朝，寻诗灞桥，策杖临皋。
他得志笑闲人，他失脚闲人笑。
依山洞，结把茅，清风雨袖长舒啸。
问江边老樵，访山中故交，伴云外孤鹤。
他得志笑闲人，他失脚闲人笑。
苍头哨，骢马骄，放辔头也只到长安道。
说家门尽教，守齑盐慢熬，请荆布休焦。
他得志笑闲人，他失脚闲人笑。
山容瘦，木叶凋，对西窗尽是诗材料。
苍烟树杪，残雪柳条，红日花梢。
他得志笑闲人，他失脚闲人笑。
越山即事二首庭前树，篱下菊，老渔樵相伴闲鸥鹭。
听道士步虚，教稚子读书，引吟客携壶。
借贺老鉴湖船，访谢傅东山去。
云轻散，月易残，女萧何成败了些风流汉。
冯魁硬铲，双生紧赶，小姐先<走山>。
今夜惜花心，明日伤春叹。','',''),('yuanqu-629','中吕・迎仙客感旧','张可久','yuanqu','','','鹦鹉洲，凤凰楼，十年故人怀旧游。
杜陵花，陶令酒，酒病花愁，不觉的今春瘦。
湖上送别钓锦鳞，棹红云，西湖画船三月春。
正思家，还送人，绿满前村，烟雨江南恨。
春日湖上二首雨亦奇，锦成围，笙歌满城莺燕飞。
紫霞杯，金缕衣，倒着接篱，湖上山翁醉。
舞绛纱，扣红牙，耳边玉人催人马。
雪儿歌，苏小家，月淡梨花，醉倚秋千架。
春晚看牡丹，倚阑干，宿酒乍醒欹髻鬟。
燕初忙，莺正懒，帘卷轻寒，玉手调筝雁。
秋夜雨乍晴，月笼明，秋香院落砧杵鸣。
二三更，千万声，捣碎离情，不管愁人听。
黄桂近玉阶，映瑶台，婆娑小丛岩畔栽。
雁初飞，花正开，金粟如来，望月佳人拜。','',''),('yuanqu-630','越调・凭阑人湖上二首','张可久','yuanqu','','','远水晴天明落霞，古岸渔村横钓槎。
翠帘沽酒家，画桥吹柳花。
二客同游过虎溪，一径无尘穿翠微。
寸心流水知，小窗明月归。
春夜灯下愁春愁未醒，枕上吟诗吟未成。
杏花残月明，竹根流水声。
春思三首莺羽金衣舒晚风，燕嘴香泥沾乱红。
翠帘花影重，玉人春睡浓。
春柳长亭倾酒樽，秋菊东篱洒泪痕。
思君不见君，倚门空闭门。
帘外轻寒归燕忙，桥下残红流水香。
游人窥粉墙，玉骢嘶绿杨。','',''),('yuanqu-631','中吕・山坡羊春日二首','张可久','yuanqu','','','芙蓉春帐，葡萄新酿，一声《金缕》樽前唱。
锦生香，翠成行，醒来犹问春无恙，花边醉来能几场？妆，黄四娘。
狂，白侍郎。
西湖沉醉，东风得意，玉骢骤响黄金辔。
赏春归，看花回，宝香已暖鸳鸯被，萝绕绿窗初睡起。
痴，人未知。
噫，春去矣。
雪夜扁舟乘兴，读书相映，不如高卧柴门静。
唾壶冰，短檠灯，隔窗孤月悬秋镜，长笛不知何处声？惊，人睡醒。
清，梅弄影。
别怀梨花都谢，春衫初卸，绿阴空锁闲台榭。
远山叠，暮云遮，青青杨柳连官舍。
此景此情难弃舍，车，且慢些。
别，人去也。','',''),('yuanqu-632','南吕・四块玉闲居','张可久','yuanqu','','','胜事添，殿尘减，玉洞仙书带云缄，金华羽士登门探。
酒一坛，药几篮，经半龛。
春情酒易阑，愁难解，杏脸香销玉妆台，柳腰宽褪罗裙带。
春已归，花又开，人未来。
乐闲远是非，寻潇洒，地暖江南燕宜家，人闲水北春无价。
一品茶，五色瓜，四季花。','',''),('yuanqu-633','中吕・喜春来鉴湖春日','张可久','yuanqu','','','雁啼秋水移冰柱，蚁泛春波倒玉壶，绿杨花谢燕将雏。
人笑语，游遍贺家湖。
金华客舍落红小雨苍苔径，飞絮东风细柳营，可怜客里过清明。
不待听，昨夜杜鹃声。
永康驿中荷盘敲雨珠千颗，山背披云玉一蓑，半篇诗景费吟哦。
芳草坡，松外采茶歌。
春夜收云敛雨销金帐，望月瞻星傅粉郎，欢天喜地小红娘。
来要赏，花影过东墙。','',''),('yuanqu-634','南吕・骂玉郎过感皇恩采茶歌为酸斋解嘲','张可久','yuanqu','','','君王曾赐琼林宴，三斗始朝天，文章懒入编修院。
红锦笺，白苎篇，黄柑传。
学会神仙，参透诗禅。
厌尘嚣，绝名利，近林泉。
天台洞口，地肺山前。
学炼丹，同货墨，共谈玄。
兴飘然，酒家眠。
洞花溪鸟结姻缘，被我瞒他四十年，海天秋月一般圆。
杨驹儿墓园莓苔生满苍云径，人去小红亭，题情犹是酸斋赠。
我把那诗韵赓，书画评，栏干凭。
茶灶尘凝，墨水冰生。
掩幽扃，悬瘦影，伴孤灯。
琴已亡伯牙，酒不到刘伶。
策短藤，乘暮景，放吟情。
写新声，寄春莺。
明年来此赏清明，窗掩梨花庭院静，小楼风雨共谁听？。','',''),('yuanqu-635','双调・水仙子访梅孤山','张可久','yuanqu','','','苍苔封了岁寒枝，翠袖闲来日暮时，黄昏说尽平生事。
西湖林处士，想当年鹤骨松姿。
花下孤山寺，水边新月儿，慰我相思。
湖上晚归二首桃花马上石榴裙，竹叶樽前玉树春，荔枝香里江梅韵。
风流比太真，索新词缠住诗人。
醉眼空银汉，歌声度锦云，凉月黄昏。
佳人微醉脱金钗，恶客佯狂饮绣鞋，小鬟催去褰罗带。
花寒月满街，荡湖光影转楼台。
未了鸳鸯债，枉教鸥鹭猜，明日重来。
清明小集红香缭绕柳围花，翠袖殷勤酒当茶，游春三月清明假。
香尘随去马，小帘栊绿水人家。
弹仙吕六幺遍，笑女童双髻丫，纤手琵琶。
苏堤晚兴翠帘堤上小肩舆，乌帽风前醉老夫，浸冰壶云锦高低树。
笑王维作画图，步凌波红粉相扶。
罗裙酒污，兰舟棹举，月上西湖。
湖上小隐二首自由湖上水云身，烂漫花前莺燕春，萧疏命里功名分。
乐琴书桑苎村，掩柴门长日无人。
蕉叶权歌扇，榴花当舞裙，一笑开樽。
梦随流水过前滩，喜共闲云归故山，倚筇和靖坟前看。
把梅花多处拣，盖深深茅屋三间。
歌白石烂，赋行路难，紧闭柴关。
春行即事绿笺香露洒蕉花，翠线晴风绽柳芽，游人三月湖山下。
六桥边争系马，江南第一所繁华。
金碧王维画，管弦苏小家，酒船回落日归鸦。
孤山宴集长桥卧柳枕苍烟，远水揉蓝洗暮天，画图千古西施面。
相逢越少年，问孤山何处逋仙？吾与二三子，来游六一泉，载酒梅边。','',''),('yuanqu-636','双调・折桂令湖上寒食','张可久','yuanqu','','','雨霏霏店舍无烟，榆荚飞钱，柳线搓绵。
绿水人家，残花院落，美女秋千。
沽酒春衣自典，思家客子谁怜？第一桥边，恋住流莺，不信啼鹃。
湖上道院鹤飞来一缕青霞，笑富贵飞蚊，名利争蜗。
古砚玄香，名琴绿绮，土釜黄芽。
双井先春采茶，孤山带月锄花。
童子谁家？贪看西湖，懒诵南华。
酒边即事莺莺燕燕相亲，幸有名园，着我闲身。
竹点诗痕，花消酒困，柳拂歌尘。
锦帐里团香弄粉，画楼前访雨寻云。
不负青春，谁共佳人，相约黄昏？避暑醉题俯沧波楼观烟霞，胜览方舆，独占繁华。
彩舰轻帘，银鞍骏马，翠袖娇娃。
十里香风酒家，一川凉雨荷花。
醉墨涂鸦，题遍红楼，倒裹乌纱。','',''),('yuanqu-637','中吕・满庭芳湖景','张可久','yuanqu','','','丝竹管弦，花围富贵，柳阵婵娟。
绿阴红影藏莺燕，醉客金鞭。
锦步障长安上苑，玉浮图极乐西天。
一步一个屏风面，孤山寺前，无数采莲船。','',''),('yuanqu-638','中吕・普天乐重过西湖','张可久','yuanqu','','','画图中，红尘外，妆台玉钗，芳径罗鞋。
金瓶带酒携，纨扇和诗卖。
一枕清风扁舟快，碧桃香两岸花开。
刘郎再来，西施好客，东阁怜才。
暮春即事老梅边，孤山下，晴桥くぐ，小舫琵琶。
春残杜宇声，香冷荼コ架。
淡抹浓妆山如画，酒旗儿三两人家。
斜阳落霞，娇云嫩水，剩柳残花。','',''),('yuanqu-639','双调・清江引独酌','张可久','yuanqu','','','玉笛一声天地愁，便觉梅花瘦。
寒流清浅时，明月黄昏后，独醉一樽桑落酒。
夜景醺醺绮罗欢笑彻，檀板歌声歇。
宝鼎串香绝，银烛灯花谢，玳筵前酒阑人散也。
情描金翠钿侵鬓贴，满口儿喷兰麝。
檀板撒红牙，皓齿歌白雪，定不定百般娇又怯。','',''),('yuanqu-640','越调・小桃红湖亭秋夜','张可久','yuanqu','','','锦鸳偷占藕花汀，花影涵秋镜。
人倚阑干叹孤另，掩围屏，伤心眼见秋成病。
月明吊影，风清遣兴，玉手寄银筝。','',''),('yuanqu-641','中吕・朝天子湖上','张可久','yuanqu','','','瘿杯，玉醅，梦冷芦花被。
风清月白总相宜，乐在其中矣。
寿过颜回，饱似伯夷，闲如越范蠡。
问谁，是非，且向西湖醉。','',''),('yuanqu-642','双调・沉醉东风湖上晚眺','张可久','yuanqu','','','林君复先生故居，苏子瞻学士西湖。
六月天，孤山路，载笙歌画船无数。
万顷玻璃浸玉壶，夕阳外荷花带雨。
晚春席上客坐松根看水，鹤来庭下观棋。
小砚香，残红坠，竹珊珊野亭交翠。
相伴闲云出岫迟，题诗在呼猿洞里。','',''),('yuanqu-643','双调・寿阳曲','李寿卿','yuanqu','','','金刀利，锦鲤肥，更那堪玉葱纤细。
添得醋来风韵美，试尝道甚生滋味！。','',''),('yuanqu-644','仙吕・醉扶归赋粉团儿','刘时中','yuanqu','','','色映金茎露，香腻玉盘酥。
一段清冰出玉壶，不管胭脂妒。
晓镜青鸾影孤，正要何郎傅。','',''),('yuanqu-645','仙吕・醉中天','刘时中','yuanqu','','','花木相思树，禽鸟折枝图。
水底双双比目鱼，岸上鸳鸯户，一步步金厢翠铺。
世间好处，休没寻思，典卖了西湖。','',''),('yuanqu-646','南吕・金字经常氏称心','刘时中','yuanqu','','','少年情缘浅，老来欢爱深，费尽长门买赋金。
酒满斟，醉来花下吟。
缠头锦，愿得常称心。','',''),('yuanqu-647','中吕・朝天子邸万户席上','刘时中','yuanqu','','','柳营，月明，听传过将军令。
高楼鼓角戒严更，卧护得边声静。
横槊吟情，投壶歌兴，有前人旧典型。
战争，惯经，草木也知名姓。
《虎韬》，《豹韬》，一览胸中了。
时时拂拭旧弓刀，却恨封侯早。
夜月饶歌，春风牙纛，看团花锦战袍。
鬓毛，未雕，谁便道冯唐老？同文子方、邓永年泛洞庭湖，宿凤凰台下月明，浪平，看远岸秋沙净。
轻舟漾漾水澄澄，天水明如镜。
范蠡归舟，张骞游兴，在渔歌三四声。
耳清，体轻，漫不省干坤剩。
舞者，唱者，满酌金荷叶。
珠围翠绕尽豪奢，银烛消残夜。
玉箸冰丝，金盘凉蔗，把平生幽愤写。
笑些，俏些，赛一道鸳鸯社。
有钱，有权，把断风流选。
朝来街子几人传，书记还平善。
兔走如棱，乌飞如箭，早秋霜两鬓边。
暮年，可怜，乞食在歌姬院。
耍些，笑些，休放琼花谢。
春风无与比奇绝，照眼明香雪。
琪树瑶林，寒光相射，争教人容易舍。
醉也，去也，更得得捱今夜。
饯别，去也，泪滴满金蕉叶。
西风锦树老了胡蝶，满眼黄花谢。
今日离筵，明朝客舍，把骊驹莫放彻。
醉者，饱者，免孤负重阳节。
粉光，雪香，是水月观音像。
三生梦绕锦鸳鸯，一味风流况。
坐上闲情，樽前清唱，是司空也断肠。
月凉，夜长，心事满流苏帐。
近来，越呆，能捻帮穷□怪。
从人ㄋ噪放狂乖，不似今番煞。
海样情缘，天来欢爱，罄山赀不当灾。
好杯，放开，大打算风魔债。
愿天，可怜，乞个身长健。
花开似锦酒如川，日日西湖宴。
杨柳宫眉，桃花人面，是平生未了缘。
过船，醉眠，还不迭风流愿。
画船，绮筵，红翠乡中宴。
荷花人面两婵娟，花不如人面。
锦绣千堆，繁华一片，是西湖六月天。
扣舷，采莲，怕什么鸳鸯见。
瘿瓢，带糟，将瓮里浮蛆舀。
氲氲双颊绛云潮，春色添多少。
稚子牵衣，山妻迎笑，急投床脚健倒。
醉了，睡好，醉乡大人间小。','',''),('yuanqu-648','中吕・满庭芳自悟','刘时中','yuanqu','','','花愁色胆，其中识破，就里曾参。
雨云情到底皆虚泛，可暂休贪。
撮艳处从今怕揽，闹篮中情愿妆憨。
这其间实心谈，一任傍人笑俺，再不将风月话儿谈。
狂踪怪胆，索一奉十，暮四朝三。
喜孜孜笑脸儿将人赚，就里虚耽。
白茫茫蓝桥水淹，黑洞洞袄庙云缄。
赤紧地他愚滥，情疏意淡，再不将风月担儿担。','',''),('yuanqu-649','中吕・山坡羊与邸明谷孤山游饮','刘时中','yuanqu','','','诗狂悲壮，杯深豪放，恍然醉眼千峰上。
意悠扬，气轩昂，天风鹤背三千丈，浮生大都空自忙。
功，也是谎；名，也是谎。
燕城述怀云山有意，轩裳无计，被西风吹断功名泪。
去来兮，便休提，青山尽解招人醉，得失到头皆物理。
得，他命里；失，咱命里。
西湖醉歌，次郭振卿韵朝朝琼树，家家朱户，骄嘶过沽酒楼前路。
贵何如？贱何如？六桥都是经行处，花落水流深院宇。
闲，天定许；忙，人自取。
怀长沙，次郭振卿韵西楼高处，东城佳处，梦魂长绕湘南路。
锦鳞无，塞鸿疏，大都来只为虚名误，老未得闲心更苦。
杯，谁共举？花，谁共主？怀武昌，次郭振卿韵烟波渔父，扁舟归去，移定鹦鹉洲边住。
任狂疏，恣痴愚，到头也有安排处，青箬绿蓑为伴侣。
闲，也自取；忙，也自取。
侍牧庵先生西湖夜饮微风不定，幽香成径，红云十里波千顷。
绮罗馨，管弦清，兰舟直入空明镜，碧天夜凉秋月冷。
天，湖外影；湖，天上景。','',''),('yuanqu-650','越调・寨儿令','刘时中','yuanqu','','','夜已阑，灯将灭，纱窗外昏擦刺月儿斜。
越求和越把个身子儿趄。
耳轮儿做死的扯。
吃敲才胼定也，子怕你悔去也。','',''),('yuanqu-651','双调・折桂令农','刘时中','yuanqu','','','想田家作苦区区，有斗酒豚蹄，畅饮歌呼。
瓦钵瓷瓯，村箫社鼓，落得妆愚。
吾将种牵衣自舞，妇秦人击缶相娱。
儿女供厨，仆妾扶舆，无是无非，不乐何如？渔鳜鱼肥流水桃花，山雨溪风，漠漠平沙。
箬笠蓑衣，笔床茶灶，小作生涯。
樵青采芳洲蓼牙，渔童薪别浦兼葭。
小小渔船，泛宅浮家，一舸鸱夷，万顷烟霞。
樵正山寒黄独无苗，听斤斧丁丁，空谷潇潇。
有涧底荆薪，淮南丛桂，吾意椹樵。
赤脚婢香粳旋捣，长须奴野菜时挑。
云暗山腰，水Ё溪桥，日暮归来，酒满山瓢。
牧被野猿山鸟相留，药解延年，草解忘忧。
土木形骸，烟霞活计，麋鹿交游。
闷来访箕山许由，闲时寻崧顶丹丘。
莫莫休休，荡荡悠悠，挈子携妻，老隐南州。
疏斋同赋木犀似娟娟日暮娥皇，翠袖天寒，静倚修篁。
怅望夫君，低回掩抑，淡尽啼妆。
贴体衫儿淡黄，掩胸诃子金装。
高洁幽芳，一片秋光，满地清香。
同文子方饮南城即事锁烟霞曲径萦回，梦不到人间，舞榭歌台。
铅鼎丹砂，玄霜玉杵，钟乳金钗。
记画烛清樽夜来，映梨花淡月闲斋。
翠壁丹崖，流水桃源，古木天台。
送王叔能赴湘南廉使正黄尘赤日长途，便雷奋天池，教雨随车。
把世外炎氛，人间热恼，一洗无余。
展洙泗千年画图，纳潇湘一道冰壶。
报政何如？风动三湘，霜满重湖。
喜潇湘一派澄清，觉松柏坚贞，兰蕙芳馨。
田里歌谣，官曹整暇，牒诉轻平。
快野寺寻春酒醒，喜邮亭问俗诗成。
传语湘灵，又只恐东风，吹上瑶京。
闲居自适饷春睛小小蓝舆，聊唤茅柴，试买溪鱼。
村北村南，山花山鸟，尽意相娱。
与农父忘形尔汝，醉归来不记谁扶。
早赋归欤，却恨红尘，不到吾庐。
张肖斋总管席间小亭轩客散留髡，添酒回灯，草草盘飧。
问甚花落花开，春来春去，覆雨翻云。
莫孤负田家瓦盆，且留边茅舍洼樽。
选甚清浑，论甚朝昏，擗掉会闲里光阴，醉里干坤。
再过村肆酒家无双丫十八鬟儿，春日当垆，袅袅腰肢。
徙倚心招，依稀眉语，记得前时。
探锦囊都无酒赀，恨邮亭不售新诗。
可惜胭脂，转首空枝，千里关山，一段相思。','',''),('yuanqu-652','双调・清江引','刘时中','yuanqu','','','春光荏苒如梦蝶，春去繁华歇。
风雨两无情，庭院三更夜，明日落红多去也。','',''),('yuanqu-653','双调・庆东原题情','刘时中','yuanqu','','','云轻散，月易残，女萧何成败了些风流汉。
冯魁硬铲，双渐紧赶，小姐先碾。
今夜惜花心，明月伤春叹。','',''),('yuanqu-654','双调・殿前欢','刘时中','yuanqu','','','醉翁酡，醒来徐步杖藜拖。
家童伴我池塘坐，鸥鹭清波。
映水红莲五六科，秋光过，两句新题破。
秋霜残菊，夜雨枯荷。
醉颜酡，太翁庄上走如梭。
门前几个官人坐，有虎皮驮驮。
呼王留唤伴哥，无一个，空叫得喉咙破。
人踏了瓜果，马践了田禾。
道情醉颜酡，水边林下且婆娑。
醉时拍手随腔和，一曲狂歌。
除渔樵那两个，无灾祸，此一着谁参破？南柯梦绕，梦绕南柯。
醉颜酡，前贤不醉我今何？古来已错今犹错，世事从他。
楚三闾葬汨罗，名犹播，谁在高唐卧？巫娥梦我，我梦巫娥。
醉颜酡，云娘行酒雪儿歌，醉时吟狂时舞醒时坐。
不醉如何？得快活且快活。
今日个，只得随缘过。
恋眼前富贵，看门外风波。','',''),('yuanqu-655','双调・雁儿落过得胜令送别','刘时中','yuanqu','','','和风闹燕莺，丽日明桃杏。
长江一线平，暮雨千山静。
载酒送君行，折柳系离情。
梦里思梁苑，花时别渭城。
长亭，咫尺人孤另；愁听，阳关第四声。
东山仰谢安，秋水思张翰。
长沙屈贾谊，落日悲王粲。
坐上酒初残，灯下剑空弹。
马援标铜柱，班超指玉关。
遥看，明月钱塘岸；云间，山头更有山。
题和靖墓西湖避世乖，东阁偿诗债。
遨游天地间，放浪江湖外。
读易坐书斋，策杖步苍苔。
酒饮方拚醉，诗成且放杯。
渐渐梅开，独立黄昏待。
暗暗香来，清闲处土宅。
套数。','',''),('yuanqu-656','正宫・端正好上高监司','刘时中','yuanqu','','','众生灵遭磨障，正值着时岁饥荒。
谢恩光，拯济皆无恙，编做本词儿唱。','',''),('yuanqu-657','滚绣球・去年时正插秧，天反常，那里取若时雨降？旱魃生四野灾伤。谷','刘时中','yuanqu','','','不登，麦不长，因此万民失望，一日日物价高涨。
十分料钞加三倒，一斗粗粮折四量，煞是凄凉。','',''),('yuanqu-658','倘秀才・殷实户欺心不良，停塌户瞒天不当，吞象心肠歹伎俩。谷中添秕','刘时中','yuanqu','','','屑，米内插粗糠，怎指望他儿孙久长。','',''),('yuanqu-659','倘秀才・或是捶麻柘稠调豆浆，或是煮麦撮稀和细糠，他每早合掌擎拳谢','刘时中','yuanqu','','','上苍。
一个个黄如经纸，一个个瘦似豺狼，填街卧巷。','',''),('yuanqu-660','滚绣球・偷宰了些阔角牛，盗斫了些大叶桑。遭时疫无棺活葬，贱卖了些','刘时中','yuanqu','','','家业田庄。
嫡亲儿共女，等闲参与商。
痛分离是何情况！乳哺儿没人要撇入长江。
那里取厨中剩饭杯中酒，看了些河里孩儿岸上娘，不由我不哽咽悲伤！。','',''),('yuanqu-661','倘秀才・私牙子船湾外港，行过河中宵月郎，则发迹了些无徒米麦行。牙','刘时中','yuanqu','','','钱加倍解，卖面处两般装，昏钞早先除了四两。','',''),('yuanqu-662','滚绣球・江乡相，有义仓，积年系税户掌。借贷数补答得十分停当，都侵','刘时中','yuanqu','','','用过将官府行唐。
那近日劝粜到江乡，按户口给月粮。
富户都用钱买放，无实惠尽是虚桩。
充饥画饼诚堪笑，印信凭由却是谎，快活了些社长知房。','',''),('yuanqu-663','伴读书・磨灭尽诸豪壮，断送了些闲浮浪。抱子携男扶筇杖，是赢伛偻如','刘时中','yuanqu','','','虾样。
一丝好气沿途创，阁泪汪汪。','',''),('yuanqu-664','谢金莲诗酒红梨花・仙吕/点绛唇','张寿卿','yuanqu','','','恰才个满目繁华，可又早落红飞下，春潇洒。
苔径轻踏，香衬凌波袜。','',''),('yuanqu-665','谢金莲诗酒红梨花・混江龙','张寿卿','yuanqu','','','则在夕阳西下，黄昏啼杀后栖鸦。
看一庭花月，几缕烟霞。
暮雨有情沾杏蕊，春风无处不杨花。
我裙拖翡翠，鞋蹙鸳鸯，行过低矮矮这个荼藤架。
我则见花穿曲径，草接平沙。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-666','谢金莲诗酒红梨花・油葫芦','张寿卿','yuanqu','','','秀才每从来我羡他，提起来偏喜恰，攻书学剑是生涯。
秀才每受辛苦下载寒窗下，久后他显才能一举登科甲。
秀才每习礼义，学问答。
哎，你一个小梅香今后休奸诈，只说那秀才每不当家。
(梅香云)秀才每几时能勾发达？(正旦唱)。','',''),('yuanqu-667','谢金莲诗酒红梨花・天下乐','张寿卿','yuanqu','','','你岂知他那有志题桥汉司马，怎不教人嗔怒发，是和非你心中自临察。
端的个无礼法，只管里抵触咱，梅香你记着我这一顿打。','',''),('yuanqu-668','谢金莲诗酒红梨花・那吒令','张寿卿','yuanqu','','','这妮子我问着呵，没些儿个势沙；这妮子道着呵，将话儿对答；这妮子使着呵，早装聋做哑。
泼贱才，堪人骂，再休来利齿能牙。
(梅香云)我说甚的来？(正旦唱)。','',''),('yuanqu-669','谢金莲诗酒红梨花・寄生草','张寿卿','yuanqu','','','我这里从头说，你那里试听咱。
有吴融八韵赋自古无人压，有杜甫五言诗盖吐人惊讶，有李白一封书吓的那南蛮怕。
你只说秀才无路上云霄，却不道文官把笔平天下。','',''),('yuanqu-670','谢金莲诗酒红梨花・后庭花','张寿卿','yuanqu','','','俺将俏书生去问他，又怕这劣梅香瞧见咱。
俺这里有意传心事，他那里无言指落花。
争奈我是女孩儿家，做这一场活靶，可不的被傍人活笑杀。','',''),('yuanqu-671','谢金莲诗酒红梨花・金盏儿','张寿卿','yuanqu','','','这秀才忒撑达，将我问根芽。
妾身住处兀那东直下，深村旷野不堪夸。
俺那里遮藏红杏树，掩映碧桃花。
兀良山前五六里，林外两三家。
(赵汝州云)小娘子，你端的谁氏之家？(正旦云)妾身是王同知之女，今夜晚间，因看花来到太守花园里，不想遇着秀才。
敢问秀才姓甚名谁？(赵汝州云)小生是太守相公的表弟赵汝州是也。
小娘子既到此处，到我书房中饮几杯，有何不可？(正旦云)既然如此，同到书房中攀话去咱。
(做进书房科)(赵汝州云)小娘子不嫌亵渎，请满饮一杯。
(正旦云)秀才请。
(赵汝州云)难得小娘子到此，多饮几杯。
(正旦唱)。','',''),('yuanqu-672','谢金莲诗酒红梨花・醉中天','张寿卿','yuanqu','','','笑哈哈捧流霞，我羞怯怯怎酬答。
也不知前世今生甚的缘法，相会在花枝下。
可知道刘郎喜杀，又值着我玉真未嫁，抵多少香饭胡麻。
(赵汝州云)小娘子，今夜幸得相会，但不知后会何时？实难为别。
(正旦云)妾明夜晚间，将一樽酒一瓶花，与秀才回礼。
(赵汝州云)小生来日晚间专望也。
(正旦唱)。','',''),('yuanqu-673','谢金莲诗酒红梨花・南吕/一枝花','张寿卿','yuanqu','','','花梢月正高，院宇人初静。
为怜才子约，嫌煞月儿明。
俺忍怕耽惊，俏俏的穿芳径。
怕人来更犬惊，花阴里蹑足行行，柳影中潜身等等。','',''),('yuanqu-674','谢金莲诗酒红梨花・梁州第七','张寿卿','yuanqu','','','不离了这花阴柳影，也强如绣帏中冷冷清清。
想才郎没半米儿尘俗性。
他比着那谢东山后嗣，杜工部门生，潘安仁颜貌，曹子建才能，他生的才貌相应。
虽不设海誓山盟，他、他、他，端的有千种风情，俺、俺、俺，办着个十分志诚，敢、敢、敢，成合了一世的前程。
对着这良宵，媚景。
玉纤重把罗衣整，露湿的绣鞋儿冷。
绕遍园池过小亭，怎敢稍停？。','',''),('yuanqu-675','谢金莲诗酒红梨花・隔尾','张寿卿','yuanqu','','','我为甚商抄过绿径慌忙迸，我则怕迟到蓝桥淹了尾生。
则这窃玉偷香的急心性。
冷落了那画屏，香消了宝鼎，这其间倚定鸳鸯枕头儿等。
(梅香云)姐姐，可早来到也。
俺和你过去。
(赵汝州慌迎科，云)小娘子来了也。
(正旦云)秀才，妾身无甚么礼物，则这一樽酒一瓶花儿，朵与你回礼。
(赵汝州云)小娘子，小生久等多时了也。
(正旦云)梅香，你先回去。
则怕夫人问着，你可支吾咱。
(梅香云)理会得，我先回去也。
(下)(正旦云)秀才，你认的这瓶花么？(赵汝州云)小娘子，这瓶花是甚么花？(正旦云)你试猜咱。
(赵汝州云)敢是海棠花么？(正旦唱)。','',''),('yuanqu-676','谢金莲诗酒红梨花・哭皇天','张寿卿','yuanqu','','','待道是海棠呵杜子美无诗兴，(赵汝州云)敢是桃花么？(正旦唱)若是桃花呵怕阮肇却早共你争。
(赵汝州云)敢是石榴花么？(正旦唱)那石榴花夏月开，这其间未过清明。
(赵汝州云)敢是山茶花么？(正旦唱)若论山茶花却是冬暮景，(赵汝州云)敢是刺梅花么？(正旦唱)刺梅花初开未盛。
(赵汝州云)敢是碧桃花么？(正旦唱)若说着碧桃花，那里讨墙外谁家凤吹声。
(赵汝州云)我也猜不着。
(正旦唱)枉将伊侯幸，说与你便省。','',''),('yuanqu-677','谢金莲诗酒红梨花・乌夜啼','张寿卿','yuanqu','','','这的是一朵红梨花，休猜做枯枝杏，恰便似佳人面晕微醒。
他三春独掌着花权柄，枝叶儿青青，颜色儿荧荧。
且休说四季牡丹亭，更休过黄花径。
这花与灯，偏相称，灯光闪烁，花影轻盈。
(赵汝州云)小娘子，既有如此好花，何不作一首诗？(正旦云)我单提着红梨花作诗一首。
(赵汝州云)小娘子，你就表白咱。
(正旦念诗科，云)本分天然白雪香，谁知今日却浓妆？秋千院落溶溶月，羞睹红脂睡海棠。
(赵汝州云)妙、妙、妙。
小生也做一首。
(念诗科，云)换却冰肌玉骨胎，丹心吐出异香来。
武陵溪畔人休说，只恐夭桃不敢开。
(正旦云)好高才也。
(唱)。','',''),('yuanqu-678','谢金莲诗酒红梨花・贺新郎','张寿卿','yuanqu','','','听绝诗句猛然惊，早是他内性儿聪明，才调儿清正。
这两般消的人钦敬，不枉了风流俊英。
诗提着花酒为名，花娇如玉软，酒色似冰清。
世间花酒济人兴，洒斟金潋滟，花列玉娉婷。
(赵汝州云)对这好花好酒，又好良夜，知音相遇，岂不美哉。
(正旦唱)。','',''),('yuanqu-679','谢金莲诗酒红梨花・四块玉','张寿卿','yuanqu','','','我剔的这灯焰儿光，那的这花瓶儿正。
我对着这烛底花前说叮咛，则愿的灯休灭花休谢人休另。
这知音人存着志诚，似花枝常在瓶，似灯儿分外明。','',''),('yuanqu-680','谢金莲诗酒红梨花・感皇恩','张寿卿','yuanqu','','','嬷嬷也老不以筋力为能，咱须是负屈高声。
俺赏的这上阳花，饮的这长寿酒，烧的这短檠灯。
正是银河耿耿，玉器泠泠，对着那一轮月，千里风，满大星。','',''),('yuanqu-681','谢金莲诗酒红梨花・采茶歌','张寿卿','yuanqu','','','俺从那期程，伴着这书生，直吃的碧桃花下月三更。
你个嬷嬷夫人心休硬，便有合该罪犯俺招承。','',''),('yuanqu-682','谢金莲诗酒红梨花・一煞','张寿卿','yuanqu','','','你休愁我衾寒枕剩人孤另，我则怕你酒醒灯昏梦不成，佳期漏泄无干净。
慌出兰堂，四下眶天如悬镜。
夜气扑人冷，一片闲云近玉绳，空余着银汉澄澄。','',''),('yuanqu-683','谢金莲诗酒红梨花・尾煞','张寿卿','yuanqu','','','我把一枝翠柳将身映，(赵汝州云)小娘子，你可仔细走。
(正旦唱)这里不比十二瑶台独自行。
曲栏傍月光净，粉墙边晚风劲。
(云)呀，兀的不有人来也。
(唱)只听的扑簌簌鞋底鸣，唬的我颤兢兢手脚冷。
俺只索止安身躯注着眼睛，(带云)原来不是人呵。
(唱)可正是云破月来花弄影。
(下)。','',''),('yuanqu-684','仙吕・寄生草酒色财气','范康','yuanqu','','','常醉后方何碍，不醉时有甚思。
糟腌两个功名字，醅淹千古兴亡事，曲埋万丈虹霓志。
不达时皆笑屈原非，但知音尽说陶潜是。
花尚有重开日，人决无再少年。
恰情欢春昼红妆面，正情浓夏日双飞燕，早情疏秋暮合欢扇。
武陵溪引入鬼门关，楚阳台驾到森罗殿。
绿珠娇人无比，石崇富祸有余。
全家儿老幼遭诛戮，半合儿帑藏无金玉，两般儿景物伤情绪。
暗尘埋锦步障花边，乱蝉鸣金谷园中树。
形骸随红尘化，功名向青史标。
七英雄事业真堪笑，六豪王踪迹平如扫，两下里争战图前闹。
一壁厢淡烟衰草霸王城，一壁厢西风落日高皇庙。
套数。','',''),('yuanqu-685','双调・新水令乐道','范康','yuanqu','','','老来方知幼时非，急省悟半途之际。
明明的添寿算，暗暗的减容仪。
白发相催，全不似少年日。','',''),('yuanqu-686','驻马听・日月如飞，急急光阴如逝水；去年今日，看看故友眼前稀。想藏','范康','yuanqu','','','阄打马都成非，思包商吟咏成何济，何所宜，都不如保全一点元阳气。','',''),('yuanqu-687','乔牌儿・叹光阴如过隙，百年人旅中寄。被宿生冤债将身累。今日还了他','范康','yuanqu','','','方利己。','',''),('yuanqu-688','沉醉东风・从教师诗书颇习，参释道性命根基。杏林中作生涯，橘井内为','范康','yuanqu','','','活计。
炼玄元象帝幽微。
有一日三岛十洲将名姓题，抵多少一官半职。','',''),('yuanqu-689','雁儿落・一心待悟真常修物理，萦方寸绝名利，离尘寰远世交，游阆苑达','范康','yuanqu','','','仙契。','',''),('yuanqu-690','得胜令・呀！我如今参透静中奇，识破动中机。人我山为平地，是非海波','范康','yuanqu','','','浪息。
莫待要呆痴，将意马心猿系。
休纵放奔驰，现一轮皓月辉。','',''),('yuanqu-691','折桂令・现一轮皓月光辉，朗朗圆明，无缺无亏，恰一气才分，二仪初判，','范康','yuanqu','','','早三姓支离。
生共死有几人悟得，死与生何处归依。
奥妙玄微，不索猜疑。
若吞却一粒金丹，怕甚么六道轮回。','',''),('yuanqu-692','离亭宴煞・诵《南华》讲《道德》，谈《周易》见天心，察地利明人事，','范康','yuanqu','','','须持心炼已。
分宾主，定浮沉；辨疏亲，识老嫩；通造化，别真伪。
晓屯蒙否泰交，知消长盈虚意。
甚的是先天至极？打破了太虚空，便是那出世超凡大道理。','',''),('yuanqu-693','陶学士醉写风光好・仙吕/点绛唇','戴善甫','yuanqu','','','凭着我雾鬓云鬟，黛眉星眼，寻衣饭。
则向这酒社诗坛，多少家乔公案。','',''),('yuanqu-694','陶学士醉写风光好・混江龙','戴善甫','yuanqu','','','悲欢聚散，二三年经到有百千番。
恰东楼饮宴，早西出阳关。
兀的般弄月嘲风留客所，便是俺追欢买笑望夫山。
这些时迎新送旧，执盏擎盘。
怎倒颤钦钦惹的我心儿惮。
怕只怕是那罗纰锦旧，莺老花残。','',''),('yuanqu-695','陶学士醉写风光好・后庭花','戴善甫','yuanqu','','','那学士若见了南唐秦弱兰，更不说西京白牡丹。
则消得我席上歌金缕，管取他尊前倒玉山。
(韩熙载云)劝的他尽醉，要他十分欢喜。
(正旦唱)要欢喜不为难，则着这星眸略瞬盼，教他和骨头都软瘫。','',''),('yuanqu-696','陶学士醉写风光好・金盏儿','戴善甫','yuanqu','','','我这里觑容颜，待迫攀。
嗨！畅好是冷丁丁沉默默无情汉。
则见那冬凌霜雪都堆在两眉间，恰便似额颅上挂着紫塞，鼻凹里倘着蓝关。
可知道秀才双脸冷，宰相五更寒。','',''),('yuanqu-697','陶学士醉写风光好・醉中天','戴善甫','yuanqu','','','他教莫把瑶筝按，只许凤箫闲。
他道是何用霓裳翠袖弯，更休撒红牙板。
不教放筵前过盏，几时得酒阑人散？直恁般见不得歌舞吹弹。
(韩熙载云)俗语云：座上若有一点红，斗筲之器盛千钟。
座上若无油木梳，烹龙炮凤总成虚。
弱兰与学士递一杯。
(正旦把盏科)(陶谷怒云)泼贱人靠后，小官一生不吃妇人手内饮食。
(韩熙载云)学士饮一杯，怕做甚么？岂不闻将酒劝人，终无恶意。
何怒之有？学士也与他接谈，略抬眼重他一看波。
直恁般的，弱兰递酒。
(正旦递酒科)(陶谷云)靠后！小官乃孔门弟子，放郑声，远佞人。
郑声淫，佞人殆。
小官平生目不视邪色，耳不听淫声。
太守何故三回五次，侮弄小官，是何道理？(正旦唱)。','',''),('yuanqu-698','陶学士醉写风光好・金盏儿','戴善甫','yuanqu','','','他不把话头攀，唬的我毛骨寒，战兢兢把不住台和盏。
我这里承欢奉喜两三番。
太守见我退后来早台意怒，学士见我向前去早恶心烦。
好教我左右没是处，来往做人难。','',''),('yuanqu-699','陶学士醉写风光好・后庭花','戴善甫','yuanqu','','','学士你只身在旅邸间，着个甚罗帏锦帐单。
学士你德行如颜子，也索要风流仿谢安。
我劝你且开颜，须不比寻常风范。
你敢越聪明越挂眼。
(陶谷云)兀那妇人靠后。
我头顶儒冠，身穿儒服，乃正人君子。
不得无礼。
(正旦退科)(韩熙载云)歌者，可再劝酒。
(陶谷云)太守，小官酒醉失礼。
李太白有诗云："我醉欲眠君且去，明朝有意抱琴来。
"我待睡些儿咱。
(做醉睡科)(韩熙载云)学士醉了也。
您歌者且回去。
(正旦云)理会的。
(唱)。','',''),('yuanqu-700','陶学士醉写风光好・赚煞','戴善甫','yuanqu','','','几时捱得酒筵阑，官员散，恨不得目下天昏日晚。
唬的那舞女歌儿似受战汗，难施逞乐艺熟闲。
(韩熙载云)弱兰，则要你小心在意者。
(正旦唱)这其间，春意相关，放着满眼芳菲纵心儿拣。
争奈这寻芳人意懒，嬉游的心慢。
哎！不是个惜花人休想肯凭栏。
(众随下)。','',''),('yuanqu-701','陶学士醉写风光好・梁州第七','戴善甫','yuanqu','','','他则是惯受用玉堂金马，不思量月户云窗。
则他那古忄敞心甚的唤做鸣珂巷，空那般衣冠济济，状貌堂堂。
却为甚偏嫌俺妓女，怕见婆娘？莫不他净了身不辨阴阳？人道这秀才每都不荒唐，偏怎那洞庭湖柳毅传书，谢家庄崔护觅浆，贾充宅韩寿偷香。
想我那往常，伎俩，播弄的子弟如翻掌。
这个铁卧单我怎窝藏？我自寻思出这个风流俏智量，须要今夜成双。','',''),('yuanqu-702','陶学士醉写风光好・贺新郎','戴善甫','yuanqu','','','他去那无人处独步也气昂昂。
这公则是阔论高谈，那里知浅斟低唱。
我这里潜身躯迸定脸凝睛望：端的是风清月朗，可甚么软玉温香。
(陶谷望北斗顶礼做笑科，云)月色团圆也。
(正旦唱)他这般更深离馆舍，夜静步回廊。
(陶谷吟诗云)月中桂子宜攀折，苑内凡花不耐看。
(正旦唱)我猜他莫不劳魂役梦胡思想。
(陶谷云)魏武帝有诗曰："月明星稀，乌鹊南飞。
绕树三匝，无枝可依。
"看来正是小官。
(正旦唱)原来他望天瞻北斗，却不肯和月待西厢。
(云)梅香，我烧罢香回去，对此月色，口占一诗。
(念科，云)"隔窗疏雨送秋声，夜夜愁人睡不成。
遇此良宵多感慨，清风明月又关情。
"(陶谷云)原来有人在柳阴深处吟诗。
我过去看咱。
(正旦云)梅香，咱回去来。
(陶谷云)小娘子勿罪。
(正旦拜科)(陶谷云)一个好女子也。
小娘子高姓，谁氏之家，因甚在此官舍之中？(正旦唱)。','',''),('yuanqu-703','陶学士醉写风光好・牧羊关','戴善甫','yuanqu','','','俺夫主为驿吏身姓张。
(陶谷云)元来是驿吏的妻子。
你是那里人氏？(正旦唱)生长在雨浙苏杭。
(陶谷云)如今你丈夫那里去了？(正旦唱)怎想他半路里情绝，他从那二年前身丧。
(陶谷云)小娘子怎生在此住坐？(正旦唱)妾身见如今独自个持着服孝。
(陶谷云)你多大年纪持服来。
(正旦唱)我从二十六上守孤孀。
(陶谷云)敢问小娘，为何这早晚对月吟诗？(正旦云)我自释闷而已，那里是诗。
(唱)我也则诗句内题秋景，月明中烧夜香。','',''),('yuanqu-704','陶学士醉写风光好・隔尾','戴善甫','yuanqu','','','我则道他喜居苦志颜回巷，却元来爱近多情宋玉墙。
这搭儿厮叙的言问那停当。
想昨日在坐上，那些儿势况，苫眼铺眉尽都是谎。','',''),('yuanqu-705','陶学士醉写风光好・牧羊关','戴善甫','yuanqu','','','你见我心先顺随了，你可不气长。
有句话须索商量：你休将容易恩情，等闲撇漾。
(陶谷云)他日你做夫人县君哩。
(正旦唱)我等驷马车为把定物，五花诰是撞门羊。
你明日北去人千里，早变做南柯梦一场。','',''),('yuanqu-706','陶学士醉写风光好・三煞','戴善甫','yuanqu','','','我看了高才词翰华笺上，却为甚不肯烂醉佳人锦瑟傍？可知我把小未的郎君放。
他兀的锦绣文章，更做着皇家卿相，被我着个小局段儿早打入天罗网。
看这公古忄敞性从来无些雅况，我试与满捧瑶觞。','',''),('yuanqu-707','陶学士醉写风光好・二煞','戴善甫','yuanqu','','','你这般当歌对酒销金帐。
煞强如扫雪烹茶破草堂。
你许下我的休教无承望。
此别后水远山长，把美缱绻则怕贵人多忘，则要你经板儿印在心上。
当日也是我在尊前不容近傍，假妆好人家便引动情肠。','',''),('yuanqu-708','陶学士醉写风光好・煞尾','戴善甫','yuanqu','','','我想这歌台舞袖风流相，怎如大院深宅窈窕娘。
也得今朝，这-场。
想官司，也不枉。
共学士，有情况。
再开筵，敢说强。
〔风光好〕，是招状。
我明白，太守行，决将咱，断觑当。
我把那段疋绫罗不希望。
我本不乐作娼，则向那烟花簿上勾抹了我的名儿胜如赏。
(下)。','',''),('yuanqu-709','陶学士醉写风光好・正宫/端正好','戴善甫','yuanqu','','','总然你富才华，高名分，谁不爱翠袖红裙。
你看这般东风桃李香成阵，犹兀自难遣东君恨。','',''),('yuanqu-710','陶学士醉写风光好・滚绣球','戴善甫','yuanqu','','','人都道秀才每村，不会将女色亲。
他每则是识廉耻正心不肯，但出语也做的个郎君。
假若是夸谈俺好妇人，则着些俗言语便不真。
他每用文章也道的来淹润，则着两句诗说尽精神。
裙拖六幅湘江水，髻挽巫山一段云，休道不消魂。','',''),('yuanqu-711','陶学士醉写风光好・倘秀才','戴善甫','yuanqu','','','昨夜个横着片风月胆房中那亲，今日个幽。','',''),('yuanqu-712','陶学士醉写风光好・叨叨令','戴善甫','yuanqu','','','学士写时节有些腔儿韵，妾身讴时节有些词儿顺。
(陶谷云)不知是何等无知之人，做下此等语句？(正旦唱)做时节难诉千般恨，写时节则是三更尽。
(旦拜陶科，唱)学士你记得也么哥，你记得也么哥，(出词科，唱)兀的是亲笔写了牢收顿。
(陶谷怒云)这个泼烟花赃诬人。
我那里与你会面来？(正旦云)妾身不敢。
昨夜蒙大人错爱。
(唱)。','',''),('yuanqu-713','折桂令・问苏卿','王晔','yuanqu','','','俏排场惯战曾经，自古惺惺，爱惜惺惺。
燕友莺朋，花阴柳影，海誓山盟。
哪一个坚心志诚？哪一个薄幸杂情？则问苏卿，是爱冯魁，是爱双生？答平生恨落风尘，虚度年化，减尽精神。
月枕云窗，锦衾绣褥，柳户花门。
一个将百十引江茶问肯，一个将数十联诗句求亲。
心事纷纭：待嫁了茶商，怕误了诗人。','',''),('yuanqu-714','水仙子・','王晔','yuanqu','','','驳明明的退佃丽春园，暗暗的开除了双解元。
惨可可说下神仙愿，却原来都是骗。
再谁听甜句儿留连。
同他行坐，和他过遣，怎做的误走上茶船。
招书生俊俏却无钱，茶客村虔倒有缘。
孔方兄教得俺心窑变，胡芦提过遣，如今是走上茶船。
拜辞了呆黄肇，上复那双解元，休怪俺不赴临川。','',''),('yuanqu-715','折桂令・问双渐','王晔','yuanqu','','','小苏卿窑变了心肠，改抹了姻缘，倒换排场。
强拆鸳鸯，轻分莺燕，失配鸾凰。
实丕丕兜笼富商，虚飘飘蹬脱了才郎。
你试思量，不害相思，也受凄凉。','',''),('yuanqu-716','水仙子・答','王晔','yuanqu','','','阳台云雨暂教晴，金斗风波且慢行。
小苏卿是接了冯魁定，俏书生便噤声。
没来由闲战闲争，非干是咱薄幸。
既然是他浅情，我着甚干害心疼。','',''),('yuanqu-717','水仙子・答','王晔','yuanqu','','','风流双渐惯轮铡，澜浪苏卿能跳塔。
小机关背地里商量下，把俺做皮灯笼看待咱，从来道水性难拿。
从他走过，由他演撒，终只是个路柳墙花。','',''),('yuanqu-718','折桂令・问苏妈妈','王晔','yuanqu','','','苏婆婆常只是熬煎，临逼得孩儿，一谜地胡扇。
使会虚脾，着些甜唾，引起顽涎。
用力的从教气喘，着昏的一任头旋。
只为贪钱，将个婵娟，卖上茶船。','',''),('yuanqu-719','双调・新水令闺情','王晔','yuanqu','','','梨花夜雨未开门，日迟迟绿窗人困。
镜缄鸾未起，香尽鸭犹温。
半晌抬身，舒玉笋整婵鬓。','',''),('yuanqu-720','驻马听・春意犹昏，杨柳青牵绵正滚；香腮微印，海棠横界线留痕。目前','王晔','yuanqu','','','春暖物华新，意中人远天涯近。
怨未伸，枝头春色三色褪。','',''),('yuanqu-721','雁儿落・齐臻臻光消宝髻云，宽绰绰瘦掩罗衫衤肯。碧幽幽天高少雁书，','王晔','yuanqu','','','绿湛湛水阔无鱼信。','',''),('yuanqu-722','得胜令・愁戚戚萧索对清晨，情默默冷落坐黄昏。悄促促翠掩合欢帐，湿','王晔','yuanqu','','','津津红绡拭泪巾。
清黯黯销魂，烟淡淡草际遥天尽。
昏惨惨伤神，夜迢迢花残过雨频。','',''),('yuanqu-723','沽美酒・江分平绿草茵，门半掩翠苔痕。悄悄闲庭不见人，无语自晒，空','王晔','yuanqu','','','目断定楚台云。','',''),('yuanqu-724','太平令・怪则怪鸾凰生分，恼则恼莺燕争春。恨则恨心中有刃，悔则悔言','王晔','yuanqu','','','而无信。
想这厮背恩，负恩，说着后一言难尽。','',''),('yuanqu-725','水仙子・气吁鸾影宝奁昏，愁蹙蛾眉翠黛颦。情随雁足青霄近，倚朱扉欲','王晔','yuanqu','','','断魂。
能消得几个青春？恰透风光一阵。
春来度尽花容数本，春先去人瘦三分。','',''),('yuanqu-726','折桂令・春先去人瘦三分。妆减了半面风流，衣松了一捻精神。步红尘愁','王晔','yuanqu','','','践红芳，上绣榻怕拈绣贴，倚朱扉愁盼朱轮。
海棠困琴闲玉轸，石榴皱睡损罗裙。
愁思昏昏，人事纷纷；眼底卿卿，心上人人。','',''),('yuanqu-727','尾声・来明跪膝儿在床前问，将那厮谎舌头裙刀儿碎刎。先将他抛闪去的','王晔','yuanqu','','','罪名儿一件件招，后把受用过凄凉一星星证了本。','',''),('yuanqu-728','吕洞宾度铁拐李岳・仙吕/点绛唇','岳伯川','yuanqu','','','名分轻薄，俸钱些小，家私暴。
又不会耕种锄刨，倚仗着笞杖徒流绞。','',''),('yuanqu-729','吕洞宾度铁拐李岳・混江龙','岳伯川','yuanqu','','','想前日解来强盗，都只为昧心钱买转了这管紫霜毫。
减一笔教当刑的责断，添一笔教为从的该敲。
这-管扭曲作宜取状笔，更狠似图财致命杀人刀。
出来的都关来节去，私多公少，町曾有一件儿合天道？他每都指出卖磨，将百姓画地为牢。
(吕洞宾做笑科，去)岳寿，你今年今月今日今时，你死也。
(张千做看见科，云)哥哥，有一个风魔先生，哭三声，笑三声，在咱门首闹哩。
(正末怒，云)这先生好无礼也。
他是盆儿，我是罐儿，他敢不知道岳孔目的名儿？我试看咱。
(做见科，云)兀那先生，为甚在我门首，哭三声，笑三声？这是怎说？(吕洞宾云)岳寿，你是个没头鬼，你死也。
(正末云)呸！你看我悔气。
连日接新官不着，来家吃饭，又被这泼先生骂我是没头鬼。
(旦上，云)孔目你不知，孩儿下学来吃饭，被这先生骂孩儿是没爷业种，又骂我是寡妇，好无礼也。
(正末云)大嫂，你家里去，等我问他。
兀那先生，我那孩儿恼着你甚么来？你骂他。
(吕洞宾云)岳寿，没头鬼，你死也，这孩儿就是无爷业种。
(正末云)这泼先生好无礼也，(唱)。','',''),('yuanqu-730','吕洞宾度铁拐李岳・油葫芦','岳伯川','yuanqu','','','你欺负俺孩儿年纪小，出家人厮扇摇，吃的来滴滴邓邓醉陶陶。
门前哭罢门前笑，街头指定街头闹。
孩儿他娘引着，你骂他爷死了。
(吕洞宾云)我是个出家人，你怎生近的我？(正末唱)也不索宫中插状衙中告，(带云)我要禁持你至容易，(唱)只消得二指阔纸提条。','',''),('yuanqu-731','吕洞宾度铁拐李岳・天下乐','岳伯川','yuanqu','','','敢把你拖到官司便下牢，我先教你，省会了你和那打家贼并排压定脚。
祗从人解了你绦，首领每剥了你袍，(带云)休道是先生，(唱)我着你似生驴般吃顿拷。','',''),('yuanqu-732','吕洞宾度铁拐李岳・金盏儿','岳伯川','yuanqu','','','你道是新官正决难逃，俺这旧吏富易通交。
眼见得一官二吏三年了，家私休想落分毫。
他这新官倚俸禄，俺这旧吏靠窠巢。
他这官清司吏瘦，俺这家富小儿娇。','',''),('yuanqu-733','吕洞宾度铁拐李岳・醉扶归','岳伯川','yuanqu','','','你问他在村镇居城郭？(张千云)兀那老子，俺哥哥问你城里住？村里住？(韩魏公云)哥哥，老汉村里也有庄儿，城里也有宅儿。
(张千云)这老头子，硬头硬脑的，正是躲避差徭游食户。
村里寻往城里去。
城里寻往村里去。
你则在这里，我回俺哥哥话去。
(做见正末，云)哥哥，那村老子说：城里也有宅儿，村里也有庄儿。
(正末云)这老子好无礼也，他回我这等话。
张千，你敢问的差了也，你则依着我再问他去。
(唱)你问他当军役纳差徭。
(张千云)兀那老子，俺哥哥着我问你当差是军身？是民户？(韩魏公云)老汉军差也当，民差也当。
因老汉有几文钱，又当站户哩。
(张千云)你军差也当，民差也当，因有钱又当站户？(韩魏公云)是。
(张千云)他是埋头财主。
我回哥哥话去。
(做见正末，云)哥哥，他说军差也当，民差也当，因有钱又当站户哩。
(正末云)噤声！这厮好不干事，跟我这几年了，着这庄家老子使的两头回来走的，你则依着我再问去。
(唱)你问他开铺席为经商可也做甚手作？(张千云)兀那老子，你可开铺席，做经商的，是什么手作？(正末云)张千你再问他。
(唱)你与我审个住处查个名号。
(张千云)他是个庄家老子，只管要问他住处怎的？(正末唱)我多待不的三日五朝，将他那左解的冤仇报。','',''),('yuanqu-734','吕洞宾度铁拐李岳・金盏儿','岳伯川','yuanqu','','','他或是使斗秤拿个大小等个低高，(云)我禁的他么？(张千云)他不卖粮食，开个段子铺儿，你怎生禁他？(正末云)更好奈何他哩。
(唱)或是他卖段匹拣个宽窄觑个纰薄。
(云)我奈何的他么？(张千云)他也不做买卖，每日闭着门，只在家里坐，你怎生奈何他？(正末云)我越好奈何他哩。
(唱)或是他粉壁迟水瓮小拖出来我则就这当街拷。
(张千云)他城里也不住，搬在乡里住，你怎生奈何他？(正末云)我正好奈何他。
(唱)便是他避城中居乡下，我则着司房中勾一遭。
(带云)他来的疾便罢，来的迟呵，加上个顽慢二字。
(唱)我着他便有祸，(带云)他依着我便罢，若不依我呵，我下上个欺官枉吏四个字。
(唱)我着他便违条。
(带云)这老子是下户，我添做中户，是中户我添做上户的差徭。
(唱)我着那挑河夫当一当直穷断那厮筋，(带云)我更狠一狠呵，(唱)我着那打家贼指一指，(带云)轻便是寄脏，重便是知情。
(唱)我直拷折那厮腰。','',''),('yuanqu-735','吕洞宾度铁拐李岳・后庭花','岳伯川','yuanqu','','','怕不初来时妆会幺，看他间深里探会爪。
我见先他见后，他临行我放刁，笑里暗藏刀。
代官来到，不道咱轻放了。','',''),('yuanqu-736','吕洞宾度铁拐李岳・金盏儿','岳伯川','yuanqu','','','有了状但去呵决私逃，停了俸但住呵怎轻饶。
离了官房没了倚靠，绝了左右没了牙爪。
我直着他典了衣卖了马，方见俺心似铁笔如刀。
饶他便会钻天能入地，怎当俺拿住脚放头稍。','',''),('yuanqu-737','吕洞宾度铁拐李岳・赚煞尾','岳伯川','yuanqu','','','赤紧的官长又廉，曹司又拗，我便是好令史怎禁他三遍家取招。
我今日为头便把交，争奈在前事乱似牛毛。
有人若是但论着，休想道肯担饶。
早停了俸追了钱断罢了。
不是我千错万错，大刚来一还一报。
(带云)他道我是大鹏金翅雕。
哎哟！(唱)谁想那百姓每的口也是祸之门，舌是斩身刀。
(下)。','',''),('yuanqu-738','吕洞宾度铁拐李岳・正宫/端正好','岳伯川','yuanqu','','','你装裹我二十重，或是三十件。
(旦云)你置下的合该你穿。
(正末唱)你道是我置下我死合穿，知他土坑中埋我多深浅，装裹杀也无人见。','',''),('yuanqu-739','吕洞宾度铁拐李岳・滚绣球','岳伯川','yuanqu','','','妻也空费你心，你也索听我言。
这衣服呵且休算万针千线，也不论旧絮新绵。
你如今值着业冤，使着死钱。
这衣服但存几件，(旦云)你命也不保留着他做甚么？(正末唱)怕你子母每受穷时典卖盘缠。
比如包尸裹骨棺函内烂，把似遇节迎寒您子母每穿，省可里熬煎。','',''),('yuanqu-740','吕洞宾度铁拐李岳・倘秀才','岳伯川','yuanqu','','','也不索嘱付你千言万言，想着咱同衙府十年五年。
(带云)倘我死之后。
(唱)你是必打听着山妻，照顾着豚犬。
他一头亡了夫主，废了家缘，(带云)您嫂嫂是个年少妇人家，(唱)他从来腼腆。
(孙福云)哥哥放心，便怎生有这等事？(正末唱)。','',''),('yuanqu-741','吕洞宾度铁拐李岳・叨叨令','岳伯川','yuanqu','','','怕有那无廉耻谎汉子胡来缠，(孙福云)嫂嫂不比其他的人。
(正末云)兄弟也，我死之后，有那等谎厮上门来。
(唱)则你那无主意拙嫂嫂从来善，则要你无私曲好兄弟频来见，(带云)你见你那嫂子有不中处，你说不出来呵。
(唱)着你那无面目的婶子儿便将他劝。
(孙福云)着媳妇子劝些甚么？(正末云)着婶子劝道：姆姆，俺伯伯是人面上的人，你要爱惜行止。
(唱)着言语劝他也么哥，着语劝他也么哥，岂不闻临危好与人方便？。','',''),('yuanqu-742','吕洞宾度铁拐李岳・倘秀才','岳伯川','yuanqu','','','或是祭先祖逢冬遇年，(云)到那冬年时节，月一十五，孩儿又小，上坟呵，大嫂，你可出去见人么？(旦云)我不去，着张千引着孩儿坟上烧纸便了。
(正末云)这个且罢。
(唱)或是待亲戚排筵坐筵，(云)福童孩儿娶媳妇，六亲相识每吃筵席，你不出去支待，着谁支待？(旦云)若有女客来，我便支待，若有男客来，着张千支待罢。
(正末云)大嫂，若有呵。
(唱)非五服内男儿不曾教见一见？则为你有人材多娇态，不老相正中年，(带云)我死之后。
(唱)你休忘了大人家体面。','',''),('yuanqu-743','吕洞宾度铁拐李岳・滚绣球','岳伯川','yuanqu','','','你必索迎门儿接纸钱，(旦云)孔目也，你直恁般多心。
我着张千领着孩儿出去迎接，我只不见人便了。
(正末云)可早一桩儿也，这个也罢。
我死之后，停到一七者波，便停到二七者波，想着咱二十年儿女夫妇，你没的不送我到郊外。
(唱)又索随灵车哭少年，(云)有那等年纪小的后生便道：岳孔目有个好浑家。
三门四户不出，无人能勾得见，今日出来送岳也目的殡，咱看去来。
(唱)那其间任谁都见，(带云)见了你这个中注模样，(唱)有那等厮图谋的贼汉心专。
(云)有那谎汉每便道：这个是岳孔目的浑家。
我久已后，好歹要娶了他。
(唱)俺亲眷行除孝服，你爷娘行使会钱，(带云)俺的亲眷，你的爷娘，都肯了，只你不肯。
(唱)他与你些打眼目的衣服头面，(云)你见了好衣服，好头面，那里还想我哩。
(旦云)孔目也，我坚心守志，怎生肯嫁别人？(正末唱)你便守熬呵刚捱到服满三年。
你嫁个知心可意新家长，(带云)哎哟，福童儿也，(唱)那里发付那有母无爷小业冤，就儿里难言。','',''),('yuanqu-744','吕洞宾度铁拐李岳・脱布衫','岳伯川','yuanqu','','','我和你十七八共枕闷眠，二十载儿女姻缘。
一脚地停尸在眼前，(带云)妻阿！(唱)则落的酒茶浇奠。','',''),('yuanqu-745','吕洞宾度铁拐李岳・小梁州','岳伯川','yuanqu','','','怕不的痛哭灵堂守志坚，两泪涟涟。
有那等赢奸卖俏俊官员，早聘下金钗钏，(带云)你见了呵，(唱)还守的几多年？。','',''),('yuanqu-746','吕洞宾度铁拐李岳・幺篇','岳伯川','yuanqu','','','那里想夫妻往日心厮恋，也是前世前缘。
嘱付你小业冤，听爷劝。
您娘别寻了缱绻，(带云)若有人与你金银钱物呵，(唱)你是必休、是必休接受买服钱。','',''),('yuanqu-747','吕洞宾度铁拐李岳・倘秀才','岳伯川','yuanqu','','','笑里刀一千声抱怨，(带云)我见新宫到呵。
(唱)马前剑有三千个利便。
旧官行揩勒些东西，新官行过度些钱。
见起由难似产，听得到照会紧如烟，做多少家罪谴。','',''),('yuanqu-748','双调・蟾宫曲','刘秉忠','yuanqu','','','盼和风春雨如膏，花发南枝，北岸冰销。
夭桃似火，杨柳如烟，穰穰桑条。
初出谷黄莺弄巧，乍衔泥燕子寻巢。
宴赏东郊，杜甫游春，散诞逍遥。
炎天地热如烧，散发披襟，纨扇轻摇。
积雪敲冰，沉李浮瓜，不用百尺楼高。
避暑凉亭静扫，树阴稠绿波池沼。
流水溪桥，右军观鹅，散诞逍遥。
梧桐一叶初凋，菊绽东篱，佳节登高。
金风飒飒，寒雁呀呀，促织叨叨。
满目黄花衰草，一川红叶飘飘。
秋景萧萧，赏菊陶潜，散诞逍遥。
朔风瑞雪飘飘，暖阁红炉，酒泛羊羔。
如飞柳絮，似舞胡蝶，乱剪鹅毛。
银砌就楼台殿阁，粉妆成野外荒郊。
冬景寂寥，浩然踏雪，散诞逍遥。
中国诗歌库中华诗库中国诗典中国诗人中国诗坛首页,{Connection=[close],Content-Type=[text/html;charset=gb2312],Last-Modified=[Thu,12Apr201807:09:17GMT],Accept-Ranges=[bytes],Vary=[Accept-Encoding],Date=[Sun,29Sep201904:38:49GMT],Server=[LiteSpeed],Alt-Svc=[quic=":443";ma=2592000;v="39,43,46",h3-22=":443";ma=2592000]}>。','',''),('yuanqu-749','地藏王证东窗事犯・仙吕/端正好','孔文卿','yuanqu','','','见一日帝王宣十三次，多应挡回俺百万雄师。
莫不朝廷中别有甚关机事，既不沙却怎竹节也似差天使？。','',''),('yuanqu-750','地藏王证东窗事犯・幺篇','孔文卿','yuanqu','','','多敢是圣明君犒赏待宣赐，怎肯信谗言节外生枝？只不过休兵罢战还朝呵是，我暗暗地自寻思。
莫不是封官爵圣恩慈，明宣赐赏金资？添军校复还时，将三略展六韬施，收九府取京师，杀猛将血横尸。
夺了四京九府，须要称了俺平生志！(下)。','',''),('yuanqu-751','地藏王证东窗事犯・仙吕/点绛唇','孔文卿','yuanqu','','','立国安邦，列着虎贲郎将。
沙场上，卧雪眠霜，争与恁百二山河掌。','',''),('yuanqu-752','地藏王证东窗事犯・油葫芦','孔文卿','yuanqu','','','想十三人舞袖登城临汴梁，向青城虏了上皇。
(带云)唬得禁军八百万丢盔卸甲。
(唱)那其间，无一个匣中宝剑掣秋霜！杨戬是个帮闲攒懒元戎将，蔡京是个传书献简头厅相。
一个治家亡了家，一个安邦的丧厂邦。
虏得些金枝玉叶离了乡党，若不是泥马走康正。','',''),('yuanqu-753','地藏王证东窗事犯・天下乐','孔文卿','yuanqu','','','到如今宋室江山都属四国王，生并的国破城荒！那一场我与你重安口月定了四方。
战沙场几个死？破敌军几处伤？兀的是功名纸半张！(云)既是我谋反，哪里积草屯粮？谁见来？(唱)。','',''),('yuanqu-754','地藏王证东窗事犯・那吒令','孔文卿','yuanqu','','','恁寻思试想，向杀场战场；恁寻思试想，俺安邦定邦；恁寻思试想，立朝纲纪纲。
我不合扶持的帝业兴，我不合保护的山河壮，我不合整顿的地老天荒。','',''),('yuanqu-755','地藏王证东窗事犯・寄生草','孔文卿','yuanqu','','','仰面将高天问，英雄气怨上苍！问天公不曾天垂象，治居民不曾教居民荡，统三军不曾教三军丧。
只落的满身枷锁跪厅前，却甚一轮皂盖飞头下！。','',''),('yuanqu-756','地藏王证东窗事犯・村里迓鼓','孔文卿','yuanqu','','','我不合扶立一人为帝，教万民失望；我不合于家为国，无明夜，将烟尘扫荡；我不合仗手策，凭英勇，占得山河雄壮。
镇得四海宁，帝业昌，民心良，则兀的是我请官受赏！。','',''),('yuanqu-757','地藏王证东窗事犯・元和令','孔文卿','yuanqu','','','消不得上马金下马银，也合教出朝将入朝相。
我与恁夺旗扯鼓统儿郎，不能够列金钗十二行。
教这个牧童村叟蠢芒郎，到能够暮登天子堂！。','',''),('yuanqu-758','地藏王证东窗事犯・上马娇','孔文卿','yuanqu','','','不索你狠，更怕我慌。
你道是先打后商量，做了个耕牛为主遭鞭杖。
见外则慌，内则相隔着汉阳江，陛下久顾镇苏杭。','',''),('yuanqu-759','地藏王证东窗事犯・游四门','孔文卿','yuanqu','','','只怕不知祸起在萧墙！你待兴心乱朝纲，诈传宣赚离我边庭亡。
原来恁没世界有官方，暗暗将刀斧列在阶旁。','',''),('yuanqu-760','地藏王证东窗事犯・胜葫芦','孔文卿','yuanqu','','','却甚烂醉佳人锦瑟旁，今日和天也顺时光。
则那逆天的天不教命亡，顺天的祸从天降；逆天的神灵不报，顺天的受灾殃！。','',''),('yuanqu-761','地藏王证东窗事犯・寄生草','孔文卿','yuanqu','','','你道我把朝廷乱，不合将社稷匡。
我不合降戚方揭寨施心亮，我不合捉李成贼到中军帐，我不合破金国扶立的高宗旺。
待将我签头号令市曹中，却甚功劳写在凌烟上？。','',''),('yuanqu-762','地藏王证东窗事犯・赚煞','孔文卿','yuanqu','','','下我在十恶死囚牢，再不坐九鼎莲花帐，则我这谋反事如何肯当！我死呵，做个负屈衔冤忠孝鬼！见有侵境界小国偏邦，秦桧结勾起刀枪。
陛下，则怕你坐不久龙床！俺死呵，落得个盖世界居民众众讲：岳飞子父每不合舍性命生并的南服北降，出气力西除东荡！(带云)杀了岳飞、岳云、张宪三人，(唱)陛下，你便似砍折条擎天架海紫金梁！(下)。','',''),('yuanqu-763','地藏王证东窗事犯・醉春风','孔文卿','yuanqu','','','又不曾礼经忏法堂中，俺则是打勤劳山寺里。
则为你上瞒天子下欺臣，(带云)你道我痴，我道你奸。
"缚虎则易，纵虎则难"。
(唱)太师，这言语单道着你！你休笑我秽，我干净如你！你问我缘由，我对你说破，看怎生支对？有甚不知你来意！。','',''),('yuanqu-764','降桑椹蔡顺奉母・仙吕/点绛唇','刘唐卿','yuanqu','','','见如今雨顺风调，万民安乐，年光好。
圣德过尧，则他这文共武行忠孝。
(旦儿云)蔡顺，是好雪也。
恰便是银妆成世界，粉填满山川。
这雪润陇亩，滋禾稼，天下黎民皆喜也。
(正末唱)。','',''),('yuanqu-765','降桑椹蔡顺奉母・混江龙','刘唐卿','yuanqu','','','上合天道，常垂甘露润田苗。
这雪单注着多收五谷，广剩仓廒。
乡下农民斟村洒，城中上户饮香醪。
好收成端的民欢乐，托赖着一人有庆，因此上万国来朝。','',''),('yuanqu-766','降桑椹蔡顺奉母・醉中天','刘唐卿','yuanqu','','','这雪更塞拥蓝关道，尽蔽了九重霄，岭畔寒梅恰便似舒玉梢。
(云)将酒来，仇员外满饮一杯。
(仇彦达云)老夫饮。
这雪真乃国家祥瑞也。
(正末唱)这雪普四海添吉兆，仰圣德黎民安乐。
满斟白醪，贺丰年万姓歌瑶。','',''),('yuanqu-767','降桑椹蔡顺奉母・清江引','刘唐卿','yuanqu','','','这雪白来白似白厮赖，(云)这雪若还下在席子上，(唱)恰便似一床白绫被。
铺在热炕上，盖着和衣儿睡，醒来时化了一身水。','',''),('yuanqu-768','降桑椹蔡顺奉母・那吒令','刘唐卿','yuanqu','','','有钱人最好，锦貂裘暖帽；无钱人困遭，穿补衣衲袄；绕人家乞讨，忍饥寒冻倒。
数九天怎过遣？大街上高声叫，战兢兢性命难逃。
(夏德闰云)人生在天地之间，贫富分其两等，乃自然之理也。
(正末唱)。','',''),('yuanqu-769','降桑椹蔡顺奉母・鹊踏枝','刘唐卿','yuanqu','','','富家郎逞英豪，显奢骄，他每便语话言谈，气势偏高。
腆着脯向人前气傲，他把这贫民每当作儿曹。','',''),('yuanqu-770','降桑椹蔡顺奉母・寄生草','刘唐卿','yuanqu','','','有钱的高堂上常奢侈，无钱的遭贫寒居瓦窑。
有钱的列金钗弦管可便心欢乐，无钱的受忄西惶寂寞伤怀抱。
有钱的逞轩昂马践红尘道，无钱的向人前缩手口难开，则他这贫穷富贵是天道。
(蔡员外云)众位长者，慢慢的饮酒。
看有甚么人来？(解子押延岑上)(延岑云)猛烈刚强自古无，平生慷慨不尘俗。
见义当为真男子，则是我正直无私大丈夫。
某姓延，名岑，字均义。
我早生好汉，刚强性鲁，膂力过人。
我在那长街市上闲行，因见个年少的后生，赶着个年老的打。
我路见不平，将那年少拉将过来，三拳两脚，过打死了。
我出首到官，饶我死罪，脊杖了六十，罚我去郑州迭配牢城。
时遇冬暮天气，纷纷扬扬的下着这般大雪，身上单寒，肚里无食。
解子哥哥，你看这家儿人家，高房子，大门楼，门前马车嚷闹，必是个豪富之家。
俺去讨些茶饭食用。
(解子云)延岑，你可休走了。
(延岑云)哥哥，小人身做身当，岂敢带累你也？(解子云)你若这般，便好。
(延岑云)来到门首也。
我试叫一声。
大主人家，有那怜悯之心，用不了的茶饭，乞讨些食用。
(正末云)甚么人在门首，大惊小怪的？我试看去者。
(蔡员外云)孩儿也，你试看去。
(正末出门见科，云)一条好汉也。
兀那壮士，你因何带锁披枷来？(延岑云)哥哥不知。
小人平昔之间，刚强怀勇，膂力过人。
一日街上闲行，见一个年少后生，赶着个年老的打。
我路见不平，把那年少的拉将过来，三拳两脚打死了。
我出首到官，免我死罪，脊杖了六十，罚去郑州迭配牢城。
身上单寒，肚中饥馁。
路打门首过，见车马盈门，小人来乞讨些茶饭食用。
(正末云)壮士，你少待片时。
(正末进门科，云)俺这家私里外，无人照管。
若得这个壮士，与我做护臂，可也好也。
我对父亲母亲说去。
(正末见蔡员外科)(蔡员外云)孩儿也，甚么人吵闹？(正末云)父亲，门首有小壮士，迭配郑州牢城去。
身上单寒，肚中饥馁，来乞讨些茶饭食用。
父亲，俺家私卫外，无人照觑。
若得这个壮士，与我做了护臂，可也好也。
(蔡员外云)孩儿也，与我唤过那壮士来。
(正末云)理会的。
(正末见延岑云)兀那壮士，俺父亲唤你哩。
(延岑云)理会的。
(见众长者科，云)众位老长者，小人施礼哩。
(蔡员外云)兀那壮士，那里人氏？姓甚名谁？因甚带锁披枷？你说一遍者。
(延岑云)小人姓延，名岑，字均义，乃济州历阳人也。
我平日之间，刚直性勇，膂力过人。
忽朝一日街上闲行，见一个年少的后生，赶着年老的打。
我路见不平，将那年少的，三拳两脚打死了。
小人出首到官，免我死罪，脊杖了六十，罚去郑州迭配牢城。
下着如此。','',''),('yuanqu-771','降桑椹蔡顺奉母・金盏儿','刘唐卿','yuanqu','','','哥哥你是英豪，逞雄骁。
(延岑云)兄弟，我路见不平，把那年少的三拳两脚，就打死了也。
(正末唱)致伤人命官司行告，郑州迭配见些功劳。
有一日身荣为官爵。
青史把名标。
博一个马靴白象简，金带紫罗袍。','',''),('yuanqu-772','降桑椹蔡顺奉母・尾声','刘唐卿','yuanqu','','','俺可便离了画阁兰堂，举步登途道，赏瑞雪排筵罢却。
(蔡员外云)孩儿也，为人在世，得欢当作乐，莫负眼前光景也。
(正末唱)咱人便休把时光虚度了，(蔡员外云)今日赏雪饮酒，都皆沉醉也。
(正末唱)尽今生乐酶酶，饮香醪，满捧羊羔。
宝鼎龙涎香未消，则他这银台上蜡烧。
他每都觥筹欢笑，(旦儿云)蔡顺，今日父母十分欢喜也。
(正末云)俺为子者，要孝当竭力也。
(唱)则愿的一双父母寿年高。
(同下)。','',''),('yuanqu-773','降桑椹蔡顺奉母・商调/集贤宾','刘唐卿','yuanqu','','','则俺那老萱亲在堂年迈高，小生我想恩养育痛悲号。
俺母亲偎于湿三年乳哺，更怀耽十月劬劳。
我母亲抬举的立志成名，生长的貌类清标。
方信养生送死防备老，忆深恩我未报分毫。
谁承望尊堂病已深，则俺这幼子泪如浇。','',''),('yuanqu-774','降桑椹蔡顺奉母・逍遥乐','刘唐卿','yuanqu','','','俺母亲骨岩岩身躯老耄，(带云)叹母亲这病，(唱)恰便似风里杨花，水亡幻泡。
(兴儿云)小哥不要心焦，到家里把奶奶的病，我替他害了罢。
(正末唱)好教我便展转的添焦，俺母亲眼睁睁病枕难熬。
我可便心似油煎身如火燎，仰穹苍痛哭嚎啕。
(带云)蔡顺一片孝心，惟天可表也。
(唱)则愿的母病安妥，父命延长，子寿愿夭。','',''),('yuanqu-775','降桑椹蔡顺奉母・南青哥儿','刘唐卿','yuanqu','','','入门来审了他这八脉，(糊突虫拿卜儿右手科)(唱)瘦伶仃有如麻秸。
(太医唱)俺快把这药包儿忙解开。
(糊突虫云)可怜也，脉息不好了。
(唱)快疾忙去买，(太医唱)快疾忙占买。
(正末云)太医，买甚么？(太医唱)去买一个棺材，(糊突虫唱)去买一个棺材。','',''),('yuanqu-776','降桑椹蔡顺奉母・后庭花','刘唐卿','yuanqu','','','我怎消的众神灵下紫霄，驾祥云香雾绕。
凛凛神威人，堂堂美像貌。
赴天朝，亲传敕诏。
为慈亲病重倒，因愚男尽孝道。
后园中诚意祷，感天神来护保。
枯桑上长出嫩条，香甘甘子结的饱。
我摘将来盘内托，母亲行将孝意表，母亲行将孝意表。
(增福神云)你那母亲，若食了这桑椹子，可自然病体安乐也。
(正末唱)。','',''),('yuanqu-777','降桑椹蔡顺奉母・青哥儿','刘唐卿','yuanqu','','','吃了呵但能得尊堂、尊堂安乐，我做一坛水陆、水陆大醮。
(增福神做推正末科，云)休推睡里梦里。
(众神随下)(正末醒科)(唱)呀！原来是一枕南柯梦已觉。
恰才那空中神道，与小生梦里相交，细说根苗，着我欢展眉梢。
小生这些时耽着忧怀着闷受煎熬，恰才呵听说罢喜孜孜开怀抱。','',''),('yuanqu-778','降桑椹蔡顺奉母・尾声','刘唐卿','yuanqu','','','可又早飕飕的风力峭，惨惨的冻云罩。
他道是三更时分雪花飘，小生我深山中摘桑我可也不惮劳。
怎敢把神灵违拗？(云)小生摘将那桑椹子来，母亲若吃下去呵。
(唱)恰便是灵丹入腹可又早病儿消。
(同旦儿下)。','',''),('yuanqu-779','降桑椹蔡顺奉母・中吕/粉蝶儿','刘唐卿','yuanqu','','','每日家腹内思量，则我这孝心肠岂能敢忘？忧的是老尊堂卧枕眠床。
我可便受驱驰，耽辛苦，满腹愁何曾展放？不由我心内忄西惶。
俺母亲害的个病容颜，全不是旧时模样。','',''),('yuanqu-780','降桑椹蔡顺奉母・醉春风','刘唐卿','yuanqu','','','有一个董永卖亲身，黄香扇枕凉，郯子鹿乳奉萱堂。
这三人万代可便讲，讲。
则愿的老母安康，病体健，町便是俺子孙兴旺。','',''),('yuanqu-781','降桑椹蔡顺奉母・迎仙客','刘唐卿','yuanqu','','','昨夜个瑞雪飘，雨汪洋，仰天外黑黯黯可便云雾长。
融融的便暖如春，轰轰的便雷震响，影影的便电走金光，感应的祥瑞舞甘泽降。
(兴儿云)小哥，你看这山林中，青山绿水，有如画意，堪入丹青之手也。
(正末云)不觉的来到这大山中，是一派好山色景致也。
(唱)。','',''),('yuanqu-782','降桑椹蔡顺奉母・红绣鞋','刘唐卿','yuanqu','','','看山色晴岚一样，看山峰高彻空苍，看山景叠翠蕊芬芳。
看山林难描画，看山涧水流长，端的是山中堪玩赏。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-783','张孔目智勘魔合罗・仙吕/赏花时','孟汉卿','yuanqu','','','则为你叔嫂从来情性乖，我因此上将伊曾劝解。
(旦悲科，云)你去了，我怎了也！(正未唱)你可便省烦恼，莫伤怀。
你则照管这家私世外，(带云)别的不打紧。
(唱)你是必好觑当小婴孩。','',''),('yuanqu-784','张孔目智勘魔合罗・幺篇','孟汉卿','yuanqu','','','则俺这男子为人须挣坐，我向这外府他乡做买卖。
(旦云)你则是早些回来。
(正末唱)休则管泪盈腮，多不到一年半载，但得些利便回来。
(同旦下)。','',''),('yuanqu-785','张孔目智勘魔合罗・仙吕/点绛唇','孟汉卿','yuanqu','','','七月才初，孟秋时序，犹存暑。
穿着这单布衣服，怎避这悬麻雨？。','',''),('yuanqu-786','张孔目智勘魔合罗・混江龙','孟汉卿','yuanqu','','','连阴不住，荒郊一望水模糊。
我则见雨迷了山岫，云锁了青虚。
(带云)这雨大不大？(唱)云气深，如倒悬着东大海；雨势大，似翻合了洞庭湖。
好教我满眼儿没处寻归路，黑暗暗云迷四野，白茫茫水淹长涂。','',''),('yuanqu-787','张孔目智勘魔合罗・油葫芦','孟汉卿','yuanqu','','','恰便似画出潇湘水墨图，淋的我湿渌渌，更那堪吉丢古堆波浪渲城渠。
你看他吸留忽刺水流乞留曲律路，更和这失留疏剌风摆希留急了树。
怎当他乞纽忽浓的泥，更和他匹丢扑搭的淤。
我与你便急章拘诸慢行的赤留出律去，我则索滴羞跌屑整身躯。','',''),('yuanqu-788','张孔目智勘魔合罗・醉扶归','孟汉卿','yuanqu','','','我这里扭我这单布裤，晒我这湿衣服。
(云)怎生这般漏？哦！元来是这屋宇坍塌了，所以这般漏。
我试看这行李咱。
(唱)我则怕盖行李的油单有漏处，我与你须索从头觑。
(云)且喜得都不曾湿嗨！可怎生这等漏得紧。
(唱)奇怪这两三番揩不干我这额头颅，(云)可是为甚么？呆汉，你慌怎的？(唱)可忘了将我这湿渌渌头巾去。','',''),('yuanqu-789','张孔目智勘魔合罗・后庭花','孟汉卿','yuanqu','','','俺家里有一遭新板闼住两间高瓦屋。
隔壁儿是个熟食店，对门儿是个生药局。
怕老的若有不是处你则问那里是李德昌家绒线铺，街坊每他都道与。','',''),('yuanqu-790','张孔目智勘魔合罗・赚煞','孟汉卿','yuanqu','','','你是必记心怀，你叮也休疑虑，不是我嘱咐了重还嘱咐。
争奈自己耽疾难动举，你教他借马寻驴莫踌躇。
争奈纸笔全无，怎写旷安两字书？老的只要你莫阻，说与俺看家拙妇，教他早些来把我这病人扶。
(下)。','',''),('yuanqu-791','张孔目智勘魔合罗・黄钟/醉花阴','孟汉卿','yuanqu','','','干着我贩卖南昌利钱好，急叫来又早病魔缠着。
盼家门咫尺似天遥，好教我这会儿心焦，按不住小鹿儿拘拘地跳。
端的是最难熬，只一阵头疼险些就劈破了。','',''),('yuanqu-792','张孔目智勘魔合罗・喜迁莺','孟汉卿','yuanqu','','','教谁来医疗，奈无人古庙萧萧。
量度，又怕有歹人来到。
不由人小中添懊恼，不由人不泪雨抛。
迭屑屑魂飞胆落，扑速速肉颤身摇。','',''),('yuanqu-793','张孔目智勘魔合罗・出队子','孟汉卿','yuanqu','','','似这般无颠无倒，越趣人厮窨约。
一会家阴阴的腹痛似锥挑，一会家烘烘的发热似火烧，一会家撒撒的增寒似水浇。','',''),('yuanqu-794','张孔目智勘魔合罗・刮地风','孟汉卿','yuanqu','','','悬望妻儿音信杳，急煎煎心痒难揉。
(云)我出庙门望一望波。
(唱)我这里慢腾腾行出灵神庙，举日偷瞧。
我与你恰下涩道，立在檐梢，觉昏沉刚挣揣把门倚靠。
我则道十分紧闭着，原来是不插拴牢。
靠着时呀的门开了，滴留扑仰剌叉吃一交。','',''),('yuanqu-795','张孔目智勘魔合罗・四门子','孟汉卿','yuanqu','','','这的是严霜偏打枯根草，哎哟！正跌着我这残病腰。
一会家疼一会家焦，想钱财莫不是无福消？一会家疼一会家焦，我将这神灵祷告。
(李文道慌上)来到这庙也，哥哥在那里？(正末见科)(唱)。','',''),('yuanqu-796','张孔目智勘魔合罗・古水仙子','孟汉卿','yuanqu','','','呀、呀、呀，猛见了，嗨、嗨、嗨，唬的我悠悠魂魄消。
将、将、将，纸钱来忙遮，把、把、把，泥神来紧靠，慌、慌、慌，我这驻掩映着。
(李文道云)我来望哥哥，受你兄弟两拜。
(正末唱)他、他、他，走将来展脚舒腰，我、我、我，向前来仔细观了相貌。
是、是、是，我兄弟间别身安乐，请、请、清，免拜波李文道。','',''),('yuanqu-797','张孔目智勘魔合罗・寨儿令','孟汉卿','yuanqu','','','也不昨宵，则是今朝，被风寒暑湿吹着。
(李文道云)我与哥哥把把脉咱。
(做把脉科，云)哥哥，我知道这病也，我就带将药来了。
(做调药，与正末吃科)(正末云)兄弟且住，等你嫂嫂来我吃。
(李文道云)不要等他，你吃了就好了。
(正末咽科)(唱)我咽下去有似热油浇，烘烘的烧五脏，火火的燎三焦。
(带云)兄弟也，(唱)这的敢不是风寒药？。','',''),('yuanqu-798','张孔目智勘魔合罗・神仗儿','孟汉卿','yuanqu','','','他将那水凋，我氵虢的咽了，不觉忽的昏迷，他把我丕的来药倒。
烟生七窍，冰浸四稍。
谁承望笑里藏刀，眼见的丧荒郊。','',''),('yuanqu-799','张孔目智勘魔合罗・节节高','孟汉卿','yuanqu','','','这厮如损人利己，不合大道。
钱物又不多，要时分明要，怎生下得教哥哥身夭。
更做道钱心重，情分少，任辱没杀分金管鲍。','',''),('yuanqu-800','张孔目智勘魔合罗・者刺古','孟汉卿','yuanqu','','','身躯被病执缚，难走难逃。
咽喉被药把捉，难叫难号。
托青天暗表，望灵神早报。
行善得善，行恶得恶。
天呵！莫不是今年灾祸招。','',''),('yuanqu-801','张孔目智勘魔合罗・挂金索','孟汉卿','yuanqu','','','我则道调理风寒，谁想他暗里藏毒药。
他如今致命图财，我正是自养着家生哨，疑怪来时，不将着亲嫂嫂。
万代人传，倒惹的关张笑。','',''),('yuanqu-802','张孔目智勘魔合罗・尾','孟汉卿','yuanqu','','','所有金珠共财宝，一星星早不剩分毫，他紧紧的将马儿驮去了。','',''),('yuanqu-803','双调・沽美酒兼太平令','张养浩','yuanqu','','','在官时只说闲，得闲也又思官，直到教人做样看。
从前的试观，哪一个不遇灾难？楚大夫行吟泽畔，伍将军血污衣冠，乌江岸消磨了好汉，咸阳市干休了丞相。
这几个百般，要安，不安，怎如俺五柳庄逍遥散诞？。','',''),('yuanqu-804','双调・胡十八','张养浩','yuanqu','','','正妙年，不觉的老来到。
思往常，似昨朝，好光阴流水不相饶，都不如醉了，睡着。
任金乌搬废兴，我只推不知道。
从退闲，遇生日，不似今，忒稀奇。
正值花明柳媚大寒食，齐歌着寿词，满斟着玉杯，愿合堂诸贵宾，都一般满千岁。
客可人，景如意，檀板敲，玉箫吹。
满堂香霭瑞云飞，左壁厢唱的，右壁厢舞的。
这其间辞酒杯，大管是不通济。
试算春，九十日，屈指间，去如飞。
三分中却早二分归，便醉的似泥，浑都有几时。
把金杯休放闲，须臾间日西坠。
人会合，不容易，但少别，早相离。
幸然有酒有相识，对着这般景致，动着这般乐器。
主人家又海量宽，劝诸公莫辞醉。
人笑余，类狂夫，我道渠，似囚拘。
为些儿名利损了身躯，不是他乐处，好教我叹吁。
唤蛾眉酒再斟，把春光且邀住。
自隐居，谢尘俗，云共烟，也欢虞。
万山青绕一茅屋，恰便似画图中间裹着老夫。
对着这无限景，怎下的又做官去。','',''),('yuanqu-805','双调・庆东原','张养浩','yuanqu','','','海来阔风波内，山般高尘土中，整做了三个十年梦。
被黄花数丛，白云几峰，惊觉周公梦。
辟却凤凰池，跳出醯鸡瓮。
人羡麒麟画，知他谁是谁？想这虚名声到底原无益。
用了无穷的气力，使了无穷的见识，费了无限的心机。
几个得全身，都不如醉了重还醉。
晁错原无罪，和衣东市中，利和名爱把人般弄。
付能元刂刻成些事功，却又早遭逢着祸凶。
不见了形踪，因此上向鹊华庄把白云种。
鹤立花边玉，莺啼树杪弦，喜沙鸥也解相留恋。
一个动开锦川，一个啼残翠烟，一个飞上青天。
诗句欲成时，满地云撩乱。','',''),('yuanqu-806','双调・庆宣和','张养浩','yuanqu','','','参议随朝天意可，又受奔波，绰然谁更笑呵呵。
倒大来快活，倒大来快活。
大小清河诸锦波，华鹊山坡，牧童齐唱采莲歌。
倒大来快活，倒大来快活。','',''),('yuanqu-807','中吕・最高歌兼喜春水咏玉簪','张养浩','yuanqu','','','想人间是有花开，谁似他幽闲洁白？亭亭玉立幽轩外，别是个清凉境界。
裁冰剪雪应难赛，一段香云历绿苔；空惹得暮云生，越显的秋容淡。
常引得月华来，和露摘，端的压尽凤头钗。
诗磨的剔透玲珑，酒灌的痴呆懵懂。
高车大纛成何用？一部笙歌断送。
金波潋滟浮银瓮，翠袖殷勤捧玉钟。
对一缕绿杨烟，看一弯梨花月，卧一枕海棠风。
似这般闲受用，再谁想丞相府帝王宫？。','',''),('yuanqu-808','双调・雁儿落兼清江引','张养浩','yuanqu','','','喜山林眼界高，嫌市井人烟闹。
过中年便退官，再不想长安道。
绰然一亭尘世表，不许俗人到。
四面桑麻深，一带云山妙，这一塔儿快活直到老。','',''),('yuanqu-809','双调・殿前欢对菊自叹','张养浩','yuanqu','','','可怜秋，一帘疏雨暗西楼。
黄花零落重阳后，减尽风流。
对黄花人自羞，花依旧，人比黄花瘦。
问花不语，花替人愁。
登会波楼四围山，会波楼上倚阑干。
大明湖铺翠描金间，华鹊中间，爱江心六月寒。
荷花绽，十里香风散。
被沙头啼鸟，唤醒这梦里微官。
玉香球花玉香球，花中无物比风流。
芳姿夺尽人间秀，冰雪堪羞，翠帏中分外幽。
开时候，把风月都熏透。
神仙在此，何必扬州。
村居会寻思，过中年便赋去来词。
为甚等闲间不肯来城市？只怕俗却新诗。
对着这落花村，流水堤，柴门闭柳外山横翠。
便有些斜风细雨，也近不得这薄笠蓑衣。','',''),('yuanqu-810','双调・落梅引','张养浩','yuanqu','','','门外山无数，亭中春有余，但沉吟早成诗句。
笑九皋禽也能相媚妩，驾白云半空飞去。
野鹤才鸣罢，山猿又复啼，压松梢月轮将坠。
响金钟洞天人睡起，拂不散满衣云气。
山隔红尘断，云随白鸟飞，只这的便是老夫心事。
休夸子房并范蠡，肯回头古人也容易。
野水明于月，沙鸥闲似云，喜村深地偏人静。
带烟霞半山斜照影，都变做满川诗兴。
流水高低涧，断云远近山，爱园林翠红相间。
对诗人怎不教天破悭，四周围水云无限。
入室琴书伴，出门出水围，别人不能够尽皆如意。
每日乐陶陶辋川图画里，与安期羡门何异？。','',''),('yuanqu-811','双调・得胜令四月一日喜雨','张养浩','yuanqu','','','万象欲焦枯，一雨足沾濡。
天地回生意，风云起壮图。
农夫，舞破蓑衣绿。
和余，欢喜的无是处！。','',''),('yuanqu-812','双调・沉醉东风','张养浩','yuanqu','','','蔬圃莲池药阑，石田茅屋柴关。
俺这里花发的疾，溪流的慢，绰然亭别是人间。
对着这万顷风烟四面山，因此上功名意懒！班定远飘零玉关，楚灵均憔悴江干。
李斯有黄犬悲，陆机有华亭叹，张柬之老来遭难。
把个苏子瞻长流了四五番，因此上功名意懒！昨日颜如渥丹，今朝鬓发斑斑。
恰才桃李春，又早桑榆晚，断送了古人何限？只为天地无情乐事悭，因此上功名意懒！郭子仪功威吐蕃，李太白书骇南蛮。
房玄龄经济才，尉敬德英雄汉，魏征般敢言直谏。
这的每都不满高人一笑看，因此上功名意懒！苫茅屋白云数间，睡芸窗红日三竿。
远近村，高低涧，把人我是非遮断。
阆苑蓬莱咫尺间，因此上功名意懒！万言策长沙不还，六韬书云梦空叹。
只为他进身的疾，收心的晚，终不免有许多忧患。
见了些无下梢从前玉笋班，因此上功名意懒！笔砚琴书座间，松筠梅菊江干。
欢有余，春无限，绰然亭只疑在天上。
万事无心一钓竿，因此上功名意懒。
寄阅世道人侯和卿披一领熬日月耐风霜道袍，系一条锁心猿拴意马环绦。
穿一对圣僧鞋，带一顶温公帽，一心敬奉三教。
休指望做神仙上九霄，只落得无是非清闲到老。','',''),('yuanqu-813','双调・折桂令','张养浩','yuanqu','','','想为官枉了贪图，正直清廉，自有亨衢。
暗室亏心，纵想致富，天意何如？白图甚身心受苦，急回头暮景桑榆。
婢妾妻孥，玉帛珍珠，都是过眼的风光，总是空虚。
功名事一笔都勾，千里归来，两鬓惊秋。
我自无能，谁言有道，勇退中流。
柴门外春风五柳，竹篱边野水孤舟。
绿蚁新ド，瓦钵磁瓯，直共青山，醉倒方休。
功名百尺竿头，自古及今，有几个干休？一个悬首城门，一个和衣东市，一个抱恨湘流。
一个十大功亲戚不留，一个万言策贬窜忠州。
一个无罪监收，一个自抹咽喉。
仔细寻思，都不如一叶扁舟。
过金山寺长江浩浩西来，水面云山，山上楼台。
山水相连，楼台相对，天与安排。
诗句成风烟动色，酒杯倾天地忘怀。
醉眼睁开，遥望蓬莱，一半儿云遮，一半儿烟霾。
中秋一轮飞镜谁磨？照彻干坤，印透山河。
玉露泠泠，洗秋空银汉无波。
比常夜清光更多，尽无碍桂影婆娑。
老子高歌，为问嫦娥，良夜恹恹，不醉如何？凿池殷勤凿破苍苔，把湖泺风烟，中半分开。
满意清香，尽都是千叶莲栽。
看镜里红妆弄色，引沙头白鸟飞来。
老子方才，陶写吟怀，忽见波光，摇动亭台。
咏胡琴八音中最妙惟弦，塞上新声，字字清圆。
锦树啼莺，朝阳鸣凤，空谷流泉。
引玉杖轻笼慢捻，赛歌喉倾倒宾筵。
常记当年，香案之前，一曲春生，四海名传。
通州巡舟呼童解缆开船，见绿树青天，两岸回旋。
欹枕篷窗，觉风波只在头边。
桂掉举摇开翠烟，竹弹斜界破平川。
老子狂颠，高咏诗篇，行过沙头，惊的些白鸟翩翩。
白莲隐括〔木兰花慢〕幽花带露池塘，恨太华峰高，身世相妨。
脉脉盈盈，何须解语，已断柔肠。
羡公子风标异常，尽一生何限清香。
华发沧浪，夜月壶觞，明日新声，付与秋娘。','',''),('yuanqu-814','正宫・塞鸿秋','张养浩','yuanqu','','','春来时绰然亭香雪梨花会，夏来时绰然亭云锦荷花会，秋来时绰然亭霜露黄花会，冬天时绰然亭风月梅花会。
春夏与秋冬，四季皆佳会，主人此意谁能会？。','',''),('yuanqu-815','中吕・山坡羊','张养浩','yuanqu','','','人生于世，休行非义，谩过人也谩不过天公意。
便亻赞些东西，得些衣食，他时终作儿孙累，本分世间为第一。
休使见识，干图甚的！休图官禄，休求金玉，随缘得过休多欲。
富何如？贵何如？没来由惹得人嫉妒，回首百年都做了土。
人，皆笑汝；渠，干受苦！如何是良贵？如何是珍味？所行所做依仁义。
淡黄齑，也似堂食，必能如此方无愧，万事莫教差半米。
天，成就你；人，钦敬你。
无官何患？无钱何惮？休教无德人轻慢。
你便列朝班，铸铜山，止不过只为衣和饭，腹内不饥身上暖。
官，君莫想；钱，君莫想。
于人诚信，于官清正，居于乡里宜和顺。
莫亏心，莫贪名，人生万事皆前定，行歹暗中天照临。
疾，也报应；迟，也报应。
休学谄佞，休学奔竞，休学说谎言无信。
貌相迎，不实诚，纵然富贵皆侥幸，神恶鬼嫌人又憎。
官，待怎生；钱，待怎生。
与人方便，救人危患，休趋富汉欺穷汉。
恶非难，善为难，细推物理皆虚幻，但得个美名儿留在世间。
心，也得安；身，也得安。
真实常在，虚脾终败，过河休把桥梁坏。
你便有文才，有钱财，一时间怕不人耽待，半空里若差将个打算的来。
强，难挣揣；乖，难挣揣。
金银盈溢，于身无益，争如长把人周济。
落便宜，是得便宜，世人岂解天公意，毒害到头伤了自己。
金，也笑你；银，也笑你。
天机参破，人情识破，归来闲枕白云卧。
向岩阿，且婆娑，琴书笔砚为功课，轩裳倘来何用躲？行，也在我；藏，也在我。
骊山怀古骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡，至今遗恨迷烟树，列国周齐秦汉楚。
赢，都变做了土；输，都变做了土！骊山屏翠，汤泉鼎沸，说琼楼玉宇今俱废。
汉唐碑，半为灰，荆榛长满繁华地，尧舜土阶君莫鄙。
生，人赞美；亡，人赞美。
沔池怀古秦如狼虎，赵如豚鼠，秦强赵弱非虚语。
笑相如，大粗疏，欲凭血气为伊吕，万一座间诛戮汝，君也，谁做主？民也，谁做主？秦王强暴，赵王懦弱，相如何以为怀抱？不量度，剩粗豪，酒席间便欲伐无道，倘若祖龙心内恼，君，干送了；民，干送了！北邙山怀古悲风成阵，荒烟埋恨，碑铭残缺应难认。
知他是汉朝君，晋朝臣？把风云庆会消磨尽，都做了北邙山下尘。
便是君，也唤不应；便是臣，也唤不应！洛阳怀古天津桥上，凭阑遥望，舂陵王气都凋丧。
树苍苍，水茫茫，云台不见中兴将，千古转头归灭亡。
功，也不久长；名，也不久长。
潼关怀古峰峦如聚，波涛如怒，山河表里潼关路。
望西都，意踌蹰，伤心秦汉经行处，宫阙万间都做了土。
兴，百姓苦；亡，百姓苦！未央怀古三杰当日，俱曾此地，殷勤纳谏论兴废。
见遗基，怎不伤悲，山河犹带英雄气，试上最高处闲坐地。
东，也在图画里；西，也在图画里。
咸阳怀古城池俱坏，英雄安在？云龙几度相交代！想兴衰，若为怀，唐家才起隋家败，世态有如云变改。
疾，也是天地差；迟，也是天地差！。','',''),('yuanqu-816','越调・天净沙','张养浩','yuanqu','','','昨朝杨柳依依，今朝雨雪霏霏，社燕秋鸿忒疾。
若不是浊醪有味，怎消磨这日月东西。
年时尚觉平安，今年陡恁衰残，更着十年试看。
烟消云散，一杯谁共歌欢？休言咱是谁非，只宜似醉如痴，便得功名待怎的？无穷无地，那驼儿用你精细？。','',''),('yuanqu-817','南吕・西番经','张养浩','yuanqu','','','天上皇华使，来回三四番，便是巢由请下山。
取索檀，略别华鹊山。
无多惭，此心非为官。
屈指归来后，山中八九年，七见征书下日边。
私自怜，又为尘事缠。
鹤休怨，行当还绰然。
累次征书至，教人去往难，岂是无心作大官？君试看，萧萧双鬓斑。
休嗟叹，只不如山水间。
说着功名事，满怀都是愁，可似青山归去休。
休，从今身自由。
谁能够，一蓑烟雨秋！小令。','',''),('yuanqu-818','中吕・红绣鞋赠美妓','张养浩','yuanqu','','','手掌儿血喷粉哨，指甲儿玉碾琼雕，子见他怀擎玛瑙泛香醪。
眼睛儿冷丢溜，话头儿热剔选，把一个李谪仙险醉倒。
荼コ院风香雪霁，海棠轩绿绕红围，他便似碧桃花映粉墙西。
梨花云春淡荡，杨柳雾晓凄迷，把一个陶学土险爱死。
套数。','',''),('yuanqu-819','双调・新水令辞官','张养浩','yuanqu','','','急流中勇退不争多，厌喧烦静中闲坐。
利名场说着逆耳，烟霞疾做了沉疴。
若不是天意相合，这清福怎能个。','',''),('yuanqu-820','川拨棹・每日家笑呵呵，陶渊明不似我。跳出天罗，占断烟波。竹坞松坡，','张养浩','yuanqu','','','到处婆婆。
倒大来清闲快活，看时节醉了呵！。','',''),('yuanqu-821','七弟兄・唱歌，弹歌，似风魔，把功名富贵都参破。有花有酒有行窝，无','张养浩','yuanqu','','','烦无恼无灾祸。','',''),('yuanqu-822','梅花酒・年纪又半百过，壮志消磨，暮景蹉跎，鬓发浑皤。想人生能几何？','张养浩','yuanqu','','','叹日月似撺梭。
自相度，图个甚？谩张罗，得磨驼，且磨驼。
共邻叟两三个，无拘束即脾和。','',''),('yuanqu-823','仙吕・一半儿','周文质','yuanqu','','','多承苏氏肯怜才，终是双生不在囗。
羞禁奶娘掩面色，耍开怀，一半儿殃及一半儿买。
写愁词赋自伤悲，传恨琵琶人共知。
司马哭痛如商妇泣，泪沾衣，一半儿才干一半儿湿。','',''),('yuanqu-824','越调・小桃红','周文质','yuanqu','','','当时罗帕写宫商，曾寄风流况。
今日樽前且休唱，断人肠，有花有酒应难忘。
香消夜凉，月明枕上，不信不思量。
彩笺滴满泪珠儿，心坎如刀刺。
明月清风两独自，暗嗟咨，愁怀写出龙蛇字。
吴姬见时，知咱心事，不信不相思。
咏桃东风有恨致玄都，吹破枝头玉。
夜月梨花也相妒，不寻俗，娇鸾彩凤风流处。
刘郎去也，武陵溪上，仙子淡妆梳。
群芳争艳斗开时，公子王孙至。
邀我名园赏春思，探花枝，任君各自簪红紫。
诸公肯许，老夫头上，插朵粉团儿。
偏嫌桃杏染胭脂，我爱丁香囗。
恨杀蔷薇有多刺，怨垂丝，梨花带雨伤春思。
海棠过了，荼コ开遍，都不似粉团儿。','',''),('yuanqu-825','越调・寨儿令','周文质','yuanqu','','','分凤鞋，剖鸾钗，薄情自来年少客。
义断恩乖，雨冷云埋，痴意尚怜才。
风不定花落闲阶，云不蔽月满楼台。
燕归也人未归，雁来也信悭来。
才，不得休约到海棠开。
弹玉指，觑腰枝，想前生欠他憔悴死。
锦帐琴瑟，罗帕胭脂，则落的害相思。
曾约在桃李开时，到今日杨柳垂丝。
假题情绝句诗，虚写恨断肠词，嗤！都扯作纸条儿。
鸾枕孤，凤衾余，愁心碎时窗外雨。
漏断铜壶，香冷金炉，宝帐暗流苏。
情不已心在天隅，魂欲离梦不华胥。
西风征雁远，湘水锦鳞无，吁！谁寄断肠书？蟾影边，凤台前，箫声为谁天外远？欹枕情牵，倚槛无言，血泪洒寒烟。
自薄情别后经年，想嫦娥不念孤眠。
葡萄架梧桐井，杨柳院海棠轩。
天！陡恁月儿圆。
斟玉波，对金荷，新来自觉酒尚可。
带解金罗，胥淡双蛾，月枕共谁歌？从别后必定心薄，待归来说甚愁多。
枕边憔悴我，灯下可憎他。
睃，腰柳瘦因何？莺燕友，凤鸾俦，尽今生猛可里不到头。
被底温柔，枕上风流，一笔尽都勾。
明知道泼水难收，争忍说和味合休。
沈腰偏着丑，潘貌不藏羞。
愁，人问瘦因由。
挑短檠，倚云屏，伤心伴人清瘦影。
薄酒初醒，好梦难成，斜月为谁明？闷恹恹听彻残更，意迟迟盼杀多情。
西风穿户冷，檐马隔帘鸣，叮，疑是佩环声。
踏草茵，步苔痕，忆宫妆懒观蝶翅粉。
桃脸香新，柳黛愁颦，谁道不消魂！海棠台榭清晨，梨花院落黄昏。
卷帘邀皓月，把酒问东君。
春，偏恼少年人。
清景幽，水痕收，潇潇几株霜后柳。
往日追游，此际还羞，新恨上眉头。
丹枫不返金沟，碧云深锁朱楼。
风凉梧翠减，露冷菊音浮。
秋，妆占许多愁。
彻骨杓，满怀学，只因爱钱心辨不得歹共好。
杨柳妖娆，兰蕙丰标，禁不过烂银锹。
旧人物不采分毫，新女婿直恁风骚。
攀不得龙虎榜，品不得凤鸾箫。
猫，不信不敛儿哮。','',''),('yuanqu-826','双调・折桂令过多景楼','周文质','yuanqu','','','滔滔春水东流，天阔云闲，树渺禽幽。
山远横眉，波平消雪，月缺沉钩。
桃蕊红妆渡口，梨花白点江头。
何处离愁，人别层楼，我宿孤舟。
咏蟠梅梨雪旋绕东风，谁屈冰梢，怪压苍松？绿萼含香，枯根层结，春信重封。
清味远嫌蝶妒蜂，老枝寒舞凤蟠龙。
夜月朦胧，疏蕊纵横；瘦影交加，碎玉玲珑。
二色鞋儿轻摇环佩丁东，半露新荷，半掩芙蓉。
花柳些些，霞绡点点，锦翠弓弓。
绿绫扇轻拈落红，茜萝尖微印苔踪。
心恨难通，裙底鸳鸯，出落雌雄。','',''),('yuanqu-827','双调・清江引咏笑靥儿','周文质','yuanqu','','','一窝粉香堪爱惜，近眼花将坠。
添他百媚生，动我千金费。
春风小桃初破蕊。','',''),('yuanqu-828','双调・落梅风','周文质','yuanqu','','','眉间恨，心上苦，口难言把脚尖儿分付。
乌靴上半痕鞋下土，忍轻将袖梢儿挪去。
楼台小，风味佳，动新愁雨初风乍。
知不知对春思念他，倚阑干海棠花下。
新秋夜，微醉时，月明中倚阑独自。
吟成几联肠断诗，说不尽满怀心事。
鸾凤配，莺燕约，感萧娘肯怜才貌。
除琴剑又别无珍共宝，则一片至诚心要也不要？风流士，年少客，花无名帽檐羞带。
新来颇觉略分外，相思病等闲不害。
干坤内，山共水，论风流古杭为最。
北高峰离不得三二里，回头看镂金铺翠。','',''),('yuanqu-829','双调・庆东原','周文质','yuanqu','','','闲评论，猛三思，想海神庙错断了乔公事，则合赚他每烧钱裂纸，则合任他每焚香扣齿，不合信他每插状供词。
人都说桂英痴，则我道王魁是。','',''),('yuanqu-830','不知宫调・时新乐','周文质','yuanqu','','','千里独行关大王，私下三关杨六郎，张飞忒煞强，诸葛军师赛张良。
暗想，这场，张飞莽撞，大闹卧龙冈，大闹卧龙冈。
金妆宝剑藏龙口，玉带红绒皇宣授。
男儿得志秋，旌旗影里骤骅骝。
满斟，玉瓯，笙歌齐奏，喧满凤凰楼，喧满凤凰楼。
人活百岁七十稀，百岁光阴能几日，光阴积渐催，穿了吃了是便宜。
唱着，舞着，终日沉醉，不饮是呆痴，不饮是呆痴。
迓鼓童童笆篷下，数个神翁年高大。
糍糕着手拿，磁瓯瓦带浑滓。
铺下，板踏，萝卜两把，盐酱蘸梢瓜，盐酱蘸梢瓜。
霎时相见便流恋，俊俏庞儿少曾见。
一朵白玉莲，端端正正在湖边。
细看，可怜，香风拂面，真乃是前缘。
套数。','',''),('yuanqu-831','大石调・青杏子元宵','周文质','yuanqu','','','明月镜无瑕，三五夜人物喧哗，水晶台榭烧银蜡。
笙歌杳杳，金珠簇簇，灯火家家。','',''),('yuanqu-832','幺・命文友步京华，看天涯往来车马，对景伤情诉说别离话。一番提起，','周文质','yuanqu','','','数年往事，几度嗟呀。','',''),('yuanqu-833','好观音・见一簇神仙香风飒，春娥舞绛烛笼纱。一个多俊多娇好似他，堪','周文质','yuanqu','','','描画，笑吟吟重把金钗插。','',''),('yuanqu-834','幺・行至侵云鳌峰下，却原来正是俺那娇娃。怕不待根前动问咱？人奸诈，','周文质','yuanqu','','','拘钤得无半点儿风流暇。','',''),('yuanqu-835','越调・斗鹌鹑咏小卿','周文质','yuanqu','','','释卷挑灯，攀今览古；妒日嫌风，埋云怨雨。
因观金斗遗文，故造绿窗新语。
自忖度，有窨腹，好做得是也有钞茶商，好行得差也能文士夫。','',''),('yuanqu-836','紫花儿・苏娘娘本贪也欲也，冯员外既与之求之，双解元怎羡乎嗟呼？但','周文质','yuanqu','','','常见酬歌买笑，谁再睹沽酒当垆。
哎！青蚨，压碎那茶药琴棋笔砚书。
今日小生做个盟甫，改正那村纣的冯魁，疏驳那俊雅的通叔。','',''),('yuanqu-837','调笑令・那其间美女，搂着村夫，怎做得贤愚不并居？便休题书中有女颜','周文质','yuanqu','','','如玉，偏那双通叔不者也之乎？他也曾悬头刺股将经史读，他几曾寻得个落雁沉鱼？。','',''),('yuanqu-838','秃厮儿・双渐正瑶琴自抚，冯魁正红袖双扶。双渐正弹成满江肠断曲，冯','周文质','yuanqu','','','魁正倒金壶，饮芳醑。','',''),('yuanqu-839','圣药王・双渐正眉不疏，冯魁正兴未足。双渐正闷随江水恨吞吴，冯魁正','周文质','yuanqu','','','乐有余。
双渐正愁怎除，冯魁正写成今世不休书。
双渐正嫌杀影儿孤。','',''),('yuanqu-840','尾・寻思两个闲人物，判风月才人记取：将俊名儿双渐行且权除，把俏字','周文质','yuanqu','','','儿冯魁行暂时与。','',''),('yuanqu-841','双调・新水令思忆','周文质','yuanqu','','','落红风里不闻声，叹东君渐成薄幸。
却艳冶，又飘零，叶底残英，刚留住惜花性。','',''),('yuanqu-842','大石调・六国朝收心','睢景臣','yuanqu','','','长江浪险，平地风恬。
恨世态柳颦频眉，顺人情花笑靥。
乌兔东西急，白发重添；寒暑往来侵，朱颜退染。
穿花蝶愁扃绿锁，营巢燕恨簌朱帘。
蝶入梦魂潜，燕经秋社闪。','',''),('yuanqu-843','摧拍子・拜辞了桃腮杏脸，追逐回雪鬓霜髯，死灰绝焰。腹难容曩日杯盘，','睢景臣','yuanqu','','','身怎跳而今坑堑？去奢从俭。
六桥云锦，十里风花，庆赏无厌。
四时独占，花溪信马，莲浦乘舟，菊绽霜严，雪残梅堑。
鸟呼人至，鹤送猿迎。
酒肴随分，费用从廉，就清流洗痕濯玷。','',''),('yuanqu-844','幺・烟花簿敛，风尘户掩，再谁曾制关抽店？尽亚仙嫁了元和，由苏氏放','睢景臣','yuanqu','','','番双渐。
罢思绝念，忘却旧游。
魔女魂香，野狐涎甜，觉来有验。
抽箱罗帕，倒袋香囊，将俺拘钳，做科撒阽，浮花浪蕊。
胜馥残豪，你能搽抹，谁敢粘沾，倒榻鬼赖人支{坫瓦}！。','',''),('yuanqu-845','归塞北・呆娇艳，自要苦厌厌。觅见银山无采取，寻着钱树不揪ㄎ，典卖','睢景臣','yuanqu','','','尽妆奁。','',''),('yuanqu-846','尾・零替了家私怕搜检，缺少了些人情我应点。情瞒儿出尖，谁负债拿着','睢景臣','yuanqu','','','我还欠？。','',''),('yuanqu-847','般涉调・哨遍高祖还乡','睢景臣','yuanqu','','','社长排门告示，但有的差使无推故。
这差使不寻俗，一壁厢纳草也恨，一边又要差夫，索应付。
又言是车驾，都说是銮舆，今日还乡故。
王乡老执定瓦台盘，赵忙郎抱着酒胡芦。
新刷来的头巾，恰糨来的绸衫，畅好是妆么大户。','',''),('yuanqu-848','耍孩儿・瞎王留引定火乔男女，胡踢蹬吹笛擂鼓。见一风彡人马到庄门，','睢景臣','yuanqu','','','匹头里几面旗舒：一面旗白胡阑套住个迎霜兔，一面旗红曲连打着个毕月乌，一面旗鸡学舞，一面旗狗生双翅，一面旗蛇缠胡芦。','',''),('yuanqu-849','四・辕条上都是马，套顶上不见驴，黄罗伞柄天生曲。车前八个天曹判，','睢景臣','yuanqu','','','车后若干递送夫。
更几个多娇女，一般穿着，一样妆梳。','',''),('yuanqu-850','三・那大汉下的车，众人施礼数，那大汉觑得人如无物。众乡老展脚舒腰','睢景臣','yuanqu','','','拜，那大汉那身着手扶。
猛可里抬头觑，觑多时认得，险气破我胸脯。','',''),('yuanqu-851','二・你须身姓刘，您妻须姓吕，把你两家儿根脚从头数。你本身做亭长耽','睢景臣','yuanqu','','','几盏酒，你丈人教村学读几卷书。
曾在俺庄东住，也曾与我喂牛切草，拽坝扶锄。','',''),('yuanqu-852','一・春采了桑，冬借了俺粟，零支了米麦无重数。换田契强秤了麻三秤，','睢景臣','yuanqu','','','还酒债偷量了豆几斛。
有甚胡突处？明标着册历，见放着文书。','',''),('yuanqu-853','尾・少我的钱，差发内旋拨还；我的粟，税粮中私准除。只道刘三，谁肯','睢景臣','yuanqu','','','把你揪ㄏ住？白甚么改了姓更了名唤做汉高祖！。','',''),('yuanqu-854','商角调・黄莺儿寓僧舍','睢景臣','yuanqu','','','秋色，秋色，几声悲怆，孤鸿出塞。
满园林野火烘霞，荷枯柳败。','',''),('yuanqu-855','踏莎行・水馆烟中，暮山云外，泊孤舟古渡侧。息风霾，净尘埃，宝刹清','睢景臣','yuanqu','','','凉境界。
僧相待，借眠何碍？。','',''),('yuanqu-856','垂丝钓・风清月白，有感心酸不耐。更触目凄凉，景物供将愁闷来。月被','睢景臣','yuanqu','','','云埋，风鸣在籁。','',''),('yuanqu-857','应天长・僧舍窄，蚊帐矮，独拥单衾，一宵如半载。旧恨新愁深似海。情','睢景臣','yuanqu','','','缘在，人无奈，几般儿可怪。','',''),('yuanqu-858','随煞・促织絮恼情怀，砧杵韵无聊赖。檐马奢殿铎鸣，疏雨滴西风煞，能','睢景臣','yuanqu','','','断送楚台云，会禁持异乡客。','',''),('yuanqu-859','中吕・迎仙客风情','曾瑞','yuanqu','','','施计策，硬栽排，把明皇没扌刷地揣过来。
假承塌，休<门系><门坐>，借债我做着傍牌。
可敢别烧上风流怪。
成密宠，正情浓，休听外人冷句儿哝。
劣冤家，小业种，情我做着屏风。
可休别凿透桃源洞。
我共你，莫相离，肉铁索更粘如胶共漆。
系着眉毛，结着{髟弟}髻，硬顶着头皮，熬一个心先退。','',''),('yuanqu-860','中吕・红绣鞋风情','曾瑞','yuanqu','','','值暮景烟花领袖，点秋霜风月班头，少年狂翻作老来羞。
有人处把些礼数，无人处结遍绸缪，任谁问休道咱共你有。
假认义做哥哥般亲厚，行人情似妹妹般追逐，着小局断儿包藏着鬼胡由。
明讲着昆仲礼，暗结了燕莺俦，似恁般谁猜疑我共你有。
祆庙火既烧着皮肉，蓝桥水已淹过咽喉，紧按捺风声满南州。
便毕罢了终是点污，若成合了到敢风流，不恁么呵也道是有。
会云雨风也教休透，闲是非屁也似休亻秋，去那无缝锁上十字儿纽一个封头。
由那快抡锹的闪着手腕，散楚的叫破咽喉，俺两个痛关心的情越有。
期白昼家前院后，约黄昏雨歇云收，知他是你卖风他负德我胡ㄐ。
由你义秧儿栽个强证，草本儿指个牵头，见如今他共我有。
题桥志文章锦绣，驾车心体态温柔，女貌郎才忒风流。
语言间情暗许，眼色内意相投，两个委实无人道做有。
口儿快特婪侃嗽，脚儿勤推恋俳优，每日家弄子里茶坊中紧相逐，为俺待的厚，也亻来气快要的恶也忒情熟，因此上外人观恰便似有。
闲谈笑踏科儿寻斗，但离别觅缝儿承头，好一会弱一会厮奚酬。
着厮拾啜为了题目，闲打骂做了开头，两个虚难当又真个有。
乔断案村亻来杂嗽，望梅花子弟单兜，侧脚里姨夫做了冤仇，苏小小弃了舞榭，许盼盼闭上歌楼，似恁么难厮着怎做得有。
实镘的剐皮割肉，虚恩情撇闪提<鼻勾>，干遇讪乔敷演几时休。
妆砌末招人谤，哮孛郎儿人羞，强折证刚道他有。','',''),('yuanqu-861','中吕・山坡羊自叹','曾瑞','yuanqu','','','南山空灿，白石空烂，星移物换愁无限。
隔重关，困尘寰，几番肩锁空长叹。
百事不成羞又赧。
闲，一梦残。
干，两鬓斑。
叹世鸡鸣为利，鸦栖收计，几曾得觉囫囵睡。
使心机，昧神祗，区区造下弥天罪。
富贵一场春梦里。
财，沤泛水。
人，泉下鬼。
荣华休傲，贫穷休笑，循环世态多颠倒。
恰春朝，早秋宵，花开花谢都知道。
今岁孟春花更早。
花，依旧好。
人，空谩老。
虚名休就，眉头休皱，终身更不遭机彀。
抱官囚，为谁愁，功名半纸难能够。
争如漆园蝶梦叟。
常，紧闭口。
闲，且袖手。
花逢春到，人逢时到，花开人旺多欢笑。
看英豪，赏花娇，乐极悲至非人乐。
花正发时风又恶。
花，零落了。
人，憔悴了。
财帛争竞，田园吞并，得来未必成嘉庆。
干虚名，舍残生，归来笑杀彭泽令。
孤云野鹤为伴等。
鹤，飞过境。
云，行过岭。
题情青鸾舞镜，红鸳交颈，梦回依旧成孤另。
冻云晴，月华明，香消烛灭人初静。
窗外朔风梅萼冷。
风，寒夜景。
横，梅瘦影。
讥时繁花春尽，穷途人困，太平分的清闲运。
整干坤，会经纶，奈何不遂风雷信。
朝市得安为大隐。
咱，妆做蠢。
民，何受窘。
闺怨孤帏独卧，良宵空过，付能有梦还惊破。
病成魔，泪如梭，凄凉无数来着末。
凭谁顿开眉上锁。
咱，无奈何。
愁，无处躲。
妓怨春花秋月，歌台舞榭，悲欢聚散花开谢。
恰和协，又离别，被娘间阻郎心趄。
离恨满怀何处说。
娘，毒似蝎。
郎，心似铁。','',''),('yuanqu-862','中吕・快活三过朝天子警世','曾瑞','yuanqu','','','有见识越大夫，无转理楚三闾。
正当权肯觅个脱身术，那的是高才处。
老孤，面糊，休直待虚名误。
全身远害倒大福，驾一叶扁舟去，烟水云林，皆无租赋，拣溪山好处居。
相府，帅府，那与他别人住。
肉撑翻鼎饕餮，土蚀损剑镆铘。
诸公荣贵不曾绝，偏我如鸠拙。
命耶，运耶，穷通内分优劣。
蜂衙蚁阵且略别，伴四季闲风月。
老瓦盆边，无明无夜，盆干时酒再赊。
醉也，睡也，一任教花开谢。
受官厅暮雨残，待漏院晓霜寒。
耽耽九虎隔重关，更险似连云栈。
左难，右难，牢着脚周公旦。
功成名遂不退闲，真个是痴呆汉。
梦里浮华，浑无多限，觉来时两鬓斑。
试看，这番，又是个新公案。
老风情莺花寨不受敌，雨云乡纳降旗。
簪花人老不相宜，枉惹的人牙戏。
忏悔，罪累，要绝了鸾凤配，人心争奈不是木石，长感动思凡意。
得遇知心，私情机密，有风声我怕谁。
你任谁，问伊，硬抵着头皮讳。
自误肉肥甘酒韵美，多一口便伤食。
家传一瓮淡黄齑，吃过后须回味。
恁地，老实，尚不可渔樵意。
时乎命也我自知，无半点闲萦系。
枕石眠云，蘧庐天地，正蝴蝶魂梦里。
晓鸡，乱啼，又惊觉陈抟睡。
劝娼花刷子拽大权，俏勤儿受熬煎。
又待趁风流成就了好姻缘，又待认没幸看钱面。
爱贤，爱钱，两件儿都从伊便。
爱贤后谁强如李亚仙，爱钱把冯魁缠。
敬富嫌贫，贤愚不辨，想苏卿也识见浅。
当时你眼前，若选，谁后似双知县。','',''),('yuanqu-863','双调・折桂令闺怨','曾瑞','yuanqu','','','秋霄淡淡轻阴，暮景萧条，疏雨霪霖。
林外鸟啼，天边雁叫，砌下蛩吟。
更漏永声来绣枕，篆烟消寒透罗衾。
恨杀邻砧，惊散离魂，捣碎人心。
秦城望断箫声，时物供愁，夜景伤情。
鹤唳松庭，风摇槛竹，雨滴檐楹。
银烛暗雕盘篆冷，绣帏孤翠被寒增。
数尽残更，天也难明，梦也难成。','',''),('yuanqu-864','仙吕・寄生草送别','曾瑞','yuanqu','','','阳关曲，歌金缕，别离杯，倒玉壶。
为功名不可留君住，远程途无计将奴去，想人间最是伤情处。
玉容愁过武陵溪，雕鞍懒上临平路。
套数。','',''),('yuanqu-865','黄钟・醉花阴远宵忆旧','曾瑞','yuanqu','','','冻雪才消腊梅谢，却早击碎泥牛应节，柳眼吐些些。
时序相催，斗把鳌山结。','',''),('yuanqu-866','出队子・想当初时节，那浓欢怎弃舍。新愁装满太平车，旧恨常堆几万叠，','曾瑞','yuanqu','','','若负德辜恩天地折。','',''),('yuanqu-867','神仗儿・这些时情诗倦写，和音书断绝。斜月笼明，残灯半灭。恨檐马玎','曾瑞','yuanqu','','','当，怨塞鸿凄切。
猛然间想起多娇，那愁闷，怎拦截。','',''),('yuanqu-868','挂金索・业缘心肠，那烦恼何时彻。对景伤情，怎捱如年夜。灯火阑珊，','曾瑞','yuanqu','','','似万朵金莲谢。
车马<门便>阗，赛一火鸳鸯社。','',''),('yuanqu-869','喜迁莺・想才郎丰鉴，貌堂堂阔论高谈。那堪。并不愚滥，一见了春愁独','曾瑞','yuanqu','','','自搅，常好是忒大胆。
怕不你心心儿里待贪，又则怕意意儿里相搀。','',''),('yuanqu-870','杏水仙子・将将将紫丝缰紧兜揽，是是是春纤长勒不住碧玉衔。飕飕飕摔','曾瑞','yuanqu','','','风过长亭，出出出方行过短站。
见见见三家店忽的向南，淹淹淹映香尘晓日红含。
我我我软兀剌绣鞍身半探，看看看曲弯弯两叶蛾眉淡，瘦怯怯六幅翠裙搀。','',''),('yuanqu-871','寨儿令・尴<九咸>，尴<九咸>，做的来所事忒严。想当初才貌两相堪，一','曾瑞','yuanqu','','','个是娇仕女，一个俊儿男，他自把那婚姻勘。','',''),('yuanqu-872','尾声・一担相思自摇撼，我和你两家担由自难担，将一个担不起担儿却怎','曾瑞','yuanqu','','','生分付俺。','',''),('yuanqu-873','黄钟・愿成双赠老妓','曾瑞','yuanqu','','','娇鸾态，雏凤姿，正生红闹簇枯枝。
含香蓓蕾未开时，没乱杀莺儿燕子。','',''),('yuanqu-874','出队子・阑珊春事，恨题绝罗扇诗。玉容香散粉慵施，锦树花残蝶倦时，','曾瑞','yuanqu','','','正绿叶成阴子满枝。','',''),('yuanqu-875','正宫・端正好自序','曾瑞','yuanqu','','','一枕梦魂惊，千载风云过，将古来英俊评跋。
谁才能谁霸道谁王佐，只落得高冢麒麟卧。','',''),('yuanqu-876','幺・百年身隙外白驹过，事无成潘鬓双皤。既生来命与时相挫，去狼虎丛','曾瑞','yuanqu','','','服低捋。','',''),('yuanqu-877','昊天塔孟良盗骨・仙吕/点绛唇','朱凯','yuanqu','','','傀儡棚中，鼓笛声送，相搬弄。
想着那世事皆空，恰便似一枕南柯梦。
(七郎云)只恨那潘仁美这个奸贼，逼的俺父子并丧番地，可怜人也。
(正末唱)。','',''),('yuanqu-878','昊天塔孟良盗骨・混江龙','朱凯','yuanqu','','','盼不到先茔旧垅，黄泉下埋没杀俺这英雄。
(七郎云)父亲，俺不能勾青史标名，留芳万古，空怀着一腔怨气，何时分解也？(正末唱)空锁着一腔怨气做不的万丈霓虹。
本待要汉主台前把俺形容画，准知道李陵碑底早是命途穷。
怎将那一座两狼山碜可可生扭做祁连冢，也枉了俺半生无敌，十大的这边功。','',''),('yuanqu-879','昊天塔孟良盗骨・油葫芦','朱凯','yuanqu','','','可便是困杀南山老大虫，枉自有爪和牙成甚么用？都做了一齐分付与东风！想着俺雕弓能劈千钧重，单枪不怕三军众。
也曾将蕃国攻，也曾将敌阵冲。
一任他八方四面干戈动，那一个敢和俺出马共争锋？。','',''),('yuanqu-880','昊天塔孟良盗骨・天下乐','朱凯','yuanqu','','','哎！你说甚么胜败兵家本不穷，则这兵也波书，我可索是通。
(带云)俺家姓杨，被番兵陷在虎口交牙峪里，这个叫做羊落虎口，正犯了兵家所忌，怎还有活的人也？(唱)奈贼臣把俺来着了羊投虎口嘶断送，方信道将在谋，不在勇，兀的不横亡了俺这姜太公。','',''),('yuanqu-881','昊天塔孟良盗骨・青哥儿','朱凯','yuanqu','','','哎他将我这尸骸恁般摩弄，因此上向儿行一星星悲控。
(杨景云)父亲，俺想韩延寿那里兵强马壮，只可智取，难以力夺。
不知三关上二十四个指挥使，还是着那一个和孩儿同去，才得成功也？(正末唱)你若是有心呵可怜见我遍体金枪不耐风，也不须打凤捞龙，别选元戎。
只在军中，火德天蓬，自有神通。
觅迹寻踪，撒泼行凶，将俺那骨匣儿早拔出虎狼丛，这便当的你香花供。','',''),('yuanqu-882','昊天塔孟良盗骨・寄生草','朱凯','yuanqu','','','俺为甚么泪频挥，也只要您心暗懂。
早遣那嘉山太仆来争哄，把这宣花巨斧轻输动，免着俺昊天塔上长酸痛。
您若是和番家忘了戴天仇，可不俺望乡台枉做下还家梦。','',''),('yuanqu-883','昊天塔孟良盗骨・赚煞尾','朱凯','yuanqu','','','儿也你回到圣明朝，备把我这冤情讼。
我也不望加官赐宠，只要个一体君臣有始终，早迎还俺那无佞清风。
恨匆匆，睡眼朦胧，儿也说甚的犹恐相逢是梦中。
嘱咐您个杨家业种，须念着子父每情重，休使俺幽魂愁杀这座梵王宫。','',''),('yuanqu-884','昊天塔孟良盗骨・中吕/粉蝶儿','朱凯','yuanqu','','','这些时无处征伐，我去那界河边恰才巡罢，我做的一个个活捉生拿。
涌彪躯，舒猿臂肝横胆乍。
也不索将武艺盘咱，回头儿只看咱披挂。','',''),('yuanqu-885','昊天塔孟良盗骨・醉春风','朱凯','yuanqu','','','比及你架上掇雕鞍，槽头牵战马。
宣花斧钺手中担，觑敌军似耍，耍。
万骑交驰，两军相见，咱手里半筹不纳。','',''),('yuanqu-886','昊天塔孟良盗骨・斗鹌鹑','朱凯','yuanqu','','','哎，那厮须不是布雾的蚩尤，又不是飞天的夜叉。
(杨景云)那厮见你手段高强，被他藏了躲了呢？(正末唱)那厮便藏在云中，躲在、躲在地下，我也翻过干坤若见他。
说那厮能变化，我呵喝一喝骨碌碌的海沸山崩，瞅一瞅赤力力的天摧地塌。
(杨景云)孟良，你猜了半日，只是猜不着。
你回避。
(正末云)既是猜不着，我且回避。
(正末出门见小军，云)兀那厮！你来这里做甚么？你快实说。
你若不说，劈了你这颗狗头来，我则一斧！(小军云)适才元帅赏了我酒十瓶，羊肉二十斤，不争你劈了我这头，教我怎么吃？(正末云)快说！你若不说，我就一斧。
(小军云)老爷不要燥暴就把斧头劈下来，待我说，我说。
我是杨家府里小军儿，奉佘太君奶奶的命，着我寄一封书与元帅。
道是梦中看见老令公，说与番兵交战，不想番兵将老令公困在两狼山虎口交牙峪，困的里无粮草，外无救军。
有七郎打出阵来求救，不想被潘仁美将七郎绑在花标树上，攒箭射死。
老令公不能得出，撞李陵碑身死。
今被韩延寿将老令公尸首烧了，将骨殖挂在幽州昊天寺塔尖上。
但是过来过往的人，有箭的射三箭，无箭的打三砖，名曰百药箭。
(正末云)敢是百箭会？(小军云)你说的是。
(正末云)眼见的哥哥召集众将商量，取那父亲骨殖去，是一件紧要的事，故瞒着我来。
嗨！哥哥，我们二十四个指挥使，都是一般的兄弟，怎么偏心，只与他们计议，独独着我回避？我再过去，白破了哥哥咱。
(见杨景科，云)哥哥，我猜着了也。
(杨景云)你猜着甚的？(正末云)哥哥，你要搭救爹爹，抢回骨殖去，是么？(杨景云)谁道是俺奶奶来兄弟？既然你知道，他如今把我父亲的骨殖，挂在幽州昊天寺塔尖上，我待要替我父亲盗取这骨殖去，展转寻思，并无妙策。
如之奈何？(正末云)哥哥，别的都去不得，只有您兄弟去得。
(杨景云)兄弟，你若肯去，就是我的重生父母也！(正末云)您兄弟回避！(杨景云)只这一句儿，你就还将我来。
兄弟，恁着你是怎么去？你说一遍咱。
(正末唱)。','',''),('yuanqu-887','昊天塔孟良盗骨・耍孩儿','朱凯','yuanqu','','','则我这慌忙不用别兵甲，轻轻的将衣服来拽扎。
觑着他千军万马只做癞虾蟆，施逞会莽撞拳法。
我脊梁边稳把葫芦放，顽石上扌蚩扌蚩的将斧刃擦。
但撞着无干罢，直杀的他似芟蒲刈苇，截瓠外瓜。
(云)排军，我分付与你两桩儿勾当。
(岳胜云)兄弟，可是那两桩儿？(正末唱)。','',''),('yuanqu-888','昊天塔孟良盗骨・三煞','朱凯','yuanqu','','','准挤着迎魂一首幡，安灵的几朵花，众儿郎都把那麻衣搭，紧拴将亡父驮丧马，哥也你牢背着亲爷的灰骨匣。
孝名儿传天下，说甚的孟宗哭笋。
袁孝拖笆。','',''),('yuanqu-889','昊天塔孟良盗骨・煞尾','朱凯','yuanqu','','','火轮左手拿，管心右手掐。
我摇一摇撼两撼厮琅琅震动琉璃瓦，兀良我与你直推倒了这一座玲珑舍利塔。
(下)。','',''),('yuanqu-890','昊天塔孟良盗骨・正宫/端正好','朱凯','yuanqu','','','只一道火光飞，早四野烟云布，都出在我背上的这葫芦。
火龙万队空中舞，明朗朗正照着那幽州路。','',''),('yuanqu-891','昊天塔孟良盗骨・滚绣球','朱凯','yuanqu','','','烧的来无处居，满城中都痛哭，似伴着老令公灰骨，且休题官法如炉，也不索祭风台，也不索狼烟举，抵多少六丁神发怒，我则见通红了半壁天衢。
恰便似汉张良烧断了连云栈，李老君推番炼药炉，这火也从无。','',''),('yuanqu-892','昊天塔孟良盗骨・倘秀才','朱凯','yuanqu','','','端的是好热闹也禅房寺宇，了得也山僧施主，可不道四大人天火最毒，只我个善知识，没贪图，待布施与你一千枝蜡烛。','',''),('yuanqu-893','昊天塔孟良盗骨・倘秀才','朱凯','yuanqu','','','不甫能撞开了天关地户，跳出这龙潭虎窟。
(云)哥哥小心者。
(杨景云)兄弟也，走便走，你这般叫怎么。
(正末唱)我则怕孟火星今番惹下火烛，疾快的，骤龙驹，紧走些儿路途。','',''),('yuanqu-894','昊天塔孟良盗骨・滚绣球','朱凯','yuanqu','','','人奔似室火猪，马窜如尾火虎，哥也猛回头定睛儿偷觑，咱两个可正是凌烟阁上的人物。
知道是和尚在钵盂在，知道是他受苦也俺受苦？这一场拚着不做，抵多少诸葛也那周瑜。
畅好是焰腾腾博望烧屯计，不刺刺鏖兵赤壁图，不枉了费尽我工夫。','',''),('yuanqu-895','昊天塔孟良盗骨・煞尾','朱凯','yuanqu','','','你牢背着一匣儿骨殖疾归去，休绕着这千里关山放声哭。
(杨景云)呀，后面喊声起，敢是追兵来了也！(正末云)哥哥你先走，等我敌住他。
(唱)猛听的城边喊声举，早卷起足律律一阵黑尘土。
多敢是韩延寿那厮紧追逐，恼了咱嘉州孟太仆。
生咬定牙关自当住，那怕有十面军兵暗埋伏。
且和他战个九千合来决胜负，也不是我杀人心忒狠毒，管教他便人亡马倒都做血糊突。
若放了他一个儿抹的着回家路，哎，兀的不屈沉杀俺宣花也这柄蘸金斧。
(下)。','',''),('yuanqu-896','昊天塔孟良盗骨・双调/新水令','朱凯','yuanqu','','','归来余醉未曾醒，但触着我这秃爷爷没些干净。
(做听科，云)哦，恰像似有人哭哩。
(唱)那哭的莫不是山中老树怪，潭底毒龙精？敢便待显圣通灵，只俺个道高的鬼神敬。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-897','仙吕・赏花时','杨果','yuanqu','','','秋水粼粼古岸苍，萧索疏篱偎短冈。
山色日微茫，黄花绽也，妆点马蹄香。','',''),('yuanqu-898','胜葫芦・见一簇人家入屏帐，竹篱折，补苔墙，破设设柴门上张着破网。','杨果','yuanqu','','','几间茅屋，一竿风旆，摇曳挂长江。','',''),('yuanqu-899','幺・客况凄凄又一春，十载区区已四旬。犹自在红尘，愁眉镇锁，白发又','杨果','yuanqu','','','添新。','',''),('yuanqu-900','煞尾・腹中愁，心间闷，九曲柔肠闷损。白日伤神犹自轻，到晚来更关情。','杨果','yuanqu','','','唱道则听得玉漏声频，搭伏定鲛绡枕头儿盹。
客窗夜水，有谁人存问？二三更睡不得被儿温。
花点苍苔绣不匀，莺唤垂杨语未真。
帘幕絮纷纷，日长人困，风暖兽烟喷。','',''),('yuanqu-901','幺・一自檀郎共锦衾，再不曾暗掷金钱卜远人。香脸笑生春，旧时衣裉，','杨果','yuanqu','','','宽放出二三分。','',''),('yuanqu-902','幺・倚定门儿语笑喧，来往星眸厮顾恋。彼各正当年，花阴柳影，月底共','杨果','yuanqu','','','星前。','',''),('yuanqu-903','仙吕・翠裙腰','杨果','yuanqu','','','莺穿细柳翻金翅，迁上最高枝。
海棠零乱飘阶址，堕胭脂，共谁同唱送春词？。','',''),('yuanqu-904','金盏儿・减容姿，瘦腰肢，绣床尘满慵针指。眉懒画，粉羞施，憔悴死。','杨果','yuanqu','','','无尽闲愁将甚比？恰如梅子雨丝丝。','',''),('yuanqu-905','绿窗愁・有客持书至，还喜却嗟咨。未委归期约几时，先拆破鸳鸯字。原','杨果','yuanqu','','','来则是卖弄他风流浪子，夸翰墨，显文词，枉用了身心空费了纸。','',''),('yuanqu-906','赚尾・总虚脾，无实事，乔问候的言辞怎使？复别了花笺重作念，偏自家','杨果','yuanqu','','','少负你相思。
唱道再展放重读，读罢也无言暗切齿。
沉吟了数次，骂你个负心贼堪恨，把一封寄来书都扯做纸条儿。','',''),('yuanqu-907','月明和尚度柳翠・仙吕/赏花时','李寿卿','yuanqu','','','这月明曾碾破银河万里空，这和尚僻击响金陵半夜钟，端的个洗碧落露浓。
(行者云)你这和尚，风张风势，说谎调皮，没些儿至诚的。
(正末唱)也不是我脱空卖弄，(行者云)正是个风魔和尚，挑着这个，不知是甚么东西，恰似个烧饼的晃子。
你家又不卖饼，要他怎的？不如打破了罢。
(做打破科)(正末唱)呀、呀、呀，则一拳打破了广寒宫。','',''),('yuanqu-908','月明和尚度柳翠・幺篇','李寿卿','yuanqu','','','早不见摊子香飘八月风。
(行者云)八月风腊月雪，冻的要不的。
(正末云)你休笑我。
(唱)这的是蟾影光磨百炼铜，这月曾照兴废古今同，你则看那北邙山的故冢。
(行者云)你这个和尚，则要吃酒吃肉，真是滥僧。
(正末云)谁是真僧。
谁是滥僧？(行者云)我是真僧，你是滥僧。
(正末云)谁是真僧，谁是滥僧？(行者云)你是真僧，我是滥僧，呸，可颠倒了。
(正末云)你和我争甚么人我，那楚家的陵丘，汉家的墓冢，都在那里也呵，你试觑波。
(唱)都一般潇洒月明中。
(下)。','',''),('yuanqu-909','月明和尚度柳翠・仙吕/点绛唇','李寿卿','yuanqu','','','自从五派禅分，要知根本，西来信，则为这懵懂禅昏，我也曾扯住俺那达摩问。','',''),('yuanqu-910','月明和尚度柳翠・混江龙','李寿卿','yuanqu','','','直待要削开混沌，月为精魄柳为魂。
一任着纷纷白眼，管甚么滚滚红尘！恰才个袖拂清风临九陌，又早是杖挑明月可便扣三门。
则为我这半生花酒为檀信，其实的倦贪名利，因此上不断您这腥荤。
(云)有人来问贫僧，如何是佛？我说：你说的便是。
有人来问贫僧：如何是道？我道：你道的便是。
(唱)。','',''),('yuanqu-911','月明和尚度柳翠・鹊踏枝','李寿卿','yuanqu','','','你则合映着孤村，你却待罩着荒坟。
(旦儿云)我这里住如何？(正末云)不争你在这里住呵。
(唱)不甫能栽向东家，却又早苫上西邻。
(旦儿云)我那里听你那风言风语。
(正末云)你可怕那风雨里那，(唱)你休那般絮纷纷似香绵乱滚，柳也，你又早这般安排下断送行人。','',''),('yuanqu-912','月明和尚度柳翠・寄生草','李寿卿','yuanqu','','','早是这光阴速，更那堪岁月紧，现如今章台怕到春光尽，则这霸陵又早秋霜近，直教楚腰傲杀东风困，有一朝花褪彩云飞。
(旦儿云)我还不老哩。
(正末云)噤声！(唱)那里取四时柳色黄金嫩？(旦儿云)师父，你休小觑我，我是那镇陌第一人哩。
(正末唱)。','',''),('yuanqu-913','月明和尚度柳翠・后庭花','李寿卿','yuanqu','','','你道你是镇柳陌第-人，(云)你认的我么？(旦儿云)我不认得你，你可是谁？(正末云)我是和尚中为头的一个子弟。
(旦儿云)那个和尚做子弟来那？(正末云)我说与你我那做子弟处。
(唱)怎知我上花台端的是第一尊。
(旦儿云)俺娘看承我，便是地长出菩提树一般哩。
(正末唱)你娘看承你似地长出菩提树，(云)你敢不是菩提树，(旦儿云)我是甚么？(正末唱)哎，柳也我道来你则是天生来罗汉身。
(旦儿云)谜言谜语，知他说甚的！(正末唱)劝你呵我是劝着一个木头人。
哎，柳也你则恋着那锦营花阵。
(云)你早些儿跟的我出家去罢。
(旦儿云)我怎么出的家？(正末唱)久以后你少不得这埚儿种下祸根。','',''),('yuanqu-914','月明和尚度柳翠・金盏儿','李寿卿','yuanqu','','','你道是花与月添神，我道是月与柳招魂。
你恋着那清阴半亩香千阵。
(旦儿云)你看这世界，全是俺花柳妆点成的。
(正末唱)你道是世间花柳本伶伦，一任你漫天琶柳絮，尽着你满地落风尘，我则去万花丛里过，常是那一叶不沾身。','',''),('yuanqu-915','月明和尚度柳翠・赚煞尾','李寿卿','yuanqu','','','我本待要蟾宫内栽培的你活，哎，柳也你却待向那牛员外上凋零尽。
惹一番信手拈来斧痕。
你则听枝上流莺和泪闻，直等的你那皮故成薪。
你如今正青春，则伴着那暮雨朝云、倚仗着客舍青青柳色新，我本待从根波至本，却把那下梢来不问，哎，柳也，再休提你那永丰坊里旧腰身。
(下)。','',''),('yuanqu-916','月明和尚度柳翠・南吕/一枝花','李寿卿','yuanqu','','','我恰才离了曹溪一指前，又来到佛祖三更后。
我则索分开临济晓，踏破他这葛藤秋。
百般的救不出白骨荒丘，每日家则恋着花和酒。
我今番儿度柳，我是个包含着天地风流，只要你肯信俺这波罗蜜咒。','',''),('yuanqu-917','月明和尚度柳翠・梁州第七','李寿卿','yuanqu','','','投至我度脱的一株翠柳，柳翠口来，少不的搜寻遍四大神州。
你倚仗着枝疏叶嫩当时候，不肯道跨天边彩凤，只待要听枝上鸣鸠。
你可也锁不住心猿意马，却罩定野鹭沙鸥。
你则恋着他那一时间翠嫩青柔，怎不想久以后绿惨红愁。
(带云)柳也，你若肯跟我出家去呵，(唱)我着你再休恋那红尘内赤力力虎斗龙争，碧天边来往往乌飞兔走，柳翠崃，早思着绿阴中闹簇簇燕侣莺俦，酒楼，玉沟，跳出那月明圈，不落樵夫勾。
比及个成材时架梁后，饶你便坚硬心肠似木头，我只着你磨做骷髅。','',''),('yuanqu-918','月明和尚度柳翠・隔尾','李寿卿','yuanqu','','','你道是月过十五也索还依旧，哎，柳也，谁似你飞尽香绵未肯休，直等的絮满了官街，那其间有谁救？(旦儿云)师父。
长老寻你哩。
(做走科)(正末云)那里去？你待要躲我那。
(唱)哎，你个迷人的好是费手。
(旦儿云)师父，行者寻你哩。
(做走科)(正末云)那里去？你又躲我那。
(唱)我这个度人的好是缠头。
(旦儿云)师父，我两次三番躲不过你。
(正末云)你怎生躲的过我？(唱)谁着你惹一缕清风则在这背巷里走。','',''),('yuanqu-919','月明和尚度柳翠・隔尾','李寿卿','yuanqu','','','你本恋着朝云暮雨慵回首，却被这明月清风缠杀你那头，不肯将七碗卢仝耐心候。
你解不过这赵州，省不得这悟头。
柳翠口来，你不向野塘内三眠，偏来渲房取宿。','',''),('yuanqu-920','月明和尚度柳翠・牧羊关','李寿卿','yuanqu','','','你觑那牛头鬼亲行刃，他把的龙泉剑扯在手。
(带云)柳翠，你若不是我呵，(唱)恰才这清风过，怎了你那六阳会首。
你跟我去呵，我着你剩积些阴功；你不跟我去呵，早早定了些阳寿。
你跟我去呵，我着你上明晃晃一条金桥路；你不跟我去呵，便索向翻滚滚千丈奈河流。
恰才那脖项上可着那钢刀挫。
哎，柳翠也，抵多少树叶儿便打破你这头。
(云)且留人者。
(阎神云)早知圣僧来到，只合远接，接待不着，勿令见罪。
(正末云)阎神，柳翠犯着何罪？(阎神云)因柳翠触污着圣僧来。
(正末云)柳翠的罪过，饶的也饶不的？(阎神云)柳翠的罪过，饶他不的。
鬼力快下手者。
疾，休推睡里梦里。
(旦儿做惊醒科，云)兀的不吓杀我也。
(正末唱)。','',''),('yuanqu-921','月明和尚度柳翠・感皇恩','李寿卿','yuanqu','','','呀，则见他刀下难收，早吓的汗雨交流，荡了香魂，消了素魄，瞪了星眸。
他用着春纤玉手，忙抹这粉颈油头。
(旦儿云)这的是那里？(正末唱)这的茶房里，桌儿前。
(旦儿云)这早晚多早晚也？(正末唱)柳翠也，这早晚是午时候。','',''),('yuanqu-922','月明和尚度柳翠・采茶歌','李寿卿','yuanqu','','','这的是剑光浮，那里也鬼神愁。
(带云)柳翠，你觑波。
(唱)兀的不一轮明月在柳梢头。
枝叶相连百十口，则你那翠眉终日端的为谁愁？(旦儿云)恰才分明的杀坏了我，却又不曾死。
我待道死来却又生，待道生来却又死。
生死原来是幻情，幻情灭尽生死止。
(正末云)假若生死止在何处？速道，速道。
(旦儿云)师父，我答不的这一转语。
(正末云)云来云去，虚空本净。
花开花谢，田地常存。
(旦儿做拜科，云)弟子早省悟了。
这回和月常相守也。
(正末唱)。','',''),('yuanqu-923','月明和尚度柳翠・黄钟尾','李寿卿','yuanqu','','','你道是这回和月常相守，(带云)我为你走了两番也。
(唱)才赚的春风可便树点头。
聚莺朋，会燕友，蜂衙喧，蝶梦幽，啭黄鹂，鸣锦鸠，噪昏鸦，覆野鸥，袅金丝，春水沟，拂红裙，夜月楼，酒旗前，望竿后，风又狂，雨又骤，霜正严，雪正厚，霜来欺，月来救，我救的这月里杪椤永长寿。
(旦儿云)师父，你如今带我那里去？(正末唱)我着你访灵山会首。
(旦儿云)待我辞别那一班儿姊妹弟兄就跟的去。
(正末唱)也不索别章台的这故友。
(旦儿云)师父，为什么不着我别去？(正末云)你道我为甚么不着你别去？(唱)我则怕你又折入情郎画眉手。
(同下)。','',''),('yuanqu-924','月明和尚度柳翠・中吕/粉蝶儿','李寿卿','yuanqu','','','投至我度脱的你心回，我着你做师姑大刚来有一个主意，常言道柳絮不沾泥。
(带云)柳翠，你跟将我来呵，(唱)不强如万人攀，千人折，我则怕损动了你这春风和气。
盖因是暮景相催，催的你这瘦伶仃可便翠腰无力。','',''),('yuanqu-925','月明和尚度柳翠・醉春风','李寿卿','yuanqu','','','早是这日月似飞梭，光阴如逝水。
你看那席前花影坐间移，想人生能有有几几？参透禅关，了达身命，出离尘世。','',''),('yuanqu-926','黄钟・人月圆甘露怀古','徐再思','yuanqu','','','江皋楼观前朝寺，秋色入秦淮。
败垣芳草，空廊落叶，深砌苍苔。
远人南去，夕阳西下，江水东来。
木兰花在，山僧试问，知为谁开？兰亭茂林修竹风流地，重到古山阴。
壮怀感慨，醉眸俯仰，世事浮沉。
惠风归燕，团沙宿鹭，芳树幽禽。
山山水水，诗诗酒酒，古古今今。','',''),('yuanqu-927','黄钟・红锦袍','徐再思','yuanqu','','','那老子爱清闲主意别，钓桐江江上雪，泛桐江江上月。
君王想念者；宣到凤凰阙。
想着七里渔滩，将着一钩香饵，望着富春山归去也。
那老子陷身在虎狼穴，将夫差仇恨雪，进西施谋计拙。
若不早去些，乌喙意儿别。
驾着一叶扁舟，披着一蓑烟雨，望他五湖中归去也。
那老子见高皇斩了蛇，助萧何立大节，荐韩侯劳汗血。
渔樵做话说，千古汉三杰。
想着云外青山，纳了腰间金印，伴赤松子归去也。
那老子觑功名如梦蝶，五斗米腰懒折，百里侯心便舍。
十年事可嗟，九日酒须赊，种着三径黄花，栽着五株杨柳，望东篱归去也。','',''),('yuanqu-928','仙吕・一半儿病酒','徐再思','yuanqu','','','昨宵中酒懒扶头，今日看花惟袖手，害酒愁花人问羞。
病根由，一半儿因花一半儿酒。
落花河阳香散唤提壶，金谷魂消啼鹧鸪，隋苑春归闻杜宇。
片红无，一半儿狂风一半儿雨。
春情眉传雨恨母先疑，眼送云情人早知，口散风声谁唤起。
这别离，一半儿因咱一半儿你。','',''),('yuanqu-929','中吕・朝天子西湖','徐再思','yuanqu','','','里湖，外湖，无处是无春处。
真山真水真画图，一片玲珑玉。
宜酒宜诗，宜晴宜雨。
销金锅锦绣窟，老苏，老逋，杨柳堤梅花墓。
手帕酒痕，泪痕，半带着胭脂润。
鲛渊一片玉霄云，缕缕东风恨。
待写回文，敷陈方寸，怕莺花说与春。
使人，赠君，寄风月平安信。
常山江行远山，近山，一片青无间。
逆流流流诉上乱石滩，险似连云栈。
落日昏鸦，西风归雁，叹崎岖途路难。
得闲，且闲，何处无鱼羹饭？杨姬艳冶，唱彻，〔金缕〕歌全阕。
秋娘声价有谁轶？曾奉黄金阙。
歌扇生春，舞裙回雪，不风流不醉也。
舞者，唱者，一曲秦楼月。','',''),('yuanqu-930','中吕・满庭芳赠歌者','徐再思','yuanqu','','','犀梳玉簪，歌裙翠浅，舞袖红深。
风流消得缠头锦，一笑千金。
痛饮时花前痛饮，知音人席上知音。
春无禁，蜂蝶快寻，先到海棠心。','',''),('yuanqu-931','中吕・红绣鞋雪','徐再思','yuanqu','','','白鹭交飞溪脚，玉龙横卧山腰，满干坤无处不琼瑶。
因风吹柳絮，和月点梅梢，想孤山鹤睡了。
半月泉凿透林间山溜，平分天上中秋，菱花分破印寒流。
沁梅疏影缺，攀桂片云愁，待团圆掬在手。
道院一榻白云竹径，半窗明月松声，红尘无处是篷瀛。
青猿藏火枣，黑虎听《黄庭》，山人参内景。','',''),('yuanqu-932','中吕・阳春曲皇亭晚泊','徐再思','yuanqu','','','水深水浅东西涧，云去云来远近山。
秋风征棹钓鱼滩，烟树晚，茅舍两三间。
双渐苏卿倦织回文锦，双渐空怀买笑金。
风流一点海棠心，不听琴，只是不知音。
春情桃花月淡胭脂冷，杨柳风微翡翠轻。
玉人欹枕倚云屏，酒未醒，肠断紫箫声。
闺怨妾身悔作商人妇，妾命当逢薄幸夫。
别时只说到东吴，三载余，却得广州书。
赠海棠玉环梦断风流事，银烛歌成富贵词。
东风一树玉胭脂，双燕子，曾见正开时。
春思酒醒眉记青鸾恨，春去香消紫燕尘。
阑干掐遍月儿痕，深闭门，花落又黄昏。','',''),('yuanqu-933','越调・小桃红花篮区髻','徐再思','yuanqu','','','东风攒簇一筐春，吹在秋蝉鬓，玉露凝香宝钗润。
绿无尘，同心双挽蜂蝶阵。
群芳顶上，连环枝下，分断楚山云。','',''),('yuanqu-934','越调・天净沙探梅','徐再思','yuanqu','','','昨朝深雪前村，今宵淡月黄昏，春到南枝几分？水香冰晕，唤回逋老诗魂。
吕侯席上素波笑浅流花，轻衫舞争飘霞，席上司空鬓华。
酒阑歌罢，不知春在谁家？别高宰青山远远天台，白云隐隐萧台，回首江南倦客。
西湖诗债，梅花等我归来。
春情双双翠舞珠歌，卿卿酒病花魔，为问风流玉娥。
海棠开过，牡丹消息如何？渔父忘形雨笠烟蓑，知心牧唱樵歌，明月清风共我。
闲人三个，从他今古消磨。
秋江夜泊斜阳万点昏鸦，西风两岸芦花，船系浔阳酒家。
多情司马，青衫梦里琵琶。
题情多才惹得多愁，多情便有多忧，不重不轻证候。
甘心消受，谁教你会风流？。','',''),('yuanqu-935','双调・沉醉东风息斋画竹','徐再思','yuanqu','','','葛陂里神龙蜕形，丹山中彩凤栖庭。
风吹粉箨香，雨洗苍苔冷，老仙翁笔底春生。
明月阑干酒半醒，对一片儿潇湘翠影。
春情一自多才间阔，几时盼得成合。
今日个猛见他门前过，待唤着怕人瞧科。
我这里高唱当时《水调歌》，要识得声音是我。
红灼灼花明翠牖。
翠丝丝柳拂青楼。
锦谷春，银瓶酒，玉天仙燕体莺喉。
不向樽前醉后休，枉笑煞花间四友。','',''),('yuanqu-936','双调・蟾宫曲西湖','徐再思','yuanqu','','','十年不到湖山，齐楚秦燕，皓首苍颜。
今日重来，莺嫌花老，燕怪春悭。
听越女鸾箫象板，恼司空雾鬓云环。
道院弹关，酒会诗坛，万古西湖，天上人间。
钱子云赴都赋河梁渺渺予怀，今日阳关，明日秦淮。
鹏翼风云，龙门波浪，马足尘埃。
宽洗汕胸中四海，便蜚腾天上三台。
休等书斋，梅子花开，人在江南，先寄诗来。
江淹寺紫霜毫是是非非，万古虚名，一梦初回。
失又何愁？得之何喜？闷也何为？落日外萧山翠微，小桥边古寺残碑。
文藻珠玑，醉墨淋淳，何似班超，投却毛锥。
登太和楼白云中涌出蓬莱，俯视西湖，图画天开。
暮雨珠帘，朝云画栋，夜月瑶台。
书籍会三千剑客，管弦声十二金钗。
对酒兴杯，拊髀怜才，寄语玲珑，王粲曾来。
竹夫人湘妃应是前身，不记何年，封虢封秦。
万古虚心，百年贞节，一世故人。
剖苍壁寒凝泪痕，挽潜蛟巧结香纹。
侍枕知恩，入梦无春，两腋清风，满枕行云。
姑苏台荒台谁唤姑苏？兵渡西兴，祸起东吴。
切齿仇冤，捧心钓饵，尝胆权谋。
三千尺侵云粪土，十万家泣血膏腴。
日月居诸，台殿丘墟。
何似灵岩，山色如初。
名姬玉莲荆山一片玲珑，分付冯夷，捧出波中。
白羽香寒，琼衣露重，粉面冰融。
知造化私加密宠，为风流洗尽娇红。
月对芙蓉，人在帘栊。
太华朝云，太液秋风。
春情平生不会相思，才会相思，便害相思。
身似浮云，心如飞絮，气若游丝。
空一缕余香在此，盼千金游子何之。
证候来时，正是何时？灯半昏时，月半明时。
西湖寻春清明春色三分，湖上行舟，陌上游人。
一片花阴，两行柳影，十里莎ブ。
不要多ゾ排一品，休嫌少酒止三巡。
处处开樽，步步寻春。
花下归来，带月敲门。
送沙宰宦游人过钱塘，江水汤汤，山色苍苍。
马首西风，鸡声残月，雁影斜阳。
男子志周流四方，循吏心恪守三章。
岐麦林桑，渡虎驱蝗。
人颂《甘棠》，春满琴堂。
月问青天呼酒重倾，几度盈亏，几度阴晴。
夜冷鱼沉，山空鹤唳，露滴乌惊。
看杨柳楼心弄影，听梨花树底吹笙。
雪与争明，风与双清。
玉兔韬光，万古长生。
赠粉英温柔乡里娉婷，清比梅花，更有余清。
玉蕊含香，琼蕤沁月，瑶萼裁冰。
冠杨柳东风媚景，赋芙蓉夜月幽情。
花下苏卿，月下崔莺，世上飞琼，天上双成。
西湖夏宴卷荷筒翠袖生香，忙处投闲，静处寻凉。
一片歌声，四围山色，十里湖光。
只此是人间醉乡，更休题天上天堂。
老子疏狂，信手新词，赠与秋娘。
红梅蕊珠宫内琼姬，醉倚东风，谁与更衣？血泪痕深，茜裙香冷，粉面春回。
桃杏色十分可喜，冰霜心一片难移。
何处长笛？吹散胭脂，分付春归。','',''),('yuanqu-937','双调・清江引苕溪','徐再思','yuanqu','','','驼风两桥分燕尾，人物风流地。
白云四面山，明月双溪水，身在董元图画里。
盘龙寺山僧定回月半吐，叱咤神龙处。
空廊旧爪痕，古殿新盘路，卷起讲华台下雨。
春夜云间玉箫三四声，人倚阑干听。
风生翡翠棂，露滴梧桐井，明月半帘花弄影。
私欢梧酮画阑明月斜，酒散笙歌歇。
梅香走将来，耳畔低低说：后堂中正夫人沉醉也。
笑靥儿东风不知何处来？吹动胭脂色。
旋成一点春，添上十分态，有千金俏人儿谁共买。
相思相思有如少债的，每日相催逼。
常挑着一担愁，准不了三分利，这本钱见他时才算得。','',''),('yuanqu-938','双调・寿阳曲梅影','徐再思','yuanqu','','','枝横水，花未雪，镜中春玉痕明灭。
梨云梦残人瘦也，弄黄昏半窗明月。
手帕香多处，情万缕，织春愁一方柔玉。
寄多才怕不知心内苦，带胭脂泪痕将去。
春情心疼事，肠断词，背秋千泪痕红渍。
剔春纤碎榴花瓣儿，就窗纱砌成愁字。
昨宵是，你自说，许是咱这般时节。
到西厢等的人静也，又不成再推明夜。
闲情绪，深院宇，正东风满帘飞絮。
怕梨花不禁三月雨，是谁教燕衔春去？醉姬绯霞佩，金缕衣，枕东风美人深醉。
便休将玉箫花下吹，怕惊回海棠春睡。
柳腰连环玉，一搦酥，舞春风柳丝相妒。
沈东阳带红香双抱住，怕随着彩云飞去。','',''),('yuanqu-939','双调・水仙子夜雨','徐再思','yuanqu','','','一声梧叶一声秋，一点芭蕉一点愁，三更归梦三更后。
落灯花棋未收，叹新丰孤馆人留。
枕上十年事，江南二老忧，都到心头。
弹唱佳人玉纤流恨出冰丝，瓠齿和春吐怨辞，秋波送巧传心事。
似邻船初听时，问江州司马何之。
青衫泪，锦字诗，总是相思。
红指甲落花飞上笋牙尖，宫叶犹将冰箸粘，抵牙关越显得樱唇艳。
怕伤春不卷帘，捧菱花香印妆奁。
雪藕丝霞十缕，镂枣班血半点，掐刘郎春在纤纤。
佳人钉履金莲脱瓣载云轻，红叶浮香带雨行，渍春泥印在苍苔径。
三寸中数点星，玉玲珑环佩交鸣。
溅越女红裙湿，沁湘妃罗袜冷，点寒波小小蜻蜓。
春情九分恩爱九分忧，两处相思两处愁，十年迤逗十年受。
几遍成几遍休，半点事半点惭羞。
三秋恨三秋感旧，三春怨三春病酒，一世害一世风流。
青玉花筒蜂房分蜜入乌云，莺嘴流金拂翠颦，鸾钗嵌玉浮红晕。
似蕊珠宫内人，虚心腹管束东君。
两朵儿瑶花弄色，半缕儿香绵沁粉，一泓儿碧露涵春。
重九东篱重赋紫萸诗，北海深倾白玉卮，西风了却黄花事。
是渊明酒醉时，笑人间名利孜孜。
钻醯瓮，检故纸，再谁题归去来兮？马嵬坡翠华香冷梦初醒，黄壤春深草自青，羽林兵拱听将军令。
拥鸾舆蜀道行，妾虽亡天子还京。
昭阳殿梨花月色，建章宫梧桐雨声，马嵬坡尘土虚名。
惠山泉自天飞下九龙涎，走地流为一股泉，带风吹作千寻练。
问山僧不记年，任松梢鹤避青烟。
湿云亭上，涵碧洞前，自采茶煎。','',''),('yuanqu-940','双调・殿前欢钓台','徐再思','yuanqu','','','钓鱼台，便齐云安稳似云台。
故人同榻成何碍，太史瘦哉。
三台宰相阶，百两黄金带，万丈风波海。
争如休去，胜似归来。
杨总管玉堂臣，经纶大展致其身。
腰间斗大黄金印，志在新民。
文章汉子云，韬略吴公瑾，勋业商伊尹。
一番桃李，两字麒麟。
观音山眠松老苍龙，避乖高卧此山中。
岁寒心不肯为梁栋，翠蜿蜒俯仰相从。
秦皇旧日封，靖节何年种？丁固当时梦，半溪明月，一枕清风。','',''),('yuanqu-941','双调・卖花声','徐再思','yuanqu','','','雪儿娇小歌《金缕》，老子婆娑倒玉壶，满身花影倩人扶。
昨宵不记，雕鞍归去，问今朝酒醒何处？碧桃红杏桃源路，绿水青山水墨图，杖头挑着酒胡芦。
行行觑着，山童分付，问前村酒家何处？红罗佩吐狮头玉，碧珥香衔凤口珠，风流相遇恨须臾。
梨花淡月，楼台如故，教吹箫玉人何处？云深不见南来羽，水远难寻北去鱼，两年不寄半行书。
危楼目断，云山无数，望天涯故人何处？。','',''),('yuanqu-942','桃花女破法嫁周公・仙吕/点绛唇','王晔','yuanqu','','','俺则见四野田畴，禾苗丰茂。
登场后，鼓腹歌讴，现如今无士马绝征斗。','',''),('yuanqu-943','桃花女破法嫁周公・油葫芦','王晔','yuanqu','','','你两个自小儿相随到白头，端的是老故友，但同行共坐笑无休。
我则道别逢闲汉频摇手，你可也敢则是饱谙世事慵开口。
俺则见这壁厢闷闷的迎，那壁厢郁郁的忧。
(带云)伯伯。
(唱)你为甚么这等悄无言则办的眉儿皱，泪簌簌不住点儿流？(云)伯伯，我去整治些酒菜儿来，与俺父亲饮几杯去。
(唱)。','',''),('yuanqu-944','桃花女破法嫁周公・天下乐','王晔','yuanqu','','','却不道一盏能消万古愁，则俺这村也波坊，不比那府共州，那里取笙歌绮罗拥上楼。
这快乐俺这里无，这快乐您那里有。
伯伯也俺这里止不过是村务酒。','',''),('yuanqu-945','桃花女破法嫁周公・寄生草','王晔','yuanqu','','','俺这里有的是黄鸡嫩，白酒熟，伯伯也你莫不为茅檐草舍庄家陋？(彭大云)俺每都是庄农人家，一村疃儿居住的，有甚么好房子在那里？(正旦云)我也道来。
(唱)也一般儿青山绿树风光秀，(带云)况我父亲呵，(唱)又和你倾心吐胆交情厚。
(彭大云)儿也，你不知道。
我家主人周公，今日与我算一卦，道我没寿，以此吃酒不下。
(正旦云)伯伯，你没寿今年也六十九岁了。
(唱)但愿的乐丰年醉倒有百千场，何必要炼丹砂学取那松乔寿？。','',''),('yuanqu-946','正宫・鹦鹉曲','冯子振','yuanqu','','','序云：白无咎有〔鹦鹉曲〕云：“侬家鹦鹉洲边住，是个不识字渔父。
浪花中一叶扁舟，睡煞江南烟雨。
觉来时满眼青山，抖擞绿蓑归去。
算从前错怨天公，甚也有安排我处。
”余壬寅岁留上京，有北京伶妇御园秀之属，相从风雪中，恨此曲无续之者。
且谓前后多亲炙士大夫，拘于韵度，如第一个“父”字，便难下语；又“甚也有安排我处”，“甚”字必须去声字，“我”字必须上声字，音律始谐，不然不可歌，此一节又难下语。
诸公举酒，索余和之，以汴、吴、上都、天京风景试续之。
山亭逸兴嵯峨峰顶移家住，是个不唧溜樵父。
烂柯时树老无花，叶叶枝枝风雨。','',''),('yuanqu-947','・故人曾唤我归来，却道不如休去。指门前万叠云山，是不费青蚨买处。荣华短梦','冯子振','yuanqu','','','幺朱门空宅无人住，村院快活煞耕父。
霎时间富贵虚花，落叶西风残雨。','',''),('yuanqu-948','・总不如水北相逢，一棹木兰舟去。待霜前雪后梅开，傍几曲寒潭浅处。愚翁放浪','冯子振','yuanqu','','','幺东家西舍随缘住，是个忒老实愚父。
赏花时暖薄寒轻，彻夜无风无雨。','',''),('yuanqu-949','・占长红小白园亭，烂醉不教人去。笑长安利锁名缰，定没个身心稳处。农夫渴雨','冯子振','yuanqu','','','幺年年牛背扶犁住，近日最懊恼杀农父。
稻苗肥恰待抽花，渴煞青天雷雨。','',''),('yuanqu-950','幺・恨残霞不近人情，截断玉虹南去。望人间三尺甘霖，看一片闲云起处。燕南百五','冯子振','yuanqu','','','东风留得轻寒住，百五闹蝶母峰父。
好花枝半出墙头，几点清明微雨。','',''),('yuanqu-951','・绣弯弯湿透罗鞋，绮陌踏青回去。约明朝后日重来，靠浅紫深红暖处。故园归计','冯子振','yuanqu','','','幺重来京国多时住，恰做了白发伧父。
十年枕上家山，负我湘烟潇雨。','',''),('yuanqu-952','幺・','冯子振','yuanqu','','','断回肠一首阳关，早晚马头南去。
对吴山结个茅庵，画不尽西湖巧处。
野渡新晴孤村三两人家住，终日对野叟田父。
说今朝绿水平桥，昨日溪南新雨。','',''),('yuanqu-953','・碧天边云归岩穴，白鹭一行飞去。便芒鞋竹杖行春，问底是青帘舞处。渔父','冯子振','yuanqu','','','幺沙鸥滩鹭衤离依住，镇日坐钓叟纶父。
趁斜阳晒网收竿，又是南风催雨。','',''),('yuanqu-954','幺・绿杨堤忘系孤桩，白浪打将船去。想明朝月落潮平，在掩映芦花浅处。市朝归兴','冯子振','yuanqu','','','山林朝市都曾住，忠孝两字报君父。
利名场反覆如云，又要商量阴雨。','',''),('yuanqu-955','・便天公有眼难开，袖手不如家去。更蛾眉强学时妆，是老子平生懒处。陆羽风流','冯子振','yuanqu','','','幺儿啼漂向波心住，舍得陆羽唤谁父？杜司空席上从容，点出茶瓯花雨。','',''),('yuanqu-956','・散蓬莱两腋清风，未便玉川仙去。待中泠一滴分时，看满注黄金鼎处。顾渚紫笋','冯子振','yuanqu','','','幺春风阳羡微喧住，顾渚问苕叟吴父。
一枪旗紫笋灵芽，摘得和烟和雨。','',''),('yuanqu-957','・焙香时碾落云飞，纸上凤鸾衔去。玉皇前宝鼎亲尝，味恰到才情写处。园父','冯子振','yuanqu','','','幺柴门鸡犬山前住，笑语听伛背园父。
辘轳边抱瓮浇畦，点点阳春膏雨。','',''),('yuanqu-958','・菜花间蝶也飞来，又趁暖风双去。杏梢红韭嫩泉香，是老瓦盆边饮处。野客','冯子振','yuanqu','','','幺春归不恋风光住，向老拙问讯槎父。
叹匡山李白漂零，寂寞长安花雨。','',''),('yuanqu-959','・指沧溟铁网珊瑚，袖卷钓竿西去。锦袍空醉墨淋漓，是万古声名响处。城南秋思','冯子振','yuanqu','','','幺新凉时节城南住，灯火诵鲁国尼父。
到秋来宋玉生悲，不赋高唐云雨。','',''),('yuanqu-960','・一声声只在芭蕉，断送别离人去。甚河桥柳树全疏，恨正在长亭短处。赤壁怀古','冯子振','yuanqu','','','幺茅庐诸葛亲曾住，早赚出抱膝梁父。
笑谈间汉鼎三分，不记得南阳耕雨。','',''),('yuanqu-961','幺・叹西风卷尽豪华，往事大江东去。彻如今话说渔樵，算也是英雄了处。处士虚名','冯子振','yuanqu','','','高人谁恋朝中住，自古便有个巢父。
子陵滩钓得虚名，几度桐江春雨。','',''),('yuanqu-962','・睡神仙别有陈抟，拂袖华山归去。漫纷纷少室终南，怎不是神仙隐处？洞庭钓客','冯子振','yuanqu','','','幺年光流水何曾住，早忘却姓吕岩父。
记蓬莱阆苑相逢，一别风流如雨。','',''),('yuanqu-963','・算人间碧海桑田，只似燕鸿来去。岳阳楼剑气凌云，度老树神仙此处。黄阁清风','冯子振','yuanqu','','','幺箕尾傅说商岩住，空桑子伊尹无父。
汉萧何昴宿分英，李靖唐时行雨。','',''),('yuanqu-964','・出山来济了苍生，却卷白云闲去。一千年黄阁清风，是万古声名响处。夷门怀古','冯子振','yuanqu','','','幺人生只合梁园住，快活煞几个白头父。
指他家五辈风流，睡足胭脂坡雨。','',''),('yuanqu-965','幺・说宣和锦片繁华，辇路看元宵去。马行街直转州桥，相国寺灯楼几处。都门感旧','冯子振','yuanqu','','','都门花月蹉跎住，恰做了白发伧父。
酒微醒曲榭回廊，忘却天街酥雨。','',''),('yuanqu-966','诈妮子调风月・上小楼','关汉卿','yuanqu','','','我敢摔碎这盒子，玳瑁纳子，教石头砸碎。
（带云）这手帕。
（唱）剪了做靴檐，染了做鞋面，持了做铺持。
一万分好待你，好觑你！如今刀子根底，我敢割得来粉零麻碎！。','',''),('yuanqu-967','诈妮子调风月・幺','关汉卿','yuanqu','','','更做道你好处打唤来的，却怎看得非轻，看得值钱，待得尊贵？这两下里捻捎的，有多少功绩，到重如细搀绒绣来胸背？。','',''),('yuanqu-968','诈妮子调风月・哨遍','关汉卿','yuanqu','','','并不是婆娘人把你抑勒，招取那肯心儿自说来的神前誓。
天果报，无差移，子争个来早来迟。
限时刻，十王地藏，六道轮回，单劝化人间世。
善恶天心人意，"人间私语，天闻若雷"。
但年高都是积善好心人；早寿夭都是辜恩负德贼。
好说话清晨，变了卦今日，冷了心晚夕。','',''),('yuanqu-969','诈妮子调风月・五煞','关汉卿','yuanqu','','','别人斩眉我早举动眼，道头知道尾。
你这般沙糖般甜话儿多曾吃！你又不是"残花酝酿蜂儿蜜，细雨调和燕子泥"。
自笑我狂踪迹。
我往常受那无男儿烦恼，今日知有丈夫滋味。','',''),('yuanqu-970','诈妮子调风月・四煞','关汉卿','yuanqu','','','待争来怎地争？待悔来怎地悔？怎补得我这有气分全身体？打也阿儿包髻，真加要带与别人成美，况团衫怎能勾披？他若不在俺宅司内，便大家南北，各自东西！。','',''),('yuanqu-971','诈妮子调风月・三煞','关汉卿','yuanqu','','','明日索一般供与他衣袂穿，一般过与他茶饭吃，到晚送得他被底成双睡。
他"做成暖帐三更梦"，我"拨尽寒炉一夜灰"。
有句话存心记：则愿得辜恩负德，一个个荫于封妻！。','',''),('yuanqu-972','诈妮子调风月・二煞','关汉卿','yuanqu','','','出门来一脚高一脚低，自不觉鞋底儿着田地。
痛连心除他外谁根前说，气夯破肚别人行怎又不敢提？独自向银蟾底，则道是孤鸿伴影，几时吃四马攒蹄？。','',''),('yuanqu-973','诈妮子调风月・尾','关汉卿','yuanqu','','','呆敲才、呆敲才休怨天；死贱人、死贱人自骂你！本待要皂腰裙，刚待要蓝包髻，则这的是折挂攀高落得的！（下）。','',''),('yuanqu-974','诈妮子调风月・越调/斗鹌鹑','关汉卿','yuanqu','','','短叹长吁，千声万声；捣枕捶床，到三更四更。
便似止渴思梅，充饥画饼，因甚顷刻体？则伤我取次成。
好个个舒心，干支刺没兴。','',''),('yuanqu-975','诈妮子调风月・紫花儿序','关汉卿','yuanqu','','','好轻乞列薄命，热忽刺姻缘，短古取恩情。
（见灯蛾科，云）哎！蛾儿，俺两个有比喻：见一个耍蛾儿来往向烈焰上飞腾，正撞着银灯，拦头送了性命。
咱两个堪为比并：我为那包譬白身，你为这灯火青荧。','',''),('yuanqu-976','诈妮子调风月・幺篇','关汉卿','yuanqu','','','我把这银灯来指定，引了咱两个魂灵，都是这一点虚名。
怕不百伶百俐，千战千赢，更做道"能行怎离得影"？这一场其身不正，怎当那厮大四至铺排，小夫人名称？。','',''),('yuanqu-977','诈妮子调风月・梨花儿','关汉卿','yuanqu','','','是教我软地上吃交，我也不共你争。
煞是多劳重，降尊临卑，（云）有劳长者车马，贵脚踏于贱地，小的每多谢承。
本待麻线道上不和你一处行；（云）你依得我一件事，依得我愿随鞭镫。
（云）你要我饶你咱，再对星月赌一个誓。
（云了）（出门了）（正旦唱）。','',''),('yuanqu-978','诈妮子调风月・紫花儿序','关汉卿','yuanqu','','','你把遥天指定，指定那淡月疏星，再说一个海誓山盟；我便收撮了火性，铺撒了人情，忍气吞声，饶过你那亏人不志诚。
赚出门程，（入房科）呼的关上栊门，铺的吹灭残灯。','',''),('yuanqu-979','诈妮子调风月・小桃红','关汉卿','yuanqu','','','燕燕上复传示煞曾经，谁会甚儿女成婚聘？甚的是许出羞、下红定？问这洛阳城，少甚么能言快语官媒证？燕燕怎敢假名托姓？但教我一权为政，情取"火上等冬凌"。','',''),('yuanqu-980','诈妮子调风月・调笑令','关汉卿','yuanqu','','','这厮短命，没前程，做得个"轻人还自轻"，横死口里栽排定。
老夫人随邪水性，道我能言快语说合成，我说波娘七代先灵！，。','',''),('yuanqu-981','诈妮子调风月・圣药王','关汉卿','yuanqu','','','然道户厮迎，也合再打听，两门亲便走一遭儿成。
我若到那户庭，见那婢婷，若是那女孩儿言语没实诚，俺这厮强风情。
（虚下）（外孤上）（旦上，见孤云）夫人使来问小姐亲事，相公许不许，燕燕回去。
（外孤云了）（闪下）（外旦上）（旦随上，见了，云）特地来问小姐亲事，许不许？回去。
（外旦许了）（正旦唱）。','',''),('yuanqu-982','诈妮子调风月・天净沙','关汉卿','yuanqu','','','先教人掩扑了我几夜恩情，来这里被他骂得我百节酸疼，我便似□墙贼蝎蜇呼声。
空使心作幸，被小夫人引了我魂灵。','',''),('yuanqu-983','诈妮子调风月・拙鲁速','关汉卿','yuanqu','','','终身无簸箕星，指云中雁做羹。
时下且口口声声，战战兢兢，袅袅婷婷，坐坐行行；有一日孤孤另另，冷冷清清，咽咽哽哽，觑着你个拖汉精！。','',''),('yuanqu-984','诈妮子调风月・收尾','关汉卿','yuanqu','','','大刚来"主人有福牙推胜"，不似这调风月媒人背厅。
说得他美甘甘枕头儿上双成，闪得我薄设设被窝儿里冷！（下）。','',''),('yuanqu-985','诈妮子调风月・双调/新水令','关汉卿','yuanqu','','','双撒敦是部尚书，女婿是世袭千户。
有二百匹金勒马，五十辆画轮车。
说得他儿女妻夫，似水如鱼；撇得我鳏寡孤独，那的是撮合山养身处？。','',''),('yuanqu-986','诈妮子调风月・驻马听','关汉卿','yuanqu','','','官人石碾连珠，满腰背无瑕玉免鹘；夫人每是依时按序，细搀绒全套绣衣服。
包髻是缨络大真珠，额花是秋色玲珑玉。
悠悠的品着鹧鸪，雁行般但举手都能舞。','',''),('yuanqu-987','诈妮子调风月・甜水令','关汉卿','yuanqu','','','姐姐骨甜肉净，堪描堪塑。
生得肌肤似凝酥。
从小里梅香、嬷嬷抬举，问燕燕梳裹何如？。','',''),('yuanqu-988','诈妮子调风月・水仙子','关汉卿','yuanqu','','','推那领系眼落处，采揪住那系腰行行掐胯骨。
我这般拈拈掐掐有甚难当处？想我那声冤不得苦痛处。
你不合先发头怒；你若无言语，怎敢将你觑付，你则索做使长、郎主。','',''),('yuanqu-989','诈妮子调风月・殿前欢','关汉卿','yuanqu','','','俺千户跨龙驹，称得上的敢望七香车。
愿结同心结，永挂合欢树。
蛮凤娇雏，连理枝比目鱼。
千载相完聚，花发无风雨。
头白相守，眼黑处全无。','',''),('yuanqu-990','诈妮子调风月・乔牌儿','关汉卿','yuanqu','','','勘婚处恰岁数，出嫁后有衣禄。
若言招女婿，下财钱将娶过去。','',''),('yuanqu-991','诈妮子调风月・挂玉钩','关汉卿','yuanqu','','','是个破败家私铁扫帚，没些儿发旺夫家处，可更绝子嗣、妨公婆、克丈夫，脸上承泪靥无重数。
今年见吊客临，丧门聚；反阴覆阴，半载其余。','',''),('yuanqu-992','诈妮子调风月・落梅风','关汉卿','yuanqu','','','据着生的年月，演的岁数，不是个义夫节妇，休想得五男并二女，死得教灭门绝户！（夫人云了）（旦跪唱）。','',''),('yuanqu-993','诈妮子调风月・雁儿落','关汉卿','yuanqu','','','燕燕那书房中伏侍处，许第二个夫人做。
他须是人身人面皮，人口人言语！。','',''),('yuanqu-994','诈妮子调风月・得胜令','关汉卿','yuanqu','','','到如今总是彻梢虚，燕燕不是石头镌、铁头做；教我死临侵身无措，错支刺心受苦。
（夫人云了）（正旦唱）瘫痪着身躯，教我两下里难停住；气夯破胸脯，教燕燕两下里没是处。','',''),('yuanqu-995','诈妮子调风月・阿古令','关汉卿','yuanqu','','','满盏内盈盈绿醑，子合当作婢为奴。
谢相公、夫人抬举，怎敢做三妻两妇？子得和丈夫一处对舞，便是燕燕花生满路。','',''),('yuanqu-996','正宫・白鹤子（四首）','关汉卿','yuanqu','','','四时春富贵，万物酒风流。
澄澄水如蓝，灼灼花如绣。
（之一）花边停骏马，柳外缆轻舟。
湖内画船交，湖上骅骝骤。
（之二）鸟啼花影里，人立粉墙头。
春意两丝牵，秋水双波溜。
（之三）香焚金鸭鼎，闲傍小红楼。
月在柳梢头，人约黄昏后。
（之四）。','',''),('yuanqu-997','南吕・四块玉别情','关汉卿','yuanqu','','','自送别，心难舍，一点相思几时绝？凭阑袖拂杨花雪。
溪又斜，山又遮，人去也！。','',''),('yuanqu-998','南吕・四块玉闲适（四首）','关汉卿','yuanqu','','','适意行，安心坐，渴时饮饥时餐醉时歌，困来时就向莎茵卧。
日月长，天地阔，闲快活！（之一）旧酒投，新醅泼，老瓦盆边笑呵呵，共山僧野叟闲吟和。
他出一对鸡，我出一个鹅，闲快活！（之二）意马多，心猿锁，跳出红尘恶风波，槐阴午梦谁惊破？离了利名场，钻入安乐窝，闲快活！（之三）南亩耕，东山卧，世态人情经历多，闲将往事思量过。
贤的是他，愚的是我，争甚么！（之四）。','',''),('yuanqu-999','中吕・朝天子书所见','关汉卿','yuanqu','','','鬓鸦，脸霞，屈杀将陪嫁。
规模全是大人家，不在红娘下。
笑眼偷瞧，文谈回话，真如解语花。
若咱得他，倒了葡萄架。','',''),('yuanqu-1000','商调・梧叶儿别情','关汉卿','yuanqu','','','别离易，相见难，何处锁雕鞍？春将去，人未还。
这其间，殃及杀愁眉泪眼。','',''),('yuanqu-1001','双调・大德歌（四首）春','关汉卿','yuanqu','','','子规啼，不如归，道是春归人未归。
几日添憔悴，虚飘飘柳絮飞。
一春鱼雁无消息，则见双燕斗衔泥。
夏俏冤家，在天涯，偏那里绿杨堪系马？困坐南窗下，数对清风想念他。
蛾眉淡了教谁画？瘦岩岩羞带石榴花。
秋风飘飘，雨潇潇，便做陈抟睡不着。
懊恼伤怀抱，扑簌簌泪点抛。
秋蝉儿噪罢寒蛩儿叫，淅零零细雨打芭蕉。
冬雪纷纷，掩重门，不由人不断魂，瘦损江梅韵。
那里是清江江上村？香闺里冷落谁瞅问？好一个憔悴的凭阑人！。','',''),('yuanqu-1002','双调・大德歌（六首）','关汉卿','yuanqu','','','粉墙低，景凄凄，正是那西厢月上时。
会得琴中意，我是个香闺里钟子期。
好教人暗想张君瑞，敢则是爱月夜眠迟。
（之一）绿杨堤，画船儿，正撞着一帆风赶上水。
冯魁吃的醺醺醉，怎想着金山寺壁上诗。
醒来不见多姝丽，冷清清空载月明归。
（之二）郑元和，受寂寞，道是你无钱怎奈何？哥哥家缘破，谁着你摇铜铃唱换歌。
因打亚仙门前过，恰便是司马泪痕多。
（之三）谢家村，赏芳春，疑怪他桃花冷笑人。
着谁传芳信，强题诗也断魂。
花阴下等待无人问，则听得黄犬吠柴门。
（之四）雪粉华，舞梨花，再不见烟村四五家。
密洒堪图画，看疏林噪晚鸦。
黄芦掩映清江下，斜缆着钓鱼航模。
（之五）吹一个，弹一个，唱新行大德歌。
快活休张罗，想人生能几何？十分淡薄随缘过，得磨陀处且磨陀。
（之六）套数。','',''),('yuanqu-1003','黄钟・侍香金童','关汉卿','yuanqu','','','春闺院宇，柳絮飘香雪。
帘幕轻寒雨乍歇，东风落花迷粉蝶。
芍药初开，海棠才谢。','',''),('yuanqu-1004','幺・柔肠脉脉，新愁千万叠。偶记年前人乍别，秦台玉萧声断绝。雁底关','关汉卿','yuanqu','','','河，马头明月。','',''),('yuanqu-1005','降黄龙衮・鳞鸿无个，锦笺慵写。腕松金，肌削玉，罗衣宽彻。泪痕淹破，','关汉卿','yuanqu','','','胭脂双颊。
宝鉴愁临，翠钿羞贴。','',''),('yuanqu-1006','幺・等闲辜负，好天良夜。玉炉中，银台上，香消烛灭。凤帏冷落，鸳衾','关汉卿','yuanqu','','','虚设，玉笋频搓，绣鞋重扌颠。','',''),('yuanqu-1007','幺・铜壶玉漏催凄切，正更阑人静也。金闺潇洒转伤嗟，莲步轻移呼侍妾：','关汉卿','yuanqu','','','“把香桌儿安排打快些。','',''),('yuanqu-1008','仙吕・翠裙腰闺怨','关汉卿','yuanqu','','','晓来雨过山横秀，野水涨汀洲。
阑干倚遍空回首。
下危楼，一天风物暮伤秋。','',''),('yuanqu-1009','六幺遍・乍凉时候，西风透。碧梧脱叶，余暑才收。香生凤口，帘垂玉钩，','关汉卿','yuanqu','','','小院深闲清昼。
清幽，听声声蝉噪柳梢头。','',''),('yuanqu-1010','寄生草・为甚忧，为甚愁？为萧郎一去经今久。玉台宝鉴生尘垢，绿窗冷','关汉卿','yuanqu','','','落闲针锈。
岂知人玉腕钏儿松，岂知人两叶眉儿皱！。','',''),('yuanqu-1011','后庭花煞・掩袖暗含羞，开樽越酿愁。闷把苔墙画，慵将锦字修。最风流，','关汉卿','yuanqu','','','真真恩爱，等闲分付等闲休。','',''),('yuanqu-1012','南吕・一枝花赠朱帘秀','关汉卿','yuanqu','','','轻裁虾万须，巧织珠千串；金钩光错落，绣带舞蹁跹。
似雾非烟，妆点就深闺院，不许那等闲人取次展。
摇四壁翡翠浓阴，射万瓦琉璃色浅。','',''),('yuanqu-1013','梁州・富贵似侯家紫帐，风流如谢府红莲，锁春愁不放双飞燕。绮窗相近，','关汉卿','yuanqu','','','翠户相连，雕栊相映，绣幕相牵。
拂苔痕满砌榆钱，惹杨花飞点如锦。
愁的是抹回廊暮雨萧萧，恨的是筛曲槛西风剪剪，爱的是透长门夜月娟娟。
凌波殿前，碧玲珑掩映湘妃面，没福怎能够见？十里扬州风物妍，出落着神仙。','',''),('yuanqu-1014','南吕・一枝花杭州景','关汉卿','yuanqu','','','普天下锦绣乡，寰海内风流地。
大元朝新附国，亡宋家旧华夷。
水秀山奇，一到处堪游戏。
这答儿忒富贵，满城中绣幕风帘，一哄地人烟辏集。','',''),('yuanqu-1015','梁州・百十里街衢整齐，万余家楼阁参差，并无半答儿闲田地。松轩竹径，','关汉卿','yuanqu','','','药圃花蹊，茶园稻陌，竹坞梅溪。
一陀儿一句诗题，行一步扇面屏帏。
西盐场便似一带琼瑶，吴山色千叠悲翠。
兀良，望钱塘江万顷玻璃。
更有清溪绿水，画船儿来往闲游戏。
浙江亭紧相对，相对着险岭高峰长怪石，堪羡堪题。','',''),('yuanqu-1016','尾・家家掩映渠流水，楼阁峥嵘出翠微。遥望西湖暮山势，看了这壁，觑','关汉卿','yuanqu','','','了那壁，纵有丹青下不得笔。','',''),('yuanqu-1017','南吕・一枝花不伏老','关汉卿','yuanqu','','','攀出墙朵朵花，折临路枝枝柳。
花攀红蕊嫩，柳折翠条柔，浪子风流。
凭着我折柳攀花手，直煞得花残柳败休。
半生来折柳攀花，一世里眠花卧柳。','',''),('yuanqu-1018','梁州・我是个普天下郎君领袖，盖世界浪子班头。愿朱颜不改常依旧，花','关汉卿','yuanqu','','','中消遣，酒内忘忧。
分茶扌颠竹，打马藏阄；通五音六律滑熟，甚闲愁到我心头！伴的是银筝女银台前理银筝笑倚银屏，伴的是玉天仙携玉手并玉肩同登玉楼，伴的是金钗客歌《金缕》捧金樽满泛金瓯。
你道我老也，暂休。
占排场风月功名首，更玲珑又剔透。
我是个锦阵花营都帅头，曾玩府游州。','',''),('yuanqu-1019','隔尾・子弟每是个茅草冈、沙土窝初生的兔羔儿乍向围场上走，我是个经','关汉卿','yuanqu','','','笼罩、受索网苍翎毛老野鸡踏踏的阵马儿熟。
经了些窝弓冷箭蜡枪头，不曾落人后。
恰不道“人到中年万事休”，我怎肯虚度了春秋。','',''),('yuanqu-1020','尾・我是个蒸不烂、煮不熟、捶不匾、炒不爆响当当一粒铜豌豆，恁子弟','关汉卿','yuanqu','','','每谁教你钻入他锄不断、斫不下、解不开、顿不脱慢腾腾千层锦套头。
我玩的是梁园月，饮的是东京酒，赏的是洛阳花，攀的是章台柳。
我也会围棋、会蹴リ、会打围、会插科、会歌舞、会吹弹、会咽作、会吟诗、会双陆。
你便是落了我牙、歪了我嘴、瘸了我腿、折了我手，天赐与我这几般儿歹症候，尚兀自不肯休。
则除是阎王亲自唤，神鬼自来勾，三魂归地府，七魂丧冥幽，天那，那其间才不向烟花路儿上走！。','',''),('yuanqu-1021','中吕・古调石榴花闺思','关汉卿','yuanqu','','','颠狂柳絮扑帘飞，绿暗红稀。
垂杨影里杜鹃啼，一弄儿断送了春归。
牡丹亭畔人寂静，恼芳心似醉如痴。
恹恹为他成病也，松金钏，褪罗衣。','',''),('yuanqu-1022','酥枣儿・一自相逢，将人来萦系。樽前席上，眼约心期。比及道是配合了，','关汉卿','yuanqu','','','受了些闲是闲非。
咱各办着个坚心，要拨个终缘之计。','',''),('yuanqu-1023','鲍老儿・当初指望成家计，谁想琼簪碎；当初指望无抛弃，谁想银瓶坠。','关汉卿','yuanqu','','','烦烦恼恼，哀哀怨怨，哭哭啼啼，回黄倒皂，长吁短叹，自跌自堆。','',''),('yuanqu-1024','墙头花・守香闺，镇日情如醉，闷懊恼离愁空教我诉与谁？愁闻的是紫燕','关汉卿','yuanqu','','','关关，倦听的是黄莺呖呖。','',''),('yuanqu-1025','卖花声煞・愁山闷海不许当敌，好教我无一个百刂划，耐心儿多陪下些凄','关汉卿','yuanqu','','','惶泪。
呼侍婢将绣帘低放，把重门深闭，怕莺花笑人憔悴。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('yuanqu-1026','幺・天付两风流，翻成南北悠悠，落花流水人何处？相思一点，离愁几许，','关汉卿','yuanqu','','','撮上心头。','',''),('yuanqu-1027','荼コ香・记得初相守，偶尔间因循成就，美满效绸缪。花朝月夜同宴赏，','关汉卿','yuanqu','','','佳节须酬，到今一旦休。
常言道好事天悭，美姻缘他娘间阻，生拆散鸾交凤友。','',''),('yuanqu-1028','幺・坐想行思，伤怀感旧，各辜负了星前月下深深咒。愿不损，愁不煞，','关汉卿','yuanqu','','','神天还佑。
他有日不测相逢，话别离情取一场消瘦。','',''),('yuanqu-1029','好观音煞・与怪友狂朋寻花柳，时复间和哄消愁。对着浪蕊浮花懒回首，','关汉卿','yuanqu','','','怏怏归来，原不饮杯中酒。','',''),('yuanqu-1030','大石调・青杏子骋怀','关汉卿','yuanqu','','','花月酒家楼，可追欢亦可悲秋。
悲欢聚散为常事，明眸皓齿，歌莺舞燕，各逞温柔。','',''),('yuanqu-1031','幺・人俊惜风流，欠前生酒病花愁。尚还不彻相思债，携云挈雨，批风切','关汉卿','yuanqu','','','月，到处绸缪。','',''),('yuanqu-1032','催拍子・爱共寝花间锦鸠，恨孤眠水上白鸥。月宵花昼，大筵排回雪韦娘，','关汉卿','yuanqu','','','小酌会窃香韩寿。
举觞红袖，玉纤横管，银甲调筝，酒令诗筹。
曲成诗就，韵协声律，情动魂消，腹稿冥搜，美恩当受。
水仙山鬼，月妹花妖，如还得遇，不许干休，会埋伏未尝泄漏。','',''),('yuanqu-1033','幺・群芳会首，繁英故友，梦回时绿肥红瘦。荣华过可见蔬薄，财物广始','关汉卿','yuanqu','','','知亲厚。
慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。
恶缘难救，痼疾常发，业贯将盈，努力呈头。
冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。','',''),('yuanqu-1034','天净沙・平生肥马轻裘，何须锦带吴钩？百岁光阴转首，休闲生受，叹功','关汉卿','yuanqu','','','名似水上浮沤。','',''),('yuanqu-1035','寨儿冷・得自由，莫刚求。茶余饭饱邀故友，谢馆秦楼，散闷消愁，惟蹴','关汉卿','yuanqu','','','リ最风流。
演习得踢打温柔，施逞得解数滑熟。
引脚蹑龙斩眼，担枪拐凤摇头。
一左一右，折叠鹘胜游。','',''),('yuanqu-1036','尾・锦缠腕、叶底桃、鸳鸯叩，入脚面带黄河逆流。斗白打赛官场，三场','关汉卿','yuanqu','','','儿尽皆有。','',''),('yuanqu-1037','越调・斗鹌鹑又','关汉卿','yuanqu','','','蹴リ场中，鸣珂巷里，南北驰名，寰中可意。
夹缝堪夸，抛声尽喜。
那换活，煞整齐。
款侧金莲，微那玉体。
唐裙轻荡，绣带斜飘，舞袖低垂。','',''),('yuanqu-1038','小桃红・装跷委实用心机，不枉了夸强会，女辈丛中最为贵。煞曾习，沾','关汉卿','yuanqu','','','身那取着田地。
赶起了白踢，诸余里快收拾。','',''),('yuanqu-1039','秃厮儿・粉汗湿珍珠乱滴，宝髻偏鸦玉斜堆。虚蹬落实拾蹑起，侧身动，','关汉卿','yuanqu','','','柳腰脆，丸惜。','',''),('yuanqu-1040','圣药王・甚旖旎，解数儿希，左盘右折煞曾习。甚整齐，省气力，旁行侧','关汉卿','yuanqu','','','脚步频移，来往似粉蝶儿飞。','',''),('yuanqu-1041','尾・不离了花前柳影闲田地，斗白打官场小踢。竿网下世无双，全场儿占','关汉卿','yuanqu','','','了第一。','',''),('yuanqu-1042','双调・新水令','关汉卿','yuanqu','','','楚台云雨会巫峡，赴昨宵约来的期话。
楼头栖燕子，庭院已闻鸦，料想他家，收针指晚妆罢。','',''),('yuanqu-1043','乔牌儿・款将花径踏，独立在纱窗下，颤钦钦把不定心头怕。不敢将小名','关汉卿','yuanqu','','','呼，咱则索等候他。','',''),('yuanqu-1044','挂搭钩・等候多时不见他，这的是约下佳期话，莫不是贪睡人儿忘了那？','关汉卿','yuanqu','','','伏冢在蓝桥下。
意懊恼却待将他骂，听得呀的门开，蓦见如花。','',''),('yuanqu-1045','豆叶黄・髻挽乌云，蝉鬓堆鸦，粉腻酥胸，脸衬红霞；袅娜腰肢更喜恰，','关汉卿','yuanqu','','','堪讲堪夸。
比月里嫦娥，媚媚孜孜，那更撑达。','',''),('yuanqu-1046','梅花酒・两情浓，兴转佳。地权为床榻，月高烧银蜡。夜深沉，人静悄，','关汉卿','yuanqu','','','低低的问如花终是个女儿家。','',''),('yuanqu-1047','收江南・好风吹绽牡丹花，半合儿揉损绛裙纱。冷丁丁舌尖上送香茶，都','关汉卿','yuanqu','','','不到半霎，森森一向遍身麻。','',''),('yuanqu-1048','尾・整乌云欲把金莲さ，纽回身再说些儿话：“你明夜个早些儿来，我专','关汉卿','yuanqu','','','听着纱窗外芭蕉叶儿上打。','',''),('yuanqu-1049','双调・新水令','关汉卿','yuanqu','','','闲争夺鼎沸了丽春园，欠排场不堪久恋。
时间相敬爱，端的怎团圆？白没事教人笑，惹人怨。','',''),('yuanqu-1050','驻马听・锦阵里争先，紧卷旗幡不再展；花营中挑战，劳拴意马与心猿。','关汉卿','yuanqu','','','降书执写纳君前，唇枪舌剑难施展。
参破脱空禅，早抽头索甚他人劝。','',''),('yuanqu-1051','天仙子・从今后，识破野狐涎。红粉无情，灾星不现。村酒酽野花浓，再','关汉卿','yuanqu','','','不粘拈。
当时话儿无应显，好事天悭。','',''),('yuanqu-1052','双调・新水令','关汉卿','yuanqu','','','搅闲风吹散楚台云，天对付满怀愁闷。
您那里欢娱嫌夜短，俺寂寞恨长更。
恰似线断风筝，绝鱼雁杳音信。','',''),('yuanqu-1053','驻马听・多绪多情，病身躯憔悴损；闲愁闲闷，将柳带结同心。瘦岩岩宽','关汉卿','yuanqu','','','褪了绛绡裙，羞答答恐怕他邻姬问。
若道伤春，今年更比年时甚。','',''),('yuanqu-1054','幺・早是我愁怀闷哽，更那堪四扇帏屏。遣人愁，添人恨，无端怨煞丹青。','关汉卿','yuanqu','','','画得来双双厮配定，做得伤情对景。','',''),('yuanqu-1055','天仙子・一扇儿画着双通叔，和苏氏到豫章城；一扇儿是司马文君；一扇','关汉卿','yuanqu','','','儿是王魁桂英。
画的来厮顾盼厮温存，比各青春。
这一扇儿比他每情更深，是君瑞莺莺。','',''),('yuanqu-1056','随煞・您团圆偏俺孤另，拥被和衣坐等。听鼓打四更过，搭伏定鸳鸯枕头','关汉卿','yuanqu','','','儿等。','',''),('yuanqu-1057','双调・新水令','关汉卿','yuanqu','','','寨儿中风月煞经谙，收心也合搠淹。
再不缠头戴蜀锦，沽酒典春衫。
心如柳絮粘泥，狂风过怎摇撼。','',''),('yuanqu-1058','夜行船・又引起往前风月胆，今番做得尴。且休说久远当来，奈何时暂，','关汉卿','yuanqu','','','这些时陡羞惨。','',''),('yuanqu-1059','天仙子・咱非参，坏怪斗来搀。怎肯袄庙火绝，蓝桥水淹。难掩盖泼风声，','关汉卿','yuanqu','','','被各俱耽。
怎只恁两下里阻隔情分减，面北眉南。','',''),('yuanqu-1060','离亭宴煞・你休起风波剁断渔舟缆，得团圆摔破青铜鉴。冤家行再三，再','关汉卿','yuanqu','','','三嘱付勤相探。
常将好事贪，却休教花星暗。
万一问休将人倒赚，眼挫了可憎才，心疼煞志诚俺。','',''),('yuanqu-1061','双调・新水令','关汉卿','yuanqu','','','凤凰台上忆吹箫，似钱塘梦魂初觉。
花月约，凤鸾交，半世疏狂，总做了一场懊。','',''),('yuanqu-1062','驻马听・黄诏奢豪，桑木剑熬乏古定刀；双郎穷薄，纸糊锹撅了点刚锹。','关汉卿','yuanqu','','','怕不待争锋取债恋多娇，又索书名画字寻人保。
枉徒劳，供钱买笑教人笑。','',''),('yuanqu-1063','落梅风・姨夫闹，咱便晓，君子不夺人之好。他揽定磨杆儿夸俏，推不动','关汉卿','yuanqu','','','磨杆上自吊。','',''),('yuanqu-1064','步步娇・积趱下三十两通行鸦青钞，买取个大笠子粗麻罩。妆甚腰，眼落','关汉卿','yuanqu','','','处和他契丹交。
虽是不风骚，不到得着圈套。','',''),('yuanqu-1065','甜水令・佳人有意郎君俏，郎君没钞莺花恼。如今等惜花人弄巧，指不过','关汉卿','yuanqu','','','美话儿排，虚科儿套，实心儿少。
想着月下情，星前约，是则是花木瓜儿看好。
李亚仙负心疾，郑元和下番早。','',''),('yuanqu-1066','庆东原・或向幽窗下，或向曲槛前，春纤相对摇纨扇。闲凭着玉肩，双歌','关汉卿','yuanqu','','','《采莲》，斗抚冰弦。
遂却少年心，称了于飞愿。','',''),('yuanqu-1067','早乡词・九秋天，三径边，绽黄花遍撒金钱。露春纤把花笑捻，捧金杯酒','关汉卿','yuanqu','','','频劝，畅好是风流如五柳庄前。','',''),('yuanqu-1068','挂打沽・浅浅江梅驿使传，乱剪碎鹅毛片。旋剖温橙列着玳筵，玉液着金','关汉卿','yuanqu','','','瓶旋。
酒晕红，新妆面，人道是穷冬，我道是虚言。','',''),('yuanqu-1069','石竹子・夜夜嬉游赛上元，朝朝宴乐赏禁烟。密爱幽欢不能恋，无奈被名','关汉卿','yuanqu','','','缰利锁牵。','',''),('yuanqu-1070','醉也摩挲・真个索去也么天，真个索去也么天！再要团圆，动是经年，思','关汉卿','yuanqu','','','量杀俺也么天！。','',''),('yuanqu-1071','相公爱・晚宿在孤村闷怎生眠，伴人离愁月当轩。月圆，人几时圆？不似','关汉卿','yuanqu','','','他南楼上斗婵娟。','',''),('yuanqu-1072','胡十八・天配合俏姻眷，分拆开并头莲。思量席上与樽前，天生的自然，','关汉卿','yuanqu','','','那些儿体面。
也是俺心上有，常常的梦中见。','',''),('yuanqu-1073','一锭银・心友每相邀列着管弦，却子待欢解动凄然。十分酒十分悲怨，却','关汉卿','yuanqu','','','不道怎生般消遣。','',''),('yuanqu-1074','不拜门・酒入愁肠闷怎生言，疏竹萧萧西风战。如年，如年似长夜天，正','关汉卿','yuanqu','','','是恰黄昏庭院。','',''),('yuanqu-1075','金盏子・咱无缘，风流十全。尽可怜，芙蓉面。腕松着金钏，鬓贴着翠钿，','关汉卿','yuanqu','','','脸朵着秋莲。
眼去眉来相思恋，春山摇，秋波转。','',''),('yuanqu-1076','也不罗・只听得乐声喧，列着华筵，聚集诸亲眷。首先一盏拦门劝，走马','关汉卿','yuanqu','','','身劳倦。','',''),('yuanqu-1077','喜人心・人丛里遥见，半遮着罗扇，可喜的风流业冤，两叶眉儿未展。百','关汉卿','yuanqu','','','般的陪告，一创的求和，只管里熬煎。
他越将个庞儿变，咱百般的难分辨。','',''),('yuanqu-1078','风流体・胡猜咱，胡猜咱居帝辇，和别人、和别人相留恋。上放着、上放','关汉卿','yuanqu','','','着赐福天，你不知、你不知神明见。','',''),('yuanqu-1079','忽都白・我半载来孤眠，信口胡言，枉了把我冤也么冤。打听的真实，有','关汉卿','yuanqu','','','人曾见，母亲跟前，恁儿情愿，一任当刑宪，死而心无怨。','',''),('yuanqu-1080','唐兀歹・不付能告求的绣帏里头眠，痛惜轻怜。斩眼不觉得绿窗儿外月明','关汉卿','yuanqu','','','却又早转，畅好是疾明也么天！。','',''),('yuanqu-1081','尾・腰肢困摆垂杨软，舌尖笑吐丁香喘。绣帐里无人，并枕低言。畅道美','关汉卿','yuanqu','','','满姻缘，风流缱绻，天若肯为人，为人是今生愿。
尽老同眠也者，也强如雁底关河路儿远。','',''),('yuanqu-1082','双调・乔牌儿','关汉卿','yuanqu','','','世情推物理，人生贵适意。
想人间造物搬兴废，吉藏凶，凶暗吉。','',''),('yuanqu-1083','夜行船・富贵那能长富贵，日盈昃月满亏蚀。地下东南，天高西北，天地','关汉卿','yuanqu','','','尚无完体。','',''),('yuanqu-1084','庆宣和・算到天明走到黑，赤紧的是衣食。凫短鹤长不能齐，且休题，谁','关汉卿','yuanqu','','','是非。','',''),('yuanqu-1085','锦上花・展放愁眉，休争闲气。今日容颜，老如昨日。古往今来，恁须尽','关汉卿','yuanqu','','','知，贤的愚的，贫的和富的。','',''),('yuanqu-1086','幺・到头这一身，难逃那一日。受用了一朝，一朝便宜。百岁光阴，七十','关汉卿','yuanqu','','','者稀。
急急流年，滔滔逝水。','',''),('yuanqu-1087','清江引・落花满院春又归，晚景成何济！车尘马足中，蚁穴蜂衙内，寻取','关汉卿','yuanqu','','','个稳便处闲坐地。','',''),('yuanqu-1088','碧玉箫・乌兔相催，日月走东西。人生别离，白发故人稀。不停闲岁月疾，','关汉卿','yuanqu','','','光阴似驹过隙。
君莫痴，休争名利。
幸有几杯，且不如花前醉。','',''),('yuanqu-1089','歇拍煞・恁则待闲熬煎、闲烦恼、闲萦系、闲追欢、闲落魄、闲游戏。金','关汉卿','yuanqu','','','鸡触祸机，得时间早弃迷途。
繁华重念箫韶歇，急流勇退寻归计。
采蕨薇，洗是非；夷齐等，巢由辈。
这两个谁人似得？松菊晋陶潜，江湖越范蠡。','',''),('yuanqu-1090','仙吕・桂枝香','关汉卿','yuanqu','','','因他别后，恹恹消瘦。
粉褪了雨后桃花，带宽了风前杨柳。
这相思怎休？这相思怎休？害得我天长地久，难禁难受！泪痕流，滴破芙蓉面，却似珍珠断线头。','',''),('yuanqu-1091','不是路・万种风流，今日番成一段愁。泪盈眸，云山满目恨悠悠。谩追求，','关汉卿','yuanqu','','','情如柳絮风前斗，性似桃花逐水流。
沉吟久，因他数尽残更漏，恁般亻孱亻愁！恁般亻孱亻愁！。','',''),('yuanqu-1092','木丫叉・雾锁秦楼，雾锁秦楼。云迷楚岫，御沟红叶空流。偷香韩寿，锦','关汉卿','yuanqu','','','帐中枉自绸缪，蹙破两眉头。
小蛮腰瘦如杨柳，浅淡樱桃樊素口。
空教人目断去时舟，又不知风流浪子，何处温柔。','',''),('yuanqu-1093','幺篇・月下砧声幽，月下砧声幽，风前笛秦。断肠声无了无休，捣碎我心','关汉卿','yuanqu','','','又加上一场症候，顿使我愁不寐，襄王梦雨散云收。','',''),('yuanqu-1094','仙吕・赏花时','阚志学','yuanqu','','','香径泥融燕语喧，彩槛风微蝶影翩。
飞絮擘香绵，娇莺时啭，惊起绿窗眠。','',''),('yuanqu-1095','煞尾・惜花愁，伤春怨，萦系杀多情少年。何处狂游袅玉鞭，谩教人暗卜','阚志学','yuanqu','','','金钱。
空写遍翠涛笺，鱼雁难传。
似这般白日黄昏怎过遣？青鸾信远。
紫箫声转，画楼中闲杀月明天。','',''),('yuanqu-1096','钱大尹智宠谢天香・仙吕/赏花时','关汉卿','yuanqu','','','则这一曲翻成和泪篇，最苦偏高离恨天，双泪落尊前。
山长水远，愁见理行轩。','',''),('yuanqu-1097','钱大尹智宠谢天香・玄篇','关汉卿','yuanqu','','','待得鸾胶续断弦，欲盼雕鞍难顾恋。
谢他新理任这官员，常好是与民方便，咱又得个一夜并头莲。
（同下）。','',''),('yuanqu-1098','钱大尹智宠谢天香・仙吕/点绛唇','关汉卿','yuanqu','','','讲论诗词，笑谈街市，学难似风里扬丝，一世常如此。','',''),('yuanqu-1099','钱大尹智宠谢天香・混江龙','关汉卿','yuanqu','','','我逐日家把您相试，乞求的教您做人时，但能勾终朝为父，也想着一日为师。
但有个敢接我这上厅行首案，情愿分会与你这搬演戏台儿。
则为四般儿误了前程事，都只为聪明智慧，因此上辛苦无辞。','',''),('yuanqu-1100','钱大尹智宠谢天香・油葫芦','关汉卿','yuanqu','','','你道是金笼内鹦哥能念诗，这便是咱家的好比似。
原来越聪明越得不出笼时！能吹弹好比人每日常看伺，惯歌讴好比人每日常差使。
（云）我不怨别人。
（众旦云）姐姐，你怨谁？（旦云）咱会弹唱的，日日官身；不会弹唱的，倒得些自在！（唱）我怨那礼案里几个令史，他每都是我掌命司，先将那等不会弹不会唱的除了名字，早知道则做个哑猱儿。','',''),('yuanqu-1101','钱大尹智宠谢天香・天下乐','关汉卿','yuanqu','','','俺可也图甚么香名贯人耳！想当也波时，不三思：越聪明，不能勾无外事。
卖弄的有伎俩，卖弄的有艳姿，则落的临老来呼"弟子"！（张千云）谢大姐，你怎生这早晚才来？你只在这里，我报复去。
（做报科，云）报的老爷得知：有乐人每来参见。
（钱大尹云）别的休进来，则着那为头的一人来见。
（张千云）别的都回去，则着谢大姐过去哩！（众旦下）（正旦见、拜科，云）上厅行首谢天香谨参。
（钱大尹云）休要误了官身。
（旦云）理会的。
（做出门科，云）爷爷，那官人好个冷脸子也！（唱）。','',''),('yuanqu-1102','钱大尹智宠谢天香・金盏儿','关汉卿','yuanqu','','','猛觑了那容姿，不觉的下阶址，下场头少不的跟官长厅前死；往常觑品官宣使似小孩儿。
他则道官身休失误，启口更无词。
立地刚一饭间，心战勾两炊时。','',''),('yuanqu-1103','钱大尹智宠谢天香・醉中天','关汉卿','yuanqu','','','初相见呼你为学士，谨厚不因而；今遍回身嘱付尔，相公也冷眼儿频偷视。
你觑他交椅上抬颏样儿，待的你不同前次，他则是微分间将表字呼之。','',''),('yuanqu-1104','钱大尹智宠谢天香・醉扶归','关汉卿','yuanqu','','','你陡恁的无才思，有甚省不的两桩儿？我道这相公不是漫词，你怎么不解其中意？他道是种桃花砍折竹枝，则说你重色轻君子！。','',''),('yuanqu-1105','钱大尹智宠谢天香・赚煞','关汉卿','yuanqu','','','我这府里祗候几曾闲，差拨无铨次，从今后无倒断嗟呀怨咨。
我去这触热也似官人行将礼数使，若是轻咳嗽便有官司。
我直到揭席时、来到家时，我又索趱下些工夫忆念尔。
是我那清歌皓齿，是我那言谈情思，是我那湿浸浸舞困袖梢儿。
（下）。','',''),('yuanqu-1106','钱大尹智宠谢天香・南吕/一枝花','关汉卿','yuanqu','','','往常时唤官身可早眉黛舒，今日个叫祗候喉咙响。
原来是你这狠首领，我则道是那个面前桑？恰才陪着笑脸儿应昂，怎觑我这查梨相，只因他忒过当。
据妾身貌陋残妆，谁教他大尹行将咱过奖？。','',''),('yuanqu-1107','钱大尹智宠谢天香・隔尾','关汉卿','yuanqu','','','我见他严容端坐挨着罗幌，可甚么和气春风满画堂！我最愁是劈先里递一声唱，这里但有个女娘、坐场，可敢烘散我家私做的赏。','',''),('yuanqu-1108','钱大尹智宠谢天香・贺新郎','关汉卿','yuanqu','','','呀，想东坡一曲〔满庭芳〕则道一个"香霭雕盘"，可又早祸从天降！当时嘲拨无拦当，乞相公宽洪海量，怎不的仔细参详？（钱大尹云）怎么在我行打关节那？（正旦唱）小人便关节煞，怎生勾除籍不做娼，弃贱得为良。
他则是一时间带酒闲支谎，量妾身本开封府阶下承应辈，怎做的柳耆卿心上谢天香？。','',''),('yuanqu-1109','钱大尹智宠谢天香・牧羊关','关汉卿','yuanqu','','','相公名誉传天下，妾身乐籍在教坊；量妾身则是个妓女排场，相公是当代名儒。
妾身则好去待宾客，供些优唱。
妾身是临路金丝柳，相公是架海紫金梁；想你便意错见、心错爱，怎做的门厮敌、户厮当？。','',''),('yuanqu-1110','钱大尹智宠谢天香・二煞','关汉卿','yuanqu','','','则恁这秀才每活计似鱼翻浪，大人家前程似狗探汤。
则俺这侍妾每近帏房，止不过供手巾到他行，能勾见些模样？着护衣须是相亲傍，止不过梳头处俺胸前靠着脊梁，几时得儿女成双？（云）指望嫁杭州柳耆卿，做个自在人，如今怎了也？（唱）。','',''),('yuanqu-1111','钱大尹智宠谢天香・正宫/端正好','关汉卿','yuanqu','','','往常我在风尘为歌妓，止不过见了那几个筵席，到家来须做个自由鬼；今日个打我在无底磨牢笼内！。','',''),('yuanqu-1112','钱大尹智宠谢天香・滚绣球','关汉卿','yuanqu','','','到早起过洗面水，到晚来又索铺床叠被，我服侍的都入罗帏，我恰才舒铺盖似孤鬼，少不的足恋蜷寝睡，整三年有名无实。
本是个见交风月耆卿伴，教我做遥受恩情大尹妻，端的谁知？（二旦扮姬妾上，云）俺二人是钱大尹家侍妾。
今日无甚事，去望姓谢的姐姐走一遭去。
（见旦科，云）姐姐，俺二人竟来望姐姐。
（正旦云）二位姐姐请坐。
（二旦云）姐姐，你在宅中三年，相公曾亲近你么？（正旦唱）。','',''),('yuanqu-1113','钱大尹智宠谢天香・倘秀才','关汉卿','yuanqu','','','俺若是曾宿睡呵，则除是天知地知；相公那铺盖儿，知他是横的竖的！比我那初使唤，如今越更稀。
想是我出身处本低微，则怕展污了相公贵体。','',''),('yuanqu-1114','钱大尹智宠谢天香・滚绣球','关汉卿','yuanqu','','','姐姐每肯教诲，怕不是好意？争奈我官人行，怎敢便话不投机？（二旦云）姐姐，你又无甚么过失。
（正旦唱）你道是无过失，学恁的，姐姐每会也那不会？我则是斟量着紧慢迟疾，强何郎旖旎煞难搽粉，狠张敞央及煞怎画眉？要识个高低。
（二旦云）敢问姐姐，当日柳七官人《乐章集》，姐姐收的好么？（正旦唱）。','',''),('yuanqu-1115','钱大尹智宠谢天香・倘秀才','关汉卿','yuanqu','','','便休题花七、柳七，若听得这里是那里，相公的耳朵里风闻那旧是非。
休只管这几句，滥黄齑，我也记得。','',''),('yuanqu-1116','钱大尹智宠谢天香・穷河西','关汉卿','yuanqu','','','姐姐每谁敢道袖褪《乐章集》，都则是断送的我一身亏。
怕待学大曲子我从头儿唱与你，本记的人前会，挂口儿从今后再休提。
（二旦云）咱和你同去竹云亭上赌戏咱。
（正旦云）姐姐每，咱去波。
（唱）。','',''),('yuanqu-1117','钱大尹智宠谢天香・滚绣球','关汉卿','yuanqu','','','想前日使象棋，说下的则是个手帕儿赌戏，你将我那玉束纳藤箱子，便不放空回。
近新来，下雨的那一日，你输与我绣鞋儿一对，挂口儿再不曾提。
那里为些些赌赛绝了交契，小小输赢丑了面皮，道我不精细。','',''),('yuanqu-1118','钱大尹智宠谢天香・倘秀才','关汉卿','yuanqu','','','幺四五骰着个撮十，二三二趁着个夹七；一面打个色儿，也当得幺二三是鼠尾。
赌钱的、不伶俐，姐姐你可便再掷。','',''),('yuanqu-1119','钱大尹智宠谢天香・呆骨朵','关汉卿','yuanqu','','','我将这色数儿轻放在骰盆内，二三五又掷个乌十；不下钱打赛，我可便赢了你两回。
这上面分明见，色数儿且休提。
姐姐，我可便做桩儿三个五，你今日这般输说甚的？。','',''),('yuanqu-1120','钱大尹智宠谢天香・倘秀才','关汉卿','yuanqu','','','你休要不君子便将闹起，我永世儿不和你厮极，塌着那臭尸骸一壁稳坐的。
（钱将拄仗放在旦右肩上）（正旦拨科，唱）兀的不闲着您！（钱将拄杖放在旦左肩上）（正旦拔科，唱）臭驴蹄！（钱又将拄杖放在旦右肩上）（正旦拿住回头科，唱）兀的是谁？。','',''),('yuanqu-1121','钱大尹智宠谢天香・醉太平','关汉卿','yuanqu','','','唬的我连忙的跪膝，不由我泪雨似扒推；可又早七留七力来到我跟底，不言语立地；我见他出留出律两个都回避。
相公将必留不剌拄杖相调戏，我不该必丢不搭口内失尊卑，这的是天香犯罪。
（钱大尹云）天香，你怕么？（正旦云）可知怕哩。
（钱大尹云）你要饶么？（正旦云）可知要饶哩。
（钱大尹云）既然要饶，或诗或词，作一首来我看，我便饶了你。
（正旦云）请。','',''),('yuanqu-1122','钱大尹智宠谢天香・二煞','关汉卿','yuanqu','','','往常时不曾挂眼都无意，今日回心有甚迟？相公的言语更怕不中，委付妾身教我转转猜疑。
相公又不是戏笑，又不是沉醉，又不是昏迷；待道是颠狂睡呓，兀的不青天这白日？。','',''),('yuanqu-1123','钱大尹智宠谢天香・一煞','关汉卿','yuanqu','','','相公，你一言既出如何悔，驷马奔驰不可追。
妾身出入兰堂，身居画阁，行有香车，宿有罗帏。
相公，整过了三年，可便调理，无个消息；不想道今朝错爱我这匪妓，也则是可怜见哭啼啼。
（钱大尹云）天香，后堂中换衣服去。
（下）（正旦唱）。','',''),('yuanqu-1124','钱大尹智宠谢天香・煞尾','关汉卿','yuanqu','','','则今番文诌诌的施才艺，从来个扑籁籁没气力。
相公这一句言语可立碑，我也不敢十分相信的。
许来大官员，恁来大职位，发出言词忒口疾。
你不委心为自家没见识，又不是花街中、柳陌里，那一个彻梢虚、雾塌桥，浑身我可也认的你！（下）。','',''),('yuanqu-1125','钱大尹智宠谢天香・中吕/粉蝶儿','关汉卿','yuanqu','','','送的那水护衣为头，先使了熬麸浆细香澡豆，暖的那温泔清手面轻揉；打底干南定粉，把蔷擞露和就；破开那苏合香油，我嫌棘针梢燎的来油臭。','',''),('yuanqu-1126','钱大尹智宠谢天香・醉春风','关汉卿','yuanqu','','','那里敢深蘸着指头搽，我则索轻将绵絮纽。
比俺那门前乐探等着官身，我今日个不丑、丑。
虽不是宅院里夫人，也是那大人家姬妾，强似那上厅的祗候。','',''),('yuanqu-1127','钱大尹智宠谢天香・石榴花','关汉卿','yuanqu','','','我则道坐着的是那个俊儒流，我这里猛窥视细凝眸，原来是三年不肯往杭州，闪的我落后，有国难投！莫不是将咱故意相迤逗，特教的露丑呈羞？你觑那衣服每各自施忠厚，百般儿省不的甚缘由。','',''),('yuanqu-1128','钱大尹智宠谢天香・斗鹌鹑','关汉卿','yuanqu','','','并无那私事公仇，倒与俺张筵置酒。
（带云）我这一过去，说些甚么的是？（唱）我则是佯不相瞅，怎敢道特来问候。
（见科）（钱大尹云）天香，与耆卿施礼咱。
（正旦唱）我这里施罢礼，官人行紧低首。
（钱大尹云）天香、近前来些。
（正旦唱）谁敢道是离了左右，我则索侍立旁边，我则索趋前褪后。','',''),('yuanqu-1129','钱大尹智宠谢天香・哨遍','关汉卿','yuanqu','','','一自才郎别后，相公那帘幕里香风透。
又无个交错觥筹，又无个宾客闲游饮杯酒，坐衙紧唤，乐探忙勾，唬的我难收救，只得向公厅祗候。
不问我舞旋，只着我歌讴。
将凤凰杯注酒尊前递，把商角调填词韵脚搜，唱到"惨绿愁红"。
"事事可可"，一时禁口。','',''),('yuanqu-1130','钱大尹智宠谢天香・耍孩儿','关汉卿','yuanqu','','','相公讳字都全有，我将别韵儿轻轻换偷；即时间乐案里便除名，扬言说要结绸缪。
三年甚事曾占着铺盖，千日何曾靠着枕头？相公意，难参透。
我本是沾泥飞絮，倒做了不缆孤舟！。','',''),('yuanqu-1131','钱大尹智宠谢天香・二煞','关汉卿','yuanqu','','','见妾身精神比杏桃，相公如何共卯酉？见天香颜色当春昼。
观花不比观娇态，饮酒合当饮巨瓯。
谁把清香嗅？则是深围在阑底，又何曾插个花头！（钱大尹云）张千，快收拾车马，送谢夫人到状元宅上去！（柳同旦拜谢科，云）深感相公大恩！（正旦唱）。','',''),('yuanqu-1132','钱大尹智宠谢天香・煞尾','关汉卿','yuanqu','','','这天香不想艳阳天气开，我则道无情干罢休！谁想这牡丹花折入东君手，今日个分与章台路傍柳。','',''),('yuanqu-1133','草桥店梦莺莺(第四本)・秃厮儿','王实甫','yuanqu','','','我则道神针法灸，谁承望燕侣莺俦。
他两个经今月余则是一处宿，何须你一一问缘由？。','',''),('yuanqu-1134','草桥店梦莺莺(第四本)・圣药王','王实甫','yuanqu','','','他每不识忧，不识愁，一双心意两相投。
夫人得好休，便好休，这其间何必苦追求？常言道"女大不中留"。','',''),('yuanqu-1135','草桥店梦莺莺(第四本)・麻郎儿','王实甫','yuanqu','','','秀才是文章魁首，姐姐是仕女班头；一个通彻三教九流，一个晓尽描鸾刺绣。','',''),('yuanqu-1136','草桥店梦莺莺(第四本)・幺篇','王实甫','yuanqu','','','世有、便休、罢手，大恩人怎做敌头？起白马将军故友，斩飞虎叛贼草寇。','',''),('yuanqu-1137','草桥店梦莺莺(第四本)・络丝娘','王实甫','yuanqu','','','不争和张解元参辰卯酉，便是与崔相国出乖弄丑。
到底干连着自己骨肉，夫人索穷究。
(夫人云)这小贱人也道得是。
我不合养了这个不肖之女。
待经官呵，玷辱家门。
罢罢！俺家无犯法之男，再婚之女，与了这厮罢。
红娘唤那贱人来！(红见旦云)且喜姐姐，那棍子则是滴溜溜在我身上，吃我直说过了。
我也怕不得许多，夫人如今唤你来，待成合亲事。
(旦去)羞人答答的，怎么见夫人？(红云)娘跟前有甚么羞？。','',''),('yuanqu-1138','草桥店梦莺莺(第四本)・小桃红','王实甫','yuanqu','','','当日个月明才上柳梢头，却早人约黄昏后。
羞得我脑背后将牙儿衬着衫儿袖。
猛凝眸，则见鞋底尖儿瘦。
一个恣情的不休，一个哑声儿厮耨。
呸！那其间可怎生不害半星儿羞？。','',''),('yuanqu-1139','草桥店梦莺莺(第四本)・东原乐','王实甫','yuanqu','','','想思事，一笔勾，早则展放从前眉儿皱，美爱幽欢恰动头。
既能够，张生，你觑兀的般可喜娘庞儿也要人消受。','',''),('yuanqu-1140','草桥店梦莺莺(第四本)・收尾','王实甫','yuanqu','','','来时节画堂箫鼓鸣春昼，列着一对儿鸾交凤友。
那其间才受你说媒红，方吃你谢亲酒。
(并下)。','',''),('yuanqu-1141','草桥店梦莺莺(第四本)・正宫/端正好','王实甫','yuanqu','','','碧云天，黄花地，西风紧，北雁南飞。
晓来谁染霜林醉？总是离人泪。','',''),('yuanqu-1142','草桥店梦莺莺(第四本)・脱布衫','王实甫','yuanqu','','','下西风黄叶纷飞，染寒烟衰草萋迷。
酒席上斜签着坐的，蹙愁眉死临侵地。','',''),('yuanqu-1143','草桥店梦莺莺(第四本)・小梁州','王实甫','yuanqu','','','我见他阁泪汪汪不敢垂，恐怕人知；猛然见了把头低，长吁气，推整素罗衣。','',''),('yuanqu-1144','草桥店梦莺莺(第四本)・幺篇','王实甫','yuanqu','','','虽然久后成佳配，奈时间怎不悲啼。
意似痴，心如醉，昨宵今日，清减了小腰围。
(夫人云)小姐把盏者！(红递酒，旦把盏长吁科，云)请吃酒！。','',''),('yuanqu-1145','草桥店梦莺莺(第四本)・上小楼','王实甫','yuanqu','','','合欢未已，离愁相继。
想着俺前暮私情，昨夜成亲，今日别离。
我谂知这几日相思滋味，却原来比别离情更增十倍。','',''),('yuanqu-1146','草桥店梦莺莺(第四本)・幺篇','王实甫','yuanqu','','','年少呵轻远别，情薄呵易弃掷。
全不想腿儿相挨，脸儿相偎，手儿相携。
你与俺崔相国做女婿，妻荣夫贵，但得一个并头莲，煞强如状元及第。
(夫人云)红娘把盏者！(红把酒科)(旦唱)。','',''),('yuanqu-1147','草桥店梦莺莺(第四本)・满庭芳','王实甫','yuanqu','','','供食太急，须臾对面，顷刻别离。
若不是酒席间子母每当回避，有心待与他举案齐眉。
虽然是厮守得一时半刻，也合着俺夫妻每共桌而食。
眼底空留意，寻思起就里，险化做望夫石。
(红云)姐姐不曾吃早饭，饮一口儿汤水。
(旦云)红娘，甚么汤水咽得下！。','',''),('yuanqu-1148','草桥店梦莺莺(第四本)・快活三','王实甫','yuanqu','','','将来的酒共食，尝着似土和泥。
假若便是上和泥，也有些土气息，泥滋味。','',''),('yuanqu-1149','草桥店梦莺莺(第四本)・朝天子','王实甫','yuanqu','','','暖溶溶玉醅，白泠泠似水，多半是相思泪。
眼面前茶饭怕不待要吃，恨塞满愁肠胃。
"蜗角虚名，蝇头微利"，拆鸳鸯在两下里。
一个这壁，一个那壁，一递一声长吁气。','',''),('yuanqu-1150','草桥店梦莺莺(第四本)・四边静','王实甫','yuanqu','','','霎时间杯盘狼籍，车儿投东，马儿向西，两意徘徊，落日山横翠。
知他今宵宿在那里？有梦也难寻觅。','',''),('yuanqu-1151','草桥店梦莺莺(第四本)・耍孩儿','王实甫','yuanqu','','','淋漓襟袖啼红泪，比司马青衫更湿。
伯劳东去燕西飞，未释程九问归期。
虽然眼底人千里，且尽生前洒一杯。
未饮心先醉，眼中流血，心水成灰。','',''),('yuanqu-1152','草桥店梦莺莺(第四本)・五煞','王实甫','yuanqu','','','到京师服水土，趁程途节饮食，顺时自保揣身体。
荒村雨露宜眠早，野店风霜要起迟！鞍马秋风里，最难调护，最要扶持。','',''),('yuanqu-1153','草桥店梦莺莺(第四本)・四煞','王实甫','yuanqu','','','这忧愁诉与谁？相思只自知，老天不管人憔悴。
泪添九曲黄河溢，恨压三峰华岳低。
到晚来闷把西楼倚，见了些夕阳古道，衰柳长堤。','',''),('yuanqu-1154','草桥店梦莺莺(第四本)・三煞','王实甫','yuanqu','','','笑吟吟一处来。
哭啼啼独自归。
归家若到罗帏里，昨宵个绣衾香暖留春住，今夜个翠被生寒有梦知。
留恋你别无意，见据鞍上马，。','',''),('yuanqu-1155','草桥店梦莺莺(第四本)・二煞','王实甫','yuanqu','','','你休忧"文齐福不齐"，我则怕你"停妻再娶妻"。
休要"一春鱼雁无消息"！我这里青鸾有信频须寄，你却休"金榜无名誓不归"。
此一节君须记，若见了那异乡花草，再休似此处栖迟。
(末云)再谁似小妇？小生又生此念。
(旦唱)。','',''),('yuanqu-1156','草桥店梦莺莺(第四本)・一煞','王实甫','yuanqu','','','青山隔送行，疏林不做美，淡烟暮蔼相遮蔽。
夕阳古道无人语，禾黍秋风听马嘶。
我为甚么懒上车儿内，来时甚急，去后何迟？。','',''),('yuanqu-1157','草桥店梦莺莺(第四本)・收尾','王实甫','yuanqu','','','四围山色中，一鞭残照里。
遍人间烦恼填胸臆，量这些大小车儿如何载得起？。','',''),('yuanqu-1158','草桥店梦莺莺(第四本)・双调/新水令','王实甫','yuanqu','','','望薄东萧寺暮云遮，惨离情半林黄叶。
马迟人意懒，风急雁行斜。
离恨重叠，破题儿第一夜。','',''),('yuanqu-1159','草桥店梦莺莺(第四本)・落梅风','王实甫','yuanqu','','','旅馆欹单枕，秋蛩鸣四野，助人愁的是纸窗儿风裂。
乍孤眠被儿薄又怯，冷清清几时温热！。','',''),('yuanqu-1160','草桥店梦莺莺(第四本)・乔木查','王实甫','yuanqu','','','走荒郊旷野，把不住心娇怯，喘吁吁难将两气接。
疾忙赶上者，打草惊蛇。','',''),('yuanqu-1161','草桥店梦莺莺(第四本)・锦上花','王实甫','yuanqu','','','有限姻缘，方才宁贴；无奈功名，使人离缺。
害不了的愁怀，却才觉些；撇不下的相思，如今又也。','',''),('yuanqu-1162','草桥店梦莺莺(第四本)・幺篇','王实甫','yuanqu','','','清霜净碧波，白露下黄叶。
下下高高，道路曲折；四野风来，左右乱踅。
我这里奔驰，他何处困歇？。','',''),('yuanqu-1163','草桥店梦莺莺(第四本)・清江引','王实甫','yuanqu','','','呆答孩店房儿里没话说，闷对如年夜。
暮雨催寒蛩，晓风吹残月，今宵酒醒何处也？(旦云)在这个店儿里，不免敲门。
(末云)谁敲门哩？是一个女人的声音。
我且开门看咱，这早晚是谁？。','',''),('yuanqu-1164','草桥店梦莺莺(第四本)・庆宣和','王实甫','yuanqu','','','是人呵疾忙快分说，是鬼呵合速灭。
(旦云)是我。
老夫人睡了。
想你去了，几时再得见，特来和你同去。
(末唱)听说罢将香罗袖儿拽，却原来是姐姐、姐姐。','',''),('yuanqu-1165','草桥店梦莺莺(第四本)・乔牌儿','王实甫','yuanqu','','','你是为人须为彻，将衣袂不藉。
绣鞋儿被露水泥沾惹，脚心儿管踏破也。','',''),('yuanqu-1166','草桥店梦莺莺(第四本)・甜水令','王实甫','yuanqu','','','想着你废寝忘餐，香消玉减，花开花谢，犹自觉争些；便枕冷衾寒，凤只鸾孤，月圆云遮，寻思来有甚伤嗟。','',''),('yuanqu-1167','草桥店梦莺莺(第四本)・折桂令','王实甫','yuanqu','','','想人生最苦离别，可怜见千里关山，独自跋涉。
似这般割肚牵肠，倒不如义断恩绝。
虽然是一时间花残月缺，休猜做瓶坠簪折。
不恋豪杰，不羡骄奢；自愿的生则同衾，死则同穴。','',''),('yuanqu-1168','草桥店梦莺莺(第四本)・雁儿落','王实甫','yuanqu','','','绿依依墙高柳半遮，静悄悄门掩清秋夜，疏剌剌林梢落叶风，昏惨惨云际穿窗月。','',''),('yuanqu-1169','草桥店梦莺莺(第四本)・得胜令','王实甫','yuanqu','','','惊觉我的是颤巍巍竹影走龙蛇，虚飘飘庄周梦蝴蝶，絮叨叨促织儿无休歇，韵悠悠砧声儿不断绝。
痛煞煞伤别，急煎煎好梦儿应难舍；冷清清的咨嗟，娇滴滴玉人儿何处也！。','',''),('yuanqu-1170','草桥店梦莺莺(第四本)・鸳鸯煞','王实甫','yuanqu','','','柳丝长咫尺情牵惹，水声幽仿佛人呜咽。
斜月残灯，半明不灭。
畅道是旧恨连绵，新愁郁结；别恨离愁，满肺腑难淘泻。
除纸笔代喉舌，千种相思对谁说。
(并下)。','',''),('yuanqu-1171','草桥店梦莺莺(第四本)・络丝娘煞尾','王实甫','yuanqu','','','都则为一官半职，阻隔得千山万水。','',''),('yuanqu-1172','中吕・普天乐','杨维桢','yuanqu','','','十月六日，云窝主者设燕于清香亭，侑卮者东平玉无瑕张氏也。
酒半，张氏乞手乐章。
为赋双飞燕调，俾度腔行酒以佐主宾。
玉无瑕，春无价，清歌一曲，俐齿伶牙。
斜簪剃髻花，紧嵌凌波袜。
玉手琵琶弹初罢，怎教他流落天涯。
抱来帐下，梨园弟子，学士人家。
套数。','',''),('yuanqu-1173','斗哈蟆・堪悲，身国俱亡。把烟花山水，等闲无主。叹高台百尺，顿遭烈','杨维桢','yuanqu','','','休觑，珠翠总劫灰，繁华只废基。
恼人意，叵耐范蠡扁舟，一片太湖烟水。','',''),('yuanqu-1174','锦衣香・馆娃宫，荆榛蔽。响さ廊，莓苔翳。可惜剩水残山，断崖高寺，','杨维桢','yuanqu','','','百花深处一僧归。
空遗旧迹，走狗斗鸡。
想当年僭祭，望郊台凄凉云树，香水鸳鸯去。
酒城倾坠，茫茫练渎，无边秋水。','',''),('yuanqu-1175','浆水令・采莲泾红芳尽死，越来溪吴歌惨凄。宫中鹿走草萋萋，黍离故墟，','杨维桢','yuanqu','','','过客伤悲。
离宫废，谁避暑？琼姬墓冷苍烟蔽。
空原滴，空原滴，梧桐秋雨，台城上，台城上，夜乌啼。','',''),('yuanqu-1176','双调・新水令','蒲察善长','yuanqu','','','听楼头画鼓打三更，绣帏中枕余衾剩。
明朗朗窗前月，昏惨惨榻前灯。
我这里独倚定帏屏，檐间铁好难听！。','',''),('yuanqu-1177','驻马听・聒煞我也当当丁丁，恰便似再出世陈抟睡不成。度一宵如同百岁，','蒲察善长','yuanqu','','','捱一朝胜似三春。
金炉香烬酒初醒，孤眠那怕心肠硬。
闲愁可惯经？惟有相思最是难熬的症。','',''),('yuanqu-1178','乔牌儿・一回家睡不着独自个寝，非干是咱薄幸。没来由簪折瓶沉井，将','蒲察善长','yuanqu','','','鸳鸯两下里分。','',''),('yuanqu-1179','得胜令・担不得翠弯眉黛远山青，红馥馥桃脸褪朱唇。细袅袅杨柳腰肢瘦，','蒲察善长','yuanqu','','','齐臻臻青丝髻绾云。
天生下精神，更那堪十指纤纤嫩。
描不就丹青，比天仙少个净瓶。','',''),('yuanqu-1180','川拨棹・不由我泪盈盈，听长空孤雁声。我与你暂出门庭，听我丁宁。自','蒲察善长','yuanqu','','','别情人，雁儿，我其实捱不过衾寒枕冷，相思病积渐成。','',''),('yuanqu-1181','七弟兄・雁儿，你却是怎生？暂停，听我诉离情。一封书与你牢拴定，快','蒲察善长','yuanqu','','','疾忙飞过蓼花汀，听人家寝睡长门静。','',''),('yuanqu-1182','梅花酒・雁儿呀呀的叫几声，惊起那人听，说着咱名姓，他自有人相迎。','蒲察善长','yuanqu','','','从别后不见影，闪得人亡了魂灵。
罗帷中愁怎禁，则为他挂心情。
朝忘餐泪如倾，曲慵唱酒慵斟。','',''),('yuanqu-1183','收江南・雁儿，可怜见今宵独自个冷清清，你与我疾回疾转莫留停，山遥','蒲察善长','yuanqu','','','水远煞劳神。
雁儿，天道儿未明，且休要等闲寻伴宿沙汀。','',''),('yuanqu-1184','正宫・鹦鹉曲','白贲','yuanqu','','','侬家鹦鹉洲边住，是个不识字渔父。
浪花中一叶扁舟，睡煞江南烟雨。','',''),('yuanqu-1185','双调・百字折桂令','白贲','yuanqu','','','弊裘尘土压征鞍鞭倦袅芦花，弓剑萧萧，一径入烟霞。
动羁怀西风木叶秋水兼葭，千点万点老树昏鸦，三行两行写长空哑哑雁落平沙。
曲岸西边近水湾鱼网纶竿钓槎，断桥东壁傍溪山竹篱茅舍人家。
满山满谷，红叶黄花，正是伤感凄凉时候，离人又在天涯。
套数。','',''),('yuanqu-1186','黄钟・醉花阴','白贲','yuanqu','','','独倚屏山把玉纤屈，并鸳枕将归期算彻。
一自玉人别，瘦骨岩岩，趱过裙腰摺。','',''),('yuanqu-1187','出队子・粉香一捻，不思量难弃舍。语怜檀口口咨嗟，情怨芳心心哽噎，','白贲','yuanqu','','','愁压蛾眉眉暗结。','',''),('yuanqu-1188','幺・秦欢晋爱成吴越，料今生缘分拙。四时饮饣善强捱些，千种恩情有间','白贲','yuanqu','','','隔，海洋相思无处说。','',''),('yuanqu-1189','神仗儿煞・菱花半缺，合欢带绝。楚岫云迷，蓝桥月缺。银瓶沉坠，琼簪','白贲','yuanqu','','','碎折。
锦筝应折弦难接，骖鸾梦宁贴，修鸳简更悲切。
紫砚飞香，墨浮兰麝。
蘸秋毫撇代喉舌，诉离情粉笺和泪写。','',''),('yuanqu-1190','仙吕・祆神急','白贲','yuanqu','','','绿阴笼小院，红雨点苍苔。
谁想东君也是人间客，纵分连理枝，谩解合欢带，伤春早是心地窄。
愁山和闷海，畅会栽排。','',''),('yuanqu-1191','六幺遍・更别离怨，风流债。云归楚岫，月冷秦台。当时眷爱，如今阻隔。','白贲','yuanqu','','','准备从今因他害，伤怀，冷清清日月怎生捱？。','',''),('yuanqu-1192','元和令・鸾交何日重？鸳梦几时再？清明前后约归期，到如今牡丹开。空','白贲','yuanqu','','','等待翠屏香里掩东风，铺陈下愁境界。','',''),('yuanqu-1193','赚尾・无情子规声更哀，畅好明白。既道不如归去，看你几声儿撺掇得那','白贲','yuanqu','','','人来？。','',''),('yuanqu-1194','双调・新水令','白贲','yuanqu','','','离情不奈子规啼，更那堪困人天气。
红玉软，绿云低。
春昼迟迟，东风恨两眉系。','',''),('yuanqu-1195','风入松・玉钩闲控绣帘垂，半掩朱扉。宝鉴鸾台尽尘昧，凤凰箫谁品谁吹？','白贲','yuanqu','','','绣塌空闲枕犀，篆烟消香冷金猊。','',''),('yuanqu-1196','不拜门・冷清清寂寞在香闺，闷恹恹潇洒在罗帏。画苔墙划短金锴，尚未','白贲','yuanqu','','','得回归。','',''),('yuanqu-1197','胡十八・往常时星月底，雨云期。到如今成间阔，受孤栖，奈何楚岫冷烟','白贲','yuanqu','','','迷？当初时想伊，为伊，消玉体减香肌。','',''),('yuanqu-1198','离带歇拍煞・急煎煎愁滴相思泪，意悬悬慵拥鲛绡被。揽衣儿倦起，恨绵','白贲','yuanqu','','','绵，情脉脉，人千里。
非是俺，贪春睡，勉强将鸳鸯枕欹。
薄幸可憎才，只怕相逢在梦儿里。','',''),('yuanqu-1199','仙吕・一半儿拟美人八咏春梦','查德卿','yuanqu','','','梨花云绕锦香亭，胡蝶春融软玉屏，花外鸟啼三四声。
梦初惊，一半儿昏迷一半儿醒。
春困琐窗人静日初曛，宝鼎香消火尚温，斜倚绣床深闭门。
眼昏昏，一半儿微开一半儿盹。
春妆自将杨柳品题人，笑捻花枝比较春，输与海棠三四分。
再偷匀，一半儿胭脂一半儿粉。
春愁厌听野鹊语雕檐，怕见杨花扑绣帘，拈起绣针还倒拈。
两眉尖，一半儿微舒一半儿敛。
春醉海棠红晕润初妍，杨柳纤腰舞自偏，笑倚玉奴娇欲眠。
粉郎前，一半儿支吾一半儿软。
春绣绿窗时有唾茸粘，银甲频将彩线ㄎ，绣到凤凰心自嫌。
按春纤，一半儿端相一半儿掩。
春夜柳绵扑槛晚风轻，花影横窗淡月明，翠被麝兰薰梦醒。
最关情，一半儿温温一半儿冷。
春情自调花露染霜毫，一种春心无处托，欲写写残三四遭。
絮叨叨，一半儿连真一半儿草。','',''),('yuanqu-1200','南吕・醉太平寄情','查德卿','yuanqu','','','钗分凤凰，衾剩鸳鸯，锦笺遗恨爱花香，写新愁半张。
晚妆楼阁空凝望，旧游台榭添惆怅，落花庭院又昏黄，正离人断肠。
春情东风柳丝，细雨花枝，好春能有几多时？韶华迅指。
芭蕉叶上鸳鸯字，芙蓉帐里鸾凰事，海棠亭畔鹧鸪词，问莺儿燕子。
楼台管弦，院落秋千，香风淡淡月娟娟，朱帘半卷。
香消玉腕黄金钏，歌残素手白罗扇，汗溶粉面翠花细，倚阑人未眠。
春风管弦，夜月秋千，调风弄月醉花前，把花枝笑捻。
千金曾许如花面，半生未了看花愿，一春长费买花钱。
风流少年。
清名先生子陵，隐者渊明，南州旧隐老云卿，为清高显名。
一个向七里滩曾受君王聘，一个向五柳庄终受彭泽令，一个向百花洲不受宋朝征，与巢由共清。','',''),('huajianji-001','菩萨蛮 其一','温庭筠','huajianji','菩萨蛮','','小山重叠金明灭，鬓云欲度香腮雪。
懒起画蛾眉，弄妆梳洗迟。
照花前后镜，花面交相映。
新帖绣罗襦，双双金鹧鸪。','["1.小山--写女子的隔夜残妆。小山：女子画眉的式样之一。小山重叠：眉晕褪色。金：额黄，在额上涂黄色。金明灭：褪色的额黄明暗不匀。","2.鬓云欲度--鬓发撩乱如云，低垂下来。香腮雪：洁白如雪的香腮。","3.照花--对镜簪花。用前镜、后镜对照以瞻顾后影。","4.双双--罗襦上用金线绣的成双的鹧鸪鸟。反衬自身孤独。"]',''),('huajianji-002','菩萨蛮 其二','温庭筠','huajianji','菩萨蛮','','水晶帘里玻璃枕，暖香惹梦鸳鸯锦。
江上柳如烟，雁飞残月天。
藕丝秋色浅，人胜参差剪。
双鬓隔香红，玉钗头上风。','["1.鸳鸯锦--绣有鸳鸯图案的锦被。","2.藕丝--写女子衣裳的颜色。","3.人胜--人形首饰。古代风俗于正月七日（人日）剪彩为人形，戴在头上。","4.香红--指花。","5.风--因走动而生风。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('huajianji-003','菩萨蛮 其三','温庭筠','huajianji','菩萨蛮','','蕊黄无限当山额，宿妆隐笑纱窗隔。
相见牡丹时，暂来还别离。
翠钗金作股，钗上蝶双舞。
心事竟谁知，月明花满枝。','["1.蕊黄--形容女子的黄额妆。","2.宿妆--宿妆：隔夜妆。","3.隐笑--浅笑。","4.牡丹时--牡丹开花的时节，即暮春。","5.暂--一时。指时间短。"]',''),('huajianji-004','菩萨蛮 其四','温庭筠','huajianji','菩萨蛮','','翠翘金缕双鸂鶒，水纹细起春池碧。
池上海棠梨，雨晴红满枝。
绣衫遮笑靥，烟草粘飞蝶。
青琐对芳菲，玉关音信稀。','["1.鸂鶒--水鸟，又名紫鸳鸯。","2.海棠梨--一种果树，二月开红花。","3.笑靥--笑时出现的酒窝。","4.烟草--草色如烟。指春草茂盛的样子。","5.青琐--门窗上雕刻着花格，涂成青色。","6.玉关--玉门 关。故址在今甘肃省敦煌西北。此处代指边关。"]',''),('huajianji-005','菩萨蛮 其五','温庭筠','huajianji','菩萨蛮','','杏花含露团香雪，绿杨陌上多离别。
灯在月胧明，觉来闻晓莺。
玉钩褰翠幕，妆浅旧眉薄。
春梦正关情，镜中蝉鬓轻。','["1.月胧明--月色朦胧。","2.褰--读(qian1),提起，挂起。","3.关情--涉及、牵连别后的情思。"]',''),('huajianji-006','菩萨蛮 其六','温庭筠','huajianji','菩萨蛮','','玉楼明月长相忆，柳丝袅娜春无力。
门外草萋萋，送君闻马嘶。
画罗金翡翠，香烛消成泪。
花落子规啼，绿窗残梦迷。','["1.玉楼--闺楼的美称。","2.袅娜--轻柔细长的样子。","3.草萋萋-春草茂盛的样子。此处借春草起兴，比喻思远怀人的意绪。","4.画罗--罗帷上画有金色的翡翠鸟。翡翠鸟：即翠鸟。","5.子规--杜鹃鸟，其叫声如“不如归去”。","6.绿窗--此处代指闺人居室。"]',''),('huajianji-007','菩萨蛮 其七','温庭筠','huajianji','菩萨蛮','','凤凰相对盘金缕，牡丹一夜经微雨。
明镜照新妆，鬓轻双脸长。
画楼相望久，栏外垂丝柳。
音信不归来，社前双燕回。','["1.凤凰--衣上盘绣着成双的金色凤凰。","2.画楼--闺楼。","3.社前--社日之前。春社在立春后，燕子归来。"]',''),('huajianji-008','菩萨蛮 其八','温庭筠','huajianji','菩萨蛮','','牡丹花谢莺声歇，绿杨满院中庭月。
相忆梦难成，背窗灯半明。
翠钿金压脸，寂寞香闺掩。
人远泪阑干，燕飞春又残。','["1.牡丹花谢--形容春天已过。","2.翠钿--翠钿：以翠玉镶嵌的金首饰。压：遮掩。","3.阑干--眼泪纵横的样子。"]',''),('huajianji-009','菩萨蛮 其九','温庭筠','huajianji','菩萨蛮','','满宫明月梨花白，故人万里关山隔。
金雁一双飞，泪痕沾绣衣。
小园芳草绿，家住越溪曲。
杨柳色依依，燕归君不归。','["1.关山--泛指边塞之地。","2.金雁--筝柱。这里指弹筝。","3.越溪曲--越溪：相传为越国美女 西施浣纱之溪。曲：深隐处。"]',''),('huajianji-010','菩萨蛮 其十','温庭筠','huajianji','菩萨蛮','','宝函钿雀金鸂鶒，沉香阁上吴山碧。
杨柳又如丝，驿桥春雨时。
画楼音信断，芳草江南岸。
鸾镜与花枝，此情谁得知。','["1.宝函--宝函：枕头。","2.钿雀--金钗。嵌金头饰","3.鸂鶒--（水鸟名）又名紫鸳鸯","4.沉香阁--沉香阁：此处泛指精美的亭阁。","5.吴山--又名胥山，在浙江杭州市西湖东南。","6.鸾镜--饰有鸾鸟图案的妆镜。"]',''),('huajianji-011','菩萨蛮 其十一','温庭筠','huajianji','菩萨蛮','','南园满地堆轻絮，愁闻一霎清明雨。
雨后却斜阳，杏花零落香。
无言匀睡脸，枕上屏山掩。
时节欲黄昏，无聊独倚门。','["1.一霎--一阵子。","2.却--再，又。","3.屏山--画着山水的屏风。"]',''),('huajianji-012','菩萨蛮 其十二','温庭筠','huajianji','菩萨蛮','','夜来皓月才当午，重帘悄悄无人语。
深处麝烟长，卧时留薄妆。
当年还自惜，往事那堪忆。
花落月明残，锦衾知晓寒。','["1.当午--月在中天。"]',''),('huajianji-013','菩萨蛮 其十三','温庭筠','huajianji','菩萨蛮','','雨暗夜合玲珑日，万枝香袅红丝拂。
闲梦忆金堂，满庭萱草长。
绣帘垂簏簌，眉黛远山绿。
春水渡溪桥，凭栏魂欲消。','["1.夜合玲珑日--夜合：又名合欢。古时赠人，以消怨合好。玲珑：空明。","2.萱草--草本植物，又名忘忧，传说能使人忘忧。","3.簏簌--簏（lù）簌（sù)。此处指帘子下垂的穗子、流苏一类的饰物","4.眉黛远山--用黛画眉，秀丽如远山。"]',''),('huajianji-014','菩萨蛮 其十四','温庭筠','huajianji','菩萨蛮','','竹风轻动庭除冷，珠帘月上玲珑影。
山枕隐秾妆，绿檀金凤凰。
两蛾愁黛浅，故国吴宫远。
春恨正关情，画楼残点声。','["1.庭除--庭前阶下。","2.山枕--枕头形状如山。","3.绿檀--绿檀：指檀枕。金凤凰：金凤钗。","4.两蛾--双眉。","5.吴宫--吴地的宫阙。此处暗用西施入吴的典故。","6.残点声--即残漏将尽的声音。表示天将明。"]',''),('huajianji-015','更漏子 其一','温庭筠','huajianji','更漏子','','柳丝长，春雨细，花外漏声迢递。
惊塞雁，起城乌，画屏金鹧鸪。
香雾薄，透帘幕，惆怅谢家池阁。
红烛背，绣帘垂，梦长君不知。','["1.迢递--遥远。","2.谢家池阁--原指唐李德裕之妾谢秋娘居所。后泛指佳人所居的豪华池阁。","3.红烛背--红烛燃尽。"]',''),('huajianji-016','更漏子 其二','温庭筠','huajianji','更漏子','','星斗稀，钟鼓歇，帘外晓莺残月。
兰露重，柳风斜，满庭堆落花。
虚阁上，倚栏望，还似去年惆怅。
春欲暮，思无穷，旧欢如梦中。','["1.虚阁上--登上空阁。"]',''),('huajianji-017','更漏子 其三','温庭筠','huajianji','更漏子','','金雀钗，红粉面，花里暂时相见。
如我意，感君怜，此情须问天。
香作穗，蜡成泪，还似两人心意。
山枕腻，锦衾寒，觉来更漏残。','["1.香作穗--香燃烬。比喻君心如死灰。"]',''),('huajianji-018','更漏子 其四','温庭筠','huajianji','更漏子','','相见稀，相忆久，眉浅淡烟如柳。
垂翠幕，结同心，待郎熏绣衾。
城上月，白如雪，蝉鬓美人愁绝。
宫树暗，鹊桥横，玉签初报明。','["1.眉浅--形容眉薄如淡烟、形如柳叶。","2.结同心--用锦带制成的菱形连环回文结，表示恩爱同心。","3.鹊桥横--星星移动。比喻天将晓。","4.玉签--报更所用的竹签。"]',''),('huajianji-019','更漏子 其五','温庭筠','huajianji','更漏子','','背江楼，临海月，城上角声呜咽。
堤柳动，岛烟昏，两行征雁分。
京口路，归帆渡，正是芳菲欲度。
银烛尽，玉绳低，一声村落鸡。','["1.角--古乐器名。多用作军号。","2.京口路--故址在今江苏省镇江市。","3.玉绳--星名。其两星。"]',''),('huajianji-020','更漏子 其六','温庭筠','huajianji','更漏子','','玉炉香，红蜡泪，偏照画堂秋思。
眉黛薄，鬓云残，夜长衾枕寒。
梧桐树，三更雨，不道离情正苦。
一叶叶，一声声，空阶滴到明。','["1.不道--不管，不顾。"]',''),('huajianji-021','归国遥·香玉','温庭筠','huajianji','归国遥','','香玉，翠凤宝钗垂簏簌，胜金粟，越罗春水绿。
画堂照帘残烛，梦余更漏促。
谢娘无限心曲，晓屏山断续。','["1.香玉--头饰。","2.簏簌--钗的穗。","3.钿筐--钿筐、金粟等饰物交互为美。","4.越罗--用越罗制成的衣服，色绿如春水。","5.谢娘--泛指闺中女子。"]',''),('huajianji-022','归国遥·双脸','温庭筠','huajianji','归国遥','','双脸，小凤战蓖金飐艳。舞衣无力风敛，藕丝秋色染。
锦帐绣帷斜掩，露珠清晓簟。
粉心黄蕊花靥，黛眉山两点。','["1.小凤--小凤：形如小凤的梳发用的篦。","2.战--通“颤”，颤动。","3.金飐艳--篦的颜色。飐艳：光彩闪动。","4.藕丝--形容舞衣的颜色。","5.簟--读：（dian4）竹席。","6.花靥--面部妆饰。"]',''),('huajianji-023','酒泉子·花映柳条','温庭筠','huajianji','酒泉子','','花映柳条，闲向绿萍池上。
凭栏干，窥细浪，雨萧萧。
近来音信两疏索，洞房空寂寞。
掩银屏，垂翠箔，度春宵。','["1.疏索--稀疏。","2.箔--帘。"]',''),('huajianji-024','酒泉子·日映纱窗','温庭筠','huajianji','酒泉子','','日映纱窗，金鸭小屏山碧。
故乡春，烟霭隔，背兰釭。
宿妆惆怅倚高阁，千里云影薄。
草初齐，花又落，燕双双。','["1.金鸭--金属的鸭形香炉。","2.背兰釭--背：熄。兰釭：用兰膏点的灯。釭：（gang1）"]',''),('huajianji-025','酒泉子·楚女不归','温庭筠','huajianji','酒泉子','','楚女不归，楼枕小河春水。
月孤明，风又起，杏花稀。
玉钗斜簪云鬟髻，裙上金缕凤。
八行书，千里梦，雁南归。','["1.楚女--此处指所思念的女子。","2.八行书--代指书信。"]',''),('huajianji-026','酒泉子·罗带惹香','温庭筠','huajianji','酒泉子','','罗带惹香，犹系别时红豆。
泪痕新，金缕旧，断离肠。
一双娇燕语雕梁，还是去年时节。
绿阴浓，芳草歇，柳花狂。','["1.红豆--又名相思子。","2.金缕--金丝绣衣。"]',''),('huajianji-027','定西番·汉使昔年离别','温庭筠','huajianji','定西番','','汉使昔年离别。
攀弱柳，折寒梅，上高台。
千里玉关春雪，雁来人不来。
羌笛一声愁绝，月徘徊。','["1.汉使--此处代指出使西番的官吏。","2.攀弱柳--攀折柳枝，表示赠别。","3.折寒梅--折梅寄远，表达思念之情。","4.千里玉关--泛指边塞。"]',''),('huajianji-028','定西番·海燕欲飞调羽','温庭筠','huajianji','定西番','','海燕欲飞调羽。萱草绿，杏花红，隔帘栊。
双鬓翠霞金缕，一枝春艳浓。
楼上月明三五，琐窗中。','["1.帘栊--帘与窗。","2.翠霞金缕--此指华丽的首饰。金缕：钗的穗。","3.三五--农历十五日的夜晚。","4.琐窗--雕刻有花纹的窗。"]',''),('huajianji-029','定西番·细雨晓莺春晚','温庭筠','huajianji','定西番','','细雨晓莺春晚。
人似玉，柳如眉，正相思。
罗幕翠帘初卷，镜中花一枝。
肠断塞门消息，雁来稀。','["1.肠断--形容极度思念。"]',''),('huajianji-030','杨柳枝·宜春苑外最长条','温庭筠','huajianji','杨柳枝','','宜春苑外最长条，闲袅春风伴舞腰。
正是玉人肠绝处，一渠春水赤栏桥。','["1.宜春苑--宜春苑：秦宫苑名。最长条：指柳条。","2.赤兰桥--桥名。隋时香积渠水流经此桥入京城。"]',''),('huajianji-031','杨柳枝·南内墙东御路傍','温庭筠','huajianji','杨柳枝','','南内墙东御路傍，须知春色柳丝黄。
杏花未肯无情思，何事行人最断肠。','["1.南内--唐时兴庆宫。"]',''),('huajianji-032','杨柳枝·苏小门前柳万条','温庭筠','huajianji','杨柳枝','','苏小门前柳万条，毵毵金线拂平桥。
黄莺不语东风起，深闭朱门伴舞腰。','["1.苏小--苏小小。南齐时钱塘名妓。","2.毵毵金线--形容细长的枝叶。","3.朱门--豪贵家的大门。"]',''),('huajianji-033','杨柳枝·金缕毵毵碧瓦沟','温庭筠','huajianji','杨柳枝','','金缕毵毵碧瓦沟，六宫眉黛惹香愁。
晚来更带龙池雨，半拂栏干半入楼。','["1.碧瓦--琉璃瓦。","2.六宫眉黛--代指皇帝的嫔妃。","3.龙池--在兴庆宫内。据说“常有云气，或见黄龙出其中，谓之龙池”（《长安志》）。"]',''),('huajianji-034','杨柳枝·馆娃宫外邺城西','温庭筠','huajianji','杨柳枝','','馆娃宫外邺城西，远映征帆近拂提。
系得王孙归意切，不关芳草绿萋萋。','["1.馆娃--馆娃宫：春秋时吴国宫殿名，故址在今江苏省吴县市西南。","2.邺城-- 三国时魏都，故址在今河北临漳县西南。","3.系得--用《楚辞·招隐士》：“王孙游兮不归，春草生兮萋萋”语。","4.王孙--代指游子。不关：不相关。"]',''),('huajianji-035','杨柳枝·两两黄鹂色似金','温庭筠','huajianji','杨柳枝','','两两黄鹂色似金，袅枝啼露动芳音。
春来幸自长如线，可惜牵缠荡子心。','["1.幸自--本自。","2.荡子--久行在外、流荡忘返的人。"]',''),('huajianji-036','杨柳枝·御柳如丝映九重','温庭筠','huajianji','杨柳枝','','御柳如丝映九重，凤凰窗映绣芙蓉。
景阳楼畔千条路，一面新妆等晓风。','["1.九重--天子所居之处的九门。","2.凤凰--凤凰窗：宫内雕窗。绣芙蓉：绣帐。","3.景阳--宫名。在今江苏江宁县北。","4.新妆--指楼中佳人晓妆。"]',''),('huajianji-037','杨柳枝·织锦机边莺语频','温庭筠','huajianji','杨柳枝','','织锦机边莺语频，停梭垂泪忆征人。
塞门三月犹萧索，纵有垂杨未觉春。','["1.织锦--暗用前秦苏蕙织锦为回文璇玑图的典故。","2.征--一作“行”。","3.塞门--一作“寒门”。萧索：景物凄凉。","4.纵有--谓塞外春晚。垂杨，泛指柳。"]',''),('huajianji-038','南歌子·手里金鹦鹉','温庭筠','huajianji','南歌子','','手里金鹦鹉，胸前绣凤凰。
偷眼暗形相，不如从嫁与，作鸳鸯。','["1.形相--端详，打量。","2.从嫁与--任从嫁给他。"]',''),('huajianji-039','南歌子·似带如丝柳','温庭筠','huajianji','南歌子','','似带如丝柳，团酥握雪花。
帘卷玉钩斜，九衢尘欲暮，逐香车。','["1.似带--比喻美人腰细。","2.团酥--形容美人面容白皙。","3.九衢--衢读：（qu3）四通八达的道路。","4.香车--装饰豪华的车。"]',''),('huajianji-040','南歌子·鬓堕低梳髻','温庭筠','huajianji','南歌子','','鬓堕低梳髻，连娟细扫眉。
终日两相思，为君憔悴尽，百花时。','["1.连娟--形容眉毛画得娟秀细长。"]',''),('huajianji-041','南歌子·脸上金霞细','温庭筠','huajianji','南歌子','','脸上金霞细，眉间翠钿深。
倚枕覆鸳衾，隔帘莺百啭，感君心。','[]',''),('huajianji-042','南歌子·扑蕊添黄子','温庭筠','huajianji','南歌子','','扑蕊添黄子，呵花满翠鬟。
鸳枕映屏山，明月三五夜，对芳颜。','["1.扑蕊--取花蕊以饰额背。","2.呵花--吹去花上露珠。"]',''),('huajianji-043','南歌子·转盼如波眼','温庭筠','huajianji','南歌子','','转盼如波眼，娉婷似柳腰。
花里暗相招，忆君肠欲断，恨春宵。','[]',''),('huajianji-044','南歌子·懒拂鸳鸯枕','温庭筠','huajianji','南歌子','','懒拂鸳鸯枕，休缝翡翠裙。
罗帐罢炉熏，近来心更切，为思君。','["1.罗帐--不再以炉香熏暖罗帐。"]',''),('huajianji-045','河渎神·河上望丛柯','温庭筠','huajianji','河渎神','','河上望丛柯，庙前春雨来时。
楚山无限鸟飞迟，兰棹空伤别离。
何处杜鹃啼不歇，艳红开尽如血。
蝉鬓美人愁绝，百花芳草佳节。','["1.丛祠--乡野林间的神祠。","2.兰棹--船的美称。","3.艳红--指杜鹃花开的灿烂。"]',''),('huajianji-046','河渎神·孤庙对寒潮','温庭筠','huajianji','河渎神','','孤庙对寒潮，西陵风雨萧萧。
谢娘惆怅倚兰桡，泪流玉箸千条。
暮天愁听思归乐，早梅香满山郭。
回首两情萧索，离魂何处飘泊。','["1.西陵--西陵峡。长江三峡之一。","2.兰桡--兰桨。代指船。","3.兰箸--比喻眼泪。","4.思归乐--杜鹃鸟的别名。其鸣声近似“不如归去”。","5.山郭--山的四周。"]',''),('huajianji-047','河渎神·铜鼓赛神来','温庭筠','huajianji','河渎神','','铜鼓赛神来，满庭幡盖徘徊。
水村江浦过风雷，楚山如画烟开。
离别橹声空萧索，玉容惆怅妆薄。
青麦燕飞落落，卷帘愁对珠阁。','["1.铜鼓--鸣铜鼓以迎神。赛神：旧俗酬神活动。","2.幡盖--幢幡华盖之类。","3.过风雷--指迎神的车，行如风，声如雷。","4.青麦--青麦：青麦时节，约在三月。落落：多。"]',''),('huajianji-048','女冠子·含娇含笑','温庭筠','huajianji','女冠子','','含娇含笑，宿翠残红窈窕。
鬓如蝉，寒玉簪秋水，轻纱卷碧烟。
雪胸鸾镜里，琪树凤楼前。
寄语青娥伴，早求仙。','["1.宿翠--写女子隔夜残妆。","2.寒玉--玉簪清凉如秋水。","3.琪树--女子妆成树立于凤楼前。","4.青娥伴--这里指身边美女。","5.早求仙--此处指入道观为女冠。此词就词调而作，咏女道士。"]',''),('huajianji-049','女冠子·霞帔云发','温庭筠','huajianji','女冠子','','霞帔云发，钿镜仙容似雪。
画愁眉，遮语回轻扇，含羞下绣帷。
玉楼相望久，花洞恨来迟。
早晚乘鸾去，莫相遗。','["1.霞帔云发--霞帔：有花纹的披肩。云发：头发如云。","2.花洞--女冠所居住的地方。","3.乘鸾去--指成仙。"]',''),('huajianji-050','玉蝴蝶·霞帔云发','温庭筠','huajianji','玉蝴蝶','','秋风凄切伤离，行客未归时。
塞外草先衰江，南雁到迟。
芙蓉凋嫩脸，杨柳堕新眉。
摇落使人悲，断肠谁得知。','["1.芙蓉--嫩脸憔悴如芙蓉凋谢。","2.杨柳--新眉懒画如柳叶脱落。","3.摇落--出自宋玉《九辩》：“悲哉，秋之为气也！萧瑟兮，草木摇落而变衰。”"]',''),('huajianji-051','清平乐·上阳春晚','温庭筠','huajianji','清平乐','','上阳春晚，宫女愁蛾浅。
新岁清平思同辇，争那长安路远。
凤帐鸳被徒熏，寂寞花锁千门。
竞把黄金买赋，为妾将上明君。','["1.上阳--唐代宫殿名。在今河南洛阳。","2.新岁--清平：太平。同辇：同皇帝同车。","3.争那--怎奈。","4.黄金买赋--汉武帝陈皇后失宠 ，以黄金百斤请司马相如写赋，司马相如作《长门赋》，使武帝回心转意。","5.将上--进上。"]',''),('huajianji-052','清平乐·洛阳愁绝','温庭筠','huajianji','清平乐','','洛阳愁绝，杨柳花飘雪。
终日行人恣攀折，桥下流水呜咽。
上马争劝离觞，南浦莺声断肠。
愁杀平原年少，回首挥泪千行。','["1.恣--任意。","2.南浦--代指送别地。","3.愁杀--愁杀：愁煞。忧愁之极。年少：少年。"]',''),('huajianji-053','遐方怨·凭绣槛','温庭筠','huajianji','遐方怨','','凭绣槛，解罗帷。
未得君书，肠断，潇湘春雁飞。
不知征马几时归，海棠花谢也，雨霏霏。','["1.潇湘--潇水和湘水。此泛指湖南湘江 流域。"]',''),('huajianji-054','遐方怨·花半坼','温庭筠','huajianji','遐方怨','','花半坼，雨初晴。
未卷珠帘，梦残，惆怅闻晓莺。
宿妆眉浅粉山横，约鬟鸾镜里，绣罗轻。','["1.坼--绽裂。","2.约鬟--环发为饰。"]',''),('huajianji-055','诉衷情·莺语花舞春昼午','温庭筠','huajianji','诉衷情','','莺语花舞春昼午，雨霏微。
金带枕，宫锦，凤凰帷。
柳弱蝶交飞，依依。
辽阳音信稀，梦中归。','["1.昼午--中午。","2.雨霏微--蒙蒙细雨。","3.金带枕--曹植《洛神赋》李善注：曹植求婚于甄后的玉缕金带枕。曹植睹物流泪。此用其典。","4.辽阳--县名。故址在今辽宁省辽阳县西北。此处泛指边塞。"]',''),('huajianji-056','思帝乡·花花','温庭筠','huajianji','思帝乡','','花花，满枝红似霞。
罗袖画帘肠断，卓香车。
回面共人闲语，战篦金凤斜。
惟有阮郎春尽，不归家。','["1.卓--立。","2.战篦金凤--头饰。","2.阮郎--阮肇，东汉人，传说他和刘晨入天台山采药，因迷路遇到两位仙女，并喜结良缘，半年后返家，世间已过数百年。这里借指不归者。"]',''),('huajianji-057','梦江南·千万恨','温庭筠','huajianji','梦江南','','千万恨，恨极在天涯。
山月不知心里事，水风空落眼前花，摇曳碧云斜。','[]',''),('huajianji-058','梦江南·梳洗罢','温庭筠','huajianji','梦江南','','梳洗罢，独倚望江楼。
过尽千帆皆不是，斜晖脉脉水悠悠，肠断白苹洲。','["1.白苹洲--洲渚名。代指分手的地方。"]',''),('huajianji-059','河传·江畔','温庭筠','huajianji','河传','','江畔，相唤。
晓妆鲜，仙景个女采莲。
请君莫向那岸边，少年，好花新满船。
红袖摇曳逐风暖，垂玉腕，肠向柳丝断。
浦南归，浦北归，莫知，晚来人已稀。','["1.个女--那个或那些女子。"]',''),('huajianji-060','河传·湖上','温庭筠','huajianji','河传','','湖上，闲望。
雨萧萧，烟浦花桥路遥。
谢娘翠蛾愁不消，终朝，梦魂迷晚潮。
荡子天涯归棹远，春已晚，莺语空肠断。
若耶溪，溪水西，柳堤，不闻郎马嘶。','["1.翠蛾--翠眉。","2.终朝--一整天。","3.若耶溪--溪名，传说西施曾在此浣沙，地址在今浙江 省绍兴市若耶山下。"]',''),('huajianji-061','河传·同伴','温庭筠','huajianji','河传','','同伴，相唤。
杏花稀，梦里每愁依违。
仙客一去燕已飞，不归，泪痕空满衣。
天际云鸟引晴远，春已晚，烟霭渡南苑。
雪梅香，柳带长，小娘，转令人意伤。','["1.依违--反覆，迟疑不决。","2.仙客--代指所思之人。","3.引晴远--版本作引情远”。","4.小娘--指少女。"]',''),('huajianji-062','番女怨·万枝香雪开已遍','温庭筠','huajianji','番女怨','','万枝香雪开已遍，细雨双燕。
钿蝉筝，金雀扇，画梁相见。
雁门消息不归来，又飞回。','["1.香雪--杏花。","2.钿蝉筝--饰以金蝉的筝。","3.金雀扇--画以金雀的扇。","4.画梁--彩绘的屋梁。此处指燕栖的地方。","5.雁门--关名。在今山西代县西北。此处泛指边塞。"]',''),('huajianji-063','番女怨·碛南沙上惊雁起','温庭筠','huajianji','番女怨','','碛南沙上惊雁起，飞雪千里。
玉连环，金镞箭，年年征战。
画楼离恨锦屏空，杏花红。','["1.碛南沙上--沙漠。","2.玉连环--征人服饰物。","3.金镞箭--饰以金箭头的箭。常用为信物。"]',''),('huajianji-064','荷叶杯·一点露珠凝冷','温庭筠','huajianji','荷叶杯','','一点露珠凝冷，波影。满池塘。
绿茎红艳两相乱，肠断。水风凉。','["1.绿茎红艳--绿茎：荷茎。红艳：荷花。"]',''),('huajianji-065','荷叶杯·镜水夜来秋月','温庭筠','huajianji','荷叶杯','','镜水夜来秋月，如雪。采莲时。
小娘红粉对寒浪，惆怅。正思惟。','["1.镜水--镜湖水。在今浙江 省绍兴市内。","2.小娘--此处指采莲少女。"]',''),('huajianji-066','荷叶杯·楚女欲归南浦','温庭筠','huajianji','荷叶杯','','楚女欲归南浦，朝雨。湿愁红。
小船摇漾入花里，波起。隔西风。','["1.愁红--指花。"]',''),('huajianji-067','天仙子·晴野鹭鸶飞一只','皇甫松','huajianji','天仙子','','晴野鹭鸶飞一只，水荭花发秋江碧。
刘郎此日别天仙，登绮席，泪珠滴，十二晚峰高历历。','["1.鹭鸶--白鹭。","2.水荭--水草。","3.刘郎--用刘晨与阮肇入天台山采药遇仙女事。参见卷第二温 庭筠《思帝乡》注。","4.十二晚峰--巫山十二峰。"]',''),('huajianji-068','天仙子·踯躅花开红照水','皇甫松','huajianji','天仙子','','踯躅花开红照水，鹧鸪飞绕青山觜。
行人经岁始归来，千万里，错相倚，懊恼天仙应有以。','["1.踯躅花--又名杜鹃花。","2.山觜--山入口处。","3.行人经岁--行人：这里指刘晨、阮肇。经岁：经年，相隔一年。","4.有以--有缘由。"]',''),('huajianji-069','浪淘沙·滩头细草接疏林','皇甫松','huajianji','浪淘沙','','滩头细草接疏林，浪恶罾船半欲沉。
宿鹭眠鸥飞旧浦，去年沙嘴是江心。','["1.罾船--渔船。罾：渔人的网。","2.去年--去年旧浦的沙嘴今已变成江 心。"]',''),('huajianji-070','浪淘沙·蛮歌豆蔻北人愁','皇甫松','huajianji','浪淘沙','','蛮歌豆蔻北人愁，蒲雨杉风野艇秋。
浪起䴔䴖眠不得，寒沙细细入江流。','["1.蛮歌--南方少数民族的歌。","2.䴔䴖--水鸟。"]',''),('huajianji-071','杨柳枝·春入行宫映翠微','皇甫松','huajianji','杨柳枝','','春入行宫映翠微，玄宗侍女舞烟丝。
如今柳向空城绿，玉笛何人更把吹。','["1.翠微--淡青的山色。","2.玄宗侍女--玄宗侍女：唐玄宗命宫中女子数百人，为梨园弟子。","3.舞烟丝--舞姿如烟柳柔丝。","4.玉笛--唐玄宗曾亲把玉笛，吹《杨柳枝》调。更把：再把。"]',''),('huajianji-072','杨柳枝·烂漫春归水国时','皇甫松','huajianji','杨柳枝','','烂漫春归水国时，吴王宫殿柳丝垂。
黄莺长叫空闺畔，西子无因更得知。','["1.吴王宫殿--此处指吴王夫差所筑的宫殿。"]',''),('huajianji-073','摘得新·酌一卮','皇甫松','huajianji','摘得新','','酌一卮，须教玉笛吹。
锦筵红蜡烛，莫来迟。
繁红一夜经风雨，是空枝。','["1.卮--酒器。","2.锦筵--精美的酒席。"]',''),('huajianji-074','摘得新·摘得新','皇甫松','huajianji','摘得新','','摘得新，枝枝叶叶春。
管弦兼美酒，最关人。
平生都得几十度，展香茵。','["1.摘得新--摘得鲜花。","2.最关人--最牵动人情。","3.香茵--香褥。"]',''),('huajianji-075','梦江南·兰烬落','皇甫松','huajianji','梦江南','','兰烬落，屏上暗红蕉。
闲梦江南梅熟日，夜船吹笛雨萧萧，人语驿边桥。','["1.兰烬--用兰膏燃的灯烛灭了。","2.梅熟日--初夏梅熟季节。俗称黄梅天”。"]',''),('huajianji-076','梦江南·楼上寝','皇甫松','huajianji','梦江南','','楼上寝，残月下帘旌。
梦见秣陵惆怅事，桃花柳絮满江城，双髻坐吹笙。','["1.秣陵--古金陵别名。故址在今江 苏省南京市。","2.双髻--少女的发型。此处代指少女。"]',''),('huajianji-077','采莲子·菡萏香莲十顷陂','皇甫松','huajianji','采莲子','','菡萏香莲十顷陂（举棹），小姑贪戏采莲迟（年少）。
晚来弄水船头湿（举棹），更脱红裙裹鸭儿（年少）。','["1.举棹--唱词时众人相和之声 。下文年少”等同此。","2.小姑--未嫁的少女。"]',''),('huajianji-078','采莲子·船动湖光滟滟秋','皇甫松','huajianji','采莲子','','船动湖光滟滟秋（举棹），贪看年少信船流（年少）。
无端隔水抛莲子（举棹），遥被人知半日羞（年少）。','["1.信船流--听任船随水而流。"]',''),('huajianji-079','浣溪沙·清晓妆成寒食天','韦庄','huajianji','浣溪沙','','清晓妆成寒食天，柳球斜袅间花钿，卷帘直出画堂前。
指点牡丹初绽朵，日高犹自凭朱栏，含颦不语恨春残。','["1.寒食--节令名。在农历清明前一日。","2.柳球--弯曲柳枝成球形。清明日妇女有带柳的风俗。","3.含颦--皱眉。"]',''),('huajianji-080','浣溪沙·欲上秋千四体慵','韦庄','huajianji','浣溪沙','','欲上秋千四体慵，拟教人送又心忪。画堂帘幕月明风。
此夜有情谁不极，隔墙梨雪又玲珑，玉容憔悴惹微红。','["1.慵--倦怠。","2.心忪--惶恐。","3.不极--不尽。"]',''),('huajianji-081','浣溪沙·惆怅梦余山月斜','韦庄','huajianji','浣溪沙','','惆怅梦余山月斜，孤灯照壁背窗纱，小楼高阁谢娘家。
暗想玉容何所似，一枝春雪冻梅花，满身香雾簇朝霞。','["1.簇--聚。"]',''),('huajianji-082','浣溪沙·绿树藏莺莺玉啼','韦庄','huajianji','浣溪沙','','绿树藏莺莺玉啼，柳丝斜拂白铜堤，弄珠江上草萋萋。
日暮饮归何处客，绣鞍骢马一声嘶，满身兰麝醉如泥。','["1.白铜堤--堤名。在今湖北襄樊。","2.弄珠--戏珠。","3.骢马--青白杂色马。","4.兰麝--兰草和麝香两种香料。这里指香气。"]',''),('huajianji-083','浣溪沙·夜夜相思更漏残','韦庄','huajianji','浣溪沙','','夜夜相思更漏残，伤心明月凭栏干，想君思我锦衾寒。
咫尺画堂深似海，忆来唯把旧书看，几时携手入长安。','["1.旧书--以往的来信。"]',''),('huajianji-084','菩萨蛮·红楼别夜堪惆怅','韦庄','huajianji','菩萨蛮','','红楼别夜堪惆怅，香灯半卷流苏帐。
残月出门时，美人和泪辞。
琵琶金翠羽，弦上黄莺语。
劝我早归家，绿窗人似花。','["1.金翠羽--琵琶上嵌金点翠的装饰。","2.弦上--形容琵琶弹奏声如黄莺语。"]',''),('huajianji-085','菩萨蛮·人人尽说江南好','韦庄','huajianji','菩萨蛮','','人人尽说江南好，游人只合江南老。
春水碧于天，画船听雨眠。
垆边人似月，皓腕凝双雪。
未老莫还乡，还乡须断肠。','["1.只合--只应，只当。","2.垆边--暗用汉代卓文君当垆卖酒事。垆：酒店安放酒坛的土台子。","垆边人：代指美女 。","3.须--应。"]',''),('huajianji-086','菩萨蛮·如今却忆江南乐','韦庄','huajianji','菩萨蛮','','如今却忆江南乐，当时年少春衫薄。
骑马倚斜桥，满楼红袖招。
翠屏金屈曲，醉入花丛宿。
此度见花枝，白头誓不归。','["1.却忆--回忆。","2.金屈曲--屏风上可折叠的环钮、搭扣。","3.花丛--美人聚集处，比喻歌楼。","4.此度--此度：这次。花枝：代指美女 。"]',''),('huajianji-087','菩萨蛮·劝君今夜须沉醉','韦庄','huajianji','菩萨蛮','','劝君今夜须沉醉，樽前莫话明朝事。
珍重主人心，酒深情亦深。
须愁春漏短，莫诉金杯满。
遇酒且呵呵，人生能几何。','["1.春漏短--春夜短。","2.呵呵--笑声。此处指强作欢笑。"]',''),('huajianji-088','菩萨蛮·洛阳城里春光好','韦庄','huajianji','菩萨蛮','','洛阳城里春光好，洛阳才子他乡老。
柳暗魏王堤，此时心转迷。
桃花春水绿，水上鸳鸯浴。
凝恨对残晖，忆君君不知。','["1.洛阳才子--本指西汉洛阳人贾谊，此处作者自称。","2.魏王堤--在洛阳。为唐代都城名胜。"]',''),('huajianji-089','归国遥·春欲暮','韦庄','huajianji','归国遥','','春欲暮，满地落花红带雨。
惆怅玉笼鹦鹉，单栖无伴侣。
南望去程何许，问花花不语。
早晚得同归去，恨无双翠羽。','["1.何许--多少。"]',''),('huajianji-090','归国遥·金翡翠','韦庄','huajianji','归国遥','','金翡翠，为我南飞传我意。
罨画桥边春水，几年花下醉。
别后只知相愧，泪珠难远寄。
罗幕绣帷鸳被，旧欢如梦里。','["1.金翡翠--金色翡翠鸟。","2.罨画--杂色的彩画。此处形容春水如画。"]',''),('huajianji-091','归国遥·春欲晚','韦庄','huajianji','归国遥','','春欲晚，戏蝶游蜂花烂漫。
日落谢家池馆，柳丝金缕断。
睡觉绿鬟风乱，画屏云雨散。
闲倚博山长叹，泪流沾皓腕。','["1.云雨--用宋玉《高唐赋》序中楚襄王梦与巫山神女相会的事。后代称男女遇合的事。","2.博山--博山炉。古香炉名，表面雕刻有重叠山形的装饰。此处代指香炉。"]',''),('huajianji-092','应天长·绿槐阴里黄莺语','韦庄','huajianji','应天长','','绿槐阴里黄莺语，深院无人春昼午。
画帘垂，金凤舞，寂寞绣屏香一炷。
碧天云，无定处，空有梦魂来去。
夜夜绿窗风雨，断肠君信否。','["1.金凤舞--帘上画金凤，风吹而舞。","2.碧天云--比喻远行人行踪不定。"]',''),('huajianji-093','应天长·别来半岁音书绝','韦庄','huajianji','应天长','','别来半岁音书绝，一寸离肠千万结。
难相见，易相别，又是玉楼花似雪。
暗相思，无处说，惆怅夜来烟月。
想得此时情切，泪沾红袖黦。','["1.黦--污迹。此处指泪痕。"]',''),('huajianji-094','荷叶杯·绝代佳人难得','韦庄','huajianji','荷叶杯','','绝代佳人难得，倾国，花下见无期。
一双愁黛远山眉，不忍更思惟。
闲掩翠屏金凤，残梦，罗幕画堂空。
碧天无路信难通，惆怅旧房栊。','["1.倾国--指容貌绝美。","2.思惟--思量。","3.房栊--窗户。"]',''),('huajianji-095','荷叶杯·记得那年花下','韦庄','huajianji','荷叶杯','','记得那年花下，深夜，初识谢娘时。
水堂西面画帘垂，携手暗相期。
惆怅晓莺残月，相别，从此隔音尘。
如今俱是异乡人，相见更无因。','["1.相期--相约。","2.音尘--音讯、踪迹。"]',''),('huajianji-096','清平乐·春愁南陌','韦庄','huajianji','清平乐','','春愁南陌，故国音书隔。
细雨霏霏梨花白，燕拂画帘金额。
尽日相望王孙，尘满衣上泪痕。
谁向桥边吹笛，驻马西望销魂。','["1.金额--金线装饰的帘额。","2.王孙--古代贵族子弟的通称。"]',''),('huajianji-097','清平乐·野花芳草','韦庄','huajianji','清平乐','','野花芳草，寂寞关山道。
柳吐金丝莺语早，惆怅香闺暗老。
罗带悔结同心，独凭朱栏思深。
梦觉半床斜月，小窗风触鸣琴。','["1.关山道--代指远人所行处。","2.结同心--同心结。用锦带打成连环回文结。表示男女相爱。"]',''),('huajianji-098','清平乐·何处游女','韦庄','huajianji','清平乐','','何处游女，蜀国多云雨。
云解有情花解语，窣地绣罗金缕。
妆成不整金钿，含羞待月秋千。
住在绿槐阴里，门临春水桥边。','["1.窣地--拂地。"]',''),('huajianji-099','清平乐·莺啼残月','韦庄','huajianji','清平乐','','莺啼残月，绣阁香灯灭。
门外马嘶郎欲别，正是落花时节。
妆成不画蛾眉，含愁独倚金扉。
云路香尘莫扫，扫即郎去归迟。','["1.金扉--饰金的门。","2.香尘--香气遗落在尘土中。"]',''),('huajianji-100','望远行·欲别无言倚画屏','韦庄','huajianji','望远行','','欲别无言倚画屏，含恨暗伤情。
谢家庭树锦鸡鸣，残月落边城。
人欲别，马频嘶，绿槐千里长堤。
出门芳草路萋萋，云雨别来易东西。
不忍别君后，却入旧香闺。','[]',''),('huajianji-101','谒金门·春漏促','韦庄','huajianji','谒金门','','春漏促，金烬暗挑残烛。
一夜帘前风撼竹，梦魂相断续。
有个娇娆如玉，夜夜绣屏孤宿。
宋袍琵琶寻旧曲，远山眉黛绿。','["1.金烬--灯火残余。","2.娇娆--妍媚、美丽。代指美人。"]',''),('huajianji-102','谒金门·空相忆','韦庄','huajianji','谒金门','','空相忆，无计得传消息。
天上嫦娥人不识，寄书何处觅。
新睡觉来无力，不忍把伊书迹。
满院落花春寂寂，断肠芳草碧。','[]',''),('huajianji-103','江城子·恩重娇多情易伤','韦庄','huajianji','江城子','','恩重娇多情易伤，漏更长，解鸳鸯。
朱唇未动，先觉口脂香。
缓揭绣衾抽皓腕，移凤枕，枕潘郎。','["1.潘郎--晋人潘岳因貌美，为妇人爱慕。此处代指情人 。"]',''),('huajianji-104','江城子·髻鬟狼藉黛眉长','韦庄','huajianji','江城子','','髻鬟狼藉黛眉长，出兰房，别檀郎。
角声呜咽，星斗渐微茫。
露冷月残人未起，留不住，泪千行。','["1.狼藉--散乱不整的样子。","2.檀郎--晋人潘岳，字安仁，小字檀奴，姿仪秀美，后人以檀郎、潘安、","潘仁等代称美男子。"]',''),('huajianji-105','河传·何处','韦庄','huajianji','河传','','何处，烟雨，隋堤春暮。
柳色葱笼，画桡金缕，翠旗高颭香风，水光融。
青娥殿脚春妆媚，轻云里，绰约司花妓。
江都宫阙，清淮月映迷楼，古今愁。','["1.画桡金缕--画桡：彩绘的桨，代指船。金缕：船的装饰物。","2.颭--因风吹而颤动。","3.青娥殿脚--隋炀帝乘龙舟游江 都，强征民间十五、六岁的子女五百人，为其牵挽彩缆，称为殿脚女。","4.司花妓--为隋炀帝持花的女子。","5.江 都--隋炀帝行宫所在地。故址在今江 苏省扬州市。","6.迷楼--隋炀帝新宫名。故址在今江 苏省扬州市西北。"]',''),('huajianji-106','河传·春晚','韦庄','huajianji','河传','','春晚，风暖，锦城花满。
狂杀游人，玉鞭金勒，寻胜驰骤轻尘，惜良晨。
翠娥争劝临邛酒，纤纤手，拂面垂丝柳。
归时烟里，钟鼓正是黄昏，暗销魂。','["1.锦城--今四川成都市。","2.寻胜--踏春。","3.翠娥--翠娥：美女 ，此处指当垆卖酒女。","临邛（qiong2）酒：汉代卓文君在临邛卖过酒，后代指美酒。"]',''),('huajianji-107','河传·锦浦','韦庄','huajianji','河传','','锦浦，春女，绣衣金缕。
雾薄云轻，花深柳暗，时节正是清明，雨初晴。
玉鞭魂断烟霞路，莺莺语，一望巫山雨。
香尘隐映，遥见翠槛红楼，黛眉愁。','["1.雾薄云轻--形容绣衣。","2.巫山雨--用宋玉《高唐赋》序中巫山云雨事。"]',''),('huajianji-108','天仙子·怅望前回梦里期','韦庄','huajianji','天仙子','','怅望前回梦里期，看花不语苦寻思。
露桃花里小腰肢，眉眼细，鬓云垂，唯有多情宋玉知。','["1.期--会，相会。","2.宋玉--战国时期楚国文学家，着有《神女赋》和《登徒子好色赋》，描写美女 。"]',''),('huajianji-109','天仙子·深夜归来长酩酊','韦庄','huajianji','天仙子','','深夜归来长酩酊，扶入流苏犹未醒。
醺醺酒气麝兰和，惊睡觉，笑呵呵，长道人生能几何。','["1.流苏--流苏帐。","2.麝兰和--与麝兰之气相融合。"]',''),('huajianji-110','天仙子·蟾彩霜华夜不分','韦庄','huajianji','天仙子','','蟾彩霜华夜不分，天外鸿声枕上闻，绣衾香冷懒重熏。
人寂寂，叶纷纷，才睡依前梦见君。','["1.蟾彩霜华--蟾彩：月光。俗传月中有蟾蜍，故称月为蟾。霜华：霜色。"]',''),('huajianji-111','天仙子·梦觉云屏依旧空','韦庄','huajianji','天仙子','','梦觉云屏依旧空，杜鹃声咽隔帘栊，玉郎薄幸去无踪。
一日日，恨重重，泪界莲腮两线红。','["1.玉郎薄幸--情人 薄情。","2.界--划。"]',''),('huajianji-112','天仙子·金似衣裳玉似身','韦庄','huajianji','天仙子','','金似衣裳玉似身，眼如秋水鬓如云，霞裙月帔一群群。
来洞口，望烟分，刘阮不归春日曛。','["1.刘阮--用刘晨、阮肇入天台山采药遇仙事。"]',''),('huajianji-113','喜迁莺·人汹汹','韦庄','huajianji','喜迁莺','','人汹汹，鼓冬冬，襟袖五更风。
大罗天上月朦胧，骑马上虚空。
香满衣，云满路，鸾凤绕身飞舞。
霓旌绛节一群群，引见玉华君。','["1.汹汹--声音喧闹。","2.大罗天--道家所谓诸天最高者。此处指朝廷。","3.上虚空--此处指进宫。","4.鸾凤--指绣有鸾凤花纹的朝服。","5.霓旌降节--指仪仗。","6.玉华君--此处代指皇帝。"]',''),('huajianji-114','喜迁莺·街鼓动','韦庄','huajianji','喜迁莺','','街鼓动，禁城开，天上探人回，凤衔金榜出云来，平地一声雷。
莺已迁，龙已化，一夜满城车马。家家楼上簇神仙，争看鹤冲天。','["1.天上--天上：朝廷。探人：入朝看榜的人。","2.凤衔金榜--凤衔：凤凰衔书，喻指皇帝诏书。金榜：科举应试考中者的名单。","3.莺已迁--唐人称举进士及第为迁莺。","4.龙已化--比喻中第者如鱼化为龙。","5.鹤冲天--比喻登第。"]',''),('huajianji-115','思帝乡·云髻坠','韦庄','huajianji','思帝乡','','云髻坠，凤钗垂。
髻坠钗垂无力，枕函欹。
翡翠屏深月落，漏依依。
说尽人间天上，两心知。','["1.枕函欹--枕函：中间可以放置物体的匣状枕头。欹：斜。"]',''),('huajianji-116','思帝乡·春日游','韦庄','huajianji','思帝乡','','春日游，杏花吹满头。
陌上谁家年少，足风流。
妾拟将身嫁与，一生休。
纵被无情弃，不能羞！','["1.年少--少年。"]',''),('huajianji-117','诉衷情·烛尽香残帘半卷','韦庄','huajianji','诉衷情','','烛尽香残帘半卷，梦初惊。
花欲谢，深夜，月胧明。
何处按歌声，轻轻。
舞衣尘暗生，负春情。','["1.按歌声--击乐唱歌声。"]',''),('huajianji-118','诉衷情·碧沼红芳烟雨静','韦庄','huajianji','诉衷情','','碧沼红芳烟雨静，倚兰桡。
垂玉佩，交带，袅纤腰。
鸳梦隔星桥，迢迢。
越罗香暗销，坠花翘。','["1.碧沼--碧水池。","2.交带--相交 的锦带。","3.星桥--银河。","4.花翘--头饰。"]',''),('huajianji-119','上行杯·芳草灞陵春岸','韦庄','huajianji','上行杯','','芳草灞陵春岸，柳烟深，满楼弦管，一曲离声肠寸断。
今日送君千万，红楼玉盘金镂盏，须劝珍重意，莫辞满。','["1.灞陵--古地名。故址在今陕西西安市东。"]',''),('huajianji-120','上行杯·白马玉鞭金辔','韦庄','huajianji','上行杯','','白马玉鞭金辔，少年郎，离别容易，迢递去程千万里。
惆怅异乡云水，满酌一杯劝和泪，须愧珍重意，莫辞醉。','[]',''),('huajianji-121','女冠子·四月十七','韦庄','huajianji','女冠子','','四月十七，正是去年今日。
别君时，忍泪佯低面，含羞半敛眉。
不知魂已断，空有梦相随。
除却天边月，没人知。','["1.佯--装作。","2.除却--除了。"]',''),('huajianji-122','女冠子·昨夜夜半','韦庄','huajianji','女冠子','','昨夜夜半，枕上分明梦见：语多时，依旧桃花面，频低柳叶眉。
半羞还半喜，欲去又依依。觉来知是梦，不胜悲。','[]',''),('huajianji-123','更漏子·钟鼓寒','韦庄','huajianji','更漏子','','钟鼓寒，楼阁暝，月照古桐金井。
深院闭，小庭空，落花香露红。
烟柳重，春雾薄，灯背水窗高阁。
闲倚户，暗沾衣，待郎郎不归。','["1.暝--晦暗。","2.金井--有雕栏的井。","3.水窗--临水的窗。"]',''),('huajianji-124','酒泉子·月落星沉','韦庄','huajianji','酒泉子','','月落星沉，楼上美人春睡。
绿云倾，金枕腻，画屏深。
子规啼破相思梦，曙色东方才动。
柳烟轻，花露重，思难任。','["1.绿云--美人发髻。","2.腻--泪污。","3.思难任--相思难以抵挡。"]',''),('huajianji-125','木兰花·独上小楼春欲暮','韦庄','huajianji','木兰花','','独上小楼春欲暮，愁望玉关芳草路。
消息断，不逢人，欲敛细眉归绣户。
坐看落花空叹息，罗袂湿斑红泪滴。
千山万水不曾行，魂梦欲教何处觅。','["1.玉关--玉门 关。此处指远人所在地。","2.绣户--闺房。","3.不曾行--不曾去过。"]',''),('huajianji-126','小重山·一闭昭阳春又春','韦庄','huajianji','小重山','','一闭昭阳春又春，夜寒宫漏永，梦君恩。
昏思陈事暗消魂，罗衣湿，红袂有啼痕。
歌吹隔重阍，绕庭芳草绿，倚长门。
万般惆怅向谁论？凝情立，宫殿欲黄昏。','["1.昭和--汉代昭阳殿。","2.陈事--旧事。","3.重阍--重重宫门。","4.长门--汉代长门宫。用汉武帝时陈皇后因失宠 ，别居长门宫事。","5.凝情--痴情。"]',''),('huajianji-127','浣溪沙·红蓼渡头秋正雨','薛昭蕴','huajianji','浣溪沙','','红蓼渡头秋正雨，印沙鸥迹自成行，整鬟飘袖野风香。
不语含颦深浦里，几回愁煞棹船郎，燕归帆尽水茫茫。','["1.棹船郎--驾船郎，指远行的情人 。"]',''),('huajianji-128','浣溪沙·钿匣菱花锦带垂','薛昭蕴','huajianji','浣溪沙','','钿匣菱花锦带垂，静临栏槛卸头时，约鬟低珥算归期。
茂苑草青湘渚阔，梦余空有漏依依，二年终日损芳菲。','["1.菱花--菱花镜。","2.卸头时--卸妆时。","3.珥--冠上的垂珠。","4.茂苑--茂苑：在今江 苏吴县太湖北。湘渚：湘水中的小洲。"]',''),('huajianji-129','浣溪沙·粉上依稀有泪痕','薛昭蕴','huajianji','浣溪沙','','粉上依稀有泪痕，郡庭花落欲黄昏，远情深恨与谁论。
记得去年寒食日，延秋门外卓金轮，日斜人散暗消魂。','["1.郡庭--郡斋的庭。","2.延秋门--延秋门：唐长安禁苑中宫庭门。卓金轮：立车轮，即停车。"]',''),('huajianji-130','浣溪沙·握手河桥柳似金','薛昭蕴','huajianji','浣溪沙','','握手河桥柳似金，蜂须轻惹百花心，蕙风兰思寄清琴。
意满便同春水满，情深还似酒杯深，楚烟湘月两沉沉。','["1.花心--花蕊。","2.蕙风兰思--蕙、兰，都是香草。喻女子纯美的情思。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('huajianji-131','浣溪沙·帘下三间出寺墙','薛昭蕴','huajianji','浣溪沙','','帘下三间出寺墙，满街垂杨绿阴长，嫩红轻翠间浓妆。
瞥地见时犹可可，却来闲处暗思量，如今情事隔仙乡。','["1.瞥地--瞥地：一瞥，过目。可可，不在意。","2.却来--回过来。"]',''),('huajianji-132','浣溪沙·江馆清秋缆客船','薛昭蕴','huajianji','浣溪沙','','江馆清秋缆客船，故人相送夜开筵，麝烟兰焰簇花钿。
正是断魂迷楚雨，不堪离恨咽湘弦，月高霜白水连天。','["1.缆客船--系缆待发的客船。","2.族花钿--聚集着盛妆的女子。","3.湘弦--传说湘水女神善于鼓瑟，这里借喻悲思。"]',''),('huajianji-133','浣溪沙·倾国倾城恨有余','薛昭蕴','huajianji','浣溪沙','','倾国倾城恨有余，几多红泪泣姑苏，倚风凝睇雪肌肤。
吴主山河空落日，越王宫殿半平芜，藕花菱蔓满重湖。','["1.倾城倾国--此指西施的美貌。","2.姑苏--姑苏台。相传吴王夫差所筑。在今江 苏苏州。","3.凝睇--注视。","4.吴主--吴主：吴王夫差。落日：这里比喻亡国。","5.越王--越王勾践。"]',''),('huajianji-134','浣溪沙·越女淘金春水上','薛昭蕴','huajianji','浣溪沙','','越女淘金春水上，步摇云鬓佩鸣璫，渚风江草又清香。
不为远山凝翠黛，只应含恨向斜阳，碧桃花谢忆刘郎。','["1.步摇--步摇：妇女的首饰。","2.刘郎--本指东汉人刘晨，这里代指情郎。"]',''),('huajianji-135','喜迁莺·残蟾落','薛昭蕴','huajianji','喜迁莺','','残蟾落，晓钟鸣，羽化觉身轻。
乍无春睡有余酲，杏苑雪初晴。
紫陌长，襟袖冷，不是人间风景。
回看尘土似前生，休羡谷中莺。','["1.残蟾--残月。","2.羽化--修道成仙。这里指登第。","3.余酲--余醉。","4.杏苑--杏园。唐人举进士，在杏园聚会。","5.紫陌--帝都郊野的道路。","6.谷中莺--比喻隐居未仕者。"]',''),('huajianji-136','喜迁莺·金门晓','薛昭蕴','huajianji','喜迁莺','','金门晓，玉京春，骏马骤轻尘。
桦烟深处白衫新，认得化龙身。
九陌喧，千户启，满袖桂香风细。
杏园欢宴曲江滨，自此占芳辰。','["1.金门--汉代金马门。代称官署。","2.玉京--京城。","3.桦烟--桦烟：桦木皮卷蜡作烛，其烟称桦烟。白衫：唐时士子穿的便服。","4.化龙身--指登第。","5.桂香--古代以折桂喻登第。","6.杏园欢宴--杏园：园名。唐时在曲江 池南，是新进士游宴之地。曲江 ：曲江 池，在今陕西西安市东南曲江 镇一带。","7.芳辰--良辰。"]',''),('huajianji-137','喜迁莺·清明节','薛昭蕴','huajianji','喜迁莺','','清明节，雨晴天，得意正当年。
马骄泥软绵连干，香袖半笼鞭。
花色融，人竞赏，尽是绣鞍朱鞅。
日斜无计更留连，归路草和烟。','["1.锦连干--马的饰物。","2.绣鞍朱鞅--马的饰物。鞅：套在马颈上的皮带。"]',''),('huajianji-138','小重山·春到长门春草青','薛昭蕴','huajianji','小重山','','春到长门春草青，玉阶华露滴，月胧明。
东风吹断紫箫声，宫漏促，帘外晓啼莺。
愁极梦难成，红妆流宿泪，不胜情。
手挼裙带绕阶行，思君切，罗幌暗尘生。','["1.长门--长门宫。用汉武帝时陈皇后失宠 ，别居长门宫事。","2.紫箫--紫竹所做的箫。","3.挼--揉搓。","4.罗幌--丝罗帷帐。"]',''),('huajianji-139','小重山·秋到长门秋草黄','薛昭蕴','huajianji','小重山','','秋到长门秋草黄，画梁双燕去，出宫墙。
玉箫无复理霓裳，金蝉坠，鸾镜掩休妆。
忆昔在昭阳，舞衣红绶带，绣鸳鸯。
至今犹惹御炉香，魂梦断，愁听漏更长。','["1.霓裳--霓裳羽衣曲。","2.金蝉--金制蝉形头饰。","3.休妆--美好的妆饰。","4.昭阳--昭阳殿。","5.绶带--丝带。"]',''),('huajianji-140','离别难·宝马晓鞲雕鞍','薛昭蕴','huajianji','离别难','','宝马晓鞲雕鞍，罗帷乍别情难。
那堪春景媚，送君千万里。
半妆珠翠落，露华寒。
红蜡烛，青丝曲，偏能钩引泪阑干。
良夜促，香尘绿，魂欲迷，檀眉半敛愁低。
未别心先咽，欲语情难说。
出芳草，路东西。
摇袖立，春风急，樱花杨柳雨凄凄。','["1.鞲--为马备鞍辔。","2.半妆，半面妆。梁元帝瞎了一只眼睛，徐妃故意为半面妆。此处指妆饰零落。","3.青丝曲--弦歌曲。","4.阑干--纵横。","5.檀眉--香眉。"]',''),('huajianji-141','相见欢·罗襦绣袂香红','薛昭蕴','huajianji','相见欢','','罗襦绣袂香红，画堂中。
细草平沙番马，小屏风。
卷罗幕，凭妆阁，思无穷。
暮雨轻烟魂断，隔帘栊。','["1.番马--吐蕃的马。","2.帘栊--帘窗。"]',''),('huajianji-142','醉公子·慢绾青丝发','薛昭蕴','huajianji','醉公子','','慢绾青丝发，光砑吴绫袜。
床上小熏笼，韶州新退红。
叵耐无端处，捻得从头污。
恼得眼慵开，问人闲事来。','["1.绾--盘。","2.光砑--光砑：砑光，以石碾磨布帛使之密实光泽。吴绫：丝织品名。","3.熏笼--罩在熏炉上的笼子。","4.韶州--韶州：地名，今属广东省。退红：韶州所产的一种红色颜料。","5.叵耐--不可耐。"]',''),('huajianji-143','女冠子·求仙去也','薛昭蕴','huajianji','女冠子','','求仙去也，翠钿金篦尽舍，入崖峦。
雾卷黄罗帔，云雕白玉冠。
野烟溪洞冷，林月石桥寒。
静夜松风下，礼天坛。','["1.黄罗帔--黄色丝罗披肩。","2.礼天坛--登坛拜天。此为道家仪式。"]',''),('huajianji-144','女冠子·云罗雾縠','薛昭蕴','huajianji','女冠子','','云罗雾縠，新授明威法箓，降真函。
髻绾青丝发，冠抽碧玉簪。
往来云过五，去往岛经三。
正遇刘郎使，启瑶缄。','["1.云罗雾縠--丝罗织物。","2.明威法箓--明威：显赫神威。法箓：道家的图籍。","3.云过五--过五云。","4.岛经三--经三座仙岛。","5.刘郎--即传说中入天台山采药遇仙女的刘晨。参见卷第二温 庭筠《思帝乡》注。","6.启瑶城--开启使者所投的书缄。瑶缄：对来书的美称。"]',''),('huajianji-145','谒金门·春满院','薛昭蕴','huajianji','谒金门','','春满院，叠损罗衣金线。
睡觉水晶帘未卷，檐前双语燕。
斜掩金铺一扇，满地落花千片。
早是相思肠欲断，忍教频梦见。','["1.金铺--门上兽面形铜制环钮，用以衔环。","2.早是--已是。","3.教--叫，使。"]',''),('huajianji-146','柳枝·解冻风来末上青','牛峤','huajianji','柳枝','','解冻风来末上青，解垂罗袖拜卿。
无端袅娜临官路，舞送行人过一生。','["1.解冻风--解冻风：春风。末上青：杨柳末梢抽青条。","2.卿卿--男女间昵称。此处形容柳条相依偎的姿态。"]',''),('huajianji-147','柳枝·吴王宫里色偏深','牛峤','huajianji','柳枝','','吴王宫里色偏深，一簇纤条万缕金。
不愤钱塘苏小小，引郎松下结同心。','["1.不愤--不平、不服气。","2.引郎--化用古诗《苏小小歌》：何处结同心，西陵松柏下”。"]',''),('huajianji-148','柳枝·桥北桥南千万条','牛峤','huajianji','柳枝','','桥北桥南千万条，恨伊张绪不相饶。
金羁白马临风望，认得杨家静婉腰。','["1.根伊--张绪：南齐武帝曾将杨柳比张绪。不相饶：不相让。","2.金羁白马--指少年郎。","3.杨家静婉--应是羊家净婉。《南史·羊侃传》载：舞人张净婉围一尺六寸，时人咸推能掌上舞。”"]',''),('huajianji-149','柳枝·狂雪随风扑马飞','牛峤','huajianji','柳枝','','狂雪随风扑马飞，惹烟无力被春欺。
莫教移入灵和殿，宫女三千又妒伊。','["1.狂雪--这里指柳絮。","2.灵和殿--用齐武帝在灵和殿前植柳事。","3.伊--指柳树。"]',''),('huajianji-150','柳枝·袅翠笼烟拂暖波','牛峤','huajianji','柳枝','','袅翠笼烟拂暖波，舞裙新染麹尘罗。
章华台畔隋堤上，傍得春风尔许多。','["1.麹尘--深黄色，指柳色","2.章华台--相传为楚灵王离台。在今湖北沙市。","3.尔许多--如此多。"]',''),('huajianji-151','女冠子·绿云高髻','牛峤','huajianji','女冠子','','绿云高髻，点翠匀红时世。月如眉。
浅笑含双靥，低声唱小词。
眼看唯恐化，魂荡欲相随。
玉趾回娇步，约佳期。','["1.时世--时世妆，入时之妆。","2.双靥--两个酒窝。","3.化--变化成仙而去。"]',''),('huajianji-152','女冠子·锦江烟水','牛峤','huajianji','女冠子','','锦江烟水，卓女烧春浓美。小檀霞。
绣带芙蓉帐，金钗芍药花。
额黄侵腻发，臂钏透红纱。
柳暗莺啼处，认郎家。','["1.卓女烧春--卓女：本指卓文君，此处代指当垆美女 。烧春：酒名。","2.小檀霞--形容香料的烟如云霞缭绕。","3.芍药花--男女相别，送芍药以传情。","4.臂钏--镯子。"]',''),('huajianji-153','女冠子·星冠霞帔','牛峤','huajianji','女冠子','','星冠霞帔，住在蕊珠宫里。佩玎珰。
明翠摇蝉翼，纤圭理宿妆。
醮坛春草绿，药院杏花香。
青鸟传心事，寄刘郎。','["1.霞帔--华美的披肩。","2.蕊珠宫--神仙宫阙名。此处指女冠居处。","3.明翠--钗钿类饰物。","4.纤圭--指手指。","5.醮坛--道士所祀的坛场。","6.青鸟--代称信使。"]',''),('huajianji-154','女冠子·双飞双舞','牛峤','huajianji','女冠子','','双飞双舞，春昼后园莺语。卷罗帷。
锦字书封了，银河雁过迟。
鸳鸯排宝帐，豆蔻绣连枝。
不语匀珠泪，落花时。','["1.锦字书--织锦为书。此处指妻子给丈夫的信。","2.豆蔻--宝帐上绣物。豆蔻：植物名，喻少女。连枝：连理枝，喻男女爱情。"]',''),('huajianji-155','梦江南·含泥燕','牛峤','huajianji','梦江南','','含泥燕，飞到画堂前。
占得杏梁安稳处，休轻唯有主人怜，堪羡好因缘。','["1.占得--择得。"]',''),('huajianji-156','梦江南·红绣被','牛峤','huajianji','梦江南','','红绣被，两两间鸳鸯。
不是鸟中偏爱尔，为缘交颈睡南塘，全胜薄情郎。','[]',''),('huajianji-157','感恩多·两条红粉泪','牛峤','huajianji','感恩多','','两条红粉泪，多少香闺意。
强攀桃李枝，敛愁眉。
陌上莺啼蝶舞，柳花飞。
柳花飞，愿得郎心，忆家还早归。','[]',''),('huajianji-158','感恩多·自从南浦别','牛峤','huajianji','感恩多','','自从南浦别，愁见丁香结。
近来情转深，忆鸳衾。
几度将书托烟雁，泪盈襟。
泪盈襟，礼月求天，愿君知我心。','["1.丁香结--丁香的花蕾。","2.礼月--拜月。"]',''),('huajianji-159','应天长·玉楼春望晴烟灭','牛峤','huajianji','应天长','','玉楼春望晴烟灭，舞衫斜卷金条脱。
黄鹂娇啭声初歇，杏花飘尽龙山雪。
凤钗低赴节，筵上王孙愁绝。
鸳鸯对含罗结，两情深夜月。','["1.条脱--手镯。","2.龙山--在湖北江 陵县。此处泛指高山。","3.赴节--按声和节。","4.鸳鸯--指罗结上的鸳鸯花纹。"]',''),('huajianji-160','应天长·双眉淡薄藏心事','牛峤','huajianji','应天长','','双眉淡薄藏心事，清夜背灯娇又醉。
玉钗横，山枕腻，宝帐鸳鸯春睡美。
别经时，无限意，虚道相思憔悴。
莫信彩笺书里，赚人肠断字。','["1.虚道--空说。"]',''),('huajianji-161','更漏子·星渐稀','牛峤','huajianji','更漏子','','星渐稀，漏频转，何处轮台声怨。
香阁掩，杏花红，月明杨柳风。
挑锦字，记情事，惟愿两心相似。
收泪语，背灯眠，玉钗横枕边。','["1.轮台--故址在今新疆轮台县东南。此处泛指边塞。","2.挑锦字--织锦为书信。"]',''),('huajianji-162','更漏子·春夜阑','牛峤','huajianji','更漏子','','春夜阑，更漏促，金烬暗挑残烛。
惊梦断，锦屏深，两乡明月心。
闺草碧，望归客，还是不知消息。
辜负我，悔怜君，靠天天不闻。','["1.春夜阑，春夜将尽。"]',''),('huajianji-163','更漏子·南浦情','牛峤','huajianji','更漏子','','南浦情，红粉泪，怎奈两人深意。
低翠黛，卷征衣，马嘶霜叶飞。
招手别，寸肠结，还是去年时节。
书托雁，梦归家，觉来江月斜。','["1.南浦情--离别情。南浦：代指离别处。"]',''),('huajianji-164','望江怨·东风急','牛峤','huajianji','望江怨','','东风急，惜别花时手频执。
罗帷愁独入，马嘶残雨春芜湿。
倚门立，寄语薄情郎，粉香和泪泣。','["1.春芜--草名。"]',''),('huajianji-165','菩萨蛮·舞裙香暖金泥凤','牛峤','huajianji','菩萨蛮','','舞裙香暖金泥凤，画梁语燕惊残梦。
门外柳花飞，玉郎犹未归。
愁匀红粉泪，眉剪春山翠。
何处是辽阳，锦屏春昼长。','["1.金泥凤--以金粉装饰的凤形图案。","2.辽阳--地名，在今辽宁省辽阳市南。这里代指远人所在地。"]',''),('huajianji-166','菩萨蛮·柳花飞处莺声急','牛峤','huajianji','菩萨蛮','','柳花飞处莺声急，暗街春色香车立。
金凤小帘开，脸波和恨来。
今宵求梦想，难到青楼上。
赢得一场愁，鸳衾谁并头。','["1.脸波--眼波。","2.青楼 --这里指车中女子所居的楼。"]',''),('huajianji-167','菩萨蛮·玉钗风动春幡急','牛峤','huajianji','菩萨蛮','','玉钗风动春幡急，交枝红杏笼烟泣。
楼上望卿卿，窗寒新雨晴。
熏炉蒙翠被，绣帐鸳鸯睡。
何处有相知，羡他初画眉。','["1.春幡--立春日所剪的彩旗。","2.卿卿--男女间昵称。这里代指情人 。","3.画眉--用汉代张敞为妻子画眉的典故，比喻夫妻相爱。"]',''),('huajianji-168','菩萨蛮·画屏重叠巫阳翠','牛峤','huajianji','菩萨蛮','','画屏重叠巫阳翠，楚神尚有行云意。
朝暮几般心，向他情漫深。
风流今古隔，虚作瞿塘客。
山月照山花，梦回灯影斜。','["1.巫阳--巫山之阳。用楚王梦神女事。","2.楚神--也用楚王梦神女事。行云意：指男女合欢 。","3.漫--枉，徒。","4.瞿塘客--李益《江 南曲》：嫁得瞿塘客，朝朝误妾期”。瞿塘：长江 三峡之首。"]',''),('huajianji-169','菩萨蛮·风帘燕舞莺啼柳','牛峤','huajianji','菩萨蛮','','风帘燕舞莺啼柳，妆台约鬓低纤手。
钗重髻盘珊，一枝红牡丹。
门前行乐客，白马嘶春色。
故故坠金鞭，回头应眼穿。','["1.盘珊--即盘桓。发髻盘曲，称盘桓髻。","2.故故--故意，偏偏。"]',''),('huajianji-170','菩萨蛮·绿云鬓上飞金雀','牛峤','huajianji','菩萨蛮','','绿云鬓上飞金雀，愁眉敛翠春烟薄。
香阁掩芙蓉，画屏山几重。
窗寒天欲曙，犹结同心苣。
啼粉污罗衣，问郎何日归。','["1.金雀--钗饰。","2.同心苣--同心结。"]',''),('huajianji-171','菩萨蛮·玉楼冰簟鸳鸯锦','牛峤','huajianji','菩萨蛮','','玉楼冰簟鸳鸯锦，粉融香汗流山枕。
帘外辘轳声，敛眉含笑惊。
柳阴烟漠漠，低鬓蝉钗落。
须作一生拌，尽君今日欢。','["1.冰簟--凉席。","2.拌（pan1）--拼。一生拌：舍弃一生。"]',''),('huajianji-172','酒泉子·记得去年','牛峤','huajianji','酒泉子','','记得去年，烟暖杏园。
花正发，雪飘香，江草绿，柳丝长。
钿车纤手卷帘望，眉学春山样。
凤钗低袅翠鬟上，落梅妆。','["1.钿车--金玉装饰的车。","2.落梅妆--宋武帝女奉阳公主因梅花落额上，而成梅花妆。"]',''),('huajianji-173','定西番·紫塞月明千里','牛峤','huajianji','定西番','','紫塞月明千里，金甲冷，戍楼寒，梦长安。
乡思望中天阔，漏残星亦残。
画角数声呜咽，雪漫漫。','["1.紫塞--边塞。","2.金甲--金属铠甲。","3.画角--古代军乐器。"]',''),('huajianji-174','玉楼春·春入横塘摇浅浪','牛峤','huajianji','玉楼春','','春入横塘摇浅浪，花落小园空惆怅。
此情谁信为狂夫，恨翠愁红流枕上。
小玉窗前嗔燕语，红泪滴窗金线缕。
雁归不见报郎归，织成锦字封过与。','["1.恨翠愁红--恨翠：眉。愁红：泪水。","2.小玉--唐传奇中的人物霍小玉。此处泛指思妇。","3.过与--寄与。"]',''),('huajianji-175','西溪子·捍拨双盘金凤','牛峤','huajianji','西溪子','','捍拨双盘金凤，蝉鬓玉钗摇动。
画堂前，人不语，弦解语。
弹到《昭君怨》处，翠蛾愁，不抬头。','["1.捍拨--护拨的饰物。拨：拨动琵琶筝瑟弦索的器具。双盘金凤：捍拨上的涂金凤纹。","2.《昭君怨》--琵琶曲名，表达汉代王昭君的哀怨情感。"]',''),('huajianji-176','江城子·䴔䴖飞起郡城东','牛峤','huajianji','江城子','','䴔䴖飞起郡城东，碧江空，半滩风。
越王宫殿，苹叶藕花中。
帘卷水楼鱼浪起，千片雪，雨蒙蒙。','[]',''),('huajianji-177','江城子·极浦烟消水鸟飞','牛峤','huajianji','江城子','','极浦烟消水鸟飞，离筵分首时，送金卮。
渡口杨花，狂雪任风吹。
日暮天空波浪急，芳草岸，雨如丝。','["1.金卮--金樽。"]',''),('huajianji-178','浣溪沙·钿毂香车过柳堤','张泌','huajianji','浣溪沙','','钿毂香车过柳堤，桦烟分处马频嘶，为他沉醉不成泥。
花满驿亭香露细，杜鹃声断玉蟾低，含情无语倚楼西。','["1.钿毂--饰有金花的车轮圆木。","2.玉蟾--月亮。"]',''),('huajianji-179','浣溪沙·马上凝情忆旧游','张泌','huajianji','浣溪沙','','马上凝情忆旧游，照花淹竹小溪流，钿筝罗幕玉搔头。
早是出门长带月，可堪分袂又经秋，晚风斜日不胜愁。','["1.玉搔头--玉钗。","2.早是--已是。","3.分袂--离别。"]',''),('huajianji-180','浣溪沙·独立寒阶望月华','张泌','huajianji','浣溪沙','','独立寒阶望月华，露浓香泛小庭花，绣屏愁背一灯斜。
云雨自从分散后，人间无路到仙家，但凭魂梦访天涯。','[]',''),('huajianji-181','浣溪沙·依约残眉理旧黄','张泌','huajianji','浣溪沙','','依约残眉理旧黄，翠鬟抛掷一簪长，暖风晴日罢朝妆。
闲折海棠看又捻，玉纤无力惹余香，此情谁会倚斜阳。','["1.依约--依约：隐约。旧黄：残留的额黄。","2.玉纤--玉指。","3.会--理解、理会。"]',''),('huajianji-182','浣溪沙·翡翠屏开绣幄红','张泌','huajianji','浣溪沙','','翡翠屏开绣幄红，谢娥无力晓妆慵，锦帷鸳被宿香浓。
微雨小庭春寂寞，燕飞莺语隔帘栊，杏花凝恨倚东风。','["1.绣幄--绣帐。","2.谢娥--谢娘。此处为女子的泛称。"]',''),('huajianji-183','浣溪沙·枕障熏炉隔绣帷','张泌','huajianji','浣溪沙','','枕障熏炉隔绣帷，二年终日两相思，杏花明月始应知。
天上人间何处去，旧欢新梦觉来时，黄昏微雨画帘垂。','["1.枕障--枕屏。"]',''),('huajianji-184','浣溪沙·花月香寒悄夜尘','张泌','huajianji','浣溪沙','','花月香寒悄夜尘，绮筵幽会暗伤神，婵娟依约画屏人。
人不见时还暂语，令才抛后爱微颦，越罗巴锦不胜春。','["1.悄夜--静夜。","2.婵娟依约--婵娟：形态美好。依约：隐约。","3.令才--令才：美好的才华。抛：抛掷、丢弃。颦：皱眉。","4.越罗巴锦--越罗巴锦：吴越及巴蜀的罗锦。不胜春：不尽春。"]',''),('huajianji-185','浣溪沙·偏戴花冠白玉簪','张泌','huajianji','浣溪沙','','偏戴花冠白玉簪，睡容新起意沉吟，翠钿金缕镇眉心。
小槛日斜风悄悄，隔帘零落杏花阴，断香轻碧锁愁深。','["1.沉吟--犹豫不决。","2.镇眉心--压眉心。","3.断香轻碧--指零落的杏花。"]',''),('huajianji-186','浣溪沙·晚逐香车入凤城','张泌','huajianji','浣溪沙','','晚逐香车入凤城，东风斜揭绣帘轻，慢回娇眼笑盈盈。
消息未通何计是，便须佯醉且随行，依稀闻道太狂生。','["1.凤城--京城。","2.消息--音讯。此处指对车中美人的情意。","3.便须--即应。","4.太狂生--此处指车中美人嗔骂语。生：语助词，无义。"]',''),('huajianji-187','浣溪沙·小市东门欲雪天','张泌','huajianji','浣溪沙','','小市东门欲雪天，众中依约见神仙，蕊黄香画贴金蝉。
饮散黄昏人草草，醉容无语立门前，马嘶尘烘一街烟。','["1.蕊黄--蕊黄：额黄。画：点画。贴金蝉：佩带金色蝉形钗。","2.草草--匆促。","3.尘烘--尘土扬起。"]',''),('huajianji-188','临江仙·烟收湘渚秋江静','张泌','huajianji','临江仙','','烟收湘渚秋江静，蕉花露泣愁红。
五云双鹤去无踪，几回魂断，凝望向长空。
翠竹暗留珠泪怨，闲调宝瑟波中，花鬟月鬓绿云重。
古祠深殿，香冷雨和风。','["1.五云--五色祥云。","2.翠竹--用湘妃哭舜帝，泪水沾竹，竹上成斑的事。","3.闲调--用湘灵（湘水之神）鼓瑟事。","4.古祠深殿--指湘妃祠。"]',''),('huajianji-189','女冠子·露花烟草','张泌','huajianji','女冠子','','露花烟草，寂寞五云三岛，春正深。
貌减潜消玉，香残尚惹襟。
竹疏虚槛静，松密醮坛阴。
何事刘郎去，信沉沉。','["1.三岛--仙境，即三神山。","2.貌减--玉貌暗暗消减。","3.惹襟--沾染衣襟。","4.醮坛--道士行礼祭祀的坛。"]',''),('huajianji-190','河传·渺莽云水','张泌','huajianji','河传','','渺莽云水，惆怅暮帆，去程迢递。
夕阳芳草，千里万里，雁声无限起。
梦魂悄断烟波里，心如醉。
相见何处是，锦屏香冷无睡，被头多少泪。','["1.渺莽--渺茫。"]',''),('huajianji-191','河传·红杏','张泌','huajianji','河传','','红杏，交枝相映，密密蒙蒙。
一庭浓艳倚东风，香融，透帘栊。
斜阳似共春光语，蝶争舞，更引流莺妒。
魂销千片玉樽前，神仙，瑶池醉暮天。','["1.蒙蒙--密布、纷杂。"]',''),('huajianji-192','酒泉子·春雨打窗','张泌','huajianji','酒泉子','','春雨打窗，惊梦觉来天气晓。
画堂深，红焰小，背兰釭。
酒香喷鼻懒开缸，惆怅更无人共醉。
旧巢中，新燕子，语双双。','["1.背兰釭--背：熄。兰釭：用兰膏点的灯。"]',''),('huajianji-193','酒泉子·紫陌青门','张泌','huajianji','酒泉子','','紫陌青门，三十六宫春色。
御沟辇路暗相通，杏园风。
咸阳沽酒宝钗空，笑指未央归去。
插花走马落残红，月明中。','["1.紫陌--紫陌：京都郊野的道路。青门：汉长安城东南门。泛指京城城门。","2.三十六宫--形容宫殿多。","3.御沟辇路--御沟：流入宫内的河道。辇路：帝王车驾经过的路。","4.未央--汉宫殿名。","5.走马--驰马。喻疾驰。"]',''),('huajianji-194','生查子·相见稀','张泌','huajianji','生查子','','相见稀，喜相见，相见还相远。
檀画荔枝红，金蔓晴蜓软。
鱼雁疏，芳信断，花落庭阴晚。
可怜玉肌肤，消瘦成慵懒。','["1.檀画--形容画妆颜色。檀：浅红色。","2.金蔓--金质晴蜓状首饰。","3.鱼雁--古人有鱼雁传书之说。"]',''),('huajianji-195','思越人·燕双飞','张泌','huajianji','思越人','','燕双飞，莺百啭，越波堤下长桥。
斗钿花筐金匣，恰舞衣罗薄纤腰。
东风淡荡慵无力，黛眉愁聚春碧。
满地落花无消息，月明肠断空忆。','["1.斗钿花筐--妇女头饰。","2.淡荡--和舒的样子。"]',''),('huajianji-196','满宫花·花正芳','张泌','huajianji','满宫花','','花正芳，楼似绮，寂寞上阳宫里。
钿笼金销睡鸳鸯，帘冷露华珠翠。
娇艳轻盈香雪腻，细雨黄莺双起。
东风惆怅欲清明，公子桥边沉醉。','["1.上阳宫--唐宫名。遗址在今河南洛阳市。","2.香雪腻--形容佳人肌肤。"]',''),('huajianji-197','柳枝·腻粉琼妆透碧纱','张泌','huajianji','柳枝','','腻粉琼妆透碧纱，雪休夸。
金凤搔头堕鬓斜，发交加。
倚着云屏新睡觉，思梦笑。
红腮隐出枕函花，有些些。','["1.些些-些许，少许。"]',''),('huajianji-198','南歌子·柳色遮楼暗','张泌','huajianji','南歌子','','柳色遮楼暗，桐花落砌香。
画堂开处远风凉，高卷水晶帘额，衬斜阳。','["1.砌--白阶。","2.帘额--帘的高处。"]',''),('huajianji-199','南歌子·岸柳拖烟绿','张泌','huajianji','南歌子','','岸柳拖烟绿，庭花照日红。
数声蜀魄入帘栊，惊断碧窗残梦，画屏空。','["1.拖--曳引。","2.蜀魄--杜鹃鸟的别名。"]',''),('huajianji-200','南歌子·锦荐红鸂鶒','张泌','huajianji','南歌子','','锦荐红鸂鶒，罗衣绣凤凰。
绮疏飘雪北风狂，帘幕尽垂无事，郁金香。','["1.锦荐--锦荐：锦垫。红鸂鶒：绣有红色鸂鶒鸟。","2.绮疏--雕饰花纹的窗户。"]',''),('huajianji-201','江城子·碧栏干外小中庭','张泌','huajianji','江城子','','碧栏干外小中庭，雨初晴，晓莺声。
飞絮落花，时节近清明。
睡起卷帘无一事，匀面了，没心情。','["1.匀面了--画妆罢了。"]',''),('huajianji-202','江城子·浣花溪上见卿卿','张泌','huajianji','江城子','','浣花溪上见卿卿，脸波明，黛眉轻。
绿云高绾，金族小蜻蜓。
好是问他来得么？和笑道：莫多情。','["1.浣花溪--在成都市西。","2.金蝉--金制蜻蜓形状的头饰。","3.好是--最好是。","4.和笑--含笑。"]',''),('huajianji-203','河渎神·古树噪寒鸦','张泌','huajianji','河渎神','','古树噪寒鸦，满庭枫叶芦花。
昼灯当午隔轻纱，画阁珠帘影斜。
门外往来祈赛客，翩翩帆落天涯。
回首隔江烟火，渡头三两人家。','["1.轻纱--轻纱灯罩。","2.祈赛--祈服神祗。"]',''),('huajianji-204','蝴蝶儿·蝴蝶儿','张泌','huajianji','蝴蝶儿','','蝴蝶儿，晚春时，阿娇初着淡黄衣，倚窗学画伊。
还似花间见，双双对对飞。
无端和泪拭胭脂，惹教双翅垂。','["1.阿娇 --汉武帝刘彻的姑母长公主之女。此处代指美人。","2.伊--指蝴蝶。"]',''),('huajianji-205','虞美人·鸳鸯对浴银塘暖','毛文锡','huajianji','虞美人','','鸳鸯对浴银塘暖，水面蒲稍短。
垂杨低拂麴尘波，蛛丝结网露珠多，滴圆荷。
遥思桃叶吴江碧，便是天河隔。
锦鳞红鬣影沉沉，相思空有梦相寻，意难任。','["1.麴尘--淡黄色。","2.桃叶--晋王献之爱妾名。此处指所怀念的人。","3.锦鳞红鬣--彩鳞红倾的角。此处代指书信。","4.任--负担、承受。"]',''),('huajianji-206','虞美人·宝檀金缕鸳鸯枕','毛文锡','huajianji','虞美人','','宝檀金缕鸳鸯枕，绶带盘宫锦。
夕阳低映小窗明，南园绿树语莺莺，梦难成。
玉炉香暖频添炷，满地飘轻絮。
珠帘不卷度沉烟，庭前间立画秋千，艳阳天。','["1.添炷--添香炷。","2.沉烟--沉香木的烟。沉香木：可燃的香料。"]',''),('huajianji-207','酒泉子·绿树春深','毛文锡','huajianji','酒泉子','','绿树春深，燕语莺啼声断续。
蕙风飘荡入芳丛，惹残红。
柳丝无力袅烟空，金盏不辞须满酌。
海棠花下思朦胧，醉香风。','["1.蕙风--夹带花草芳香的风。","2.残红--落花。"]',''),('huajianji-208','喜迁莺·芳春景','毛文锡','huajianji','喜迁莺','','芳春景，暖晴烟，乔木见莺迁。
传枝偎叶语关关，飞过绮丛间。
锦翼鲜，金毳软，百啭千娇相唤。
碧纱窗晓怕闻声，惊破鸳鸯暖。','["1.暧--晦暗。","2.乔木--比喻登第。","3.关关--莺叫声。","4.金毳--鸟的金色腹毛。"]',''),('huajianji-209','赞成功·海棠未坼','毛文锡','huajianji','赞成功','','海棠未坼，万点深红，香包缄结一熏熏。
似含羞态，邀勒春风。
蜂来蝶去，任绕芳丛。
昨夜微雨，飘酒庭中。
忽闻声滴井边桐，美人惊起，坐听晨钟。
快教折取，戴玉璁。','["1.坼--开。","2.香包缄结--香包：花苞。缄结：封闭。","3.邀勒--强求，逼迫。","4.玉珑璁--首饰。"]',''),('huajianji-210','西溪子·昨日西溪游赏','毛文锡','huajianji','西溪子','','昨日西溪游赏，芳树奇花千样，锁春光。
金樽满，听弦管，娇妓舞衫香暖。
不觉到斜晖，马驮归。
中兴乐
豆蔻花繁烟艳深，丁香软结同心。
翠鬟女，相与共淘金。
红蕉叶里猩猩语，鸳鸯浦，镜中鸾舞。
丝雨隔，荔枝阴。','["1.淘金--用水冲刷含金的沙子，选出沙金。","2.红蕉--红蕉：芭蕉。猩猩语：猩猩叫声如小儿啼，古人传其能说话。"]',''),('huajianji-211','更漏子·春夜阑','毛文锡','huajianji','更漏子','','春夜阑，春恨切，花外子规啼月。
人不见，梦难见，红纱一点灯。
偏怨别，是芳节，庭中丁香千结。
宵雾散，晓霞晖，梁同双燕飞。','["1.春夜阑--春夜将尽。","2.一点灯--一盏灯。"]',''),('huajianji-212','接贤宾·香鞯镂襜五花骢','毛文锡','huajianji','接贤宾','','香鞯镂襜五花骢，值春景初融。
流珠喷沫躞蹀，汗血流红。
少年公子能乘驭，金镳玉辔珑璁。
为惜珊瑚鞭不下，骄生百步千踪。
信穿花，从拂柳，向九陌追风。','["1.香鞯镂襜--鞯(jian4）,襜（chan2）,马鞍具。","2.流珠--流珠喷沫：马喷涌唾沫。躞蹀（xie4 die2）：马行走的样子。","3.汗血流红--马汗颜色如血。","4.金镳--金镳：饰金的马嚼子。珑璁：光洁的样子。","5.珊瑚鞭--华贵的马鞭。","6.信--信马，任马奔驰。","7.九陌--都城中的大道。"]',''),('huajianji-213','赞浦子·锦帐添香睡','毛文锡','huajianji','赞浦子','','锦帐添香睡，金炉换夕照。
懒结芙蓉带，慵拖翡翠裙。
正是桃夭柳媚，那堪暮雨朝云。
宋玉高唐意，裁琼欲赠君。','["1.桃夭柳媚--桃花艳丽、杨柳妩媚。比喻妙龄女子。","2.暮雨朝云--用宋玉《高唐赋》中巫山神女旦为朝云，暮为行雨”的典故。","3.琼--琼瑶，代指情书。"]',''),('huajianji-214','甘州遍·春光好','毛文锡','huajianji','甘州遍','','春光好，公子爱闲游，足风流。
金鞍白马，雕弓宝剑，红缨锦襜出长揪。
花蔽膝，玉衔头。
寻芳逐胜欢宴，丝竹不曾休。
美人唱，揭调是《甘州》。醉红楼。
尧年舜日，乐圣永无忧。','["1.红缨--红缨：马缰绳。锦襜--马鞍垫。长揪：有楸树的大道，代指大路。","2.蔽膝--护膝的围裙。","3.玉衔头--玉饰的马嚼子。","4.揭调--揭调：高调。《甘州》：唐教坊曲名。","5.尧年舜日--比喻太平盛世。","6.乐圣--古人称嗜酒为乐圣。此处指饮酒。"]',''),('huajianji-215','甘州遍·秋风紧','毛文锡','huajianji','甘州遍','','秋风紧，平碛雁行低，阵云齐。
萧萧飒飒，边声四起，愁闻戍角与征鼙。
青冢北，黑山西。
沙飞聚散无定，往往路人迷。
铁衣冷，战马血沾蹄，破番奚。
凤凰诏下，步步蹑丹梯。','["1.平碛--沙漠。","2.萧萧飒飒--语出屈原《九歌·山鬼》：风飒飒兮木萧萧”。萧萧：摇动的样子。飒飒：风声。","3.征鼙--战鼓。","4.青冢--王昭君墓。相传冢上草色常青，故名。在今内蒙古呼和浩物市南。","5.黑山--在今内蒙古包头市西北。","6.番奚--匈奴的别种。","7.凤凰诏--皇帝诏书。","8.丹梯--宫殿的台阶。"]',''),('huajianji-216','纱窗恨·新春燕子还来至','毛文锡','huajianji','纱窗恨','','新春燕子还来至，一双飞。
垒巢泥湿时时坠，涴人衣。
后园里看百花发，香风拂，绣户金扉。
月照纱窗，恨依依。','["1.涴--弄脏。"]',''),('huajianji-217','纱窗恨·双双蝶翅涂铅粉','毛文锡','huajianji','纱窗恨','','双双蝶翅涂铅粉，咂花心。
绮窗绣户飞来稳，画堂阴。
二三月爱随飘絮，伴落花，来拂衣襟。
更剪轻罗片，傅黄金。','["1.铅粉--涂面的化妆品。","2.咂花心--吮花蕊。","3.轻罗片--形容蝶翅轻薄。","4.傅黄金--敷黄金，形容蝶翅的颜色。"]',''),('huajianji-218','柳含烟·隋堤柳','毛文锡','huajianji','柳含烟','','隋堤柳，汴河旁。
夹岸绿阴千里，龙舟凤舸木兰香，锦帆张。
因梦江南春景好，一路流苏羽葆。
笙歌未尽起横流，锁春愁。','["1.汴河--即汴水，又名通济渠。隋炀帝游江 都经此道，今久废。","2.龙舟--隋炀帝所乘木兰树制成的龙舟、凤舸。","3.锦帆--锦制的船帆。","4.流苏羽葆--皇帝仅仗中车马的装饰。流苏：五彩羽毛制成的穗子。羽葆盖。车上以鸟羽连缀作为装饰的华盖。","5.起横流--发生变故。即隋亡。"]',''),('huajianji-219','柳含烟·河桥柳','毛文锡','huajianji','柳含烟','','河桥柳，占芳春。
映水含烟拂路，几回攀折赠行人，暗伤神。
乐府吹为横笛曲，能使离肠断续。
不如移植在金门，近天恩。','["1.乐府--指乐府横吹曲辞中的《折杨柳》曲。","2.移植在金门--用唐宣宗取永丰坊垂柳植于禁中的事。金门：金马门，代指皇宫。"]',''),('huajianji-220','柳含烟·章台柳','毛文锡','huajianji','柳含烟','','章台柳，近垂旒。
低拂往来冠盖，鞭胧春色满皇州，瑞烟浮。
直与路边江畔别，免被离人攀折。
最怜京兆画蛾眉，叶纤时。','["1.章台柳--汉代长安章台街所植的柳树。","2.垂旒--帝王冠冕上的装饰，用丝绳系玉下垂。","3.冠盖--官吏的服饰和车乘，借指官吏。","4.皇州--京城。","5.瑞烟--祥瑞的烟。","6.直--即使。","7.京兆画蛾眉--用汉京兆尹张敞为其妻画眉事，形容柳叶纤细如眉。"]',''),('huajianji-221','柳含烟·御沟柳','毛文锡','huajianji','柳含烟','','御沟柳，占春多。
半出宫墙婀娜，有时倒影蘸轻罗，麴尘波。
昨日金銮巡上苑，风亚舞腰纤软。
栽培得她近皇宫，瑞烟浓。','["1.婀娜--摇曳的样子。","2.有时--蘸（zhan4）：浸入。轻罗：形容柳条。","3.麴尘--淡黄色。","4.昨日--金銮：金銮殿。此处代指皇帝。上苑：皇帝的庭苑。","5.风亚--风亚：风压。舞腰：形容柳条。"]',''),('huajianji-222','醉花间·休相问','毛文锡','huajianji','醉花间','','休相问，怕相问，相问还添恨。
春水满塘生，鸂鶒正相趁。
咋夜雨霏霏，临明寒一阵。
偏忆戍楼人，久绝边庭信。','["1.相趁--相宜。","2.边庭--边塞。"]',''),('huajianji-223','醉花间·深相忆','毛文锡','huajianji','醉花间','','深相忆，莫相忆，相忆情难极。
银汉是红墙，一带遥相隔。
金盘珠露滴，两岸榆花白。
风摇玉佩清，今夕为何夕。','["1.银汉--银河。","2.一带--银河如一衣带水，隔断鹊桥路。","3.金盘--承露盘。"]',''),('huajianji-224','浣沙溪·春水轻波浸绿苔','毛文锡','huajianji','浣沙溪','','春水轻波浸绿苔，楷杷洲上紫檀开。
晴天眠沙鸂鶒稳，暖相偎。
罗袜生尘游女过，有人逢着弄珠回。
兰麝飘香初解佩，忘归来。','["1.罗袜生尘--曹植《洛神赋》：凌波微步，罗袜生尘”。","2.解佩--即解佩”。《列仙传》云：江 妃二女曾解下佩玉，赠与郑交甫。","3.弄珠--即玉珠。"]',''),('huajianji-225','浣溪沙·七夕年年信不违','毛文锡','huajianji','浣溪沙','','七夕年年信不违，银河清浅白云微，蟾光鹊影伯劳飞。
每恨蟪蛄怜婺女，几回娇妒下鸳机，今宵嘉会两依依。','["1.七夕--农历七月初七夜。民间传说牛郎织女此夜在天河相会。","2.蟾光--蟾光：月光。鹊影：鹊为桥，故写鹊影。伯劳：鸟名。","3.蟪蛄--蟪蛄：蝉的一种，秋日悲鸣。婺女：星名，二十八宿之一，代指织女。"]',''),('huajianji-226','月宫春·水晶宫里桂花开','毛文锡','huajianji','月宫春','','水晶宫里桂花开，神仙探几回。
红芳金蕊绣重台，低倾玛瑙杯。
玉兔银蟾争夺护，嫦娥姹女戏相偎。
遥听钧天九奏，玉皇亲看来。','["1.水晶--水晶宫，月宫。传说月中有桂树。","2.重台--花的复瓣。","3.玉兔银蟾--传说月中有玉兔、有银蟾蜍。","4.姹女--这里指月中美女 。","5.钧天九奏--天上仙乐。钧天：上帝所居。九奏：奏乐九曲。","6.玉皇--玉皇大帝，道教中最大的神。"]',''),('huajianji-227','恋情深·滴滴铜壶塞漏咽','毛文锡','huajianji','恋情深','','滴滴铜壶塞漏咽，醉红楼月。
宴余香殿会鸳衾，荡春心。
真珠帘下晓光侵，莺语隔琼林。
宝帐欲开慵起，恋情深。','["1.真珠帘--珍珠穿成的帘子。","2.琼林--树木的美称。"]',''),('huajianji-228','恋情深·玉殿春浓花烂熳','毛文锡','huajianji','恋情深','','玉殿春浓花烂熳，族神仙伴。
罗裙窣地缕黄金，奏清音。
酒阑歌罢两沉沉，一笑动君心。
永作鸳鸯伴，恋情深。','["1.窣地--拂地。","2.酒阑--酒残。"]',''),('huajianji-229','诉衷情·桃花流水漾纵横','毛文锡','huajianji','诉衷情','','桃花流水漾纵横，春昼彩霞明。
刘郎去，阮郎行，惆怅恨难平。
愁坐对云屏，算归程。
何时携手洞边迎，诉衷情。','["1.此词咏东汉刘晨、阮美人天台山采药遇仙女事。","2.纵横--桃花相交 。","3.刘晨、阮肇在天台山遇仙女的桃源洞。"]',''),('huajianji-230','诉衷情·鸳鸯交颈绣衣轻','毛文锡','huajianji','诉衷情','','鸳鸯交颈绣衣轻，碧沼藕花馨。
偎藻荇，映兰汀，和雨浴浮萍。
思妇对心惊，想边庭。何时解佩掩云屏，诉衷情。','["1.绣衣轻--形容鸳鸯羽翼。","2.藻荇--水生植物。","3.兰汀--有兰花的水边平地。","4.解佩--此处指征人解佩，比喻征人回归。"]',''),('huajianji-231','应天长·平江波暖鸳鸯语','毛文锡','huajianji','应天长','','平江波暖鸳鸯语，两两镏般归极浦。
芦州一夜风和雨，飞起浅沙翘雪鹭。
渔灯明远渚，兰棹今宵何处。
罗袂从风轻举，愁杀采莲女。','["1.雪鹭--白鹭。","2.罗袂--罗袖。","3.愁杀--愁煞，愁极。"]',''),('huajianji-232','河满子·红粉楼前月照','毛文锡','huajianji','河满子','','红粉楼前月照，碧纱窗外莺啼。
梦断辽阳音信，那堪独守空闺。
恨对百花时节，王孙绿草萋萋。','["1.红粉楼--妇女妆楼。","2.辽阳--这里代指征人所在地。","3.王孙--《楚辞·招隐士》：王孙游兮不归，春草生兮萋萋。”王孙：代指游子。萋萋：草木茂盛的样子。巫山一段云雨霁巫山上，云轻映碧天。远峰吹散又相连，十二晚峰前。暗湿啼猿树，高笼过客船。朝朝暮暮楚江 边，几度降神仙。","1.朝朝--用宋玉《高唐赋》序中楚王梦神女事。"]',''),('huajianji-233','临江仙·暮蝉声尽落斜阳','毛文锡','huajianji','临江仙','','暮蝉声尽落斜阳，银蟾影挂潇湘。
黄陵庙侧水茫茫。楚山红树，烟雨隔高唐。
岸泊渔灯风飐碎，白苹远散浓香。
灵娥鼓瑟韵清商，朱弦凄切，云散碧云长。','["1.银蟾--月亮。","2.黄陵庙--在今湖南湘阴县北湘水入洞庭湖处,祠舜之二妃娥皇、女英。","3.灵娥--灵娥，即湘灵、湘水女神。《楚辞·远游》有使湘灵鼓瑟兮。清商：古五音之一。商声。"]',''),('huajianji-234','临江仙·峭碧参差十二峰','牛希济','huajianji','临江仙','','峭碧参差十二峰，冷烟寒树重重。
瑶姬宫殿是仙踪，金炉珠帐，香霭昼偏浓。
一自楚王惊梦断，人间无路相逢。
至今云雨带愁容，月斜江上，征棹动晨钟。','["1.瑶姬--神女。","2.一自--用宋玉《高唐赋》中楚王梦神女事。"]',''),('huajianji-235','临江仙·谢家仙观寄云岑','牛希济','huajianji','临江仙','','谢家仙观寄云岑，岩萝拂地成阴。
洞房不闭白云深，当时丹灶，一粒化黄金。
石壁霞衣犹半挂，松风长似鸣琴。
时间唳鹤起前林，十洲高会，何处许相寻？','["1.谢家--谢家仙观：谢女峡。在今广东省中山县境海中。相传为谢女得道地。云岑：山的高峰。","2.丹灶--谢女炼丹的炉灶。","3.一粒化黄金--丹砂化为一粒黄金。","4.十洲--海中仙境。"]',''),('huajianji-236','临江仙·渭阙宫城秦树凋','牛希济','huajianji','临江仙','','渭阙宫城秦树凋，玉楼独上无聊。
含情不语自吹箫，调情和恨，天路逐风飘。
何事乘龙入忽降，似知深意相招。
三清携手路非遥，世间屏障，彩笔画娇娆。','["1.渭阙宫城--秦的宫城，因地近渭水，故称。","2.乘龙入忽降--用《列仙传》春秋时入萧史善吹箫，作凤鸣。一夕吹箫引凤。萧史乘龙，与秦穆公女弄玉乘凤升天而去的事。","3.三清--仙人所居地。","4.屏障--屏风。","5.娇娆--美人。指弄玉。"]',''),('huajianji-237','临江仙·江绕黄陵春庙闲','牛希济','huajianji','临江仙','','江绕黄陵春庙闲，娇莺独语关关。
满庭重叠绿苔斑，阴云无事，四散自归山。
箫鼓声稀香烬冷，月娥敛尽弯环。
风流皆道胜人间，须知狂客，拼死为红颜。','["1.黄陵春庙--即黄陵庙。此词咏湘妃。"]',''),('huajianji-238','临江仙·素洛春光潋滟平','牛希济','huajianji','临江仙','','素洛春光潋滟平，千重媚脸初生。
凌波罗袜势轻轻，烟笼日照，珠翠半分明。
风引宝衣疑欲舞，鸾回凤翥堪惊。
也知心许无恐成，陈王辞赋，千载有声名。','["1.素洛--素洛：清澄的洛水。潋滟：水波摇荡。","2.凌波--洛神步履轻盈。语出曹植《洛神赋》：凌波微步，罗袜生尘”。","3.陈王辞赋--陈思王曹植作《洛神赋》。"]',''),('huajianji-239','临江仙·柳带摇风汉水滨','牛希济','huajianji','临江仙','','柳带摇风汉水滨，平芜两岸争匀。
鸳鸯对浴浪痕新。弄珠游女，微笑自含春。
轻步暗移蝉鬓动，罗裙风惹轻尘。
水晶宫殿岂无因？空劳牵手，解佩赠情人。','["1.弄珠游女--用《列仙传》中江 妃二女逢郑交 甫，解佩玉赠关交 甫事。","2.水晶宫殿--神女所居处。","3.情人 --指郑交 甫。"]',''),('huajianji-240','临江仙·洞庭波浪飐晴天','牛希济','huajianji','临江仙','','洞庭波浪飐晴天，君山一点凝烟。
此中真境属神仙，玉楼珠殿，相映月轮边。
万里平湖秋色冷，星辰垂影参然。
桔林霜重更红鲜，罗浮山下，有路暗相连。','["1.洞庭--洞庭湖。","2.君山--洞庭山，在洞庭湖中。","3.此中--《拾遗记》卷十《洞庭山》：洞庭山浮于水上，其下有金堂数百间，帝女居之。”","4.参然--参差不齐。","5.罗浮山--传说中的仙山。在广东省增城、博罗、河源等县间。","6.有路--用谢灵运《罗浮山赋序》关于洞庭与罗浮山相连的记载。"]',''),('huajianji-241','酒泉子·枕转簟凉','牛希济','huajianji','酒泉子','','枕转簟凉，清晓远钟残梦。
月光斜、帘影动，旧炉香。
梦中说尽相思事，纤手匀双泪。
去年春，今日意，断离肠。','[]',''),('huajianji-242','生查子·春山烟欲收','牛希济','huajianji','生查子','','春山烟欲收，天淡稀星小。
残月脸边明，别泪临清晓。
语已多，情未了，回首犹重道：
记得绿罗裙，处处怜芳草。','["1.重道--再次说。","2.记得--因芳草与罗裙同色，故因物及人。"]',''),('huajianji-243','中兴乐·池塘暖碧浸晴晖','牛希济','huajianji','中兴乐','','池塘暖碧浸晴晖，蒙蒙柳絮轻飞。
红蕊凋来，解梦还稀。
春云空有雁归，珠帘垂。
东风寂寞，恨郎抛掷，泪湿罗衣。','[]',''),('huajianji-244','谒金门·秋已暮','牛希济','huajianji','谒金门','','秋已暮，重叠关山岐路。
嘶马摇鞭何处去，晓禽霜满树。
梦断禁城神鼓，泪滴枕檀无数。
一点凝红和薄雾，翠蛾愁不语。','["1.枕檀--檀木枕。","2.翠蛾--美人的眉毛。此处指思妇。"]',''),('huajianji-245','浣溪沙·落絮残莺半日天','欧阳炯','huajianji','浣溪沙','','落絮残莺半日天，玉柔花醉只思眠，惹窗映竹满炉烟。
独掩画屏愁不语，斜掩瑶枕髻鬟偏，此时心在阿谁边。','["1.阿谁--谁。"]',''),('huajianji-246','浣溪沙·天碧罗衣拂地垂','欧阳炯','huajianji','浣溪沙','','天碧罗衣拂地垂，美人初着更相宜，宛风如舞透香肌。
独坐含颦吹风竹，园中缓步折花枝，有情无力泥人时。','["1.宛风--柔风。","2.泥人--这里指人醉如泥。"]',''),('huajianji-247','浣溪沙·相见休言有泪珠','欧阳炯','huajianji','浣溪沙','','相见休言有泪珠，酒阑重得叙欢娱，凤屏鸳枕宿金铺。
兰麝细香闻喘息，绮罗纤缕见肌肤，此时还恨薄情无。','["1.金铺--门上铺首，用以衔环。此处代指闺房。"]',''),('huajianji-248','三字令·春欲尽','欧阳炯','huajianji','三字令','','春欲尽，日迟迟，牡丹时。
罗幌卷，翠帘垂。
彩笺书，红粉泪，两心知。
人不在，燕空归，负佳期。
香烬落，枕函欹。
月分明，花淡薄，惹相思。','["1.罗幌--丝织帷幌。","2.枕函欹--枕头倾斜。欹（qi1）:倾斜。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('huajianji-249','南乡子·嫩草如烟','欧阳炯','huajianji','南乡子','','嫩草如烟，石榴花发海南天。
日暮江亭春影绿，鸳鸯浴。
水远山长看不足。','[]',''),('huajianji-250','南乡子·画舸停桡','欧阳炯','huajianji','南乡子','','画舸停桡，槿花篱外竹横桥。
水上游人沙上女，回顾，笑指芭蕉林里住。','["1.停桡--停桨，停船。"]',''),('huajianji-251','南乡子·岸远沙平','欧阳炯','huajianji','南乡子','','岸远沙平，日斜归路晚霞明。
孔雀自怜金翠尾，临水，认得行人惊不起。','[]',''),('huajianji-252','南乡子·洞口谁家','欧阳炯','huajianji','南乡子','','洞口谁家，木兰船系木兰花。
红袖女郎相引去，游南浦，笑倚春风相对语。','["1.相引去--相约去。"]',''),('huajianji-253','南乡子·二八花钿','欧阳炯','huajianji','南乡子','','二八花钿，胸前如雪脸如莲。
耳坠金环穿瑟瑟，霞衣窄，笑倚江头招远客。','["1.二八花钿--代指少女。二八：十六岁。","2.瑟瑟--绿宝石。"]',''),('huajianji-254','南乡子·路入南中','欧阳炯','huajianji','南乡子','','路入南中，桃榔叶暗蓼花红。
两岸人家微雨后，收红豆，树底纤纤抬素手。','["1.南中--南国。","2.桃榔--树名。常绿树。"]',''),('huajianji-255','南乡子·袖敛鲛绡','欧阳炯','huajianji','南乡子','','袖敛鲛绡，采香深洞笑相邀。
藤杖枝头芦酒滴，铺葵席，豆蔻花间趖晚日。','["1.鲛绡--相传为鲛人所织的绡。此处指手帕。","2.趖晚日--指太阳跌落。趁：走。"]',''),('huajianji-256','南乡子·翡翠䴔䴖','欧阳炯','huajianji','南乡子','','翡翠䴔䴖，白萍香里小沙汀。
岛上阴阴秋雨色，芦花扑，数只渔船何处宿。','[]',''),('huajianji-257','献衷心·见好花颜色','欧阳炯','huajianji','献衷心','','见好花颜色，争笑东风。
双脸上，晚妆同。
闭小楼深阁，春景重重。
三五夜，偏有恨，月明中。
情未已，信曾通，满衣犹自染檀红。
恨不如双燕，飞舞帘栊。
春欲暮，残絮尽，柳条空。','["1.三五夜--农历十五日夜。"]',''),('huajianji-258','贺明朝·忆昔花间初识面','欧阳炯','huajianji','贺明朝','','忆昔花间初识面，红袖半遮妆脸。
轻转石榴裙带，故将纤纤玉指，愉捻双凤金线。
碧梧桐锁深深院，谁料得，两情何日教缱绻。
羡春来双燕，飞到玉楼，朝暮相见。','["1.缱绻--牢结，不离散。"]',''),('huajianji-259','贺明朝·忆昔花间相见后','欧阳炯','huajianji','贺明朝','','忆昔花间相见后，只凭纤手，暗抛红豆。
人前不解，巧传心事。
别来依旧，辜负春昼。
碧罗衣上蹙金绣，睹对对鸳鸯，空裛泪痕透。
想韶颜非久，终是为伊，只恁偷瘦。','["1.暗抛红豆--暗中抛掷红豆，以表相思情。","2.蹙金绣--用金丝银线剌绣成绉纹状。","3.裛--沾。","4.韶颜--美好容颜。","5.只恁--竟然如此。"]',''),('huajianji-260','江城子·晚日金陵岸草平','欧阳炯','huajianji','江城子','','晚日金陵岸草平，落霞明，水无情，六代繁华，暗逐逝波声。
空有姑苏台上月，如西子镜照江城。','["1.金陵--今南京。","2.六代繁华--东吴、东晋、宋、齐、梁、陈都定都在金陵。","3.姑苏繁华--在今江 苏苏州市西南姑苏山上，为春秋时吴国修筑。","4.江 城--指金陵。"]',''),('huajianji-261','凤楼春·凤髻绿云丛','欧阳炯','huajianji','凤楼春','','凤髻绿云丛，深掩房栊。
锦书通，梦中相见觉来慵，匀面泪脸珠融。
因想玉郎何处去，对淑景谁同。
小楼中，春思无穷。
倚栏颙望，暗牵愁绪，柳花飞起东风。
斜日照帘，罗幌香冷粉屏空。
海棠零落，莺语残红。','["1.绿云丛--发丛。","2.淑景--美景。","3.颙望--仰头远望。"]',''),('huajianji-262','小重山·春入神京万木芳','和凝','huajianji','小重山','','春入神京万木芳，禁林莺语滑，蝶飞狂。
晓花擎露妨啼妆，红日水，风和百花香。
烟锁柳丝长，御沟澄碧水，转池塘。
时时微雨洗劫风光，天衢远，到处引笙簧。','["1.神京--帝都。","2.禁林--禁林：禁苑的园林。莺语滑：莺叫声流利。","3.啼妆--妇女以粉薄拭目下，好像啼痕。","4.天衢--通往京师的路。","5.笙簧--竹制乐器。"]',''),('huajianji-263','小重山·正是神京烂熳时','和凝','huajianji','小重山','','正是神京烂熳时，群仙初折得，郄诜枝。
乌犀白纻最相宜，精神出，御陌袖鞭垂。
柳色展愁眉，管弦分响亮，探花期。
光阴占断曲江池，新榜上，名姓彻丹墀。','["1.郄诜枝--事见《晋书·郄诜传》。郄诜自称：臣举贤良对箫，为天下第一，犹桂林第一，昆山之片玉。”此处指科举及第，即折桂。","2.乌犀白纻--乌犀：黑犀，装饰物。白纻--白布衣服。","3.探花期--指进士初宴的时间。唐时进士在曲江 、杏园初宴，称探花宴，以进士少俊者二人为探花使。","4.丹墀--漆成红色的石阶，代指皇宫。"]',''),('huajianji-264','临江仙·海棠香老春江晚','和凝','huajianji','临江仙','','海棠香老春江晚，小楼雾縠涳蒙。
翠鬟初出绣帘中，麝烟鸾鬟苹风。
碾玉钗摇鸂鶒战，雪肌云鬓将融。
含情遥指碧波东，越王台殿蓼花红。','["1.雾縠--原指如薄雾的轻纱，此处指薄如轻纱的云雾。","2.苹风--微风。","3.鸂鶒战--鸂鶒鸟形首饰在头上颤动。战：通颤”。"]',''),('huajianji-265','临江仙·披袍窣地红宫锦','和凝','huajianji','临江仙','','披袍窣地红宫锦，莺语时啭轻音。
碧罗冠子稳犀簪，凤凰双飐步摇金。
肌骨细匀红玉软，脸波微送春心。
娇羞不肯入鸳衾，兰膏光里两情深。','["1.犀簪--犀角制的发簪。","2.步摇金--黄金制的步摇首饰。","3.兰膏--代指兰灯。"]',''),('huajianji-266','菩萨蛮·越梅半坼轻寒里','和凝','huajianji','菩萨蛮','','越梅半坼轻寒里，冰清淡薄笼蓝水。
暖觉杏梢红，游丝狂惹风。
闲阶莎径碧，远梦犹堪惜。
离恨又迎春，相思难重陈。','["1.蓝水--水名，源出陕西蓝田东蓝田谷。","2.莎（suo1）径碧--长着绿色莎草的小径。"]',''),('huajianji-267','山花子·莺锦蝉縠馥麝脐','和凝','huajianji','山花子','','莺锦蝉縠馥麝脐，轻裾花早晓烟迷。
鸂鶒战金红掌坠，翠云低。
星靥笑偎霞脸畔，蹙金开襜衬银泥。
春思半和芳草嫩，碧萋萋。','["1.莺锦--蝉縠：薄如蝉翼的轻纱。麝脐：即麝香。","2.轻裾--轻袖。","3.鸂鶒--鸂鶒形的饰物。","4.星靥--即黄星靥、一种面妆。","5.蹙金--蹙金开襜：用金丝线剌绣成绉纹状的一种短裙。银泥：裙饰。"]',''),('huajianji-268','山花子·银字笙寒调正长','和凝','huajianji','山花子','','银字笙寒调正长，水纹簟冷画屏凉。
玉腕重金扼臂，淡梳妆。
几度试香纤手暖，一回尝酒绛唇光。
佯弄红丝蝇拂子，打檀郎。','["1.银字笙--乐器。用银作字，标明音色高低。","2.水纹簟--水纹竹席。","3.扼臂--约臂。","4.蝇拂子--拂蝇用具。","5.檀郎--代称美男子。"]',''),('huajianji-269','河满子·正是破瓜年几','和凝','huajianji','河满子','','正是破瓜年几，含情惯得人饶。
桃李精神鹦鹉舌，可堪虚度良宵。
却爱蓝罗裙子，羡他长束纤腰。','["1.破瓜年几--十六岁年龄。","2.含情--惯：纵容。得：语助辞。人饶：要人相让，宽恕。"]',''),('huajianji-270','河满子·写得鱼笺无限','和凝','huajianji','河满子','','写得鱼笺无限，其如花锁春晖。
目断巫山云雨，空教残梦依依。
却爱熏香小鸭，羡他长在屏帷。','["1.鱼笺--蜀地的笺。这里代指情书。","2.熏香小鸭--鸭形小香炉。"]',''),('huajianji-271','薄命女·天欲晓','和凝','huajianji','薄命女','','天欲晓，宫漏穿花声缭绕。
窗里星光少，冷霞寒侵帐额，残月光沉树杪。
梦断锦帷空悄悄，强起愁眉小。','["1.树杪--树梢。"]',''),('huajianji-272','望梅花·春草全无消息','和凝','huajianji','望梅花','','春草全无消息，腊雪犹余踪迹。
越岭寒枝香自坼，冷艳奇芳堪惜。
何事寿阳无处觅，吹入谁家横笛。','["1.越岭--越城岭。在今广西金州、资源等县之间。","2.寿阳--宋武帝女寿阳公主。此用其梅妆事。","3.横笛--横笛曲。此指《梅花落》。"]',''),('huajianji-273','天仙子·柳色披衫金缕凤','和凝','huajianji','天仙子','','柳色披衫金缕凤，纤手轻拈红豆弄，翠蛾双敛正含情。
桃花洞，瑶台梦，一片春愁谁与共。','["1.桃花洞--刘晨、阮肇在天台山采药遇仙女的地方。","2.瑶台梦--梦入仙境。瑶台：神话中神仙居信的地方，以玉色玉为台基。"]',''),('huajianji-274','天仙子·洞口春红飞蔌蔌','和凝','huajianji','天仙子','','洞口春红飞蔌蔌，仙子含愁眉黛绿。
阮郎何事不归来，懒烧金，慵篆玉。
流水桃花空断续。','["1.洞口--洞口：此处指桃花洞。蔌蔌：象声词。此处指风吹落花声。","2.烧金--焚香于炉。","3.篆玉--盘香。这里代指焚香。"]',''),('huajianji-275','春光好·纱窗暖','和凝','huajianji','春光好','','纱窗暖，画屏间，亸云鬟。
睡起四肢无力，半春闲。
玉指剪裁罗胜，金盘点缀酥山。
窥宋深心无限事，小眉弯。','["1.亸云鬟--发鬟下垂。","2.罗胜--绮罗所做的饰物。","3.酥山--酥酷堆积如山形。","4.窥宋--窥视宋玉。事见宋玉《登徒子好色赋》。此处指窥视情郎。"]',''),('huajianji-276','春光好·苹叶软','和凝','huajianji','春光好','','苹叶软，杏花明，画船轻。
双浴鸳鸯出绿汀，棹歌声。
春水无风无浪，春天半雨半晴。
红粉相随南浦晚，几含情。','["1.棹歌声--船家所唱歌声。"]',''),('huajianji-277','采桑子·蝤蛴领上诃梨子','和凝','huajianji','采桑子','','蝤蛴领上诃梨子，绣带双垂，椒户闲时，竞学樗蒲赌荔枝。
丛头鞋子红编细，裙窣金丝。
无事颦眉，春思翻教阿母疑。','["1.蝤蛴--蝤蛴：天牛、桑牛的幼虫，因色白丰洁而长，古时用以比喻妇女的颈，此处指妇女衣领。诃梨子：本名诃梨勒，天竺果名。此处指妇女衣领上所绣的花饰。","2.椒户--椒泥涂饰的屋子。","3.樗蒲--古代赌博 游戏。","4.丛头--丛头鞋子：鞋头如花丛状。红编：红色鞋带。","5.翻教--反使。"]',''),('huajianji-278','柳枝·软碧瑶烟似送人','和凝','huajianji','柳枝','','软碧瑶烟似送人，映花时把翠蛾颦。
青青自是风流主，慢飐金丝待洛神。','["1.青青--形容柳树。《南史·张绪传》：南朝齐武帝曾称赞太昌灵和殿的柳说：“此杨柳风流 可爱，似张绪当年时”。张绪（422-489）风姿美，故称“风流 主”。","2.洛神--洛水女神。"]',''),('huajianji-279','柳枝·瑟瑟罗裙金缕腰','和凝','huajianji','柳枝','','瑟瑟罗裙金缕腰，黛眉偎破未重描。
醉来咬损新花子，拽住仙郎尽放娇。','["1.瑟瑟--象声词。","2.花子--画饰。"]',''),('huajianji-280','柳枝·雀桥初就咽银河','和凝','huajianji','柳枝','','雀桥初就咽银河，今夜仙郎自姓和。
不是昔年攀桂树，岂能月里索嫦娥。','["1.自姓和--和凝自称。","2.攀桂树--即折桂，比喻科举中第。"]',''),('huajianji-281','渔父·白芷汀寒立鹭鸶','和凝','huajianji','渔父','','白芷汀寒立鹭鸶，苹风轻剪浪花时。
烟幂幂，日迟迟。
香引芙蓉惹钓丝。','["1.白芷汀--长满白芷草的水边平地。","2.苹风--微风。","3.幂幂--覆盖的样子。","4.芙蓉--荷花。"]',''),('huajianji-282','虞美人·晓莺啼破相思梦','顾敻','huajianji','虞美人','','晓莺啼破相思梦，帘看金泥凤。
宿妆犹在酒初醒，翠翘慵整倚云屏，转娉婷。
香檀细画侵桃脸，罗袂轻轻敛。
佳期堪恨再难寻，绿芜满院柳成阴，负春心。','["1.金泥凤--帘上金粉所饰的凤形花纹。","2.香檀--浅红色化妆品。","3.绿芜--绿色杂草。"]',''),('huajianji-283','虞美人·触帘风送景阳钟','顾敻','huajianji','虞美人','','触帘风送景阳钟，鸳被绣花重。
晓帷初卷冷烟浓，翠匀粉黛好仪容，思娇慵。
起来无语理朝妆，宝匣镜凝光。
绿荷相倚满池塘，露清枕簟藕花香，恨悠扬。','["1.景阳钟--南齐武帝以宫深不闻端门鼓漏声，置钟于景和殿上。宫人闻钟声，早起妆饰。","2.粉黛--妇女化妆品。粉以饰面，黛以画眉。"]',''),('huajianji-284','虞美人·翠屏闲掩垂珠箔','顾敻','huajianji','虞美人','','翠屏闲掩垂珠箔，丝雨笼池阁。
露沾红藕咽清香，谢娘娇极不成狂，罢朝妆。
小金鸂鶒沉烟细，腻枕堆云髻。
浅眉微敛注檀轻，旧欢时有梦魂惊，悔多情。','["1.珠箔--珠帘。","2.小金--小金鸂鶒：鸂鶒形金属香炉。沉烟：沉香的焚烟。","3.注檀轻--浅涂红唇。"]',''),('huajianji-285','虞美人·碧梧桐映纱窗晚','顾敻','huajianji','虞美人','','碧梧桐映纱窗晚，花谢莺声懒。
小屏屈曲掩青山，翠帷香粉玉炉寒，两蛾攒。
颠狂少年轻离别，辜负春时节。
画罗红袂有啼痕，魂消无语倚闺门，欲黄昏。','["1.屈曲--小屏上用以折叠的环纽。","2.两蛾攒--双眉愁聚。","3.颠狂--癫狂。"]',''),('huajianji-286','虞美人·深闺春色劳思想','顾敻','huajianji','虞美人','','深闺春色劳思想，恨共春芜长。
黄鹂娇啭泥芳妍，杏枝如画倚轻烟，琐窗前。
凭栏愁立双蛾细，柳影斜摇砌。
玉郎还是不还家，教人魂梦逐杨花，绕天涯。','["1.劳思想--勤思念。","2.春芜--春日的杂草。","3.砌--台阶。"]',''),('huajianji-287','虞美人·少年艳质胜琼英','顾敻','huajianji','虞美人','','少年艳质胜琼英，早晚别三清。
莲冠稳簪钿篦横，飘飘罗袖碧云轻，画难成。
迟迟少转腰身袅，翠靥眉心小。
醮坛风急杏花香。
此时恨不驾鸾凤，访刘郎。','["1.琼英--似玉的美石。","2.三清--仙境。","3.稳簪--稳插。","4.醮坛--道士祈祷的坛。","5.鸾凤--鸾鸟与凤凰。"]',''),('huajianji-288','河传·燕飏','顾敻','huajianji','河传','','燕飏，晴景。
小窗屏暖，鸳鸯交颈。
菱花掩却翠鬓欹，慵整。海棠帘外影。
绣帷香断金鸂鶒，无消息，心事空相忆。
倚东风，春正浓。
愁红，泪痕衣上重。','["1.燕飏--燕高飞。","2.鸳鸯交 颈--这里指屏上的图案。","3.金鸂鶒--鸂鶒形金属香炉。"]',''),('huajianji-289','河传·曲槛','顾敻','huajianji','河传','','曲槛，春晚。
波光渺渺，不知何处。
岸花汀草共依依，雨微，鹧鸪相逐飞。
天涯离恨江声咽，啼猿切，此意向谁说。
倚兰桡，独无聊。
魂消，小炉香欲焦。','["1.焦--烬。"]',''),('huajianji-290','甘州子·一炉龙麝锦帷旁','顾敻','huajianji','甘州子','','一炉龙麝锦帷旁，屏掩映，烛荧煌。
禁楼刁斗喜初长，罗荐绣鸳鸯。
山枕上，私语口脂香。','["1.龙麝--龙脑香和麝香。","2.荧煌--烛光半明半暗。","3.刁斗--小铃。此处指宫中传夜铃。","4.罗荐--罗席。"]',''),('huajianji-291','甘州子·每逢清夜与良晨','顾敻','huajianji','甘州子','','每逢清夜与良晨，多怅望，足伤神。
云迷水隔意中人，寂寞绣罗茵。
山枕上，几点泪痕新。','["1.罗茵--丝罗褥子。"]',''),('huajianji-292','甘州子·曾如刘阮访仙踪','顾敻','huajianji','甘州子','','曾如刘阮访仙踪，深洞客，此时逢。
绮筵散后绣衾同，款曲见韶容。
山枕上，长是怯晨钟。','["1.刘阮访仙踪--用刘晨、阮肇采药遇仙女事。","2.款曲--款曲：诉说衷情委曲。韶容：美丽的容貌。"]',''),('huajianji-293','甘州子·露桃花里小楼深','顾敻','huajianji','甘州子','','露桃花里小楼深，持玉盏，听瑶琴。
醉归青琐入鸳衾，月色照衣襟。
山枕上，翠钿镇眉心。','["1.瑶琴--玉饰的琴。","2.青琐--雕花的窗。此处代指闺房。","3.镇--压。"]',''),('huajianji-294','甘州子·红炉深夜醉调笙','顾敻','huajianji','甘州子','','红炉深夜醉调笙，敲拍处，玉纤轻。
小屏古画岸低平，烟月满闲庭。
山枕上，灯背脸波横。','["1.红炉--火旺的香炉。","2.玉纤--纤指如玉。"]',''),('huajianji-295','玉楼春·月照玉楼春漏促','顾敻','huajianji','玉楼春','','月照玉楼春漏促，飒飒风摇庭砌竹。
梦惊鸳被觉来时，何处管弦声断续。
惆怅少年游冶去，枕上两蛾攒细绿。
晓莺帘外语花枝，背帐犹残红蜡烛。','["1.庭砌--庭前砌阶。","2.游冶--冶游，野游。后世多指声色娱乐。"]',''),('huajianji-296','玉楼春·柳映玉楼春日晚','顾敻','huajianji','玉楼春','','柳映玉楼春日晚，雨细风轻烟草软。
画堂鹦鹉语雕笼，金粉小屏犹半掩。
香灭绣帷人寂寂，倚槛无言愁思远。
恨郎何处纵疏狂，长使含啼眉不展。','["1.纵疏狂--放纵不羁。"]',''),('huajianji-297','玉楼春·月皎露华窗影细','顾敻','huajianji','玉楼春','','月皎露华窗影细，风送菊香沾绣袂。
博山炉冷水沉微，惆怅金闺终日闭。
懒展罗衾垂玉箸，羞对菱花簪宝髻。
良宵好事枉教休，无计那他狂耍婿。','["1.水沉--沉香。","2.玉箸--比喻眼泪。","3.无计--无计那他：无计奈他。婿：女子之夫。"]',''),('huajianji-298','玉楼春·拂水双飞来去燕','顾敻','huajianji','玉楼春','','拂水双飞来去燕，曲槛小屏山六扇。
春愁凝思结眉心，绿绮懒调红锦荐。
话别情多声欲战，玉箸痕留红粉面。
镇长独立到黄昏，却怕良宵频梦见。','["1.绿绮--绿绮：琴名。红锦荐：红锦席。","2.声欲战--声音颤动。","3.镇长--久长。"]',''),('huajianji-299','浣溪沙·春色迷人恨正赊','顾敻','huajianji','浣溪沙','','春色迷人恨正赊，可堪荡子不还家，细风轻露着梨花。
帘外有情双燕飏，槛前无力绿杨斜，小屏狂梦极天涯。','["1.赊--长。","2.可堪--哪堪。","3.飏--飞。"]',''),('huajianji-300','浣溪沙·红藕香寒翠渚平','顾敻','huajianji','浣溪沙','','红藕香寒翠渚平，月笼虚阁夜蛩清，塞鸿惊梦两牵情。
宝帐玉炉，残麝冷，罗衣金缕暗尘生，小窗孤烛泪纵横。','["1.蛩--蟋蟀。"]',''),('huajianji-301','浣溪沙·荷芰风轻帘幕香','顾敻','huajianji','浣溪沙','','荷芰风轻帘幕香，绣衣鸂鶒泳回塘，小屏闲掩旧潇湘。
恨入空帷鸾影独，泪凝双脸渚莲光，薄情年少悔思量。','["1.荷芰--荷花、菱角。","2.绣衣鸂鶒--屏风所画萧湘湘图。","3.潇湘--屏风所画潇湘图。","4.泪凝--形容脸如莲，泪凝如水珠发光。"]',''),('huajianji-302','浣溪沙·惆怅经年别谢娘','顾敻','huajianji','浣溪沙','','惆怅经年别谢娘，月窗花院好风光，此时相望最情伤。
青鸟不来传锦字，瑶姬何处琐兰房，忍教魂梦两茫茫。','["1.青鸟--青鸟：《汉武故事》中为西王母传信的鸟。此处代指信使。锦字：即织锦字书，代指书信。","2.瑶姬--神女，即巫山神女。代指所思念的女子。"]',''),('huajianji-303','浣溪沙·庭菊飘黄玉露浓','顾敻','huajianji','浣溪沙','','庭菊飘黄玉露浓，冷莎偎砌隐鸣蛩，何期良夜得相逢。
背帐风摇红蜡滴，惹香梦暖绣衾重，觉来枕上怯晨钟。','["1.冷莎偎砌--莎草偎倚庭阶而长。"]',''),('huajianji-304','浣溪沙·云峡风高叶乱飞','顾敻','huajianji','浣溪沙','','云峡风高叶乱飞，小庭寒雨绿苔微，深闺人静掩屏帷。
粉黛暗愁金带枕，鸳鸯空绕画罗衣，那堪辜负不思归。','["1.粉黛--粉黛：此处代指闺中人。金带枕：甄后玉镂金带枕。"]',''),('huajianji-305','浣溪沙·雁响遥天玉漏清','顾敻','huajianji','浣溪沙','','雁响遥天玉漏清，小纱窗外月胧明，翠帷金鸭炷香平。
何处不归音信断，良宵空使攀魂惊，簟凉枕冷不胜情。','["1.炷香--焚香。"]',''),('huajianji-306','浣溪沙·露白蟾明又到秋','顾敻','huajianji','浣溪沙','','露白蟾明又到秋，佳期幽会两悠悠，梦牵情役几时休。
记得泥人微敛黛，无言斜倚小书楼，暗思前事不胜愁。','["1.蟾明--月明。","2.泥人--软缠人。"]',''),('huajianji-307','酒泉子·杨柳舞风','顾敻','huajianji','酒泉子','','杨柳舞风，轻惹春烟残雨。
杏花愁，莺正语，画楼东。
锦屏寂寞思无穷，还是不知消息。
镜尘生，珠泪滴，损仪容。','[]',''),('huajianji-308','酒泉子·罗带缕金','顾敻','huajianji','酒泉子','','罗带缕金，兰麝烟凝魂断。
画屏欹，云鬓乱，恨难任。
几回垂泪滴鸳衾，薄情何处去。
月临窗，花满树，信沉沉。','[]',''),('huajianji-309','酒泉子·小槛日斜','顾敻','huajianji','酒泉子','','小槛日斜，风度绿窗人悄悄。
翠帷闲掩舞双鸾，旧香寒。
别来情绪转难拚，韶颜看却老。
依稀粉上有啼痕，暗销魂。','["1.难拚--难舍。","2.却--又。"]',''),('huajianji-310','酒泉子·黛薄红深','顾敻','huajianji','酒泉子','','黛薄红深，约掠绿鬟云腻。
小鸳鸯，金翡翠，称人心。
锦鳞无处传幽意，海燕兰堂春又去。
隔年书，千点泪，恨难任。','["1.约惊--缠束。","2.锦鳞--鱼。此处指传书的鱼。"]',''),('huajianji-311','酒泉子·掩却菱花','顾敻','huajianji','酒泉子','','掩却菱花，收拾翠钿休上面。
金虫玉燕锁香奁，恨厌厌。
云鬟半坠懒重簪，泪侵山枕湿。
恨灯背帐梦方酣，雁飞南。','["1.休上面--不戴面妆和头饰。","2.金虫玉燕--头饰。","3.厌厌--精神不振。"]',''),('huajianji-312','酒泉子·水碧风清','顾敻','huajianji','酒泉子','','水碧风清，入槛细香红藕腻。
谢娘敛翠恨无涯，小屏斜。
堪憎荡子不还家，漫留罗带结。
帐深枕腻炷沉烟，负当年。','["1.腻--滑泽。","2.漫留--空留。"]',''),('huajianji-313','酒泉子·黛愁怨红羞','顾敻','huajianji','酒泉子','','黛愁怨红羞，掩映画堂春欲暮。
残花微雨隔青楼，思悠悠。
芳菲时节看将度，寂寞无人还独语。
画罗襦，香粉污，不胜愁。','[]',''),('huajianji-314','杨柳枝·秋夜香闺思寂寞','顾敻','huajianji','杨柳枝','','秋夜香闺思寂寞，漏迢迢。
鸳帷罗幌麝烟销，烛光摇。
正忆玉郎游荡去，无寻处。
更闻帘外雨萧萧，滴芭蕉。','["1.迢迢--漫长。"]',''),('huajianji-315','遐方怨·帘影细','顾敻','huajianji','遐方怨','','帘影细，簟纹平。
象纱笼玉指，缕金罗扇轻。
嫩双脸似花明，两条眉黛远山横。
风箫歇，镜尘生。
辽塞音书绝，梦魂长暗惊。
玉郎经岁负娉婷，教人怎不恨无情。','["1.象纱--纱名。","2.娉婷--姿态美好。"]',''),('huajianji-316','献衷心·绣鸳鸯帐暖','顾敻','huajianji','献衷心','','绣鸳鸯帐暖，画孔雀欹。
人悄悄，月明时，想昔年欢笑，恨今日分离。
银背，铜漏永，阻佳期。
小炉烟细，虚阁帘垂。
几多心事，暗地思惟。
被娇娥牵役，魂梦如痴。
金闺里，山枕上，始应知。','["1.思惟--思量。","2.娇娥--貌美女 子。"]',''),('huajianji-317','应天长·瑟瑟罗裙金线缕','顾敻','huajianji','应天长','','瑟瑟罗裙金线缕，轻透鹅黄香画袴。
垂交带，盘鹦鹉，袅袅翠翘移玉步。
背人匀檀注，慢转横波偷觑。
敛黛春情暗许，倚慵不语。','["1.画袴--彩色套裤。","2.盘鹦鹉--带上绣物。","3.檀注--唇上的胭红。","4.偷觑--偷看。","5.春情--男女爱恋之情。"]',''),('huajianji-318','诉衷情·香灭帘垂春漏永','顾敻','huajianji','诉衷情','','香灭帘垂春漏永，整鸳衾。
罗带重，双凤，缕黄金。
窗外月光临，沉沉。
断肠无处寻，负春心。','[]',''),('huajianji-319','诉衷情·永夜抛人何处去','顾敻','huajianji','诉衷情','','永夜抛人何处去，绝来音。
香阁掩，眉敛，月将沉。
怎忍不相寻？鸳孤衾。
换我心为你心，始知相忆深。','["1.永夜--长夜。","2.孤衾--比喻独眠。"]',''),('huajianji-320','荷叶杯·春尽小庭花落','顾敻','huajianji','荷叶杯','','春尽小庭花落，寂寞。
凭槛敛双眉，忍教成病忆佳期。
知么知，知么知。','[]',''),('huajianji-321','荷叶杯·歌发谁家筵上','顾敻','huajianji','荷叶杯','','歌发谁家筵上，寥亮。
别恨正悠悠，兰釭背帐月当楼。
愁么愁，愁么愁。','["1.寥亮--声音清越高远。"]',''),('huajianji-322','荷叶杯·弱柳好花尽坼','顾敻','huajianji','荷叶杯','','弱柳好花尽坼，晴陌。
陌上少年郎，满身兰麝扑人香。
狂么狂，狂么狂。','["1.尽坼--尽裂。"]',''),('huajianji-323','荷叶杯·记得那时相见','顾敻','huajianji','荷叶杯','','记得那时相见，胆战。
鬓乱四肢柔，泥人无语不抬头。
羞么羞，羞么羞。','[]',''),('huajianji-324','荷叶杯·夜久歌声怨咽','顾敻','huajianji','荷叶杯','','夜久歌声怨咽，残月。
菊冷露微微，看看湿透缕金衣。
归么归，归么归。','[]',''),('huajianji-325','荷叶杯·我忆君诗最苦','顾敻','huajianji','荷叶杯','','我忆君诗最苦，知否。
字字尽关心，红笺写寄表情深。
吟么吟，吟么吟。','[]',''),('huajianji-326','荷叶杯·金鸭香浓鸳被','顾敻','huajianji','荷叶杯','','金鸭香浓鸳被，枕腻。
小髻簇花钿，腰如细柳脸如莲。
怜么怜，怜么怜。','[]',''),('huajianji-327','荷叶杯·曲砌蝶飞烟暖','顾敻','huajianji','荷叶杯','','曲砌蝶飞烟暖，春半。
花发柳垂条，花如双脸柳如腰。
娇么娇，娇么娇。','["1.曲砌--曲折的台阶。"]',''),('huajianji-328','荷叶杯·一去又乖期信','顾敻','huajianji','荷叶杯','','一去又乖期信，春尽。
满院长莓苔，手挼裙带独徘徊。
来么来，来么来。','["1.乖期信--违背约会的日期。"]',''),('huajianji-329','渔歌子·晓风清','顾敻','huajianji','渔歌子','','晓风清，幽沼绿，倚栏凝望珍禽浴。
画帘垂，翠屏曲，满袖荷香馥郁。
好摅怀，堪寓目，身闲心静平生足。
酒杯深，光影促，名利无心较逐。','["1.馥郁--香气浓烈。","2.摅怀--抒怀。","3.寓目--观看，过目。","4.光影促--岁月短促。","5.较逐--角逐。"]',''),('huajianji-330','临江仙·碧染长空池似镜','顾敻','huajianji','临江仙','','碧染长空池似镜，倚楼闲望凝情，满衣红藕细香清。
象床珍簟，山障掩，玉琴横。
暗想昔时欢笑事，如今赢得愁生。
博山炉暖淡烟轻。
蝉吟人静，残日傍，小窗明。','["1.象床 --以象牙为饰的床 。","2.山障掩--屏风掩。"]',''),('huajianji-331','临江仙·幽闺小槛春光晚','顾敻','huajianji','临江仙','','幽闺小槛春光晚，柳浓花淡莺稀。
旧欢思想尚依依，翠颦红敛，终日损芳菲。
何事狂夫音信断，不如梁燕犹归。
画意深处麝烟微，屏虚枕冷，风细雨霏霏。','["1.思想--思念。","2.损芳菲--比喻红颜衰老。"]',''),('huajianji-332','临江仙·月色穿帘风入竹','顾敻','huajianji','临江仙','','月色穿帘风入竹，倚屏双黛愁时。
砌花含露两三枝，如啼恨脸，魂断损容仪。
香烬暗消金鸭冷，可堪辜负前期。
绣襦不整鬓鬟欹，几多惆怅，情绪在天涯。','["1.砌花--种植在台阶前的花。"]',''),('huajianji-333','醉公子·漠漠秋云淡','顾敻','huajianji','醉公子','','漠漠秋云淡，红耦香侵槛。
枕欹小山屏，金铺向晚扃。
睡起横波慢，独望情何限。
衰柳数声蝉，魂消似去年。','["1.金铺--金铺：此处指门。扃：关闭。","2.横波--眼睛。"]',''),('huajianji-334','醉公子·岸柳垂金线','顾敻','huajianji','醉公子','','岸柳垂金线，雨晴莺石啭。
家在绿杨边，往来多少年。
马嘶芳草远，高楼帘半卷。
敛袖翠蛾攒，相逢尔许难。','["1.尔许难--如此难。"]',''),('huajianji-335','更漏子·旧欢娱','顾敻','huajianji','更漏子','','旧欢娱，新怅望，拥鼻含颦楼上。
浓柳翠，晚霞微，江鸥接翼飞。
帘半卷，屏斜掩，远岫参差迷眼。
歌满耳，酒盈樽，前非不要论。','["1.远岫--远山。"]',''),('huajianji-336','浣溪沙·蓼岸风多枯柚香','孙光宪','huajianji','浣溪沙','','蓼岸风多枯柚香，江边一望楚天长，片帆烟际闪孤光。
目送征鸿飞杳杳，思随流水去茫茫，兰红波碧忆潇湘。','["1.蓼岸--开满蓼花的江 岸。","2.楚天--泛指今湖北、湘南一带。","3.杳杳--幽远。"]',''),('huajianji-337','浣溪沙·桃杏风香帘幕闲','孙光宪','huajianji','浣溪沙','','桃杏风香帘幕闲，谢家门户约花关，画梁幽语燕初还。
绣阁数行题了壁，晓屏一枕酒醒山，却疑身是梦魂间。','["1.约--拦，沿。","2.题了壁--题完璧。书字于璧。","3.山--山枕。"]',''),('huajianji-338','浣溪沙·花渐凋疏不耐风','孙光宪','huajianji','浣溪沙','','花渐凋疏不耐风，画帘垂地晚堂空，堕阶萦藓舞愁红。
腻粉半沾金靥子，残香犹暖绣熏笼，蕙心无处与人同。','["1.不耐--不奈。无可奈何。","2.腻粉--腻粉：指落花。金靥子：黄星靥：--一种面妆。","3.蕙心--比喻女子纯美之心。这里指落花而言。"]',''),('huajianji-339','浣溪沙·揽镜无言泪欲流','孙光宪','huajianji','浣溪沙','','揽镜无言泪欲流，凝情半日懒梳头，一庭疏雨湿春愁。
杨柳只知伤离别，杏花应信损娇羞，泪沾魂断轸离忧。','["1.轸--悲痛。"]',''),('huajianji-340','浣溪沙·半踏长裾宛约行','孙光宪','huajianji','浣溪沙','','半踏长裾宛约行，晚帘疏处见分明，此时堪恨昧平生。
早是消魂残烛影，更愁闻着品弦声，杳无消息若为情。','["1.半踏--半踏：小步。长裾：长襟衣服。","2.昧平生--即素昧平生，一向不了解。","3.品弦--品竹调弦，即吹弹尔器。","4.若为情--何以为情，难以为情。"]',''),('huajianji-341','浣溪沙·兰沐初休曲槛前','孙光宪','huajianji','浣溪沙','','兰沐初休曲槛前，缓风迟日洗头天，湿云新敛未梳蝉。
翠袂半将遮粉臆，宝钗长欲坠香肩，此时模样不禁怜。','["1.兰沐--以兰汤洗发。","2.迟日--春日。","3.翠袂--翠袂：绿色衣袖。粉臆：白嫩的胸。","4.不禁怜--禁不住怜爱之情。"]',''),('huajianji-342','浣溪沙·风递残香出绣帘','孙光宪','huajianji','浣溪沙','','风递残香出绣帘，团窠金凤舞襜襜，落花微雨恨相兼。
何处去来狂太甚，空推宿酒睡无厌，怎教人不别猜嫌。','["1.团窠--团窠：锦锻。金凤：绣帘上的纹饰。","2.空推--宿酒：隔夜酒。无厌：不安静。"]',''),('huajianji-343','浣溪沙·轻打银筝坠燕泥','孙光宪','huajianji','浣溪沙','','轻打银筝坠燕泥，断丝高罥画楼西，花冠闲上午墙啼。
粉箨半开新竹径，红苞尽落旧桃蹊，不堪终日闭深闺。','["1.高罥--高挂。","2.花冠--雄鸡。","3.粉箨--竹笋壳。","4.桃蹊--桃树下的道路。"]',''),('huajianji-344','浣溪沙·乌帽斜欹倒佩鱼','孙光宪','huajianji','浣溪沙','','乌帽斜欹倒佩鱼，静街偷步访仙居，隔墙应认打门初。
将见客时微掩敛，得人怜处且先疏，低头羞问壁边书。','["1.乌帽--乌帽：乌纱帽。隋代帝王贵臣多戴乌纱帽。其后渐行于民间。佩鱼：唐时五品官以上的佩饰，称佩金鱼袋。","2.仙居--神仙住所。此指所思女子居处。","3.打门--叩门。","4.生疏--不亲密。"]',''),('huajianji-345','河传·太平天子','孙光宪','huajianji','河传','','太平天子，等闲游戏，疏河千里。
柳如丝，偎倚绿波春水，长淮风不起。
如花殿脚三千女，争云雨，何处留人住？
锦帆风，烟际江，烧空，魂迷大业中。','["1.太平天子--此处指隋炀帝。","2.等闲--随便，寻常。","3.长淮--淮水。","4.如花--为隋炀帝牵羊挽舟的美女 很多。参见卷第三韦庄《河传》其一注。","5.大业--隋炀帝年号。"]',''),('huajianji-346','河传·柳拖金缕','孙光宪','huajianji','河传','','柳拖金缕，着烟笼雾，蒙蒙落絮。
凤皇舟上楚女，妙舞，雷喧波上鼓。
龙争虎战分中土，人无主，桃叶江南渡。
襞花笺，艳思牵。
成篇，官娥相与传。','["1.龙争--批隋末群雄争斗，瓜分国土，天下无人主宰。","2.桃叶江 南渡--江 南桃叶渡。故址在今江 苏南京秦淮河畔。","3.襞花笺--折叠精致华美的诗笺。这里指作诗。"]',''),('huajianji-347','河传·花落','孙光宪','huajianji','河传','','花落，烟薄，谢家池阁。
寂寞春深，翠蛾轻敛意沉吟。
沾襟，无人知此心。
玉炉香断霜灰冷，帘铺影，梁燕归红杏。
晚来天，空悄然。
孤眠，枕檀云髻偏。','["1.霜灰冷--香灰冷如霜。","2.悄然--忧愁。"]',''),('huajianji-348','河传·风飐','孙光宪','huajianji','河传','','风飐，波敛。
团荷闪闪，珠倾露点。
木兰舟上，何处吴娃越艳，藕花红照脸。
大堤狂杀襄阳客，烟波隔，渺渺湖光白。
身已归，心不归。
斜晖，远汀鸂鶒飞。','["1.飐--风吹使物动。","2.吴娃越艳--吴越美女 。","3.大堤--大堤：即《大堤曲》，乐府名。襄阳客：唐代吴兢《乐府古题要解》收乐府词云：“朝发襄阳城，暮至大堤宿。大堤诸女儿，花艳惊郎目。”此句用其词义。"]',''),('huajianji-349','菩萨蛮·月华如水笼香砌','孙光宪','huajianji','菩萨蛮','','月华如水笼香砌，金环碎撼门初闭。
寒影堕高檐，钩垂一画帘。
碧烟轻袅袅，红战灯花笑。
即此是高唐，掩屏秋梦长。','["1.碎撼--闭门时门环震动声。","2.红战--红战：灯花颤动。灯花：灯心的余烬，爆成花形。古人以灯花为吉兆，故称“灯花笑”。","3.高唐--用宋玉《高唐赋》楚王游高唐梦神女事。"]',''),('huajianji-350','菩萨蛮·花冠频鼓墙头翼','孙光宪','huajianji','菩萨蛮','','花冠频鼓墙头翼，东方淡白连窗色。
门外早莺声，背楼残月明。
薄寒笼醉态，依旧铅华在。
握手送人归，半拖金缕衣。','["1.花冠--雄鸡。","2.铅华-铅粉，妇女妆饰品。"]',''),('huajianji-351','菩萨蛮·小庭花落无人归','孙光宪','huajianji','菩萨蛮','','小庭花落无人归，疏香满地东风老。
春晚信沉沉，天涯何处寻。
晓堂屏六扇，眉共湘山远。
怎奈别离心，近来尤不禁。','["1.眉共--眉色如画屏上湘山。即远山眉。"]',''),('huajianji-352','菩萨蛮·青岩碧洞经朝雨','孙光宪','huajianji','菩萨蛮','','青岩碧洞经朝雨，隔花相唤南溪去。
一只木兰船，波平远浸天。
扣舷惊翡翠，嫩玉抬香臂。
红日欲沉西，烟中遥解觽。','["1.扣舷--敲击船帮打节拍，以应船歌。","2.解觽--解下佩物。觽--古代用以解结绳的角锥，象骨所做。"]',''),('huajianji-353','菩萨蛮·木绵花映丛祠小','孙光宪','huajianji','菩萨蛮','','木绵花映丛祠小，越禽声里春光晓。
铜鼓与蛮歌，南人祈赛多。
客帆风正急，茜袖偎樯立。
极浦几回头，烟波无限愁。','["1.木绵花--木绵花：木棉花。丛祠：乡野林间的神祠。","2.越禽--南方食鸟。","3.铜鼓--铜鼓：求神所击的乐器。蛮歌：巴楚一带民歌。","4.茜袖--绿色衣袖。"]',''),('huajianji-354','河渎神·汾水碧依依','孙光宪','huajianji','河渎神','','汾水碧依依，黄云落叶初飞。
翠华一去不言归，庙门空掩斜晖。
四壁阴森排古画，依旧琼轮羽驾。
小殿沉沉清夜，银灯飘落香灺。','["1.汾水--汾河。在今山西省境内。","2.翠华--本作翠蛾”。","3.琼轮羽驾--河神所御的车驾。","4.香灺--烛烬。"]',''),('huajianji-355','河渎神·江上草芊芊','孙光宪','huajianji','河渎神','','江上草芊芊，春晚湘妃庙前。
一方卵色楚南天，数行征雁联翩。
独倚朱栏情不极，魂断终朝相忆。
两桨不知消息，远汀时起鸂鶒。','["1.草芊芊--草茂盛。","2.湘妃庙--黄陵庙。","3.卵色--鱼肚白色。","4.联翩--鸟飞的样子。"]',''),('huajianji-356','虞美人·红窗寂寂无人语','孙光宪','huajianji','虞美人','','红窗寂寂无人语，暗淡梨花雨。
绣罗纹地粉新描，博山香炷旋抽条，暗魂消。
天涯一去无消息，终日长相忆。
教人相忆几时休？不堪枨触别离愁，泪还流。','["1.博山--博山：博山炉，古香炉名，此处代指香炉。香炷：点燃着的香。炷：灯心。抽条：香穗，即灯花。","2.枨(cheng2)触--感触。"]',''),('huajianji-357','虞美人·好风微揭帘旌起','孙光宪','huajianji','虞美人','','好风微揭帘旌起，金翼鸾相倚。
翠檐愁听乳禽声，此时春态暗关情，独难平。
画堂流水空相翳，一穗香摇曳。
教人无处寄相思，落花芳草过前期，没人知。','["1.金翼--帘上绣物。","2.乳禽--雏燕。","3.相翳--相蔽。"]',''),('huajianji-358','后庭花·景阳钟动宫莺啭','孙光宪','huajianji','后庭花','','景阳钟动宫莺啭，露凉金殿。
轻飙吹起琼花旋，玉叶如剪。
晚来高阁上，珠帘卷，见坠香千片。
修蛾慢脸陪雕辇，后庭新宴。','["1.轻飙--微风。","2.修蛾--修蛾慢脸：长眉娇脸。雕辇：皇帝的车。"]',''),('huajianji-359','后庭花·石城依旧空江国','孙光宪','huajianji','后庭花','','石城依旧空江国，故宫春色。
七尺青丝芳草碧，绝世难得。
玉英凋落尽，更何人识，野棠如织。
只是教人添怨忆，怅望无极。','["1.石城--石头城。故址在今江 苏南京市石头山后。","2.七尺青丝--南朝陈后主的贵妃张丽华发长七尺。"]',''),('huajianji-360','生查子·寂寞掩朱门','孙光宪','huajianji','生查子','','寂寞掩朱门，正是天将暮。
暗淡小庭中，滴滴梧桐雨。
绣工夫，牵心绪，配尽鸳鸯缕。
待得没人时，偎倚论私语。','["1.绣工夫--刺绣。","2.私语--低声小语。"]',''),('huajianji-361','生查子·暖日策花骢','孙光宪','huajianji','生查子','','暖日策花骢，亸鞚垂杨陌。
芳草惹烟青，落絮随风白。
谁家绣毂动香尘，隐遇难神仙客。
狂杀玉鞭郎，咫尺音容隔。','["1.亸鞚--垂下马勒。","2.绣毂--华美装饰的车。","3.神仙客--这里指车中美女 。"]',''),('huajianji-362','生查子·金井堕高梧','孙光宪','huajianji','生查子','','金井堕高梧，玉殿笼斜月。
永巷寂无人，敛态愁堪绝。
玉炉寒，香烬灭，还似君恩歇。
翠辇不归来，幽恨将谁说。','["1.永巷--皇宫中妃嫔住处，即后宫。","2.翠辇--皇帝所乘的车。","3.将谁说--与谁说。"]',''),('huajianji-363','临江仙·霜拍井梧干叶堕','孙光宪','huajianji','临江仙','','霜拍井梧干叶堕，翠帷雕槛初寒。
薄铅残黛称花冠，含情无语，延伫倚栏干。
杳杳征轮何处去，离愁别恨千般。
不堪心绪正多端，镜奁长掩，无意对孤鸾。','["1.延伫--久立。","2.孤鸾--比喻镜中孤影。"]',''),('huajianji-364','临江仙·暮雨凄凄深院闭','孙光宪','huajianji','临江仙','','暮雨凄凄深院闭，灯前凝坐初更。
玉钗低压鬓云横，半垂罗幕，相映烛光明。
终是有心投汉佩，低头但理秦筝。
燕双鸾耦不胜情，只愁明发，将逐楚云行。','["1.投汉佩--相传周郑文甫于汉皋台下遇二女，解佩相赠。后因以汉皋佩作男女爱慕赠答的典故。此指女子有心赠物于情人 。","2.理秦筝--调秦筝。","3.鸾耦--鸾偶。","4.明发--黎明。《诗经·小雅·小宛》：明发不寐，有怀二人”。"]',''),('huajianji-365','酒泉子·空碛无边','孙光宪','huajianji','酒泉子','','空碛无边，万里阳关道路。
马萧萧，人去去，陇云愁。
香貂旧制戎衣窄，胡霜千里白。
绮罗心，魂梦隔，上高楼。','["1.空碛--空阔的沙漠。","2.阳关--古代中原通往西城的交 通要道。今甘肃敦煌市西南，玉门 关的南面。","3.萧萧--马鸣声。","4.人去去--人截止离越远。","5.陇--地名。泛指今甘肃一带，是古代西北边防要地。","6.香貂--贵重的貂皮，这里指战袍。"]',''),('huajianji-366','酒泉子·曲槛小楼','孙光宪','huajianji','酒泉子','','曲槛小楼，正是莺花二月。
思无聊，愁欲绝，郁离襟。
展屏空对潇湘水，眼前千万里。
泪掩红，眉敛翠，恨沉沉。','["1.潇湘水--屏上的画。"]',''),('huajianji-367','酒泉子·敛态窗前','孙光宪','huajianji','酒泉子','','敛态窗前，袅袅雀钗抛颈。
燕成双，鸾对影，耦新知。
玉纤淡拂眉山小，镜中嗔共照。
翠连娟，红缥渺，早妆时。','["1.敛态--严肃的神态。","2.耦新知--偶新知。两相知。","3.嗔--佯装嗔怪。","4.翠连娟--指画眉。","5.红缥渺--指簪花。"]',''),('huajianji-368','清平乐·愁肠欲断','孙光宪','huajianji','清平乐','','愁肠欲断，正是青春半。
连理分枝鸾失伴，又是一场离散。
掩镜无语眉低，思随芳草萋萋。
凭仗东风吹梦，与郎终日东西。','["1.凭仗--凭借、倚仗。"]',''),('huajianji-369','清平乐·等闲无语','孙光宪','huajianji','清平乐','','等闲无语，春恨如何去？
终是疏狂留不住，花暗柳浓何处。
尽日目断魂飞，晚窗斜界残晖。
长恨朱门薄暮，绣鞍骢马空归。','["1.凭仗--凭借、倚仗。","2.斜界残晖--残晖一线。界：画线。"]',''),('huajianji-370','更漏子·听寒更','孙光宪','huajianji','更漏子','','听寒更，闻远雁，半夜萧娘深院。
扃绣户，下珠帘，满庭喷玉蟾。
人语静，香闺冷，红幕半垂清影。
云雨态，蕙兰心，此情江海深。','["1.萧娘--女子的泛称。","2.喷玉蟾--喷射月光。","3.蕙兰心--以香草蕙、兰比喻女子纯美之心。"]',''),('huajianji-371','更漏子·今夜期','孙光宪','huajianji','更漏子','','今夜期，来日别，相对只堪愁绝。
偎粉面，捻瑶簪，无言泪满襟。
银箭落，霜华薄，墙外晓鸡咿喔。
听咐嘱，恶情悰，断肠西复东。','["1.银箭--银制漏箭。古代计时器。","2.咿喔--鸡叫声。","3.情悰--情绪。"]',''),('huajianji-372','女冠子·蕙风芝露','孙光宪','huajianji','女冠子','','蕙风芝露，坛际残香轻度。
蕊珠宫，苔点分圆碧，桃花践破红。
品流巫峡外，名籍紫微中。
真侣墉城会，梦魂通。','["1.蕙风--蕙风：夹带花草芳香的风。芝露：香草上的露。","2.坛际--祭坛边。","3.蕊珠宫--神仙所居处。","4.品流--等级辈分。","5.名籍--名籍：名册。紫微：仙府，天帝所居。","6.墉城--神仙所居地。"]',''),('huajianji-373','女冠子·淡花瘦玉','孙光宪','huajianji','女冠子','','淡花瘦玉，依约神仙妆束。
佩琼文，瑞露通宵贮，幽香尽日焚。
碧纱笼绛节，黄藕冠浓云。
勿以吹箫伴，不同群。','["1.淡花瘦玉--形容女冠的仪态。","2.依约--隐约。","3.佩琼文--佩玉饰。","4.瑞露--道家贮露，为修炼事。","5.绛节--红色符节。道士作法时用具。","6.黄藕--黄藕冠：黄藕色的冠。浓云：指头发。","7.吹萧伴--用弄玉和萧史事。"]',''),('huajianji-374','风流子·茅舍槿篱溪曲','孙光宪','huajianji','风流子','','茅舍槿篱溪曲，鸡犬自南自北。
菰叶长，水葓开，门外春波涨绿。
听织，声促，轧轧鸣梭穿屋。','["1.水葓--草名，生于池塘草泽中。","2.轧轧--织机声。"]',''),('huajianji-375','风流子·楼倚长衢欲暮','孙光宪','huajianji','风流子','','楼倚长衢欲暮，簪见神仙伴侣。
微傅粉，拢梳头，隐映画帘开处。
无语，无绪，慢曳罗裙归去。','["1.长衢--长街。","2.傅粉--搽粉。","3.无绪--情绪低落。"]',''),('huajianji-376','风流子·金络玉衔嘶马','孙光宪','huajianji','风流子','','金络玉衔嘶马，系向绿杨阴下。
朱户掩，绣帘垂，曲院水流花谢。
欢罢，归也，犹在九衢深夜。','["1.九衢--四通八达的路。"]',''),('huajianji-377','定西番·鸡禄山前游骑','孙光宪','huajianji','定西番','','鸡禄山前游骑，边草白，朔天明，马蹄轻。
鹊面弓离短韔，弯来月欲成。
一只鸡鹘云外，晓鸿惊。','["1.鸡禄山--鸡禄山，疑即鸡禄塞，在内蒙古边塞地。游骑：流动的骑兵。","2.朔天--北方的天。","3.鹊面弓--鹊面弓：弓名。短韔：弓袋。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('huajianji-378','定西番·帝子枕前秋夜','孙光宪','huajianji','定西番','','帝子枕前秋夜，霜幄冷，月华明，正三更。
何处戍楼寒笛，梦残闻一声。
遥想汉关万里，泪纵横。','["1.帝子--帝王之女。此处应指汉代去西番和亲的公主。"]',''),('huajianji-379','河满子·冠剑不随君去','孙光宪','huajianji','河满子','','冠剑不随君去，江河还共恩深。
歌袖半遮眉黛惨，泪珠旋滴衣襟。
惆怅云愁雨怨，断魂何处相寻。','["1.冠剑--士的服饰的佩物。"]',''),('huajianji-380','玉蝴蝶·春欲尽','孙光宪','huajianji','玉蝴蝶','','春欲尽，景仍长，满园花正黄。
粉翘两悠飏，翩翩过短墙。
鲜飙暖，牵游伴，飞去立残芳。
无语对萧娘，舞衫沉麝香。','["1.粉翘--粉翘：代指飞蝶类。","2.两悠飏--两翅飞扬。","3.鲜飙暖--新鲜洁净的暖风。"]',''),('huajianji-381','八拍蛮·孔雀尾拖金线长','孙光宪','huajianji','八拍蛮','','孔雀尾拖金线长，怕人飞起入丁香。
越女沙头争拾翠，相呼归去背斜阳。','["1.拾翠--原指拾取翠鸟羽毛以为首饰，后指妇女春日嬉游。"]',''),('huajianji-382','竹枝·门前春水白苹花','孙光宪','huajianji','竹枝','','门前春水（竹枝）白苹花（女儿），岸上无人（竹枝）小艇斜（女儿）。
商女经过（竹枝）江欲暮（女儿），散抛残食（竹枝）饲神鸦（女儿）。','["1.竹枝、女儿--唱歌时众人随和的声字。下同。","2.商女--歌女。","3.神鸦--乌鸦，因栖息于神祠而称。"]',''),('huajianji-383','竹枝·乱绳千结绊人深','孙光宪','huajianji','竹枝','','乱绳千结（竹枝）绊人深（女儿），越罗万丈（竹枝）表长寻（女儿）。
杨柳在身（竹枝）垂意绪（女儿），藕花落尽（竹枝）见莲心（女儿）。','["1.寻--古长度单位，八尺为一寻。","2.莲心--双关怜心”。"]',''),('huajianji-384','思帝乡·如何','孙光宪','huajianji','思帝乡','','如何？遣情情更多。
永日水堂帘下，敛羞蛾。
六幅罗裙窣地，微行曳碧波。
看尽满地疏雨，打团荷。','["1.微行--小径。"]',''),('huajianji-385','上行杯·草草离亭鞍马','孙光宪','huajianji','上行杯','','草草离亭鞍马，从远道，此地分襟，燕宋秦吴千万里。
无辞一醉。野棠开，江草湿。伫立，沾泣，征骑骎骎。','["1.从远道--行远道。","2.分襟--分别。","3.燕宋--语出江 淹《别赋》：况秦吴兮绝国，复燕宋兮千里”。意思是：秦、吴、燕、赵四国相隔极远，别恨必深。","4.骎骎--马疾行。"]',''),('huajianji-386','上行杯·离棹逡巡欲动','孙光宪','huajianji','上行杯','','离棹逡巡欲动，临极浦，故人相送，去住心情知不共。
金船满捧。绮罗愁，丝管咽。回别，帆影灭，江浪如雪。','["1.逡巡--迟疑徘徊，欲行又止。","2.金船--酒器。"]',''),('huajianji-387','谒金门·留不得','孙光宪','huajianji','谒金门','','留不得！留得也应无益。
白纻春衫如雪色，扬州初去日。
轻别离，甘抛掷，江上满帆风疾。
却羡彩鸳三十六，孤鸾还一只。','["1.三十六--指三十六对。","2.孤鸾--这里以孤鸾自喻。"]',''),('huajianji-388','思越人·古台平','孙光宪','huajianji','思越人','','古台平，芳草远，馆娃宫外春深。
翠黛空留千载恨，教人何处相寻。
绮罗无复当时事，露花点滴香泪。
惆怅遥天横绿水，鸳鸯对时飞起。','["1.古台--此处指姑苏台。吴王夫差为西施而筑。","2.馆娃宫--春秋吴宫名。吴王夫差为西施建。故址在今江 苏省吴县市西南。"]',''),('huajianji-389','思越人·渚莲枯','孙光宪','huajianji','思越人','','渚莲枯，宫树老，长洲废萧条。
想象玉人空处所，月明独上溪桥。
经春初败秋风起，江兰绿蕙愁死。
一片风流伤心地，魂销目断西子。','["1.长洲废苑--长洲苑。在今江 苏吴县市太湖北。","2.玉人--此处指西施。"]',''),('huajianji-390','杨柳枝·阊门风暖落花干','孙光宪','huajianji','杨柳枝','','阊门风暖落花干，飞遍江城江城雪不寒。
独有晚来临水驿，闲人多凭赤栏干。','["1.阊门--吴王阖闾所建城门名，为苏州城西门。"]',''),('huajianji-391','杨柳枝·有池有榭即蒙蒙','孙光宪','huajianji','杨柳枝','','有池有榭即蒙蒙，浸润翻成长养功。
恰似有人长点检，着行排立向春风。','["1.蒙蒙--此处指杨花柳絮。","2.浸润--浸润：此处指杨柳受池水渗透。长养：长期养育。","3.点检--清理。","4.着行--成行。"]',''),('huajianji-392','杨柳枝·根柢虽然傍浊河','孙光宪','huajianji','杨柳枝','','根柢虽然傍浊河，无妨终日近笙歌。
骖骖金带谁堪比，还共黄莺不较多。','["1.根柢--此处指杨柳的根部。","2.骖骖金带--形容随风飞舞的柳条。"]',''),('huajianji-393','杨柳枝·万株枯槁怨亡隋','孙光宪','huajianji','杨柳枝','','万株枯槁怨亡隋，似吊吴台各自垂。
好是淮阴明月里，酒楼横笛不胜吹。','["1.吴台--姑苏台。","2.横笛不胜吹--横笛吹不尽《杨柳枝》曲。"]',''),('huajianji-394','望梅花·数枝开与短墙平','孙光宪','huajianji','望梅花','','数枝开与短墙平，见雪萼红跗相映，引起谁人边塞情。
帘外欲三更，吹断离愁月正明，空听隔江声。','["1.红跗(fu1)--红色花萼的基部。"]',''),('huajianji-395','渔歌子·草芊芊','孙光宪','huajianji','渔歌子','','草芊芊，波漾漾，湖边草色连波涨。
沿蓼岸，泊飘汀，天际玉轮初上。
扣舷歌，联极望，桨声伊轧知何向。
黄鹊叫，白鸥眠，谁似侬家疏旷。','["1.玉轮--月亮。","2.联极望--四面张望。","3.黄鹄--天鹅。","4.侬家--自称。"]',''),('huajianji-396','渔歌子·泛流萤','孙光宪','huajianji','渔歌子','','泛流萤，明又灭，夜凉水冷东湾阔。
风浩浩，笛寥寥，万顷金波澄澈。
杜若洲，香郁烈，一声宿雁霜时节。
经霅水，过松江，尽属侬家日月。','["1.金波--月光。","2.杜若--香草。","3.霅水--水名。在今浙江 省湖州市南。","4.松江 --吴淞江 。在今江 苏省境内。 魏承班 二首"]',''),('huajianji-397','菩萨蛮·罗裾薄薄秋波染','魏承班','huajianji','菩萨蛮','','罗裾薄薄秋波染，眉间画时山两点。
相见绮筵时，深情暗共知。
翠翘云鬓动，敛态弹金凤。
宴罢入兰房，邀入解佩珰。','["1.弹金凤--弹琴筝之类乐器。","2.兰房--妇女所居的房间。","3.佩珰--玉佩耳珠。"]',''),('huajianji-398','菩萨蛮·罗衣隐约金泥画','魏承班','huajianji','菩萨蛮','','罗衣隐约金泥画，玳筵一曲当秋夜。
声战觑人娇，云袅翠翘。
酒醺红玉软，眉翠秋山远。
绣幌麝烟沉，谁人知两心。','["1.金泥画--泥金画，用金粉涂饰的图案。","2.玳筵--盛筵。","3.声战--作声颤”。","4.红玉--形容人的画容。"]',''),('huajianji-399','满宫花·雪霏霏','魏承班','huajianji','满宫花','','雪霏霏，风凛凛，玉郎何处狂饮。
醉时想得纵风流，罗帐香帷鸳寝。
春朝秋夜思君甚，愁见绣屏孤枕。
少年何事负初心，泪滴缕金双衽。','["1.双衽--双袖。"]',''),('huajianji-400','木兰花·小芙蓉','魏承班','huajianji','木兰花','','小芙蓉，香旖旎，碧玉堂深清似水。
闭宝匣，掩金铺，倚屏拖袖愁如醉。
迟迟好景烟花媚，曲渚鸳鸯眠锦翅。
凝然愁望静相思，一双笑靥嚬香蕊。','["1.旖旎--繁盛。","2.一双--笑靥：笑时面颊上的酒窝。","3.嚬--皱眉。","4.香蕊--酒窝上涂点的装饰物。"]',''),('huajianji-401','玉楼春·寂寂画堂梁上燕','魏承班','huajianji','玉楼春','','寂寂画堂梁上燕，高卷翠帘横数扇。
一庭春色恼人来，满地落花红几片。
愁倚锦屏低雪面，泪滴绣罗金缕线。
好天凉月尽伤心，为是玉郎长不见。','["1.横数扇--指打开数扇窗门。"]',''),('huajianji-402','玉楼春·轻敛翠蛾呈皓齿','魏承班','huajianji','玉楼春','','轻敛翠蛾呈皓齿，莺啭一枝花影里。
声声清迥遏行云，寂寂画梁尘暗起。
玉斝满斟情未已，促坐王孙公子醉。
春风筵上贯珠匀，艳色韶颜娇旖旎。','["1.莺啭--形容歌声如莺鸣百啭。","2.声声--清迥：清远。遏行云：阻遏行云，比喻歌声响亮美妙。","3.寂寂--形容歌声响亮震动画梁上的尘土。","4.玉斝--玉爵。古代酒器。","5.促坐--接近而坐。","6.贯珠匀--珠玉成串均匀，比喻歌声圆润。"]',''),('huajianji-403','诉衷情·高歌宴罢月初盈','魏承班','huajianji','诉衷情','','高歌宴罢月初盈，诗情引恨情。
烟露冷，水流轻，思想梦难成。
罗帐袅香平，恨频生。
思君无计睡还醒，隔层城。','["1.层城--古代传说昆仑山有层城九重，为大帝所居。这里比喻相隔遥远。"]',''),('huajianji-404','诉衷情·春深花簇小楼台','魏承班','huajianji','诉衷情','','春深花簇小楼台，风飘锦绣开。
新睡觉，步香阶，山枕印红腮。
鬓乱坠金钗，语檀偎。
临行执手重重嘱，几千回。','["1.锦绣开--这里指锦绣帘开。","2.语檀偎--亲昵而语。檀：即檀口，浅红的嘴唇。"]',''),('huajianji-405','诉衷情·银汉云晴玉漏长','魏承班','huajianji','诉衷情','','银汉云晴玉漏长，蛩声悄画堂。
筠簟冷，碧窗凉，红蜡泪飘香。
皓月泻寒光，割人肠。
那堪独自步池塘，对鸳鸯。','["1.筠簟--竹席。"]',''),('huajianji-406','诉衷情·金风轻透碧窗纱','魏承班','huajianji','诉衷情','','金风轻透碧窗纱，银釭焰影斜。
倚枕卧，恨何赊，山掩小屏霞。
云雨别吴娃，想容华。
梦成几度绕天涯，到君家。','["1.金风--秋风。","2.何赊--何多。","3.吴娃--吴地美女 。"]',''),('huajianji-407','诉衷情·春情满眼脸红绡','魏承班','huajianji','诉衷情','','春情满眼脸红绡，娇妒索人饶。
星靥小，玉珰摇，几共醉春朝。
别后忆纤腰，梦魂劳。
如今风叶又萧萧，恨迢迢。','["1.脸红绡--脸色红润如薄绸。","2.星靥--脸上的酒窝。","3.玉珰---玉耳珰。"]',''),('huajianji-408','生查子·烟雨晚晴天','魏承班','huajianji','生查子','','烟雨晚晴天，零落花无语。
难话此时心，梁燕双来去。
琴韵对薰风，有恨和情抚。
肠断断弦频，泪滴黄金缕。','["1.薰风--和风，初夏时的东南风。","2.黄金缕--衣上饰物。"]',''),('huajianji-409','生查子·寂寞画堂空','魏承班','huajianji','生查子','','寂寞画堂空，深夜垂罗幕。
灯暗锦屏欹，月冷珠帘薄。
愁恨梦难成，何处贪欢乐。
看看又春来，还是长萧索。','[]',''),('huajianji-410','黄钟乐·池塘烟暖草萋萋','魏承班','huajianji','黄钟乐','','池塘烟暖草萋萋。
惆怅闲宵，含恨愁坐，思堪迷。
遥想玉人情事远，音容浑似隔桃溪。
偏记同欢秋月低，帘外论心，花畔和醉，暗相携。
何事春来君不见，梦魂长在锦江西。','["1.浑似--全似。","2.论心--谈心。","3.锦江 --四川成都市南河，源自灌县岷江 。"]',''),('huajianji-411','渔歌子·柳如眉','魏承班','huajianji','渔歌子','','柳如眉，云似发。
姣绡雾縠笼香雪。
梦魂惊，钟漏歇，窗外晓莺残月。
几多情，无处说，落花飞絮清明节。
少年郎，容易别，一去音书断绝。','["1.蛟绡--鲛绡：即鲛绡，相传为鲛人所织的绡。雾縠：如薄雾的轻纱。香雪：形容人的肌肤美白。","2.容易别--草草别。"]',''),('huajianji-412','临江仙·金锁重门荒苑静','鹿虔扆','huajianji','临江仙','','金锁重门荒苑静，绮窗愁对秋空。
翠华一去寂无踪，玉楼歌吹，声断已随风。
烟月不知人事改，夜阑还照深宫。
藕花相向野塘中，暗伤亡国，清露泣香红。','["1.翠华--咏蜀国灭亡事。翠华：指蜀后主的仪仗。"]',''),('huajianji-413','临江仙·无赖晓莺惊梦断','鹿虔扆','huajianji','临江仙','','无赖晓莺惊梦断，起来残醉初醒。
映窗丝柳袅烟青，翠帘慵卷，约砌杏花零。
一自玉郎游冶去，莲凋月惨仪形。
暮天微雨洒闲庭，手挼裙带，无语倚云屏。','["1.无赖--无奈。","2.约砌--沿着台阶。","3.莲凋--莲凋月惨：如莲花凋谢，如月色惨淡，形容仪容。仪形：容仪形体。"]',''),('huajianji-414','女冠子·凤楼琪树','鹿虔扆','huajianji','女冠子','','凤楼琪树，惆怅刘郎一去，正春深。
洞里愁空结，人间信莫寻。
竹疏斋殿迥，松密醮坛阴。
倚云低首望，可知心。','["1.凤楼--凤楼：妇女居处。此处指女道士居处。琪树：树名。垂条如柳，结子如碧珠。","2.信莫寻--料想无法寻找。","3.迥--远。"]',''),('huajianji-415','女冠子·步虚坛上','鹿虔扆','huajianji','女冠子','','步虚坛上，绛节霓旌相向，引真仙。
玉佩摇蟾影，金炉袅麝烟。
露浓霜简湿，风紧羽衣偏。
欲留难得住，却归天。','["1.步虚坛--道士诵经坛。","2.绛节霓旌--这里指坛上招神的彩旗。","3.蟾影--月光。","4.霜简--此处指道士招神的符。","5.羽衣--道士服饰。"]',''),('huajianji-416','思越人·翠屏欹','鹿虔扆','huajianji','思越人','','翠屏欹，银烛背，漏残清夜迢迢。
双带绣窠盘锦荐，泪浸花暗香消。
珊瑚枕腻鸦鬟乱，玉纤慵整云散。
若是适来新梦见，离肠怎不千断。','["1.双带--绣窠：此处指双带上的彩绣花团 。锦荐：锦席。盘锦荐：曲折置于于锦席上。","2.拥鬟--黑色的鬟发。"]',''),('huajianji-417','虞美人·卷荷香淡浮烟渚','鹿虔扆','huajianji','虞美人','','卷荷香淡浮烟渚，绿嫩擎新雨。
绣窗疏透晓风情，象床珍簟冷光轻，水纹平。
九疑黛色屏斜掩，枕上眉心敛。
不堪相望病将成，钿昏檀粉泪纵横，不胜情。','["1.水纹--席上的纹。","2.九疑--九嶷，山名。此处指屏上所画。"]',''),('huajianji-418','虞美人·粉融红腻莲房绽','阎选','huajianji','虞美人','','粉融红腻莲房绽，脸动双波慢。
小鱼衔玉鬓钗横，石榴裙染象纱轻，转娉婷。
偷期锦浪荷深处，一梦云兼雨。
臂留檀印齿痕香，深秋不寐漏初长，尽思量。','["1.粉融--形容美人脸如莲花绽开。","2.脸动--双波：眼波。慢：漫，随便。","3.小鱼衔玉--指鱼形玉制钗饰。","4.偷期--暗自约会。"]',''),('huajianji-419','虞美人·楚腰蛴领团香玉','阎选','huajianji','虞美人','','楚腰蛴领团香玉，鬓叠深深绿。
月蛾星眼笑微嚬，柳妖桃艳不胜春，晚妆匀。
水纹簟青纱帐，雾罩秋波上。
一枝娇卧醉芙蓉，袅宵不得与君同，恨忡忡。','["1.楚腰--楚腰：细腰。蛴领：洁白的颈。香玉：形容肌肤柔美。","2.月蛾星眼--眉弯如月，眼亮如星。"]',''),('huajianji-420','临江仙·雨停荷芰逗浓香','阎选','huajianji','临江仙','','雨停荷芰逗浓香，岸边蝉噪垂杨。
物华空有旧池塘，不逢仙子，何处梦襄王。
珍簟对欹鸳枕冷，此来尘暗凄凉。
欲凭危槛恨偏长，藕花珠缀，犹似汗凝妆。','["1.逗--逗留。","2.物华--自然景色。","3.不逢--用宋玉《高唐赋》序中楚襄王梦神女事。","4.珠缀--露珠连缀。"]',''),('huajianji-421','临江仙·十二高峰天外寒','阎选','huajianji','临江仙','','十二高峰天外寒，竹梢轻拂仙坛。
宝衣行雨在云端，画帘深殿，香雾冷风残。
欲问楚王何处去？翠屏犹掩金鸾。
猿啼明月照空滩，孤舟行客，惊梦亦艰难。','["1.十二高峰--指巫山十二峰。","2.宝衣--用宋玉《高唐赋》序中巫山神女旦为朝云，暮为行雨”事。","3.楚王--用楚襄王梦神女事。"]',''),('huajianji-422','浣溪沙·寂寞流苏冷绣茵','阎选','huajianji','浣溪沙','','寂寞流苏冷绣茵，倚屏山枕惹香尘，小庭花露泣浓香。
刘阮信非仙洞客，嫦娥终是月中人，此生无路访东邻。','["1.刘阮--指刘晨、阮肇采药遇仙女事。信非：诚非。","2.东邻--代指美女 。典出司马相如《美人赋》：臣之东邻，有一女子”。"]',''),('huajianji-423','八拍蛮·云锁嫩黄烟柳细','阎选','huajianji','八拍蛮','','云锁嫩黄烟柳细，风吹红蒂雪梅残。
光景不胜闺阁恨，行行坐坐黛眉攒。','["1.行行坐坐--行坐不安。"]',''),('huajianji-424','八拍蛮·愁锁黛眉烟易惨','阎选','huajianji','八拍蛮','','愁锁黛眉烟易惨，泪飘红脸粉难匀。
憔悴不知缘底事，遇人推道不宜春。','["1.缘底事--缘何事。","2.推道--推说。"]',''),('huajianji-425','河传·秋雨','阎选','huajianji','河传','','秋雨，秋雨，无昼无夜，滴滴霏霏。
暗灯凉簟怨分离，妖姬，不胜悲。
西风稍急喧窗竹，停又续，腻脸悬双玉。
几回邀约雁来时，违期，雁归，人不归。','["1.妖姬--妖艳的女子。","2.双玉--双泪。"]',''),('huajianji-426','临江仙·一番荷芰生池沼','尹鹗 六首','huajianji','临江仙','','一番荷芰生池沼，槛前风送馨香。
昔年于此伴萧娘，相偎伫立，牵惹叙衷肠。
时逞笑容无限态，还如菡萏争芳。
别来虚遣思悠飏，慵窥往事，金锁小兰房。','["1.一番--一度。","2.萧娘--女子的泛称。"]',''),('huajianji-427','临江仙·深秋寒夜银河静','尹鹗 六首','huajianji','临江仙','','深秋寒夜银河静，月明深院中庭。
西窗幽梦等闲成，逡巡觉后，特地恨难平。
红烛半消残焰短，依稀暗背银屏。
枕前何事最伤情，梧桐叶上，点点露珠零。','["1.等闲--无端。","2.逡巡--逡巡：顷刻，不一会。觉后：醒来后。","3.特地--特别。"]',''),('huajianji-428','满宫花·月沉沉','尹鹗 六首','huajianji','满宫花','','月沉沉，人悄悄，一炷后庭香袅。
风流帝子不归来，满地禁花慵扫。
离恨多，相见少，何处醉迷三岛。
漏清宫树子规啼，愁锁碧窗春晓。','["1.帝子--此处指蜀宫妃子。","2.三岛--仙境，即三神山。"]',''),('huajianji-429','杏园芳·严妆嫩脸花明','尹鹗 六首','huajianji','杏园芳','','严妆嫩脸花明，教人见了关情。
含羞举步越罗轻，称娉婷。
终朝咫尺窥香阁，迢遥似隔层城。
何时休遣梦相萦，入云屏。','["1.娉婷--姿态美好。","2.终朝--终日。","3.隔层城--隔仙境，比喻难相见。"]',''),('huajianji-430','醉公子·暮烟笼藓砌','尹鹗 六首','huajianji','醉公子','','暮烟笼藓砌，戟门犹未闭。
尽日醉寻春，归来月满身。
离鞍偎绣袂，坠巾花乱缀。
何处恼佳人，檀痕衣上新。','["1.藓砌--有苔藓的台阶.","2.戟门--显贵家的门、门前立戟，故称。","3.绣袂--代指女子。","4.檀痕--唇红的痕迹。"]',''),('huajianji-431','菩萨蛮·陇云暗合秋天白','尹鹗 六首','huajianji','菩萨蛮','','陇云暗合秋天白，俯窗独坐窥烟陌。
楼际角重吹，黄昏方醉归。
荒唐难共语，明日还应去。
上马出门时，金鞭莫与伊。','["1.荒唐--行为放荡。"]',''),('huajianji-432','浣溪沙·春暮黄莺下砌前','毛熙震','huajianji','浣溪沙','','春暮黄莺下砌前，水晶帘影露珠悬，绮霞低映晚晴天。
弱柳万条垂翠带，残红落地碎香钿，蕙风飘荡散轻烟。','[]',''),('huajianji-433','浣溪沙·花榭香红烟景迷','毛熙震','huajianji','浣溪沙','','花榭香红烟景迷，满庭芳草绿萋萋，金铺闲掩绣帘低。
紫燕一双娇语碎，翠屏十二晚峰齐，梦魂消散醉空闺。','["1.十二晚峰--巫山十二峰。"]',''),('huajianji-434','浣溪沙·晚起红房醉欲消','毛熙震','huajianji','浣溪沙','','晚起红房醉欲消，绿鬟云散袅金翘，雪香花语不胜娇。
好是向人柔弱处，玉纤时急绣裙腰，春心牵惹转无聊。','["1.急--紧。"]',''),('huajianji-435','浣溪沙·一只横钗坠髻丛','毛熙震','huajianji','浣溪沙','','一只横钗坠髻丛，静眠珍簟起来慵，绣罗红嫩抹酥胸。
羞敛细蛾魂暗断，困迷无语思犹浓，小屏香霭碧山重。','["1.抹酥胸--即抹胸，胸间小衣。"]',''),('huajianji-436','浣溪沙·云薄罗裙绶带长','毛熙震','huajianji','浣溪沙','','云薄罗裙绶带长，满身新裛瑞龙香，翠钿斜映艳梅妆。
佯不觑人空婉约，笑和娇语太猖狂，忍教牵恨暗形相。','["1.满身裛--裛：熏染。","2.瑞龙香--龙脑香。","3.艳梅妆--即梅花妆。参见卷第四牛峤《酒泉子》注2。","4.婉约--娇羞的样子。"]',''),('huajianji-437','浣溪沙·碧玉冠轻袅燕钗','毛熙震','huajianji','浣溪沙','','碧玉冠轻袅燕钗，捧心无语步香阶，缓移弓底绣罗鞋。
暗想欢娱何计好，岂堪期约有时乖，日高深院正忘怀。','["1.捧心--双手抱着胸口。用西施捧心典故。","2.乖--背离。"]',''),('huajianji-438','浣溪沙·半醉凝情卧绣茵','毛熙震','huajianji','浣溪沙','','半醉凝情卧绣茵，睡容无力卸罗裙，玉笼鹦鹉厌听闻。
慵整落钗金翡翠，象梳欹鬓月生云，锦屏销幌麝烟熏。','["1.绣茵--绣褥。","2.象梳--象牙梳。"]',''),('huajianji-439','临江仙·南齐天子宠婵娟','毛熙震','huajianji','临江仙','','南齐天子宠婵娟，六宫罗绮三千。
潘妃娇艳独芳妍，椒房兰洞，云雨降神仙。
纵态迷欢心不足，风流可惜当年。
纤腰婉约步金莲，妖君倾国，犹自至今传。','["1.南齐--南齐天子：南齐废帝东昏侯。宠 婵娟：贪恋女色。","2.潘妃--东昏侯妃子。","3.椒房兰洞--此代指奢华的居处。","4.步金莲--《南齐书》载：东昏侯凿地为金莲花，使潘妃行其上，曰：“此步步生莲华也”。","5.妖君倾国--媚惑国君，使国家倾覆。"]',''),('huajianji-440','临江仙·幽闺欲曙闻莺啭','毛熙震','huajianji','临江仙','','幽闺欲曙闻莺啭，红窗月影微明。
好风频谢落花声，隔帷残烛，犹照绮屏筝。
绣被锦茵眠玉暖，炷香斜袅烟轻。
淡蛾羞敛不胜情，暗思闲梦，何处逐云行。','["1.眠玉--指美人睡态。"]',''),('huajianji-441','更漏子·秋色清','毛熙震','huajianji','更漏子','','秋色清，河影淡，深户烛寒光暗。
绡幌碧，锦衾红，博山香炷融。
更漏咽，蛩鸣切，满院霜华如雪。
新月上，薄云收，映帘悬玉钩。','["1.玉钩--弯月。"]',''),('huajianji-442','更漏子·烟月寒','毛熙震','huajianji','更漏子','','烟月寒，秋夜静，漏转金壶初永。
罗幕下，绣屏空，灯花结碎红。
人悄悄，愁无了，思梦不成难晓。
长忆得，与郎期，窃香私语时。','["1.初永--初长。天初转长。","2.窃香--指男女偷情 。用晋贾充之女以奇香私赠韩寿事。"]',''),('huajianji-443','女冠子·碧桃红杏','毛熙震','huajianji','女冠子','','碧桃红杏，迟日媚笼光影，彩霞深。
香暖熏莺语，风清引鹤音。
翠鬟冠玉叶，霓袖捧瑶琴。
应共吹箫侣，暗相寻。','["1.迟日--春日。","2.玉叶--女冠头上所属物。","3.霓袖--彩袖。","4.吹箫侣--用弄玉和萧史事。"]',''),('huajianji-444','女冠子·修蛾慢脸','毛熙震','huajianji','女冠子','','修蛾慢脸，不语檀心一点，小山妆。
蝉鬓低含绿，罗衣淡拂黄。
闷来深院里，闲步落花傍。
纤手轻轻整，玉炉香。','["1.修娥--修娥：长眉。慢脸：美丽的脸。慢：通曼”。","2.檀心--红唇。","3.小山妆--发髻高耸如小山。"]',''),('huajianji-445','清平乐·春光欲暮','毛熙震','huajianji','清平乐','','春光欲暮，寂寞闲庭户。
粉蝶双双穿槛舞，帘卷晚天疏雨。
含愁独倚闺帷，玉炉烟断香微。
正是销魂时节，东风满树花飞。','[]',''),('huajianji-446','南歌子·远山愁黛眉','毛熙震','huajianji','南歌子','','远山愁黛眉，横波慢脸明，腻香红玉茜罗轻。
深院晚堂人静，理银筝。
鬓动行云影，裙遮点屐声，娇羞爱问曲中名。
杨柳杏花时节，几多情？','["1.腻香--腻香红玉：香润红腻的肌肤。茜罗：绛色丝罗。"]',''),('huajianji-447','南歌子·惹恨还添恨','毛熙震','huajianji','南歌子','','惹恨还添恨，牵肠即断肠。
凝情不语一枝芳，独映画帘闲立，绣衣香。
暗想为云女，应怜傅粉郎。
晚来轻步出闺房，髻慢钗横无力，纵猖狂。','["1.为云女--用宋玉《高唐赋》序中巫山神女事。比喻所思美女 。","2.傅粉郎--魏何晏面白，魏明帝怀疑他傅粉。此处指情郎。","3.髻慢--发髻乱。"]',''),('huajianji-448','河满子·寂寞芳菲暗度','毛熙震','huajianji','河满子','','寂寞芳菲暗度，岁华如箭堪惊。
缅想旧欢多少事，转添春思难平。
曲槛丝垂金柳，小窗弦断银筝。
深院空闻燕语，满园闲落花轻。
一片相思休不得，忍教长日愁生。
谁见夕阳孤梦，觉来无限伤情。','["1.缅想--缅怀、追想。","2.长日愁生--终日生愁。","3.谁见--哪见。"]',''),('huajianji-449','河满子·无语残妆淡薄','毛熙震','huajianji','河满子','','无语残妆淡薄，含羞亸袂轻盈。
几度香闺眠过晓，绮窗疏日微明。
云母帐中偷惜，水晶枕上初惊。
笑靥嫩疑花坼，愁眉翠敛山横。
相望只教添怅恨，整鬟时见纤琼。
独倚朱扉闲立，谁知别有深情。','["1.亸袂--垂袖。","2.云母帐--以云母为饰的帐。云母：一种矿石。","3.纤琼--指佳人手指。"]',''),('huajianji-450','小重山·梁燕双飞画阁前','毛熙震','huajianji','小重山','','梁燕双飞画阁前，寂寥多少恨，懒孤眠。
晓来闲处想君怜，红罗帐，金鸭冷沉烟。
谁信损婵娟，倚屏啼玉箸，湿香钿。
四肢无力上秋千，群花谢，愁对艳阳天。','["1.损婵娟--损坏美好姿态。","2.玉箸--比喻眼泪。"]',''),('huajianji-451','定西番·苍翠浓阴满院','毛熙震','huajianji','定西番','','苍翠浓阴满院，莺对语，蝶交飞，戏蔷薇。
斜日倚栏风好，余香出绣衣。
未得玉郎消息，几时归。','["1.戏蔷薇--嘲弄蔷薇。此处以花比喻美人孤独。"]',''),('huajianji-452','木兰花·掩朱扉','毛熙震','huajianji','木兰花','','掩朱扉，钩翠箔，满院莺声春寂寞。
匀粉泪，恨檀郎，一去不归花又落。
对斜晖，临小阁，前事岂堪重想着。
金带冷，画屏幽，宝帐慵熏兰麝薄。','["1.翠箔--翠帘。","2.金带--指金带枕。"]',''),('huajianji-453','后庭花·莺啼燕语芳菲节','毛熙震','huajianji','后庭花','','莺啼燕语芳菲节，瑞庭花发。
昔时欢宴歌声揭，管弦清越。
自从陵谷追游歇，画梁尘黦。
伤心一片如圭月，闲锁宫阙。','["1.瑞庭--宫庭。","2.揭--揭调、高调。","3.陵谷--指地面高低形势的变动。比喻世事的变化。","4.尘黦--尘斑。","5.圭月--语出江 淹《别赋》：秋月如圭”。圭：长形玉版。"]',''),('huajianji-454','后庭花·轻盈舞妓含芳艳','毛熙震','huajianji','后庭花','','轻盈舞妓含芳艳，竞妆新脸。
步摇珠翠修蛾敛，腻鬟云染。
歌声慢发开檀点，绣衫斜掩。
时将纤手匀红脸，笑招金靥。','["1.步摇珠翠--首饰。","2.檀点--红唇一点。"]',''),('huajianji-455','后庭花·越罗小袖新香蒨','毛熙震','huajianji','后庭花','','越罗小袖新香蒨，薄笼金钏。
倚栏无语摇轻扇，半遮匀面。
春残日暖莺娇懒，满庭花片。
怎不教人长相见，画堂深院。','["1.蒨--蒨草，可以染绛色。此处形容衣色。"]',''),('huajianji-456','酒泉子·闲卧绣纬','毛熙震','huajianji','酒泉子','','闲卧绣纬，慵想万般情宠。
锦檀偏，翘股重，翠云欹。
暮天屏上春山碧，映香烟雾隔。
蕙兰心，魂梦役，敛蛾眉。','["1.锦檀--有锦套的檀木枕。","2.翘股--钗饰。","3.翠云--头发。","4.魂梦役--魂梦牵。"]',''),('huajianji-457','酒泉子·钿匣舞鸾','毛熙震','huajianji','酒泉子','','钿匣舞鸾，隐映艳红修碧。
月梳斜，云鬓腻，粉香寒。
晓花微敛轻呵展，袅钗金燕软。
日初升，帘半卷，对妆残。','["1.钿匣--钿匣：镜匣。舞鸾：镜中孤影。","2.呵展--用口嘘之。使舒展开。"]',''),('huajianji-458','菩萨蛮·梨花满院飘香雪','毛熙震','huajianji','菩萨蛮','','梨花满院飘香雪，高楼夜静风筝咽。
斜月照帘帷，忆君和梦稀。
小窗灯影背，燕语惊愁态。
屏掩断香飞，行云山外归。','["1.风筝--此处指风铃。","2.行云--写梦境。行云：比喻远行的情人 。"]',''),('huajianji-459','菩萨蛮·绣帘高轴临塘看','毛熙震','huajianji','菩萨蛮','','绣帘高轴临塘看，雨翻荷芰真珠散。
残暑晚初凉，轻风渡水香。
无聊悲往事，怎奈牵情思。
光景暗相催，等闲秋又来。','["1.高轴--高卷。","2.等闲--无端。"]',''),('huajianji-460','菩萨蛮·天含残碧融春色','毛熙震','huajianji','菩萨蛮','','天含残碧融春色，五陵薄幸无消息。
尽日掩朱门，离愁暗断魂。
莺啼芳树暖，燕拂回塘满。
寂寞对屏山，相思醉梦间。','["1.五陵--五陵：富贵家所居的地方。薄幸：浅薄轻浮，此指薄情郎。"]',''),('huajianji-461','浣溪沙·入夏偏宜淡薄妆','李珣','huajianji','浣溪沙','','入夏偏宜淡薄妆，越罗衣褪郁金黄，翠钿檀注助容光。
相见无言还有恨，几回拚却又思量，月窗香径梦悠飏。','["1.郁金黄--郁金香染成的黄色。","2.檀注--点红唇。","3.拚却--舍弃。"]',''),('huajianji-462','浣溪沙·晚出闲庭看海棠','李珣','huajianji','浣溪沙','','晚出闲庭看海棠，风流学得内家妆，小钗横戴一枝芳。
镂玉梳斜云鬓腻，缕金衣透雪肌香，暗思何事立残阳。','["1.内家妆--内宫妆，宫人妆。"]',''),('huajianji-463','浣溪沙·访旧伤离欲断魂','李珣','huajianji','浣溪沙','','访旧伤离欲断魂，无因重见玉楼人，六街微雨镂香尘。
早为不逢巫峡梦，那堪虚度锦江春，遇花倾酒莫辞频。','["1.六街--泛指繁华街市。","2.早为--早为：已是。巫峡梦：指楚襄王梦巫山神女事。"]',''),('huajianji-464','浣溪沙·红藕花香到槛频','李珣','huajianji','浣溪沙','','红藕花香到槛频，可堪闲忆似花人，旧欢如梦绝音尘。
翠叠画屏山隐隐，冷铺纹簟水潾潾，断魂何处一蝉新。','["1.水潾潾--此处形容簟席的水纹。"]',''),('huajianji-465','渔歌子·楚山青','李珣','huajianji','渔歌子','','楚山青，湘水绿，春风淡荡看不足。
草芊芊，花簇簇，渔艇棹歌相续。
信浮沉，无管束，钓回乘月归湾曲。
酒盈樽，云满屋，不见人间荣辱。','["1.信浮沉--任其浮沉。比喻人生的升降际遇。"]',''),('huajianji-466','渔歌子·荻花秋','李珣','huajianji','渔歌子','','荻花秋，潇湘夜，橘洲佳景如屏画。
碧烟中，明月下，小艇垂纶初罢。
水为乡，篷作舍，鱼羹稻饭常餐也。
酒盈杯，书满架，名利不将心挂。','["1.荻花--草名。","2.橘洲--又名橘子洲，因多橘而名。在湖南长沙湘江 中。","3.垂纶--垂下钓丝。"]',''),('huajianji-467','渔歌子·柳垂丝','李珣','huajianji','渔歌子','','柳垂丝，花满树，莺啼楚岸春山暮。
棹轻舟，出深浦，缓唱渔歌归去。
罢垂纶，还酌醑，孤村遥指云遮处。
下长汀，临浅渡，惊起一行沙鹭。','["1.酌醑--酌美酒。"]',''),('huajianji-468','渔歌子·九疑山','李珣','huajianji','渔歌子','','九疑山，三湘水，芦花时节秋风起。
水云间，山月里，棹月穿云游戏。
鼓清琴，倾绿蚁，扁舟自得逍遥志。
任东西，无定止，不议人间醒醉。','["1.九疑山--九嶷山。在今湖南宁远县南，相传虞舜葬于此。","2.三湘水--流经湖南的三条江 水。","3.绿蚁--洒上浮起绿色泡沫，代称酒。"]',''),('huajianji-469','巫山一段云·有客经巫峡','李珣','huajianji','巫山一段云','','有客经巫峡，停桡向水湄。
楚王曾此梦瑶姬，一梦杳无期。
尘暗珠帘卷，香消翠帷垂。
西风回首不胜悲，暮雨洒空祠。','["1.停桡--停桡：停桨。水湄：水岸。","2.空祠--指巫山神女祠。相传为楚怀王立，号为朝云。"]',''),('huajianji-470','巫山一段云·古庙依青嶂','李珣','huajianji','巫山一段云','','古庙依青嶂，行宫枕碧流。
水声山色锁妆楼，往事思悠悠。
云雨朝还暮，烟花春复秋。
啼猿何必近孤舟，行客自多愁。','["1.古庙--古庙：巫山神女庙。青峰：巫山十二峰。","2.行宫--这里指楚灵王游宴处，俗称细腰宫。","3.啼猿--巫峡多猿啼声。"]',''),('huajianji-471','临江仙·帘卷池心小阁虚','李珣','huajianji','临江仙','','帘卷池心小阁虚，暂凉闲步徐徐。
芰荷经雨半凋疏，拂堤垂柳，蝉噪夕阳余。
不语低鬟幽思远，玉钗斜坠双鱼。
几回偷看寄来书，离情别恨，相隔欲何如。','["1.双鱼--钗饰。"]',''),('huajianji-472','临江仙·莺报帘前暖日红','李珣','huajianji','临江仙','','莺报帘前暖日红，玉炉残麝犹浓。
起来闺思尚疏慵，别愁春梦，谁解此情悰。
强整娇姿临宝镜，小池一朵芙蓉。
旧欢无处再寻踪，更堪回顾，屏画九疑峰。','["1.情悰--情绪。","2.小池--小池：代指镜子。芙蓉：比喻佳人姿容美丽。"]',''),('huajianji-473','南乡子·烟漠漠','李珣','huajianji','南乡子','','烟漠漠，雨凄凄，岸花零落鹧鸪啼。
远客扁舟临野渡，思乡处，潮退水平春色暮。','[]',''),('huajianji-474','南乡子·兰棹举','李珣','huajianji','南乡子','','兰棹举，水纹开，竞携藤笼采莲来。
回塘深处遥相见，邀同宴，绿酒一卮红上面。','["1.一卮--一杯。卮：酒器。"]',''),('huajianji-475','南乡子·归路近','李珣','huajianji','南乡子','','归路近，扣舷歌，采真珠处水风多。
曲岸小桥山月过，烟深锁，豆蔻花垂千万朵。','["1.真珠--珍珠。蚌中所生。"]',''),('huajianji-476','南乡子·乘彩舫','李珣','huajianji','南乡子','','乘彩舫，过莲塘，棹歌惊起睡鸳鸯。
游女带香偎伴笑，争窈窕，竞折团荷遮晚照。','["1.窈窕--美好。"]',''),('huajianji-477','南乡子·倾绿蚁','李珣','huajianji','南乡子','','倾绿蚁，泛红螺，闲邀女伴簇笙歌。
避暑信船轻浪里，闲游戏，夹岸荔枝红蘸水。','["1.泛红螺--浮酒满杯。红螺：酒器。","2.蘸水--浸入水。"]',''),('huajianji-478','南乡子·云带雨','李珣','huajianji','南乡子','','云带雨，浪迎风，钓翁回棹碧湾中。
春酒香熟鲈鱼美，谁同醉？
缆却扁舟篷底睡。','["1.春酒--冬季酿制，及春而成的酒。"]',''),('huajianji-479','南乡子·沙月静','李珣','huajianji','南乡子','','沙月静，水烟轻，芰荷香里夜船行。
绿鬟红脸谁家女？
遥相顾，缓唱棹歌极浦去。','["1.缓唱--棹歌：以棹击节而歌。极浦：远浦。"]',''),('huajianji-480','南乡子·渔市散','李珣','huajianji','南乡子','','渔市散，渡船稀，越南云树望中微。
行客待湘天欲暮，送春浦，愁听猩猩啼瘴雨。','["1.越南--古百越之地。今闽、粤之地。","2.瘴雨--含瘴气的雨。瘴气：我国南部和西南部地区山林间湿热蒸发致人疾病的气。"]',''),('huajianji-481','南乡子·拢云髻','李珣','huajianji','南乡子','','拢云髻，背犀梳，焦红衫映绿罗裙。
越王台下春风暖，药盈岸，游赏每邀邻女伴。','["1.焦红--蕉红。深红色。","2.越王台--西汉南越王赵佗筑。在今广东越秀山上。"]',''),('huajianji-482','南乡子·相见处','李珣','huajianji','南乡子','','相见处，晚晴天，斜桐花下越台前。
暗里回眸深属意，遗双翠，骑象背人先过水。','["1.属意--心有所属。"]',''),('huajianji-483','女冠子·星高月午','李珣','huajianji','女冠子','','星高月午，丹桂青松深处。
醮坛开，金磬敲清露，珠幢立翠苔。
步虚声缥缈，想象思徘徊。
晓天归去路，指蓬莱。','["1.金磬--乐器。","2.珠幢--以珠为饰的旌旗。","3.步虚声--道士诵经的声音。"]',''),('huajianji-484','女冠子·春山夜静','李珣','huajianji','女冠子','','春山夜静，愁闻洞天疏磬。
玉堂虚，细雾垂珠佩，轻烟曳翠裙。
对花情脉脉，望月步徐徐。
刘阮今何处？绝来书。','["1.洞天--道家称仙人所居处。","2.玉堂--仙人所居。","3.刘阮--用刘晨、阮肇采药遇仙女事。"]',''),('huajianji-485','酒泉子·寂寞青楼','李珣','huajianji','酒泉子','','寂寞青楼，风触绣帘珠碎撼。
月朦胧，花暗淡，锁春愁。
寻想往事依稀梦，泪脸桃红色重。
鬓欹蝉。钗坠凤，思悠悠。','[]',''),('huajianji-486','酒泉子·雨渍花零','李珣','huajianji','酒泉子','','雨渍花零，红散香凋池两岸。
别情遥，春歌断，掩银屏。
孤帆早晚离三楚，闲理钿筝愁几许？
曲中情，弦上语，不堪听。','["1.雨渍--雨浸。","2.三楚--战国楚地。今黄淮至湖南一带。"]',''),('huajianji-487','酒泉子·秋雨联绵','李珣','huajianji','酒泉子','','秋雨联绵，声散败荷丛里。
那堪深夜枕前听，酒初醒。
牵愁惹思更无停，烛暗香凝天欲曙。
细和烟，冷和雨，透帘旌。','[]',''),('huajianji-488','酒泉子·秋月婵娟','李珣','huajianji','酒泉子','','秋月婵娟，皎洁碧纱窗外。
照花穿竹冷沉沉，印池心。
凝露滴，砌蛩吟，惊觉谢娘残梦。
夜深斜傍枕前来，影徘徊。','["1.影徘徊--指月影徘徊。"]',''),('huajianji-489','望远行·春日迟迟思寂寥','李珣','huajianji','望远行','','春日迟迟思寂寥，行客关山路遥。
琼窗时听语莺娇，柳丝牵恨一条条。
休晕绣，罢吹萧，貌逐残花暗凋。
同心犹结旧裙腰，忍辜风月度良宵。','["1.晕绣--用彩线绣成颜色凋和的花纹。","2.辜--辜负。"]',''),('huajianji-490','望远行·露滴幽庭落叶时','李珣','huajianji','望远行','','露滴幽庭落叶时，愁聚萧娘柳眉。
玉郎一去负佳期，水云迢递雁书迟。
屏半掩，枕斜欹，蜡泪无言对垂。
吟蛩断续漏频移，入窗明月鉴空帷。','["1.鉴空帷--照空帷。"]',''),('huajianji-491','菩萨蛮·回塘起波纹细','李珣','huajianji','菩萨蛮','','回塘起波纹细，剌桐花里门斜闭。
残日照平芜，双双飞鹧鸪。
征帆何处客，相见还相隔。
不语欲魂消，望中烟水遥。','["1.平芜--杂草繁茂的原野。"]',''),('huajianji-492','菩萨蛮·等闲将度三春景','李珣','huajianji','菩萨蛮','','等闲将度三春景，帘垂碧砌参差影。
曲槛日初斜，杜鹃啼落花。
恨君容易处，又话潇湘去。
凝思倚屏山，泪流红脸斑。','["1.等闲--平常，随便。","2.恨君”二句--怨恨你轻易说离别。潇湘：泛指湖南湘江 流域。"]',''),('huajianji-493','菩萨蛮·隔帘微雨双飞燕','李珣','huajianji','菩萨蛮','','隔帘微雨双飞燕，砌花零落红深浅。
捻得宝筝凋，心随征棹遥。
楚天云外路，动便经年去。
香断画屏深，旧欢何处寻。','["1.征棹--征人的船。","2.动--不觉，不经意。"]',''),('huajianji-494','西溪子·金缕翠钿浮动','李珣','huajianji','西溪子','','金缕翠钿浮动，妆罢小窗圆梦。
日高时，春已老，人来到，满地落花慵扫。
无语倚屏风，泣残红。','["1.圆梦--解说梦中事，从而附会人事，推测吉凶。"]',''),('huajianji-495','虞美人·金笼莺报天将曙','李珣','huajianji','虞美人','','金笼莺报天将曙，惊起分飞处。
夜来潜与玉郎期，多情不觉酒醒迟，失归期。
映花避月遥相送，腻髻偏凤。
欲回娇步入香闺，倚屏无语捻云篦，翠眉低。','["1.垂凤--风钗。"]',''),('huajianji-496','河传·去去','李珣','huajianji','河传','','去去，何处？迢迢巴楚，山水相连。
朝云暮雨，依旧十二峰前，猿声到客船。
愁肠岂异丁香结？因离别，故国音书绝。
想佳人花下，对明月春风，恨应同。','["1.巴楚--巴江 、楚江 。"]',''),('huajianji-497','河传·春暮','李珣','huajianji','河传','','春暮，微雨。送君南浦，愁敛双蛾。
落花深处，啼鸟似逐离散，粉檀珠泪和。
临流更把同心结，情哽咽，后会何时节？
不堪回首，相望已隔汀洲，檐声幽。','["1.送君南浦--江 淹《别赋》：送君南浦，伤如之何？”","2.粉檀--指傅面涂唇的化妆品。"]',''),('nantang-001','应天长·一钩初月临妆镜','李璟','nantang','应天长','','一钩初月临妆镜，蝉鬓凤钗慵不整。
重帘静，层楼迥，惆怅落花风不定。
柳堤芳草径，梦断辘轳金井。
昨夜更阑酒醒，春愁过却病。','["初月--新月，一说指愁眉。","蝉鬓--古代妇女的一种发式。两鬓薄如蝉翼，故称。凤钗：钗的一种，妇女的头饰。钗头如凤形，故名。慵不整：指无心梳洗。慵，形容懒散的样子。","重帘--层层帘幕。","迥--深远，遥远。","惆怅--因失意或失望而伤感、懊恼。","柳堤--植有柳树的堤岸。","辘轳--利用轮轴原理制成的井上汲水的起重装置，比喻心中情思如辘轳般反复上下。金井：井栏上有雕饰的井，一般用以指宫廷园林里的井。","更阑--夜深月残。","过却--超过，胜过。"]',''),('nantang-002','望远行·碧砌花光照眼','李璟','nantang','望远行','','碧砌花光照眼明，朱扉长日镇长扃。
馀寒欲去梦难成，炉香烟冷自亭亭。
辽阳月、秣陵砧，不传消息但传情。
黄金台下忽然惊，征人归日二毛生！','["朱扉--红漆门。（宋）柳永 《凤栖梧》词之三：“玉砌雕阑新月上，朱扉半掩人相望。”","镇--常；永久。（唐）褚亮《咏花烛》：“莫言春稍晚,自有镇开花。”","扃--关门。","辽阳--古称襄平、辽东城，位于辽宁省中部。曾为县名。今为市名。泛指今辽阳市一带地方。从公元前3世纪到17世纪，一直是中国东北地区的政治、经济、文化中心和交通枢纽，也是军事重镇。李善：“《汉书》曰：辽东郡有辽阳县。” （唐）沈佺期 《古意呈补阙乔知之》诗：“九月寒砧催木叶，十五征戍忆辽阳。”","秣陵--秦汉时期，今南京的称谓。","砧--捣衣声。（唐）刘沧《秋日山寺怀友人》：“月明遥听远村砧。”李白《子夜吴歌》：“长安一片月，万户捣衣声。秋风吹不尽，总是玉关情。何日平胡虏。良人罢远征。”李颀《诵魏万之京》：“关城树色催寒近，御苑砧声向晚多。”","二毛--指头发斑白。","征人--指出征或戍边的军人。（唐）苏拯 《古塞下》诗：“血染长城沙，马踏征人骨。”（唐）李益《夜上受降城闻笛》：“不知何处吹芦管，一夜征人尽望乡。”"]',''),('nantang-003','摊破浣溪沙·手卷真珠上玉钩','李璟','nantang','摊破浣溪沙','','手卷真珠上玉钩，依前春恨锁重楼。
风里落花谁是主？思悠悠。
青鸟不传云外信，丁香空结雨中愁。
回首绿波三楚暮，接天流。','["真珠--以珍珠编织之帘。或为帘之美称。《西京杂记》：“昭阳殿织珠为帘，风至则鸣，如珩佩之声”。玉钩：帘钩之美称。","依前--依然，依旧。春恨：犹春愁，春怨。锁：这里形容春恨笼罩。","悠悠--形容忧思不尽。","青鸟--传说曾为西王母传递消息给汉武帝。这里指带信的人。《史记·司马相如列传》：“幸有三足鸟为之使。”注：“三足鸟，青鸟也。主西王母取食。”云外：指遥远的地方。","丁香结--丁香的花蕾。此处诗人用以象征愁心。","三楚--指南楚、东楚、西楚。三楚地域，说法不一。这里用《汉书·高帝纪》注：江陵（今湖北江陵一带）为南楚。吴（今江苏吴县一带）为东楚。彭城（今江苏铜山县一带）为西楚。“三楚暮”，一作“三峡暮”。"]',''),('nantang-004','摊破浣溪沙·菡萏香销翠叶残','李璟','nantang','摊破浣溪沙','','菡萏香销翠叶残，西风愁起绿波间。
还与韶光共憔悴，不堪看！
细雨梦回鸡塞远，小楼吹彻玉笙寒。
多少泪珠无限恨，倚栏杆。','["菡萏--荷花的别称。","西风愁起--西风从绿波之间起来。以花叶凋零，故曰“愁起“。","鸡塞--《汉书·匈奴传》：“送单于出朔方鸡鹿塞。“颜师古注：”在朔方浑县西北。“今陕西省横山县西。《后汉书·和帝纪》：”窦宪出鸡鹿塞“，简称鸡塞。亦作鸡禄山。《花间集》卷八孙光宪《定西番》：”鸡禄山前游骑。“这里泛指边塞。","彻--大曲中的最后一遍。“吹彻“意谓吹到最后一曲。笙以吹久而含润，故云”寒“。元稹《连昌宫词》：”逡巡大遍凉州彻“，” 大遍“有几十段。后主《玉楼春》：”重按霓裳歌遍彻“，可以参证。玉笙寒：玉笙以铜质簧片发声，遇冷则音声不畅，需要加热，叫暖笙。","倚--明吕远本作“寄“，《读词偶得》曾采用之。但”寄“字虽好，文意比较晦，今仍从《花庵词选》与通行本、作“倚”。"]',''),('nantang-005','虞美人·春花秋月何时了','李煜','nantang','虞美人','','春花秋月何时了，往事知多少？
小楼昨夜又东风，故国不堪回首月明中。
雕栏玉砌应犹在，只是朱颜改。
问君能有几多愁？恰似一江春水向东流。','["了--了结，完结。","故国--指南唐故都金陵（今南京）。","砌--台阶。雕栏玉砌：指远在金陵的南唐故宫。应犹：一作“依然”。","朱颜改--指所怀念的人已衰老。朱颜，红颜，少女的代称，这里指南唐旧日的宫女。","君--作者自称。能：或作“都”“那”“还”“却”。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('nantang-006','乌夜啼·昨夜风兼雨','李煜','nantang','乌夜啼','','昨夜风兼雨，帘帏飒飒秋声。
烛残漏断频攲枕，起坐不能平。
世事漫随流水，算来一梦浮生。
醉乡路稳宜频到，此外不堪行。','["兼--同有，还有。","帘帏--帘子和帐子。帘，用布、竹、苇等做的遮蔽门窗的东西。帏，同帷，帐子，幔幕，一般用纱、布制成。","飒飒--象声词，这里形容风吹帘帏发出的声音。","烛残--蜡烛燃烧将尽。残，尽，竭。","漏断--漏壶中的水已经滴尽，表示时间已经很晚。漏，漏壶，为古代计时的器具，用铜制成。壶上下分好几层，上层底有小孔，可以滴水，层层下注，以底层蓄水多少计算时问。","频--时常，频繁。","欹枕--通彀，斜，倾斜。欹枕，头斜靠在枕头上。","平--指内心平静。","世事--指人世间的各种各样的事情。","漫--枉然，徒然。","浮生--指人生短促，世事虚浮不定。浮，这里为短暂、空虚之意。","醉乡--指人醉酒时神志不清的状态。","稳--平稳，稳当。宜，应当。","不堪行--不能行。堪，能够。"]',''),('nantang-007','一斛珠·晓妆初过','李煜','nantang','一斛珠','','晓妆初过，沈檀轻注些儿个。
向人微露丁香颗。
一曲清歌，暂引樱桃破。
罗袖裛残殷色可，杯深旋被香醪涴。
绣床斜凭娇无那。
烂嚼红茸，笑向檀郎唾。','["晓--《词谱》《古今词统》《花草粹编》《历代诗余》《全唐诗》《诗余图谱》等文本均作“晚”。沈际飞选评《草堂诗余》（古香岑四集本）中注：“一作晚，误。”晓，早晨。晓妆初过：指早晨起床刚刚梳洗打扮完毕。","沈檀--即“沉檀”。沈，《醉翁琴趣》外篇作“浓”。沉，带有润泽的深绛色。檀：浅绛色。沉檀：一种妇女妆饰用的颜料，唐、宋时妇女闺妆多用它，或用于眉端之间，或用于口唇之上。《花间集》阎选《虞美人》词中有“臂留檀印齿痕香”之句，毛熙震《后庭花》词中亦有“歌声慢发开檀点”之句，都是描绘以檀注唇的情形，这里也是。注：这里是点的意思。轻注：轻轻点画。些儿个：当时方言，意谓少许，一点点。","向--《醉翁琴趣》外篇中作“见”。人：吴本二主词、侯本二主词中缺字。丁：《花间集补》中误作“了”。丁香：常绿乔木，又名“鸡舌香”，“丁子香”，丁香子如钉，长三、四分，可以含于口中。古时用以代指女人的舌头。颗：指牙。丁香颗：这里指女人口内之牙，此句描绘歌女开口歌唱，舌齿微露，形容得意的神情。","清歌--清脆响亮的歌声。也指不用乐器伴奏的独唱。南朝宋谢灵运《拟魂太子“邺中集”诗·魏太子》中有句：“急弦动飞听，清歌拂梁尘。”","暂--《醉翁琴趣》外篇中作“渐”。引：使得。樱桃破：指女人张开娇小红润的口。樱桃，落叶乔木。果实多为红色，味道甜美或略带酸味。古人常用樱桃比喻女子口唇。白居易诗有“樱桃樊素口，杨柳小蛮腰。”唐李商隐《赠歌妓》诗之一：“红绽樱桃含白雪，断肠声里唱《阳关》。”唐韩偓《袅娜》诗云：“着词但见樱桃破，飞盏遥闻豆蔻香。”破，张开。此句描写歌女们张开红润小口歌唱的情形。","罗袖裛（yì）残殷色可--罗袖，质地较薄的丝衣的袖。裛，熏蒸，这里指香气。残，指香气消失殆尽。殷，深红色。可，意近“可可”，这里是模模糊糊、隐隐约约的意思。元稹《春》诗：“九霄浑可可，万姓尚忡忡。”此句说歌女的丝制的衣袖上的香气已经消失将尽，深红的颜色也只隐约可见了。","杯深旋（xuán）被香醪（láo）涴（wò）--杯深，指酒杯斟酒斟得很满，引申意谓酒喝得过量。旋，随即，很快地。香醪（láo），美酒，醇酒。本是一种汁滓混合的醇酒，味甜。涴（wò），沾污，污染。《醉翁琴趣》外篇中作“污”。","绣床--铺着织绣的床，这里指歌女的床。凭：倚靠，靠着。娇：《醉翁琴趣》外篇作“情”。娇无那（nuò）：这里是形容娇娜无比，不能自主的样子。无那，犹言无限，非常之意。","烂嚼（jiáo）红茸（róng）--烂嚼，细嚼。嚼，用牙齿磨碎食物。红茸，吕本二主词、吴讷《唐宋名贤百家词》本《尊前集》中均作“红绒”。即红绒，刺绣用的红色丝线。","檀郎--西晋文学人潘岳是个出名的美男子，小名檀奴，后世文人因以“檀郎”为妇女对夫婿或所爱的男子的美称。唾（tuò）：萧本二主词中作“吐”，误，“吐”与“唾”韵不同。唾，将口中含物吐出来。"]',''),('nantang-008','子夜歌·人生愁恨何能免','李煜','nantang','子夜歌','','人生愁恨何能免，销魂独我情何限。
故国梦重归，觉来双泪垂。
高楼谁与上？长记秋晴望。
往事已成空，还如一梦中。','["何能--怎能。何：什么时候。免：免去，免除，消除。","销魂--同“消魂”，谓灵魂离开肉体，这里用来形容哀愁到极点，好像魂魄离开了形体。独我：只有我。何限：即无限。","重归--《南唐书·后主书》注中作“初归”。全句意思是说，梦中又回到了故国。","觉来--醒来。觉：睡醒。垂：流而不落之态。","谁与--同谁。","长记--永远牢记。秋晴：晴朗的秋天。这里指过去秋游欢l青的景象。望：远望，眺望。","还如--仍然好像。还：仍然。"]',''),('nantang-009','临江仙·樱桃落尽春归去','李煜','nantang','临江仙','','樱桃落尽春归去，蝶翻轻粉双飞。
子规啼月小楼西。
玉钩罗幕，惆怅暮烟垂。
别巷寂寥人散后，望残烟草低迷。
炉香闲袅凤凰儿。
空持罗带，回首恨依依。','["樱桃--初夏时结果实，古代有帝王以樱桃献宗庙的传统。《礼记·月令》中记载：“仲夏之月，天子以含桃(樱桃)先荐寝庙。落尽：凋谢之意。","翻--翻飞。","金粉--妇女装饰用的铅粉，这里借指蝴蝶的翅膀。全句意谓蝴蝶翻飞着银灰色的翅膀双双飞舞。","子规--鸟名，即杜鹃鸟的别名。古代传说失国的蜀帝杜宇，被其臣相所逼，逊位后隐居山中，其魂化为杜鹃。又经常于夜间呜叫，令人生悲，故古人有“杜鹃啼血”之说。白居易《琵琶行》中有“其间旦暮闻何物?杜鹃啼血猿哀鸣”之句。","啼月--指子规在夜里啼叫。","寂寥--冷冷清清。","低迷--《古今词统》、《古今词话》、《历代诗余》等本中均作“凄迷”。低迷，模糊不清。","闲袅--形容细长柔软的东西随风轻轻摆动，这里指香烟缭绕悠闲而缓慢上升的样子。","凤凰儿--指绣有凤凰花饰的丝织品。这里指饰有凤凰图形的或制成风凰形状的香炉。","持--拿着。罗带：丝带。","恨依依--形容愁恨绵绵不断的样子。"]',''),('nantang-010','望江南·多少泪','李煜','nantang','望江南','','多少泪，断脸复横颐。
心事莫将和泪说，凤笙休向泪时吹。
肠断更无疑。','["断脸--《全唐诗》中作“沾袖”。意思是泪水流在脸上擦断了。断：擦断。颐（yí）：下巴。全句是说，泪水流在脸上擦断了，但又横挂在下巴上，形容眼泪纵横交流的状态。","心事--心中所思念或期望的事。唐刘皂《长门怨》诗之三：“旁人未必知心事，一面残妆空泪痕。”将：拿。和：《花草粹编》、吴讷本《尊前集》中均作“如”。说：《全唐诗》、《花草粹编》中均作“滴”。和泪说：一面流眼泪，一面述说。","凤笙--相传秦穆公时，萧史善吹箫，穆公女弄玉爱慕他，穆公便将弄玉许配给他。后弄玉学吹箫，其声清脆悦耳，引动了凤，夫妇遂驾凤飞去。汉应劭《风俗通·声音·笙》：“《世本》：‘随作笙。’长四寸、十二簧、像凤之身，正月之音也。”后因称笙为“凤笙”。唐韩愈《淮氏子》诗：“或云欲学吹凤笙，所慕灵妃媲萧史。”休：不要。向：朝着，在。泪时：伤心落泪之时。吹：吹奏。","肠断--形容极度悲伤痛苦。唐代白居易《长恨歌》有“行宫见月伤心色，夜雨闻铃肠断声”之句。更：愈发。","沾袖--（泪水）沾湿衣袖。","月明--月光明朗。唐白居易《崔十八新池》诗：“见底月明夜，无波风定时。”"]',''),('nantang-011','望江南·多少恨','李煜','nantang','望江南','','多少恨，昨夜梦魂中。
还似旧时游上苑，车如流水马如龙。
花月正春风。','["梦魂--古人认为在睡梦中人的灵魂会离开肉体，故称“梦魂”。唐代刘希夷《巫山怀古》中有句：“颓想卧瑶席，梦魂何翩翩。”","还似--《花间集补》中作“还是”。上苑：封建时代供帝王玩赏、打猎的园林。","车如流水马如龙--车子接连不断像流水一样驰过，马匹络绎不绝像一条龙一样走动。形容车马络绎不绝，十分繁华热闹。语出袁宏《后汉纪·孝章皇帝纪》：“建初二年（马）太后诏曰：‘吾万乘主，身服大练，食不求甘，左右旁人无香熏之饰，衣但布皇，如是者欲以身率服众也。……前过濯龙门，见外家车如流水马如龙。吾亦不谴怒之，但绝其岁用，冀以默愧其心。……’”","花月--花和月，泛指美好的景色。花月正春风，是形容春天鲜花怒放，春夜月光明朗，春风微拂的情景，描绘春光的明媚。"]',''),('nantang-012','清平乐·别来春半','李煜','nantang','清平乐','','别来春半，触目柔肠断。
砌下落梅如雪乱，拂了一身还满。
雁来音信无凭，路遥归梦难成。
离恨恰如春草，更行更远还生。','["春半--即半春，春天的一半。唐代柳宗元《柳州二日》诗中有句：“宦情羁思共凄凄，春半如秋意转迷“。别来春半，指自分别以来，春天已过去一半，说明时光过得很快。","柔--吕本二主词、吴本二主词、侯本二主词、《尊前集》、《全唐诗》、《词综》等本中均作“愁”。柔肠，原指温柔的心肠，此指绵软情怀。","砌下--台阶下。砌，台阶。落梅：指白梅花，开放较晚。全句意思，台阶下飘落的白梅花犹如雪片纷飞。","拂了一身还满--指把满身的落梅拂去了又落了满身。","雁来音信无凭--这句话是说鸿雁虽然来了，却没将书信传来。古代有凭借雁足传递书信的故事。《汉书·苏武传》中记载：“天子射上林中，得雁，足有系帛书。”故见雁就联想到了所思之人的音信。无凭：没有凭证，指没有书信。","遥--远。归梦难成：指有家难回。","恰如--正像。《全唐诗》、《古今词统》、《古今诗余醉》等本中均作”却如”；毛本《尊前集》中作“怯如”。","更行更远还生--更行更远，指行程越远。更，越。还生，还是生得很多。还，仍然，还是。"]',''),('nantang-013','采桑子·庭前春逐红英尽','李煜','nantang','采桑子','','庭前春逐红英尽，舞态徘徊。
细雨霏微，不放双眉时暂开。
绿窗冷静芳英断，香印成灰。
可奈情怀，欲睡朦胧入梦来。','["亭--侯本二主词、萧本二主词、吕本二主词、《花草粹编》、《尊前集》、《历代诗余》、《全唐诗》等本中均作“亭”。晨本二主词中作“庭”。逐：跟随。红英：红花。尽：完。全句意思是，春光随着红花的飘落而完结。","徘徊--这里形容回旋飞转的样子。","细--萧本二主词中作“零”；吕本二主词中此字空缺。霏微：《尊前集》中作“霏霏”；吴讷《唐宋名贤百家词》中误作“非非”。霏（fēi）微，雨雪细小，迷迷蒙蒙的样子。唐代李端《巫山高》中有诗云：“回合云藏日，霏微雨带风。”","不放双眉--就是紧锁双眉的意思。全句意思是，无法使双眉暂时展开。","芳音--晨本二主词中作“芳英”。吴讷《唐宋名贤百家词》本《尊前集》中作“芳春”。芳音，即佳音，好音。断：断绝。","香印成灰--指香烧成了灰烬。香印，即印香，打上印的香，用多种香料捣成末调和均匀制成的一种香。王建《香印》诗中有句：“闲坐印香烧，满户松柏气。”可见，“香印”与“印香”同义。古时富贵人家为使屋里气味芬芳，常常在室内燃香。成灰，成为灰烬。","可奈--《花草粹编》中作“可赖”；吴本二主词中误作“可奎”。可奈，怎奈，即无可奈何。情怀：心情，心境。唐代杜甫《北征》中有诗句：“老夫情怀恶，呕泄卧数日。”"]',''),('nantang-014','喜迁莺·晓月坠','李煜','nantang','喜迁莺','','晓月坠，宿烟微，无语枕频倾攲。
梦回芳草思依依，天远雁声稀。
啼莺散，馀花乱，寂寞画堂深院。
片红休扫尽从伊，留待舞人归。','["坠--落下。","微--疏淡。","欹--斜倚。","馀花--馀即余，残花。","埽--扫去。","尽从伊--这里指全由落花，任凭它飘落一地。"]',''),('nantang-015','蝶恋花·遥夜亭皋闲信步','李煜','nantang','蝶恋花','','遥夜亭皋闲信步。
乍过清明，早觉伤春暮。
数点雨声风约住，朦胧淡月云来去。
桃李依依春暗度。
谁在秋千，笑里低低语？
一片芳心千万绪，人间没个安排处。','["遥夜--长夜，深夜。亭皋（gāo）：水边的亭子。皋，水边地。信步：随意行走，漫步。","乍过--刚过，才过。一作“才过”。","渐觉--一作“早觉”。春暮：春日晚暮。","约--约束，约住。住：遮拦住。","澹月--不太明亮的月亮或月光。云来去：指云彩飘浮不定。","桃李--桃花和李花，一作“桃杏”。《诗·召南》中有：“何彼矣，华如桃李。”之句。后因以“桃李”形容人的容貌姣美。依依：形容鲜花盛开的样子。春暗度：指春光在不知不觉之中悄然而过。","秋千--运动和游戏用具，架子上系两根长绳，绳端拴一块板，人在板上前后摆动。","芳心--即花蕊。这里指女人的心。","安排--安置排解。"]',''),('nantang-016','相见欢·无言独上西楼','李煜','nantang','相见欢','','无言独上西楼，月如钩。
寂寞梧桐深院，锁清秋。
剪不断，理还乱，是离愁。
别是一般滋味，在心头。','["锁清秋--深深被秋色所笼罩。清秋，一作深秋。","剪--一作翦。","离愁--指去国之愁。","别是一般--另有一种意味。别是，一作别有。"]',''),('nantang-017','相见欢·林花谢了春红','李煜','nantang','相见欢','','林花谢了春红，太匆匆！
无奈朝来寒雨晚来风。
胭脂泪，留人醉，几时重？
自是人生长恨水长东！','["谢--凋谢。春红：春天的花朵。","匆匆--一作忽忽。","无奈--作常恨。","寒雨--一作寒重。","晚：一作晓。","胭脂泪--原指女子的眼泪，女子脸上搽有胭脂，泪水流经脸颊时沾上胭脂的红色，故云。在这里，胭脂是指林花着雨的鲜艳颜色，指代美好的花。胭脂，一作胭脂，又作燕支。","相留醉--一本作“留人醉”，意为令人陶醉。留，遗留，给以。醉，心醉。","几时重--何时再度相会。","自是--自然是，必然是。"]',''),('nantang-018','长相思·云一涡','李煜','nantang','长相思','','云一涡，玉一梭。
澹澹衫儿薄薄罗，轻颦双黛螺。
秋风多，雨相和。
帘外芭蕉三两窠。夜长人奈何？','["云--指妇女蓬卷如云的头发。","緺--《阳春白雪》、《浩然斋雅谈》中作“窝”；《乐府雅词》中作“〈髟上呙下〉”。一緺，即一束。一说緺，读为guā，意为青紫色的绶带（丝带）。这里指饰发用的紫青色丝带。元薛惠英《苏台竹枝词》中有句：“一凤髻绿如云，八字牙梳白似银。”","玉--这里指插在女子头上的玉簪。梭：萧本二主词中误作“梳”。梭，原是织布用的梭子，这里用以比喻玉簪。","淡淡--指衣裳的颜色轻淡。","衫儿--古代女子穿的短袖上衣，又称衫子或半衣。《龙洲词》、《龙洲集》、《阳春白雪》中均作“春衫”。吴讷《唐宋名贤百家词》本《龙洲词》中作“春山”。","薄薄--指衣裳的质料轻薄。","罗--丝罗，这里指用丝罗制成的裙子（下裳），即罗裙。","颦--皱眉。黛：古代妇女用来画眉的青黑色颜料。","黛螺--《龙洲集》中作“翠娥”。黛螺，又名黛子螺。古代女子画眉用的螺形黛黑，亦称螺黛。因其用来画眉，所以常用以作妇女眉毛的代称。","相--指雨声和风声，相互应和，交织一起。《古今词统》、《历代诗余》、《全唐诗》、《古今诗余醉》、《续选草堂诗余》中均作“如”。","帘--《龙洲集》、《龙洲词》、《阳春白雪》、《乐府雅词》中均作“窗”。","人--《龙洲词》、《龙洲集》中均作“争”。"]',''),('nantang-019','捣练子令·深院静','李煜','nantang','捣练子令','','深院静，小庭空，断续寒砧断续风。
无奈夜长人不寐，数声和月到帘栊。','["寒砧--砧，捣衣石，这里指捣衣声。古时将生丝织成的绢用木杵在石上捣软制成熟绢，以便裁制衣服。寒砧，因夜深天寒，故称。这里指寒夜之中的捣衣声。唐代杜甫《秋兴》中有诗句云：“寒衣处处催刀尺，白帝城高急暮砧。”","无奈--《啸余谱》、《尊前集》、《南词新谱》中作“早是”。","不寐--《啸余谱》、《尊前集》、《南词新谱》中均作“不寝”。不寐，不能入睡。","数声--几声，这里指捣衣的声音。","和月--伴随着月光。","到--传到。","帘栊--挂着竹帘的格子窗。栊：有横直格的窗子。"]',''),('nantang-020','浣溪沙·红日已高三丈透','李煜','nantang','浣溪沙','','红日已高三丈透，金炉次第添香兽。
红锦地依随步皱。
佳人舞点金钗溜，酒恶时拈花蕊嗅。
别殿遥闻箫鼓奏。','["红日--《诗话总龟》《西清诗话》《类说》《诗人玉屑》等本中均作“帘日”。三丈透：指太阳升起已有三丈多高，这里指太阳升起的高度，是虚数，不是实数。透，透过。","金炉--《诗话总龟》中作“佳人”。金炉，铜制的香炉。次第：依次。唐刘禹锡《秋江晚泊》诗中有“暮霞千万状，宾鸿次第飞”之句。香兽：以炭屑为末，匀和香料制成各种兽形的燃料。始用于晋代羊祜。《晋书·羊祜传》有记载。","红锦地衣--红色锦缎制成的地毯。地衣，古时铺在地上的纺织品，即地毯。随步皱：指金锦织成的地衣随人的舞步的移动而打皱，此用以形容舞女舞蹈时红锦地毯随着舞女旋转打皱的情形。皱，明刻本《类说》卷三十四误作“雏”。","佳人--美女，这里指善于起舞的宫女。汉司马相如《长门赋》中有句：“夫何一佳人兮，步逍遥以自虞；魂足逾佚而不反兮，形枯槁而独居？”舞点：萧本二主词作“舞急”；吕本二主词作“舞黠”；《诗话总龟》、《西清诗话》、诗人玉屑》中均作“舞彻”。舞点，按照音乐的节拍舞完了一支曲调。点，音乐的节拍。金钗溜：头上的金钗滑落了。金钗，又称金雀钗，古代妇女头饰的一种。溜，滑落。","酒恶时拈花蕊嗅--酒恶，《诗话总龟》中作“酒渥”。亦称“中酒”，指喝酒至微醉。这是当时方言。宋赵令《侯鲭录》卷八中云：“金陵人谓‘中酒’曰‘酒恶’，则知李后主诗云‘酒恶时拈花蕊嗅’，用乡人语也。”拈（niān），侯本二主词、吴本二主词中均作“沾”。《扪虱新语》中作“将”。时拈，常常拈取。花蕊，这里代指花朵。嗅，闻。","别殿--古代帝王所居正殿以外的宫殿。唐王勃《春思赋》中有句：“洛阳宫城纷合沓，离房别殿花周匝。”遥闻：《西清诗话》《类说》《扪虱新话》中引《古今诗话》《诗话总龟》《诗人玉屑》作“微闻”。箫鼓：箫与鼓，泛指乐奏。南朝梁江淹《别赋》中有句：“琴羽张兮箫鼓陈，燕赵歌兮伤美人。”箫，一种竹制管乐器。古代的箫用许多竹管排在一起做成，有底；现代的箫一般只用一根竹管制成，不封底，直吹。"]',''),('nantang-021','望江梅·闲梦远','李煜','nantang','望江梅','','闲梦远，南国正芳春。
船上管弦江面绿，满城飞絮滚轻尘。
忙杀看花人。
闲梦远，南国正清秋。
千里江山寒色暮，芦花深处泊孤舟。
笛在月明楼。','["望江南--此词调名一作“望江梅”，又作“忆江南”。李煜此词调名下共二首，《花草粹编》置于《望江南》下，未析为二首。《全唐诗》、《历代诗余》将此调下二首与《望江南》二首归为一调，计为四首。","闲梦远--闲，指囚禁中百无聊赖的生活和心情。梦远，指梦见遥远的地方，也指梦长。","南国--一般指长江以南的广大地区，这里指南唐国土。正芳春：正是春光明媚的时候。芳春：美好的春天。唐陈子昂《送东莱王学士无竞》有“孤松宜晚岁，众木爱芳春”句。","管弦--管乐器与弦乐器，也泛指乐器，这里指各种乐器共同演奏。江面绿：指春天里江水明彻而泛绿色。绿，也作“渌”，水清彻的样子。","飞絮--飞扬的柳絮。辊：有本作“滚”（gǔn），翻滚，滚动，转动。轻尘：指车马过后扬起的尘土。此句比喻柳絮像细微的尘土在空中地下翻滚。","忙杀--犹言忙死。杀：同“煞”，形容极甚。忙杀，《花草粹编》、《全唐诗》等本作“愁杀”。","清秋--天高气爽的秋天，指深秋。唐杜甫《宿府》有“清秋幕府井梧寒，独宿江城蜡炬残”句。","寒色--指自然景物在寒冷时节的颜色，即秋色。暮：萧本二主词等本中作“远”。","芦花--芦苇花絮。隋江总《赠贺左丞萧舍人》有“芦花霜外白，枫叶水前丹”句。泊：停泊，停放。","笛在月明楼--全句意谓笛声发自于月光照耀下的高楼。月明：月光明照。"]',''),('nantang-022','菩萨蛮·花明月暗笼轻雾','李煜','nantang','菩萨蛮','','花明月暗笼轻雾，今宵好向郎边去。
铲袜步香阶，手提金缕鞋。
画堂南畔见，一晌偎人颤。
奴为出来难，教郎恣意怜。','["暗--一作“黯”。","笼轻雾--笼罩着薄薄的晨雾。笼，一作“飞”；一作“水”。","今朝--今夜，一作“今宵”。郎边：一作“侬边”。","刬--《全唐诗》及《南唐书》中均作“衩”。刬，只，仅，犹言“光着”。刬袜，只穿着袜子着地。唐《醉公子》词中有：“刬袜下香阶，冤家今夜醉。”步：这里作动词用，意为走过。香阶：台阶的美称，即飘散香气的台阶。","手提--一作“手携”。金缕鞋：指鞋面用金线绣成的鞋。缕，线。","画堂--古代宫中绘饰华丽的殿堂，这里也泛指华丽的堂屋。南畔：南边。","一向--一作“一晌。”一向，同一晌，即一时，刹时间。偎：紧紧地贴着，紧挨着。一作“畏”。颤：由于心情激动而身体发抖。","奴--一作“好”。奴，古代妇女自称的谦词，也作奴家。出来：一作“去来”。","教君--让君，让你。一作“教郎”；一作“从君”。","恣意--任意，放纵。恣，放纵，无拘束。","怜--爱怜，疼爱。"]',''),('nantang-023','菩萨蛮·蓬莱院闭天台女','李煜','nantang','菩萨蛮','','蓬莱院闭天台女，画堂昼寝人无语。
抛枕翠云光，绣衣闻异香。
潜来珠琐动，惊觉银屏梦。
脸慢笑盈盈，相看无限情。','["蓬莱院--形容庭院幽美如蓬莱仙境一般。蓬莱：是古代传说中的三座仙山之一。据《史记·封禅书》中记载：“蓬莱、方丈、瀛洲，此三神山者其传在勃海中，去人不远，患且至，则船风引而去。盖尝有至者，诸仙人及不死之药皆在焉。”后就用蓬莱泛指人们想象中的美好的仙境。","天台女--本代指仙女，这里指像仙女一样美丽的女子。天台：山名，在浙江省天台县北。相传东汉时期刘晨、阮肇二人曾上天台山采药，遇见二位女子，留住半年回家，归家时发现已过了七世，乃知二女子为仙女。于是后人用“天台女”代指仙女。","画堂--本汉代宫中的殿堂，后用以泛指绘饰华丽的堂屋。","昼寝--白天睡觉。","抛枕--形容人熟睡时头离开了枕头，把它抛在一边。","翠云--形容女子的头发乌黑浓密。宋代柳永《洞仙歌》中有句：“记得翠云偷剪，和鸣彩凤于飞。”云：云髻，形容妇女的发髻乌黑卷曲如云的样子。","光--光亮。","异香--指女子身上散发出异乎寻常的香气。","潜来--偷偷地进来，暗中来。","珠锁--指用珍珠连缀而成或有珍珠镶饰的门环。门动时可以发出清脆悦耳的声音。","惊觉--惊醒。","银屏--指白色而有光泽的屏风或围屏。银屏梦：这里指好梦。","脸慢--脸慢，指细嫩而美丽的脸。慢：同“曼”，形容容颜的美好。","盈盈--形容仪态美好的样子。","相看--对看，仔细看。"]',''),('nantang-024','菩萨蛮·铜簧韵脆锵寒竹','李煜','nantang','菩萨蛮','','铜簧韵脆锵寒竹，新声慢奏移纤玉。
眼色暗相钩，秋波横欲流。
雨云深绣户，未便谐衷素。
宴罢又成空，魂迷春梦中。','["铜簧--乐器中的薄叶，用铜片制成，吹乐器时能够发出声响。韵脆：指吹奏出来的声音清越响亮。锵寒竹：竹制管乐器发出的锵然的声音。竹，指笛、箫、笙一类的乐器。锵，指乐器发出锵然的声响。寒竹，指箫笛乐器因久吹而含润变凉。","新声--指新制的乐曲或新颖美妙的声音。晋代陶潜《诸人共游周家墓柏下》中有句：“清歌散新声，绿酒开芳颜。”移纤玉；指白嫩纤细的手指在管弦乐器上移动弹奏。纤玉，比喻美女纤细洁白如玉的手指。","眼色--眼神，传情的目光。钩：同“勾”，招引。","秋波--《词林纪事》中作“娇波”。比喻美女的目光犹如秋水一样的清澈明亮。宋代苏轼《百步洪》中有诗句云：“佳人未肯回秋波，幼舆欲语防飞梭。”","雨云--降雨的云，这里比喻男女之间的欢情作爱。典故出自宋玉的《高唐赋》中。绣户：雕绘华美的庭户，这里指精美的居室。","来便--一作“未便”。此从《花间集补》、《全唐诗》、《词林万选》等本。便，立即。谐：谐和。衷素：内心的真情。素，通“愫”，本心、真情。","宴罢--欢乐之后。宴，指欢乐、快乐。","魂迷--吕本二主词、吴主二王词、侯本二主词、《花间集补》、《词林万选》、《历代诗余》、《全唐诗》、《词林纪事》本中均为“梦迷”。此从晨本二主词、萧本二主词、《花草粹编》本。春梦：吕本二主词中作“春雨”，注中为：“‘雨’一作‘睡’。《全唐诗》、《词林万选》、《历代诗余》、《词林纪事》、《花间集补》中均作“春睡”。此从吴本二主词、侯本二主词、晨本二主词、萧本二主词、《花草粹编》。"]',''),('nantang-025','阮郎归·呈郑王十二弟','李煜','nantang','阮郎归','','东风吹水日衔山，春来长是闲。
落花狼籍酒阑珊，笙歌醉梦间。
佩声悄，晚妆残，凭谁整翠鬟？
留连光景惜春颜，黄昏独倚栏。','["吹水--《乐府雅词》《近体乐府》《醉翁琴趣外篇》中均作“临水”。《阳春集》中“吹”下注云“别作‘临’。”日衔山：日落到了山后。衔，《花间集补》中误作“御”，包藏的意思。","是--《词谱》中作“自”。长是闲：总是闲。闲，无事，无聊。","落花--《阳春集》中作“林花”，注中云：“（林）别作‘落’。","狼藉--形容纵横散乱、乱七八糟的样子。","阑珊--衰落，将尽，残。","笙歌--合笙之歌。笙，管乐器名，用若干根长短不同的簧管制成，用口吹奏。","春睡觉--一作“佩声悄”。佩，即环佩，古人衣带上佩带的饰物。《墨子·辞过》中有句：“铸金以为钩，珠玉以为佩”。悄：声音低微。","晚妆残--天色已晚，晚妆因醉酒而不整。残，零乱不整。","凭谁--《古今词统》《词谱》《花间集补》《全唐诗》等本中均作“无人”。《阳春集》注中所云：“别作‘凭谁’。”整翠鬟：整理头发。翠鬟，女子环形的发式，绿色的发髻。翠，翡翠鸟，羽毛青绿色，尾短，捕食小鱼。鬟，古代妇女的一种环形发髻。《古今诗余醉》《醉翁琴趣外篇》中误作“环”。","留连光景--指珍惜时间。留连，留恋而舍不得离开。光景，时光。惜：四印斋所刻词本《阳春集》中作“喜”。其他本《阳春集》中均作“惜”。朱颜：美好红润的容颜，这里指青春。","独倚阑--独自倚靠栏杆。独，《古今词统》《花间集补》《草堂诗余》中均作“人”。"]',''),('nantang-026','浪淘沙·往事只堪哀','李煜','nantang','浪淘沙','','往事只堪哀，对景难排。
秋风庭院藓侵阶。
一任珠帘闲不卷，终日谁来？
金剑已沉埋，壮气蒿莱。
晚凉天净月华开。
想得玉楼瑶殿影，空照秦淮。','["藓侵阶--苔藓上阶，表明很少有人来。","一任--任凭。吴本、吕本、侯本《南唐二主词》、《花草粹编》作“一行”。《续选草堂诗余》、《古今词统》作“一片”。粟本《二主词》、《历代诗余》、《全唐诗》作“桁（héng）”。一桁：一列，一挂。如杜牧《十九兄郡楼有宴病不赴》：“燕子嗔重一桁帘。”","终日谁来--整天没有人来。","金锁--即铁锁，用三国时吴国用铁锁封江对抗晋军事。或以为“金锁”即“金琐”，指南唐旧日宫殿。也有人把“金锁”解为金线串制的铠甲，代表南唐对宋兵的抵抗。众说皆可通。锁：萧本、晨本《二主词》作“琐”。侯本《南唐二主词》、《花草粹编》、《词综》、《历代诗余》、《全唐诗》作“金剑”。《续选草堂诗余》、《古今词统》作“金敛”。《古今词统》并注：“敛，一作剑。”按：作敛不可解，盖承“金剑”而误。","已--《草堂诗余续集》、《古今词统》作“玉”。《古今词统》并注：“玉，一作已。","蒿莱--蒿莱，借指野草、杂草，这里用作动词，意为淹没野草之中，以此象征消沉，衰落。","净--吴讷《百家词》旧抄本、吕本、侯本、萧本《南唐二主词》、《花草粹编》、《词综》、《续集》、《词综》、《全唐诗》俱作“静”。","秦淮--即秦淮河。是长江下游流经今南京市区的一条支流。据说是秦始皇为疏通淮水而开凿的，故名秦淮。秦淮一直是南京的胜地，南唐时期两岸有舞馆歌楼，河中有画舫游船。"]',''),('nantang-027','采桑子·辘轳金井梧桐晚','李煜','nantang','采桑子','','辘轳金井梧桐晚，几树惊秋。
昼雨如愁，百尺虾须在玉钩。
琼窗梦断双蛾皱，回首边头。
欲寄鳞游，九曲寒波不溯流。','["辘轳--一种安在井上绞起汲水斗的器具，亦即汲取井水用的滑车。金井：井栏上有雕饰的井，这里指宫廷园林中的井。梧桐：一种落叶乔木，叶柄长，叶大，质地轻而韧。","几树--多少的树。树，这里指梧桐树。惊秋：《词林万选》中作“经秋”。有两种理解，一说吃惊秋天的到来，二说秋风惊动了梧桐树。","昼雨--指白天下的雨。昼，白天。新愁：指悲秋之愁。《词林万选》、《啸余谱》等本中均作“和愁”；《全唐诗》、《历代诗余》、《花间集补》、《古今词统》等本中均作“如愁”，《古今词统》注中云：“如”一作“和”。","百尺--这里为约指，极言其长。虾须：因帘子的表状像虾的触须，所以用“虾须”作为帘子的别称。《类编草堂诗余》注中云：“虾须，帘也。”玉钩：玉制的钩子。","琼窗--雕饰精美而华丽的窗。春断：《词林万选》中作“梦断”。春断，这里指情意断绝，即男女相爱之情断绝。春，指男女相爱之情。双蛾：《花草粹编》、《花间集补》等本中均作“双娥”。即指美女的两眉。蛾，蛾眉，指妇女长而美的眉。皱：起皱纹，指皱眉。","回首--回望。边头：指偏僻而遥远的地方。","欲--想要。寄：寄托。鳞游：游鱼，这里借指书信。古人有“鱼传尺素”之说，古乐府《饮马长城窟》中记载：“客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书。”后人遂以“双鲤”或“鱼信”代指书信。","九曲--形容黄河河道的迂回曲折，这里代指黄河。九，泛指多数。曲，萧本二主词中作“月”。","溯流--倒流。溯，同“溯”，逆流而上。"]',''),('nantang-028','虞美人·风回小院庭芜绿','李煜','nantang','虞美人','','风回小院庭芜绿，柳眼春相续。
凭栏半日独无言，依旧竹声新月似当年。
笙歌未散尊前在，池面冰初解。
烛明香暗画楼深，满鬓清霜残雪思难禁。','["风--指春风。庭芜：庭院里的草。","芜--丛生的杂草。","柳眼--早春时柳树初生的嫩叶，好像人的睡眼初展，故称柳眼。李商隐《二月二日》诗中有“花须柳眼多无赖，紫蝶黄蜂俱有情”之句。","春相续--一年又一年的春天继续来到人间。","凭阑--靠着栏杆。","竹声--竹制管乐器发出的声音。竹，古乐八晋之一，指竹制管乐器，箫、管、笙、笛之类。一说“竹声”为风吹竹叶之声。","笙歌--泛指奏乐唱歌，这里指乐曲。尊罍（léi）在：意谓酒席未散，还在继续。尊罍，一作“尊前”。","尊--酒杯","罍--一种酒器，小口大肚，有盖，上部有一对环耳，下部有一鼻可系。","池面冰初解--池水冰面初开，指时已初春。","烛明香暗--是指夜深之时。香，熏香。","画楼--一作“画歌”，一作“画阑”；一作“画堂”。指华丽而精美的君室。","深--一作“声”，指幽深。","清霜残雪--形容鬓发苍白，如同霜雪，谓年已衰老。","思难任：忧思令人难以承受，即指极度忧伤。思，忧思。难任，难以承受。任：读（rèn），一作“禁”。"]',''),('nantang-029','玉楼春·晚妆初了明肌雪','李煜','nantang','玉楼春','','晚妆初了明肌雪，春殿嫔娥鱼贯列。
笙箫吹断水云间，重按霓裳歌遍彻。
临春谁更飘香屑？醉拍栏杆情味切。
归时休放烛光红，待踏马啼清夜月。','["明肌雪--肌肤明洁，白滑似雪。韦庄《菩萨蛮》：”皓腕凝霜雪。”亦是用白雪形容肌肤清亮光洁。","嫔娥--宫中的姬妾与宫女。","鱼贯--游鱼先后接续．比喻一个挨一个地依序排列。","凤箫--凤凰箫。泛指管乐器。","水云--水和云。此指水云相接之处。","重按--一再按奏。","霓裳--《霓裳羽衣舞》的简称，唐代着名法曲。","歌遍彻--唱完大曲中的最后一曲。唐宋大曲系按一定顺序连接若干小曲而成，又称大遍。其中各小曲亦有称“遍”的。一说遍、彻都是称曲调中的名目。据王国维《宋元戏曲史》云：“彻者，如破之末一遍也。”","香屑--香粉，香的粉末。一说指花瓣，花的碎片。如许昂胃《词综偶评》：“疑指落花言之。”","阑干--栏杆。用竹、木、砖石或金属等构制而成，设于亭台楼阁或路边、水边等处作遮拦用。","情味--犹情趣。"]',''),('nantang-030','子夜歌·寻春须是先春早','李煜','nantang','子夜歌','','寻春须是先春早，看花莫待花枝老。
缥色玉柔擎，醅浮盏面清。
何妨频笑粲，禁苑春归晚。
同醉与闲评，诗随羯鼓成。','["先--《花草粹编》中作“阳”。这句意思是，要寻春就应该在春天到来之前。","看花莫待花枝老--意思是，欣赏花不要等到花已枯萎时再欣赏。","缥色玉柔擎--缥色，淡青色，青白色。这里指青白色的酒。玉柔，像玉一样洁白柔嫩，这里指女人洁白柔嫩的手。擎，往上托，上举。","醅浮盏面清--醅，没有过滤的酒，这里泛指酒。盏，酒杯。浮，这里指酒漫上杯口。清王国维辑本《南唐二主词》、吴讷《百家词》旧抄本中均空一格，根据吕远本、萧江声抄本《南唐二主词》、《历代诗余》本补“清”字。","何妨--王国维辑本《南唐二主词》中注云：“二字磨灭不可认，疑是‘何妨’二字。”萧本二主词，《历代诗余》中均作“何妨”。频笑粲（càn）：频频地欢笑。粲，笑貌，露齿而笑。又一说：粲，大笑的样子。《春秋谷梁传·昭公四年》中有句：“军人粲然皆笑。”范宁注云：“粲然，盛笑貌。”","禁苑--《历代诗余》中作“禁院”。禁苑是封建帝王的园林。禁，因帝王所居之处，戒备森严，禁止人们随便通行，所以称王宫为禁，称宫中为禁中。春归晚：指春天过去得比较晚。全句意思是，春天的景色有较长的时间可以供人们玩赏。","闲评--侯本二主词、吴本二主词、晨本二主词均作“闲评”。闲评，随意品评、议论，即没有固定题目的自由评论。","羯鼓--《历代诗余》中作“叠鼓”；吴本二主词中作“揭鼓”。是唐代很盛行的一种打击乐器，起源于印度，据说南北朝时从西域传入中国内地。《通典·乐四》中有记载：“羯鼓，正如漆桶，两头俱击。以出羯中，故号羯鼓，亦谓之两杖鼓。”羯，是中国古代少数民族之一，曾附属匈奴，此鼓因出于羯，所以称之为羯鼓。“诗随羯鼓成”，意思是，赋诗随羯鼓的敲击而完成，羯鼓一响赋诗开始，羯鼓一停，所赋之诗即成。历史上的李煜不但善词，而且能诗，《全唐诗》卷八中云：“煜，善属文，工书画，妙于音律。集十卷，诗一卷，失传。今存诗十八首。”"]',''),('nantang-031','谢新恩·秦楼不见吹箫女','李煜','nantang','谢新恩','','秦楼不见吹箫女，空馀上苑风光。
粉英含蕊自低昂。
东风恼我，才发一衿香。
琼窗梦醒留残日，当年得恨何长。
碧栏杆外映垂杨。
暂时相见，如梦懒思量。','["秦楼--秦穆公为其女弄玉所建之楼，亦名凤楼。相传秦穆公女弄玉，好乐。萧史善吹箫作凤鸣。秦穆公以弄玉妻之，为之作风楼。二人吹箫，凤凰来集，后乘凤，飞升而去。事见汉刘向《列仙传》。后人遂以“凤去楼空”指楼中人去、睹物思人。吹箫女：指秦弄玉。","上苑--指古代供帝王玩赏、打猎的园林。","粉英金蕊--粉红的鲜花，金嗽，此泛指各种颜色的花卉。低昂：起伏不定，时高时低。","一衿香--衿，同“襟”。是以人的感受说明香的程度。一般指不能指出形状的事物，类似的情况有：徐仲雅《赠齐己》：“骨瘦神清风一襟，松老霜天鹤病深。”吕岩《沁园春》：“有一襟风月，两袖云烟。”一说，堂后（北）叫背，堂前（南）叫襟，一襟香，指堂前一面有香。","琼窗--华美精致的窗子。梦醒：一本无“醒”字。","碧阑干--绿色栏杆。垂杨：垂柳。古诗文中杨、柳常通用。","思量（liáng）--想念，相思。"]',''),('nantang-032','谢新恩·樱花落尽阶前月','李煜','nantang','谢新恩','','樱花落尽阶前月，象床愁倚薰笼。
远似去年今日，恨还同。
双鬟不整云憔翠，泪沾红抹胸。
何处相思苦？纱窗醉梦中。','["樱花--指樱花树的花。樱花树是产于中国及日本的一种落叶乔木，品种甚多。花有白红等色，春天与叶同时开放，非常美丽。唐代李商隐《无题》诗中有句：“何处哀筝随急管，樱花永巷垂杨岸。”","象床--即象牙床，用象牙为饰的床。薰（xūn）笼：侯本二主词中作“熏笼”。薰，一种香草，也泛指花草香。薰笼，同熏笼，古代用以熏香、烘物和取暖用的炉子。《东宫旧事》中记载：“太子纳妃，有漆画手巾熏笼二，条被熏笼三，衣熏笼三。”","远似--吕本二主词、吴本二主词、侯本二主词、萧本二主词中均作“远是”。全句意思是，今日之恨与去年之恨一样。","双鬟--古代年轻妇女头上的两个环形发髻。云：本指天空中堆积的乌云，这里比喻轻柔舒卷如云的头发。憔悴：这里指头发枯干，没有光泽。","抹胸--俗称“兜肚”，古代内衣的一种，多为女子所用，有前片无后片，上可覆乳，下可遮肚，又称金诃子。《太真外传》中记载：“金诃子，抹胸也。”全句意思是，眼泪沾湿了胸前红色的抹胸。","何处--什么地方，哪里。","醉--吴本二主词中作“睡”。"]',''),('nantang-033','谢新恩·庭空客散人归后','李煜','nantang','谢新恩','','庭空客散人归后，画堂半掩珠帘。
林风淅淅夜厌厌。
小楼新月，回首自纤纤。
春光镇在人空老，新愁往恨何穷！
金窗力困起还慵。
一声羌笛，惊起醉怡容。','["归--离去。","珠帘--《全唐诗》中作“朱帘”。珠帘，以珍珠缀成的帘子。","淅淅-- 读（xīxī），指风声。","厌厌--漫长、久长的样子。南唐冯延巳《长相思》中有词句云：“红满枝，绿满枝，宿雨厌厌睡起迟。”《诗小雅·湛露》中云：“厌厌夜饮，不醉无归。”","纤纤--读（xiānxiān），小巧、尖细的样子。这里用来形容蛾眉似的新月的纤巧。南朝宋鲍照《玩月城西门廨中》中有诗句：“始见西南楼，纤纤如玉钩。”","镇在--长在，安在。镇，犹常，长久。唐太宗《咏烛》中有句：“镇下千行泪，非是为恩人。”","何穷--什么时候才是尽头，即无穷无尽的意思。","窗--《词谱》中作“刀”。金窗，又称黄金窗，宫廷中装饰华美的窗户。力困：力乏。","慵--《花草粹编》中误作“墉”，慵，懒。","羌笛--羌，中国古代少数民族之一，原住在以青海为中心，南至四川，北接新疆的一带地区。东汉时移居今甘肃一带。因其主要居于西北西南地区，又称西羌。据说笛为羌族乐器。东汉马融《笛赋》中所载：“近世双笛从羌起，羌人伐竹未及已。龙鸣水中不见已，截竹吹之声相似”。","醉怡容--酒醉以后脸上泛起红晕的容颜。怡，舒适愉快，喜悦的样子。"]',''),('nantang-034','谢新恩·樱花落尽春将困','李煜','nantang','谢新恩','','樱花落尽春将困，秋千架下归时。
漏暗斜月迟迟，花在枝。
□□□□□□□，□□□□□。
彻晓纱窗下，待来君不知。','["樱花--一作“樱桃”","漏暗--又疑是满阶","彻晓--通宵达旦。唐陆翱《宴赵氏北楼》诗：“本为愁人设，愁人彻晓愁。”"]',''),('nantang-035','谢新恩·冉冉秋光留不住','李煜','nantang','谢新恩','','冉冉秋光留不住，满阶红叶暮。
又是过重阳，台榭登临处。
茱萸香坠，紫菊气，飘庭户，晚烟笼细雨。
嗈嗈新雁咽寒声，愁恨年年长相侣。','["冉冉--读（rǎn），慢慢地、渐渐地，这里形容时光渐渐地流逝。秋光：秋天的时光。","红叶--枫、槭等树的叶子到秋天都变成了红色，统称红叶。这里指飘落的枯叶。","重阳--节日名。古人以九为阳数，因此农历九月初九称为“重九”或“重阳”。魏晋以后，习俗为这一天登高游宴。","台--高而上平的建筑物，供观察眺望用。榭（xiè）：建筑在高土台上的敞屋，多为游观之所。台榭，台和榭，也泛指楼台等建筑物。登临处：指登高望远的地方。","茱萸--读（zhū）（yú），植物名，香味浓烈，可入药。中国古代有在重阳节佩戴茱萸以去邪辟恶的风俗。王维《九月九日忆山东兄弟》中有句：“遥知兄弟登高处，遍插茱萸少一人。”香坠：装有香料的坠子。坠，一种从上下挂的装饰品。","紫菊气飘庭户--全句意思是，紫菊的香气飘散在庭户中。","笼--笼罩。","雝雝--雝，同鈤，鸟的和鸣声。咽寒声：咽，呜咽。寒声，战栗、悲凉的声音。","侣--一作“似”,《词律拾遗》、《历代诗余》中作“侣”。"]',''),('nantang-036','破阵子·四十年来家国','李煜','nantang','破阵子','','四十年来家国，三千里地山河。
凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈？
一旦归为臣虏，沈腰潘鬓销磨。
最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。','["四十年--南唐自建国至李煜作此词，为三十八年。此处四十年为概数。","凤阁--别作“凤阙”。凤阁龙楼指帝王能够居所。霄汉：天河。","玉树琼枝--别作“琼枝玉树”，形容树的美好。烟萝：形容树枝叶繁茂，如同笼罩着雾气。","识干戈--经历战争。识，别作“惯”。干戈：武器，此处指代战争。","潘鬓销磨--沈指沈约，《南史·沈约传》：“言已老病，百日数旬，革带常应移孔。”后用沈腰指代人日渐消瘦。潘指潘岳，潘岳曾在《秋兴赋》序中云：余春秋三十二，始见二毛。后以潘鬓指代中年白发。","辞庙--辞，离开。庙，宗庙，古代帝王供奉祖先牌位的地方。","犹奏--别作“独奏”。","垂泪--别作“挥泪”。"]',''),('nantang-037','浪淘沙令·帘外雨潺潺','李煜','nantang','浪淘沙令','','帘外雨潺潺，春意阑珊。
罗衾不耐五更寒。
梦里不知身是客，一晌贪欢。
独自莫凭栏，无限江山。
别时容易见时难。
流水落花春去也，天上人间','["潺潺--形容雨声。","阑珊--衰残。一作“将阑”。","罗衾--绸被子。不耐：受不了。一作“不暖”。","身是客--指被拘汴京，形同囚徒。","一晌--一会儿，片刻。一作“饷（xiǎng）”。","贪欢--指贪恋梦境中的欢乐。","凭栏--靠着栏杆。","江山--指南唐河山。"]',''),('nantang-038','浣溪沙·风压轻云贴水飞','李煜','nantang','浣溪沙','','风压轻云贴水飞，乍晴池馆燕争泥。
沈郎多病不胜衣。
沙上未闻鸿雁信，竹间时听鹧鸪啼。
此情唯有落花知。','["轻云--本指轻薄飘浮的白云。这里比喻柳絮。贴水：紧挨近水面。","乍晴--雨后初晴。乍：初，刚。池馆：池沼馆阁。这里主要指池沼。燕争泥：燕子趁着天晴衔泥筑巢。","沈郎--即沈约，字休文，南朝梁诗人。他在《与徐勉书》中说：“百日数旬，革带常应移孔。”意思是说因多病而腰围消瘦。后遂以“沈腰”作多病的代称。不胜衣：形容消瘦无力，连衣服的重量都难以承受。胜，承受。","沙上--指沙渚、沙滩之上。鸿雁信：古人有鸿雁传书的说法。《汉书·苏武传》：武帝时，苏武出使匈奴，被匈奴扣留，流于北海。昭帝即位，匈奴与汉和亲，汉请求匈奴归还苏武。匈奴诈言苏武已死。后汉派使者说天子射上林中，得雁，足有系帛书，说苏武等在某沼泽中。匈奴单于大惊，致歉汉使。","鹧鸪啼--鹧鸪鸟的叫声像“行不得也哥哥”，所以在外的游子听到鹧鸪的叫声会感到凑凉。鹧鸪，禽名，善啼。"]',''),('nantang-039','长相思·一重山','李煜','nantang','长相思','','一重山，两重山。
山远天高烟水寒，相思枫叶丹。
菊花开，菊花残。
寒雁高飞人未还，一帘风月闲。','["重--量词。层，道。","烟水--雾气蒙蒙的水面。唐代孟浩然《送袁十岭南寻弟》中有“苍梧白云远，烟水洞庭深。”诗句。","枫叶--枫树叶。枫，落叶乔木，春季开花，叶子掌状三裂。其叶经秋季而变为红色，因此称“丹枫”。古代诗文中常用枫叶形容秋色。丹：红色。","塞雁--塞外的鸿雁，也作“塞鸿”。塞雁春季北去，秋季南来，所以古人常以之作比，表示对远离故乡的亲人的思念。唐代白居易《赠江客》中有诗句：“江柳影寒新雨地，塞鸿声急欲霜天。”","帘--帷帐，帘幕。","风月--风声月色。"]',''),('nantang-040','柳枝·风情渐老见春羞','李煜','nantang','柳枝','','风情渐老见春羞，到处芳魂感旧游。
多谢长条似旧识，强垂烟穗拂人头。','["风情--风月之情，指男女相亲相爱之情，这里指好容貌。","羞--羞愧。","到处--随处，各处。","芳魂--指美人的魂魄。","旧游--以往游览所经之处。","长条--指柳树下垂的枝条。","似--好像。","强--勉强，强迫。","烟穗--形容柳树枝叶下垂为雾气笼罩的样子。穗：植物的花或果实聚生在茎的顶端，叫做穗。"]',''),('nantang-041','后庭花破子·玉树后庭前','李煜','nantang','后庭花破子','','玉树后庭前，瑶草妆镜边。
去年花不老，今年月又圆。
莫教偏，和月和花，大教长少年。','["title--此词作者有异议。从沈雄《古今词话》“词辨”云:“《后庭花破子》，李后主、冯延巳相率为之”，为李煜中、后期的作品。","玉树--神话传说中的仙树。《淮南子·地形训》中记载：“（昆仑）上有木禾，其修五寻。珠树、玉树、璇树、不死树在其西。”后庭：指后宫。","瑶草--《遗山乐府》中作“瑶华”。指传说中的香草。","偏--偏倚，偏失，指变化。","和月和花--《花草粹编》、《遗山乐府》中均作“和花和月”。和，共，同。","大教--唐圭璋《南唐二主词汇笺》中作“天教”。大，一定。教，令，使得。"]',''),('nantang-042','三台令·不寐倦长更','李煜','nantang','三台令','','不寐倦长更，披衣出户行。
月寒秋竹冷，风切夜窗声。','["不寐--不能入睡。","倦--懈怠。","长更--即更长。","切--急迫。","窗声--风吹在窗户上发出的声音。"]',''),('nantang-043','捣练子·云鬓乱','李煜','nantang','捣练子','','云鬓乱，晚妆残，带恨眉儿远岫攒。
斜托香腮春笋嫩，为谁和泪倚栏杆。','["云鬓--形容女子像乌云一般浓黑、秀美的鬓发。","远岫--远处的山峰。岫，山。","攒--簇聚，凑集。这里是指紧皱双眉。全句意思是，因愁带恨的双眉像远山一样聚在一起。","香腮--指美女的腮颊。春笋：春季的竹笋。这里指女子像春笋样纤润尖细的手指。","嫩--柔软纤细。","和--带，含。","阑干：同“栏干”。"]',''),('nantang-044','浣溪沙·转烛飘蓬一梦归','李煜','nantang','浣溪沙','','转烛飘蓬一梦归，欲寻陈迹怅人非。
天教心愿与身违。
待月池馆空逝水，映花楼阁谩斜晖。
登临不惜更沾衣。','["转烛--风吹烛火。这里用来比喻世事变幻莫测。唐代杜甫《佳人》中有“世情恶衰歇，万事随转烛。”之句。","飘蓬--飘动的蓬草，这里比喻人世沧桑，飘泊不定。蓬，蓬草，多年生草本植物，枯后根断，遇风飞旋，故又称飞蓬。","陈迹--过去事情遗留下来的痕迹。","怅--怅惘，不如意。","教--让，令。","待月--这里暗指夜深人静时情人私下约会。池台：池苑楼台。","逝水--逝去的流水，常用来比喻已过去的时间或事情。","荫花--《全唐诗》中作“映花。荫，隐藏，遮挡。","谩--同“漫”，弥漫。","斜晖--傍晚的光辉。南朝梁简文帝《序愁赋》中有句：“玩飞花之入户，看斜晖之度寮。”","沾--沾湿，浸润。"]',''),('nantang-045','渔父·浪花有意千里雪','李煜','nantang','渔父','','浪花有意千里雪，桃花无言一队春。
一壶酒，一竿身，快活如侬有几人。
一棹春风一叶舟，一纶茧缕一轻钩。
花满渚，酒满瓯，万顷波中得自由。','["浪花--一作“阆（láng）苑”，指传说中神仙居住的地方。","有意--一作“有情”。","千里--一作“千重”。","桃花--一作“桃李”。","一队春--指桃李盛开，由近及远，好像队列有序一样排列着。","一竿身--一根钓竿。身，一作“轮”，一作“鳞”。","快活--一作“世上”。","侬--我，江南口语。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('nalan-001','长相思·山一程','纳兰性德','nalan','','','山一程，水一程，身向榆关那畔行，夜深千帐灯
风一更，雪一更，聒碎乡心梦不成，故园无此声','',''),('nalan-002','木兰花令·拟古决绝词','纳兰性德','nalan','','','人生若只如初见，何事秋风悲画扇
等闲变却故人心，却道故心人易变
骊山语罢清宵半，泪雨霖铃终不怨
何如薄幸锦衣郎，比翼连枝当日愿','',''),('nalan-003','点绛唇·咏风兰','纳兰性德','nalan','','','别样幽芬，更无浓艳催开处
凌波欲去，且为东风住
忒煞萧疏，争奈秋如许
还留取，冷香半缕，第一湘江雨','',''),('nalan-004','画堂春·一生一代一双人','纳兰性德','nalan','','','一生一代一双人，争教两处销魂
相思相望不相亲，天为谁春
浆向蓝桥易乞，药成碧海难奔
若容相访饮牛津，相对忘贫','',''),('nalan-005','忆秦娥·长飘泊','纳兰性德','nalan','','','长飘泊，多愁多病心情恶
心情恶
模糊一片，强分哀乐
拟将欢笑排离索，镜中无奈颜非昨
颜非昨
才华尚浅，因何福薄','',''),('nalan-006','酒泉子·谢却荼蘼','纳兰性德','nalan','','','谢却荼蘼，一片月明如水
篆香消，犹未睡，早鸦啼
嫩寒无赖罗衣薄，休傍阑干角
最愁人，灯欲落，雁还飞','',''),('nalan-007','菩萨蛮·问君何事轻离别','纳兰性德','nalan','','','问君何事轻离别，一年能几团圆月
杨柳乍如丝
故园春尽时
春归归不得，两桨松花隔
旧事逐寒潮，啼鹃恨未消','',''),('nalan-008','生查子·东风不解愁','纳兰性德','nalan','','','东风不解愁，偷展湘裙衩
独夜背纱笼，影着纤腰画
爇尽水沉烟，露滴鸳鸯瓦
花骨冷宜香，小立樱桃下','',''),('nalan-009','浣溪沙·谁念西风独自凉','纳兰性德','nalan','','','谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳
被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常','',''),('nalan-010','浣溪沙·郊游联句','纳兰性德','nalan','','','出郭寻春春已阑(陈维崧)，东风吹面不成寒(秦松龄)，青村几曲到西山(严绳孙)
并马未须愁路远(姜宸英)，看花且莫放杯闲(朱彝尊)，人生别易会常难(纳兰性德)','',''),('nalan-011','采桑子·谁翻乐府凄凉曲','纳兰性德','nalan','','','谁翻乐府凄凉曲
风也萧萧，雨也萧萧，瘦尽灯花又一宵
不知何事萦怀抱，醒也无聊，醉也无聊，梦也何曾到谢桥','',''),('nalan-012','生查子·短焰剔残花','纳兰性德','nalan','','','短焰剔残花，夜久边声寂
倦舞却闻鸡，暗觉青绫湿
天水接冥蒙，一角西南白
欲渡浣花溪，远梦轻无力','',''),('nalan-013','生查子·惆怅彩云飞','纳兰性德','nalan','','','惆怅彩云飞，碧落知何许
不见合欢花，空倚相思树
总是别时情，那待分明语
判得最长宵，数尽厌厌雨','',''),('nalan-014','浣溪沙·庚申除夜','纳兰性德','nalan','','','收取闲心冷处浓，舞裙犹忆柘枝红
谁家刻烛待春风
竹叶樽空翻采燕，九枝灯灺颤金虫
风流端合倚天公','',''),('nalan-015','江城子·咏史','纳兰性德','nalan','','','湿云全压数峰低
影凄迷，望中疑
非雾非烟，神女欲来时、若问生涯原是梦，除梦里，没人知','',''),('nalan-016','点绛唇·一种蛾眉','纳兰性德','nalan','','','一种蛾眉，下弦不似初弦好
庾郎未老，何事伤心早
素壁斜辉，竹影横窗扫
空房悄，乌啼欲晓，又下西楼了','',''),('nalan-017','青衫湿·悼亡','纳兰性德','nalan','','','近来无限伤心事，谁与话长更
从教分付，绿窗红泪，早雁初莺
当时领略，而今断送，总负多情
忽疑君到，漆灯风飐，痴数春星','',''),('nalan-018','摊破浣溪沙·葬名花','纳兰性德','nalan','','','林下荒苔道韫家，生怜玉骨委尘沙
愁向风前无处说，数归鸦
半世浮萍随逝水，一宵冷雨葬名花
魂是柳绵吹欲碎，绕天涯','',''),('nalan-019','点绛唇·五夜光寒','纳兰性德','nalan','','','五夜光寒，照来积雪平于栈
西风何限，自起披衣看
对此茫茫，不觉成长叹
何时旦，晓星欲散，飞起平沙雁','',''),('nalan-020','浣溪沙·欲问江梅瘦几分','纳兰性德','nalan','','','欲问江梅瘦几分，只看愁损翠罗裙
麝篝衾冷惜余熏
可耐暮寒长倚竹，便教春好不开门
枇杷花底校书人','',''),('nalan-021','浣溪沙·脂粉塘空遍绿苔','纳兰性德','nalan','','','脂粉塘空遍绿苔
掠泥营垒燕相催
妒他飞去却飞回
一骑近从梅里过，片帆遥自藕溪来
博山香烬未全灰','',''),('nalan-022','梦江南·昏鸦尽','纳兰性德','nalan','','','昏鸦尽，小立恨因谁
急雪乍翻香阁絮，轻风吹到胆瓶梅，心字已成灰','',''),('nalan-023','赤枣子·惊晓漏','纳兰性德','nalan','','','惊晓漏，护春眠
格外娇慵只自怜
寄语酿花风日好，绿窗来与上琴弦','',''),('nalan-024','浣溪沙·残雪凝辉冷画屏','纳兰性德','nalan','','','残雪凝辉冷画屏，落梅横笛已三更，更无人处月胧明
我是人间惆怅客，知君何事泪纵横，断肠声里忆平生','',''),('nalan-025','忆王孙·西风一夜剪芭蕉','纳兰性德','nalan','','','西风一夜剪芭蕉，倦眼经秋耐寂寥
强把心情付浊醪
读《离骚》
愁似湘江日夜潮','',''),('nalan-026','生查子·散帙坐凝尘','纳兰性德','nalan','','','散帙坐凝尘，吹气幽兰并
茶名龙凤团，香字鸳鸯饼
玉局类弹棋，颠倒双栖影
花月不曾闲，莫放相思醒','',''),('nalan-027','浣溪沙·一半残阳下小楼','纳兰性德','nalan','','','一半残阳下小楼，朱帘斜控软金钩
倚阑无绪不能愁
有个盈盈骑马过，薄妆浅黛亦风流
见人羞涩却回头','',''),('nalan-028','浣溪沙·睡起惺忪强自支','纳兰性德','nalan','','','睡起惺忪强自支
绿倾蝉鬓下帘时
夜来愁损小腰肢
远信不归空伫望，幽期细数却参差
更兼何事耐寻思','',''),('nalan-029','浣溪沙·凤髻抛残秋草生','纳兰性德','nalan','','','凤髻抛残秋草生
高梧湿月冷无声
当时七夕记深盟
信得羽衣传钿合，悔教罗袜葬倾城
人间空唱雨淋铃
','',''),('nalan-030','如梦令·正是辘轳金井','纳兰性德','nalan','','','正是辘轳金井，满砌落花红冷
蓦地一相逢，心事眼波难定
谁省，谁省
从此簟纹灯影','',''),('nalan-031','如梦令·纤月黄昏庭院','纳兰性德','nalan','','','纤月黄昏庭院，语密翻教醉浅
知否那人心
旧恨新欢相半
谁见
谁见
珊枕泪痕红泫','',''),('nalan-032','采桑子·彤霞久绝飞琼字','纳兰性德','nalan','','','彤霞久绝飞琼字，人在谁边
人在谁边，今夜玉清眠不眠
香销被冷残灯灭，静数秋天
静数秋天，又误心期到下弦','',''),('nalan-033','好事近·何路向家园','纳兰性德','nalan','','','何路向家园，历历残山剩水
都把一春冷淡，到麦秋天气
料应重发隔年花，莫问花前事
纵使东风依旧，怕红颜不似','',''),('nalan-034','忆秦娥·春深浅','纳兰性德','nalan','','','春深浅，一痕摇漾青如剪
青如剪
鹭鸶立处，烟芜平远
吹开吹谢东风倦，缃桃自惜红颜变
红颜变
兔葵燕麦，重来相见
','',''),('nalan-035','忆秦娥·山重叠','纳兰性德','nalan','','','山重叠
悬崖一线天疑裂
天疑裂
断碑题字，苔痕横啮
风声雷动鸣金铁
阴森潭底蛟龙窟
蛟龙窟
兴亡满眼，旧时明月','',''),('nalan-036','眼儿媚·咏梅','纳兰性德','nalan','','','莫把琼花比澹妆，谁似白霓裳
别样清幽，自然标格，莫近东墙
冰肌玉骨天分付，兼付与凄凉
可怜遥夜，冷烟和月，疏影横窗','',''),('nalan-037','眼儿媚·重见星娥碧海槎','纳兰性德','nalan','','','重见星娥碧海槎，忍笑却盘鸦
寻常多少，月明风细，今夜偏佳
休笼彩笔闲书字，街鼓巳三挝
烟丝欲袅，露光微泫，春在桃花','',''),('nalan-038','眼儿媚·独倚春寒掩夕扉','纳兰性德','nalan','','','独倚春寒掩夕扉，清露泣铢衣
玉萧吹梦，金钗划影，悔不同携
刻残红烛曾相待，旧事总依稀
料应遗恨，月中教去，花底催归','',''),('nalan-039','摊破浣溪沙·欲语心情梦已阑','纳兰性德','nalan','','','欲语心情梦已阑，镜中依约见春山
方悔从前真草草，等闲看
环佩只应归月下，钗钿何意寄人间
多少滴残红蜡泪，几时干','',''),('nalan-040','摊破浣溪沙·一霎灯前醉不醒','纳兰性德','nalan','','','一霎灯前醉不醒，恨如春梦畏分明
淡月淡云窗外雨，一声声
人道情多情转薄，而今真个不多情
又听鹧鸪啼遍了，短长亭','',''),('nalan-041','太常引·自题小照','纳兰性德','nalan','','','西风乍起峭寒生，惊雁避移营
千里暮云平，休回首、长亭短亭
无穷山色，无边往事，一例冷清清
试倩玉萧声，唤千古、英雄梦醒','',''),('nalan-042','生查子·鞭影落春堤','纳兰性德','nalan','','','鞭影落春堤，绿锦鄣泥卷
脉脉逗菱丝，嫩水吴姬眼
啮膝带香归，谁整樱桃宴
蜡泪恼东风，旧垒眠新燕','',''),('nalan-043','浣溪沙·万里阴山万里沙','纳兰性德','nalan','','','万里阴山万里沙
谁将绿鬓斗霜华
年来强半在天涯
魂梦不离金屈戌，画图亲展玉鸦叉
生怜瘦减一分花','',''),('nalan-044','浣溪沙·姜女庙','纳兰性德','nalan','','','海色残阳影断霓，寒涛日夜女郎祠
翠钿尘网上蛛丝
澄海楼高空极目，望夫石在且留题
六王如梦祖龙非','',''),('nalan-045','减字木兰花·相逢不语','纳兰性德','nalan','','','相逢不语，一朵芙蓉着秋雨
小晕红潮，斜溜鬟心只凤翘
待将低唤，直为凝情恐人见
欲诉幽怀，转过回阑叩玉钗','',''),('nalan-046','采桑子·当时错','纳兰性德','nalan','','','而今才道当时错，心绪凄迷
红泪偷垂，满眼春风百事非
情知此后来无计，强说欢期
一别如斯，落尽梨花月又西','',''),('nalan-047','采桑子·梦一场','纳兰性德','nalan','','','谢家庭院残更立，燕宿雕梁
月度银墙，不辨花丛哪瓣香
此情已自成追忆，零落鸳鸯
雨歇微凉，十一年前梦一场！','',''),('nalan-048','采桑子·拨灯书尽红笺也','纳兰性德','nalan','','','拨灯书尽红笺也，依旧无聊
玉漏迢迢，梦里寒花隔玉箫
几竿修竹三更雨，叶叶萧萧
