湔裙梦断续应难
西风多少恨，吹不散眉弯','',''),('nalan-097','沁园春·瞬息浮生','纳兰性德','nalan','','','丁巳重阳前三日，梦亡妇淡妆素服，执手硬咽
语多不复能
但临别有云：“衔恨愿为天上月，年年犹得向郎圆”
妇素未工诗，不知何以得此也
觉后感赋长调:
瞬息浮生，薄命如斯，低徊怎忘？
记绣榻闲时，并吹红雨，雕阑曲处，同倚斜阳。
梦好难留，诗残莫续，赢得更深哭一场。
遗容在，只灵飙一转，未许端详。
重寻碧落茫茫，料短发，朝来定有霜。
便人间天上，尘缘未断，春花秋叶，触绪还伤。
欲结绸缪，翻惊摇落，减尽荀衣昨日香。
真无奈，倩声声邻笛，谱出回肠。','',''),('nalan-098','浣溪沙·古北口','纳兰性德','nalan','','','杨柳千条送马蹄，北来征雁旧南飞
