凭高目断征途，暮云千里平芜
日夜河流东下，锦书应托双鱼','',''),('nalan-100','满庭芳·堠雪翻鸦','纳兰性德','nalan','','','堠雪翻鸦，河冰跃马，惊风吹度龙堆
阴磷夜泣，此景总堪悲
