暗思何事断人肠
曾是向他春梦里，瞥遇回廊
','',''),('nalan-106','菩萨蛮·朔风吹散三更雪','纳兰性德','nalan','','','朔风吹散三更雪，倩魂犹恋桃花月
梦好莫催醒，由他好处行
无端听画角，枕畔红冰薄
塞马一声嘶，残星拂大旗','',''),('nalan-107','鹧鸪天·背立盈盈故作羞','纳兰性德','nalan','','','背立盈盈故作羞，手挼梅蕊打肩头
欲将离恨寻郎说，待得郎来恨却休
云淡淡，水悠悠
一声横笛锁空楼
何时共泛春溪月，断岸垂杨一叶舟','',''),('nalan-108','虞美人·残灯风灭炉烟冷','纳兰性德','nalan','','','残灯风灭炉烟冷，相伴唯孤影
判教狼藉醉清樽，为问世间醒眼是何人
难逢易散花间酒，饮罢空搔首
闲愁总付醉来眠，只恐醒时依旧到樽前
','',''),('nalan-109','渔父·收却纶竿落照红','纳兰性德','nalan','','','收却纶竿落照红，秋风宁为翦芙蓉
人淡淡，水蒙蒙，吹入芦花短笛中','',''),('nalan-110','浣溪沙·消息谁传到拒霜','纳兰性德','nalan','','','消息谁传到拒霜
两行斜雁碧天长
晚秋风景倍凄凉
银蒜押帘人寂寂，玉钗敲竹信茫茫
黄花开也近重阳
','',''),('nalan-111','天仙子·月落城乌啼未了','纳兰性德','nalan','','','月落城乌啼未了，起来翻为无眠早
薄霜庭院怯生衣，心悄悄，红阑绕
此情待共谁人晓
','',''),('nalan-112','水调歌头·题西山秋爽图','纳兰性德','nalan','','','空山梵呗静，水月影俱沉
悠然一境人外，都不许尘侵
岁晚忆曾游处，犹记半竿斜照，一抹界疏林
绝顶茅庵里，老衲正孤吟
云中锡，溪头钓，涧边琴
此生着几两屐，谁识卧游心?
准拟乘风归去，错向槐安回首，何日得投簪
布袜青鞋约，但向画图寻','',''),('nalan-113','鹧鸪天·雁贴寒云次第飞','纳兰性德','nalan','','','雁帖寒云次第飞，向南犹自怨归迟
谁能瘦马关山道，又到西风扑鬓时
人杳杳，思依依，更无芳树有乌啼
凭将扫黛窗前月，持向今宵照别离
','',''),('nalan-114','琵琶仙·中秋','纳兰性德','nalan','','','碧海年年，试问取、冰轮为谁圆缺
吹到一片秋香，清辉了如雪
愁中看、好天良夜，知道尽成悲咽
只影而今，那堪重对，旧时明月
花径里、戏捉迷藏，曾惹下萧萧井梧叶
记否轻纨小扇，又几番凉热
只落得，填膺百感，总茫茫、不关离别。
一任紫玉无情，夜寒吹裂','',''),('nalan-115','于中好·独背残阳上小楼','纳兰性德','nalan','','','独背残阳上小楼，谁家玉笛韵偏幽
一行白雁遥天暮，几点黄花满地秋
惊节序，叹沉浮，秾华如梦水东流
人间所事堪惆怅，莫向横塘问旧游
','',''),('nalan-116','浪淘沙·夜雨做成秋','纳兰性德','nalan','','','夜雨做成秋，恰上心头
教他珍重护风流
端的为谁添病也，更为谁羞
密意未曾休，密愿难酬
珠帘四卷月当楼
暗忆欢期真似梦，梦也须留','',''),('nalan-117','南乡子·烟暖雨初收','纳兰性德','nalan','','','烟暖雨初收，落尽繁花小院幽
摘得一双红豆子，低头，说着分携泪暗流
人去似春休，卮酒曾将酹石尤
别自有人桃叶渡，扁舟，一种烟波各自愁
','',''),('nalan-118','梦江南·新来好','纳兰性德','nalan','','','新来好，唱得虎头词
一片冷香唯有梦，十分清瘦更无诗
标格早梅知
','',''),('nalan-119','鹧鸪天·别绪如丝梦不成','纳兰性德','nalan','','','别绪如丝梦不成，那堪孤枕梦边城
因听紫塞三更雨，却忆红楼半夜灯
书郑重，恨分明，天将愁味酿多情
起来呵手封题处，偏到鸳鸯两字冰
','',''),('nalan-120','临江仙·昨夜个人曾有约','纳兰性德','nalan','','','昨夜个人曾有约，严城玉漏三更
一钩新月几疏星
夜阑犹未寝，人静鼠窥灯
原是瞿唐风间阻，错教人恨无情
小阑干外寂无声
几回肠断处，风动护花铃','',''),('nalan-121','浪淘沙·望海','纳兰性德','nalan','','','蜃阙半模糊，踏浪惊呼
任将蠡测笑江湖
沐日光华还浴月，我欲乘桴
钓得六鳌无
竿拂珊瑚
桑田清浅问麻姑
水气浮天天接水，那是蓬壶','',''),('nalan-122','清平乐·弹琴峡题壁','纳兰性德','nalan','','','泠泠彻夜，谁是知音者
如梦前朝何处也，一曲边愁难写
极天关塞云中，人随落雁西风
唤取红襟翠袖，莫教泪洒英雄
','',''),('nalan-123','蝶恋花·又到绿杨曾折处','纳兰性德','nalan','','','又到绿杨曾折处，不语垂鞭，踏遍清秋路
衰草连天无意绪，雁声远向萧关去
不恨天涯行役苦，只恨西风，吹梦成今古
明日客程还几许，沾衣况是新寒雨','',''),('nalan-124','摊破浣溪沙·风絮飘残已化萍','纳兰性德','nalan','','','风絮飘残已化萍，泥莲刚倩藕丝萦
珍重别拈香一瓣，记前生
人到情多情转薄，而今真个悔多情
又到断肠回首处，泪偷零
','',''),('nalan-125','于中好·十月初四夜风雨其明日是亡妇生辰','纳兰性德','nalan','','','尘满疏帘素带飘，真成暗度可怜宵
几回偷拭青衫泪，忽傍犀奁见翠翘
惟有恨，转无聊
五更依旧落花朝
衰杨叶尽丝难尽，冷雨凄风打画桥
','',''),('nalan-126','蝶恋花·眼底风光留不住','纳兰性德','nalan','','','眼底风光留不住，和暖和香，又上雕鞍去
