欲眠还展旧时书
鸳鸯小字，犹记手生疏
倦眼乍低缃帙乱，重看一半模糊
幽窗冷雨一灯孤
料应情尽，还道有情无','',''),('nalan-128','踏莎行·倚柳题笺','纳兰性德','nalan','','','倚柳题笺，当花侧帽，赏心应比驱驰好
