','',''),('nalan-129','金缕曲·姜西溟言别赋此赠之','纳兰性德','nalan','','','谁复留君住
叹人生、几翻离合，便成迟暮
最忆西窗同剪烛，却话家山夜雨
不道只、暂时相聚
衮衮长江萧萧木，送遥天、白雁哀鸣去
黄叶下，秋如许
曰归因甚添愁绪
料强似、冷烟寒月，栖迟梵宇
一事伤心君落魄，两鬓飘萧未遇
有解忆、长安儿女
裘敝入门空太息，信古来、才命真相负
身世恨，共谁语？','',''),('nalan-130','金缕曲·慰西溟','纳兰性德','nalan','','','何事添凄咽
但由他、天公簸弄，莫教磨涅
失意每多如意少，终古几人称屈
须知道、福因才折
独卧藜床看北斗，背高城、玉笛吹成血
听谯鼓，二更彻
丈夫未肯因人热，且乘闲、五湖料理，扁舟一叶
泪似秋霖挥不尽，洒向野田黄蝶
须不羡、承明班列
马迹车尘忙未了，任西风吹冷长安月
又萧寺，花如雪','',''),('nalan-131','于中好·谁道阴山行路难','纳兰性德','nalan','','','谁道阴山行路难
风毛雨血万人欢
松梢露点沾鹰绁，芦叶溪深没马鞍
依树歇，映林看
黄羊高宴簇金盘
萧萧一夕霜风紧，却拥貂裘怨早寒','',''),('nalan-132','赤枣子·风淅淅','纳兰性德','nalan','','','风淅淅，雨纤纤
难怪春愁细细添
记不分明疑是梦，梦来还隔一重帘
','',''),('nalan-133','浣溪沙·欲寄愁心朔雁边','纳兰性德','nalan','','','欲寄愁心朔雁边，西风浊酒惨离颜
黄花时节碧云天
