盈盈自此隔银湾
便无风雪也摧残
青雀几时裁锦字，玉虫连夜翦春旙
不禁辛苦况相关','',''),('nalan-138','浣溪沙·酒醒香销愁不胜','纳兰性德','nalan','','','酒醒香销愁不胜，如何更向落花行
