若似月轮终皎洁，不辞冰雪为卿热
无那尘缘容易绝，燕子依然，软踏帘钩说
唱罢秋坟愁未歇，春丛认取双栖蝶','',''),('nalan-140','采桑子·那能寂寞芳菲节','纳兰性德','nalan','','','那能寂寞芳菲节，欲话生平
夜已三更
一阕悲歌泪暗零
须知秋叶春花促，点鬓星星
遇酒须倾，莫问千秋万岁名','',''),('nalan-141','于中好·小构园林寂不哗','纳兰性德','nalan','','','小构园林寂不哗，疏篱曲径仿山家
昼长吟罢风流子，忽听楸枰响碧纱
添竹石，伴烟霞
拟凭樽酒慰年华
休嗟髀里今生肉，努力春来自种花
','',''),('nalan-142','秣陵怀古','纳兰性德','nalan','','','山色江声共寂寥，十三陵树晚萧萧
