犹记碧桃影里、誓三生
乌丝阑纸娇红篆，历历春星
道休孤密约，鉴取深盟
语罢一丝香露、湿银屏
','',''),('nalan-145','浣溪沙·十八年来堕世间','纳兰性德','nalan','','','十八年来堕世间，吹花嚼蕊弄冰弦
多情情寄阿谁边
紫玉钗斜灯影背，红绵粉冷枕函偏
相看好处却无言','',''),('nalan-146','浣溪沙·已惯天涯莫浪愁','纳兰性德','nalan','','','已惯天涯莫浪愁，寒云衰草渐成秋
漫因睡起又登楼
伴我萧萧惟代马，笑人寂寂有牵牛，劳人只合一生休','',''),('nalan-147','浣溪沙·燕垒空梁画壁寒','纳兰性德','nalan','','','燕垒空梁画壁寒，诸天花雨散幽关
