蛱蝶乍从帘影度，樱桃半是鸟街残
此时相对一忘言','',''),('nalan-148','眼儿媚·中元夜有感','纳兰性德','nalan','','','手写香台金字经，惟愿结来生
莲花漏转，杨枝露滴，想鉴微诚
欲知奉倩神伤极，凭诉与秋擎
西风不管，一池萍水，几点荷灯','',''),('nalan-149','菩萨蛮·为春憔悴留春住','纳兰性德','nalan','','','为春憔悴留春住，那禁半霎催归雨
深巷卖樱桃，雨余红更娇
黄昏清泪阁，忍便花飘泊
消得一声莺，东风三月情','',''),('nalan-150','鬓云松令·枕函香','纳兰性德','nalan','','','枕函香，花径漏
依约相逢，絮语黄昏后
时节薄寒人病酒，刬地梨花，彻夜东风瘦
掩银屏，垂翠袖
何处吹箫，脉脉情微逗
肠断月明红豆蔻，月似当时，人似当时否','',''),('nalan-151','望江南·咏弦月','纳兰性德','nalan','','','初八月，半镜上青霄
斜倚画阑娇不语，暗移梅影过红桥，裙带北风飘','',''),('nalan-152','蝶恋花·出塞','纳兰性德','nalan','','','今古河山无定据
画角声中，牧马频来去
满目荒凉谁可语
西风吹老丹枫树
从前幽怨应无数
铁马金戈，青冢黄昏路
一往情深深几许
深山夕照深秋雨','',''),('nalan-153','荷叶杯·知己一人谁是','纳兰性德','nalan','','','知己一人谁是
已矣
赢得误他生
有情终古似无情，别语悔分明
莫道芳时易度，朝暮
珍重好花天
为伊指点再来缘，疏雨洗遗钿','',''),('nalan-154','南乡子·为亡妇题照','纳兰性德','nalan','','','泪咽却无声
只向从前悔薄情，凭仗丹青重省识
盈盈
一片伤心画不成
别语忒分明
午夜鹣鹣梦早醒
卿自早醒侬自梦，更更
泣尽风檐夜雨铃','',''),('nalan-155','金人捧露盘·净业寺观莲有怀荪友','纳兰性德','nalan','','','藕风轻，莲露冷，断虹收，正红窗、初上帘钩
田田翠盖，趁斜阳鱼浪香浮
此时画阁垂杨岸，睡起梳头
旧游踪，招提路，重到处，满离忧
想芙蓉湖上悠悠
红衣狼藉，卧看少妾荡兰舟
午风吹断江南梦，梦里菱讴','',''),('nalan-156','菩萨蛮·春云吹散湘帘雨','纳兰性德','nalan','','','春云吹散湘帘雨，絮黏蝴蝶飞还住
人在玉楼中，楼高四面风
柳烟丝一把，暝色笼鸳瓦
休近小阑干，夕阳无限山','',''),('nalan-157','南歌子·古戍','纳兰性德','nalan','','','古戍饥乌集，荒城野雉飞
何年劫火剩残灰，试看英雄碧血，满龙堆
玉帐空分垒，金笳已罢吹
东风回首尽成非，不道兴亡命也，岂人为','',''),('nalan-158','虞美人·银床淅沥青梧老','纳兰性德','nalan','','','银床淅沥青梧老，屧粉秋蛩扫
采香行处蹙连钱，拾得翠翘何恨不能言
回廊一寸相思地，落月成孤倚
背灯和月就花阴，已是十年踪迹十年心','',''),('nalan-159','忆江南·宿双林禅院有感','纳兰性德','nalan','','','心灰尽、有发未全僧
风雨消磨生死别，似曾相识只孤檠，情在不能醒
摇落后，清吹那堪听
淅沥暗飘金井叶，乍闻风定又钟声，薄福荐倾城','',''),('nalan-160','百字令·宿汉儿村','纳兰性德','nalan','','','无情野火，趁西风烧遍、天涯芳草
榆塞重来冰雪里，冷入鬓丝吹老
牧马长嘶，征笳乱动，并入愁怀抱
定知今夕，庾郎瘦损多少
便是脑满肠肥，尚难消受，此荒烟落照
何况文园憔悴后，非复酒垆风调
回乐峰寒，受降城远，梦向家山绕
茫茫百感，凭高唯有清啸','',''),('nalan-161','一络索·过尽遥山如画','纳兰性德','nalan','','','过尽遥山如画
短衣匹马
萧萧落木不胜秋， 莫回首、 斜阳下
别是柔肠萦挂
待归才罢
却愁拥髻向灯前， 说不尽、 离人话','',''),('nalan-162','清平乐·风鬟雨鬓','纳兰性德','nalan','','','风鬟雨鬓，偏是来无准
倦倚玉兰看月晕，容易语低香近
软风吹遍窗纱，心期便隔天涯
从此伤春伤别，黄昏只对梨花','',''),('nalan-163','清平乐·青陵蝶梦','纳兰性德','nalan','','','青陵蝶梦，倒挂怜么凤
退粉收香情一种，栖傍玉钗偷共
愔愔镜阁飞蛾，谁传锦字秋河
莲子依然隐雾，菱花暗惜横波','',''),('nalan-164','清平乐·添烟深漾','纳兰性德','nalan','','','麝烟深漾
人拥缑笙氅
新恨暗随新月长
不辨眉尖心上
六花斜扑疏帘
地衣红锦轻沾
记取暖香如梦，耐他一晌寒岩','',''),('nalan-165','清平乐·角声哀咽','纳兰性德','nalan','','','角声哀咽，襆被驮残月
过去华年如电掣，禁得番番离别
一鞭冲破黄埃乱山影里徘徊
蓦忆去年今日，十三陵下归来','',''),('nalan-166','清平乐·参横月落','纳兰性德','nalan','','','参横月落，客绪从谁托
望里家山云漠漠，似有红楼一角
不如意事年年，消磨绝塞风烟
输与五陵公子，此时梦绕花前','',''),('nalan-167','天仙子·梦里藻芜青一剪','纳兰性德','nalan','','','梦里蘼芜青一剪，玉郎经岁音书远
暗钟明月不归来，梁上燕，轻罗扇
好风又落桃花片','',''),('nalan-168','天仙子·天咫尺','纳兰性德','nalan','','','好在软绡红泪积，漏痕斜罥菱丝碧
古钗封寄玉关秋，天咫尺，人南北，
不信鸳鸯头不白','',''),('nalan-169','天仙子·渌水亭秋夜','纳兰性德','nalan','','','水浴凉蟾风入袂，鱼鳞蹙损金波碎
好天良夜酒盈尊，心自醉，愁难睡
西风月落城乌起','',''),('nalan-170','相见欢·落花如梦凄迷','纳兰性德','nalan','','','落花如梦凄迷，麝烟微，又是夕阳潜下小楼西
愁无限，消瘦尽，有谁知
闲教玉笼鹦鹉念郎诗','',''),('nalan-171','昭君怨·深禁好春谁惜','纳兰性德','nalan','','','深禁好春谁惜，薄暮瑶阶伫立
别院管弦声，不分明
又是梨花欲谢，绣被春寒今夜
寂寞锁朱门，梦承恩','',''),('nalan-172','浣溪沙·藕荡桥边埋钓筒','纳兰性德','nalan','','','藕荡桥边埋钓筒，苎萝西去五湖东
笔床茶灶太从容
况有短墙银杏雨，更兼高阁玉兰风
画眉闲了画芙蓉','',''),('nalan-173','浣溪沙·身向云山那畔行','纳兰性德','nalan','','','身向云山那畔行，北风吹断马嘶声
深秋远塞若为情
一抹晚烟荒戍垒，半竿斜日旧关城
古今幽恨几时平','',''),('nalan-174','浣溪沙·桦屋鱼衣柳作城','纳兰性德','nalan','','','桦屋鱼衣柳作城，蛟龙鳞动浪花腥，飞扬应逐海东青
犹记当年军垒迹，不知何处梵钟声，莫将兴废话分明','',''),('nalan-175','菩萨蛮·回文','纳兰性德','nalan','','','雾窗寒对遥天暮，暮天遥对寒窗雾
花落正啼鸦，鸦啼正落花
袖罗垂影瘦，瘦影垂罗袖
风翦一丝红，红丝一翦风','',''),('nalan-176','菩萨蛮·阑风伏雨催寒食','纳兰性德','nalan','','','阑风伏雨催寒食，樱桃一夜花狼藉
刚与病相宜，锁窗薰绣衣
画眉烦女伴，央及流莺唤
半晌试开奁，娇多直自嫌','',''),('nalan-177','菩萨蛮·白日惊飚冬已半','纳兰性德','nalan','','','白日惊飚冬已半，解鞍正值昏鸦乱
冰合大河流，茫茫一片愁
烧痕空极望，鼓角高城上
明日近长安，客心愁未阑','',''),('nalan-178','菩萨蛮·萧萧几叶风兼雨','纳兰性德','nalan','','','萧萧几叶风兼雨，离人偏识长更苦
欹枕数秋天，蟾蜍下早弦
夜寒惊被薄，泪与灯花落
无处不伤心，轻尘在玉琴','',''),('nalan-179','菩萨蛮·窗前桃蕊娇如倦','纳兰性德','nalan','','','窗前桃蕊娇如倦，东风泪洗胭脂面
人在小红楼，离情唱《石州》
夜来双燕宿，灯背屏腰绿
香尽雨阑珊，薄衾寒不寒','',''),('nalan-180','菩萨蛮·雾窗寒对遥天暮','纳兰性德','nalan','','','雾窗寒对遥天暮，暮天遥对寒窗雾
花落正啼鸦，鸦啼正落花
袖罗垂影瘦，瘦影垂罗袖
风翦一丝红，红丝一翦风','',''),('nalan-181','菩萨蛮·飘蓬只逐惊飚转','纳兰性德','nalan','','','飘蓬只逐惊飚转，行人过尽烟光远
立马认河流，茂陵风雨秋
寂寥行殿锁，梵呗琉璃火
塞雁与宫鸦，山深日易斜','',''),('nalan-182','菩萨蛮·为陈其年题照','纳兰性德','nalan','','','晓寒瘦着西南月，丁丁漏箭余香咽
春已十分宜，东风无是非
蜀魂羞顾影，玉照斜红冷
谁唱《后庭花》，新年忆旧家','',''),('nalan-183','菩萨蛮·催花未歇花奴鼓','纳兰性德','nalan','','','催花未歇花奴鼓，酒醒已见残红舞
不忍覆余觞，临风泪数行
粉香看又别，空剩当时月
月也异当时，凄清照鬓丝','',''),('nalan-184','菩萨蛮·过张见阳山居，赋赠','纳兰性德','nalan','','','车尘马迹纷如织，羡君筑处真幽僻
柿叶一林红，萧萧四面风
功名应看镜，明月秋河影
安得此山间，与君高卧闲','',''),('nalan-185','菩萨蛮·玉绳斜转疑清晓','纳兰性德','nalan','','','玉绳斜转疑清晓，凄凄月白渔阳道
星影漾寒沙，微茫织浪花
金笳鸣故垒，唤起人难睡
无数紫鸳鸯，共嫌今夜凉','',''),('nalan-186','菩萨蛮·惜春春去惊新燠','纳兰性德','nalan','','','惜春春去惊新燠，粉融轻汗红绵扑
妆罢只思眠，江南四月天
绿阴帘半揭，此景清幽绝
行度竹林风，单衫杏子红','',''),('nalan-187','菩萨蛮·寄梁汾苕中','纳兰性德','nalan','','','知君此际情萧索，黄芦苦竹孤舟泊
烟白酒旗青，水村鱼市晴
柁楼今夕梦，脉脉春寒送
直过画眉桥，钱塘江上潮','',''),('nalan-188','菩萨蛮·乌丝画作回纹纸','纳兰性德','nalan','','','乌丝画作回纹纸，香煤暗蚀藏头字
筝雁十三双，输他作一行
相看仍似客，但道休相忆
索性不还家，落残红杏花','',''),('nalan-189','菩萨蛮·榛荆满眼山城路','纳兰性德','nalan','','','榛荆满眼山城路，征鸿不为愁人住
何处是长安，湿云吹雨寒
丝丝心欲碎，应是悲秋泪
泪向客中多，归时又奈何','',''),('nalan-190','菩萨蛮·隔花才歇廉纤雨','纳兰性德','nalan','','','隔花才歇廉纤雨，一声弹指混无语
梁燕自双归，长条脉脉垂
小屏山色远，妆薄铅华浅
独自立瑶阶，透寒金缕鞋','',''),('nalan-191','菩萨蛮·山城夜半催金柝','纳兰性德','nalan','','','山城夜半催金柝，酒醒孤馆灯花落
窗白一声鸡，枕函闻马嘶
门前乌桕树，霜月迷行处
遥忆独眠人，早寒惊梦频','',''),('nalan-192','虞美人·曲阑深处重相见','纳兰性德','nalan','','','曲阑深处重相见，匀泪偎人颤
凄凉别后两应同，最是不胜清怨月明中
半生已分孤眠过，山枕檀痕涴
忆来何事最销魂，第一折枝花样画罗裙','',''),('nalan-193','菩萨蛮·荒鸡再咽天难晓','纳兰性德','nalan','','','荒鸡再咽天难晓，星榆落尽秋将老
毡幕绕牛羊，敲冰饮酪浆
山程兼水宿，漏点清钲续
正是梦回时，拥衾无限思','',''),('nalan-194','菩萨蛮·砑笺银粉残煤画','纳兰性德','nalan','','','砑笺银粉残煤画，画煤残粉银笺砑
清夜一灯明，明灯一夜清
片花惊宿燕，燕宿惊花片
亲自梦归人，人归梦自亲','',''),('nalan-195','菩萨蛮·新寒中酒敲窗雨','纳兰性德','nalan','','','新寒中酒敲窗雨，残香细袅秋情绪
才道莫伤神，青衫湿一痕
无聊成独卧，弹指韶光过
记得别伊时，桃花柳万丝','',''),('nalan-196','长相思·一重山','纳兰性德','nalan','','','一重山，两重山，山远天高烟水寒，相思枫叶丹
菊花开，菊花残，塞雁高飞人未还，一帘风月闲','',''),('nalan-197','卜算子·新柳','纳兰性德','nalan','','','娇软不胜垂，瘦怯那禁舞
多事年年二月风，翦出鹅黄缕
一种可怜生，落日和烟雨
苏小门前长短条，即渐迷行处','',''),('nalan-198','采桑子·咏春雨','纳兰性德','nalan','','','嫩烟分染鹅儿柳，一样风丝
似整如欹，才着春寒瘦不支
凉侵晓梦轻蝉腻，约略红肥
不惜葳蕤，碾取名香作地衣','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('nalan-199','采桑子·桃花羞作无情死','纳兰性德','nalan','','','桃花羞作无情死，感激东风，吹落娇红，飞入窗间伴懊侬
谁怜辛苦东阳瘦，也为春慵，不及芙蓉，一片幽情冷处浓','',''),('nalan-200','虞美人·春情只到梨花薄','纳兰性德','nalan','','','春情只到梨花薄，片片催零落
夕阳何事近黄昏，不道人间犹有未招魂
银笺别梦当时句，密绾同心苣
为伊判作梦中人，索向画图清夜唤真真','',''),('nalan-201','虞美人·黄昏又听城头角','纳兰性德','nalan','','','黄昏又听城头角，病起心情恶
药炉初沸短檠青，无那残香半缕恼多情
多情自古原多病，清镜怜清影
一声弹指泪如丝，央及东风休遣玉人知','',''),('nalan-202','金缕曲·亡妇忌日有感','纳兰性德','nalan','','','此恨何时已
滴空阶、寒更雨歇，葬花天气
三载悠悠魂梦杳，是梦久应醒矣
料也觉、人间无味
不及夜台尘土隔，冷清清、一片埋愁地
钗钿约，竟抛弃
重泉若有双鱼寄
好知他、年来苦乐，与谁相倚
我自中宵成转侧，忍听湘弦重理
待结个、他生知己
还怕两人俱薄命，再缘悭、剩月零风里
清泪尽，纸灰起','',''),('nalan-203','虞美人·秋夕信步','纳兰性德','nalan','','','愁痕满地无人省，露湿琅玕影
闲阶小立倍荒凉
还剩旧时月色在潇湘
薄情转是多情累，曲曲柔肠碎
红笺向壁字模糊，忆共灯前呵手为伊书','',''),('nalan-204','柳枝词','纳兰性德','nalan','','','池上闲房碧树围，帘纹如彀上斜晖
生憎飞絮吹难定，一出红窗便不归','',''),('nalan-205','遐方怨·欹角枕','纳兰性德','nalan','','','欹角枕，掩红窗
梦到江南，伊家博山沉水香
湔裙归晚坐思量
轻烟笼浅黛，月茫茫','',''),('nalan-206','浣溪沙·肯把离情容易看','纳兰性德','nalan','','','肯把离情容易看，要从容易见艰难
难抛往事一般般
今夜灯前形共影，枕函虚置翠衾单
更无人与共春寒','',''),('nalan-207','霜天晓角·重来丁酒','纳兰性德','nalan','','','重来丁酒，折尽风前柳
若问看花情绪，似当日，怎能够
休为西风瘦，痛饮频搔首
自古青蝇白璧，天已早安排就','',''),('nalan-208','菩萨蛮·黄云紫塞三千里','纳兰性德','nalan','','','黄云紫塞三千里，女墙西畔啼乌起
落日万山寒，萧萧猎马还
笳声听不得，入夜空城黑
秋梦不归家，残灯落碎花','',''),('nalan-209','减字木兰花·烛花摇影','纳兰性德','nalan','','','烛花摇影，冷透疏衾刚欲醒
待不思量，不许孤眠不断肠
茫茫碧落，天上人间情一诺
银汉难通，稳耐风波愿始从','',''),('nalan-210','减字木兰花·从教铁石','纳兰性德','nalan','','','从教铁石，每见花开成惜惜
泪点难消，滴损苍烟玉一条
怜伊大冷，添个纸窗疏竹影
记取相思，环佩归来月上时','',''),('nalan-211','采桑子·明月多情应笑我','纳兰性德','nalan','','','明月多情应笑我，笑我如今
辜负春心，独自闲行独自吟
近来怕说当时事，结遍兰襟
月浅灯深，梦里云归何处寻','',''),('nalan-212','采桑子·巂周声里严关峙','纳兰性德','nalan','','','巂周声里严关峙，匹马登登，乱踏黄尘
听报邮签第几程
行人莫话前朝事，风雨诸陵，寂寞鱼灯
天寿山头冷月横','',''),('nalan-213','采桑子·土花曾染湘娥黛','纳兰性德','nalan','','','土花曾染湘娥黛，铅泪难消
清韵谁敲，不是犀椎是凤翘
只应长伴端溪紫，割取秋潮
鹦鹉偷教，方响前头见玉萧','',''),('nalan-214','河传·春浅','纳兰性德','nalan','','','春浅，红怨，掩双环
微雨花间，昼闲
无言暗将红泪弹
阑珊，香销轻梦还
斜倚画屏思往事，皆不是，空作相思字
记当时垂柳丝，花枝，满庭蝴蝶儿','',''),('nalan-215','于中好·咏史','纳兰性德','nalan','','','马上吟成促渡江，分明闲气属闺房
生憎久闭金铺暗，花冷回心玉一床
添哽咽，足凄凉
谁教生得满身香
只今西海年年月，犹为萧家照断肠','',''),('nalan-216','菩萨蛮·隔花才歇帘纤雨','纳兰性德','nalan','','','隔花才歇帘纤雨，一声弹指浑无语
梁燕自双归，长条脉脉垂
小屏山色远，妆薄铅华浅
独自立瑶阶，透寒金缕鞋','',''),('nalan-217','玉连环影','纳兰性德','nalan','','','何处几叶萧萧雨
湿尽檐花，花底人无语
掩屏山，玉炉寒
谁见两眉愁聚倚阑干','',''),('nalan-218','茅斋','纳兰性德','nalan','','','闲亭照白日，一室罗古今
偶焉此栖迟，抱膝悠然吟
吟罢有余适，散瞩复披襟
时开玉怀卷，或弹珠柱琴
檐树吐新花，枝头语珍禽
花发饶冶色，禽鸣多姣音
色冶眩春目，音姣伤春心
夕阳下虞渊，寂莫还空林
清光复相照，片月西山岭
东园桃李姿，是妾嫁君时
燕婉为夫妇，相爱不相离
良人忽远征，妾独守空帏
忧来恒自叹，冀死魂追随
又念妾死时，谁制万里衣
幸有双鲤鱼，拟为寄君辞
终日不成章，含泪自封题
君若得鲤鱼，剖鱼开素书
但看行中字，一一与泪俱','',''),('nalan-219','净业寺','纳兰性德','nalan','','','红楼高耸碧池深，荷芰生凉豁远襟
湖色静涵孤刹影，花香暗入定僧心
经翻佛藏研朱荚，地赐朝家布紫金
下马长堤一吟望，梵钟杂送海潮音','',''),('nalan-220','菩萨蛮·客中愁损催寒夕','纳兰性德','nalan','','','客中愁损催寒夕，夕寒催损愁中客
门掩月黄昏，昏黄月掩门
翠衾孤拥醉，醉拥孤衾翠
醒莫更多情，情多更莫醒','',''),('nalan-221','高楼望月','纳兰性德','nalan','','','戚戚复戚戚，高楼月如雪
二八正婵娟，月明翡翠钿
由来工织锦，生小倚朱弦
朱弦岂解愁，素手似云浮
一声落天上，闻者皆泪流
别郎已经年，望郎出楼前
青天如海水，碧月如珠圆
月圆以复缺，不见长安客
古道白于霜，沙灭行人迹
月出光在天，月高光在地
何当同心人，两两不相弃','',''),('nalan-222','扈驾马兰峪赐观温泉恭纪十韵','纳兰性德','nalan','','','御天来凤辇，浴日启龙池
野迥纡皇览，春浓值圣时
落花萦彩仗，初柳拂朱旗
行漏三辰拥，停銮万象随
瑞征泉是醴，喜溢沼生芝
特许观灵液，相将涉禁墀','',''),('nalan-223','拟古·高云媚春日','纳兰性德','nalan','','','高云媚春日，坐觉鱼鸟亲
可怜暮春候，病中别故人
莺啼花乱落，风吹成锦茵
君去一何速，到家垂柳新
芙蓉湖上月，照君垂长纶','',''),('nalan-224','南海子·分弓列戟四门开','纳兰性德','nalan','','','分弓列戟四门开，游豫长陪万乘来
七十二桥天汉上，彩虹飞下晾鹰台','',''),('nalan-225','扈跸霸州','纳兰性德','nalan','','','霸山重镇奠神京，鸾辂春游淑景明
万呱银涛冲古岸，四围玉甃护严城
花乘暖日迎来骑，柳带新膏绾去旌
八寨雄图今更固，行随赏乐胜蓬瀛','',''),('nalan-226','江行','纳兰性德','nalan','','','木落江已空，清辉澹鸥鹭
不见系缆石，寒潮没瓜步
帆移清枫林，人归白沙渡
似有山猿啼，窈然潇湘暮','',''),('nalan-227','中元前一夕枕上偶成','纳兰性德','nalan','','','酒醒池塘耿不眠，帐纹漠漠隔轻烟
溪风到竹初疑雨，秋月如弓渐满弦
残梦远经吹角戍，明河长亘衣天
哀蛩饯晓浑多事，也似严更古驿边','',''),('nalan-228','盛京','纳兰性德','nalan','','','拔地蛟龙宅，当关虎豹城
山连长白秀，江入混同清
庙社灵风肃，豪强右族更
明明开创业，休拟作陪京','',''),('nalan-229','柳条边','纳兰性德','nalan','','','是处垣篱防绝塞，角端西来画疆界
汉使今行虎落中，秦城合筑龙荒外
龙荒虎落两依然，护得当时饮马泉
若使春风知别苦，不应吹到柳条边','',''),('nalan-230','南海子·红桥夹岸柳平分','纳兰性德','nalan','','','红桥夹岸柳平分，雉兔年年不掩群
飞放何须烦海户，郊南新置羽林军','',''),('nalan-231','古北口','纳兰性德','nalan','','','乱山入戟拥孤城，一线人争鸟道行
地险东西分障塞，云开南北望神京
新图已入三关志，往事休论十路兵
都护近来长不调，年年烽火报生平','',''),('nalan-232','玉泉','纳兰性德','nalan','','','芙蓉殿俯御河寒，残月西风并马看
十里松杉清绝处，不知晓雪在西山','',''),('nalan-233','玉泉十二韵','纳兰性德','nalan','','','地涌西山脉，名标禁御泉
百层飞作雨，万顷汇成渊
润下终归海，源高却自天
萦烟来树杪，带雪落云边
隐见瑶光曳，琤苁佩响传
红栋桥宛转，乌榜棹洄沿
蛟龙蟠翠岛，雁鹜起琼田
镜面晶荧合，珠痕荡漾圆
翠流初放荇，娇拥半开莲
睿赏悬孤鉴，馀波溢九璇
那居真有庆，鱼藻在诗篇','',''),('nalan-234','汤泉应制·六龙初驻浴蓝天','纳兰性德','nalan','','','六龙初驻浴蓝天，碧瓦朱旗共一川
