吹成暖律回燕谷，散作薰风入舜弦
最是垂衣深圣德，不须词笔颂甘泉','',''),('nalan-235','记征人语','纳兰性德','nalan','','','边月无端照别离，故园何处寄相思
西风不解征人语，一夕萧萧满大旗','',''),('nalan-236','汤泉应制·清时礼乐萃朝端','纳兰性德','nalan','','','清时礼乐萃朝端，次第郊原引玉銮
