便从畿甸亲民隐，更启神泉示从官
非独炎灵钟坎德，恩波深处不知寒','',''),('nalan-237','汤泉应制·鱼鳞雁齿镜中开','纳兰性德','nalan','','','鱼鳞雁齿镜中开，溅沫为霖遍九垓
不用劫灰求仿佛，便从天汉象昭回
桑坛法驾乘春转，鹤禁仙镳问寝来
遥祝海隅同帝泽，年年长听属车雷','',''),('nalan-238','雄县观鱼','纳兰性德','nalan','','','渔师临广泽，侍从俯清澜
瑞入王舟好，仁知圣网宽
拨鳞飞白雪，行鲙缕金盘
在藻同周宴，时容万姓看','',''),('nalan-239','梅花落','纳兰性德','nalan','','','春色凤城来，寒梅逼岁开
条风初入树，缥雪渐侵苔
粉逐莺衣散，香黏蝶翅回
陇头人未返，急管莫频催','',''),('nalan-240','蕉园','纳兰性德','nalan','','','见说斋坦闭，前朝大乙祠
莺边花树树，燕外柳丝丝
宫御人稀少，词臣例许窥
今朝陪豹尾，新长万年枝','',''),('nalan-241','风流子·秋郊射猎','纳兰性德','nalan','','','平原草枯矣，重阳后，黄叶树骚骚
记玉勒青丝，落花时节，曾逢拾翠，忽听吹箫
今来是、烧痕残碧尽，霜影乱红凋
秋水映空，寒烟如织，皂雕飞处，天惨云高
人生须行乐，君知否。容易两鬓萧萧
自与东君作别，刬地无聊
算功名何许，此身博得
短衣射虎，沽酒西郊。
便向夕阳影里，倚马挥毫','',''),('nalan-242','扈驾西山','纳兰性德','nalan','','','凤翥龙蟠势作环，浮青不断太行山
九重殿阁葱茏里，一气风云吐纳间
熊虎自当驰道伏，蛟螭长棒御书闲
黄图此日论形胜，惭愧频叨侍从班','',''),('nalan-243','入直西苑','纳兰性德','nalan','','','望里蓬瀛近，行来阆苑齐
晴霞开碧沼，落月隐金堤
叶密莺先觉，花繁径不迷
笙歌回辇处，长在凤城西','',''),('nalan-244','兴京陪祭福陵','纳兰性德','nalan','','','龙盘凤翥气佳哉，东指斋宫玉辇来
影入松楸仙仗远，香升俎豆晓云开
盛仪备处千官肃，神贶乘时万马回
豹尾叨陪须献颂，小臣惭愧展微才','',''),('nalan-245','汤泉应制·身向咸池榜末光','纳兰性德','nalan','','','身向咸池榜末光，三危露暖不成霜
金铺照日初涵影，玉求生烟别作香
地接蓬莱通御气，波翻豆蔻散朝凉
微臣幸属赓歌日，愿借如川献寿觞','',''),('nalan-246','菩萨蛮·春花春月年年客','纳兰性德','nalan','','','春花春月年年客，怜春又怕春离别
只为晓风愁，催花扑玉钩
娟娟双蛱蝶，宛转飞花侧
花底一声歌，疼花花奈何','',''),('nalan-247','拟冬日景忠山应制·岧峣铁凤锁琳宫','纳兰性德','nalan','','','岧峣铁凤锁琳宫，亲侍銮舆度碧空
圣主岂因崇象教，宸游直自接鸿蒙
远山雪有一峰白，别浦枫余几树红
天意不教常肃杀，伫看宇宙遍春风','',''),('nalan-248','景山','纳兰性德','nalan','','','雪里瑶华岛，云端白玉京
削成千仞势，高出九重城
绣陌回环绕，红楼宛转迎
近天多雨露，草木每先荣','',''),('nalan-249','拟古·美人临残月','纳兰性德','nalan','','','美人临残月，无言若有思
含颦但斜睇，吁嗟怜者谁
予本多情人，寸心聊自持
浩歌幽兰曲，援琴终不怡
私恨托远梦，初日照帘帏','',''),('nalan-250','拟古·予生未三十','纳兰性德','nalan','','','予生未三十，忧愁居其半
心事如落花，春风吹已断
行当适远道，作记殊汗漫
寒食青草多，薄暮烟冥冥
山桃一夜红，茵箔随飘零
愿餐玉红草，一醉不复醒','',''),('nalan-251','密云','纳兰性德','nalan','','','白檀山下水声秋，地踞潮河最上流
日暮行人寻堠馆，凉砧一片古檀州','',''),('nalan-252','芳树','纳兰性德','nalan','','','连理无分影，同心岂独芳
傍檐巢翡翠，临水宿鸳鸯
叶叶含春思，枝枝向画廊
君情若比树，妾意复何伤
陌上谁攀折，闺中思复侵
眼凝清露重，眉敛翠烟深
羌笛临风曲，悲笳出塞音
纵垂千万缕，那系别离心','',''),('nalan-253','拟冬日景忠山应制·雄关阻塞戴灵鳌','纳兰性德','nalan','','','雄关阻塞戴灵鳌，控制卢龙胜百牢
山界万重横翠黛，海当三面涌银涛
哀笳带月传声切，早雁迎秋度影高
旧是六师开险处，待陪巡幸扈星旌','',''),('nalan-254','明月棹孤舟·海淀','纳兰性德','nalan','','','一片亭亭空凝伫
趁西风霓裳偏舞
白鸟惊飞，菰蒲叶乱，断续浣纱人语
丹碧驳残秋夜雨
风吹去采菱越女
辘轳声断，昏鸦欲起，多少博山情绪','',''),('nalan-255','南海子·相风微动九门开','纳兰性德','nalan','','','相风微动九门开，南陌离宫万柳栽
草色横粘下马泊，水光平占晾鹰台
锦鞯欲射波间去，玉辇疑从岛上回
自是软红惊十丈，天教到此洗尘埃','',''),('nalan-256','班婕妤怨歌','纳兰性德','nalan','','','团团望舒月，皓皓冰蚕绢
欲却炎天暑，比月裁成扇
望舒圆易缺，金风换炎节
风凉秋气寒，匣扇复谁看
扇弃何足道，感妾伤怀抱
对月泪如丝，君恩异旧时','',''),('nalan-257','浣溪沙·伏雨朝寒愁不胜','纳兰性德','nalan','','','伏雨朝寒悉不胜，那能还傍杏花行
去年高摘斗轻盈
漫惹炉烟双袖紫，空将酒晕一衫青
人间何处问多情','',''),('caocao-001','度关山','曹操','caocao','','','天地间，人为贵。
立君牧民，为之轨则。
车辙马迹，经纬四极。
黜陟幽明，黎庶繁息。
于铄贤圣，总统邦域。
封建五爵，井田刑狱。
有燔丹书，无普赦赎。
皋陶甫侯，何有失职？
嗟哉后世，改制易律。
劳民为君，役赋其力。
舜漆食器，畔者十国，
不及唐尧，采椽不斫。
世叹伯夷，欲以厉俗。
侈恶之大，俭为共德。
许由推让，岂有讼曲？
兼爱尚同，疏者为戚。','',''),('caocao-002','短歌行 其一','曹操','caocao','','','对酒当歌，人生几何！譬如朝露，去日苦多。
慨当以慷，忧思难忘。何以解忧？唯有杜康。
青青子衿，悠悠我心。但为君故，沉吟至今。
呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。
明明如月，何时可掇？忧从中来，不可断绝。(明明 一作：佼佼)
越陌度阡，枉用相存。契阔谈宴，心念旧恩。(谈宴 一作：谈宴)
月明星稀，乌鹊南飞。绕树三匝，何枝可依？
山不厌高，海不厌深。周公吐哺，天下归心。(海 一作：水)','',''),('caocao-003','短歌行 其二','曹操','caocao','','','周西伯昌，怀此圣德。
三分天下，而有其二。
修奉贡献，臣节不隆。
崇侯谗之，是以拘系。
后见赦原，赐之斧钺，得使征伐。
为仲尼所称，达及德行，
犹奉事殷，论叙其美。
齐桓之功，为霸之首。
九合诸侯，一匡天下。
一匡天下，不以兵车。
正而不谲，其德传称。
孔子所叹，并称夷吾，民受其恩。
赐与庙胙，命无下拜。
小白不敢尔，天威在颜咫尺。
晋文亦霸，躬奉天王。
受赐圭瓒，秬鬯彤弓，
卢弓矢千，虎贲三百人。
威服诸侯，师之所尊。
八方闻之，名亚齐桓。
河阳之会，诈称周王，是其名纷葩。','',''),('caocao-004','对酒','曹操','caocao','','','对酒歌，太平时，吏不呼门。
王者贤且明，宰相股肱皆忠良。
咸礼让，民无所争讼。
三年耕有九年储，仓谷满盈。
斑白不负载。
雨泽如此，百谷用成。
却走马，以粪其土田。
爵公侯伯子男，咸爱其民，以黜陟幽明。
子养有若父与兄。
犯礼法，轻重随其刑。
路无拾遗之私。
囹圄空虚，冬节不断。
人耄耋，皆得以寿终。
恩德广及草木昆虫。','',''),('caocao-005','观沧海','曹操','caocao','','','东临碣石，以观沧海。
水何澹澹，山岛竦峙。
树木丛生，百草丰茂。
秋风萧瑟，洪波涌起。
日月之行，若出其中；
星汉灿烂，若出其里。
幸甚至哉，歌以咏志。','',''),('caocao-006','龟虽寿','曹操','caocao','','','神龟虽寿，犹有竟时。
腾蛇乘雾，终为土灰。(腾 一作：螣)
老骥伏枥，志在千里。
烈士暮年，壮心不已。
盈缩之期，不但在天；
养怡之福，可得永年。
幸甚至哉，歌以咏志。','',''),('caocao-007','蒿里行','曹操','caocao','','','关东有义士，兴兵讨群凶。
初期会盟津，乃心在咸阳。
军合力不齐，踌躇而雁行。
势利使人争，嗣还自相戕。
淮南弟称号，刻玺于北方。
铠甲生虮虱，万姓以死亡。
白骨露于野，千里无鸡鸣。
生民百遗一，念之断人肠。','',''),('caocao-008','精列','曹操','caocao','','','厥初生，
造划之陶物，莫不有终期。
莫不有终期。
圣贤不能免，何为怀此忧？
愿螭龙之驾，思想昆仑居。
思想昆仑居。
见期于迂怪，志意在蓬莱。
志意在蓬莱。
周礼圣徂落，会稽以坟丘。
会稽以坟丘。
陶陶谁能度？君子以弗忧。
年之暮奈何，时过时来微。','',''),('caocao-009','苦寒行','曹操','caocao','','','北上太行山，艰哉何巍巍！
羊肠坂诘屈，车轮为之摧。
树木何萧瑟！北风声正悲。
熊罴对我蹲，虎豹夹路啼。
溪谷少人民，雪落何霏霏！
延颈长叹息，远行多所怀。
我心何怫郁？思欲一东归。
水深桥梁绝，中路正徘徊。
迷惑失故路，薄暮无宿栖。
行行日已远，人马同时饥。
担囊行取薪，斧冰持作糜。
悲彼东山诗，悠悠使我哀。','',''),('caocao-010','气出唱 其一','曹操','caocao','','','华阴山，自以为大。
高百丈，浮云为之盖。
仙人欲来，出随风，列之雨。
吹我洞箫，鼓瑟琴，何訚訚！
酒与歌戏，今日相乐诚为乐。
玉女起，起舞移数时。
鼓吹一何嘈嘈。
从西北来时，仙道多驾烟，
乘云驾龙，郁何务务。
遨游八极，乃到昆仑之山，
西王母侧，神仙金止玉亭。
来者为谁？赤松王乔，乃德旋之门。
乐共饮食到黄昏。
多驾合坐，万岁长，宜子孙。','',''),('caocao-011','气出唱 其二','曹操','caocao','','','驾六龙，乘风而行。
行四海，路下之八邦。
历登高山临溪谷，乘云而行。
行四海外，东到泰山。
仙人玉女，下来翱游。
骖驾六龙饮玉浆。
河水尽，不东流。
解愁腹，饮玉浆。
奉持行，东到蓬莱山，上至天之门。
玉阙下，引见得入，
赤松相对，四面顾望，视正焜煌。
开玉心正兴，其气百道至。
传告无穷闭其口，但当爱气寿万年。
东到海，与天连。
神仙之道，出窈入冥，常当专之。
心恬澹，无所愒。
欲闭门坐自守，天与期气。
愿得神之人，乘驾云车，
骖驾白鹿，上到天之门，来赐神之药。
跪受之，敬神齐。
当如此，道自来。','',''),('caocao-012','气出唱 其三','曹操','caocao','','','游君山，甚为真。
崔嵬砟硌，尔自为神。
乃到王母台，金阶玉为堂，芝草生殿旁。
东西厢，客满堂。
主人当行觞，坐者长寿遽何央。
长乐甫始宜孙子。
常愿主人增年，与天相守。','',''),('caocao-013','却东西门行','曹操','caocao','','','鸿雁出塞北，乃在无人乡。
举翅万馀里，行止自成行。
冬节食南稻，春日复北翔。
田中有转蓬，随风远飘扬。
长与故根绝，万岁不相当。
奈何此征夫，安得驱四方！
戎马不解鞍，铠甲不离傍。
冉冉老将至，何时返故乡？
神龙藏深泉，猛兽步高冈。
狐死归首丘，故乡安可忘！','',''),('caocao-014','塘上行','曹操','caocao','','','蒲生我池中，其叶何离离。
傍能行仁义，莫若妾自知。
众口铄黄金，使君生别离。
念君去我时，独愁常苦悲。
想见君颜色，感结伤心脾。
念君常苦悲，夜夜不能寐。
莫以豪贤故，弃捐素所爱？
莫以鱼肉贱，弃捐葱与薤？
莫以麻枲贱，弃捐菅与蒯？
出亦复何苦，入亦复何愁。
边地多悲风，树木何修修！
从君致独乐，延年寿千秋。','',''),('caocao-015','薤露行','曹操','caocao','','','惟汉廿二世，所任诚不良。
沐猴而冠带，知小而谋疆。
犹豫不敢断，因狩执君王。
白虹为贯日，己亦先受殃。
贼臣持国柄，杀主灭宇京。
荡覆帝基业，宗庙以燔丧。
播越西迁移，号泣而且行。
瞻彼洛城郭，微子为哀伤。','',''),('caocao-016','陌上桑','曹操','caocao','','','驾虹霓，乘赤云，登彼九疑历玉门。
济天汉，至昆仑，见西王母谒东君。
交赤松，及羡门，受要秘道爱精神。
食芝英，饮醴泉，柱杖桂枝佩秋兰。
绝人事，游浑元，若疾风游欻翩翩。
景未移，行数千，寿如南山不忘愆。','',''),('caocao-017','秋胡行 其一','曹操','caocao','','','晨上散关山，此道当何难！
晨上散关山，此道当何难！
牛顿不起，车堕谷间。
坐磐石之上，弹五弦之琴。
作为清角韵，意中迷烦。
歌以言志，晨上散关山。
有何三老公，卒来在我旁？
有何三老公，卒来在我旁？
负揜被裘，似非恒人。
谓卿云何困苦以自怨，徨徨所欲，来到此间？
歌以言志，有何三老公？
我居昆仑山，所谓者真人。
我居昆仑山，所谓者真人。
道深有可得。
名山历观，遨游八极，枕石漱流饮泉。
沈吟不决，遂上升天。
歌以言志，我居昆仑山。
去去不可追，长恨相牵攀。
去去不可追，长恨相牵攀。
夜夜安得寐，惆怅以自怜。
正而不谲，辞赋依因。
经传所过，西来所传。
歌以言志，去去不可追。','',''),('caocao-018','秋胡行 其二','曹操','caocao','','','愿登泰华山，神人共远游。
愿登泰华山，神人共远游。
经历昆仑山，到蓬莱。
飘遥八极，与神人俱。
思得神药，万岁为期。
歌以言志，愿登泰华山。
天地何长久！人道居之短。
天地何长久！人道居之短。
世言伯阳，殊不知老；
赤松王乔，亦云得道。
得之未闻，庶以寿考。
歌以言志，天地何长久！
明明日月光，何所不光昭！
明明日月光，何所不光昭！
二仪合圣化，贵者独人不？
万国率土，莫非王臣。
仁义为名，礼乐为荣。
歌以言志，明明日月关。
四时更逝去，昼夜以成岁。
四时更逝去，昼夜以成岁。
大人先天而天弗违。
不戚年往，忧世不治。
存亡有命，虑之为蚩。
歌以言志，四时更逝去。
戚戚欲何念！欢笑意所之。
戚戚欲何念！欢笑意所之。
壮盛智愚，殊不再来。
爱时进趣，将以惠谁？
泛泛放逸，亦同何为！
歌以言志，戚戚欲何念！','',''),('caocao-019','善哉行 其一','曹操','caocao','','','古公亶甫，积德垂仁。
思弘一道，哲王于豳。
太伯仲雍，王德之仁。
行施百世，断发文身。
伯夷叔齐，古之遗贤。
让国不用，饿殂首山。
智哉山甫，相彼宣王。
何用杜伯，累我圣贤。
齐桓之霸，赖得仲父。
后任竖刁，虫流出户。
晏子平仲，积德兼仁。
与世沈德，未必思命。
仲尼之世，主国为君。
随制饮酒，扬波使官。','',''),('caocao-020','善哉行 其二','曹操','caocao','','','自惜身薄祜，夙贱罹孤苦。
既无三徙教，不闻过庭语。
其穷如抽裂，自以思所怙。
虽怀一介志，是时其能与！
守穷者贫贱，惋叹泪如雨。
泣涕于悲夫，乞活安能睹？
我愿于天穷，琅邪倾侧左。
虽欲竭忠诚，欣公归其楚。
快人由为叹，抱情不得叙。
显行天教人，谁知莫不绪。
我愿何时随？此叹亦难处。
今我将何照于光曜？释衔不如雨。','',''),('caocao-021','善哉行 其三','曹操','caocao','','','朝日乐相乐，酣饮不知醉。
悲弦激新声，长笛吹清气。
弦歌感人肠，四坐皆欢悦。
寥寥高堂上，凉风入我室。
持满如不盈，有德者能卒。
君子多苦心，所愁不但一。
慊慊下白屋，吐握不可失。
众宾饱满归，主人苦不悉。
比翼翔云汉，罗者安所羁？
冲静得自然，荣华何足为！','',''),('caocao-022','步出夏门行 艳','曹操','caocao','','','云行雨步，超越九江之皋。
临观异同，心意怀犹豫，不知当复何从？
经过至我碣石，心惆怅我东海。','',''),('caocao-023','步出夏门行 冬十月','曹操','caocao','','','孟冬十月，北风徘徊，
天气肃清，繁霜霏霏。
鹍鸡晨鸣，鸿雁南飞，
鸷鸟潜藏，熊罴窟栖。
钱鎛停置，农收积场。
逆旅整设，以通贾商。
幸甚至哉！歌以咏志。','',''),('caocao-024','步出夏门行 土不同','曹操','caocao','','','乡土不同，河朔隆冬。
流澌浮漂，舟船行难。
锥不入地，蘴藾深奥。
水竭不流，冰坚可蹈。
士隐者贫，勇侠轻非。
心常叹怨，戚戚多悲。
幸甚至哉！歌以咏志。','',''),('caocao-025','谣俗词','曹操','caocao','','','瓮中无斗储，发箧无尺缯。
友来从我贷，不知所以应。','',''),('caocao-026','董逃歌词','曹操','caocao','','','德行不亏缺，变故自难常。
郑康成行酒，伏地气绝；
郭景图命尽于园桑。','',''),('shuimo-001','蜀先主庙','刘禹锡','shuimo','','','天地英雄气，千秋尚凛然。
势分三足鼎，业复五铢钱。
得相能开国，生儿不象贤。
凄凉蜀故伎，来舞魏宫前。','','此诗歌颂了开国之君刘备的历史功绩。天地英雄的气派，千秋还存在的凛然正气。在三足鼎立的形势下，从事兴复汉室。得到诸葛丞相，便开创了蜀国；生个儿子刘禅，却不像先贤。令人感到凄凉的是，蜀国原来的歌伎，竟来到洛阳的魏宫起舞。'),('shuimo-002','新嫁娘','王建','shuimo','','','三日入厨下，洗手作羹汤。
未谙姑食性，先遣小姑尝。','','此诗朴素生动地刻划了封建社会媳妇对婆婆，特别是新嫁娘初到婆婆家，那种畏惧谨慎的心理状态。 按照习俗，新嫁娘婚后的第三天要下厨做菜。 第三天下厨房，洗手后煮羹汤，不熟悉婆婆的口味，先请小姑尝试。'),('shuimo-003','田家行','王建','shuimo','','','男声欣欣女颜悦，人家不怨言语别。
五月虽热麦风清，檐头索索缲车鸣。
野蚕作茧人不取，叶间扑扑秋蛾生。
麦收上场绢在轴，的知输得官家足。
不望入口复上身，且免向城卖黄犊。
田家衣食无厚薄，不见县门身即乐。','','田家一派丰收景象，男女老少都高兴，不说一句跟往常一样怨恨的话。五月虽然炎热，但吹来带着麦香的风，特别清凉；屋檐下缫丝车发出索索的响声。野蚕茧竟没有人收取，叶间竟扑扑地长出了秋蛾。麦子已经收割上场，丝绢已缠在轴上，确实知道缴纳赋税让官家富足。不指望将丰收的产品自已吃，自已穿，只要过得下去，不到城里去卖小牛就行。田家不讲究衣食的好歹，只要不去县衙门就是快乐。'),('shuimo-004','野老歌','张籍','shuimo','','','老农家贫在山住，耕种山田三四亩。
苗疏税多不得食，输入官仓化为土。
岁暮锄犁傍空室，呼儿登山收橡实。
西江贾客珠百斛，船中养犬长食肉。','','老翁家贫住在山中，靠耕种三四亩山田为生。田亩少，赋税多，没有吃的。粮食送进官府的仓库，最后腐烂变质，化为泥土。一年到头，家中只剩下锄头、犁耙靠在空房子里面，只好叫儿子上山去拾橡子充饥。西来的长江的富商的船中，成百上千的珠宝用斛来计量，连船上养的狗也长年吃肉。'),('shuimo-005','没蕃故人','张籍','shuimo','','','前年戍月支，城下没全师。
蕃汉断消息，死生长别离。
无人收废帐，归马识残旗。
欲祭疑君在，天涯哭此时。','','诗写悼念战死于吐蕃的故人。 前年我军讨伐月支(借指吐蕃)，城下一战，全军覆没。战后，吐蕃和汉族从此断绝消息，死的死，活的活，长时间地分离。打战后废弃的营帐无人收，只有马还能认识残旗，知道回来的路。想要祭奠，怀疑君还活着，此时只有向着天涯放声痛哭。'),('shuimo-006','游子吟','孟郊','shuimo','','','慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。','','母亲为即将远去的儿子缝补衣裳，临行时密密地缝补，担心他要很长的时间不能回来。子女像小草般的爱心，难以报答像春天阳光一样的母爱。'),('shuimo-007','暖川','李益','shuimo','','','胡风冻合䴙鹈泉，牛马千群逐暖川。
塞外征行无尽日，年年移帐雪中天。','','诗写戍边战士在冰天雪地中度过漫长的艰苦岁月。塞外的寒风吹得䴙鹈泉结了厚冰，千万群牛马向温暖的平川迁移。军队在塞外征战没有尽期，年年转战在冰天雪地。'),('shuimo-008','从军北征','李益','shuimo','','','天山雪后海风寒，横笛偏吹《行路难》。
碛里征人三十万，一时回首月中看。','','天山下了一场大雪，薄海刮来寒冷的风。行军途中，战士都吹起《行路难》的笛曲。沙漠里征军三十万，一到夜晚，所有的战士都望着故乡的明月。'),('shuimo-009','夜上受降城闻笛','李益','shuimo','','','回乐烽前沙似雪，受降城外月如霜。
不知何处吹芦管，一夜征人尽望乡。','','月光像霜一样洁白而寒冷，映照在回乐城东面耸立着的烽火台。沙漠像雪一样白，边塞一片荒凉景象。不知什么地方吹响了芦管的音乐，整个夜晚，所有的将士都在思念自已的故乡。'),('shuimo-010','水宿闻雁','李益','shuimo','','','早雁忽为双，惊秋风水凉。
夜长人自起，星月满空江。','','诗写作者在水边住宿，在早起的一瞬间所见雁群的景象。 清晨的大雁忽然变成一对对。秋风吹过，江水寒冷，把大雁惊醒，它们迅速地飞离。经过漫漫长夜，我起身只见天上布满星月，映照在空落落的江水之上。'),('shuimo-011','江南曲','李益','shuimo','','','嫁得瞿塘贾，朝朝误妾期。
早知潮有信，嫁与弄潮儿。','','此诗摹拟商人妻子的口吻写别离的哀怨。 嫁给瞿塘的商人，每天都耽误约定的时期。早知道潮水涨落有定时，不如嫁给弄潮的人。'),('shuimo-012','送李端','卢纶','shuimo','','','故关衰草遍，离别正堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
掩泣空相向，风尘何所期。','','这是一首送别诗。 往日的要塞荒草遍地，在这里离别真令人悲伤。道路通向寒冷的云天之外，送别的人踏着傍晚的雪花归来。幼年失去父亲，很早就漂流在外，困难重重，可惜认识得太迟。朝他离去的方向掩面哭泣，风尘仆仆，今朝一别，什么时候再相见呢？'),('shuimo-013','晚次鄂州','卢纶','shuimo','','','云开远见洛阳城，犹见孤帆一日程。
估客昼眠知浪静，舟人夜语觉潮生。','','三湘愁鬓逢秋色，万里归心对月明。旧业已随征战尽，更堪江上鼓鼙声。 云高气爽，远远可望见汉阳城，孤舟还要走一天的路程。商人白天睡觉感觉风平浪静，驾船人半夜说话，让人感觉潮水上涨。在三湘地区，因愁苦变白的双鬓正遇上萧条的秋色，面对明月，不禁有万里归乡之心。田园家产的旧业已经随着征战被毁光，更不能忍受长江上战鼓的声音。'),('shuimo-014','塞下曲','卢纶','shuimo','','','林暗草惊风，将军夜引弓。
平明寻白羽，没在石棱中。','','夜晚，树林阴暗不明，野草在疾风中颤动，将军拉开了他的弓简明。天刚亮时，去寻找尾部装有白色鸟羽箭矢。箭已射入石中。'),('shuimo-015','寄李儋元锡','韦应物','shuimo','','','去年花里逢君别，今日花开又一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几回圆。','','记得去年春天，在百花盛开的时节与君相逢而又分别。过了一年，又到花开时节。世事茫茫，难以预料。春愁使我心神黯淡，夜晚难以入睡。因身体多病而想念田园乡里。城邑中有百姓流离失所，真是愧对官吏的俸禄。听说你们想来探望我，我常在西楼盼望，已经有好几个月了'),('shuimo-016','赋得暮雨送李曹','韦应物','shuimo','','','楚江微雨里，建业暮钟时。
漠漠帆来重，冥冥鸟去迟。
海门深不见，浦树远含滋。
相送情无限，沾襟比散丝。','','在长江的小雨之中，在建业晚钟敲响的时候，水气弥漫，风帆被雨打湿，行驶沉重。天气昏暗，归鸟也迟迟飞去。遥望前方，海门深远而看不见，远处长江边的树林，饱含着水汽。朋友相送，怀着无限的深情，像密雨一样的眼泪纵横，打湿了我的衣襟。'),('shuimo-017','夕次盱眙县','韦应物','shuimo','','','落帆逗淮镇，停舫临孤驿。
浩浩风起波，冥冥日沉夕。
人归山郭暗，雁下芦洲白。
独夜忆秦关，听钟未眠客。','','傍晚，落下风帆，船舫停泊在淮水边的盱眙县，靠近一家孤独的驿站。晚风劲吹，水波浩荡，太阳西下，天色昏暗。人回归昏暗的山城，雁群落到芦苇开花的水洲。独自一人过夜，不禁思念家乡，一直到早上钟响，都不能入睡。'),('shuimo-018','长安遇冯着','韦应物','shuimo','','','客从东方来，衣上灞陵雨。
问客何为来，采山因买斧。
冥冥花正开，飏飏燕新乳。
昨别今已春，鬓丝生几缕。','','客人从长安东边来这里，衣服上还留着灞陵的雨水。询问客人近况，流露出买斧采山归隐的想法。春花正静静地开放，乳燕轻轻地飞翔。去年分别，现在又到春天，两鬓又增添了几缕白发。'),('shuimo-019','初发杨子寄元大校书','韦应物','shuimo','','','凄凄去亲爱，泛泛入烟雾。
归棹洛阳人，残钟广陵树。
今朝此为别，何处还相遇。
世事波上舟，沿洄安得住？。','','悲凄凄地离开相亲相爱的朋友，泛泛地漂流在烟雾一样的世界。乘上回归洛阳的船舫，在广陵的树下听晓钟的残音。今朝在这里分别，谁知在什么地方还能相遇？世事好像这漂泊在波涛上的小船，谁能把握自已的顺境和逆境呢？'),('shuimo-020','滁州西涧','韦应物','shuimo','','','独怜幽草涧边生，上有黄鹂深树鸣。
春潮带雨晚来急，野渡无人舟自横。','','特别喜爱看生长在涧边的幽雅的青草，绿阴深处，黄鹂在上面婉转地鸣叫。傍晚，春水如潮，再加上雨水来势紧急，郊野的渡口无人来往，渡船始终像原来的样子横在那里。'),('shuimo-021','秋夜寄邱员外','韦应物','shuimo','','','怀君属秋夜，散步咏凉天。
空山松子落，幽人应未眠。','','适逢秋夜天凉，我出外散步吟诗，不禁怀念起君来。空山分外幽静，只听见松子落地的声音。隐居的你，在这个时候一定还没有入睡。'),('shuimo-022','江乡故人偶集客舍','戴叔伦','shuimo','','','天秋月又满，城阙夜千重。
还作江南会，翻疑梦里逢。
风枝惊暗鹊，露草泣寒虫。
羁旅长堪醉，相留畏晓钟。','','秋天月又圆，照射着京城的宫阙，出现千道暗影。居然能在京城会集江南故人，反而怀疑是梦中相逢。风刮树枝，使藏身树上的鹊鸟惊恐，露水打湿青草，让寒虫吓得哭泣。作客他乡，可长夜醉饮，只怕晓钟一响，就难以相信了。'),('shuimo-023','题三闾大夫庙','戴叔伦','shuimo','','','沅湘流不尽，屈子怨何深。
日暮秋风起，萧萧枫树林。','','沅江、湘江的水长流不断，诉说着屈原多么深的怨恨。太阳西下，秋风萧瑟，枫树摇曳，恍惚中如见屈原归来。'),('shuimo-024','凉州曲','柳中庸','shuimo','','','关山万里远征人，一望关山泪满巾。
青海戍头空有月，黄沙碛里本无春。','','万里远征到边塞关山的将士，看见荒凉的边关不禁潸然泪下。戍守青海的将士头上空有一片明月，放眼望去，一片黄沙，大漠本来就没有春天。'),('shuimo-025','征人怨','柳中庸','shuimo','','','岁岁金河复玉关，朝朝马策与刀环。
三春白雪归青冢，万里黄河绕黑山。','','年年在边城，离开金河(大黑河)，又到玉门关。天天要打仗，要手执马鞭和刀环。晚春三月，大雪返回王昭君的青色的暮地。长途跋涉，战士行程万里，从黄河绕过黑山。'),('shuimo-026','宫词','顾况','shuimo','','','玉楼天半起笙歌，风送宫嫔笑语和。
月殿影开闻夜漏，水精帘卷近秋河。','','华丽的玉楼耸立在半天云霄，微风传送着笙歌笑语。云开月出，静听计时滴水的声音。卷上水晶帘儿，银河就在眼前。'),('shuimo-027','过山农家','顾况','shuimo','','','板桥人渡泉声，茅檐日午鸡鸣。
莫嗔焙茶烟暗，却喜晒谷天晴。','','渡过板桥，桥下泉水淙淙，到农家的茅屋屋檐下，正是日午鸡叫的时候。请不要讨厌焙茶时烟雾弥漫。在晒谷的时候，山民还喜欢天晴。'),('shuimo-028','石窦泉','顾况','shuimo','','','吹沙复喷石，曲折仍圆旋。
野客漱流时，杯粘落花片。','','春风吹拂，泉水就从石头的洞隙里喷出来，有的弯弯曲曲，有的打着圆圈。野外的游客在泉中洗漱时，杯子粘上落下的花瓣。'),('shuimo-029','欹松漪','顾况','shuimo','','','湛湛碧涟漪，老松欹侧卧。
悠扬绿萝影，下拂波纹破。','','碧绿湛湛的波涛上，老松树斜躺在岸边。疾风吹过，松枝摇曳，划破水中的涟漪，水面映照出它的倒影。'),('shuimo-030','石上藤','顾况','shuimo','','','空山无鸟迹，何物如人意。
委曲结绳文，离披草书字。','','荒凉的山崖没有鸟的踪迹，为何这种植物长得像有人修饰。藤蔓弯曲像古代结绳的文字，远看又像在石板上写的草书。'),('shuimo-031','宿石涧店闻妇人哭','李端','shuimo','','','山店门前一妇人，哀哀夜哭向秋云。
自说夫因征战死，朝来逢着旧将军。','','晚上，在山涧的旅店门前，有一位妇女对着天上的秋云悲哀地哭诉。问她为什么伤心，她说，早上碰见以前带领丈夫出征的那位将军回来，而自已的丈夫却死在战场上。'),('shuimo-032','芜城','李端','shuimo','','','风吹城上树，草没城边路。
城里月明时，精灵自来去。','','大风吹拂着生长在城墙边的树木，野草淹没了城边的大路。城里没有人迹，在月明的夜晚，精灵鬼怪自由自在地进出。'),('shuimo-033','听筝','李端','shuimo','','','鸣筝金粟柱，素手玉房前。
欲得周郎顾，时时误拂弦。','','一个女子在她的闺房，用她洁白纤细的手指弹着一张装饰着金星的华美的鸣筝。为了想得到像三国周瑜一样的知音的顾望，她不时地把弦故意拨错。'),('shuimo-034','秋晚宿破山寺','皎然','shuimo','','','秋风落叶满空山，古寺残灯石壁间。
昔日经行人尽去，寒云夜夜自飞还。','','秋风过后，落叶撒满空旷的山谷。石壁之间古老的寺庙中，残灯散发着微弱的光。往日在这里活动的人们都已走尽，只有寒冷的云夜夜飞回山寺的上空。'),('shuimo-035','寻陆鸿渐不遇','皎然','shuimo','','','移家虽带郭，野径入桑麻。
近种篱边菊，秋来未着花。
扣门无犬吠，欲去问西家。
报道山中去，归时每日斜。','','陆鸿渐移居到城边的农村，从小路穿过桑麻地。新近种在篱边的菊花，秋天来到还没有开花。敲门没有听见狗叫，就到西边的邻居家问问去向。邻居回答说：“他到山上去了，归来时常常是太阳落山”。'),('shuimo-036','江村即事','司空曙','shuimo','','','钓罢归来不系船，江村月落正堪眠。
纵然一夜风吹去，只在芦花浅水边。','','钓完鱼回来不必把船系好，江村上空的月亮落了，正是睡觉的好时候。即使吹一夜的风，船也不会飘远，只会在芦花浅水边。'),('shuimo-037','云阳馆与韩绅宿别','司空曙','shuimo','','','故人江海别，几度隔山川。
乍见翻疑梦，相悲各问年。
孤灯寒照雨，深竹暗浮烟。
更有明朝恨，离杯惜共传。','','与老朋友(故人)在长江下游一带分别，几年来远隔山水。忽然相见反而怀疑是在梦中，都伤感地问对方分别多少年了。云阳馆的孤灯寒冷地映照着窗外的雨帘，竹林深处升起雨雾。明天一早更有遗恨的事情，依依惜别，两相传递饯别之杯。'),('shuimo-038','喜外弟卢纶见宿','司空曙','shuimo','','','静夜四无邻，荒居旧业贫。
雨中黄叶树，灯下白头人。
以我独沉久，愧君相见频。
平生自有分，况是蔡家亲。','','居住在荒僻的地方，周围没有邻居，夜晚特别安静。原来的家业丧失殆尽，家徒四壁。在雨中，枯黄的树叶飘零，灯下有我白发老人。因我长久地孤独沉沦，有愧于君的多次看望。平素就有情分，何况还有表亲呢。'),('shuimo-039','留卢秦卿','司空曙','shuimo','','','知有前期在，难分此夜中。
无将故人酒，不及石尤风。','','知道在这以前就决定，今天晚上就要分手，实在是难分难舍。老朋友备酒也留不住你，岂不是故人的酒，不及石尤风(阻挡行船的逆风)能阻止你的行程！'),('shuimo-040','酬李甫见赠','元稹','shuimo','','','杜甫天才颇绝伦，每寻诗卷似情亲。
怜渠直道当时语，不着心源傍古人。','','杜甫是天才绝伦的诗人，他创作的诗卷读来似亲人、似情愫。喜欢直截了当地说当时的语言，不是一味地依傍古人。所以说，杜甫的诗有创新的功劳'),('shuimo-041','闻乐天授江州司马','元稹','shuimo','','','残灯无焰影幢幢，此夕闻君谪九江。
垂死病中惊坐起，暗风吹雨入寒窗。','','残灯已没有火焰，周围留下模糊不清的影子，这时听说君被贬官九江。在垂死的重病中，我被这个消息震惊得坐了起来，暗夜的风雨吹进我窗户，感觉分外寒冷。'),('shuimo-042','古筑城曲（二首）','元稹','shuimo','','','筑城须努力，城高遮得贼。
但恐贼路多，有城遮不得。','','筑城安敢烦，愿听丁一言。请筑鸿胪寺，兼愁虏出关。 努力地修筑长城，长城高就可以阻挡盗贼的入侵。但是恐怕盗贼的路子多，就是有长城也阻挡不了。 筑城不敢厌烦，但愿能听取一种说法。希望多修筑接待外宾的像鸿胪寺这样的宫室，况且城防坚固，反使俘虏不能出去，必为内乱。'),('shuimo-043','寒食','韩竑','shuimo','','','春城无处不飞花，寒食东风御柳斜。
日暮汉宫传蜡烛，轻烟散入五侯家。','','春天的京城无处不繁华似锦。寒食节这天，东风吹拂，宫廷的柳树迎风摇曳。家家禁火，可傍晚时分宫廷的蜡烛传来传去，幽暗的烛光进入了天子宠幸的五侯之家。'),('shuimo-044','枫桥夜泊','张继','shuimo','','','月落乌啼霜满天，江枫渔火对愁眠。
姑苏城外寒山寺，夜半钟声到客船。','',''),('shuimo-045','行宫','元稹','shuimo','','','寥落古行宫，宫花寂寞红。
白头宫女在，闲坐说玄宗。','','过去的行宫一片冷落，宫中的春花再无人欣赏。白头发的宫女住在里面，闲谈玄宗往事。'),('shuimo-046','渔翁','柳宗元','shuimo','','','渔翁夜傍西岩宿，晓汲清湘燃楚竹。
烟销日出不见人，唉乃一声山水绿。
回看天际下中流，岩上无心云相逐。','',''),('shuimo-047','江雪','柳宗元','shuimo','','','千山鸟飞绝，万径人踪灭。
孤舟蓑笠翁，独钓寒江雪。','',''),('shuimo-048','将牛何处去（二首）','元结','shuimo','','','将牛何处去，耕彼故城东。
相伴有田父，相欢惟牧童。','','将牛何处去，耕彼西阳城。叔闲修家具，直者伴我耕。 牵牛到什么地方去？去故城东耕种那里的田地。老农和我做伴，还有牧童高兴地在那里玩耍。牵牛到什么地方去？去耕种西阳城的田地。叔闲帮助修农具，长子和我一道耕种。'),('shuimo-049','月夜','刘方平','shuimo','','','更深月色半人家，北斗阑干南斗斜。
今夜偏知春气暖，虫声新透绿窗纱。','','更深夜静，星移斗转，月光斜射半个庭院。今夜，我出乎意料地感知春天温暖的气息，因为昆虫的叫声透过绿色的窗纱传来。'),('shuimo-050','采莲曲','刘方平','shuimo','','','落日清江里，荆歌艳楚腰。
采莲从小惯，十五即乘潮。','','西落的太阳余辉照着清澈的江水，荆楚民歌让姑娘们更艳丽。她们从小习惯采莲，十五岁一过就开始上船在水中劳动。'),('shuimo-051','春雪','刘方平','shuimo','','','飞雪带春风，徘徊乱绕空。
君看似花处，偏在洛城东。','','春风携带着雪花，在空中徘徊、狂舞。请君观察，在洛城东的豪门宅第，雪花并不寒冷，并像花一样美。'),('shuimo-052','逢入京使','岑参','shuimo','','','故园东望路漫漫，双袖龙钟泪不干。
马上相逢无纸笔，凭君传语报平安。','','向东望见通往长安故乡的漫漫长路，双袖擦不干泪水长流。在马上与你相遇没有准备纸和笔，请君带口信给家中报平安。'),('shuimo-053','白雪歌送武判官归京','岑参','shuimo','','','北风卷地白草折，胡天八月即飞雪。
忽如一夜春风来，千树万树梨花开。
散入珠帘湿罗幕，狐裘不暖锦衾薄。
将军角弓不得控，都护铁衣冷难着。
瀚海阑干百丈冰，愁云惨淡万里凝。
中军置酒饮归客，胡琴琵琶与羌笛。
纷纷暮雪下辕门，风掣红旗冻不翻。
轮台东门送君去，去时雪满天山路。
山回路转不见君，雪上空留马行处。','','祖国西北的天空飘着鹅毛大雪，北风席卷大地，刮断了大雪染白的野草。像忽然吹来一夜春风，千树万树上的白雪如花开满枝头。雪花飘进珠帘，浸湿罗幕，即便穿着狐皮袄也不暖和，盖着锦缎被也不能御寒。将军的角弓不能拉开，都护的铁甲冰冷但还要穿在身上。浩瀚如海的沙漠纵横百丈冰层，阴沉沉的愁云凝聚在万里天空。中军备酒招待回去的客人，并吹奏胡琴、琵琶和羌笛助兴。暮雪纷纷飘进军营，旌旗冻硬，寒风无法吹动它。在轮台东门送君，大雪覆盖通往天山的路。山回路转，不一会儿就看不见君，在雪地上只留下马蹄的印迹。'),('shuimo-054','苜蓿峰寄家人','岑参','shuimo','','','苜蓿峰边逢立春，葫芦河上泪沾巾。
闺中只是空相忆，不见沙场愁杀人。','','我到苜蓿峰边正是立春那一天，见葫芦河还结着厚厚的冰层，不禁泪湿衣襟。家人只是想念远征的亲人，而远戍沙场的愁苦他们怎么知道呢？'),('shuimo-055','碛中作','岑参','shuimo','','','走马西来欲到天，辞家见月两回圆。
今夜未知何处宿，平沙万里绝人烟。','','骑马西行几乎来到天边，离开家乡将近两月。今天晚上我将住宿什么地方？眼前是万里平沙无人烟。'),('shuimo-056','山房春事','岑参','shuimo','','','梁园日暮乱飞鸦，极目箫条三两家。
庭树不知人去尽，春来还发旧时花。','','梁园黄昏的时候，鸦雀乱飞，放眼望去，只见萧条衰败的几户人家。庭院的树木花草不知时过境迁，春天到来时还像过去一样花开茂盛。'),('shuimo-057','行军九日思长安故园','岑参','shuimo','','','强欲登高去，无人送酒来。
遥怜故园菊，应傍战场开。','',''),('shuimo-058','暮秋山行（节选）','岑参','shuimo','','','疲马卧长坂，夕阳下通津。
山风吹空林，飒飒如有人。','','夕阳照射着通向渡口的道路，疲惫的马卧在山坡旁歇息。山风吹过空旷的树林，发出飒飒的响声，树林里面好像有人的声音。'),('shuimo-059','题三会寺仓颉造字台','岑参','shuimo','','','野寺荒台晚，寒天古木悲。
空阶有鸟迹，犹似造书时。','','傍晚，来到这荒野寺庙的古台，天气寒冷，古老的树木在冷风中悲鸣。三会寺的空阶上只残留鸟的足迹，就像仓颉当年造字的时候一样。');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('shuimo-060','送李中丞归汉阳别业','刘长卿','shuimo','','','流落征南将，曾驱十万师。
罢归无旧业，老去恋明时。
独立三边静，轻生一剑知。
茫茫江汉上，日暮欲何之。','','曾经是率领十万兵马的征南将军，如今流落他乡。辞官之后没有过去的事业，老迈时留恋圣明的时代。独自治理边塞平静，不怕牺牲的精神只有我的佩剑知道。在茫茫的汉水，太阳下山了，谁知道它将去哪里！'),('shuimo-061','秋日登吴公台上寺远眺','刘长卿','shuimo','','','古台摇落后，秋入望乡心。
野寺来人少，云峰隔水深。
夕阳依旧垒，寒磬满空林。
惆怅南朝事，长江独至今。','','古台零落之后，又一个秋天来到，勾起人们思念故乡之情。荒郊野寺很少有来客，高耸入云的山峰远隔深深的江水。夕阳依傍古老的台垒，寒冷的磬声充满空旷的山林。为南朝的兴衰而惆怅，惟有长江水，滚滚向东至今没有改变。'),('shuimo-062','寻南溪常道士','刘长卿','shuimo','','','一路经行处，莓苔见屐痕。
白云依静渚，芳草闭闲门。
过雨看松色，随山到水源。
溪花与禅意，相对亦忘言。','','一路行走过来的地方，青苔上出现鞋的痕迹。白云依傍安静的小洲，芳草封闭闲置的园门。山雨过后松色更美，环山找到了水的源头。溪景与禅意相互默喻，不需要言词表达。'),('shuimo-063','送灵澈','刘长卿','shuimo','','','苍苍竹林寺，杳杳种声晚。
荷笠带斜阳，青山独归远。','','暮色苍茫笼罩着的竹林寺，傍晚从远处传来阵阵钏声。在夕阳的辉映中，灵澈和尚肩负斗笠，他孤独的身影消失在那遥远的青山中。'),('shuimo-064','逢雪宿鞭蓉山主人','刘长卿','shuimo','','','日暮苍山远，天寒白屋贫。
柴门闻犬吠，风雪夜归人。','','太阳下山，风雪到来，青山显更加模糊遥远。投宿一家贫寒的山民家，他家的房屋空空，很有几分寒冷。深夜，用柴草编成的门外传来狗的叫声，主人冒雪归来。'),('shuimo-065','早梅','张谓','shuimo','','','一权寒梅白玉条，迥临村路傍溪桥。
不知近水花先发，疑是经冬雪未销。','','在远离村路的小溪桥边，满树早梅凌寒开放，像一条条白玉。如果不知道这棵梅树靠近溪水而花先开放，还怀疑是经冬的冰雪没有融化哩。'),('shuimo-066','登高','杜甫','shuimo','','','风急天高猿啸哀，渚清沙白鸟飞回。
无边落木萧萧下，不尽长江滚滚来。
万里悲秋常作客，百年多病独登台。
艰难苦恨繁霜鬓，潦倒新停浊酒杯。','','天高风急，猿猴叫声凄哀，清澈的小岛和白色的沙滩上，水鸟回旋。落叶萧萧，没有着落地飘零，流不尽的长江水滚滚向东。万里飘泊，悲愁无限。一生多病灾，今孤独地登上高台。时事艰难，遗恨白发染鬓；穷愁潦倒，新近连酒也停饮了。'),('shuimo-067','登楼','杜甫','shuimo','','','花近高楼伤客心，万方多难此登临。
锦江春色来天地，玉垒浮云变古今。
北极朝廷终不改，西山寇盗莫相侵。
可怜后主还祠庙，日暮聊为《梁父吟》。','',''),('shuimo-068','野望','杜甫','shuimo','','','西山白雪三城戍，南浦清江万里桥。
海内风尘诸弟隔，天涯涕泪一身遥。
惟将迟暮供多病，未有涓埃答圣朝。
跨马出郊时极目，不堪人事日萧条。','','安史之乱尚未平息，国内战火纷飞，外族乘机侵入，作者困居成都。这首诗通过出郊野望的描写，表达作者忧国思亲的沉痛心情。 西山覆盖白雪，松州、维州、保州有重兵防守；成都市南的锦江边矗立着万里桥(万里之行，始于此桥)。四海之内战火纷飞，和弟弟们离散，飘泊天涯孤独一身不禁伤感泪下。只能把晚年交给这多病之身，没有半点功劳报答圣明的朝廷。骑着马来到郊外放眼望去，禁受不了人间世事一天比一天萧条、衰败。'),('shuimo-069','阁夜','杜甫','shuimo','','','岁暮阴阳催短景，天涯霜雪霁寒宵。
五更鼓角声悲壮，三峡星河影动摇。
野哭几家闻战伐，夷歌数处起渔樵。
卧龙跃马终黄土，人事音书漫寂寥。','','年末的节令催促得白昼变短，天涯漂泊的我，在这雪后的夜晚，觉得更加寒冷。五更时传来军营悲壮的战鼓和号角声，三峡江面，星河的倒影在摇动。从传来的几家野外的哭声听到战争的信息，多处渔人和樵夫在唱夷族的歌谣。卧龙诸葛亮、跃马称帝的公孙述这样的英雄人物终究成为黄土，人情世事信息带来不尽的寂寞和空虚。'),('shuimo-070','客至','杜甫','shuimo','','','舍南舍北皆春水，但见群鸥日日来。
花径不曾缘客扫，蓬门今始为君开。
盘飧市远无兼味，樽酒家贫只旧醅。
肯与邻翁相对饮，隔篱呼取尽馀杯。','','房前屋后都是花溪的春水，只见群鸥天天飞来飞去。平日很少来客，今天因崔君到来特意打扫花径，开蓬门迎接。集市路远，盘中只有单一的菜肴，家贫只能喝几樽未过滤的老陈酒。客人如乐意与邻居老翁共饮，不妨隔篱唤他来一道干杯。'),('shuimo-071','绝句三首','杜甫','shuimo','','','前年渝州杀刺史，今年开州杀刺吏。
群盗相随剧虎狼，食人更肯留妻子。
二十一人同入蜀。
惟残一人出骆谷。
自说二女啮臂时，回头却向秦云器。
殿前兵马虽骁雄，纵暴略与羌浑同。
闻道杀人汉水上，妇女多在官军中。','','前年渝州刺史被杀，今年开州刺史被杀。盗贼四起比虎狼还凶，虎狼食人尚留下妻子。 一家二十一口 逃难到蜀地，只剩下一人离开骆谷。说到两个女儿被掠时生离死别的情景，不禁向天嚎啕大哭。禁军兵马可称骁勇，施暴大略和党项羌、吐谷浑差不多。听说在汉水杀了很多人，把妇女留在军营。'),('shuimo-072','江南逢李龟年','杜甫','shuimo','','','岐王宅里寻常见，崔九堂前几度闻。
正是江南好风景，落花时节又逢君。','',''),('shuimo-073','赠花卿','杜甫','shuimo','','','锦城丝管日纷纷，半入江风半入云。
此曲只应天上有，人间能得几回闻？。','','锦城(今四川成都)的弦乐声每日纷纷不断，随江风直上云天，声高传播远。这些曲子应是天宫(暗示皇宫)才有的，人间哪里能够听得到几次呢？'),('shuimo-074','江畔独步寻花','杜甫','shuimo','','','黄四娘家花满蹊，千朵万朵压枝低。
留连戏蝶时时舞，自在娇莺恰恰啼。','',''),('shuimo-075','绝句','杜甫','shuimo','','','两个黄鹂鸣翠柳，一行白鹭上青天。
窗含西岭千秋雪，门泊东吴万里船。','',''),('shuimo-076','旅夜书怀','杜甫','shuimo','','','细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章着，官应老病休。
飘飘何所似，天地一沙鸥。','','微风吹拂着岸边的小草，这艘竖着高高桅杆的船在夜里孤独地停泊着。星星好像低垂到辽阔原野的地平线上，月影随波起伏，大江滚滚东流。有名声，难道仅因为文章好？做官却因年老多病而退下。飘然一生像什么？只是天地中的一只沙鸥罢了。'),('shuimo-077','别房太尉墓','杜甫','shuimo','','','他乡复行役，驻马别孤坟。
近泪无干土，低空有断云。
对棋陪谢傅，把剑觅徐君。
唯见林花落，莺啼送客闻。','','在他乡东奔西走，今日骑马来告别埋有你的孤坟。泪下如雨，使得身边的泥土都潮湿了，抬头只见天上飘着浮云。我们的经历和友谊像历史上谢太傅举荐谢玄和吴国季握剑寻觅喜欢宝剑的徐君似的。想着想着只见林中遍地落花，听莺鸟啼叫，似乎在送客呢。'),('shuimo-078','登岳阳楼','杜甫','shuimo','','','昔闻洞庭水，今上岳阳楼。
吴楚东南坼，干坤日夜浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。','','从前就听说洞庭湖水的浩瀚，今天有机会登上岳阳楼亲眼一见。古代的吴和楚被洞庭湖分成东西两部分，湖面宽广，从城楼望去，整个天地都像日夜在湖面上浮动。亲朋没有一点消息，年老且生病只能孤独困在船上。关山以北战事不断，倚凭着岳阳楼的栏杆，不禁泪流满面。'),('shuimo-079','望岳','杜甫','shuimo','','','岱宗夫如何？齐鲁青未了。
造化钟神秀，阴阳割昏晓。
荡胸生层云，决眦入归鸟。
会当凌绝顶，一览众山小。','','泰山的风景如何？远远望去齐鲁一带一片青翠苍茫。泰山聚集了大自然的神奇秀美，山南和山北被分割出明暗不同，可见其高峻。坦荡的胸怀可以装下层层云雾，睁大眼眶尽收归林的飞鸟。一定要登上泰山最高处，看一看比它小得多的众山。'),('shuimo-080','春宿左省','杜甫','shuimo','','','花隐掖垣暮，啾啾栖鸟过。
星临万户动，月傍九霄多。
不寝听金钥，因风想玉珂。
明朝有封事，数问夜如何？。','','天色已晚，百花隐没在左省宫墙，百鸟鸣叫着飞回巢穴。星星照耀宫中的千门万户，月亮靠近高耸入云的宫殿。不能入睡，听见开宫门的金锁的声音；因为夜风吹拂，想起百官上朝时的马铃声。明日早晨还有奏章要呈给皇帝，多次探问快天亮了吗？'),('shuimo-081','八阵图','杜甫','shuimo','','','功盖三分国，名成八阵图。
江流石不转，遗恨失吞吴。','',''),('shuimo-082','黄鹤楼','崔颢','shuimo','','','昔人已乘黄鹤去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，芳草萋萋鹦鹉洲。
日暮乡关何处是？烟波江上使人愁。','','过去的人(指传说已成仙的三国时人费文)已骑着黄鹤飞离而去，此地只留下空空的黄鹤楼。黄鹤一去不再回来，千百年来只留下白云悠悠飘荡。阳光照耀下，可以清晰地看见汉阳的景物以及芳草茂盛的鹦鹉洲。太阳下山了，何处是故乡？在这烟雾笼罩的江面，真教人悲愁不已啊！'),('shuimo-083','次北固山下','王湾','shuimo','','','客路青山外，行舟绿水前。
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达？归雁洛阳边。','','大路绕过青山之外，船在绿水中向前航行。潮平息，江面宽阔；风顺，白帆高挂。在夜将尽未尽之时，海上一轮红日升起；江上萌动的春意，在旧年未尽时提前到来。写回家乡的书信到什么地方去寄？要到归雁经过的洛阳附近。'),('shuimo-084','登金陵凤凰台','李白','shuimo','','','凤凰台上凤凰游，凤去台空江自流。
吴宫花草埋幽径，晋代衣冠成古丘。
三山半落青天外，一水中分白鹭洲。
总为浮云能蔽日，长安不见使人愁。','','传说凤凰台上有凤凰飞游，现在凤凰飞走，只留下空台和滔滔江水。三国时吴国孙权的宫殿和奇花异草，都淹没在荒僻的小路之中。东晋的豪门望族都变成了一座座古墓。有三峰相接的护国山，一半被云遮住，好像落在青天之外，一条长江被白鹭洲从中分为两支。只因为浮云能遮蔽太阳，看不见长安使人悲愁。'),('shuimo-085','黄鹤楼送孟浩然之广陵','李白','shuimo','','','故人西辞黄鹤楼，烟花三月下扬州。
孤帆远影碧空尽，惟见长江天际流。','',''),('shuimo-086','早发白帝城','李白','shuimo','','','朝辞白帝彩云间，千里江陵一日还。
两岸猿声啼不住，轻舟已过万重山。','',''),('shuimo-087','夜泊牛渚怀古','李白','shuimo','','','牛渚西江夜，青天无片云。
登舟望秋月，空忆谢将军。
余亦能高咏，斯人不可闻。
明朝挂帆席，枫叶落纷纷。','','西江(从江西到南京的长江江面)牛渚山之夜，青天没有一片云彩。站在船头看秋月，徒然思念东晋的谢尚将军。我还能高声咏诗，却再不能听说有谢将军那样的人了。明早张帆而去，在枫叶纷纷飘落的江上远行。'),('shuimo-088','子夜吴歌','李白','shuimo','','','长安一片月，万户捣衣声。
秋风吹不尽，总是玉关情。
何日平胡虏，良人罢远征。','','长安明月高照，家家户户传来捶打衣服的声音。秋风不断地吹，吹不尽对远征在玉门关外的丈夫的怀念之情。不知何日能平定北方的入侵者，丈夫才可以停止远征，返回家园？'),('shuimo-089','古朗月行（节选）','李白','shuimo','','','小时不识月，呼作白玉盘。
又疑瑶台镜，飞在青云端。
仙人垂两足，桂树何团团。
白兔捣药成，问言与谁餐。','','我小时候不认识月亮，叫它白玉盘，又怀疑它是瑶台仙镜，飞到了青云之上。传说月亮中有仙人，月亮刚升起的时候，能看见仙人的两只脚，为什么我却只看见团团的桂树。传说月中有玉兔捣药，不知它捣药给谁吃？'),('shuimo-090','秋浦歌','李白','shuimo','','','白发三千丈，缘愁似个长。
不知明镜里，何处得秋霜？。','',''),('shuimo-091','怨情','李白','shuimo','','','美人卷珠帘，深坐颦蛾眉。
但见泪痕湿，不知心恨谁？。','','珠帘高卷，美女深坐闺阁愁眉不展。只见她眼泪涟涟，却不知她心里在怨恨哪一个。'),('shuimo-092','送李少府贬峡中 王少府贬长沙','高适','shuimo','','','嗟君此别意何如，驻马衔杯问谪居。
巫峡啼猿数行泪，衡阳归雁几封书。
青枫江上秋帆远，白帝城边古木疏。
圣代即今多雨露，暂时分手莫踌躇。','','不知这次分别二位的心情如何，停下马来饯别，询问贬谪的地方。巫峡一带常有猿猴啼叫，十分凄凉；长沙虽然遥远，但相传雁飞到衡阳而北返可以传递书信。青枫江(位于长沙市南)上秋风萧瑟，远望白帆点点，白帝城边树木凋零，一派荒凉稀疏的景象。圣明的时代，君王多施雨露(恩泽)，暂时分别不要犹豫向前。'),('shuimo-093','别董大','高适','shuimo','','','千里黄云白日曛，北风吹雁雪纷纷。
莫愁前路无知己，天下谁人不识君？。','',''),('shuimo-094','九月九日忆山东兄弟','王维','shuimo','','','独在异乡为异客，每逢佳节倍思亲。
遥知兄弟登高处，遍插茱萸少一人。','',''),('shuimo-095','送元二使安西','王维','shuimo','','','渭城朝雨浥轻尘，客舍青青柳色新。
劝君更尽一杯酒，西出阳关无故人。','','渭城的一场晨雨洗涤了灰尘，客店外的柳色青翠一新。劝你再饮一杯酒，西出阳关，路途遥远，再无老友关怀。'),('shuimo-096','嫦娥','李商隐','shuimo','','','云母屏风烛影深，长河渐落晓星沉。
嫦娥应悔偷灵药，碧海青天夜夜心。','','云母石装饰的屏风旁，烛影深深；银河西移，启明星渐渐消失。月中仙女嫦娥应当懊悔当初偷吃了不死灵药，以致在月宫夜夜对着碧海青天，过着孤寂凄冷的生活。'),('shuimo-097','锦瑟','李商隐','shuimo','','','锦瑟无端五十弦，一弦一柱思华年。
庄生晓梦迷蝴蝶，望帝春心托杜鹃。
沧海月明珠有泪，蓝田日暖玉生烟。
此情可待成追忆，只是当时已惘然。','','精美的瑟没来由地有五十根弦，而我年近五十，每一根弦和柱都触发对盛年之思。庄周曾经梦见自已化身成了蝴蝶；望帝被迫让国，死后将自已伤春的情思托付给杜鹃鸟。大海月明之时，珠是由眼泪变成的。阳光下蓝田玉的光泽犹如烟霭，被弃置是何等悲哀！以上的情怀和感受岂待回忆时才有，在当时就已经让人失意惘然了。'),('shuimo-098','汉江临眺','王维','shuimo','','','楚塞三湘接，荆门九派通。
江流天地外，山色有无中。
郡邑浮前浦，波澜动远空。
襄阳好风日，留醉与山翁。','',''),('shuimo-099','送黎拾遗','王维','shuimo','','','相送临高台，川原杳何极！日暮飞鸟还，行人去不息。','','登上高台送别黎昕，只见山川原野广阔遥远。太阳落山时，飞鸟回到自已的林中巢穴，远行的人一去不再回来。'),('shuimo-100','竹里馆','王维','shuimo','','','独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。','',''),('shuimo-101','相思','王维','shuimo','','','红豆生南国，春来发几枝？愿君多采撷，此物最相思。','','经豆生长在南方，春天来到，它又长出了多少新的枝条？劝你多彩撷一些经豆，因为它能唤起你思念的情感。'),('shuimo-102','送别','王维','shuimo','','','山中相送罢，日暮掩柴扉。
春草明年绿，王孙归不归？。','',''),('shuimo-103','鹿柴','王维','shuimo','','','空山不见人，但闻人语响。
返影入深林，复照青苔上。','',''),('shuimo-104','鸟鸣涧','王维','shuimo','','','人闲桂花落，夜静春山空。
月出惊山鸟，时鸣春涧中。','','春夜静悄悄，独自在洒满桂花的山路上悠闲地行走，春山空寂。月亮从云层中露出来，惊动了山林的鸟雀，它们的鸣叫声不时地回荡在春夜的溪涧之中。'),('shuimo-105','终南望余雪','祖咏','shuimo','','','终南阴岭秀，积雪浮云端。
林表明霁色，城中增暮寒。','',''),('shuimo-106','芙蓉楼送辛渐','王昌龄','shuimo','','','寒雨连江夜入吴，平明送客楚江孤。
洛阳亲友如相问，一片冰心在玉壶。','',''),('shuimo-107','出塞','王昌龄','shuimo','','','秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。','',''),('shuimo-108','塞下曲','王昌龄','shuimo','','','饮马渡秋水，水寒风似刀。
平沙日未没，黯黯见临洮。
昔日长城战，咸言意气高。
黄尘足今古，白骨乱蓬蒿。','','秋凉了，戍边的将士们饮马渡江，水冰凉风似刀割。放眼望去，太阳还没西落，只见一片沙漠。远望临洮(今甘肃岷县，秦时长城的起点)已是昏暗不清。联想到从前在这一带进行的激烈的战斗，将士们意气风发，斗志高昂。这里从古到今都是黄沙充塞的征战之地，战死者的白骨混迹在野草之中。'),('shuimo-109','塞上曲','王昌龄','shuimo','','','蝉鸣空桑林，八月萧关道。
出塞复入塞，处处共芦草。
从来幽并客，皆共尘沙老。
莫学游侠儿，矜夸紫骝好。','','蝉在叶子已经柘落的桑树林中鸣叫。八月，只见在萧关的道路上，士兵频繁地出塞入塞，到处芦草枯黄，一片荒凉。从古至今幽州和并州的健儿都在沙场度过一生。不要学那些游侠儿，只知夸耀自已的紫骝骏马。'),('shuimo-110','早寒有怀','孟浩然','shuimo','','','木落雁南度，北风江上寒。
我家襄水曲，遥隔楚云端。
乡泪客中尽，孤帆天际看。
迷津欲有问，平海夕漫漫。','','树叶飘零，北雁南飞，北风吹冷了江滩。我家住在襄水边，相隔在遥远的楚国云天之下。流尽了情乡之泪，遥望天边的一叶孤舟。要问出路在哪里，黄昏时，江水滔滔，与海相平，一片茫茫。'),('shuimo-111','过故人庄','孟浩然','shuimo','','','故人具鸡黍，邀我至田家。
绿树村边合，青山郭外斜。
开轩面场圃，把酒话桑麻。
待到重阳日，还来就菊花。','','老朋友准备了鸡和黍等农家饭菜，邀请我去他家做客。绿树围绕着村庄，青山在城外斜立。打开窗户，就可以看到打谷场地和菜园，我们一边喝酒，一边畅谈农事。等到九九重阳，我还要来饮酒赏菊。'),('shuimo-112','岁暮归南山','孟浩然','shuimo','','','北阙休上书，南山归敝庐。
不才明主弃，多病故人疏。
白发催年老，青阳逼岁除。
永怀愁不寐，松月夜窗虚。','','休要到北阙(宫殿北面的门楼)，还是回到南山破败的家园吧。自已而被君主舍弃，多病又被过去的亲戚朋友疏远。白发催人年老，新春逼走旧岁。漫漫长夜，满怀愁绪无法入睡，陪伴自已的只有窗外松林月夜的空寂。'),('shuimo-113','宿建德江','孟浩然','shuimo','','','移舟泊烟渚，日暮客愁新。
野旷天低树，江清月近人。','',''),('shuimo-114','咏柳','贺知章','shuimo','','','碧玉妆成一树高，万条垂下绿丝绦。
不知细叶谁裁出，二月春风似剪刀。','',''),('shuimo-115','登幽州台歌','陈子昂','shuimo','','','前不见古人，后不见来者。
念天地之悠悠，独怆然而涕下！。','','向前看不见古人，向后看不见来者，我是多么孤独！想到天地是何等广阔，我一个人却在这里伤感得泪如雨下！'),('shuimo-116','晓发','贺知章','shuimo','','','故乡杳无际，江皋闻曙钟。
始见沙上鸟，犹埋云外峰。','','这首诗描写了晓雾初开清晨的景色，表达了作者对故乡的眷恋和对前路的渺茫之感。 故乡已是遥远而没有边际，江岸传来了清晨的钟声。近处可以清晰地看见沙滩的水鸟，远处的山峰还隐没于云雾之中。'),('shuimo-117','易水送人','骆宾王','shuimo','','','此地别燕丹，壮发上冲冠。
昔时人已没，今日水犹寒。','','在这个地方荆轲告别燕太子丹，慷慨赴义，怒发冲冠。岁月匆匆，过去的人都不在了，只留下易水还和当年一样冰冷。'),('shuimo-118','早春','韩愈','shuimo','','','天街小雨润如酥，草色遥看近却无。
最是一年春好处，绝胜烟柳满皇都。','','这首诗是作者对唐代京城长安的早春美景的描绘与赞美。 蒙蒙细雨在长安街道上，像酥油一样地滋润着大地。远远望去，只见小草一片嫩绿，近看却稀稀疏疏，像是没有什么。正是一年春天最美好的时光，大大地胜过满长安花红柳绿的晚春时节。'),('shuimo-119','问刘十九','白居易','shuimo','','','绿蚁新醅酒，红泥小火炉。
晚来天欲雪，能饮一杯无？。','','此诗表现白居易的好客。 新酿的美酒，酒滓像绿蚂蚁一样浮在表面，用红泥做的小火炉刚温好酒。晚上天要下雪了，来饮一杯吗？'),('shuimo-120','闺怨词','白居易','shuimo','','','关山征戍远，闺阁别离难。
苦战应憔悴，寒衣不要宽。','','诗写闺阁的妇女为远征的亲人制作寒衣，不仅表现思念心切，还从侧面反映戍边生活的艰苦卓绝。 到偏远的边关要塞去打仗，家人难分难舍。经历许多艰苦的战斗，人一定会消瘦，寒衣不要做得太宽大。'),('shuimo-121','赋得古原草送别','白居易','shuimo','','','离离原上草，一岁一枯荣。
野火烧不尽，春风吹又生。','',''),('shuimo-122','浪淘沙','刘禹锡','shuimo','','','九曲黄河万里沙，浪淘风簸自天涯。
如今直上银河去，同到牵牛织女家。','','此诗写九曲黄河的雄伟气势，并展开奇特的想像，表现作者非凡的向往与追求。 弯弯曲曲的黄河来自天涯，奔腾万里，它携带的泥沙也经历浪淘风簸。如今我想沿着黄河滚滚的波涛，直上九天银河，到牵牛星和织女星的家中去做客。'),('shuimo-123','望洞庭','刘禹锡','shuimo','','','湖光秋月两相和，潭面无风镜未磨。
遥望洞庭山水翠，白银盘里一青螺。','','这首诗是写洞庭湖的秋色夜景，给人以美的享受。 秋夜，湖水的波光和月光两相融合，湖上没有风浪，水面像没有经过打磨的铜镜。远望洞庭的山(即君山)和水一片青翠，好像银白色的盘子里放着一颗青色的田螺。'),('shuimo-124','乌衣巷','刘禹锡','shuimo','','','朱雀桥边野草花，乌衣巷口夕阳斜。
旧时王谢堂前燕，飞入寻常百姓家。','','此诗通过对南京淮河一带景物的描绘，今昔对比，表达作者怀古的悠思。 朱雀桥边长满丛丛野草，花开点点，夕阳斜照在乌衣巷口，一片荒凉的景象。昔日飞进王导和谢安他们家豪华的厅堂的燕子，现在飞进了普通百姓的家。'),('shuimo-125','竹枝词','刘禹锡','shuimo','','','杨柳青青江水平，闻郎江上唱歌声。
东边日出西边雨，道是无晴还有晴。','','此诗是作者模仿民歌创作的情歌，以少女的口吻表现朦胧的初恋。 杨柳青青，江水平如明镜，传来了郎哥在江上唱歌的声音。东边还有太阳，西边却下着雨，要说是无晴(情)却是有晴(情)。'),('shuimo-126','西塞山怀古','刘禹锡','shuimo','','','王浚楼船下益州，金陵王气黯然收。
千寻铁锁沉江底，一片降幡出石头。
人世几回伤往事，山形依旧枕寒流。
从今四海为家日，故垒萧萧芦荻秋。','','因不满当时朝政腐败，藩镇割据的局面，作者在经过西塞山时写下此诗，凭吊古人，抒发感慨。 当年西晋王浚统率水军从益州出发的时候，金陵东吴政权呈现出要灭亡的黯淡景象。几百丈的铁锁链被烧毁沉在江底，石头城出现一片白旗投降。人世间有几个王朝的兴亡使人伤感，而西塞山临靠长江，依旧不变。现在是四海为家的统一局面，旧时营垒却隐伏在秋风萧萧的芦荻之中。'),('shuimo-127','春词','刘禹锡','shuimo','','','新妆宜面下朱楼，深锁春光一院愁。
行到中庭数花朵，蜻蜓飞上玉搔头。','','这首诗咏叹贵族少妇的春愁。 刚施好匀称的脂粉走下朱楼，春光被深深锁住，庭院尽是哀愁。走到中庭数花朵，蜻蜓飞落在她头上的碧玉簪头上。'),('shuimo-128','石头城','刘禹锡','shuimo','','','山围故国周遭在，潮打空城寂寞回。
淮水东边旧时月，夜深还过女墙来。','','石头城一直是六朝的国都，唐被废弃。诗咏古城，寄寓作者对今昔盛衰的感慨。 环绕着故国的山脉还在，潮水拍打空城。秦淮河东边挂着的还是过去那个月亮，夜深时，月光还像过去一样，透过城墙上的城垛照射过来。'),('shuimo-129','雁门太守行','李贺','shuimo','','','黑云压城城欲催，甲光向日金鳞开。
角声满天秋色里，塞上燕脂凝夜紫。
半卷红旗临易水，霜重鼓寒声不起。
报君黄金台上意，提携玉龙为君死。','','战争的乌云翻滚而来，像是要把城楼压垮，将士的铁甲在阳光下闪耀，我自岿然不动。号角声声，响彻秋夜的长空，塞上战士的鲜血和泥土凝成紫色，战斗惨烈。援军连夜到达易水，半卷红旗，冒着霜寒，战鼓低沉，一场新的斗争即将开始。为报答君王在黄金台招贤纳士的恩惠，将士拿起玉龙宝剑愿为君王决一死战。'),('shuimo-130','卖炭翁','白居易','shuimo','','','卖炭翁，伐薪烧炭南山中。
满面尘灰烟火色，两鬓苍苍十指黑。
卖炭得钱何所营，身上衣裳口中食。
可怜身上衣正单，心忧炭贱愿天寒。
夜来城外一尺雪，晓驾炭车辗冰辙。
牛困人饥日已高，市南门外泥中歇。
翩翩两骑来是谁？黄衣使者白衫儿。
手把文书口称敕，回车叱牛牵向北。
一车炭，千余斤，宫使驱将惜不得。
半匹红纱一丈绫，系向牛头充炭值。','','此诗揭露唐朝的“宫市”(就是皇宫派太监在市场上采购货物)实质上是掠夺资财的一种方式，给人民带来深重的灾难。 卖炭翁每日在终南山砍柴烧炭。他两鬓白发苍苍，满面灰尘，脸上和手上黑黝黝的。卖炭得钱去干什么？为了吃饭和穿衣。可怜他身上穿着单衣，而担心炭的卖价太低却希望天气更冷一些。夜晚下了一场大雪，城外积雪一尺多厚，清晨他驾着炭车在结冰的道路上行进。太阳升得老高，牛疲倦了，人也饿了，在集市南门外歇息。两匹马飞快地跑 来，来的是谁？原来是宫中的太监和他们手下的爪牙。手里拿着文书，嘴里说皇帝有命令，回转车头，吆喝着将牛向北边牵赶。一车炭有一千多斤重，宫廷的使者驱走毫不吝惜。用半匹红纱和一丈绫，系在牛的头上作为一车炭的价钱。'),('shuimo-131','悯农（之二）','李绅','shuimo','','','春种一粒粟，秋收万颗子。
四海无闲田，农夫犹饿死。','','春天种下一颗种子，秋天收获万颗粮食。到处的田地都耕种了，可还有农民饿死。这是多么不合理的现象呀！'),('shuimo-132','暮江吟','白居易','shuimo','','','一道残阳铺水中，半江瑟瑟半江红。
可怜九月初三夜，露似珍珠月似弓。','','一道夕阳斜照在江面上，江水的半边为青绿色，半边泛出红色。九月初三这个夜晚真是令人喜爱、陶醉，露水像圆润的珍珠，月亮像一张弯弓。'),('shuimo-133','大林寺桃花','白居易','shuimo','','','人间四月芳菲尽，山寺桃花始盛开。
长恨春归无觅处，不知转入此中来。','','这首诗是作者游庐山大林寺所作，山下春天已过去，而这里桃花盛开，诗人喜出望外。 山下过了四月，各种花草的芳香都结束了，而大林寺的桃花才茂盛地开放。人们常常为春去无处寻找而遗憾万分，哪知春转入山中的大林寺来了。'),('shuimo-134','村民苦寒（节选）','白居易','shuimo','','','八年十二月，五日雪纷纷。
竹柏皆冻死，况彼无衣民。
回观村闾间，十室八九贫。
北风利如剑，布絮不蔽身。
唯烧蒿棘火，愁坐夜待晨。','','作者因母亲去世，回故乡居丧三年，遇上大雪苦寒，出于对人民疾苦的关注和同情，写下此诗。 元和八年十二月五日这天，大雪纷纷地下，天寒地冻，竹柏都被冻死，何况那些没有寒衣的百姓呢！回看村庄的人家，十家就有八九家贫困。北风像利剑一样地吹刮，破旧的棉衣不能蔽体御寒。只能烧蓬蒿和荆棘取暖，愁苦地坐到天明。'),('shuimo-135','别州民','白居易','shuimo','','','耆老遮归路，壶浆满别筵。
甘棠一无树，那得泪潸然。
税重多贫户，农饥足旱田。
唯留一湖水，与汝救凶年。','','诗写白居易离开任职多年的杭州去洛阳时，杭州父老拦路送别的情景。 杭州的父老准备水酒满筵，拦路相送。作为地方官吏为自已在任时一无建树而惭愧 ，不禁潸然泪下。因为税重，贫穷的农户很多；又因为旱田多，农民也有饥荒。我只能给父老们留下一湖水(指在钱塘增筑湖堤工程)，救救干旱的灾荒。'),('shuimo-136','池上','白居易','shuimo','','','小娃撑小艇，偷采白莲回。
不解藏踪迹，浮萍一道开。','','此诗描写孩子的天真无邪。 小娃撑着小船，到池上去偷采白色的莲篷。他们还不会隐藏自已的踪迹，在浮萍上留下一条明显的水路。'),('shuimo-137','悯农（之一）','李绅','shuimo','','','锄禾日当午，汗滴禾下土。
谁知盘中餐，粒粒皆辛苦。','','这首诗说明粮食来之不易。夏季的正午，烈日当头，给禾苗锄草的农民汗下如雨。有谁知道盘中的饭食，每一粒都来自于辛勤的劳动？'),('shuimo-138','马诗','李贺','shuimo','','','大漠沙如雪，燕山月似钩。
何当金络脑，快走踏清秋。','','大漠的沙像雪一样铺天盖地，燕山的月亮像一弯银钩(兵器)。什么时候能够给马套上镶金的笼头，在凉爽的秋天飞快地奔驰在疆场。'),('shuimo-139','山行','杜牧','shuimo','','','远目寒山石径斜，白云生处有人家。
停车坐爱枫林晚，霜叶红于二月花。','','沿着不平的石路登上带有寒意的山间，白云飘出的地方有人家。因为深深喜爱傍晚枫林的美景而停车欣赏，经过霜打的枫叶比二月的鲜花还要红。'),('shuimo-140','清明','杜牧','shuimo','','','清明时节雨纷纷，路上行人欲断魂。
借问酒家何处有？牧童遥指杏花村。','','清明节这天细雨纷飞，行路的人心绪烦乱。请问哪里有酒店？牧童指向远处的杏花村。'),('shuimo-141','江南春','杜牧','shuimo','','','千里莺啼绿映红，水村山郭酒旗风。
南朝四百八十寺，多少楼台烟雨中。','','这首诗描绘江南如画的春色。 在绿叶和红花交相辉映的江南，传来了莺鸟婉转的歌唱。水乡山城的酒店的幡旗迎风招展。南朝修建筑的四百八十多座古寺，有多少亭台楼阁沉浸在这迷蒙的春雨之中。'),('shuimo-142','秋夕','杜牧','shuimo','','','银烛秋光冷画屏，轻罗小扇扑流萤。
天阶夜色凉如水，坐看牵牛织女星。','','这首诗写宫女在七月七日(秋夕)这天的情思。 银色的蜡烛和秋夕的月光都冷冷地照射在房中的画屏上，宫女手拿轻小的罗扇到房外去扑打飞着的萤火虫。坐在皇宫的石阶上，夜色像水一样透着寒意，忽然想起七月七日是牛郎与织女相会的日子，抬头看望牵牛星与织女星。'),('shuimo-143','鹭鸶','杜牧','shuimo','','','雪衣雪发青玉嘴，群捕鱼儿溪影中。
惊飞远映碧山去，一树梨花落晚风。','','这首诗描绘鹭鸶鸟的样子和生活习性，真实动人。 雪白的鹭鸶像穿着白色的外衣，白色的毛发、青玉琢成的小嘴，群起群落在溪水中捕鱼。受惊向远远的碧绿的山林飞去，好像晚风吹落一树的梨花，飘酒在天际。'),('shuimo-144','灞上秋居','马戴','shuimo','','','灞原风雨定，晚见雁行频。
落叶他乡树，寒灯独夜人。
空园白露滴，孤壁野僧邻。
寄卧郊扉久，何年致此身？。','','此诗反映作者客居异乡的孤寂，抒发自已怀才不遇的感慨，并在一定程度上，反映唐末社会动乱的现实。 在一个风停雨歇的灞水高原的黄昏，只见空中的雁群不断往南飞去。这纷纷飘落的树叶，是他乡之树，而不是故乡的树。寒灯独照着孤寂的异乡之人，空园中一片荒凉，连白露滴下的声音都可听见，孤独的房舍，只有与野僧为邻。寄居在这郊外的住宅已经很久了，何年何月能够出仕为官，为国效力呢？'),('shuimo-145','渡汉江','李频','shuimo','','','岭外音书绝，经冬复立春。
近乡情更怯，不敢问来人。','','这首诗通过表现游子归来时，临到家门口前的心理变化和紧张情绪，反映出他对家乡的一片深情。 离家到五岭以外偏远的地方客居，与家乡音书断绝，冬去春来，一年又一年。游子归来，临近家门时心情更加紧张，怕家中发生什么变故，不敢询问迎面走来的人。'),('shuimo-146','蜂','罗隐','shuimo','','','不论平地与山尖，无限风光尽被占。
采得百花成蜜后，为谁辛苦为谁甜？。','','不论在平地或是山顶，都有蜜蜂在辛勤劳动，美好的风光几乎都有它的踪迹。采得花粉酿成蜜却属于他人，为谁辛苦为谁甜啊？'),('shuimo-147','筹笔驿','李商隐','shuimo','','','猿鸟犹疑畏简书，风云长为护储胥。
徒令上将挥神笔，终见降王走传车。
管乐有才真不忝，关张无命欲何如。
他年锦里经祠庙，梁父吟成恨有余。','','此诗为作者北归途中，经筹笔驿有感而作。 自诸葛亮在此筹划军事后，直到今天，猿鸟还畏惧诸葛亮当年的军令，风云聚集，长久地护卫着过去的营垒。诸葛亮虽然善于筹划，但蜀汉终不免灭亡，刘禅被押送乘车到洛阳。诸葛亮的政治军事才能和管仲、乐毅比较丝毫不差，但关羽、张飞死于非命，又有什么办法呢？往年我曾在锦里拜谒武侯神祠，每当吟诵《梁父吟》时，不禁为诸葛亮的壮志未酬而抱恨不已。'),('shuimo-148','春雨','李商隐','shuimo','','','怅卧新春白袷衣，白门寥落意多违。
红楼隔雨相望冷，珠箔飘灯独自归。
远路应悲春晼晚，残宵犹得梦依稀。
玉铛缄札何由达，万里云罗一雁飞。','','这也是一首爱情诗，诗写因春雨而怀念意中人。 新春之时，穿着闲居时的白夹衣失意而卧，去金陵寻访心爱的女子不遇，心情异常寂寞。隔雨相望红楼，人去楼空，倍觉凄冷，夜晚冒雨独自归来。远去的路上，面对春天的暮色，她也会悲伤。夜色将尽时，自已还可以在梦中与她相见。密封的书信和玉耳环怎样送到对方的手中呢？只有靠远飞万里的鸿雁来传递了。'),('shuimo-149','陇西行','陈陶','shuimo','','','誓扫匈奴不顾身，五千貂锦丧胡尘。
可怜无定河边骨，犹是春闺梦里人。','','本诗控诉当时的统治阶级为了满足私欲而发动战争的罪恶行径。 发誓扫平入侵西北的外族而奋不顾身，五千精练的军队丧身在西北战场，伤亡惨重。可怜无定河边的累累白骨，他们都是姑娘们在梦中思念的亲人。'),('shuimo-150','登乐游原','李商隐','shuimo','','','向晚意不适，驱车登古原。
夕阳无限好，只是近黄昏。','','诗写傍晚登上乐游原所见的景色和深刻的感慨。 傍晚时分情绪不好，驾车登上古原。只见夕阳西下，尽管它美好无限，只可惜已近黄昏，要下山了。'),('shuimo-151','落花','李商隐','shuimo','','','高阁客竟去，小园花乱飞。
参差连曲陌，迢递送斜晖。
肠断未忍扫，眼穿仍仍欲归。
芳心向春尽，所得是沾衣。','','此诗咏落花，也抒发自已的迟暮之感。 小园里的花在风的吹拂下胡乱地飞舞，高高阁楼上的游客竟然离去了。参差不齐的花瓣片片连接曲折的小路，残瓣飘飞遥送夕阳西下。因极度悲痛而不忍心去打扫残花，望眼欲穿地盼来春天，春天仍要归去。春花为春尽而落，我的心为花落而悲，伤心得泪湿衣襟。'),('shuimo-152','风雨','李商隐','shuimo','','','凄凉宝剑篇，羁泊欲穷年。
黄叶仍风雨，青楼自管弦。
新知遭薄俗，旧好隔良缘。
心断新丰酒，销愁又几千。','','诗写羁旅终年、怀才不遇的感慨。 唐将郭震写下《宝剑篇》受到武则天的赏识，可自已胸怀大志，却无人赏识。处境凄凉，终年在外飘泊，好像枯黄的树叶，还遭风雨的侵袭。而在青楼妓院，权贵们却各自歌舞取乐。新的知交，遭到薄情世俗的冷落，旧的友好，因阻隔而关系疏远。绝望地畅饮新丰的酒，自已不能像马周那样得到皇帝的赏识，只好借每斗几千铜钱的美酒来浇愁。'),('shuimo-153','蝉','李商隐','shuimo','','','本以高难饱，徒劳恨费声。
五更疏欲断，一树碧无情。
薄宦梗犹泛，故园芜已平。
烦君最相警，我亦举家清。','','此诗以寓情于物的手法，以蝉寓已。 蝉原来因为栖于高树，餐风饮露，难以获得一饱，寒蝉恨的是白费唇舌，劳而无功。天快亮时，蝉声稀疏，难以再继续下去。而树木却一片碧绿，像是全然无动于衷。自已官职卑微，像桃树梗那样在水面漂浮无着落。而此时故乡的田园已长满乱草而成为平旷的原野。蝉的悲鸣最能触动我，引起我强烈的共呜；我家境清贫，一无所有。'),('shuimo-154','瑶瑟怨','温庭筠','shuimo','','','冰簟银床梦不成，碧天如水夜云轻。
雁声远过潇湘去，十二楼中月自明。','','这首诗描绘的是听鼓瑟的各种感受。当精美的瑟奏出哀怨的乐曲时，如月光照射在银床上，人睡在冰凉的竹席上不能入梦，感到寒凉；如碧蓝如水的天空，轻轻地飘来几朵夜云，令人感到凄清；如大雁鸣叫着远飞潇湘，令人悲恻；如明月照射在女子所住的高楼，令人感到孤寂。'),('shuimo-155','送人东归','温庭筠','shuimo','','','荒戍落黄叶，浩然离故关。
高风汉阳渡，初日郢门山。
江上几人在，天涯孤棹还。
何当重相见，尊酒慰离颜。','','诗写秋季塞下送别，送朋友到东边的家乡。 荒凉的驻防地区黄叶飘零，朋友意志坚决地离开旧时的关塞。太阳刚刚升起的时候离开郢门山，高风送舟，很快就到汉阳渡。江上风波险阻，过去的朋友还有几个人在呢？当你坐孤舟从遥远的天际返回的时候，什么时候还能相见？让我们高举酒杯告慰离别后的愁颜。'),('shuimo-156','早秋','许浑','shuimo','','','遥夜泛清瑟，西风生翠萝。
残萤西玉露，早雁拂金河。
高树晓还密，远山晴更多。
淮南一叶下，自觉洞庭波。','','这是一首优美的描绘景物的诗歌。 漫漫的长夜回荡着清越的瑟声，青翠的藤萝在西风地吹拂中飘荡。残存的萤火虫栖息在晶莹如玉的露水旁，早雁掠过银河飞向远方。曙光中，高大的树木还是那么茂密，在明朗的阳光照射下，远处的山峰看得更清楚了。淮南落下一片叶子，便知是秋天到来。秋风起，洞庭湖波涛滚滚，也自然感觉早秋地到来。'),('shuimo-157','秋日赴阙题潼关驿楼','许浑','shuimo','','','红叶晚萧萧，长亭酒一瓢。
残云归太华，疏雨过中条。
树色随关迥，河声入海遥。
帝乡明日到，犹自梦渔樵。','','秋日赴京，路过潼关，在驿楼上题壁。 红叶在晚风中萧萧作响，驿楼内饮一瓢酒浇愁。几朵残云聚集在太华山，一阵稀疏的雨点飘过中条山。那苍翠的树色，从潼关一直伸向遥远的地方。咆哮的九曲黄河汇入遥远的大海。明天就要到都城长安，自已却还在做归隐后过渔樵生活的梦。'),('shuimo-158','宫词','朱庆馀','shuimo','','','寂寂花时闭院门，美人相并立琼轩。
含情欲说宫中事，鹦鹉前头不敢言。','','这是一首写宫中情事的诗歌，它含蓄地描绘了宫女的生活和痛苦。 百花盛开的季节，宫廷的院门却紧紧地关闭，两个宫女百无聊赖地并立在华美的长廓之下。她们彼此含情正要说宫廷的情事，却看见前面站着那只学舌的鹦鹉，吓得不敢作声了。'),('shuimo-159','题金陵渡','张祜','shuimo','','','金陵津渡小山楼，一宿行人自可愁。
潮落夜江斜月里，两三星火是瓜洲。','','诗写旅宿京口驿楼的客愁。 旅客在金陵渡的小山楼住一宿，自有可愁之处。住在这小山楼，面对长江潮起潮落，月亮西斜，遥望对岸瓜洲，闪烁着两三点星星似的灯火，谁都会产生辽阔凄寂的伤感。'),('shuimo-160','何满子','张祜','shuimo','','','故国三千里，深宫二十年。
一声何满子，双泪落君前。','','诗写宫女的哀怨。相传唐文宗病重时想让孟才人以死相殉，孟歌《何满子》一声肠断而殒。作者以诗吊之。 远离家乡三千里，深居宫中二十年。凄惨地唱一声《何满子》，在君王的面前，眼泪哗哗地流，到头来不免要惨死相殉。'),('shuimo-161','遣怀','杜牧','shuimo','','','落魄江湖载酒行，楚腰纤细掌中轻。
十年一觉扬中梦，赢得青楼薄幸名。','','此诗为作者抒发情怀的着名篇章。 失意潦倒，携酒漂泊江湖，沉湎于楚灵王喜好的细腰女子和赵飞燕的轻盈舞姿。扬州十年的纵情声色，好像一场梦，醒悟回头，却在青楼女子这中落得一个薄情的名声。'),('shuimo-162','赤壁','杜牧','shuimo','','','折戟沉沙铁未销，自将磨洗认前朝。
东风不与周郎便，铜雀春深锁二乔。','','作者借遗物而起兴，引发对历史事件和历史人物的议论和评价。 断戟被埋在赤壁古战场的沙土中，铁器还没有毁坏，我将它拿去打磨洗净辨认出是前朝的遗物。在着名的赤壁之战中，倘若不是东风刮得及时，给周瑜方便，那么东吴将被曹操所灭，二乔将被虏而关在曹操所建的铜雀台中了。'),('shuimo-163','将赴吴兴登乐游原','杜牧','shuimo','','','清明有味是无能，闲爱孤云静爱僧。
欲把一麾江海去，乐游原上望昭陵。','','这首诗以婉转的语言抒发了作者对当时现实的不满和怀才不遇的感慨。 当此清明世道，可以有所作为之时，自已则喜爱孤云的悠闲，僧侣的宁静。以为是有兴味，实则是无能的表现。将要手持旌旗到吴兴去任职湖州刺史，在乐游原上凭吊唐太宗李世民的昭陵，不能不想起唐代的太平盛事。'),('shuimo-164','寄扬州韩绰判官','杜牧','shuimo','','','青山隐隐水迢迢，秋尽江南草木凋。
二十四桥明月夜，玉人何处教吹箫。','','此诗是杜牧离开扬州以后，在江南怀念昔日同僚韩绰判官而作。 青山隐约可见，水流千里迢迢。江南秋尽，草木凋零，在难耐的孤寂中怀念远方的友人。在拥有二十四座桥的扬州的月光明媚的夜晚，君在何处教玉人(美人)吹箫？在什么地方潇洒呢？'),('shuimo-165','金谷园','杜牧','shuimo','','','繁华事散逐香尘，流水无情草自春。
日暮东风怨啼鸟，落花犹似坠楼人。','','诗抒发了作者凭吊西晋大官僚石崇构筑的金谷园遗址时的感慨。 石崇当年的繁华往事，早已追随沉香木粉散尽。流水无情地流淌，春草还像过去一样青青。太阳落山，东风劲吹，使归鸟啼怨，凋零的落花好像当年绿珠坠楼再现在我们眼前。'),('shuimo-166','泊秦淮','杜牧','shuimo','','','烟笼寒水月笼沙，夜泊秦淮近酒家。
商女不知亡国恨，隔江犹唱后庭花。','','当晚唐王朝忧患交迫之时，豪门贵族依然过着醉生梦死的生活，作者对此发出无限感慨。 烟雾笼罩着寒水，月光洒在岸边的沙滩上，小船在夜色中停泊在秦淮河一带的酒店旁边。卖唱的女子不懂得亡国之恨，隔江还听见她在唱《玉树后庭花》。'),('shuimo-167','旅宿','杜牧','shuimo','','','旅馆无良伴，凝情自悄然。
寒灯思旧事，断雁警愁眠。
远梦归侵晓，家书到隔年。
沧江好烟月，门系钓鱼船。','','这首诗极力描述怀乡之情，以烘托厌倦生途之感。旅途歇宿没有好伴，满怀的思乡之情悄然而生。在旅馆冰冷的孤灯之下，不禁回忆起过去的事情，失群的孤雁在愁眠中也被惊醒。做梦返回家乡，路途遥远，要等到天亮才能到家，家书寄达那更是隔年的事了。沧江有好风景，门外系着渔船，倒不如渔翁生活自在。'),('shuimo-168','哥舒歌','西鄙人','shuimo','','','北斗七星高，哥舒夜带刀。
至今窥牧马，不敢过临洮。','','哥舒指哥舒翰，是唐玄宗的大将，突厥族哥舒部的后裔。 北斗七星高照，哥舒翰夜巡，严守边防。到现在胡骑(敌军)只能远远地窥探，却不敢轻举妄动，轻易地越过临洮。'),('shuimo-169','贫女','秦韬玉','shuimo','','','蓬门未识绮罗香，拟托良媒益自伤。
谁爱风流高格调，共怜时世俭梳妆。
敢将十指夸针巧，不把双眉斗画长。
苦恨年年压金线，为他人作嫁衣裳。','','此诗勾画了一个品德高尚、勤劳善良的穷苦姑娘的形象，并寄予深切的同情。 贫穷人家的姑娘没有华丽的服饰和香粉之类的修饰，打算请好媒人说媒出嫁也因为家穷而不能，实在令人伤心。有谁赏识高尚的品德和优雅的风度，世人都在追求奇异的妆扮。贫女敢用手工针线刺绣的精巧来夸耀，而不愿和别人比画眉的美丽。深恨年年辛勤地刺绣，只是为别人缝制出嫁的衣裳。'),('shuimo-170','孤雁','崔涂','shuimo','','','几行归塞尽，念尔独何之？暮雨相呼失，寒塘欲下迟。
渚云低暗度，关月冷相随。
未必逢矰缴，孤飞自可疑。','','此诗通过对失群孤雁的描绘，寄托着诗人悲凉的身世之感。 一行行大雁飞回塞外不见了，你孤孤单单将要飞向哪里？在暮雨苍茫中，你因失群而呼唤，声声悲切，想落到寒塘栖息，又迟疑不决。在黑夜中偷偷掠过水洲上的浮云，边关的月亮冰冷地相随。此去路途遥遥，即使可以避开弓箭的射击，独自飞翔，毕竟害怕！'),('shuimo-171','除夜有怀','崔涂','shuimo','','','迢递三巴路，羁危万里身。
乱山残雪夜，孤独异乡人。
渐与骨肉远，转于童仆亲。
那堪正漂泊，明日岁华新。','','此诗写阴历年三十夜的感慨，系作者客居四川的作品。跋涉遥远的通往四川三巴地区的道路，寄居离家万里的异乡，生活十分困难，随时会有危险发生。在乱山丛中，冬尽雪残，一丝微弱的烛光，映照着飘泊的异乡人。与骨肉亲人越来越远，只好与童子仆人亲近。明天又是新的一年，哪里能忍受这飘泊孤独的生涯啊。'),('shuimo-172','再经胡城县','杜荀鹤','shuimo','','','去岁曾经此县城，县民无口不冤声。
今来县宰加朱绂，便是生灵血染成。','','此诗反映了晚唐时期官场的腐败。 去年曾经路过这胡城县，县民中没有一个人不喊冤叫屈的。今年再路过胡城县，得知县令升官晋级，这官帽是老百姓的鲜血染成的啊！'),('shuimo-173','春怨','金昌绪','shuimo','','','打起黄莺儿，莫教枝上啼。
啼时惊妾梦，不得到辽西。','','这首诗写女子思念远征辽西的丈夫，反映战争拆散年轻夫妇，离散给人民带来的痛苦。 赶走黄莺儿，不让它在树枝上啼叫。它的叫声惊醒了我的好梦，使我不能在梦中去辽西和丈夫相见。'),('shuimo-174','书边事','张乔','shuimo','','','调角断清秋，征人倚戍楼。
春风对青冢，白日落梁州。
大漠无兵阻，穷边有客游。
蕃情似此水，长愿向南流。','','此诗是作者客游边塞有感之作，反映了晚唐时期政治腐败，边境松弛，导致外敌入侵之患。 调角之声断然无疑地说明已是清秋时节，远行的人正倚傍在边防地区的城楼上。王昭君墓上的青草沐浴着春风，可看见太阳落下梁州的景象。广大的沙漠地带，竟无兵卒防守，僻远的边境可供我自由地游览。少数民族酋长的心情好似眼前的流水，常想向南侵犯我唐朝。'),('shuimo-175','台城','韦庄','shuimo','','','江雨霏霏江草齐，六朝如梦鸟空啼。
无情最是台城柳，依旧烟笼十里堤。','','台城也称苑城，在今南京玄武湖边上，六朝时把它称为宫城。本诗题咏台城，也是凭吊古迹的意思。 江雨密密地下，江草齐齐地长。六朝像梦一样消失，只剩下寂寞的鸟叫声。台城之柳最是无情，它依旧茂盛，像烟雾一样笼罩在十里长堤上。'),('shuimo-176','章台夜思','韦庄','shuimo','','','清瑟怨遥夜，绕弦风雨哀。
孤灯闻楚角，残月下章台。
芳草已云暮，故人殊未来。
乡书不可寄，秋雁又南回。','','此诗为秋夜思乡的作品。章台在今湖北监利县西北。 凄清的瑟在长夜中发出哀怨的音调，而伴随着弦的乐曲，又是风雨的哀呜。孤灯下听到楚地的角声，残月从章台落下去。转眼春光将尽，年华已逝，故人都已疏远。我写的家信已无法寄回，因为秋雁已经向南飞回去了。'),('qingyan-001','幽梦影 · 一','张潮','qingyan','','','读经宜冬，其神专也；读史宜夏，其时久也；读诸子宜秋，其致别也；读诸集宜春，其机物也。','["曹秋岳曰：可想见其南面百城时。","庞笔奴曰：读《幽梦影》则春、夏、秋、冬，无时不宜。"]',''),('qingyan-002','幽梦影 · 二','张潮','qingyan','','','经传宜独坐读，史鉴宜与友共读。','["孙恺似曰：深得此中真趣，固难为不知者道。","王景州曰：如无好友，即红友亦可。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('qingyan-003','幽梦影 · 三','张潮','qingyan','','','无善无恶是圣人(如“帝力何有于我”、“杀之而不怨，利之而不庸”、“以直报怨，以德报德”、“一介不与，一介不取”之类)，善多恶少是贤者(如颜子“不贰过，有不善未尝不知”、子路“人告有过则喜”之类)，善少恶多是庸人，有恶无善是小人(其偶为善处，亦必有所为)，有善无恶是仙佛(其所谓善，亦非吾儒之所谓善也)。','["黄九烟曰：今人“一介不与”者甚多，普天之下皆半边圣人也。“利之不庸”者亦复不少。","江含征曰：先恶后善是回头人，先善后恶是两截人。","殷日戒曰：貌善而心恶者是奸人，亦当分别。","冒青若曰：昔人云：“善可为而不可为。”唐解元诗云：“善亦懒为何况恶！”当于有无多少中，更进一层。"]',''),('qingyan-004','幽梦影 · 四','张潮','qingyan','','','天下有一人知己，可以不恨。不独人也，物亦有之。如菊以渊明为知己，梅以和靖为知己，竹以子猷为知己，莲以濂溪为知己，桃以避秦人为知己，杏以董奉为知己，石以米颠为知己，荔枝以太真为知己，茶以卢仝、陆羽为知己，香草以灵均为知己，莼鲈以季鹰为知己，蕉以怀素为知己，瓜以邵平为知己，鸡以处宗为知己，鹅以右军为知己，鼓以祢衡为知己，琵琶以明妃为知己。一与之订，千秋不移。若松之于秦始，鹤之于卫懿，正所谓不可与作缘者也。','["查二瞻曰：此非松、鹤有求于秦始、卫懿，不幸为其所近，欲避之而不能耳。","殷日戒曰：二君究非知松、鹤者，然亦无损其为松、鹤。","周星远曰：鹤于卫懿，犹当感恩。至吕政五大夫之爵，直是唐突十八公耳。","王名友曰：松遇封，鹤乘轩，还是知己。世间尚有剧松煮鹤者，此又秦、卫之罪人也。","张竹坡曰：人中无知己，而下求于物，是物幸而人不幸矣。物不遇知己而滥用于人，是人快而物不快矣。可见知己之难，知其难方能知其乐。"]',''),('qingyan-005','幽梦影 · 五','张潮','qingyan','','','为月忧云，为书忧蠹，为花忧风雨，为才子、佳人忧命薄，真是菩萨心肠。','["余淡心曰：洵如君言，亦安有乐时耶！","孙松坪曰：所谓“君子有终身之忧”者耶！","黄交三曰：“为才子、佳人忧命薄”一语，真令人泪湿青衫。","张竹坡曰：第四忧，恐命薄者消受不起。","江含征曰：我读此书时，不免为蟹忧雾。","竹坡又曰：江子此言，直是为自己忧蟹耳。","尤悔庵曰：杞人忧天，嫠妇忧国，无乃类是。"]',''),('qingyan-006','幽梦影 · 六','张潮','qingyan','','','花不可以无蝶，山不可以无泉，石不可以无苔，水不可以无藻，乔木不可以无藤萝，人不可以无癖。','["黄石闾曰：“事到可传皆具癖”，正谓此耳。","孙松坪曰：和长舆却未许藉口。"]',''),('qingyan-007','幽梦影 · 七','张潮','qingyan','','','春听鸟声，夏听蝉声，秋听虫声，冬听雪声，白昼听棋声，月下听箫声，山中听松风声，水际听欺乃声，方不虚生此世耳。若恶少斥辱，悍妻诟谇，真不若耳聋也。','["黄仙裳曰：此诸种声颇易得，在人能领略耳。","朱菊山曰：山老所居，乃城市山林，故其言如此。若我辈日在广陵城市中，求一鸟声，不啻如凤凰之鸣，顾可易言耶！","释中洲曰：昔文殊选二十五位圆通，以普门耳根为第一。今心斋居士耳根不减普门。吾他日选圆通，自当以心斋为第一矣。","张竹坡曰：久客者，欲听儿辈读书声，了不可得。","张迂庵曰：可见对恶少J陴妻，尚不若日与禽虫周旋也。","又曰：读此，方知先生耳聋之妙。"]',''),('qingyan-008','幽梦影 · 八','张潮','qingyan','','','上元须酌豪友，端午须酌丽友，七夕须酌韵友，中秋须酌淡友，重九须酌逸友。','["朱菊山曰：我于诸友中，当何所属耶？","王武征曰：君当在豪与韵之间耳。","王名友曰：维扬丽友多，豪友少，韵友更少。至于淡友、逸友，则削迹矣。","张竹坡曰：诸友易得，发心酌之者为难能耳。","顾天石曰：除夕须酌不得意之友。","徐砚谷曰：惟我则无时不可酌耳。","尤谨庸曰：上元酌灯，端午酌采丝，七夕酌双星，中秋酌月，重九酌菊，则吾友俱备矣。"]',''),('qingyan-009','幽梦影 · 九','张潮','qingyan','','','鳞虫中金鱼，羽虫中紫燕，可云物类神仙。正如东方曼倩避世金马门，人不得而害之。','["江含征曰：金鱼之所以免汤镬者，以其色胜而味苦耳。昔人有以重价觅奇特者以馈邑侯，邑侯他日谓之日：“贤所赠花鱼，殊无味。”盖已烹之矣。世岂少削圆方竹杖者哉！"]',''),('qingyan-010','幽梦影 · 十','张潮','qingyan','','','入世须学东方曼倩，出世须学佛印了元。','["江含征曰：武帝高明喜杀，而曼倩能免于死者，亦全赖吃了长生酒耳。","殷日戒曰：曼倩诗有云：“依隐玩世，诡时不逢。”此其所以免死也。","石天外曰：入得世，然后出得世。入世出世，打成一片，方有得心应手处。"]',''),('qingyan-011','幽梦影 · 十一','张潮','qingyan','','','赏花宜对佳人，醉月宜对韵人，映雪宜对高人。','["余淡心日：花即佳人，月即韵人，雪即高人。既已赏花、醉月、映雪，即与对佳人、韵人、高人无异也。","江含征曰：若对此君仍大嚼，世间那有扬州鹤！","张竹坡日：聚花、月、雪于一时，合佳、韵、高为一人，吾当不赏而心醉矣。"]',''),('qingyan-012','幽梦影 · 十二','张潮','qingyan','','','对渊博友，如读异书；对风雅友，如读名人诗文；对谨饬友，如读圣贤经传；对滑稽友，如阅传奇小说。','["李圣许曰：读这几种书，亦如对这几种友。","张竹坡曰：善于读书、取友之言。"]',''),('qingyan-013','幽梦影 · 十三','张潮','qingyan','','','楷书须如文人，草书须如名将，行书介乎二者之间，如羊叔子缓带轻裘，正是佳处。','["程桦老曰：心斋不工书法，乃解作此语耶！","张竹坡曰：所以羲之必做右将军。"]',''),('qingyan-014','幽梦影 · 十四','张潮','qingyan','','','人须求可入诗，物须求可入画。','["龚半千曰：物之不可入画者，猪也，阿堵物也，恶少年也。","张竹坡曰：诗亦求可见得人，画亦求可像个物。","石天外曰：人须求可入画，物须求可入诗，亦妙。"]',''),('qingyan-015','幽梦影 · 十五','张潮','qingyan','','','少年人须有老成之识见，老成人须有少年之襟怀。','["江含征日：今之钟鸣漏尽、白发盈头者，若多收几斛麦，便欲置侧室，岂非有少年襟怀耶！独是少年老成者少耳。","张竹坡日：十七八岁便有妾，亦居然少年老成。","李若金曰：老而腐板，定非豪杰。","王司直日：如此方不使岁月弄人。"]',''),('qingyan-016','幽梦影 · 十六','张潮','qingyan','','','春者，天之本怀；秋者，天之别调。','["石天外曰：此是透彻性命关头语。","袁江中曰：得春气者，人之本怀；得秋气者，人之别调。","尤悔庵日：夏者，天之客气；冬者，天之素风。","陆云士日：和神当春，清节为秋，天在人中矣。"]',''),('qingyan-017','幽梦影 · 十七','张潮','qingyan','','','昔人云：若无花月美人，不愿生此世界。予益一语云：若无翰墨棋酒，不必定作人身。','["殷日戒曰：枉为人身，生在世界者，急宜猛省。","顾天石曰：海外诸国，决无翰、墨、棋、酒，即有，亦不与吾同，一般有人，何也？","胡会来曰：若无豪杰、文人，亦不须要此世界。"]',''),('qingyan-018','幽梦影 · 十八','张潮','qingyan','','','愿在木而为樗(不才，终其天年)，愿在草而为蓍(前知)，愿在鸟而为鸥(忘机)，愿在兽而为廌(触邪)，愿在虫而为蝶(花间栩栩)，愿在鱼而为鲲(逍遥游)。','["吴园次曰：较之《闲情》一赋，所愿更自不同。","郑破水曰：我愿生生世世为顽石。","尤悔庵曰：第一大愿。","又曰：愿在人而为梦。","尤慧珠曰：我亦有大愿，愿在梦而为影。","弟木山曰：前四愿皆是相反。盖“前知”则必多“才”，“忘机”则不能“触邪”也。"]',''),('qingyan-019','幽梦影 · 十九','张潮','qingyan','','','黄九烟先生云：“古今人必有其偶双，千古而无偶者，其惟盘古乎！”予谓：“盘古亦未尝无偶，但我辈不及见耳。其人为谁？即此劫尽时，最后一人是也。”','["孙松坪曰：如此眼光，何啻出牛背上耶！","洪秋士日：偶亦不必定是两人，有三人为偶者，有四人为偶者，有五、六、七、八人为偶者，是又不可不知。"]',''),('qingyan-020','幽梦影 · 二十','张潮','qingyan','','','古人以冬为三余，予谓当以夏为三余：晨起者，夜之余；夜坐者，昼之余；午睡者，应酬人事之余。古人诗云“我爱夏日长”，洵不诬也。','["张竹坡曰：眼前问冬夏皆有余者，能几人乎？","张迂庵曰：此当是先生辛未年以前语。"]',''),('qingyan-021','幽梦影 · 一','张潮','qingyan','','','庄周梦为蝴蝶，庄周之幸也；蝴蝶梦为庄周，蝴蝶之不幸也。','["黄九烟曰：惟庄周乃能梦为蝴蝶，惟蝴蝶乃能梦为庄周耳。若世之扰扰红尘者，其能有此等梦乎！","孙恺似曰：君于梦之中又占其梦耶！","江含征曰：周之喜梦为蝴蝶者，以其入花深也。若梦甫酣而乍醒，则又如嗜酒者梦赴席而为妻惊醒，不得不痛加诟谇矣。","张竹坡曰：我何不幸而为蝴蝶之梦者？"]',''),('qingyan-022','幽梦影 · 二','张潮','qingyan','','','艺花可以邀蝶，累石可以邀云，栽松可以邀风，贮水可以邀萍，筑台可以邀月，种蕉可以邀雨，植柳可以邀蝉。','["曹秋岳曰：藏书可以邀友。","崔莲峰曰：酿酒可以邀我。","尤艮斋曰：安得此贤主人？","尤慧珠曰：贤主人非心斋而谁乎？","倪永清曰：选诗可以邀谤。","陆云士曰：积德可以邀天，力耕可以邀地，乃无意相邀。而若邀之者，与邀名邀利者迥异。","庞天池曰：不仁可以邀富。"]',''),('qingyan-023','幽梦影 · 三','张潮','qingyan','','','景有言之极幽而实萧索者，烟雨也；境有言之极雅而实难堪者，贫病也；声有言之极韵而实粗鄙者，卖花声也。','["谢海翁曰：物有言之极俗而实可爱者，阿堵物也。","张竹坡曰：我幸得极雅之境。"]',''),('qingyan-024','幽梦影 · 四','张潮','qingyan','','','才子而富贵，定从福、慧双修得来。','["冒青若曰：才子富贵难兼。若能运用富贵，才是才子，才是福、慧双修。世岂无才子而富贵者乎？徒自贪着，无济于人，仍是有福无慧。","陈鹤山曰：释氏云：修福不修慧，象身挂璎珞；修慧不修福，罗汉供应薄。正以其难兼耳。山翁发为此论，直是夫子自道。","江含征曰：宁可拼一副菜园肚皮，不可有一副酒肉面孔。"]',''),('qingyan-025','幽梦影 · 五','张潮','qingyan','','','新月恨其易沉，缺月恨其迟上。','["孔东塘曰：我唯以月之迟早为睡之迟早耳。","孙松坪曰：第勿使浮云点缀，尘滓太清，足矣。","冒青若曰：天道忌盈。沉与迟，请君勿恨。","张竹坡曰：易沉、迟上，可以卜君子之进退。"]',''),('qingyan-026','幽梦影 · 六','张潮','qingyan','','','躬耕吾所不能，学灌园而已矣；樵薪吾所不能，学剃草而已矣。','["汪扶晨曰：不为老农，而为老圃，可云半个樊迟。","释菌人曰：以灌园、剃草自任，自待可谓不薄。然笔端隐隐有“非其种者，锄而去之”之意。","王司直曰：予自名为识字农夫，得毋妄甚！"]',''),('qingyan-027','幽梦影 · 七','张潮','qingyan','','','一恨书囊易蛀，二恨夏夜有蚊，三恨月台易漏，四恨菊叶多焦，五恨松多大蚁，六恨竹多落叶，七恨桂荷易谢，八恨薜萝藏虺，九恨架花生刺，十恨河豚多毒。','["江药庵曰：黄山松并无大蚁，可以不恨。","张竹坡曰：安得诸恨物尽有黄山乎！","石天外曰：予另有二恨：一日才人无行，二曰佳人薄命。"]',''),('qingyan-028','幽梦影 · 八','张潮','qingyan','','','楼上看山，城头看雪，灯前看月，舟中看霞，月下看美人，另是一番情境。','["江允凝曰：黄山看云，更佳。","倪永清曰：做官时看进士，分金处看文人。","毕右万曰：予每于雨后看柳，觉尘襟俱涤。","尤谨庸曰：山上看雪，雪中看花，花中看美人，亦可。"]',''),('qingyan-029','幽梦影 · 九','张潮','qingyan','','','山之光，水之声，月之色，花之香，文人之韵致，美人之姿态，皆无可名状，无可执着，真足以摄召魂梦，颠倒情思。','["吴街南曰：以极有韵致之文人，与极有姿态之美人，共坐于山、水、花、月间，不知此时魂梦何如？情思何如？"]',''),('qingyan-030','幽梦影 · 十','张潮','qingyan','','','假使梦能自主，虽千里无难命驾，可不羡长房之缩地；死者可以晤对，可不需少君之招魂；五岳可以卧游，可不俟婚嫁之尽毕。','["黄九烟曰：予尝谓“鬼有时胜于人”，正以其能自主耳。","江含征曰：吾恐“上穷碧落下黄泉，两地茫茫皆不见”也。","张竹坡曰：梦魂能自主，则可一生死，通人鬼。真见道之言矣。"]',''),('qingyan-031','幽梦影 · 十一','张潮','qingyan','','','昭君以和亲而显，刘蕡以下第而传。可谓之不幸，不可谓之缺陷。','["江含征曰：若故折黄雀腿而后医之，亦不可。","尤悔庵日：不然，一老宫人，一低进士耳。"]',''),('qingyan-032','幽梦影 · 十二','张潮','qingyan','','','以爱花之心爱美人，则领略自饶别趣；以爱美人之心爱花，则护惜倍有深情。','["冒辟疆曰：能如此，方是真领略、真护惜也。","张竹坡曰：花与美人，何幸遇此东君。"]',''),('qingyan-033','幽梦影 · 十三','张潮','qingyan','','','美人之胜于花者，解语也；花之胜于美人者，生香也。二者不可得兼，舍生香而取解语者也。','["王勿翦曰：飞燕吹气若兰，合德体自生香，薛瑶英肌肉皆香。则美人又何尝不生香也！"]',''),('qingyan-034','幽梦影 · 十四','张潮','qingyan','','','窗内人于窗纸上作字，吾于窗外观之，极佳。','["江含征曰：若索债人于窗外纸上画，吾且望之却走矣。"]',''),('qingyan-035','幽梦影 · 十五','张潮','qingyan','','','少年读书，如隙中窥月；中年读书，如庭中望月；老年读书，如台上玩月。皆以阅历之浅深为所得之浅深耳。','["黄交三曰：真能知读书痛痒者也。","张竹坡曰：吾叔此论，直置身广寒宫里，下视大千世界，皆清光似水矣。","毕右万曰：吾以为学道亦有浅深之别。"]',''),('qingyan-036','幽梦影 · 十六','张潮','qingyan','','','吾欲致书雨师：春雨宜始于上元节后 (观灯已毕)，至清明十日前之内(雨止桃开)，及谷雨节中；夏雨宜于每月上弦之前，及下弦之后(免碍于月)；秋雨宜于孟秋、季秋之上、下二旬(八月为玩月胜境)；至若三冬，正可不必雨也。','["孔东塘曰：君若果有此牍，吾愿作致书邮也。","余生生曰：使天而雨粟，虽自元旦雨至除夕，亦未为不可。","张竹坡曰：此书独不可致于巫山雨师。"]',''),('qingyan-037','幽梦影 · 十七','张潮','qingyan','','','为浊富，不若为清贫；以忧生，不若以乐死。','["李圣许曰：顺理而生，虽忧不忧；逆理而死，虽乐不乐。","吴野人曰：我宁愿为浊富。","张竹坡曰：我愿太奢，欲为清富，焉能遂愿！"]',''),('qingyan-038','幽梦影 · 十八','张潮','qingyan','','','天下唯鬼最富，生前囊无一文，死后每饶楮镪；天下唯鬼最尊，生前或受欺凌，死后必多跪拜。','["吴野人曰：世于贫士，辄目为穷鬼，则又何也？","陈康畴曰：穷鬼若死，即并称尊矣。"]',''),('qingyan-039','幽梦影 · 十九','张潮','qingyan','','','蝶为才子之化身，花乃美人之别号。','["张竹坡曰：蝶入花房香满衣，是反以金屋贮才子矣。"]',''),('qingyan-040','幽梦影 · 二十','张潮','qingyan','','','因雪想高士，因花想美人，因酒想侠客，因月想好友，因山水想得意诗文。','["弟木山曰：佘每见人一长、一技，即思效之；虽至琐屑，亦不厌也。大约是爱博而情不专。","张竹坡曰：多情语令人泣下。","尤谨庸曰：因得意诗文，想心斋矣。","李季子曰：此善于设想者。","陆云士曰：临川谓：“想内成，因中见。”与此相发。"]',''),('qingyan-041','幽梦影 · 一','张潮','qingyan','','','闻鹅声，如在白门；闻橹声，如在三吴；闻滩声，如在浙江；闻羸马项下铃铎声，如在长安道上。','["聂晋人曰：南无观世音菩萨摩诃萨。","倪永清曰：众音寂灭时，叉作么生话会？"]',''),('qingyan-042','幽梦影 · 二','张潮','qingyan','','','一岁诸节，以上元为第一，中秋次之，五日、九日又次之。','["张竹坡曰：一岁当以我畅意日为佳节。","顾天石曰：跻上元于中秋之上，未免尚耽绮习。"]',''),('qingyan-043','幽梦影 · 三','张潮','qingyan','','','雨之为物，能令昼短，能令夜长。','["张竹坡曰：雨之为物，能令天闭眼，能令地生毛，能为水国广封疆。"]',''),('qingyan-044','幽梦影 · 四','张潮','qingyan','','','古之不传于今者，啸也，剑术也，弹棋也，打球也。','["黄九烟曰：古之绝胜于今者，官妓、女道士也。","张竹坡曰：今之绝胜于古者，能吏也，猾棍也，无耻也。","庞天池曰：今之必不能传于后者，八股也。"]',''),('qingyan-045','幽梦影 · 五','张潮','qingyan','','','诗僧时复有之，若道士之能诗者，不啻空谷足音，何也？','["毕右万曰：僧、道能诗，亦非难事；但惜僧、道不知禅玄耳。","顾天石曰：道于三教中，原属第三。应是根器最钝人做，那得会诗！轩辕弥明，昌黎寓言耳。","尤谨庸曰：僧家势利第一，能诗次之。","倪永清曰：我所恨者，辟谷之法不传。"]',''),('qingyan-046','幽梦影 · 六','张潮','qingyan','','','当为花中之萱草，毋为鸟中之杜鹃。','["袁翔甫补评曰：萱草忘忧，杜鹃啼血。悲欢哀乐，何去何从？"]',''),('qingyan-047','幽梦影 · 七','张潮','qingyan','','','物之稚者，皆不可厌，惟驴独否。','["黄略似曰：物之老者，皆可厌；惟松与梅则否。","倪永清曰：惟癖于驴者，则不厌之。"]',''),('qingyan-048','幽梦影 · 八','张潮','qingyan','','','女子自十四五岁至二十四五岁，此十年中，无论燕、秦、吴、越，其音大都娇媚动人；一睹其貌，则美恶判然矣。“耳闻不如目见”，于此益信。','["吴听翁曰：我向以耳根之有余，补目力之不足；今读此，乃知卿言亦复佳也。","江含征曰：帘为妓衣，亦殊有见。","张竹坡曰：家有少年丑婢者，当令隔屏私语，灭烛侍寝。何如？","倪永清曰：若逢关貌而恶声者，又当何如？"]',''),('qingyan-049','幽梦影 · 九','张潮','qingyan','','','寻乐境，乃学仙；避苦趣，乃学佛。佛家所谓“极乐世界”者，盖谓众苦之所不到也。','["江含征曰：着败絮行荆棘中，固是苦事；彼披忍辱铠者，亦未得优游自到也。","陆云士曰：空诸所有，受即是空。其为苦乐，不足言矣，故学佛优于学仙。"]',''),('qingyan-050','幽梦影 · 十','张潮','qingyan','','','富贵而劳悴，不若安闲之贫贱；贫贱而骄傲，不若谦恭之富贵。','["曹实庵曰：富贵而又安闲，自能谦恭也。","许师六曰：富贵而又谦恭，乃能安闲耳。","张竹坡曰：谦恭安闲，乃能长富贵也。","张迂庵曰：安闲乃能骄傲，劳悴则必谦恭。"]',''),('qingyan-051','幽梦影 · 十一','张潮','qingyan','','','目不能自见，鼻不能自嗅，舌不能自舐，手不能自握，惟耳能自闻其声。','["弟木山曰：岂不闻心不在焉、听而不闻乎？兄其诳我哉！","张竹坡曰：心能自信。","释师昂曰：古德云：眉与目不相识，只为太近。"]',''),('qingyan-052','幽梦影 · 十二','张潮','qingyan','','','凡声皆宜远听，惟听琴则远近皆宜。','["王名友曰：松涛声、瀑布声、箫笛声、潮声、读书声、钟声、梵声，皆宜远听；惟琴声、度曲声、雪声，非至近不能得其离合抑扬之妙。","庞天池曰：凡色皆宜近看，惟山色远近皆宜。"]',''),('qingyan-053','幽梦影 · 十三','张潮','qingyan','','','目不能识字，其闷尤过于盲；手不能执管，其苦更甚于哑。','["陈鹤山曰：君独未知今之不识字、不握管者，其乐尤过于不盲、不哑者也。"]',''),('qingyan-054','幽梦影 · 十四','张潮','qingyan','','','并头联句，交颈论文，宫中应制，历使属国，皆极人间乐事。','["狄立人曰：既已并头、交颈，即欲联句、论文，恐亦有所不暇。","汪舟次曰：历使属国，殊不易易。","孙松坪曰：邯郸旧梦，对此惘然。","张竹坡曰：并头、交颈，乐事也；联句、论文，亦乐事也。是以两乐并为一乐者，则当以两夜并一夜方妙。然其乐一刻，胜于一日矣。","沈契掌曰：恐天亦见妒。"]',''),('qingyan-055','幽梦影 · 十五','张潮','qingyan','','','《水浒传》武松诘蒋门神云：“为何不姓李？”此语殊妙。盖姓实有佳有劣，如华、如柳、如云、如苏、如乔，皆极风韵；若夫毛也、赖也、焦也、牛也，则皆尘于目而棘于耳者也。','["先渭求曰：然则君为何不姓李耶？","张竹坡曰：止闻今张昔李，不闻今李昔张也。"]',''),('qingyan-056','幽梦影 · 十六','张潮','qingyan','','','花之宜于目而复宜于鼻者，梅也，菊也，兰也，水仙也，珠兰也，莲也；止宜于鼻者，橼也，桂也，瑞香也，栀子也，茉莉也，木香也，玫瑰也，腊梅也。余则皆宜于目者也。花与叶俱可观者，秋海棠为最，荷次之，海棠、酴(tu)醾 (mi）、虞美人、水仙又次之；叶胜于花者，止雁来红、美人蕉而已；花与叶俱不足观者，紫薇也，辛夷也。','["周星远曰：山老可当花阵一面。","张竹坡曰：以一叶而能胜诸花者，此君也。"]',''),('qingyan-057','幽梦影 · 十七','张潮','qingyan','','','高语山林者，辄不喜谈市朝事。审若此，则当并废《史》、《汉》诸书而不读矣。盖诸书所载者，皆古之市朝也。','["张竹坡曰：高语者，必是虚声处士；真入山者，方能经纶市朝。"]',''),('qingyan-058','幽梦影 · 十八','张潮','qingyan','','','云之为物，或崔巍如山，或潋滟如水，或如人，或如兽，或如鸟毳，或如鱼鳞；故天下万物皆可画，惟云不能画。世所画云，亦强名耳。','["何蔚宗曰：天下百官皆可做，惟教官不可做。做教官者，皆谪戍耳。","张竹坡曰：云有反面、正面，有阴阳、向背，有层次、内外。细观其与日相映，则知其明处乃一面，暗处又一面。尝谓古今无一画云手，不谓《幽梦影》中先得我心。"]',''),('qingyan-059','幽梦影 · 十九','张潮','qingyan','','','值太平世，生湖山郡；官长廉静，家道优裕；娶妇贤淑，生子聪慧。人生如此，可云全福。','["许筱林曰：若以粗笨愚蠢之人当之，则负却造物。","江含征曰：此是黑面老子要思量做鬼处。","吴岱观曰：过屠门而大嚼，虽不得肉，亦且快意。","李荔园日：贤淑、聪慧，尤贵永年，否则福不全。"]',''),('qingyan-060','幽梦影 · 二十','张潮','qingyan','','','天下器玩之类，其制日工，其价日贱，毋惑乎民之贫也。','["张竹坡曰：由于民贫，故益工；而益贱，若不贫，如何肯贱？"]',''),('qingyan-061','幽梦影 · 一','张潮','qingyan','','','养花胆瓶，其式之高低大小，须与花相称；而色之浅深浓淡，又须与花相反。','["程穆倩曰：足补袁中郎《瓶史》所未逮。","张竹坡曰：夫如此，有不甘去南枝而生香于几案之右者乎！名花心足矣。","王宓草曰：须知相反者，正欲其相称也。"]',''),('qingyan-062','幽梦影 · 二','张潮','qingyan','','','春雨如恩诏，夏雨如赦书，秋雨如挽歌。','["张谐石曰：我辈居恒苦饥，但愿夏雨如馒头耳。","张竹坡曰：赦书太多，亦不甚妙。"]',''),('qingyan-063','幽梦影 · 三','张潮','qingyan','','','十岁为神童，二十、三十为才子，四十、五十为名臣，六十为神仙，可谓全人矣。','["江含征曰：此却不可知，盖神童原有仙骨故也，只恐中间做名臣时，堕落名利场中耳。","杨圣藻曰：人孰不想？难得有此全福！","张竹坡曰：神童、才子由于己，可能也；名臣由于君，仙由于天，不可必也。","顾天石曰：六十神仙，似乎太早。"]',''),('qingyan-064','幽梦影 · 四','张潮','qingyan','','','武人不苟战，是为武中之文；文人不迂腐，是为文中之武。','["梅定九曰：近日文人不迂腐者颇多，心斋亦其一也。","顾天石曰：然则心斋直谓之武夫可乎？笑笑。","王司直曰：是真文人，必不迂腐。"]',''),('qingyan-065','幽梦影 · 五','张潮','qingyan','','','文人讲武事，大都纸上谈兵；武将论文章，半属道听途说。','["吴街南曰：今之武将讲武事，亦属纸上谈兵；今之文人论文章，大都道听途说。"]',''),('qingyan-066','幽梦影 · 六','张潮','qingyan','','','斗方止三种可存：佳诗文一也，新题目二也，精款式三也。','["闵宾连日：近年斗方名士甚多，不知能入吾心斋彀中否也？"]',''),('qingyan-067','幽梦影 · 七','张潮','qingyan','','','情必近于痴而始真，才必兼乎趣而始化。','["陆云士曰：真情种真才子能为此言。","顾天石曰：才兼乎趣，非心斋不足当之。","尤慧珠曰：余情而痴则有之，才而趣则未能也。"]',''),('qingyan-068','幽梦影 · 八','张潮','qingyan','','','凡花色之娇媚者，多不甚香；瓣之千层者，多不结实。甚矣！全才之难也！兼之者，其惟莲乎！','["殷日戒曰：花、叶、根、实无所不空，亦无不适于用，莲则全有其德者也。","贯玉曰：莲花易谢，所谓有全才而无全福也。","王丹麓曰：我欲荔枝有好花，牡丹有佳实，方妙。","尤谨庸曰：全才必为人所忌，莲花故名君子。"]',''),('qingyan-069','幽梦影 · 九','张潮','qingyan','','','着得一部新书，便是千秋大业；注得一部古书，允为万世宏功。','["黄交三曰：世间难事，注书第一。大要于极寻常书，要看出作者苦心。","张竹坡曰：注书无难，天使人得安居无累，有可以注书之时与地为难耳。"]',''),('qingyan-070','幽梦影 · 十','张潮','qingyan','','','延名师训子弟，入名山习举业，丐名士代捉刀，三者都无是处。','["陈康畴曰：大抵名而已矣，好歹原未必着意。","殷日戒曰：况今之所谓名乎！"]',''),('qingyan-071','幽梦影 · 十一','张潮','qingyan','','','积画以成字，积字以成句，积句以成篇，谓之文。文体日增，至八股而遂止。如古文、如诗、如赋、如词、如曲、如说部、如传奇小说，皆自无而有。方其未有之时，固不料后来之有此一体也。逮既有此一体之后，又若天造地设，为世必应有之物。然自明以来，未见有创一体裁新人耳目者。遥计百年之后，必有其人，惜乎不及见耳！','["陈康畴曰：天下事，从意起。山来今日既作此想，安知其来生不即为此辈翻新之士乎！惜乎今人不及知耳。","陈鹤山曰：此是先生应以创体身得度者，即现创体身而为设法。","孙恺似曰：读心斋别集，拈四子书题，以五七言韵体行之，无不入妙，叹其独绝。此则直可当先生自序也。","张竹坡曰：见及于此，是必能创之者。吾拭目以待新裁。"]',''),('qingyan-072','幽梦影 · 十二','张潮','qingyan','','','云映日而成霞，泉挂岩而成瀑。所托者异，而名亦因之。此友道之所以可贵也。','["张竹坡曰：非日而云不映，非岩而泉不挂。此友道之所以当择也。"]',''),('qingyan-073','幽梦影 · 十三','张潮','qingyan','','','大家之文，吾爱之慕之，吾愿学之；名家之文，吾爱之慕之，吾不敢学之。学大家而不得，所谓“刻鹄不成尚类鹜”也；学名家而不得，则是“画虎不成反类狗”矣。','["黄旧樵曰：我则异于是，最恶世之貌为大家者。","殷日戒曰：彼不曾闯其藩篱，乌能窥其阃奥！只说得隔壁话耳。","张竹坡曰：今人读得一两句名家，便自称大家矣。"]',''),('qingyan-074','幽梦影 · 十四','张潮','qingyan','','','由戒得定，由定得慧，勉强渐近自然；炼精化气，炼气化神，清虚有何渣滓！','["袁中江曰：此二氏之学也。吾儒何独不然！","陆云士曰：《楞严经》、《参同契》精义尽涵在内。","尤悔庵曰：极平常语，然道在是矣。"]',''),('qingyan-075','幽梦影 · 十五','张潮','qingyan','','','南北东西，一定之位也；前后左右，无定之位也。','["张竹坡曰：闻天地昼夜旋转，则此东西南北，亦无定之位也。或者天地外贮此天地者，当有一定耳。"]',''),('qingyan-076','幽梦影 · 十六','张潮','qingyan','','','予尝谓二氏不可废，非袭夫大养济院之陈言也。盖名山胜境，我辈每思褰裳就之，使非琳宫梵刹，则倦时无可驻足，饥时谁与授餐！忽有疾风暴雨，五大夫果真足恃乎？又或丘壑深邃，非一日可了。岂能露宿以待明日乎？虎豹蛇虺能保其不为人患乎？又或为士大夫所有，果能不问主人，任我之登陟凭吊，而莫之禁乎？##不特此也。甲之所有，乙思起而夺之，是启争端也。祖父之所创建，子孙贫，力不能修葺。其倾颓之状，反足令山川减色矣。##然此特就名山胜境言之耳。即城市之内，与夫四达之衢，亦不可少此一种。客游可作居停，一也；长途可以稍憩，二也；夏之茗，冬之姜汤，复可以济役夫负戴之困，三也。凡此皆就事理言之，非二氏福报之说也。','["释中洲曰：此论一出，量无悭檀越矣。","张竹坡曰：如此处置此辈甚妥。但不得令其于人家丧事诵经，吉事拜忏；装金为像，铸铜作身；房如宫殿，器御钟鼓，动说因果；虽饮酒食肉，娶妻生子，总无不可。","石天外曰：天地生气，大抵五十年一聚。生气一聚，必有刀兵、饥馑、瘟疫以收其生气。此古今一治一乱，必然之数也。自佛入中国，用剃度出家法，绝其后嗣，天地盖欲以佛节古今之生气也。所以，唐、宋、元、明以来，剃度者多，而刀兵去刀数稍减于春秋、战国、秦、汉诸时也。然则佛氏且未必无功于天地，宁特人类已哉！"]',''),('qingyan-077','幽梦影 · 十七','张潮','qingyan','','','虽不善书，而笔砚不可不精；虽不业医，而验方不可不存；虽不工弈，而楸枰不可不备。','["江含征曰：虽不善饮，而良酝不可不藏，此坡仙之所以为坡仙也。","顾天石曰：虽不好色，而美女妖童不可不蓄。","毕右万曰：虽不习武，而弓矢不可不张。"]',''),('qingyan-078','幽梦影 · 十八','张潮','qingyan','','','方外不必戒酒，但须戒俗；红裙不必通文，但须得趣。','["朱其恭曰：以不戒酒之方外，遇不通文之红裙，必有可观。","陈定九曰：我不善饮，而方外不饮酒者誓不与之语；红裙若不识趣，亦不乐与近。","释浮村曰：得居士此论，我辈可放心豪饮矣。","弟东囿曰：方外并戒了化缘，方妙。"]',''),('qingyan-079','幽梦影 · 十九','张潮','qingyan','','','梅边之石宜古，松下之石宜拙，竹傍之石宜瘦，盆内之石宜巧。','["周星远曰：论石至此，直可作九品中正。","释中洲曰：位置相当，足见胸次。"]',''),('qingyan-080','幽梦影 · 二十','张潮','qingyan','','','律己宜带秋气，处世宜带春气。','["孙松楸曰：君子所以有矜群而无争党也。","胡静夫曰：合夷、惠为一人，吾愿亲炙之。","尤悔庵曰：皮里春秋。"]',''),('qingyan-081','幽梦影 · 一','张潮','qingyan','','','厌催租之败意，亟宜早早完粮；喜老衲之谈禅，难免常常布施。','["释中洲曰：居士辈之实情，吾僧家之私冀，直被一笔写出矣。","瞎尊者曰：我不会谈禅，亦不敢妄求布施，惟闲写青山卖耳。"]',''),('qingyan-082','幽梦影 · 二','张潮','qingyan','','','松下听琴，月下听箫，涧边听瀑布，山中听梵呗，觉耳中别有不同。','["张竹坡曰：其不同处，有难于向不知者道。","倪永清曰：识得不同二字，方许享此清听。"]',''),('qingyan-083','幽梦影 · 三','张潮','qingyan','','','月下听禅，旨趣益远；月下说剑，肝胆益真；月下论诗，风致益幽；月下对美人，情意益笃。','["袁士旦曰：溽暑中赴华筵，冰雪中应考试，阴雨中对道学先生，与此况味何如？"]',''),('qingyan-084','幽梦影 · 四','张潮','qingyan','','','有地上之山水，有画上之山水，有梦中之山水，有胸中之山水。地上者，妙在丘壑深邃；画上者，妙在笔墨淋漓；梦中者，妙在景象变幻；胸中者，妙在位置自如。','["周星远曰：心斋《幽梦影》中文字，其妙亦在景象变幻。","殷日戒曰：若诗文中之山水，其幽深变幻更不可以名状。","江含征曰：但不可有面上之山水。","余香祖曰：余境况不佳，水穷山尽矣。"]',''),('qingyan-085','幽梦影 · 五','张潮','qingyan','','','一日之计种蕉，一岁之计种竹，十年之计种柳，百年之计种松。','["周星远曰：千秋之计，其着书乎？","张竹坡曰：百世之计种德。"]',''),('qingyan-086','幽梦影 · 六','张潮','qingyan','','','春雨宜读书，夏雨宜弈棋，秋雨宜检藏，冬雨宜饮酒。','["周星远曰：四时惟秋雨最难听，然予谓无分今雨、旧雨，听之要皆宜于饮也。"]',''),('qingyan-087','幽梦影 · 七','张潮','qingyan','','','诗文之体，得秋气为佳；词曲之体，得春气为佳。','["江含征曰：调有惨淡悲伤者，亦须相称。","殷日戒曰：陶诗，欧文，亦似以春气胜。"]',''),('qingyan-088','幽梦影 · 八','张潮','qingyan','','','抄写之笔墨，不必过求其佳；若施之缣素，则不可不求其佳。诵读之书籍，不必过求其备；若以供稽考，则不可不求其备。游历之山水，不必过求其妙；若因之卜居，则不可不求其妙。','["冒辟疆曰：外遇之女色，不必过求其美；若以作姬妾，则不可不求其美。","倪永清曰：观其区处条理，所在经济可知。","王司直曰：求其所当求，而不求其所不必求。"]',''),('qingyan-089','幽梦影 · 九','张潮','qingyan','','','人非圣贤，安能无所不知！只知其一，惟恐不止其一，复求知其二者，上也；止知其一，因人言始知有其二者，次也；止知其一，人言有其二而莫之信者，又其次也；止知其一，恶人言有其二者，斯下之下矣。','["周星远曰：兼听则聪，心斋所以深于知也。","倪永清曰：圣贤大学问，不意于清语得之。"]',''),('qingyan-090','幽梦影 · 十','张潮','qingyan','','','史官所纪者，直世界也；职方所载者，横世界也。','["袁中江曰：众宰官所治者，斜世界也。","尤悔庵曰：普天下所行者，混沌世界也。","顾天石曰：吾尝思天上之天堂，何处筑基？地下之地狱，何处出气？世界固有不可思议者！"]',''),('qingyan-091','幽梦影 · 十一','张潮','qingyan','','','先天八卦，竖看者也；后天八卦，横看者也。','["吴街南曰：横看竖看，皆看不着。","钱目天曰：何如袖手旁观！"]',''),('qingyan-092','幽梦影 · 十二','张潮','qingyan','','','藏书不难，能看为难；看书不难，能读为难；读书不难，能用为难；能用不难，能记为难。','["洪去芜曰：心斋以“能记”次于“能用”之后，想亦苦记性不如耳。世固有能记而不能用者。","王端人曰：能记、能用，方是真藏书人。","张竹坡曰：能记固难，能行尤难。"]',''),('qingyan-093','幽梦影 · 十三','张潮','qingyan','','','求知己于朋友易，求知己于妻妾难，求知己于君臣则尤难之难。','["王名友曰：求知己于妾易，求知己于妻难，求知己于有妾之妻尤难。","张竹坡曰：求知己于兄弟亦难。","江含征曰：求知己于鬼神则反易耳。"]',''),('qingyan-094','幽梦影 · 十四','张潮','qingyan','','','何谓善人？无损于世者，则谓之善人；何谓恶人？有害于世者，则谓之恶人。','["江含征曰：尚有有害于世而反邀善人之誉，此实为好利而显为名高者，则又恶人之尤。"]',''),('qingyan-095','幽梦影 · 十五','张潮','qingyan','','','有工夫读书，谓之福；有力量济人，谓之福；有学问着述，谓之福；无是非到耳，谓之福；有多闻、直谅之友，谓之福。','["殷日戒曰：我本薄福人，宜行求福事，在随时儆醒而已。","杨圣藻曰：在我者可必，在人者不能必。","王丹麓曰：备此福者，惟我心斋。","李水樵曰：五福骈臻固佳，苟得其半者，亦不得谓之无福。","倪永清曰：直谅之友，富贵人久拒之矣，何心斋反求之也？"]',''),('qingyan-096','幽梦影 · 十六','张潮','qingyan','','','人莫乐于闲，非无所事事之谓也。闲则能读书，闲则能游名胜，闲则能交益友，闲则能饮酒，闲则能着书。天下之乐，孰大于是？','["陈鹤山曰：然则正是极忙处。","黄交三曰：闲字前，有止敬功夫，方能到此。","尤悔庵曰：昔人云“忙里偷闲”，闲而可偷，盗亦有道矣。","李若金曰：闲固难得。有此五者，方不负闲字。"]',''),('qingyan-097','幽梦影 · 十七','张潮','qingyan','','','文章是案头之山水，山水是地上之文章。','["李圣许曰：文章必明秀，方可作案头山水；山水必曲折，乃可名地上文章。"]',''),('qingyan-098','幽梦影 · 十八','张潮','qingyan','','','平上去入，乃一定之至理。然入声之为字也少，不得谓凡字皆有四声也。世之调平仄者，于入声之无其字者，往往以不相合之音隶于其下。为所隶者，苟无平上去之三声，则是以寡妇配鳏夫，犹之可也。若所隶之字自有其平上去之三声，而欲强以从我，则是干有夫之妇矣，其可乎？姑就诗韵言之，如东、冬韵，无入声者也，今人尽调之以东、董、冻、督。夫督之为音，当附于都、睹、妒之下；若属之于东、董、冻，又何以处夫都、睹、妒乎？若东、都二字俱以督字为入声，则是一妇而两夫矣。三江无入声者也，今人尽调之以江、讲、绛、觉，殊不知觉之为音，当附于交、绞、教之下者也。诸如此类，不胜其举。然则如之何而后可？曰：鳏者听其鳏，寡者听其寡，夫妇全者安其全，各不相干而已矣。（东、冬、欢、桓、寒、山、真、文、元、渊、先、天、庚、青、侵、盐、咸诸部皆无入声者也。屋、沃内如秃、独、鹄、束等字，乃鱼、虞韵，内都、图等字之入声；卜、木、六、仆等字，乃五歌部之入声；玉、菊、狱、育等字，乃尤部之入声；三觉、十药，当属于萧、肴、豪；质、锡、职、缉，当属于支、微、齐。质内之桔、卒，物内之郁、屈，当属于虞、鱼；物内之勿、物等音，无平上去者也；讫、乞等，四支之入声也。陌部乃佳、灰之半，开、来等字之入声也。月部之月、厥、阙、谒等及屑、叶二部，古无平上去，而今则为中州韵内车、遮诸字之入声也。伐、发等字及曷部之括、适及八黠全部，又十五合内诸字，又十七洽全部，皆六麻之入声也。曷内之撮、阔等字，合部之合、盒数字，皆无平上去者也。若以缉、合、叶、洽为闭口韵，则止当谓之无平上去之寡妇，而不当调之以侵、寝、缉、咸、喊、陷、洽也。）','["石天外曰：中州韵无入声，是有夫无妇，天下皆成旷夫世界矣。"]',''),('qingyan-099','幽梦影 · 十九','张潮','qingyan','','','《水浒传》是一部怒书，《西游记》是一部悟书，《金瓶梅》是一部哀书。','["江含征曰：不会看《金瓶梅》，而只学其淫，是爱东坡者，但喜吃东坡肉耳。","殷日戒曰：《幽梦影》是一部快书。","朱其恭曰：余谓《幽梦影》是一部趣书。"]',''),('qingyan-100','幽梦影 · 二十','张潮','qingyan','','','读书最乐，若读史书，则喜少怒多；究之怒处，亦乐处也。','["张竹坡曰：读到喜、怒俱忘，是大乐境。","陆云士曰：余尝有句云：“读《三国志》，无人不为刘；读《南宋书》，无人不冤岳。”第人不知怒处亦乐处耳。怒而能乐，惟善读史者知之。"]',''),('qingyan-101','幽梦影 · 一','张潮','qingyan','','','发前人未发之论，方是奇书；言妻子难言之情，乃为密友。','["孙恺似曰：前二语，是心斋着书本领。","毕右万曰：奇书我却有数种，如人不肯看何？","陆云士曰：《幽梦影》一书所发者，皆未发之论；所言者，皆难言之情。欲语羞雷同，可以题赠。"]',''),('qingyan-102','幽梦影 · 二','张潮','qingyan','','','一介之士，必有密友。密友不必定是刎颈之交。大率虽千百里之遥，皆可相信，而不为浮言所动；闻有谤之者，即多方为之辩析而后已；事之宜行宜止者，代为筹画决断；或事当利害关头，有所需而后济者，即不必与闻，亦不虑其负我与否，竟为力承其事。此皆所谓密友也。','["殷日戒曰：后段更见恳切周详，可以想见其为人矣。","石天外曰：如此密友，人生能得几个？仆愿心斋先生当之。"]',''),('qingyan-103','幽梦影 · 三','张潮','qingyan','','','风流自赏，只容花鸟趋陪；真率谁知？合受烟霞供养。','["江含征曰：东坡有云：当此之时，若有所思，而无所思。"]',''),('qingyan-104','幽梦影 · 四','张潮','qingyan','','','万事可忘，难忘者名心一段；千般易淡，未淡者美酒三杯。','["张竹坡曰：是闻鸡起舞，酒后耳热气象。","王丹麓曰：予性不耐饮，美酒亦易淡。所最难忘者，名耳。","陆云士曰：惟恐不好名。丹麓此言，具见真处。"]',''),('qingyan-105','幽梦影 · 五','张潮','qingyan','','','芰荷可食，而亦可衣；金石可器，而亦可服。','["张竹坡曰：然后知濂溪不过为衣食计耳。","王司直曰：今之为衣食计者，果似濂溪否？"]',''),('qingyan-106','幽梦影 · 六','张潮','qingyan','','','宜于耳，复宜于目者，弹琴也，吹箫也；宜于耳，不宜于目者，吹笙也，擪(ye)管也。','["李圣许曰：宜于目不宜于耳者，狮子吼之美妇人也；不宜于目并不宜于耳者，面目可憎、语言无味之纨袴子也。","庞天池曰：宜于耳复宜于目者，巧言令色也。"]',''),('qingyan-107','幽梦影 · 七','张潮','qingyan','','','看晓妆，宜于傅粉之后。','["余淡心曰：看晚妆，不知心斋以为宜于何时？","周冰持曰：不可说！不可说！","黄交三曰：水晶帘下看梳头，不知尔时曾傅粉否？","庞天池曰：看残妆，宜于微醉后，然眼花撩乱矣。"]',''),('qingyan-108','幽梦影 · 八','张潮','qingyan','','','我不知我之生前，当春秋之季，曾一识西施否？当典午之时，曾一看卫玠否？当义熙之世，曾一醉渊明否？当天宝之代，曾一睹太真否？当元丰之朝，曾一晤东坡否？##千古之上相思者，不止此数人。而此数人则其尤甚者，故姑举之以概其余也。','["杨圣藻曰：君前生曾与诸君周旋，亦未可知，但今生忘之耳。","纪伯紫曰：君之前生，或竞是渊明、东坡诸人，亦未可知。","王名友曰：不特此也！心斋自云：“愿来生为绝代佳人！”又安知西施、太真不即为其前生耶！","郑破水曰：赞叹爱慕，千古一情。美人不必为妻妾，名士不必为朋友，又何必问之前生也耶！心斋真情痴也。","陆云士曰：余尝有诗曰：“自昔闻佛言，人有轮回事。前生为古人，不知何姓氏！或览青史中，若与他人遇！”竟与心斋同情，然大逊其奇快！"]',''),('qingyan-109','幽梦影 · 九','张潮','qingyan','','','我又不知在隆、万时，曾于旧院中交几名妓？眉公、伯虎、若士、赤水诸君，曾共我谈笑几回？茫茫宇宙，我今当向谁问之耶！','["江含征曰：死者有知，则良晤匪遥。如各化为异物，吾未如之何也已！","顾天石曰：具此襟情，百年后当有恨不与心斋周旋者，则吾幸矣！"]',''),('qingyan-110','幽梦影 · 十','张潮','qingyan','','','文章是有字句之锦绣，锦绣是无字句之文章，两者同出于一原。姑即粗迹论之，如金陵，如武林，如姑苏，书林之所在，即机杼之所在也。','["袁翔甫补评曰：若兰回文，是有字句之锦绣也；落花水面，是无字句之文章也。"]',''),('qingyan-111','幽梦影 · 十一','张潮','qingyan','','','予尝集诸法帖字为诗，字之不复而多者，莫善于《千字文》。然诗家目前常用之字，犹苦其未备。如天文之烟霞风雪，地理之江山塘岸，时令之春霄晓暮，人物之翁僧渔樵，花木之花柳苔萍，鸟兽之蜂蝶莺燕，宫室之台槛轩窗，器用之舟船壶杖，人事之梦忆愁恨，衣服之裙袖锦绮，饮食之茶浆饮酌，身体之须眉韵态，声色之红绿香艳，文史之骚赋题吟，数目之一三双半，皆无其字。《千字文》且然，况其他乎？','["黄仙裳曰：山来此种诗，竟似为我而设。","顾天石曰：使其皆备，则《千字文》不为奇矣！吾尝于千字之外另集千字，而已不可复得，更奇。"]',''),('qingyan-112','幽梦影 · 十二','张潮','qingyan','','','花不可见其落，月不可见其沉，美人不可见其夭。','["朱其恭曰：君言谬矣！洵如所云，则美人必见其发白齿豁，而后快耶！"]',''),('qingyan-113','幽梦影 · 十三','张潮','qingyan','','','种花须见其开，待月须见其满，着书须见其成，美人须见其畅适，方有实际。否则皆为虚设。','["王璞庵曰：此条与上条互相发明。盖曰“花不可见其落”耳，必须见其开也。"]',''),('qingyan-114','幽梦影 · 十四','张潮','qingyan','','','惠施多方，其书五车；虞卿以穷愁着书，今皆不传。不知书中果作何语？我不见古人，安得不恨！','["王仔园曰：想亦与《幽梦影》相类耳！","顾天石曰：古人所读之书，所着之书，若不被秦人所烧尽，则奇奇怪怪，可供今人刻画者，知复何限！然如《幽梦影》等书出，不必思古人矣。","倪永清曰：有着书之名，而不见书，省人多少指摘！","庞天池曰：我独恨古人不见心斋！"]',''),('qingyan-115','幽梦影 · 十五','张潮','qingyan','','','以松花为粮，以松实为香，以松枝为麈尾，以松阴为步障，以松涛为鼓吹。山居得乔松百余章，真乃受用不尽。','["施愚山曰：君独不记曾有“松多大蚁”之恨耶！","江含征曰：松多大蚁，不妨便为蚁王。","石天外曰：坐乔松下，如在水晶宫中见万顷波涛总在头上，真仙境也。"]',''),('qingyan-116','幽梦影 · 十六','张潮','qingyan','','','玩月之法，皎洁则宜仰观，朦胧则宜俯视。','["孔东塘曰：深得玩月三昧。"]',''),('qingyan-117','幽梦影 · 十七','张潮','qingyan','','','孩提之童，一无所知，目不能辨美恶，耳不能判清浊，鼻不能别香臭。至若味之甘苦，则不第知之，且能取之弃之。告子以甘食、悦色为性，殆指此类耳。','[]',''),('qingyan-118','幽梦影 · 十八','张潮','qingyan','','','凡事不宜刻，若读书则不可不刻；凡事不宜贪，若买书则不可不贪；凡事不宜痴，若行善，则不可不痴。','["余淡心曰：“读书不可不刻”，请去一“读”字，移以赠我，何如？","张竹坡曰：我为刻书累，请并去一“不”字。","杨圣藻曰：行善不痴，是邀名矣。"]','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('qingyan-119','幽梦影 · 十九','张潮','qingyan','','','酒可好，不可骂座；色可好，不可伤生；财可好，不可昧心；气可好，不可越理。','["袁中江曰：如灌夫使酒，文园病肺，昨夜南塘一出，马上挟章台柳归，亦自无妨，觉愈见英雄本色也。"]',''),('qingyan-120','幽梦影 · 二十','张潮','qingyan','','','文名可以当科第，俭德可以当货财，清闲可以当寿考。','["聂晋人曰：若名人而登甲第，富翁而不骄奢，寿翁而又清闲，便是蓬壶三岛中人也。","范汝受曰：此亦是贫贱文人无所事事，自为慰藉云耳；恐亦无实在受用处也。","曾青藜曰：“无事此静坐，一日似两日。若活七十年，便是百四十。”此是清闲当寿考注脚。","石天外曰：得《老子》“退一步”法。","顾天石曰：予生平喜游，每逢佳山水，辄留连不去，亦自谓“可当园亭之乐”。质之心斋，以为然否？"]',''),('qingyan-121','幽梦影 · 一','张潮','qingyan','','','不独诵其诗、读其书是尚友古人，即观其字画，亦是尚友古人处。','["张竹坡曰：能友字画中之古人，则九原皆为之感泣矣！"]',''),('qingyan-122','幽梦影 · 二','张潮','qingyan','','','无益之施舍，莫过于斋僧；无益之诗文，莫甚于祝寿。','["张竹坡曰：无益之心思，莫过于忧贫；无益之学问，莫过于务名。","殷简堂曰：若诗文有笔资，亦未尝不可。","庞天池曰：有益之施舍，莫过于多送我《幽梦影》几册。"]',''),('qingyan-123','幽梦影 · 三','张潮','qingyan','','','妾美不如妻贤，钱多不如境顺。','["张竹坡曰：此所谓“竿头欲进步”者。然妻不贤，安用妾美？钱不多，那得境顺？","张迂庵曰：此盖谓二者不可得兼，舍一而取一者也。","又曰：世固有钱多而境不顺者。"]',''),('qingyan-124','幽梦影 · 四','张潮','qingyan','','','创新庵不若修古庙，读生书不若温旧业。','["张竹坡曰：是真会读书者，是真读过万卷书者，是真一书曾读过数遍者。","顾天石曰：惟《左传》、《楚词》、马、班、杜、韩之诗文，及《水浒》、《西厢》、《还魂》等书，虽读百遍不厌。此外皆不耐温者矣，奈何！","王安节曰：今世建生祠，又不若创茅庵。"]',''),('qingyan-125','幽梦影 · 五','张潮','qingyan','','','字与画同出一原，观六书始于象形，则可知已。','["江含征曰：有不可画之字，不得不用六法也。","张竹坡曰：千古人未经道破，却一口拈出。"]',''),('qingyan-126','幽梦影 · 六','张潮','qingyan','','','忙人园亭，宜与住宅相连；闲人园亭，不妨与住宅相远。','["张竹坡曰：真闲人，必以园亭为住宅。"]',''),('qingyan-127','幽梦影 · 七','张潮','qingyan','','','酒可以当茶，茶不可以当酒；诗可以当文，文不可以当诗；曲可以当词，词不可以当曲；月可以当灯，灯不可以当月；笔可以当口，口不可以当笔；婢可以当奴，奴不可以当婢。','["江含征曰：婢当奴，则太亲，吾恐“忽闻河东狮子吼”耳！","周星远曰：奴亦有可以当婢处，但未免稍逊耳。","又曰：近时士大夫往往耽此癖。吾辈驰骛之流，盗此虚名，亦欲效颦相尚；滔滔者天下皆是也，心斋岂未识其故乎？","张竹坡曰：婢可以当奴者，有奴之所有者也；奴不可以当婢者，有婢之所同有，无婢之所独有者也。","弟木山曰：兄于饮食之顷，恐月不可以当灯。","余湘客曰：以奴当婢，小姐权时落后也。","宗子发曰：惟帝王家不妨以奴当婢，盖以有阉割法也。每见人家奴子出入主母卧房，亦殊可虑。"]',''),('qingyan-128','幽梦影 · 八','张潮','qingyan','','','胸中小不平，可以酒消之；世间大不平，非剑不能消也。','["周星远曰：“看剑引杯长。”一切不平皆破除矣。","张竹坡曰：此平世的剑术，非隐娘辈所知。","张迂庵曰：苍苍者未必肯以太阿假人，似不能代作空空儿也。","尤悔庵曰：龙泉、太阿，汝知我者，岂止苏子美以一斗读《汉书》耶！"]',''),('qingyan-129','幽梦影 · 九','张潮','qingyan','','','不得已而谀之者，宁以口，毋以笔；不可耐而骂之者，亦宁以口，毋以笔。','["孙豹人曰：但恐未必能自主耳！","张竹坡曰：上句立品，下句立德。","张迂庵曰：匪惟立德，亦以免祸。","顾天石曰：今人笔不谀人，更无用笔之处矣。心斋不知此苦，还是唐、宋以上人耳！","陆云士曰：古《笔铭》曰：“毫毛茂茂，陷水可脱，陷文不活。”正此谓也。亦有谀以笔而实讥之者，亦有骂以笔而若誉之者。总以不笔为高。"]',''),('qingyan-130','幽梦影 · 十','张潮','qingyan','','','多情者必好色，而好色者未必尽属多情；红颜者必薄命，而薄命者未必尽属红颜；能诗者必好酒，而好酒者未必尽属能诗。','["张竹坡曰：情起于色者，则好色也，非情也；祸起于颜色者，则薄命在红颜，否则亦止曰命而已矣！","洪秋士曰：世亦有能诗而不好酒者。"]',''),('qingyan-131','幽梦影 · 十一','张潮','qingyan','','','梅令人高，兰令人幽，菊令人野，莲令人淡，春海棠令人艳，牡丹令人豪，蕉与竹令人韵，秋海棠令人媚，松令人逸，桐令人清，柳令人感。','["张竹坡曰：美人令众卉皆香，名士令群芳俱舞。","尤谨庸曰：读之惊才绝艳，堪采入《群芳谱》中。"]',''),('qingyan-132','幽梦影 · 十二','张潮','qingyan','','','物之能感人者，在天莫如月，在乐莫如琴，在动物莫如鹃，在植物莫如柳。','[]',''),('qingyan-133','幽梦影 · 十三','张潮','qingyan','','','妻、子颇足累人，羡和靖梅妻鹤子；奴、婢亦能供职，喜志和樵婢渔奴。','["尤悔庵曰：梅妻鹤子，樵婢渔童，可称绝对。人生眷属，得此足矣！"]',''),('qingyan-134','幽梦影 · 十四','张潮','qingyan','','','涉猎虽曰无用，犹胜于不通古今；清高固然可嘉，莫流于不识时务。','["黄交三曰：南阳抱膝时，原非清高者可比。","江含征曰：此是心斋经济语。","张竹坡曰：不合时宜，则可；不达时务，奚其可？","尤悔庵曰：名言！名言！"]',''),('qingyan-135','幽梦影 · 十五','张潮','qingyan','','','所谓美人者，以花为貌，以鸟为声，以月为神，以柳为态，以玉为骨，以冰雪为肤，以秋水为姿，以诗词为心，吾无间然矣。','["冒辟疆曰：合古今灵秀之气，庶几铸此一人。","江含征曰：还要有松蘖之操才好。","黄交三曰：论美人而曰“以诗词为心”，真是闻所未闻！"]',''),('qingyan-136','幽梦影 · 十六','张潮','qingyan','','','蝇集人面，蚊嘬人肤，不知以人为何物！','["陈康畴曰：应是头陀转世，意中但求布施也。","释菌人曰：不堪道破！","张竹坡曰：此《南华》精髓也。","尤悔庵曰：正以人之血肉只堪供蝇蚊咀嚼耳。以我视之，人也；自蝇蚊视之，何异腥膻臭腐乎！","陆云士曰：集人面者，非蝇而蝇；嘬人肤者，非蚊而蚊。明知其为人也，而集之、嘬之，更不知其以人为何物！"]',''),('qingyan-137','幽梦影 · 十七','张潮','qingyan','','','有山林隐逸之乐而不知享者，渔樵也，农圃也，缁黄也；有园亭姬妾之乐而不能享、不善享者，富商也，大僚也。','["弟木山曰：有山珍海错而不能享者，庖人也；有牙签玉轴而不能读者，蠹鱼也，书贾也。"]',''),('qingyan-138','幽梦影 · 十八','张潮','qingyan','','','黎举云：“欲令梅聘海棠，枨子(想是橙)臣樱桃，以芥嫁笋，但时不同耳！”予谓物各有偶，拟必于伦。今之嫁娶，殊觉未当。如梅之为物，品最清高；棠之为物，姿极妖艳。即使同时，亦不可为夫妇。不若梅聘梨花，海棠嫁杏，橼臣佛手，荔枝臣樱桃，秋海棠嫁雁来红，庶几相称耳。至若以芥嫁笋，笋如有知，必受河东狮子之累矣。','["弟木山曰：余尝以芍药为牡丹后，因作贺表一通。兄曾云：“但恐芍药未必肯耳！”","石天外曰：花神有知，当以花果数升谢蹇修矣。","姜学在曰：雁来红做新郎，真个是老少年也。"]',''),('qingyan-139','幽梦影 · 十九','张潮','qingyan','','','五色有太过，有不及，惟黑与白无太过。','["杜茶村曰：君独不闻唐有李太白乎？","江含征曰：又不闻“玄之又玄”乎？","尤悔庵曰：知此道者，其惟弈乎！老子曰：“知其白，守其黑。”"]',''),('qingyan-140','幽梦影 · 二十','张潮','qingyan','','','许氏《说文》分部，有止有其部，而无所属之字者，下必注云：“凡某之属，皆从某。”赘句殊觉可笑，何不省此一句乎？','["谭公子日：此独民县到任告示耳。","王司直日：此亦古史之遗。"]',''),('qingyan-141','幽梦影 · 一','张潮','qingyan','','','阅《水浒传》，至鲁达打镇关西、武松打虎，因思人生必有一桩极快意事，方不枉在生一场。即不能有其事，亦须着得一种得意之书，庶几无憾耳！（如李太白有贵妃捧砚事，司马相如有文君当垆事，严子陵有足加帝腹事，王之涣、王昌龄有旗亭画壁事，王子安有顺风过江作《滕王阁序》事之类。）','["张竹坡曰：此等事，必须无意中方做得来。","陆云士曰：心斋所着得意之书颇多，不止一打快活林、一打景阳冈称快意矣。","弟木山曰：兄若打中山狼，更极快意。"]',''),('qingyan-142','幽梦影 · 二','张潮','qingyan','','','春风如酒，夏风如茗，秋风如烟，如姜芥。','["许筠庵曰：所以“秋风客”气味狠辣。","张竹坡日：安得东风夜夜来！"]',''),('qingyan-143','幽梦影 · 三','张潮','qingyan','','','冰裂纹极雅，然宜细不宜肥。若以之作窗栏，殊不耐观也。（冰裂纹须分大小，先作大冰裂，再于每大块之中作小冰裂，方佳。）','["江含征曰：此便是哥窑纹也。","靳熊封曰：“一片冰心在玉壶”，可以移赠。"]',''),('qingyan-144','幽梦影 · 四','张潮','qingyan','','','鸟声之最佳者，画眉第一，黄鹂、百舌次之。然黄鹂、百舌，世未有笼而畜之者。其殆高士之俦，可闻而不可屈者耶。','["江含征曰：又有“打起黄莺儿”者，然则亦有时用他不着。","陆云士曰：“黄鹂住久浑相识，欲别频啼四五声。”来去有情，正不必笼而畜之也。"]',''),('qingyan-145','幽梦影 · 五','张潮','qingyan','','','不治生产，其后必致累人；专务交游，其后必致累己。','["杨圣藻曰：晨钟夕磬，发人深省。","冒巢民曰：若在我，虽累己、累人，亦所不悔。","宗子发曰：累己犹可，若累人，则不可矣。","江含征曰：今之人未必肯受你累，还是自家稳些的好。"]',''),('qingyan-146','幽梦影 · 六','张潮','qingyan','','','昔人云：“妇人识字，多致诲淫。”予谓此非识字之过也。盖识字则非无闻之人，其淫也，人易得而知耳。','["张竹坡曰：此名士持身，不可不加谨也。","李若金曰：贞者识字愈贞，淫者不识字亦淫。"]',''),('qingyan-147','幽梦影 · 七','张潮','qingyan','','','善读书者，无之而非书：山水亦书也，棋酒亦书也，花月亦书也；善游山水者，无之而非山水：书史亦山水也，诗酒亦山水也，花月亦山水也。','["陈鹤山曰：此方是真善读书人，善游山水人。","黄交三曰：善于领会者，当作如是观。","江含征曰：五更卧被，时有无数山水书籍在眼前胸中。","尤悔庵曰：山耶，水耶，书耶，一而二，二而三，三而一者也。","陆云士曰：妙舌如环，真慧业文人之语。"]',''),('qingyan-148','幽梦影 · 八','张潮','qingyan','','','园亭之妙，在丘壑布置，不在雕绘琐屑。往往见人家园亭，屋脊墙头，雕砖镂瓦，非不穷极工巧，然未久即坏，坏后极难修葺，是何如朴素之为佳乎！','["江含征曰：世间最令人神怆者，莫如名园雅墅，一经颓废，风台月榭，埋没荆棘。故昔之贤达，有不欲置别业者。予尝过琴虞，留题名园，句有云：“而今绮砌雕栏在，剩与园丁作业钱。”盖伤之也。","弟木山曰：予尝悟作园亭与作光棍二法。园亭之善，在多回廊；光棍之恶，在能结讼。"]',''),('qingyan-149','幽梦影 · 九','张潮','qingyan','','','清宵独坐，邀月言愁；良夜孤眠，呼蛩语恨。','["袁士旦曰：令我百端交集。","黄孔植曰：此逆旅无聊之况，心斋亦知之乎！"]',''),('qingyan-150','幽梦影 · 十','张潮','qingyan','','','官声采于舆论，豪右之口与寒乞之口俱不得其真；花案定于成心，艳媚之评与寝陋之评概恐失其实。','["黄九烟曰：先师有言：“不如乡人之善者，好之；其不善者，恶之。”","李若金曰：豪右而不讲分上，寒乞而不望推恩者，亦未尝无公论。","倪永清曰：我谓众人唾骂者，其人必有可观。"]',''),('qingyan-151','幽梦影 · 十一','张潮','qingyan','','','胸藏丘壑，城市不异山林；兴寄烟霞，阎浮有如蓬岛。','[]',''),('qingyan-152','幽梦影 · 十二','张潮','qingyan','','','梧桐为植物中清品，而形家独忌之，甚且谓“梧桐大如斗，主人往外走”，若竟视为不祥之物也者。夫剪桐封弟，其为宫中之桐可知；而卜世最久者，莫过于周。俗言之不足据，类如此夫！','["江含征曰：爱碧梧者，遂艰于白镪。造物盖忌之，故靳之也。有何吉凶、休咎之可关！只是打秋风时，光棍样可厌耳！","尤悔庵曰：“梧桐生矣，于彼朝阳”，《诗》言之矣。","倪永清曰：心斋为梧桐雪千古之奇冤，百卉俱当九顿。"]',''),('qingyan-153','幽梦影 · 十三','张潮','qingyan','','','多情者，不以生死易心；好饮者，不以寒暑改量；喜读书者，不以忙闲作辍。','["朱其恭曰：此三言者，皆是心斋自为写照。","王司直日：我愿饮酒、读《离骚》，至死方辍，何如？"]',''),('qingyan-154','幽梦影 · 十四','张潮','qingyan','','','蛛为蝶之敌国，驴为马之附庸。','["周星远曰：妙论解颐，不数晋人危语、隐语。","黄交三曰：自开辟以来，未闻有此奇论。"]',''),('qingyan-155','幽梦影 · 十五','张潮','qingyan','','','立品，须发乎宋人之道学；涉世，须参以晋代之风流。','["方宝臣曰：真道学，未有不风流者。","张竹坡曰：夫子自道也。","胡静夫曰：予赠金陵前辈赵容庵句云：“文章鼎立庄骚外，杖履风流晋宋间。”今当移赠山老。","倪永清曰：等闲地位，却是个双料圣人。","陆云士曰：有不风流之道学，有风流之道学；有不道学风流，有道学之风流，毫厘千里。"]',''),('qingyan-156','幽梦影 · 十六','张潮','qingyan','','','古谓禽兽亦知人伦。予谓匪独禽兽也，即草木亦复有之。牡丹为王，芍药为相，其君臣也；南山之乔，北山之梓，其父子也；荆之闻分而枯，闻不分而活，其兄弟也；莲之并蒂，其夫妇也；兰之同心，其朋友也。','["江含征曰：纲常伦理，今日几于扫地，合向花木鸟兽中求之。","又曰：心斋不喜迂腐，此却有腐气。"]',''),('qingyan-157','幽梦影 · 十七','张潮','qingyan','','','豪杰易于圣贤，文人多于才子。','["张竹坡曰：豪杰不能为圣贤，圣贤未有不豪杰。文人才子亦然。"]',''),('qingyan-158','幽梦影 · 十八','张潮','qingyan','','','牛与马，一仕而一隐也；鹿与豕，一仙而一凡也。','["杜茶村曰：田单之火牛，亦曾效力疆场；至马之隐者，则绝无之矣。若武王归马于华山之阳，所谓“勒令致仕”者也。","张竹坡曰：“莫与儿孙作马牛”，盖为后人审出处语也。"]',''),('qingyan-159','幽梦影 · 十九','张潮','qingyan','','','古今至文，皆血泪所成。','["吴晴岩曰：山老《清泪痕》一书，细看皆是血泪。","江含征曰：古今恶文，亦纯是血。"]',''),('qingyan-160','幽梦影 · 二十','张潮','qingyan','','','情之一字，所以维持世界；才之一字，所以粉饰干坤。','["吴雨若曰：世界原从情字生出，有夫妇，然后有父子；有父子，然后有兄弟；有兄弟，然后有朋友；有朋友，然后有君臣。","释中洲曰：情与才缺一不可。"]',''),('qingyan-161','幽梦影 · 一','张潮','qingyan','','','孔子生于东鲁。东者，生方，故礼乐文章，其道皆自无而有。释迦生于西方。西者，死地，故受想行识，其教皆自有而无。','["吴街南曰：佛游东土，佛入生方；人望西天，岂知是寻死地。呜呼，西方之人兮，之死靡他！","殷日戒曰：孔子只勉人生时用功，佛氏只教人死时作主，各自一意。","倪永清曰：盘古生于天心，故其人在不有不无之间。"]',''),('qingyan-162','幽梦影 · 二','张潮','qingyan','','','有青山方有绿水，水惟借色于山；有美酒便有佳诗，诗亦乞灵于酒。','["李圣许曰：有青山绿水，乃可酌美酒而咏佳诗。是诗酒又发端于山水也。"]',''),('qingyan-163','幽梦影 · 三','张潮','qingyan','','','严君平，以卜讲学者也；孙思邈，以医讲学者也；诸葛武侯，以出师讲学者也。','["殷日戒曰：心斋殆又以《幽梦影》讲学者耶！","戴田友曰：如此讲学，才可称道学先生。"]',''),('qingyan-164','幽梦影 · 四','张潮','qingyan','','','人则女美于男，禽则雄华于雌，兽则牝牡无分者也。','["杜于皇曰：人亦有男美于女者，此尚非确论。","徐松之曰：此是茶村兴到之言，亦非定论。"]',''),('qingyan-165','幽梦影 · 五','张潮','qingyan','','','镜不幸而遇嫫母，砚不幸而遇俗子，剑不幸而遇庸将，皆无可奈何之事。','["杨圣藻曰：凡不幸者，皆可以此概之。","闵宾连日：心斋案头无一佳砚，然诗、文绝无一点尘俗气。此又砚之大幸也。","曹冲谷曰：最无可奈何者，佳人定随痴汉。"]',''),('qingyan-166','幽梦影 · 六','张潮','qingyan','','','天下无书则已，有则必当读；无酒则已，有则必当饮；无名山则已，有则必当游；无花月则已，有则必当赏玩；无才子佳人则已，有则必当爱慕怜惜。','["弟木山日：谈何容易！即吾家黄山，几能得一到耶？"]',''),('qingyan-167','幽梦影 · 七','张潮','qingyan','','','秋虫春鸟，尚能调声弄舌，时吐好音；我辈搦管拈毫，岂可甘作鸦鸣牛喘！','["吴园次曰：牛若不喘，宰相安肯问之？","张竹坡曰：宰相不问科律，而问牛喘，真是文章司命！","倪永清曰：世皆以鸦呜牛喘为凤歌鸾唱，奈何！"]',''),('qingyan-168','幽梦影 · 八','张潮','qingyan','','','媸颜陋质，不与镜为仇者，亦以镜为无知之死物耳。使镜而有知，必遭扑破矣。','["江含征曰：镜而有知，遇若辈早已回避矣。","张竹坡曰：镜而有知，必当化媸为妍。"]',''),('qingyan-169','幽梦影 · 九','张潮','qingyan','','','吾家公艺，恃百忍以同居，千古传为美谈。殊不知忍而至于百，则其家庭乖戾睽隔之处，正未易更仆数也。','["江含征曰：然除了一忍，更无别法。","顾天石曰：心斋此论，先得我心。忍以治家可耳；奈何进之高宗，使忍以养成武氏之祸哉！","倪永清曰：若用“忍”字，则百犹嫌少。否则以“剑”字处之，足矣。或曰“出家”二字，足以处之。","王安节曰：惟其乖戾睽隔，是以要忍。"]',''),('qingyan-170','幽梦影 · 十','张潮','qingyan','','','九世同居，诚为盛事。然止当与割股、庐墓者作一例看。可以为难矣，不可以为法也，以其非中庸之道也。','["洪去芜曰：古人原有“父子异宫”之说。","沈契掌曰：必居天下之广居而后可。"]',''),('qingyan-171','幽梦影 · 十一','张潮','qingyan','','','作文之法，意之曲折者，宜写之以显浅之词；理之显浅者，宜运之以曲折之笔。题之熟者，参之以新奇之想；题之庸者，深之以关系之论。至于窘者舒之使长，缛者删之使简，俚者文之使雅，闹者摄之使静，皆所谓裁制也。','["陈康畴曰：深得作文三昧语。","张竹坡曰：所谓节制之师。","王丹麓曰：文家秘旨，和盘托出，有功作者不浅。"]',''),('qingyan-172','幽梦影 · 十二','张潮','qingyan','','','笋为蔬中尤物，荔枝为果中尤物，蟹为水中尤物，酒为饮食中尤物，月为天文中尤物，西湖为山水中尤物，词曲为文字中尤物。','["张南村曰：《幽梦影》可为书中尤物。","陈鹤山曰：此一则又为《幽梦影》中尤物。"]',''),('qingyan-173','幽梦影 · 十三','张潮','qingyan','','','买得一本好花，犹且爱护而怜惜之，矧其为解语花乎！','["周星远曰：性至之语，自是君身有仙骨，世人那得知其故耶！","石天外曰：此一副心，令我念佛数声。","李若金曰：花能解语，而落于粗恶武夫，或遭狮吼戕贼，虽欲爱护，何可得？","王司直曰：此言是恻隐之心，即是是非之心。"]',''),('qingyan-174','幽梦影 · 十四','张潮','qingyan','','','观手中便面，足以知其人之雅俗，足以识其人之交游。','["李圣许曰：今人以笔资丐名人书画，名人何尝与之交游！吾知其手中便面虽雅，而其人则俗甚也。心斋此条，犹非定论。","毕蝎谷曰：人苟肯以笔资丐名人书画，则其人犹有雅道存焉，世固有并不爱此道者。","钱目天曰：二说皆然。"]',''),('qingyan-175','幽梦影 · 十五','张潮','qingyan','','','水为至污之所会归，火为至污之所不到。若变不洁为至洁，则水火皆然。','["江含征曰：世间之物，宜投诸水火者不少，盖喜其变也。"]',''),('qingyan-176','幽梦影 · 十六','张潮','qingyan','','','貌有丑而可观者，有虽不丑而不足观者；文有不通而可爱者，有虽通而极可厌者。此未易与浅人道也。','["陈康畴曰：相马于牝牡骊黄之外者，得之矣。","李若金曰：究竟可观者，必有奇怪处；可爱者，必无大不通。","梅雪坪曰：虽通而可厌，便可谓之不通。"]',''),('qingyan-177','幽梦影 · 十七','张潮','qingyan','','','游玩山水，亦复有缘。苟机缘未至，则虽近在数十里之内，亦无暇到也。','["张南村曰：予晤心斋时，询其曾游黄山否。心斋对以“未游”，当是机缘未至耳。","陆云士曰：余慕心斋者十年。今戊寅之冬，始得一面。身到黄山恨其晚，而正未晚也。"]',''),('qingyan-178','幽梦影 · 十八','张潮','qingyan','','','贫而无谄，富而无骄，古人之所贤也；贫而无骄，富而无谄，今人之所少也。足以知世风之降矣。','["许耒庵曰：战国时已有“贫贱骄人”之说矣。","张竹坡曰：有一人一时而对此谄、对彼骄者，更难！"]',''),('qingyan-179','幽梦影 · 十九','张潮','qingyan','','','昔人欲以十年读书、十年游山、十年检藏。予谓检藏尽可不必十年，只二三载足矣。若读书与游山，虽或相倍蓰，恐亦不足以偿所愿也。必也，如黄九烟前辈之所云，人生必三百年而后可乎？','["江含征曰：昔贤原谓尽则安能，但身到处，莫放过耳。","孙松坪曰：吾乡李长蘅先生爱湖上诸山，有“每个峰头住一年”之句。然则黄九烟先生所云，犹恨其少。","张竹坡曰：今日想来，彭祖反不如马迁。"]',''),('qingyan-180','幽梦影 · 二十','张潮','qingyan','','','宁为小人之所骂，毋为君子之所鄙；宁为盲主司之所摈弃，毋为诸名宿之所不知。','["陈康畴曰：世之人自今以后，慎毋骂心斋也。","江含征曰：不独骂也，即打亦无妨，但恐鸡肋不足以安尊拳耳！","张竹坡曰：后二句足少平吾恨。","李若金曰：不为小人所骂，便是乡愿；若为君子所鄙，断非佳士。"]',''),('qingyan-181','幽梦影 · 一','张潮','qingyan','','','傲骨不可无，傲心不可有。无傲骨则近于鄙夫，有傲心不得为君子。','["吴街南曰：立君子之侧，骨亦不可傲；当鄙夫之前，心亦不可不傲。","石天外曰：道学之言，才人之笔。","庞笔奴曰：现身说法，真实妙谛。"]',''),('qingyan-182','幽梦影 · 二','张潮','qingyan','','','蝉为虫中之夷、齐，蜂为虫中之管、晏。','["崔青峙曰：心斋可谓虫之董狐。","吴镜秋曰：蚊是虫中酷吏，蝇是虫中游客。"]',''),('qingyan-183','幽梦影 · 三','张潮','qingyan','','','曰痴、曰愚、曰拙、曰狂，皆非好字面，而人每乐居之；曰奸、曰黠、曰强、曰佞，反是，而人每不乐居之，何也？','["江含征曰：有其名者无其实，有其实者避其名。"]',''),('qingyan-184','幽梦影 · 四','张潮','qingyan','','','唐、虞之际，音乐可感鸟兽。此盖唐、虞之鸟兽，故可感耳。若后世之鸟兽，恐未必然。','["洪去芜曰：然则鸟兽亦随世道为升降耶？","陈康畴日：后世之鸟兽，应是后世之人所化身，即不无升降，正未可知。","石天外曰：鸟兽自是可感，但无唐、虞音乐耳。","毕右万曰：后世之鸟兽，与唐、虞无异，但后世之人迥不同耳！"]',''),('qingyan-185','幽梦影 · 五','张潮','qingyan','','','痛可忍，而痒不可忍；苦可耐，而酸不可耐。','["陈康畴曰：余见酸子偏不耐苦。","张竹坡曰：是痛、痒关心语。","余香祖曰：痒不可忍，须倩麻姑搔背。","释牧堂曰：若知痛痒、辨苦酸，便是居士悟处。"]',''),('qingyan-186','幽梦影 · 六','张潮','qingyan','','','镜中之影，着色人物也；月下之影，写意人物也。镜中之影，钩边画也；月下之影，没骨画也。月中山河之影，天文中地理也；水中星月之象，地理中天文也。','["恽叔子曰：绘空镂影之笔。","石天外曰：此种着色写意，能令古今善画人一齐搁笔。","沈契掌曰：好影子俱被心斋先生画着。"]',''),('qingyan-187','幽梦影 · 七','张潮','qingyan','','','能读无字之书，方可得惊人妙句；能会难通之解，方可参最上禅机。','["黄交三曰：山老之学，从悟而入，故常有彻天彻地之言。"]',''),('qingyan-188','幽梦影 · 八','张潮','qingyan','','','若无诗酒，则山水为具文；若无佳丽，则花月皆虚设。','[]',''),('qingyan-189','幽梦影 · 九','张潮','qingyan','','','才子而美姿容，佳人而工着作，断不能永年者。匪独为造物之所忌，盖此种原不独为一时之宝，乃古今万世之宝，故不欲久留人世，以取亵耳！','["郑破水曰：千古伤心，同声一哭。","王司直曰：千古伤心者，读此可以不哭矣！"]',''),('qingyan-190','幽梦影 · 十','张潮','qingyan','','','陈平封曲逆侯，《史》、《汉》注皆云“音去遇”。予谓此是北人土音耳。若南人四音俱全，似仍当读作本音为是。（北人于唱曲之曲，亦读如去字。）','["孙松坪曰：曲逆，今定县也。众水潆洄，势曲而流逆。予尝为土人订之，心斋重发吾覆矣。"]',''),('qingyan-191','幽梦影 · 十一','张潮','qingyan','','','古人四声俱备，如“六”、“国”二字皆入声也。今梨园演苏秦剧，必读“六”为“溜”，读“国”为“鬼”，从无读入声者。然考之《诗经》，如“良马六之”、“无衣六兮”之类，皆不与去声叶，而叶祝告燠；“国”字皆不与上声叶，而叶入陌质韵。则是古人似亦有入声，未必尽读“六”为“溜”，读“国”为“鬼”也。','["弟木山曰：梨园演苏秦，原不尽读“六国”为“溜鬼”，大抵以曲调为别。若曲是南调，则仍读入声也。"]',''),('qingyan-192','幽梦影 · 十二','张潮','qingyan','','','闲人之砚，固欲其佳；而忙人之砚，尤不可不佳。娱情之妾，固欲其美；而广嗣之妾，亦不可不美。','["江含征曰：砚美下墨可也，妾美招妒奈何？","张竹坡曰：妒在妾，不在美。"]',''),('qingyan-193','幽梦影 · 十三','张潮','qingyan','','','如何是独乐乐，曰鼓琴；如何是与人乐乐，曰弈棋；如何是与众乐乐，曰马吊。','["蔡铉升曰：独乐乐，与人乐乐，孰乐？曰不若与人。与少乐乐，与众乐乐，孰乐？曰不若与少。","王丹麓曰：我与蔡君异。独畏人为鬼阵，见则必乱其局而后已。"]',''),('qingyan-194','幽梦影 · 十四','张潮','qingyan','','','不待教而为善为恶者，胎生也；必待教而后为善为恶者，卵生也；偶因一事之感触而突然为善为恶者，湿生也（如周处、戴渊之改过，李怀光反叛之类）；前后判若两截，究非一日之故者，化生也（如唐玄宗、卫武公之类）。','[]',''),('qingyan-195','幽梦影 · 十五','张潮','qingyan','','','凡物皆以形用，其以神用者，则镜也、符印也、日晷也、指南针也。','["袁中江曰：凡人皆以形用。其以神用者，圣贤也，仙也，佛也。","黄虞外士曰：凡物之用皆形，而其所以然者，神也。镜凸凹而易其肥瘦，符印以专一而主其神机，日晷以恰当而定准则，指南以灵动而活其针缝。是皆神而明之存乎人矣。"]',''),('qingyan-196','幽梦影 · 十六','张潮','qingyan','','','才子遇才子，每有怜才之心；美人遇美人，必无惜美之意。我愿来世托为绝代佳人，一反其局而后快。','["陈鹤山曰：谚云：“鲍老当筵笑郭郎，笑他舞袖大郎当。若教鲍老当筵舞，转更郎当舞袖长。”则为之奈何？","郑蕃修曰：俟心斋来世为佳人时再议。","余湘客曰：古亦有“我见犹怜”者。","倪永清曰：再来时不可忘却。"]',''),('qingyan-197','幽梦影 · 十七','张潮','qingyan','','','予尝欲建一无遮大会，一祭历代才子，一祭历代佳人。俟遇有真正高僧，即当为之。','["顾天石曰：君若果有此盛举，请迟至二三十年之后，则我亦可以拜领盛情也。","释中洲曰：我是真正高僧，请即为之，何如？不然，则此二种沉魂滞魄，何日而得解脱耶？","江含征曰：折柬虽具，而未有定期，则才子佳人亦复怨声载道。","又曰：我恐非才子而冒为才子，非佳人而冒为佳人。虽有十万八千母陀罗臂，亦不能具香厨法膳也，心斋以为然否？","释远峰曰：中洲和尚，不得夺我施主！"]',''),('qingyan-198','幽梦影 · 十八','张潮','qingyan','','','圣贤者，天地之替身。','["石天外曰：此语大有功名教，敢不伏地拜倒！","张竹坡曰：圣贤者，干坤之帮手。"]',''),('qingyan-199','幽梦影 · 十九','张潮','qingyan','','','天极不难做，只须生仁人君子有才德者二三十人足矣。君一、相一、冢宰一，及诸路总制、抚军是也。','["黄九烟曰：吴歌有云：“做天切莫做四月天。”可见天亦有难做之时。","江含征曰：天若好做，又不须女娲氏补之。","尤谨庸曰：天不做天，只是做梦。奈何！奈何！","倪永清曰：天若都生善人，君相皆当袖手，便可无为而治。","陆云士曰：极诞极奇之话，极真极确之话。"]',''),('qingyan-200','幽梦影 · 二十','张潮','qingyan','','','掷“升官图”，所重在德，所忌在赃。何一登仕版，辄与之相反耶？','["江含征曰：所重在德，不过是要赢几文钱耳！","沈契掌曰：仕版原与纸版不同！"]',''),('qingyan-201','幽梦影 · 一','张潮','qingyan','','','动物中有三教焉：蛟、龙、麟、凤之属，近于儒者也；猿、狐、鹤、鹿之属，近于仙者也；狮子、牯牛之属，近于释者也。##植物中有三教焉：竹、梧、兰、蕙之属，近于儒者也；蟠桃、老桂之属，近于仙者也；莲花、薝卜之属，近于释者也。','["顾天石曰：请高唱《西厢》一句，一个通彻三教九流。","石天外曰：众人碌碌，动物中蜉蝣而已；世人峥嵘，植物中荆棘而已。"]',''),('qingyan-202','幽梦影 · 二','张潮','qingyan','','','佛氏云：“日月在须弥山腰。”果尔，则日月必是绕山横行而后可。苟有升有降，必为山巅所碍矣。又云：“地上有阿耨达池，其水四出，流入诸印度。”又云：“地轮之下为水轮，水轮之下为风轮，风轮之下为空轮。”余谓此皆喻言人身也。须弥山喻人首，日月喻两目；池水四出喻血脉流通，地轮喻此身，水为便溺，风为泄气。此下则无物也。','["释远峰曰：却被此公道破。","毕右万曰：干坤交后，有三股大气：一呼吸、二盘旋、三升降。呼吸之气，在八卦为震、巽，在天地为风、雷，为海潮，在人身为鼻息；盘旋之气，在八卦为坎、离，在天地为日、月，在人身为两目，为指尖、发顶罗纹，在草木为树节、蕉心；升降之气，在八卦为艮、兑，在天地为山、泽，在人身为髓液便溺，为头颅、肚腹，在草木为花叶之萌、雕，为树梢之向天、树根之入地。知此，而寓言之出于二氏者，皆可类推而悟。"]',''),('qingyan-203','幽梦影 · 三','张潮','qingyan','','','苏东坡和陶诗，尚遗数十首。予尝欲集坡句以补之，苦于韵之弗备而止。如《责子诗》中“不识六与七”、“但觅梨与栗”，“七”字与“栗”字，皆无其韵也。','[]',''),('qingyan-204','幽梦影 · 四','张潮','qingyan','','','予尝偶得句，亦殊可喜。惜无佳对，遂未成诗。其一为“枯叶带虫飞”，其一为“乡月大于城”。姑存之，以俟异日。','[]',''),('qingyan-205','幽梦影 · 五','张潮','qingyan','','','“空山无人，水流花开”二句，极琴心之妙境；“胜固欣然，败亦可喜”二句，极手谈之妙境；“帆随湘转，望衡九面”二句，极泛舟之妙境；“胡然而天，胡然而帝”二句，极美人之妙境。','[]',''),('qingyan-206','幽梦影 · 六','张潮','qingyan','','','镜与水之影，所受者也；日与灯之影，所施者也；月之有影，则在天者为受，而在地者为施也。','["郑破水曰：受、施二字，深得阴阳之理。","庞天池曰：幽梦之影，在心斋为施，在笔奴为受。"]',''),('qingyan-207','幽梦影 · 七','张潮','qingyan','','','水之为声有四：有瀑布声，有流泉声，有滩声，有沟浍声；风之为声有三：有松涛声，有秋叶声，有波浪声；雨之为声有二：有梧叶、荷叶上声，有承檐溜竹筒中声。','["弟木山曰：数声之中，惟水声最为厌。以其无已时，甚聒人耳也。"]',''),('qingyan-208','幽梦影 · 八','张潮','qingyan','','','文人每好鄙薄富人，然于诗文之佳者，又往往以金玉、珠玑、锦绣誉之，则又何也？','["陈鹤山曰：犹之富贵家张山癯野老落木荒村之画耳。","江含征曰：富人嫌其悭且俗耳，非嫌其珠玉文绣也。","张竹坡曰：不文，虽穷可鄙；能文，虽富可敬。","陆云士曰：竹坡之言，是真公道说话！","李若金曰：富人之可鄙者，在吝，或不好史、书，或畏交游，或趋炎热而轻忽寒士。若非然者，则富翁大有裨益人处，何可少之！"]',''),('qingyan-209','幽梦影 · 九','张潮','qingyan','','','能闲世人之所忙者，方能忙世人之所闲。','[]',''),('qingyan-210','幽梦影 · 十','张潮','qingyan','','','先读经，后读史，则论事不谬于圣贤；既读史，复读经，则观书不徒为章句。','["黄交三曰：宋儒语录中不可多得之句。","陆云士曰：先儒着书法，累牍连章，不若心斋数言道尽。","王宓草曰：妄论经、史者，还宜退而读经。"]',''),('qingyan-211','幽梦影 · 十一','张潮','qingyan','','','居城市中，当以画幅当山水，以盆景当苑囿，以书籍当朋友。','["周星远曰：究是心斋偏重独乐乐！","王司直曰：心斋先生置身于画中矣！"]',''),('qingyan-212','幽梦影 · 十二','张潮','qingyan','','','乡居须得良朋始佳，若田夫樵子仅能辨五谷而测晴雨，久且数，未免生厌矣。而友之中又当以能诗为第一，能谈次之，能画次之，能歌又次之，解觞政者又次之。','["江含征曰：说鬼话者，又次之。","殷日戒曰：奔走于富贵之门者，自应以善说鬼话为第一，而诸客次之。","倪永清曰：能诗者，必能说鬼话。","陆云士曰：三说递进，愈转愈妙，滑稽之雄。"]',''),('qingyan-213','幽梦影 · 十三','张潮','qingyan','','','玉兰，花中之伯夷也(高而且洁)；葵，花中之伊尹也(倾心向日)；莲，花中之柳下惠也(污泥不染)。鹤，鸟中之伯夷也(仙品)；鸡，鸟中之伊尹也(司晨)；莺，鸟中之柳下惠也(求友)。','[]',''),('qingyan-214','幽梦影 · 十四','张潮','qingyan','','','无其罪而虚受恶名者，蠹鱼也（蛀书之虫另是一种，其形如蚕蛹而差小）；有其罪而恒逃清议者，蜘蛛也。','["张竹坡曰：自是老吏断狱。","李若金曰：予尝有除蛛网说，则讨之未尝无人。"]',''),('qingyan-215','幽梦影 · 十五','张潮','qingyan','','','臭腐化为神奇，酱也，乳也，金汁也；至神奇化为臭腐，则是物皆然。','["袁中江曰：神奇不化臭腐者，黄金也、真诗文也。","王司直曰：曹操、王安石文字，亦是神奇出于臭腐。"]',''),('qingyan-216','幽梦影 · 十六','张潮','qingyan','','','黑与白交，黑能污白，白不能掩黑；香与臭混，臭能胜香，香不能敌臭。此君子小人相攻之大势也。','["弟木山曰：人必喜白而恶黑，黜臭而取香，此又君子必胜小人之理也。理在，又乌论乎势！","石天外曰：余尝言：于黑处着一些白，人必惊心骇目，皆知黑处有白；于白处着一些黑，人亦必惊心骇目，以为白处有黑。甚矣！君子之易于形短，小人之易于见长，此不虞之誉、求全之毁所由来也。读此慨然。","倪永清曰：当今以臭攻臭者不少。"]',''),('qingyan-217','幽梦影 · 十七','张潮','qingyan','','','耻之一字，所以治君子；痛之一字，所以治小人。','["张竹坡曰：若使君子以耻治小人，则有耻且格；小人以痛报君子，则尽忠报国。"]',''),('qingyan-218','幽梦影 · 十八','张潮','qingyan','','','镜不能自照，衡不能自权，剑不能自击。','["倪永清曰：诗不能自传，文不能自誉。","庞天池曰：美不能自见，恶不能自掩。"]',''),('qingyan-219','幽梦影 · 十九','张潮','qingyan','','','古人云：“诗必穷而后工。”盖穷则语多感慨，易于见长耳。若富贵中人，既不可忧贫叹贱，所谈者不过风云月露而已，诗安得佳！##苟思所变，计惟有出游一法。即以所见之山川风土、物产人情，或当疮痍兵燹之余，或值旱涝灾棂之后，无一不可寓之诗中。借他人之穷愁，以供我之咏叹，则诗亦不必待穷而后工也。','["张竹坡曰：所以郑监门《流民图》独步千古。","倪永清曰：得意之游，不暇作诗；失意之游，不能作诗。苟能以无意游之，则眼光识力定是不同。","尤悔庵曰：世之穷者多而工诗者少，诗亦不任受过也。"]',''),('quantangshi-00001','帝京篇十首 一','太宗皇帝','quantangshi','','卷1','秦川雄帝宅，函谷壮皇居。
绮殿千寻起，离宫百雉余。
连甍遥接汉，飞观迥凌虚。
云日隐层阙，风烟出绮疎。','',''),('quantangshi-00002','帝京篇十首 二','太宗皇帝','quantangshi','','卷1','岩廊罢机务，崇文聊驻辇。
玉匣启龙图，金绳披凤篆。
韦编断仍续，缥帙舒还卷。
对此乃淹留，欹案观坟典。','',''),('quantangshi-00003','帝京篇十首 三','太宗皇帝','quantangshi','','卷1','移步出词林，停舆欣武宴。
雕弓写明月，骏马疑流电。
惊雁落虚弦，啼猿悲急箭。
阅赏诚多美，于兹乃忘倦。','',''),('quantangshi-00004','帝京篇十首 四','太宗皇帝','quantangshi','','卷1','鸣笳临乐馆，眺听欢芳节。
急管韵朱弦，清歌凝白雪。
彩凤肃来仪，玄鹤纷成列。
去兹郑卫声，雅音方可悦。','',''),('quantangshi-00005','帝京篇十首 五','太宗皇帝','quantangshi','','卷1','芳辰追逸趣，禁苑信多奇。
桥形通汉上，峰势接云危。
烟霞交隐映，花鸟自参差。
何如肆辙迹？万里赏瑶池。','',''),('quantangshi-00006','帝京篇十首 六','太宗皇帝','quantangshi','','卷1','飞盖去芳园，兰桡游翠渚。
萍间日彩乱，荷处香风举。
桂楫满中川，弦歌振长屿。
岂必汾河曲，方为欢宴所。','',''),('quantangshi-00007','帝京篇十首 七','太宗皇帝','quantangshi','','卷1','落日双阙昏，回舆九重暮。
长烟散初碧，皎月澄轻素。
搴幌翫琴书，开轩引云雾。
斜汉耿层阁，清风摇玉树。','',''),('quantangshi-00008','帝京篇十首 八','太宗皇帝','quantangshi','','卷1','欢乐难再逢，芳辰良可惜。
玉酒泛云罍，兰肴陈绮席。
千钟合尧禹，百兽谐金石。
得志重寸阴，忘怀轻尺璧。','',''),('quantangshi-00009','帝京篇十首 九','太宗皇帝','quantangshi','','卷1','建章欢赏夕，二八尽妖妍。
罗绮昭阳殿，芬芳玳瑁筵。
佩移星正动，扇掩月初圆。
无劳上悬圃，即此对神仙。','',''),('quantangshi-00010','帝京篇十首 十','太宗皇帝','quantangshi','','卷1','以兹游观极，悠然独长想。
披卷览前踪，抚躬寻既往。
望古茅茨约，瞻今兰殿广。
人道恶高危，虚心戒盈荡。
奉天竭诚敬，临民思惠养。
纳善察忠谏，明科慎刑赏。
六五诚难继，四三非易仰。
广待淳化敷，方嗣云亭响。','',''),('quantangshi-00011','饮马长城窟行','太宗皇帝','quantangshi','','卷1','塞外悲风切，交河冰已结。
瀚海百重波，阴山千里雪。
迥戍危烽火，层峦引高节。
悠悠卷斾旌，饮马出长城。
寒沙连骑迹，朔吹断边声。
胡尘清玉塞，羌笛韵金钲。
绝漠干戈戢，车徒振原隰。
都尉反龙堆，将军旋马邑。
扬麾氛雾静，纪石功名立。
荒裔一戎衣，灵台凯歌入。','',''),('quantangshi-00012','执契静三边','太宗皇帝','quantangshi','','卷1','执契静三边，持衡临万姓。
玉彩辉关烛，金华流日镜。
无为宇宙清，有美璇玑正。
皎佩星连景，飘衣云结庆。
戢武耀七德，升文辉九功。
烟波澄旧碧，尘火息前红。
霜野韬莲劒，关城罢月弓。
钱缀榆天合，新城柳塞空。
花销葱岭雪，縠尽流沙雾。
秋驾转兢怀，春冰弥轸虑。
书绝龙庭羽，烽休凤穴戍。
衣宵寝二难，食旰餐三惧。
翦暴兴先废，除凶存昔亡。
圆盖归天壤，方舆入地荒。
孔海池京邑，双河沼帝乡。
循躬思励己，抚俗愧时康。
元首伫盐梅，股肱惟辅弼。
羽贤崆岭四，翼圣襄城七。
浇俗庶反淳，替文聊就质。
已知隆至道，共欢区宇一。','',''),('quantangshi-00013','正日临朝','太宗皇帝','quantangshi','','卷1','条风开献节，灰律动初阳。
百蛮奉遐賮，万国朝未央。
虽无舜禹迹，幸欣天地康。
车轨同八表，书文混四方。
赫奕俨冠盖，纷纶盛服章。
羽旄飞驰道，钟鼓震岩廊。
组练辉霞色，霜戟耀朝光。
晨宵怀至理，终愧抚遐荒。','',''),('quantangshi-00014','幸武功庆善宫','太宗皇帝','quantangshi','','卷1','寿丘惟旧迹，酆邑乃前基。
粤予承累圣，悬弧亦在兹。
弱龄逢运改，提劒郁匡时。
指麾八荒定，怀柔万国夷。
梯山咸入款，驾海亦来思。
单于陪武帐，日逐卫文㮰。
端扆朝四岳，无为任百司。
霜节明秋景，轻冰结水湄。
芸黄徧原隰，禾颖积京畿。
共乐还乡宴，欢比大风诗。','',''),('quantangshi-00015','重幸武功','太宗皇帝','quantangshi','','卷1','代马依朔吹，惊禽愁昔丛。
况兹承眷德，怀旧感深衷。
积善忻余庆，畅武悦成功。
垂衣天下治，端拱车书同。
白水巡前迹，丹陵幸旧宫。
列筵欢故老，高宴聚新丰。
驻跸抚田畯，回舆访牧童。
瑞气萦丹阙，祥烟散碧空。
孤屿含霜白，遥山带日红。
于焉欢击筑，聊以咏南风。','',''),('quantangshi-00016','经破薛举战地','太宗皇帝','quantangshi','','卷1','昔年怀壮气，提戈初仗节。
心随朗日高，志与秋霜洁。
移锋惊电起，转战长河决。
营碎落星沈，阵卷横云裂。
一挥氛沴静，再举鲸鲵灭。
于兹俯旧原，属目驻华轩。
沈沙无故迹，减竈有残痕。
浪霞穿水净，峰雾抱莲昏。
世途亟流易，人事殊今昔。
长想眺前踪，抚躬聊自适。','',''),('quantangshi-00017','过旧宅二首 一','太宗皇帝','quantangshi','','卷1','新丰停翠辇，谯邑驻鸣笳。
园荒一径断，苔古半阶斜。
前池消旧水，昔树发今花。
一朝辞此地，四海遂为家。','',''),('quantangshi-00018','过旧宅二首 二','太宗皇帝','quantangshi','','卷1','金舆巡白水，玉辇驻新丰。
纽落藤披架，花残菊破丛。
叶铺荒草蔓，流竭半池空。
纫佩兰凋径，舒圭叶翦桐。
昔地一蕃内，今宅九围中。
架海波澄镜，韬戈器反农。
八表文同轨，无劳歌大风。','',''),('quantangshi-00019','还陕述怀','太宗皇帝','quantangshi','','卷1','慨然抚长劒，济世岂邀名。
星旗纷电举，日羽肃天行。
徧野屯万骑，临原驻五营。
登山麾武节，背水纵神兵。
在昔戎戈动，今来宇宙平。','',''),('quantangshi-00020','入潼关','太宗皇帝','quantangshi','','卷1','崤函称地险，襟带壮两京。
霜峰直临道，冰河曲绕城。
古木参差影，寒猿断续声。
冠盖往来合，风尘朝夕惊。
高谈先马度，伪晓预鸡鸣。
弃繻怀远志，封泥负壮情。
别有真人气，安知名不名。','',''),('quantangshi-00021','于北平作','太宗皇帝','quantangshi','','卷1','翠野驻戎轩，卢龙转征斾。
遥山丽如绮，长流萦似带。
海气百重楼，岩松千丈盖。','',''),('quantangshi-00022','辽城望月','太宗皇帝','quantangshi','','卷1','玄兔月初明，澄辉照辽碣。
映云光暂隐，隔树花如缀。
魄满桂枝圆，轮亏镜彩缺。
临城却影散，带晕重围结。
驻跸俯九都，停观妖氛灭。','',''),('quantangshi-00023','春日登陕州城楼俯眺原野回丹碧缀烟霞密翠斑红芳菲花柳即目川岫聊以命篇','太宗皇帝','quantangshi','','卷1','碧原开雾隰，绮岭峻霞城。
烟峰高下翠，日浪浅深明。
斑红妆橤树，圆青压溜荆。
迹岩劳傅想，窥野访莘情。
巨川何以济，舟楫伫时英。','',''),('quantangshi-00024','春日玄武门宴羣臣','太宗皇帝','quantangshi','','卷1','韶光开令序，淑气动芳年。
驻辇华林侧，高宴柏梁前。
紫庭文佩满，丹墀衮绂连。
九夷簉瑶席，五狄列琼筵。
娱宾歌湛露，广乐奏钧天。
清尊浮绿醑，雅曲韵朱弦。
粤余君万国，还慙抚八埏。
庶几保贞固，虚己厉求贤。','',''),('quantangshi-00025','登三台言志','太宗皇帝','quantangshi','','卷1','未央初壮汉，阿房昔侈秦。
在危犹骋丽，居奢遂役人。
岂如家四海，日宇罄朝伦。
扇天裁户旧，砌地翦基新。
引月擎宵桂，飘云逼曙鳞。
露除光炫玉，霜阙映雕银。
舞接花梁燕，歌迎鸟路尘。
镜池波太液，庄苑丽宜春。
作异甘泉日，停非路寝辰。
念劳慙逸己，居旷返劳神。
所欣成大厦，宏材伫渭滨。','',''),('quantangshi-00026','出猎','太宗皇帝','quantangshi','','卷1','楚王云梦泽，汉帝长杨宫。
岂若因农暇，阅武出轘嵩。
三驱陈锐卒，七萃列材雄。
寒野霜氛白，平原烧火红。
雕戈夏服箭，羽骑绿沈弓。
怖兽潜幽壑，惊禽散翠空。
长烟晦落景，灌木振严风。
所为除民瘼，非是悦林丛。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00027','冬狩','太宗皇帝','quantangshi','','卷1','烈烈寒风起，惨惨飞云浮。
霜浓凝广隰，冰厚结清流。
金鞍移上苑，玉勒骋平畴。
旌旗四望合，罝罗一面求。
楚踣争兕殪，秦亡角鹿愁。
兽忙投密树，鸿惊起砾洲。
骑敛原尘静，戈回岭日收。
心非洛汭逸，意在渭滨游。
禽荒非所乐，抚辔更招忧。','',''),('quantangshi-00028','春日望海','太宗皇帝','quantangshi','','卷1','披襟眺沧海，凭轼翫春芳。
积流横地纪，疎派引天潢。
仙气凝三岭，和风扇八荒。
拂潮云布色，穿浪日舒光。
照岸花分彩，迷云雁断行。
怀卑运深广，持满守灵长。
有形非易测，无源讵可量。
洪涛经变野，翠岛屡成桑。
之罘思汉帝，碣石想秦皇。
霓裳非本意，端拱且图王。','',''),('quantangshi-00029','临洛水','太宗皇帝','quantangshi','','卷1','春搜驰骏骨，总辔俯长河。
霞处流萦锦，风前漾卷罗。
水花翻照树，堤兰倒插波。
岂必汾阴曲，秋云发棹歌。','',''),('quantangshi-00030','望终南山','太宗皇帝','quantangshi','','卷1','重峦俯渭水，碧嶂插遥天。
出红扶岭日，入翠贮岩烟。
叠松朝若夜，复岫阙疑全。
对此恬千虑，无劳访九仙。','',''),('quantangshi-00031','元日','太宗皇帝','quantangshi','','卷1','高轩暧春色，邃阁媚朝光。
彤庭飞彩斾，翠幌曜明璫。
恭己临四极，垂衣驭八荒。
霜戟列丹陛，丝竹韵长廊。
穆矣熏风茂，康哉帝道昌。
继文遵后轨，循古鉴前王。
草秀故春色，梅艳昔年妆。
巨川思欲济，终以寄舟航。','',''),('quantangshi-00032','初春登楼即目观作述怀','太宗皇帝','quantangshi','','卷1','凭轩俯兰阁，眺瞩散灵襟。
绮峰含翠雾，照日蕊红林。
镂丹霞锦岫，残素雪斑岑。
拂浪堤垂柳，娇花鸟续吟。
连甍岂一拱，众干如千寻。
明非独材力，终藉栋梁深。
弥怀矜乐志，更惧戒盈心。
愧制劳居逸，方规十产金。','',''),('quantangshi-00033','首春','太宗皇帝','quantangshi','','卷1','寒随穷律变，春逐鸟声开。
初风飘带柳，晚雪间花梅。
碧林青旧竹，绿沼翠新苔。
芝田初雁去，绮树巧鸎来。','',''),('quantangshi-00034','初晴落景','太宗皇帝','quantangshi','','卷1','晚霞聊自怡，初晴弥可喜。
日晃百花色，风动千林翠。
池鱼跃不同，园鸟声还异。
寄言博通者，知予物外志。','',''),('quantangshi-00035','初夏','太宗皇帝','quantangshi','','卷1','一朝春夏改，隔夜鸟花迁。
阴阳深浅叶，晓夕重轻烟。
哢鸎犹响殿，横丝正网天。
佩高兰影接，绶细草纹连。
碧鳞惊棹侧，玄燕舞檐前。
何必汾阳处，始复有山泉。','',''),('quantangshi-00036','度秋','太宗皇帝','quantangshi','','卷1','夏律昨留灰，秋箭今移晷。
峨嵋岫初出，洞庭波渐起。
桂白发幽岩，菊黄开灞涘。
运流方可叹，含毫属微理。','',''),('quantangshi-00037','仪鸾殿早秋','太宗皇帝','quantangshi','','卷1','寒惊蓟门叶，秋发小山枝。
松阴背日转，竹影避风移。
提壶菊花岸，高兴芙蓉池。
欲知凉气早，巢空燕不窥。','',''),('quantangshi-00038','秋日即目','太宗皇帝','quantangshi','','卷1','爽气浮丹阙，秋光澹紫宫。
衣碎荷疎影，花明菊点丛。
袍轻低草露，盖侧舞松风。
散岫飘云叶，迷路飞烟鸿。
砌冷兰凋佩，闺寒树陨桐。
别鹤栖琴里，离猿啼峡中。
落野飞星箭，弦虚半月弓。
芳菲夕雾起，暮色满房栊。','',''),('quantangshi-00039','山阁晚秋','太宗皇帝','quantangshi','','卷1','山亭秋色满，岩牖凉风度。
疎兰尚染烟，残菊犹承露。
古石衣新苔，新巢封古树。
历览情无极，咫尺输光暮。','',''),('quantangshi-00040','秋暮言志','太宗皇帝','quantangshi','','卷1','朝光浮烧野，霜华净碧空。
结浪冰初镜，在迳菊方丛。
约岭烟深翠，分旗霞散红。
抽思滋泉侧，飞想傅岩中。','',''),('quantangshi-00041','喜雪','太宗皇帝','quantangshi','','卷1','碧昏朝合雾，丹卷暝韬霞。
结叶繁云色，凝璚徧雪华。
光楼皎若粉，映幕集疑沙。
泛柳飞飞絮，妆梅片片花。
照璧台圆月，飘珠箔穿露。
瑶洁短长阶，玉藂高下树。
映桐圭累白，萦峰莲抱素。
断续气将沈，徘徊岁云暮。
怀珍愧隐德，表瑞伫丰年。
橤间飞禁苑，鹤处舞伊川。
傥咏幽兰曲，同懽黄竹篇。','',''),('quantangshi-00042','秋日斅庾信体','太宗皇帝','quantangshi','','卷1','岭衔宵月桂，珠穿晓露丛。
蝉啼觉树冷，萤火不温风。
花生圆菊橤，荷尽戏鱼通。
晨浦鸣飞雁，夕渚集栖鸿。
飒飒高天吹，氛澄下炽空。','',''),('quantangshi-00043','赋尚书','太宗皇帝','quantangshi','','卷1','崇文时驻步，东观还停辇。
辍膳翫三坟，晖灯披五典。
寒心覩肉林，飞魄看沈湎。
纵情昏主多，克己明君鲜。
灭身资累恶，成名由积善。
既承百王末，战兢随岁转。','',''),('quantangshi-00044','咏司马彪续汉志','太宗皇帝','quantangshi','','卷1','二仪初创象，三才乃分位。
非惟树司牧，固亦垂文字。
緜代更膺期，芳图无辍记。
炎汉承君道，英谟纂神器。
潜龙既可跃，逵兔奚难致。
前史殚妙词，后昆沈雅思。
书言扬盛迹，补阙兴洪志。
川谷犹旧途，郡国开新意。
梅山未觉朽，谷水谁云异。
车服随名表，文物因时置。
凤戟翼康衢，銮舆总柔辔。
清浊必能澄，洪纤幸无弃。
观仪不失序，遵礼方由事。
政宣竹律和，时平玉条备。
文囿雕奇彩，艺门蕴深致。
云飞星共流，风扬月兼至。
类禋遵令典，坛壝资良地。
五胜竟无违，百司诚有庇。
粤予承暇景，谈丛引泉祕。
讨论穷义府，看核披经笥。
大辨良难仰，小学终先匮。
闻道谅知荣，含毫孰忘愧。','',''),('quantangshi-00045','咏风','太宗皇帝','quantangshi','','卷1','萧条起关塞，摇扬下蓬瀛。
拂林花乱彩，响谷鸟分声。
披云罗影散，泛水织文生。
劳歌大风曲，威加四海清。','',''),('quantangshi-00046','咏雨','太宗皇帝','quantangshi','','卷1','罩云飘远岫，喷雨泛长河。
低飞昏岭腹，斜足洒岩阿。
泫丛珠缔叶，起溜镜图波。
蒙柳添丝密，含吹织空罗。','',''),('quantangshi-00047','咏雪','太宗皇帝','quantangshi','','卷1','洁野凝晨曜，装墀带夕晖。
集条分树玉，拂浪影泉玑。
色洒妆台粉，花飘绮席衣。
入扇萦离匣，点素皎残机。','',''),('quantangshi-00048','赋得夏首启节','太宗皇帝','quantangshi','','卷1','北阙三春晚，南荣九夏初。
黄莺弄渐变，翠林花落余。
瀑流还响谷，猿啼自应虚。
早荷向心卷，长杨就影舒。
此时欢不极，调轸坐相于。','',''),('quantangshi-00049','赋得白日半西山','太宗皇帝','quantangshi','','卷1','红轮不暂驻，乌飞岂复停。
岑霞渐渐落，溪阴寸寸生。
藿叶随光转，葵心逐照倾。
晚烟含树色，栖鸟杂流声。','',''),('quantangshi-00050','置酒坐飞阁','太宗皇帝','quantangshi','','卷1','高轩临碧渚，飞檐迥架空。
余花攒镂槛，残柳散雕栊。
岸菊初含橤，园梨始带红。
莫虑昆山暗，还共尽杯中。','',''),('quantangshi-00051','采芙蓉','太宗皇帝','quantangshi','','卷1','结伴戏方塘，携手上雕航。
船移分细浪，风散动浮香。
游鸎无定曲，惊凫有乱行。
莲稀钏声断，水广棹歌长。
栖乌还密树，泛流归建章。','',''),('quantangshi-00052','赋得樱桃','太宗皇帝','quantangshi','','卷1','华林满芳景，洛阳徧阳春。
朱颜含远日，翠色影长津。
乔柯啭娇鸟，低枝映美人。
昔作园中实，今来席上珍。','',''),('quantangshi-00053','赋得李','太宗皇帝','quantangshi','','卷1','玉衡流桂圃，成蹊正可寻。
鸎啼密叶外，蝶戏脆花心。
丽景光朝彩，轻霞散夕阴。
暂顾晖章侧，还眺灵山林。','',''),('quantangshi-00054','赋得浮桥','太宗皇帝','quantangshi','','卷1','岸曲非千里，桥斜异七星。
暂低逢辇度，还高值浪惊。
水摇文鷁动，缆转锦花萦。
远近随轮影，轻重应人行。','',''),('quantangshi-00055','谒并州大兴国寺诗','太宗皇帝','quantangshi','','卷1','回銮游福地，极目玩芳晨。
梵钟交二响，法日转双轮。
宝刹遥承露，天花近足春。
未佩兰犹小，无丝柳尚新。
圆光低月殿，碎影乱风筠。
对此留余想，超然离俗尘。','',''),('quantangshi-00056','咏兴国寺佛殿前幡','太宗皇帝','quantangshi','','卷1','拂霞疑电落，腾虚状写虹。
屈伸烟雾里，低举白云中。
纷披乍依迥，掣曳或随风。
念兹轻薄质，无翅强摇空。','',''),('quantangshi-00057','望送魏征葬','太宗皇帝','quantangshi','','卷1','阊阖总金鞍，上林移玉辇。
野郊怆新别，河桥非旧饯。
惨日映峰沈，愁云随盖转。
哀笳时断续，悲旌乍舒卷。
望望情何极，浪浪泪空泫。
无复昔时人，芳春共谁遣。','',''),('quantangshi-00058','伤辽东战亡','太宗皇帝','quantangshi','','卷1','凿门初奉律，仗战始临戎。
振鳞方跃浪，骋翼正凌风。
未展六奇术，先亏一篑功。
防身岂乏智，殉命有余忠。','',''),('quantangshi-00059','月晦','太宗皇帝','quantangshi','','卷1','晦魄移中律，凝暄起丽城。
罩云朝盖上，穿露晓珠呈。
笑树花分色，啼枝鸟合声。
披襟欢眺望，极目畅春情。','',''),('quantangshi-00060','秋日翠微宫','太宗皇帝','quantangshi','','卷1','秋光凝翠岭，凉吹肃离宫。
荷疎一盖缺，树冷半帷空。
侧阵移鸿影，圆花钉菊丛。
摅怀俗尘外，高眺白云中。','',''),('quantangshi-00061','初秋夜坐','太宗皇帝','quantangshi','','卷1','斜廊连绮阁，初月照宵帏。
塞冷鸿飞疾，园秋蝉噪迟。
露结林疎叶，寒轻菊吐滋。
愁心逢此节，长叹独含悲。','',''),('quantangshi-00062','秋日二首 一','太宗皇帝','quantangshi','','卷1','菊散金风起，荷疎玉露圆。
将秋数行雁，离夏几林蝉。
云凝愁半岭，霞碎缬高天。
还似成都望，直见峨眉前。','',''),('quantangshi-00063','秋日二首 二','太宗皇帝','quantangshi','','卷1','爽气澄兰沼，秋风动桂林。
露凝千片玉，菊散一丛金。
日岫高低影，云空点缀阴。
蓬瀛不可望，泉石且娱心。','',''),('quantangshi-00064','冬宵各为四韵','太宗皇帝','quantangshi','','卷1','雕宫静龙漏，绮阁宴公侯。
珠帘烛焰动，绣柱月光浮。
云起将歌发，风停与管遒。','',''),('quantangshi-00065','冬日临昆明池','太宗皇帝','quantangshi','','卷1','石鲸分玉溜，劫烬隐平沙。
柳影冰无叶，梅心冻有花。
寒野凝朝雾，霜天散夕霞。
欢情犹未极，落景遽西斜。','',''),('quantangshi-00066','望雪','太宗皇帝','quantangshi','','卷1','冻云宵徧岭，素雪晓凝华。
入牖千重碎，迎风一半斜。
不妆空散粉，无树独飘花。
萦空慙夕照，破彩谢晨霞。','',''),('quantangshi-00067','守岁','太宗皇帝','quantangshi','','卷1','暮景斜芳殿，年华丽绮宫。
寒辞去冬雪，暖带入春风。
阶馥舒梅素，盘花卷烛红。
共欢新故岁，迎送一宵中。','',''),('quantangshi-00068','除夜','太宗皇帝','quantangshi','','卷1','岁阴穷暮纪，献节启新芳。
冬尽今宵促，年开明日长。
冰消出镜水，梅散入风香。
对此欢终宴，倾壶待曙光。','',''),('quantangshi-00069','咏雨','太宗皇帝','quantangshi','','卷1','和气吹绿野，梅雨洒芳田。
新流添旧涧，宿雾足朝烟。
雁湿行无次，花霑色更鲜。
对此欣登岁，披襟弄五弦。','',''),('quantangshi-00070','赋得含峰云','太宗皇帝','quantangshi','','卷1','翠楼含晓雾，莲峰带晚云。
玉叶依岩聚，金枝触石分。
横天结阵影，逐吹起罗文。
非复阳台下，空将惑楚君。','',''),('quantangshi-00071','三层阁上置音声','太宗皇帝','quantangshi','','卷1','绮筵移暮景，紫阁引宵烟。
隔栋歌尘合，分阶舞影连。
声流三处管，响乱一重弦。
不似秦楼上，吹箫空学仙。','',''),('quantangshi-00072','远山澄碧雾','太宗皇帝','quantangshi','','卷1','残云收翠岭，夕雾结长空。
带岫凝全碧，障霞隐半红。
仿髴分初月，飘颻度晓风。
还因三里处，冠盖远相通。','',''),('quantangshi-00073','赋得花庭雾','太宗皇帝','quantangshi','','卷1','兰气已熏宫，新橤半妆丛。
色含轻重雾，香引去来风。
拂树浓舒碧，萦花薄蔽红。
还当杂行雨，仿髴隐遥空。','',''),('quantangshi-00074','春池柳','太宗皇帝','quantangshi','','卷1','年柳变池台，隋堤曲直回。
逐浪丝阴去，迎风带影来。
疎黄一鸟弄，半翠几眉开。
萦雪临春岸，参差间早梅。','',''),('quantangshi-00075','芳兰','太宗皇帝','quantangshi','','卷1','春晖开紫苑，淑景媚兰场。
映庭含浅色，凝露泫浮光。
日丽参差影，风传轻重香。
会须君子折，佩里作芬芳。','',''),('quantangshi-00076','咏桃','太宗皇帝','quantangshi','','卷1','禁苑春晖丽，花蹊绮树妆。
缀条深浅色，点露参差光。
向日分千笑，迎风共一香。
如何仙岭侧，独秀隐遥芳。','',''),('quantangshi-00077','赋帘','太宗皇帝','quantangshi','','卷1','参差垂玉阙，舒卷映兰宫。
珠光摇素月，竹影乱清风。
彩散银钩上，文斜桂户中。
惟当杂罗绮，相与媚房栊。','',''),('quantangshi-00078','咏乌代陈师道','太宗皇帝','quantangshi','','卷1','凌晨丽城去，薄暮上林栖。
辞枝枝暂起，停树树还低。
向日终难托，迎风讵肯迷。
只待纤纤手，曲里作宵啼。','',''),('quantangshi-00079','咏饮马','太宗皇帝','quantangshi','','卷1','骏骨饮长泾，奔流洒络缨。
细纹连喷聚，乱荇绕蹄萦。
水光鞍上侧，马影溜中横。
翻似天池里，腾波龙种生。','',''),('quantangshi-00080','赋得残菊','太宗皇帝','quantangshi','','卷1','阶兰凝曙霜，岸菊照晨光。
露浓曦晚笑，风劲浅残香。
细叶凋轻翠，圆花飞碎黄。
还持今岁色，复结后年芳。','',''),('quantangshi-00081','赋秋日悬清光赐房玄龄','太宗皇帝','quantangshi','','卷1','秋露凝高掌，朝光上翠微。
参差丽双阙，照耀满重闱。
仙驭随轮转，灵乌带影飞。
临波无定彩，入隙有圆晖。
还当葵藿志，倾叶自相依。','',''),('quantangshi-00082','琵琶','太宗皇帝','quantangshi','','卷1','半月无双影，全花有四时。
摧藏千里态，掩抑几重悲。
促节萦红袖，清音满翠帷。
驶弹风响急，缓曲钏声迟。
空余关陇恨，因此代相思。','',''),('quantangshi-00083','宴中山','太宗皇帝','quantangshi','','卷1','驱马出辽阳，万里转旗常。
对敌六奇举，临戎八阵张。
斩鲸澄碧海，卷雾扫扶桑。
昔去兰萦翠，今来桂染芳。
云芝浮碎叶，冰镜上朝光。
回首长安道，方欢宴柏梁。','',''),('quantangshi-00084','饯中书侍郎来济','太宗皇帝','quantangshi','','卷1','暧暧去尘昏灞岸，飞飞轻盖指河梁。
云峰衣结千重叶，雪岫花开几树妆。
深悲黄鹤孤舟远，独叹青山别路长。
聊将分袂霑巾泪，还用持添离席觞。','',''),('quantangshi-00085','于太原召侍臣赐宴守岁','太宗皇帝','quantangshi','','卷1','四时运灰琯，一夕变冬春。
送寒余雪尽，迎岁早梅新。','',''),('quantangshi-00086','咏烛二首 一','太宗皇帝','quantangshi','','卷1','焰听风来动，花开不待春。
镇下千行泪，非是为思人。','',''),('quantangshi-00087','咏烛二首 二','太宗皇帝','quantangshi','','卷1','九龙蟠焰动，四照逐花生。
即此流高殿，堪持待月明。','',''),('quantangshi-00088','咏弓','太宗皇帝','quantangshi','','卷1','上弦明月半，激箭流星远。
落雁带书惊，啼猿映枝转。','',''),('quantangshi-00089','赋得早雁出云鸣','太宗皇帝','quantangshi','','卷1','初秋玉露清，早雁出空鸣。
隔云时乱影，因风乍含声。','',''),('quantangshi-00090','赋得临池柳','太宗皇帝','quantangshi','','卷1','岸曲丝阴聚，波移带影疎。
还将眉里翠，来就镜中舒。','',''),('quantangshi-00091','赋得临池竹','太宗皇帝','quantangshi','','卷1','贞条障曲砌，翠叶贯寒霜。
拂牖分龙影，临池待凤翔。','',''),('quantangshi-00092','赋得弱柳鸣秋蝉','太宗皇帝','quantangshi','','卷1','散影玉阶柳，含翠隐鸣蝉。
微形藏叶里，乱响出风前。','',''),('quantangshi-00093','探得李','太宗皇帝','quantangshi','','卷1','盘根直盈渚，交干横倚天。
舒华光四海，卷叶荫三川。','',''),('quantangshi-00094','咏小山','太宗皇帝','quantangshi','','卷1','近谷交萦橤，遥峰对出莲。
径细无全磴，松小未含烟。','',''),('quantangshi-00095','赐萧瑀','太宗皇帝','quantangshi','','卷1','疾风知劲草，板荡识诚臣。
勇夫安识义，智者必怀仁。','',''),('quantangshi-00096','赐房玄龄','太宗皇帝','quantangshi','','卷1','太液仙舟迥，西园隐上才。
未晓征车度，鸡鸣关早开。','',''),('quantangshi-00097','辽东山夜临秋','太宗皇帝','quantangshi','','卷1','烟生遥岸隐，月落半崖阴。
连山惊鸟乱，隔岫断猿吟。','',''),('quantangshi-00098','赐魏征诗','太宗皇帝','quantangshi','','卷1','醽醁胜兰生，翠涛过玉䪥。
千日醉不醒，十年味不败。','',''),('quantangshi-00099','两仪殿赋柏梁体','太宗皇帝','quantangshi','','卷1','绝域降附天下平，八表无事悦圣情。
云披雾敛天地明，登封日观禅云亭。
太常具礼方告成。','',''),('quantangshi-00100','句','太宗皇帝','quantangshi','','卷1','雪耻酬百王，除凶报千古。
昔乘匹马去，今驱万乘来。
近日毛虽暖闻弦心已惊。','',''),('quantangshi-00101','太子纳妃太平公主出降','高宗皇帝','quantangshi','','卷1','龙楼光曙景，鲁馆启朝扉。
艳日浓妆影，低星降婺辉。
玉庭浮瑞色，银牓藻祥徽。
云转花萦盖，霞飘叶缀旗。
雕轩回翠陌，宝驾归丹殿。
鸣珠佩晓衣，镂璧轮开扇。
华冠列绮筵，兰醑申芳宴。
环阶凤乐陈，玳席珍羞荐。
蝶舞袖香新，歌分落素尘。
欢凝欢懿戚，庆叶庆初姻。
暑阑炎气息，凉早吹疎频。
方期六合泰，共赏万年春。','',''),('quantangshi-00102','七夕宴悬圃二首 一','高宗皇帝','quantangshi','','卷1','羽盖飞天汉，凤驾越层峦。
俱叹三秋阻，共敍一宵欢。
璜亏夜月落，靥碎晓星残。
谁能重操杼，纤手濯清澜。','',''),('quantangshi-00103','七夕宴悬圃二首 二','高宗皇帝','quantangshi','','卷1','霓裳转云路，凤驾俨天潢。
亏星凋夜靥，残月落朝璜。
促欢今夕促，长离别后长。
轻梭聊驻织，掩泪独悲伤。','',''),('quantangshi-00104','过温汤','高宗皇帝','quantangshi','','卷1','温渚停仙跸，丰郊驻晓旌。
路曲回输影，岩虚传漏声。
暖溜惊湍驶，寒空碧雾轻。
林黄疎叶下，野白曙霜明。
眺听良无已，烟霞断续生。','',''),('quantangshi-00105','九月九日','高宗皇帝','quantangshi','','卷1','端居临玉扆，初律启金商。
凤阙澄秋色，龙闱引夕凉。
野净山气敛，林疎风露长。
砌兰亏半影，岩桂发全香。
满盖荷凋翠，圆花菊散黄。
挥鞭争电烈，飞羽乱星光。
柳空穿石碎，弦虚侧月张。
怯猿啼落岫，惊雁断分行。
斜轮低夕景，归斾拥通庄。','',''),('quantangshi-00106','谒慈恩寺题奘法师房','高宗皇帝','quantangshi','','卷1','停轩观福殿，游目眺皇畿。
法轮含日转，花盖接云飞。
翠烟香绮阁，丹霞光宝衣。
幡虹遥合彩，定水迥分晖。
萧然登十地，自得会三归。','',''),('quantangshi-00107','谒大慈恩寺','高宗皇帝','quantangshi','','卷1','日宫开万仞，月殿耸千寻。
花盖飞团影，幡虹曳曲阴。
绮霞遥笼帐，丛珠细网林。
寥廓烟云表，超然物外心。','',''),('quantangshi-00108','守岁','高宗皇帝','quantangshi','','卷1','今宵冬律尽，来朝丽景新。
花余凝地雪，条含暖吹分。
绶吐芽犹嫩，冰□已镂津。
薄红梅色冷，浅绿柳轻春。
送迎交两节，暄寒变一辰。','',''),('quantangshi-00109','咸亨殿宴近臣诸亲柏梁体','高宗皇帝','quantangshi','','卷1','屏欲除奢政返淳。','',''),('quantangshi-00110','九月九日幸临渭亭登高得秋字','中宗皇帝','quantangshi','','卷1','九月正乘秋，三杯兴已周。
泛桂迎尊满，吹花向酒浮。
长房萸早熟，彭泽菊初收。','',''),('quantangshi-00111','登骊山高顶寓目','中宗皇帝','quantangshi','','卷1','四郊秦汉国，八水帝王都。
阊阖雄里閈，城阙壮规模。
贯渭称天邑，含岐实奥区。
金门披玉馆，因此识皇图。','',''),('quantangshi-00112','幸秦始皇陵','中宗皇帝','quantangshi','','卷1','眷言君失德，骊邑想秦余。
政烦方改篆，愚俗乃焚书。
阿房久已灭，阁道遂成墟。
欲厌东南气，翻伤掩鲍车。','',''),('quantangshi-00113','立春日游苑迎春','中宗皇帝','quantangshi','','卷1','神皐福地三秦邑，玉台金阙九仙家。
寒光犹恋甘泉树，淑景偏临建始花。
彩蝶黄鸎未歌舞，梅香柳色已矜夸。
迎春正启流霞席，暂嘱曦轮勿遽斜。','',''),('quantangshi-00114','十月诞辰内殿宴羣臣效柏梁体联句','中宗皇帝','quantangshi','','卷1','润色鸿业寄贤才，叨居右弼愧盐梅。
运筹帷幄荷时来，职掌图籍滥蓬莱。
两司谬忝谢钟裴，礼乐铨管效涓埃。
陈师振旅清九垓，欣承顾问侍天杯。
衔恩献寿梁柏台，黄缣青简奉康哉。
鲰生侍从忝王枚，右掖司言实不才。
宗伯秩礼天地开，帝歌难续仰昭回。
微臣捧日变寒灰，远慙班左愧游陪。','',''),('quantangshi-00115','景龙四年正月五日移仗蓬莱宫御大明殿会吐蕃骑马之戏因重为柏梁体联句','中宗皇帝','quantangshi','','卷1','大明御宇临万方，顾慙内政翊陶唐。
鸾鸣凤舞向平阳，秦楼鲁馆沐恩光。
无心为子辄求郎，雄才七步谢陈王。
当熊让辇愧前芳，再司铨筦恩可忘。
文江学海思济航，万邦考绩臣所详。
着作不休出中肠，权豪屏迹肃严霜。
铸鼎开岳造明堂，玉醴由来献寿觞。','',''),('quantangshi-00116','石淙','中宗皇帝','quantangshi','','卷1','三阳本是标灵纪，二室由来独擅名。
霞衣霞锦千般状，云峰云岫百重生。
水炫珠光遇泉客，岩悬石镜厌山精。
永愿干坤符睿算，长居膝下属欢情。','',''),('quantangshi-00117','石淙','睿宗皇帝','quantangshi','','卷1','奇峰嶾嶙箕山北，秀崿岹峣嵩镇南。
地首地肺何曾拟，天目天台倍觉慙。
树影蒙茏鄣叠岫，波深汹涌落悬潭。
□愿紫宸居得一，永欣丹扆御通三。','',''),('quantangshi-00118','过晋阳宫','皇帝','quantangshi','','卷1','缅想封唐处，实惟建国初。
俯察伊晋野，仰观乃参虚。
井邑龙斯跃，城池凤翔余。
林塘犹沛泽，台榭宛旧居。
运革祚中否，时迁命兹符。
顾循承丕构，怵惕多忧虞。
尚恐威不逮，复虑化未孚。
岂徒劳辙迹，所期训戎车。
习俗问黎人，亲巡慰里闾。
永言念成功，颂德临康衢。
长怀经纶日，叹息履庭隅。
艰难安可忘，欲去良踟蹰。','',''),('quantangshi-00119','行次成皋途经先圣擒建德之所缅思功业感而赋诗','皇帝','quantangshi','','卷1','有隋政昏虐，羣雄已交争。
先圣按劒起，叱咤风云生。
饮马河洛竭，作气嵩华惊。
克敌睿图就，擒俘帝道亨。
顾慙嗣宝历，恭承天下平。
幸过翦鲸地，感慕神且英。','',''),('quantangshi-00120','校猎义成喜逢大雪率题九韵以示羣官','皇帝','quantangshi','','卷1','弧矢威天下，旌旗游近县。
一面施鸟罗，三驱教人战。
暮云成积雪，晓色开行殿。
皓然原隰同，不觉林野变。
北风勇士马，东日华组练。
触地银麞出，连山缟鹿见。
月兔落高矰，星狼下急箭。
既欣盈尺兆，复忆磻溪便。
岁丰将遇贤，俱荷皇天眷。','',''),('quantangshi-00121','赐诸州刺史以题座右','皇帝','quantangshi','','卷1','眷言思共理，鉴梦想维良。
猗欤此推择，声绩着周行。
贤能既俟进，黎献实伫康。
视人当如子，爱人亦如伤。
讲学试诵论，阡陌劝耕桑。
虚誉不可饰，清知不可忘。
求名迹易见，安贞德自彰。
讼狱必以情，教民贵有常。
恤惸且存老，抚弱复绥强。
勉哉各祗命，知予眷万方。','',''),('quantangshi-00122','送忠州太守康昭远等','皇帝','quantangshi','','卷1','端拱临中枢，缅怀共予理。
不有台阁英，孰振循良美。
分符侯甸内，拜手明庭里。
誓节期饮冰，调人方导水。
嘉声驰九牧，惠化光千祀。
时雨侔昔贤，芳猷贯前史。
伫尔颂中和，吾将令卿士。','',''),('quantangshi-00123','送李邕之任滑台','皇帝','quantangshi','','卷1','汉家重东郡，宛彼白马津。
黎庶既蕃殖，临之劳近臣。
远别初首路，今行方及春。
课成应第一，良牧尔当仁。','',''),('quantangshi-00124','端午三殿宴羣臣探得神字','皇帝','quantangshi','','卷1','五月符天数，五音调夏钧。
旧来传五日，无事不称神。
穴枕通灵气，长丝续命人。
四时花竞巧，九子糉争新。
方殿临华节，圆宫宴雅臣。
进对一言重，遒文六义陈。
股肱良足咏，风化可还淳。','',''),('quantangshi-00125','温汤对雪','皇帝','quantangshi','','卷1','北风吹同云，同云飞白雪。
白雪乍回散，同云何惨烈。
未见温泉冰，宁知火井灭。
表瑞良在兹，庶几可怡悦。','',''),('quantangshi-00126','登蒲州逍遥楼','皇帝','quantangshi','','卷1','长榆息烽火，高柳静风尘。
卜征巡九洛，展豫出三秦。
昔是潜龙地，今为上理辰。
时平乘道泰，聊赏遇年春。
黄河分地络，飞观接天津。
一览遗芳翰，千载肃如神。','',''),('quantangshi-00127','经河上公庙','皇帝','quantangshi','','卷1','昔闻有耆叟，河上独遗荣。
迹与尘嚻隔，心将道德并。
讵以天地累，宁为宠辱惊。
矫然翔寥廓，如何屈坚贞。
玄玄妙门启，肃肃祠宇清。
冥漠无先后，那能纪姓名。','',''),('quantangshi-00128','过王浚暮','皇帝','quantangshi','','卷1','吴国分牛斗，晋室命龙骧。
受任敌已灭，策勋名不彰。
居美未尽善，矜功徒自伤。
长戟今何在？孤坟此路傍。
不观松柏茂，空余荆棘场。
叹嗟悬劒陇，谁识梦刀祥。','',''),('quantangshi-00129','初入秦川路逢寒食','皇帝','quantangshi','','卷1','洛阳芳树映天津，灞岸垂杨窣地新。
直为经过行处乐，不知虚度两京春。
去年余闰今春早，曙色和风着花草。
可怜寒食与清明，光辉并在长安道。
自从关路入秦川，争道何人不戏鞭。
公子途中妨蹴踘，佳人马上废秋千。
渭水长桥今欲渡，葱葱渐见新丰树。
远看骊岫入云霄，预想汤池起烟雾。
烟雾氛氲水殿开，暂拂香轮归去来。
今岁清明行已晚，明年寒食更相陪。','',''),('quantangshi-00130','春台望','皇帝','quantangshi','','卷1','暇景属三春，高台聊四望。
目极千里际，山川一何壮。
太华见重岩，终南分叠嶂。
郊原纷绮错，参差多异状。
佳气满通沟，迟步入绮楼。
初鸎一一鸣红树，归雁双双去绿洲。
太液池中下黄鹤，昆明水上映牵牛。
闻道汉家全盛日，别馆离宫趣非一。
甘泉逶迤亘明光，五柞连延接未央。
周庐徼道纵横转，飞阁回轩左右长。
须念作劳居者逸，勿言我后焉能恤。
为想雄豪壮柏梁，何如俭陋卑茅室。
阳乌黯黯向山沈，夕鸟喧喧入上林。
薄暮赏余回步辇，还念中人罢百金。','',''),('quantangshi-00131','过大哥宅探得歌字韵','皇帝','quantangshi','','卷1','鲁卫情先重，亲贤爱转多。
冕旒丰暇日，乘景暂经过。
戚里申高宴，平台奏雅歌。
复寻为善乐，方验保山河。','',''),('quantangshi-00132','同玉真公主过大哥山池','皇帝','quantangshi','','卷1','地有招贤处，人传乐善名。
鹜池临九达，龙岫对层城。
桂月先秋冷，苹风向晚清。
凤楼遥可见，彷佛玉箫声。','',''),('quantangshi-00133','经邹鲁祭孔子而叹之','皇帝','quantangshi','','卷1','夫子何为者？栖栖一代中。
地犹鄹氏邑，宅即鲁王宫。
叹凤嗟身否，伤麟怨道穷。
今看两楹奠，当与梦时同。','',''),('quantangshi-00134','惟此温泉是称愈疾岂予独受其福思与兆人共之乘暇巡游乃言其志','皇帝','quantangshi','','卷1','桂殿与山连，兰汤涌自然。
阴崖含秀色，温谷吐潺湲。
绩为蠲邪着，功因养正宣。
愿言将亿兆，同此共昌延。','',''),('quantangshi-00135','旋师喜捷','皇帝','quantangshi','','卷1','边服胡尘起，长安汉将飞。
龙蛇开阵法，貔虎振军威。
诈虏脑涂地，征夫血染衣。
今朝书奏入，明日凯歌归。','',''),('quantangshi-00136','过老子庙','皇帝','quantangshi','','卷1','仙居怀圣德，灵庙肃神心。
草合人踪断，尘浓鸟迹深。
流沙丹竈没，关路紫烟沈。
独伤千载后，空余松柏林。','',''),('quantangshi-00137','途次陕州','皇帝','quantangshi','','卷1','境出三秦外，途分二陕中。
山川入虞虢，风俗限西东。
树古棠阴在，耕余让畔空。
鸣笳从此去，行见洛阳宫。','',''),('quantangshi-00138','野次喜雪','皇帝','quantangshi','','卷1','拂曙辟行宫，寒皋野望通。
繁云低远岫，飞雪舞长空。
赋象恒依物，萦回屡逐风。
为知勤恤意，先此示年丰。','',''),('quantangshi-00139','送贺知章归四明','皇帝','quantangshi','','卷1','遗荣期入道，辞老竟抽簪。
岂不惜贤达，其如高尚心。
寰中得祕要，方外散幽襟。
独有青门饯，羣僚怅别深。','',''),('quantangshi-00140','轩游宫十五夜','皇帝','quantangshi','','卷1','行迈离秦国，巡方赴洛师。
路逢三五夜，春色暗中期。
关外长河转，宫中淑气迟。
歌钟对明月，不减旧游时。','',''),('quantangshi-00141','观拔河俗戏','皇帝','quantangshi','','卷1','壮徒恒贾勇，拔拒抵长河。
欲练英雄志，须明胜负多。
噪齐山岌嶪，气作水腾波。
预期年岁稔，先此乐时和。','',''),('quantangshi-00142','同刘晃喜雨','皇帝','quantangshi','','卷1','节变寒初尽，时和气已春。
繁云先合寸，膏雨自依旬。
飒飒飞平野，霏霏静暗尘。
悬知花叶意，朝夕望中新。','',''),('quantangshi-00143','千秋节赐羣臣镜','皇帝','quantangshi','','卷1','铸得千秋镜，光生百炼金。
分将赐羣后，遇象见清心。
台上冰华澈，窗中月影临。
更衔长绶带，留意感人深。','',''),('quantangshi-00144','赐道士邓紫阳','皇帝','quantangshi','','卷1','太乙三门诀，元君六甲符。
下传金版术，上刻玉清书。
有美探真士，囊中得祕书。
自知三醮后，翊我灭残胡。','',''),('quantangshi-00145','幸蜀西至劒门','皇帝','quantangshi','','卷1','劒阁横云峻，銮舆出狩回。
翠屏千仞合，丹嶂五丁开。
灌木萦旗转，仙云拂马来。
乘时方在德，嗟尔勒铭才。','',''),('quantangshi-00146','答司马承祯上劒镜','皇帝','quantangshi','','卷1','宝照含天地，神劒合阴阳。
日月丽光景，星斗裁文章。
写鉴表容质，佩服为身防。
从兹一赏玩，永德保龄长。','',''),('quantangshi-00147','送赵法师还蜀因名山奠简','皇帝','quantangshi','','卷1','道家奠灵简，自昔仰神仙。
真子今将命，苍生福可传。
江山寻故国，城郭信依然。
二室遥相望，云回洞里天。','',''),('quantangshi-00148','送道士薛季昌还山','皇帝','quantangshi','','卷1','洞府修真客，衡阳念旧居。
将成金阙要，愿奉玉清书。
云路三天近，松溪万籁虚。
犹期传祕诀，来往候仙舆。','',''),('quantangshi-00149','送玄同真人李抱朴谒灊山仙祠','皇帝','quantangshi','','卷1','城阙天中近，蓬瀛海上遥。
归期千载鹤，春至一来朝。
采药逢三秀，餐霞卧九霄。
参同如有旨，金鼎待君烧。','',''),('quantangshi-00150','春日出苑游瞩','皇帝','quantangshi','','卷1','三阳丽景早芳辰，四序佳园物候新。
梅花百树障去路，垂柳千条暗回津。
鸟飞直为惊风叶，鱼没都由怯岸人。
惟愿圣主南山寿，何愁不赏万年春。','',''),('quantangshi-00151','春晚宴两相及礼官丽正殿学士探得风字','皇帝','quantangshi','','卷1','干道运无穷，恒将人代工。
阴阳调历象，礼乐报玄穹。
介胄清荒外，衣冠佐域中。
言谈延国辅，词赋引文雄。
野霁伊川绿，郊明巩树红。
冕旒多暇景，诗酒会春风。','',''),('quantangshi-00152','首夏花萼楼观羣臣宴宁王山亭回楼下又申之以赏乐赋诗','皇帝','quantangshi','','卷1','今年通闰月，入夏展春辉。
楼下风光晚，城隅宴赏归。
九歌扬政要，六舞散朝衣。
天喜时相合，人和事不违。
礼中推意厚，乐处感心微。
别赏阳台乐，前旬暮雨飞。','',''),('quantangshi-00153','同二相已下羣官乐游园宴','皇帝','quantangshi','','卷1','撰日岩廊暇，需云宴乐初。
万方朝玉帛，千品会簪裾。
地入南山近，城分北斗余。
池塘垂柳密，原隰野花疎。
帟幕看逾暗，歌钟听自虚。
兴阑归骑转，还奏弼违书。','',''),('quantangshi-00154','集贤书院成送张说上集贤学士赐宴得珍字','皇帝','quantangshi','','卷1','广学开书院，崇儒引席珍。
集贤招衮职，论道命台臣。
礼乐沿今古，文章革旧新。
献酬尊俎列，宾主位班陈。
节变云初夏，时移气尚春。
所希光史册，千载仰兹晨。','',''),('quantangshi-00155','王屋山送道士司马承祯还天台','皇帝','quantangshi','','卷1','紫府求贤士，清溪祖逸人。
江湖与城阙，异迹且殊伦。
间有幽栖者，居然厌俗尘。
林泉先得性，芝桂欲调神。
地道逾稽岭，天台接海滨。
音徽从此间，万古一芳春。','',''),('quantangshi-00156','早度蒲津关','皇帝','quantangshi','','卷1','钟鼓严更曙，山河野望通。
鸣銮下蒲坂，飞斾入秦中。
地险关逾壮，天平镇尚雄。
春来津树合，月落戍楼空。
马色分朝景，鸡声逐晓风。
所希常道泰，非复候繻同。','',''),('quantangshi-00157','途经华岳','皇帝','quantangshi','','卷1','饬驾去京邑，鸣鸾指洛川。
循途经太华，回跸暂周旋。
翠崿留斜影，悬岩冒夕烟。
四方皆石壁，五位配金天。
彷佛看高掌，依稀听子先。
终当铭岁月，从此记灵仙。','',''),('quantangshi-00158','喜雪','皇帝','quantangshi','','卷1','日观卜先征，时巡顺物情。
风行未备礼，云密遽飘霙。
委树寒花发，萦空落絮轻。
朝如玉已会，庭似月犹明。
既覩肤先合，还欣尺有盈。
登封何以报？因此谢功成。','',''),('quantangshi-00159','幸凤泉汤','皇帝','quantangshi','','卷1','西狩观周俗，南山历汉宫。
荐鲜知路近，省敛觉年丰。
阴谷含神爨，汤泉养圣功。
益龄仙井合，愈疾醴源通。
不重鸣岐凤，谁矜陈宝雄。
愿将无限泽，霑沐众心同。','',''),('quantangshi-00160','南出雀鼠谷答张说','皇帝','quantangshi','','卷1','雷出应干象，风行顺国人。
川途犹在晋，车马渐归秦。
背陕关山险，横汾鼓吹频。
草依阳谷变，花待北岩春。
闻有鵷鸾客，清词雅调新。
求音思欲报，心迹竟难陈。','',''),('quantangshi-00161','赐崔日知往潞州','皇帝','quantangshi','','卷1','潞国开新府，壶关宠旧林。
妙旌循吏德，持悦庶氓心。
礼乐中朝贵，神明列郡钦。
扬风非赠扇，易俗是张琴。
藩镇讴谣满，行宫雨露深。
会书丞相策，先赐颍川金。','',''),('quantangshi-00162','为赵法师别造精院过院赋诗','皇帝','quantangshi','','卷1','宗师心物外，为道运虚舟。
不恋岩泉赏，来从宫禁游。
探玄知几岁，习静更宜秋。
烟树辨朝色，风湍闻夜流。
坐朝繁听览，寻胜在清幽。
欲广无为化，因兹庶可求。','',''),('quantangshi-00163','端午','皇帝','quantangshi','','卷1','端午临中夏，时清日复长。
盐梅已佐鼎，麯糵且传觞。
事古人留迹，年深缕积长。
当轩知槿茂，向水觉芦香。
亿兆同归寿，羣公共保昌。
忠贞如不替，贻厥后昆芳。','',''),('quantangshi-00164','春中兴庆宫酺宴','皇帝','quantangshi','','卷1','九达长安道，三阳别馆春。
还将听朝暇，回作豫游晨。
不战要荒服，无刑礼乐新。
合酺覃土宇，欢宴接羣臣。
玉斝飞千日，琼筵荐八珍。
舞衣云曳影，歌扇月开轮。
伐鼓鱼龙杂，撞钟角抵陈。
曲终酣兴晚，须有醉归人。','',''),('quantangshi-00165','千秋节宴','皇帝','quantangshi','','卷1','兰殿千秋节，称名万寿觞。
风传率土庆，日表继天祥。
玉宇开花蕚，宫县动会昌。
衣冠白鹭下，帟幕翠云长。
献遗成新俗，朝仪入旧章。
月衔花绶镜，露缀彩丝囊。
处处祠田祖，年年宴杖乡。
深思一德事，小获万人康。','',''),('quantangshi-00166','左丞相说右丞相璟太子少傅干曜同日上官命宴东堂赐诗','皇帝','quantangshi','','卷1','赤帝收三杰，黄轩举二臣。
由来丞相重，分掌国之钧。
我有握中璧，双飞席上珍。
子房推道要，仲子讶风神。
复辍台衡老，将为调护人。
鵷鸾同拜日，车骑拥行尘。
乐聚南宫宴，觞连北斗醇。
俾予成百揆，垂拱问彝伦。','',''),('quantangshi-00167','早登太行山中言志','皇帝','quantangshi','','卷1','清跸度河阳，凝笳上太行。
火龙明鸟道，铁骑绕羊肠。
白雾埋阴壑，丹霞助晓光。
涧泉含宿冻，山木带余霜。
野老茅为屋，樵人薜作裳。
宣风问耆艾，敦俗劝耕桑。
凉德慙先哲，徽猷慕昔皇。','',''),('quantangshi-00168','平胡','皇帝','quantangshi','','卷1','杂虏忽猖狂，无何敢乱常。
羽书朝继入，烽火夜相望。
将出凶门勇，兵因死地强。
蒙轮皆突骑，按劒尽鹰扬。
鼓角雄山野，龙蛇入战场。
流膏润沙漠，溅血染锋铓。
雾扫清玄塞，云开静朔方。
武功今已立，文德愧前王。','',''),('quantangshi-00169','游兴庆宫作','皇帝','quantangshi','','卷1','代邸青门右，离宫紫陌陲。
庭如过沛日，水若渡江时。
绮观连鸡岫，朱楼接雁池。
从来敦棣蕚，今此茂荆枝。
万叶传余庆，千年志不移。
凭轩聊属目，轻辇共追随。
务本方崇训，相辉保羽仪。
时康俗易渐，德薄政难施。
鼓吹迎飞盖，弦歌送羽巵。
所希覃率土，孝弟一同规。','',''),('quantangshi-00170','送张说巡边','皇帝','quantangshi','','卷1','端拱复垂裳，长怀御远方。
股肱申教义，戈劒靖要荒。
命将绥边服，雄图出庙堂。
三台入武帐，八座起文昌。
宝胄匡韩主，华宗辅汉王。
茂先慙博物，平子谢文章。
尽节恢时佐，输诚御寇场。
三军临朔野，驷马即戎行。
鼓吹威夷狄，旌轩溢洛阳。
云台先着美，今日更贻芳。','',''),('quantangshi-00171','饯王晙巡边','皇帝','quantangshi','','卷1','振武威荒服，扬文肃远墟。
金坛申将礼，玉节授军符。
免胄三方外，衔刀万里余。
昔时吴会静，今日虏庭虚。
分阃仍推毂，援桴且训车。
风扬旌斾远，雨洗甲兵初。
坐见台阶谧，行闻祆祲除。
檄来虽插羽，箭去亦飞书。
舟檝功须着，盐梅望匪疎。
不应陈七德，欲使化先敷。','',''),('quantangshi-00172','巡省途次上党旧宫赋','皇帝','quantangshi','','卷1','三千初击浪，九万欲抟空。
天地犹惊否，阴阳始遇蒙。
存贞期历试，佐贰伫昭融。
多谢时康理，良慙实赖功。
长怀问鼎气，夙负拔山雄。
不学刘琨舞，先歌汉祖风。
英髦既包括，豪杰自牢笼。
人事一朝异，讴歌四海同。
如何昔朱邸，今此作离宫？
雁沼澄澜翠，猿岩落照红。
小山秋桂馥，长坂旧兰丛。
即是淹留处，乘欢乐未穷。','',''),('quantangshi-00173','潼关口号','皇帝','quantangshi','','卷1','河曲回千里，关门限二京。
所嗟非恃德，设险到天平。','',''),('quantangshi-00174','千秋节赐羣臣镜','皇帝','quantangshi','','卷1','瑞露垂花绶，寒冰澈宝输。
对兹台上月，聊以庆佳辰。','',''),('quantangshi-00175','续薛令之题壁','皇帝','quantangshi','','卷1','啄木觜距长，凤皇羽毛短。
苦嫌松桂寒，任逐桑榆暖。','',''),('quantangshi-00176','送胡真师还西山','皇帝','quantangshi','','卷1','仙客厌人间，孤云比性闲。
话离情未已，烟水万重山。','',''),('quantangshi-00177','过大哥山池题石壁','皇帝','quantangshi','','卷1','澄潭皎镜石崔巍，万壑千岩暗绿苔。
林亭自有幽贞趣，况复秋深爽气来。','',''),('quantangshi-00178','题梅妃画真','皇帝','quantangshi','','卷1','忆昔娇妃在紫宸，铅华不御得天真。
霜绡虽似当时态，争奈娇波不顾人。','',''),('quantangshi-00179','鹡鸰颂','皇帝','quantangshi','','卷1','伊我轩宫，奇树青葱。
蔼周庐兮，冒霜停雪，以茂以悦。
恣卷舒兮，连枝同荣，吐绿含英。
曜春初兮，蓐收御节，寒露微结。
气清虚兮，桂宫兰殿，唯所息宴。
栖雍渠兮，行摇飞鸣，急难有情。
情有余兮，顾惟德凉，夙夜兢惶。
慙化疎兮，上之所教，下之所效。
实在予兮，天伦之性，鲁卫分政。
亲贤居兮，爰游爰处，爰笑爰语。
巡庭除兮，观此翔禽，以悦我心，良史书兮。','',''),('quantangshi-00180','傀儡吟','皇帝','quantangshi','','卷1','刻木牵丝作老翁，鸡皮鹤发与真同。
须臾弄罢寂无事，还似人生一梦中。','',''),('quantangshi-00181','句','皇帝','quantangshi','','卷1','昔见漳滨卧，言将人事违。
今逢庆诞日，犹谓学仙归。
棠棣花重发，鸰原鸟再飞。
德比代云布，心如晋水清。','',''),('quantangshi-00182','延英殿玉灵芝诗三章章八句 一','肅宗皇帝','quantangshi','','卷1','玉殿肃肃，灵芝煌煌。
重英发秀，连叶分房。
宗庙之福，垂其耿光。','',''),('quantangshi-00183','延英殿玉灵芝诗三章章八句 二','肅宗皇帝','quantangshi','','卷1','元气产芝，明神合德。
紫微间采，白蕣呈色。
载启瑞图，庶符皇极。
天心有眷，王道惟直。','',''),('quantangshi-00184','延英殿玉灵芝诗三章章八句 三','肅宗皇帝','quantangshi','','卷1','幸生芳本，当我扆旒。
效此灵质，贲其王猷。
神惟不爱，道亦无求。
端拱思惟，永荷天休。','',''),('quantangshi-00185','赐棃李泌与诸王联句','肅宗皇帝','quantangshi','','卷1','先生年几许，颜色似童儿。
夜抱九仙骨，朝披一品衣。
不食千钟粟，唯餐两颗棃。
天生此间气，助我化无为。','',''),('quantangshi-00186','中和节日宴百僚赐诗','德宗皇帝','quantangshi','','卷1','韶年启仲序，初吉谐良辰。
肇兹中和节，式庆天地春。
欢酣朝野同，生德区宇均。
云开洒膏露，草疏芳河津。
岁华今载阳，东作方肆勤。
慙非熏风唱，曷用慰吾人。','',''),('quantangshi-00187','中和节赐百官燕集因示所怀','德宗皇帝','quantangshi','','卷1','至化恒在宥，保和兹息人。
推诚抚诸夏，与物长为春。
仲月风景暖，禁城花柳新。
芳时协金奏，赐宴同羣臣。
丝竹岂云乐，忠贤惟所亲。
庶洽朝野意，旷然天地均。','',''),('quantangshi-00188','重阳日赐宴曲江亭赋六韵诗用清字','德宗皇帝','quantangshi','','卷1','早衣对庭燎，躬化勤意诚。
时此万机暇，适与佳节并。
曲池洁寒流，芳菊舒金英。
干坤爽气满，台殿秋光清。
朝野庆年丰，高会多欢声。
永怀无荒戒，良士同斯情。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00189','九月十八赐百僚追赏因书所怀','德宗皇帝','quantangshi','','卷1','雨霁霜气肃，天高云日明。
繁林已坠叶，寒菊仍舒荣。
懿此秋节时，更延追赏情。
池台列广宴，丝竹传新声。
至乐非外奖，浃欢同中诚。
庶敦朝野意，永使风化清。','',''),('quantangshi-00190','送徐州张建封还镇','德宗皇帝','quantangshi','','卷1','牧守寄所重，才贤生为时。
宣风自淮甸，授钺膺藩维。
入觐展遐恋，临轩慰来思。
忠诚在方寸，感激陈情词。
报国尔所向，恤人予是资。
欢宴不尽怀，车马当还期。
谷雨将应候，行春犹未迟。
勿以千里遥，而云无己知。','',''),('quantangshi-00191','麟德殿宴百僚','德宗皇帝','quantangshi','','卷1','忧勤承圣绪，开泰喜时康。
恭己临羣后，垂衣御八荒。
务闲春向暮，朝罢日犹长。
紫殿初筵列，彤庭广乐张。
成功归辅弼，致理赖忠良。
共此欢娱事，千秋乐未央。','',''),('quantangshi-00192','元日退朝观军仗归营','德宗皇帝','quantangshi','','卷1','献岁视元朔，万方咸在庭。
端旒揖羣后，回辇阅师贞。
彩仗宿华殿，退朝归禁营。
分行左右出，转斾风云生。
历历趋复道，容容映层城。
勇余矜捷技，令肃无喧声。
眷此戎旅节，载嘉良士诚。
顺时倾宴赏，亦以助文经。','',''),('quantangshi-00193','中和节赐羣臣宴赋七韵','德宗皇帝','quantangshi','','卷1','东风变梅柳，万汇生春光。
中和纪月令，方与天地长。
耽乐岂予尚，懿兹时景良。
庶遂亭育恩，同致寰海康。
君臣永终始，交泰符阴阳。
曲沼水新碧，华林桃稍芳。
胜赏信多欢，戒之在无荒。','',''),('quantangshi-00194','三日书怀因示百僚','德宗皇帝','quantangshi','','卷1','佳节上元巳，芳时属暮春。
流觞想兰亭，捧劒得金人。
风轻水初绿，日晴花更新。
天文信昭回，皇道颇敷陈。
恭己每从俭，清心常保真。
戒兹游衍乐，书以示羣臣。','',''),('quantangshi-00195','重阳日中外同欢以诗言志因示羣官','德宗皇帝','quantangshi','','卷1','[爽]节在重九，物华新雨余。
清秋黄叶下，菊散金潭初。
万实行就稔，百工欣所如。
欢心畅遐迩，殊俗同车书。
至化自敦睦，佳辰宜宴胥。
锵锵间丝竹，济济罗簪裾。
此乐匪足耽，此诚期永孚。','',''),('quantangshi-00196','重阳日即事','德宗皇帝','quantangshi','','卷1','令节晓澄霁，四郊烟霭空。
天清白露洁，菊散黄金丛。
寡德荷天贶，顺时休百工。
岂怀歌钟乐，思为君臣同。
至化在亭育，相成资始终。
未知康衢咏，所仰惟年丰。','',''),('quantangshi-00197','丰年多庆九日示怀','德宗皇帝','quantangshi','','卷1','爽气肃时令，早衣闻朔鸿。
重阳有佳节，具物欣年丰。
皎洁暮潭色，芬敷新菊丛。
芳尊满衢室，繁吹凝烟空。
惠合信吾道，保和惟尔同。
推诚至玄化，天下期为公。','',''),('quantangshi-00198','七月十五日题章敬寺','德宗皇帝','quantangshi','','卷1','招提迩皇邑，复道连重城。
法筵会早秋，驾言访禅扃。
尝闻大仙教，清净宗无生。
七物匪吾宝，万行先求成。
名相既双寂，繁华奚所荣。
金风扇微凉，远烟凝翠晶。
松院静苔色，竹房深磬声。
境幽真虑恬，道胜外物轻。
意适本非说，含毫空复情。','',''),('quantangshi-00199','中春麟德殿会百僚观新乐诗一章章十六句','德宗皇帝','quantangshi','','卷1','芳岁肇佳节，物华当仲春。
干坤既昭泰，烟景含氤氲。
德浅荷玄贶，乐成思治人。
前庭列钟鼓，广殿延羣臣。
八卦随舞意，五音转曲新。
顾非咸池奏，庶协南风熏。
式宴礼所重，浃欢情必均。
同和谅在兹，万国希可亲。','',''),('quantangshi-00200','九日绝句','德宗皇帝','quantangshi','','卷1','禁苑秋来爽气多，昆明风动起沧波。
中流箫鼓诚堪赏，讵假横汾发棹歌。','',''),('quantangshi-00201','暮春喜雨诗','文宗皇帝','quantangshi','','卷1','风云喜际会，雷雨遂流滋。
荐币虚陈礼，动天实精思。
渐侵九夏节，复在三春时。
霢霂垂朱阙，飘颻入绿墀。
郊坰既霑足，黍稷有丰期。
百辟同康乐，万方伫雍熙。','',''),('quantangshi-00202','题程修己竹障','文宗皇帝','quantangshi','','卷1','良工运精思，巧极似有神。
临窗忽覩繁阴合，再盼真假殊未分。','',''),('quantangshi-00203','宫中题','文宗皇帝','quantangshi','','卷1','辇路生春草，上林花发时。
凭高何限意，无复侍臣知。','',''),('quantangshi-00204','上巳日赐裴度','文宗皇帝','quantangshi','','卷1','注想待元老，识君恨不早。
我家柱石衰，忧来学丘祷。','',''),('quantangshi-00205','上元日二首 一','文宗皇帝','quantangshi','','卷1','上元高会集羣仙，心斋何事欲祈年。
丹诚傥彻玉帝座，且共吾人庆大田。','',''),('quantangshi-00206','上元日二首 二','文宗皇帝','quantangshi','','卷1','蓂生三五叶初齐，上元羽客出桃蹊。
不爱仙家登真诀，愿蒙四海福黔黎。','',''),('quantangshi-00207','夏日联句','文宗皇帝','quantangshi','','卷1','人皆苦炎热，我爱夏日长。
熏风自南来，殿阁生微凉。','',''),('quantangshi-00208','百丈山','宣宗皇帝','quantangshi','','卷1','大雄真迹枕危峦，梵宇层楼耸万般。
日月每从肩上过，山河长在掌中看。
仙峰不间三春秀，灵境何时六月寒？
更有上方人罕到，暮钟朝磬碧云端。','',''),('quantangshi-00209','吊白居易','宣宗皇帝','quantangshi','','卷1','缀玉联珠六十年，谁教冥路作诗仙。
浮云不系名居易，造化无为字乐天。
童子解吟《长恨曲》，胡儿能唱《琵琶篇》。
文章已满行人耳，一度思卿一怆然。','',''),('quantangshi-00210','幸华严寺','宣宗皇帝','quantangshi','','卷1','云散晴山几万重，烟收春色更冲融。
帐殿出空登碧汉，遐川俯望色蓝笼。
林光入户低韶景，岭气通宵展霁风。
今日追游何所似，莫慙汉武赏汾中。','',''),('quantangshi-00211','重阳锡宴羣臣','宣宗皇帝','quantangshi','','卷1','款塞旋征骑，和戎委庙贤。
倾心方倚注，叶力共安边。','',''),('quantangshi-00212','题泾县水西寺','宣宗皇帝','quantangshi','','卷1','大殿连云接爽溪，钟声还与鼓声齐。
长安若问江南事，说道风光在水西。','',''),('quantangshi-00213','瀑布联句','宣宗皇帝','quantangshi','','卷1','千岩万壑不辞劳，远看方知出处高。
溪涧岂能留得住，终归大海作波涛。','',''),('quantangshi-00214','句','宣宗皇帝','quantangshi','','卷1','海岳宴咸通，七载秉钧调四序。
一方狱市获来苏。','',''),('quantangshi-00215','咏雷句','昭宗皇帝','quantangshi','','卷1','只解劈牛兼劈树，不能诛恶与诛凶。','',''),('quantangshi-00216','春游曲','文德皇后','quantangshi','','卷1','上苑桃花朝日明，兰闺艳妾动春情。
井上新桃偷面色，檐边嫩柳学身轻。
花中来去看舞蝶，树上长短听啼莺。
林下何须远借问，出众风流旧有名。','',''),('quantangshi-00217','曳鼎歌','則天皇后','quantangshi','','卷1','羲农首出，轩昊膺期。
唐虞继踵，汤禹乘时。
天下光宅，海内雍熙。
上玄降鉴，方建隆基。','',''),('quantangshi-00218','唐享昊天乐 第一','則天皇后','quantangshi','','卷1','太阴凝至化，真耀蕴轩仪。
德迈娥台敞，仁高[姒]幄披。
扪天遂启极，梦日乃升曦。','',''),('quantangshi-00219','唐享昊天乐 第二','則天皇后','quantangshi','','卷1','瞻紫极，望玄穹。
翘至恳，罄深衷。
听虽远，诚必通。
垂厚泽，降云宫。','',''),('quantangshi-00220','唐享昊天乐 第三','則天皇后','quantangshi','','卷1','干仪混成冲邃，天道下济高明。
闿阳晨披紫阙，太一晓降黄庭。
圜坛敢申昭报，方璧冀展虔情。
丹襟式敷衷恳，玄鉴庶察微诚。','',''),('quantangshi-00221','唐享昊天乐 第四','則天皇后','quantangshi','','卷1','巍巍睿业广，赫赫圣基隆。
菲德承先顾，祯符萃眇躬。
铭开武岩侧，图荐洛川中。
微诚讵幽感，景命忽昭融。
有怀慙紫极，无以谢玄穹。','',''),('quantangshi-00222','唐享昊天乐 第五','則天皇后','quantangshi','','卷1','朝坛雾卷，曙岭烟沈。
爰设筐币，式表诚心。
筵辉丽璧，乐畅和音。
仰惟灵鉴，俯察翘襟。','',''),('quantangshi-00223','唐享昊天乐 第六','則天皇后','quantangshi','','卷1','昭昭上帝，穆穆下临。
礼崇备物，乐奏锵金。
兰羞委荐，桂醑盈斟。
敢希明德，幸罄庄心。','',''),('quantangshi-00224','唐享昊天乐 第七','則天皇后','quantangshi','','卷1','尊浮九酝，礼备三周。
陈诚菲奠，契福神猷。','',''),('quantangshi-00225','唐享昊天乐 第八','則天皇后','quantangshi','','卷1','奠璧郊坛昭大礼，锵金拊石表虔诚。
始奏承云娱帝赏，复歌调露畅韶英。','',''),('quantangshi-00226','唐享昊天乐 第九','則天皇后','quantangshi','','卷1','荷恩承顾托，执契恭临抚。
庙略静边荒，天兵曜神武。
有截资先化，无为遵旧矩。
祯符降昊穹，大业光寰宇。','',''),('quantangshi-00227','唐享昊天乐 第十','則天皇后','quantangshi','','卷1','肃肃祀典，邕邕礼秩。
三献已周，九成斯毕。
爰撤其俎，载迁其实。
或升或降，惟诚惟质。','',''),('quantangshi-00228','唐享昊天乐 第十一','則天皇后','quantangshi','','卷1','礼终肆类，乐阕九成。
仰惟明德，敢荐非馨。
顾慙菲奠，久驰云軿。
瞻荷灵泽，悚恋兼盈。','',''),('quantangshi-00229','唐享昊天乐 第十二','則天皇后','quantangshi','','卷1','式干路，辟天扉。
回日驭，动云衣。
登金阙，入紫微。
望仙驾，仰恩徽。','',''),('quantangshi-00230','唐明堂乐章 外办将出','則天皇后','quantangshi','','卷1','总章陈昔典，衢室礼惟神。
宏规则天地，神用叶陶钧。
负扆三春旦，充庭万宇宾。
顾己诚虚薄，空慙驭兆人。','',''),('quantangshi-00231','唐明堂乐章 皇帝行','則天皇后','quantangshi','','卷1','仰膺历数，俯顺讴歌。
远安迩肃，俗阜时和。
化光玉镜，讼息金科。
方兴典礼，永戢干戈。','',''),('quantangshi-00232','唐明堂乐章 皇嗣出入升降','則天皇后','quantangshi','','卷1','至人光俗，大孝通神。
谦以表性，恭惟立身。
洪规载启，茂典方陈。
誉隆三善，祥开万春。','',''),('quantangshi-00233','唐明堂乐章 迎送王公','則天皇后','quantangshi','','卷1','千官肃事，万国朝宗。
载延百辟，爰集三宫。
君臣德合，鱼水斯同。
睿图方永，周历长隆。','',''),('quantangshi-00234','唐明堂乐章 登歌','則天皇后','quantangshi','','卷1','礼崇宗祀，志表严禋。
笙镛合奏，文物惟新。
敬遵茂典，敢择良辰。
絜诚斯着，奠谒方申。','',''),('quantangshi-00235','唐明堂乐章 配飨','則天皇后','quantangshi','','卷1','笙镛间玉宇，文物昭清辉。
晬影临芳奠，休光下太微。
孝思期有感，明絜庶无违。','',''),('quantangshi-00236','唐明堂乐章 宫音','則天皇后','quantangshi','','卷1','履艮包羣望，居中冠百灵。
万方资广运，庶品荷财成。
神功谅匪测，盛德实难名。
藻奠申诚敬，恭祀表惟馨。','',''),('quantangshi-00237','唐明堂乐章 角音','則天皇后','quantangshi','','卷1','出震位，开平秩。
扇条风，乘甲乙。
龙德盛，鸟星出。
荐圭篚，陈诚实。','',''),('quantangshi-00238','唐明堂乐章 征音','則天皇后','quantangshi','','卷1','赫赫离精御炎陆，滔滔炽景开隆暑。
冀延神鉴俯兰尊，式表虔襟陈桂俎。','',''),('quantangshi-00239','唐明堂乐章 商音','則天皇后','quantangshi','','卷1','律中夷则，序应收成。
功宣建武，义表惟明。
爰申礼奠，庶展翘诚。
九秋是式，百谷斯盈。','',''),('quantangshi-00240','唐明堂乐章 羽音','則天皇后','quantangshi','','卷1','葭律肇启隆冬，苹藻攸陈飨祭。
黄钟既陈玉烛，红粒方殷稔岁。','',''),('quantangshi-00241','唐大飨拜洛乐章 昭和','則天皇后','quantangshi','','卷1','九玄眷命，三圣基隆。
奉成先旨，明台毕功。
宗祀展敬，冀表深衷。
永昌帝业，式播淳风。','',''),('quantangshi-00242','唐大飨拜洛乐章 致和','則天皇后','quantangshi','','卷1','神功不测兮运阴阳，包藏万宇兮孕八荒。
天符既出兮帝业昌，愿临明祀兮降祯祥。','',''),('quantangshi-00243','唐大飨拜洛乐章 咸和','則天皇后','quantangshi','','卷1','坎泽祠容备举，坤坛祭典爰申。
灵睠遥行祕躅，嘉贶荐委殊珍。
肃礼恭禋载展，翘襟邈志逾殷。
方期交际悬应。','',''),('quantangshi-00244','唐大飨拜洛乐章 九和','則天皇后','quantangshi','','卷1','祗荷坤德，钦若干灵。
慙惕罔置，兴居匪宁。
恭崇礼则，肃奉仪形。
惟凭展敬，敢荐非馨。','',''),('quantangshi-00245','唐大飨拜洛乐章 拜洛','則天皇后','quantangshi','','卷1','菲躬承睿顾，薄德忝坤仪。
干干遵后命，翼翼奉先规。
抚俗勤虽切，还淳化尚亏。
未能弘至道，何以契明只。','',''),('quantangshi-00246','唐大飨拜洛乐章 显和','則天皇后','quantangshi','','卷1','顾德有慙虚菲，明只屡降祯符。
汜水初呈祕象，温洛荐表昌图。
玄泽流恩载洽，丹襟荷渥增愉。','',''),('quantangshi-00247','唐大飨拜洛乐章 昭和','則天皇后','quantangshi','','卷1','舒云致养，合大资生。
德以恒固，功由永贞。
升歌荐序，垂币翘诚。
虹开玉照，凤引金声。','',''),('quantangshi-00248','唐大飨拜洛乐章 敬和','則天皇后','quantangshi','','卷1','兰俎既升，苹羞可荐。
金石载设，咸英已变。
林泽斯总，山川是徧。
敢用敷诚，实惟忘倦。','',''),('quantangshi-00249','唐大飨拜洛乐章 齐和','則天皇后','quantangshi','','卷1','沈潜演贶分三极，广大凝祯总万方。
既荐羽旌文化启，还呈干戚武威扬。','',''),('quantangshi-00250','唐大飨拜洛乐章 德和','則天皇后','quantangshi','','卷1','夕惕同龙契，晨兢当凤扆。
崇儒习旧规，偃伯循先旨。
绝壤飞冠盖，遐区丽山水。
幸承三圣余，忻属千年始。','',''),('quantangshi-00251','唐大飨拜洛乐章 禋和','則天皇后','quantangshi','','卷1','百礼崇容，千官肃事。
灵降舞兆，神凝有粹。
奠享咸周，威仪毕备。
奏夏登列，歌雍撤肆。','',''),('quantangshi-00252','唐大飨拜洛乐章 通和','則天皇后','quantangshi','','卷1','皇皇灵睠，穆穆神心。
暂动凝质，还归积阴。
功玄枢纽，理寂高深。
衔恩佩德，耸志翘襟。','',''),('quantangshi-00253','唐大飨拜洛乐章 归和','則天皇后','quantangshi','','卷1','言旋云洞兮蹑烟涂，永宁中宇兮安下都。
包涵动植兮顺荣枯，长贻宝贶兮赞璇图。','',''),('quantangshi-00254','唐大飨拜洛乐章 归和','則天皇后','quantangshi','','卷1','调云阕兮神座兴，骖云驾兮俨将升。
腾绛霄兮垂景祜，翘丹恳兮荷休征。','',''),('quantangshi-00255','唐武氏享先庙乐章','則天皇后','quantangshi','','卷1','先德谦撝冠昔，严规节素超今。
奉国忠诚每竭，承家至孝纯深。
追崇惧乖尊意，显号恐玷徽音。
既迫王公屡请，方乃俯遂羣心。
有限无由展敬，奠醑每阙亲斟。
大礼虔申典册，苹藻敬荐翘襟。','',''),('quantangshi-00256','早春夜宴','則天皇后','quantangshi','','卷1','九春开上节，千门敞夜扉。
兰灯吐新焰，桂魄朗圆辉。
送酒惟须满，流杯不用稀。
务使霞浆兴，方乘泛洛归。','',''),('quantangshi-00257','游九龙潭','則天皇后','quantangshi','','卷1','山窗游玉女，涧户对琼峰。
岩顶翔双凤，潭心倒九龙。
酒中浮竹叶，杯上写芙蓉。
故验家山赏，惟有风入松。','',''),('quantangshi-00258','赠胡天师','則天皇后','quantangshi','','卷1','高人叶高志，山服往山家。
迢迢间风月，去去隔烟霞。
碧岫窥玄洞，玉竈炼丹砂。
今日星津上，延首望灵槎。','',''),('quantangshi-00259','从驾幸少林寺','則天皇后','quantangshi','','卷1','陪銮游禁苑，侍赏出兰闱。
云偃攒峰盖，霞低插浪旗。
日宫疏涧户，月殿启岩扉。
金轮转金地，香阁曳香衣。
铎吟轻吹发，幡摇薄雾霏。
昔遇焚芝火，山红连野飞。
花台无半影，莲塔有全辉。
实赖能仁力，攸资善世威。
慈缘兴福绪，于此罄归依。
风枝不可静，泣血竟何追。','',''),('quantangshi-00260','石淙','則天皇后','quantangshi','','卷1','三山十洞光玄箓，玉峤金峦镇紫微。
均露均霜标胜壤，交风交雨列皇畿。
万仞高岩藏日色，千寻幽涧浴云衣。
且驻欢筵赏仁智，雕鞍薄晚杂尘飞。','',''),('quantangshi-00261','腊日宣诏幸上苑','則天皇后','quantangshi','','卷1','明朝游上苑，火急报春知。
花须连夜发，莫待晓风吹。','',''),('quantangshi-00262','如意娘','則天皇后','quantangshi','','卷1','看朱成碧思纷纷，顦顇支离为忆君。
不信比来长下泪，开箱验取石榴裙。','',''),('quantangshi-00263','制袍字赐狄仁杰','則天皇后','quantangshi','','卷1','敷政术，守清勤。
升显位，励相臣。','',''),('quantangshi-00264','拟小山篇','徐賢妃','quantangshi','','卷1','仰幽岩而流盼，抚桂枝以凝想。
将千龄兮此遇，荃何为兮独往。','',''),('quantangshi-00265','长门怨','徐賢妃','quantangshi','','卷1','旧爱柏梁台，新宠昭阳殿。
守分辞芳辇，含情泣团扇。
一朝歌舞荣，夙昔诗书贱。
颓恩诚已矣，覆水难重荐。','',''),('quantangshi-00266','秋风函谷应诏','徐賢妃','quantangshi','','卷1','秋风起函谷，劲气动河山。
偃松千岭上，杂雨二陵间。
低云愁广隰，落日惨重关。
此时飘紫气，应验真人还。','',''),('quantangshi-00267','赋得北方有佳人','徐賢妃','quantangshi','','卷1','由来称独立，本自号倾城。
柳叶眉间发，桃花脸上生。
腕摇金钏响，步转玉环鸣。
纤腰宜宝袜，红衫艳织成。
悬知一顾重，别觉舞腰轻。','',''),('quantangshi-00268','进太宗','徐賢妃','quantangshi','','卷1','朝来临镜台，妆罢暂裴回。
千金始一笑，一召讵能来。','',''),('quantangshi-00269','奉和圣制立春日侍宴内殿出翦彩花应制','上官昭容','quantangshi','','卷1','密叶因裁吐，新花逐翦舒。
攀条虽不谬，摘橤讵知虚。
春至由来发，秋还未肯疎。','',''),('quantangshi-00270','九月九日上幸慈恩寺登浮图羣臣上菊花寿酒','上官昭容','quantangshi','','卷1','帝里重阳节，香园万乘来。
却邪萸入佩，献寿菊传杯。
墖类承天涌，门疑待佛开。
睿词悬日月，长得仰昭回。','',''),('quantangshi-00271','彩书怨','上官昭容','quantangshi','','卷1','叶下洞庭初，思君万里余。
露浓香被冷，月落锦屏虚。
欲奏江南曲，贪封蓟北书。
书中无别意，惟怅久离居。','',''),('quantangshi-00272','驾幸三会寺应制','上官昭容','quantangshi','','卷1','释子谈经处，轩臣刻字留。
故台遗老识，残简圣皇求。
驻跸怀千古，开襟望九州。
四山缘塞合，二水夹城流。
宸翰陪瞻仰，天杯接献酬。
太平词藻盛，长愿纪鸿休。','',''),('quantangshi-00273','驾幸新丰温泉宫献诗三首 一','上官昭容','quantangshi','','卷1','三冬季月景[龙]年，万乘观风出灞川。
遥看电跃龙为马，回瞩霜原玉作田。','',''),('quantangshi-00274','驾幸新丰温泉宫献诗三首 二','上官昭容','quantangshi','','卷1','鸾旗掣曳拂空回，羽骑骖驔蹑景来。
隐隐骊山云外耸，迢迢御帐日边开。','',''),('quantangshi-00275','驾幸新丰温泉宫献诗三首 三','上官昭容','quantangshi','','卷1','翠幕珠帏敞月营，金罍玉斝泛兰英。
岁岁年年常扈跸，长长久久乐升平。','',''),('quantangshi-00276','游长宁公主流杯池二十五首 一','上官昭容','quantangshi','','卷1','逐仙赏，展幽情。
逾昆阆，迈蓬瀛。','',''),('quantangshi-00277','游长宁公主流杯池二十五首 二','上官昭容','quantangshi','','卷1','游鲁馆，陟秦台。
汚山壁，愧琼瓌。','',''),('quantangshi-00278','游长宁公主流杯池二十五首 三','上官昭容','quantangshi','','卷1','檀栾竹影，飙䫻松声。
不烦歌吹，自足娱情。','',''),('quantangshi-00279','游长宁公主流杯池二十五首 四','上官昭容','quantangshi','','卷1','仰循茅宇，俯眄乔枝。
烟霞问讯，风月相知。','',''),('quantangshi-00280','游长宁公主流杯池二十五首 五','上官昭容','quantangshi','','卷1','枝条郁郁，文质彬彬。
山林作伴，松桂为邻。','',''),('quantangshi-00281','游长宁公主流杯池二十五首 六','上官昭容','quantangshi','','卷1','清波汹涌，碧树冥蒙。
