三摘犹自可，摘绝抱蔓归。','',''),('quantangshi-00305','奉和同太子监守违恋','韓王元嘉','quantangshi','','卷1','干象开层构，离明启少阳。
卜征从献吉，守器属元良。
逖矣凌周诵，遥哉掩汉庄。
好士倾南洛，多才盛北场。
地分丹鹫岭，途间白云乡。
储诚虔晓夕，宸爱积炎凉。
珠璧连霄汉，万物仰重光。','',''),('quantangshi-00306','奉和圣制过温汤','越王貞','quantangshi','','卷1','凤辇腾宸驾，骊籞次干游。
坎德疎温液，山隈派暖流。
寒氛空外拥，蒸气沼中浮。
林凋帷影散，云敛盖阴收。
霜郊畅玄览，参差落景遒。','',''),('quantangshi-00307','石桥','信安王禕','quantangshi','','卷1','别有经行所，迥跨重峦侧。
粤因求瘼余，倏想寻真域。
放情恣披拂，杖策聊□□。
□□□□□，□□□□色。
乱幡雾中见，雁塔云间识。
薄烟幂远郊，遥峰没归翼。
仙桥危石架，幽洞乘□□。
□□□□□，□□□易测。
二教无先后，一相平而直。
冀兹捐俗心，永怀依妙力。','',''),('quantangshi-00308','虚池驿题屏风','宜芬公主','quantangshi','','卷1','出嫁辞乡国，由来此别难。
圣恩愁远道，行路泣相看。
沙塞容颜尽，边隅粉黛残。
妾心何所断，他日望长安。','',''),('quantangshi-00309','嘲陆畅','女學士宋氏若華','quantangshi','','卷1','十二层楼倚翠空，凤鸾相对立梧桐。
双成走报监门卫，莫使吴歈入汉宫。','',''),('quantangshi-00310','奉和御制麟德殿宴百僚应制','尚宮宋氏若昭','quantangshi','','卷1','垂衣临八极，肃穆四门通。
自是无为化，非关辅弼功。
修文招隐伏，尚武殄妖凶。
德炳韶光炽，恩霑雨露浓。
衣冠陪御宴，礼乐盛朝宗。
万寿称觞举，千年信一同。','',''),('quantangshi-00311','奉和御制麟德殿宴百官','尚宮宋氏若憲','quantangshi','','卷1','端拱承休命，时清荷圣皇。
四聪闻受谏，五服远朝王。
景媚莺初啭，春残日更长。
命筵多济济，盛乐复锵锵。
酆镐谁将敌，横汾未可方。
愿齐山岳寿，祉福永无疆。','',''),('quantangshi-00312','奉和麟德殿宴百僚应[制]','鮑氏君徽','quantangshi','','卷1','睿泽先寰海，功成展武韶。
戈鋋清外垒，文物盛中朝。
圣祚山河固，宸章日月昭。
玉筵鸾鹄集，仙管凤皇调。
御柳新低绿，宫莺乍啭娇。
愿将[亿]兆庆，千祀奉神尧。','',''),('quantangshi-00313','关山月','鮑氏君徽','quantangshi','','卷1','高高秋月明，北照辽阳城。
塞迥光初满，风多晕更生。
征人望乡思，战马闻鼙惊。
朔风悲边草，胡沙暗虏营。
霜凝匣中劒，风惫原上旌。
早晚谒金阙，不闻刁斗声。','',''),('quantangshi-00314','惜花吟','鮑氏君徽','quantangshi','','卷1','枝上花，花下人，可怜颜色俱青春。
昨日看花花灼灼，今朝看花花欲落。
不如尽此花下欢，莫待春风总吹却。
莺歌蝶舞韶光长，红炉煑茗松花香。
妆成罢吟恣游后，独把芳枝归洞房。','',''),('quantangshi-00315','东亭茶宴','鮑氏君徽','quantangshi','','卷1','闲朝向晓出帘栊，茗宴东亭四望通。
