故言如梦里，赖得雁书飞。','',''),('quantangshi-00317','咏灯','南唐先主李昪','quantangshi','','卷1','一点分明值万金，开时惟怕冷风侵。
主人若也勤挑拨，敢向尊前不尽心。','',''),('quantangshi-00318','游后湖赏莲花','嗣主璟','quantangshi','','卷1','蓼花蘸水火不灭，水鸟惊鱼银梭投。
满目荷花千万顷，红碧相杂敷清流。
孙武已斩吴宫女，琉璃池上佳人头。','',''),('quantangshi-00319','保大五年元日大雪同太弟景遂汪王景逷齐王景逵进士李建勋中书徐铉勤政殿学士张义方登楼赋','嗣主璟','quantangshi','','卷1','珠帘高卷莫轻遮，往往相逢隔岁华。
春气昨宵飘律管，东风今日放梅花。
