苍苔迷古道，红叶乱朝霞。
栖凤枝梢犹輭弱，化龙形状已依稀。','',''),('quantangshi-00321','九月十日偶书','後主煜','quantangshi','','卷1','晚雨秋阴酒乍醒，感时心绪杳难平。
黄花冷落不成艳，红叶飕飗竞鼓声。
背世返能厌俗态，偶缘犹未忘多情。
自从双鬓斑斑白，不学安仁却自惊。','',''),('quantangshi-00322','秋莺','後主煜','quantangshi','','卷1','残莺何事不知秋，横过幽林尚独游。
老舌百般倾耳听，深黄一点入烟流。
栖迟背世同悲鲁，浏亮如笙碎在缑。
莫更留连好归去，露华凄冷蓼花愁。','',''),('quantangshi-00323','病起题山舍壁','後主煜','quantangshi','','卷1','山舍初成病乍轻，杖藜巾褐称闲情。
炉开小火深回暖，沟引新流几曲声。
暂约彭涓安朽质，终期宗远问无生。
谁能役役尘中累，贪合鱼龙构强名。','',''),('quantangshi-00324','送邓王二十弟从益牧宣城','後主煜','quantangshi','','卷1','且维轻舸更迟迟，别酒重倾惜解携。
浩浪侵愁光荡漾，乱山凝恨色高低。
君驰桧楫情何极，我凭阑干日向西。
咫尺烟江几多地，不须怀抱重凄凄。','',''),('quantangshi-00325','渡中江望石城泣下','後主煜','quantangshi','','卷1','江南江北旧家乡，三十年来梦一场。
吴苑宫闱今冷落，广陵台殿已荒凉。
云笼远岫愁千片，雨打归舟泪万行。
兄弟四人三百口，不堪闲坐细思量。','',''),('quantangshi-00326','挽辞 一','後主煜','quantangshi','','卷1','珠碎眼前珍，花凋世外春。
未销心里恨，又失掌中身。
玉笥犹残药，香匳已染尘。
前哀将后感，无泪可霑巾。','',''),('quantangshi-00327','挽辞 二','後主煜','quantangshi','','卷1','艳质同芳树，浮危道略同。
正悲春落实，又苦雨伤丛。
穠丽今何在？飘零事已空。
沈沈无问处，千载谢东风。','',''),('quantangshi-00328','悼诗','後主煜','quantangshi','','卷1','永念难消释，孤怀痛自嗟。
雨深秋寂莫，愁引病增加。
咽绝风前思，昏蒙眼上花。
空王应念我，穷子正迷家。','',''),('quantangshi-00329','感怀 一','後主煜','quantangshi','','卷1','又见桐花发旧枝，一楼烟雨暮凄凄。
凭阑惆怅人谁会，不觉澘然泪眼低。','',''),('quantangshi-00330','感怀 二','後主煜','quantangshi','','卷1','层城无复见娇姿，佳节缠哀不自持。
空有当年旧烟月，芙蓉城上哭蛾眉。','',''),('quantangshi-00331','梅花','後主煜','quantangshi','','卷1','殷勤移植地，曲槛小阑边。
共约重芳日，还忧不盛妍。
阻风开步障，乘月溉寒泉。
谁料花前后，蛾眉却不全。','',''),('quantangshi-00332','梅花','後主煜','quantangshi','','卷1','失却烟花主，东君自不知。
清香更何用，犹发去年枝。','',''),('quantangshi-00333','书灵筵手巾','後主煜','quantangshi','','卷1','浮生共顦顇，壮岁失婵娟。
汗手遗香渍，痕眉染黛烟。','',''),('quantangshi-00334','书琵琶背','後主煜','quantangshi','','卷1','侁自肩如削，难胜数缕绦。
天香留凤尾，余暖在檀槽。','',''),('quantangshi-00335','病中感怀','後主煜','quantangshi','','卷1','顦顇年来甚，萧条益自伤。
风威侵病骨，雨气咽愁肠。
夜鼎唯煎药，朝髭半染霜。
前缘竟何似，谁与问空王。','',''),('quantangshi-00336','病中书事','後主煜','quantangshi','','卷1','病身坚固道情深，宴坐清香思自任。
月照静居唯捣药，门扃幽院只来禽。
庸医嬾听词何取，小婢将行力未禁。
赖问空门知气味，不然烦恼万涂侵。','',''),('quantangshi-00337','赐宫人庆奴','後主煜','quantangshi','','卷1','风情渐老见春羞，到处消魂感旧游。
多谢长条似相识，强垂烟态拂人头。','',''),('quantangshi-00338','题金楼子后','後主煜','quantangshi','','卷1','牙签万轴裹红绡，王粲书同付火烧。
不于祖龙留面目，遗篇那得到今朝。','',''),('quantangshi-00339','句','後主煜','quantangshi','','卷1','迢迢牵牛星，杳在河之阳。
粲粲黄姑女，耿耿遥相望。
鸎狂应有恨，蝶舞已无多。
揖让月在手，动摇风满怀。
病态如衰弱，厌厌向五年。
衰颜一病难牵复，晓殿君临颇自羞。
冷笑秦皇经远略，静怜姬满苦时巡。
鬓从今日添新白，菊是去年依旧黄。
万古到头归一死，醉乡葬地有高原。
人生不满百，刚作千年画。
日暎仙云薄，秋高天碧深。
乌照始潜辉，龙烛便争秉。
凝珠满露枝，游扬日已西。
肃穆寒初至，九重开扇鹄。
四牖炳灯鱼，羽觞无算酌。
倾盌更为寿，深卮递酬宾。','',''),('quantangshi-00340','蔷薇诗一首十八韵呈东海侍郎徐铉','韓王從善','quantangshi','','卷1','绿影覆幽池，芳菲四月时。
管弦朝夕兴，组绣百千枝。
盛引墙看徧，高烦架屡移。
露轻濡彩笔，蜂误拂吟髭。
日照玲珑幔，风摇翡翠帷。
早红飘藓地，狂蔓挂蛛丝。
嫩刺牵衣细，新条窣草垂。
晚香难暂舍，娇态自相窥。
深浅分前后，荣华互盛衰。
尊前留客久，月下欲归迟。
何处繁临砌？谁家密映篱。
绛罗房灿烂，碧玉叶参差。
分得殷勤种，开来远近知。
晶荧歌袖袂，柔弱舞腰支。
膏麝谁将比，庭萱自合嗤。
匀妆低水鉴，泣泪滴烟𩅰。
画拟凭梁广，名宜亚楚姬。
寄君十八韵，思拙愧新奇。','',''),('quantangshi-00341','观棊','吉王從謙','quantangshi','','卷1','竹林二君子，尽日竟沈吟。
相对终无语，争先各有心。
恃强斯有失，守分固无侵。
若算机筹处，沧沧海未深。','',''),('quantangshi-00342','赠别唐太师道袭','蜀高祖王建','quantangshi','','卷1','丱岁便将为肘腋，二纪何曾离一日。
更深犹尚立案前，敷奏柔和不伤物。
今朝荣贵慰我心，双旌引向重城出。
褒斜旧地委勋贤，从此生灵永泰息。','',''),('quantangshi-00343','幸秦川上梓潼山','後主衍','quantangshi','','卷1','乔岩簇冷烟，幽径上寒天。
下瞰峨眉岭，上窥华岳巅。
驱驰非取乐，按幸为忧边。
此去如登陟，歌楼路几千。','',''),('quantangshi-00344','题劒门','後主衍','quantangshi','','卷1','缓辔逾双劒，行行蹑石棱。
作千寻壁垒，为万祀依凭。
道德虽无取，江山粗可矜。
回看城阙路，云叠树层层。','',''),('quantangshi-00345','过白卫岭和韩昭','後主衍','quantangshi','','卷1','先朝神武力开边，画断封疆四五千。
前望陇山屯劒戟，后凭巫峡锁烽烟。
轩皇尚自亲平寇，嬴政徒劳爱学仙。
想到隗宫寻胜处，正应莺语暮春天。','',''),('quantangshi-00346','宫词','後主衍','quantangshi','','卷1','辉辉赫赫浮玉云，宣华池上月华新。
月华如水浸宫殿，有酒不醉真痴人。','',''),('quantangshi-00347','醉妆词','後主衍','quantangshi','','卷1','者边走，那边走，只是寻花柳。
那边走，者边走，莫厌金杯酒。','',''),('quantangshi-00348','句','後主衍','quantangshi','','卷1','不缘朝阙去，好此结茅庐。','',''),('quantangshi-00349','巡衣锦军制还乡歌','吳越王錢鏐','quantangshi','','卷1','三节还乡兮挂锦衣，碧天朗朗兮爱日晖。
功成道上兮列旌旗，父老远来兮相追随。
家山乡眷兮会时稀，今朝设宴兮觥散飞。
斗牛无孛兮民无欺，吴越一王兮驷马归。','',''),('quantangshi-00350','没了期歌 一','吳越王錢鏐','quantangshi','','卷1','没了期，没了期，营基才了又仓基。','',''),('quantangshi-00351','没了期歌 二','吳越王錢鏐','quantangshi','','卷1','没了期，没了期，春衣才了又冬衣。','',''),('quantangshi-00352','句','吳越王錢鏐','quantangshi','','卷1','须将一片地，付与有心人。
黄河信有澄清日，后代应难继此才。
传语龙王并水府，钱塘借与筑钱城。','',''),('quantangshi-00353','宫中作','後王錢俶','quantangshi','','卷1','廊庑周遭翠幕遮，禁林深处绝喧哗。
界开日影怜窗纸，穿破苔痕恶笋芽。
西第晚宜供露茗，小池寒欲结冰花。
谢公未是深沈量，犹把输赢局上夸。','',''),('quantangshi-00354','避暑摩诃池上作','後蜀嗣主孟昶','quantangshi','','卷1','冰肌玉骨清无汗，水殿风来暗香暖。
帘开明月独窥人，敧枕钗横云鬓乱。
起来琼户寂无声，时见疎星渡河汉。
屈指西风几时来，只恐流年暗中换。','',''),('quantangshi-00355','批叶翘谏书纸尾','閩王王繼鵬','quantangshi','','卷1','春色曾看紫陌头，乱红飞尽不禁愁。
人情自厌芳华歇，一叶随风落御沟。','',''),('quantangshi-00356','丈人观','蜀太后徐氏','quantangshi','','卷1','早与元妃慕至化，同跻灵岳访真仙。
当时信有壶中景，今日亲来洞里天。
仪仗影空寥廓外，金丝声揭翠微巅。
惟慙未致华胥理，徒卜升平万万年。','',''),('quantangshi-00357','玄都观','蜀太后徐氏','quantangshi','','卷1','千寻绿嶂夹流溪，登眺因知海岳低。
瀑布迸舂青石碎，轮茵横翦翠峰齐。
步黏苔藓龙桥滑，日闭烟罗鸟径迷。
莫道穹天无路到，此山便是碧云梯。','',''),('quantangshi-00358','丈人观谒先帝御容','蜀太后徐氏','quantangshi','','卷1','圣帝归梧野，躬来谒圣颜。
旋登三径路，似陟九嶷山。
日照堆岚迥，云横积翠间。
期修封禅礼，方俟再跻攀。','',''),('quantangshi-00359','题金华宫','蜀太后徐氏','quantangshi','','卷1','再到金华顶，玄都访道回。
云披分景象，黛锁显楼台。
雨涤前山净，风吹去路开。
翠屏夹流水，何必羡蓬莱。','',''),('quantangshi-00360','丹景山至德寺','蜀太后徐氏','quantangshi','','卷1','周回云水游丹景，因与真妃眺上方。
晴日晓升金晃曜，寒泉夜落玉丁当。
松梢月转琴栖影，柏径风牵麝食香。
虔煠六铢宜铸祝，惟祈圣祉保遐昌。','',''),('quantangshi-00361','题彭州阳平化','蜀太后徐氏','quantangshi','','卷1','寻真游胜境，巡礼到阳平。
水远波澜碧，山高气象清。
殿严孙氏貌，碑暗系师名。
夜月登坛醮，松风森磬声。','',''),('quantangshi-00362','三学山夜看圣灯','蜀太后徐氏','quantangshi','','卷1','虔祷游灵境，元妃夙志同。
玉香焚静夜，银烛炫辽空。
泉漱云根月，钟敲桧杪风。
印金标圣迹，飞石显神功。
满望天涯极，平临日脚红。
猿来斋石上，僧集讲筵中。
顿作超三界，浑疑证六通。
愿成修偃化，社稷保延洪。','',''),('quantangshi-00363','题天回驿','蜀太后徐氏','quantangshi','','卷1','周游灵境散幽情，千里江山暂得行。
所恨风光看未足，却驱金翠入龟城。','',''),('quantangshi-00364','丈人观','蜀太妃徐氏','quantangshi','','卷1','获陪翠辇喜殊常，同涉仙坛岂厌长。
不羡乘鸾入烟雾，此中便是五云乡。','',''),('quantangshi-00365','玄都观','蜀太妃徐氏','quantangshi','','卷1','登寻丹壑到玄都，接日红霞照座隅。
即向周回岩下看，似看曾进画图无。','',''),('quantangshi-00366','游丈人观谒先帝御容','蜀太妃徐氏','quantangshi','','卷1','共谒御容仪，还同在禁闱。
笙歌喧宝殿，彩仗耀金徽。
清泪霑罗袂，红霞拂绣衣。
九疑山水远，无路继湘妃。','',''),('quantangshi-00367','题金华宫','蜀太妃徐氏','quantangshi','','卷1','碧烟红雾漾人衣，宿雾苍苔石径危。
风巧解吹松上曲，蝶娇频采脸边脂。
同寻僻境思携手，暗指遥山学画眉。
好把身心清净处，角冠霞帔事希夷。','',''),('quantangshi-00368','和题丹景山至德寺','蜀太妃徐氏','quantangshi','','卷1','丹景山头宿梵宫，玉轮金辂驻虚空。
军持无水注寒碧，兰若有花开晚红。
武士尽排青嶂下，内人皆在讲筵中。
我家帝子传王业，积善终期四海同。','',''),('quantangshi-00369','题彭州阳平化','蜀太妃徐氏','quantangshi','','卷1','云浮翠辇届阳平，真似骖鸾到上清。
风起半厓闻虎啸，雨来当面见龙行。
晚寻水涧听松韵，夜上星坛看月明。
长恐前身居此境，玉皇教向锦城生。','',''),('quantangshi-00370','三学山夜看圣灯','蜀太妃徐氏','quantangshi','','卷1','圣灯千万炬，旋向碧空生。
细雨湿不暗，好风吹更明。
磬敲金地响，僧唱梵天声。
若说无心法，此光如有情。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00371','题天回驿','蜀太妃徐氏','quantangshi','','卷1','翠驿红亭近玉京，梦魂犹是在青城。
比来出看江山景，却被江山看出行。','',''),('quantangshi-00372','郊庙歌辞 祀圜丘乐章 豫和','褚亮','quantangshi','','卷1','上灵睠命膺会昌，盛德殷荐叶辰良。
景福降兮圣德远，玄化穆兮天历长。','',''),('quantangshi-00373','郊庙歌辞 祀圜丘乐章 太和','褚亮','quantangshi','','卷1','穆穆我后，道应千龄。
登三处大，得一居贞。
礼惟崇德，乐以和声。
百神仰止，天下文明。','',''),('quantangshi-00374','郊庙歌辞 祀圜丘乐章 肃和','褚亮','quantangshi','','卷1','闿阳播气，甄曜垂明。
有赫圜宰，深仁曲成。
日丽苍璧，烟开紫营。
聿遵干享，式降鸿祯。','',''),('quantangshi-00375','郊庙歌辞 祀圜丘乐章 雍和','褚亮','quantangshi','','卷1','钦惟大帝，[载]仰皇穹。
始命田烛，爰启郊宫。
云门骇听，雷鼓鸣空。
神其介祀，景祚斯融。','',''),('quantangshi-00376','郊庙歌辞 祀圜丘乐章 寿和','褚亮','quantangshi','','卷1','八音斯奏，三献毕陈。
宝祚惟永，晖光日新。','',''),('quantangshi-00377','郊庙歌辞 祀圜丘乐章 舒和','褚亮','quantangshi','','卷1','叠璧凝影皇坛路，编珠流彩帝郊前。
已奏黄钟歌大吕，还符宝历祚昌年。','',''),('quantangshi-00378','郊庙歌辞 祀圜丘乐章 凯安','褚亮','quantangshi','','卷1','昔在炎运终，中华乱无象。
酆郊赤乌见，邙山黑云上。
大赉下周车，禁暴开殷网。
幽明同叶赞，鼎祚齐天壤。','',''),('quantangshi-00379','郊庙歌辞 祀圜丘乐章 豫和','褚亮','quantangshi','','卷1','歌奏毕兮礼献终，六龙驭兮神将升。
明德感兮非黍稷，降福简兮祚休征。','',''),('quantangshi-00380','郊庙歌辞 郊天旧乐章 豫和','不詳','quantangshi','','卷1','苹蘩礼着，黍稷诚微。
音盈凤管，彩驻龙旗。
洪歆式就，介福攸归。
送乐有阕，灵驭遄飞。','',''),('quantangshi-00381','郊庙歌辞 武后大享昊天乐章 一','不詳','quantangshi','','卷1','大阴凝至化，真耀蕴轩仪。
德迈娥台敞，仁高姒幄披。
扪天遂启极，梦日乃升曦。','',''),('quantangshi-00382','郊庙歌辞 武后大享昊天乐章 二','不詳','quantangshi','','卷1','瞻紫极，望玄穹。
翘至恳，罄深衷。
听虽远，诚必通。
垂厚泽，降云宫。','',''),('quantangshi-00383','郊庙歌辞 武后大享昊天乐章 三','不詳','quantangshi','','卷1','干仪混成冲邃，天道下济高明。
闿阳晨披紫阙，太一晓降黄庭。
圆坛敢[申]昭报，方璧冀展虔情。
丹禁式敷衷恳，玄鉴庶察微诚。','',''),('quantangshi-00384','郊庙歌辞 武后大享昊天乐章 四','不詳','quantangshi','','卷1','巍巍睿业广，赫赫圣基隆。
菲德承先顾，祯符萃眇躬。
铭开武岩侧，图荐洛川中。
微诚讵幽感，景命忽昭融。
有怀慙紫极，无以谢玄穹。','',''),('quantangshi-00385','郊庙歌辞 武后大享昊天乐章 五','不詳','quantangshi','','卷1','朝坛雾卷，曙岭烟沈。
爰设筐币，式表诚心。
筵辉丽璧，乐畅和音。
仰惟灵鉴，俯察翘襟。','',''),('quantangshi-00386','郊庙歌辞 武后大享昊天乐章 六','不詳','quantangshi','','卷1','昭昭上帝，穆穆下临。
礼崇备物，乐奏锵金。
兰羞委荐，桂醑盈斟。
敢希[明]德，聿罄庄心。','',''),('quantangshi-00387','郊庙歌辞 武后大享昊天乐章 七','不詳','quantangshi','','卷1','樽浮九酝，礼备三周。
陈诚菲奠，契福神猷。','',''),('quantangshi-00388','郊庙歌辞 武后大享昊天乐章 八','不詳','quantangshi','','卷1','奠璧郊坛昭大礼，锵金拊石表虔诚。
始奏承云娱帝赏，复歌调露畅韶英。','',''),('quantangshi-00389','郊庙歌辞 武后大享昊天乐章 九','不詳','quantangshi','','卷1','荷恩承顾托，执契恭临抚。
庙畧静边荒，天兵耀神武。
有截资先化，无为遵旧矩。
祯符降昊穹，大业光寰宇。','',''),('quantangshi-00390','郊庙歌辞 武后大享昊天乐章 十','不詳','quantangshi','','卷1','肃肃祀典，邕邕礼秩。
三献已周，九成斯毕。
爰撤其俎，载迁其实。
或升或降，唯诚唯质。','',''),('quantangshi-00391','郊庙歌辞 武后大享昊天乐章 十一','不詳','quantangshi','','卷1','礼终肆类，乐阕九成。
仰惟明德，敢荐非馨。
顾慙菲奠，久驻云軿。
瞻荷灵泽，悚恋兼盈。','',''),('quantangshi-00392','郊庙歌辞 武后大享昊天乐章 十二','不詳','quantangshi','','卷1','式干路，辟天扉。
回日驭，动云衣。
登金阙，入紫微。
望仙驾，仰恩徽。','',''),('quantangshi-00393','郊庙歌辞 中宗祀昊天乐章 豫和','不詳','quantangshi','','卷1','天之历数归睿唐，顾惟菲德钦昊苍。
撰吉日兮表殷荐，冀神鉴兮降闿阳。','',''),('quantangshi-00394','郊庙歌辞 中宗祀昊天乐章 太和','不詳','quantangshi','','卷1','恭临宝位，肃奉瑶图。
恒思解网，每轸泣辜。
德慙巢燧，化劣唐虞。
期我良弼，式赞嘉谟。','',''),('quantangshi-00395','郊庙歌辞 中宗祀昊天乐章 告谢','不詳','quantangshi','','卷1','得一流玄泽，通三御紫宸。
远叶千龄运，遐销九域尘。
绝瑞骈阗集，殊祥络绎臻。
登年庆栖亩，稔岁贺盈囷。','',''),('quantangshi-00396','郊庙歌辞 中宗祀昊天乐章 肃和','不詳','quantangshi','','卷1','悠哉广覆，大矣曲成。
九玄着象，七曜贞明。
圭璧是奠，酝酎斯盈。
作乐崇德，爰畅咸英。','',''),('quantangshi-00397','郊庙歌辞 中宗祀昊天乐章 雍和','不詳','quantangshi','','卷1','郊坛展敬，严配因心。
孤竹箫管，空桑瑟琴。
肃穆大礼，铿锵八音。
恭惟上帝，希降灵歆。','',''),('quantangshi-00398','郊庙歌辞 中宗祀昊天乐章 福和','不詳','quantangshi','','卷1','九成爰奏，三献式陈。
钦承景福，恭托明禋。','',''),('quantangshi-00399','郊庙歌辞 中宗祀昊天乐章 中宫助祭升坛','不詳','quantangshi','','卷1','坤元光至德，柔训阐皇风。
芣苡芳声远，螽斯美化隆。
睿范超千载，嘉猷备六宫。
肃恭陪盛典，钦若荐禋宗。','',''),('quantangshi-00400','郊庙歌辞 中宗祀昊天乐章 亚献','不詳','quantangshi','','卷1','三灵降飨，三后配神。
虔敷藻奠，敬展郊禋。','',''),('quantangshi-00401','郊庙歌辞 中宗祀昊天乐章 舒和','不詳','quantangshi','','卷1','已陈粢盛敷严祀，更奏笙镛协雅声。
璇图宝历欣宁谧，晏俗淳风乐太平。','',''),('quantangshi-00402','郊庙歌辞 中宗祀昊天乐章 凯安','不詳','quantangshi','','卷1','堂堂圣祖兴，赫赫昌基泰。
戎车盟津偃，玉帛涂山会。
舜日启祥晖，尧云卷征斾。
风猷被有截，声教覃无外。','',''),('quantangshi-00403','郊庙歌辞 明皇祀圜丘乐章 豫和','不詳','quantangshi','','卷1','至矣丕构，烝哉太平。
授牺膺箓，复禹继明。
草木仁化，凫鹥颂声。
祀宗陈德，无愧斯诚。','',''),('quantangshi-00404','郊庙歌辞 明皇祀圜丘乐章 太和','不詳','quantangshi','','卷1','郊坛斋帝，礼乐祀天。
丹青寰宇，宫征山川。
神只毕降，行止重旋。
融融穆穆，纳祉洪延。','',''),('quantangshi-00405','郊庙歌辞 明皇祀圜丘乐章 肃和','不詳','quantangshi','','卷1','止奏潜聆，登仪宿啭。
太玉躬奉，参钟首奠。
簠簋聿升，牺牲遰荐。
昭事颙若，存存以俔。','',''),('quantangshi-00406','郊庙歌辞 明皇祀圜丘乐章 雍和','不詳','quantangshi','','卷1','烂云普洽，律风无外。
