玄覆攸广，鸿休汪濊。','',''),('quantangshi-00407','郊庙歌辞 明皇祀圜丘乐章 寿和','不詳','quantangshi','','卷1','六变爰阕，八阶载虔。
佑我皇祚，于万斯年。','',''),('quantangshi-00408','郊庙歌辞 明皇祀圜丘乐章 寿和','不詳','quantangshi','','卷1','于赫圣祖，龙飞晋阳。
底定万国，奄有四方。
功格上下，道冠农黄。
郊天配享，德合无疆。','',''),('quantangshi-00409','郊庙歌辞 明皇祀圜丘乐章 寿和','不詳','quantangshi','','卷1','崇崇泰畤，肃肃严禋。
粢盛既洁，金石毕陈。
上帝来享，介福爰臻。
受厘合祉，宝祚维新。','',''),('quantangshi-00410','郊庙歌辞 明皇祀圜丘乐章 舒和','不詳','quantangshi','','卷1','祝史正辞，人神叶庆。
福以德招，享以诚应。
六变云备，百礼斯浃。
祀事孔明，祚流万叶。','',''),('quantangshi-00411','郊庙歌辞 明皇祀圜丘乐章 凯安','不詳','quantangshi','','卷1','馨香惟后德，明命光天保。
肃和崇圣灵，陈信表皇道。
玉鏚初蹈厉，金匏既静好。','',''),('quantangshi-00412','郊庙歌辞 明皇祀圜丘乐章 豫和','不詳','quantangshi','','卷1','大号成命，思文配天。
