眇眇阊阖，昭昭上玄。
俾昌而大，于斯万年。','',''),('quantangshi-00413','郊庙歌辞 明皇祀圜丘乐章 太和','不詳','quantangshi','','卷1','六成既阕，三荐云终。
神心具醉，圣敬愈崇。
受厘皇邸，回跸帷宫。
穰穰之福，永永无穷。','',''),('quantangshi-00414','郊庙歌辞 封泰山乐章 豫和 一','張說','quantangshi','','卷1','款泰坛，柴泰清。
