嘉祝信，大糦馨。
澹神心，醉皇灵。','',''),('quantangshi-00416','郊庙歌辞 封泰山乐章 豫和 三','張說','quantangshi','','卷1','相百辟，贡八荒。
九歌敍，万舞翔。
肃振振，铿皇皇。
帝欣欣，福穰穰。','',''),('quantangshi-00417','郊庙歌辞 封泰山乐章 豫和 四','張說','quantangshi','','卷1','高在上，道光明。
物资始，德难名。
承眷命，牧苍生。
寰宇谧，太阶平。','',''),('quantangshi-00418','郊庙歌辞 封泰山乐章 豫和 五','張說','quantangshi','','卷1','天道无亲，至诚与邻。
山川遍礼，宫征维新。
玉帛非盛，聪明会真。
正斯一德，通乎百神。','',''),('quantangshi-00419','郊庙歌辞 封泰山乐章 豫和 六','張說','quantangshi','','卷1','飨帝飨亲，维孝维圣。
缉熙懿德，敷扬成命。
华夷志同，笙镛礼盛。
明灵降止，感此诚敬。','',''),('quantangshi-00420','郊庙歌辞 封泰山乐章 太和','張說','quantangshi','','卷1','孝敬中发，和容外彰。
腾华照宇，如升太阳。
贞璧就奠，玄灵垂光。
礼乐具举，济济洋洋。','',''),('quantangshi-00421','郊庙歌辞 封泰山乐章 肃和','張說','quantangshi','','卷1','奠祖配天，承天享帝。
