璧玉宵备，旌旄曙立。
张乐以迎，帝神其入。','',''),('quantangshi-00473','郊庙歌辞 五郊乐章 送神','不詳','quantangshi','','卷1','文物流彩，声明动色。
人竭其恭，灵昭其饬。
歆荐不已，垂祯无极。
送礼有章，惟神还轼。','',''),('quantangshi-00474','郊庙歌辞 五郊乐章 赤郊迎神','不詳','quantangshi','','卷1','青阳节谢，朱明候改。
靡草雕华，含桃流彩。
虡列钟磬，筵陈脯醢。
乐以迎神，神其如在。','',''),('quantangshi-00475','郊庙歌辞 五郊乐章 送神','不詳','quantangshi','','卷1','炎精式降，苍生攸仰。
羞列豆笾，酒陈牺象。
昭祀有应，冥期不爽。
送乐张音，惟灵之往。','',''),('quantangshi-00476','郊庙歌辞 五郊乐章 白郊迎神','不詳','quantangshi','','卷1','序移玉律，节应金商。
天严杀气，吹警秋方。
槱燎既积，稷奠并芳。
乐以迎奏，庶降神光。','',''),('quantangshi-00477','郊庙歌辞 五郊乐章 送神','不詳','quantangshi','','卷1','祀遵五礼，时属三秋。
人怀肃敬，灵降祯休。
奠歆旨酒，荐享珍羞。
载张送乐，神其上游。','',''),('quantangshi-00478','郊庙歌辞 五郊乐章 黑郊迎神','不詳','quantangshi','','卷1','玄英戒序，黑郊临候。
掌礼陈彝，司筵执豆。
寒氛敛色，冱泉凝漏。
乐以迎神，八音斯奏。','',''),('quantangshi-00479','郊庙歌辞 五郊乐章 送神','不詳','quantangshi','','卷1','北郊时冽，南陆辉处。
奠本虔诚，献弥恭虑。
上延祉福，下承欢豫。
广乐送神，神其整驭。','',''),('quantangshi-00480','郊庙歌辞 朝日乐章 肃和','不詳','quantangshi','','卷1','惟圣格天，惟明飨日。
帝郊肆类，王宫戒吉。
圭奠春舒，钟歌晓溢。
礼云克备，斯文有秩。','',''),('quantangshi-00481','郊庙歌辞 朝日乐章 雍和','不詳','quantangshi','','卷1','晨仪式荐，明祀惟光。
神物爰止，灵晖载扬。
玄端肃事，紫幄兴祥。
福履攸假，于昭允王。','',''),('quantangshi-00482','郊庙歌辞 朝日乐章 舒和','不詳','quantangshi','','卷1','崇牙树羽延调露，旋宫扣律掩承云。
诞敷懿德昭神武，载集丰功表睿文。','',''),('quantangshi-00483','郊庙歌辞 朝日乐章 迎神','不詳','quantangshi','','卷1','太阳朝序，王宫有仪。
蟠桃彩驾，细柳光驰。
轩祥表合，汉历彰奇。
礼和乐备，神其降斯。','',''),('quantangshi-00484','郊庙歌辞 朝日乐章 送神','不詳','quantangshi','','卷1','五齐兼酌，百羞具陈。
乐终广奏，礼毕崇禋。
明鉴万宇，照临兆人。
永流洪庆，式动曦轮。','',''),('quantangshi-00485','郊庙歌辞 夕月乐章 肃和','不詳','quantangshi','','卷1','测妙为神，通微曰圣。
坎祀贻则，郊禋展敬。
璧荐登光，金歌动映。
以载嘉德，以流曾庆。','',''),('quantangshi-00486','郊庙歌辞 夕月乐章 雍和','不詳','quantangshi','','卷1','朏晨争举，天宗礼辟。
夜典凉秋，阴明湛夕。
有𨣧斯旨，有牲斯硕。
穆穆其晖，穰穰是积。','',''),('quantangshi-00487','郊庙歌辞 夕月乐章 舒和','不詳','quantangshi','','卷1','合吹八风金奏动，分容万舞玉鞘惊。
词昭茂典光前列，夕曜乘功表盛明。','',''),('quantangshi-00488','郊庙歌辞 祀九宫贵神乐章 豫和 一','不詳','quantangshi','','卷1','于昭上穹，临下有光。
羽翼五佐，周流八荒。
谁其飨之，时文对敭。
虞经夏典，兹礼未遑。','',''),('quantangshi-00489','郊庙歌辞 祀九宫贵神乐章 豫和 二','不詳','quantangshi','','卷1','黑帝旋驭，青躔导日。
金箓上玄，玉堂初吉。
钩陈夕次，銮和先跸。
蔼蔼羣灵，昭昭咸秩。','',''),('quantangshi-00490','郊庙歌辞 祀九宫贵神乐章 豫和 三','不詳','quantangshi','','卷1','帝临中坛，受厘元神。
皇灵萃止，羽旄肃陈。
摄提运衡，招摇移轮。
光光宇宙，电耀雷震。','',''),('quantangshi-00491','郊庙歌辞 祀九宫贵神乐章 豫和 四','不詳','quantangshi','','卷1','夜如何其，明星煌煌。
天清容卫，露结坛场。
树羽幢幢，佩玉锵锵。
凝精驻目，瞻望神光。','',''),('quantangshi-00492','郊庙歌辞 祀九宫贵神乐章 豫和 五','不詳','quantangshi','','卷1','九位既肃，万灵毕会。
天门启扄，日驭飞盖。
焕兮棽离，傧兮暗霭。
如山之福，惟圣时对。','',''),('quantangshi-00493','郊庙歌辞 祀九宫贵神乐章 豫和 六','不詳','quantangshi','','卷1','崇崇泰坛，灵具临兮。
铿鍠大乐，振动心兮。
神之降矣，卿云郁兮。
神之至止，清风肃兮。','',''),('quantangshi-00494','郊庙歌辞 祀九宫贵神乐章 太和','不詳','quantangshi','','卷1','帝在灵坛，大明登光。
天回云粹，穆穆皇皇。
金奏九夏，圭陈八芗。
旷哉动植，如熙春阳。','',''),('quantangshi-00495','郊庙歌辞 祀九宫贵神乐章 肃和','不詳','quantangshi','','卷1','歌工既奏，神位既秩。
天符众星，运行太一。
声和十管，气应中律。
肃肃明廷，介兹元吉。','',''),('quantangshi-00496','郊庙歌辞 祀九宫贵神乐章 雍和','不詳','quantangshi','','卷1','俎豆有践，黄流在尊。
九宫之祀，三代莫存。
乐变六宫，坛开八门。
圣皇昭对，佑我黎元。','',''),('quantangshi-00497','郊庙歌辞 祀九宫贵神乐章 寿和','不詳','quantangshi','','卷1','时文哲后，肃事严禋。
馨我明德，享于贵神。
大庖载盈，旨酒斯醇。
精意所属，期于利人。','',''),('quantangshi-00498','郊庙歌辞 祀九宫贵神乐章 福和','不詳','quantangshi','','卷1','祀既云毕，明灵告旋。
礼洽和应，神歆福延。
动植咸若，阴阳不愆。
锡兹纯嘏，天子万年。','',''),('quantangshi-00499','郊庙歌辞 祀九宫贵神乐章 舒和','不詳','quantangshi','','卷1','羽龠既阕干戚陈，八音克谐六变新。
愉贵神兮般以乐，保皇祚兮万斯春。','',''),('quantangshi-00500','郊庙歌辞 祀九宫贵神乐章 凯安','不詳','quantangshi','','卷1','盛德陈万舞，威棱畅九垓。
风云交律候，日月丽昭回。
行庆休祥发，乘和春气来。
百神肃临享，荡荡天门开。','',''),('quantangshi-00501','郊庙歌辞 祀九宫贵神乐章 肃和','不詳','quantangshi','','卷1','精意严恭，明祠丰洁。
献酬既备，俎豆斯撤。
日丽天仪，风和乐节。
事光祀典，福覃有截。','',''),('quantangshi-00502','郊庙歌辞 祀九宫贵神乐章 豫和','不詳','quantangshi','','卷1','享申百礼，庆洽百灵。
上排阊阖，洞入杳冥。
奠玉高坛，燔柴广庭。
神之降福，万国咸宁。','',''),('quantangshi-00503','郊庙歌辞 祀风师乐章 迎神','包佶','quantangshi','','卷1','太皞御气，句芒肇功。
苍龙青旗，爰候祥风。
律以和应，神以感通。
鼎俎修蠁，时惟礼崇。','',''),('quantangshi-00504','郊庙歌辞 祀风师乐章 奠币登歌','包佶','quantangshi','','卷1','旨酒告絜，青苹应候。
礼陈瑶币，乐献金奏。
弹弦自昔，解冻惟旧。
仰瞻肸蠁，羣祥来凑。','',''),('quantangshi-00505','郊庙歌辞 祀风师乐章 迎俎酌献','包佶','quantangshi','','卷1','德盛昭临，迎拜巽方。
爰候发生，式荐馨香。
酌醴具举，工歌载扬。
神歆六律，恩降百祥。','',''),('quantangshi-00506','郊庙歌辞 祀风师乐章 亚献终献','包佶','quantangshi','','卷1','膋芗备，玉帛陈。
风动物，乐感神。
三献终，百神臻。
草木荣，天下春。','',''),('quantangshi-00507','郊庙歌辞 祀风师乐章 送神','包佶','quantangshi','','卷1','微穆敷华能应节，飘扬发彩宜行庆。
送迎灵驾神心享，跪拜灵坛礼容盛。
气和草木发萌芽，德畅禽鱼遂翔泳。
永望翠盖逐流云，自兹率土调春令。','',''),('quantangshi-00508','郊庙歌辞 祀雨师乐章 迎神','包佶','quantangshi','','卷1','陟降左右，诚达幽圜。
作解之功，乐惟有年。
云軿戾止，洒雾飘烟。
惟馨展礼，爰列豆笾。','',''),('quantangshi-00509','郊庙歌辞 祀雨师乐章 奠币登歌','包佶','quantangshi','','卷1','岁正朱明，礼布元制。
惟乐能感，与神合契。
阴雾离翍，灵驭摇裔。
膏泽之庆，期于稔岁。','',''),('quantangshi-00510','郊庙歌辞 祀雨师乐章 迎俎酌献','包佶','quantangshi','','卷1','阳开幽蛰，躬奉郁鬯。
礼备节应，震来灵降。
动植求声，飞沈允望。
时康气茂，惟神之贶。','',''),('quantangshi-00511','郊庙歌辞 祀雨师乐章 亚献终献','包佶','quantangshi','','卷1','奠既备，献将终。
神行令，瑞飞空。
迎干德，祈岁功。
乘烟燎，俨从风。','',''),('quantangshi-00512','郊庙歌辞 祀雨师乐章 送神','包佶','quantangshi','','卷1','整驾升车望寥廓，垂阴荐祉荡昏氛。
飨时灵贶僾如在，乐罢余声遥可闻。
饮福陈诚礼容备，撤俎终献曙光分。
跪拜临坛结空想，年年应节候油云。','',''),('quantangshi-00513','郊庙歌辞 祭方丘乐章 顺和','褚亮','quantangshi','','卷1','万方资以化，交泰属升平。
易从业惟简，得一道斯宁。
具仪光玉帛，送舞变咸英。
黍稷良非贵，明德信惟馨。','',''),('quantangshi-00514','郊庙歌辞 祭方丘乐章 肃和','褚亮','quantangshi','','卷1','至矣坤德，皇哉地只。
开元统纽，合大承规。
九宫肃列，六典相仪。
永言配命，长保无亏。','',''),('quantangshi-00515','郊庙歌辞 祭方丘乐章 雍和','褚亮','quantangshi','','卷1','柔而能方，直而能敬。
载厚以德，大亨以正。
有涤斯牷，有馨斯盛。
介兹景福，祚我休庆。','',''),('quantangshi-00516','郊庙歌辞 祭方丘乐章 舒和','褚亮','quantangshi','','卷1','玉币牲牷分荐享，羽旄干鏚遰成容。
一德惟宁两仪泰，三才保合四时邕。','',''),('quantangshi-00517','郊庙歌辞 祭方丘乐章 顺和','褚亮','quantangshi','','卷1','阴只协赞，厚载方贞。
牲币具举，箫管备成。
其礼惟肃，其德惟明。
神之听矣，式鉴虔诚。','',''),('quantangshi-00518','郊庙歌辞 武后大享拜洛乐章 昭和','不詳','quantangshi','','卷1','九玄眷命，三圣基隆。
奉承先旨，明台毕功。
宗祀展敬，冀表深衷。
永昌帝业，式播淳风。','',''),('quantangshi-00519','郊庙歌辞 武后大享拜洛乐章 致和','不詳','quantangshi','','卷1','神功不测兮运阴阳，包藏万宇兮孕八荒。
天符既出兮帝业昌，愿临明祀兮降祯祥。','',''),('quantangshi-00520','郊庙歌辞 武后大享拜洛乐章 咸和','不詳','quantangshi','','卷1','坎泽祠容备举，坤坛祭典爰申。
灵睠遥行祕躅，嘉贶荐委殊珍。
肃礼恭禋载展，翘襟邈志逾殷。
方期交际悬应。','',''),('quantangshi-00521','郊庙歌辞 武后大享拜洛乐章 九和','不詳','quantangshi','','卷1','祗荷坤德，钦若干灵。
慙惕罔置，兴居匪宁。
恭崇礼则，肃奉仪形。
惟凭展敬，敢荐非馨。','',''),('quantangshi-00522','郊庙歌辞 武后大享拜洛乐章 显和','不詳','quantangshi','','卷1','菲躬承睿顾，薄德忝坤仪。
干干遵后命，翼翼奉先规。
抚俗勤虽切，还淳化尚亏。
未能弘至道，何以契明只。','',''),('quantangshi-00523','郊庙歌辞 武后大享拜洛乐章 显和','不詳','quantangshi','','卷1','顾德有慙虚菲，明只屡降祯符。
汜水初呈祕象，温洛荐表昌图。
玄泽流恩载洽，丹襟荷渥增愉。','',''),('quantangshi-00524','郊庙歌辞 武后大享拜洛乐章 昭和','不詳','quantangshi','','卷1','舒阴致养，合大资生。
德以恒固，功由永贞。
升歌荐序，垂币翘诚。
虹开玉照，凤引金声。','',''),('quantangshi-00525','郊庙歌辞 武后大享拜洛乐章 敬和','不詳','quantangshi','','卷1','兰俎既升，苹羞可荐。
金石载设，咸英已变。
林泽斯总，山川是遍。
敢用敷诚，实惟忘倦。','',''),('quantangshi-00526','郊庙歌辞 武后大享拜洛乐章 齐和','不詳','quantangshi','','卷1','沈潜演贶分三极，广大凝祯总万方。
既荐羽旌文化启，还呈干鏚武威扬。','',''),('quantangshi-00527','郊庙歌辞 武后大享拜洛乐章 德和','不詳','quantangshi','','卷1','夕惕司龙契，晨兢当凤扆。
崇儒习旧规，偃伯循先旨。
绝壤飞冠盖，遐区丽山水。
幸承三圣余，忻属千年始。','',''),('quantangshi-00528','郊庙歌辞 武后大享拜洛乐章 禋和','不詳','quantangshi','','卷1','百礼崇容，千官肃事。
灵降无兆，神凝有粹。
奠享咸周，威仪毕备。
奏夏登列，歌雍彻肆。','',''),('quantangshi-00529','郊庙歌辞 武后大享拜洛乐章 通和','不詳','quantangshi','','卷1','皇皇灵睠，穆穆神心。
暂动凝质，还归积阴。
功玄枢纽，理寂高深。
衔恩佩德，耸志翘襟。','',''),('quantangshi-00530','郊庙歌辞 武后大享拜洛乐章 归和','不詳','quantangshi','','卷1','言旋云洞兮蹑烟途，永宁中宇兮安下都。
包涵动植兮顺荣枯，长贻宝贶兮赞璇图。','',''),('quantangshi-00531','郊庙歌辞 武后大享拜洛乐章 又归和','不詳','quantangshi','','卷1','调云阕兮神座兴，骖云驾兮俨将升。
腾绛霄兮垂景佑，翘丹恳兮荷休征。','',''),('quantangshi-00532','郊庙歌辞 祭方丘乐章 顺和','不詳','quantangshi','','卷1','坤厚载物，德柔垂祉。
九域咸雍，四溟为纪。
敬因良节，虔修阴祀。
广乐式张，灵其降止。','',''),('quantangshi-00533','郊庙歌辞 祭方丘乐章 金奏','不詳','quantangshi','','卷1','坤元至德，品物资生。
神凝博厚，道协高明。
列镇五岳，环流四瀛。
于何不载，万宝斯成。','',''),('quantangshi-00534','郊庙歌辞 祭方丘乐章 顺和','不詳','quantangshi','','卷1','乐备金石，礼光尊俎。
大享爰终，洪休是举。
雨零感节，云飞应序。
缨绂载辞，皇灵具举。','',''),('quantangshi-00535','郊庙歌辞 祭汾阴乐章 顺和','林鍾宮','quantangshi','','卷1','大乐和畅，殷荐明神。
一降通感，八变必臻。
有求斯应，无德不亲。
降灵醉止，休征万人。','',''),('quantangshi-00536','郊庙歌辞 祭汾阴乐章 太簇角','盧從愿','quantangshi','','卷1','坤元载物，阳乐发生。
播殖资始，品汇咸亨。
列俎棋布，方坛砥平。
神歆禋祀，后德惟明。','',''),('quantangshi-00537','郊庙歌辞 祭汾阴乐章 姑洗征','劉晃','quantangshi','','卷1','大君出震，有事郊禋。
斋戒既肃，馨香毕陈。
乐和礼备，候暖风春。
恭惟降福，实赖明神。','',''),('quantangshi-00538','郊庙歌辞 祭汾阴乐章 南吕羽','韓休','quantangshi','','卷1','于穆浚哲，维清缉熙。
肃事昭配，永言孝思。
涤濯静嘉，馨香在兹。
神之听之，用受福厘。','',''),('quantangshi-00539','郊庙歌辞 祭汾阴乐章 太和','王晙','quantangshi','','卷1','于穆圣皇，六叶重光。
太原刻颂，后土疎场。
宝鼎呈符，歊云孕祥。
礼乐备矣，降福穰穰。','',''),('quantangshi-00540','郊庙歌辞 祭汾阴乐章 肃和','崔玄童','quantangshi','','卷1','聿修严配，展事禋宗。
祥符宝鼎，礼备黄琮。
[祝]词以信，明德惟聪。
介兹景福，永永无穷。','',''),('quantangshi-00541','郊庙歌辞 祭汾阴乐章 雍和','賈曾','quantangshi','','卷1','蠲我饎餴，絜我膋芗。
有豆孔硕，为羞既臧。
至诚无昧，精意惟芳。
神其醉止，欣欣乐康。','',''),('quantangshi-00542','郊庙歌辞 祭汾阴乐章 寿和','蘇頲','quantangshi','','卷1','礼物斯具，乐章乃陈。
谁其作主，皇考圣真。
对越在天，圣明佐神。
窅然汾上，厚泽如春。','',''),('quantangshi-00543','郊庙歌辞 祭汾阴乐章 舒和','何鸞','quantangshi','','卷1','乐奏云阕，礼章载虔。
禋宗于地，昭假于天。
惟馨荐矣，既醉歆焉。
神之降福，永永万年。','',''),('quantangshi-00544','郊庙歌辞 祭汾阴乐章 凯安','蔣挺','quantangshi','','卷1','维岁之吉，维辰之良。
圣君绂冕，肃事坛场。
大礼已备，大乐斯[张]。
神其醉止，降福无疆。','',''),('quantangshi-00545','郊庙歌辞 祭汾阴乐章 顺和','源光裕','quantangshi','','卷1','方丘既膳，嘉飨载谧。
齐敬毕诚，陶匏贵质。
秀毕丰荐，芳俎盈实。
永永福流，其升如日。','',''),('quantangshi-00546','郊庙歌辞 禅社首乐章 顺和','賀知章、源乾曜','quantangshi','','卷1','至哉含柔德，万物资以生。
常顺称厚载，流谦通变盈。
圣心事能察，增广陈厥诚。
黄只僾如在，泰折俟咸亨。','',''),('quantangshi-00547','郊庙歌辞 禅社首乐章 太和','賀知章、源乾曜','quantangshi','','卷1','肃我成命，于昭黄只。
裘冕而祀，陟降在斯。
五音克备，八音聿施。
缉熙肆靖，厥心匪离。','',''),('quantangshi-00548','郊庙歌辞 禅社首乐章 肃和','賀知章、源乾曜','quantangshi','','卷1','黄只是[祗]，我其夙夜。
寅畏诚絜，匪遑宁舍。
礼以琮玉，荐厥茅藉。
念兹降康，胡宁克暇。','',''),('quantangshi-00549','郊庙歌辞 禅社首乐章 雍和','賀知章、源乾曜','quantangshi','','卷1','夙夜宥密，不敢宁宴。
五齐既陈，八音在县。
粢盛以洁，房俎斯荐。
惟德惟馨，尚兹克徧。','',''),('quantangshi-00550','郊庙歌辞 禅社首乐章 寿和','賀知章、源乾曜','quantangshi','','卷1','惟以明发，有怀载殷。
乐盈而反，礼顺其禋。
立清以献，荐欲是亲。
于穆不已，裒对斯臻。','',''),('quantangshi-00551','郊庙歌辞 禅社首乐章 福和','賀知章、源乾曜','quantangshi','','卷1','穆穆天子，告成岱宗。
大裘如濡，执珽有颙。
乐以平志，礼以和容。
上帝临我，云胡肃邕。','',''),('quantangshi-00552','郊庙歌辞 禅社首乐章 太和','賀知章、源乾曜','quantangshi','','卷1','昭昭有唐，天俾万国。
列祖应命，四宗顺则。
申锡无疆，宗我同德。
曾孙继序，享神配极。','',''),('quantangshi-00553','郊庙歌辞 禅社首乐章 灵具醉','賀知章、源乾曜','quantangshi','','卷1','灵具醉，杳熙熙。
灵将往，眇禗禗。
顾明德，吐正辞。
烂遗光，流祯祺。','',''),('quantangshi-00554','郊庙歌辞 祭神州乐章 肃和','褚亮','quantangshi','','卷1','大矣坤仪，至哉神县。
包含日域，牢笼月竁。
露絜三清，风调六变。
皇只介祉，式歆恭荐。','',''),('quantangshi-00555','郊庙歌辞 祭神州乐章 雍和','褚亮','quantangshi','','卷1','泰折严享，阴郊展敬。
礼以导神，乐以和性。
黝牲在列，黄琮俯暎。
九土既平，万邦贻庆。','',''),('quantangshi-00556','郊庙歌辞 祭神州乐章 舒和','褚亮','quantangshi','','卷1','坤道降祥和庶品，灵心载德厚羣生。
水土既调三极泰，文武毕备九区平。','',''),('quantangshi-00557','郊庙歌辞 祭神州乐章 迎神','不詳','quantangshi','','卷1','黄舆厚载，赤寰归德。
含育九区，保安万国。
诚敬无怠，禋祀有则。
乐以迎神，其仪不忒。','',''),('quantangshi-00558','郊庙歌辞 祭神州乐章 送神','不詳','quantangshi','','卷1','神州阴祀，洪恩广济。
草树霑和，飞沈沐惠。
礼修鼎俎，奠歆瑶币。
送乐有章，灵轩其逝。','',''),('quantangshi-00559','郊庙歌辞 祭[太]社乐章 肃和','褚亮','quantangshi','','卷1','后土凝德，神功协契。
九域底平，两仪交际。
戊期应序，阴墉展币。
灵车少留，俯歆樽桂。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00560','郊庙歌辞 祭[太]社乐章 雍和','褚亮','quantangshi','','卷1','美报崇本，严恭展事。
受露疎坛，承风启地。
絜粢登俎，醇牺入馈。
介福远流，羣生毕遂。','',''),('quantangshi-00561','郊庙歌辞 祭[太]社乐章 舒和','褚亮','quantangshi','','卷1','神道发生敷九稼，阴极乘仁畅八埏。
纬武经文隆景化，登祥荐祉启丰年。','',''),('quantangshi-00562','郊庙歌辞 祭大社乐章 迎神','不詳','quantangshi','','卷1','烈山有子，后土有臣。
播种百谷，济育兆人。
春官缉礼，宗伯司禋。
戊为吉日，迎享兹辰。','',''),('quantangshi-00563','郊庙歌辞 祭大社乐章 送神','不詳','quantangshi','','卷1','吉祥式就，酬功载毕。
亲地尊天，礼文经术。
贶征令序，福流初日。
神驭爰归，祠官其出。','',''),('quantangshi-00564','郊庙歌辞 蜡百神乐章 肃和','不詳','quantangshi','','卷1','序迫岁阴，日躔星纪。
爰稽茂典，聿崇清祀。
绮币霞舒，瑞圭虹起。
百禩垂裕，万灵荐祉。','',''),('quantangshi-00565','郊庙歌辞 蜡百神乐章 雍和','不詳','quantangshi','','卷1','缇龠劲序，玄英晚候。
姬蜡开仪，豳歌入奏。
蕙馥雕俎，兰芬玉酎。
大享明只，永绥多佑。','',''),('quantangshi-00566','郊庙歌辞 蜡百神乐章 舒和','不詳','quantangshi','','卷1','经纬两仪文化洽，削平方域武功成。
瑶弦自乐干坤泰，玉鏚长欢区宇宁。','',''),('quantangshi-00567','郊庙歌辞 蜡百神乐章 迎神','不詳','quantangshi','','卷1','八蜡开祭，万物合祀。
上极天维，下穷坤纪。
鼎俎流芬，罇彝荐美。
有灵有只，咸希来止。','',''),('quantangshi-00568','郊庙歌辞 蜡百神乐章 送神','不詳','quantangshi','','卷1','十旬欢洽，一日祠终。
澄彝拂俎，报德酬功。
虑虔容肃，礼缛仪丰。
神其降祉，整驭随风。','',''),('quantangshi-00569','郊庙歌辞 享先农乐章 咸和','褚亮','quantangshi','','卷1','粒食伊始，农之所先。
古今攸赖，是曰人天。
耕斯帝籍，播厥公田。
式崇明祀，神其福焉。','',''),('quantangshi-00570','郊庙歌辞 享先农乐章 肃和','褚亮','quantangshi','','卷1','樽彝既列，瑚簋方荐。
歌工载登，币礼斯奠。
肃肃享祀，颙颙缨弁。
神之听之，福流寰县。','',''),('quantangshi-00571','郊庙歌辞 享先农乐章 雍和','褚亮','quantangshi','','卷1','前夕视牲，质明奉俎。
沐芳整弁，其仪式序。
盛礼毕陈，嘉乐备举。
歆我懿德，非馨稷黍。','',''),('quantangshi-00572','郊庙歌辞 享先农乐章 舒和','褚亮','quantangshi','','卷1','羽龠低昂文缀已，干戚蹈厉武行初。
望岁祈农神所听，延祥介福岂云虚。','',''),('quantangshi-00573','郊庙歌辞 享先农乐章 咸和','不詳','quantangshi','','卷1','三推礼就，万庾祈凝。
夤宾志远，藨衮惟兴。
降歆肃荐，垂佑祗膺。
送神有乐，神其上升。','',''),('quantangshi-00574','郊庙歌辞 享先蚕乐章 永和','不詳','quantangshi','','卷1','芳春开令序，韶苑畅和风。
惟灵申广佑，利物表神功。
绮会周天宇，黼黻藻寰中。
庶几承庆节，歆奠下帷宫。','',''),('quantangshi-00575','郊庙歌辞 享先蚕乐章 肃和','不詳','quantangshi','','卷1','明灵光至德，深功掩百神。
祥源应节启，福绪逐年新。
万宇承恩覆，七庙伫恭禋。
于兹申至恳，方期远庆臻。','',''),('quantangshi-00576','郊庙歌辞 享先蚕乐章 展敬','不詳','quantangshi','','卷1','霞庄列宝卫，云集动和声。
金卮荐绮席，玉币委芳庭。
因心罄丹款，先己励苍生。
所冀延明福，于兹享至诚。','',''),('quantangshi-00577','郊庙歌辞 享先蚕乐章 絜诚','不詳','quantangshi','','卷1','桂筵开玉俎，兰圃荐琼芳。
八音调凤历，三献奉鸾觞。
絜粢申大享，庭宇冀降祥。
神其覃有庆，契福永无疆。','',''),('quantangshi-00578','郊庙歌辞 享先蚕乐章 昭庆','不詳','quantangshi','','卷1','仙坛礼既毕，神驾俨将升。
伫属深祥起，方期庶绩凝。
虔诚资宇内，务本勖黎蒸。
灵心昭备享，率土洽休征。','',''),('quantangshi-00579','郊庙歌辞 释奠文宣王乐章 诚和','不詳','quantangshi','','卷1','圣道日用，神几不测。
金石以陈，弦歌载陟。
爰释其菜，匪馨于稷。
来顾来享，是宗是极。','',''),('quantangshi-00580','郊庙歌辞 释奠文宣王乐章 承和','不詳','quantangshi','','卷1','万国以贞光上嗣，三善茂德表重轮。
视膳寝门尊要道，高辟崇贤引正人。','',''),('quantangshi-00581','郊庙歌辞 释奠文宣王乐章 肃和','不詳','quantangshi','','卷1','粤惟上圣，有纵自天。
傍周万物，俯应千年。
旧章允着，嘉贽孔虔。
王化兹首，儒风是宣。','',''),('quantangshi-00582','郊庙歌辞 释奠文宣王乐章 雍和','不詳','quantangshi','','卷1','堂献瑶篚，庭敷璆县。
礼备其容，乐和其变。
肃肃亲享，雍雍执奠。
明德惟馨，苹蘩可荐。','',''),('quantangshi-00583','郊庙歌辞 释奠文宣王乐章 舒和','不詳','quantangshi','','卷1','隼集龟开昭圣烈，龙蹲凤跱肃神仪。
尊儒敬业宏图阐，纬武经文盛德施。','',''),('quantangshi-00584','郊庙歌辞 享孔子庙乐章 迎神','不詳','quantangshi','','卷1','通吴表圣，问老探真。
三千弟子，五百贤人。
亿龄规法，万载嗣禋。
洁诚以祭，奏乐迎神。','',''),('quantangshi-00585','郊庙歌辞 享孔子庙乐章 送神','不詳','quantangshi','','卷1','醴溢牺象，羞陈俎豆。
鲁壁类闻，泗川入觏。
里校覃福，胄筵承佑。
雅乐清音，送神具奏。','',''),('quantangshi-00586','郊庙歌辞 释奠武成王乐章 迎神','于邵','quantangshi','','卷1','卜畋不从，兆发非熊。
乃倾荒政，爰佐一戎。
盛烈载垂，命祀惟崇。
日练上戊，宿严閟宫。
迎奏嘉至，感而遂通。','',''),('quantangshi-00587','郊庙歌辞 释奠武成王乐章 奠币登歌','于邵','quantangshi','','卷1','管磬升，膻芗集。
上公进，嘉币执。
信以通，僾如及。
恢帝功，锡后邑。
四维张，百度立。
绵亿载，邈难挹。','',''),('quantangshi-00588','郊庙歌辞 释奠武成王乐章 迎俎酌献','于邵','quantangshi','','卷1','五齐洁，九牢硕。
梡橛循，罍斝涤。
进具物，扬鸿绩。
和奏发，高灵寂。
虔告终，繁祉锡。
昭秩祀，永无易。','',''),('quantangshi-00589','郊庙歌辞 释奠武成王乐章 亚献终献','于邵','quantangshi','','卷1','贰觞以献，三变其终。
顾此非馨，尚达斯衷。
茅缩可致，神歆载融。
始神翊周，拯溺除凶。
时维降佑，永绝兴戎。','',''),('quantangshi-00590','郊庙歌辞 释奠武成王乐章 送神','于邵','quantangshi','','卷1','明祀方终，备乐斯阕。
黝纁就瘗，豆笾告撤。
肸蠁尚余，光景云灭。
返归虚极，神心则悦。','',''),('quantangshi-00591','郊庙歌辞 享龙池乐章 第一章','姚崇','quantangshi','','卷1','恭闻帝里生灵沼，应报明君鼎业新。
既协翠泉光宝命，还符白水出真人。
此时舜海潜龙跃，此地尧河带马巡。
独有前池一小雁，叨承旧惠入天津。','',''),('quantangshi-00592','郊庙歌辞 享龙池乐章 第二章','蔡孚','quantangshi','','卷1','帝宅王家大道边，神马龙龟涌圣泉。
昔日昔时经此地，看来看去渐成川。
歌台舞榭宜正月，柳岸梅洲胜往年。
莫言波上春云少，祗为从龙直上天。','',''),('quantangshi-00593','郊庙歌辞 享龙池乐章 第三章','沈佺期','quantangshi','','卷1','龙池跃龙龙已飞，龙德[光]天天不违。
池开天汉分黄道，龙向天门入紫微。
邸第楼台多气色，君王凫雁有光辉。
为报寰中百川水，来朝此地莫东归。','',''),('quantangshi-00594','郊庙歌辞 享龙池乐章 第四章','盧懷慎','quantangshi','','卷1','代邸东南龙跃泉，清漪碧浪远浮天。
楼台影就波中出，日月光疑镜里悬。
雁沼回流成舜海，龟书荐祉应尧年。
大川既济慙为檝，报德空思奉细涓。','',''),('quantangshi-00595','郊庙歌辞 享龙池乐章 第五章','姜皎','quantangshi','','卷1','龙池初出此龙山，常经此地谒龙颜。
日日芙蓉生夏水，年年杨柳变春湾。
尧坛宝匣余烟雾，舜海渔舟尚往还。
愿似飘颻五云影，从来从去九天间。','',''),('quantangshi-00596','郊庙歌辞 享龙池乐章 第六章','崔日用','quantangshi','','卷1','龙兴白水汉兴符，圣主时乘运斗枢。
岸上丰茸五花树，波中的皪千金珠。
操环昔闻迎夏启，发匣先来瑞有虞。
风色云光随隐见，赤云神化象江湖。','',''),('quantangshi-00597','郊庙歌辞 享龙池乐章 第七章','蘇頲','quantangshi','','卷1','西京凤邸跃龙泉，佳气休光镇在天。
轩后雾图今已得，秦王水劒昔常传。
恩鱼不似昆明钓，瑞鹤长如太液仙。
愿侍巡游同旧里，更闻箫鼓济楼船。','',''),('quantangshi-00598','郊庙歌辞 享龙池乐章 第八章','李乂','quantangshi','','卷1','星分邑里四人居，水洊源流万顷余。
魏国君王称象处，晋家藩邸化龙初。
青蒲暂似游梁马，绿藻还疑宴镐鱼。
自有神灵滋液地，年年云物史官书。','',''),('quantangshi-00599','郊庙歌辞 享龙池乐章 第九章','姜皎','quantangshi','','卷1','灵沼萦回邸第前，浴日涵天写曙天。
始见龙台升凤阙，应如霄汉起神泉。
石匮渚傍还启圣，桃李初生更有仙。
欲化帝图从此受，正同河变一千年。','',''),('quantangshi-00600','郊庙歌辞 享龙池乐章 第十章','裴璀','quantangshi','','卷1','干坤启圣吐龙泉，泉水年年胜一年。
始看鱼跃方成海，即覩龙飞利在天。
洲渚遥将银汉接，楼台直与紫微连。
休气荣光常不散，悬知此地是神仙。','',''),('quantangshi-00601','郊庙歌辞 享太庙乐章 永和','魏徵、褚亮','quantangshi','','卷1','于穆烈祖，弘此丕基。
永言配命，子孙保之。
百神既洽，万国在兹。
是用孝享，神其格思。','',''),('quantangshi-00602','郊庙歌辞 享太庙乐章 肃和','魏徵、褚亮','quantangshi','','卷1','大哉至德，允兹明圣。
格于上下，聿遵诚敬。
嘉乐斯登，鸣球以咏。
神其降止，式隆景命。','',''),('quantangshi-00603','郊庙歌辞 享太庙乐章 雍和','魏徵、褚亮','quantangshi','','卷1','崇兹享祀，诚敬兼至。
乐以感灵，礼以昭事。
粢盛咸絜，牲牷孔备。
永言孝思，庶几不匮。','',''),('quantangshi-00604','郊庙歌辞 享太庙乐章 长发舞','魏徵、褚亮','quantangshi','','卷1','睿哲维唐，长发其祥。
帝命斯佑，王业克昌。
配天载德，就日重光。
本支百代，申锡无疆。','',''),('quantangshi-00605','郊庙歌辞 享太庙乐章 大基舞','魏徵、褚亮','quantangshi','','卷1','猗与祖业，皇矣帝先。
翦商德厚，封唐庆延。
在姬犹稷，方晋喻宣。
基我鼎运，于万斯年。','',''),('quantangshi-00606','郊庙歌辞 享太庙乐章 大成舞','魏徵、褚亮','quantangshi','','卷1','周称王季，晋美帝文。
明明盛德，穆穆齐芬。
藏用四履，屈道三分。
铿锵钟石，载纪鸿勋。','',''),('quantangshi-00607','郊庙歌辞 享太庙乐章 大明舞','魏徵、褚亮','quantangshi','','卷1','五纪更运，三正递升。
勋华既没，禹汤勃兴。
神武命代，灵睠是膺。
望云彰德，察纬告征。
上纽天维，下安地轴。
征师涿野，万国咸服。
偃伯灵台，九官允穆。
殊域委賮，怀生介福。
大礼既饰，大乐已和。
黑章扰囿，赤字浮河。
功宣载籍，德被咏歌。
克昌厥后，百禄是荷。','',''),('quantangshi-00608','郊庙歌辞 享太庙乐章 寿和','魏徵、褚亮','quantangshi','','卷1','八音斯奏，三献毕陈。
宝祚惟永，晖光日新。','',''),('quantangshi-00609','郊庙歌辞 享太庙乐章 舒和','魏徵、褚亮','quantangshi','','卷1','圣敬通神光七庙，灵心荐祚和万方。
严禋克配鸿基远，明德惟馨凤历昌。','',''),('quantangshi-00610','郊庙歌辞 享太庙乐章 雍和','魏徵、褚亮','quantangshi','','卷1','于穆清庙，聿修严祀。
四县载陈，三献斯止。
笾豆彻荐，人只介祉。
神维格思，锡祚不已。','',''),('quantangshi-00611','郊庙歌辞 享太庙乐章 永和','魏徵、褚亮','quantangshi','','卷1','肃肃清祀，烝烝孝思。
荐享昭备，虔恭在兹。
雍歌彻俎，祝嘏陈辞。
用光武志，永固鸿基。','',''),('quantangshi-00612','郊庙歌辞 享太庙乐章 崇德舞','不詳','quantangshi','','卷1','五运改卜，千龄启圣。
彤云晓聚，黄星夜映。
叶阐珠囊，基开玉镜。
下临万宇，上齐七政。
雾开三象，尘清九服。
海溓星晖，远安迩肃。
天地交泰，华夷辑睦。
翔泳归仁，中外禔福。
绩逾黜夏，勋高翦商。
武陈七德，刑设三章。
祥禽巢阁，仁兽游梁。
卜年惟永，景福无疆。','',''),('quantangshi-00613','郊庙歌辞 享太庙乐章 钧天[舞]','不詳','quantangshi','','卷1','承天抚箓，纂圣登皇。
遐清万宇，仰协三光。
功成日用，道济时康。
璇图载永，宝历斯昌。
日月扬晖，烟云烂色。
河岳修贡，神只効职。
舜风攸偃，尧曦先就。
睿感通寰，孝思浃宙。
奉扬先德，虔遵曩狩。
展义天扄，飞英云岫。
化逸王表，神凝帝先。
乘云厌俗，驭日登玄。','',''),('quantangshi-00614','郊庙歌辞 享太庙乐章 太和舞','不詳','quantangshi','','卷1','广乐既备，嘉荐既新。
述先惟德，孝飨惟亲。
七献具举，五齐毕陈。
锡兹祚福，于万斯春。','',''),('quantangshi-00615','郊庙歌辞 享太庙乐章 景云舞','不詳','quantangshi','','卷1','惟睿作圣，惟圣登皇。
精感耀魄，时膺会昌。
舜慙大孝，尧推让王。
能事斯极，振古谁方。
文明履运，车书同轨。
巍巍赫赫，尽善尽美。
衢室凝旒，大庭端扆。
释负之寄，事光复子。
脱屣高天，登遐上玄。
龙湖超忽，象野芊绵。
游衣复道，荐果初年。
新庙奕奕，明德配天。','',''),('quantangshi-00616','郊庙歌辞 享太庙乐章 光大舞','不詳','quantangshi','','卷1','大业龙祉，徽音骏尊。
潜居皇德，赫嗣天昆。
展仪宗祖，重诚孝孙。
春秋无极，享奏存存。','',''),('quantangshi-00617','郊庙歌辞 享太庙乐章 迎神','不詳','quantangshi','','卷1','七庙观德，百灵攸仰。
俗荷财成，物资含养。
道光执契，化笼提象。
肃肃雍雍，神其来飨。','',''),('quantangshi-00618','郊庙歌辞 享太庙乐章 金奏','不詳','quantangshi','','卷1','肃肃清庙，巍巍盛唐。
配天立极，累圣重光。
乐和管磬，礼备烝尝。
永惟来格，降福无疆。','',''),('quantangshi-00619','郊庙歌辞 享太庙乐章 送神','不詳','quantangshi','','卷1','五声备奏，三献终祠。
车移凤辇，斾转虹旗。
礼周笾豆，诚效虔祗。
皇灵徙跸，簪绅拜辞。','',''),('quantangshi-00620','郊庙歌辞 武后享清庙乐章十首 第一','不詳','quantangshi','','卷1','建清庙，赞玄功。
择吉日，展禋宗。
乐已变，礼方崇。
望神驾，降仙宫。','',''),('quantangshi-00621','郊庙歌辞 武后享清庙乐章十首 第二','不詳','quantangshi','','卷1','隆周创业，宝命惟新。
敬宗茂典，爰表虔禋。
声明已备，文物斯陈。
肃容如在，恳志方申。','',''),('quantangshi-00622','郊庙歌辞 武后享清庙乐章十首 第三登歌','不詳','quantangshi','','卷1','肃敷大礼，上谒尊灵。
敬[陈]筐币，载表丹诚。','',''),('quantangshi-00623','郊庙歌辞 武后享清庙乐章十首 第四迎神','不詳','quantangshi','','卷1','敬奠苹藻，式罄虔襟。
洁诚斯展，伫降灵歆。','',''),('quantangshi-00624','郊庙歌辞 武后享清庙乐章十首 第五饮福','不詳','quantangshi','','卷1','爰陈玉醴，式奠琼浆。
灵心有穆，介福无疆。','',''),('quantangshi-00625','郊庙歌辞 武后享清庙乐章十首 第六送文舞','不詳','quantangshi','','卷1','帝图草创，皇业初开。
功高佐命，业赞云雷。','',''),('quantangshi-00626','郊庙歌辞 武后享清庙乐章十首 第七迎武舞','不詳','quantangshi','','卷1','赫赫玄功被穹壤，皇皇至德洽生灵。
开基拨乱妖氛廓，佐命宣威海内清。','',''),('quantangshi-00627','郊庙歌辞 武后享清庙乐章十首 第八武舞作','不詳','quantangshi','','卷1','荷恩承顾托，执契恭临抚。
庙畧静边荒，天兵耀神武。','',''),('quantangshi-00628','郊庙歌辞 武后享清庙乐章十首 第九彻俎','不詳','quantangshi','','卷1','登歌已阕，献礼方周。
钦承景福，肃奉鸿休。','',''),('quantangshi-00629','郊庙歌辞 武后享清庙乐章十首 第十送神','不詳','quantangshi','','卷1','大礼言毕，仙卫将归。
莫申丹恳，空瞻紫微。','',''),('quantangshi-00630','郊庙歌辞 享太庙乐章 严和','不詳','quantangshi','','卷1','肃肃清庙，赫赫玄猷。
功高万古，化奄十洲。
中兴丕业，上荷天休。
祗奉先构，礼备怀柔。','',''),('quantangshi-00631','郊庙歌辞 享太庙乐章 升和','不詳','quantangshi','','卷1','顾惟菲薄，纂历应期。
中外同轨，夷狄来思。
乐用崇德，礼以陈词。
夕惕若厉，钦奉弘基。','',''),('quantangshi-00632','郊庙歌辞 享太庙乐章 虔和','不詳','quantangshi','','卷1','礼标荐鬯，肃事祠庭。
敬申如在，敢托非馨。','',''),('quantangshi-00633','郊庙歌辞 享太庙乐章 歆和','不詳','quantangshi','','卷1','崇禋已备，粢盛聿修。
洁诚斯展，钟石方遒。','',''),('quantangshi-00634','郊庙歌辞 享太庙乐章 承光舞','不詳','quantangshi','','卷1','金相载穆，玉裕重辉。
养德清禁，承光紫微。
干宫候色，震象增威。
监国方永，宾天不归。
孝友自衷，温文性与。
龙楼正启，鹤驾斯举。
丹扆流念，鸿名式序。
中兴考室，永陈彝俎。','',''),('quantangshi-00635','郊庙歌辞 享太庙乐章 延和','不詳','quantangshi','','卷1','巍巍累圣，穆穆重光。
奄有区夏，祚启隆唐。
百蛮饮泽，万国来王。
本枝亿载，鼎祚逾长。','',''),('quantangshi-00636','郊庙歌辞 享太庙乐章 同和','不詳','quantangshi','','卷1','惟圣配天敷盛礼，惟天为大阐洪名。
恭禋展敬光先德，苹藻申虔表志诚。','',''),('quantangshi-00637','郊庙歌辞 享太庙乐章 宁和','不詳','quantangshi','','卷1','炎驭失天纲，土德承天命。
英猷被寰宇，懿躅隆邦政。
七德已绥边，九夷咸底定。
景化覃遐迩，深仁洽翔泳。','',''),('quantangshi-00638','郊庙歌辞 享太庙乐章 恭和','不詳','quantangshi','','卷1','礼周三献，乐阕九成。
肃承灵福，悚惕兼盈。','',''),('quantangshi-00639','郊庙歌辞 享太庙乐章 通和','不詳','quantangshi','','卷1','祠容既毕，仙座爰兴。
停停凤举，霭霭云升。
长隆宝运，永锡休征。
福覃贻厥，恩被黎蒸。','',''),('quantangshi-00640','郊庙歌辞 享太庙乐章 昭和','不詳','quantangshi','','卷1','道洽二仪交泰，时休四宇和平。
环佩肃于庭实，钟石扬乎颂声。','',''),('quantangshi-00641','郊庙歌辞 享太庙乐章 诚敬','不詳','quantangshi','','卷1','顾惟菲质，忝位椒宫。
虔奉苹藻，肃事神宗。
敢申诚絜，庶罄深衷。
睟容有裕，灵享无穷。','',''),('quantangshi-00642','郊庙歌辞 享太庙乐章 肃和','不詳','quantangshi','','卷1','月礼已周，云和将变。
爰献其醑，载迁其奠。
明德逾隆，非馨是荐。
泽霑动植，仁覃宇县。','',''),('quantangshi-00643','郊庙歌辞 享太庙乐章 昭感','不詳','quantangshi','','卷1','铿锵韶濩，肃穆神容。
洪规赫赫，祠典雍雍。
已周三献，将乘六龙。
虔诚有托，恳志无从。','',''),('quantangshi-00644','郊庙歌辞 享太庙乐章 永和三章 一','張說','quantangshi','','卷1','肃九室，谐八音。
歌皇慕，动神心。
礼宿设，乐妙寻。
声明备，[裸]奠临。','',''),('quantangshi-00645','郊庙歌辞 享太庙乐章 永和三章 二','張說','quantangshi','','卷1','律迓气，音入玄。
依玉几，御黼筵。
聆忾息，僾周旋。
九韶遍，百福传。','',''),('quantangshi-00646','郊庙歌辞 享太庙乐章 永和三章 三','張說','quantangshi','','卷1','信工祝，永颂声。
来祖考，听和平。
相百辟，贡九瀛。
神休委，帝孝成。','',''),('quantangshi-00647','郊庙歌辞 享太庙乐章 太和','張說','quantangshi','','卷1','时文圣后，清庙肃邕。
致诚勤荐，在貌思恭。
玉节肆夏，金锵五钟。
绳绳云步，穆穆天容。','',''),('quantangshi-00648','郊庙歌辞 享太庙乐章 肃和','張說','quantangshi','','卷1','天子享孝，工歌溥将。
躬[裸]郁鬯，乃焚膋芗。
臭以达阴，声以求阳。
奉时烝尝，永代不忘。','',''),('quantangshi-00649','郊庙歌辞 享太庙乐章 雍和二章 一','張說','quantangshi','','卷1','在涤嘉豢，丽碑敬牲。
角握之牡，色纯之騂。
火传阳燧，水溉阴精。
太公胖俎，[傅]说和羹。','',''),('quantangshi-00650','郊庙歌辞 享太庙乐章 雍和二章 二','張說','quantangshi','','卷1','俎豆有馥，粢盛絜丰。
亦有和羹，既戒既平。
鼓钟管磬，肃唱和鸣。
皇皇后祖，来我思成。','',''),('quantangshi-00651','郊庙歌辞 享太庙乐章 文舞','張說','quantangshi','','卷1','圣謩九德，真言五千。
庆集昌胄，符开帝先。
高文杖钺，克配彼天。
三宗握镜，六合涣然。
帝其承祀，率礼罔愆。
图书雾出，日月清悬。
舞形德类，咏谂功传。
黄龙蜿蟮，彩云蹁跹。
五行气顺，八佾风宣。
介此百禄，于皇万年。','',''),('quantangshi-00652','郊庙歌辞 享太庙乐章 光大舞','張說','quantangshi','','卷1','肃肃艺祖，滔滔浚源。
有雄玉剑，作镇金门。
玄王贻绪，后稷谋孙。
肇禋九庙，四海来尊。','',''),('quantangshi-00653','郊庙歌辞 享太庙乐章 长发舞','張說','quantangshi','','卷1','具礼崇德，备乐承风。
魏推幢主，周赠司空。
不行而至，无成有终。
神兴王业，天归帝功。','',''),('quantangshi-00654','郊庙歌辞 享太庙乐章 大政舞','張說','quantangshi','','卷1','于赫元命，权舆帝文。
天齐八柱，地半三分。
宗庙观德，笙镛乐勋。
封唐之兆，成天下君。','',''),('quantangshi-00655','郊庙歌辞 享太庙乐章 大成舞','張說','quantangshi','','卷1','帝舞季历，龙圣生昌。
后歌有蟜，胎炎孕黄。
天地合德，日月齐光。
肃雝孝享，祚我万方。','',''),('quantangshi-00656','郊庙歌辞 享太庙乐章 大明舞','張說','quantangshi','','卷1','赤精乱德，四海困穷。
黄旗举义，三灵会同。
旱望春雨，云披大风。
溥天来祭，高祖之功。','',''),('quantangshi-00657','郊庙歌辞 享太庙乐章 崇德舞','張說','quantangshi','','卷1','皇合一德，朝宗百神。
削平天地，大拯生人。
上帝配食，单于入臣。
戎歌陈舞，晔晔震震。','',''),('quantangshi-00658','郊庙歌辞 享太庙乐章 钧天舞','張說','quantangshi','','卷1','高皇迈道，端拱无为。
化怀獯鬻，兵赋句骊。
礼尊封禅，乐盛来仪。
合位娲后，同称伏羲。','',''),('quantangshi-00659','郊庙歌辞 享太庙乐章 大和舞','張說','quantangshi','','卷1','退居江水，郁起丹陵。
礼物还旧，朝章中兴。
龙图友及，骏命恭膺。
鸣球香瓒，大糦是承。','',''),('quantangshi-00660','郊庙歌辞 享太庙乐章 景云舞','張說','quantangshi','','卷1','景云霏烂，告我帝符。
噫帝冲德，与天为徒。
笙镛遥远，俎豆虚无。
春秋孝献，回复此都。','',''),('quantangshi-00661','郊庙歌辞 享太庙乐章 福和','張說','quantangshi','','卷1','备礼用乐，崇亲致尊。
诚通慈降，敬彻爱存。
献怀称寿，啐感承恩。
皇帝孝德，子孙千亿。
大包天域，长亘不极。','',''),('quantangshi-00662','郊庙歌辞 享太庙乐章 舒和','張說','quantangshi','','卷1','六钟翕协六变成，八佾徜徉八风生。
乐九韶兮人神感，美七德兮天地清。','',''),('quantangshi-00663','郊庙歌辞 享太庙乐章 凯安四章 一','張說','quantangshi','','卷1','瑟彼瑶爵，亚惟上公。
室如屏气，门不容躬。
礼殷其本，乐执其中。
圣皇永慕，天地幽通。','',''),('quantangshi-00664','郊庙歌辞 享太庙乐章 凯安四章 二','張說','quantangshi','','卷1','礼匝三献，乐遍九成。
降循轩陛，仰欷皇情。
福与仁合，德因孝明。
百年[神畏]，四海风行。','',''),('quantangshi-00665','郊庙歌辞 享太庙乐章 凯安四章 三','張說','quantangshi','','卷1','总总干戚，填填鼓钟。
奋扬争气，坐作为容。
离若鸷鸟，合如战龙。
万方观德，肃肃雝雝。','',''),('quantangshi-00666','郊庙歌辞 享太庙乐章 凯安四章 四','張說','quantangshi','','卷1','烈祖顺三灵，文宗威四海。
黄钺诛羣盗，朱旗扫多罪。
戢兵天下安，约法人心改。
大哉干羽意，长见风云在。','',''),('quantangshi-00667','郊庙歌辞 享太庙乐章 登歌','張說','quantangshi','','卷1','止笙磬，撤豆笾。
廓无响，窅入玄。
主在室，神在天。
情余慕，礼罔愆。
喜黍稷，屡丰年。','',''),('quantangshi-00668','郊庙歌辞 享太庙乐章 永和','張說','quantangshi','','卷1','眇嘉乐，授灵爽。
感若来，思如往。
休气散，回风上。
返寂寞，还惚恍。
怀灵驾，结空想。','',''),('quantangshi-00669','郊庙歌辞 享太庙乐章 广运舞','郭子儀','quantangshi','','卷1','于赫皇祖，昭明有融。
惟文之德，惟武之功。
河海静谧，车书混同。
虔恭孝飨，穆穆玄风。','',''),('quantangshi-00670','郊庙歌辞 享太庙乐章 惟新舞','劉晏','quantangshi','','卷1','汉祚惟永，神功中兴。
风驱氛祲，天覆黎蒸。
三光再朗，庶绩其凝。
重熙累洽，景命是膺。','',''),('quantangshi-00671','郊庙歌辞 享太庙乐章 保大舞','郭子儀','quantangshi','','卷1','于穆文考，圣神昭章。
肃勺羣慝，含光远方。
万物茂遂，九夷宾王。
愔愔云韶，德音不忘。','',''),('quantangshi-00672','郊庙歌辞 享太庙乐章 文明舞','鄭餘慶','quantangshi','','卷1','开邸除暴，时迈勋尊。
三元告命，四极骏奔。
金枝翠叶，辉烛瑶琨。
象德亿载，贻庆汤孙。','',''),('quantangshi-00673','郊庙歌辞 享太庙乐章 大顺舞','鄭絪','quantangshi','','卷1','于穆时文，受天明命。
允恭玄默，化成理定。
出震嗣德，应干传圣。
猗欤缉熙，千亿流庆。','',''),('quantangshi-00674','郊庙歌辞 享太庙乐章 象德舞','段文昌','quantangshi','','卷1','肃肃清庙，登显至德。
泽周八荒，兵定四极。
生物咸遂，羣盗灭息。
明圣钦承，子孙千亿。','',''),('quantangshi-00675','郊庙歌辞 享太庙乐章 和宁舞','牛僧孺','quantangshi','','卷1','湜湜颀颀，融昭德辉。
不纽不舒，贯成九围。
武烈文经，敷施当宜。
纂尧付启，亿万熙熙。','',''),('quantangshi-00676','郊庙歌辞 享太庙乐章 大定舞','李回','quantangshi','','卷1','受天明命，敷佑下土。
化时以俭，卫文以武。
氛消夷夏，俗臻往古。
亿万斯年，形于律吕。','',''),('quantangshi-00677','郊庙歌辞 享太庙乐章 宣宗室舞','夏侯孜','quantangshi','','卷1','于铄令主，圣祚重昌。
兴起教义，申明典章。
俗尚素朴，人皆乐康。
积德可报，流庆无疆。','',''),('quantangshi-00678','郊庙歌辞 懿宗室舞','蕭倣','quantangshi','','卷1','圣祚无疆，庆传乐章。
金枝繁茂，玉叶延长。
海渎常[晏]，波涛不扬。
汪汪美化，垂范今王。','',''),('quantangshi-00679','郊庙歌辞 享太庙乐章 咸宁舞','不詳','quantangshi','','卷1','于铄丕嗣，惟帝之光。
羽龠象德，金石荐祥。
圣系无极，景命永昌。
神降上哲，维天配长。','',''),('quantangshi-00680','郊庙歌辞 太清宫乐章 煌煌','不詳','quantangshi','','卷1','煌煌道宫，肃肃太清。
礼光尊祖，乐备充庭。
罄竭诚至，希夷降灵。
云凝翠盖，风焰红旌。
众真以从，九奏初迎。
永惟休佑，是锡和平。','',''),('quantangshi-00681','郊庙歌辞 太清宫乐章 冲和','不詳','quantangshi','','卷1','虚无结思，钟磬和音。
歌以颂德，香以达心。
礼殊裸鬯，义感昭临。
云车至止，庆垂愔愔。','',''),('quantangshi-00682','郊庙歌辞 太清宫乐章 香初上','不詳','quantangshi','','卷1','肃肃我祖，緜緜道宗。
至感潜达，灵心暗通。
云軿御气，芝盖随风。
四时禋祀，万国来同。','',''),('quantangshi-00683','郊庙歌辞 太清宫乐章 再上','不詳','quantangshi','','卷1','仙宗绩道，我李承天。
庆深虚极，符光象先。
俗登仁寿，化阐蟮涓。
五千贻范，亿万斯年。','',''),('quantangshi-00684','郊庙歌辞 太清宫乐章 终上','不詳','quantangshi','','卷1','不宰元功，无为上圣。
洪源长发，诞受天命。
金奏迎真，璇宫展盛。
备礼周乐，垂光储庆。','',''),('quantangshi-00685','郊庙歌辞 太清宫乐章 紫极舞','不詳','quantangshi','','卷1','至道生元气，重圆法混成。
无为观大象，冲用体常名。
仙乐临丹阙，云车出玉京。
灵符百代应，瑞节九贞迎。
宝运开皇极，天临映太清。
长垂一德庆，永庇万方宁。','',''),('quantangshi-00686','郊庙歌辞 太清宫乐章 序入破第一奏','不詳','quantangshi','','卷1','真宗开妙理，冲教统清虚。
化演无为日，言昭有象初。
瑶台肃灵瑞，金阙映仙居。
一奏三清乐，长回八景舆。','',''),('quantangshi-00687','郊庙歌辞 太清宫乐章 序入破第二奏','不詳','quantangshi','','卷1','虚极仙宗本，希夷象帝先。
百灵朝太上，万法祖重圆。
善贷惟冲德，功成谓自然。
云门达和气，思用合钧天。','',''),('quantangshi-00688','郊庙歌辞 太清宫乐章 序入破第三奏','不詳','quantangshi','','卷1','元符传紫极，宝祚启高真。
道德先垂裕，冲和已化淳。
人风齐太古，天瑞叶惟新。
仙乐清都上，长明交泰辰。','',''),('quantangshi-00689','郊庙歌辞 太清宫乐章 登歌','不詳','quantangshi','','卷1','严禋展事，理洁烝尝。
皇矣圣祖，德惟馨香。
盛荐既撤，工歌载扬。
大来之庆，降福穰穰。','',''),('quantangshi-00690','郊庙歌辞 太清宫乐章 真和','不詳','quantangshi','','卷1','玉磬含香，金炉既馥。
风驭泠泠，云坛肃肃。
杳归大象，霈流嘉福。
俾宁万邦，无思不服。','',''),('quantangshi-00691','郊庙歌辞 德明兴圣庙乐章 迎神','李舒','quantangshi','','卷1','元尊九德，佐尧光宅。
烈祖太宗，方周作伯。
响怀霜露，乐变金石。
白云清风，仿髴来格。','',''),('quantangshi-00692','郊庙歌辞 德明兴圣庙乐章 登歌奠币','李舒','quantangshi','','卷1','四时有典，百事来祭。
尊祖奉宗，严禋大帝。
礼先苍璧，奠币黝制。
于斯万年，熙成帝系。','',''),('quantangshi-00693','郊庙歌辞 德明兴圣庙乐章 迎俎','李舒','quantangshi','','卷1','盛牲实俎，涓选休成。
鼎煁阳燧，玉盥阴精。
有飶嘉豆，既和大羹。
侑以清乐，细齐人情。','',''),('quantangshi-00694','郊庙歌辞 德明兴圣庙乐章 德明酌献','李舒','quantangshi','','卷1','清庙奕奕，和乐雍雍。
器尊牺象，礼属宗公。
白水方裸，黄流在中。
谟明之德，万古清风。','',''),('quantangshi-00695','郊庙歌辞 德明兴圣庙乐章 兴圣酌献','李舒','quantangshi','','卷1','閟宫静谧，合乐周张。
泰尊始献，百末重觞。
震澹存诚，庶几迪尝。
遥源之祚，天汉灵长。','',''),('quantangshi-00696','郊庙歌辞 德明兴圣庙乐章 亚献终献','李舒','quantangshi','','卷1','惟清惟肃，靡闻靡见。
举备九成，俛终三献。
庆彰曼寿，胙彻嘉荐。
瘗玉埋牲，礼神斯徧。','',''),('quantangshi-00697','郊庙歌辞 德明兴圣庙乐章 送神','李舒','quantangshi','','卷1','元精回复，灵贶繁滋。
风洒兰路，云摇桂旗。
高丘缅邈，凉部逶迟。
瞻望靡及，缠绵永思。','',''),('quantangshi-00698','郊庙歌辞 仪坤庙乐章 永和','徐彥伯','quantangshi','','卷1','猗若清庙，肃肃荧荧。
国荐严祀，坤兴淑灵。
有几在室，有乐在庭。
临兹孝享，百禄惟宁。','',''),('quantangshi-00699','郊庙歌辞 仪坤庙乐章 金奏','不詳','quantangshi','','卷1','阴灵曜祉，轩曜降精。
祥符淑气，庆集柔明。
瑶俎既列，雕桐发声。
徽猷永远，比德皇英。','',''),('quantangshi-00700','郊庙歌辞 仪坤庙乐章 太和','丘說','quantangshi','','卷1','孝哉我后，冲乎乃圣。
道映重华，德辉文命。
慕深视箧，情殷抚镜。
万国移风，兆人承庆。','',''),('quantangshi-00701','郊庙歌辞 仪坤庙乐章 肃和','張齊賢','quantangshi','','卷1','裸圭既濯，郁鬯既陈。
画幕云举，黄流玉醇。
仪充献酌，礼盛众禋。
地察惟孝，愉焉飨亲。','',''),('quantangshi-00702','郊庙歌辞 仪坤庙乐章 雍和','鄭善玉','quantangshi','','卷1','酌郁既灌，芗萧方爇。
笾豆静器，簠簋芬飶。
鱼腊荐美，牲牷表洁。
是戢是将，载迎载列。','',''),('quantangshi-00703','郊庙歌辞 仪坤庙乐章 昭升','薛稷','quantangshi','','卷1','阳灵配德，阴魄昭升。
尧坛凤下，汉室龙兴。
俔天作对，前旒是凝。
化行南国，道盛西陵。
造舟集灌，无德而称。
我粢既絜，我醴既澄。
阴阴灵庙，光灵若凭。
德馨惟享，孝思烝烝。','',''),('quantangshi-00704','郊庙歌辞 仪坤庙乐章 坤贞','不詳','quantangshi','','卷1','干道既亨，坤元以贞。
肃雍攸在，辅佐斯成。
外睦九族，内光一庭。
克生睿哲，祚我休明。
钦若徽范，悠哉淑灵。
建兹清宫，于彼上京。
缩茅以献，絜秬惟馨。
实受其福，期乎亿龄。','',''),('quantangshi-00705','郊庙歌辞 仪坤庙乐章 寿和','徐堅','quantangshi','','卷1','于穆清庙，肃雍严祀。
合福受厘，介以繁[祉]。','',''),('quantangshi-00706','郊庙歌辞 仪坤庙乐章 舒和','胡雄','quantangshi','','卷1','送文迎武递参差，一始一终光圣仪。
四海生人歌有庆，千龄孝享肃无亏。','',''),('quantangshi-00707','郊庙歌辞 仪坤庙乐章 安和','劉子玄','quantangshi','','卷1','妙筭申帷幄，神谋及庙庭。
两阶文物备，七德武功成。
校猎长杨苑，屯军细柳营。
将军献凯入，歌舞溢重城。','',''),('quantangshi-00708','郊庙歌辞 仪坤庙乐章 雍和','員半千','quantangshi','','卷1','孝享云毕，惟彻有章。
云感玄羽，风凄素商。
瞻望神座，祗恋匪遑。
礼终乐阕，肃雍锵锵。','',''),('quantangshi-00709','郊庙歌辞 仪坤庙乐章 永和','祝欽明','quantangshi','','卷1','閟宫实实，清庙微微。
降格无象，馨香有依。
式昭纂庆，方融嗣徽。
明禋是享，神保聿归。','',''),('quantangshi-00710','郊庙歌辞 仪坤庙乐章 迎神','不詳','quantangshi','','卷1','月灵降德，坤元授光。
娥英比秀，任姒均芳。
瑶台荐祉，金屋延祥。
迎神有乐，歆此嘉芗。','',''),('quantangshi-00711','郊庙歌辞 仪坤庙乐章 送神','不詳','quantangshi','','卷1','玉帛仪大，金丝奏广。
灵应有孚，冥征不爽。
降彼休福，歆兹禋享。
送乐有章，神麾其上。','',''),('quantangshi-00712','郊庙歌辞 昭德皇后庙乐章 永和','不詳','quantangshi','','卷1','穆清庙，荐严禋。
昭礼备，和乐新。
望灵光，集元辰。
祚无极，享万春。','',''),('quantangshi-00713','郊庙歌辞 昭德皇后庙乐章 肃和','不詳','quantangshi','','卷1','诚心达，娱乐分。
升箫膋，郁氛氲。
茅既缩，鬯既薰。
后来思，福如云。','',''),('quantangshi-00714','郊庙歌辞 昭德皇后庙乐章 雍和','不詳','quantangshi','','卷1','我将我享，尽明而诚。
载芬黍稷，载涤牺牲。
懿矣元良，万邦以贞。
心乎爱敬，若覩容声。','',''),('quantangshi-00715','郊庙歌辞 昭德皇后庙乐章 坤元','不詳','quantangshi','','卷1','于穆先后，丽圣称崇。
母临万宇，道[被]六宫。
昌时协庆，理内成功。
殷荐明德，传芳国风。','',''),('quantangshi-00716','郊庙歌辞 昭德皇后庙乐章 寿和','不詳','quantangshi','','卷1','工祝致告，徽音不遐。
酒醴咸旨，馨香具嘉。
受厘献祉，永庆邦家。','',''),('quantangshi-00717','郊庙歌辞 昭德皇后庙乐章 舒和','不詳','quantangshi','','卷1','金枝羽部彻清歌，瑶台肃穆笙磬罗。
谐音遍响合明意，万类昭融灵应多。','',''),('quantangshi-00718','郊庙歌辞 昭德皇后庙乐章 凯安','不詳','quantangshi','','卷1','辰位列四星，帝功参十乱。
进贤勤内辅，扈跸清多难。
承天厚载均，并耀宵光璨。
留徽蔼前躅，万古披图焕。','',''),('quantangshi-00719','郊庙歌辞 昭德皇后庙乐章 雍和','不詳','quantangshi','','卷1','公尸既起，享礼载终。
称歌进彻，尽敬繇衷。
泽流惠下，大小咸同。','',''),('quantangshi-00720','郊庙歌辞 昭德皇后庙乐章 永和','不詳','quantangshi','','卷1','昭事终，幽享余。
移月御，返仙居。
璇庭寂，灵幄虚。
顾裴回，感皇储。','',''),('quantangshi-00721','郊庙歌辞 让皇帝庙乐章 迎神','李舒','quantangshi','','卷1','皇矣天宗，德先王季。
因心则友，克让以位。
爰命有司，式遵前志。
神其降灵，昭飨祀事。','',''),('quantangshi-00722','郊庙歌辞 让皇帝庙乐章 奠币','李舒','quantangshi','','卷1','惟帝时若，去而上仙。
祀用商舞，乐备宫悬。
白璧加荐，玄纁告虔。
子孙拜后，承兹吉蠲。','',''),('quantangshi-00723','郊庙歌辞 让皇帝庙乐章 迎俎','李舒','quantangshi','','卷1','祀盛体荐，礼协粢盛。
方周假庙，用鲁纯牲。
捧彻祗敬，击拊和鸣。
受厘归胙，既戒而平。','',''),('quantangshi-00724','郊庙歌辞 让皇帝庙乐章 酌献','李舒','quantangshi','','卷1','八音具举，三寿既盥。
洁兹宗彝，瑟彼圭瓒。
兰肴重错，椒醑飘散。
降胙维城，永为藩翰。','',''),('quantangshi-00725','郊庙歌辞 让皇帝庙乐章 亚献终献','李舒','quantangshi','','卷1','秩礼有序，和音既同。
九仪不忒，三揖将终。
孝感藩后，相维辟公。
四时之典，永永无穷。','',''),('quantangshi-00726','郊庙歌辞 让皇帝庙乐章 送神','李舒','quantangshi','','卷1','奠献已事，昏昕载分。
风摇雨散，灵卫絪緼。
龙驾帝服，上腾五云。
泮宫复閟，寂寞无闻。','',''),('quantangshi-00727','郊庙歌辞 享隐太子庙乐章 诚和','不詳','quantangshi','','卷1','道閟鹤关，运缠鸠里。
门集大命，俾歆嘉祀。
礼亚六瑚，诚殚二簋。
有诚颙若，神斯戾止。','',''),('quantangshi-00728','郊庙歌辞 享隐太子庙乐章 肃和','不詳','quantangshi','','卷1','岁肇春宗，干开震长。
瑶山既寂，戾园斯享。
玉肃其事，物昭其象。
弦诵成风，笙歌合响。','',''),('quantangshi-00729','郊庙歌辞 享隐太子庙乐章 雍和','不詳','quantangshi','','卷1','明典肃陈，神居邃启。
春伯联事，秋官相礼。
有来雍雍，登歌济济。
缅维主鬯，庶歆芳醴。','',''),('quantangshi-00730','郊庙歌辞 享隐太子庙乐章 舒和','不詳','quantangshi','','卷1','三县已判歌钟列，六佾将开羽鏚分。
尚想燕飞来蔽日，终疑鹤影降凌云。','',''),('quantangshi-00731','郊庙歌辞 享隐太子庙乐章 凯安','不詳','quantangshi','','卷1','天步昔将开，商郊初欲践。
抚戎金阵廓，贰极瑶图阐。
鸡戟遂崇仪，龙楼期好善。
弄兵隳震业，启圣隆嗣典。','',''),('quantangshi-00732','郊庙歌辞 隐太子庙乐章 迎神','不詳','quantangshi','','卷1','苍震有位，黄离蔽明。
江充祸结，戾据灾成。
衔冤昔痛，赠典今荣。
享灵有秩，奉乐以迎。','',''),('quantangshi-00733','郊庙歌辞 隐太子庙乐章 送神','不詳','quantangshi','','卷1','皇情悼往，祀议增设。
钟鼓铿锵，羽旄昭晰。
掌礼云备，司筵告彻。
乐以送神，灵其鉴阕。','',''),('quantangshi-00734','郊庙歌辞 享章怀太子庙乐章 迎神','不詳','quantangshi','','卷1','副君昭象，道应黄离。
铜楼备德，玉裕成规。
仙气霭霭，灵从师师。
前驱戾止，控鹤来仪。','',''),('quantangshi-00735','郊庙歌辞 享章怀太子庙乐章 登歌酌鬯','不詳','quantangshi','','卷1','忠孝本着，羽翼先成。
寝门昭德，驰道为程。
币帛有典，容卫无声。
司存既肃，庙享惟清。','',''),('quantangshi-00736','郊庙歌辞 享章怀太子庙乐章 迎俎酌献','不詳','quantangshi','','卷1','通三锡胤，明两承英。
太山比赫，伊水闻笙。
宗祧是寄，礼乐其亨。
嘉辰荐俎，以发声明。','',''),('quantangshi-00737','郊庙歌辞 享章怀太子庙乐章 送文舞迎武舞','不詳','quantangshi','','卷1','羽龠崇文礼以毕，干鏚奋武事将行。
用舍繇来其有致，壮志宣威乐太平。','',''),('quantangshi-00738','郊庙歌辞 享章怀太子庙乐章 武舞作','不詳','quantangshi','','卷1','绿林炽炎历，黄虞格有苗。
沙尘惊塞外，帷幄命嫖姚。
七德干戈止，三边云雾消。
宝祚长无极，歌舞盛今朝。','',''),('quantangshi-00739','郊庙歌辞 享懿德太子庙乐章 迎神','不詳','quantangshi','','卷1','甲观昭祥，画堂升位。
礼绝羣后，望尊储贰。
启诵慙德，庄丕掩粹。
伊浦凤翔，缑峰鹤至。','',''),('quantangshi-00740','郊庙歌辞 享懿德太子庙乐章 登歌酌鬯','不詳','quantangshi','','卷1','誉阐元储，寄崇明两。
玉裕虽晦，铜楼可想。
弦诵辍音，笙歌罢响。
币帛言设，礼容无爽。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00741','郊庙歌辞 享懿德太子庙乐章 迎俎酌献','不詳','quantangshi','','卷1','雍雍盛典，肃肃灵祠。
宾天有圣，对日无期。
飘颻羽服，掣曳云旗。
眷言主鬯，心乎怆兹。','',''),('quantangshi-00742','郊庙歌辞 享懿德太子庙乐章 送文舞迎武舞','不詳','quantangshi','','卷1','八音协奏陈金石，六佾分行整礼容。
沧溟赴海还称少，素月开轮即是重。','',''),('quantangshi-00743','郊庙歌辞 享懿德太子庙乐章 武舞作','不詳','quantangshi','','卷1','隋季昔云终，唐年初启圣。
纂戎将禁暴，崇儒更敷政。
威略静三边，仁恩覃万姓。','',''),('quantangshi-00744','郊庙歌辞 享节愍太子庙乐章 迎神','不詳','quantangshi','','卷1','储后望崇，元良寄切。
寝门是仰，驰道不绝。
仙袂云会，灵旗电晰。
煌煌而来，礼物攸设。','',''),('quantangshi-00745','郊庙歌辞 享节愍太子庙乐章 登歌酌鬯','不詳','quantangshi','','卷1','灼灼重明，仰承元首。
既贤且哲，惟孝与友。
惟孝虽遥，灵规不朽。
礼因诚致，备絜玄酒。','',''),('quantangshi-00746','郊庙歌辞 享节愍太子庙乐章 迎俎酌献','不詳','quantangshi','','卷1','嘉荐有典，至诚莫骞。
画梁云亘，雕俎星连。
乐器周列，礼容备宣。
依稀如在，若未宾天。','',''),('quantangshi-00747','郊庙歌辞 享节愍太子庙乐章 送文舞出迎武舞入','不詳','quantangshi','','卷1','邕邕阐化凭文德，赫赫宣威藉武功。
既执羽旄先拂吹，还持玉鏚更挥空。','',''),('quantangshi-00748','郊庙歌辞 享节愍太子庙乐章 武舞作','不詳','quantangshi','','卷1','武德谅雍雍，由来扫寇戎。
劒光挥作电，旗影列成虹。
雾廓三边静，波澄四海同。
睿图今已盛，相共舞皇风。','',''),('quantangshi-00749','郊庙歌辞 享文敬太子庙乐章 请神','許孟容','quantangshi','','卷1','觞牢具品，管磬有节。
祝道夤恭，神仪昭晰。
桐圭早贵，象辂追设。
声达乐成，降歆丰洁。','',''),('quantangshi-00750','郊庙歌辞 享文敬太子庙乐章 登歌','陳京','quantangshi','','卷1','歌以德发，声以乐贵。
乐善名存，追仙礼异。
鸾旌拱修，凤鸣合吹。
神听皇慈，仲月皆至。','',''),('quantangshi-00751','郊庙歌辞 享文敬太子庙乐章 迎俎酌献','馮伉','quantangshi','','卷1','撰日瞻景，诚陈乐张。
礼容秩秩，羽舞煌煌。
肃将涤濯，祗荐芬芳。
永锡繁祉，思深飨尝。','',''),('quantangshi-00752','郊庙歌辞 享文敬太子庙乐章 送文舞迎武舞','不詳','quantangshi','','卷1','干旄羽龠相亏蔽，一进一退殊行缀。
昔献三雍盛礼容，今陈六佾崇仪制。','',''),('quantangshi-00753','郊庙歌辞 享文敬太子庙乐章 亚献终献','崔邠','quantangshi','','卷1','醴齐泛尊彝，轩县动干戚。
入室僾如在，升阶虔所历。
奋疾合威容，定利舒皦绎。
方崇庙貌礼，永被君恩锡。','',''),('quantangshi-00754','郊庙歌辞 享文敬太子庙乐章 送神','張薦','quantangshi','','卷1','三献具举，九旗将旋。
追劳表德，罢享宾天。
风引仙管，堂虚画筵。
芳馨常在，瞻望悠然。','',''),('quantangshi-00755','郊庙歌辞 享惠昭太子庙乐章 请神','歸登','quantangshi','','卷1','嘉荐既陈，祀事孔明。
闲歌在堂，万舞在庭。
外则尽物，内则尽诚。
凤笙如闻，歌其洁精。','',''),('quantangshi-00756','郊庙歌辞 享惠昭太子庙乐章 登歌','杜羔','quantangshi','','卷1','因心克孝，位震遗芬。
宾天道茂，轸怀气分。
发祗乃祀，咳叹如闻。
二歌斯升，以咏德薰。','',''),('quantangshi-00757','郊庙歌辞 享惠昭太子庙乐章 迎俎酌献','李逢吉','quantangshi','','卷1','既洁酒醴，聿陈熟腥。
肃将震念，昭格储灵。
展矣礼典，薰然德馨。
愔愔管磬，亦具是听。','',''),('quantangshi-00758','郊庙歌辞 享惠昭太子庙乐章 送文舞出迎武舞入','孟簡','quantangshi','','卷1','喧喧金石容既缺，肃肃羽驾就行列。
缑山遗响昔所闻，庙庭进旅今攸设。','',''),('quantangshi-00759','郊庙歌辞 享惠昭太子庙乐章 亚献终献','裴度','quantangshi','','卷1','重轮始发祥，齿胄方兴学。
冥然升紫府，铿尔荐清乐。
奠斝致馨香，在庭纷羽龠。
礼成神既醉，仿髴缑山鹤。','',''),('quantangshi-00760','郊庙歌辞 享惠昭太子庙乐章 送神','王涯','quantangshi','','卷1','威仪毕陈，备乐将阕。
苞茅酒缩，膋萧香彻。
宫臣展事，肃雍在列。
迎精送往，厥鉴昭晰。','',''),('quantangshi-00761','郊庙歌辞 武后崇先庙乐章','不詳','quantangshi','','卷1','先德谦撝冠昔，严规节素超今。
奉国忠诚每竭，承家至孝纯深。
追崇惧乖尊意，显号恐玷徽音。
既迫王公屡请，方乃俯遂羣心。
有限无由展敬，奠醑每阙亲斟。
大礼虔申典册，苹藻敬荐翘襟。','',''),('quantangshi-00762','郊庙歌辞 襃德庙乐章 昭德','不詳','quantangshi','','卷1','道赫梧宫，悲盈蒿里。
爰赐徽烈，载敷嘉祀。
享洽四时，规陈二簋。
灵应昭格，神其戾止。','',''),('quantangshi-00763','郊庙歌辞 襃德庙乐章 进德','不詳','quantangshi','','卷1','涂山懿戚，妫汭崇姻。
祠筵肇启，祭典方申。
礼以备物，乐以感神。
用隆敦敍，载穆彝伦。','',''),('quantangshi-00764','郊庙歌辞 襃德庙乐章 襃德','不詳','quantangshi','','卷1','家着累仁，门昭积善。
瑶篚既列，金县式展。','',''),('quantangshi-00765','郊庙歌辞 襃德庙乐章 武舞作','不詳','quantangshi','','卷1','昭昭竹殿开，奕奕兰宫启。
懿范隆丹掖，殊荣辟朱邸。
六佾荐徽容，三簋陈芳醴。
万石覃贻厥，分圭崇祖禰。','',''),('quantangshi-00766','郊庙歌辞 襃德庙乐章 彰德','不詳','quantangshi','','卷1','名隆五岳，秩映三台。
严祠已备，[睟]影方回。','',''),('quantangshi-00767','舞曲歌辞 功成庆善乐舞词','不詳','quantangshi','','卷1','寿丘惟旧迹，酆邑乃前基。
粤余承累圣，悬弧亦在兹。
弱龄逢运改，提劒郁匡时。
指麾八荒定，怀柔万国夷。
梯山盛入欵，驾海亦来思。
单于陪武帐，日逐卫文㮰。
端扆朝四岳，无为任百司。
霜节明秋景，轻冰结水湄。
芸黄遍原隰，禾頴积京坻。
共乐还谯宴，欢此大风诗。','',''),('quantangshi-00768','舞曲歌辞 中和乐舞词','不詳','quantangshi','','卷1','芳岁肇佳节，物华当仲春。
干坤既昭泰，烟景含氤氲。
德浅荷玄贶，乐成思治人。
前庭列钟鼓，广殿延羣臣。
八卦随舞意，五音转曲新。
顾非咸池奏，庶协南风薰。
式宴礼所重，浃欢情必均。
同和谅在兹，万国希可亲。','',''),('quantangshi-00769','舞曲歌辞 凯乐歌辞 破阵乐','不詳','quantangshi','','卷1','受律辞元首，相将讨叛臣。
咸歌破阵乐，共赏太平人。','',''),('quantangshi-00770','舞曲歌辞 凯乐歌辞 应圣期','不詳','quantangshi','','卷1','圣德期昌运，雍熙万宇清。
干坤资化育，海岳共休明。
辟土欣耕稼，销戈遂偃兵。
殊方歌帝泽，执贽贺升平。','',''),('quantangshi-00771','舞曲歌辞 凯乐歌辞 贺圣欢','不詳','quantangshi','','卷1','四海皇风被，千年德水清。
戎衣更不着，今日告功成。','',''),('quantangshi-00772','舞曲歌辞 凯乐歌辞 君臣同庆乐','不詳','quantangshi','','卷1','主圣开昌历，臣忠奉大猷。
君看偃革后，便是太平秋。','',''),('quantangshi-00773','郊庙歌辞 梁郊祀乐章 庆和 一','趙光逢、張衮','quantangshi','','卷1','就阳位，升圆丘。
佩双玉，御大裘。
膺天命，拥神休。
万灵感，百禄遒。','',''),('quantangshi-00774','郊庙歌辞 梁郊祀乐章 庆和 二','趙光逢、張衮','quantangshi','','卷1','秉黄钺，建朱旗。
震八表，清二仪。
帝业显，王道夷。
受景命，启皇基。','',''),('quantangshi-00775','郊庙歌辞 梁郊祀乐章 庆和 三','趙光逢、張衮','quantangshi','','卷1','开九门，怀百神。
通肸蠁，接氤氲。
明粢荐，广乐陈。
奠嘉璧，燎芳薪。','',''),('quantangshi-00776','郊庙歌辞 梁郊祀乐章 庆和 四','趙光逢、張衮','quantangshi','','卷1','膺宝图，执左契。
德应天，圣飨帝。
荐表衷，荷灵惠。
寿万年，祚百世。','',''),('quantangshi-00777','郊庙歌辞 梁郊祀乐章 庆和 五','趙光逢、張衮','quantangshi','','卷1','惟德动天，有感必通。
秉兹一德，禋于六宗。
钦夤宝命，恭肃礼容。
来顾来享，永穆皇风。','',''),('quantangshi-00778','郊庙歌辞 梁郊祀乐章 庆和 六','趙光逢、張衮','quantangshi','','卷1','天惟佑德，辟乃奉天。
交感斯在，昭事罔愆。
岁功已就，王道无偏。
于焉报本，是用告虔。','',''),('quantangshi-00779','郊庙歌辞 梁郊祀乐章 庆顺','趙光逢、張衮','quantangshi','','卷1','圣皇戾止，天步舒迟。
干干睿相，穆穆皇仪。
进退必肃，陟降是祗。
六变克协，万灵协随。','',''),('quantangshi-00780','郊庙歌辞 梁郊祀乐章 庆平','趙光逢、張衮','quantangshi','','卷1','天命降鉴，帝德惟馨。
享祀不忒，礼容孔明。
奠璧布币，荐神献精。
神佑以答，敷锡永宁。','',''),('quantangshi-00781','郊庙歌辞 梁郊祀乐章 庆肃','趙光逢、張衮','quantangshi','','卷1','笾豆簠簋，黍稷非馨。
懿兹彝器，厥德惟明。
金石匏革，以和以平。
繇此无体，期乎永宁。','',''),('quantangshi-00782','郊庙歌辞 梁郊祀乐章 庆熙','趙光逢、張衮','quantangshi','','卷1','哲后躬享，旨酒斯陈。
王恭无斁，严祀维夤。
皇祖以配，大孝以振。
宜锡景福，永休下民。','',''),('quantangshi-00783','郊庙歌辞 梁郊祀乐章 庆隆','趙光逢、張衮','quantangshi','','卷1','恭祀上帝，于国之阳。
爵醴是荷，鸿基永昌。','',''),('quantangshi-00784','郊庙歌辞 梁郊祀乐章 庆融','趙光逢、張衮','quantangshi','','卷1','道和气兮袭氤氲，宣皇规兮彰圣神。
服遐裔兮敷质文，格苗扈兮息烟尘。','',''),('quantangshi-00785','郊庙歌辞 梁郊祀乐章 庆休','趙光逢、張衮','quantangshi','','卷1','大业来四夷，仁风和万国。
白日体无私，皇天辅有德。
七旬罪已服，六月师方克。
伟哉帝道隆，终始常作则。','',''),('quantangshi-00786','郊庙歌辞 梁郊祀乐章 庆和','趙光逢、張衮','quantangshi','','卷1','烟燎升，礼容彻。
诚感达，人神悦。
灵贶彰，圣情结。
玉座寂，金炉歇。','',''),('quantangshi-00787','郊庙歌辞 周郊祀乐章 昭顺乐','不詳','quantangshi','','卷1','五兵勿用，万国咸安。
告功圆盖，受命云坛。
乐鸣凤律，礼备鸡竿。
神光欲降，众目遐观。','',''),('quantangshi-00788','郊庙歌辞 周郊祀乐章 治顺乐','不詳','quantangshi','','卷1','羽卫离丹阙，金轩赴泰坛。
珠旗明月色，玉佩晓霜寒。
黼黻龙衣备，琮璜宝器完。
百神将受职，宗社保长安。','',''),('quantangshi-00789','郊庙歌辞 周郊祀乐章 感顺乐','不詳','quantangshi','','卷1','明君陈大礼，展币祀圆丘。
雅乐声其发，祥云色正浮。','',''),('quantangshi-00790','郊庙歌辞 周郊祀乐章 禋顺乐','不詳','quantangshi','','卷1','黄彝将献，特牲预迎。
既修昭事，潜达明诚。','',''),('quantangshi-00791','郊庙歌辞 周郊祀乐章 福顺乐','不詳','quantangshi','','卷1','相承五运，取法三才。
大礼爰展，率土咸来。
卿云祕室，甘泉宝台。
象樽初酌，受福不回。','',''),('quantangshi-00792','郊庙歌辞 周郊祀乐章 福顺乐','不詳','quantangshi','','卷1','昊天成命，邦国盛仪。
多士齐列，六龙载驰。
坛升泰一，乐奏咸池。
高明祚德，永致昌期。','',''),('quantangshi-00793','郊庙歌辞 周郊祀乐章 福顺乐','不詳','quantangshi','','卷1','上天垂景贶，哲后举鸾觞。
明德今方祚，邦家万世昌。','',''),('quantangshi-00794','郊庙歌辞 周郊祀乐章 忠顺乐','不詳','quantangshi','','卷1','木铎敷音文德昌，朱干成列武功彰。
雷鼗鹭羽今休用，玉鏚相参正发扬。','',''),('quantangshi-00795','郊庙歌辞 周郊祀乐章 武舞乐','不詳','quantangshi','','卷1','圭瓒方陈礼，干旄乃象功。
成文非羽龠，猛势若罴熊。','',''),('quantangshi-00796','郊庙歌辞 周郊祀乐章 昭顺乐','不詳','quantangshi','','卷1','云门孤竹，苍璧黄琮。
既祀天地，克配祖宗。
虔修盛礼，仰答玄功。
神归碧落，福降无穷。','',''),('quantangshi-00797','郊庙歌辞 梁太庙乐舞辞 开平舞','不詳','quantangshi','','卷1','黍稷馨，醴𨣧清。
牲牷洁，金石铿。
恭祀事，结皇情。
神来格，歌颂声。','',''),('quantangshi-00798','郊庙歌辞 梁太庙乐舞辞 皇帝行','不詳','quantangshi','','卷1','莫高者天，攀跻弗克。
隮天有方，累仁积德。
祖宗隆之，子孙履之。
配天明祀，永永孝思。','',''),('quantangshi-00799','郊庙歌辞 梁太庙乐舞辞 帝盥','不詳','quantangshi','','卷1','庄肃莅事，周旋礼容。
裸鬯严洁，穆穆雍雍。','',''),('quantangshi-00800','郊庙歌辞 梁太庙乐舞辞 登歌','不詳','quantangshi','','卷1','于赫我皇，建中立极。
动以武功，静以文德。
昭事上帝，欢心万国。
大报严禋，四海述职。','',''),('quantangshi-00801','郊庙歌辞 梁太庙乐舞辞 大合舞','不詳','quantangshi','','卷1','于穆皇祖，浚哲雍熙。
美溢中夏，化被南陲。
后稷累德，公刘创基。
肇兴九庙，乐合来仪。','',''),('quantangshi-00802','郊庙歌辞 梁太庙乐舞辞 象功舞','不詳','quantangshi','','卷1','天地合德，睿圣昭彰。
累赠太傅，俄登魏王。
雄名不朽，奕叶而光。
建国之兆，君临万方。','',''),('quantangshi-00803','郊庙歌辞 梁太庙乐舞辞 来仪舞','不詳','quantangshi','','卷1','于赫帝命，应天顺人。
亭育品汇，宾礼百神。
洪基永固，景命惟新。
肃恭孝享，祚我生民。','',''),('quantangshi-00804','郊庙歌辞 梁太庙乐舞辞 昭德舞','不詳','quantangshi','','卷1','肃肃文考，源浚派长。
汉称诞季，周实生昌。
奄有四海，超彼百王。
笙镛迭奏，礼物荧煌。','',''),('quantangshi-00805','郊庙歌辞 梁太庙乐舞辞 饮福','不詳','quantangshi','','卷1','戛玉摐金永颂声，檿丝孤竹和且清。
灵歆醉止牺象盈，自天降福千万龄。','',''),('quantangshi-00806','郊庙歌辞 梁太庙乐舞辞 撤豆','不詳','quantangshi','','卷1','笙镛洋洋，庭燎煌煌。
明星有烂，祝史下堂。
[笾]豆斯撤，礼容有章。
克勤克俭，无怠无荒。','',''),('quantangshi-00807','郊庙歌辞 梁太庙乐舞辞 送神','不詳','quantangshi','','卷1','其降无从，其往无踪。
黍稷非馨，有感必通。
赫奕令德，仿髴睟容。
再拜慌忽，遐想昊穹。','',''),('quantangshi-00808','郊庙歌辞 后唐宗庙乐舞辞 昭德舞','崔居儉、盧文紀','quantangshi','','卷1','懿彼明德，赫赫煌煌。
名高阃域，功着旗常。
道符休泰，运叶祺祥。
庆传万祀，以播耿光。','',''),('quantangshi-00809','郊庙歌辞 后唐宗庙乐舞辞 文明舞','崔居儉、盧文紀','quantangshi','','卷1','帝业光扬，皇图翕赫。
圣德孔彰，神功不测。
信及豚鱼，恩霑动植。
懿范鸿名，传之万亿。','',''),('quantangshi-00810','郊庙歌辞 后唐宗庙乐舞辞 应天舞','崔居儉、盧文紀','quantangshi','','卷1','晋国肇兴，雄图再固。
黼黻帝道，金玉王度。
皇天无亲，惟德是辅。
载诞英明，永光圣祚。','',''),('quantangshi-00811','郊庙歌辞 后唐宗庙乐舞辞 永平舞','崔居儉、盧文紀','quantangshi','','卷1','庆传瓒祚，位正瑶图。
功宣四海，化被八区。
静彰帝道，动合干符。
千秋万祀，永荷昭苏。','',''),('quantangshi-00812','郊庙歌辞 后唐宗庙乐舞辞 武成舞','崔居儉、盧文紀','quantangshi','','卷1','艰难王业，返正皇唐。
先天再造，却日重光。
汉绍世祖，夏资少康。
功成德茂，率祀无疆。','',''),('quantangshi-00813','郊庙歌辞 后唐宗庙乐舞辞 雍煕舞','崔居儉、盧文紀','quantangshi','','卷1','仁君御宇，寰海谧清。
运符武德，道协文明。
九成式敍，百度惟贞。
金门积庆，玉叶传荣。','',''),('quantangshi-00814','郊庙歌辞 汉宗庙乐舞辞 武德舞','張昭','quantangshi','','卷1','明明我祖，天集休明。
神母夜哭，彤云昼兴。
笾豆有践，管龠斯登。
孝孙致告，神其降灵。','',''),('quantangshi-00815','郊庙歌辞 汉宗庙乐舞辞 灵长舞','張昭','quantangshi','','卷1','天降祥，汉祚昌。
火炎上，水灵长。
建庙社，洁蒸尝。
罗钟石，俨珩璜。
陈玉豆，酌金觞。
气昭感，德馨香。
祗洛汭，瞻晋阳。
降吾祖，福穰穰。','',''),('quantangshi-00816','郊庙歌辞 汉宗庙乐舞辞 积善舞','張昭','quantangshi','','卷1','黍稷斯馨，祖德惟明。
蛇告赤帝，龟谋大横。
云行雨施，天成地平。
造我家邦，斡我璇衡。
陶匏在御，醍盎惟精。
或戛或击，载炮载烹。
饮福受胙，舞降歌迎。
滔滔不竭，洪惟水行。','',''),('quantangshi-00817','郊庙歌辞 汉宗庙乐舞辞 显仁舞','張昭','quantangshi','','卷1','运极金行谢，天资水德隆。
礼神鄜畤馆，布政未央宫。
诘旦备明祀，登歌答茂功。
云轩临降久，星俎荐陈丰。
霭霭沈檀雾，铿锵环佩风。
荧煌升藻藉，肸蠁转珠栊。
尊祖咸韶备，贻孙书轨同。
京坻长有积，宗社享无穷。','',''),('quantangshi-00818','郊庙歌辞 汉宗庙乐舞辞 章庆舞','張昭','quantangshi','','卷1','罘罳晓唱鸡人，三牲八簋斯陈。
雾集瑶阶琐闼，香生绮席华茵。
珠佩貂璫熠爚，羽旄干戚纷纶。
酌鬯既终三献，凝旒何止千春。
阿阁长栖彩凤，郊宫叠奏祥麟。
赤伏英灵未泯，玄圭运祚重新。
玉斝牺樽潋滟，龙旗凤辖逡巡。
瞻望月游冠冕，犹疑苍野回轮。','',''),('quantangshi-00819','郊庙歌辞 汉宗庙乐舞辞 观德舞','張昭','quantangshi','','卷1','高庙明灵再启图，金根玉辂幸神都。
巢阿丹凰衔书命，入昴飞星献宝符。
正换熏弦娱赤子，忽登仙驾泣苍梧。
荐樱鹤馆笳箫咽，酌鬯金楹劒佩趋。
星俎云罍兼鲁礼，朱干象箾杂巴渝。
氤氲龙麝交青琐，仿髴[锡]銮下蘂珠。
荐豆奉觞亲玉几，配天合祖耀璇枢。
受厘饮酒皇欢洽，仰俟余灵泰九区。','',''),('quantangshi-00820','郊庙歌辞 周宗庙乐舞辞 肃顺','不詳','quantangshi','','卷1','我后至孝，祗谒祖先。
仰瞻庙貌，夙设宫悬。
朱弦疏越，羽舞回旋。
神其来格，明祀惟虔。','',''),('quantangshi-00821','郊庙歌辞 周宗庙乐舞辞 治顺','不詳','quantangshi','','卷1','清庙将入，衮服是依。
载行载止，令行令仪。
永终就养，空极孝思。
瞻望如在，顾复长违。','',''),('quantangshi-00822','郊庙歌辞 周宗庙乐舞辞 肃雍舞','不詳','quantangshi','','卷1','周道载兴，象日之明。
万邦咸庆，百谷用成。
于穆圣祖，祗荐鸿名。
祀于庙社，陈其牺牲。
进旅退旅，皇武之形。
一倡三叹，朱弦之声。
以妥以侑，既和且平。
至诚潜达，介福攸宁。','',''),('quantangshi-00823','郊庙歌辞 周宗庙乐舞辞 章德舞','不詳','quantangshi','','卷1','清庙新，展严禋。
恭祖德，厚人伦。
雅乐荐，礼器陈。
俨皇尸，列虞宾。
神如在，声不闻。
享必信，貌惟夤。
想龙服，奠牺樽。
礼既备，庆来臻。','',''),('quantangshi-00824','郊庙歌辞 周宗庙乐舞辞 善庆舞','不詳','quantangshi','','卷1','卜世长，帝祚昌。
定中国，服四方。
修明祀，从旧章。
奏激楚，转清商。
罗俎豆，列簪裳。
歌累累，容皇皇。
望来格，降休祥。
祝敢告，寿无疆。','',''),('quantangshi-00825','郊庙歌辞 周宗庙乐舞辞 观成舞','不詳','quantangshi','','卷1','穆穆王国，奕奕神功。
毖祀载展，明德有融。
彝樽斯满，簠簋斯丰。
纷絺旄羽，锵洋磬钟。
或升或降，克和克同。
孔惠之礼，必肃之容。
锡以纯嘏，祚其允恭。
神保是飨，万世无穷。','',''),('quantangshi-00826','郊庙歌辞 周宗庙乐舞辞 明德舞','不詳','quantangshi','','卷1','惟彼岐阳，德大流光。
载造周室，泽及遐荒。
于铄圣祖，上帝是皇。
乃圣乃神，知微知彰。
新庙奕奕，丰年穰穰。
取彼血膋，以往蒸尝。
黍稷惟馨，笾豆大房。
工祝致告，受福无疆。','',''),('quantangshi-00827','郊庙歌辞 周宗庙乐舞辞 咸顺','不詳','quantangshi','','卷1','万舞咸列，三阶克清。
贯珠一倡，击石九成。
盈觞虽酌，灵坐无形。
永怀我祖，达其孝诚。','',''),('quantangshi-00828','郊庙歌辞 周宗庙乐舞辞 禋顺','不詳','quantangshi','','卷1','旨酒既献，嘉肴乃迎。
振其鼗鼓，洁以铏羹。
肇禋肇祀，或炮或烹。
皇尸俨若，保飨是明。','',''),('quantangshi-00829','郊庙歌辞 周宗庙乐舞辞 福顺','不詳','quantangshi','','卷1','新庙奕奕，金奏洋洋。
享于祖考，循彼典章。
清酤特满，嘉玉腾光。
神醉既告，帝祉无疆。','',''),('quantangshi-00830','郊庙歌辞 周宗庙乐舞辞 忠顺','不詳','quantangshi','','卷1','称文既表温柔德，示武须成蹈厉容。
缀兆疾舒皆应节，明明我祖乐无穷。','',''),('quantangshi-00831','郊庙歌辞 善胜舞','不詳','quantangshi','','卷1','圣祖累功，福钟来裔。
持羽执干，舞文不废。','',''),('quantangshi-00832','郊庙歌辞 禋顺','不詳','quantangshi','','卷1','礼毕祀先，香散几筵。
罢舞干戚，收撤豆笾。','',''),('quantangshi-00833','郊庙歌辞 肃顺','不詳','quantangshi','','卷1','乐奏四顺，福受万年。
神归碧天，庭余瑞烟。','',''),('quantangshi-00834','郊庙歌辞 晋朝飨乐章 初举酒文同乐','不詳','quantangshi','','卷1','赫矣昌运，明哉圣王。
文兴坠典，礼复旧章。
鸳鸾济济，鸟兽跄跄。
一人有庆，万福无疆。','',''),('quantangshi-00835','郊庙歌辞 晋朝飨乐章 举酒','不詳','quantangshi','','卷1','大明御宇，至德动天。
君臣庆会，礼乐昭宣。
劒佩成列，金石在县。
椒觞再献，宝历万年。','',''),('quantangshi-00836','郊庙歌辞 晋朝飨乐章 再举酒','不詳','quantangshi','','卷1','朝野无事，寰瀛大康。
圣人有作，盛礼重光。
万国执玉，千官奉觞。
南山永固，地久天长。','',''),('quantangshi-00837','郊庙歌辞 晋朝飨乐章 四举酒','不詳','quantangshi','','卷1','八表欢无事，三秋贺有成。
照临同日远，渥泽并云行。
河变千年色，山呼万岁声。
愿修封岱礼，方以称文明。','',''),('quantangshi-00838','郊庙歌辞 晋朝飨乐章 羣臣酒行歌 一','不詳','quantangshi','','卷1','劒佩俨如林，齐倾拱北心。
渥恩颁美禄，咸濩听和音。
一德君臣合，重瞳日月临。
歌时兼乐圣，唯待赞泥金。','',''),('quantangshi-00839','郊庙歌辞 晋朝飨乐章 羣臣酒行歌 二','不詳','quantangshi','','卷1','万国咸归禹，千官共祝尧。
拜恩瞻凤扆，倾耳听云韶。
运启金行远，时和玉烛调。
酒酣齐拚舞，同贺圣明朝。','',''),('quantangshi-00840','郊庙歌辞 晋朝飨乐章 羣臣酒行歌 三','不詳','quantangshi','','卷1','令节陈高会，羣臣侍御筵。
玉墀留爱景，金殿霭祥烟。
振鹭涵天泽，灵禽下乐悬。
圣明无一事，何处让尧年。','',''),('quantangshi-00841','郊庙歌辞 周朝飨乐章 忠顺','不詳','quantangshi','','卷1','岁迎更始，节及朝元。
冕旒仰止，冠劒相连。
八音合奏，万物齐宣。
常陈盛礼，愿永千年。','',''),('quantangshi-00842','郊庙歌辞 周朝飨乐章 忠顺','不詳','quantangshi','','卷1','明君当宁，列辟奉觞。
云容表瑞，日影初长。
衣冠济济，钟磬洋洋。
令仪克盛，嘉会有章。','',''),('quantangshi-00843','郊庙歌辞 周朝飨乐章 治顺','不詳','quantangshi','','卷1','庭陈大乐，作当太微。
凝旒负扆，端拱垂衣。
鸳鸾成列，簪组相辉。
御炉香散，郁郁霏霏。','',''),('quantangshi-00844','郊庙歌辞 周朝飨乐章 福顺','不詳','quantangshi','','卷1','圣皇端拱，多士输忠。
蛮觞共献，臣心毕同。
声齐嵩岳，祝比华封。
千龄万祀，常保时雍。','',''),('quantangshi-00845','郊庙歌辞 周朝飨乐章 康顺','不詳','quantangshi','','卷1','鸿钧广运，嘉节良辰。
列辟在位，万国来宾。
干旌屡舞，金石咸陈。
礼容既备，帝履长春。','',''),('quantangshi-00846','郊庙歌辞 周朝飨乐章 忠顺','不詳','quantangshi','','卷1','礼成三爵，乐毕九成。
共离金戺，复列彤庭。','',''),('quantangshi-00847','郊庙歌辞 周朝飨乐章 忠顺','不詳','quantangshi','','卷1','明庭展礼，为龙为光。
咸韶息韵，鵷鹭归行。','',''),('quantangshi-00848','郊庙歌辞 晋昭德成功舞歌 昭德舞歌二首 一','不詳','quantangshi','','卷1','圣代修文德，明庭举旧章。
两阶陈羽龠，万舞合宫商。
劒佩森鸳鹭，箫韶下凤凰。
我朝青史上，千古有辉光。','',''),('quantangshi-00849','郊庙歌辞 晋昭德成功舞歌 昭德舞歌二首 二','不詳','quantangshi','','卷1','淮海干戈戢，朝廷礼乐施。
白驹皆就絷，丹凤复来仪。
德备三苗格，风行万国随。
小臣同百兽，率舞贺昌期。','',''),('quantangshi-00850','郊庙歌辞 晋昭德成功舞歌 武功舞歌二首 一','不詳','quantangshi','','卷1','拨乱资英主，开基自晋阳。
一戎成大业，七德焕前王。
炎汉提封远，姬周世祚长。
朱干将玉戚，全象武功扬。','',''),('quantangshi-00851','郊庙歌辞 晋昭德成功舞歌 武功舞歌二首 二','不詳','quantangshi','','卷1','睿算超前古，神功格上圆。
百川留禹迹，万国戴尧天。
既已櫜弓矢，诚宜播管弦。
跄跄随鸟兽，共乐太平年。','',''),('quantangshi-00852','鼓吹曲辞 朱鹭','張籍','quantangshi','','卷1','翩翩兮朱鹭，来泛春塘栖绿树。
羽毛如翦色如染，远飞欲下双翅敛。
避人引子入深壍，动处水纹开滟滟。
谁知豪家网尔躯，不如饮啄江海隅。','',''),('quantangshi-00853','鼓吹曲辞 艾如张','李賀','quantangshi','','卷1','锦襜褕，绣裆襦，强强饮啄哺尔雏。
陇东卧穟满风雨，莫信龙媒陇西去。
齐人织网如素空，张在野春平碧中。
网丝漠漠无形影，误尔触之伤首红。
艾叶绿花谁翦刻，中藏祸机不可测。','',''),('quantangshi-00854','鼓吹曲辞 上之回','盧照鄰','quantangshi','','卷1','回中道路险，萧关烽候多。
五营屯北地，万乘出西河。
单于拜玉玺，天子按雕戈。
振旅汾川曲，秋风横大歌。','',''),('quantangshi-00855','鼓吹曲辞 上之回','李白','quantangshi','','卷1','三十六离宫，楼台与天通。
阁道步行月，美人愁烟空。
恩疎宠不及，桃李伤春风。
淫乐意何极，金舆向回中。
万乘出黄道，千旗扬彩虹。
前军细柳北，后骑甘泉东。
岂问渭川老，宁邀襄野童。
秋暮瑶池宴，归来乐未穷。','',''),('quantangshi-00856','鼓吹曲辞 上之回','李賀','quantangshi','','卷1','上之回，大旗喜。
悬虹彗，挞凤尾。
劒匣破，舞蛟龙。
蚩尤死，鼓逢逢。
天高庆雷齐坠地，地无惊烟海千里。','',''),('quantangshi-00857','鼓吹曲辞 战城南','盧照鄰','quantangshi','','卷1','将军出紫塞，冒顿在乌贪。
笳喧雁门北，阵翼龙城南。
雕弓夜宛转，铁骑晓参潭。
应须驻白日，为待战方酣。','',''),('quantangshi-00858','鼓吹曲辞 战城南','李白','quantangshi','','卷1','去年战桑干源，今年战葱河道。
洗兵条支海上波，放马天山雪中草。
万里长征战，三军尽衰老。
匈奴以杀戮为耕作，古来唯见白骨黄沙田。
秦家筑城备胡处，汉家还有烽火然。
烽火然不息，征战无已时。
野战格鬬死，败马号鸣向天悲。
乌鸢啄人肠，衔飞上挂枯树枝。
士卒涂草莽，将军空尔为。
乃知兵者是凶器，圣人不得已而用之。','',''),('quantangshi-00859','鼓吹曲辞 战城南','劉駕','quantangshi','','卷1','城南征战多，城北无饥鵶。
白骨马蹄下，谁言皆有家。
城前水声苦，倏忽流万古。
莫争城外地，城里有闲土。','',''),('quantangshi-00860','鼓吹曲辞 战城南二首 一','僧貫休','quantangshi','','卷1','万里桑干傍，茫茫古蕃壤。
将军貌顦顇，抚劒悲年长。
胡兵尚陵逼，久住亦非强。
邯郸少年辈，个个有伎俩。
拖枪半夜去，雪片大如掌。','',''),('quantangshi-00861','鼓吹曲辞 战城南二首 二','僧貫休','quantangshi','','卷1','碛中有阴兵，战马时惊蹶。
轻猛李陵心，摧残苏武节。
黄金锁子甲，风吹色如铁。
十载不封侯，茫茫向谁说。','',''),('quantangshi-00862','鼓吹曲辞 巫山高','鄭世翼','quantangshi','','卷1','巫山凌太清，岧峣类削成。
霏霏暮雨合，霭霭朝云生。
危峰入鸟道，深谷泻猿声。
别有幽栖客，淹留攀桂情。','',''),('quantangshi-00863','鼓吹曲辞 巫山高二首 一','沈佺期','quantangshi','','卷1','巫山峰十二，环合隐昭回。
俯眺琵琶峡，平看云雨台。
古槎天外倚，瀑水日边来。
何忽啼猨夜，荆王枕席开。','',''),('quantangshi-00864','鼓吹曲辞 巫山高二首 二','沈佺期','quantangshi','','卷1','神女向高唐，巫山下夕阳。
裴回作行雨，婉娈逐荆王。
电影江前落，雷声峡外长。
霁云无处所，台馆晓苍苍。','',''),('quantangshi-00865','鼓吹曲辞 巫山高','盧照鄰','quantangshi','','卷1','巫山望不极，望望下朝雰。
莫辨啼猿树，徒看神女云。
惊涛乱水脉，骤雨暗峰文。
霑裳即此地，况复远思君。','',''),('quantangshi-00866','鼓吹曲辞 巫山高','張循之','quantangshi','','卷1','巫山高不极，沓沓状奇新。
暗谷疑风雨，幽岩若鬼神。
月明三峡曙，潮满二江春。
为问阳台夕，应知入梦人。','',''),('quantangshi-00867','鼓吹曲辞 巫山高','劉方平','quantangshi','','卷1','楚国巫山秀，清猨日夜啼。
万重春树合，十二碧峰齐。
峡出朝云下，江来暮雨西。
阳台归路直，不畏向家迷。','',''),('quantangshi-00868','鼓吹曲辞 巫山高','皇甫冉','quantangshi','','卷1','巫峡见巴东，迢迢半出空。
云藏神女馆，雨到楚王宫。
朝暮泉声落，寒暄树色同。
清猨不可听，偏在九秋中。','',''),('quantangshi-00869','鼓吹曲辞 巫山高','李端','quantangshi','','卷1','巫山十二峰，皆在碧虚中。
回合云藏日，霏微雨带风。
猨声寒过水，树色暮连空。
愁向高唐望，清秋见楚宫。','',''),('quantangshi-00870','鼓吹曲辞 巫山高','于濆','quantangshi','','卷1','何山无朝云，彼云亦悠扬。
何山无暮雨，彼雨亦苍茫。
宋玉恃才者，凭云构高唐。
自重文赋名，荒淫归楚襄。
峨峨十二峰，永作妖鬼乡。','',''),('quantangshi-00871','鼓吹曲辞 巫山高二首 一','孟郊','quantangshi','','卷1','巴山上峡重复重，阳台碧峭十二峰。
荆王猎时逢暮雨，夜卧高丘梦神女。
轻红流烟湿艳姿，行云飞去明星稀。
目极魂断望不见，猨啼三声泪霑衣。','',''),('quantangshi-00872','鼓吹曲辞 巫山高二首 二','孟郊','quantangshi','','卷1','见尽数万里，不闻三声猨。
但飞萧萧雨，中有亭亭魂。
千载楚襄恨，遗文宋玉言。
至今青冥里，云结深闺门。','',''),('quantangshi-00873','鼓吹曲辞 巫山高','李賀','quantangshi','','卷1','碧丛丛，高插天，大江翻澜神曳烟。
楚魂寻梦风飔然，晓风飞雨生苔钱。
瑶姬一去一千年，丁香筇竹啼老猨。
古祠近月蟾桂寒，椒花坠红湿云间。','',''),('quantangshi-00874','鼓吹曲辞 巫山高','僧齊己','quantangshi','','卷1','巫山高，巫女妖。
雨为暮兮云为朝，楚王顦顇魂欲销。
秋猨嗥嗥日将夕，红霞紫烟凝老壁。
千岩万壑花皆坼，但恐芳菲无正色。
不知今古行人行，几人经此无秋情。
云深庙远不可觅，十二峰头插天碧。','',''),('quantangshi-00875','鼓吹曲辞 将进酒','李白','quantangshi','','卷1','君不见黄河之水天上来，奔流到海不复回。
君不见高堂明镜悲白发，朝如青丝暮成雪。
人生得意须尽欢，莫使金尊空对月。
天生我材必有用，千金散尽还复来。
烹羊宰牛且为乐，会须一饮三百杯。
岑夫子，丹丘生，将进酒，杯莫停。
与君歌一曲，请君为我侧耳听。
钟鼓馔玉不足贵，但愿长醉不复醒。
古来圣贤皆寂寞，惟有饮者留其名。
陈王昔时宴平乐，斗酒十千恣欢谑。
主人何为言少钱，径须酤取对君酌。
五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。','',''),('quantangshi-00876','鼓吹曲辞 将进酒','李賀','quantangshi','','卷1','将进酒，将进酒。
酒中有毒鸩主父，言之主父伤主母。
母为妾地父妾天，仰天俯地不忍言。
佯为僵踣主父前，主父不知加妾鞭。
旁人知妾为主说，主将泪洗鞭头血。
推摧主母牵下堂，扶妾遣升堂上牀。
将进酒，酒中无毒令主寿。
愿主回思归主母，遣妾如此事主父。
妾为此事人偶知，自慙不密方自悲。
主今颠倒安置妾，贪天僭地谁不为。','',''),('quantangshi-00877','鼓吹曲辞 将进酒','李賀','quantangshi','','卷1','瑠璃钟，琥珀浓，小槽酒滴真珠红。
烹龙炮凤玉脂泣，罗屏绣幕围香风。
吹龙笛，击鼍鼓，皓齿歌，细腰舞。
况是青春日将暮，桃花乱落如红雨。
劝君终日酩酊醉，酒不到刘伶坟上土。','',''),('quantangshi-00878','鼓吹曲辞 君马黄','李白','quantangshi','','卷1','君马黄，我马白。
马色虽不同，人心本无隔。
共作游冶盘，双行洛阳陌。
长劒既照曜，高冠何赩赫。
各有千金裘，俱为五侯客。
猛虎落陷穽，壮夫时屈厄。
相知在急难，独好亦何益。','',''),('quantangshi-00879','鼓吹曲辞 芳树','沈佺期','quantangshi','','卷1','何地早芳菲？宛在长门殿。
夭桃色若绶，穠李光如练。
啼鸟弄花疎，游蠭饮香徧。
叹息春风起，飘零君不见。','',''),('quantangshi-00880','鼓吹曲辞 芳树','盧照鄰','quantangshi','','卷1','芳树本多奇，年华复在斯。
结翠成新幄，开红满旧枝。
风归花历乱，日度影参差。
容色朝朝落，思君君不知。','',''),('quantangshi-00881','鼓吹曲辞 芳树','徐彥伯','quantangshi','','卷1','玉花珍簟上，金缕画屏开。
晓月怜筝柱，春风忆镜台。
筝柱春风吹晓月，芳树落花朝暝歇。
藳砧刀头未有时，攀条拭泪坐相思。','',''),('quantangshi-00882','鼓吹曲辞 芳树','韋應物','quantangshi','','卷1','迢迢芳园树，列映清池曲。
对此伤人心，还如故时绿。
风条洒余霭，露叶承新旭。
佳人不再攀，下有往来躅。','',''),('quantangshi-00883','鼓吹曲辞 芳树','稹','quantangshi','','卷1','芳树已寥落，孤英尤可嘉。
可怜团团叶，盖覆深深花。
游蠭竞攒刺，鬬雀亦纷拏。
天生细碎物，不爱好光华。
非无歼殄法，念尔有生涯。
春雷一声发，惊燕亦惊蛇。
清池养神蔡，已复长虾蟆。
雨露贵平施，吾其春草芽。','',''),('quantangshi-00884','鼓吹曲辞 芳树','羅隱','quantangshi','','卷1','细蘂慢逐风，暖香闲破鼻。
青帝固有心，时时动人意。
去年高枝犹压地，今年低枝已顦顇。
吾所以见造化之权，变通之理。
春夏作头，秋冬为尾。
循环反覆无穷已，今生长短同一轨。
若使威可以制，力可以止，秦皇不肯敛手下沙丘，孟贲不合低头入蒿里。
伊人彊猛犹如此，顾我劳生何足恃？
但愿开素袍，倾绿蚁，陶陶兀兀大醉于青冥白昼间。
任他上是天，下是地。','',''),('quantangshi-00885','鼓吹曲辞 有所思','沈佺期','quantangshi','','卷1','君子事行役，再空芳岁期。
美人旷延伫，万里浮云思。
园槿绽红艳，郊桑柔绿滋。
坐看长夏晚，秋月生罗帏。','',''),('quantangshi-00886','鼓吹曲辞 有所思','李白','quantangshi','','卷1','我思仙人，乃在碧海之东隅。
海寒多天风，白波连山倒蓬壶。
长鲸喷涌不可涉，抚心茫茫泪如珠。
西来青鸟东飞去，愿寄一书谢麻姑。','',''),('quantangshi-00887','鼓吹曲辞 有所思','孟郊','quantangshi','','卷1','桔槔烽火昼不灭，客路迢迢信难越。
古镇刀攒万片霜，寒江浪起千堆雪。
此时西去定如何，空使南心远凄切。','',''),('quantangshi-00888','鼓吹曲辞 有所思','盧仝','quantangshi','','卷1','当时我醉美人家，美人颜色娇如花。
今日美人弃我去，青楼珠箔天之涯。
天涯娟娟常娥月，三五二八盈又缺。
翠眉蝉鬓生别离，一望不见心断绝。
心断绝，几千里，梦中醉卧巫山云。
觉来泪滴湘江水，湘江两岸花木深。
美人不见愁人心，含愁更奏绿绮琴，调高弦绝无知音。
美人兮美人！不知为暮雨兮为朝云。
相思一夜梅花发，忽到窗前疑是君。','',''),('quantangshi-00889','鼓吹曲辞 有所思','韋應物','quantangshi','','卷1','借问江上柳，青青为谁春。
空游昨日地，不见昨日人。
缭绕万家井，往来车马尘。
莫道无相识，要非心所亲。','',''),('quantangshi-00890','鼓吹曲辞 有所思','劉氏雲','quantangshi','','卷1','朝亦有所思，暮亦有所思。
登楼望君处，蔼蔼浮云飞。
浮云遮却阳关道，向晚谁知妾怀抱。
玉井苍苔春院深，桐花落地无人扫。','',''),('quantangshi-00891','鼓吹曲辞 雉子班','李白','quantangshi','','卷1','辟邪伎作鼓吹惊，雉子班之奏曲成。
喔咿振迅欲飞鸣，扇锦翼，雄风生。
双雌同饮啄，趫悍谁能争。
乍向草中耿介死，不求黄金笼下生。
天地至广大，何惜遂物情。
善卷让天子，务光亦逃名。
所贵旷士怀，朗然合太清。','',''),('quantangshi-00892','鼓吹曲辞 临高台','褚亮','quantangshi','','卷1','高台暂俯临，飞翼耸轻音。
浮光随日度，漾影逐波深。
迥瞰周平野，开怀畅远襟。
独此三休上，还伤千岁心。','',''),('quantangshi-00893','鼓吹曲辞 临高台','王勃','quantangshi','','卷1','临高台，高台迢递绝浮埃。
瑶轩绮构何崔嵬，鸾歌凤吹清且哀。
俯瞰长安道，萋萋御沟草。
斜对甘泉路，苍苍茂陵树。
高台四望同，帝乡佳气郁葱葱。
紫阁丹楼纷照曜，璧房锦殿相玲珑。
东弥长乐观，西指未央宫。
赤城映朝日，绿树摇春风。
旗亭百队开新市，甲第千甍分戚里。
朱轮翠盖不胜春，叠树层楹相对起。
复有青楼大道中，绣户文窗雕绮栊。
锦衣昼不襞，罗帏夕未空。
歌屏朝揜翠，妆镜晚窥红。
为吾安宝髻，蛾眉罢花丛。
狭路尘间黯将暮，云间月色明如素。
鸳鸯池上两两飞，凤皇楼下双双度。
物色正如此，佳期那不顾。
银鞍绣毂盛繁华，可怜今夜宿倡家。
倡家少妇不须嚬，东园桃李片时春。
君看旧日高台处，柏梁铜雀生黄尘。','',''),('quantangshi-00894','鼓吹曲辞 临高台','僧貫休','quantangshi','','卷1','凉风吹远念，使我升高台。
宁知数片云，不是旧山来。
故人天一涯，久客殊未回。
雁来不得书，空寄声哀哀。','',''),('quantangshi-00895','鼓吹曲辞 黄雀行','莊南傑','quantangshi','','卷1','穿屋穿墙不知止，争树争巢入营死。
林间公子挟弹弓，一丸致毙花丛里。
小雏黄口未有知，青天不解高高飞。
虞人设网当要路，白日啾嘲祸万机。','',''),('quantangshi-00896','鼓吹曲辞 钓竿篇','沈佺期','quantangshi','','卷1','朝日敛红烟，垂竿向绿川。
人疑天上坐，鱼似镜中悬。
避檝时惊透，猜钩每误牵。
湍危不理辖，潭静欲留船。
钓玉君徒尚，征金我未贤。
为看芳饵下，贪得会无全。','',''),('quantangshi-00897','鼓吹曲辞 凯歌六首 一','岑參','quantangshi','','卷1','汉将承恩西破戎，捷书先奏未央宫。
天子预开麟阁待，祗今谁数贰师功。','',''),('quantangshi-00898','鼓吹曲辞 凯歌六首 二','岑參','quantangshi','','卷1','官军西出过楼兰，营幕傍临月窟寒。
蒲海晓霜凝劒尾，葱山夜雪扑旌竿。','',''),('quantangshi-00899','鼓吹曲辞 凯歌六首 三','岑參','quantangshi','','卷1','鸣笳擂鼓拥回军，破国平蕃昔未闻。
大夫鹊印摇边月，天将龙旗掣海云。','',''),('quantangshi-00900','鼓吹曲辞 凯歌六首 四','岑參','quantangshi','','卷1','月落辕门鼓角鸣，千羣面缚出蕃城。
洗兵鱼海云迎阵，秣马龙堆月照营。','',''),('quantangshi-00901','鼓吹曲辞 凯歌六首 五','岑參','quantangshi','','卷1','蕃军遥见汉家营，满谷连山徧哭声。
万箭千刀一夜杀，平明流血浸空城。','',''),('quantangshi-00902','鼓吹曲辞 凯歌六首 六','岑參','quantangshi','','卷1','暮雨旌旗湿未干，胡尘白草日光寒。
昨日将军连晓战，蕃军只见马空鞍。','',''),('quantangshi-00903','鼓吹曲辞 鼓吹铙歌 晋阳武','柳宗元','quantangshi','','卷1','晋阳武，奋义威。
炀之渝，德焉归。
氓毕屠，绥者谁。
皇烈烈，专天机。
号以仁，扬其旗。
日之升，九土曦。
斥田圻，流洪辉。
有其二，翼余隋。
斮枭骜，连熊螭。
枯以肉，勍者羸。
后土荡，玄穹弥。
合之育，莽然施。
惟德辅，庆无期。','',''),('quantangshi-00904','鼓吹曲辞 鼓吹铙歌 兽之穷','柳宗元','quantangshi','','卷1','兽之穷，奔大麓。
天厚黄德，狙犷服。
甲之櫜弓，弭矢箙。
皇旅靖，敌逾蹙。
自亡其徒，匪予戮。
屈𧹁猛，虔栗栗。
縻以尺组，噉以秩。
黎之阳，土茫茫。
富兵戎，盈仓箱。
乏者德，莫能享。
驱豺兕，授我疆。','',''),('quantangshi-00905','鼓吹曲辞 鼓吹铙歌 战武牢','柳宗元','quantangshi','','卷1','战武牢，动河朔。
逆之助，图掎角。
怒鷇麛，抗乔岳。
翘萌牙，傲霜雹。
王谋内定，申掌握。
铺施芟夷，二主缚。
惮华戎，廓封略。
命之瞢，卑以斮。
归有德，唯先觉。','',''),('quantangshi-00906','鼓吹曲辞 鼓吹铙歌 泾水黄','柳宗元','quantangshi','','卷1','泾水黄，陇野茫。
负太白，腾天狼。
有鸟鸷立，羽翼张。
钩喙决前，钜趯傍。
怒飞饥啸，翾不可当。
老雄死，子复良。
巢岐饮渭，肆翱翔。
顿地纮，提天纲。
列缺掉帜，招摇耀铓。
鬼神来助，梦嘉祥。
脑涂原野，魂飞扬。
星辰复，恢一方。','',''),('quantangshi-00907','鼓吹曲辞 鼓吹铙歌 奔鲸沛','柳宗元','quantangshi','','卷1','奔鲸沛，荡海垠。
吐霓翳日，腥浮云。
帝怒下顾，哀垫昏。
[授]以神柄，推元臣。
手援天矛，截修鳞。
披攘蒙霿，开海门。
地平水静，浮天垠。
羲和显耀，乘清氛。
赫炎溥畅，融大钧。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-00908','鼓吹曲辞 鼓吹铙歌 苞枿','柳宗元','quantangshi','','卷1','苞枿𪒶矣，惟根之蟠。
弥巴蔽荆，负南极以安。
曰我旧梁氏，辑绥艰难。
江汉之阻，都邑固以完。
圣人作，神武用。
有臣勇智，奋不以众。
投迹死地，谋猷纵。
化敌为家，虑则中。
浩浩海裔，不威而同。
系缧降王，定厥功。
澶漫万里，宣唐风。
蛮夷九译，咸来从。
凯旋金奏，象形容。
震赫万国，罔不龚。','',''),('quantangshi-00909','鼓吹曲辞 鼓吹铙歌 河右平','柳宗元','quantangshi','','卷1','河右澶漫，顽为之魁。
王师如雷震，昆仑以颓。
上聋下聪，骜不可回。
助雠抗有德，惟人之灾。
乃溃乃奋，执缚归厥命。
万室蒙其仁，一夫则病。
濡以鸿泽，皇之圣。
威畏德怀，功以定。
顺之于理，物咸遂厥性。','',''),('quantangshi-00910','鼓吹曲辞 鼓吹铙歌 铁山碎','柳宗元','quantangshi','','卷1','铁山碎，大漠舒。
二虏劲，连穹庐。
背北海，专坤隅。
岁来侵边，或傅于都。
天子命元帅，奋其雄图。
破定襄，降魁渠。
穷竟窟宅，斥余吾。
百蛮破胆，边氓苏。
威武辉耀，明鬼区。
利泽弥万祀，功不可逾。
官臣拜手，惟帝之谟。','',''),('quantangshi-00911','鼓吹曲辞 鼓吹铙歌 靖本邦','柳宗元','quantangshi','','卷1','本邦伊晋，惟时不靖。
根柢之摇，枝叶攸病。
守臣不任，勚于神圣。
惟钺之兴，翦焉则定。
洪惟我理，式和以敬。
羣顽既夷，庶绩咸正。
皇谟载大，惟人之庆。','',''),('quantangshi-00912','鼓吹曲辞 鼓吹铙歌 吐谷浑','柳宗元','quantangshi','','卷1','吐谷浑盛彊，背西海以夸。
岁侵扰我疆，退匿险且遐。
帝谓神武师，往征靖皇家。
烈烈斾其旗，熊虎杂龙蛇。
王旅千万人，衔枚默无哗。
束刃逾山徼，张翼纵漠沙。
一举刈膻腥，尸骸积如麻。
除恶务本根，况敢遗萌芽。
洋洋西海水，威命穷天涯。
系虏来王都，犒乐穷休嘉。
登高望还师，竟野如春华。
行者靡不归，亲戚讙要遮。
凯旋献清庙，万国思无邪。','',''),('quantangshi-00913','鼓吹曲辞 鼓吹铙歌 高昌','柳宗元','quantangshi','','卷1','麴氏雄西北，别绝臣外区。
既恃远且险，纵傲不我虞。
烈烈王者师，熊螭以为徒。
龙旗飜海浪，馹骑驰坤隅。
贲育搏婴儿，一扫不复余。
平沙际天极，但见黄云驱。
臣靖执长缨，智勇伏囚拘。
文皇南面坐，夷狄千羣趋。
咸称天子神，往古不得俱。
献号天可汗，以覆我国都。
兵戎不交害，各保性与躯。','',''),('quantangshi-00914','鼓吹曲辞 鼓吹铙歌 东蛮','柳宗元','quantangshi','','卷1','东蛮有谢氏，冠带理海中。
自言我异世，虽圣莫能通。
王卒如飞翰，鹏骞骇羣龙。
轰然自天坠，乃信神武功。
系虏君臣人，累累来自东。
无思不服从，唐业如山崇。
百辟拜稽首，咸愿图形容。
如周王会书，永永传无穷。
睢盱万状乖，咿嗢九译重。
广轮抚四海，浩浩知皇风。
歌诗铙鼓间，以壮我元戎。','',''),('quantangshi-00915','横吹曲辞 陇头','張籍','quantangshi','','卷1','陇头已断人不行，胡骑夜入凉州城。
汉家处处格鬬死，一朝尽没陇西地。
驱我边人胡中去，散放牛羊食禾黍。
去年中国养子孙，今着毡裘学胡语。
谁能更使李轻车，收取凉州属汉家。','',''),('quantangshi-00916','横吹曲辞 陇头吟','王維','quantangshi','','卷1','长安少年游侠客，夜上戍楼看太白。
陇头明月迥临关，陇上行人夜吹笛。
关西老将不胜愁，驻马听之双泪流。
身经大小百余战，麾下偏裨万户侯。
苏武才为典属国，节旄空尽海西头。','',''),('quantangshi-00917','横吹曲辞 陇头吟','翁綬','quantangshi','','卷1','陇水潺湲陇树黄，征人陇上尽思乡。
马嘶斜日朔风急，雁过寒云边思长。
残月出林明劒戟，平沙隔水见牛羊。
横行俱足封侯者，谁斩楼兰献未央。','',''),('quantangshi-00918','横吹曲辞 陇头水','楊師道','quantangshi','','卷1','陇头秋月明，陇水带关城。
笳添离别曲，风送断肠声。
映雪峰犹暗，乘冰马屡惊。
雾中寒雁至，沙上转蓬轻。
天山传羽檄，汉地急征兵。
阵开都护道，劒聚伏波营。
于兹觉无度，方共濯胡缨。','',''),('quantangshi-00919','横吹曲辞 陇头水','盧照鄰','quantangshi','','卷1','陇坂高无极，征人一望乡。
关河别去水，沙塞断归肠。
马系千年树，旌悬九月霜。
从来共呜咽，皆是为勤王。','',''),('quantangshi-00920','横吹曲辞 陇头水','王建','quantangshi','','卷1','陇水何年陇头别，不在山中亦呜咽。
征人塞耳马不行，未到陇头闻水声。
谓是西流入蒲海，还闻北海绕龙城。
陇东陇西多屈曲，野麋饮水长簇簇。
胡兵夜回水傍住，忆着来时磨劒处。
向前无井复无泉，放马回看陇头树。','',''),('quantangshi-00921','横吹曲辞 陇头水','于濆','quantangshi','','卷1','借问陇头水，终年恨何事。
深疑呜咽声，中有征人泪。
昨日上山下，达曙不能寐。
何处接长波？东流入清渭。','',''),('quantangshi-00922','横吹曲辞 陇头水 一','僧皎然','quantangshi','','卷1','陇头心欲绝，陇水不堪闻。
碎影摇枪垒，寒声咽帐军。
素从盐海积，绿带柳城分。
日落天边望，逶迤入塞云。','',''),('quantangshi-00923','横吹曲辞 陇头水 二','僧皎然','quantangshi','','卷1','秦陇逼氐羌，征人去未央。
如何幽咽水，并欲断君肠。
西注悲穷漠，东分忆故乡。
旅魂声搅乱，无梦到辽阳。','',''),('quantangshi-00924','横吹曲辞 陇头水','鮑溶','quantangshi','','卷1','陇头水，千古不堪闻。
生归苏属国，死别李将军。
细响风凋草，清哀雁落云。','',''),('quantangshi-00925','横吹曲辞 陇头水','羅隱','quantangshi','','卷1','借问陇头水，年年恨何事。
全疑呜咽声，中有征人泪。
自古无长策，况我非深智。
何计谢潺湲，一宵空不寐。','',''),('quantangshi-00926','横吹曲辞 出关','魏徵','quantangshi','','卷1','中原还逐鹿，投笔事戎轩。
纵横计不就，慷慨志犹存。
策杖谒天子，驱马出关门。
请缨羁南越，凭轼下东藩。
郁纡陟高岫，出没望平原。
古木吟寒鸟，空山啼夜猨。
既伤千里目，还惊九折魂。
岂不惮艰险，深怀国士恩。
季布无二诺，侯嬴重一言。
人生感意气，功名谁复论。','',''),('quantangshi-00927','横吹曲辞 入关','賈馳','quantangshi','','卷1','河上微风来，关头树初湿。
今朝关城吏，又见孤客入。
上国谁与期，西来徒自急。','',''),('quantangshi-00928','横吹曲辞 入关','張祜','quantangshi','','卷1','都城连百二，雄险北回环。
地势遥尊岳，河流侧让关。
秦皇曾虎视，汉祖亦龙颜。
何事枭凶辈，干戈自不闲。','',''),('quantangshi-00929','横吹曲辞 出塞','竇威','quantangshi','','卷1','匈奴屡不平，汉将欲纵横。
看云方结阵，却月始连营。
潜军度马邑，扬斾掩龙城。
会勒燕然石，方传车骑名。','',''),('quantangshi-00930','横吹曲辞 出塞','陳子昂','quantangshi','','卷1','忽闻天上将，关塞重横行。
始返楼兰国，还向朔方城。
黄金装战马，白羽集神兵。
星月开天阵，山川列地营。
晚风吹画角，春色耀飞旌。
宁知班定远，独是一书生。','',''),('quantangshi-00931','横吹曲辞 出塞','張易之','quantangshi','','卷1','侠客重恩光，骢马饰金装。
瞥闻传羽檄，驰突救边荒。
转战磨筓地，横行戴斗乡。
将军占太白，小妇怨流黄。
騕褭青丝骑，娉婷红粉妆。
一春莺度曲，八月雁成行。
谁堪坐秋思，罗袖拂空牀。','',''),('quantangshi-00932','横吹曲辞 出塞','沈佺期','quantangshi','','卷1','十年通大漠，万里出长平。
寒日生戈劒，阴云摇斾旌。
饥乌啼旧垒，疲马恋空城。
辛苦[皋兰]北，胡霜损汉兵。','',''),('quantangshi-00933','横吹曲辞 出塞','王維','quantangshi','','卷1','居延城外猎天骄，白草连天野火烧。
暮云空碛时驱马，秋日平原好射雕。
护羌校尉朝乘障，破虏将军夜渡辽。
玉靶角弓珠勒马，汉家将赐霍嫖姚。','',''),('quantangshi-00934','横吹曲辞 出塞 一','王昌齡','quantangshi','','卷1','秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。','',''),('quantangshi-00935','横吹曲辞 出塞 二','王昌齡','quantangshi','','卷1','白花垣上望京师，黄河水流无尽时。
穷秋旷野行人绝，马首东来知是谁。','',''),('quantangshi-00936','横吹曲辞 出塞','馬戴','quantangshi','','卷1','金带连环束战袍，马头冲雪度临洮。
卷旗夜劫单于帐，乱斫胡兵缺宝刀。','',''),('quantangshi-00937','横吹曲辞 前出塞九首 一','杜甫','quantangshi','','卷1','戚戚去故里，悠悠赴交河。
公家有程期，亡命婴祸罗。
君已富土境，开边一何多？
弃绝父母恩，吞声行负戈。','',''),('quantangshi-00938','横吹曲辞 前出塞九首 二','杜甫','quantangshi','','卷1','出门日已远，不受徒旅欺。
骨肉恩岂断，男儿死无时。
走马脱辔头，手中挑青丝。
捷下万仞冈，俯身试搴旗。','',''),('quantangshi-00939','横吹曲辞 前出塞九首 三','杜甫','quantangshi','','卷1','磨刀呜咽水，水赤刃伤手。
欲轻肠断声，心绪乱已久。
丈夫誓许国，愤惋复何有？
功名图麒麟，战骨当速朽。','',''),('quantangshi-00940','横吹曲辞 前出塞九首 四','杜甫','quantangshi','','卷1','送徒既有长，远戍亦有身。
生死向前去，不劳吏怒嗔。
路逢相识人，附书与六亲。
哀哉两决绝，不复同苦辛。','',''),('quantangshi-00941','横吹曲辞 前出塞九首 五','杜甫','quantangshi','','卷1','迢迢万余里，领我赴三军。
军中异苦乐，主将宁尽闻。
隔河见胡骑，倏忽数百羣。
我始为奴仆，几时树功勋。','',''),('quantangshi-00942','横吹曲辞 前出塞九首 六','杜甫','quantangshi','','卷1','挽弓当挽彊，用箭当用长。
射人先射马，擒贼先擒王。
杀人亦有限，列国自有疆。
苟能制侵陵，岂在多杀伤。','',''),('quantangshi-00943','横吹曲辞 前出塞九首 七','杜甫','quantangshi','','卷1','驱马天雨雪，军行入高山。
迳危抱寒石，指落曾冰间。
已去汉月远，何时筑城还？
浮云暮南征，可望不可攀。','',''),('quantangshi-00944','横吹曲辞 前出塞九首 八','杜甫','quantangshi','','卷1','单于寇我垒，百里风尘昏。
雄劒四五动，彼军为我奔。
虏其名王归，系颈授辕门。
潜身备行列，一胜何足论。','',''),('quantangshi-00945','横吹曲辞 前出塞九首 九','杜甫','quantangshi','','卷1','从军十年余，能无分寸功。
众人贵苟得，欲语羞雷同。
中原有鬬争，况在狄与戎。
丈夫四方志，安可辞固穷。','',''),('quantangshi-00946','横吹曲辞 后出塞五首 一','杜甫','quantangshi','','卷1','男儿生世间，及壮当封侯。
战伐有功业，焉能守旧丘。
召募赴蓟门，军动不可留。
千金买马鞭，百金装刀头。
闾里送我行，亲戚拥道周。
斑白居上列，酒酣进庶羞。
少年别有赠，含笑看吴钩。','',''),('quantangshi-00947','横吹曲辞 后出塞五首 二','杜甫','quantangshi','','卷1','朝进东门营，暮上河阳桥。
落日照大旗，马鸣风萧萧。
平沙列万幕，部伍各见招。
中天悬明月，令严夜寂寥。
悲笳数声动，壮士惨不骄。
借问大将谁，恐是霍嫖姚。','',''),('quantangshi-00948','横吹曲辞 后出塞五首 三','杜甫','quantangshi','','卷1','古人重守边，今人重高勋。
岂知英雄主，出师亘长云。
六合已一家，四夷且孤军。
遂使貔虎士，奋身勇所闻。
拔劒击大荒，日牧胡马羣。
誓开玄冥北，持以奉吾君。','',''),('quantangshi-00949','横吹曲辞 后出塞五首 四','杜甫','quantangshi','','卷1','献凯日继踵，两蕃静无虞。
渔阳豪侠地，击鼓吹笙竽。
云帆转辽海，粳稻来东吴。
越罗与楚练，照耀舆台躯。
主将位益崇，气骄陵上都。
边人不敢议，议者死路衢。','',''),('quantangshi-00950','横吹曲辞 后出塞五首 五','杜甫','quantangshi','','卷1','我本良家子，出师亦多门。
将骄益愁思，身贵不足论。
跃马二十年，恐辜明主恩。
坐见幽州骑，长驱河洛昏。
中夜间道归，故里但空村。
恶名幸脱免，穷老无儿孙。','',''),('quantangshi-00951','横吹曲辞 出塞','皇甫冉','quantangshi','','卷1','吹角出塞门，前瞻即胡地。
三军尽回首，皆洒望乡泪。
转念关山长，行看风景异。
由来征戍客，各负轻生义。','',''),('quantangshi-00952','横吹曲辞 出塞','王之渙','quantangshi','','卷1','黄砂直上白云间，一片孤城万仞山。
羌笛何须怨杨柳，春风不度玉门关。','',''),('quantangshi-00953','横吹曲辞 出塞','耿[湋]','quantangshi','','卷1','汉家边事重，窦宪出临戎。
绝漠秋山在，阳关旧路通。
列营依茂草，吹角向高风。
更就燕然石，看铭破虏功。','',''),('quantangshi-00954','横吹曲辞 出塞','張籍','quantangshi','','卷1','秋塞雪初下，将军远出师。
分营长记火，放马不收旗。
月冷边帐湿，沙昏夜探迟。
征人皆白首，谁见灭胡时。','',''),('quantangshi-00955','横吹曲辞 出塞','劉駕','quantangshi','','卷1','胡风不开花，四气多作雪。
北人尚冻死，况我本南越。
古来犬羊地，巡狩无遗辙。
九土耕不尽，武皇犹征伐。
中天有高阁，图画何时歇？
坐恐塞上山，低于砂中骨。','',''),('quantangshi-00956','横吹曲辞 出塞曲','劉濟','quantangshi','','卷1','将军在重围，音信绝不通。
羽书如流星，飞人甘泉宫。
倚是并州儿，少年心胆雄。
一朝随召募，百战争王公。
去年桑干北，今年桑干东。
死是征人死，功是将军功。
汗马牧秋月，疲兵卧霜风。
仍闻左贤王，更欲图云中。','',''),('quantangshi-00957','横吹曲辞 出塞曲 一','于鵠','quantangshi','','卷1','微雪将军出，吹笳天未明。
观兵登古戍，斩将对双旌。
分阵瞻山势，潜军制马鸣。
如今新史上，已有灭胡名。','',''),('quantangshi-00958','横吹曲辞 出塞曲 二','于鵠','quantangshi','','卷1','单于骄爱猎，放火到军城。
待月调新弩，防秋置远营。
空山朱戟影，寒碛铁衣声。
逢着降胡说，阴山有伏兵。','',''),('quantangshi-00959','横吹曲辞 出塞曲 一','僧貫休','quantangshi','','卷1','埽尽狂胡迹，回戈望故关。
相逢唯死鬬，岂易得生还。
纵宴参胡乐，收兵过雪山。
不封十万户，此事亦应闲。','',''),('quantangshi-00960','横吹曲辞 出塞曲 二','僧貫休','quantangshi','','卷1','玉帐将军意，殷勤把酒论。
功高宁在我，阵没与招魂。
塞色干戈束，军容喜气屯。
男儿今始是，敢出玉关门。','',''),('quantangshi-00961','横吹曲辞 出塞曲 三','僧貫休','quantangshi','','卷1','回首陇山头，连天草木秋。
圣君应入梦，半路遣封侯。
水不担阴雪，柴令倒戍楼。
归来麟阁上，春色满皇州。','',''),('quantangshi-00962','横吹曲辞 入塞','劉希夷','quantangshi','','卷1','将军陷虏围，边务息戎机。
霜雪交河尽，旌旗入塞飞。
晓光随马度，春色伴人归。
课绩朝明主，临轩拜武威。','',''),('quantangshi-00963','横吹曲辞 入塞曲','耿[湋]','quantangshi','','卷1','将军带十围，重锦制戎衣。
猨臂销弓力，虬须长劒威。
首登平乐宴，新破大宛归。
楼上姝姬笑，门前问客稀。
暮烽玄菟急，秋草紫骝肥。
未奉君主诏，高槐昼掩扉。','',''),('quantangshi-00964','横吹曲辞 入塞曲 一','僧貫休','quantangshi','','卷1','单于烽火动，都护去天涯。
别赐黄金甲，亲临白玉墀。
塞垣须静谧，师旅审安危。
定远条支宠，如今胜古时。','',''),('quantangshi-00965','横吹曲辞 入塞曲 二','僧貫休','quantangshi','','卷1','方见将军贵，分明对冕旒。
圣恩如远被，狂虏不难收。
臣节唯期死，功勋敢望侯。
终辞修里第，从此出皇州。','',''),('quantangshi-00966','横吹曲辞 入塞曲 三','僧貫休','quantangshi','','卷1','百里精兵动，参差便渡辽。
如何好白日，亦照此天骄。
远树深疑贼，惊蓬迥似雕。
凯歌何日唱？碛路共天遥。','',''),('quantangshi-00967','横吹曲辞 入塞曲 一','沈彬','quantangshi','','卷1','欲为皇王服远戎，万人金甲鼓鼙中。
阵云暗塞三边黑，兵血愁天一片红。
半夜飜营旗搅月，深秋防戍劒磨风。
谤书未及明君爇，卧骨将军已殁功。','',''),('quantangshi-00968','横吹曲辞 入塞曲 二','沈彬','quantangshi','','卷1','苦战沙间卧箭痕，戍楼闲上望星文。
生希国泽分偏将，死夺河源答圣君。
鸢覰败兵眠白草，马惊边鬼哭阴云。
功多地远无人纪，汉阁笙歌日又曛。','',''),('quantangshi-00969','横吹曲辞 折杨柳','盧照鄰','quantangshi','','卷1','倡楼启曙扉，园柳正依依。
鸟鸣知岁隔，条变识春归。
露叶疑啼脸，风花乱舞衣。
攀折聊将寄，军中书信稀。','',''),('quantangshi-00970','横吹曲辞 折杨柳','沈佺期','quantangshi','','卷1','玉窗朝日映，罗帐春风吹。
拭泪攀杨柳，长条宛地垂。
白花飞历乱，黄鸟思参差。
妾自肝肠断，旁人那得知。','',''),('quantangshi-00971','横吹曲辞 折杨柳','喬知之','quantangshi','','卷1','可怜濯濯春杨柳，攀折将来就纤手。
妾容与此同盛衰，何必君恩独能久。','',''),('quantangshi-00972','横吹曲辞 折杨柳','劉憲','quantangshi','','卷1','沙塞三河道，金闺二月春。
碧烟杨柳色，红粉绮罗人。
露叶怜啼脸，风花思舞巾。
攀持君不见，为听曲中新。','',''),('quantangshi-00973','横吹曲辞 折杨柳','崔湜','quantangshi','','卷1','二月风光半，三边戍不还。
年华妾自惜，杨柳为君攀。
落絮缘衫袖，垂条拂髻鬟。
那堪音信断，流涕望阳关。','',''),('quantangshi-00974','横吹曲辞 折杨柳','韋承慶','quantangshi','','卷1','万里边城地，三春杨柳节。
叶似镜中眉，花如关外雪。
征人远乡思，倡妇高楼别。
不忍掷年华，含情寄攀折。','',''),('quantangshi-00975','横吹曲辞 折杨柳','歐陽瑾','quantangshi','','卷1','垂柳拂妆台，葳蕤叶半开。
年华枝上见，边思曲中来。
嫩色宜新雨，轻花伴落梅。
朝朝倦攀折，征戍几时回。','',''),('quantangshi-00976','横吹曲辞 折杨柳','張祜','quantangshi','','卷1','红粉青楼曙，垂杨仲月春。
怀君重攀折，非妾妒腰身。
舞带萦丝断，娇娥向叶嚬。
横吹凡几曲，独自最愁人。','',''),('quantangshi-00977','横吹曲辞 折杨柳','張九齡','quantangshi','','卷1','纤纤折杨柳，持此寄情人。
一枝何足贵，怜是故园春。
迟景那能久，流芳不及新。
更愁征戍客，鬓老边城尘。','',''),('quantangshi-00978','横吹曲辞 折杨柳','余延壽','quantangshi','','卷1','大道连国门，东西种杨柳。
葳蕤君不见，褭娜垂来久。
缘枝栖暝禽，雄去雌独吟。
余花怨春尽，微月起秋阴。
坐望窗中蝶，起攀枝上叶。
好风吹长条，妸娜何如妾。
妾见柳园新，高楼四五春。
莫吹胡塞曲，愁杀陇头人。','',''),('quantangshi-00979','横吹曲辞 折杨柳','李白','quantangshi','','卷1','垂杨拂绿水，摇艳东风年。
花明玉关雪，叶暖金窗烟。
美人结长恨，相对心凄然。
攀条折春色，远寄龙庭前。','',''),('quantangshi-00980','横吹曲辞 折杨柳 一','孟郊','quantangshi','','卷1','杨柳多短枝，短枝多别离。
赠远累攀折，柔条安得垂。
青春有定节，离别无定时。
但恐人别促，不怨来迟迟。
莫言短枝条，中有长相思。
朱颜与绿杨，并在别离期。','',''),('quantangshi-00981','横吹曲辞 折杨柳 二','孟郊','quantangshi','','卷1','楼上春风过，风前杨柳歌。
枝疎缘别苦，曲怨为年多。
花惊燕地雪，叶映楚池波。
谁堪别离此，征戍在交河。','',''),('quantangshi-00982','横吹曲辞 折杨柳','李端','quantangshi','','卷1','东城攀柳叶，柳叶低着草。
少壮莫轻年，轻年有人老。
柳发徧川岗，登高堪断肠。
雨烟轻漠漠，何树近君乡？
赠君折杨柳，颜色岂能久。
上客莫霑巾，佳人正回首。
新柳送君行，古柳伤君情。
突兀临荒渡，婆娑出旧营。
隋家两岸尽，陶宅五株平。
日暮偏愁望，春山有鸟声。','',''),('quantangshi-00983','横吹曲辞 折杨柳','翁綬','quantangshi','','卷1','紫陌金堤映绮罗，游人处处动离歌。
阴移古戍迷荒草，花带残阳落远波。
台上少年吹白雪，楼中思妇敛青蛾。
殷勤攀折赠行客，此去关山雨雪多。','',''),('quantangshi-00984','横吹曲辞 望行人','王建','quantangshi','','卷1','自从江树秋，日日上江楼。
梦见离珠浦，书来在桂州。
不同鱼比目，终恨水分流。
久不开明镜，多应是白头。','',''),('quantangshi-00985','横吹曲辞 望行人','張籍','quantangshi','','卷1','秋风窗下起，旅雁向南飞。
日日出门望，家家行客归。
无因见边使，空待寄寒衣。
独闭青楼暮，烟深鸟雀稀。','',''),('quantangshi-00986','横吹曲辞 关山月','盧照鄰','quantangshi','','卷1','塞垣通碣石，虏障抵祈连。
相思在万里，明月正孤悬。
影移金岫北，光断玉门前。
寄书谢中妇，时看鸿雁天。','',''),('quantangshi-00987','横吹曲辞 关山月','沈佺期','quantangshi','','卷1','汉月生辽海，曈昽出半晖。
合昏玄兔郡，中夜白登围。
晕落关山迥，光合霜霰微。
将军听晓角，战马欲南归。','',''),('quantangshi-00988','横吹曲辞 关山月','李白','quantangshi','','卷1','明月出天山，苍茫云海间。
长风几万里，吹度玉门关。
汉下白登道，胡窥青海湾。
由来征战地，不见有人还。
戍客望边色，思归多苦颜。
高楼当此夜，叹息未应闲。','',''),('quantangshi-00989','横吹曲辞 关山月','長孫佐輔','quantangshi','','卷1','凄凄还切切，戍客多离别。
何处最伤心？关山见秋月。
关月竟如何？由来远近过。
始经玄兔塞，终绕白狼河。
忽忆秦楼妇，流光应共有。
已得竝蛾眉，还知揽纤手。
去岁照同行，比翼复连形。
今宵照独立，顾影自茕茕。
余晖渐西落，夜夜看如昨。
借问映旌旗，何如鉴帷幕。
拂晓朔风悲，蓬惊雁不飞。
几时征戍罢，还向月中归。','',''),('quantangshi-00990','横吹曲辞 关山月','耿[湋]','quantangshi','','卷1','月明边徼静，戍客望乡时。
塞古柳衰尽，关寒榆发迟。
苍苍万里道，戚戚十年悲。
今夜青楼上，还应照所思。','',''),('quantangshi-00991','横吹曲辞 关山月二首 一','戴叔倫','quantangshi','','卷1','月出照关山，秋风人未还。
清光无远近，乡泪半书间。','',''),('quantangshi-00992','横吹曲辞 关山月二首 二','戴叔倫','quantangshi','','卷1','一雁过连营，繁霜覆古城。
胡笳在何处？半夜起边声。','',''),('quantangshi-00993','横吹曲辞 关山月','崔融','quantangshi','','卷1','月生西海上，气逐边风壮。
万里度关山，苍茫非一状。
汉兵开郡国，胡马窥亭障。
夜夜闻悲笳，征人起南望。','',''),('quantangshi-00994','横吹曲辞 关山月','李端','quantangshi','','卷1','露湿月苍苍，关头榆叶黄。
回轮照海远，分彩上楼长。
水冻频移幕，兵疲数望乡。
祗应城影外，万里共如霜。','',''),('quantangshi-00995','横吹曲辞 关山月','王建','quantangshi','','卷1','关山月，营开道白前军发。
冻轮当碛光悠悠，照见三堆两堆骨。
边风割面天欲明，金莎岭西看看没。','',''),('quantangshi-00996','横吹曲辞 关山月','張籍','quantangshi','','卷1','秋月朗朗关山上，山中行人马蹄响。
关山秋来雨雪多，行人见月唱边歌。
海边漠漠天气白，胡儿夜度黄龙碛。
军中探骑暮出城，伏兵暗处低旌戟。
溪水连地霜草平，野駞寻水碛中鸣。
陇头风急雁不下，沙场苦战多流星。
可怜万国关山道，年年战骨多秋草。','',''),('quantangshi-00997','横吹曲辞 关山月','翁綬','quantangshi','','卷1','裴回汉月满边州，照尽天涯到陇头。
影转银河寰海静，光分玉塞古今愁。
笳吹远戍孤烽灭，雁下平沙万里秋。
况是故园摇落夜，那堪少妇独登楼。','',''),('quantangshi-00998','横吹曲辞 关山月','鮑氏君[徽]微','quantangshi','','卷1','高高秋月明，北照辽阳城。
塞迥光初满，风多晕更生。
征人望乡思，战马闻鞞惊。
朔风悲边草，胡沙昏虏营。
霜疑匣中劒，风惫原上旌。
早晚谒金阙，不闻刁斗声。','',''),('quantangshi-00999','横吹曲辞 洛阳道','于武陵','quantangshi','','卷1','浮世若浮云，千回故复新。
旋添青草冢，更有白头人。
岁暮客将老，雪晴山欲春。
行行车与马，不尽洛阳尘。','',''),('quantangshi-01000','横吹曲辞 洛阳道','鄭渥','quantangshi','','卷1','客亭门外路东西，多少喧腾事不齐。
杨柳惹鞭公子醉，紵麻掩泪鲁人迷。
通宵尘土飞山月，是处经营夹御堤。
顷刻知音几存殁，半回依约认轮蹄。','',''),('quantangshi-01001','横吹曲辞 洛阳陌','李白','quantangshi','','卷2','白玉谁家郎，回车渡天津。
看花东上陌，惊动洛阳人。','',''),('quantangshi-01002','横吹曲辞 长安道','崔顥','quantangshi','','卷2','长安甲第高入云，谁家居住霍将军。
日晚朝回拥宾从，路傍拜揖何纷纷。
莫言炙手手可热，须臾火尽灰亦灭。
莫言贫贱即可欺，人生富贵自有时。
一朝天子赐颜色，世上悠悠应始知。','',''),('quantangshi-01003','横吹曲辞 长安道','孟郊','quantangshi','','卷2','胡风激秦树，贱子风中泣。
家家朱门开，得见不可入。
长安十二衢，投树鸟亦急。
高阁何人家？笙簧正喧吸。','',''),('quantangshi-01004','横吹曲辞 长安道','顧況','quantangshi','','卷2','长安道，人无衣，马无草，何不归来山中老。','',''),('quantangshi-01005','横吹曲辞 长安道','聶夷中','quantangshi','','卷2','此地无驻马，夜中犹走轮。
所以路旁草，少于衣上尘。','',''),('quantangshi-01006','横吹曲辞 长安道','韋應物','quantangshi','','卷2','汉家宫殿含云烟，两宫十里相连延。
晨霞出没弄丹阙，春雨依微自甘泉。
春雨依微春尚早，长安贵游爱芳草。
宝马横来下建章，香车却转避驰道。
贵游谁最贵，卫霍世难比。
何能蒙主恩？幸遇边尘起。
归来甲第拱皇居，朱门峨峨临九衢。
中有流苏合欢之宝帐，一百二十凤皇罗列含明珠。
下有锦铺翠被之粲烂，博山吐香五云散。
丽人绮阁情飘颻，头上鸳钗双翠翘。
低鬟曳袖回春雪，聚黛一声愁碧霄。
山珍海错弃藩篱，烹犊炮羔如折葵。
既请列侯封部曲，还将金印授庐儿。
欢荣若此何所苦，但苦白日西南驰。','',''),('quantangshi-01007','横吹曲辞 长安道','白居易','quantangshi','','卷2','花枝缺处青楼开，艳歌一曲酒一杯。
美人劝我急行乐，自古朱颜不再来。
君不见外州客，长安道，一回来，一回老。','',''),('quantangshi-01008','横吹曲辞 长安道','薛能','quantangshi','','卷2','汲汲复营营，东西连两京。
关繻古若在，山岳累应成。
各自有身事，不相知姓名。
交驰喧众类，分散入重城。
此路去无尽，万方人始生。
空余片言苦，来往觅刘桢。','',''),('quantangshi-01009','横吹曲辞 长安道','僧貫休','quantangshi','','卷2','憧憧合合，八表一辙。
黄尘雾合，车马火热。
名汤风雨，利辗霜雪。
千车万駄，半宿关月。
上有尧禹，下有夔契。
紫气银轮兮常覆金阙，仙掌捧日兮浊河澄澈。
愚将草木兮有言，与华封人兮不别。','',''),('quantangshi-01010','横吹曲辞 长安道','沈佺期','quantangshi','','卷2','秦地平如掌，层城出云汉。
楼阁九衢春，车马千门旦。
绿柳开复合，红尘聚还散。
日晚鬬鸡回，经过狭斜看。','',''),('quantangshi-01011','横吹曲辞 梅花落','盧照鄰','quantangshi','','卷2','梅岭花初发，天山雪未开。
雪处疑花满，花边似雪回。
因风入舞袖，杂粉向妆台。
匈奴几万里，春至不知来。','',''),('quantangshi-01012','横吹曲辞 梅花落','沈佺期','quantangshi','','卷2','铁骑几时回，金闺怨早梅。
雪中花已落，风暖叶应开。
夕逐新春管，香迎小岁杯。
感时何足贵，书里报轮台。','',''),('quantangshi-01013','横吹曲辞 梅花落','劉方平','quantangshi','','卷2','新岁芳梅树，繁苞四面同。
春风吹渐落，一夜几枝空。
小妇今如此，长城恨不穷。
莫将辽海雪，来比后庭中。','',''),('quantangshi-01014','横吹曲辞 紫骝马','盧照鄰','quantangshi','','卷2','骝马照金鞍，转战入皐兰。
塞门风稍急，长城水正寒。
雪暗鸣珂重，山长喷玉难。
不辞横绝漠，流血几时干。','',''),('quantangshi-01015','横吹曲辞 紫骝马','李白','quantangshi','','卷2','紫骝行且嘶，双飜碧玉蹄。
临流不肎渡，似惜锦障泥。
白雪关山远，黄云海树迷。
挥鞭万里去，安得念春闺。','',''),('quantangshi-01016','横吹曲辞 紫骝马','李益','quantangshi','','卷2','争场看鬬鸡，白鼻紫騧嘶。
漳水春归晚，丛台日向低。
歇鞍珠作汗，试劒玉如泥。
为谢红梁燕，年年妾独栖。','',''),('quantangshi-01017','横吹曲辞 紫骝马','秦韜玉','quantangshi','','卷2','渥洼奇骨本难求，况是豪家重紫骝。
膘大宜悬银压銙，力浑欺却玉衔头。
生狞弄影风随起，躞蹀冲尘汗满沟。
若遇丈夫皆调御，任从骑取觅封侯。','',''),('quantangshi-01018','横吹曲辞 骢马','李羣玉','quantangshi','','卷2','浮云何权奇，绝足势未知。
长嘶青海风，躞蹀振云丝。
由来渥洼种，本是苍龙儿。
穆满不再活，无人昆阆骑。
君识跃峤怯，宁劳耀金羁。
青刍与白水，空笑驽骀肥。
伯乐傥一见，应惊耳长垂。
当思八荒外，逐日向瑶池。','',''),('quantangshi-01019','横吹曲辞 骢马曲','紀唐天','quantangshi','','卷2','连钱出塞蹋沙蓬，岂比当时御史骢。
逐北自谙深碛路，连嘶谁念静边功。
登山每与青云合，弄影应知碧草同。
今日虏平将换妾，不如罗袖舞春风。','',''),('quantangshi-01020','横吹曲辞 雨雪曲','李端','quantangshi','','卷2','天山一丈雪，杂雨夜霏霏。
湿马胡歌乱，经烽汉火微。
丁零苏武别，疎勒范羌归。
若着关头过，长榆叶定稀。','',''),('quantangshi-01021','横吹曲辞 雨雪曲','翁綬','quantangshi','','卷2','边声四合殷河流，雨雪飞来徧陇头。
铁岭探人迷鸟道，阴山飞将湿貂裘。
斜飘旌斾过戎帐，半杂风沙入戍楼。','',''),('quantangshi-01022','横吹曲辞 刘生','盧照鄰','quantangshi','','卷2','刘生气不平，抱劒欲专征。
报恩为豪侠，死难在横行。
翠羽装劒鞘，黄金饰马缨。
但令一顾重，不吝百身轻。','',''),('quantangshi-01023','横吹曲辞 雍台歌','溫庭筠','quantangshi','','卷2','太子池南楼百尺，八窗新树疎帘隔。
黄金铺首画钩陈，羽葆亭童拂交戟。
盘纡阑楯临高台，帐殿临流鸾扇开。
早雁声鸣细波起，映花卤簿龙飞回。','',''),('quantangshi-01024','横吹曲辞 捉搦歌','張祜','quantangshi','','卷2','门上关，墙上棘，窗中女子声唧唧，洛阳大道徒自直。
女子心在婆舍侧，呜呜笼鸟触四隅。
养男男娶妇，养女女嫁夫。
阿婆六十翁七十，不知女子长日泣，从他嫁去无悒悒。','',''),('quantangshi-01025','横吹曲辞 幽州胡马客歌','李白','quantangshi','','卷2','幽州胡马客，绿眼虎皮冠。
笑拂两只箭，万人不可干。
弯弓若转月，白雁落云端。
双双掉鞭行，游猎向楼兰。
出门不顾后，报国死何难。
天骄五单于，狼戾好凶残。
牛马散北海，割鲜若虎餐。
虽居燕支山，不道朔雪寒。
妇女马上笑，颜如赬玉盘。
飜入射鸟兽，花月醉雕鞍。
旄头四光芒，争战若蜂攒。
白刃洒赤血，流沙为之丹。
名将古谁是，疲兵良可叹。
何时天狼灭？父子得闲安。','',''),('quantangshi-01026','横吹曲辞 白鼻騧','李白','quantangshi','','卷2','银鞍白鼻騧，绿地障泥锦。
细雨春风花落时，挥鞭且就胡姬饮。','',''),('quantangshi-01027','横吹曲辞 白鼻騧','張祜','quantangshi','','卷2','为底胡姬酒，长来白鼻騧。
摘莲抛水上，郎意在浮花。','',''),('quantangshi-01028','相和歌辞 箜篌引','李賀','quantangshi','','卷2','公乎公乎，提壶将焉如？
屈平沈湘不足慕，徐衍入海诚为愚。
公乎公乎，牀有菅席盘有鱼。
北里有贤兄，东邻有小姑。
陇亩油油黍与葫，瓦甒浊醪蚁浮浮。
黍可食，醪可饮，公乎公乎其奈居。
被发奔流竟何如？贤兄小姑哭呜呜。','',''),('quantangshi-01029','相和歌辞 公无渡河','李白','quantangshi','','卷2','黄河西来决崐崘，咆吼万里触龙门。
波滔天，尧咨嗟。
大禹理百川，儿啼不窥家。
杀湍湮洪水，九州始蚕麻。
其害乃去，茫然风沙。
被发之叟狂而痴，清晨径流欲奚为。
旁人不惜妻止之，公无渡河苦渡之。
虎可搏，河难凭。
公果溺死流海湄，有长鲸白齿若雪山。
公乎公乎，挂骨于其间，箜篌所悲竟不还。','',''),('quantangshi-01030','相和歌辞 公无渡河','王建','quantangshi','','卷2','渡头恶天两岸远，波涛塞川如叠坂。
幸无白刃驱向前，何用将身自弃捐。
蛟龙啮尸鱼食血，黄泥直下无青天。
男儿纵轻妇人语，惜君性命还须取。
妇人无力挽断衣，舟沈身死悔难追，公无渡河公自为。','',''),('quantangshi-01031','相和歌辞 公无渡河','溫庭筠','quantangshi','','卷2','黄河怒浪连天来，大响谹谹如殷雷。
龙伯驱风不敢上，百川喷雪高崔嵬。
二十五弦何太哀？请公勿渡立裴回。
下有狂蛟锯为尾，裂帆截棹磨霜齿。
神锥凿石塞神潭，白马䟃𧽼赤尘起。
公乎跃马扬玉鞭，灭没高蹄日千里。','',''),('quantangshi-01032','相和歌辞 公无渡河','王叡','quantangshi','','卷2','浊波洋洋兮凝晓雾，公无渡河兮公苦渡。
风号水激兮呼不闻，提壶看入兮中流去。
浪摆衣裳兮随步没，沈尸深入兮蛟螭窟。
蛟螭尽醉兮君血干，推出黄沙兮泛君骨。
当时君死妾何适？遂就波澜合魂魄。
愿持精卫衔石心，穷取河源塞泉脉。','',''),('quantangshi-01033','相和歌辞 江南曲','之問','quantangshi','','卷2','妾住越城南，离居不自堪。
采花惊曙鸟，摘叶餧春蚕。
嬾结茱萸带，愁安玳瑁簪。
侍臣消瘦尽，日暮碧江潭。','',''),('quantangshi-01034','相和歌辞 江南曲','劉眘虛','quantangshi','','卷2','美人何荡漾，湖上风月长。
玉手欲有赠，裴回双鸣璫。
歌声随渌水，怨色起朝阳。
日暮还家望，云波横洞房。','',''),('quantangshi-01035','相和歌辞 江南曲','丁仙芝','quantangshi','','卷2','长干斜路北，近浦是儿家。
有意来相访，明朝出浣纱。
发向横塘口，船开值急流。
知郎旧时意，且请拢船头。
昨暝逗南陵，风声波浪阻。
入浦不逢人，归家谁信汝。
未晓已成妆，乘潮去茫茫。
因从京口渡，使报邵陵王。
始下芙蓉楼，言发琅邪岸。
急为打船开，恶许傍人见。','',''),('quantangshi-01036','相和歌辞 江南曲八首 一','劉希夷','quantangshi','','卷2','暮宿南洲草，晨行北岸林。
日悬沧海阔，水隔洞庭深。
烟景无留意，风波有异浔。
岁游难极目，春戏易为心。
朝夕无荣遇，芳菲已满襟。','',''),('quantangshi-01037','相和歌辞 江南曲八首 二','劉希夷','quantangshi','','卷2','艳唱潮初落，江花露未曦。
春洲惊翡翠，朱服弄芳菲。
画舫烟中浅，青阳日际微。
锦帆冲浪湿，罗袖拂行衣。
含情罢所采，相叹惜流晖。','',''),('quantangshi-01038','相和歌辞 江南曲八首 三','劉希夷','quantangshi','','卷2','君为陇西客，妾遇江南春。
朝游含灵果，夕采弄风苹。
果气时不歇，苹花日自新。
以此江南物，持赠陇西人。
空盈万里怀，欲赠竟无因。','',''),('quantangshi-01039','相和歌辞 江南曲八首 四','劉希夷','quantangshi','','卷2','皓如楚江月，霭若吴岫云。
波中自皎镜，山上亦氛氲。
明月留照妾，轻云持赠君。
山川各离散，光气乃殊分。
天涯一为别，江北自相闻。','',''),('quantangshi-01040','相和歌辞 江南曲八首 五','劉希夷','quantangshi','','卷2','舣舟乘潮去，风帆振草凉。
潮平见楚甸，天际望维扬。
洄溯经千里，烟波接两乡。
云明江屿出，日照海流长。
此中逢岁晏，浦树落花芳。','',''),('quantangshi-01041','相和歌辞 江南曲八首 六','劉希夷','quantangshi','','卷2','暮春三月晴，维扬吴楚城。
城临大江汜，回映洞浦清。
晴云曲金阁，珠楼碧烟里。
月明芳树羣鸟飞，风过长林杂花起。
可怜离别谁家子，于此一至情何已。','',''),('quantangshi-01042','相和歌辞 江南曲八首 七','劉希夷','quantangshi','','卷2','北堂红草盛丰茸，南湖碧水照芙蓉。
朝游暮起金花尽，渐觉罗裳珠露浓。
自惜妍华三五岁，已叹关山千万重。
人情一去无还日，欲赠怀芳怨不逢。','',''),('quantangshi-01043','相和歌辞 江南曲八首 八','劉希夷','quantangshi','','卷2','忆昔江南年盛时，平生怨在长洲曲。
冠盖星繁湘水上，冲风摽落洞庭渌。
落花舞袖红纷纷，朝霞高阁洗晴云。
谁言此处婵娟子，珠玉为心以奉君。','',''),('quantangshi-01044','相和歌辞 江南曲','于鵠','quantangshi','','卷2','偶向江边采白苹，还随女伴赛江神。
众中不敢分明语，暗掷金钱卜远人。','',''),('quantangshi-01045','相和歌辞 江南曲','李益','quantangshi','','卷2','嫁得瞿塘贾，朝朝误妾期。
早知潮有信，嫁与弄潮儿。','',''),('quantangshi-01046','相和歌辞 江南曲','李賀','quantangshi','','卷2','汀洲白苹草，柳恽乘马归。
江头樝树香，岸上蝴蝶飞。
酒杯若叶露，玉轸蜀桐虚。
朱楼通水陌，沙暖一双鱼。','',''),('quantangshi-01047','相和歌辞 江南曲','李商隱','quantangshi','','卷2','郎船安两桨，侬舸动双桡。
埽黛开宫额，裁裙约楚腰。
乖期方积思，临醉欲拚娇。
莫以采菱唱，欲羡秦台箫。','',''),('quantangshi-01048','相和歌辞 江南曲','韓翃','quantangshi','','卷2','长乐花枝雨点消，江城日暮好相邀。
春楼不闭葳蕤锁，绿水回通宛转桥。','',''),('quantangshi-01049','相和歌辞 江南曲','溫庭筠','quantangshi','','卷2','妾家白苹浦，日上芙蓉檝。
轧轧摇桨声，移舟入茭叶。
溪长茭叶深，作底难相寻。
避郎郎不见，鸂鶒自浮沈。
拾萍萍无根，采莲莲有子。
不作浮萍生，宁作藕花死。
岸傍骑马郎，乌帽紫游缰。
含愁复含笑，回首问横塘。
妾住金陵步，门前朱雀航。
流苏持作帐，芙蓉持作梁。
出入金犊幰，兄弟侍中郎。
前年学歌舞，定得郎相许。
连娟眉绕山，依约腰如杵。
凤管悲若咽，鸾弦娇欲语。
扇薄露红鈆，罗轻压金缕。
明月西南楼，珠帘玳瑁钩。
横波巧能笑，弯蛾不识愁。
花开子留树，草长根依土。
早闻金沟远，底事归郎许。
不学杨白花，朝朝泪如雨。','',''),('quantangshi-01050','相和歌辞 江南曲','張籍','quantangshi','','卷2','江南人家多橘树，吴姬舟上织白紵。
土地卑湿饶虫蛇，连木为牌入江住。
江村亥日长为市，落帆渡桥来浦里。
青莎覆城竹为屋，无井家家饮潮水。
长江午日酤春酒，高高酒旗悬江口。
倡楼两岸悬水栅，夜唱竹枝留北客。
江南风土欢乐多，悠悠处处尽经过。','',''),('quantangshi-01051','相和歌辞 江南曲','羅隱','quantangshi','','卷2','江烟湿雨鲛绡輭，漠漠远山眉黛浅。
水国多愁又有情，夜槽压酒银船满。
綳丝采怨凝晓空，吴王台榭春梦中。
鸳鸯鸂鶒唤不起，平铺渌水眠东风。
西陵路边月悄悄，油壁轻车嫁苏小。','',''),('quantangshi-01052','相和歌辞 江南曲','陸龜蒙','quantangshi','','卷2','为爱江南雪，涉江聊采苹。
水深烟浩浩，空对双车轮。
车轮明月团，车盖浮云盘。
云月徒自好，水中行路难。
遥遥洛阳道，夹岸生春草。
寄语棹船郎，莫夸风浪好。','',''),('quantangshi-01053','相和歌辞 江南曲 一','陸龜蒙','quantangshi','','卷2','鱼戏莲叶间，参差隐叶扇。
䴔䴖鸀鳿窥，潋滟无因见。','',''),('quantangshi-01054','相和歌辞 江南曲 二','陸龜蒙','quantangshi','','卷2','鱼戏莲叶东，初霞射红尾。
傍临谢山侧，恰值清风起。','',''),('quantangshi-01055','相和歌辞 江南曲 三','陸龜蒙','quantangshi','','卷2','鱼戏莲叶西，盘盘舞波急。
潜依曲岸凉，正对斜光入。','',''),('quantangshi-01056','相和歌辞 江南曲 四','陸龜蒙','quantangshi','','卷2','鱼戏莲叶南，欹危午烟叠。
光摇越鸟巢，影乱吴娃檝。','',''),('quantangshi-01057','相和歌辞 江南曲 五','陸龜蒙','quantangshi','','卷2','鱼戏莲叶北，澄阳动微涟。
回看帝子渚，稍背鄂君船。','',''),('quantangshi-01058','相和歌辞 度关山','李端','quantangshi','','卷2','雁塞日初晴，胡关雪复平。
危竿缘广漠，古窦傍长城。
拔劒金星出，弯弧玉羽鸣。
谁知系虏者，贾谊是书生。','',''),('quantangshi-01059','相和歌辞 关山曲 一','馬戴','quantangshi','','卷2','金锁耀兜鍪，黄云拂紫骝。
叛羌旗下戮，陷壁夜中收。
霜霰戎衣故，关河碛气秋。
箭创殊未合，更遣击兰州。','',''),('quantangshi-01060','相和歌辞 关山曲 二','馬戴','quantangshi','','卷2','火发龙山北，中宵易左贤。
勒兵临汉水，惊雁散胡天。
木落防河急，军孤受敌偏。
犹闻汉皇怒，按劒待开边。','',''),('quantangshi-01061','相和歌辞 登高丘而望远','李白','quantangshi','','卷2','登高丘而望远海，六鳌骨已霜，三山流安在。
扶桑半摧折，白日沈光彩。
银台金阙如梦中，秦皇汉武空相待。
精卫费木石，鼋鼍无所凭。
君不见骊山茂陵尽灰灭，牧羊之子来攀登。
盗贼劫宝玉，精灵竟何能。','',''),('quantangshi-01062','相和歌辞 蒿里','僧貫休','quantangshi','','卷2','兔不迟，乌更急，但恐穆王八骏，着鞭不及。
所以蒿里，坟出蕺蕺，气凌云天，龙腾凤集，尽为风消土吃，狐掇蚁拾。
黄金不啼玉不泣，白杨骚屑。
乱风愁月，折碑石人。
莽秽榛没，牛羊窸窣。
时见牧童儿，弄枯骨。','',''),('quantangshi-01063','相和歌辞 挽歌','趙微明','quantangshi','','卷2','寒日蒿上明，凄凄郭东路。
素车谁家子，丹旐引将去。
原下荆棘丛，丛边有新墓。
人间痛伤别，此是长别处。
旷野何萧条，青松白杨树。','',''),('quantangshi-01064','相和歌辞 挽歌二首 一','于鵠','quantangshi','','卷2','阴风吹黄蒿，挽歌渡秋水。
车马却归城，孤坟月明里。','',''),('quantangshi-01065','相和歌辞 挽歌二首 二','于鵠','quantangshi','','卷2','双辙出郭门，緜緜东西道。
送死多于生，几人得终老。
见人切肺肝，不如归山好。
不闻哀哭声，默默安怀抱。
时尽从物化，又免生忧扰。
世间寿者稀，尽为悲伤恼。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01066','相和歌辞 挽歌','孟雲卿','quantangshi','','卷2','草草门巷喧，涂车俨成位。
冥寞何所须，尽我生人意。
北邙路非远，此别终天地。
临穴频抚棺，至哀反无泪。
尔形未衰老，尔息犹童穉。
骨肉不可离，皇天若容易。
房帷即虚张，庭宇为哀次。
薤露歌若斯，人生尽如寄。','',''),('quantangshi-01067','相和歌辞 挽歌','白居易','quantangshi','','卷2','丹旐何飞扬，素骖亦悲鸣。
晨光照闾巷，輀车俨欲行。
萧条九月天，哀挽出重城。
借问送者谁，妻子与弟兄。
苍苍上古原，峨峨开新茔。
含酸一恸哭，异口同哀声。
旧垄转芜绝，新坟日罗列。
春风草绿北邙山，此地年年生死别。','',''),('quantangshi-01068','相和歌辞 对酒','崔國輔','quantangshi','','卷2','行行日将夕，荒村古冢无人迹。
朦胧荆棘一鸟飞，屡唱提壶酤酒吃。
古人不达酒不足，遗恨精灵传此曲。
寄言当代诸少年，平生且尽杯中渌。','',''),('quantangshi-01069','相和歌辞 对酒二首 一','李白','quantangshi','','卷2','松子栖金华，安期入蓬海。
此人古之仙，羽化竟何在？
浮生速流电，倏忽变光彩。
天地无凋换，容颜有迁改。
对酒不肯饮，含情欲谁待。','',''),('quantangshi-01070','相和歌辞 对酒二首 二','李白','quantangshi','','卷2','劝君莫拒杯，春风笑人来。
桃李如旧识，倾花向我开。
流莺啼碧树，明月窥金罍。
昨来朱颜子，今日白发催。
棘生石虎殿，鹿走姑苏台。
自古帝王宅，城阙闭黄埃。
君若不饮酒，昔人安在哉。','',''),('quantangshi-01071','相和歌辞 陌上桑','李白','quantangshi','','卷2','美女渭桥东，春还事蚕作。
五马如飞龙，青丝结金络。
不知谁家子，调笑来相谑。
妾本秦罗敷，玉颜艳名都。
绿条映素手，采桑向城隅。
使君且不顾，况复论秋胡。
寒螿爱碧草，鸣凤栖青梧。
托心自有处，但怪傍人愚。
徒令白日暮，高驾空踟蹰。','',''),('quantangshi-01072','相和歌辞 陌上桑','常建','quantangshi','','卷2','翳翳陌上桑，南枝交北堂。
美人金梯出，素手自提筐。
非但畏蚕饥，盈盈娇路傍。','',''),('quantangshi-01073','相和歌辞 陌上桑','陸龜蒙','quantangshi','','卷2','皓齿还如贝色含，长眉亦似烟华贴。
邻娃尽着绣裆襦，独自提筐采蚕叶。','',''),('quantangshi-01074','相和歌辞 采桑','郎大家宋氏','quantangshi','','卷2','春来南雁归，日去西蚕远。
妾思纷何极，客游殊未返。','',''),('quantangshi-01075','相和歌辞 采桑','劉希夷','quantangshi','','卷2','杨柳送行人，青青西入秦。
秦家采桑女，楼上不胜春。
盈盈灞水曲，步步春芳绿。
红脸耀明珠，绛唇含白玉。
回首渭桥东，遥怜树色同。
青丝娇落日，缃绮弄春风。
携笼长叹息，逶迤恋春色。
看花若有情，倚树疑无力。
薄暮思悠悠，使君南陌头。
相逢不相识，归去梦青楼。','',''),('quantangshi-01076','相和歌辞 采桑','李彥暐','quantangshi','','卷2','采桑畏日高，不待春眠足。
攀条有余愁，那矜貌如玉。
千金岂不赠，五马空踟躅。
何以变真性，幽篁雪中绿。','',''),('quantangshi-01077','相和歌辞 采桑','王建','quantangshi','','卷2','鸟鸣桑叶间，叶绿条复柔。
攀看去手近，放下长长钩。
黄花盖野田，白马少年游。
所念岂回顾，良人在高楼。','',''),('quantangshi-01078','相和歌辞 日出行','李白','quantangshi','','卷2','日出东方隈，似从地底来。
历天又入海，六龙所舍安在哉？
其始与终古不息，人非元气安能与之久裴回。
草不谢荣于春风，木不怨落于秋天。
谁挥鞭策驱四运，万物兴歇皆自然。
羲和羲和，汝奚汩没于荒淫之波。
鲁阳何德？驻景挥戈。
逆道违天，矫诬实多。
吾将囊括大块，浩然与溟涬同科。','',''),('quantangshi-01079','相和歌辞 日出行','李賀','quantangshi','','卷2','白日下崐崘，发光如舒丝。
徒照葵藿心，不照游子悲。
折折黄河曲，日从中央转。
阳谷耳曾闻，若木眼不见。
奈何铄石，胡为销人。
羿弯弓属矢那不中，足令久不得奔，讵教晨光夕昏。','',''),('quantangshi-01080','相和歌辞 王昭君','崔國輔','quantangshi','','卷2','汉使南还尽，胡中妾独存。
紫台緜望绝，秋草不堪论。','',''),('quantangshi-01081','相和歌辞 王昭君','崔國輔','quantangshi','','卷2','一回望月一回悲，望月月移人不移。
何时得见汉朝使？为妾传书斩画师。','',''),('quantangshi-01082','相和歌辞 王昭君','盧照鄰','quantangshi','','卷2','合殿恩中绝，交河使渐稀。
肝肠辞玉辇，形影向金微。
汉宫草应绿，胡庭沙正飞。
愿逐三秋雁，年年一度归。','',''),('quantangshi-01083','相和歌辞 王昭君','駱賓王','quantangshi','','卷2','敛容辞豹尾，缄怨度龙鳞。
金钿明汉月，玉箸染胡尘。
妆镜菱花暗，愁眉柳叶嚬。
惟有清笳曲，时闻芳树春。','',''),('quantangshi-01084','相和歌辞 王昭君','沈佺期','quantangshi','','卷2','非君惜鸾殿，非妾妬蛾眉。
薄命由骄虏，无情是画师。
嫁来胡地恶，不竝汉宫时。
心苦无聊赖，何堪上马辞。','',''),('quantangshi-01085','相和歌辞 王昭君','梁獻','quantangshi','','卷2','图画失天真，容华坐误人。
君恩不可再，妾命在和亲。
泪点关山月，衣销边塞尘。
一闻阳鸟至，思绝汉宫春。','',''),('quantangshi-01086','相和歌辞 王昭君','上官儀','quantangshi','','卷2','玉关春色晚，金河路几千。
琴悲桂条上，笛怨柳花前。
雾掩临妆月，风惊入鬓蝉。
缄书待还使，泪尽白云天。','',''),('quantangshi-01087','相和歌辞 王昭君','董思恭','quantangshi','','卷2','琵琶马上弹，行路曲中难。
汉月正南远，燕山直北寒。
髻鬟风拂散，眉黛雪霑残。
斟酌红颜尽，何劳镜里看。','',''),('quantangshi-01088','相和歌辞 王昭君','顧朝陽','quantangshi','','卷2','莫将铅粉匣，不用镜花光。
一去边城路，何情更画妆。
影销胡地月，衣尽汉宫香。
妾死非关命，祗缘怨断肠。','',''),('quantangshi-01089','相和歌辞 王昭君三首 一','東方虯','quantangshi','','卷2','汉道初全盛，朝廷足武臣。
何须薄命妾，辛苦事和亲。','',''),('quantangshi-01090','相和歌辞 王昭君三首 二','東方虯','quantangshi','','卷2','揜涕辞丹凤，衔悲向白龙。
单于浪惊喜，无复旧时容。','',''),('quantangshi-01091','相和歌辞 王昭君三首 三','東方虯','quantangshi','','卷2','胡地无花草，春来不似春。
自然衣带缓，非是为腰身。','',''),('quantangshi-01092','相和歌辞 王昭君三首 一','郭元振','quantangshi','','卷2','自嫁单于国，长衔汉掖悲。
容颜日顦顇，有甚画图时。','',''),('quantangshi-01093','相和歌辞 王昭君三首 二','郭元振','quantangshi','','卷2','厌践冰霜域，嗟为边塞人。
思从汉南猎，一见汉家尘。','',''),('quantangshi-01094','相和歌辞 王昭君三首 三','郭元振','quantangshi','','卷2','闻有南河信，传闻杀画师。
始知君惠重，更遣画蛾眉。','',''),('quantangshi-01095','相和歌辞 王昭君','劉長卿','quantangshi','','卷2','自矜妖艳色，不顾丹青人。
那知粉缋能相负，却使容华飜误身。
上马辞君嫁骄虏，玉颜对人啼不语。
北风雁急浮清秋，万里独见黄河流。
纤腰不复汉宫宠，双蛾长向胡天愁。
琵琶弦中苦调多，萧萧羌笛声相和。
可怜一曲传乐府，能使千秋伤绮罗。','',''),('quantangshi-01096','相和歌辞 王昭君二首 一','李白','quantangshi','','卷2','汉家秦地月，流影照明妃。
一上玉关道，天涯去不归。
汉月还从东海出，明妃西嫁无来日。
燕支长寒雪作花，蛾眉顦顇没胡沙。
生乏黄金枉图画，死留青冢使人嗟。','',''),('quantangshi-01097','相和歌辞 王昭君二首 二','李白','quantangshi','','卷2','昭君拂玉鞍，上马啼红颊。
今日汉宫人，明朝胡地妾。','',''),('quantangshi-01098','相和歌辞 王昭君','儲光羲','quantangshi','','卷2','日暮惊沙乱雪飞，傍人相劝易罗衣。
强来前帐看歌舞，共待单于夜猎归。','',''),('quantangshi-01099','相和歌辞 王昭君','僧皎然','quantangshi','','卷2','自倚婵娟望主恩，谁知美恶忽相飜。
黄金不买汉宫貌，青冢空埋胡地魂。','',''),('quantangshi-01100','相和歌辞 王昭君二首 一','白居易','quantangshi','','卷2','满面胡沙满鬓风，眉销残黛脸销红。
愁苦辛勤顦顇尽，如今却似画图中。','',''),('quantangshi-01101','相和歌辞 王昭君二首 二','白居易','quantangshi','','卷2','汉使却回凭寄语，黄金何日赎蛾眉？君王若问妾颜色，莫道不如宫里时。','',''),('quantangshi-01102','相和歌辞 王昭君','令狐楚','quantangshi','','卷2','锦车天外去，毳幕云中开。
魏阙苍龙远，萧关赤雁哀。','',''),('quantangshi-01103','相和歌辞 王昭君','張仲素','quantangshi','','卷2','仙娥今下嫁，骄子自同和。
劒戟归田尽，牛羊绕塞多。','',''),('quantangshi-01104','相和歌辞 王昭君','李商隱','quantangshi','','卷2','毛延寿画欲通神，忍为黄金不为人。
马上琵琶行万里，汉宫长有隔生春。','',''),('quantangshi-01105','相和歌辞 明妃曲','王偃','quantangshi','','卷2','北望单于日半斜，明君马上泣胡沙。
一双泪滴黄河水，应得东流入汉家。','',''),('quantangshi-01106','相和歌辞 昭君词','張文琮','quantangshi','','卷2','戒途飞万里，回首望三秦。
忽见天山雪，还疑上苑春。
玉痕垂泪粉，罗袂拂胡尘。
为得胡中曲，还悲远嫁人。','',''),('quantangshi-01107','相和歌辞 昭君词','陳昭','quantangshi','','卷2','跨鞍今永诀，垂泪别亲宾。
汉地行将远，胡关逐望新。
交河拥塞路，陇首暗沙尘。
唯有孤明月，犹能远送人。','',''),('quantangshi-01108','相和歌辞 昭君词','戴叔倫','quantangshi','','卷2','汉宫若远近，路在寒沙上。
到死不得归，何人共南望。','',''),('quantangshi-01109','相和歌辞 昭君词','李端','quantangshi','','卷2','李陵初送子卿回，汉月明明照帐来。
忆着长安旧游处，千门万户玉楼台。','',''),('quantangshi-01110','相和歌辞 楚妃叹','張籍','quantangshi','','卷2','湘云初起江沈沈，君王遥在云梦林。
江南雨多旌旗暗，台下朝朝春水深。
章华殿前朝万国，君心独自终无极。
楚兵满地能逐禽，谁用一身继筋力。
西江若飜云梦中，麋鹿死尽应还宫。','',''),('quantangshi-01111','相和歌辞 楚妃怨','張籍','quantangshi','','卷2','梧桐叶下黄金井，横架辘轳牵素绠。
美人初起天未明，手拂银瓶秋水冷。','',''),('quantangshi-01112','相和歌辞 王子乔','之問','quantangshi','','卷2','王子乔，爱神仙，七月七日上宾天。
白虎摇瑟凤吹笙，乘骑云气吸日精。
吸日精，长不归，遗庙今在而人非。
空望山头草，草露湿君衣。','',''),('quantangshi-01113','相和歌辞 蜀国弦','李賀','quantangshi','','卷2','枫香晚华静，锦水南山影。
惊石坠猨哀，竹云愁半岭。
凉月生秋浦，玉沙鳞鳞光。
谁家红泪客，不忍过瞿塘。','',''),('quantangshi-01114','相和歌辞 长歌行','李白','quantangshi','','卷2','桃李得日开，荣华照当年。
东风动百物，草木尽欲言。
枯枝无丑叶，涸水吐清泉。
大力运天地，羲和无停鞭。
功名不早着，竹帛将何宣？
桃李务青春，谁能贯白日。
富贵与神仙，蹉跎成两失。
金石犹销铄，风霜无久质。
畏落日月后，强欢歌与酒。
秋霜不惜人，倏忽侵蒲柳。','',''),('quantangshi-01115','相和歌辞 长歌行','王昌齡','quantangshi','','卷2','旷野饶悲风，飕飕黄蒿草。
系马停白杨，谁知我怀抱。
所是同袍者，相逢尽衰老。
况登汉家陵，南望长安道。
下有枯树根，上有鼷鼠窠。
高皇子孙尽，千古无人过。
宝玉频发掘，精灵其奈何？
人生须达命，有酒且长歌。','',''),('quantangshi-01116','相和歌辞 短歌行','聶夷中','quantangshi','','卷2','八月木荫薄，十叶三堕枝。
人生过五十，亦已同此时。
朝出东郭门，嘉树郁参差。
暮出西郭门，原草已离披。
南邻好台榭，北邻善歌吹。
荣华忽消歇，四顾令人悲。
生死与荣辱，四者乃常期。
古人耻其名，没世无人知。
无言鬓似霜，勿谓发如丝。','',''),('quantangshi-01117','相和歌辞 短歌行','李白','quantangshi','','卷2','白日何短短，百年苦易满。
苍穹浩茫茫，万劫太极长。
麻姑垂两鬓，一半已成霜。
天公见玉女，大笑亿千场。
吾欲搅六龙，回车挂扶桑。
北斗酌美酒，劝龙各一觞。
富贵非所愿，为人驻颓光。','',''),('quantangshi-01118','相和歌辞 短歌行六首 一','顧況','quantangshi','','卷2','城边路，今人犂田昔人墓。
岸上沙，昔时江水今人家。
今人昔人共长叹，四气相催节回换。
明月皎皎入华池，白云离离度清汉。','',''),('quantangshi-01119','相和歌辞 短歌行六首 二','顧況','quantangshi','','卷2','我欲升天天隔霄，我思渡水水无桥。
我欲上山山路险，我欲汲井井泉遥。
越人翠被今何夕，独立沙边江草碧。','',''),('quantangshi-01120','相和歌辞 短歌行六首 三','顧況','quantangshi','','卷2','新系青丝百尺绳，心在君家辘轳上。
我心皎洁君不知，辘轳一转一惆怅。','',''),('quantangshi-01121','相和歌辞 短歌行六首 四','顧況','quantangshi','','卷2','何处春风吹晓幕？江南绿水通朱阁。
美人二八面如花，泣向东风畏花落。','',''),('quantangshi-01122','相和歌辞 短歌行六首 五','顧況','quantangshi','','卷2','临春风，听春鸟。
别时多，见时少。
愁人夜永不得眠，瑶井玉绳相向晓。','',''),('quantangshi-01123','相和歌辞 短歌行六首 六','顧況','quantangshi','','卷2','轩辕皇帝初得仙，鼎湖一去三千年。
周流三十六洞天，洞中日月星辰连。
骑龙驾景游八极，轩辕弓劒无人识，东海青童寄消息。','',''),('quantangshi-01124','相和歌辞 短歌行','王建','quantangshi','','卷2','人初生，日初出。
上山迟，下山疾。
百年三万六千朝，夜里分将彊半日。
有歌有舞间早为，昨日健于今日时。
人家见生男女好，不知男女催人老。
短歌行，无乐声。','',''),('quantangshi-01125','相和歌辞 短歌行','張籍','quantangshi','','卷2','青天荡荡高且虚，上有白日无根株。
流光暂出还入地，催我少年不须臾。
与君相逢不寂寞，衰老不复如今乐。
玉卮盛酒置君前，再拜愿君千万年。','',''),('quantangshi-01126','相和歌辞 短歌行二首 一','白居易','quantangshi','','卷2','曈曈太阳如火色，上行千里下一刻。
出为白昼入为夜，圜转如珠住不得。
住不得，可奈何？为君举酒歌短歌。
歌声苦，词亦苦，四座少年君听取。
今夕未竟明夕催，秋风才往春风回。
人无根蔕时不驻，朱颜白日相隳颓。
劝君且强笑一面，劝君复强饮一杯。
人生不得长欢乐，年少须臾老到来。','',''),('quantangshi-01127','相和歌辞 短歌行二首 二','白居易','quantangshi','','卷2','世人求富贵，多为身嗜欲。
盛衰不自由，得失常相逐。
问君少年日，苦学将干禄。
负笈尘中游，抱书雪前宿。
布衾不周体，藜茄才充腹。
三十登宦途，五十被朝服。
奴温已挟纩，马肥初食粟。
未敢议欢游，尚为名检束。
耳目聋暗后，堂上调丝竹。
牙齿缺落时，盘中堆酒肉。
彼来此已去，外余中不足。
少壮与荣华，相避如寒燠。
青云去地远，白日终天速。
从古无奈何，短歌听一曲。','',''),('quantangshi-01128','相和歌辞 短歌行','陸龜蒙','quantangshi','','卷2','爪牙在身上，陷穽犹可制。
爪牙在胷中，劒戟无所畏。
人言畏猛虎，谁是撩头毙。
祗见古来心，奸雄暗相噬。','',''),('quantangshi-01129','相和歌辞 短歌行','僧皎然','quantangshi','','卷2','古人若不死，吾亦何所悲。
萧萧烟雨九原上，白杨青松葬者谁。
贵贱同一尘，死生同一指。
人生在世共如此，何异浮云与流水。
短歌行，短歌无穷日已倾。
邺宫梁苑徒有名，春草秋风伤我情。
何为不学金仙侣？一悟空王无死生。','',''),('quantangshi-01130','相和歌辞 铜雀台','王無競','quantangshi','','卷2','北登铜雀上，西望青松郭。
繐帐空苍苍，陵田纷漠漠。
平生事已变，歌吹宛犹昨。
长袖拂玉麈，遗情结罗幕。
妾怨在朝露，君恩岂中薄。
高台奏曲终，曲终泪横落。','',''),('quantangshi-01131','相和歌辞 铜雀台','鄭愔','quantangshi','','卷2','日斜漳浦望，风起邺台寒。
玉座平生晚，金尊妓吹阑。
舞余依帐泣，歌罢向陵看。
萧索松风暮，愁烟入井阑。','',''),('quantangshi-01132','相和歌辞 铜雀台','劉長卿','quantangshi','','卷2','娇爱更何日？高台空数层。
含啼映双袖，不忍看西陵。
漳河东流无复来，百花辇路为苍苔。
青楼月夜长寂寞，碧云日暮空裴回。
君不见邺中万事非昔时，古人何在今人悲。
春风不逐君王去，草色年年旧宫路。
宫中歌舞已浮云，空指行人往来处。','',''),('quantangshi-01133','相和歌辞 铜雀台','賈至','quantangshi','','卷2','日暮铜雀静，西陵鸟雀归。
抚弦心断绝，听管泪霏霏。
灵几临朝奠，空牀卷夜衣。
苍苍川上月，应照妾魂飞。','',''),('quantangshi-01134','相和歌辞 铜雀台','羅隱','quantangshi','','卷2','强歌强舞竟难胜，花落花开泪满缯。
祗合当年伴君死，免教顦顇望西陵。','',''),('quantangshi-01135','相和歌辞 铜雀台','薛能','quantangshi','','卷2','魏帝当时铜雀台，黄花深映棘丛开。
人生富贵须回首，此地岂无歌舞来。','',''),('quantangshi-01136','相和歌辞 铜雀台','張氏琰','quantangshi','','卷2','君王冥寞不可见，铜雀歌舞空裴回。
西陵啧啧悲宿鸟，空殿沈沈闭青苔。
青苔无人迹，红粉空相哀。','',''),('quantangshi-01137','相和歌辞 铜雀台','梁氏瓊','quantangshi','','卷2','歌扇向陵开，齐行奠玉杯。
舞时飞燕列，梦里片云来。
月色空余恨，松声暮更哀。
谁怜未死妾，掩袂下铜台。','',''),('quantangshi-01138','相和歌辞 铜雀妓 一','王勃','quantangshi','','卷2','妾本深宫妓，曾城闭九重。
君王欢爱尽，歌舞为谁容。
锦衾不复襞，罗衣谁再缝。
高台西北望，流涕向青松。','',''),('quantangshi-01139','相和歌辞 铜雀妓 二','王勃','quantangshi','','卷2','金凤邻铜雀，漳河望邺城。
君王无处所，台榭若平生。
舞筵纷可就，歌梁俨未倾。
西陵松槚冷，谁见绮罗情。','',''),('quantangshi-01140','相和歌辞 铜雀妓','沈佺期','quantangshi','','卷2','昔年分鼎地，今日望陵台。
一旦雄图尽，千秋遗令开。
绮罗君不见，歌舞妾空来。
恩共漳河水，东流无重回。','',''),('quantangshi-01141','相和歌辞 铜雀妓','喬知之','quantangshi','','卷2','金阁惜分香，鈆华不重妆。
空余歌舞地，犹是为君王。
哀弦调已绝，艳曲不须长。
共看西陵暮，秋烟生白杨。','',''),('quantangshi-01142','相和歌辞 铜雀妓','王適','quantangshi','','卷2','日暮铜雀迥，幽声玉座清。
萧森松柏望，委郁绮罗情。
君恩不再重，妾舞为谁轻。','',''),('quantangshi-01143','相和歌辞 铜雀妓','歐陽詹','quantangshi','','卷2','萧条登古台，回首黄金屋。
落叶不归林，高陵永为谷。
妆容徒自丽，舞态阅谁目。
惆怅繐帷前，歌声苦于哭。','',''),('quantangshi-01144','相和歌辞 铜雀妓','袁暉','quantangshi','','卷2','君爱本相饶，从来事舞腰。
那堪攀玉座，肠断望陵朝。
怨着情无主，哀凝曲不调。
况临松日暮，悲吹坐萧萧。','',''),('quantangshi-01145','相和歌辞 铜雀妓','劉商','quantangshi','','卷2','魏主矜蛾眉，美人美于玉。
高台无昼夜，歌舞竟未足。
盛色如转圜，夕阳落深谷。
仍令身殁后，尚足平生欲。
红粉横泪痕，调弦空向屋。
举头君不在，唯见西陵木。
玉辇岂再来，娇鬟为谁绿。
那堪秋风里，更舞阳春曲。
曲终情不胜，阑干向西哭。
台边生野草，来去罥罗縠。
况复陵寝间，双双见麋鹿。','',''),('quantangshi-01146','相和歌辞 铜雀妓','李賀','quantangshi','','卷2','佳人一壶酒，秋容满千里。
石马卧新烟，忧来何所似？
歌声且潜弄，陵树风自起。
长裾压高台，泪眼看花机。','',''),('quantangshi-01147','相和歌辞 铜雀妓','吳燭','quantangshi','','卷2','秋色西陵满绿芜，繁弦急管彊欢娱。
长舒罗袖不成舞，却向风前承泪珠。','',''),('quantangshi-01148','相和歌辞 铜雀妓','朱光弼','quantangshi','','卷2','魏王铜雀妓，日暮管弦清。
一见西陵树，悲心舞不成。','',''),('quantangshi-01149','相和歌辞 铜雀妓','朱放','quantangshi','','卷2','恨唱歌声咽，愁飜舞袖迟。
西陵日欲暮，是妾断肠时。','',''),('quantangshi-01150','相和歌辞 铜雀妓','僧皎然','quantangshi','','卷2','彊开尊酒向陵看，忆得君王旧日欢。
不觉余歌悲自断，非关艳曲转声难。','',''),('quantangshi-01151','相和歌辞 雀台怨','馬戴','quantangshi','','卷2','魏宫歌舞地，蝶戏鸟还鸣。
玉座人难到，铜台雨滴平。
西陵树不见，漳浦草空生。
万恨尽埋此，徒悬千载名。','',''),('quantangshi-01152','相和歌辞 雀台怨','程氏長文','quantangshi','','卷2','君王去后行人绝，萧竽不响歌喉咽。
雄劒无威光彩沈，宝琴零落金星灭。
玉阶寂寂坠秋露，月照当时歌舞处。
当时歌舞人不回，化为今日西陵灰。','',''),('quantangshi-01153','相和歌辞 置酒行','李益','quantangshi','','卷2','置酒命所欢，凭觞遂为戚。
日往不再来，兹辰坐成昔。
百龄非长久，五十将半百。
胡为劳我形，已须还复白。
西山鸾鹤顾，矫矫烟雾翮。
明霞发金丹，阴洞潜水碧。
安得凌风羽，崦嵫驻灵魄。
兀然坐衰老，慙叹东陵柏。','',''),('quantangshi-01154','相和歌辞 置酒行','陸龜蒙','quantangshi','','卷2','落尘花片排香痕，阑珊醉露栖愁魂。
洞庭波色惜不得，东风领入黄金尊。
千筠掷毫春谱大，碧舞红啼相唱和。
安知寂寞西海头，青𥳇未垂孤凤饿。','',''),('quantangshi-01155','相和歌辞 长歌续短歌','李賀','quantangshi','','卷2','长歌破衣襟，短歌断白发。
秦王不可见，旦夕成内热。
渴饮壶中酒，饥拔陇头粟。
凄凄四月兰，千里一时绿。
夜峰何离离，月明落石底。
裴回沿石寻，照出高峰外。
不得与之游，歌成鬓先改。','',''),('quantangshi-01156','相和歌辞 猛虎行','儲光羲','quantangshi','','卷2','寒亦不忧雪，饥亦不食人。
人血岂不甘，所恶伤明神。
太室为我宅，孟门为我邻。
百兽为我膳，五龙为我宾。
蒙马一何威，浮江亦以仁。
彩章耀朝日，牙爪雄武臣。
高云逐气浮，厚地随声振。
君能贾余勇，日夕长相亲。','',''),('quantangshi-01157','相和歌辞 猛虎行','李白','quantangshi','','卷2','朝作猛虎行，暮作猛虎吟。
肠断非关陇头水，泪下不为雍门琴。
旌旗缤纷两河道，战鼓惊山欲倾倒。
秦人半作燕地囚，胡马飜衔洛阳草。
一输一失关下兵，朝降夕叛幽蓟城。
巨鳌未斩海水动，鱼龙奔走安得宁。
颇似楚汉时，飜覆无定止。
朝过博浪沙，暮入淮阴市。
张良未遇韩信贫，刘项存亡在两臣。
暂到下邳受兵略，来投漂母作主人。
贤哲栖栖古如此，今时亦弃青云士。
有策不敢犯龙鳞，窜身南国避胡尘。
宝书长劒挂高阁，金鞍骏马散故人。
昨日方为宣城客，掣铃交通二千石。
有时六博快壮心，绕牀三帀呼一掷。
楚人每道张旭奇，心藏风云世莫知。
三吴邦伯多顾盼，四海雄侠皆相推。
萧曹曾作沛中吏，攀龙附凤当有时。
溧阳酒楼三月春，杨花漠漠愁杀人。
胡人绿眼吹玉笛，吴歌白紵飞梁尘。
丈夫相见且为乐，槌牛挝鼓会众宾。
我从此去钓东海，得鱼笑寄情相亲。','',''),('quantangshi-01158','相和歌辞 猛虎行','韩愈','quantangshi','','卷2','猛虎虽云恶，亦各有匹侪。
羣行深谷间，百兽望风低。
身食黄熊父，子食赤豹麛。
择肉于熊罴，肎视兔与狸。
正昼当谷眠，眼有百步威。
自矜无当对，气性纵以乖。
朝怒杀其子，暮还飧其妃。
匹侪四散走，猛虎还孤栖。
狐鸣门四旁，乌鹊从噪之。
出逐猴入居，虎不知所归。
谁云猛虎恶，中路正悲啼。
豹来衔其尾，熊来攫其颐。
猛虎死不辞，但慙前所为。
虎坐无助死，况如汝细微。
故当结以信，亲当结以私。
亲故且不保，人谁信汝为。','',''),('quantangshi-01159','相和歌辞 猛虎行','張籍','quantangshi','','卷2','南山北山树冥冥，猛虎白日绕林行。
向晚一身当道食，山中麋鹿尽无声。
年年养子在深谷，雌雄上山不相逐。
谷中近窟有山村，长向村家取黄犊。
五陵年少不敢射，空来林下看行迹。','',''),('quantangshi-01160','相和歌辞 猛虎行','李賀','quantangshi','','卷2','长戈莫舂，彊弩莫烹。
乳孙哺子，教得生狞。
举头为城，掉尾为旌。
东海黄公，愁见夜行。
道逢驺虞，牛哀不平。
生何用尺刀，壁上雷鸣。
泰山之下，妇人哭声。
官家有程，吏不敢听。','',''),('quantangshi-01161','相和歌辞 猛虎行','僧齊己','quantangshi','','卷2','磨尔牙，错尔爪，狐莫威，兔莫狡，饮来吞噬取肠饱。
横行不怕日月明，皇天产尔为生狞。','',''),('quantangshi-01162','相和歌辞 君子行','僧齊己','quantangshi','','卷2','圣人不生，麟龙何瑞？
梧桐不高，凤皇何止？
吾闻古之有君子，行藏以时，进退求己。
荣必为天下荣，耻必为天下耻。','',''),('quantangshi-01163','相和歌辞 燕歌行','高適','quantangshi','','卷2','汉家烟尘在东北，汉将辞家破残贼。
男儿本自重横行，天子非常赐颜色。
摐金伐鼓下榆关，旌旗逶迤碣石间。
校尉羽书飞瀚海，单于猎火照狼山。
山川萧条极边土，胡骑凭凌杂风雨。
战士军前半死生，美人帐下犹歌舞。
大漠穷秋塞草衰，孤城落日鬬兵稀。
身当恩遇常轻敌，力尽关山未解围。
铁衣远戍辛勤久，玉箸应啼别离后。
少妇城南欲断肠，征人蓟北空回首。
边风飘飘那可度，绝域苍茫更何有。
杀气三日作阵云，寒声一夜传刁斗。
相看白刃血纷纷，死节从来岂顾勋。
君不见沙场征战苦，至今犹忆李将军。','',''),('quantangshi-01164','相和歌辞 燕歌行','賈至','quantangshi','','卷2','国之重镇惟幽都，东威九夷制北胡。
五军精卒三十万，百战百胜擒单于。
前临滹沲后沮水，崇山沃野亘千里。
昔时燕王重贤士，黄金筑台从隗始。
倏忽兴王定蓟丘，汉家又以封王侯。
萧条魏晋为横流，鲜卑窃据朝五州。
我唐区夏余十纪，军容武备赫万祀。
彤弓黄钺授元帅，垦耕大漠为内地。
季秋胶折边草腓，治兵羽猎因出师。
千营万队连旌旗，望之如火忽雷驰。
匈奴慑窜穷发北，大荒万里无尘飞。
隋家昔为天下宰，穷兵黩武征辽海。
南风不竞多死声，鼓卧旗折黄云横。
六军将士皆死尽，战马空鞍归故营。
时迁道革天下平，白环入贡沧海清。
自有农夫已高枕，无劳校尉重横行。','',''),('quantangshi-01165','相和歌辞 燕歌行','陶翰','quantangshi','','卷2','请君留楚调，听我吟燕歌。
家在辽水头，边风意气多。
出身为汉将，正值戎未和。
雪中凌天山，冰上渡交河。
大小百余战，封侯竟蹉跎。
归来霸陵下，故旧无相过。
雄劒委尘匣，空门唯雀罗。
玉篸还赵女，宝瑟付齐娥。','',''),('quantangshi-01166','相和歌辞 从军行二首 一','虞世南','quantangshi','','卷2','涂山烽候惊，弭节度龙城。
冀马楼兰将，燕犀上谷兵。
劒寒花不落，弓晓月逾明。
凛凛严霜节，冰壮黄河绝。
蔽日卷征蓬，浮天散飞雪。
全兵值月满，精骑乘胶折。
结发早驱驰，辛苦事旌麾。
马冻重关冷，轮摧九折危。
独有西山将，年年属数奇。','',''),('quantangshi-01167','相和歌辞 从军行二首 二','虞世南','quantangshi','','卷2','爟火发金微，连营出武威。
孤城寒云起，绝阵虏尘飞。
侠客吸龙劒，恶少缦胡衣。
朝摩骨都垒，夜解谷蠡围。
萧关远无极，蒲海广难依。
沙磴离旌断，晴川候马归。
交河梁已毕，燕山斾欲飞。
方知万里相，侯服有光辉。','',''),('quantangshi-01168','相和歌辞 从军行','駱賓王','quantangshi','','卷2','平生一顾念，意气溢三军。
野日分戈影，天星合劒文。
弓弦抱汉月，马足践胡尘。
不求生入塞，唯当死报君。','',''),('quantangshi-01169','相和歌辞 从军行','劉希夷','quantangshi','','卷2','秋来风瑟瑟，羣马胡行疾。
严城昼不开，伏兵暗相失。
天子庙堂拜，将军玉门出。
纷纷伊洛间，戎马数千匹。
军门压黄河，兵气冲白日。
平生怀伏劒，忼慨既投笔。
南登汉月孤，北走燕云密。
近取韩彭计，早知孙吴术。
丈夫清万里，谁能埽一室。','',''),('quantangshi-01170','相和歌辞 从军行','喬知之','quantangshi','','卷2','南庭结白露，北风埽黄叶。
此时鸿燕来，惊鸣催思妾。
曲房理针线，平砧捣文练。
鸳绮裁易成，龙乡信难见。
窈窕九重闺，寂寞十年啼。
纱窗白云宿，罗幌月光栖。
云月晓微微，愁思流黄机。
玉霜冻珠履，金吹薄罗衣。
汉家已得地，君去将何事？
宛转结蚕书，寂寞无雁使。
生平荷恩信，本为容华进。
况复落红颜，蝉声催绿鬓。','',''),('quantangshi-01171','相和歌辞 从军行','李頎','quantangshi','','卷2','白日登山望烽火，昏黄饮马傍交河。
行人刁斗风砂暗，公主琵琶幽怨多。
野营万里无城郭，雨雪纷纷连大漠。
胡雁哀鸣夜夜飞，胡儿眼泪双双落。
闻道玉门犹被遮，应将性命逐轻车。
年年战骨埋荒外，空见蒲萄入汉家。','',''),('quantangshi-01172','相和歌辞 从军行三首 一','李約','quantangshi','','卷2','看图闲教阵，画地静论边。
乌垒天西戍，鹰姿塞上川。
路长须算日，书远每题年。
无复生还望，飜思未别前。','',''),('quantangshi-01173','相和歌辞 从军行三首 二','李約','quantangshi','','卷2','栅高三面鬬，箭尽举烽频。
营柳和烟暮，关榆带雪春。
边城多老将，碛路少归人。
点尽三河卒，年年添塞尘。','',''),('quantangshi-01174','相和歌辞 从军行三首 三','李約','quantangshi','','卷2','候火起雕城，尘砂拥战声。
游军藏汉帜，降骑说蕃情。
霜降滮池浅，秋深太白明。
嫖姚方虎视，不觉请添兵。','',''),('quantangshi-01175','相和歌辞 从军行','戎昱','quantangshi','','卷2','昔从李都尉，双鞬照马蹄。
擒生黑山北，杀敌黄云西。
太白沈虏地，边草复萋萋。
归来邯郸市，百尺青楼梯。
感激然诺重，平生胆力齐。
芳筵暮歌发，艳粉轻鬟低。
半醉秋风起，铁骑门前嘶。
远戍报烽火，孤城严鼓鼙。
挥鞭望尘去，少妇莫含啼。','',''),('quantangshi-01176','相和歌辞 从军行','厲玄','quantangshi','','卷2','边草早不春，劒花增泞尘。
广场收骥尾，清瀚怯龙鳞。
帆色已归越，松声厌避秦。
几时逢范蠡，处处是通津。','',''),('quantangshi-01177','相和歌辞 从军行二首 一','李白','quantangshi','','卷2','从军玉门道，逐虏金微山。
笛奏梅花曲，刀开明月环。
鼓声鸣海上，兵气拥云间。
愿斩单于首，长驱静铁关。','',''),('quantangshi-01178','相和歌辞 从军行二首 二','李白','quantangshi','','卷2','百战沙场碎铁衣，城南已合数重围。
突营射杀呼延将，独领残兵千骑归。','',''),('quantangshi-01179','相和歌辞 从军行','王維','quantangshi','','卷2','吹角动行人，喧喧行人起。
笳鸣马嘶乱，争渡金河水。
日暮沙漠垂，战声烟尘里。
尽系名王颈，归来报天子。','',''),('quantangshi-01180','相和歌辞 从军行','王昌齡','quantangshi','','卷2','向夕临大荒，朔风轸归虑。
平沙万里余，飞鸟宿何处？
虏骑猎长原，翩翩傍河去。
边声摇白草，海气生黄雾。
百战苦风尘，十年履霜露。
虽投定远笔，未坐将军树。
早知行路难，悔不理章句。','',''),('quantangshi-01181','相和歌辞 从军行 二','王昌齡','quantangshi','','卷2','烽火城西百尺楼，黄昏独上海风秋。
更吹横笛关山月，谁解金闺万里愁。','',''),('quantangshi-01182','相和歌辞 从军行 三','王昌齡','quantangshi','','卷2','琵琶起舞换新声，总是关山旧别情。
撩乱边愁弹不尽，高高秋月下长城。','',''),('quantangshi-01183','相和歌辞 从军行 四','王昌齡','quantangshi','','卷2','青海长云暗雪山，孤城遥望雁门关。
黄沙百战穿金甲，不破楼兰终不还。','',''),('quantangshi-01184','相和歌辞 从军行','盧綸','quantangshi','','卷2','二十在边城，军中得勇名。
卷旗收败马，断碛拥残兵。
覆阵乌鸢起，烧山草木明。
塞闲思远猎，师老厌分营。
雪岭无人迹，冰河足雁声。
李陵甘此没，惆怅汉公卿。','',''),('quantangshi-01185','相和歌辞 从军行六首 一','劉長卿','quantangshi','','卷2','回看虏骑合，城下汉兵稀。
白刃两相向，黄云愁不飞。
手中无尺铁，徒欲突重围。','',''),('quantangshi-01186','相和歌辞 从军行六首 二','劉長卿','quantangshi','','卷2','落日更萧条，北方动枯草。
将军追虏骑，夜失阴山道。
战败仍树勋，韩彭但空老。','',''),('quantangshi-01187','相和歌辞 从军行六首 三','劉長卿','quantangshi','','卷2','草枯秋塞上，望见渔阳郭。
胡马嘶一声，汉兵泪双落。
谁为吮痈者，此事令人薄。','',''),('quantangshi-01188','相和歌辞 从军行六首 四','劉長卿','quantangshi','','卷2','目极雁门道，青青边草春。
一身事征战，匹马同辛勤。
末路成白首，功归天下人。','',''),('quantangshi-01189','相和歌辞 从军行六首 五','劉長卿','quantangshi','','卷2','倚劒白日暮，望乡登戍楼。
北风吹羌笛，此夜关山愁。
回首不无意，滹河空自流。','',''),('quantangshi-01190','相和歌辞 从军行六首 六','劉長卿','quantangshi','','卷2','黄沙一万里，白首无人怜。
报国劒已折，归乡身幸全。
单于古台下，边色寒苍然。','',''),('quantangshi-01191','相和歌辞 从军行','杜頠','quantangshi','','卷2','秋草马蹄轻，角弓持弦急。
去为龙城候，正值胡兵袭。
军气横大荒，战酣日将入。
长风金鼓动，白雾铁衣湿。
四起愁边声，南辕时伫立。
断蓬孤自转，寒雁飞相及。
万里云沙涨，路平冰霰涩。
夜闻汉使归，独向刀环泣。','',''),('quantangshi-01192','相和歌辞 从军行 一','僧皎然','quantangshi','','卷2','候骑出纷纷，元戎霍冠军。
汉鞞秋聒地，羌火昼烧云。
万里戍城合，三边羽檄分。
乌孙驱未尽，肯顾辽阳勋。','',''),('quantangshi-01193','相和歌辞 从军行 二','僧皎然','quantangshi','','卷2','汉斾拂丹霄，汉军新破辽。
红尘驱卤簿，白羽拥嫖姚。
战苦军犹乐，功高将不骄。
至今丁令塞，朔吹空萧萧。','',''),('quantangshi-01194','相和歌辞 从军行 三','僧皎然','quantangshi','','卷2','百万逐呼韩，频年不解鞍。
兵屯绝漠暗，马饮浊河干。
破虏功未录，劳师力已殚。
须防肘腋下，飞祸出无端。','',''),('quantangshi-01195','相和歌辞 从军行 四','僧皎然','quantangshi','','卷2','飞将下天来，奇谋阃外裁。
水心龙劒动，地肺雁山开。
望气燕师锐，当锋虏阵摧。
从今射雕骑，不敢过云堆。','',''),('quantangshi-01196','相和歌辞 从军行 五','僧皎然','quantangshi','','卷2','黄纸君王诏，青泥校尉书。
誓师张虎落，选将擐犀渠。
雾暗津浦失，天寒塞柳疎。
横行十万骑，欲埽虏尘余。','',''),('quantangshi-01197','相和歌辞 从军行','王建','quantangshi','','卷2','汉军逐单于，日没处河曲。
浮云道傍起，行子车下宿。
枪城围鼓角，氊帐依山谷。
马上悬壶浆，刀头分顿肉。
来时高堂上，父母亲结束。
回首不见家，风吹破衣服。
金创生肢节，相与拔箭镞。
闻道西凉州，家家妇人哭。','',''),('quantangshi-01198','相和歌辞 从军行','張祜','quantangshi','','卷2','少年金紫就光辉，直指边城虎翼飞。
一卷旌收千骑虏，万全身出百重围。
黄云断塞寻鹰去，白草连天射雁归。
白首汉廷刀笔吏，丈夫功业本相依。','',''),('quantangshi-01199','相和歌辞 从军行五首 一','令狐楚','quantangshi','','卷2','荒鸡隔水啼，汗马逐风嘶。
终日随征斾，何时罢鼓鼙。','',''),('quantangshi-01200','相和歌辞 从军行五首 二','令狐楚','quantangshi','','卷2','孤心眠夜雪，满眼是秋沙。
万里犹防塞，三年不见家。','',''),('quantangshi-01201','相和歌辞 从军行五首 三','令狐楚','quantangshi','','卷2','却望冰河阔，前登雪岭高。
征人几多在，又拟战临洮。','',''),('quantangshi-01202','相和歌辞 从军行五首 四','令狐楚','quantangshi','','卷2','胡风千里惊，汉月五更明。
纵有还家梦，犹闻出塞声。','',''),('quantangshi-01203','相和歌辞 从军行五首 五','令狐楚','quantangshi','','卷2','暮雪连青海，阴云覆白山。
可怜班定远，出入玉门关。','',''),('quantangshi-01204','相和歌辞 从军行三首 一','王涯','quantangshi','','卷2','旌甲从军久，风云识阵难。
今朝韩信计，日下斩成安。','',''),('quantangshi-01205','相和歌辞 从军行三首 二','王涯','quantangshi','','卷2','燕颔多奇相，狼头敢犯边。
寄言班定远，正是立功年。','',''),('quantangshi-01206','相和歌辞 从军行三首 三','王涯','quantangshi','','卷2','旄头夜落捷书飞，来奏金门着赐衣。
白马将军频破敌，黄龙戍卒几时归。','',''),('quantangshi-01207','相和歌辞 从军有苦乐行','李益','quantangshi','','卷2','劳者且勿歌，我欲送君觞。
从军有苦乐，此曲乐未央。
仆本居陇上，陇水断人肠。
东过秦宫路，宫路入咸阳。
时逢汉帝出，谏猎至长杨。
讵驰游侠窟，非结少年场。
一旦承嘉惠，轻命重恩光。
秉笔参帷帟，从军至朔方。
边地多阴风，草木自凄凉。
断绝海云去，出没胡沙长。
参差引雁翼，隐辚腾军装。
劒文夜如水，马汗冻成霜。
侠气五都少，矜功六郡良。
山河起目前，睚眦死路傍。
北逐驱獯虏，西临复旧疆。
昔还赋余资，今出乃赢粮。
一矢弢夏服，我弓不再张。
寄言丈夫雄，苦乐身自当。','',''),('quantangshi-01208','相和歌辞 苦战远征人','鮑溶','quantangshi','','卷2','征人歌古曲，携手上河梁。
李陵死别处，杳杳玄冥乡。
忆昔从此路，连年征鬼方。
久行迷汉历，三洗氊衣裳。
百战身且在，微功信难忘。
远承云台议，非势孰敢当。
落日吊李广，白身过河阳。
闲弓失月影，劳劒无龙光。
去日始束发，今来发成霜。
虚名乃闲事，生见父母乡。
掩抑大风歌，裴回少年场。
诚哉古人言，鸟尽良弓藏。','',''),('quantangshi-01209','相和歌辞 苦哉行五首 一','戎昱','quantangshi','','卷2','彼鼠侵我厨，纵狸授梁肉。
鼠虽为君却，狸食自须足。
冀雪大国耻，飜是大国辱。
膻腥逼绮罗，甎瓦杂珠玉。
登楼非骋望，目笑是心哭。
何意天乐中，至今奏胡曲。','',''),('quantangshi-01210','相和歌辞 苦哉行五首 二','戎昱','quantangshi','','卷2','官军收洛阳，家住洛阳里。
夫壻与兄弟，目前见伤死。
吞声不许哭，还谴衣罗绮。
上马随匈奴，数秋黄尘里。
生为名家女，死作塞垣鬼。
乡国无还期，天津哭流水。','',''),('quantangshi-01211','相和歌辞 苦哉行五首 三','戎昱','quantangshi','','卷2','登楼望天衢，目极泪盈睫。
彊笑无笑容，须妆旧花靥。
昔年买奴仆，奴仆来碎叶。
岂意未死间，自为匈奴妾。
一生忽至此，万事痛苦业。
得出塞垣飞，不如彼蜂蝶。','',''),('quantangshi-01212','相和歌辞 苦哉行五首 四','戎昱','quantangshi','','卷2','妾家青河边，七叶承貂蝉。
身为最小女，偏得浑家怜。
亲戚不相识，幽闺十五年。
有时最远出，祗到中门前。
前年狂胡来，惧死飜生全。
今秋官军至，岂意遭戈鋋。
匈奴为先锋，长鼻黄发拳。
弯弓猎生人，百步牛羊膻。
脱身落虎口，不及归黄泉。
苦哉难重陈，暗哭苍苍天。','',''),('quantangshi-01213','相和歌辞 苦哉行五首 五','戎昱','quantangshi','','卷2','可汗奉亲诏，今月归燕山。
忽如乱刀劒，[搅]妾心肠间。
出户望北荒，迢迢玉门关。
生人为死别，有去无时还。
汉月割妾心，胡风凋妾颜。
去去断绝魂，叫天天不闻。','',''),('quantangshi-01214','相和歌辞 鞠歌行','李白','quantangshi','','卷2','玉不自言如桃李，鱼目笑之卞和耻。
楚国青蝇何太多？连城白璧遭谗毁。
荆山长号泣血人，忠臣死为刖足鬼。
听曲知甯戚，[夷]吾因小妻。
秦穆五羊皮，买死百里奚。
洗拂青云上，当时贱如泥。
朝歌鼓刀叟，虎变蟠溪中。
一举钓六合，逐荒营丘东。
平生渭水曲，谁识此老翁。
奈何今之人，双目送征鸿。','',''),('quantangshi-01215','相和歌辞 前苦寒行二首 一','杜甫','quantangshi','','卷2','汉时长安雪一丈，牛马毛寒缩如猬。
楚江巫峡冰入怀，虎豹哀号又堪记。
秦城老翁荆扬客，惯习炎蒸岁絺綌。
玄冥祝融气或交，手持白羽未敢释。','',''),('quantangshi-01216','相和歌辞 前苦寒行二首 二','杜甫','quantangshi','','卷2','去年白帝雪在山，今年白帝雪在地。
冻埋蛟龙南浦缩，寒刮肌肤北风利。
楚人四时皆麻衣，楚天万里无晶辉。
三足之乌足恐断，羲和送将安所归。','',''),('quantangshi-01217','相和歌辞 后苦寒行二首 一','杜甫','quantangshi','','卷2','南纪巫庐瘴不绝，太古以来无尺雪。
蛮夷长老怨苦寒，崐崘天关冻应折。','',''),('quantangshi-01218','相和歌辞 后苦寒行二首 二','杜甫','quantangshi','','卷2','晚来江门失大木，猛风中夜吹白屋。
天兵断斩青海戎，杀气南行动坤轴，不尔苦寒何太酷？
巴东之峡生凌凘，彼苍回轩人得知。','',''),('quantangshi-01219','相和歌辞 苦寒行','劉駕','quantangshi','','卷2','严寒动八荒，莿莿无休时。
阳乌不自暖，雪压扶桑枝。
岁暮寒益壮，青春安得归。
朔雁到南海，越禽何处飞？
谁言贫士叹，不为身无衣。','',''),('quantangshi-01220','相和歌辞 苦寒行','僧貫休','quantangshi','','卷2','北风北风，职何严毒。
摧壮士心，缩金乌足。
冻云嚣嚣碍雪，一片下不得。
声绕枯桑，根在沙塞。
黄河彻底，顽直到海。
一气搏束，万物无态。
唯有吾庭前杉松树枝，枝枝健在。','',''),('quantangshi-01221','相和歌辞 苦寒行','僧齊己','quantangshi','','卷2','冰峰撑空寒矗矗，雪凝水冻埋海陆。
杀物之性，伤人之欲。
既不能断绝蒺藜荆棘之根株，又不能展凤皇麒麟之拳局。
如此则何如为和煦，为膏雨。
自然天下之荣枯，融融于万户。','',''),('quantangshi-01222','相和歌辞 北上行','李白','quantangshi','','卷2','北上何所苦，北上缘太行。
磴道盘且峻，巉岩凌穹苍。
马足蹶侧石，车轮摧高冈。
沙尘接幽州，烽火连朔方。
杀气毒劒戟，严风裂衣裳。
奔鲸夹黄河，凿齿屯洛阳。
前行无归日，返顾思旧乡。
惨戚冰雪里，悲号绝中肠。
尺布不掩体，皮肤剧枯桑。
汲水涧谷阻，采薪陇坂长。
猛虎又掉尾，磨牙皓秋霜。
草木不可湌，饥饮零露浆。
叹此北上苦，停骖为之伤。
何日王道平？开颜覩天光。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01223','相和歌辞 豫章行','李白','quantangshi','','卷2','胡风吹代马，北拥鲁阳关。
吴兵照海雪，西讨何时还？
半渡上辽津，黄云惨无颜。
老母与子别，呼天野草间。
白马绕旌旗，悲鸣相追攀。
白杨秋月苦，早落豫章山。
本为休明人，斩虏素不闲。
岂惜战鬬死，为君埽凶顽。
精感石没羽，岂忘惮险艰。
楼船若鲸飞，波荡落星湾。
此曲不可奏，三军鬓成斑。','',''),('quantangshi-01224','相和歌辞 董逃行','稹','quantangshi','','卷2','董逃董逃董卓逃，揩铿戈甲声劳嘈。
剜剜深脐脂焰焰，人皆数叹曰。
尔独不忆年年取我身上膏，膏销骨尽烟火死。
长安城中贼毛起，城门四走公卿士。
走劝刘虞作天子，刘虞不敢作天子。
曹瞒纂乱从此始，董逃董逃人莫喜。
胜负飜环相枕倚，缝缀难成裁破易。
何况曲针不能伸巧指，欲学裁缝须准拟。','',''),('quantangshi-01225','相和歌辞 董逃行','張籍','quantangshi','','卷2','洛阳城头火曈曈，乱兵烧我天子宫。
宫城南面有深山，尽将老幼藏其间。
重岩为屋橡为食，丁男夜行候消息。
闻道官军犹掠人，旧里如今归未得。
董逃行，汉家几时重太平。','',''),('quantangshi-01226','相和歌辞 相逢行','崔顥','quantangshi','','卷2','妾年初二八，家住洛桥头。
玉户临驰道，朱门近御沟。
使君何假问，夫壻大长秋。
女弟新承宠，诸兄近拜侯。
春生百子殿，花发五城楼。
出入千门里，年年乐未休。','',''),('quantangshi-01227','相和歌辞 相逢行二首 一','李白','quantangshi','','卷2','朝骑五花马，谒帝出银台。
秀色谁家子，云车珠箔开。
金鞭遥指点，玉勒近迟回。
夹毂相借问，疑从天上来。
怜肠愁欲断，斜日复相催。
下车何轻盈，飘然似落梅。
邀入青绮门，当歌共衔杯。
衔杯映歌扇，似月云中见。
相见不相亲，不如不相见。
相见情已深，未语可知心。
胡为守空闺，孤眠愁锦衾。
锦衾与罗帏，缠緜会有时。
春风正澹荡，暮雨来何迟？
愿因三青鸟，更报长相思。
光景不待人，须臾发成丝。
当年失行乐，老去徒伤悲。
持此道密意，无令旷佳期。','',''),('quantangshi-01228','相和歌辞 相逢行二首 二','李白','quantangshi','','卷2','相逢红尘内，高揖黄金鞭。
万户垂杨里，君家阿那边。','',''),('quantangshi-01229','相和歌辞 相逢行','韋應物','quantangshi','','卷2','二十登汉朝，英声迈今古。
适从东方来，又欲谒明主。
犹酣新丰酒，尚带霸陵雨。
邂逅两相逢，别来间寒暑。
宁知白日晚，暂向花间语。
忽闻长乐钟，走马东西去。','',''),('quantangshi-01230','相和歌辞 三妇艳诗','董思恭','quantangshi','','卷2','大妇裁纨素，中妇弄明璫。
小妇多姿态，登楼红粉妆。
丈人且安坐，初日渐流光。','',''),('quantangshi-01231','相和歌辞 中妇织流黄','虞世南','quantangshi','','卷2','寒闺织素锦，含怨敛双蛾。
综新交缕涩，经脆断丝多。
衣香逐举袖，钏动应鸣梭。
还恐裁缝罢，无信达交河。','',''),('quantangshi-01232','相和歌辞 难忘曲','李賀','quantangshi','','卷2','夹道开洞门，弱杨低画戟。
帘影竹叶起，箫声吹日色。
蠭语绕妆镜，拂蛾学春碧。
乱系丁香梢，满阑花向夕。','',''),('quantangshi-01233','相和歌辞 塘上行','李賀','quantangshi','','卷2','藕花凉露湿，花缺藕根涩。
飞下雌鸳鸯，塘水声溢溢。','',''),('quantangshi-01234','相和歌辞 苦辛行','戎昱','quantangshi','','卷2','且莫奏短歌，听余苦辛词。
如今刀笔士，不及屠酤儿。
少年无事学诗赋，岂意文章复相误。
东西南北少知音，终年竟岁悲行路。
仰面诉天天不闻，低头告地地不言。
天地生我尚如此，陌上他人何足论。
谁谓西江深，涉之固无忧。
谁谓南山高，可以登之游。
险巇惟有世间路，一向令人堪白头。
贵人立意不可测，等闲桃李成荆棘。
风尘之士深可亲，心如鸡犬能依人。
悲来却忆汉天子，不弃相如家旧贫。
饮酒酒能散羇愁，谁家有酒判一醉，万事从他江水流。','',''),('quantangshi-01235','相和歌辞 秋胡行','高適','quantangshi','','卷2','妾本邯郸未嫁时，容华倚翠人未知。
一朝结发从君子，将妾迢迢东路陲。
时逢大道无难阻，君方游宦从陈汝。
蕙楼独卧频度春，彩落辞君几徂暑。
三月垂杨蚕未眠，携笼结侣南陌边。
道逢行子不相识，赠妾黄金买少年。
妾家夫壻轻离久，寸心誓与长相守。
愿言行路莫多情，送妾贞心在人口。
日暮蚕饥相命归，携笼端饰来庭闱。
劳心苦力终无恨，所冀君恩那可依。
闻说行人已归止，乃是向来赠金子。
相看颜色不复言，相顾怀慙有何已。
从来自隐无疑背，直为君情也相会。
如何咫尺仍有情，况复迢迢千里外。
此时顾恩不顾身，念君此日赴河津。
莫道向来不得意，故欲留规诫后人。','',''),('quantangshi-01236','相和歌辞 善哉行','僧貫休','quantangshi','','卷2','有美一人兮婉如清扬，识曲别音兮令姿煌煌。
绣袂捧琴兮登君子堂，如彼萱草兮使我忧忘。
欲赠之以紫玉尺，白银璫，久不见之兮湘水茫茫。','',''),('quantangshi-01237','相和歌辞 善哉行','僧齊己','quantangshi','','卷2','大鹏刷翮谢溟渤，青云万层高突出。
下视秋涛空渺弥，旧处鱼龙皆细物。
人生在世何容易，眼浊心昏信生死。
愿除嗜欲待身轻，携手同寻列仙事。','',''),('quantangshi-01238','相和歌辞 来日大难','李白','quantangshi','','卷2','来日一身，携粮负薪。
道长食尽，苦口焦唇。
今日醉饱，乐过千春。
仙人相存，诱我远学。
海陵三山，陆憩五岳。
乘龙上三天，飞目瞻两角。
授以神药，金丹满握。
蟪蛄蒙恩，深愧短促。
思填东海，彊衔一木。
道重天地，轩师广成。
蝉翼九五，以求长生。
下士大笑，如苍蝇声。','',''),('quantangshi-01239','相和歌辞 当来日大难','稹','quantangshi','','卷2','当来日大难行，前有坂，后有坑，大梁侧，小梁倾，两轴相绞，两轮相撑，大牛竖，小牛横，乌啄牛背，足跌力狞。
当来日大难行，太行虽险，险可使平。
轮轴自挠，牵制不停。
泥潦渐久，荆棘旋生。
行必不得，不如不行。','',''),('quantangshi-01240','相和歌辞 陇西行','王維','quantangshi','','卷2','十里一走马，五里一扬鞭。
都护军书至，匈奴围酒泉。
关山正飞雪，烽戍断无烟。','',''),('quantangshi-01241','相和歌辞 陇西行','耿[湋]','quantangshi','','卷2','雪下阳关路，人稀陇戍头。
封狐犹未翦，边将岂无羞。
白草三冬色，黄云万里愁。
因思李都尉，毕竟不封侯。','',''),('quantangshi-01242','相和歌辞 陇西行','長孫佐輔','quantangshi','','卷2','阴云凝朔气，陇上正飞雪。
四月草不生，北风劲如切。
朝来羽书急，夜救长城窟。
道隘行不前，相呼抱鞍歇。
人寒指欲堕，马冻蹄亦裂。
射雁旋充饥，斧冰还止渴。
宁辞解围鬬，但恐乘疲没。
早晚边候空，归来养羸卒。','',''),('quantangshi-01243','相和歌辞 东门行','柳宗元','quantangshi','','卷2','汉家三十六将军，东方雷动横阵云。
鸡鸣函谷客如雾，貌同心异不可数。
赤丸夜语飞电光，徼巡司隶眠如羊。
当街一叱百吏走，冯敬胷中函匕首。
凶徒侧耳潜惬心，悍臣破胆皆杜口。
魏王卧内藏兵符，子西掩袂真无辜。
羌胡毂下一朝起，敌国舟中非所拟。
安陵谁辨削砺功，韩国讵明深井里。
绝咽断骨那下补，万金宠赠不如土。','',''),('quantangshi-01244','相和歌辞 饮马长城窟行','太宗皇帝','quantangshi','','卷2','塞外悲风切，交河冰已结。
瀚海百重波，阴山千里雪。
迥戍危烽火，层峦引高节。
悠悠卷斾旌，饮马出长城。
寒沙连骑迹，朔吹断边声。
胡尘清玉塞，羌笛韵金钲。
绝寞干戈戢，车徒振原隰。
都尉反龙堆，将军旋马邑。
扬麾氛雾静，纪石功名立。
荒裔一戎衣，云台凯歌入。','',''),('quantangshi-01245','相和歌辞 饮马长城窟行','虞世南','quantangshi','','卷2','驰马渡河干，流深马渡难。
前逢锦车使，都护在楼兰。
轻骑犹衔勒，疑兵尚解鞍。
温池下绝涧，栈道接危峦。
拓地勋未赏，亡城律讵宽。
有月关犹暗，经春陇尚寒。
云昏无复影，冰合不闻湍。
怀君不可遇，聊持报一餐。','',''),('quantangshi-01246','相和歌辞 饮马长城窟行','袁朗','quantangshi','','卷2','朔风动秋草，清跸长安道。
长城连不穷，所以隔华戎。
规模惟圣作，荷负晓成功。
鸟庭已向内，龙荒更凿空。
玉关尘卷静，金微路已通。
汤征随北怨，舜咏起南风。
画野功初立，绥边事云集。
朝服践狼居，凯歌旋马邑。
山响传凤吹，霜华藻琼鈒。
属国拥节归，单于款关入。
日落寒云起，惊沙被原隰。
零落叶已寒，河流清且急。
四时徭役尽，千载干戈戢。
太平今若斯，汗马竟无施。
惟当事笔研，归去草封禅。','',''),('quantangshi-01247','相和歌辞 饮马长城窟行','王翰','quantangshi','','卷2','长安少年无远图，一生惟羡执金吾。
骐驎前殿拜天子，走马为君西击胡。
胡沙猎猎吹人面，汉虏相逢不相见。
遥闻鼙鼓动地来，传道单于夜犹战。
此时顾恩宁顾身，为君一行摧万人。
壮士挥戈回白日，单于溅血染朱轮。
回来饮马长城窟，长安道傍多白骨。
问之耆老何代人，云是秦王筑城卒。
黄昏塞北无人烟，鬼哭啾啾声沸天。
无罪见诛功不赏，孤魂流落此城边。
当昔秦王按劒起，诸侯膝行不敢视。
富国彊兵二十年，筑怨兴徭九千里。
秦王筑城何太愚，天实亡秦非北胡。
一朝祸起萧墙内，渭水咸阳不复都。','',''),('quantangshi-01248','相和歌辞 饮马长城窟行','王建','quantangshi','','卷2','长城窟，长城窟边多马骨。
古来此地无井泉，赖得秦家筑城卒。
征人饮马愁不回，长城变作望乡堆。
蹄迹未干人去近，续后马来泥污尽。
枕弓睡着待水生，不见阴山在前阵。
马蹄足脱装马头，健儿战死谁封侯。','',''),('quantangshi-01249','相和歌辞 饮马长城窟行','僧子蘭','quantangshi','','卷2','游客长城下，饮马长城窟。
马嘶闻水腥，为浸征人骨。
岂不是流泉，终不成潺湲。
洗尽骨上土，不洗骨中冤。
骨若比流水，四海有还魂。
空流呜咽声，声中疑是言。','',''),('quantangshi-01250','相和歌辞 上留田','李白','quantangshi','','卷2','行至上留田，孤坟何峥嵘。
积此万古恨，春草不复生。
悲风四边来，肠断白杨声。
借问谁家地，埋没蒿里茔。
古老向余言，言是上留田。
蓬科马鬣今已平，昔之弟死兄不葬。
他人于此举铭旌，一鸟死，百鸟鸣，一兽死，百兽惊。
桓山之禽别离苦，欲去回翔不能征。
田氏仓卒骨肉分，青天白日摧紫荆。
交柯之木本同形，东枝顦顇西枝荣。
无心之物尚如此，参商胡乃寻天兵。
孤竹延陵，让国扬名。
高风缅邈，颓波激清。
尺布之谣，塞耳不能听。','',''),('quantangshi-01251','相和歌辞 上留田','僧貫休','quantangshi','','卷2','父不父，兄不兄，上留田，蝥贼生。
徒陟冈，泪峥嵘，我欲使诸凡鸟雀，尽变为鹡鸰。
我欲使诸凡草木，尽变为田荆。
邻人歌，邻人歌，古风清，清风生。','',''),('quantangshi-01252','相和歌辞 安乐宫','李賀','quantangshi','','卷2','深井桐乌起，尚复牵清水。
未盥邵陵王，瓶中弄长翠。
新城安乐宫，宫如凤皇翅。
歌回蜡版鸣，大绾提壶使。
绿繁悲水曲，茱萸别秋子。','',''),('quantangshi-01253','相和歌辞 放歌行','王昌齡','quantangshi','','卷2','南渡洛阳津，西望十二楼。
明堂坐天子，月朔朝诸侯。
清乐动千门，皇风被九州。
庆云从东来，泱漭抱日流。
升平贵论道，文墨将何求。
有诏征草泽，微臣献谋猷。
冠冕如星罗，拜揖曹与周。
望尘非吾事，入赋且迟留。
幸蒙国士识，因脱负薪裘。
今者放歌行，以慰梁父愁。
但营数斗禄，奉养毋丰羞。
若得金膏遂，飞云亦可俦。','',''),('quantangshi-01254','相和歌辞 野田黄雀行','李白','quantangshi','','卷2','游莫逐炎洲翠，栖莫近吴宫燕。
吴宫火起焚尔窠，炎洲逐翠遭网罗。','',''),('quantangshi-01255','相和歌辞 野田黄雀行','儲光羲','quantangshi','','卷2','啧啧野田雀，不知躯体微。
闲穿深蒿里，争食复争飞。
穷老一颓舍，枣多桑树稀。
无枣犹可食，无桑何以衣。
萧条空仓暮，相引时来归。
邪路岂不捷，渚田岂不肥。
水长路且坏，恻恻与心违。','',''),('quantangshi-01256','相和歌辞 野田黄雀行','僧貫休','quantangshi','','卷2','高树风多，吹尔巢落。
深蒿叶暖，宜尔依薄。
莫近鸮类，珠网亦恶。
饮野田之清水，食野田之黄粟。
深花中睡，𡋯土里浴。
如此即全胜啄太仓之谷，而更穿人屋。','',''),('quantangshi-01257','相和歌辞 野田黄雀行','僧齊己','quantangshi','','卷2','双双野田雀，上下同饮啄。
暖去栖蓬蒿，寒归傍篱落。
殷勤避罗网，乍可遇雕鹗。
雕鹗虽不仁，分明在寥廓。','',''),('quantangshi-01258','相和歌辞 雁门太守行','李賀','quantangshi','','卷2','黑云压城城欲摧，甲光向月金鳞开。
角声满天秋色里，塞上燕支凝夜紫。
半卷红旗临易水，霜重鼓寒声不起。
报君黄金台上意，提携玉龙为君死。','',''),('quantangshi-01259','相和歌辞 雁门太守行','張祜','quantangshi','','卷2','城头月没霜如水，趚趚蹋沙人似鬼。
灯前拭泪试香裘，长引一声残漏子。
驼囊泻酒酒一杯，前头啑血心不回。
寄语年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。','',''),('quantangshi-01260','相和歌辞 雁门太守行','莊南傑','quantangshi','','卷2','旌旗闪闪摇天末，长笛横吹虏尘阔。
跨下嘶风白练狞，腰间切玉青蛇活。
击革摐金燧牛尾，犬羊兵败如山死。
九泉寂寞葬秋虫，湿云荒草啼秋思。','',''),('quantangshi-01261','相和歌辞 飞来双白鹤','虞世南','quantangshi','','卷2','飞来双白鹤，奋翼远凌烟。
双栖集紫盖，一举背青田。
扬影过伊洛，流声入管弦。
鸣羣倒景外，刷羽阆风前。
映海疑浮雪，拂涧泻飞泉。
燕雀宁知去，蜉蝣不识还。
何言别俦侣，从此间山川。
顾步已相失，裴回反自怜。
危心犹警露，哀响讵闻天。
无因振六翮，轻举复随仙。','',''),('quantangshi-01262','相和歌辞 门有车马客行','虞世南','quantangshi','','卷2','财雄重交结，戚里擅豪华。
曲台临上路，高门抵狭斜。
赭汗千金马，绣毂五香车。
白鹤随飞盖，朱鹭入鸣笳。
夏莲开劒水，春桃发露花。
轻裙染回雪，浮蚁泛流霞。
高谈辨飞兔，摛藻握灵蛇。
逢恩借羽翼，失路委泥沙。
暧暧风烟晚，路长归骑远。
日斜青琐第，尘飞金谷苑。
危弦促柱奏巴渝，遗簪堕珥解罗襦。
如何守直道，飜使谷名愚。','',''),('quantangshi-01263','相和歌辞 门有车马客行','李白','quantangshi','','卷2','门有车马客，金鞍曜朱轮。
谓从丹霄落，乃是故乡亲。
呼儿埽中堂，坐客论悲辛。
对酒两不饮，停觞泪盈巾。
叹我万里游，飘颻三十春。
空谈霸王略，紫绶不挂身。
雄劒藏玉匣，阴符生素尘。
廓落无所合，流离湘水滨。
借问宗党间，多为泉下人。
生苦百战役，死托万鬼邻。
北风扬胡沙，埋翳周与秦。
大运且如此，苍穹宁匪仁。
恻怆竟何道？存亡任大钧。','',''),('quantangshi-01264','相和歌辞 蜀道难','張文琮','quantangshi','','卷2','梁山镇地险，积石阻云端。
深谷下寥廓，层岩上郁盘。
飞梁架绝岭，栈道接危峦。
揽辔独长息，方知斯路难。','',''),('quantangshi-01265','相和歌辞 蜀道难','李白','quantangshi','','卷2','噫吁嚱！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。
尔来四万八千岁，乃与秦塞通人烟。
西当太白有鸟道，可以横绝峨眉巅。
地崩山摧壮士死，然后天梯石栈方钩连。
上有六龙回日之高标，下有冲波逆折之回川。
黄鹤之飞尚不得，猨猱欲度愁攀缘。
青泥何盘盘，百步九折萦岩峦。
扪参历井仰胁息，以手抚膺坐长叹。
问君西游何时还？畏途巉岩不可攀。
但见悲鸟号枯木，雄飞呼雌绕林间。
又闻子规啼夜月，愁空山，蜀道之难难于上青天！使人听此雕朱颜。
连峰去天不盈尺，枯松倒挂倚绝壁。
飞湍瀑流相喧豗，砅崖转石万壑雷。
其嶮也若此，嗟尔远道之人胡为乎来哉？
劒阁峥嵘而崔嵬，一夫当关，万夫莫开。
所守或匪亲，化为狼与豺。
朝避猛虎，夕避长蛇。
磨牙吮血，杀人如麻。
锦城虽云乐，不如早还家。
蜀道之难难于上青天，侧身西望长咨嗟。','',''),('quantangshi-01266','相和歌辞 棹歌行','駱賓王','quantangshi','','卷2','写月图黄罢，凌波拾翠通。
镜花摇芰日，衣麝入荷风。
叶密舟难荡，莲疎浦易空。
凤媒羞自托，鸳翼恨难穷。
秋帐灯花翠，倡楼粉色红。
相思无别曲，并在棹歌中。','',''),('quantangshi-01267','相和歌辞 棹歌行','徐堅','quantangshi','','卷2','棹女饰银钩，新妆下翠楼。
霜丝青桂檝，兰栧紫霞舟。
水落金陵曙，风起洞庭秋。
扣船过曲浦，飞帆越回流。
影入桃花浪，香飘杜若洲。
洲长殊未返，萧散云霞晚。
日下大江平，烟生归岸远。
岸远闻潮波，争途游戏多。
因声赵津女，来听采菱歌。','',''),('quantangshi-01268','相和歌辞 胡无人行','徐彥伯','quantangshi','','卷2','十月繁霜下，征人远凿空。
云摇锦更节，海照角端弓。
暗碛埋砂树，冲飙卷塞蓬。
方随膜拜入，歌舞玉门中。','',''),('quantangshi-01269','相和歌辞 胡无人行','聶夷中','quantangshi','','卷2','男儿徇大义，立节不沽名。
腰间悬陆离，大歌胡无行。
不读战国书，不览黄石经。
醉卧咸阳楼，梦入受降城。
更愿生羽翼，飞身入青冥。
请携天子劒，斫下旄头星。
自然胡无人，虽有无战争。
悠哉典属国，驱羊老一生。','',''),('quantangshi-01270','相和歌辞 胡无人行','李白','quantangshi','','卷2','严风吹霜海草雕，筋干精坚胡马骄。
汉家战士三十万，将军兼领霍嫖姚。
流星白羽腰间插，劒花秋莲光出匣。
天兵照雪下玉关，虏箭如沙射金甲。
云龙风虎尽交回，太白入月敌可摧。
敌可摧，旄头灭，履胡之肠涉胡血。
悬胡青天上，埋胡紫[塞]旁。
胡无人，汉道昌，陛下之寿三千霜。
但歌大风云飞扬，安得猛士兮守四方。
胡无人，汉道昌。','',''),('quantangshi-01271','相和歌辞 胡无人行','僧貫休','quantangshi','','卷2','霍嫖姚，赵充国，天子将之平朔漠。
肉胡之肉，烬胡帐幄。
千里万里，惟留胡之空壳。
边风萧萧，榆叶初落。
杀气昼赤，枯骨夜哭。
将军既立殊勋，遂有胡无人曲。
我闻之，天子富有四海，德被无垠。','',''),('quantangshi-01272','相和歌辞 白头吟','劉希夷','quantangshi','','卷2','洛阳城东桃李花，飞来飞去落谁家。
洛阳女儿惜颜色，行逢落花长叹息。
今年花落颜色改，明年花开复谁在。
已见松柏摧为薪，更闻桑田变成海。
古人无复洛城东，今人还对落花风。
年年岁岁花相似，岁岁年年人不同。
寄言全盛红颜子，须怜半死白头翁。
此翁白头真可怜，伊昔红颜美少年。
公子王孙芳树下，清歌妙舞落花前。
光禄池台文锦绣，将军楼阁画神仙。
一朝卧病无人识，三春行乐在谁边。
宛转蛾眉能几时，须臾白发乱如丝。
但看旧来歌舞地，惟有黄昏鸟雀悲。','',''),('quantangshi-01273','相和歌辞 白头吟二首 一','李白','quantangshi','','卷2','锦水东北流，波荡双鸳鸯。
雄巢汉宫树，雌弄秦草芳。
宁同万死碎绮翼，不忍云间两分张。
此时阿娇正娇妬，独坐长门愁日暮。
但愿君恩顾妾深，岂惜黄金将买赋。
相如作赋得黄金，丈夫好新多异心。
一朝将聘茂陵女，文君因赠白头吟。
东流不作西归水，落花辞条归故林。
兔丝固无情，随风任颠倒。
谁使女萝枝，而来彊萦抱。
两草犹一心，人心不如草。
莫卷龙须席，从他生网丝。
且留琥珀枕，或有梦来时。
覆水再收岂满杯，弃妾已去难重回。
古时得意不相负，祗今惟见青陵台。','',''),('quantangshi-01274','相和歌辞 白头吟二首 二','李白','quantangshi','','卷2','锦水东流碧，波荡双鸳鸯。
雄巢汉宫树，雌弄秦草芳。
相如去蜀谒武帝，赤车驷马生辉光。
一朝再览大人作，万乘忽欲凌云翔。
闻道阿娇失恩宠，千金买赋要君王。
相如不忆贫贱日，官高金多聘私室。
茂陵姝子皆见求，文君欢爱徒此毕。
泪如双泉水，行堕紫罗襟。
五起鸡三唱，清晨白头吟。
长吁不整绿云鬓，仰诉青天哀怨深。
城崩杞梁妻，谁道土无心。
东流不作西归水，落花辞枝羞故林。
头上玉燕钗，是妾嫁时物。
赠君表相思，罗袖幸时拂。
莫卷龙须席，从他生网丝。
且留琥珀枕，还有梦来时。
鷫鸘裘在锦屏上，自君一挂无由披。
妾有秦楼镜，照心胜照井。
愿持照新人，双对可怜影。
覆水却收不满杯，相如还谢文君回。
古来得意不相负，祗今惟有青陵台。','',''),('quantangshi-01275','相和歌辞 白头吟','張籍','quantangshi','','卷2','请君膝上琴，弹我白头吟。
忆昔君前娇笑语，两情宛转如萦素。
宫中为我起高楼，更开华池种芳树。
春天百草秋始衰，弃我不待白头时。
罗襦玉珥色未暗，今朝已道不相宜。
扬州青铜作明镜，暗中持照不见影。
人心回互自无穷，眼前好恶那能定。
君恩已去若再返，菖蒲花生月长满。','',''),('quantangshi-01276','相和歌辞 反白头吟','白居易','quantangshi','','卷2','炎炎者烈火，营营者小蝇。
火不热真玉，蝇不点清冰。
此苟无所受，彼莫能相仍。
乃知物性中，各有能不能。
古称怨报死，则人有所惩。
惩淫或应可，在道未为弘。
譬如蜩鷃徒，啾啾啅龙鹏。
宜当委之去，寥廓高飞腾。
岂能泥尘下，区区酬怨憎。
胡为作自苦，吞悲仍抚膺。','',''),('quantangshi-01277','相和歌辞 决绝[词]三首 一','稹','quantangshi','','卷2','乍可为天上牵牛织女星，不愿为庭前红槿枝。
七月七日一相见，故心终不移。
那能朝开暮飞去，一任东西南北吹。
分不两相守，恨不两相思。
对面且如此，背面当何知。
春风撩乱伯劳语，此时抛去时。
握手苦相问，竟不言后期。
君情既决绝，妾意已参差。
借如死生别，安得长苦悲。','',''),('quantangshi-01278','相和歌辞 决绝[词]三首 二','稹','quantangshi','','卷2','噫春冰之将泮，何余怀之独结。
有美一人，于焉旷绝。
一日不见，比一日于三年，况三年之旷别。
水得风兮小而已波，笋在苞兮高不见节。
矧桃李之当春，竞众人之攀折。
我自顾悠悠而若云，又安能保君皓皓之如雪。
感破镜之分明，覩泪痕之余血。
幸他人之既不我先，又安能使他人之终不我夺。
已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。','',''),('quantangshi-01279','相和歌辞 决绝[词]三首 三','稹','quantangshi','','卷2','夜夜相抱眠，幽怀尚沈结。
那堪一年事，长遣一宵说。
但感久相思，何暇暂相悦。
虹桥薄夜成，龙驾侵晨列。
生憎野鹊往迟回，死恨天鸡识时节。
曙色渐曈昽，华星次明灭。
一去又一年，一年何时彻。
有此迢遰期，不如生死别。','',''),('quantangshi-01280','相和歌辞 梁甫吟','李白','quantangshi','','卷2','长啸梁甫吟，何时见阳春？
君不见朝歌屠叟辞棘津，八十西来钓渭滨。
宁羞白发照渌水，逢时吐气思经纶。
广张三千六百钧，风雅暗与文王亲。
大贤虎变愚不测，当年颇似寻常人。
君不见高阳酒徒起草中，长揖山东隆准公。
入门不拜骋雄辨，两女辍洗来趋风。
东下齐城七十二，指麾楚汉如旋蓬。
狂生落拓尚如此，何况壮士当羣雄。
我欲攀龙见明主，雷公砰訇震天鼓。
帝旁投壶多玉女，三时大笑开电光。
倏烁晦冥起风雨，阊阖九门不可通。
以额叩关阍者怒，白日不照吾精诚。
杞国无事忧天倾，䝟貐磨牙竞人肉。
驺虞不折生草茎，手接飞猱搏雕虎。
侧足焦原未言苦，智者可卷愚者豪。
世人见我轻鸿毛，力排南山三壮士，齐相杀之费二桃。
吴楚弄兵无剧孟，亚夫咍尔为徒劳。
梁父吟，梁父吟，声正悲。
张公两龙劒，神物合有时。
风云感会起屠钓，大人𡸣屼当安之。','',''),('quantangshi-01281','相和歌辞 东武吟','李白','quantangshi','','卷2','好古笑流俗，素闻贤达风。
方希佐明主，长揖辞成功。
白日在高天，回光烛微躬。
恭承凤皇诏，歘起云萝中。
清切紫霄迥，优游丹禁通。
君王赐颜色，声价凌烟虹。
乘舆拥翠盖，扈从金城东。
宝马丽绝景，锦衣入新丰。
倚岩望松雪，对酒鸣丝桐。
因学扬子云，献赋甘泉宫。
天书美片善，清芬播无穷。
归来入咸阳，谈笑皆王公。
一朝去金马，飘落成飞蓬。
宾友日疎散，玉尊亦已空。
才力犹可倚，不慙世上雄。
闲作东武吟，曲尽情未终。
书此谢知己，吾寻黄绮翁。','',''),('quantangshi-01282','相和歌辞 怨诗二首 一','薛奇童','quantangshi','','卷2','日晚梧桐落，微寒入禁垣。
月悬三雀观，霜度万秋门。
艳舞矜新宠，愁容泣旧恩。
不堪深殿里，帘外欲黄昏。','',''),('quantangshi-01283','相和歌辞 怨诗二首 二','薛奇童','quantangshi','','卷2','禁苑春风起，流莺绕合欢。
玉窗通日气，珠箔卷轻寒。
杨叶垂金砌，梨花入井阑。
君王好长袖，新作舞衣宽。','',''),('quantangshi-01284','相和歌辞 怨诗','張汯','quantangshi','','卷2','去年离别雁初归，今夜裁缝萤已飞。
征客近来音信断，不知何处寄寒衣。','',''),('quantangshi-01285','相和歌辞 怨诗','劉元濟','quantangshi','','卷2','玉关芳信断，兰闺锦字新。
愁来好自抑，念切已含嚬。
虚牖风惊梦，空牀月厌人。
归期傥可促，勿度柳园春。','',''),('quantangshi-01286','相和歌辞 怨诗三首 一','李暇','quantangshi','','卷2','罗敷初总髻，蕙芳正娇小。
月落始归船，春眠恒着晓。','',''),('quantangshi-01287','相和歌辞 怨诗三首 二','李暇','quantangshi','','卷2','何处期郎游？小苑花台间。
相忆不可见，且复乘月还。','',''),('quantangshi-01288','相和歌辞 怨诗三首 三','李暇','quantangshi','','卷2','别来花照路，别后露垂叶。
歌舞须及时，如何坐悲妾。','',''),('quantangshi-01289','相和歌辞 怨诗二首 一','崔國輔','quantangshi','','卷2','楼前桃李疎，池上芙蓉落。
织锦犹未成，虫声入罗幕。','',''),('quantangshi-01290','相和歌辞 怨诗二首 二','崔國輔','quantangshi','','卷2','妾有罗衣裳，秦王在时作。
为舞春风多，秋来不堪着。','',''),('quantangshi-01291','相和歌辞 怨诗','孟郊','quantangshi','','卷2','试妾与君泪，两处滴池水。
看取芙蓉花，今年为谁死。','',''),('quantangshi-01292','相和歌辞 怨诗','劉义','quantangshi','','卷2','君莫嫌丑妇，丑妇死守贞。
山头一怪石，长作望夫名。
鸟有竝翼飞，兽有比肩行。
丈夫不立义，岂如鸟兽情。','',''),('quantangshi-01293','相和歌辞 怨诗','鮑溶','quantangshi','','卷2','女萝寄松柏，绿蔓花緜緜。
三五定君婚，结发早移天。
肃肃羊雁礼，泠泠琴瑟篇。
恭承采蘩祀，敢效同居贤。
皎日不留景，良时如逝川。
秋心还遗爱，春貌无归妍。
翠袖洗朱粉，碧阶对绮钱。
新人易如玉，废瑟难为弦。
寄羡蕣华木，荣名香阁前。
岂无摇落苦，贵与根蒂连。
希君旧光景，照妾薄暮年。','',''),('quantangshi-01294','相和歌辞 怨诗','白居易','quantangshi','','卷2','夺宠心那惯，寻思倚殿门。
不知移旧爱，何处作新恩。','',''),('quantangshi-01295','相和歌辞 怨诗二首 一','姚氏月華','quantangshi','','卷2','春水悠悠春水绿，对此思君泪相续。
羞将离恨向东风，理尽秦筝不成曲。','',''),('quantangshi-01296','相和歌辞 怨诗二首 二','姚氏月華','quantangshi','','卷2','与君形影分胡越，玉枕终年对离别。
登台北望烟雨深，回身泣向寥天月。','',''),('quantangshi-01297','相和歌辞 怨歌行','虞世南','quantangshi','','卷2','紫殿秋风冷，雕甍白日沈。
裁纨凄断曲，织素别离心。
掖庭羞改画，长门不惜金。
宠移恩稍薄，情疎恨转深。
香销翠羽帐，弦断凤皇琴。
镜前红粉歇，阶上绿苔侵。
谁言掩歌扇，飜作白头吟。','',''),('quantangshi-01298','相和歌辞 怨歌行','李白','quantangshi','','卷2','十五入汉宫，花颜笑春红。
君王选玉色，侍寝金屏中。
荐枕娇夕月，卷衣恋春风。
宁知赵飞燕，夺宠恨无穷。
沈忧能伤人，绿鬓成霜蓬。
一朝不得意，世事徒为空。
鷫鸘换美酒，舞衣罢雕笼。
寒苦不忍言，为君奏丝桐。
肠断弦亦绝，悲心夜忡忡。','',''),('quantangshi-01299','相和歌辞 怨歌行','吳少微','quantangshi','','卷2','城南有怨妇，含怨倚兰丛。
自谓二八时，歌舞入汉宫。
皇恩弄幸玉堂中，绿陌黄花催夜酒。
锦衣罗袂逐春风，建章西宫焕若神。
燕赵美女二千人，君王厌德不忘新。
况羣艳冶纷来陈，是时别君不再见。
三十三春长信殿，长信重门昼掩关。
清房晓帐幽且闲，绮窗虫网氛尘色。
文轩莺对桃李颜，天王贵宫不贮老。
浩然泪陨今来还，自怜转晚暮。
试逐佳游芳草路，小腰丽女夺人奇。
金鞍少年曾不顾，归来谁为夫。
请谢西家妇，莫辞先醉解罗襦。','',''),('quantangshi-01300','相和歌辞 明月照高楼','雍陶','quantangshi','','卷2','朗月何高高，楼中帘影寒。
一妇独含叹，四坐谁成欢。
时节屡已移，游旅杳不还。
沧溟倘未涸，妾泪终不干。
君若无定云，妾若不动山。
云行出山易，山逐云去难。
愿为边塞尘，因风委君颜。
君颜良洗多，荡妾浊水间。','',''),('quantangshi-01301','相和歌辞 长门怨','徐賢妃','quantangshi','','卷2','旧爱柏梁台，新宠昭阳殿。
守分辞方辇，含情泣团扇。
一朝歌舞荣，夙昔诗书贱。
颓恩诚已矣，覆水难重荐。','',''),('quantangshi-01302','相和歌辞 长门怨','沈佺期','quantangshi','','卷2','月皎风泠泠，长门次掖庭。
玉阶闻坠叶，罗幌见飞萤。
清露凝珠缀，流尘下翠屏。
妾心君未察，秋叹剧繁星。','',''),('quantangshi-01303','相和歌辞 长门怨','吳少微','quantangshi','','卷2','月出映曾城，孤圜上太清。
君王春爱歇，枕席凉风生。
怨咽不能寝，踟蹰步前楹。
空阶白露色，百草寒虫鸣。
念昔金房里，犹嫌玉座轻。
如何娇所误，长夜泣恩情。','',''),('quantangshi-01304','相和歌辞 长门怨','張脩之','quantangshi','','卷2','长门落景尽，洞房秋月明。
玉阶草路积，金屋网尘生。
妾妬今应改，君恩昔未平。','',''),('quantangshi-01305','相和歌辞 长门怨','裴交泰','quantangshi','','卷2','自闭长门经几秋，罗衣湿尽泪还流。
一种蛾眉明月夜，南宫歌管北宫愁。','',''),('quantangshi-01306','相和歌辞 长门怨','劉皁','quantangshi','','卷2','宫殿沈沈月欲分，昭阳更漏不堪闻。
珊瑚枕上千行泪，不是思君是恨君。','',''),('quantangshi-01307','相和歌辞 长门怨','袁暉','quantangshi','','卷2','早知君爱歇，本自无萦妬。
谁使恩情深，今来反相误。
愁眠罗帐晓，泣坐金闺暮。
独有梦中魂，犹言意如故。','',''),('quantangshi-01308','相和歌辞 长门怨','劉言史','quantangshi','','卷2','独坐炉边结夜愁，暂时恩去亦难留。
手持金箸垂红泪，乱拨寒灰不举头。','',''),('quantangshi-01309','相和歌辞 长门怨二首 一','李白','quantangshi','','卷2','天回北斗挂西楼，金屋无人萤火流。
月光欲到长门殿，别作深宫一段愁。','',''),('quantangshi-01310','相和歌辞 长门怨二首 二','李白','quantangshi','','卷2','桂殿长愁不记春，黄金四屋起秋尘。
夜悬明镜青天上，独照长门宫里人。','',''),('quantangshi-01311','相和歌辞 长门怨','李華','quantangshi','','卷2','弱体鸳鸯荐，啼妆翡翠衾。
鸦鸣秋殿晓，人静禁门深。
每忆椒房宠，那堪永巷阴。
日惊罗带缓，非复旧来心。','',''),('quantangshi-01312','相和歌辞 长门怨','岑參','quantangshi','','卷2','君王嫌妾妬，闭妾在长门。
舞袖垂新宠，愁眉结旧恩。
绿钱生履迹，红粉湿啼痕。
羞被桃花笑，看春独不言。','',''),('quantangshi-01313','相和歌辞 长门怨','齊澣','quantangshi','','卷2','茕茕孤思逼，寂寂长门夕。
妾妬亦非深，君恩那不惜。
携琴就玉阶，调悲声未谐。
将心托明月，流影入君怀。','',''),('quantangshi-01314','相和歌辞 长门怨','劉長卿','quantangshi','','卷2','何事长门闭，珠帘只自垂。
月移深殿早，春向后宫迟。
蕙草生闲地，梨花发旧枝。
芳菲自恩幸，看却被风吹。','',''),('quantangshi-01315','相和歌辞 长门怨','僧皎然','quantangshi','','卷2','春风日日闭长门，摇荡春心自梦魂。
若遣花开只笑妾，不如桃李正无言。','',''),('quantangshi-01316','相和歌辞 长门怨','盧綸','quantangshi','','卷2','空宫古廊殿，寒月照斜晖。
卧听未央曲，满箱歌舞衣。','',''),('quantangshi-01317','相和歌辞 长门怨','戴叔倫','quantangshi','','卷2','自忆专房宠，曾居第一流。
移恩向何处？暂妬不容收。
夜久丝管绝，月明宫殿秋。
空将旧时意，长望凤皇楼。','',''),('quantangshi-01318','相和歌辞 长门怨','劉駕','quantangshi','','卷2','御泉长绕凤皇楼，只是恩波别处流。
闲揲舞衣归未得，夜来砧杵六宫秋。','',''),('quantangshi-01319','相和歌辞 长门怨 一','高蟾','quantangshi','','卷2','天上何劳万古春，君前谁是百年人。
魂销尚愧金炉烬，思起犹慙玉辇尘。
烟翠薄情攀不得，星芒浮艳采无因。
可怜明镜来相向，何似恩光朝夕新。','',''),('quantangshi-01320','相和歌辞 长门怨 二','高蟾','quantangshi','','卷2','天上凤皇休寄梦，人间鹦鹉旧堪悲。
平生心绪无人识，一只金梭万丈丝。','',''),('quantangshi-01321','相和歌辞 长门怨','張祜','quantangshi','','卷2','日映宫墙柳色寒，笙歌遥指碧云端。
珠铅滴尽无心语，彊把花枝冷笑看。','',''),('quantangshi-01322','相和歌辞 长门怨二首 一','鄭谷','quantangshi','','卷2','闲把罗衣泣凤皇，先朝曾教舞霓裳。
春来却羡庭花落，得逐晴风出禁墙。','',''),('quantangshi-01323','相和歌辞 长门怨二首 二','鄭谷','quantangshi','','卷2','流水君恩共不回，杏花争忍埽成堆。
残春未必多烟雨，泪滴闲阶长绿苔。','',''),('quantangshi-01324','相和歌辞 长门怨二首 一','劉氏媛','quantangshi','','卷2','雨滴梧桐秋夜长，愁心和雨到昭阳。
泪痕不学君恩断，拭却千行更万行。','',''),('quantangshi-01325','相和歌辞 长门怨二首 二','劉氏媛','quantangshi','','卷2','学画蛾眉独出羣，当时人道便承恩。
经年不见君王面，花落黄昏空掩门。','',''),('quantangshi-01326','相和歌辞 阿娇怨','劉禹錫','quantangshi','','卷2','望见葳蕤举翠华，试开金屋埽庭花。
须臾宫女传来信，云幸平阳公主家。','',''),('quantangshi-01327','相和歌辞 班倢伃','徐彥伯','quantangshi','','卷2','君恩忽断绝，妾思终未央。
巾栉不可见，枕席空余香。
窗暗网罗白，阶秋苔藓黄。
应门寂已闭，流涕向昭阳。','',''),('quantangshi-01328','相和歌辞 班倢伃','嚴識玄','quantangshi','','卷2','贱妾如桃李，君王若岁时。
秋风一已劲，摇落不胜悲。
寂寂苍苔满，沈沈绿草滋。
荣华非此日，指辇竞何辞。','',''),('quantangshi-01329','相和歌辞 班倢伃三首 一','王維','quantangshi','','卷2','玉窗萤影度，金殿人声绝。
秋夜守罗帏，孤灯耿不灭。','',''),('quantangshi-01330','相和歌辞 班倢伃三首 二','王維','quantangshi','','卷2','宫殿生秋草，君王恩幸疎。
那堪闻凤吹，门外度金舆。','',''),('quantangshi-01331','相和歌辞 班倢伃三首 三','王維','quantangshi','','卷2','怪来妆阁闭，朝下不相迎。
总向春园里，花间语笑声。','',''),('quantangshi-01332','相和歌辞 倢伃怨','崔湜','quantangshi','','卷2','不分君恩断，新妆视镜中。
容华尚春日，娇爱已秋风。
枕席临窗晓，帏屏向月空。
年年后庭树，荣落在深宫。','',''),('quantangshi-01333','相和歌辞 倢伃怨','崔國輔','quantangshi','','卷2','长信宫中草，年年愁处生。
故侵珠履迹，不使玉阶行。','',''),('quantangshi-01334','相和歌辞 倢伃怨','張烜','quantangshi','','卷2','贱妾裁纨扇，初摇明月姿。
君王看舞席，坐起秋风时。
玉树清御路，金陈翳垂丝。
昭阳无分理，愁寂任前期。','',''),('quantangshi-01335','相和歌辞 倢伃怨','劉方平','quantangshi','','卷2','夕殿别君王，宫深月似霜。
人愁在长信，萤出向昭阳。
露裛红兰死，秋雕碧树伤。
惟当合欢扇，从此箧中藏。','',''),('quantangshi-01336','相和歌辞 倢伃怨','王沈','quantangshi','','卷2','长信梨花暗欲栖，应门上龠草萋萋。
春风吹花乱扑户，班倢车声不至啼。','',''),('quantangshi-01337','相和歌辞 倢伃怨','皇甫冉','quantangshi','','卷2','由来咏团扇，今与值秋风。
事逐时皆往，恩无日再中。
早鸿闻上苑，寒露下深宫。
颜色年年谢，相如赋岂工。','',''),('quantangshi-01338','相和歌辞 倢伃怨','陸龜蒙','quantangshi','','卷2','妾貌非倾国，君王忽然宠。
南山掌上来，不及新恩重。
后宫多窈窕，日日学新声。
一落君王耳，南山又须轻。','',''),('quantangshi-01339','相和歌辞 倢伃怨','翁綬','quantangshi','','卷2','谗谤潜来起百忧，朝承恩宠暮仇讐。
火烧白玉非因玷，霜翦红兰不待秋。
花落昭阳谁共辇，月明长信独登楼。
繁华事逐东流水，团扇悲歌万古愁。','',''),('quantangshi-01340','相和歌辞 倢伃怨','劉氏雲','quantangshi','','卷2','君恩不可见，妾岂如秋扇。
秋扇尚有时，妾身永微贱。
莫言朝花不复落，娇容几夺昭阳殿。','',''),('quantangshi-01341','相和歌辞 长信怨','王諲','quantangshi','','卷2','飞燕倚身轻，争人巧笑名。
生君弃妾意，增妾怨君情。
日落昭阳殿，秋来长信城。
寥寥金殿里，歌吹夜无声。','',''),('quantangshi-01342','相和歌辞 长信怨 一','王昌齡','quantangshi','','卷2','金井梧桐秋叶黄，珠帘不卷夜来霜。
金炉玉枕无颜色，卧听南宫清漏长。','',''),('quantangshi-01343','相和歌辞 长信怨 二','王昌齡','quantangshi','','卷2','奉帚平明金殿开，暂将团扇共裴回。
玉颜不及寒鵶色，犹带昭阳日影来。','',''),('quantangshi-01344','相和歌辞 长信怨','李白','quantangshi','','卷2','月皎昭阳殿，霜清长信宫。
天行乘玉辇，飞燕与君同。
更有留情处，承恩乐未穷。
谁怜团扇妾，独坐怨秋风。','',''),('quantangshi-01345','相和歌辞 蛾眉怨','王翰','quantangshi','','卷2','君不见宜春苑中九华殿，飞阁连连直如发。
白日全含朱鸟窗，流云半入苍龙阙。
宫中彩女夜无事，学凤吹箫弄清越。
珠帘北卷待凉风，绣户南开向明月。
忽闻天子忆蛾眉，宝凤衔花揲两螭。
传声走马开金屋，夹路鸣环上玉墀。
长乐彤庭宴华寝，三千美人曳光锦。
灯前含笑更罗衣，帐里承恩荐瑶枕。
不意君心半路回，求仙别作望仙台。
仓琅禁闼遥相忆，紫翠岩房昼不开。
欲向人间种桃实，先从海底觅蓬莱。
蓬莱可求不可上，孤舟缥缈知何往？
黄金作盘铜作茎，晴天白露掌中擎。
王母嫣然感君意，云车雨斾欲相迎。
飞帘观前空怨慕，少君何事须相误。
一朝埋没茂陵田，贱妾蛾眉不重顾。
宫车晚出向南山，仙卫逶迤去不还。
朝晡泣对麒麟树，树下苍苔日渐斑。
人生百年夜将半，对酒长歌莫长叹。
剩知白日不可思，一死一生何足算。','',''),('quantangshi-01346','相和歌辞 玉阶怨','李白','quantangshi','','卷2','玉阶生白露，夜久侵罗袜。
却下水精帘，玲珑望秋月。','',''),('quantangshi-01347','相和歌辞 宫怨','長孫佐輔','quantangshi','','卷2','窗前好树名玫瑰，去年花落今年开。
无情春色尚识返，君心忽断何时来？
忆昔妆成候仙仗，宫琐玲珑日新上。
拊心却笑西子嚬，掩鼻谁忧郑姬谤。
草染文章衣下履，花黏甲乙牀前帐。
三千玉貌休自夸，十二金钗独相向。
盛衰倾夺欲何如，娇爱飜悲逐佞谀。
重远岂能慙沼鹄，弃前方见泣船鱼。
看笼不记熏龙脑，咏扇空曾秃鼠须。
始意类萝新托柏，终伤如荠却甘荼。
深院独开还独闭，鹦鹉惊飞苔覆地。
满箱旧赐前日衣，渍枕新垂夜来泪。
痕多开镜照还悲，绿髻青蛾尚未衰。
莫道新缣长绝比，犹逢故劒会相追。','',''),('quantangshi-01348','相和歌辞 宫怨','李益','quantangshi','','卷2','露湿晴花宫殿香，月明歌吹在昭阳。
似将海水添宫漏，共滴长门一夜长。','',''),('quantangshi-01349','相和歌辞 宫怨','于濆','quantangshi','','卷2','妾家望江口，少年家财厚。
临江起珠楼，不卖文君酒。
当年乐贞独，巢燕时为友。
父兄未许人，畏妾事姑舅。
西墙邻宋玉，窥见妾眉宇。
一旦及天聪，恩光生户牖。
谓言入汉宫，富贵可长久。
君王纵有情，不奈陈皇后。
谁怜颊似桃，孰知腰胜柳。
今日在长门，从来不如丑。','',''),('quantangshi-01350','相和歌辞 宫怨 一','柯崇','quantangshi','','卷2','尘满金炉不炷香，黄昏独自立重廊。
笙歌何处承恩宠？一一随风入上阳。','',''),('quantangshi-01351','相和歌辞 宫怨 二','柯崇','quantangshi','','卷2','长门槐柳半萧疎，玉辇沈思恨有余。
红泪旋销倾国态，黄金谁为达相如。','',''),('quantangshi-01352','相和歌辞 杂怨三首 一','聶夷中','quantangshi','','卷2','生在绮罗下，岂识渔阳道。
良人自戍来，夜夜梦中到。
渔阳万里远，近于中门限。
中门逾有时，渔阳常在眼。','',''),('quantangshi-01353','相和歌辞 杂怨三首 二','聶夷中','quantangshi','','卷2','良人昨日去，明日又不还。
别时各有泪，零落青楼前。','',''),('quantangshi-01354','相和歌辞 杂怨三首 三','聶夷中','quantangshi','','卷2','君泪濡罗巾，妾泪滴路尘。
罗巾今在手，日得随妾身。
路尘如因飞，得上君车轮。','',''),('quantangshi-01355','相和歌辞 杂怨三首 一','孟郊','quantangshi','','卷2','夭桃花清晨，游女红粉新。
夭桃花薄暮，游女红粉故。
树有百年花，人无一定颜。
花送人老尽，人悲花自闲。','',''),('quantangshi-01356','相和歌辞 杂怨三首 二','孟郊','quantangshi','','卷2','贫女镜不明，寒花日少容。
暗蛩有虚织，短线无长缝。
浪水不可照，狂夫不可从。
浪水多散影，狂夫多异踪。
持此一生薄，空成百恨浓。','',''),('quantangshi-01357','相和歌辞 杂怨三首 三','孟郊','quantangshi','','卷2','忆人莫至悲，至悲空自衰。
寄人莫翦衣，翦衣未必归。
朝为双蒂花，暮为四散飞。
花落却绕树，游子不顾期。','',''),('quantangshi-01358','相和歌辞 子夜春歌','王翰','quantangshi','','卷2','春气满林香，春游不可忘。
落花吹欲尽，垂柳折还长。
桑女淮南曲，金鞍塞北装。
行行小垂手，日暮渭川阳。','',''),('quantangshi-01359','相和歌辞 子夜冬歌','崔國輔','quantangshi','','卷2','寂寥抱冬心，裁罗又褧褧。
夜久频挑灯，霜寒剪刀冷。','',''),('quantangshi-01360','相和歌辞 子夜冬歌','薛耀','quantangshi','','卷2','朔风扣羣木，岩霜凋百草。
借问月中人，安得长不老。','',''),('quantangshi-01361','相和歌辞 子夜四时歌六首 春歌二首 一','郭元振','quantangshi','','卷2','青楼含日光，绿池起风色。
赠子同心花，殷勤此何极。','',''),('quantangshi-01362','相和歌辞 子夜四时歌六首 春歌二首 二','郭元振','quantangshi','','卷2','陌头杨柳枝，已被春风吹。
妾心正断绝，君怀那得知。','',''),('quantangshi-01363','相和歌辞 子夜四时歌六首 秋歌二首 一','郭元振','quantangshi','','卷2','邀欢空伫立，望美频回顾。
何时复采菱？江中密相遇。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01364','相和歌辞 子夜四时歌六首 秋歌二首 二','郭元振','quantangshi','','卷2','辟恶茱萸囊，延年菊花酒。','',''),('quantangshi-01365','相和歌辞 子夜四时歌六首 冬歌二首 一','郭元振','quantangshi','','卷2','北极严气升，南至温风谢。
调丝竞短歌，拂枕怜长夜。','',''),('quantangshi-01366','相和歌辞 子夜四时歌六首 冬歌二首 二','郭元振','quantangshi','','卷2','帷横双翡翠，被卷两鸳鸯。
婉态不自得，宛转君王牀。','',''),('quantangshi-01367','相和歌辞 子夜四时歌四首 春歌','李白','quantangshi','','卷2','秦地罗敷女，采桑绿水边。
素手青条上，红妆白日鲜。
蚕饥妾欲去，五马莫留连。','',''),('quantangshi-01368','相和歌辞 子夜四时歌四首 夏歌','李白','quantangshi','','卷2','镜湖三百里，菡萏发荷花。
五月西施采，人看隘若邪。
回舟不待月，归去越王家。','',''),('quantangshi-01369','相和歌辞 子夜四时歌四首 秋歌','李白','quantangshi','','卷2','长安一片月，万户捣衣声。
秋风吹不尽，总是玉关情。
何日平胡虏？良人罢远征。','',''),('quantangshi-01370','相和歌辞 子夜四时歌四首 冬歌','李白','quantangshi','','卷2','明朝驿使发，一夜絮征袍。
素手抽针冷，那堪把剪刀。
裁缝寄远道，几日到临洮。','',''),('quantangshi-01371','相和歌辞 子夜四时歌四首 春歌','陸龜蒙','quantangshi','','卷2','山连翠羽屏，草接烟华席。
望尽南飞燕，佳人断信息。','',''),('quantangshi-01372','相和歌辞 子夜四时歌四首 夏歌','陸龜蒙','quantangshi','','卷2','兰眼抬露斜，莺唇映花老。
金龙倾漏尽，玉井敲冰早。','',''),('quantangshi-01373','相和歌辞 子夜四时歌四首 秋歌','陸龜蒙','quantangshi','','卷2','凉汉清泬寥，衰林怨风雨。
愁听络纬唱，似与羇魂语。','',''),('quantangshi-01374','相和歌辞 子夜四时歌四首 冬歌','陸龜蒙','quantangshi','','卷2','南光走冷圭，北籁号空木。
年年任霜霰，不减篔簹绿。','',''),('quantangshi-01375','相和歌辞 大子夜歌二首 一','陸龜蒙','quantangshi','','卷2','歌谣数百种，子夜最可怜。
慷慨吐清音，明转出天然。','',''),('quantangshi-01376','相和歌辞 大子夜歌二首 二','陸龜蒙','quantangshi','','卷2','丝竹发歌响，假器扬清音。
不知歌谣妙，声势出口心。','',''),('quantangshi-01377','相和歌辞 子夜警歌二首 一','陸龜蒙','quantangshi','','卷2','镂椀传绿酒，雕炉熏紫烟。
谁知苦寒调，共作白雪弦。','',''),('quantangshi-01378','相和歌辞 子夜警歌二首 二','陸龜蒙','quantangshi','','卷2','恃爱如欲进，含羞出不前。
朱口发艳歌，玉指弄娇弦。','',''),('quantangshi-01379','相和歌辞 丁督护歌','李白','quantangshi','','卷2','云阳上征去，两岸饶商贾。
吴牛喘月时，拖船一何苦。
水浊不可饮，壶浆半成土。
一唱都护歌，心摧泪如雨。
万人凿盘石，无由达江浒。
君看石芒砀，掩泪悲千古。','',''),('quantangshi-01380','相和歌辞 团扇郎','張祜','quantangshi','','卷2','白团扇，今来此去捐。
愿得入郎手，团圆郎眼前。','',''),('quantangshi-01381','相和歌辞 团扇郎','劉禹錫','quantangshi','','卷2','团扇复团扇，奉君清暑殿。
秋风入庭树，从此不相见。
上有乘鸾女，苍苍虫网遍。
明年入怀袖，别是机中练。','',''),('quantangshi-01382','相和歌辞 碧玉歌','李暇','quantangshi','','卷2','碧玉上宫妓，出入千花林。
珠被玳瑁牀，感郎情意深。','',''),('quantangshi-01383','相和歌辞 懊恼曲','溫庭筠','quantangshi','','卷2','藕丝作线难胜针，蘂粉染黄那得深。
玉白兰芳不相顾，倡楼一笑轻千金。
莫言自古皆如此，健劒刜钟铅绕指。
三秋庭绿尽迎霜，惟有荷花守红死。
西江小吏朱斑轮，柳缕吐芽香玉春。
两股金钗已相许，不令独作空城尘。
悠悠楚水流如马，恨紫愁红满平野。
野土千年怨不平，至今烧作鸳鸯瓦。','',''),('quantangshi-01384','相和歌辞 读曲歌五首 一','張祜','quantangshi','','卷2','窗中独自起，帘外独自行。
愁见蜘蛛织，寻思直到明。','',''),('quantangshi-01385','相和歌辞 读曲歌五首 二','張祜','quantangshi','','卷2','碓上米不舂，窗中丝罢络。
看渠驾去车，定是无四角。','',''),('quantangshi-01386','相和歌辞 读曲歌五首 三','張祜','quantangshi','','卷2','不见心相许，徒云脚漫勤。
摘荷空摘叶，是底采莲人。','',''),('quantangshi-01387','相和歌辞 读曲歌五首 四','張祜','quantangshi','','卷2','窗外山魈立，知渠脚不多。
三更机底下，摸着是谁梭。','',''),('quantangshi-01388','相和歌辞 读曲歌五首 五','張祜','quantangshi','','卷2','郎去摘黄瓜，郎来收赤枣。
郎耕种麻地，今作西舍道。','',''),('quantangshi-01389','相和歌辞 春江花月夜二首 一','張子容','quantangshi','','卷2','林花发岸口，气色动江新。
此夜江中月，流光花上春。
分明石潭里，宜照浣纱人。','',''),('quantangshi-01390','相和歌辞 春江花月夜二首 二','張子容','quantangshi','','卷2','交甫怜瑶佩，仙妃难重期。
沈沈绿江晚，惆怅碧云姿。
初逢花上月，言是弄珠时。','',''),('quantangshi-01391','相和歌辞 春江花月夜','張若虛','quantangshi','','卷2','春江潮水连海平，海上明月共潮生。
滟滟随波千万里，何处春江无月明？
江流宛转遶芳甸，月照花林皆似霰。
空里流霜不觉飞，汀上白沙看不见。
江天一色无纤尘，皎皎空中孤月轮。
江畔何人初见月？江月何年初照人？
人生代代无穷已，江月年年望相似。
不知江月待何人，但见长江送流水。
白云一片去悠悠，青枫浦上不胜愁。
谁家今夜扁舟子，何处相思明月楼？
可怜楼上月裴回，应照离人妆镜台。
玉户帘中卷不去，捣衣砧上拂还来。
此时相望不相闻，愿逐月华流照君。
鸿雁长飞光不度，鱼龙潜跃水成文。
昨夜闲潭梦落花，可怜春半不还家。
江水流春去欲尽，江潭落月复西斜。
斜月沈沈藏海雾，碣石潇湘无限路。
不知乘月几人归，落月摇情满江树。','',''),('quantangshi-01392','相和歌辞 春江花月夜','溫庭筠','quantangshi','','卷2','玉树歌阑海云黑，花庭忽作青芜国。
秦淮有水水无情，还向金陵漾春色。
杨家二世安九重，不御华芝嫌六龙。
百幅锦帆风力满，连天展尽金芙蓉。
珠翠丁星复明灭，龙头劈浪哀笳发。
千里涵空照水魂，万枝破鼻团香雪。
漏转霞高沧海西，颇黎枕上闻天鸡。
蛮弦代雁曲如语，一醉昏昏天下迷。
四方倾动烟尘起，犹在浓香梦魂里。
后主荒宫有晓莺，飞来只隔西江水。','',''),('quantangshi-01393','相和歌辞 玉树后庭花','張祜','quantangshi','','卷2','轻车何草草，独唱后庭花。
玉座谁为主，徒悲张丽华。','',''),('quantangshi-01394','相和歌辞 堂堂','溫庭筠','quantangshi','','卷2','钱塘岸上春如织，淼淼寒潮带晴色。
淮南游客马连嘶，碧草迷人归不得。
风飘客意如吹烟，纤指殷勤伤雁弦。
一曲堂堂红烛筵，金鲸泻酒如飞泉。','',''),('quantangshi-01395','相和歌辞 三阁词四首 一','劉禹錫','quantangshi','','卷2','贵人三阁上，日晏未梳头。
不应有恨事，娇甚却成愁。','',''),('quantangshi-01396','相和歌辞 三阁词四首 二','劉禹錫','quantangshi','','卷2','珠箔曲琼钩，子细见扬州。
北兵那得度，浪语判悠悠。','',''),('quantangshi-01397','相和歌辞 三阁词四首 三','劉禹錫','quantangshi','','卷2','沈香帖阁柱，金缕画门楣。
回首降幡下，已见黍离离。','',''),('quantangshi-01398','相和歌辞 三阁词四首 四','劉禹錫','quantangshi','','卷2','三人出眢井，一身登槛车。
朱门漫临水，不可见鲈鱼。','',''),('quantangshi-01399','相和歌辞 神弦曲','李賀','quantangshi','','卷2','西山日没东山昏，旋风吹马马踏云。
画弦素管声浅繁，花裙綷䌨步秋尘。
桂叶刷风桂坠子，青狸哭血寒狐死。
古壁彩虬金帖尾，雨工骑入秋潭水。
百年老鸮成木魅，笑声碧火巢中起。','',''),('quantangshi-01400','相和歌辞 神弦别曲','李賀','quantangshi','','卷2','巫山小女隔云别，松花春风山上发。
绿盖独穿香迳归，白马花竿前孑孑。
蜀江风澹水如罗，堕兰谁泛相经过。
南山桂树为君死，云衫残污红脂花。','',''),('quantangshi-01401','相和歌辞 祠渔山神女歌 迎神','王維','quantangshi','','卷2','坎坎击鼓，渔山之下。
吹洞箫，望极浦。
女巫进，纷屡舞。
陈瑶席，湛清酤。
风凄凄，又夜雨。
不知神之来兮不来，使我心兮苦复苦。','',''),('quantangshi-01402','相和歌辞 祠渔山神女歌 送神','王維','quantangshi','','卷2','纷进舞兮堂前，目眷眷兮琼筵。
来不言兮意不传，作暮雨兮愁空山。
悲急管兮思繁弦，神之驾兮俨欲旋。
倏云收兮雨歇，山青青兮水潺湲。','',''),('quantangshi-01403','相和歌辞 祠神歌 迎神','王叡','quantangshi','','卷2','蓪草头花椰叶裙，蒲葵树下舞蛮云。
引领望江遥滴酒，白苹风起水生文。','',''),('quantangshi-01404','相和歌辞 祠神歌 送神','王叡','quantangshi','','卷2','枨枨山响答琵琶，酒湿青莎肉饲鵶。
树叶无声神去后，纸钱灰出木绵花。','',''),('quantangshi-01405','相和歌辞 乌夜啼','楊巨源','quantangshi','','卷2','可怜杨叶复杨花，雪净烟深碧玉家。
乌栖不定枝条弱，城头夜半声哑哑。
浮萍摇荡门前水，任罥芙蓉莫堕沙。','',''),('quantangshi-01406','相和歌辞 乌夜啼','李白','quantangshi','','卷2','黄云城边乌欲栖，归飞哑哑枝上啼。
机中织锦秦川女，碧纱如烟隔窗语。
停梭怅然忆远人，独宿孤房泪如雨。','',''),('quantangshi-01407','相和歌辞 乌夜啼二首 一','顧況','quantangshi','','卷2','玉房掣锁声翻叶，银箭添泉遶霜堞。
毕逋发刺月衔城，八九雏飞其母惊。
此是天上老鵶鸣，人间老鵶无此声。
摇杂佩，耿华烛，良夜羽人弹此曲，东方曈曈赤日旭。','',''),('quantangshi-01408','相和歌辞 乌夜啼二首 二','顧況','quantangshi','','卷2','月出江林西，江林寂寂城鵶啼。
昔人何处为此曲？今人何处听不足。
城寒月晓驰思深，江上青草为谁绿。','',''),('quantangshi-01409','相和歌辞 乌夜啼','李羣玉','quantangshi','','卷2','曾波隔梦渚，一望青枫林。
有乌在其间，达晓自悲吟。
是时月黑天，四野烟雨深。
如闻生离哭，其声痛人心。
悄悄夜正长，空山响哀音。
远客不可听，坐愁华发侵。
既非蜀帝魂，恐是恒山禽。
四子各分散，母声犹至今。','',''),('quantangshi-01410','相和歌辞 乌夜啼','聶夷中','quantangshi','','卷2','众鸟各归枝，乌乌尔不栖。
还应知妾恨，故向绿窗啼。','',''),('quantangshi-01411','相和歌辞 乌夜啼','白居易','quantangshi','','卷2','城上归时晚，庭前宿处危。
月明无叶树，霜滑有风枝。
啼涩饥喉咽，飞低冻翅垂。
画堂鹦鹉鸟，冷暖不相知。','',''),('quantangshi-01412','相和歌辞 乌夜啼','王建','quantangshi','','卷2','庭树乌，尔何不向别处栖？
夜夜夜半当户啼。
家人把烛出洞户，惊栖失羣飞落树。
一飞直欲飞上天，回回不离旧栖处。
未明重绕主人屋，欲下空中黑相触。
风飘雨湿亦不移，君家树头多好枝。','',''),('quantangshi-01413','相和歌辞 乌夜啼','張祜','quantangshi','','卷2','忽忽南飞返，危弦共怨凄。
暗霜移树宿，残夜遶枝啼。
咽绝声重敍，愔淫思乍迷。
不妨还报喜，误使玉颜低。','',''),('quantangshi-01414','相和歌辞 乌栖曲','李白','quantangshi','','卷2','姑苏台上乌栖时，吴王宫里醉西施。
吴歌楚舞欢未毕，青山犹衔半边日。','',''),('quantangshi-01415','相和歌辞 乌栖曲','李端','quantangshi','','卷2','白马逐牛车，黄昏入狭斜。
狭斜柳树乌争宿，争枝未得飞上屋。
东房少妇壻从军，每听乌啼知夜分。','',''),('quantangshi-01416','相和歌辞 乌栖曲','王建','quantangshi','','卷2','章华宫人夜上楼，君王望月西山头。
夜深宫殿门不锁，白露满山山叶堕。','',''),('quantangshi-01417','相和歌辞 乌栖曲','張籍','quantangshi','','卷2','西山作宫潮满池，宫乌晓鸣茱萸枝。
吴姬自唱采莲曲，君王昨夜舟中宿。','',''),('quantangshi-01418','相和歌辞 栖乌曲二首 一','劉方平','quantangshi','','卷2','蛾眉曼脸倾城国，鸣环动佩新相识。
银汉斜临白玉堂，芙蓉行障掩灯光。','',''),('quantangshi-01419','相和歌辞 栖乌曲二首 二','劉方平','quantangshi','','卷2','画舸双艚锦为缆，芙蓉花发莲叶暗。
门前月色映横塘，感郎中夜渡潇湘。','',''),('quantangshi-01420','相和歌辞 莫愁乐','張祜','quantangshi','','卷2','侬居石城下，郎到石城游。
自郎石城出，长在石城头。','',''),('quantangshi-01421','相和歌辞 莫愁曲','李賀','quantangshi','','卷2','草生陇坂下，鵶噪城堞头。
何人此城里，城角栽石榴。
青丝系五马，黄金络双牛。
白鱼驾莲船，夜作十里游。
归来无人识，暗上沈香楼。
罗牀倚瑶瑟，残月倾帘钩。
今日槿花落，明朝梧树秋。
若负平生意，何名作莫愁。','',''),('quantangshi-01422','相和歌辞 估客乐','李白','quantangshi','','卷2','海客乘天风，将船远行役。
譬如云中鸟，一去无踪迹。','',''),('quantangshi-01423','相和歌辞 估客乐','稹','quantangshi','','卷2','估客无住着，有利身即行。
出门求火伴，入户辞父兄。
父兄相教示，求利莫求名。
求名有所避，求利无不营。
火伴相勒缚，卖假莫卖诚。
交关少交假，交假本生轻。
自兹相将去，誓死意不更。
一解市头语，便无乡里情。
鍮石打臂钏，糯米炊项璎。
归来村中卖，敲作金玉声。
村中田舍娘，贵贱不敢争。
所费百钱本，已得十倍赢。
颜色转光净，饮食亦甘馨。
子本频蕃息，货赂日兼并。
求珠驾沧海，采玉上荆衡。
北买党项马，西擒吐蕃鹦。
炎洲布火浣，蜀地锦织成。
越婢脂肉滑，奚僮眉眼明。
通算衣食费，不计远近程。
经营天下徧，却到长安城。
城中东西市，闻客次第迎。
迎客兼说客，多财为势倾。
客心本明黠，闻语心已惊。
先问十常侍，次求百公卿。
侯家与主第，点缀无不精。
归来始安坐，富与王家勍。
市卒酒肉臭，县胥家舍成。
岂惟绝言语，奔走极使令。
大儿贩材木，巧识梁栋形。
小儿贩盐卤，不入州县征。
一身偃市利，突若截海鲸。
钩距不敢下，下则牙齿横。
生为估客乐，判尔乐一生。','',''),('quantangshi-01424','相和歌辞 贾客乐','張籍','quantangshi','','卷2','金陵向西贾客多，船中生长乐风波。
欲发移船近江口，船头祭神各浇酒。
停杯共说远行期，入蜀经蛮远别离。
金多众中为上客，夜夜算缗眠独迟。
秋江初月猩猩语，孤帆夜发满湘渚。
水工持檝防暗滩，直过山边及前侣。
年年逐利西复东，姓名不在县籍中。
农夫税多长辛苦，弃业长为贩卖翁。','',''),('quantangshi-01425','相和歌辞 贾客词','劉禹錫','quantangshi','','卷2','贾客无定游，所游惟利并。
眩俗杂良苦，乘时知重轻。
心计析秋毫，摇钩侔悬衡。
锥刀既无弃，转化日已盈。
邀福祷波神，施财游化城。
妻约雕金钏，女垂贯珠缨。
高赀比封君，奇货通幸卿。
趋时鸷鸟思，藏镪盘龙形。
大艑浮通川，高楼次旗亭。
行止皆有乐，关梁似无征。
农夫何为者？辛苦事寒耕。','',''),('quantangshi-01426','相和歌辞 贾客词','劉駕','quantangshi','','卷2','贾客灯下起，犹言发已迟。
高山有疾路，暗行终不疑。
寇盗伏其路，猛兽来相追。
金玉四散去，空囊委路岐。
扬州有大宅，白骨无地归。
少妇当此日，对镜弄花枝。','',''),('quantangshi-01427','相和歌辞 襄阳乐','張祜','quantangshi','','卷2','大堤花月夜，长江春水流。
东风正上信，春夜特来游。','',''),('quantangshi-01428','相和歌辞 襄阳曲二首 一','崔國輔','quantangshi','','卷2','蕙草娇红蕚，时光舞碧鸡。
城中美年少，相见白铜鞮。','',''),('quantangshi-01429','相和歌辞 襄阳曲二首 二','崔國輔','quantangshi','','卷2','少年襄阳地，来往襄阳城。
城中轻薄子，知妾解秦筝。','',''),('quantangshi-01430','相和歌辞 襄阳曲','施肩吾','quantangshi','','卷2','大堤女儿郎莫寻，三三五五结同心。
清晨对镜冶容色，意欲取郎千万金。','',''),('quantangshi-01431','相和歌辞 襄阳曲','李端','quantangshi','','卷2','襄阳堤路长，草碧杨柳黄。
谁家女儿临夜妆，红罗帐里有灯光。
雀钗翠羽动明璫，欲出不出脂粉香。
同居女伴正衣裳，中庭寒月白如霜。
贾生十八称才子，空得门前一断肠。','',''),('quantangshi-01432','相和歌辞 大堤曲','張柬之','quantangshi','','卷2','南国多佳人，莫若大堤女。
玉牀翠羽帐，宝袜莲花炬。
魂处自目成，色授开心许。
迢迢不可见，日暮空愁予。','',''),('quantangshi-01433','相和歌辞 大堤曲','楊巨源','quantangshi','','卷2','二八婵娟大堤女，开炉相对依江渚。
待客登楼向水看，邀郎卷幔临花语。
细雨蒙蒙湿芰荷，巴东商侣挂帆多。
自传芳酒涴红袖，谁调妍妆回翠蛾。
珍簟华灯夕阳后，当炉理瑟矜纤手。
月落星微五鼓声，春风摇荡窗前柳。
岁岁逢迎沙岸间，北人多识绿云鬟。
无端嫁与五陵少，离别烟波伤玉颜。','',''),('quantangshi-01434','相和歌辞 大堤曲','李白','quantangshi','','卷2','汉水临襄阳，花开大堤暖。
佳期大堤下，泪向南云满。
春风复无情，吹我梦魂散。
不见眼中人，天长音信断。','',''),('quantangshi-01435','相和歌辞 大堤曲','李賀','quantangshi','','卷2','妾家住横塘，红纱满桂香。
青云教绾头上髻，明月与作耳边璫。
莲风起，江畔春。
大堤上，留北人。
郎食鲤鱼尾，妾食猩猩唇。
莫指襄阳道，绿浦归帆少。
今日菖蒲花，明朝枫树老。','',''),('quantangshi-01436','相和歌辞 大堤行','孟浩然','quantangshi','','卷2','大堤行乐处，车马相驰突。
岁岁春草生，踏青二三月。
王孙挟珠弹，游女矜罗韈。
携手今莫同，江花为谁发。','',''),('quantangshi-01437','相和歌辞 三洲歌','溫庭筠','quantangshi','','卷2','团圆莫作波中月，洁白莫为枝上雪。
月随波动碎潾潾，雪似梅花不堪折。
李娘十六青丝发，画带双花为君结。
门前有路轻离别，惟恐归来旧香灭。','',''),('quantangshi-01438','相和歌辞 拔蒲歌','張祜','quantangshi','','卷2','拔蒲来，领郎镜湖边。
郎心在何处？莫趂新莲去。
拔得无心蒲，问郎看好无。','',''),('quantangshi-01439','相和歌辞 杨叛儿','李白','quantangshi','','卷2','君歌杨叛儿，妾劝新丰酒。
何许最关人，乌啼白门柳。
乌啼隐杨花，君醉留妾家。
博山炉中沈香火，双咽一气凌紫霞。','',''),('quantangshi-01440','相和歌辞 常林欢','溫庭筠','quantangshi','','卷2','宜城酒熟花覆桥，沙晴绿鸭鸣咬咬。
穠桑绕舍麦如尾，幽轧鸣机双燕巢。
马声特特荆门道，蛮水扬光色如草。
锦荐金炉梦正长，东家呃喔鸡鸣早。','',''),('quantangshi-01441','相和歌辞 江南弄','王勃','quantangshi','','卷2','江南弄，巫山连楚梦，行雨行云几相送。
瑶轩金谷上春时，玉童仙女无见期。
紫露香烟眇难托，清风明月遥相思。
遥相思，草徒绿，为听双飞凤凰曲。','',''),('quantangshi-01442','相和歌辞 江南弄','李賀','quantangshi','','卷2','江中绿雾起凉波，天上叠巘红嵯峨。
水风浦云生老竹，渚瞑蒲帆如一幅。
鲈鱼千头酒百斛，酒中倒卧南山绿。
吴歈越吟未终曲，江上团团帖寒玉。','',''),('quantangshi-01443','相和歌辞 采莲曲','崔國輔','quantangshi','','卷2','玉溆花红发，金塘水碧流。
相逢畏相失，并着采莲舟。','',''),('quantangshi-01444','相和歌辞 采莲曲','徐彥伯','quantangshi','','卷2','妾家越水边，摇艇入江烟。
既觅同心侣，复采同心莲。
折藕丝能脆，开花叶正圆。
春歌弄明月，归棹落花前。','',''),('quantangshi-01445','相和歌辞 采莲曲','李白','quantangshi','','卷2','若耶溪边采莲女，笑隔荷花共人语。
日照新妆水底明，风飘香袖空中举。
岸上谁家游冶郎，三三五五映垂杨。
紫骝嘶入落花去，见此踟蹰空断肠。','',''),('quantangshi-01446','相和歌辞 采莲曲','賀知章','quantangshi','','卷2','稽山罢雾郁嵯峨，镜水无风也自波。
莫言春度芳菲尽，别有中流采芰荷。','',''),('quantangshi-01447','相和歌辞 采莲曲三首 一','王昌齡','quantangshi','','卷2','吴姬越艳楚王妃，争弄莲舟水湿衣。
来时浦口花迎入，采罢江头月送归。','',''),('quantangshi-01448','相和歌辞 采莲曲三首 二','王昌齡','quantangshi','','卷2','荷叶罗裙一色裁，芙蓉向脸两边开。
乱入池中看不见，闻歌始觉有人来。','',''),('quantangshi-01449','相和歌辞 采莲曲三首 三','王昌齡','quantangshi','','卷2','越女作桂舟，还将桂为檝。
湖上水渺漫，清江初可涉。
摘取芙蓉花，莫摘芙蓉叶。','',''),('quantangshi-01450','相和歌辞 采莲曲二首 一','戎昱','quantangshi','','卷2','虽听采莲曲，讵识采莲心。
漾檝爱花远，回船愁浪深。
烟生极浦色，日落半江阴。
同侣怜波静，看妆堕玉簪。','',''),('quantangshi-01451','相和歌辞 采莲曲二首 二','戎昱','quantangshi','','卷2','涔阳女儿花满头，毵毵同泛木兰舟。
春风日暮南湖里，争唱菱歌不肯休。','',''),('quantangshi-01452','相和歌辞 采莲曲','儲光羲','quantangshi','','卷2','浅渚荷花繁，深塘菱叶疎。
独往方自得，耻邀淇上姝。
广江无术阡，大泽绝方隅。
浪中海童语，流下鲛人居。
春雁时隐舟，新荷复满湖。
采采乘日暮，不思贤与愚。','',''),('quantangshi-01453','相和歌辞 采莲曲二首 一','鮑溶','quantangshi','','卷2','弄舟朅来南塘水，荷叶映身摘莲子。
暑衣清净鸳鸯喜，作浪舞花惊不起。
殷勤护惜纤纤指，水菱初熟多新刺。','',''),('quantangshi-01454','相和歌辞 采莲曲二首 二','鮑溶','quantangshi','','卷2','采莲朅来水无风，莲潭如镜松如龙。
夏衫短袖交斜红，艳歌笑鬬新芙蓉，戏鱼住听莲花东。','',''),('quantangshi-01455','相和歌辞 采莲曲','張籍','quantangshi','','卷2','秋江岸边莲子多，采莲女儿凭船歌。
青房圆实齐戢戢，争前竞折荡漾波。
试牵绿茎下寻藕，断处丝多刺伤手。
白练束腰袖半卷，不插玉钗妆梳浅。
船中未满度前洲，借问谁家家住远。
归时共待暮潮上，自弄芙蓉还荡桨。','',''),('quantangshi-01456','相和歌辞 采莲曲','白居易','quantangshi','','卷2','菱叶萦波荷颭风，荷花深处小船通。
逢郎欲语低头笑，碧玉搔头落水中。','',''),('quantangshi-01457','相和歌辞 采莲曲','僧齊己','quantangshi','','卷2','越江女，越江莲。
齐菡萏，双婵娟。
嬉游向何处？
采摘且同船。
浩唱发容与，清波生漪涟。
时逢岛屿泊，几共鸳鸯眠。
襟袖既盈溢，馨香亦相传。
薄暮归去来，苎罗生碧烟。','',''),('quantangshi-01458','相和歌辞 采莲归','王勃','quantangshi','','卷2','采莲归，绿水芙蓉衣，秋风起浪凫雁飞。
桂棹兰桡下长浦，罗裙玉腕摇轻橹。
叶屿花潭极望平，江讴越吹相思苦。
相思苦，佳期不可驻。
塞外征夫犹未还，江南采莲今已暮。
今已暮，摘莲花，今渠那必尽倡家。
官道城南把桑叶，何如江上采莲花？
莲花复莲花，花叶何重叠。
叶翠本羞眉，花红彊如颊。
佳人不兹期，怅望别离时。
牵花怜共蒂，折藕爱连丝。
故情何处所？新物徒华滋。
不惜南津交佩解，还羞北海雁书迟。
采莲歌有节，采莲夜未歇。
正逢浩荡江上风，又值徘徊江上月。
莲浦夜相逢，吴姬越女何丰茸。
共问寒江千里外，征客关山更几重。','',''),('quantangshi-01459','相和歌辞 采莲女','閻朝隱','quantangshi','','卷2','采莲女，采莲舟，春日春江碧水流。
莲衣承玉钏，莲刺罥银钩。
薄暮敛容歌一曲，氛氲香气满汀洲。','',''),('quantangshi-01460','相和歌辞 湖边采莲妇','李白','quantangshi','','卷2','小姑织白紵，未解将人语。
大嫂采芙蓉，溪湖千万重。
长兄行不在，莫使外人逢。
愿学秋胡妇，真心比古松。','',''),('quantangshi-01461','相和歌辞 张静婉采莲曲','溫庭筠','quantangshi','','卷2','兰膏坠发红玉春，燕钗拖颈抛盘云。
城西杨柳向娇晚，门前沟水波潾潾。
麒麟公子朝天客，佩马璫璫铛度春陌。
掌中无力舞衣轻，翦断鲛绡破春碧。
抱月飘烟一尺腰，麝脐龙髓怜娇饶。
秋罗拂衣碎光动，露重花多香不销。
鸂鶒胶胶塘水满，绿萍如粟莲茎短。
一夜西风送雨来，粉痕零落愁红浅。
船头折藕丝暗牵，藕根莲子相留连。
郎心似月月易缺，十五十六清光圆。','',''),('quantangshi-01462','相和歌辞 凤笙曲','沈佺期','quantangshi','','卷2','忆昔王子晋，凤笙游云空。
挥手弄白日，安能恋青宫。
岂无婵娟子，结念罗帐中。
怜寿不贵色，身世两无穷。','',''),('quantangshi-01463','相和歌辞 凤吹笙曲','李白','quantangshi','','卷2','仙人十五爱吹笙，学得昆丘彩凤鸣。
始闻炼气餐金液，复道朝天赴玉京。
玉京迢迢几千里，凤笙去去无边已。
欲叹离声发绛唇，更嗟别调流纤指。
此时惜别讵堪闻，此地相看未忍分。
重吟真曲和清吹，却奏仙歌响绿云。
绿云紫气向函关，访道应寻缑氏山。
莫学吹笙王子晋，一遇浮丘断不还。','',''),('quantangshi-01464','相和歌辞 采菱曲','儲光羲','quantangshi','','卷2','浊水菱叶肥，清水菱叶鲜。
义不游浊水，志士多苦言。
潮没具区薮，潦深云梦田。
朝随北风去，暮逐南风还。
浦口多渔家，相与邀我船。
饭稻以终日，羹莼将永年。
方冬水物穷，又欲休山樊。
尽室相随从，所贵无忧患。','',''),('quantangshi-01465','相和歌辞 采菱行','劉禹錫','quantangshi','','卷2','白马湖平秋日光，紫菱如锦彩鸾翔。
荡舟游女满中央，采菱不顾马上郎。
争多逐胜纷相向，时转兰桡破轻浪。
长鬟弱袂动参差，钗影钏文浮荡漾。
笑语哇咬顾晚晖，蓼花绿岸扣舷归。
归来共到市桥步，野蔓系船萍满衣。
家家竹楼临广陌，下有连樯多估客。
携觞荐芰夜经过，醉踏大堤相应歌。
屈平祠下沅江水，月照寒波白烟起。
一曲南音此地闻，长安北望三千里。','',''),('quantangshi-01466','相和歌辞 阳春歌','李白','quantangshi','','卷2','长安白日照春空，绿杨结烟桑褭风。
披香殿前花始红，流芳发色绣户中。
绣户中，相经过。
飞燕皇后轻身舞，紫宫夫人绝世歌。','',''),('quantangshi-01467','相和歌辞 阳春曲','溫庭筠','quantangshi','','卷2','云母空窗晓烟薄，香昏龙气凝辉阁。
霏霏雾雨杏花天，帘外春威着罗幕。
曲栏伏槛金麒麟，沙苑芳郊连翠茵。
廐马何能啮芳草，路人不敢随流尘。','',''),('quantangshi-01468','相和歌辞 阳春曲','莊南傑','quantangshi','','卷2','紫锦红囊香满风，金鸾玉轼摇丁冬。
沙鸥白羽翦晴碧，野桃红艳烧春空。
芳草绵延锁平地，壠蝶双双舞幽翠。
凤叫龙吟白日长，落花声底仙娥醉。','',''),('quantangshi-01469','相和歌辞 阳春曲','僧貫休','quantangshi','','卷2','为口莫学阮嗣宗，不言是非非至公。
为手须似朱云辈，折槛英风至今在。
男儿结发事君亲，须斅前贤多慷慨。
历数雍熙房与杜，魏公姚公宋开府。','',''),('quantangshi-01470','相和歌辞 朝云引','郎大家宋氏','quantangshi','','卷2','巴西巫峡指巴东，朝云触石上朝空。
巫山巫峡高何已，行雨行云一时起。
一时起，三春暮。
若言来，且就阳台路。','',''),('quantangshi-01471','相和歌辞 上云乐','李白','quantangshi','','卷2','金天之西，白日所没。
康老胡雏，生彼月窟。
巉岩仪容，[戌]削风骨。
碧玉炅炅双目瞳，黄金拳拳两鬓红。
华盖垂下睫，嵩岳临上唇。
不覩谲诡貌，岂知造化神。
大道是文康之严父，元气乃文康之老亲。
抚顶弄盘古，推车转天轮。
云见日月初生时，铸冶火精与水银。
阳乌未出谷，顾兔半藏身。
女娲戏黄土，团作愚下人。
散在六合间，蒙蒙如沙尘。
生死了不尽，谁明此胡是仙真。
西海栽若木，东溟植扶桑。
别来几多时，枝叶万里长。
中国有七圣，半路颓鸿荒。
陛下应运起，龙飞入咸阳。
赤眉立盆子，白水兴汉光。
叱咤四海动，洪涛为簸扬。
举足蹋紫微，天关自开张。
老胡感至德，东来进仙倡。
五色师子，九苞凤凰。
是老胡鸡犬，鸣舞飞帝乡。
淋漓飒沓，进退成行。
能胡歌，献汉酒。
跪双膝，并两肘。
散花指天举素手，拜龙颜，献圣寿。
北斗戾，南山摧。
天子九九八十一[万]岁，长倾万岁杯。','',''),('quantangshi-01472','相和歌辞 上云乐','李賀','quantangshi','','卷2','飞香走红满天春，花龙盘盘上紫云。
三千宫女列金屋，五十弦瑟海上闻。
大江碎碎银沙路，嬴女机中断烟素。
断烟素，缝舞衣，八月一日君前舞。','',''),('quantangshi-01473','相和歌辞 凤台曲','王無競','quantangshi','','卷2','凤台何逶迤，嬴女管参差。
一旦彩云至，身去无还期。
遗曲此台上，世人多学吹。
一吹一落泪，至今怜玉姿。','',''),('quantangshi-01474','相和歌辞 凤台曲','李白','quantangshi','','卷2','尝闻秦帝女，传得凤凰声。
是日逢仙子，当时别有情。
人吹彩箫去，天借绿云迎。
曲在身不返，空余弄玉名。','',''),('quantangshi-01475','相和歌辞 凤凰曲','李白','quantangshi','','卷2','嬴女吹玉箫，吟弄天上春。
青鸾不独去，更有携手人。
影灭彩云断，遗声落西秦。','',''),('quantangshi-01476','相和歌辞 君道曲','李白','quantangshi','','卷2','大君若天覆，广运无不至。
轩后爪牙常先太山稽，如心之使臂。
小白鸿翼于夷吾，刘葛鱼水本无二。
土扶可成墙，积德为厚地。','',''),('quantangshi-01477','舞曲歌辞 吴俞儿舞歌 劒俞','陸龜蒙','quantangshi','','卷2','枝月喉，棹霜脊，北斗离离在寒碧。
龙魂清，虎尾白，秋照海心同一色。
纛影吒沙干影侧，神豪发直。
四睨之人股佶栗，欲定不定定不得。
舂牍残，儿且止。
狄胡有胆大如山，怖亦死。','',''),('quantangshi-01478','舞曲歌辞 吴俞儿舞歌 矛俞','陸龜蒙','quantangshi','','卷2','手盘风，头背分，电光战扇，欲刺敲心留半线。
缠肩绕脰，𧞔合眩旋。
卓植赴列，夺避中节。
前冲函礼穴，上指孛彗灭，与君一用来有截。','',''),('quantangshi-01479','舞曲歌辞 吴俞儿舞歌 弩俞','陸龜蒙','quantangshi','','卷2','牛来开弦，人为置镞。
捩机关，迸山谷。
鹿骇涩，隼击迟。
析毫中睫，洞腋分龟。
达坚垒，残雄师。
可以冠猛乐壮曲，抑扬蹈厉，有裂犀兕之气者非公与。','',''),('quantangshi-01480','舞曲歌辞 东海有勇妇','李白','quantangshi','','卷2','梁山感杞妻，恸哭为之倾。
金石忽暂开，都由激深情。
东海有勇妇，何慙苏子卿。
学劒越处子，超腾若流星。
捐躯报夫讐，万死不顾生。
白刃耀素雪，苍天感精诚。
十步两躩跃，三呼一交兵。
斩首掉国门，蹴踏五藏行。
割此伉俪愤，粲然大义明。
北海李使君，飞章奏天庭。
舍罪警风俗，流芳播沧瀛。
志在列女籍，竹帛已光荣。
淳于免诏狱，汉主为缇萦。
津妾一棹歌，脱父于严刑。
十子若不肖，不如一女英。
豫让斩空衣，有心竟无成。
要离杀庆忌，壮夫素所轻。
妻子亦何辜，焚之买虚名。
岂如东海妇，事立独扬名。','',''),('quantangshi-01481','舞曲歌辞 章和二年中','李賀','quantangshi','','卷2','云萧素，风拂拂，麦芒如彗黍和粟。
关中父老百领襦，关东吏人乏诟租。
健犊春耕土膏黑，菖蒲丛丛沿水脉。
殷勤为我下田鉏，百钱携赏丝桐客。
游春漫光坞花白，野林散香神降席。
拜神得寿献天子，七星贯断姮娥死。','',''),('quantangshi-01482','舞曲歌辞 公莫舞歌','李賀','quantangshi','','卷2','方花古础排九楹，刺豹淋血盛银甖。
华筵鼓吹无桐竹，长刀直立割鸣筝。
横楣麤锦生红纬，日炙锦嫣王未醉。
腰下三看宝玦光，项庄掉箾拦前起。
材官小臣公莫舞，座上真人赤龙子。
芒砀云瑞抱天回，咸阳王气清如水。
铁枢铁楗重束关，大旗五丈撞双环。
汉王今日须秦印，绝膑刳肠臣不论。','',''),('quantangshi-01483','舞曲歌辞 拂舞辞','李賀','quantangshi','','卷2','吴娥声绝天，空云闲裴回。
门外满车马，亦须生绿苔。
尊有乌程酒，劝君千万寿。
全胜汉武锦楼上，晓望晴寒饮花露。
东方日不破，天光无老时。
丹成作蛇乘白雾，千年重化玉井龟。
从蛇作龟二千载，吴堤绿草年年在。
背有八卦称神仙，邪鳞顽甲滑腥涎。','',''),('quantangshi-01484','舞曲歌辞 白鸠辞','李白','quantangshi','','卷2','铿鸣钟，考朗鼓。
歌白鸠，引拂舞。
白鸠之白谁与邻，霜衣雪襟诚可珍。
含哺七子能平均，食不咽，性安驯。
首农政，鸣阳春。
天子刻玉杖，镂形赐耆人。
白鹭亦白非纯真，外洁其色心匪仁。
阙五德，无司晨。
胡为啄我葭下之紫鳞，鹰鹯雕鹗，贪而好杀。
凤皇虽大圣，不愿以为臣。','',''),('quantangshi-01485','舞曲歌辞 独漉篇','李白','quantangshi','','卷2','独漉水中泥，水浊不见月。
不见月尚可，水深行人没。
越鸟从南来，胡鹰亦北度。
我欲弯弓向天射，惜其中道失归路。
落叶别树，飘零随风。
客无所托，悲与此同。
罗帷舒卷，似有人开。
明月直入，无心可猜。
雄劒挂壁，时时龙鸣。
不断犀象，绣涩苔生。
国耻未雪，何由成名。
神鹰梦泽，不顾鸱鸢。
为君一击，抟鹏九天。','',''),('quantangshi-01486','舞曲歌辞 独漉歌','王建','quantangshi','','卷2','独独漉漉，鼠食猫肉。
乌日中，鹤露宿，黄河水直人心曲。','',''),('quantangshi-01487','舞曲歌辞 白紵辞二首 一','崔國輔','quantangshi','','卷2','洛阳梨花落如霰，河阳桃叶生复齐。
坐恐玉楼春欲尽，红绵粉絮裛妆啼。','',''),('quantangshi-01488','舞曲歌辞 白紵辞二首 二','崔國輔','quantangshi','','卷2','董贤女弟在椒风，窈窕繁华贵后宫。
璧带金釭皆翡翠，一朝零落变成空。','',''),('quantangshi-01489','舞曲歌辞 白紵辞二首 一','楊衡','quantangshi','','卷2','玉缨翠佩杂轻罗，香汗微渍朱颜酡，为君起唱白紵歌。
清声褭云思繁多，凝笳哀琴时相和。
金壶半倾芳夜促，梁尘霏霏暗红烛。
令君安坐听终曲，坠叶飘花难再复。','',''),('quantangshi-01490','舞曲歌辞 白紵辞二首 二','楊衡','quantangshi','','卷2','蹑珠履，步琼筵。
轻身起舞红烛前，芳姿艳态妖且妍。
回眸转袖暗催弦，凉风萧萧流水急。
月华泛艳红莲湿，牵裙揽带翻成泣。','',''),('quantangshi-01491','舞曲歌辞 白紵辞三首 一','李白','quantangshi','','卷2','扬清歌，发皓齿，北方佳人东邻子。
且吟白紵停渌水，长袖拂面为君起。
寒云夜卷霜海空，胡风吹天飘塞鸿。
玉颜满堂乐未终，馆娃日落歌吹蒙。','',''),('quantangshi-01492','舞曲歌辞 白紵辞三首 二','李白','quantangshi','','卷2','月寒江清夜沈沈，美人一笑千黄金。
垂罗舞縠扬哀音，郢中白雪且莫吟，子夜吴歌动君心。
动君心，冀君赏。
愿作天池双鸯鸯，一朝飞去青云上。','',''),('quantangshi-01493','舞曲歌辞 白紵辞三首 三','李白','quantangshi','','卷2','吴刀翦彩缝舞衣，明妆丽服夺春辉。
扬眉转袖若雪飞，倾城独立世所稀。
激楚结风醉忘归，高堂月落烛已微，玉钗挂缨君莫违。','',''),('quantangshi-01494','舞曲歌辞 白紵歌二首 一','王建','quantangshi','','卷2','天河漫漫北斗粲，宫中乌啼知夜半。
新缝白紵舞衣成，来迟邀得吴王迎。
低鬟转面掩双袖，玉钗浮动秋风生。
酒多夜长夜未晓，月明灯光两相照，后庭歌声更窈窕。','',''),('quantangshi-01495','舞曲歌辞 白紵歌二首 二','王建','quantangshi','','卷2','馆娃宫中春日暮，荔枝木瓜花满树。
城头乌栖休击鼓，青娥弹瑟白紵舞。
夜天燑燑不见星，宫中火照西江明。
美人醉起无次第，堕钗遗佩满中庭。
此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。','',''),('quantangshi-01496','舞曲歌辞 白紵歌','張籍','quantangshi','','卷2','皎皎白紵白且鲜，将作春衫称少年。
裁缝长短不能定，自持刀尺向姑前。
复恐兰膏污纤指，常遣傍人收堕珥。
衣裳着时寒食下，还把玉鞭鞭白马。','',''),('quantangshi-01497','舞曲歌辞 白紵歌','柳宗元','quantangshi','','卷2','翠帷双卷出倾城，龙劒破匣霜月明。
朱唇掩抑悄无声，金簧玉磬宫中生。','',''),('quantangshi-01498','舞曲歌辞 冬白紵歌','稹','quantangshi','','卷2','吴宫夜长宫漏款，帘幕四垂灯焰暖。
西施自舞王自管，雪紵翻翻鹤翎散。
促节牵繁舞腰嬾，舞腰嬾，王罢饮。
盖覆西施凤花锦，身作匡牀臂为枕。
朝佩摐摐王晏寝，酒醒阍报门无事。
子胥死后言为讳，近王之臣谕王意。
共笑越王穷惴惴，夜夜抱冰寒不睡。','',''),('quantangshi-01499','舞曲歌辞 霓裳辞十首 一','王建','quantangshi','','卷2','弟子部中留一色，听风听水作霓裳。
散声未足重来授，直到牀前见上皇。','',''),('quantangshi-01500','舞曲歌辞 霓裳辞十首 二','王建','quantangshi','','卷2','中管五弦初半曲，遥教合上隔帘听。
一声声向天头落，效得仙人夜唱经。','',''),('quantangshi-01501','舞曲歌辞 霓裳辞十首 三','王建','quantangshi','','卷2','自直梨园得出稀，更番上曲不教归。
一时跪拜霓裳彻，立地阶前赐紫衣。','',''),('quantangshi-01502','舞曲歌辞 霓裳辞十首 四','王建','quantangshi','','卷2','旋翻新谱声初足，除却梨园未教人。
宣与书家分手写，中官走马赐功臣。','',''),('quantangshi-01503','舞曲歌辞 霓裳辞十首 五','王建','quantangshi','','卷2','伴教霓裳有贵妃，从初直到曲成时。
日长耳里闻声熟，拍数分毫错总知。','',''),('quantangshi-01504','舞曲歌辞 霓裳辞十首 六','王建','quantangshi','','卷2','弦索摐摐隔彩云，五更初发一山闻。
武皇自送西王母，新换霓裳月色裙。','',''),('quantangshi-01505','舞曲歌辞 霓裳辞十首 七','王建','quantangshi','','卷2','敕赐宫人澡浴回，遥看美女院门开。
一山星月霓裳动，好字先从殿里来。','',''),('quantangshi-01506','舞曲歌辞 霓裳辞十首 八','王建','quantangshi','','卷2','传呼法部按霓裳，新得承恩别作行。
应是贵妃楼上看，内人舁下彩罗箱。','',''),('quantangshi-01507','舞曲歌辞 霓裳辞十首 九','王建','quantangshi','','卷2','朝元阁上山风起，夜听霓裳玉露寒。
宫女月中更替立，黄金梯滑竝行难。','',''),('quantangshi-01508','舞曲歌辞 霓裳辞十首 十','王建','quantangshi','','卷2','知向华清年月满，山头山底种长生。
去时留下霓裳曲，总是离宫别馆声。','',''),('quantangshi-01509','舞曲歌辞 柘枝词','失撰人名','quantangshi','','卷2','将军奉命即须行，塞外领彊兵。
闻道烽烟动，腰间宝劒匣中鸣。','',''),('quantangshi-01510','舞曲歌辞 柘枝词 一','薛能','quantangshi','','卷2','同营三十万，震鼓伐西羌。
战血黏秋草，征尘搅夕阳。
归来人不识，帝里独戎装。','',''),('quantangshi-01511','舞曲歌辞 柘枝词 二','薛能','quantangshi','','卷2','悬军征拓羯，内地隔萧关。
日色昆仑上，风声朔漠间。
何当千万骑，飒飒贰师还。','',''),('quantangshi-01512','舞曲歌辞 柘枝词 三','薛能','quantangshi','','卷2','意气成功日，春风起絮天。
楼台新邸第，歌舞小婵娟。
急破催摇曳，罗衫半脱肩。','',''),('quantangshi-01513','舞曲歌辞 屈柘词','溫庭筠','quantangshi','','卷2','杨柳萦桥绿，玫瑰拂地红。
绣衫金騕褭，花髻玉珑璁。
宿雨香潜润，春流水暗通。
画楼初梦断，晴日照湘风。','',''),('quantangshi-01514','琴曲歌辞 白雪歌','僧貫休','quantangshi','','卷2','列鼎佩金章，泪眼看风枝。
却思食藜藿，身作屠沽儿。
负米无远近，所希升斗归。
为人无贵贱，莫学鸡狗肥。
斯言如不忘，别更无光辉。
斯言如或忘，即安用人为。','',''),('quantangshi-01515','琴曲歌辞 湘妃','劉長卿','quantangshi','','卷2','帝子不可见，秋风来暮思。
婵娟湘江月，千载空蛾眉。','',''),('quantangshi-01516','琴曲歌辞 湘妃','李賀','quantangshi','','卷2','筠竹千年老不死，长伴秦娥盖湘水。
蛮娘吟弄满寒空，九山静绿泪花红。
离鸾别凤烟梧中，巫云蜀雨遥相通。
幽愁秋气上青枫，凉夜波间吟古龙。','',''),('quantangshi-01517','琴曲歌辞 湘妃怨','孟郊','quantangshi','','卷2','南巡竟不返，帝子怨逾积。
万里丧蛾眉，潇湘水空碧。
冥冥荒山下，古庙收贞魄。
乔木深青春，清光满瑶席。
搴芳徒有荐，灵意殊脉脉。
玉佩不可亲，裴回烟波夕。','',''),('quantangshi-01518','琴曲歌辞 湘妃怨','陳羽','quantangshi','','卷2','二妃怨处云沈沈，二妃哭处湘水深。
商人酒滴庙前草，萧飒风生斑竹林。','',''),('quantangshi-01519','琴曲歌辞 湘妃列女操','鮑溶','quantangshi','','卷2','有虞夫人哭虞后，淑女何事又伤离。
竹上泪迹生不尽，寄哀云和五十丝。
云和经奏钧天曲，乍听宝琴遥嗣续。
三湘测测流急绿，秋夜露寒蜀帝飞。
枫林月斜楚臣宿，更疑川宫日黄昏。
暗携女手殷勤言，环佩玲珑有无间。
终疑既远双悄悄，苍梧旧云岂难召。
老猨心寒不可啸，目眄眄兮意蹉跎。','',''),('quantangshi-01520','琴曲歌辞 湘夫人','鄒紹先','quantangshi','','卷2','枫叶下秋渚，二妃愁渡湘。
疑山空杳蔼，何处望君王？
日落水云里，油油心自伤。','',''),('quantangshi-01521','琴曲歌辞 湘夫人','李頎','quantangshi','','卷2','九嶷日已暮，三湘云复愁。
窅蔼罗袂色，潺湲江水流。
佳期来北渚，捐玦在芳洲。','',''),('quantangshi-01522','琴曲歌辞 湘夫人','郎士元','quantangshi','','卷2','娥眉对湘水，遥哭苍梧间。
万乘既已殁，孤舟谁忍还。
至今楚山上，犹有泪痕斑。
南有涔阳路，渺渺多新愁。
昔神降回时，风波江上秋。
彩云忽无处，碧水空安流。','',''),('quantangshi-01523','琴曲歌辞 霹雳引','沈佺期','quantangshi','','卷2','岁七月，火伏而金生。
客有鼓瑟于门者，奏霹雳之商声。
始戛羽以騞砉，终扣宫而砰駖。
电耀耀兮龙跃，雷阗阗兮雨冥。
气呜唅以会雅，态歘翕以横生。
有如驱千旗，制五兵，截荒虺，斮长鲸。
孰与广陵比，意别鹤俦精而已。
俾我雄子魄动，毅夫发立，怀恩不浅，武义双辑，视胡若芥，翦羯如拾。
岂徒慨慷中筵，备羣娱之翕习哉。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01524','琴曲歌辞 拘幽操','韓愈','quantangshi','','卷2','目揜揜兮其凝其盲，耳肃肃兮听不闻声。
朝不日出兮夜不见月与星，有知无知兮为死为生。
呜呼！臣罪当诛兮天王圣明。','',''),('quantangshi-01525','琴曲歌辞 越裳操','韓愈','quantangshi','','卷2','雨之施，物以孳，我何意于彼为。
自周之先，其艰其勤。
以有疆宇，私我后人。
我祖在上，四方在下。
厥临孔威，敢戏以侮。
孰荒于门，孰治于田。
四海既均，越裳是臣。','',''),('quantangshi-01526','琴曲歌辞','韓愈','quantangshi','','卷2','我家于豳，自我先公。
伊我承绪，敢有不同。
今狄之人，将土我疆。
民为我战，谁使死伤。
彼岐有岨，我往独处。
人莫余追，无思我悲。','',''),('quantangshi-01527','琴曲歌辞 履霜操','韓愈','quantangshi','','卷2','父兮儿寒，母兮儿饥。
儿罪当笞，逐儿何为？
儿在中野，以宿以处。
四无人声，谁与儿语。
儿寒何衣，儿饥何食。
儿行于野，履霜以足。
母生众儿，有母怜之。
独无母怜，儿宁不悲。','',''),('quantangshi-01528','琴曲歌辞 雉朝飞操','李白','quantangshi','','卷2','麦陇青青三月时，白雉朝飞挟两雌。
锦衣绮翼何离褷，犊牧采薪感之悲。
春天和，白日暖，啄食饮泉勇气满。
争雄鬬死绣颈断，雉子班奏急管弦，心倾美酒尽玉椀。
枯杨枯杨尔生荑，我独七十而孤栖。
弹弦写恨意不尽，瞑目归黄泥。','',''),('quantangshi-01529','琴曲歌辞 雉朝飞操','韓愈','quantangshi','','卷2','雉之飞，于朝日。
羣雌孤雄，意气横出。
当东而西，当啄而飞。
随飞随啄，羣雌粥粥。
嗟我虽人，曾不如彼雉鸡。
生身七十年，无一妾与妃。','',''),('quantangshi-01530','琴曲歌辞 雉朝飞操','張祜','quantangshi','','卷2','朝阳陇东泛暖景，双啄双飞双顾影。
朱冠锦襦聊日整，漠漠雾中如衣褧。
伤心卢女弦，七十老翁长独眠。
雄飞在草雌在田，衷肠结愤气呵天。
圣人在上心不偏，翁得女妻甚可怜。','',''),('quantangshi-01531','琴曲歌辞 思归引','張祜','quantangshi','','卷2','重重作闺清旦鐍，两耳深声长不彻。
深宫坐愁百年身，一片玉中生愤血。
焦桐罢弹丝自绝，漠漠暗魂愁夜月。
故乡不归谁共穴，石上作蒲蒲九节。','',''),('quantangshi-01532','琴曲歌辞 猗兰操','韓愈','quantangshi','','卷2','兰之猗猗，扬扬其香。
不采而佩，于兰何伤。
今天之旋，其曷为然。
我行四方，以日以年。
雪霜贸贸，荠麦之茂。
子如不伤，我不尔觏。
荠麦之茂，荠麦之有。
君子之伤，君子之守。','',''),('quantangshi-01533','琴曲歌辞 幽兰','崔塗','quantangshi','','卷2','幽植众能知，贞芳只暗持。
自无君子佩，未是国香衰。
白露霑长早，青春每到迟。','',''),('quantangshi-01534','琴曲歌辞 将归操','韓愈','quantangshi','','卷2','秋之水兮其色幽幽，我将济兮不得其由。
涉其浅兮石啮我足，乘其深兮龙入我舟，我济而悔兮将安归尤？
归乎归乎，无与石鬬兮无应龙求。','',''),('quantangshi-01535','琴曲歌辞 龟山操','韓愈','quantangshi','','卷2','龟之气兮不能云雨，龟之枿兮不中梁柱，龟之大兮祗以奄鲁。
知将隳兮哀莫余伍，周公有鬼兮嗟余归辅。','',''),('quantangshi-01536','琴曲歌辞 残形操','韓愈','quantangshi','','卷2','有兽维狸兮我梦得之，其身孔明兮而头不知。
吉凶何为兮觉坐而思，巫咸上天兮识者其谁。','',''),('quantangshi-01537','琴曲歌辞 双燕离','李白','quantangshi','','卷2','双燕复双燕，双飞令人羡。
玉楼珠阁不独栖，金窗绣户长相见。
柏梁失火去，因入吴王宫。
吴宫又焚荡，雏尽巢亦空。
憔悴一身在，孀雌忆故雄。
双飞难再得，伤我寸心中。','',''),('quantangshi-01538','琴曲歌辞 列女操','孟郊','quantangshi','','卷2','梧桐相待老，鸳鸯会双死。
贞妇贵徇夫，舍生亦如此。
波澜誓不起，妾心井中水。','',''),('quantangshi-01539','琴曲歌辞 别鹄操','韓愈','quantangshi','','卷2','雄鹄衔枝来，雌鹄啄泥归。
巢成不生子，大义当乖离。
江汉水之大，鹄身鸟之微。
更无相逢日，安可相随飞。','',''),('quantangshi-01540','琴曲歌辞 别鹤','楊巨源','quantangshi','','卷2','海鹤一为别，高程方杳然。
影摇江海路，思结潇湘天。
皎然仰白日，真姿栖紫烟。
含情九霄际，顾侣五云前。
遐心属清都，凄响激朱弦。
超摇间云雨，迢遰各山川。
东南信多水，会合当有年。','',''),('quantangshi-01541','琴曲歌辞 别鹤','王建','quantangshi','','卷2','主人一去池水绝，池鹤散飞不相别。
青天漫漫碧海重，知向何山风雪中？
万里虽然音影在，向心终是死生同。
池边巢破松树死，树头年年乌生子。','',''),('quantangshi-01542','琴曲歌辞 别鹤','張籍','quantangshi','','卷2','双鹤出云溪，分飞各自迷。
空巢在松杪，折羽落江泥。
寻水终不饮，逢林亦未栖。
别离应易老，万里两凄凄。','',''),('quantangshi-01543','琴曲歌辞 别鹤','杜牧','quantangshi','','卷2','分飞共所从，六翮势摧风。
声断碧云外，影孤明月中。
青田归路远，月桂旧巢空。
矫翼知何处，天涯不可穷。','',''),('quantangshi-01544','琴曲歌辞 走马引','李賀','quantangshi','','卷2','我有辞乡劒，玉锋堪截云。
襄阳走马客，意气自生春。
朝嫌劒光静，暮嫌劒花冷。
能持劒向人，不解持照身。','',''),('quantangshi-01545','琴曲歌辞 昭君怨','白居易','quantangshi','','卷2','明妃风貌最娉婷，合在椒房应四星。
只得当年备宫掖，何曾专夜奉帏屏。
见疎从道迷图画，知屈那教配虏廷。
自是君恩薄如纸，不须一向恨丹青。','',''),('quantangshi-01546','琴曲歌辞 昭君怨 一','張祜','quantangshi','','卷2','万里边城远，千山行路难。
举头唯见日，何处是长安。','',''),('quantangshi-01547','琴曲歌辞 昭君怨 二','張祜','quantangshi','','卷2','汉庭无大议，戎虏几先和。
莫羡倾城色，昭君恨最多。','',''),('quantangshi-01548','琴曲歌辞 昭君怨','梁氏瓊','quantangshi','','卷2','自古无和亲，贻灾到妾身。
胡风嘶去马，汉月吊行轮。
衣薄狼山雪，妆成虏塞春。
回看父母国，生死毕胡尘。','',''),('quantangshi-01549','琴曲歌辞 明妃怨','楊淩','quantangshi','','卷2','汉国明妃去不还，马駞弦管向阴山。
匣中纵有菱花镜，羞对单于照旧颜。','',''),('quantangshi-01550','琴曲歌辞 蔡氏五弄 游春曲二首 一','王涯','quantangshi','','卷2','万树江边杏，新开一夜风。
满园深浅色，照在绿波中。','',''),('quantangshi-01551','琴曲歌辞 蔡氏五弄 游春曲二首 二','王涯','quantangshi','','卷2','上苑何穷树，花开次第新。
香车与丝骑，风静亦生尘。','',''),('quantangshi-01552','琴曲歌辞 游春辞二首 一','王涯','quantangshi','','卷2','曲江丝柳变烟条，寒骨冰随暖气销。
才见春光生绮陌，已闻清乐动云韶。','',''),('quantangshi-01553','琴曲歌辞 游春辞二首 二','王涯','quantangshi','','卷2','经过柳陌与桃蹊，寻逐风光着处迷。
鸟度时时冲絮起，花繁衮衮压枝低。','',''),('quantangshi-01554','琴曲歌辞 游春辞三首 一','令狐楚','quantangshi','','卷2','晚游临碧殿，日上望春亭。
芳树罗仙仗，晴山展翠屏。','',''),('quantangshi-01555','琴曲歌辞 游春辞三首 二','令狐楚','quantangshi','','卷2','一夜好风吹，新花一万枝。
风前调玉管，花下簇金羁。','',''),('quantangshi-01556','琴曲歌辞 游春辞三首 三','令狐楚','quantangshi','','卷2','阊阖春风起，蓬莱雪水消。
相将折杨柳，争取最长条。','',''),('quantangshi-01557','琴曲歌辞 渌水曲','李白','quantangshi','','卷2','渌水明秋月，南湖采白苹。
荷花娇欲语，愁杀荡舟人。','',''),('quantangshi-01558','琴曲歌辞 渌水辞','李賀','quantangshi','','卷2','今宵好风月，阿侯在何处？
为有倾城色，翻成足愁苦。
东湖采莲叶，南湖拔蒲根。
未持寄小姑，且持感愁魂。','',''),('quantangshi-01559','琴曲歌辞 幽居弄','顧況','quantangshi','','卷2','苔衣生，花露滴，月入西林荡东壁。
扣商占角两三声，洞户溪窗一冥寂。
独去沧洲无四邻，身婴世网此何身？
关情命曲寄惆怅，久别江南山里人。','',''),('quantangshi-01560','琴曲歌辞 秋思二首 一','李白','quantangshi','','卷2','春阳如昨日，碧树鸣黄鹂。
芜然蕙草暮，飒尔凉风吹。
天秋木叶下，月冷莎鸡悲。
坐愁羣芳歇，白露凋华滋。','',''),('quantangshi-01561','琴曲歌辞 秋思二首 二','李白','quantangshi','','卷2','阏氏黄叶落，妾望白登台。
月出碧云断，蝉声秋色来。
胡兵沙塞合，汉使玉关回。
征客无归日，空悲蕙草摧。','',''),('quantangshi-01562','琴曲歌辞 秋思二首 一','鮑溶','quantangshi','','卷2','胡风吹雁翼，远别无人乡。
君近雁来处，几回断君肠。
昔奉千日书，抚心怨星霜。
无书又千日，世路重茫茫。
燕国有佳丽，蛾眉富春光。
自然君归晚，花落君空堂。
君其若不然，岁晚双鸳鸯。
顾兔蚀残月，幽光不如星。
女儿晚事夫，颜色同秋萤。
秋日边马思，武夫不遑宁。
燕歌易水怨，劒舞蛟龙腥。
风折连枝树，水翻无蒂萍。
立身多户门，何必燕山铭。
生世不如鸟，双双比翼翎。','',''),('quantangshi-01563','琴曲歌辞 秋思二首 二','鮑溶','quantangshi','','卷2','季秋天地闲，万物生意足。
我忧长于生，安得及草木。
试从古人愿，致酒歌秉烛。
燕赵皆世人，讵能长似玉。
俯怜老期近，仰视日车速。
萧飒御风君，魂梦愿相逐。
百年夜销半，端为垂缨束。','',''),('quantangshi-01564','琴曲歌辞 秋思','司空曙','quantangshi','','卷2','静与嬾相偶，年将衰共催。
前途欢不集，往事恨空来。
昼景委红叶，月华铺绿苔。
沈思更何有？结坐玉琴哀。','',''),('quantangshi-01565','琴曲歌辞 秋思','司空圖','quantangshi','','卷2','身病时亦危，逢秋多恸哭。
风波一摇荡，天地几翻覆。
孤萤出荒池，落叶穿破屋。','',''),('quantangshi-01566','琴曲歌辞 秋思二首 一','王涯','quantangshi','','卷2','网轩凉吹动轻衣，夜听更长玉漏稀。
月渡天河光转湿，鹊惊秋树叶频飞。','',''),('quantangshi-01567','琴曲歌辞 秋思二首 二','王涯','quantangshi','','卷2','宫连太液见苍波，暑气微清秋意多。
一夜轻风苹末起，露珠翻尽满池荷。','',''),('quantangshi-01568','琴曲歌辞 胡笳十八拍 第一拍','劉商','quantangshi','','卷2','汉室将衰兮四夷不宾，动干戈兮征战频。
哀哀父母生育我，见离乱兮当此辰。
纱窗对镜未经事，将谓珠帘能蔽身。
一朝虏骑入中国，苍黄处处逢胡人。
忽将薄命委锋镝，可惜红颜随虏尘。','',''),('quantangshi-01569','琴曲歌辞 胡笳十八拍 第二拍','劉商','quantangshi','','卷2','马上将余向绝域，厌生求死死不得。
戎羯腥膻岂是人，豺狼喜怒难姑息。
行尽天山足霜霰，风土萧条近胡国。
万里重阴鸟不飞，寒沙莽莽无南北。','',''),('quantangshi-01570','琴曲歌辞 胡笳十八拍 第三拍','劉商','quantangshi','','卷2','如羇囚兮在缧绁，忧虑万端无处说。
使余力兮翦余发，食余肉兮饮余血。
诚知杀身愿如此，以余为妻不如死。
早被蛾眉累此身，空悲弱质柔如水。','',''),('quantangshi-01571','琴曲歌辞 胡笳十八拍 第四拍','劉商','quantangshi','','卷2','山川路长谁记得，何处天涯是乡国？
自从惊怖少精神，不觉风霜损颜色。
夜中归梦来又去，朦胧岂解传消息。
漫漫胡天叫不闻，明明汉月应相识。','',''),('quantangshi-01572','琴曲歌辞 胡笳十八拍 第五拍','劉商','quantangshi','','卷2','水头宿兮草头坐，风吹汉地衣裳破。
羊脂沐发长不梳，羔子皮裘领仍左。
狐襟貉袖腥复膻，昼披行兮夜披卧。
毡帐时移无定居，日月长兮不可过。','',''),('quantangshi-01573','琴曲歌辞 胡笳十八拍 第六拍','劉商','quantangshi','','卷2','怪得春光不来久，胡中风土无花柳。
天翻地覆谁得知，如今正南看北斗。
姓名音信两不通，终日经年常闭口。
是非取与在指撝，言语传情不如手。','',''),('quantangshi-01574','琴曲歌辞 胡笳十八拍 第七拍','劉商','quantangshi','','卷2','男儿妇人带弓箭，塞马蕃羊卧霜霰。
寸步东西岂自由，偷生乞死非情愿。
龟兹筚篥愁中听，碎叶琵琶夜深怨。
竟夕无云月上天，故乡应得重相见。','',''),('quantangshi-01575','琴曲歌辞 胡笳十八拍 第八拍','劉商','quantangshi','','卷2','忆昔私家恣娇小，远取珍禽学驯扰。
如今沦弃念故乡，悔不当初放林表。
朔风萧萧寒日暮，星河寥落胡天晓。
旦夕思归不得归，愁心想似笼中鸟。','',''),('quantangshi-01576','琴曲歌辞 胡笳十八拍 第九拍','劉商','quantangshi','','卷2','当日苏武单于问，道是宾鸿解传信。
学他刺血写得书，书上千重万重恨。
髯胡少年能走马，弯弓射飞无远近。
遂令边雁转怕人，绝域何由达方寸。','',''),('quantangshi-01577','琴曲歌辞 胡笳十八拍 第十拍','劉商','quantangshi','','卷2','恨凌辱兮恶腥膻，憎胡地兮怨胡天。
生得胡儿欲弃捐，及生母子情宛然。
貌殊语异憎还爱，心中不觉常相牵。
朝朝暮暮在眼前，腹生手养宁不怜。','',''),('quantangshi-01578','琴曲歌辞 胡笳十八拍 第十一拍','劉商','quantangshi','','卷2','日来月往相推迁，迢迢星岁欲周天。
无冬无夏卧霜霰，水冻草枯为一年。
汉家甲子有正朔，绝域三光空自悬。
几回鸿雁来又去，肠断蟾蜍亏复圆。','',''),('quantangshi-01579','琴曲歌辞 胡笳十八拍 第十二拍','劉商','quantangshi','','卷2','破瓶落井空永沈，故乡望断无归心。
宁知远使问姓名，汉语泠泠传好音。
梦魂几度到乡国，觉后翻成哀怨深。
如今果是梦中事，喜过悲来情不任。','',''),('quantangshi-01580','琴曲歌辞 胡笳十八拍 第十三拍','劉商','quantangshi','','卷2','童稚牵衣双在侧，将来不可留又忆。
还乡惜别两难分，宁弃胡儿归旧国。
山川万里复边戍，背面无由得消息。
泪痕满面对残阳，终日依依向南北。','',''),('quantangshi-01581','琴曲歌辞 胡笳十八拍 第十四拍','劉商','quantangshi','','卷2','莫以胡儿可羞耻，恩情亦各言其子。
手中十指有长短，截之痛惜皆相似。
还乡岂不见亲族，念此飘零隔生死。
南风万里吹我心，心亦随风渡辽水。','',''),('quantangshi-01582','琴曲歌辞 胡笳十八拍 第十五拍','劉商','quantangshi','','卷2','叹息襟怀无定分，当时怨来归又恨。
不知愁怨意若何？似有锋铓扰方寸。
悲欢竝行情未快，心意相尤自相问。
不缘生得天属亲，岂向仇讐结恩信。','',''),('quantangshi-01583','琴曲歌辞 胡笳十八拍 第十六拍','劉商','quantangshi','','卷2','去时只觉天苍苍，归日始知胡地长。
重阴白日落何处？秋雁所向应南方。
平沙四顾自迷惑，远近悠悠随雁行。
征途未尽马蹄尽，不见行人边草黄。','',''),('quantangshi-01584','琴曲歌辞 胡笳十八拍 第十七拍','劉商','quantangshi','','卷2','行尽胡天千万里，惟见黄沙白云起。
马饥跑雪衔草根，人渴敲冰饮流水。
燕山仿髴辨烽戍，鼙鼓如闻汉家垒。
努力前程是帝乡，生前免向胡中死。','',''),('quantangshi-01585','琴曲歌辞 胡笳十八拍 第十八拍','劉商','quantangshi','','卷2','归来故乡见亲族，田园半芜春草绿。
明烛重然煨烬灰，寒泉更洗沈泥玉。
载持巾栉礼仪好，一弄丝桐生死足。
出入关山十二年，哀情尽在胡笳曲。','',''),('quantangshi-01586','琴曲歌辞 飞龙引二首 一','李白','quantangshi','','卷2','黄帝铸鼎于荆山，炼丹砂。
丹砂成黄金，骑龙飞上太清家。
云愁海思令人嗟，宫中彩女颜如花。
飘然挥手凌紫霞，从风纵体登銮车。
登銮车，侍轩辕。
遨游青天中，其乐不可言。','',''),('quantangshi-01587','琴曲歌辞 飞龙引二首 二','李白','quantangshi','','卷2','鼎湖流水清且闲，轩辕去时有弓劒。
古人传道留其间，后宫婵娟多花颜。
乘鸾飞烟亦不还，骑龙攀天造天关。
造天关，闻天语，长云河车载玉女。
载玉女，过紫皇，紫皇乃赐白兔所捣之药，后天而老凋三光。
下视瑶池见王母，蛾眉萧飒如秋霜。','',''),('quantangshi-01588','琴曲歌辞 乌夜啼引','張籍','quantangshi','','卷2','秦乌啼哑哑，夜啼长安吏人家。
吏人得罪囚在狱，倾家卖产将自赎。
少妇起听夜啼乌，知是官家有赦书。
下牀心喜不重寐，未明上堂贺舅姑。
少妇语啼乌，汝啼慎勿虚。
借汝庭树作高巢，年年不令伤尔雏。','',''),('quantangshi-01589','琴曲歌辞 宛转歌 一','郎大家宋氏','quantangshi','','卷2','风已清，月朗琴复鸣。
掩抑非千态，殷勤是一声。
歌宛转，宛转和且长。
愿为双鸿鹄，比翼共翱翔。','',''),('quantangshi-01590','琴曲歌辞 宛转歌 二','郎大家宋氏','quantangshi','','卷2','日已暮，长檐鸟应度。
此时望君君不来，此时思君君不顾。
歌宛转，宛转那能异栖宿。
愿为形与影，出入恒相逐。','',''),('quantangshi-01591','琴曲歌辞 宛转歌二首 一','劉方平','quantangshi','','卷2','星参差，月二八，灯五枝。
黄鹤瑶琴将别去，芙蓉羽帐惜空垂。
歌宛转，宛转恨无穷。
愿为波与浪，俱起碧流中。','',''),('quantangshi-01592','琴曲歌辞 宛转歌二首 二','劉方平','quantangshi','','卷2','晓将近，黄姑织女银河尽。
九华锦衾无复情，千金宝镜谁能引。
歌宛转，宛转伤别离。
愿作杨与柳，同向玉窗垂。','',''),('quantangshi-01593','琴曲歌辞 宛转行','張籍','quantangshi','','卷2','华屋重翠幄，绮席雕象牀。
远漏微更疎，薄衾中夜凉。
炉氲暗裴回，寒灯背斜光。
妍姿结宵态，寝臂幽梦长。
宛转复宛转，忆忆更未央。','',''),('quantangshi-01594','琴曲歌辞 王敬伯歌','李端','quantangshi','','卷2','妾本舟中客，闻君江上琴。
君初感妾叹，妾亦感君心。
遂出合欢被，同为交颈禽。
传杯惟畏浅，接膝犹嫌远。
侍婢奏箜篌，女郎歌宛转。
宛转怨如何，中庭霜渐多。
霜多叶可惜，昨日非今夕。
徒结万里欢，终成一宵客。
王敬伯，渌水青山从此隔。','',''),('quantangshi-01595','琴曲歌辞 三峡流泉歌','李季蘭','quantangshi','','卷2','妾家本住巫山云，巫山流水常自闻。
玉琴弹出转寥敻，直似当时梦中听。
三峡流泉几千里，一时流入深闺里。
巨石奔崖指下生，飞波走浪弦中起。
初疑喷涌含雷风，又似呜咽流不通。
回湍曲濑势将尽，时复滴沥平沙中。
忆昔阮公为此曲，能使仲容听不足。
一弹既罢复一弹，愿似流泉镇相续。','',''),('quantangshi-01596','琴曲歌辞 风入松歌','僧皎然','quantangshi','','卷2','西岭松声落日秋，千枝万叶风飕飗。
美人援琴弄成曲，写得松间声断续。
声断续，清我魂，流波坏陵安足论。
美人夜坐月明里，含少商兮照清征。
风何凄兮飘飉，搅寒松兮又夜起。
夜未央，曲何长，金徽更促声泱泱。
何人此时不得意，意苦弦悲闻客堂。','',''),('quantangshi-01597','琴曲歌辞 秋风引','劉禹錫','quantangshi','','卷2','何处秋风至？萧萧送雁羣。
朝来入庭树，孤客最先闻。','',''),('quantangshi-01598','琴曲歌辞 明月引','盧照鄰','quantangshi','','卷2','洞庭波起兮鸿雁翔，风瑟瑟兮野苍苍。
浮云卷霭，明月流光。
荆南兮赵北，碣石兮潇湘。
澄清规于万里，照离思于千行。
横桂枝于西第，绕菱花于北堂。
高楼思妇，飞盖君王。
文姬绝域，侍子他乡。
见胡鞍之似练，知汉劒之如霜。
试登高而极目，莫不变而回肠。','',''),('quantangshi-01599','琴曲歌辞 明月歌','閻朝隱','quantangshi','','卷2','梅花雪白柳叶黄，云雾四起月苍苍，箭水泠冷刻漏长。
挥玉指，拂罗裳，为君一奏楚明光。','',''),('quantangshi-01600','琴曲歌辞 绿竹引','之問','quantangshi','','卷2','青溪绿潭潭水侧，修竹婵娟同一色。
徒生仙实凤不游，老死空山人讵识。
妙年秉愿逃俗纷，归卧嵩丘弄白云。','',''),('quantangshi-01601','琴曲歌辞 山人劝酒','李白','quantangshi','','卷2','苍苍云松，落落绮皓。
春风尔来为阿谁，胡蝶忽然满芳草。
秀眉霜雪颜桃花，骨青髓绿长美好。
称是秦时避世人，劝酒相欢不知老。
各守兔鹿志，耻随龙虎争。
歘起佐太子，汉王乃复惊。
顾谓戚夫人，彼翁羽翼成。
归来南山下，泛若云无情。
举觞酹巢由，洗耳何独清？
浩歌望嵩岳，意气还相倾。','',''),('quantangshi-01602','琴曲歌辞 幽涧泉','李白','quantangshi','','卷2','拂彼白石，弹吾素琴。
幽涧愀兮流泉深，善手明徽高张清。
心寂历似千古，松飕飗兮万寻。
中见愁猨吊影而危处兮，呌秋木而长吟。
客有哀时失志而听者，泪淋浪以霑襟。
乃缉商缀羽，潺湲成音。
吾但写声发情于妙指，殊不知此曲之古今。
幽涧泉，鸣深林。','',''),('quantangshi-01603','琴曲歌辞 龙宫操','顧況','quantangshi','','卷2','龙宫月明光参差，精卫衔石东飞时。
鲛人织绡采藕丝，翻江倒海倾吴蜀。
汉女江妃杳相续，龙王宫中水不足。','',''),('quantangshi-01604','琴曲歌辞 飞鸢操','劉禹錫','quantangshi','','卷2','鸢飞杳杳青云里，鸢鸣萧萧风四起。
旗尾飘扬势渐高，箭头砉划声相似。
长空悠悠霁日悬，六翮不动凝飞烟。
游鶤翔雁出其下，庆云清景相回旋。
忽闻饥乌一噪聚，瞥下云中争腐鼠。
腾音砺吻相喧呼，仰天大吓疑鸳雏。
畏人避犬投高处，俛啄无声犹屡顾。
青鸟自爱玉山禾，仙禽徒贵华亭露。
朴𣙙危巢向暮时，毰毸饱腹蹲枯枝。
游童挟弹一麾肘，臆碎羽分人不悲。
天生众禽各有类，威凤文章在仁义。
鹰隼仪形蝼蚁心，虽能戾天何足贵。','',''),('quantangshi-01605','琴曲歌辞 升仙操','李羣玉','quantangshi','','卷2','嬴女去秦宫，琼箫生碧空。
凤台闭烟雾，鸾吹飘天风。
复闻周太子，亦遇浮丘公。
丛簧发仙弄，轻举紫霞中。
浊世不久住，清都路何穷。
一去霄汉上，世人那得逢。','',''),('quantangshi-01606','琴曲歌辞 司马相如琴歌','張祜','quantangshi','','卷2','凤兮凤兮非无凰，山重水阔不可量。
梧桐结阴在朝阳，濯羽弱水鸣高翔。','',''),('quantangshi-01607','琴曲歌辞 霍将军','崔顥','quantangshi','','卷2','长安甲第高入云，谁家居住霍将军。
日晚朝回拥宾从，路傍揖拜何纷纷。
莫言炙手手可热，须臾火尽灰亦灭。
莫言贫贱即可欺，人生富贵自有时。
一朝天子赐颜色，世上悠悠应自知。','',''),('quantangshi-01608','琴曲歌辞 琴歌','顧況','quantangshi','','卷2','琴调秋些，胡风遶雪。
峡泉生咽，佳人愁些。','',''),('quantangshi-01609','杂曲歌辞 秦女休行','李白','quantangshi','','卷2','西门秦氏女，秀色如琼花。
手挥白杨刀，清昼杀讐家。
罗袖洒赤血，英声凌紫霞。
直上西山去，关吏相邀遮。
壻为燕国王，身被诏狱加。
犯刑若履虎，不畏落爪牙。
素颈未及断，摧眉伏泥沙。
金鸡忽放赦，大辟得宽赊。
何慙聂政姊，万古共惊嗟。','',''),('quantangshi-01610','杂曲歌辞 出门行二首 一','孟郊','quantangshi','','卷2','长河悠悠去无极，百龄同此可叹息。
秋风白露霑人衣，壮心凋落夺颜色。
少年出门将诉谁，川无梁兮路无岐。
一闻陌上苦寒奏，使我伫立惊且悲。
君今得意厌粱肉，岂复念我贫贱时。','',''),('quantangshi-01611','杂曲歌辞 出门行二首 二','孟郊','quantangshi','','卷2','海风萧萧天雨霜，穷愁独坐夜何长？
驱车旧忆太行险，始知游子悲故乡。
美人相思隔天阙，长望云端不可越。
手持琅玕欲有赠，爱而不见心断绝。
南山峨峨白石烂，碧海之波浩漫漫。
参辰出没不相待，我欲横天无羽翰。','',''),('quantangshi-01612','杂曲歌辞 出门行','稹','quantangshi','','卷2','兄弟同出门，同行不同志。
凄凄分岐路，各各营所为。
兄上荆山巅，翻石辨虹气。
弟沈沧海底，偷珠待龙睡。
出门不数年，同归亦同遂。
俱用私所珍，升沈自兹异。
献珠龙王宫，值龙觅珠次。
但喜复得珠，不求珠所自。
酬客双龙女，授客六龙辔。
遣充行雨神，雨泽随客意。
雩夏钟鼓繁，禜秋玉帛积。
彩色画廊庙，奴僮被珠翠。
骥騄千万双，鸳鸯七十二。
言者禾稼枯，无人敢轻议。
其兄因献璞，再刖不履地。
门户亲戚疎，匡牀妻妾弃。
铭心有所待，视足无所愧。
持璞自枕头，泪痕双血渍。
一朝龙醒寤，本问偷珠事。
因知行雨偏，妻子五刑备。
仁兄捧尸哭，势友掉头讳。
丧车黔首葬，吊客青蝇至。
楚有望气人，王前忽长跪。
贺王得贵宝，不远王所莅。
求之果如言，剖则浮云腻。
白珩无颜色，垂棘有瑕累。
在楚列地封，入赵连城贵。
秦遣李斯书，书为传国瑞。
秦亡汉魏传，传者得神器。
卞和名永永，与宝不相坠。
劝尔出门行，行难莫行易。
易得还易失，难同亦难离。
善贾识贪廉，良田无稙穉。
磨劒莫磨锥，磨锥成小利。','',''),('quantangshi-01613','杂曲歌辞 出自蓟北门行','李白','quantangshi','','卷2','虏阵横北荒，胡星曜精芒。
羽书速惊电，烽火昼连光。
虎竹救边急，戎车森已行。
明主不安席，按劒心飞扬。
推毂出猛将，连旗登战场。
兵威冲绝漠，杀气凌穹苍。
列卒赤山下，开营紫塞傍。
途冬沙风紧，旌旗飒凋伤。
[画]角悲海月，征衣卷天霜。
挥刃斩楼兰，弯弓射贤王。
单于一平荡，种落自奔亡。
收功报天子，行歌归咸阳。','',''),('quantangshi-01614','杂曲歌辞 蓟门行五首 一','高適','quantangshi','','卷2','边城十一月，雨雪乱霏霏。
元戎号令严，人马亦轻肥。
羌胡无尽日，征战几人归。','',''),('quantangshi-01615','杂曲歌辞 蓟门行五首 二','高適','quantangshi','','卷2','幽州多骑射，结发重横行。
一朝事将军，出入有声名。
纷纷猎秋草，相向角弓鸣。','',''),('quantangshi-01616','杂曲歌辞 蓟门行五首 三','高適','quantangshi','','卷2','蓟门逢古老，独立思氛氲。
一身既零丁，头鬓白纷纷。
勋庸今已矣，不识霍将军。','',''),('quantangshi-01617','杂曲歌辞 蓟门行五首 四','高適','quantangshi','','卷2','茫茫长城外，日没更烟尘。
胡骑虽凭陵，汉兵不顾身。
古树满空塞，黄云愁杀人。','',''),('quantangshi-01618','杂曲歌辞 蓟门行五首 五','高適','quantangshi','','卷2','汉家能用武，开拓穷异域。
戍卒厌糠核，降胡饱衣食。
开亭试一望，吾欲涕霑臆。','',''),('quantangshi-01619','杂曲歌辞 蓟门行','李希仲','quantangshi','','卷2','旄头有精芒，胡骑猎秋草。
羽檄南渡河，边庭用兵早。
汉家爱征战，宿将今已老。
辛苦羽林儿，从戎榆关道。
一身救边速，烽火连蓟门。
前军鸟飞断，格鬬尘沙昏。
寒日鼓声急，单于夜火奔。
当须徇忠义，身死报国恩。','',''),('quantangshi-01620','杂曲歌辞 君子有所思行','李白','quantangshi','','卷2','紫阁连终南，青冥天倪色。
凭崖望咸阳，宫阙罗北极。
万井惊画出，九衢如弦直。
渭水清银河，横天流不息。
朝野盛文物，衣冠何翕赩。
廐马散连山，军容威绝域。
伊皐运元化，卫霍输筋力。
歌钟乐未休，荣去老还逼。
圆光过满缺，太阳移中昃。
不散东海金，何争西辉匿。
无作牛山悲，恻怆泪霑臆。','',''),('quantangshi-01621','杂曲歌辞 君子有所思行 一','僧貫休','quantangshi','','卷2','我爱正考甫，思贤作商颂。
我爱扬子云，理乱皆如凤。
振衣中夜起，露花香旖旎。
扑碎骊龙明月珠，敲出凤凰五色髓。
陋卷萧萧风淅淅，缅想斯人胜圭璧。
寂寥千载不相逢，无限区区尽虚掷。
君不见沈约道，佳人不在兹，春光为谁惜。','',''),('quantangshi-01622','杂曲歌辞 君子有所思行 二','僧貫休','quantangshi','','卷2','安得龙猛笔，点石为黄金。
散问酷吏家，使无贪残心。
甘棠密叶成翠幄，颍凤不来天地塞。
所以倾城人，如今不可得。','',''),('quantangshi-01623','杂曲歌辞 伤歌行','張籍','quantangshi','','卷2','黄门诏下促收捕，京兆君系御史府。
出门无复部曲随，亲戚相逢不容语。
辞成谪尉南海州，受命不得须臾留。
身着青衫骑恶马，东门之东无送者。
邮夫防吏急喧驱，往往惊堕马蹏下。
长安里中荒大宅，朱门已除十二戟。
高堂舞榭锁管弦，美人遥望西南天。','',''),('quantangshi-01624','杂曲歌辞 伤歌行','孟郊','quantangshi','','卷2','众毒蔓贞松，一枝难久荣。
岂知黄庭客，仙骨生不成。
春色舍芳蕙，秋风遶枯茎。
弹琴不成曲，始觉知音倾。
馆月改旧照，吊宾写余情。
还舟空江上，波浪送铭旌。','',''),('quantangshi-01625','杂曲歌辞 伤歌行','莊南傑','quantangshi','','卷2','兔走鸟飞不相见，人事依稀速如电。
王母夭桃一度开，玉楼红粉千回变。
车驰马走咸阳道，石家旧宅空荒草。
秋雨无情不惜花，芙蓉一一惊香倒。
劝君莫谩栽荆棘，秦皇虚费驱山力。
英风一去更无言，白骨沈埋暮山碧。','',''),('quantangshi-01626','杂曲歌辞 悲歌','李白','quantangshi','','卷2','悲来乎，悲来乎！主人有酒且莫斟，听我一曲悲来吟。
悲来不吟还不笑，天下无人知我心。
君有数斗酒，我有三尺琴。
琴鸣酒乐两相得，一杯不啻千钧金。
悲来乎，悲来乎！天虽长，地虽久，金玉满堂应不守。
富贵百年能几何？死生一度人皆有。
孤猨坐啼坟上月，且须一尽杯中酒。
悲来乎，悲来乎！凤鸟不至河无图，微子去之箕子奴。
汉帝不忆李将军，楚王放却屈大夫。
悲来乎，悲来乎！秦家李斯早追悔，虚名拨向身之外。
范子何曾爱五湖，功成名遂身自退。
劒是一夫用，书能知姓名。
惠施不肯干万乘，卜式未必穷一经。
还须黑头取方伯，莫谩白首为儒生。','',''),('quantangshi-01627','杂曲歌辞 悲哉行','孟雲卿','quantangshi','','卷2','孤儿去慈亲，远客丧主人。
莫吟苦辛曲，谁忍闻可闻。
可闻不可说，去去无期别。
行人念前程，不待参辰没。
朝亦常苦饥，暮亦常苦饥。
飘飘万余里，贫贱多是非。
少年莫远游，远游多不归。','',''),('quantangshi-01628','杂曲歌辞 悲哉行','白居易','quantangshi','','卷2','悲哉为儒者，力学不能疲。
读书眼欲暗，秉笔手生胝。
十上方一第，成名常苦迟。
纵有宦达者，两鬓已成丝。
可怜少壮日，适在穷贱时。
丈夫老且病，焉用富贵为。
沈沈朱门宅，中有乳臭儿。
状貌如妇人，光明膏粱肌。
手不把书卷，身不擐戎衣。
二十袭封爵，门承勋戚资。
春来日日出，服御何轻肥。
朝从博徒饮，暮有倡楼期。
评封还酒债，堆金选蛾眉。
声色狗马外，其余一无知。
山苗与涧松，地势随高卑。
古来无奈何，非君独伤悲。','',''),('quantangshi-01629','杂曲歌辞 悲哉行','鮑溶','quantangshi','','卷2','促促晨复昏，死生同一源。
贵年不惧老，贱老伤久存。
朗朗哭前歌，绛旌引幽魂。
来为千金子，去卧百草根。
黄土塞生路，悲风送回辕。
金鞍旧良马，四顾不出门。
生结千岁念，荣及百代孙。
黄金买性命，白刃讐一言。
宁知北山上，松柏侵田园。','',''),('quantangshi-01630','杂曲歌辞 妾薄命','崔國輔','quantangshi','','卷2','虽入秦帝宫，不上秦帝牀。
夜夜玉窗里，与他卷罗裳。','',''),('quantangshi-01631','杂曲歌辞 妾薄命','武平一','quantangshi','','卷2','有女妖且丽，裴回湘水湄。
水湄兰杜芳，采之将寄谁。
瓠犀发皓齿，双蛾嚬翠眉。
红脸如开莲，素肤若凝脂。
绰约多逸态，轻盈不自持。
常矜绝代色，复恃倾城姿。
子夫前入侍，飞燕复当时。
正悦掌中舞，宁哀团扇诗。
洛川昔云遇，高唐今尚违。
幽合禽雀噪，闲阶草露滋。
流景一何速，年华不可追。
解佩安何赠，怨咽空自悲。','',''),('quantangshi-01632','杂曲歌辞 妾薄命','李百藥','quantangshi','','卷2','团扇秋风起，长门夜月明。
羞闻拊背人，恨说舞腰轻。
太常应已醉，刘君恒带酲。
横陈每虚设，吉梦竟何成。','',''),('quantangshi-01633','杂曲歌辞 妾薄命','杜審言','quantangshi','','卷2','草绿长门闭，苔青永巷幽。
宠移新爱夺，泣下故情留。
啼鸟惊残梦，飞花搅独愁。
自怜春色罢，团扇复迎秋。','',''),('quantangshi-01634','杂曲歌辞 妾薄命','劉元淑','quantangshi','','卷2','自从离别守空闺，遥闻征战起云梯。
夜夜愁君辽海外，年年弃妾渭桥西。
阳春白日照空暖，紫燕衔花向庭满。
彩鸾琴里怨声多，飞鹊镜前妆梳断。
谁家夫壻不从征，应是渔阳别有情。
莫道红颜燕地少，家家还似洛阳城。
且逐新人殊未归，还令秋至夜霜飞。
北斗星前横度雁，南楼月下捣寒衣。
夜深闻雁肠欲绝，独坐缝衣灯又灭。
暗啼罗帐空自怜，梦度阳关向谁说。
每怜容貌宛如神，如何薄命不胜人。
愿君朝夕燕山至，好作明年杨柳春。','',''),('quantangshi-01635','杂曲歌辞 妾薄命','李白','quantangshi','','卷2','汉帝重阿娇，贮之黄金屋。
咳唾落九天，随风生珠玉。
宠极爱还歇，妒深情却疎。
长门一步地，不肯暂回车。
雨落不上天，水覆难再收。
君情与妾意，各自东西流。
昔日芙蓉花，今成断根草。
以色事他人，能得几时好。','',''),('quantangshi-01636','杂曲歌辞 妾薄命','孟郊','quantangshi','','卷2','不惜十指弦，为君千万弹。
常恐新声至，坐使故声残。
弃置今日悲，即是昨日欢。
将新变故易，持故为新难。
青山有蘼芜，泪叶长不干。
空令后代人，采掇幽思攒。','',''),('quantangshi-01637','杂曲歌辞 妾薄命','張籍','quantangshi','','卷2','薄命妇，良家子，无事从军去万里。
汉家天子平四夷，护羌都尉裹尸归。
念君此行为死别，对君裁缝泉下衣。
与君一日为夫妇，千年万岁亦相守。
君爱龙城征战功，妾愿青楼欢乐同。
人生各各有所欲，讵得将心入君腹。','',''),('quantangshi-01638','杂曲歌辞 妾薄命三首 一','李端','quantangshi','','卷2','忆妾初嫁君，花鬟如绿云。
回灯入绮帐，对面脱罗裙。
折步教人学，偷香与客熏。
容颜南国重，名字北方闻。
一从失恩意，转觉身憔悴。
对镜不梳头，倚窗空落泪。
新人莫恃新，秋至会无春。
从来闭在长门者，必是宫中第一人。','',''),('quantangshi-01639','杂曲歌辞 妾薄命三首 二','李端','quantangshi','','卷2','玉垒城边争走马，铜蹏市里共乘舟。
鸣环动佩思无尽，掩袖低巾泪不流。
畴昔将歌邀客醉，如今欲舞对君羞。
忍怀贱妾平生曲，独上襄阳旧酒楼。','',''),('quantangshi-01640','杂曲歌辞 妾薄命三首 三','李端','quantangshi','','卷2','自从君弃妾，憔悴不羞人。
惟余坏粉泪，未免映衫匀。','',''),('quantangshi-01641','杂曲歌辞 妾薄命','盧綸','quantangshi','','卷2','妾年初二八，两度嫁狂夫。
薄命今犹在，坚贞扫地无。','',''),('quantangshi-01642','杂曲歌辞 妾薄命','盧弼','quantangshi','','卷2','君恩已断尽成空，追想娇欢恨莫穷。
长为蕣华光晓日，谁知团扇送秋风。
黄金买赋心徒切，清路飞尘信莫通。
闲凭玉栏思旧事，几回春暮泣残红。','',''),('quantangshi-01643','杂曲歌辞 妾薄命','胡曾','quantangshi','','卷2','阿娇初失汉皇恩，旧赐罗衣亦罢熏。
欹枕夜悲金屋雨，卷帘朝泣玉楼云。
宫前叶落鸳鸯瓦，架上尘生翡翠裙。
龙骑不巡时渐久，长门长掩绿苔文。','',''),('quantangshi-01644','杂曲歌辞 妾薄命','王貞白','quantangshi','','卷2','薄命头欲白，频年嫁不成。
秦娥未十五，昨夜事公卿。
岂有机杼力，空传歌舞名。
妾专修妇德，媒氏却相轻。','',''),('quantangshi-01645','杂曲歌辞 羽林行','王建','quantangshi','','卷2','长安恶少出名字，楼下劫商楼上醉。
天明下直明光宫，散入五陵松柏中。
百回杀人身合死，赦书尚有收城功。
九衢一日消息定，乡吏籍中重改姓。
出来依旧属羽林，立在殿前射飞禽。','',''),('quantangshi-01646','杂曲歌辞 羽林行','孟郊','quantangshi','','卷2','朔雪寒断指，朔风劲裂冰。
胡中射雕者，此日犹不能。
翩翩羽林儿，锦臂飞苍鹰。
挥鞭决白马，走出黄河凌。','',''),('quantangshi-01647','杂曲歌辞 羽林行','鮑溶','quantangshi','','卷2','朝出羽林宫，入参云台议。
独请万里行，不奏和亲事。
君王重年少，深纳开边利。
宝马雕玉鞍，一朝从万骑。
煌煌都门外，祖帐光七贵。
歌钟乐行军，云物惨别地。
箫笳整部曲，幢盖动郊次。
临风亲戚怀，满袖儿女泪。
行行复何赠，长劒报恩字。','',''),('quantangshi-01648','杂曲歌辞 白马篇','李白','quantangshi','','卷2','龙马花雪毛，金鞍五陵豪。
秋霜切玉劒，落日明珠袍。
鬬鸡事万乘，轩盖一何高。
弓摧宜山虎，手接泰山猱。
酒后竞风彩，三杯弄宝刀。
杀人如翦草，剧孟同游遨。
发愤去函谷，从军向临洮。
叱咤万战场，匈奴尽波涛。
归来使酒气，未肯拜萧曹。
羞入原宪室，荒径隐蓬蒿。','',''),('quantangshi-01649','杂曲歌辞 升天行','僧齊己','quantangshi','','卷2','身不沈，骨不重，驱青鸾，驾白凤。
幢盖飘飘入冷空，天风瑟瑟星河动。
瑶阙参差阿母家，楼台戏闭凝彤霞。
五三仙子乘龙车，堂前碾烂蟠桃花。
回头却顾蓬山顶，一点浓岚在深井。','',''),('quantangshi-01650','杂曲歌辞 神仙曲','李賀','quantangshi','','卷2','碧峰海面藏灵书，上帝拣作神仙居。
晴时笑语闻空虚，鬬乘巨浪骑鲸鱼。
春罗翦字邀王母，共宴红楼最深处。
鹤羽冲风过海迟，不如却使青龙去。
犹疑王母不相许，垂露娃鬟更传语。','',''),('quantangshi-01651','杂曲歌辞 北风行','李白','quantangshi','','卷2','烛龙栖寒门，光曜犹旦开。
日月照之何不及此，惟有北风怒号天上来。
燕山雪花大如席，片片吹落轩辕台。
幽州思妇十二月，停歌罢笑双蛾摧。
倚门望行人，念君长城苦寒良可哀。
别时提劒救边去，遗此虎文金髀钗。
中有一双白羽箭，蜘蛛结网生尘埃。
箭空在，人今战死不复回。
不忍见此物，焚之已成灰。
黄河捧土尚可塞，北风雨雪恨难裁。','',''),('quantangshi-01652','杂曲歌辞 苦热行','王維','quantangshi','','卷2','赤日满天地，火云成山岳。
草木尽焦卷，川泽皆竭涸。
轻纨觉衣重，密树苦阴薄。
莞簟不可近，絺綌再三濯。
思出宇宙外，旷然在寥廓。
长风万里来，江海荡烦浊。
却顾身为患，始知心未觉。
忽入甘露门，宛然清凉乐。','',''),('quantangshi-01653','杂曲歌辞 苦热行','王轂','quantangshi','','卷2','祝融南来鞭火龙，火旗焰焰烧天红。
日轮当午凝不去，万国如在洪炉中。
五岳翠干云彩灭，阳侯海底愁波竭。
何当一夕金风发？为我扫却天下热。','',''),('quantangshi-01654','杂曲歌辞 苦热行','僧皎然','quantangshi','','卷2','六月金数伏，兹辰日在庚。
炎曦曝肌肤，毒雾昏檐楹。
安得奋翅翮，超遥出云征。
不知天地心，如何匠生成。
火德烧百卉，瑶草不及荣。
省客当此时，忽贻怀中琼。
捧翫烦袂涤，啸歌美风生。
迟君佐元气，调使四序平。
中令霜不祆，火余气常贞。
江南诗骚客，休吟苦热行。','',''),('quantangshi-01655','杂曲歌辞 苦热行','僧齊己','quantangshi','','卷2','离宫划开赤帝怒，喝起六龙奔日驭。
下土熬熬若煎煮，苍生惶惶无处处。
火云峥嵘焚泬寥，东皐老农肠欲焦。
何当一雨苏我苗？为君击坏歌帝尧。','',''),('quantangshi-01656','杂曲歌辞 太行苦热行','劉長卿','quantangshi','','卷2','迢迢太行路，自古称险恶。
千骑俨欲前，羣峯望如削。
火云从中起，仰视飞鸟落。
汗马卧高原，危旌倚长薄。
清风何不至？赤日方煎烁。
石露山木焦，鳞穷水泉涸。
九重今旰食，万里传明略。
诸将候轩车，元凶愁鼎镬。
何劳短兵接，自有长缨缚。
通越事岂难，渡泸功未博。
朝辞羊肠坂，夕望贝丘郭。
漳水斜遶营，常山遥入幕。
永怀姑苏下，因寄建安作。
白雪和诚难，沧波意空托。
陈琳书记好，王粲从军乐。
早晚归汉庭，随君上麟阁。','',''),('quantangshi-01657','杂曲歌辞 太行苦热行','獨孤及','quantangshi','','卷2','驷马上太行，修途亘辽碣。
王程无留驾，日昃未遑歇。
请问此何时，恢台朱明月。
长蛇稽天讨，上将方北伐。
明主命使臣，皇华得时杰。
已忘羊肠险，岂惮温风入。
摇策汗滂沲，登崖思纡结。
炎云如烟火，溪谷将恐竭。
昼景赩可畏，凉飙何由发？
山长飞鸟堕，目极行车绝。
赵魏方俶扰，安危俟明哲。
归路岂不怀，饮冰有苦节。
会同传檄至，疑议立谈决。
况有阮元瑜，翩翩秉书札。
起予歌赤坂，永好逾白雪。
维念剖竹人，无因执羁绁。','',''),('quantangshi-01658','杂曲歌辞 春日行','李白','quantangshi','','卷2','深宫高楼入紫清，金作蛟龙盘绣楹。
佳人当窗弄白日，弦将手语弹鸣筝。
春风吹落君王耳，此曲乃是升天行。
因出天池泛蓬瀛，楼船蹙沓波浪惊。
三千双蛾献歌笑，挝钟考鼓宫殿倾。
万姓聚舞歌太平，我无为，人自宁。
三十六帝欲相迎，仙人飘翩下云軿。
帝不去，留镐京。
安能为轩辕，独往入窅冥。
小臣拜献南山寿，陛下万古垂鸿名。','',''),('quantangshi-01659','杂曲歌辞 春日行','張籍','quantangshi','','卷2','春日融融池上暖，竹牙出土兰心短。
草堂晨起酒半醒，家僮报我园花满。
头上皮冠未曾整，直入花间不寻径。
树树殷勤尽遶行，举枝未徧春日暝。
不用积金着青天，不用服药求神仙。
但愿园里花长好，一生饮酒花前老。','',''),('quantangshi-01660','杂曲歌辞 朗月行','李白','quantangshi','','卷2','小时不识月，呼作白玉盘。
又疑瑶台镜，飞在青云端。
仙人垂两足，桂树作团团。
白兔捣药成，问言与谁餐。
蟾蜍蚀圜影，天明夜已残。
羿昔落九乌，天人清且安。
阴精此沦惑，去去不足观。
忧来其如何？恻怆摧心肝。','',''),('quantangshi-01661','杂曲歌辞 前有一尊酒行二首 一','李白','quantangshi','','卷2','春风东来忽相过，金尊绿酒生微波。
落花纷纷稍觉多，美人欲醉朱颜酡。
青轩桃李能几何？流光欺人忽蹉跎。
君起舞，日西夕，当年意气不肯倾，白发如丝叹何益。','',''),('quantangshi-01662','杂曲歌辞 前有一尊酒行二首 二','李白','quantangshi','','卷2','琴奏龙门之绿桐，玉壶美酒清若空。
催弦拂柱与君饮，看朱成碧颜始红。
胡姬貌如花，当炉笑春风。
笑春风，舞罗衣，君今不醉欲安归。','',''),('quantangshi-01663','杂曲歌辞 缓歌行','李頎','quantangshi','','卷2','小来托身攀贵游，倾财破产无所忧。
暮拟经过石渠署，朝将出入铜龙楼。
结交杜陵轻薄子，谓言可生复可死。
一沈一浮会有时，弃我翻然如脱屣。
男儿立身须自彊，十五闭户颍水阳。
业就功成见明主，击钟鼎食坐华堂。
二八蛾眉梳堕马，美酒清歌曲房下。
文昌宫中赐锦衣，长安陌上退朝归。
五侯宾从莫敢视，三省官僚揖者稀。
早知今日读书是，悔作从来任侠非。','',''),('quantangshi-01664','杂曲歌辞 结客少年场行','虞世南','quantangshi','','卷2','韩魏多奇节，倜傥遗名利。
共矜然诺心，各负纵横志。
结友一言重，相思千里至。
绿沈明月弦，金络浮云辔。
吹箫入吴市，击筑游燕肆。
寻源博望侯，结客远相求。
少年重一顾，长驱背陇头。
焰焰霜戈动，耿耿劒虹浮。
天山冬夏雪，交河南北流。
云起龙沙暗，木落雁行秋。
轻生徇知己，非是为身谋。','',''),('quantangshi-01665','杂曲歌辞 结客少年场行','虞羽客','quantangshi','','卷2','幽并侠少年，金络控连钱。
窃符方救赵，击筑正怀燕。
轻生辞凤阙，挥袂上祁连。
陆离横宝劒，出没惊徂旃。
蒙轮恒顾敌，超乘忽争先。
摧枯逾百战，拓地远三千。
骨都魂已散，楼兰首复传。
龙城含晓雾，瀚海隔遥天。
歌吹金微返，振旅玉门旋。
烽火今已息，非复照甘泉。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01666','杂曲歌辞 结客少年场行','盧照鄰','quantangshi','','卷2','长安重游侠，洛阳富才雄。
玉劒浮云骑，金鞍明月弓。
鬬鸡过渭北，走马向关东。
孙宾遥见待，郭解暗相通。
不受千金爵，谁论万里功。
将军下天上，虏骑入云中。
