死生容易如反掌，得意失意由一言。
少年但饮莫相问，此中报讐亦报恩。','',''),('quantangshi-01720','杂曲歌辞 轻薄篇二首 一','僧貫休','quantangshi','','卷2','绣林锦野，春态相压。
谁家少年，马蹏蹋蹋。
鬬鸡走狗夜不归，一掷赌却如花妾。
惟云不颠不狂，其名不彰。
悲夫！。','',''),('quantangshi-01721','杂曲歌辞 轻薄篇二首 二','僧貫休','quantangshi','','卷2','木落萧萧，蛩鸣唧唧。
不觉朱蔫脸红，霜劫鬓漆。
世途多事，泣向秋日。
方吟少壮不努力，老大徒伤悲。','',''),('quantangshi-01722','杂曲歌辞 轻薄行','僧齊己','quantangshi','','卷2','玉鞭金镫骅骝蹏，横眉吐气如虹霓。
五陵春暖芳草齐，笙歌到处花成泥。
日沈月上且鬬鸡，醉来莫问天高低。
伯阳道德何涕唾，仲尼礼乐徒卑栖。','',''),('quantangshi-01723','杂曲歌辞 灞上轻薄行','孟郊','quantangshi','','卷2','长安无缓步，况值天景暮。
相逢灞浐间，亲戚不相顾。
自叹方拙身，忽随轻薄伦。
常恐失所避，化为车辙尘。
此中生白发，疾走亦未歇。','',''),('quantangshi-01724','杂曲歌辞 游侠篇','崔顥','quantangshi','','卷2','少年负胆气，好勇复知机。
仗劒出门去，孤城逢合围。
杀人辽水上，走马渔阳归。
错落金琐甲，蒙茸貂鼠衣。
还家行且猎，弓矢速如飞。
地迥鹰犬疾，草深狐兔肥。
腰间悬两绶，转眄生光辉。','',''),('quantangshi-01725','杂曲歌辞 游侠行','孟郊','quantangshi','','卷2','壮士性刚决，火中见石裂。
杀人不回头，轻生如暂别。
岂知眼有泪，肯白头上发。
平生无恩酬，劒闲一百月。','',''),('quantangshi-01726','杂曲歌辞 侠客行','李白','quantangshi','','卷2','赵客缦胡缨，吴钩霜雪明。
银鞍照白马，飒沓如流星。
十步杀一人，千里不留行。
事了拂衣去，深藏身与名。
闲过信陵饮，脱劒膝前横。
将炙啖朱亥，持觞劝侯嬴。
三杯吐然诺，五岳倒为轻。
眼花耳热后，意气素霓生。
救赵挥金槌，邯郸先震惊。
千秋二壮士，烜赫大梁城。
纵死侠骨香，不慙世上英。
谁能书阁下，白首太玄经。','',''),('quantangshi-01727','杂曲歌辞 侠客行','稹','quantangshi','','卷2','侠客不怕死，怕在事不成。
事成不肯藏姓名，我非窃贼谁夜行。
白日堂堂杀袁盎，九衢草草人面青。
此客此心师海鲸，海鲸露背横沧溟。
海滨分作两处生，海鲸分海减海力。
侠客有谋人不测，三尺铁蛇延二国。','',''),('quantangshi-01728','杂曲歌辞 侠客行','溫庭筠','quantangshi','','卷2','欲出鸿都门，阴云蔽城阙。
宝劒黯如水，微红湿余血。
白马夜频嘶，三更霸陵雪。','',''),('quantangshi-01729','杂曲歌辞 行行游且猎篇','李白','quantangshi','','卷2','边城儿，生年不读一字书，但知游猎夸轻趫。
胡马秋肥宜白草，骑来蹑影何矜骄。
金鞭拂云挥鸣鞘，半酣呼鹰出远郊。
弓弯满月不虚发，双鸧迸落连飞𩩉。
海边观者皆辟易，猛气英风振沙碛。','',''),('quantangshi-01730','杂曲歌辞 游子吟','孟郊','quantangshi','','卷2','慈母手中线，游子身上衣。
临行密密缝，意恐迟迟归。
谁言寸草心，报得三春晖。','',''),('quantangshi-01731','杂曲歌辞 游子吟','顧況','quantangshi','','卷2','故枥思疲马，故巢思迷禽。
浮云蔽我乡，踯躅游子吟。
游子悲久滞，浮云郁东岑。
客堂无丝桐，落叶如秋霖。
艰哉远游子，所以悲滞淫。
一为浮云词，愤塞谁能禁。
驰晖百年内，惟愿展所钦。
胡为不归欤，坐使年病侵。
未老霜遶鬓，非狂火烧心。
太行何艰哉？北斗不可斟。
夜晴星河出，耿耿辰与参。
佳人敻青天，尺素重于金。
泬寥羣动异，眇默诸境森。
苔衣上闲阶，蜻蛚催寒砧。
立身计几误，道险无容针。
三年不还家，万里遗锦衾。
梦魂无重阻，离忧因古今。
胡为不归欤，孤负丘中琴。
腰下是何物？牵缠旷登寻。
朝与名山期，夕宿楚水阴。
楚水殊演漾，名山杳岖嵚。
客从洞庭来，婉娈潇湘深。
橘柚在南国，鸿雁遗秋音。
下有碧草洲，上有青橘林。
引烛窥洞穴，凌波睥天琛。
蒲荷影参差，凫鹤雏淋涔。
浩歌惜芳杜，散发轻华簪。
胡为不归欤，泪下霑衣襟。
鸢飞戾霄汉，蝼蚁制鳣鱏。
赫赫大圣朝，日月光照临。
圣主虽启迪，奇人分堙沈。
层城发云韶，玉府锵球琳。
鹿鸣志丰草，况复虞人箴。','',''),('quantangshi-01732','杂曲歌辞 游子吟','李益','quantangshi','','卷2','女羞夫壻荡，客耻主人贱。
遭遇同众流，低回愧相见。
君非青铜镜，何事空照面？
莫以衣上尘，不谓心如练。
人生当荣盛，待士勿言倦。
君看白日驰，何异弦上箭。','',''),('quantangshi-01733','杂曲歌辞 壮士吟','賈島','quantangshi','','卷2','壮士不曾悲，悲即无回期。
如何易水上，未歌先泪垂。','',''),('quantangshi-01734','杂曲歌辞 壮士行','劉禹錫','quantangshi','','卷2','阴风振寒郊，猛虎正咆哮。
徐行出烧地，连吼入黄茆。
壮士走马去，镫前弯玉弰。
叱之使人立，一发如铍交。
悍睛忽星坠，飞血溅林梢。
彪炳为我席，膻腥充我庖。
里中欣害除，贺酒纷号呶。
明日长桥上，倾城看斩蛟。','',''),('quantangshi-01735','杂曲歌辞 壮士行','鮑溶','quantangshi','','卷2','西方太白高，壮士羞病死。
心知报恩处，对酒歌易水。
砂鸿嗥天末，横劒别妻子。
苏武执节归，班超束书起。
山河不足重，重在遇知己。','',''),('quantangshi-01736','杂曲歌辞 壮士行','施肩吾','quantangshi','','卷2','一斗之胆撑脏腑，如磥之筋碍臂骨。
有时误入千人丛，自觉一身横突兀。
当今四海无烟尘，胸襟被压不得伸。
冻枭残虿我不取，污我匣黑青蛇鳞。','',''),('quantangshi-01737','杂曲歌辞 浩歌','李賀','quantangshi','','卷2','南风吹山作平地，帝遣天吴移海水。
王母桃花千遍红，彭祖巫咸几回死。
青毛骢马参差钱，娇春杨柳含细烟。
筝人劝我金屈巵，神血未凝身问谁。
不须浪饮丁督护，世上英雄本无主。
买丝绣作平原君，有酒惟浇赵州土。
漏催水咽玉蟾蜍，卫娘发薄不胜梳。
看见秋眉换深绿，二十男儿那刺促。','',''),('quantangshi-01738','杂曲歌辞 浩歌行','白居易','quantangshi','','卷2','天长地久无终毕，昨夜今朝又明日。
鬓发苍浪牙齿疎，不觉身年四十七。
前去五十有几年，把镜照面心茫然。
既无长绳系白日，又无大药驻朱颜。
朱颜日渐不如故，青史功名在何处？
欲留年少待富贵，富贵不来年少去。
去复去兮如长河，东流赴海无回波。
贤愚贵贱同归尽，北邙冢墓高嵯峨。
古来如此非独我，未死有酒且酣歌。
颜回短命伯夷饿，我今所得亦已多。','',''),('quantangshi-01739','杂曲歌辞 归去来引','張熾','quantangshi','','卷2','归去来，归期不可违。
相见故明月，浮云共我归。','',''),('quantangshi-01740','杂曲歌辞 丽人曲','崔國輔','quantangshi','','卷2','红颜称绝代，欲并真无侣。
独有镜中人，由来自相许。','',''),('quantangshi-01741','杂曲歌辞 丽人行','杜甫','quantangshi','','卷2','三月三日天气新，长安水边多丽人。
态浓意远淑且真，肌理细腻骨肉匀。
绣罗衣裳照暮春，蹙金孔雀银麒麟。
头上何所有？翠微㔩叶垂鬓唇。
背后何所见？珠压腰衱稳称身。
就中云幕椒房亲，赐名大国虢与秦。
紫駞之峯出翠釜，水晶之盘行素鳞。
犀筯厌饫久未下，鸾刀缕切空纷纶。
黄门飞鞚不动尘，御厨丝络送八珍。
箫鼓哀吟感鬼神，宾从杂遝实要津。
后来鞍马何逡巡，当轩下马入锦茵。
杨花雪落覆白苹，青鸟飞去衔红巾。
炙手可热势绝伦，慎莫近前丞相嗔。','',''),('quantangshi-01742','杂曲歌辞 东飞伯劳歌','張柬之','quantangshi','','卷2','青田白鹤丹山凤，婺女姮娥两相送。
谁家绝世绮帐前，艳粉芳脂映宝钿。
窈窕玉堂褰翠幕，参差绣户悬珠箔。
绝世三五爱红妆，冶袖长裾兰麝香。
春去花枝俄易改，可叹年光不相待。','',''),('quantangshi-01743','杂曲歌辞 东飞伯劳歌','李嶠','quantangshi','','卷2','传书青鸟迎箫凤，巫岭荆台数通梦。
谁家窈窕住园楼，五马千金照陌头。
罗裙玉佩当轩出，点翠施红竞春日。
佳人二八盛舞歌，羞将百万呈双娥。
庭前芳树朝夕改，空驻妍华欲谁待。','',''),('quantangshi-01744','杂曲歌辞 东飞伯劳歌','李暇','quantangshi','','卷2','秦王龙劒燕后琴，珊瑚宝匣镂双心。
谁家女儿抱香枕，开衾灭烛愿侍寝。
琼窗半上金缕帱，轻罗隐面不障羞。
青绮帏中坐相忆，红罗镜里见愁色。
檐花照月莺对栖，空将可怜暗中啼。','',''),('quantangshi-01745','杂曲歌辞 鸣雁行','李白','quantangshi','','卷2','胡雁鸣，辞燕山，昨发委羽朝度关。
一一衔芦枝，南飞散落天地间。
连行接翼往复还，客居烟波寄湘吴。
凌霜触雪毛体枯，畏逢矰缴惊相呼。','',''),('quantangshi-01746','杂曲歌辞 鸣雁行','韓愈','quantangshi','','卷2','嗷嗷鸣雁鸣且飞，穷秋南去春北归。
去寒就暖识所处，天长地阔栖息稀。
风霜酸苦稻粱微，羽毛摧落身不肥。
徘徊反顾羣侣违，哀鸣欲下洲渚非。
江南水阔朝云多，草长沙輭无网罗。','',''),('quantangshi-01747','杂曲歌辞 鸣雁行','鮑溶','quantangshi','','卷2','七月朔方雁心苦，联影翻空落南土。
八月江南阴复晴，浮云绕天难夜行。
羽翼劳痛心虚惊，一声相呼百处鸣。
楚童夜宿烟波侧，沙上布罗连草色。
月暗风悲欲下天，不知何处容栖息？
楚童胡为伤我神，尔不曾作远行人。
江南羽族本不少，宁得网罗此客鸟。','',''),('quantangshi-01748','杂曲歌辞 鸣雁行','陸龜蒙','quantangshi','','卷2','朔风动地来，吹起沙上声。
闺中有边思，玉筯此时横。
莫怕儿女恨，主人烹不鸣。','',''),('quantangshi-01749','杂曲歌辞 空城雀','李白','quantangshi','','卷2','嗷嗷空城雀，身计何戚促。
本与鹪鹩羣，不随凤凰族。
提携四黄口，饮乳未尝足。
食君糠粃余，常恐乌鸢逐。
耻涉太行险，羞营覆车粟。
天命有定端，守分绝所欲。','',''),('quantangshi-01750','杂曲歌辞 空城雀','王建','quantangshi','','卷2','空城雀，何不飞来人家住？
空城无人种禾黍。
土间生子草间长，满地蓬蒿幸无主。
近村虽有高树枝，雨中无食长苦饥。
八月小儿夹弓箭，家家畏我田头飞。
但能不出空城里，秋时百草皆有子。
黄口黄口莫啾啾，长尔得成无横死。','',''),('quantangshi-01751','杂曲歌辞 空城雀','聶夷中','quantangshi','','卷2','一雀入官仓，所食能损几。
所虑往损频，官仓乃害尔。
鱼网不在天，鸟网不在水。','',''),('quantangshi-01752','杂曲歌辞 空城雀','劉駕','quantangshi','','卷2','饥啄空城土，莫近太仓粟。
一粒未充肠，却入公子腹。
且吊城上骨，几曾害尔族。
不闻庄辛语，今日寒芜绿。','',''),('quantangshi-01753','杂曲歌辞 车遥遥','孟郊','quantangshi','','卷2','路喜到江尽，江上又通舟。
舟车两无阻，何处不得游？
丈夫四方志，女子安可留？
郎自别日言，无令生远愁。
旅雁忽叫月，断猨寒啼秋。
此夕梦君梦，君在百城楼。
寄泪无因波，寄恨无因輈。
愿为驭者手，与郎回马头。','',''),('quantangshi-01754','杂曲歌辞 车遥遥','張籍','quantangshi','','卷2','征人遥遥出古城，双轮齐动驷马鸣。
山川无处无归路，念君长作万里行。
野田人稀秋草绿，日暮放马车中宿。
惊麏游兔在我傍，独唱乡歌对僮仆。
君家大宅凤城隅，年年道上随行车。
愿为玉銮系华轼，终日有声在君侧。
门前旧辙久已平，无由复得君消息。','',''),('quantangshi-01755','杂曲歌辞 车遥遥','張祜','quantangshi','','卷2','东方昽昽车轧轧，地色不分新去辙。
闺门半掩牀半空，斑斑枕花残泪红。
君心若车千万转，妾身如辙遗渐远。
碧川迢迢山宛宛，马蹏在耳轮在眼。
桑间女儿情不浅，莫道野蚕能作茧。','',''),('quantangshi-01756','杂曲歌辞 车遥遥','胡曾','quantangshi','','卷2','自从车马出门朝，便入空房守寂寥。
玉枕夜残鱼信绝，金钿秋尽雁书遥。
脸边楚雨临风落，头上春云向日销。
芳草又衰还不至，碧天霜冷转无憀。','',''),('quantangshi-01757','杂曲歌辞 自君之出矣','辛弘智','quantangshi','','卷2','自君之出矣，梁尘静不飞。
思君如满月，夜夜减容晖。','',''),('quantangshi-01758','杂曲歌辞 自君之出矣','李康成','quantangshi','','卷2','自君之出矣，弦吹绝无声。
思君如百草，撩乱逐春生。','',''),('quantangshi-01759','杂曲歌辞 自君之出矣','盧仝','quantangshi','','卷2','自君之出矣，壁上蜘蛛织。
近取见妾心，夜夜无休息。
妾有双玉环，寄君表相忆。
环是妾之心，玉是君之德。
驰情增悴容，蓄思损精力。
玉簟寒凄凄，延想心恻恻。
风含霜月明，水泛碧天色。
此水有尽时，此情无终极。','',''),('quantangshi-01760','杂曲歌辞 自君之出矣','雍裕之','quantangshi','','卷2','自君之出矣，宝镜为谁明。
思君如陇水，长闻呜咽声。','',''),('quantangshi-01761','杂曲歌辞 自君之出矣','張祜','quantangshi','','卷2','自君之出矣，万物看成古。
千寻葶苈枝，争奈长长苦。','',''),('quantangshi-01762','杂曲歌辞 长相思','郎大家宋氏','quantangshi','','卷2','长相思，久离别。
关山阻，风烟绝。
台上镜文销，袖中书字灭。
不见君形影，何曾有懽悦。','',''),('quantangshi-01763','杂曲歌辞 长相思','蘇頲','quantangshi','','卷2','君不见天津桥下东流水，东望龙门北朝市。
杨柳青青宛地垂，桃红李白花参差。
花参差，柳堪结，此时忆君心断绝。','',''),('quantangshi-01764','杂曲歌辞 长相思三首 一','李白','quantangshi','','卷2','长相思，在长安，络纬秋啼金井栏。
微霜凄凄簟色寒，孤灯不明思欲绝。
卷帷望月空长叹，美人如花隔云端。
上有青冥之长天，下有绿水之波澜。
天长路远魂飞苦，梦魂不到关山难。
长相思，摧心肝。','',''),('quantangshi-01765','杂曲歌辞 长相思三首 二','李白','quantangshi','','卷2','日色已尽花含烟，月明欲素愁不眠。
赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。
此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。
昔日横波目，今成流泪泉。
不信妾肠断，归来看取明镜前。','',''),('quantangshi-01766','杂曲歌辞 长相思三首 三','李白','quantangshi','','卷2','美人在时花满堂，美人去后花余牀。
牀中绣被卷不寝，至今三载犹闻香。
香亦竟不灭，人亦竟不来。
相思黄叶落，白露点青苔。','',''),('quantangshi-01767','杂曲歌辞 长相思','張繼','quantangshi','','卷2','辽阳望河县，白首无由见。
海上珊瑚枝，年年寄春燕。','',''),('quantangshi-01768','杂曲歌辞 长相思二首 一','令狐楚','quantangshi','','卷2','君行登陇上，妾梦在闺中。
玉筯千行落，银牀一半空。','',''),('quantangshi-01769','杂曲歌辞 长相思二首 二','令狐楚','quantangshi','','卷2','绮席春眠觉，纱窗晓望迷。
朦胧残梦里，犹自在辽西。','',''),('quantangshi-01770','杂曲歌辞 长相思','白居易','quantangshi','','卷2','九月西风兴，月冷霜华凝。
思君秋夜长，一夜魂九升。
二月东风来，草坼花心开。
思君春日迟，一日肠九回。
妾住洛桥北，君住洛桥南。
十五即相识，今年二十三。
有如女萝草，生在松之侧。
蔓短枝苦高，萦回上不得。
人言人有愿，愿至天必成。
愿作远方兽，步步比肩行。
愿作深山木，枝枝连理生。','',''),('quantangshi-01771','杂曲歌辞 千里思','李白','quantangshi','','卷2','李陵没胡沙，苏武还汉家。
迢迢五原关，朔雪乱边花。
一去隔绝域，思归但长嗟。
鸿雁向西北，飞书报天涯。','',''),('quantangshi-01772','杂曲歌辞 千里思','李端','quantangshi','','卷2','凉州风月美，遥望居延路。
泛泛下天云，青青缘塞树。
燕山苏武上，海岛田横住。
更是草生时，行人出门去。','',''),('quantangshi-01773','杂曲歌辞 行路难','盧照鄰','quantangshi','','卷2','君不见长安城北渭桥边，枯木横槎卧古田。
昔日含红复含紫，常时留雾亦留烟。
春景春风花似雪，香车玉轝恒阗咽。
若个游人不竞攀，若个倡家不来折。
倡家宝袜蛟龙帔，公子银鞍千万骑。
黄莺一向花娇春，两两三三将子戏。
千尺长条百尺枝，丹桂青榆相蔽亏。
珊瑚叶上鸳鸯鸟，凤凰巢里雏鵷儿。
巢倾枝折凤归去，条枯叶落狂风吹。
一朝零落无人问，万古摧残君讵知。
人生贵贱无终始，倏忽须臾难久恃。
谁家能驻西山日，谁家能堰东流水。
汉家陵树满秦川，行来行去尽哀怜。
自昔公卿二千石，咸拟荣华一万年。
不见朱唇将白貌，惟闻素棘与黄泉。
金貂有时须换酒，玉麈但摇莫计钱。
寄言坐客神仙署，一生一死交情处。
苍龙阙下君不来，白鹤山前我应去。
云间海上邈难期，赤心会合在何时？
但愿尧年一百万，长作巢由也不辞。','',''),('quantangshi-01774','杂曲歌辞 行路难','張紘','quantangshi','','卷2','君不见温家玉镜台，提携抱握九重来。
君不见相如绿绮琴，一抚一拍凤凰音。
人生意气须及早，莫负当年行乐心。
荆王奏曲楚妃叹，曲尽欢终夜将半。
朱楼银阁正平生，碧草青苔坐芜漫。
当春对酒不须疑，视目相看能几时。
春风吹尽燕初至，此时自谓称君意。
秋露萎草鸿始归，此时衰暮与君违。
人生翻覆何常足，谁保容颜无是非。','',''),('quantangshi-01775','杂曲歌辞 行路难五首 一','賀蘭進明','quantangshi','','卷2','君不见岩下井，百尺不及泉。
君不见山上蒿，数寸凌云烟。
人生相命亦如此，何苦太息自忧煎。
但愿亲友长含笑，相逢莫吝杖头钱。
寒夜邀欢须秉烛，岂得空思花柳年。','',''),('quantangshi-01776','杂曲歌辞 行路难五首 二','賀蘭進明','quantangshi','','卷2','君不见门前柳，荣曜暂时萧索久。
君不见陌上花，狂风吹去落谁家。
谁家思妇见之叹，蓬首不梳心历乱。
盛年夫壻长别离，岁暮相逢色凋换。','',''),('quantangshi-01777','杂曲歌辞 行路难五首 三','賀蘭進明','quantangshi','','卷2','君不见荒树枝，春花落尽蜂不窥。
君不见梁上泥，秋风始高燕不栖。
荡子从军事征战，蛾眉婵娟空守闺。
独宿自然堪下泪，况复时闻乌夜啼。','',''),('quantangshi-01778','杂曲歌辞 行路难五首 四','賀蘭進明','quantangshi','','卷2','君不见云间月，暂盈还复缺。
君不见林下风，声远意难穷。
亲故平生欲聚散，欢娱未尽尊酒空。
自叹青青陵上柏，岁寒能与几人同。','',''),('quantangshi-01779','杂曲歌辞 行路难五首 五','賀蘭進明','quantangshi','','卷2','君不见东流水，一去无穷已。
君不见西郊云，日夕空氛氲。
羣雁裴回不能去，一雁悲鸣复失羣。
人生结交在终始，莫为升沈中路分。','',''),('quantangshi-01780','杂曲歌辞 行路难','崔顥','quantangshi','','卷2','君不见建章宫中金明枝，万万长条拂地垂。
二月三月花如霰，九重幽深君不见。
艳彩朝含四宝宫，香风吹入朝云殿。
汉家宫女春未阑，爱此芳香朝暮看。
看去看来心不忘，攀折将安镜台上。
双双素手剪不成，两两红妆笑相向。
建章昨夜起春风，一花飞落长信宫。
长信丽人见花泣，忆此珍树何嗟及。
我昔初在昭阳时，朝折暮折登玉墀。
祗言岁岁长相对，不寤今朝遥相思。','',''),('quantangshi-01781','杂曲歌辞 行路难三首 一','李白','quantangshi','','卷2','金尊清酒斗十千，玉盘珍羞直万钱。
停杯投筯不能食，拔劒四顾心茫然。
欲渡黄河冰塞川，将登太行雪暗天。
闲来垂钓坐溪上，忽复乘舟梦日边。
行路难，行路难，多岐路，今安在？
长风破浪会有时，直挂云帆济沧海。','',''),('quantangshi-01782','杂曲歌辞 行路难三首 二','李白','quantangshi','','卷2','大道如青天，我独不得出。
羞逐长安社中儿，赤鸡白狗赌梨栗。
弹劒作歌奏苦声，曳裾王门不称情。
淮阴市井笑韩信，汉朝公卿忌贾生。
君不见昔时燕家重郭隗，拥彗折腰无嫌猜。
剧辛乐毅感恩分，输肝剖胆效英才。
昭王白骨萦蔓草，谁人更扫黄金台。
行路难，归去来。','',''),('quantangshi-01783','杂曲歌辞 行路难三首 三','李白','quantangshi','','卷2','有耳莫洗颍川水，有口莫食首阳蕨。
含光混世贵无名，何用孤高比云月。
吾观自古贤达人，功成不退皆殒身。
子胥既弃吴江上，屈原终投湘水滨。
陆机才多岂自保，李斯税驾苦不早。
华亭鹤唳讵可闻，上蔡苍鹰何足道？
君不见吴中张翰称达士，秋风忽忆江东行。
且乐生前一杯酒，何须身后千载名。','',''),('quantangshi-01784','杂曲歌辞 行路难三首 一','顧況','quantangshi','','卷2','君不见古来烧水银，变作北邙山上尘。
藕丝挂身在虚空，欲落不落愁杀人。
睢水英雄多血刃，建章宫阙成灰烬。
淮王身死桂枝折，徐氏一去音书绝。
行路难，行路难，生死皆由天。
秦皇汉武遭下脱，汝独何人学神仙。','',''),('quantangshi-01785','杂曲歌辞 行路难三首 二','顧況','quantangshi','','卷2','君不见担雪塞井徒用力，炊砂作饭岂堪吃。
一生肝胆向人尽，相识不如不相识。
冬青树上挂凌宵，岁[晏]花凋树不凋。
凡物各自有根本，种禾终不生豆苗。
行路难，行路难，何处是平道？
中心无事当富贵，今日觉君颜色好。','',''),('quantangshi-01786','杂曲歌辞 行路难三首 三','顧況','quantangshi','','卷2','君不见少年头上如云发，少壮如云老如雪。
岂知灌顶有醍醐，能使清凉头不热。
吕梁之水挂飞流，鼋鼍蛟蜃不敢游。
少年恃险若平地，独倚长劒凌清秋。
行路难，行路难，昔少年，今已老。
前朝竹帛事皆空，日暮牛羊古城草。','',''),('quantangshi-01787','杂曲歌辞 行路难','李頎','quantangshi','','卷2','汉家名臣杨德祖，四代五公享茅土。
父兄子弟绾银黄，跃马鸣珂朝建章。
火浣单衣绣方领，茱萸锦带玉盘囊。
宾客填街复满坐，片言出口生辉光。
世人逐势争奔走，沥胆隳肝惟恐后。
当时一顾生青云，自谓生死长随君。
一朝谢病还乡里，穷巷苍茫绝知己。
秋风落叶闭重门，昨日论交竟谁是。
薄俗嗟嗟难重陈，深山麋鹿下为邻。
鲁连所以蹈沧海，古往今来称达人。','',''),('quantangshi-01788','杂曲歌辞 行路难二首 一','高適','quantangshi','','卷2','君不见富家翁，昔时贫贱谁比数。
一朝金多结豪贵，万事胜人健如虎。
子孙成长满眼前，妻能管弦妾能舞。
自矜一朝忽如此，却笑傍人独悲苦。
东邻少年安所如，席门穷巷出无车。','',''),('quantangshi-01789','杂曲歌辞 行路难二首 二','高適','quantangshi','','卷2','长安少年不少钱，能骑骏马鸣金鞭。
五侯相逢大道边，美人弦管争留连。
黄金如斗不敢惜，片言如山莫弃捐。
安知顦顇读书者，暮宿虚台私自怜。','',''),('quantangshi-01790','杂曲歌辞 行路难','張籍','quantangshi','','卷2','湘东行人长叹息，十年离家归未得。
弊裘羸马苦难行，童仆饥寒少筋力。
君不见牀头黄金尽，壮士无颜色。
龙蟠泥中未有云，不能生彼升天翼。','',''),('quantangshi-01791','杂曲歌辞 行路难','聶夷中','quantangshi','','卷2','莫言行路难，夷狄如中国。
谓言骨肉亲，中门如异域。
出处全在人，路亦无通塞。
门前两条辙，何处去不得。','',''),('quantangshi-01792','杂曲歌辞 行路难','韋應物','quantangshi','','卷2','荆山之白玉兮。
良工雕琢双环连，月蚀中央镜心穿。
故人赠妾初相结，恩在环中寻不绝。
人情厚薄苦须臾，昔似连环今似玦。
连环可碎不可离，如何物在人自移。
上客勿遽欢，听妾歌路难。
傍人见环环可怜，不知中有长恨端。','',''),('quantangshi-01793','杂曲歌辞 行路难三首 一','柳宗元','quantangshi','','卷2','君不见夸父逐日窥虞渊，跳踉北海超昆仑。
披霄决汉出沆漭，瞥裂左右遗星辰。
须臾力尽道渴死，狐鼠蜂蚁争噬吞。
北方竫人长九寸，开口抵掌更笑喧。
啾啾饮食滴与粒，生死亦足终天年。
睢盱大志少成遂，坐使儿女相悲怜。','',''),('quantangshi-01794','杂曲歌辞 行路难三首 二','柳宗元','quantangshi','','卷2','虞衡斤斧罗千山，工命采斫杙与椽。
深林土翦十取一，百牛连鞅摧双辕。
万围千寻妨道路，东西蹶倒山火焚。
遗余毫末不见保，躝砾磵壑何当存。
羣材未成质已夭，突兀𡷸豁空岩峦。
柏梁天灾武库火，匠石狼顾相愁冤。
君不见南山栋梁益稀少，爱材养育谁复论。','',''),('quantangshi-01795','杂曲歌辞 行路难三首 三','柳宗元','quantangshi','','卷2','飞雪断道冰成梁，侯家炽炭雕玉房。
蟠龙吐耀虎喙张，熊蹲豹掷争低昂。
攒峦丛崿射朱光，丹霞翠雾飘奇香。
美人四向回明璫，雪山冰谷曦太阳。
星躔奔走不得止，奄忽双燕栖虹梁。
风台露榭生光饰，死灰弃置参与商。
盛时一去贵反贱，桃笙葵扇安可常。','',''),('quantangshi-01796','杂曲歌辞 行路难','鮑溶','quantangshi','','卷2','玉堂向夕如无人，丝竹俨然宫商死。
细人何言入君耳？尘生金尊酒如水。
君今不念岁蹉跎，雁天明明凉露多。
华灯青凝久照夜，彩童窈窕虚垂罗。
入宫见妬君不察，莫入此地出风波。','',''),('quantangshi-01797','杂曲歌辞 行路难五首 一','僧貫休','quantangshi','','卷2','不会当时作天地，刚有多般愚与智。
到头还用真宰心，何如上下皆清气。
大道冥冥不知处，那堪顿得羲和辔。
义不义兮仁不仁，拟学长生更容易。
负心为炉复为火，缘木求鱼应且止。
君不见烧金炼石古帝王，鬼火荧荧白杨里。','',''),('quantangshi-01798','杂曲歌辞 行路难五首 二','僧貫休','quantangshi','','卷2','君不见道傍废井生古木，本是骄奢贵人屋。
几度美人照影来，素绠银瓶濯纤玉。
云飞雨散今如此，绣闼雕甍作荒谷。
沸渭笙歌君莫夸，不应长是西家哭。
休说遗编行者几，至竟终须合天理。
败他成此亦何功，苏张终作多言鬼。
行路难，行路难，不在羊肠里。','',''),('quantangshi-01799','杂曲歌辞 行路难五首 三','僧貫休','quantangshi','','卷2','九有茫茫共尧日，浪死虚生亦非一。
清净玄音竟不闻，花眼酒肠暗如漆。
或偶因片言只字登第光二亲，又不能献可替不航要津。
口谈羲轩与周孔，履行不及屠沽人。
行路难，行路难，日暮途远空悲叹。','',''),('quantangshi-01800','杂曲歌辞 行路难五首 四','僧貫休','quantangshi','','卷2','君不见道傍树有寄生枝，青青郁郁同荣衰。
无情之物尚如此，为人不及还堪悲。
父归坟兮未朝夕，已分黄金争田宅。
高堂老母头似霜，心作数支泪常滴。
我闻忽如负芒刺，不独为君空叹息。
古人尺布犹可缝，浔阳义犬令人忆。
寄言世上为人子，孝义团圆莫如此。','',''),('quantangshi-01801','杂曲歌辞 行路难五首 五','僧貫休','quantangshi','','卷2','君不见山高海深人不测，古往今来转青碧。
浅近轻浮莫与交，池卑只解生荆棘。
谁道黄金如粪土，张耳陈余断消息。
行路难，行路难，君自看。','',''),('quantangshi-01802','杂曲歌辞 行路难二首 一','僧齊己','quantangshi','','卷2','行路难，君好看。
惊波不在黤黮间，小人心里藏奔湍。
七盘九折寒崷崪，翻车倒盖犹堪出。
未似是非唇舌危，暗中潜毁平人骨。
君不见楚灵均，千古沈冤湘水滨。
又不见李太白，一朝却作江南客。','',''),('quantangshi-01803','杂曲歌辞 行路难二首 二','僧齊己','quantangshi','','卷2','下浸与高盘，不为行路难。
是非真险恶，翻覆作峰峦。
漆愧同时黑，朱慙巧处丹。
令人畏相识，欲画白云看。','',''),('quantangshi-01804','杂曲歌辞 行路难','翁綬','quantangshi','','卷2','行路艰难不复歌，故人荣达我蹉跎。
双轮晚上铜梁雪，一叶春浮瘴海波。
自古要津皆若此，方今失路欲如何？
君看西汉翟丞相，凤沼朝辞暮雀罗。','',''),('quantangshi-01805','杂曲歌辞 行路难','薛能','quantangshi','','卷2','何处力堪殚？人心险万端。
藏山难测度，暗水自波澜。
对面如千里，回肠似七盘。
已经吴坂困，欲向雁门难。
南北诚须泣，高深不可干。
无因善行止，车辙得平安。','',''),('quantangshi-01806','杂曲歌辞 从军中行路难二首 一','駱賓王','quantangshi','','卷2','君不见封狐雄虺自成羣，冯深负固结妖氛。
玉玺分兵征恶少，金坛受律动将军。
将军拥旄宣庙略，战士横行静夷落。
长驱一息背铜梁，直指三巴逾劒阁。
阁道岧嶤上戍楼，劒门遥裔俯灵丘。
邛关九折无平路，江水双源有急流。
征役无期返，他乡岁华晚。
杳杳丘陵出，苍苍林薄远。
途危紫盖峰，路涩青泥坂。
去去指哀牢，行行入不毛。
绝壁千里险，连山四望高。
中外分区宇，夷夏殊风土。
交趾枕南荒，昆弥临北户。
川源饶毒雾，溪谷多淫雨。
行潦四时流，崩查千岁古。
漂梗飞蓬不自安，扪藤引葛度危峦。
昔时闻道从军乐，今日方知行路难。
苍江绿水东流驶，炎洲丹徼南中地。
南中南斗映星河，秦川秦塞阻烟波。
三春边地风光少，五月泸中瘴疠多。
朝驱疲斥候，夕息倦谁何。
向月弯繁弱，连星转太阿。
重义轻生怀一顾，东伐西征凡几度。
夜夜朝朝斑鬓新，年年岁岁戎衣故。
灞城隅，滇池水，天涯望转积，地际行无已。
徒觉炎凉节物非，不知关山千万里。
弃置勿重陈，重陈多苦辛。
且悦清笳杨柳曲，讵忆芳园桃李人。
绛节朱旗分白羽，丹心白刃酬明主。
但令一技君王识，谁惮三边征战苦。
行路难，行路难，岐路几千端。
无复归云冯短翰，望日想长安。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01807','杂曲歌辞 从军中行路难二首 二','駱賓王','quantangshi','','卷2','君不见玉关尘色暗边亭，铜鞮杂虏寇长城。
天子按劒征余勇，将军受脤事横行。
七德龙韬开玉帐，千里鼍鼓叠金钲。
阴山苦雾埋高垒，交河孤月照连营。
连营去去无穷极，拥斾遥遥过绝国。
阵云朝结晦天山，寒沙夕涨迷疎勒。
龙鳞水上开鱼贯，马首山前振雕翼。
长驱万里讋祁连，分麾三命武功宣。
百发乌号遥碎柳，七尺龙文迥照莲。
春来秋去移灰琯，兰闺柳市芳尘断。
雁门迢遰尺书稀，鸳被相思双带缓。
行路难，誓令氛祲静皐兰。
但使封侯龙额贵，讵随中妇凤楼寒。','',''),('quantangshi-01808','杂曲歌辞 变行路难','王昌齡','quantangshi','','卷2','向晚横吹悲，风动马嘶合。
前驱引旗节，千重阵云帀。
单于下阴山，砂砾空飒飒。
封侯取一战，岂复念闺合。','',''),('quantangshi-01809','杂曲歌辞 古别离','沈佺期','quantangshi','','卷2','白水东悠悠，中有西行舟。
舟行有返棹，水去无还流。
奈何生别者，戚戚怀远游。
远游谁当惜，所悲会难收。
自君间芳躧，青阳四五遒。
皓月掩兰室，光风虚蕙楼。
相思无明晦，长叹累冬秋。
离居分迟暮，驾高何淹留。','',''),('quantangshi-01810','杂曲歌辞 古别离','孟雲卿','quantangshi','','卷2','朝日上高台，离人怨秋草。
但见万里天，不见万里道。
君行本遥远，苦乐良难保。
宿昔梦同衾，忧心梦颠倒。
含酸欲谁诉，转转伤怀抱。
结发年已迟，征行去何早。
寒暄有时谢，顦顇难再好。
人皆算年寿，死者何曾老。
少壮无见期，水深风浩浩。','',''),('quantangshi-01811','杂曲歌辞 古别离','李益','quantangshi','','卷2','双劒欲别风凄然，雌沈水底雄上天。
江回汉转两不见，云交雨合知何年。
古来万事皆由命，何用临岐苦涕涟。','',''),('quantangshi-01812','杂曲歌辞 古别离二首 一','于濆','quantangshi','','卷2','入室少情意，出门多路岐。
黄鹤有归日，荡子无还时。
人谁无分命，妾身何太奇。
君为东南风，妾作西北枝。
青楼邻里妇，终年画长眉。
自倚对良匹，笑妾空罗帏。','',''),('quantangshi-01813','杂曲歌辞 古别离二首 二','于濆','quantangshi','','卷2','郎本东家儿，妾本西家女。
对门中道间，终谓无离阻。
岂知中道间，遣作空闺主。
自是爱封侯，非关备胡虏。','',''),('quantangshi-01814','杂曲歌辞 古别离二首 一','李端','quantangshi','','卷2','水国叶黄时，洞庭霜落夜。
行舟闻商估，宿在枫林下。
此地送君还，茫茫似梦间。
后期知几日，前路转多山。
巫峡通湘浦，迢迢隔云雨。
天晴见海樯，月落闻津鼓。
人老自多愁，水深难急流。
清宵歌一曲，白首对汀洲。','',''),('quantangshi-01815','杂曲歌辞 古别离二首 二','李端','quantangshi','','卷2','与君桂阳别，令君岳阳待。
后事忽差池，前期日空在。
木落雁嗷嗷，洞庭波浪高。
远山云似盖，极浦树如毫。
朝发能几里，暮来风又起。
如何两处愁，皆在孤舟里。
昨夜天月明，长川寒且清。
菊花开欲尽，荠菜拍来生。
下江帆势速，五两遥相逐。
欲问去时人，知投何处宿。
空令猨啸时，泣对湘潭竹。','',''),('quantangshi-01816','杂曲歌辞 古别离','王縉','quantangshi','','卷2','下阶欲离别，相对映兰丛。
含辞未及吐，泪落兰丛中。
高堂静秋日，罗衣飘暮风。
谁能待明月，回首见牀空。','',''),('quantangshi-01817','杂曲歌辞 古别离','僧皎然','quantangshi','','卷2','太湖三山口，吴王在时道。
寂寞千载心，无人见春草。
谁堪缄怨者，持此伤怀抱。
孤舟畏狂风，一点宿烟岛。
望所思兮若何，月荡漾兮空波。
云离离兮北断，雁眇眇兮南多。
身去兮天畔，心折兮湖岸。
春山胡为兮塞路，使我归梦兮撩乱。','',''),('quantangshi-01818','杂曲歌辞 古别离','聶夷中','quantangshi','','卷2','欲别牵郎衣，问郎游何处？不恨归日迟，莫向临邛去。','',''),('quantangshi-01819','杂曲歌辞 古别离二首 一','施肩吾','quantangshi','','卷2','古人谩歌西飞燕，十年不见狂夫面。
三更风作切梦刀，万转愁成系肠线。
所嗟不及牛女星，一年一度得相见。','',''),('quantangshi-01820','杂曲歌辞 古别离二首 二','施肩吾','quantangshi','','卷2','老母别爱子，少妻送征郎。
血流既四面，乃亦断二肠。
不愁寒无衣，不怕饥无粮。
惟恐征战不还乡，母化为鬼妻为孀。','',''),('quantangshi-01821','杂曲歌辞 古别离','吳融','quantangshi','','卷2','紫燕黄鹄虽别离，一举千里何难追。
犹闻啼风与叫月，流连断续令人悲。
赋情更有深缱绻，碧甃千寻尚为浅。
蟾蜍正向清夜流，蛱蝶须教堕丝罥。
莫道断丝不可续，丹穴凤皇胶不远。
草草通流水不回，海上两潮长不返。','',''),('quantangshi-01822','杂曲歌辞 古离别','王適','quantangshi','','卷2','昔岁惊杨柳，高楼悲独守。
今年芳树枝，孤栖怨别离。
珠帘昼不卷，罗幔晓长垂。
苦调琴先觉，愁容镜独知。
频来雁度无消息，罢去鸳文何用织。
夜还罗帐空有情，春着帬腰自无力。
青轩桃李落纷纷，紫庭兰蕙日氛氲。
已能顦顇今如此，更复含情一待君。','',''),('quantangshi-01823','杂曲歌辞 古离别','常理','quantangshi','','卷2','君御狐白裘，妾居缃绮帱。
粟钿金夹膝，花错玉搔头。
离别生庭草，征行断戍楼。
蟏蛸网清曙，菡萏落红秋。
小胆空房怯，长眉满镜愁。
为传儿女意，不用远封侯。','',''),('quantangshi-01824','杂曲歌辞 古离别','姚係','quantangshi','','卷2','凉风已袅袅，露重木兰枝。
独上高楼望，行人远不知。
轻寒入洞户，明月满秋池。
燕去鸿方至，年年是别离。','',''),('quantangshi-01825','杂曲歌辞 古离别','張彪','quantangshi','','卷2','离别无远近，事欢情亦悲。
不闻车轮声，后会将何时。
去日忘寄书，来日乖前期。
纵知明当还，一夕千万思。','',''),('quantangshi-01826','杂曲歌辞 古离别','趙微明','quantangshi','','卷2','违别未几日，一日如三秋。
犹疑望可见，日日上高楼。
惟见分手处，白苹满芳洲。
寸心宁死别，不忍生离愁。','',''),('quantangshi-01827','杂曲歌辞 古离别二首 一','孟郊','quantangshi','','卷2','松山云缭绕，萍路水分离。
云去有归日，水分无合时。
春芳役双眼，春色柔四支。
杨柳织别愁，千条万条丝。','',''),('quantangshi-01828','杂曲歌辞 古离别二首 二','孟郊','quantangshi','','卷2','山川古今路，纵横无断绝。
来往天地间，人皆有离别。
行衣未束带，中肠已先结。
不用看镜中，自知生白发。
欲陈去留意，声向言前咽。
愁结填心胸，茫茫若为说。
荒郊烟莽苍，旷野风凄切。
处处得相随，人那不如月。','',''),('quantangshi-01829','杂曲歌辞 古离别','顧況','quantangshi','','卷2','西江上，风动麻姑嫁时浪。
西山为水水为尘，不是人间离别人。','',''),('quantangshi-01830','杂曲歌辞 古离别','僧貫休','quantangshi','','卷2','离恨如旨酒，古今饮皆醉。
只恐长江水，尽是儿女泪。
伊余非此辈，送人空把臂。
他日再相逢，清风动天地。','',''),('quantangshi-01831','杂曲歌辞 古离别','韋莊','quantangshi','','卷2','晴烟漠漠柳毵毵，不那离情酒半酣。
更把马鞭云外指，断肠春色在江南。','',''),('quantangshi-01832','杂曲歌辞 生别离','孟雲卿','quantangshi','','卷2','结发生别离，相思复相保。
何知日已久，五变庭中草。
眇眇天海途，悠悠吴江岛。
但恐不出门，出门无远道。
远道行既难，家贫衣服单。
严风吹积雪，晨起鼻何酸。
人生各有恋，岂不怀所安。
分明天上日，生死誓同欢。','',''),('quantangshi-01833','杂曲歌辞 生别离','白居易','quantangshi','','卷2','食蘖不易食梅难，蘖能苦兮梅能酸。
未如生别之为难，苦在心兮酸在肝。
晨鸡载鸣残月没，征马重嘶行人出。
回看骨肉哭一声，梅酸蘖苦甘如蜜。
黄河水白黄云秋，行人河边相对愁。
天寒野旷何处宿？棠梨叶战风飕飕。
生离别，生离别，忧从中来无断绝。
忧积心劳血气衰，未年三十生白发。','',''),('quantangshi-01834','杂曲歌辞 远别离','李白','quantangshi','','卷2','远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。
海水直下万里深，谁人不言此离苦。
日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。
我纵言之将何补，皇穹窃恐不照余之忠诚。
雷冯冯兮欲吼怒，尧舜当之亦禅禹。
君失臣兮龙为鱼，权归臣兮鼠变虎。
或云尧幽囚，舜野死，九疑联緜皆相似，重瞳孤坟竟何是。
帝子泣兮绿云间，随风波兮去无还。
恸哭兮远望，见苍梧之深山。
苍梧山崩湘水绝，竹上之泪乃可灭。','',''),('quantangshi-01835','杂曲歌辞 远别离','張籍','quantangshi','','卷2','莲叶团团杏花拆，长江鲤鱼鳍鬣赤。
念君少年弃亲戚，千里万里独为客。
谁言远别心不易，天星坠地能为石。
几时断得城南陌，勿使居人有行役。','',''),('quantangshi-01836','杂曲歌辞 远别离二首 一','令狐楚','quantangshi','','卷2','杨柳黄金穗，梧桐碧玉枝。
春来消息断，早晚是归时。','',''),('quantangshi-01837','杂曲歌辞 远别离二首 二','令狐楚','quantangshi','','卷2','玳织鸳鸯履，金装翡翠簪。
畏人相问着，不拟到城南。','',''),('quantangshi-01838','杂曲歌辞 久别离','李白','quantangshi','','卷2','别来几春未还家，玉窗五见樱桃花。
况有锦字书，开缄使人嗟。
至此肠断彼心绝，云鬟绿鬓罢揽结。
愁如回飙乱白雪，去年寄书报阳台。
今年寄书重相催，胡为东风为我吹行云。
使西来，待来竟不来，落花寂寂委青苔。','',''),('quantangshi-01839','杂曲歌辞 新别离','戴叔倫','quantangshi','','卷2','手把杏花枝，未曾经别离。
黄昏掩闺后，寂寞自心知。','',''),('quantangshi-01840','杂曲歌辞 今别离','崔國輔','quantangshi','','卷2','送别未能旋，相望连水口。
船行欲映洲，几度急摇手。','',''),('quantangshi-01841','杂曲歌辞 暗别离','劉氏瑤','quantangshi','','卷2','槐花结子桐叶焦，单飞越鸟嗁青霄。
翠轩辗云轻遥遥，燕脂泪迸红线条。
瑶草歇芳心耿耿，玉佩无声画屏冷。
朱弦暗断不见人，风动花枝月中影。
青鸾脉脉西飞去，海阔天高不知处。','',''),('quantangshi-01842','杂曲歌辞 潜别离','白居易','quantangshi','','卷2','不得哭，潜别离，不得语，暗相思，两心之外无人知。
深笼夜[锁]独栖鸟，利劒[春]断连理枝。
河水虽浊有清日，乌头虽黑有白时。
惟有潜离与暗别，彼此甘心无后期。','',''),('quantangshi-01843','杂曲歌辞 别离曲','張籍','quantangshi','','卷2','行人结束出门去，马蹏几时踏门路。
忆昔君初纳彩时，不言身属辽阳戍。
早知今日当别离，成君家计良为谁。
男儿生身自有役，那得悞我少年时。
不如逐君征战死，谁能独老空闺里。','',''),('quantangshi-01844','杂曲歌辞 别离曲','陸龜蒙','quantangshi','','卷2','丈夫非无泪，不洒离别间。
仗劒对尊酒，耻为游子颜。
蝮蛇一螫手，壮士疾解腕。
所思在功名，离别何足叹。','',''),('quantangshi-01845','杂曲歌辞 西洲曲','溫庭筠','quantangshi','','卷2','悠悠复悠悠，昨日下西洲。
西洲风色好，遥见武昌楼。
武昌何郁郁，侬家定无匹。
小妇被流黄，登楼抚瑶瑟。
朱弦繁复轻，素手直凄清。
一弹三四解，掩抑似含情。
南楼登且望，西江广复平。
艇子摇两桨，催过石头城。
门前乌臼树，惨澹天将曙。
鵾鵊飞复还，郎随早帆去。
回头语同伴，定复负情侬。
去帆不安幅，作抵使西风。
他日相寻索，莫作西洲客。
西洲人不归，春草年年碧。','',''),('quantangshi-01846','杂曲歌辞 荆州乐','李白','quantangshi','','卷2','白帝城边足风波，瞿塘五月谁敢过。
荆州麦熟茧成蛾，缫丝忆君头绪多，拨谷飞鸣奈妾何。','',''),('quantangshi-01847','杂曲歌辞 荆州乐二首 一','劉禹錫','quantangshi','','卷2','渚宫杨柳暗，麦城朝雉飞。
可怜踏青伴，乘暖着轻衣。','',''),('quantangshi-01848','杂曲歌辞 荆州乐二首 二','劉禹錫','quantangshi','','卷2','今日好南风，商旅相催发。
沙头樯竿上，始见春江阔。','',''),('quantangshi-01849','杂曲歌辞 荆州泊','李端','quantangshi','','卷2','南楼西下时，月里闻来棹。
桂水舳舻回，荆州津济闹。
移帷望星汉，引带思容貌。
今夜一江人，惟应妾身觉。','',''),('quantangshi-01850','杂曲歌辞 纪南歌','劉禹錫','quantangshi','','卷2','风烟纪南城，尘土荆门路。
天寒猎兽者，走上樊姬墓。','',''),('quantangshi-01851','杂曲歌辞 宜城歌','劉禹錫','quantangshi','','卷2','野水遶空城，行尘起孤驿。
花台侧生树，石碣阳镌头。
靡靡度行人，温风吹宿麦。','',''),('quantangshi-01852','杂曲歌辞 长干曲四首 一','崔顥','quantangshi','','卷2','君家定何处？妾住在横塘。
停舟暂借问，或恐是同乡。','',''),('quantangshi-01853','杂曲歌辞 长干曲四首 二','崔顥','quantangshi','','卷2','家临九江水，去来九江侧。
同是长干人，生小不相识。','',''),('quantangshi-01854','杂曲歌辞 长干曲四首 三','崔顥','quantangshi','','卷2','下渚多风浪，莲舟渐觉稀。
那能不相待，独自逆潮归。','',''),('quantangshi-01855','杂曲歌辞 长干曲四首 四','崔顥','quantangshi','','卷2','三江潮水急，五湖风浪涌。
由来花性轻，莫畏莲舟重。','',''),('quantangshi-01856','杂曲歌辞 长干行二首 一','李白','quantangshi','','卷2','妾发初覆额，折花门前剧。
郎骑竹马来，遶牀弄青梅。
同居长干里，两小无嫌猜。
十四为君妇，羞颜尚不开。
低头向暗壁，千唤不一回。
十五始展眉，愿同尘与灰。
常存抱柱信，岂上望夫台。
十六君远行，瞿塘滟预堆。
五月不可触，猨鸣天上哀。
门前迟行迹，一一生绿苔。
苔深不能扫，落叶秋风早。
八月蝴蝶来，双飞西园草。
感此伤妾心，坐愁红颜老。
早晚下三巴，预将书报家。
相迎不道远，直至长风沙。','',''),('quantangshi-01857','杂曲歌辞 长干行二首 二','李白','quantangshi','','卷2','忆妾深闺里，烟尘不曾识。
嫁与长干人，沙头候风色。
五月南风兴，思君在巴陵。
八月西风起，想君发扬子。
去来悲如何，见少别离多。
湘潭几日到，妾梦越风波。
昨夜狂风度，吹折江头树。
淼淼暗无边，行人在何处？
北客真王公，朱衣满江中。
日暮来投宿，数朝不肎东。
好乘浮云骢，佳期兰渚东。
鸳鸯绿浦上，翡翠锦屏中。
自怜十五余，颜色桃李红。
那作商人妇，愁水复愁风。','',''),('quantangshi-01858','杂曲歌辞 长干行','張潮','quantangshi','','卷2','壻贫如珠玉，壻富如埃尘。
贫时不忘旧，富贵多宠新。
妾本富家女，与君为偶匹。
惠好一何深，中门不曾出。
妾有绣衣裳，葳蕤金缕光。
念君贫且贱，易此从远方。
远方三千里，发去悔不已。
日暮情更来，空望去时水。
孟夏麦始秀，江上多南风。
商贾归欲尽，君今尚巴东。
巴东有巫山，窈窕神女颜。
常恐游此山，果然不知还。','',''),('quantangshi-01859','杂曲歌辞 小长干曲','崔國輔','quantangshi','','卷2','月暗送湖风，相寻路不通。
菱歌唱不辍，知在此塘中。','',''),('quantangshi-01860','杂曲歌辞 杞梁妻','僧貫休','quantangshi','','卷2','秦之无道兮四海枯，筑长城兮遮北胡。
筑人筑土一万里，杞梁贞妇嗁呜呜。
上无父兮中无夫，下无子兮孤复孤。
一号城崩塞色苦，再号杞梁骨出土。
疲魂饥魄相逐归，陌上少年莫相非。','',''),('quantangshi-01861','杂曲歌辞 卢女曲','崔顥','quantangshi','','卷2','二月春来半，宫中日渐长。
柳垂金屋暖，花覆玉楼香。
拂匣先临镜，调笙更炙簧。
还将卢女曲，夜夜奉君王。','',''),('quantangshi-01862','杂曲歌辞 卢姬篇','崔顥','quantangshi','','卷2','卢姬小小魏王家，绿鬓红唇桃李花。
魏王绮楼十二重，水精帘箔绣芙蓉。
白玉阑干金作柱，楼上朝朝学歌舞。
前堂后堂罗袖人，南窗北窗花发春。
翠幌珠帘鬬弦管，一奏一弹云欲断。
君王日晚下朝归，鸣环佩玉生光辉。
人生今日得骄贵，谁道卢姬身细微。','',''),('quantangshi-01863','杂曲歌辞 邯郸才人嫁为厮养卒妇','李白','quantangshi','','卷2','妾本丛台女，扬蛾入丹阙。
自倚颜如花，宁知有凋歇。
一辞玉阶下，去若朝云没。
每忆邯郸城，深宫梦秋月。
君王不可见，惆怅至明发。','',''),('quantangshi-01864','杂曲歌辞 杨白花','柳宗元','quantangshi','','卷2','杨白花，风吹度江水。
坐令宫树无颜色，摇荡春光千万里。
茫茫晓日下长秋，哀歌未断城鵶起。','',''),('quantangshi-01865','杂曲歌辞 茱萸女','萬楚','quantangshi','','卷2','山阴柳家女，九日采茱萸。
复得东邻伴，双为陌上姝。
插花向高髻，结子置长裾。
作性恒迟缓，非关诧丈夫。
平明折林树，日入反城隅。
侠客邀罗袖，行人挑短书。
蛾眉自有主，年少莫踟蹰。','',''),('quantangshi-01866','杂曲歌辞 于阗采花','李白','quantangshi','','卷2','于阗采花人，自言花相似。
明妃一朝西入胡，胡中美女多羞死。
乃知汉地多名姝，胡中无花可方比。
丹青能令丑者妍，无盐翻在深宫里。
自古妬蛾眉，胡沙埋皓齿。','',''),('quantangshi-01867','杂曲歌辞 秦女卷衣','李白','quantangshi','','卷2','天子居未央，妾侍卷衣裳。
顾无紫宫宠，敢拂黄金牀。
水至亦不去，熊来尚可当。
微身奉日月，飘若萤火光。
愿君采葑菲，无以下体妨。','',''),('quantangshi-01868','杂曲歌辞 爱妾换马 一','張祜','quantangshi','','卷2','一面妖桃千里蹏，娇姿骏背价应齐。
乍牵玉勒辞金栈，催整花钿出绣闺。
去日岂无霑袂泣，归时还有顿衔嘶。
婵娟躞蹀春风里，挥手摇鞭杨柳堤。','',''),('quantangshi-01869','杂曲歌辞 爱妾换马 二','張祜','quantangshi','','卷2','绮阁香销华厩空，忍将行雨换追风。
休怜柳叶双眉翠，却爱桃花两耳红。
侍宴永辞春色里，趁朝休立漏声中。
恩劳未尽情先尽，暗泣嘶风两意同。','',''),('quantangshi-01870','杂曲歌辞 枯鱼过河泣','李白','quantangshi','','卷2','白龙改常服，偶被豫且制。
谁使尔为鱼，徒劳诉天帝。
作书报鲸鲵，勿恃风涛势。
涛落归泥沙，翻遭蝼蚁噬。
万乘慎出入，柏人以为诫。','',''),('quantangshi-01871','杂曲歌辞 饮酒乐','聶夷中','quantangshi','','卷2','日月似有事，一夜行一周。
草木犹须老，人生得无愁。
一饮解百结，再饮破百忧。
白发欺贫贱，不入醉人头。
我愿东海水，尽向杯中流。
安得阮步兵，同入醉乡游。','',''),('quantangshi-01872','杂曲歌辞 王孙游','崔國輔','quantangshi','','卷2','自与王孙别，频看黄鸟飞。
应由春草误，着处不成归。','',''),('quantangshi-01873','杂曲歌辞 发白马','李白','quantangshi','','卷2','将军发白马，旌节渡黄河。
箫鼓聒川岳，沧溟涌洪波。
武安有振瓦，易水无寒歌。
铁骑若雪山，饮流涸滹沱。
扬兵猎月窟，转战畧朝那。
倚剑登燕然，边峰列嵯峨。
萧条万里外，耕作五原多。
一扫清大漠，包虎戢金戈。','',''),('quantangshi-01874','杂曲歌辞 结韈子','李白','quantangshi','','卷2','燕南壮士吴门豪，筑中置铅鱼隐刀。
感君恩重许君命，泰山一掷轻鸿毛。','',''),('quantangshi-01875','杂曲歌辞 沐浴子','李白','quantangshi','','卷2','沐芳莫弹冠，浴兰莫振衣。
处世忌太洁，志人贵藏辉。
沧浪有钓叟，吾与尔同归。','',''),('quantangshi-01876','杂曲歌辞 三台二首 一','韋應物','quantangshi','','卷2','一年一年老去，明日后日花开。
未报长安平定，万国岂得衔杯。','',''),('quantangshi-01877','杂曲歌辞 三台二首 二','韋應物','quantangshi','','卷2','冰泮寒塘始绿，雨余百草皆生。
朝来门合无事，晚下高斋有情。','',''),('quantangshi-01878','杂曲歌辞 上皇三台','韋應物','quantangshi','','卷2','不寐倦长更，披衣出户行。
月寒秋竹冷，风切夜窗声。','',''),('quantangshi-01879','杂曲歌辞 突厥三台','韋應物','quantangshi','','卷2','雁门山上雁初飞，马邑阑中马正肥。
日旰山西逢驿使，殷勤南北送征衣。','',''),('quantangshi-01880','杂曲歌辞 宫中三台二首 一','王建','quantangshi','','卷2','鱼藻池边射鸭，芙蓉园里看花。
日色柘袍相似，不着红鸾扇遮。','',''),('quantangshi-01881','杂曲歌辞 宫中三台二首 二','王建','quantangshi','','卷2','池北池南草绿，殿前殿后花红。
天子千年万岁，未央明月清风。','',''),('quantangshi-01882','杂曲歌辞 江南三台四首 一','王建','quantangshi','','卷2','扬州桥边小妇，长干市里商人。
三年不得消息，各自拜鬼求神。','',''),('quantangshi-01883','杂曲歌辞 江南三台四首 二','王建','quantangshi','','卷2','青草湖边草色，飞猨岭上猨声。
万里三湘客到，有风有雨人行。','',''),('quantangshi-01884','杂曲歌辞 江南三台四首 三','王建','quantangshi','','卷2','树头花落花开，道上人去人来。
朝愁暮愁即老，百年几度三台。','',''),('quantangshi-01885','杂曲歌辞 江南三台四首 四','王建','quantangshi','','卷2','闻身彊健且为，头白齿落难追。
准拟百年千岁，能得几许多时。','',''),('quantangshi-01886','杂曲歌辞 筑城曲','張籍','quantangshi','','卷2','筑城去，千人万人齐抱杵。
重重土坚试行锥，军吏执鞭催作迟。
来时一年深碛里，着尽短衣渴无水。
力尽不得抛杵声，杵声未定人皆死。
家家养男当门户，今日作君城下土。','',''),('quantangshi-01887','杂曲歌辞 筑城曲五解','稹','quantangshi','','卷2','年年塞下丁，长作出塞兵。
自从冒顿彊，官筑遮虏城。
筑城须努力，城高遮得贼。
但恐贼路多，有城遮不得。
丁口传父口，莫问城坚不。
平城被虏围，汉斸城墙走。
因兹虏请和，虏往骑来多。
半疑兼半信，筑城犹嵯峨。
筑城安敢烦，愿听丁一言。
请筑鸿胪寺，兼愁虏出关。','',''),('quantangshi-01888','杂曲歌辞 筑城曲','陸龜蒙','quantangshi','','卷2','城上一掊土，手中千万杵。
筑城畏不坚，坚城在何处？
莫叹筑城劳，将军要却敌。
城高功亦高，尔命何处惜。','',''),('quantangshi-01889','杂曲歌辞 湖阴曲','溫庭筠','quantangshi','','卷2','祖龙黄须珊瑚鞭，铁骢金面青连钱。
虎髯拔劒欲成梦，日压贼营如血鲜。
海旗风急惊眠起，甲重光摇照湖水。
苍黄追骑尘外归，森索妖星阵前死。
五陵愁碧春萋萋，灞川玉马空中嘶。
羽书如电入青琐，雪腕如捶催画鞞。
白虬天子金煌铓，高临帝座回龙章。
吴波不动楚山晚，花压阑干春昼长。','',''),('quantangshi-01890','杂曲歌辞 无愁果有愁曲','李商隱','quantangshi','','卷2','东有青龙西白虎，中含福皇包世度。
玉壶渭水笑清潭，凿天不到牵牛处。
骐驎踏云天马狞，牛山撼碎珊瑚声。
秋娥点滴不成泪，十二玉楼无故钉。
推烟唾月抛千里，十番红桐一行死。
白杨别屋鬼迷人，空留暗记如蚕纸。
日暮向风牵短丝，血凝血散今谁是。','',''),('quantangshi-01891','杂曲歌辞 起夜来','施肩吾','quantangshi','','卷2','香销连理带，尘覆合欢杯。
嬾卧相思枕，愁吟起夜来。','',''),('quantangshi-01892','杂曲歌辞 起夜半','聶夷中','quantangshi','','卷2','念远心如烧，不觉中夜起。
桃花带露泛，立在月明里。','',''),('quantangshi-01893','杂曲歌辞 独不见','沈佺期','quantangshi','','卷2','卢家小妇郁金堂，海燕双栖玳瑁梁。
九月寒砧催下叶，十年征戍忆辽阳。
白狼河北音书断，丹凤城南秋夜长。
谁知含愁独不见，使妾明月照流黄。','',''),('quantangshi-01894','杂曲歌辞 独不见','王訓','quantangshi','','卷2','日晚宜春暮，风輭上林朝。
对酒近初节，开楼荡夜娇。
石桥通小涧，竹路上青霄。
持底谁见许，长愁成细腰。','',''),('quantangshi-01895','杂曲歌辞 独不见','楊巨源','quantangshi','','卷2','东风艳阳色，柳绿花如霰。
竞理同心鬟，争持合欢扇。
香传贾娘手，粉离何郎面。
最恨卷帘时，含情独不见。','',''),('quantangshi-01896','杂曲歌辞 独不见','李白','quantangshi','','卷2','白马谁家子，黄龙边塞儿。
天山三丈雪，岂是远行时。
春蕙忽秋草，莎鸡鸣曲池。
风催寒椶响，月入霜闺悲。
忆与君别年，种桃齐蛾眉。
桃今百余尺，花落成枯枝。
终然独不见，流泪空自知。','',''),('quantangshi-01897','杂曲歌辞 独不见','戴叔倫','quantangshi','','卷2','前宫路非远，旧苑春将遍。
玉户看早梅，雕梁数归燕。
身轻逐舞袖，香暖传歌扇。
自知秋风词，长侍昭阳殿。
谁信后庭人，年年独不见。','',''),('quantangshi-01898','杂曲歌辞 独不见','胡曾','quantangshi','','卷2','玉关一自有氛埃，年少从军竟未回。
门外尘凝张乐榭，水边香灭按歌台。
窗残夜月人何处？帘卷春风燕复来。
万里寂寥音信绝，寸心争忍不成灰。','',''),('quantangshi-01899','杂曲歌辞 携手曲','田娥','quantangshi','','卷2','携手共惜芳菲节，莺啼锦花满城阙。
行乐逶迤念容色，色衰祗恐君恩歇。
凤笙龙管白日阴，盈亏自感青天月。','',''),('quantangshi-01900','杂曲歌辞 大垂手','聶夷中','quantangshi','','卷2','金刀翦轻云，盘用黄金缕。
装束赵飞燕，教来掌上舞。
舞罢飞燕死，片片随风去。','',''),('quantangshi-01901','杂曲歌辞 夜夜曲','不詳','quantangshi','','卷2','愁人夜独伤，灭烛卧兰房。
祗恐多情月，旋来照妾牀。','',''),('quantangshi-01902','杂曲歌辞 夜夜曲','王偃','quantangshi','','卷2','北斗星移银汉低，班姬愁思凤城西。
青槐陌上人行绝，明月楼前乌夜啼。','',''),('quantangshi-01903','杂曲歌辞 夜夜曲','僧貫休','quantangshi','','卷2','蟪蛄切切风骚骚，芙蓉喷香蟾蜍高。
孤灯耿耿征妇劳，更深扑落金错刀。','',''),('quantangshi-01904','杂曲歌辞 秋夜长','王勃','quantangshi','','卷2','秋夜长，殊未央。
月明白露澄清光，层城绮阁遥相望。
遥相望，川无梁。
北风受节雁南翔，崇兰委质时菊芳。
鸣环曳履出长廊，为君秋夜捣衣裳。
纤罗对凤皇，丹绮双鸳鸯。
调砧乱杵思自伤，思自伤，征夫万里戍他乡。
鹤关音信断，龙门道路长。
所在天一方，寒衣徒自香。','',''),('quantangshi-01905','杂曲歌辞 秋夜长','張籍','quantangshi','','卷2','秋天如水夜未央，天汉东西月色光。
愁人不寐畏枕席，暗虫唧唧遶我傍。
荒城为村无更声，起看北斗天未明。
白露满田风褭褭，千声万声鹖鸟鸣。','',''),('quantangshi-01906','杂曲歌辞 秋夜曲二首 一','王建','quantangshi','','卷2','天清漏长霜泊泊，兰绿收荣桂膏涸。
高楼云鬟弄婵娟，古瑟暗断秋风弦。
玉关遥隔万里道，金刀不翦双泪泉。
香囊火死香气少，向帷合眼何时晓？
城乌作营嗁野月，秦川少妇生离别。','',''),('quantangshi-01907','杂曲歌辞 秋夜曲二首 二','王建','quantangshi','','卷2','秋灯向壁掩洞房，良人此夜直明光。
天河悠悠漏水长，南楼北斗两相当。','',''),('quantangshi-01908','杂曲歌辞 秋夜曲','張仲素','quantangshi','','卷2','丁丁漏水夜何长，漫漫轻云露月光。
秋壁暗虫通夕响，寒衣未寄莫飞霜。','',''),('quantangshi-01909','杂曲歌辞 秋夜曲','王涯','quantangshi','','卷2','桂魄初生秋露微，轻罗已薄未更衣。
银筝夜久殷勤弄，心怯空房不忍归。','',''),('quantangshi-01910','杂曲歌辞 夜坐吟','李白','quantangshi','','卷2','冬夜夜寒觉夜长，沈吟久坐坐北堂。
冰合井泉月入闺，青缸凝明照悲嗁。
青缸灭，嗁转多，掩妾泪，听君歌。
歌有声，妾有情，情声合，两无违。
一语不入意，从君万曲梁尘飞。','',''),('quantangshi-01911','杂曲歌辞 夜坐吟','李白','quantangshi','','卷2','踏踏马头谁见过，眼看北斗直天河。
西风罗幕生翠波，铅华笑妾颦青蛾。
为君起唱长相思，帘外严霜皆倒飞。
明星烂烂东方陲，红霞稍出东南涯，陆郎去矣乘斑骓。','',''),('quantangshi-01912','杂曲歌辞 夜寒吟','鮑溶','quantangshi','','卷2','九衢金吾夜行行，上宫玉漏遥分明。
霜飙乘阴扫地起，旅鸿迷雪绕枕声。
远人归梦既不成，留家惜夜欢心发。
罗幕画堂深皎洁，兰烟对酒客几人。
兽火扬光二三月，细腰楚姬丝竹间。
白紵长袖歌闲闲，岂识苦寒损朱颜。','',''),('quantangshi-01913','杂曲歌辞 定情篇','喬知之','quantangshi','','卷2','共君结新婚，岁寒心未卜。
相与游春园，各随情所逐。
君念菖蒲花，妾感苦寒竹。
菖花多艳姿，寒竹有贞叶。
此时妾比君，君心不如妾。
簪玉步河堤，妖韶援绿{𥫗/戢}。
凫雁将子游，莺燕从双栖。
君念春光好，妾向春光嗁。
君时不得意，妾弃还金闺。
结言本同心，悲懽何未齐。
怨咽前致辞，愿得中所悲。
人间丈夫易，世路妇难为。
始经天月照，终若流星驰。
长信佳丽人，失意非蛾眉。
庐江小吏妇，非关织作迟。
本愿长相对，今已长相思。
复有游宦子，结援从梁陈。
燕居崇三朝，去来历九春。
誓心妾终始，蚕桑奉所亲。
归愿未克从，黄金赠路人。
洁妇怀明义，从泛河之津。
于今千万年，谁当问水滨。
更忆倡家楼，夫壻事封侯。
去时思灼灼，去罢心悠悠。
不怜妾岁晏，千载陇西头。
以兹常惕惕，百虑恒盈积。
由来共结褵，几人同匪石。
故岁雕梁燕，双去今来只。
今日玉庭梅，朝红暮成碧。
碧荣始芬敷，黄叶已[淅]沥。
何用念芳春，芳春有流易。
何用重懽娱，懽娱俄戚戚。
家本巫山阳，归去路何长。
敍言情未尽，采菉已盈筐。
桑榆日映物，草色盈高冈。
下有碧流水，上有丹桂香。
桂枝不须折，碧流清且洁。
赠君比芳菲，受惠常不灭。
赠君泪潺湲，相思无断绝。
妾有秦家镜，宝匣装珠玑。
鉴来年二八，不记易阴晖。
妾无光寂寂，委照影依依。
今日持为赠，相识莫相违。','',''),('quantangshi-01914','杂曲歌辞 定情乐','施肩吾','quantangshi','','卷2','敢嗟君不怜，自是命不谐。
着破三条裾，却还双股钗。','',''),('quantangshi-01915','杂曲歌辞 春江曲','郭元振','quantangshi','','卷2','江水春沈沈，上有双竹林。
竹叶坏水色，郎亦坏人心。','',''),('quantangshi-01916','杂曲歌辞 春江曲','張籍','quantangshi','','卷2','春江无云潮水平，蒲心出水凫雏鸣。
长干夫壻爱远行，自染春衣缝已成。
妾身生长金陵侧，去年随夫住江北。
春来未到父母家，舟小风多渡不得。
欲辞舅姑先问人，私向江头祭水神。','',''),('quantangshi-01917','杂曲歌辞 春江曲','王涯','quantangshi','','卷2','摇漾越江春，相将看白苹。
归时不觉夜，出浦月随人。','',''),('quantangshi-01918','杂曲歌辞 春江曲二首 一','張仲素','quantangshi','','卷2','家寄征江岸，征人几岁游。
不知潮水信，每日到沙头。','',''),('quantangshi-01919','杂曲歌辞 春江曲二首 二','張仲素','quantangshi','','卷2','乘晓南湖去，参差叠浪横。
前洲在何处？雾里雁嘤嘤。','',''),('quantangshi-01920','杂曲歌辞 江上曲','李嘉祐','quantangshi','','卷2','江上澹澹芙蓉花，江口蛾眉独浣纱。
可怜应是阳台女，坐对鸬鷀娇不语。
掩面羞看北地人，回首忽作空山雨。
苍梧秋色不堪论，千载依依帝子魂。
君看峯上斑斑竹，尽是湘妃泣泪痕。','',''),('quantangshi-01921','杂曲歌辞 桃花曲','顧況','quantangshi','','卷2','魏帝宫人舞凤楼，隋家天子泛龙舟。
君王夜醉春眠[晏]，不觉桃花逐水流。','',''),('quantangshi-01922','杂曲歌辞 树中草','李白','quantangshi','','卷2','鸟衔野田草，误入枯桑里。
客土植危根，逢春犹不死。
草木虽无情，因依尚可生。
如何同枝叶，各自有枯荣。','',''),('quantangshi-01923','杂曲歌辞 树中草','張祜','quantangshi','','卷2','青青树中草，托根非不危。
草生树却死，荣枯君可知。','',''),('quantangshi-01924','杂曲歌辞 春游吟','李章','quantangshi','','卷2','初春遍芳甸，千里霭盈瞩。
美人摘新英，步步玩春绿。
所思杳何处，宛在吴江曲。
可怜不得共芳菲，日暮归来泪满衣。','',''),('quantangshi-01925','杂曲歌辞 春游乐','施肩吾','quantangshi','','卷2','一年三百六十日，赏心那似春中物。
草迷曲坞花满园，东家少年西家出。','',''),('quantangshi-01926','杂曲歌辞 春游乐二首 一','李端','quantangshi','','卷2','游童苏合带，倡女蒲葵扇。
初日映城时，相思忽相见。
褰裳踏露草，理鬓回花面。
薄暮不同归，留情此芳甸。','',''),('quantangshi-01927','杂曲歌辞 春游乐二首 二','李端','quantangshi','','卷2','柘弹连钱马，银钩妥堕鬟。
采桑春陌上，踏草夕阳间。
意合辞先露，心诚貌却闲。
明朝若相忆，云雨出巫山。','',''),('quantangshi-01928','杂曲歌辞 春游曲三首 一','張仲素','quantangshi','','卷2','烟柳飞轻絮，风榆落小钱。
蒙蒙百花里，罗绮竞秋千。','',''),('quantangshi-01929','杂曲歌辞 春游曲三首 二','張仲素','quantangshi','','卷2','骋望登香阁，争高下砌台。
林间踏青去，席上意钱来。','',''),('quantangshi-01930','杂曲歌辞 春游曲三首 三','張仲素','quantangshi','','卷2','行乐三春节，林花百和香。
当年重意气，先占鬬鸡场。','',''),('quantangshi-01931','杂曲歌辞 乐府二首 一','劉言史','quantangshi','','卷2','花颔红鬃一向偏，绿槐香陌欲朝天。
仍嫌众里娇行疾，傍镫深藏白玉鞭。','',''),('quantangshi-01932','杂曲歌辞 乐府二首 二','劉言史','quantangshi','','卷2','喷珠团香小桂条，玉鞭兼赐霍嫖姚。
弄影便从天禁出，碧蹏声碎五门桥。','',''),('quantangshi-01933','杂曲歌辞 乐府','顧況','quantangshi','','卷2','暖谷春光至，宸游近甸荣。
云随天仗转，风入御帘轻。
翠盖浮佳气，朱楼倚太清。
朝臣冠劒退，宫女管弦迎。
细草承雕辇，繁花入幔城。
文房开圣藻，武卫宿天营。
玉醴随觞至，铜壶逐漏行。
五星含土德，万姓彻中声。
亲祀先崇典，躬推示劝耕。
国风新正乐，农器近消兵。
道德关河固，刑章日月明。
野人同鸟兽，率舞感升平。','',''),('quantangshi-01934','杂曲歌辞 乐府','權德輿','quantangshi','','卷2','光风澹荡百花吐，楼上朝朝学歌舞。
身年二八壻侍中，幼妹承恩兄尚主。
绿窗珠箔绣鸳鸯，侍婢先焚百和香。
莺嗁日出不知曙，寂寂罗帏春梦长。','',''),('quantangshi-01935','杂曲歌辞 乐府三首 一','孟郊','quantangshi','','卷2','莲子不可得，荷花生水中。
犹胜道傍柳，无事荡春风。','',''),('quantangshi-01936','杂曲歌辞 乐府三首 二','孟郊','quantangshi','','卷2','渌萍与荷叶，同时一水中。
风吹荷叶在，渌萍西复东。','',''),('quantangshi-01937','杂曲歌辞 乐府三首 三','孟郊','quantangshi','','卷2','莲花未开时，苦心终日卷。
春水徒荡漾，荷花未开展。','',''),('quantangshi-01938','杂曲歌辞 乐府','陸長源','quantangshi','','卷2','芙蓉初出水，菡萏露中花。
风吹着枯木，无奈值空槎。','',''),('quantangshi-01939','杂曲歌辞 杂曲','王勃','quantangshi','','卷2','智琼神女，来访文君。
蛾眉始约，罗袖初薰。
歌齐曲韵，舞乱行分。
若向阳台荐枕，何啻得胜朝云。','',''),('quantangshi-01940','杂曲歌辞 古曲五首 一','施肩吾','quantangshi','','卷2','可怜江北女，惯唱江南曲。
摇荡木兰舟，双凫不成浴。','',''),('quantangshi-01941','杂曲歌辞 古曲五首 二','施肩吾','quantangshi','','卷2','郎为匕上香，妾为笼上灰。
归时虽暖热，去罢生尘埃。','',''),('quantangshi-01942','杂曲歌辞 古曲五首 三','施肩吾','quantangshi','','卷2','夜裁鸳鸯绮，朝织蒲桃绫。
欲试一寸心，待缝三尺冰。','',''),('quantangshi-01943','杂曲歌辞 古曲五首 四','施肩吾','quantangshi','','卷2','怜时鱼得水，怨罢商与参。
不如山支子，却解结同心。','',''),('quantangshi-01944','杂曲歌辞 古曲五首 五','施肩吾','quantangshi','','卷2','红颜感暮花，白日同流水。
思君如孤灯，一夜一心死。','',''),('quantangshi-01945','杂曲歌辞 高句丽','李白','quantangshi','','卷2','金花折风帽，白马小迟回。
翩翩舞广袖，似鸟海东来。','',''),('quantangshi-01946','杂曲歌辞 摩多楼子','李賀','quantangshi','','卷2','玉塞去金人，二万四千里。
风吹沙作云，一时渡辽水。
天白水如练，甲丝双串断。
行行莫苦辛，城月犹残半。
晓气朔烟上，趢趗胡马蹏。
行人听水别，隔陇长东西。','',''),('quantangshi-01947','杂曲歌辞 辽东行','王建','quantangshi','','卷2','辽东万里辽水曲，古戍无城复无屋。
黄云盖地雪作山，不惜黄金买衣服。
战回各自收弓箭，正西回面家乡远。
年年郡县送征人，将与辽东作丘坂。
宁为草木乡中生，有身不向辽东行。','',''),('quantangshi-01948','杂曲歌辞 渡辽水','王建','quantangshi','','卷2','渡辽水，此去咸阳五千里。
来时父母知隔生，重着衣裳如送死。
亦有白骨归咸阳，营家各与题本乡。
身在应无回渡日，驻马相看辽水傍。','',''),('quantangshi-01949','杂曲歌辞 昔昔盐 垂柳覆金堤','趙嘏','quantangshi','','卷2','新年垂柳色，袅袅对空闺。
不畏芳菲好，自缘离别嗁。
因风飘玉户，向日映金堤。
驿使何时度？还将赠陇西。','',''),('quantangshi-01950','杂曲歌辞 昔昔盐 蘼芜叶复齐','趙嘏','quantangshi','','卷2','提筐红叶下，度日采蘼芜。
掬翠香盈袖，看花忆故夫。
叶齐谁复见，风暖恨偏孤。
一被春光累，容颜与昔殊。','',''),('quantangshi-01951','杂曲歌辞 昔昔盐 水溢芙蓉沼','趙嘏','quantangshi','','卷2','渌沼春光后，青青草色浓。
绮罗惊翡翠，暗粉妒芙蓉。
云遍窗前见，荷翻镜里逢。
将心托流水，终日渺无从。','',''),('quantangshi-01952','杂曲歌辞 昔昔盐 花飞桃李蹊','趙嘏','quantangshi','','卷2','远期难可托，桃李自依依。
花径无容迹，戎裘未下机。
随风开又落，度日扫还飞。
欲折枝枝赠，那知归不归。','',''),('quantangshi-01953','杂曲歌辞 昔昔盐 采桑秦氏女','趙嘏','quantangshi','','卷2','南陌采桑出，谁知妾姓秦。
独怜倾国貌，不负早莺春。
珠履荡花湿，龙钩折桂新。
使君那驻马，自有侍中人。','',''),('quantangshi-01954','杂曲歌辞 昔昔盐 织锦窦家妻','趙嘏','quantangshi','','卷2','当年谁不羡，分作窦家妻。
锦字行行苦，罗帷日日嗁。
岂知登陇远，祗恨下机迷。
直候阳关使，殷勤寄海西。','',''),('quantangshi-01955','杂曲歌辞 昔昔盐 关山别荡子','趙嘏','quantangshi','','卷2','那堪闻荡子，迢遰涉关山。
肠为马嘶断，衣从泪滴斑。
愁看塞上路，讵惜镜中颜。
傥见征西雁，应传一字还。','',''),('quantangshi-01956','杂曲歌辞 昔昔盐 风月守空闺','趙嘏','quantangshi','','卷2','良人犹远戍，耿耿夜闺空。
绣户流宵月，罗帷坐晓风。
魂飞沙帐北，肠断玉关中。
尚自无消息，锦衾那得同。','',''),('quantangshi-01957','杂曲歌辞 昔昔盐 恒敛千金笑','趙嘏','quantangshi','','卷2','玉颜恒自敛，羞出镜台前。
早惑阳城客，今悲华锦筵。
从军人更远，投喜鹊空传。
夫壻交河北，迢迢路几千。','',''),('quantangshi-01958','杂曲歌辞 昔昔盐 长垂双玉嗁','趙嘏','quantangshi','','卷2','双双红泪堕，度日暗中嗁。
雁出居延北，人犹辽海西。
向灯垂玉枕，对月洒金闺。
不惜罗衣湿，惟愁归意迷。','',''),('quantangshi-01959','杂曲歌辞 昔昔盐 蟠龙随镜隐','趙嘏','quantangshi','','卷2','鸾镜无由照，蛾眉岂忍看。
不知愁发换，空见隐龙蟠。
那惬红颜改，偏伤白日残。
今朝窥玉匣，双泪落阑干。','',''),('quantangshi-01960','杂曲歌辞 昔昔盐 彩凤逐帷低','趙嘏','quantangshi','','卷2','巧绣双飞凤，朝朝伴下帷。
春花那见照，暮色已频欺。
欲卷思君处，将嗁裛泪时。
何年征戍客？传语报佳期。','',''),('quantangshi-01961','杂曲歌辞 昔昔盐 惊魂同夜鹊','趙嘏','quantangshi','','卷2','万里无人见，众情难与论。
思君常入梦，同鹊屡惊魂。
孤寝红罗帐，双嗁玉筯痕。
妾心甘自保，岂复暂忘恩。','',''),('quantangshi-01962','杂曲歌辞 昔昔盐 倦寝听晨鸡','趙嘏','quantangshi','','卷2','去去边城骑，愁眠掩夜闺。
披衣窥落月，拭泪待鸣鸡。
不愤连年别，那堪长夜嗁。
功成应自恨，早晚发辽西。','',''),('quantangshi-01963','杂曲歌辞 昔昔盐 暗牖悬蛛网','趙嘏','quantangshi','','卷2','暗中蛛网织，历乱绮窗前。
万里终无信，一条徒自悬。
分从珠露滴，愁见隙风牵。
妾意何聊赖，看看剧断弦。','',''),('quantangshi-01964','杂曲歌辞 昔昔盐 空梁落燕泥','趙嘏','quantangshi','','卷2','春至今朝燕，花时伴独嗁。
飞斜珠箔隔，语近画梁低。
帷卷闲窥户，牀空暗落泥。
谁能长对此，双去复双栖。','',''),('quantangshi-01965','杂曲歌辞 昔昔盐 前年过代北','趙嘏','quantangshi','','卷2','代北几千里，前年又复经。
燕山云自合，胡塞草应青。
铁马喧鼙鼓，蛾眉怨锦屏。
不知羌笛曲，掩泪若为听。','',''),('quantangshi-01966','杂曲歌辞 昔昔盐 今岁往辽西','趙嘏','quantangshi','','卷2','万里飞书至，闻君已渡辽。
祗谙新别苦，忘却旧时娇。
烽戍年将老，红颜日向雕。
胡沙兼汉苑，相望几迢迢。','',''),('quantangshi-01967','杂曲歌辞 昔昔盐 一去无还意','趙嘏','quantangshi','','卷2','良人征绝域，一去不言还。
百战攻胡虏，三冬阻玉关。
萧萧边马思，猎猎戍旗闲。
独把千重恨，连年未解颜。','',''),('quantangshi-01968','杂曲歌辞 昔昔盐 那能惜马蹏','趙嘏','quantangshi','','卷2','云中路杳杳，江畔草萋萋。
妾久垂珠泪，君何惜马蹏。
边风悲晓角，营月怨春鼙。
未道休征战，愁眉又复低。','',''),('quantangshi-01969','杂曲歌辞 水调 歌第一','不詳','quantangshi','','卷2','平沙落日大荒西，陇上明星高复低。
孤山几处看烽火，壮士连营候鼓鼙。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-01970','杂曲歌辞 水调 歌第二','不詳','quantangshi','','卷2','猛将关西意气多，能骑骏马弄雕戈。
金鞍宝铰精神出，笛倚新翻水调歌。','',''),('quantangshi-01971','杂曲歌辞 水调 歌第三','不詳','quantangshi','','卷2','王孙别上绿珠轮，不羡名公乐此身。
户外碧潭春洗马，楼前红烛夜迎人。','',''),('quantangshi-01972','杂曲歌辞 水调 歌第四','不詳','quantangshi','','卷2','陇头一叚气长秋，举目萧条总是愁。
秖为征人多下泪，年年添作断肠流。','',''),('quantangshi-01973','杂曲歌辞 水调 歌第五','不詳','quantangshi','','卷2','双带仍分影，同心巧结香。
不应须换彩，意欲媚浓妆。','',''),('quantangshi-01974','杂曲歌辞 水调 入破第一','不詳','quantangshi','','卷2','细草河边一雁飞，黄龙关里挂戎衣。
为受明王恩宠甚，从事经年不复归。','',''),('quantangshi-01975','杂曲歌辞 水调 入破第二','不詳','quantangshi','','卷2','锦城丝管日纷纷，半入江风半入云。
此曲只应天上去，人间能得几回闻。','',''),('quantangshi-01976','杂曲歌辞 水调 入破第三','不詳','quantangshi','','卷2','昨夜遥欢出建章，今朝缀赏度昭阳。
传声莫闭黄金屋，为报先开白玉堂。','',''),('quantangshi-01977','杂曲歌辞 水调 入破第四','不詳','quantangshi','','卷2','日晚笳声咽戍楼，陇云漫漫水东流。
行人万里向西去，满目关山空恨愁。','',''),('quantangshi-01978','杂曲歌辞 水调 入破第五','不詳','quantangshi','','卷2','千年一遇圣明朝，愿对君王舞细腰。
乍可当熊任生死，谁能伴凤上云霄。','',''),('quantangshi-01979','杂曲歌辞 水调 入破第六彻','不詳','quantangshi','','卷2','闺烛无人影，罗屏有梦魂。
近来音耗绝，终日望君门。','',''),('quantangshi-01980','杂曲歌辞 水调','吳融','quantangshi','','卷2','凿河千里走黄沙，浮殿西来动日华。
可道新声是亡国，且贪惆怅后庭花。','',''),('quantangshi-01981','杂曲歌辞 堂堂 一','李義府','quantangshi','','卷2','镂月成歌扇，裁云作舞衣。
自怜回雪影，好取洛川归。','',''),('quantangshi-01982','杂曲歌辞 堂堂 二','李義府','quantangshi','','卷2','嬾正鸳鸯被，羞褰玳瑁牀。
春风别有意，密处也寻香。','',''),('quantangshi-01983','杂曲歌辞 堂堂','李賀','quantangshi','','卷2','堂堂复堂堂，红脱梅灰香。
十年粉蠹生画梁，饥虫不食推碎黄。
蕙花已老桃叶长，禁院悬帘隔御光。
华清源中礜石汤，裴回百凤随君王。','',''),('quantangshi-01984','杂曲歌辞 凉州 歌第一','不詳','quantangshi','','卷2','汉家宫里柳如丝，上苑桃花连碧池。
圣寿已传千岁酒，天文更赏百僚诗。','',''),('quantangshi-01985','杂曲歌辞 凉州 歌第二','不詳','quantangshi','','卷2','朔风吹叶雁门秋，万里烟尘昏戍楼。
征马长思青海北，胡笳夜听陇山头。','',''),('quantangshi-01986','杂曲歌辞 凉州 歌第三','不詳','quantangshi','','卷2','开箧泪霑襦，见君前日书。
夜台空寂寞，犹见紫云车。','',''),('quantangshi-01987','杂曲歌辞 凉州 排遍第一','不詳','quantangshi','','卷2','三秋陌上早霜飞，羽猎平田浅草齐。
锦背苍鹰初出按，五花骢马喂来肥。','',''),('quantangshi-01988','杂曲歌辞 凉州 排遍第二','不詳','quantangshi','','卷2','鸳鸯殿里笙歌起，翡翠楼前出舞人。
唤上紫微三五夕，圣明方寿一千春。','',''),('quantangshi-01989','杂曲歌辞 凉州词','耿[湋]','quantangshi','','卷2','国使翩翩随斾旌，陇西岐路足荒城。
毡裘牧马胡雏小，日暮蕃歌三两声。','',''),('quantangshi-01990','杂曲歌辞 凉州词 一','張籍','quantangshi','','卷2','边城暮雨雁飞低，芦笋初生渐欲齐。
无数铃声遥过碛，应驮白练到安西。','',''),('quantangshi-01991','杂曲歌辞 凉州词 二','張籍','quantangshi','','卷2','古镇城门白碛开，胡兵往往傍沙堆。
巡边使客行应早，每待平安火到来。','',''),('quantangshi-01992','杂曲歌辞 凉州词 三','張籍','quantangshi','','卷2','凤林关里水东流，白草黄榆六十秋。
边将皆承主恩泽，无人解道取凉州。','',''),('quantangshi-01993','杂曲歌辞 凉州词','薛逢','quantangshi','','卷2','昨夜蕃兵报国讐，沙州都护破凉州。
黄河九曲今归汉，塞外纵横战血流。','',''),('quantangshi-01994','杂曲歌辞 太和 第一','不詳','quantangshi','','卷2','国门卿相旧山庄，圣主移来宴绿芳。
帘外辗为车马路，花间踏出舞人场。','',''),('quantangshi-01995','杂曲歌辞 太和 第二','不詳','quantangshi','','卷2','国鸟尚含天乐转，寒风犹带御衣香。
为报碧潭明月夜，会须留赏待君王。','',''),('quantangshi-01996','杂曲歌辞 太和 第三','不詳','quantangshi','','卷2','庭前鹊遶相思树，井上莺歌争刺桐。
含情少妇悲春草，多是良人学转蓬。','',''),('quantangshi-01997','杂曲歌辞 太和 第四','不詳','quantangshi','','卷2','塞北江南共一家，何须泪落怨黄沙。
春酒半酣千日醉，庭前还有落梅花。','',''),('quantangshi-01998','杂曲歌辞 太和 第五彻','不詳','quantangshi','','卷2','我皇膺运太平年，四海朝宗会百川。
自古几多明圣主，不如今帝胜尧天。','',''),('quantangshi-01999','杂曲歌辞 伊州 歌第一','蓋嘉運','quantangshi','','卷2','秋风明月独离居，荡子从戎十载余。
征人去日殷勤属，归雁来时数寄书。','',''),('quantangshi-02000','杂曲歌辞 伊州 歌第二','蓋嘉運','quantangshi','','卷2','彤闱晓辟万鞍回，玉辂春游薄晚开。
渭北清光摇草树，州南嘉景入楼台。','',''),('quantangshi-02001','杂曲歌辞 伊州 歌第三','蓋嘉運','quantangshi','','卷3','闻道黄花戍，频年不解兵。
可怜闺里月，偏照汉家营。','',''),('quantangshi-02002','杂曲歌辞 伊州 歌第四','蓋嘉運','quantangshi','','卷3','千里东归客，无心忆旧游。
挂帆游白水，高枕到青州。','',''),('quantangshi-02003','杂曲歌辞 伊州 歌第五','蓋嘉運','quantangshi','','卷3','桂殿江乌对，雕屏海燕重。
秖应多酿酒，醉罢乐高钟。','',''),('quantangshi-02004','杂曲歌辞 伊州 入破第一','蓋嘉運','quantangshi','','卷3','千门今夜晓初晴，万里天河彻帝京。
璨璨繁星驾秋色，棱棱霜气韵钟声。','',''),('quantangshi-02005','杂曲歌辞 伊州 入破第二','蓋嘉運','quantangshi','','卷3','长安二月柳依依，西出流沙路渐微。
阏氏山上春光少，相府庭边驿使稀。','',''),('quantangshi-02006','杂曲歌辞 伊州 入破第三','蓋嘉運','quantangshi','','卷3','三秋大漠冷溪山，八月严霜变草颜。
卷斾风行宵渡碛，衔枚电扫晓应还。','',''),('quantangshi-02007','杂曲歌辞 伊州 入破第四','蓋嘉運','quantangshi','','卷3','行乐三阳早，芳菲二月春。
闺中红粉态，陌上看花人。','',''),('quantangshi-02008','杂曲歌辞 伊州 入破第五','蓋嘉運','quantangshi','','卷3','君住孤山下，烟深夜径长。
辕门渡绿水，游苑遶垂杨。','',''),('quantangshi-02009','杂曲歌辞 陆州 歌第一','不詳','quantangshi','','卷3','分野中峰变，阴晴众壑殊。
欲投人处宿，隔浦问樵夫。','',''),('quantangshi-02010','杂曲歌辞 陆州 歌第二','不詳','quantangshi','','卷3','共得烟霞径，东归山水游。
萧萧望林夜，寂寂坐中秋。','',''),('quantangshi-02011','杂曲歌辞 陆州 歌第三','不詳','quantangshi','','卷3','香气传空满，妆花映薄红。
歌声天仗外，舞态御楼中。','',''),('quantangshi-02012','杂曲歌辞 陆州 排遍第一','不詳','quantangshi','','卷3','树发花如锦，莺嗁柳若丝。
更逢欢宴地，愁见别离时。','',''),('quantangshi-02013','杂曲歌辞 陆州 排遍第二','不詳','quantangshi','','卷3','明月照秋叶，西风响夜砧。
彊言徒自乱，往事不堪寻。','',''),('quantangshi-02014','杂曲歌辞 陆州 排遍第三','不詳','quantangshi','','卷3','坐对银釭晓，停留玉筯痕。
君门常不见，无处谢前恩。','',''),('quantangshi-02015','杂曲歌辞 陆州 排遍第四','不詳','quantangshi','','卷3','曙月当窗满，征人出塞遥。
画楼终日闭，清管为谁调。','',''),('quantangshi-02016','杂曲歌辞 簇拍陆州','不詳','quantangshi','','卷3','西去轮台万里余，故乡音耗日应疎。
陇山鹦鹉能言语，为报闺人数寄书。','',''),('quantangshi-02017','杂曲歌辞 石州','不詳','quantangshi','','卷3','自从君去远巡边，终日罗帏独自眠。
看花情转切，揽镜泪如泉。
一自离君后，嗁多双脸穿。
何时狂虏灭，免得更留连。','',''),('quantangshi-02018','杂曲歌辞 盖罗缝 一','不詳','quantangshi','','卷3','秦时明月汉时关，万里征人尚未还。
但愿龙庭神将在，不教胡马渡阴山。','',''),('quantangshi-02019','杂曲歌辞 盖罗缝 二','不詳','quantangshi','','卷3','音书杜绝白狼西，桃李无颜黄鸟嗁。
寒鸟春深归去尽，出门肠断草萋萋。','',''),('quantangshi-02020','杂曲歌辞 双带子','不詳','quantangshi','','卷3','私言切语谁人会，海燕双飞绕画梁。
君学秋胡不相识，妾亦无心去采桑。','',''),('quantangshi-02021','杂曲歌辞 昆仑子','不詳','quantangshi','','卷3','[扬]子谭经去，淮王载酒过。
醉来嗁鸟唤，坐久落花多。','',''),('quantangshi-02022','杂曲歌辞 祓禊曲 一','不詳','quantangshi','','卷3','昨见春条绿，那知秋叶黄。
蝉声犹未断，寒雁已成行。','',''),('quantangshi-02023','杂曲歌辞 祓禊曲 二','不詳','quantangshi','','卷3','金谷园中柳，春来已舞腰。
那堪好风景，独上洛阳桥。','',''),('quantangshi-02024','杂曲歌辞 祓禊曲 三','不詳','quantangshi','','卷3','何处堪愁思，花间长乐宫。
君王不重客，泣泪向春风。','',''),('quantangshi-02025','杂曲歌辞 上巳乐','張祜','quantangshi','','卷3','猩猩血彩系头标，天上齐声举画桡。
却是内人争意切，六宫罗袖一时招。','',''),('quantangshi-02026','杂曲歌辞 穆护砂','不詳','quantangshi','','卷3','玉管朝朝弄，清歌日日新。
折花当驿路，寄与陇头人。','',''),('quantangshi-02027','杂曲歌辞 思归乐 一','不詳','quantangshi','','卷3','晚日催弦管，春风入绮罗。
杏花如有意，偏落舞衫多。','',''),('quantangshi-02028','杂曲歌辞 思归乐 二','不詳','quantangshi','','卷3','万里春应尽，三江雁亦稀。
连天汉水广，孤客未言归。','',''),('quantangshi-02029','杂曲歌辞 金殿乐','不詳','quantangshi','','卷3','入夜秋砧动，千门起四邻。
不缘楼上月，应为陇头人。','',''),('quantangshi-02030','杂曲歌辞 胡渭州 一','不詳','quantangshi','','卷3','亭亭孤月照行舟，寂寂长江万里流。
乡国不知何处是？云山漫漫使人愁。','',''),('quantangshi-02031','杂曲歌辞 胡渭州 二','不詳','quantangshi','','卷3','杨柳千寻色，桃花一苑芳。
风吹入帘里，惟有惹衣香。','',''),('quantangshi-02032','杂曲歌辞 戎浑','不詳','quantangshi','','卷3','风劲角弓鸣，将军猎渭城。
草枯鹰眼疾，雪尽马蹏轻。','',''),('quantangshi-02033','杂曲歌辞 墙头花 一','不詳','quantangshi','','卷3','蟋蟀鸣洞房，梧桐落金井。
为君裁舞衣，天寒翦刀冷。','',''),('quantangshi-02034','杂曲歌辞 墙头花 二','不詳','quantangshi','','卷3','妾有罗衣裳，秦王在时作。
为舞春风多，秋来不堪着。','',''),('quantangshi-02035','杂曲歌辞 采桑','不詳','quantangshi','','卷3','自古多征战，由来尚甲兵。
