INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02186','杂曲歌辞 杨柳枝 一','和凝','quantangshi','','卷3','软碧摇烟似送人，映花时把翠眉嚬。
