轻爵禄，慕玄虚，莫道渔人只为鱼。','',''),('quantangshi-02335','杂歌谣辞 渔父歌 二','李珣','quantangshi','','卷3','避世垂纶不记年，官高争得似君闲。
倾白酒，对青山，笑指柴门待月还。','',''),('quantangshi-02336','杂歌谣辞 渔父歌 三','李珣','quantangshi','','卷3','棹警鸥飞水溅袍，影侵潭面柳垂绦。
终日醉，绝尘劳，曾见钱塘八月涛。','',''),('quantangshi-02337','杂歌谣辞 鸡鸣曲','王建','quantangshi','','卷3','鸡初鸣，明星照东屋。
鸡再鸣，红霞生海腹。
百官待漏双阙前，圣人亦挂山龙服。
宝钗命妇灯下起，环佩玲珑晓光里。
直内初烧玉[案]香，司更尚滴铜壶水。
金吾卫里直郎妻，到明不睡听晨鸡。
天头日月相送迎，夜栖旦鸣人不迷。','',''),('quantangshi-02338','杂歌谣辞 鸡鸣曲','李廓','quantangshi','','卷3','星稀月没上五更，胶胶角角鸡初鸣。
征人牵马出门立，辞妾欲向安西行。
再鸣引颈檐头下，月中角声催上马。
才分地色第三鸣，旌旗红尘已出城。
妇人上城乱招手，夫壻不闻遥哭声。
长恨鸡鸣别时苦，不遣鸡栖近窗户。','',''),('quantangshi-02339','杂歌谣辞 吴楚歌','張籍','quantangshi','','卷3','庭前春鸟啄林声，红夹罗襦缝未成。
今朝社日停针线，起向朱樱树下行。','',''),('quantangshi-02340','杂歌谣辞 李夫人歌 一','李商隱','quantangshi','','卷3','一带不结心，两股方安髻。
慙愧白茅人，月没教星替。','',''),('quantangshi-02341','杂歌谣辞 李夫人歌 二','李商隱','quantangshi','','卷3','剩结茱萸枝，多擘秋莲的。
独自有波光，彩囊盛不得。','',''),('quantangshi-02342','杂歌谣辞 李夫人歌 三','李商隱','quantangshi','','卷3','蛮丝系条脱，妍眼和香屑。
寿宫不惜铸南人，柔肠早被秋波割。
清澄有余幽素香，鳏鱼渴凤真珠房。
不知瘦骨类冰井，更许夜帘通晓霜。
土花漠碧云[茫茫]，黄河欲尽天苍黄。','',''),('quantangshi-02343','杂歌谣辞 李夫人歌','李賀','quantangshi','','卷3','紫皇宫殿重重开，夫人飞入琼瑶台。
绿香绣帐何时歇，青云无光宫水咽。
翩联桂花坠秋月，孤鸾惊啼商丝发。
红璧阑珊悬佩璫，歌台小妓遥相望。
玉蟾滴水鸡人唱，露华兰叶参差光。','',''),('quantangshi-02344','杂歌谣辞 李夫人歌','鮑溶','quantangshi','','卷3','璇闺羽帐华烛陈，方士夜降夫人神。
葳蕤半露芙蓉色，窈窕将期环佩身。
丽如三五月，可望难亲近。
嚬黛含犀竟不言，春思秋怨谁能问。
欲求巧笑如生时，歌尘在空瑟衔丝。
神来未及梦相见，帝比初亡心更悲。
爱之欲其生又死，东流万代无回水。
宫漏丁丁夜向晨，烟销雾散愁方士。','',''),('quantangshi-02345','杂歌谣辞 李夫人歌','張祜','quantangshi','','卷3','延年不语望三星，莫说夫人上涕零。
争奈世间惆怅在，甘泉宫夜看图形。','',''),('quantangshi-02346','杂歌谣辞 中山孺子妾歌','李白','quantangshi','','卷3','中山孺子妾，特以色见珍。
虽不如延年妹，亦是当时绝世人。
桃李出深井，花艳惊上春。
一贵复一贱，关天岂由身。
芙蓉老秋霜，团扇羞网尘。
戚姬髡翦入舂市，万古共悲辛。','',''),('quantangshi-02347','杂歌谣辞 临江王节士歌','李白','quantangshi','','卷3','洞庭白波木叶稀，燕鸿始入吴云飞。
吴云寒，燕鸿苦。
风号沙宿潇湘浦，节士感秋泪如雨。
白日当天心，照之可以事明主。
壮士愤，雄风生。
安得倚天劒，跨海斩长鲸。','',''),('quantangshi-02348','杂歌谣辞 司马将军歌','李白','quantangshi','','卷3','狂风吹古月，窃弄章华台。
北落明星动光彩，南征猛将如云雷。
手中电曳倚天劒，直斩长鲸海水开。
我见楼船壮心目，颇似龙骧下三蜀。
扬兵习战张虎旗，江中白浪如银屋。
身居玉帐临河魁，紫髯若戟冠崔嵬。
细柳开营揖天子，始知灞上为婴孩。
羌笛横吹阿嚲回，向月楼中吹落梅。
将军自起舞长劒，壮士呼声动九垓。
功成献凯见明主，丹青画像麒麟台。','',''),('quantangshi-02349','杂歌谣辞 郑樱桃歌','李頎','quantangshi','','卷3','石季龙，僭天禄。
擅雄豪，美人姓郑名樱桃。
樱桃美颜香且泽，娥娥侍寝专宫掖。
后庭卷衣三万人，翠眉清镜不得亲。
官军女骑一千匹，繁花照耀漳河春。
织成花映红纶巾，红旗掣曳卤簿新。
鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。
凤阳重门如意馆，百尺金梯倚银汉。
自言富贵不可量，女为公主男为王。
赤花双簟珊瑚牀，盘龙斗帐琥珀光。
淫昏伪位神所恶，灭石者陵终不误。
邺城苍苍白露微，世事飜覆黄云飞。','',''),('quantangshi-02350','杂歌谣辞 襄阳歌','李白','quantangshi','','卷3','落日欲没岘山西，倒着接䍦花下迷。
襄阳小儿齐拍手，拦街争唱白铜鞮。
傍人借问笑何事，笑杀山公醉似泥。
鸬鷀杓，鹦鹉杯，百年三万六千日，一日须倾三百杯。
遥看汉水鸭头绿，恰似蒲萄初发醅。
此江若变作春酒，垒麴便筑糟丘台。
千金骏马换少妾，醉坐雕鞍歌落梅。
车傍侧挂一壶酒，凤笙龙管行相催。
咸阳市上叹黄犬，何如月下倾金罍。
君不见晋朝羊公一片石，龟龙剥落生莓苔。
泪亦不能为之堕，心亦不能为之哀。
谁能忧彼身后事，金凫银鸭葬死灰。
清风朗月不用一钱买，玉山自倒非人推。
舒州杓，力士铛，李白与尔同死生。
襄王云雨今安在，江水东流猨夜声。','',''),('quantangshi-02351','杂歌谣辞 襄阳曲 一','李白','quantangshi','','卷3','襄阳行乐处，歌舞白铜鞮。
江城回渌水，花月使人迷。','',''),('quantangshi-02352','杂歌谣辞 襄阳曲 二','李白','quantangshi','','卷3','山公醉酒时，酩酊襄阳下。
头上白接䍦，倒着还骑马。','',''),('quantangshi-02353','杂歌谣辞 襄阳曲 三','李白','quantangshi','','卷3','岘山临汉江，水渌沙如雪。
上有堕泪碑，青苔久磨灭。','',''),('quantangshi-02354','杂歌谣辞 襄阳曲 四','李白','quantangshi','','卷3','且醉习家池，莫看堕泪碑。
山公欲上马，笑杀襄阳儿。','',''),('quantangshi-02355','杂歌谣辞 苏小小歌','李賀','quantangshi','','卷3','幽兰露，如啼眼。
无物结同心，烟花不堪翦。
草如茵，松如盖。
风为裳，水为佩。
油壁车，久相待。
冷翠烛，劳光彩。
西陵下，风吹雨。','',''),('quantangshi-02356','杂歌谣辞 苏小小歌','溫庭筠','quantangshi','','卷3','买莲莫破券，买酒莫解金。
酒里春容抱离恨，水中莲子怀芳心。
吴公女儿腰似束，家在钱塘小江曲。
一自檀郎逐便风，门前春水年年绿。','',''),('quantangshi-02357','杂歌谣辞 苏小小歌 一','張祜','quantangshi','','卷3','车轮不可遮，马足不可绊。
长怨十字街，使郎心四散。','',''),('quantangshi-02358','杂歌谣辞 苏小小歌 二','張祜','quantangshi','','卷3','新人千里去，故人千里来。
翦刀横眼底，方觉泪难裁。','',''),('quantangshi-02359','杂歌谣辞 苏小小歌 三','張祜','quantangshi','','卷3','登山不愁峻，涉海不愁深。
中擘庭前枣，教郎见赤心。','',''),('quantangshi-02360','杂歌谣辞 挟瑟歌','陸龜蒙','quantangshi','','卷3','挟瑟为君抚，君嫌声太古。
寥寥倚浪丝，㗫㗫沈湘语。
赖有秋风知，清泠吹玉柱。','',''),('quantangshi-02361','杂歌谣辞 勅勒歌','不詳','quantangshi','','卷3','敕勒金颓壁，阴山无岁华。
帐外风飘雪，营前月照沙。
羌儿吹玉管，胡姬踏锦花。
却笑江南客，梅落不归家。','',''),('quantangshi-02362','杂歌谣辞 黄麞歌','不詳','quantangshi','','卷3','黄麞黄麞草里藏，弯弓射尔伤。','',''),('quantangshi-02363','杂歌谣辞 得体歌','不詳','quantangshi','','卷3','得体纥那也，纥囊得体那。
潭里船车闹，扬州铜器多。
三郎当殿坐，听唱得体歌。','',''),('quantangshi-02364','杂歌谣辞 得宝歌','不詳','quantangshi','','卷3','得宝弘农野，弘农得宝那。
潭里船车闹，扬州铜器多。
三郎当殿坐，听唱得宝歌。','',''),('quantangshi-02365','杂歌谣辞 黄台瓜辞','章懷太子','quantangshi','','卷3','种瓜黄台下，瓜熟子离离。
一摘使瓜好，再摘令瓜稀。
三摘尚自可，摘绝抱蔓归。','',''),('quantangshi-02366','杂歌谣辞 古歌','沈佺期','quantangshi','','卷3','落叶流风向玉台，夜寒秋思洞房开。
水精帘外金波下，云母窗前银汉回。
玉阶阴阴苔藓色，君王履綦难再得。
璇闺窈窕秋夜长，绣户徘徊秋月光。
燕姬彩帐芙蓉色，秦子金炉兰麝香。
北斗七星横夜半，清歌一曲断君肠。','',''),('quantangshi-02367','杂歌谣辞 古歌 一','薛維翰','quantangshi','','卷3','美人怨何深，含情倚金阁。
不嚬复不语，红泪双双落。','',''),('quantangshi-02368','杂歌谣辞 古歌 二','薛維翰','quantangshi','','卷3','美人闭红烛，独坐裁新锦。
频放翦刀声，夜寒知未寝。','',''),('quantangshi-02369','杂歌谣辞 黄昙子歌','溫庭筠','quantangshi','','卷3','参差绿蒲短，摇艳云塘满。
红潋荡融融，莺翁鸂鶒暖。
萋芊小城路，马上修蛾懒。
罗衫褭向风，点粉金鹂卵。','',''),('quantangshi-02370','杂歌谣辞 邯郸郭公辞','溫庭筠','quantangshi','','卷3','金笳悲故曲，玉座积深尘。
言是邯郸伎，不易邺城人。
青苔竟埋骨，红粉自伤神。
唯有漳河柳，还向旧营春。','',''),('quantangshi-02371','杂歌谣辞 箜篌谣','李白','quantangshi','','卷3','攀天莫登龙，走山莫骑虎。
贵贱结交心不移，唯有严陵及光武。
周公称大圣，管蔡宁相容。
汉谣一斗粟，不与淮南舂。
兄弟尚路人，吾心安所从。
它人方寸间，山海几千重。
轻言托朋友，对面九疑峰。
多花必早落，桃李不如松。
管鲍久已死，何人继其踪。','',''),('quantangshi-02372','杂歌谣辞 邺城童子谣','李賀','quantangshi','','卷3','邺城中，暮尘起。
将黑丸，斫文吏。
棘为鞭，虎为马。
团团走，邺城下。
切玉劒，射日弓。
献何人，奉相公。
扶毂来，关右儿。
香扫涂，相公归。','',''),('quantangshi-02373','杂歌谣辞 大麦行','杜甫','quantangshi','','卷3','大麦干枯小麦黄，妇人行泣夫走藏。
东至集壁西梁洋，问谁腰镰胡与羌。
岂无蜀兵三千人，部领辛苦江山长。
安得如鸟有羽翅，托身白云还故乡。','',''),('quantangshi-02374','杂歌谣辞 白鼍鸣','張籍','quantangshi','','卷3','天欲雨，有东风，南溪白鼍鸣窟中。
六月人家井无水，夜闻白鼍人尽起。','',''),('quantangshi-02375','杂歌谣辞 步虚词','陳羽','quantangshi','','卷3','汉武清斋读鼎书，内官扶上画云车。
坛上月明宫殿闭，仰看星斗礼空虚。','',''),('quantangshi-02376','杂歌谣辞 步虚词','顧況','quantangshi','','卷3','逈步游三洞，清心礼七真。
飞符超羽翼，禁火醮星辰。
残药霑鸡犬，灵香出凤麟。
壶中无窄处，愿得一容身。','',''),('quantangshi-02377','杂歌谣辞 步虚词 一','劉禹錫','quantangshi','','卷3','阿母种桃云海际，花落子成二千岁。
海风吹折最繁枝，跪捧琼盘献天帝。','',''),('quantangshi-02378','杂歌谣辞 步虚词 二','劉禹錫','quantangshi','','卷3','华表千年鹤一归，凝丹为顶雪为衣。
星星仙语人听尽，却向五云翻翅飞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02379','杂歌谣辞 步虚词 一','韋渠牟','quantangshi','','卷3','玉简真人降，金书道箓通。
烟霞方蔽日，云雨已生风。
四极威仪异，三天使命同。
那将人世恋，不去上清宫。','',''),('quantangshi-02380','杂歌谣辞 步虚词 二','韋渠牟','quantangshi','','卷3','羽驾正翩翩，云鸿最自然。
霞冠将月晓，珠佩与星连。
镂玉留新诀，雕金得旧编。
不知飞鸟学，更有几人仙。','',''),('quantangshi-02381','杂歌谣辞 步虚词 三','韋渠牟','quantangshi','','卷3','上帝求仙使，真符取玉郎。
三才闲布象，二景郁生光。
骑吏排龙虎，笙歌走凤凰。
天高人不见，暗入白云乡。','',''),('quantangshi-02382','杂歌谣辞 步虚词 四','韋渠牟','quantangshi','','卷3','鸾鹤共徘徊，仙官使者催。
香花三洞启，风雨百神来。
凤篆文初定，龙泥印已开。
何须生羽翼，始得上瑶台。','',''),('quantangshi-02383','杂歌谣辞 步虚词 五','韋渠牟','quantangshi','','卷3','羽节忽排烟，苏君已得仙。
命风驱日月，缩地走山川。
几处留丹竈，何时种玉田。
一朝骑白虎，直上紫微天。','',''),('quantangshi-02384','杂歌谣辞 步虚词 六','韋渠牟','quantangshi','','卷3','静发降灵香，思神意智长。
虎存时促步，龙想更成章。
扣齿风雷响，挑灯日月光。
仙云在何处？仿髴满空堂。','',''),('quantangshi-02385','杂歌谣辞 步虚词 七','韋渠牟','quantangshi','','卷3','几度游三洞，何方召百神。
风云皆守一，龙虎亦全真。
执节仙童小，烧香玉女春。
应须绝岩内，委曲问皇人。','',''),('quantangshi-02386','杂歌谣辞 步虚词 八','韋渠牟','quantangshi','','卷3','上法杳无营，玄修似有情。
道宫琼作想，真帝玉为名。
召岳驱旌节，驰雷发吏兵。
云车降何处，斋室有仙卿。','',''),('quantangshi-02387','杂歌谣辞 步虚词 九','韋渠牟','quantangshi','','卷3','羽卫一何鲜，香云起莫烟。
方朝太素帝，更向玉清天。
凤曲凝犹吹，龙骖俨欲前。
真文几时降，知在永和年。','',''),('quantangshi-02388','杂歌谣辞 步虚词 十','韋渠牟','quantangshi','','卷3','大道何年学，真符此日催。
还持金作印，未要玉为台。
羽节分明授，霞衣整顿裁。
应缘五云使，教上列仙来。','',''),('quantangshi-02389','杂歌谣辞 步虚词 十一','韋渠牟','quantangshi','','卷3','独自授金书，萧条咏紫虚。
龙行还当马，云起自成车。
九转风烟合，千年井竈余。
参差从太一，寿等混元初。','',''),('quantangshi-02390','杂歌谣辞 步虚词 十二','韋渠牟','quantangshi','','卷3','道学已通神，香花会女真。
霞牀珠斗帐，金荐玉舆轮。
一室心偏静，三天夜正春。
